          NextDialogue = 6100608,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100608] = {
          ContentFR = "Tu comprends aussitôt : ce tourbillon n’était autre que la marée noire, l’Abysse affamé qui dévore toute matière.",
          DialogueId = 6100608,
          GUID = "0F45B100",
          NextDialogue = 6100609,
          RougeTalkActorType = 3
        },
        [6100609] = {
          ContentFR = "Demander pourquoi ils ont tentés d’atteindre Élysium",
          DialogueId = 6100609,
          GUID = "0F45B12A",
          NextDialogue = 6100610,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100610] = {
          ContentFR = "« Maman disait... que nous étions des "Enfants du Démon"... »\n« Même tomber dans l’Abysse... valait mieux... que rester en Hyperborea... »",
          DialogueId = 6100610,
          GUID = "0F45B154",
          NextDialogue = 6100611,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100611] = {
          ContentFR = "« Merci pour votre feu... et merci de m’avoir révélé... que je n’étais déjà plus de ce monde. »",
          DialogueId = 6100611,
          GUID = "0F45B17E",
          NextDialogue = 6100612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100612] = {
          ContentFR = "Elle disparaît. Il ne reste que le crépitement du feu, comme si elle n’avait jamais existé.",
          DialogueId = 6100612,
          GUID = "0F45B1A8",
          RougeTalkActorType = 3
        },
        [6100613] = {
          ContentFR = "Refuser",
          DialogueId = 6100613,
          GUID = "0F45B1D2",
          IsKeyOption = true,
          NextDialogue = 6100614,
          RougeTalkActorType = 2
        },
        [6100614] = {
          ContentFR = "« P-Pardon... je n’aurais pas dû vous déranger. »",
          DialogueId = 6100614,
          GUID = "0F45B1FC",
          NextDialogue = 6100615,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100615] = {
          ContentFR = "Elle s’éloigne en tremblant.\nSeul demeure le crépitement du feu, comme si personne n’était venue.",
          DialogueId = 6100615,
          GUID = "0F45B226",
          RougeTalkActorType = 3
        },
        [6100701] = {
          ContentFR = "« Salut ! »",
          DialogueId = 6100701,
          GUID = "0F45C042",
          NextDialogue = 6100702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100702] = {
          ContentFR = "Un jeune homme jovial, un sac au dos, s’avance jusqu’au feu de camp et te salue d’une voix éclatante.",
          DialogueId = 6100702,
          GUID = "0F45C06C",
          NextDialogue = 6100703,
          RougeTalkActorType = 3
        },
        [6100703] = {
          ContentFR = "« Excuse mon franc-parler, mais... tu es bien {性别:vivant|vivante}, pas vrai ? »",
          DialogueId = 6100703,
          GUID = "0F45C096",
          NextOptions = {
            [1] = 6100704,
            [2] = 6100711
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100704] = {
          ContentFR = "Rendre son salut d’un signe de tête",
          DialogueId = 6100704,
          GUID = "0F45C0C0",
          IsKeyOption = true,
          NextDialogue = 6100705,
          RougeTalkActorType = 2
        },
        [6100705] = {
          ContentFR = "« Jamais je n’aurais cru croiser une âme vivante ici. On dirait bien que toi et moi sommes des élus de la chance ! »",
          DialogueId = 6100705,
          GUID = "0F45C0EA",
          NextDialogue = 6100706,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100706] = {
          ContentFR = "« À seize ans, j’ai écrit une ballade avec mon père. Le Tribunal Sacré y a vu un blasphème. »\n« Comme lui, j’aurais dû finir exécuté... Mais le jour de la sentence, la foudre a frappé le bourreau. Et je fus gracié. »",
          DialogueId = 6100706,
          GUID = "0F45C114",
          NextDialogue = 6100707,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100707] = {
          ContentFR = "« À vingt ans, j’ai rejoint une caravane de marchands. Nous avons été attaqués dans une forêt du nord. »\n« Ligotés et abandonnés dans une grotte, j’ai regardé mes compagnons mourir de faim... Jusqu’à ce qu’au matin du septième jour, un sanglier me tire de ma torpeur, et qu’une jeune fille me tende de la nourriture. Ce jour-là, j’ai cru voir un ange. »",
          DialogueId = 6100707,
          GUID = "0F45C13E",
          NextDialogue = 6100708,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100708] = {
          ContentFR = "« Plus tard, je suis descendu dans l’Abysse aux côtés d’un ordre de chevaliers, simple marchand à leur suite. Leurs lanternes se sont éteintes une à une. L’un d’eux est tombé, et sa propre lame lui a transpercé la gorge. Moi seul en suis sorti vivant. »\n« Alors j’ai compris : la Déesse du Destin veille sur moi. Elle m’accordera bonheur et fortune sans limites. »",
          DialogueId = 6100708,
          GUID = "0F45C168",
          NextDialogue = 6100709,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100709] = {
          ContentFR = "« Et si elle m’a guidé jusqu’ici, c’est qu’un trésor unique repose en ces profondeurs. Il est temps pour moi de le trouver. »\nIl charge son lourd sac sur ses épaules.",
          DialogueId = 6100709,
          GUID = "0F45C192",
          NextDialogue = 6100710,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100710] = {
          ContentFR = "« Toi aussi, mon {性别:ami|amie} ! Puisqu’elle t’a laissé en vie, c’est qu’une bénédiction t’attend, aussi unique que la mienne ! »\nIl rit aux éclats, serrant les poings.\n« À notre chance ! »",
          DialogueId = 6100710,
          GUID = "0F45C1BC",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100711] = {
          ContentFR = "Se coucher et feindre la mort",
          DialogueId = 6100711,
          GUID = "0F45C1E6",
          IsKeyOption = true,
          NextDialogue = 6100712,
          RougeTalkActorType = 2
        },
        [6100712] = {
          ContentFR = "« {性别:Évanoui|Évanouie} ? »\nIl s’accroupit et vérifie ton souffle.\n« À moins que... tu ne sois déjà un spectre, comme les autres ? »",
          DialogueId = 6100712,
          GUID = "0F45C210",
          NextDialogue = 6100713,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100713] = {
          ContentFR = "Tu restes {性别:muet|muette}.\nIl dépose son sac, en sort de l’eau et de la nourriture.",
          DialogueId = 6100713,
          GUID = "0F45C23A",
          NextDialogue = 6100714,
          RougeTalkActorType = 3
        },
        [6100714] = {
          ContentFR = "« Tiens, pauvre {性别:ami|amie} ! Puisse la première lueur du soleil, en effleurant la Tour Sacrée, te trouver debout et {性别:sain|saine}. »",
          DialogueId = 6100714,
          GUID = "0F45C264",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100801] = {
          ContentFR = "Deux fleurs jumelles, d’un rouge sang, répandent leur lueur spectrale dans l’ombre.\nTu lèves ta lanterne : la lumière dévoile quelques mèches blondes, des vertèbres blêmes... Est-ce un Souillé à l’apparence humaine, ou bien un humain au seuil de sa Dégradation ?\nTu serres ton arme avec méfiance... Mais la créature n’attaque pas. Elle se contente de te fixer de ses yeux écarlates, brillants dans la nuit.",
          DialogueId = 6100801,
          GUID = "0F45D0AA",
          NextDialogue = 6100802,
          RougeTalkActorType = 3
        },
        [6100802] = {
          ContentFR = "Soudain, un râle grince dans sa gorge, bruit de pierres qui s’entrechoquent, mais rythmé comme une parole. Contre toute raison, tu comprends son sens.",
          DialogueId = 6100802,
          GUID = "0F45D0D4",
          NextDialogue = 6100803,
          RougeTalkActorType = 3
        },
        [6100803] = {
          ContentFR = "« {性别:Voyageur|Voyageuse} à la lanterne... dis-moi : mon reflet dans ta lumière est-il toujours beau ? »",
          DialogueId = 6100803,
          GUID = "0F45D0FE",
          NextDialogue = 6100804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100804] = {
          ContentFR = "« J’ai tressé mes cheveux pour qu’ils brillent et tombent souples. » Ses doigts frôlent la chair fendue derrière sa nuque.\n« J’ai repassé ma robe et l’ai parée de joyaux étincelants. » Ses doigts caressent les cristaux incrustés dans sa peau.\n« Je porte encore le collier de mon bien-aimé, souvenir de son amour ardent. » Ses doigts effleurent les os jaillissant de sa gorge.",
          DialogueId = 6100804,
          GUID = "0F45D128",
          NextOptions = {
            [1] = 6100805,
            [2] = 6100808
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100805] = {
          ContentFR = "« Oui... tu es belle. »",
          DialogueId = 6100805,
          GUID = "0F45D152",
          IsKeyOption = true,
          NextDialogue = 6100806,
          RougeTalkActorType = 2
        },
        [6100806] = {
          ContentFR = "Ses yeux rouges vacillent, tels des pétales battus par le vent.",
          DialogueId = 6100806,
          GUID = "0F45D17C",
          NextDialogue = 6100807,
          RougeTalkActorType = 3
        },
        [6100807] = {
          ContentFR = "« Merci, noble {性别:voyageur|voyageuse}. Accepte ce présent. »\n« Et si tu croises mon amour, dis-lui que je l’aimerai à jamais. »",
          DialogueId = 6100807,
          GUID = "0F45D1A6",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100808] = {
          ContentFR = "« Non... tu n’es qu’un monstre hideux. »",
          DialogueId = 6100808,
          GUID = "0F45D1D0",
          IsKeyOption = true,
          NextDialogue = 6100809,
          RougeTalkActorType = 2
        },
        [6100809] = {
          ContentFR = "Ses yeux écarlates se voilent sous ses griffes.",
          DialogueId = 6100809,
          GUID = "0F45D1FA",
          NextDialogue = 6100810,
          RougeTalkActorType = 3
        },
        [6100810] = {
          ContentFR = "« Non... jamais je ne voudrais que mon aimé me voie ainsi. »\n« {性别:Voyageur compatissant|Voyageuse compatissante}, accorde-moi le repos. »",
          DialogueId = 6100810,
          GUID = "0F45D224",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100901] = {
          ContentFR = "« Bien le bonjour, {性别:voyageur inconnu|voyageuse inconnue}. »",
          DialogueId = 6100901,
          GUID = "0F45E112",
          NextDialogue = 6100902,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100902] = {
          ContentFR = "Un jeune homme richement vêtu s’arrête dans la lumière du feu. Il s’incline avec élégance.",
          DialogueId = 6100902,
          GUID = "0F45E13C",
          NextDialogue = 6100903,
          RougeTalkActorType = 3
        },
        [6100903] = {
          ContentFR = "« Je cherche une dame aux yeux écarlates. Auriez-vous aperçu son ombre ? »",
          DialogueId = 6100903,
          GUID = "0F45E166",
          NextDialogue = 6100904,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100904] = {
          ContentFR = "« Elle chante d’une voix si pure que le rossignol lui-même se tait. »\n« Ses cheveux d’or ruissellent comme le soleil du printemps. »\n« Sa robe, noble et majestueuse, est incrustée de gemmes scintillantes tels des astres. »\n« Et à son cou repose mon présent : un pendentif rouge, aussi profond et mystérieux que son regard. »",
          DialogueId = 6100904,
          GUID = "0F45E190",
          NextDialogue = 6100905,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100905] = {
          ContentFR = "Dire que tu n’as jamais vu une telle femme",
          DialogueId = 6100905,
          GUID = "0F45E1BA",
          NextDialogue = 6100906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100906] = {
          ContentFR = "« Vraiment... »\nSes yeux s’abaissent un instant, puis il retrouve sa prestance.\n« Qu’importe. Je poursuivrai ma quête. »",
          DialogueId = 6100906,
          GUID = "0F45E1E4",
          NextDialogue = 6100907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100907] = {
          ContentFR = "Le jeune homme s’assoit près du feu. Les flammes se reflètent dans ses yeux clairs.",
          DialogueId = 6100907,
          GUID = "0F45E20E",
          NextDialogue = 6100908,
          RougeTalkActorType = 3
        },
        [6100908] = {
          ContentFR = "« Elle était ma fiancée. Le mariage devait sceller notre union à sa majorité. Mais les dieux ont gravé leur marque sur son front. »\n« La veille de ses quatorze ans, des émissaires l’ont emmenée. Elle m’a laissé une lettre de rupture, m’enjoignant de trouver une autre compagne. Mais j’ai juré : ma vie n’appartient qu’à elle. »\n« Je la ramènerai parmi les vivants. Le Dieu de la Pleine Lune, qui chante l’amour des mortels, bénira notre union. »",
          DialogueId = 6100908,
          GUID = "0F45E238",
          NextOptions = {
            [1] = 6100909,
            [2] = 6100911
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100909] = {
          ContentFR = "Souhaiter qu’il retrouve celle qu’il aime",
          DialogueId = 6100909,
          GUID = "0F45E262",
          IsKeyOption = true,
          NextDialogue = 6100910,
          RougeTalkActorType = 2
        },
        [6100910] = {
          ContentFR = "« Merci à vous, noble {性别:voyageur|voyageuse}. »\n« Acceptez ce modeste présent. Puisse votre propre vœu s’accomplir. »",
          DialogueId = 6100910,
          GUID = "0F45E28C",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100911] = {
          ContentFR = "« Et si les dieux refusaient ? »",
          DialogueId = 6100911,
          GUID = "0F45E2B6",
          IsKeyOption = true,
          NextDialogue = 6100912,
          RougeTalkActorType = 2
        },
        [6100912] = {
          ContentFR = "Un sourire discret éclaire ses lèvres.\n« Alors je livrerai mon corps au Lac Sacré, et mon âme rejoindra la sienne pour l’éternité. »",
          DialogueId = 6100912,
          GUID = "0F45E2E0",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6101001] = {
          ContentFR = "Une femme surgit près du feu. Elle plonge sa main gauche dans les flammes, en retire de la suie et trace sur le sol des symboles indéchiffrables.",
          DialogueId = 6101001,
          GUID = "0F45F17A",
          NextDialogue = 6101002,
          RougeTalkActorType = 3
        },
        [6101002] = {
          ContentFR = "« Ah... {性别:Voyageur|Voyageuse} rebelle au temps. {性别:Compagnon|Compagne} du désespoir, la mort te suit comme ton ombre. »\nSa voix s’élève en murmure.",
          DialogueId = 6101002,
          GUID = "0F45F1A4",
          NextOptions = {
            [1] = 6101003,
            [2] = 6101005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101003] = {
          ContentFR = "Demander ce qu’elle fait",
          DialogueId = 6101003,
          GUID = "0F45F1CE",
          IsKeyOption = true,
          NextDialogue = 6101004,
          RougeTalkActorType = 2
        },
        [6101004] = {
          ContentFR = "« Ah... {性别:Cher ami|Chère amie}. Comme tu le vois, je suis poétesse. »\n« Je compose ma mille et unième œuvre, oui, un poème écrit pour toi ! »",
          DialogueId = 6101004,
          GUID = "0F45F1F8",
          NextDialogue = 6101008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101005] = {
          ContentFR = "« Le feu ne brûle donc pas ?",
          DialogueId = 6101005,
          GUID = "0F45F222",
          IsKeyOption = true,
          NextDialogue = 6101006,
          RougeTalkActorType = 2
        },
        [6101006] = {
          ContentFR = "Elle rit doucement.",
          DialogueId = 6101006,
          GUID = "0F45F24C",
          NextDialogue = 6101007,
          RougeTalkActorType = 3
        },
        [6101007] = {
          ContentFR = "« {性别:Cher ami|Chère amie}, regarde. »\nSa main pâle s’ouvre devant toi, intacte.\n« Au fond de toi, tu le savais : ce feu n’est pas réel, et moi non plus. »",
          DialogueId = 6101007,
          GUID = "0F45F276",
          NextDialogue = 6101008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101008] = {
          ContentFR = "La poétesse agite de nouveau les flammes. Ses doigts gracieux y dansent comme les pas d’une ballerine.",
          DialogueId = 6101008,
          GUID = "0F45F2A0",
          NextDialogue = 6101009,
          RougeTalkActorType = 3
        },
        [6101009] = {
          ContentFR = "« N’est-ce pas un lieu merveilleux ? »\n« Enfin libérée de la prison de la chair, délivrée des fardeaux mesquins... Je suis infinie désormais, maîtresse du temps ! »\n« Merci, {性别:voyageur|voyageuse}, d’avoir croisé ma route. Ton passage m’offre une étincelle d’inspiration. Voici mes vers. Qu’ils te guident hors de ce cycle sans fin, jusqu’à ton désir le plus cher. »",
          DialogueId = 6101009,
          GUID = "0F45F2CA",
          NextDialogue = 6101010,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101010] = {
          ContentFR = "Elle tend la main. La suie s’élève en tempête et envahit ton regard.\nQuand la poussière retombe, elle n’est déjà plus là.",
          DialogueId = 6101010,
          GUID = "0F45F2F4",
          RougeTalkActorType = 3
        },
        [6101101] = {
          ContentFR = "« Bonjour... permettez-moi de profiter un peu de votre feu. »",
          DialogueId = 6101101,
          GUID = "0F4601E2",
          NextDialogue = 6101102,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101102] = {
          ContentFR = "Le garçon s’approche avec une dignité forcée, mais ses pas maladroits trahissent son jeune âge.\nIl s’assoit lentement près du feu, noyé dans un manteau trop grand pour sa frêle silhouette.\nSous la lumière vacillante, il ouvre un mince livret et se met à lire avec un sérieux cérémonial.",
          DialogueId = 6101102,
          GUID = "0F46020C",
          NextDialogue = 6101103,
          RougeTalkActorType = 3
        },
        [6101103] = {
          ContentFR = "« Dieu des Flammes, accorde-nous ta sagesse... Dieu des Eaux, offre-nous l’abondance... »",
          DialogueId = 6101103,
          GUID = "0F460236",
          NextOptions = {
            [1] = 6101104
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101104] = {
          ContentFR = "Demander ce qu’il lit",
          DialogueId = 6101104,
          GUID = "0F460260",
          NextDialogue = 6101105,
          RougeTalkActorType = 2
        },
        [6101105] = {
          ContentFR = "« Oh... c’est un livre que mes frères m’ont donné. »\nIl se gratte la tête, un sourire gêné aux lèvres.\n« Je dois devenir plus intelligent avant de rencontrer les dieux. »\n« J’ai toujours été le plus stupide de la famille, mes frères étaient meilleurs que moi en tout. Mais pour une raison que personne ne comprend, c’est moi que les dieux ont choisi. »\n« Ils m’ont offert ce recueil d’hymnes, en me disant de l’apprendre par cœur avant de paraître devant les Neuf. Ils m’ont supplié de ne pas faire honte à la famille. »",
          DialogueId = 6101105,
          GUID = "0F46028A",
          NextDialogue = 6101106,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101106] = {
          ContentFR = "Le garçon se rapproche encore, levant son petit livre vers toi, t’invitant du regard.",
          DialogueId = 6101106,
          GUID = "0F4602B4",
          NextDialogue = 6101107,
          RougeTalkActorType = 3
        },
        [6101107] = {
          ContentFR = "« Tu veux lire avec moi ? »",
          DialogueId = 6101107,
          GUID = "0F4602DE",
          NextOptions = {
            [1] = 6101108,
            [2] = 6101112
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101108] = {
          ContentFR = "Lire avec lui",
          DialogueId = 6101108,
          GUID = "0F460308",
          IsKeyOption = true,
          NextDialogue = 6101109,
          RougeTalkActorType = 2
        },
        [6101109] = {
          ContentFR = "Tu acceptes. Mais dès que tes yeux se posent sur les pages, ton sang se glace.\nDes mots immondes, griffonnés d’une encre noire, recouvrent les lignes.\nLes lettres se tordent, se transforment en ronces noires et barbelées qui se projettent hors du papier, serpentant autour de tes membres.\nTon souffle se fait court, l’obscurité grignote ta vision...\nPar instinct, tu bascules en arrière, arrachant ton regard du livre maudit.",
          DialogueId = 6101109,
          GUID = "0F460332",
          NextDialogue = 6101110,
          RougeTalkActorType = 3
        },
        [6101110] = {
          ContentFR = "« Hein ? Qu’est-ce qu’il y a ? Tu as vu quelque chose d’effrayant ? »\nIl te regarde, les yeux limpides et pleins d’incompréhension.",
          DialogueId = 6101110,
          GUID = "0F46035C",
          NextDialogue = 6101111,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101111] = {
          ContentFR = "Tu ouvres la bouche, mais aucun son n’en sort.\nLes ronces noires s’élancent soudain, engloutissant le garçon.\nEn un instant, lui, le livre et les épines disparaissent sans laisser de trace.",
          DialogueId = 6101111,
          GUID = "0F460386",
          RougeTalkActorType = 3
        },
        [6101112] = {
          ContentFR = "Refuser de lire",
          DialogueId = 6101112,
          GUID = "0F4603B0",
          IsKeyOption = true,
          NextDialogue = 6101113,
          RougeTalkActorType = 2
        },
        [6101113] = {
          ContentFR = "Tu n’es pas {性别:venu|venue} ici pour lire.",
          DialogueId = 6101113,
          GUID = "0F4603DA",
          NextDialogue = 6101114,
          RougeTalkActorType = 3
        },
        [6101114] = {
          ContentFR = "« D’accord... alors je lirai seul. »\nIl repose le livre sur ses genoux.",
          DialogueId = 6101114,
          GUID = "0F460404",
          NextDialogue = 6101115,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101115] = {
          ContentFR = "Mais soudain, d’innombrables ronces noires jaillissent des pages.\nAvant même que tu aies le temps de réagir, elles s’enroulent autour de lui, l’engloutissent, et disparaissent avec lui et son livre dans le néant.",
          DialogueId = 6101115,
          GUID = "0F46042E",
          RougeTalkActorType = 3
        },
        [6101201] = {
          ContentFR = "Une femme d’âge mûr s’assoit près du feu, le visage marqué par la gravité. La flamme ne parvient pas à éclairer ses yeux sombres.",
          DialogueId = 6101201,
          GUID = "0F46124A",
          NextDialogue = 6101202,
          RougeTalkActorType = 3
        },
        [6101202] = {
          ContentFR = "« Bonjour, {性别:étranger|étrangère}. Pardonnez ma question, mais... où sommes-nous ? »",
          DialogueId = 6101202,
          GUID = "0F461274",
          NextDialogue = 6101203,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101203] = {
          ContentFR = "Répondre",
          DialogueId = 6101203,
          GUID = "0F46129E",
          NextDialogue = 6101204,
          RougeTalkActorType = 3
        },
        [6101204] = {
          ContentFR = "« Le Lac Sacré... ? L’Abysse... ? » Sa voix vacille de confusion. \n« Ces mots... je n’en ai aucun souvenir... »\nElle contemple ses mains ridées, creusées de sillons.\n« J’ai oublié pourquoi je suis venue ici... »",
          DialogueId = 6101204,
          GUID = "0F4612C8",
          NextOptions = {
            [1] = 6101205,
            [2] = 6101207
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101205] = {
          ContentFR = "Proposer de lui raconter l’histoire du Lac Sacré",
          DialogueId = 6101205,
          GUID = "0F4612F2",
          IsKeyOption = true,
          NextDialogue = 6101206,
          RougeTalkActorType = 2
        },
        [6101206] = {
          ContentFR = "« Les porteurs du stigmate sacré... sont amenés en ce lieu... ? »\n« Ah... je me souviens. Ma fille... elle est ici. Un stigmate est apparu au coin de son œil, comme les ailes d’un papillon prêt à s’ouvrir. »",
          DialogueId = 6101206,
          GUID = "0F46131C",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101207] = {
          ContentFR = "Suggérer qu’elle fouille ses affaires",
          DialogueId = 6101207,
          GUID = "0F461346",
          IsKeyOption = true,
          NextDialogue = 6101208,
          RougeTalkActorType = 2
        },
        [6101208] = {
          ContentFR = "« Tu as raison. »\nElle plonge la main dans sa poche et en sort une broche d’argent.",
          DialogueId = 6101208,
          GUID = "0F461370",
          NextDialogue = 6101209,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101209] = {
          ContentFR = "« Ah... je me souviens. » Elle frotte doucement la broche avec sa manche.\n« C’était un cadeau... pour ma fille. »",
          DialogueId = 6101209,
          GUID = "0F46139A",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101210] = {
          ContentFR = "Elle relève enfin la tête. Cette fois, la flamme éclaire pleinement son regard.",
          DialogueId = 6101210,
          GUID = "0F4613C4",
          NextDialogue = 6101211,
          RougeTalkActorType = 3
        },
        [6101211] = {
          ContentFR = "« Je suis venue chercher mon enfant. »\n« Ils l’ont prise dans son sommeil, quand je n’étais pas là. Elle a toujours eu peur des inconnus... Si elle s’est réveillée sans voir un visage familier, elle a dû être terrorisée. »\n« Je dois rester auprès d’elle... Oui, c’est pour ça que je suis ici. »",
          DialogueId = 6101211,
          GUID = "0F4613EE",
          NextDialogue = 6101212,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101212] = {
          ContentFR = "Demander depuis combien de temps sa fille est partie",
          DialogueId = 6101212,
          GUID = "0F461418",
          NextDialogue = 6101213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101213] = {
          ContentFR = "« Cela fait dix jours... non, dix mois... ou dix ans... Ah... je ne m’en souviens plus... »",
          DialogueId = 6101213,
          GUID = "0F461442",
          NextDialogue = 6101214,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101214] = {
          ContentFR = "Sa voix s’éteint. Elle demeure immobile, figée comme une statue.\nTu as beau lui parler, plus rien ne l’atteint.",
          DialogueId = 6101214,
          GUID = "0F46146C",
          RougeTalkActorType = 3
        },
        [6101301] = {
          ContentFR = "« Fwoosh— »\nLes flammes jaillissent soudain plus haut.\nTu remarques une jeune fille blonde, debout près du feu. Elle retient le bas de sa robe pour y porter une brassée de pierres dorées, qu’elle jette une à une dans le brasier.",
          DialogueId = 6101301,
          GUID = "0F4622B2",
          NextDialogue = 6101302,
          RougeTalkActorType = 3
        },
        [6101302] = {
          ContentFR = "Le feu s’élève, bouillonnant, comme une forêt au printemps qui bourgeonne dans un élan de vie.",
          DialogueId = 6101302,
          GUID = "0F4622DC",
          NextOptions = {
            [1] = 6101303,
            [2] = 6101305
          },
          RougeTalkActorType = 3
        },
        [6101303] = {
          ContentFR = "Admirer la beauté des flammes",
          DialogueId = 6101303,
          GUID = "0F462306",
          IsKeyOption = true,
          NextDialogue = 6101304,
          RougeTalkActorType = 2
        },
        [6101304] = {
          ContentFR = "« Oui ! » Sa voix brûle de la même ardeur que les flammes. \n« Comme je suis heureuse de voir que tu penses comme moi ! »",
          DialogueId = 6101304,
          GUID = "0F462330",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101305] = {
          ContentFR = "Demander d’où viennent les pierres",
          DialogueId = 6101305,
          GUID = "0F46235A",
          IsKeyOption = true,
          NextDialogue = 6101306,
          RougeTalkActorType = 2
        },
        [6101306] = {
          ContentFR = "« Je les ai ramassées non loin d’ici. Je pense que ce sont des cristaux de magie du feu. »",
          DialogueId = 6101306,
          GUID = "0F462384",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101307] = {
          ContentFR = "Elle continue à lancer ses pierres, et tu crois voir les flammes s’incliner vers elle, caressant doucement ses cheveux d’or.",
          DialogueId = 6101307,
          GUID = "0F4623AE",
          NextDialogue = 6101308,
          RougeTalkActorType = 3
        },
        [6101308] = {
          ContentFR = "« Demain, le feu redeviendra comme avant, et ces pierres se disperseront à nouveau autour du camp. »\n« Alors chaque jour, je les ramasse pour les jeter encore une fois. Toujours cent quarante-six. Pas une de plus, pas une de moins. »",
          DialogueId = 6101308,
          GUID = "0F4623D8",
          NextDialogue = 6101309,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101309] = {
          ContentFR = "Dire que tout cela est vain",
          DialogueId = 6101309,
          GUID = "0F462402",
          NextDialogue = 6101310,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101310] = {
          ContentFR = "La jeune fille penche la tête, ses yeux brillants d’innocence.",
          DialogueId = 6101310,
          GUID = "0F46242C",
          NextDialogue = 6101311,
          RougeTalkActorType = 3
        },
        [6101311] = {
          ContentFR = "« Non. Moi, j’aime le feu. J’aime écouter son crépitement, regarder ses bonds joyeux. »\n« Tu sais... dans cet endroit, l’espace est instable. On ferme les yeux près du feu et on se réveille au fond du lac. »\n« Mais ces petites pierres, elles, ne changent pas. Peu importe où je me retrouve, je sais que demain elles seront encore là. Cette certitude... me permet de dormir paisiblement. »",
          DialogueId = 6101311,
          GUID = "0F462456",
          NextDialogue = 6101312,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101312] = {
          ContentFR = "« J’aime ce qui est certain. »",
          DialogueId = 6101312,
          GUID = "0F462480",
          NextDialogue = 6101313,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101313] = {
          ContentFR = "Elle jette sa dernière pierre.\nLes flammes l’enveloppent, et sa chevelure dorée se confond avec le brasier, jusqu’à s’y dissoudre entièrement.",
          DialogueId = 6101313,
          GUID = "0F4624AA",
          RougeTalkActorType = 3
        },
        [6101401] = {
          ContentFR = "« Mmm... ugh... »",
          DialogueId = 6101401,
          GUID = "0F46331A",
          NextDialogue = 6101402,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101402] = {
          ContentFR = "Des gémissements étouffés montent du sol. Un homme décharné est affalé près du feu, les joues creuses, vidé par la faim.",
          DialogueId = 6101402,
          GUID = "0F463344",
          NextOptions = {
            [1] = 6101403,
            [2] = 6101409
          },
          RougeTalkActorType = 3
        },
        [6101403] = {
          ContentFR = "Donner un peu de nourriture",
          DialogueId = 6101403,
          GUID = "0F46336E",
          IsKeyOption = true,
          NextDialogue = 6101404,
          RougeTalkActorType = 2
        },
        [6101404] = {
          ContentFR = "« ... Merci à toi, enfant au cœur pur. Mais je n’ai plus besoin de nourriture. »\n« La marée noire m’a englouti. Je ne peux plus rentrer. Aucun pain au monde ne me ramènera. »\n« Tu me rappelles une fillette d’Élysium... une enfant aussi douce que toi. »",
          DialogueId = 6101404,
          GUID = "0F463398",
          NextDialogue = 6101405,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101405] = {
          ContentFR = "« Elle avait de longs cheveux d’or et chevauchait un sanglier rose. Alors que j’errais, affamé, dans les rues, elle m’a tendu une miche de pain... »\n« Mais mon orgueil était trop grand. J’ai refusé l’aumône de l’Église Élyséenne, et j’ai craché des injures à son geste. »",
          DialogueId = 6101405,
          GUID = "0F4633C2",
          NextDialogue = 6101406,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101406] = {
          ContentFR = "« Aujourd’hui, repensant à ma vie... je réalise qu’elle fut peut-être la seule à m’avoir traité avec sincérité. »\n« La foi, la race, la naissance... Les hommes se parent de ces artifices... Mais aucun titre ne peut éclipser la lumière d’une véritable bonté... »",
          DialogueId = 6101406,
          GUID = "0F4633EC",
          NextDialogue = 6101407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101407] = {
          ContentFR = "« Si je pouvais revenir en arrière... je voudrais... lui demander pardon... Mais il est trop tard... »",
          DialogueId = 6101407,
          GUID = "0F463416",
          NextDialogue = 6101408,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101408] = {
          ContentFR = "Sa voix s’étiole. Tu clignes des yeux, et sa silhouette s’efface.\nUn parfum de pain chaud flotte dans l’air.",
          DialogueId = 6101408,
          GUID = "0F463440",
          RougeTalkActorType = 3
        },
        [6101409] = {
          ContentFR = "Ne rien faire",
          DialogueId = 6101409,
          GUID = "0F46346A",
          IsKeyOption = true,
          NextDialogue = 6101410,
          RougeTalkActorType = 2
        },
        [6101410] = {
          ContentFR = "L’homme paraît misérable, mais tes provisions sont déjà bien maigres.\nDans cet abysse cruel, il te faut d’abord survivre toi-même.",
          DialogueId = 6101410,
          GUID = "0F463494",
          RougeTalkActorType = 3
        },
        [6101501] = {
          ContentFR = "Un éclat d’or fend le ciel. Tu crois voir l’aube apparaître, mais c’est un oiseau doré qui descend en planant.\nIl se pose près de toi avec élégance. Ses plumes étincellent au feu comme un or plus pur que les joyaux des nobles.",
          DialogueId = 6101501,
          GUID = "0F464382",
          NextOptions = {
            [1] = 6101502,
            [2] = 6101505,
            [3] = 6101509
          },
          RougeTalkActorType = 3
        },
        [6101502] = {
          ContentFR = "Donner de l’eau à l’oiseau",
          DialogueId = 6101502,
          GUID = "0F4643AC",
          IsKeyOption = true,
          NextDialogue = 6101503,
          RougeTalkActorType = 2
        },
        [6101503] = {
          ContentFR = "Tu verses un peu d’eau dans ta paume et l’offres à l’oiseau.",
          DialogueId = 6101503,
          GUID = "0F4643D6",
          NextDialogue = 6101504,
          RougeTalkActorType = 3
        },
        [6101504] = {
          ContentFR = "Il penche la tête, hésite, puis avance son bec étincelant. \nIl boit avec retenue, puis pousse un trille joyeux, secoue ses plumes dorées et s’élève, disparaissant dans une spirale lumineuse.",
          DialogueId = 6101504,
          GUID = "0F464400",
          RougeTalkActorType = 3
        },
        [6101505] = {
          ContentFR = "Arracher une plume de la queue",
          DialogueId = 6101505,
          GUID = "0F46442A",
          IsKeyOption = true,
          NextDialogue = 6101506,
          RougeTalkActorType = 2
        },
        [6101506] = {
          ContentFR = "Profitant de son repos, tu tires discrètement sur une plume de sa queue. Elle brille comme l’or le plus précieux.",
          DialogueId = 6101506,
          GUID = "0F464454",
          NextDialogue = 6101507,
          RougeTalkActorType = 3
        },
        [6101507] = {
          ContentFR = "L’oiseau s’éveille furieux, fond sur toi, et son bec frappe comme une goutte d’or en fusion. Une marque rouge s’imprime dans ta paume.",
          DialogueId = 6101507,
          GUID = "0F46447E",
          NextDialogue = 6101508,
          RougeTalkActorType = 3
        },
        [6101508] = {
          ContentFR = "Quand la douleur s’apaise, l’oiseau a disparu dans les hauteurs.",
          DialogueId = 6101508,
          GUID = "0F4644A8",
          RougeTalkActorType = 3
        },
        [6101509] = {
          ContentFR = "Arracher une plume de la tête",
          DialogueId = 6101509,
          GUID = "0F4644D2",
          IsKeyOption = true,
          NextDialogue = 6101510,
          RougeTalkActorType = 2
        },
        [6101510] = {
          ContentFR = "Tu tends la main vers sa tête, tes doigts prêts à saisir une plume. Mais soudain, l’oiseau ouvre brusquement les yeux.\nDans un hurlement de fureur, il déploie ses ailes et se jette sur toi. Son bec s’abat dans ta paume comme une goutte d’or en fusion, y imprimant une marque rouge vive, brûlante et irrévocable.",
          DialogueId = 6101510,
          GUID = "0F4644FC",
          NextDialogue = 6101511,
          RougeTalkActorType = 3
        },
        [6101511] = {
          ContentFR = "Lorsque tu reprends ton souffle, il n’est déjà plus qu’un éclat d’or dans le ciel.",
          DialogueId = 6101511,
          GUID = "0F464526",
          RougeTalkActorType = 3
        },
        [6101601] = {
          ContentFR = "Une odeur de pourriture emplit l’air. \nUne petite fille s’approche du feu. Son visage et ses bras sont couverts de plaies purulentes. Sans la lueur qui survit encore dans ses yeux, tu la croirais morte.",
          DialogueId = 6101601,
          GUID = "0F4653EA",
          NextOptions = {
            [1] = 6101602,
            [2] = 6101606,
            [3] = 6101612
          },
          RougeTalkActorType = 3
        },
        [6101602] = {
          ContentFR = "Tu sors quelques remèdes de ton sac et les tends à la fillette.",
          DialogueId = 6101602,
          GUID = "0F465414",
          IsKeyOption = true,
          NextDialogue = 6101603,
          RougeTalkActorType = 2
        },
        [6101603] = {
          ContentFR = "« Merci... {性别:voyageur|voyageuse}... c’est si doux... »\nElle lève lentement la tête. Son sourire tremblant oscille entre gratitude et rictus de douleur.",
          DialogueId = 6101603,
          GUID = "0F46543E",
          NextDialogue = 6101604,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101604] = {
          ContentFR = "« Mais... ne m’aidez pas... » murmure-t-elle d’une voix basse.\n« Le prêtre a dit que cette malédiction, cette maladie de l’Abysse, est mon péché... »\n« Je dois me repentir sincèrement... alors je guérirai... jusque-là, je ne dois approcher personne... »",
          DialogueId = 6101604,
          GUID = "0F465468",
          NextDialogue = 6101605,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101605] = {
          ContentFR = "Elle chancelle et disparaît dans les ténèbres.",
          DialogueId = 6101605,
          GUID = "0F465492",
          RougeTalkActorType = 3
        },
        [6101606] = {
          ContentFR = "Soigner ses blessures",
          DialogueId = 6101606,
          GUID = "0F4654BC",
          IsKeyOption = true,
          NextDialogue = 6101607,
          RougeTalkActorType = 2
        },
        [6101607] = {
          ContentFR = "Tu t’approches prudemment, examinant ses plaies.",
          DialogueId = 6101607,
          GUID = "0F4654E6",
          NextDialogue = 6101608,
          RougeTalkActorType = 3
        },
        [6101608] = {
          ContentFR = "« Kof... kof ! »\nElle crache un sang sombre qui éclabousse ta main tendue, se changeant en une fumée noire inquiétante.",
