          ExStoryInfo = "Player",
          GUID = "1910100C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100115/1910100C"
        },
        [10011601] = {
          ContentFR = "Ça fait des années qu’on cherche… La commandante devrait abandonner cette fichue traque, non ?",
