          Duration = 3.5,
          GUID = "1910204A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "We've been searching for years. When will our chief give up this pointless hunt?",
          VoiceName = "voice/$Locale$/story/1001/100116/1910204A"
        },
        [10011602] = {
          ContentFR = "Qui va là ?!",
          DialogueId = 10011602,
          Duration = 1.5,
          GUID = "19102074",
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "Who's there?!",
          VoiceName = "voice/$Locale$/story/1001/100116/19102074"
        },
        [10011603] = {
