          SpeakNpcId = 100006,
          Subtitle = "The soldiers did their best with the Filthoids. These are indeed unforeseen circumstances. But we did find something valuable on this island today—",
          VoiceName = "voice/$Locale$/story/1001/100117/191030DC"
        },
        [10011703] = {
          ContentFR = "On a trouvé des installations d’alchimie qu’elle utilisait, et même un dirigeable avec un numéro de série de la Légion.",
          DialogueId = 10011703,
          DisableMouth = 1,
          Duration = 5.4,
