          SpeakNpcId = 100003,
          Subtitle = "Run!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BA"
        },
        [10012202] = {
          ContentFR = "Tu ne m’échapperas pas !",
          DialogueId = 10012202,
          Duration = 2,
          GUID = "191082BB",
          SpeakNpcId = 100006,
          Subtitle = "You can't get away!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BB"
        },
        [10012301] = {
          Content = "你的伤……好些没有？",
          DialogueId = 10012301,
          Duration = 2,
          GUID = "19109322",
          NextDialogue = 10012302,
