          VoiceName = "voice/$Locale$/story/1001/100123/19109322"
        },
        [10012302] = {
          Content = "好多了，只是还有些头晕……",
          DialogueId = 10012302,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910934C",
          NextDialogue = 10012303,
