          SpeakNpcId = 100001,
          Subtitle = "A ship... on the mountain?",
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9C"
        },
        [10018904] = {
          Camera = "-719.279663,652.294922,186.867676,0.000371,-7.196232,-42.994892,35.0,131.625381,false,Disable,8.286504",
          ContentFR = "Oui. Un "bateau" qui vole. Suis-moi.",
          DefaultLookAt = "KeepState",
          DialogueId = 10018904,
          FinalCamera = "-767.170166,696.94043,195.135254,0.000371,-7.196232,-42.994892,35.0,131.625381,false,Disable,8.286504",
          GUID = "190FAD9E",
          SpeakNpcId = 100003,
          Subtitle = "Yes, a "ship" that flies. Now follow me.",
          TalkActionId = {
            [1] = "100003:Agree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9E"
        },
        [10019001] = {
          ContentFR = "Le village est plongé dans un silence de mort... J’ai bien peur qu’ils soient déjà...",
          DialogueId = 10019001,
          Duration = 1.8,
          GUID = "1914DE5A",
          NextDialogue = 10019002,
          SpeakNpcId = 100003,
          Subtitle = "The village is in dead silence. I'm afraid they've probably...",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DE5A"
        },
        [10019002] = {
          ContentFR = "... !",
          DialogueId = 10019002,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1914DE84",
          NextDialogue = 10019003,
          SpeakNpcId = 100001,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DE84"
        },
        [10019003] = {
          ContentFR = "... Je veux dire, la plupart ont sûrement pris la fuite par bateau.",
          DialogueId = 10019003,
          Duration = 2.5,
          GUID = "1914DEAE",
          NextDialogue = 10019004,
          SpeakNpcId = 100003,
          Subtitle = "...I mean, they've probably scarpered off by boat.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAE"
        },
        [10019004] = {
          ContentFR = "On doit vite rentrer récupérer les armes, puis filer au quai. Ici, ça reste trop dangereux.",
          DialogueId = 10019004,
          Duration = 2.5,
          GUID = "1914DEAF",
          NextDialogue = 10019005,
          SpeakNpcId = 100003,
          Subtitle = "We should hurry home and get the weapons, and then get to the wharf. It's still dangerous here.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAF"
        },
        [10019005] = {
          ContentFR = "On est complètement désarmés... Il faut éviter les Souillés à tout prix.",
          DialogueId = 10019005,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "1914DEB1",
          NextDialogue = 10019006,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(We're unarmed right now. Gotta avoid those Filthoids as much as possible.)",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB1"
        },
        [10019006] = {
          ContentFR = "Encore un peu... la maison est juste devant.",
          DialogueId = 10019006,
          Duration = 2.5,
          GUID = "1914DEB2",
          SpeakNpcId = 100003,
          Subtitle = "Almost there. It's up ahead.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB2"
        },
        [10019007] = {
          Content = "（……我们现在赤手空拳，得尽量避开秽兽。）",
          DialogueId = 10019007,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "1914DEB3",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(We're unarmed right now. Gotta avoid those Filthoids as much as possible.)",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB1"
        },
        [10019008] = {
          Content = "还差一点……家就在前面了。",
          DialogueId = 10019008,
          Duration = 2.5,
          GUID = "1914DEB4",
          SpeakNpcId = 100003,
          Subtitle = "Almost there. It's up ahead.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB2"
        },
        [10019101] = {
          ContentFR = "Souviens-toi de ▇▇... ▇▇, tu dois ▇▇▇...",
          DialogueId = 10019101,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EEC2",
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Remem▇▇... ▇▇, you must ▇▇▇...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EEC2"
        },
        [10019102] = {
          ContentFR = "Ton ▇▇... le pouvoir de ▇▇...",
          DialogueId = 10019102,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EEEC",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Your ▇▇... the power of ▇▇...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EEEC"
        },
        [10019103] = {
          ContentFR = "▇▇▇ désire ▇▇... tout cela...",
          DialogueId = 10019103,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EF16",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "▇▇▇ wish to ▇ all this...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EF16"
        },
        [10019104] = {
          ContentFR = "Qu’est-ce que tu racontes... ? Je n’entends pas...",
          DialogueId = 10019104,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "1914EF17",
          SpeakNpcId = 100001,
          Subtitle = "Wait, I can't hear you...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EF17"
        },
        [10019201] = {
          Content = "关于那柄剑……除了它从小就在身边之外，我一无所知。",
          DialogueId = 10019201,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1914FF2A",
          NextDialogue = 10019202,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF2A"
        },
        [10019202] = {
          Content = "正如我不知道自己从何而来——我没有与贝蕾相遇之前的任何记忆。",
          DialogueId = 10019202,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "1914FF54",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF54"
        },
        [10019301] = {
          ContentFR = "Ces Souillés... ça n’en finit pas...",
          DialogueId = 10019301,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19150F92",
          NextDialogue = 10019302,
          SpeakNpcId = 100001,
          Subtitle = "How many of them are there...",
          VoiceName = "voice/$Locale$/story/1001/100193/19150F92"
        },
        [10019302] = {
          ContentFR = "Monte. On doit les semer.",
          DialogueId = 10019302,
          Duration = 4,
          GUID = "19150FBC",
          SpeakNpcId = 100003,
          Subtitle = "Let's get to the top to shake them off.",
          VoiceName = "voice/$Locale$/story/1001/100193/19150FBC"
        },
        [10019401] = {
          Content = "这是我第一次来科赛托斯省。看来，这里的待客之道颇为独特啊。",
          DialogueId = 10019401,
          Duration = 8,
          ExStoryInfo = "EXPlayer",
          GUID = "19151FFA",
          RelatedWikiId = {
            [1] = 408002
          },
          SpeakNpcId = 100012,
          Subtitle = "This is my first time in Cocytus Province. Is this how the people here show their hospitality?",
          VoiceName = "voice/$Locale$/story/1001/100194/19151FFA"
        },
        [10019402] = {
          Content = "我没有任何恶意，只是想同你做一笔……小小的交易。",
          DialogueId = 10019402,
          Duration = 5.3,
          ExStoryInfo = "EXPlayer",
          GUID = "19152024",
          SpeakNpcId = 100012,
          Subtitle = "I don't want to bother you, I just want to... strike a small "bargain".",
          VoiceName = "voice/$Locale$/story/1001/100194/19152024"
        },
        [10019403] = {
          Content = "我会付给你无法拒绝的报酬，而你要做的，非常简单。",
          DialogueId = 10019403,
          Duration = 6.9,
          ExStoryInfo = "EXPlayer",
          GUID = "1915204E",
          SpeakNpcId = 100012,
          Subtitle = "I'll pay you whatever you want, and all you have to do, well, it will be a piece of cake.",
          VoiceName = "voice/$Locale$/story/1001/100194/1915204E"
        },
        [10019501] = {
          Content = "？？？：不杀了{性别：他|她}吗？",
          DialogueId = 10019501,
          Duration = 2.5,
          GUID = "19153057.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153057"
        },
        [10019502] = {
          Content = "？？？：{性别：他|她}和您一样，拥有决定历史轨迹的力量。不要忘记，您的使命。",
          DialogueId = 10019502,
          Duration = 9,
          GUID = "19153058.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153058"
        },
        [10019503] = {
          Content = "？？？：我会处理。但，现在还不是时候。",
          DialogueId = 10019503,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "19153059.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153059"
        },
        [10019504] = {
          Content = "？？？：收到。将如实提交您的答复。",
          DialogueId = 10019504,
          Duration = 5,
          GUID = "19153060.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153060"
        },
        [10019505] = {
          Content = "？？？：……听着，{NickName}。",
          DialogueId = 10019505,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "19153061.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153061"
        },
        [10019506] = {
          Content = "？？？：“生命是航行在无尽长夜里的孤船。”",
          DialogueId = 10019506,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "19153062.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153062"
        },
        [10019507] = {
          Content = "？？？：“河流泪水满溢，夹岸荆棘丛生。”",
          DialogueId = 10019507,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1915308C",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915308C"
        },
        [10019508] = {
          Content = "？？？：“我会一直注视着……”",
          DialogueId = 10019508,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "191530B6",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530B6"
        },
        [10019509] = {
          Content = "？？？：“来自彼岸之人，你将驶向何方。”",
          DialogueId = 10019509,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "191530E0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530E0"
        },
        [10019510] = {
          Content = "（是谁……）",
          DialogueId = 10019510,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1915310A",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915310A"
        },
        [10025701] = {
          ContentFR = "Cette fuite... elle a commencé avec ce rêve étrange. Depuis mon enfance, je suis {性别:hanté|hantée} par des rêves similaires.",
          DialogueId = 10025701,
          Duration = 3,
          GUID = "19192992",
          NextDialogue = 10025702,
          Subtitle = "This escape was heralded by that odd dream.\nI've been plagued by similar ones all my life.",
          VoiceName = "voice/$Locale$/story/1002/100257/19192992"
        },
        [10025702] = {
          ContentFR = "Mais ce n’est pas le moment de se perdre dans le passé. Il y a plus urgent, à présent...",
          DialogueId = 10025702,
          Duration = 3,
          GUID = "191929BC",
          NextDialogue = 10025703,
          Subtitle = "But now's not the time for reflection...\nThere's something more pressing at the moment—",
          VoiceName = "voice/$Locale$/story/1002/100257/191929BC"
        },
        [10025703] = {
          ContentFR = "Berry et moi devons fuir l’Île du Purgatoire, même si c’est ici que nous avons grandi ensemble.",
          DialogueId = 10025703,
          Duration = 4,
          GUID = "191929E6",
          Subtitle = "Berry and I must flee from this isle known as \"Purgatorio Island\",\nwhere we spent our childhoods together.",
          VoiceName = "voice/$Locale$/story/1002/100257/191929E6"
        },
        [10025704] = {
          ContentFR = "Car notre vie paisible a déjà été déchirée, mise en pièces par les griffes impies des Souillés.",
          DialogueId = 10025704,
          Duration = 3,
          GUID = "19192A10",
          Subtitle = "For the peace we once knew has been torn asunder by the vile claws of Filthoids...",
          VoiceName = "voice/$Locale$/story/1002/100257/19192A10"
        },
        [10025801] = {
          ContentFR = "Ces Souillés... sont morts ?",
          DialogueId = 10025801,
          ExStoryInfo = "Player",
          GUID = "191939FA",
          NextDialogue = 10025802,
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/191939FA"
        },
        [10025802] = {
          ContentFR = "Quelqu’un les a déjà affrontés... juste avant notre arrivée.",
          DialogueId = 10025802,
          GUID = "19193A24",
          NextDialogue = 10025803,
          SpeakNpcId = 100003,
          Subtitle = "It seems someone had a fight here with these Filthoids just before we came.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A24"
        },
        [10025803] = {
          ContentFR = "Serait-ce un villageois qui a trouvé refuge ici... ? Non. Cette porte, c’est nous qui l’avons ouverte.",
          DialogueId = 10025803,
          ExStoryInfo = "Player",
          GUID = "19193A4E",
          NextDialogue = 10025804,
          SpeakNpcId = 100001,
          Subtitle = "Could it be one of the villagers... No, we were the first to open that door.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A4E"
        },
        [10025804] = {
          ContentFR = "Enfin... grâce à lui, le passage est dégagé. Sinon, ça aurait été encore plus difficile.",
          DialogueId = 10025804,
          ExStoryInfo = "Player",
          GUID = "19193A78",
          NextDialogue = 10025805,
          SpeakNpcId = 100001,
          Subtitle = "Anyway, thanks to that person, we don't have to deal with these Filthoids ourselves.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A78"
        },
        [10025805] = {
          ContentFR = "Qui que ce soit, il ne faut pas le sous-estimer. Restons sur nos gardes.",
          DialogueId = 10025805,
          GUID = "19193AA2",
          SpeakNpcId = 100003,
          Subtitle = "Whoever it was, they're not to be underestimated. We must be vigilant.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA2"
        },
        [10025806] = {
          Content = "这些秽兽……断气了？",
          DialogueId = 10025806,
          ExStoryInfo = "Player",
          GUID = "19193AA3",
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA3"
        },
        [10027501] = {
          Content = "在不远处……",
          DialogueId = 10027501,
          Duration = 2,
          GUID = "191A50E2",
          Subtitle = "A short distance away...",
          VoiceName = "voice/$Locale$/story/1001/100275/191A50E2"
        },
        [10029301] = {
          ContentFR = "Dans mes rêves qui se répètent en spirales, je me pose cette question encore et encore.",
          DialogueId = 10029301,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "1914AD4C",
          NextDialogue = 10018401,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "In my dreams that unfold like a double helix, I've asked myself that question countless times.",
          VoiceName = "voice/$Locale$/story/1002/100293/1914AD4C"
        },
        [10029309] = {
          Content = "恭喜你起名完成啦！！！！！",
          DialogueId = 10029309,
          Duration = 3,
          GUID = "1914AD4D",
          VoiceName = "voice/$Locale$/story/1002/100293/"
        },
        [10029401] = {
          ContentFR = "Veux-tu te reposer encore un peu ?",
          DialogueId = 10029401,
          GUID = "1914AD4E",
          SpeakNpcId = 100003
        },
        [10030101] = {
          ContentFR = "Haa... haa...",
          DialogueId = 10030101,
          Duration = 3,
          GUID = "191BFB72",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100301/191BFB72"
        },
