          VoiceName = "voice/$Locale$/story/1003/100312/191CB068"
        },
        [10031205] = {
          ContentFR = "Oui, chanter est si difficile.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031205,
          GUID = "191CB092",
          ImprPlusId = 1009,
          NextDialogue = 10031206
        },
        [10031206] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Et puis, je n’ai entendu la chanson qu’une fois. Impossible de retenir l’air. Mais si je l’entends de nouveau, je pourrai sûrement la reconnaître.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031206,
          GUID = "191CB0BC",
          NextDialogue = 10031209,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB0BC"
        },
        [10031207] = {
          ContentFR = "Je ne suis pas mauvais en musique. Ne me mettez pas dans le même panier que vous.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031207,
          GUID = "191CB0E6",
          ImprPlusId = 1010,
          NextDialogue = 10031208
        },
        [10031208] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "J’ai juste oublié parce que je suis resté trop longtemps dans le coma. Si je l’entends à nouveau, je la reconnaîtrai sans aucun doute.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031208,
          GUID = "191CB110",
          NextDialogue = 10031209,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB110"
        },
        [10031209] = {
          Camera = "-53.863281,-63.319824,136.021973,0.000113,2.80494,77.005501,35.000015,100000.0,false,Manual,22.0",
          ContentFR = "Alors je compte sur vous pour rester à l’écoute.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031209,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191CB13A",
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB13A"
        },
        [10031210] = {
          ContentFR = "C’est... un morceau de tissu ? Il est plutôt agréable au toucher.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031210,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MainCurtain.T_Guide_Chapter_MainCurtain'}",
          GUID = "191CB164",
          NextDialogue = 10031211,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100312/191CB164"
        },
        [10031211] = {
          ContentFR = "Berry adorerait ce côté tout doux...",
          DetectiveQuestionId = 1003,
          DialogueId = 10031211,
          DisableMouth = 1,
          GUID = "191CB18E",
          NextDialogue = 10031212,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100312/191CB18E"
        },
        [10031212] = {
          ContentFR = "Laissez-moi voir... Hmm, du velours. D’après le motif et les plis, il s’agit d’un <H>rideau de scène</>.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031212,
          GUID = "191CB1B8",
          NextDialogue = 10031213,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100312/191CB1B8"
        },
        [10031213] = {
          ContentFR = "Le seul endroit avec une scène à proximité, c’est le <H>Théâtre Galea</>. Ils préparent actuellement la <H>Fête de la Chandelle d’Argent</>, et avec toute l’agitation, il n’est pas surprenant que quelqu’un ait accidentellement jeté un vieux rideau.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031213,
          GUID = "191CB1E2",
          NextDialogue = 10031214,
          RelatedWikiId = {
            [1] = 406002,
            [2] = 405006
          },
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100312/191CB1E2"
        },
        [10031214] = {
          ContentFR = "Fête de la Chandelle d’Argent... Les décorations dans la cité, c’est donc pour cette fête ?",
          DetectiveQuestionId = 1003,
          DialogueId = 10031214,
          DisableMouth = 1,
          GUID = "191CB20C",
          NextDialogue = 10031215,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100312/191CB20C"
        },
        [10031215] = {
          ContentFR = "Seul ce morceau ne suffit pas à tirer des conclusions, mais si l’on combine cette piste avec celle que vous avez mentionnée tout à l’heure...",
          DetectiveQuestionId = 1003,
          DialogueId = 10031215,
          GUID = "191CB236",
          NextDialogue = 10031216,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100312/191CB236"
        },
        [10031216] = {
          ContentFR = "Hmm... un rideau de scène. Cela semble effectivement lié à <H>cette autre piste</>.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031216,
          DisableMouth = 1,
          GUID = "191CB260",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100312/191CB260"
        },
        [10031301] = {
          ContentFR = "Hé ! Il y a une <H>girouette cassée</> dans cette poubelle. Ouah, elle a l’air quasi neuve ! On l’a juste jetée ? Quel gaspillage... On pourrait l’emporter !",
          DetectiveQuestionId = 1002,
          DialogueId = 10031301,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Vane.T_Guide_Chapter_Vane'}",
          GUID = "191CC052",
          NextDialogue = 10031302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC052"
        },
        [10031302] = {
          ContentFR = "Vous collectionnez les girouettes ? Voilà un passe-temps étrange. Je pourrais demander à un de mes subordonnés de vous en acheter une neuve, mais celle-ci est une pièce à conviction, vous ne pouvez pas la garder.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031302,
          GUID = "191CC07C",
          NextDialogue = 10031303,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC07C"
        },
        [10031303] = {
          ContentFR = "Euh... Je disais ça comme ça... Je... je n’ai pas vraiment un faible pour les girouettes...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031303,
          GUID = "191CC0A6",
          NextDialogue = 10031304,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0A6"
        },
        [10031304] = {
          ContentFR = "Ouinn, c’est la première fois que quelqu’un prend mes paroles au sérieux... je suis trop touchée... ouinn...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031304,
          GUID = "191CC0D0",
          NextDialogue = 10031305,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0D0"
        },
        [10031305] = {
          ContentFR = "Officier Fischer, depuis quand cette rue est-elle scellée ?",
          DetectiveQuestionId = 1002,
          DialogueId = 10031305,
          GUID = "191CC0FA",
          NextDialogue = 10031306,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0FA"
        },
        [10031306] = {
          ContentFR = "Le matin suivant le premier incident de "Traque aux Charons".",
          DetectiveQuestionId = 1002,
          DialogueId = 10031306,
          GUID = "191CC124",
          NextDialogue = 10031307,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC124"
        },
        [10031307] = {
          ContentFR = "C’est relativement rapide... Et comme cette girouette est pratiquement neuve, elle n’a sûrement pas été jetée volontairement...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031307,
          GUID = "191CC14E",
          NextDialogue = 10031308,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC14E"
        },
        [10031308] = {
          ContentFR = "Ce serait à cause de la tempête cette nuit-là ?",
          DetectiveQuestionId = 1002,
          DialogueId = 10031308,
          GUID = "191CC178",
          NextDialogue = 10031309,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC178"
        },
        [10031309] = {
          ContentFR = "Non. Après la tempête il y a cinq jours, le Bureau de la Sécurité a bien reçu de nombreux rapports de dommages matériels, mais cette girouette n’a pas été soufflée par le vent, il est beaucoup plus probable qu’elle ait été <H>renversée par le coup de l’agresseur</>.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031309,
          GUID = "191CC1A2",
          NextDialogue = 10031310,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1A2"
        },
        [10031310] = {
          ContentFR = "Selon le témoignage de Madame Camilla, le coupable a sauté sur le <H>toit</> après l’avoir affrontée. Cette girouette doit provenir de là.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031310,
          GUID = "191CC1CC",
          NextDialogue = 10031311,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1CC"
        },
        [10031311] = {
          ContentFR = "Le toit... autant aller y jeter un œil.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031311,
          DisableMouth = 1,
          GUID = "191CC1F6",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1F6"
        },
        [10031401] = {
          ContentFR = "C’est bien celle-ci, l’angle de rupture correspond parfaitement. À en juger par la courbure de la base, il semble que ce ne soit pas le vent qui l’ait emportée, mais qu’elle ait été frappée avec force.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031401,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_VaneBottom.T_Guide_Chapter_VaneBottom'}",
          GUID = "191CD0BA",
          NextDialogue = 10031402,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100314/191CD0BA"
        },
        [10031402] = {
          ContentFR = "Et à partir de cet angle, on peut déduire dans quelle direction l’agresseur s’est enfui.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031402,
          GUID = "191CD0E4",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100314/191CD0E4"
        },
        [10031501] = {
          Camera = "-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,3.0-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,22.0",
          ContentFR = "C’est exact, vous l’avez vu aussi. L’agresseur a fui en direction du sud-ouest.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031501,
          FinalCamera = "-300.109375,-328.852295,9.648438,0.000112,13.797432,46.589191,30.0,100000.0,false,Manual,22.0",
