        },
        [10031508] = {
          Camera = "25.955078,-88.894897,153.555908,0.000082,-7.000821,146.786774,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Attraper l’agresseur est le seul moyen de rendre justice et de faire honneur à tous. Mais... nous n’avons toujours pas trouvé ce monstre.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031508,
          FacialId = {
