        [10031601] = {
          ContentFR = "C’est... de la neige bleue ?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031601,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MoonWaterOnSnow.T_Guide_Chapter_MoonWaterOnSnow'}",
          GUID = "191CF18A",
          NextDialogue = 10031602,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF18A"
        },
        [10031602] = {
          ContentFR = "J’ai vérifié, ce sont quelques gouttes de <H>Phoxichor</>. Quand il s’infiltre dans la neige, il s’étale comme une petite fleur.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031602,
          GUID = "191CF1B4",
          NextDialogue = 10031603,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1B4"
        },
        [10031603] = {
          ContentFR = "C’est beau, n’est-ce pas ? Chaque fois que je vois ces petites "fleurs" bleues, j’ai l’impression que toute ma fatigue disparaît.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031603,
          GUID = "191CF1DE",
          NextDialogue = 10031604,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1DE"
        },
        [10031604] = {
          ContentFR = "Vu la couleur, la pureté est assez élevée... Il y aurait eu une fuite de Phoxichor ?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031604,
          GUID = "191CF208",
          NextDialogue = 10031605,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF208"
        },
        [10031605] = {
