        },
        [10032106] = {
          Camera = "-57.99271,40.446503,110.507812,0.000493,-24.002615,60.69154,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Comment ça, vous continuez à répéter ? C’est une énorme affaire, il y a déjà eu plein de morts ! Si l’agresseur est parmi vous, vous courez un vrai danger !",
          DialogueId = 10032106,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "-74.687424,17.77153,121.558594,0.000493,-24.002615,60.69154,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D4464",
