        [10032316] = {
          Camera = "76.511719,-140.939392,119.402344,-0.00003,11.462054,-69.546867,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "C’est difficile d’imaginer une fête pareille à Givrelac... Les gens d’ici ont l’air si... sérieux.",
