          VoiceName = "voice/$Locale$/story/1003/100329/191DC6FC"
        },
        [10032903] = {
          ContentFR = "Ces dernières années, l’Empire a beaucoup investi dans les infrastructures souterraines des cités. Les Veilleurs ont aussi participé à leur entretien.",
          DialogueId = 10032903,
          GUID = "191DC726",
          NextDialogue = 10032904,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC726"
        },
        [10032904] = {
          ContentFR = "Quand j’ai rejoint l’unité, on m’a affectée au nettoyage des égouts, jour après jour.",
          DialogueId = 10032904,
          GUID = "191DC750",
          NextDialogue = 10032905,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC750"
        },
        [10032905] = {
          ContentFR = "Nettoyer les égouts tous les jours... Donc même dans la Légion, un Charon subit encore des brimades ?",
          DialogueId = 10032905,
          GUID = "191DC77A",
          NextDialogue = 10032906,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC77A"
        },
        [10032906] = {
          ContentFR = "Les préjugés sont tenaces. Mais au sein de la Légion, au moins, nous pouvons espérer gagner du respect grâce à nos exploits.",
          DialogueId = 10032906,
          GUID = "191DC7A4",
          NextDialogue = 10032907,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7A4"
        },
        [10032907] = {
          ContentFR = "C’est aussi une manière, pour nous les "Enfants du Démon", de racheter nos fautes.",
          DialogueId = 10032907,
          GUID = "191DC7CE",
          NextDialogue = 10032908,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7CE"
        },
        [10032908] = {
          ContentFR = "Attendez... vous n’entendez pas un bruit ?",
          DialogueId = 10032908,
          GUID = "191DC7F8",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7F8"
        },
        [10032909] = {
          ContentFR = "À... à l’aide... je ne veux pas mourir...",
          DialogueId = 10032909,
          GUID = "191DC822",
          NextDialogue = 10032910,
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC822"
        },
        [10032910] = {
          ContentFR = "... Un appel à l’aide ! J’y vais tout de suite !",
          DialogueId = 10032910,
          GUID = "191DC84C",
          NextDialogue = 10032911,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC84C"
        },
        [10032911] = {
          ContentFR = "Hé, vous n’allez même pas vérifier si ce n’est pas un piège... Tch. Dépêchons-nous de la suivre avant qu’elle ne fasse une folie.",
          DialogueId = 10032911,
          GUID = "191DC876",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC876"
        },
        [10033001] = {
          Camera = "624.507812,337.115234,453.645508,0.000164,-26.398672,-154.983353,25.0,100000.0,false,Manual,22.0",
          ContentFR = "Que se passe-t-il ici ?",
