        },
        [10033003] = {
          Camera = "275.736328,107.594727,170.033081,-3.000002,-7.798368,-166.566574,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Ils ont eu la vie sauve, mais ce secteur est un véritable labyrinthe rempli de Souillés. Ils sont restés piégés.",
          DialogueId = 10033003,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "275.736328,107.594727,165.155518,-3.000002,-7.398337,-166.566345,35.000011,100000.0,false,Manual,22.0",
