        },
        [10033006] = {
          Camera = "-295.976562,77.636719,167.921021,0.000128,-13.597185,-9.189079,20.000011,100000.0,false,Manual,22.0",
          ContentFR = "M-Merci, officiers. Mon compagnon... il est derrière la porte verrouillée, juste un peu plus loin !",
          DialogueId = 10033006,
          FacialId = {
            [1] = "100321:CM_Smile01"
