        },
        [10033007] = {
          Camera = "-182.212891,50.145508,105.839355,0.00015,-18.094679,-161.810562,20.000008,100000.0,false,Manual,22.0",
          ContentFR = "Hein ? Alors on est devenu une garderie maintenant ? Bon, si personne d’autre ne veut le faire, Snow assumera cette noble tâche ! Mais reste bien collé à moi, compris ?",
          DialogueId = 10033007,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-175.617188,51.421875,103.599365,0.000152,-15.494515,-164.608749,20.000008,100000.0,false,Manual,22.0",
          GUID = "191DD836",
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}},\nPlayAnimation{_delay{4},ActorId{200002},AnimationId{\"Think_End\"},Duration{1}},\n}",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "100321:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100330/191DD836"
        },
        [10033101] = {
          ContentFR = "Le panneau de commande de la porte est hors service...",
          DialogueId = 10033101,
          GUID = "191DE7A2",
          NextDialogue = 10033102,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE7A2"
        },
        [10033102] = {
          ContentFR = "Sans doute à cause d’une obstruction dans les canalisations. Essayons d’ouvrir la vanne d’urgence, avec un peu de chance, ça évacuera le blocage.",
          DialogueId = 10033102,
          GUID = "191DE7CC",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE7CC"
        },
        [10033103] = {
          ContentFR = "<W>Alerte : anomalie dans le processus d’évacuation. Débit maximal atteint. Veuillez dégager les conduites immédiatement.</>",
          DialogueId = 10033103,
          GUID = "191DE7F6",
          SnapShot = "BROADCAST",
          VoiceName = "voice/$Locale$/story/1003/100331/191DE7F6"
        },
        [10033104] = {
          ContentFR = "Aaaaah ! Ces choses arrivent droit sur nous ! Ma jambe... je n’arrive pas à bouger !",
          DialogueId = 10033104,
          GUID = "191DE820",
          NextDialogue = 10033105,
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE820"
        },
        [10033105] = {
          ContentFR = "Bon sang, mais combien de saletés peut contenir un seul tuyau !?",
          DialogueId = 10033105,
          GUID = "191DE84A",
          NextDialogue = 10033106,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE84A"
        },
        [10033106] = {
          ContentFR = "Éliminons-les rapidement et redémarrons le panneau de contrôle.",
          DialogueId = 10033106,
          GUID = "191DE874",
          NextDialogue = 10038102,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE874"
        },
        [10033107] = {
          ContentFR = "Le système de défense s’est arrêté. On dirait que le panneau de commande fonctionne de nouveau.",
          DialogueId = 10033107,
          GUID = "191DE89E",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE89E"
        },
        [10033108] = {
          ContentFR = "Vous êtes blessée ?",
          DialogueId = 10033108,
          GUID = "191DE8C8",
          NextDialogue = 10033109,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE8C8"
        },
        [10033109] = {
          ContentFR = "En aidant, j’ai pris une petite entaille. Rien de grave. Trouver l’autre victime est plus urgent.",
          DialogueId = 10033109,
          GUID = "191DE8F2",
          NextDialogue = 10033110,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE8F2"
        },
        [10033110] = {
          ContentFR = "Le monstre nous a pourchassés jusque-là... puis a disparu. Mon ami doit être juste devant...",
          DialogueId = 10033110,
          GUID = "191DE91C",
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE91C"
        },
        [10033111] = {
          ContentFR = "Ah ! Il est là, derrière le mécanisme ! Hé, hé ! Enfin, quelqu’un est venu nous sauver !",
          DialogueId = 10033111,
          GUID = "191DE946",
          NextDialogue = 10033112,
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE946"
        },
        [10033112] = {
          ContentFR = "Argh... Fuyez vite... Ces égouts... grouillent de Souillés...",
          DialogueId = 10033112,
          GUID = "191DE970",
          NextDialogue = 10033113,
          SpeakNpcId = 100322,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE970"
        },
        [10033113] = {
          ContentFR = "Tenez bon, nous arrivons tout de suite !",
          DialogueId = 10033113,
          GUID = "191DE99A",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE99A"
        },
        [10033114] = {
          ContentFR = "Hein ? Ce panneau ne réagit pas non plus...",
          DialogueId = 10033114,
          GUID = "191DE9C4",
          NextDialogue = 10033115,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE9C4"
        },
        [10033115] = {
          ContentFR = "Comme tout à l’heure, il est verrouillé. Ouvrons aussi les vannes de secours dans le secteur. L’une d’elles doit être—",
          DialogueId = 10033115,
          GUID = "191DE9EE",
          NextDialogue = 10033116,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE9EE"
        },
        [10033116] = {
          ContentFR = "O-Officier... vous parlez de cette vanne, de mon côté... ? Je... je peux vous aider...",
          DialogueId = 10033116,
          GUID = "191DEA18",
          SpeakNpcId = 100322,
          VoiceName = "voice/$Locale$/story/1003/100331/191DEA18"
        },
        [10033117] = {
          ContentFR = "Occupons-nous d’abord des Souillés. Ce serait trop risqué de le déplacer tant qu’ils sont encore là.",
          DialogueId = 10033117,
          GUID = "191DEA42",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DEA42"
        },
        [10033118] = {
          ContentFR = "M-Merci... Merci infiniment, Officiers...",
          DialogueId = 10033118,
          GUID = "191DEA6C",
          NextDialogue = 10033119,
          SpeakNpcId = 100322,
          VoiceName = "voice/$Locale$/story/1003/100331/191DEA6C"
        },
        [10033119] = {
          ContentFR = "Allez, partez. Votre ami vous attend.",
          DialogueId = 10033119,
          GUID = "191DEA96",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DEA96"
        },
        [10033201] = {
