        [10033301] = {
          ContentFR = "—ROOAAAR !",
          DialogueId = 10033301,
          GUID = "191E0872",
          NextDialogue = 10033302,
          SpeakNpcName = "Cp2CharacterName01",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0872"
        },
        [10033302] = {
          ContentFR = "Où est-ce qu’il se cache, ce monstre... ?",
          DialogueId = 10033302,
          GUID = "191E089C",
          NextDialogue = 10033303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100333/191E089C"
        },
        [10033303] = {
          ContentFR = "La zone de traitement est reliée au reste des égouts. Vidons les bassins et fouillons chaque recoin.",
          DialogueId = 10033303,
          GUID = "191E08C6",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E08C6"
        },
        [10033304] = {
          ContentFR = "Madame, nous sommes là pour vous prêter main forte !",
          DialogueId = 10033304,
          GUID = "191E08F0",
          NextDialogue = 10033305,
          SpeakNpcId = 100344,
          VoiceName = "voice/$Locale$/story/1003/100333/191E08F0"
        },
        [10033305] = {
          ContentFR = "Et les deux civils ?",
          DialogueId = 10033305,
          GUID = "191E091A",
          NextDialogue = 10033306,
