        [10034601] = {
          ContentFR = "... Héhé.",
          DialogueId = 10034601,
          GUID = "191EDDBA",
          NextDialogue = 10034602,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDBA"
        },
        [10034602] = {
          ContentFR = "Qu’est-ce qui vous fait sourire ?",
          DialogueId = 10034602,
          GUID = "191EDDE4",
          NextDialogue = 10034603,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDE4"
        },
        [10034603] = {
          ContentFR = "Je repensais à la dernière fois que j’ai pêché ici... c’était il y a trois ans, avec Blues.",
          DialogueId = 10034603,
          GUID = "191EDE0E",
          NextDialogue = 10034604,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE0E"
        },
        [10034604] = {
          ContentFR = "Il est intelligent, mais tellement turbulent qu’il ne tenait pas en place. Il a pêché toute la journée et s’est retrouvé avec un panier vide.",
          DialogueId = 10034604,
          GUID = "191EDE38",
          NextDialogue = 10034605,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE38"
        },
        [10034605] = {
          ContentFR = "... Je me demande comment il vit aujourd’hui, dans la cité intérieure. Peut-être qu’il a enfin appris à pêcher.",
          DialogueId = 10034605,
          GUID = "191EDE62",
          NextDialogue = 10034606,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE62"
        },
        [10034606] = {
          ContentFR = "Hmpf, vous les mortels, toujours prisonniers de vos attachements dérisoires. Prenez exemple sur moi, le Roi Démon, cool et détaché de tout !",
          DialogueId = 10034606,
          GUID = "191EDE8C",
          NextDialogue = 10034607,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE8C"
        },
        [10034607] = {
          ContentFR = "C’est bon, Petit Champi, nous sommes ta famille, nous aussi. Si ça peut te faire plaisir, je peux même t’appeler mamie.",
          DialogueId = 10034607,
          GUID = "191EDEB6",
          NextDialogue = 10034608,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEB6"
        },
        [10034608] = {
          ContentFR = "Hein ? Mais... pourquoi tu es si gentil tout à coup... ?",
          DialogueId = 10034608,
          GUID = "191EDEE0",
          NextDialogue = 10034609,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEE0"
        },
        [10034609] = {
          ContentFR = "Mamie, j’ai faim. Tu me donnes un peu d’argent de poche ?",
          DialogueId = 10034609,
          GUID = "191EDF0A",
          NextDialogue = 10034610,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF0A"
        },
        [10034610] = {
          ContentFR = "Aaaargh ! Je le savais !",
          DialogueId = 10034610,
          GUID = "191EDF34",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF34"
        },
        [10034611] = {
          ContentFR = "Ça devrait suffire. Allons livrer tout ça à Brumelac.",
          DialogueId = 10034611,
          GUID = "191EDF5E",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF5E"
        },
        [10034612] = {
          ContentFR = "La circulation est interdite pendant le couvre-feu. Merci de votre coopération !",
          DialogueId = 10034612,
          GUID = "191EDF60",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF60"
        },
        [10034613] = {
          Content = "（<H>地面都被士兵封锁了</>……或许可以试试别的路——比如<H>楼顶</>？）",
          DialogueId = 10034613,
          GUID = "191EDF61",
