        [10035251] = {
          Camera = "230.964554,123.720169,183.445557,0.000094,-14.6028,-143.350281,30.000008,100000.0,false,Manual,22.0",
          ContentFR = "Euh... moi non plus. Et toi, Rhythm ?",
          DialogueId = 10035251,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "191F485E",
          LookAt = {
            [1] = "200021:n(200002)",
            [2] = "100304:n(200002)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10035252,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"ScratchHead_Start\"},Duration{2}},\nPlayAnimation{ActorId{200002},AnimationId{\"ScratchHead_End\"},Duration{1}},\nLookAt{LookAtDescription{\"200002:n(100304)\"}},\n}",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200021:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F485E"
        },
        [10035252] = {
          Camera = "-56.100571,-8.342358,115.075195,0.000082,8.198917,-0.569315,30.000013,100000.0,false,Manual,22.0",
          ContentFR = "Désolée. Je vous l’ai dit, la musique n’est pas mon fort... soupir... Si seulement je m’étais pas endormie quand Blues insistait pour me faire écouter ses cassettes...",
          DialogueId = 10035252,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          GUID = "191F4888",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(100304)"
          },
          NextDialogue = 10035253,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F4888"
        },
        [10035253] = {
          ContentFR = "Attendez... Blues ! Lui, c’était un passionné d’opéra. Je me souviens qu’il avait laissé un tas de cassettes dans notre base secrète ! Ça va prendre du temps de tout écouter une par une, mais... peut-être qu’on retrouvera cet air !",
          DialogueId = 10035253,
          GUID = "191F48B2",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035254,
          Scripts = "SEQ{\nLookAt{LookAtDescription{\"100304:n(100304)\"}},\nPlayAnimation{ActorId{100304},AnimationId{\"Sigh_End\"},Duration{1}},\nPlayAnimation{ActorId{100304},AnimationId{\"Think_Start\"},Duration{1}},\n}",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100352/191F48B2"
        },
        [10035254] = {
          Camera = "-314.120422,323.028412,138.915283,0.0001,-2.600881,-44.171185,30.000002,100000.0,false,Manual,22.0",
          ContentFR = "Pas mal. Merci du coup de main, Blues ! Capitaine, retournons à la base secrète.",
          DialogueId = 10035254,
          GUID = "191F48DC",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(200021)",
            [3] = "100304:n(200021)",
            [4] = "100001:n(200021)"
          },
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F48DC"
        },
        [10035255] = {
          ContentFR = "Le train à destination de Dismania partira dans une heure. Bon retour à la XIIIᵉ Légion. Toute gloire à l’Empereur !",
          DialogueId = 10035255,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "191F4906",
          SpeakNpcName = "Cp2CharacterName30",
          VoiceName = "voice/$Locale$/story/1003/100352/191F4906"
        },
        [10035301] = {
          ContentFR = "Dis donc, avec une collection pareille, ton frère devait être riche en secret !",
          DialogueId = 10035301,
          GUID = "191F5092",
          NextDialogue = 10035302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5092"
        },
        [10035302] = {
          ContentFR = "Pas du tout. C’étaient surtout des copies qu’il enregistrait chez ses amis.",
          DialogueId = 10035302,
          GUID = "191F50BC",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F50BC"
        },
        [10035303] = {
          ContentFR = "La mélodie ressemble... mais ce n’est pas ça. Celle du coupable sonnait plus triste.",
          DialogueId = 10035303,
          GUID = "191F50E6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F50E6"
        },
        [10035304] = {
          ContentFR = "Aïe, mes oreilles ! Sérieusement, Blues, dans quel monde cette musique existe-t-elle ?",
          DialogueId = 10035304,
          GUID = "191F5110",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5110"
        },
        [10035305] = {
          ContentFR = "Celle-ci non plus... ça ne colle pas.",
          DialogueId = 10035305,
          GUID = "191F513A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F513A"
        },
        [10035306] = {
          Camera = "375.742188,-433.851562,288.041016,0.00005,-17.800415,125.025429,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "C’est tout ? Il n’y en a pas d’autres ?",
          DialogueId = 10035306,
          FinalCamera = "317.1875,-472.192383,288.041016,0.000045,-19.000452,121.826225,25.000002,100000.0,false,Manual,22.0",
