        },
        [10035308] = {
          Camera = "70.957031,207.253906,117.710938,0.000085,4.599012,-117.169922,25.000006,100000.0,false,Manual,22.0",
          ContentFR = "Où est Rhythm ?",
          DialogueId = 10035308,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191F51B8",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10035309,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F51B8"
        },
        [10035309] = {
          ContentFR = "Elle est sortie prendre l’air.",
          DialogueId = 10035309,
          GUID = "191F51E2",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F51E2"
        },
        [10035310] = {
          Camera = "27.261719,-48.188965,98.787598,0.000046,5.787246,58.397362,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "« ... Ô neige silencieuse, fille des cieux... Accorde ta bénédiction à l’enfant sans nom... Qu’il danse en liesse parmi les flocons légers... »",
          DialogueId = 10035310,
          FinalCamera = "42.640625,-23.193359,101.764648,0.000046,5.787246,58.397282,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F520C",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035311,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Lise_Sing_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F520C"
        },
        [10035311] = {
          Camera = "106.324219,18.061035,129.950195,0.000045,-7.413487,-143.597916,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "... C’est ça ! C’est cette mélodie ! Comment elle s’appelle ? Qu’est-ce que ça raconte ?",
          DialogueId = 10035311,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "191F5236",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035312,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5236"
        },
        [10035312] = {
          Camera = "-158.65625,-332.602051,130.729492,0.000072,-4.813562,57.80043,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Hein ? Celle que je viens de fredonner ? J’y ai même pas pensé... ça m’est venu tout seul. Attends...",
          DialogueId = 10035312,
          FacialId = {
            [1] = "100001:None",
            [2] = "100304:Shock01"
          },
          GUID = "191F5260",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10035313,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Lise_Sing_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5260"
        },
        [10035313] = {
          ContentFR = "C’est Blues qui me l’a apprise. Ça s’appelle Requiem pour les sans-nom. Un air de l’opéra Né du blizzard. Mais les paroles que je chantais ne sont pas les vraies. Les originales sont bien plus tristes.",
          DialogueId = 10035313,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F528A",
          NextDialogue = 10035314,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F528A"
        },
        [10035314] = {
          ContentFR = "Ça raconte l’histoire d’un esprit sans nom, qui se sacrifie pour sauver ses amis. Mais ceux-ci ne découvrent jamais la vérité. Seule la neige s’en souvient.",
          DialogueId = 10035314,
          GUID = "191F52B4",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10035315,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F52B4"
        },
        [10035315] = {
          Camera = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Blues n’aimait pas cette fin. Alors il avait réécrit les paroles, en version heureuse. Il connaissait cet air par cœur, il pouvait même le jouer à l’envers. C’est pour ça qu’il ne l’a jamais enregistré.",
          DialogueId = 10035315,
          FacialId = {
            [1] = "100304:Think01"
          },
          GUID = "191F52DE",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035316,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F52DE"
        },
        [10035316] = {
          ContentFR = "Tu veux dire... que c’est bien cette mélodie que tu as entendue ?",
          DialogueId = 10035316,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5308",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035317,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5308"
        },
        [10035317] = {
          Camera = "138.671875,16.285156,67.811523,7.200567,11.981702,-152.809799,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Oui. C’est exactement celle que j’ai entendue la nuit de l’attaque.",
          DialogueId = 10035317,
          GUID = "191F5332",
          NextDialogue = 10035318,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5332"
        },
        [10035318] = {
          Camera = "43.828125,-22.387695,88.140137,0.000081,6.1863,60.000423,35.0,100000.0,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 10035318,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
          GUID = "191F535C",
          LookAt = {
            [1] = "100304:p(lise_50_ditou)"
          },
          NextDialogue = 10035319,
          SpeakNpcId = 100304,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F535C"
        },
        [10035319] = {
          ContentFR = "C’est un nouvel indice... mais malheureusement, il est trop large. Né du blizzard a été joué au Théâtre Galéa pendant des dizaines d’années. C’était extrêmement populaire. Beaucoup d’habitants savent le fredonner.",
          DialogueId = 10035319,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5386",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035320,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt03/0071_lise_secret"},RelatedRegionId{101103}}",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5386"
        },
        [10035320] = {
          Camera = "-47.433594,-302.833496,184.461426,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "Un jour, Blues et moi avions économisé pendant six mois pour acheter deux places. Mais une fois sur place, quelqu’un nous a accusés d’avoir volé ses billets. On a été mis dehors avant que la pièce commence.",
          DialogueId = 10035320,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "-43.898438,-292.427002,181.38916,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          GUID = "191F53B0",
          NextDialogue = 10035321,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53B0"
        },
        [10035321] = {
          ContentFR = "J’étais dévastée. Je suis restée assise des heures contre le mur du théâtre. Et là, Blues a sorti son vieil harmonica et a joué cet air. Il l’avait appris en cachette...",
          DialogueId = 10035321,
          GUID = "191F53DA",
          NextDialogue = 10035322,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53DA"
        },
        [10035322] = {
          Camera = "69.078125,-79.48877,262.419922,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Et soudain, de l’autre côté du mur, un garçon s’est mis à chanter. Sa voix... magnifique, comme une alouette.",
          DialogueId = 10035322,
          FinalCamera = "75.945312,-56.791992,244.148438,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F5404",
          NextDialogue = 10035323,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5404"
        },
        [10035323] = {
          Camera = "292.566406,182.274902,118.647949,0.000237,-2.417996,-149.207611,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Ce soir-là, grâce à Blues et à cet inconnu, j’ai presque oublié qu’on nous avait chassés.",
          DialogueId = 10035323,
          GUID = "191F542E",
          NextDialogue = 10035324,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F542E"
        },
        [10035324] = {
          Camera = "72.292969,-58.250488,84.757324,0.000228,9.781732,71.391068,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "... Désolée, je me suis laissée emporter. Ce que je veux dire, c’est que cette chanson est trop répandue. Elle ne peut pas servir de preuve.",
          DialogueId = 10035324,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5458",
          NextDialogue = 10035325,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5458"
        },
        [10035325] = {
          Camera = "35.425781,210.5625,76.637207,0.000075,18.182783,-57.792496,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Alors, cette pièce sera rejouée bientôt ? On pourrait essayer de guetter au théâtre.",
          DialogueId = 10035325,
          FinalCamera = "35.425781,210.5625,76.637207,0.000069,11.982678,-57.391754,35.000011,100000.0,false,Manual,22.0",
          GUID = "191F5482",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035326,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5482"
        },
        [10035326] = {
          Camera = "46.15625,-202.915527,167.463867,0.000052,-11.016801,66.199203,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Je ne sais pas. D’après ce que j’ai lu, l’opéra a été suspendu il y a deux ans, après un <H>incident</>.",
          DialogueId = 10035326,
          GUID = "191F54AC",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(200021)"
          },
          NextDialogue = 10035327,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F54AC"
        },
        [10035327] = {
          Camera = "109.480469,38.969727,114.763672,0.000073,-0.616664,-141.401657,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Un incident ?",
          DialogueId = 10035327,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191F54D6",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035328,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
