        [10035703] = {
          Camera = "-97.664062,-97.821289,211.294312,0.000093,-6.601774,-26.81625,20.000011,670.626465,false,Manual,1.2",
          ContentFR = "...",
          DialogueId = 10035703,
          FinalCamera = "-91.411133,-85.444336,211.294312,0.000093,-6.601774,-27.615789,20.000011,670.626465,false,Manual,22.0",
          GUID = "191F9286",
          NextDialogue = 10035704,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9286"
        },
        [10035704] = {
          Camera = "316.166016,-370.8125,168.484741,0.000076,8.598402,-44.815922,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentFR = "Pas envie de parler ? Ce n’est pas grave. Dis juste un mot, que je sache que tu es vivant.",
          DialogueId = 10035704,
          FinalCamera = "290.038086,-344.858398,162.916687,0.000075,8.598402,-44.815895,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F92B0",
          NextDialogue = 10035705,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F92B0"
        },
        [10035705] = {
          Camera = "-180.529297,-310.954102,177.634216,0.000067,1.398201,38.782471,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentFR = "... 47.",
          DialogueId = 10035705,
          FinalCamera = "-190.380859,-298.686523,177.634216,0.000067,1.1982,38.781147,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F92DA",
          NextDialogue = 10035706,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100357/191F92DA"
        },
        [10035706] = {
          Camera = "215.392578,-260.694336,230.287964,0.000079,-5.401976,-49.228199,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentFR = "Ouf, je croyais que je ne trouverais plus jamais quelqu’un avec qui parler.",
          DialogueId = 10035706,
          FinalCamera = "220.646484,-256.163086,230.287964,0.000079,-5.401976,-49.228199,20.000011,335.406189,false,DoNotOverride,1.2",
