        [10036333] = {DialogueId = 10036333, GUID = "191FF719"},
        [10036334] = {
          ContentFR = "Hé, beau gosse ! Ça te dit une danse plus tard ?",
          DialogueId = 10036334,
          Duration = 5,
          GUID = "191FF521",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF521"
        },
        [10036335] = {
          ContentFR = "Mate mon flingue, on dirait un vrai, non ? Il tire même des balles en mousse, c'est pas cool, ça ?",
          DialogueId = 10036335,
          Duration = 8,
          GUID = "191FF522",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF522"
        },
        [10036336] = {
          ContentFR = "Hein, moi saoul ? Pas du tout ! Regardez, je peux encore faire un roulé-boulé !",
          DialogueId = 10036336,
          Duration = 8,
          GUID = "191FF523",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF523"
        },
        [10036337] = {
          ContentFR = "Eh, cette année, personne n’a osé se déguiser en punaise d’eau ? Dommage, j’attendais ça.",
          DialogueId = 10036337,
          Duration = 7,
          GUID = "191FF524",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF524"
        },
        [10036338] = {
          ContentFR = "Grrrrr ! Je suis un Souillé ! Grrrrr ! Je vais te croquer !",
          DialogueId = 10036338,
          Duration = 6,
          GUID = "191FF525",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF525"
        },
        [10036339] = {
          ContentFR = "Fais attention où tu marches, je joue le cadavre.",
          DialogueId = 10036339,
          Duration = 4,
          GUID = "191FF526",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF526"
        },
        [10036340] = {
          ContentFR = "Eh ! C’est moi qui l’ai invitée à danser ! Tu cherches la bagarre ou quoi ?",
          DialogueId = 10036340,
          Duration = 8,
          GUID = "191FF527",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF527"
        },
        [10036341] = {
          ContentFR = "Pas de bagarre ici ! Même en pleine Fête de la Chandelle d’Argent, les règles sont les règles !",
          DialogueId = 10036341,
          Duration = 7,
          GUID = "191FF528",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF528"
        },
        [10036342] = {
          ContentFR = "Quelle carrure ! Je peux toucher tes abdos ?",
          DialogueId = 10036342,
          Duration = 6,
          GUID = "191FF529",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF529"
        },
        [10036343] = {
          ContentFR = "La représentation tout à l’heure était incroyable... Quelqu’un peut donner cette lettre à la sublime actrice principale pour moi ?",
          DialogueId = 10036343,
          Duration = 10,
          GUID = "191FF52A",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52A"
        },
        [10036344] = {
          ContentFR = "Superbe danse ! Bravo !",
          DialogueId = 10036344,
          Duration = 2,
          GUID = "191FF52B",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52B"
        },
        [10036345] = {
          ContentFR = "Matez mon ballon Souillé, on dirait un vrai, hein ?",
          DialogueId = 10036345,
          Duration = 6,
          GUID = "191FF52C",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52C"
        },
        [10036346] = {
          ContentFR = "Mais il est tôt encore ! Allez, on continue ! Cette nuit, personne ne dort ! Hahahaha !",
          DialogueId = 10036346,
          Duration = 9,
          GUID = "191FF52D",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52D"
        },
        [10036401] = {
          ContentFR = "Qui va là ?!",
          DialogueId = 10036401,
          GUID = "1920050A",
          SpeakNpcId = 100310,
          VoiceName = "voice/$Locale$/story/1003/100364/1920050A"
        },
        [10036402] = {
          ContentFR = "Feu !",
          DialogueId = 10036402,
          GUID = "19200534",
          SpeakNpcId = 100310
        },
        [10036501] = {
