        [10036557] = {
          Camera = "129.630859,-634.838989,126.636719,0.000079,7.986567,19.837446,35.000011,100000.0,false,DoNotOverride,22",
          ContentFR = "Rhythm nous avait dit que Blues détestait les paroles d’origine. Il les avait réécrites pour inventer une fin heureuse. Mais toi... tu as chanté la vraie version. Celle qui parle de repos sous le givre éternel.",
          DialogueId = 10036557,
          GUID = "19201EA2",
          LookAt = {
