          },
          NextDialogue = 10036568,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19202046"
        },
        [10036568] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          ContentFR = "Non. Blues est parti. Mais il ne voulait pas que sa sœur sache qui... l’avait tué.",
          DialogueId = 10036568,
          GUID = "19202070",
          LookAt = {
            [1] = "100327:n(100001)",
            [2] = "100001:n(100327)"
          },
          NextDialogue = 10036569,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19202070"
        },
        [10036569] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          ContentFR = "Tu es perspicace. Si seulement... nous avions été... aussi perspicaces à l’époque... Ça n’a plus d'importance maintenant. Les regrets ne changeront pas... le passé.",
          DialogueId = 10036569,
          GUID = "1920209A",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 100365691,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          VoiceName = "voice/$Locale$/story/1003/100365/1920209A"
        },
        [10036570] = {
          ContentFR = "Je vous ai menti. Dans ce récit, j’ai inversé nos noms. C’était Blues... qui m’a sauvé. C’est lui qui m’a rappelé ce que c’était... d’être humain.",
          DialogueId = 10036570,
          GUID = "192020C4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036570.T_Story_Recall_10036570'",
          NextDialogue = 10036571,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          VoiceName = "voice/$Locale$/story/1003/100365/192020C4"
        },
        [10036571] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          ContentFR = "Mais moi... j’avais déjà perdu ce droit. Les noms... ne sont que des illusions du passé. Alors... appelle-moi simplement <H>Phantasio</>.",
          DialogueId = 10036571,
          GUID = "192020EE",
          NextDialogue = 10036572,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192020EE"
        },
        [10036572] = {
