        },
        [10036602] = {
          ContentFR = "Ce secret... je l’emporterai dans la tombe.",
          DialogueId = 10036602,
          GUID = "19202604",
          NextDialogue = 10036603,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100366/19202604"
        },
        [10036603] = {
          Camera = "-508.236328,-141.803528,-26.71875,-0.001345,50.110828,41.260582,15.0,100000.0,false,Manual,22.0",
          ContentFR = "Blues... j’ai tenu ma promesse.",
          DialogueId = 10036603,
          FinalCamera = "-508.236328,-141.803528,-26.71875,-0.001344,55.910446,50.060265,15.0,100000.0,false,Manual,22.0",
          GUID = "1920262E",
          LookAt = {
            [1] = "100327:p(tuosi02_62_lookat)"
          },
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100327:p(70)"
          },
          VoiceName = "voice/$Locale$/story/1003/100366/1920262E"
        },
        [10036604] = {
          ContentFR = "Une fine entaille traverse le poignet du soldat, nette, trop régulière, manifestement infligée par une épée. Mais <H>sur cette scène, seuls la Légion et le "monstre" devraient avoir laissé leurs marques.</>",
          DialogueId = 10036604,
          GUID = "1920226A",
          NextOptions = {
            [1] = 10036605
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036605] = {
          ContentFR = "Effacer l’entaille",
          DialogueId = 10036605,
          GUID = "1920226B",
          NextDialogue = 10036606
        },
        [10036606] = {
          ContentFR = "La coupure est si fine qu’un simple geste suffit à en brouiller les contours. Des perles écarlates roulent, <H>comme si jamais aucun Chasseur de Phoxène armé d’une épée n’avait foulé cet endroit.</>",
          DialogueId = 10036606,
          GUID = "1920226C",
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036607] = {
          ContentFR = "Le corps est couvert de larges plaques noirâtres, brûlures électriques évidentes. Mais <H>sur cette scène, seuls la Légion et le "monstre" devraient avoir laissé leurs marques.</>",
          DialogueId = 10036607,
          GUID = "1920226D",
          NextOptions = {
            [1] = 10036608
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036608] = {
          ContentFR = "Arracher le câble",
          DialogueId = 10036608,
          GUID = "1920226E",
          NextDialogue = 10036609
        },
        [10036609] = {
          ContentFR = "La lampe sur pied éclate. Un câble rompu pend mollement, sectionné net. Des étincelles jaillissent dans une danse joyeuse, <H>comme si jamais aucun officier maniant la foudre n’avait mis les pieds ici.</> Dommage... c’était une si belle lampe.",
          DialogueId = 10036609,
          GUID = "1920226F",
          NextDialogue = 10036610,
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036610] = {
          ContentFR = "Maintenant, le décor est en place : la XIIIᵉ Légion a traqué la créature jusqu’au Théâtre Galea. <H>L’avant-garde, bien qu’ayant évacué les civils, est tombée sous les griffes du "monstre".</> Le gros des troupes est ensuite arrivé, a terrassé la bête, et clos la Traque aux Charons. Une chute de rideau parfaite... comme si l’histoire avait toujours été écrite ainsi.",
          DialogueId = 10036610,
          GUID = "19202270",
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036701] = {
          ContentFR = "Le type des Déchus est parti maintenant... Blues, ta blessure, comment... Blues ! Blues !",
          DialogueId = 10036701,
          GUID = "19203642",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036702,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203642"
        },
        [10036702] = {
          ContentFR = "Ce corps... n’est pas si indestructible que ça après tout... L’alchimie impériale... n’a rien d’un miracle.",
          DialogueId = 10036702,
          GUID = "1920366C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920366C"
        },
        [10036703] = {
          ContentFR = "... Ma sœur... son tir était précis, bien plus qu’avant... Elle sait se défendre, maintenant... Kof !",
          DialogueId = 10036703,
          GUID = "19203696",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036704,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203696"
        },
        [10036704] = {
          ContentFR = "C’est vraiment le moment de dire ça !?",
          DialogueId = 10036704,
          GUID = "192036C0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/192036C0"
        },
        [10036705] = {
          ContentFR = "Haa... haa...",
          DialogueId = 10036705,
          GUID = "192036EA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036706,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192036EA"
        },
        [10036706] = {
          ContentFR = "Tiens bon ! Je vais t’emmener à un médecin ! Même s’il faut les contraindre... même des monstres comme nous peuvent—",
          DialogueId = 10036706,
          GUID = "19203714",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036707,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203714"
        },
        [10036707] = {
          ContentFR = "... Pas la peine.",
          DialogueId = 10036707,
          GUID = "1920373E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036708,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920373E"
        },
        [10036708] = {
          ContentFR = "Tu n’as jamais voulu me dire... mais je sais d’où vient... ce sang qui ne part pas...",
          DialogueId = 10036708,
          GUID = "19203768",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036709,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203768"
        },
        [10036709] = {
          ContentFR = "Alors... mourir ici... c’est sans doute mieux pour tout le monde.",
          DialogueId = 10036709,
          GUID = "19203792",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036710,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203792"
        },
        [10036710] = {
          ContentFR = "« Mieux pour tout le monde » !? Et toi, alors !? Tu oublies ce que tu disais ? Une scène rien qu’à nous, un spectacle pour nos proches !",
          DialogueId = 10036710,
          GUID = "192037BC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036711,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/192037BC"
        },
        [10036711] = {
          ContentFR = "Désolé... je ne pourrai pas tenir cette promesse...",
          DialogueId = 10036711,
          GUID = "192037E6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036712,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192037E6"
        },
        [10036712] = {
          ContentFR = "Non... et ta sœur !? Celle que tu voulais revoir plus que tout ! Tu ne l’as même pas retrouvée !",
          DialogueId = 10036712,
          GUID = "19203810",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036713,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203810"
        },
        [10036713] = {
          ContentFR = "... Je suis lâche. Je disais vouloir la revoir... Mais quand je l’ai vue... je n’ai su que fuir...",
          DialogueId = 10036713,
          GUID = "1920383A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920383A"
        },
        [10036714] = {
          ContentFR = "J’ai... une dernière requête.",
          DialogueId = 10036714,
          GUID = "19203864",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036715,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203864"
        },
        [10036715] = {
          ContentFR = "Cette chaîne... est un gage. Retrouve ma sœur, dis-lui la vérité... sur la VIᵉ Légion. Qu’elle ne tombe pas dans leur piège... comme moi...",
          DialogueId = 10036715,
          GUID = "1920388E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036716,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920388E"
        },
        [10036716] = {
          ContentFR = "Et... <H>ne lui dis jamais... que je suis mort... de sa main.</> Elle ne le supporterait pas...",
          DialogueId = 10036716,
          GUID = "192038B8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036717,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192038B8"
        },
        [10036717] = {
          ContentFR = "Je t’en... supplie...",
          DialogueId = 10036717,
          GUID = "192038E2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036718,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192038E2"
        },
        [10036718] = {
          ContentFR = "Blues... !",
          DialogueId = 10036718,
          GUID = "1920390C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036719,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/1920390C"
        },
        [10036719] = {
          ContentFR = "Je te le promets.",
          DialogueId = 10036719,
          GUID = "19203936",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036720,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203936"
        },
        [10036720] = {
          ContentFR = "Mais... comment lui dire la vérité sans qu’elle devine ta mort...?",
          DialogueId = 10036720,
          GUID = "19203960",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036721,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203960"
        },
        [10036721] = {
          ContentFR = "... Je comprends.",
          DialogueId = 10036721,
          GUID = "1920398A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036722,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/1920398A"
        },
        [10036722] = {
          ContentFR = "<H>Il suffit de lui faire croire que "Blues" vit encore... et que "Blues" lui révèle la vérité.</> Oui...",
          DialogueId = 10036722,
          GUID = "192039B4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/192039B4"
        },
