        },
        [10037701] = {
          ContentFR = "Ô neige silencieuse, fille des cieux...",
          DialogueId = 10037701,
          GUID = "1920DA52",
          NextDialogue = 10037702,
          VoiceName = "voice/$Locale$/story/1003/100377/1920DA52"
        },
        [10037702] = {
          ContentFR = "Prie pour l’enfant sans nom.",
          DialogueId = 10037702,
          GUID = "1920DA53",
          NextDialogue = 10037703
        },
        [10037703] = {
          ContentFR = "Qui repose déjà sous le givre éternel.",
          DialogueId = 10037703,
          GUID = "1920DA54",
          NextDialogue = 10037704
        },
        [10037704] = {
          ContentFR = "Souviens-toi de son chant, de son visage d’antan,",
          DialogueId = 10037704,
          GUID = "1920DA55",
          NextDialogue = 10037705
        },
        [10037705] = {
          ContentFR = "et de son cœur, éclatant et immaculé.",
          DialogueId = 10037705,
          GUID = "1920DA56",
          NextDialogue = 10037706
        },
        [10037706] = {
          ContentFR = "Requiem pour les sans-nom",
          DialogueId = 10037706,
          GUID = "1920DA57"
        },
        [10037801] = {
          Content = "黎瑟·费西尔，进去找到我在墙壁上留下的<H>刻痕</>，等待下一步指示。",
          DialogueId = 10037801,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1920EABA",
          NextDialogue = 10037802,
          SpeakNpcId = 100310,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EABA"
        },
        [10037802] = {
          Content = "刻痕……刻痕……",
          DialogueId = 10037802,
          GUID = "1920EAE4",
          NextDialogue = 10037803,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EAE4"
        },
        [10037803] = {
          Content = "找到了，那边墙壁上有刀划过的痕迹。",
          DialogueId = 10037803,
          GUID = "1920EB0E",
          NextDialogue = 10037804,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB0E"
        },
        [10037804] = {
          Content = "在哪在哪？",
          DialogueId = 10037804,
          GUID = "1920EB38",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB38"
        },
        [10037805] = {
          ContentFR = "On y est presque... oui, juste devant, le passage sous la Place de la Paix d’Argent.",
          DialogueId = 10037805,
          GUID = "1920EB62",
          NextDialogue = 10037806,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB62"
        },
        [10037806] = {
          ContentFR = "Devant ? Mais le couloir est complètement inondé ! ... Attends ! La Princesse des Déchets a parlé d’une <H>vanne</> !",
          DialogueId = 10037806,
          GUID = "1920EB8C",
          NextDialogue = 10037807,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB8C"
        },
        [10037807] = {
          ContentFR = "En effet. Activons cette <H>vanne</> pour drainer l’eau. Nous pourrons passer après.",
          DialogueId = 10037807,
          GUID = "1920EBB6",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBB6"
        },
        [10037808] = {
          ContentFR = "Des Souillés ! Restez vigilants !",
          DialogueId = 10037808,
          GUID = "1920EBE0",
          NextDialogue = 10037809,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBE0"
        },
        [10037809] = {
          ContentFR = "N’était-ce pas censé être mieux entretenu ? Depuis des années l’Empire se vante de renforcer les infrastructures souterraines... et il suffit de taper un tuyau pour faire sortir plus de Souillés que d’eaux usées. Magnifique.",
          DialogueId = 10037809,
          GUID = "1920EC0A",
          NextDialogue = 10037810,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC0A"
        },
        [10037810] = {
          ContentFR = "Désolée... Je renforcerai la surveillance des égouts une fois la mission terminée...",
          DialogueId = 10037810,
          GUID = "1920EC34",
          NextDialogue = 10037811,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC34"
        },
        [10037811] = {
          ContentFR = "Je ne parlais pas de vous— ... oubliez ça. Occupons-nous d’eux.",
          DialogueId = 10037811,
          GUID = "1920EC5E",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC5E"
        },
        [10037812] = {
          ContentFR = "Voilà. Il reste encore une vanne, là-bas.",
          DialogueId = 10037812,
          GUID = "1920EC88",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC88"
        },
        [10037813] = {
          ContentFR = "C’est bon, on peut avancer.",
          DialogueId = 10037813,
          GUID = "1920ECB2",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920ECB2"
        },
        [10037995] = {
          ContentFR = "Peu importe ce qu’ils exigent de nous... n’oublie jamais : nous ne sommes pas des monstres.",
          DialogueId = 10037995,
          GUID = "19210B11",
          SpeakNpcId = 100328,
          VoiceName = "voice/$Locale$/story/1003/100379/19210B11"
        },
        [10037996] = {
          ContentFR = "Clive traîne souvent près du Quai du Vent-Murmure. Allez le trouver là-bas.",
          DialogueId = 10037996,
          GUID = "19210B10",
          SpeakNpcId = 200022,
          VoiceName = "voice/$Locale$/story/1003/100379/19210B10"
        },
        [10037997] = {
          ContentFR = "Je demanderai au docteur de s’occuper du papier et de l’encre. Quant au sceau, je compte sur vous pour aller le récupérer. Désolée... cette blessure finit vraiment par vous ralentir.",
          DialogueId = 10037997,
          GUID = "19210B0G",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100379/19210B0G"
        },
        [10037998] = {
          DialogueId = 10037998,
          FinalCamera = "2935.045898,2450.00293,654.427734,0.000057,-7.99936,-141.003235,35.0,100000.0,false,Manual,22.0",
          GUID = "19210B0C",
          Scripts = "PARA{\nMoveTo{\n_click{false},_delay{0},ActorId{100330},TargetPoint{\"movetPoint06\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n},\nMoveTo{\n_click{false},_delay{0},ActorId{100331},TargetPoint{\"movetPoint07\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n},\nMoveTo{\n_click{false},_delay{0},ActorId{100332},TargetPoint{\"movetPoint08\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n},\nMoveTo{\n_click{false},_delay{0},ActorId{100333},TargetPoint{\"movetPoint09\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n}\n}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 30
        },
        [10037999] = {
          DialogueId = 10037999,
          FinalCamera = "-2598.648438,-2713.077148,706.673462,0.00002,-10.600037,46.999477,35.0,100000.0,false,Manual,22.0",
          GUID = "19210B36",
          Scripts = "PARA{\nMoveTo{\n_click{false},_delay{0},ActorId{100330},TargetPoint{\"movetPoint04\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n},\nMoveTo{\n_click{false},_delay{0},ActorId{100331},TargetPoint{\"movetPoint03\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n},\nMoveTo{\n_click{false},_delay{0},ActorId{100332},TargetPoint{\"movetPoint02\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n},\nMoveTo{\n_click{false},_delay{0},ActorId{100333},TargetPoint{\"movetPoint01\"},MoveSpeed{100},Visibility{\"Show\"},Duration{3}\n}\n}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 30
        },
        [10038001] = {
          ContentFR = "Officiers... faites attention...",
          DialogueId = 10038001,
          GUID = "191DEA43",
          NextDialogue = 10038002,
          SpeakNpcId = 100322,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA43"
        },
        [10038002] = {
          ContentFR = "Encore eux... Pas une minute de répit avec ces saletés.",
          DialogueId = 10038002,
          GUID = "191DEA44",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA44"
        },
        [10038004] = {
          ContentFR = "Bien, à la suivante.",
          DialogueId = 10038004,
          GUID = "191DEA46",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA46"
        },
        [10038006] = {
          ContentFR = "Pff, elle est coincée cette fichue vanne... Je suis épuisée... À toi de jouer, petit larbin, je te laisse le soin de prouver ta force...",
          DialogueId = 10038006,
          GUID = "191DEA48",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA48"
        },
        [10038007] = {
          ContentFR = "Ça doit être la dernière.",
          DialogueId = 10038007,
          GUID = "191DEA49",
          NextDialogue = 10038008,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA49"
        },
        [10038008] = {
          ContentFR = "Hourra... Enfin !",
          DialogueId = 10038008,
          GUID = "191DEA4A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA4A"
        },
        [10038009] = {
          ContentFR = "Le panneau est de nouveau opérationnel. Utilisons-le pour couper le système de défense.",
          DialogueId = 10038009,
          GUID = "191DEA4B",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA4B"
        },
        [10038012] = {
          Content = "迈尔斯，再给我拿两个弹匣过来！喂，听得见吗！啧……通讯器又出问题了？",
          DialogueId = 10038012,
          GUID = "191EF0C3",
          NextDialogue = 10038013,
          SpeakNpcId = 100340,
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C3"
        },
        [10038013] = {
          Content = "嗯？是你们啊。",
          DialogueId = 10038013,
          GUID = "191EF0C4",
          NextDialogue = 10038014,
          SpeakNpcId = 100340,
          TurnTo = {
            [1] = "100341:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C4"
        },
        [10038014] = {
          Content = "你们的行动地点不是在前面吗？快去吧，这次行动决不允许有任何闪失。",
          DialogueId = 10038014,
          GUID = "191EF0C5",
          NextDialogue = 10038015,
          SpeakNpcId = 100340,
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C5"
        },
        [10038015] = {
          Content = "收到。",
          DialogueId = 10038015,
          GUID = "191EF0C6",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C6"
        },
        [10038101] = {
          ContentFR = "Pendant le couvre-feu de Givrelac, la circulation est strictement interdite dans cette zone.",
          DialogueId = 10038101,
          GUID = "19210B0D"
        },
        [10038102] = {
          ContentFR = "Le système de défense des égouts s’est enclenché. Il devrait nous prêter main forte.",
          DialogueId = 10038102,
          GUID = "191DE875",
          NextDialogue = 10038103,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE875"
        },
        [10038103] = {
          ContentFR = "Il y a un système de défense dans un endroit comme celui-ci ?!",
          DialogueId = 10038103,
          GUID = "191DE876",
          NextDialogue = 10038104,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE876"
        },
        [10038104] = {
          ContentFR = "Beaucoup d’équipements ont été installés par les Éolipyliens. Ils nous ont simplement dit de ne pas poser de questions.",
          DialogueId = 10038104,
          GUID = "191DE877",
          NextDialogue = 10038105,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE877"
        },
        [10038105] = {
          ContentFR = "Ils installent du matériel militaire dans les égouts... qu’est-ce qu’ils mijotent encore...",
          DialogueId = 10038105,
          GUID = "191DE878",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE878"
        },
        [10038201] = {
          DialogueId = 10038201,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "19210B0E",
          NextOptions = {
            [1] = 10038202
          }
        },
        [10038202] = {
          ContentFR = "Entrée de l’Hôpital de la Légion",
          DialogueId = 10038202,
          GUID = "19210B0F"
        },
        [10038301] = {
          Camera = "-352.324951,420.12915,199.878906,0.000157,-10.802886,-58.593517,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Allons, allons... J’ai juste entendu dire que tu avais été salement amochée, alors je viens gentiment prendre de tes nouvelles.",
          DialogueId = 10038301,
          FinalCamera = "-377.254883,404.907959,199.878906,0.000155,-10.602905,-55.19278,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA15",
          NextDialogue = 10038302,
          SpeakNpcId = 100006,
          TalkActionId = {
            [1] = "100006:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100383/1920CA15"
        },
        [10038302] = {
          Camera = "-158.971191,-46.777344,212.847656,0.000162,-24.602238,66.810852,55.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Inutile. Tant que je respire, je vais bien. Je ne suis pas un enfant riche et gâté comme toi.",
          DialogueId = 10038302,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-152.550293,-49.527588,212.847656,0.000171,-24.402216,70.010948,55.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA16",
          NextDialogue = 10037603,
          SpeakNpcId = 200022,
          TalkActionId = {
            [1] = "200022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100383/1920CA16"
        },
        [10038401] = {
          ContentFR = "Après ça, les Charons ont déclenché la guerre dans tout Hyperborea, tuant partout où ils passaient... Jusqu’à ce que Sa Majesté Dis Galea, le fondateur de l’Empire, dans sa grande clémence, mette fin au carnage et ramène la paix.",
          DialogueId = 10038401,
          GUID = "191E6E2B",
          NextDialogue = 10033922,
          SpeakNpcId = 100357,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E2B"
        },
        [10100101] = {
          ContentFR = "... Hé... Hé—",
          DialogueId = 10100101,
          Duration = 3.5,
          GUID = "1948D7D2",
          SpeakNpcId = 200002,
          Subtitle = "...Hello? ...Hello—",
          VoiceName = "voice/$Locale$/story/1002/101001/1948D7D2"
        },
        [10100102] = {
          ContentFR = "Tu— m’entends— là— ?",
          DialogueId = 10100102,
          Duration = 7,
          GUID = "1948D7FC",
          SpeakNpcId = 200002,
          Subtitle = "Can— you— hear— me—",
          VoiceName = "voice/$Locale$/story/1002/101001/1948D7FC"
        },
        [10100103] = {
          ContentFR = "<H>Camilla</>, regarde ! {nickname} s’est {性别:réveillé|réveillée} !",
          DialogueId = 10100103,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1948D826",
          SpeakNpcId = 200002,
          Subtitle = "Camilla, look! has woken up!",
          VoiceName = "voice/$Locale$/story/1002/101001/1948D826"
        },
        [10100201] = {
          Camera = "-196.878906,-289.845947,119.943359,0.001203,-1.699679,54.031475,35.0,450.0,false,Manual,4.0",
          ContentFR = "Hmm. En vie, mobile, et rien de cassé. Tant mieux.",
          DialogueId = 10100201,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1948D850",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200003:n(100001)"
          },
          NextDialogue = 10100202,
          RelatedWikiId = {
            [1] = 201001,
            [2] = 408001,
            [3] = 201002
          },
          SpeakNpcId = 200003,
          Subtitle = "Mmm. Alive and not incapacitated, no broken bones then.",
          TalkActionId = {
            [1] = "200003:Talk03_Loop",
            [2] = "\n100001:Story_Headache_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101001/1948D850"
        },
        [10100202] = {
          Camera = "1.257812,221.437988,150.764648,0.001272,-6.900089,-89.157776,35.0,323.951599,false,Manual,1.8",
          ContentFR = "Vous êtes... Qui êtes-vous ? Et comment connaissez-vous mon nom ? Berry, où est-ce qu’on...",
          DialogueId = 10100202,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "1948E83A",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10100203,
          Scripts = "PARA{\nPlayAnimation{ActorId{100001},AnimationId{\"Story_Headache_End\"},Duration{1}},\nLookAt{_delay{2.2},LookAtDescription{\"100001:n(200003)\"}},\nCameraMoveTo{_delay{5},TargetPosition{\"-113.109375,132.11084,145.952637,0.001274,-7.49926,-55.951866,35.54715,492.602234,false,DoNotOverride,1.8\"},duration{0}},\nLookAt{_delay{4.2},LookAtDescription{\"100001:p(P10100201Nvzhu)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Who are you...? How do you know my name? Berry, where are we—",
          VoiceName = "voice/$Locale$/story/1002/101002/1948E83A"
        },
        [10100203] = {
          Camera = "-22.90625,-45.071777,149.469238,0.001231,-17.499626,-66.962013,35.0,60.930546,false,Manual,4.493256",
          ContentFR = "Non... À ce moment-là, nous étions...",
          DialogueId = 10100203,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "1949781C",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10100204,
          SpeakNpcId = 100001,
          Subtitle = "No, we were...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101010/1949781C"
        },
        [10100204] = {
          ContentFR = "Je dois retrouver Berry. Si elle n’avait pas eu à me protéger, elle aurait sûrement échappé aux soldats...",
          DialogueId = 10100204,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "1948E88E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10100204.T_Story_Recall_10100204'",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10100205,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/01/flashing"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "(I must find Berry. If it weren't for me, she would've managed to escape from those soldiers...)",
          VoiceName = "voice/$Locale$/story/1002/101002/1948E88E"
        },
        [10100205] = {
          Camera = "-29.84375,9.120605,109.405273,0.001219,9.699885,-73.354439,35.0,117.889595,false,Manual,2.8",
          ContentFR = "Peut-être...",
          DialogueId = 10100205,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "1948E8B8",
          NextDialogue = 10100206,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "(Maybe...)",
          VoiceName = "voice/$Locale$/story/1002/101002/1948E8B8"
        },
        [10100206] = {
          Camera = "-113.203125,-295.231201,144.942871,0.001206,-5.299714,67.000038,35.0,368.848145,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Hé ! Tu comptes rester planté là combien de temps ? <H>Snow</> et Camilla ont fait tout ce chemin juste pour te sauver ! Alors suis-nous sagement en ville, sinon tu vas finir en casse-croûte pour le premier Souillé qui traîne !",
          DialogueId = 10100206,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          FinalCamera = "-115.261719,-294.439941,138.69043,0.001206,-5.299714,69.000008,35.0,371.583008,false,Manual,4.0",
          GUID = "1948E8E2",
          NextDialogue = 10100207,
          RelatedWikiId = {
            [1] = 201004,
            [2] = 201005
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{5},TargetPosition{\"-60.582031,-61.83252,90.654297,0.001224,-6.29949,77.795509,39.952579,130.753311,false,Manual,4.0\"},duration{0}},\nSEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Talk03_Start\"},Duration{1}},\nPlayAnimation{_delay{4},ActorId{200002},AnimationId{\"Talk03_End\"},Duration{2.7}},\nPlayAnimation{_delay{1},ActorId{200002},AnimationId{\"Explain02_Start\"},Duration{1.6}},\nPlayAnimation{ActorId{200002},AnimationId{\"Explain02_End\"},Duration{2.2}},\nPlayAnimation{ActorId{200002},AnimationId{\"Shock_Start\"},Duration{1}}\n},\nLookAt{_delay{0.9},LookAtDescription{\"100001:n(200002)\"}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Hey, are you even listening? Camilla and Snow have come all this way to save you! You better come with us to the city right now, or else you'll soon become a snack for some wandering Filthoids!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101002/1948E8E2"
        },
        [10100207] = {
          Camera = "-251.304688,292.147461,84.040039,1.999924,0.699848,-51.566563,35.000011,460.972412,false,Manual,3.0",
          ContentFR = "En... ville ?",
          DialogueId = 10100207,
          ExStoryInfo = "Player",
          GUID = "1948E90C",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 10100208,
          SpeakNpcId = 100001,
          Subtitle = "To... the city?",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E90C"
        },
        [10100208] = {
          Camera = "-48.933594,-71.695312,97.074219,0.001207,-9.199916,81.628067,36.0,141.230881,false,Manual,4.0",
          ContentFR = "Tu as eu peur, pas vrai ? Pas de panique, on sera bientôt en sécurité. <H>Givrelac</>, c’est la plus grande cité du nord d’Hyperborea !",
          DialogueId = 10100208,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "1948E936",
          NextDialogue = 10100209,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003
          },
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Think_Start\"},Duration{3}},\nPlayAnimation{ActorId{200002},AnimationId{\"Think_End\"},Duration{1.2}},\nPlayAnimation{ActorId{200002},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Got a fright, huh? No worries, you'll be safe in a jiffy — Icelake is the largest city in northern Hyperborea!",
          VoiceName = "voice/$Locale$/story/1002/101002/1948E936"
        },
        [10100209] = {
          Camera = "-36.417969,82.69043,124.596191,0.00116,-1.800137,-76.755249,35.000008,184.209518,false,Manual,4.0",
          ContentFR = "Hyperborea... Je suis donc dans l’Empire Hyperboréen... ?!",
          DialogueId = 10100209,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "1948E960",
          NextDialogue = 10100210,
          Scripts = "PARA{\nPlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}},\nLookAt{_delay{2},LookAtDescription{\"100001:n(200003)\"}},\nPlayFacial{_delay{2},ActorId{100001},FacialId{\"Shock01\"}},\nCameraMoveTo{_delay{2},TargetPosition{\"-29.773438,54.472656,127.289062,0.00116,-1.800137,-76.755142,35.000008,157.238007,false,Manual,4.0\"},duration{0.4}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Hyperborea... I'm in the Hyperborean Empire...?!",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E960"
        },
        [10100210] = {
          Camera = "4915.476562,-702.842285,1756.620605,0.000003,25.494759,-14.000834,12.000003,3073.631592,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Ben oui, pourquoi tu fais tout un drame ?",
          DialogueId = 10100210,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "4915.476562,-702.842285,1756.620605,0.000003,30.894625,-20.001587,12.000003,3073.631592,false,Manual,1.2",
          GUID = "1948E98A",
          NextDialogue = 10100211,
          Scripts = "PARA{\nPlayAnimation{ActorId{200002},AnimationId{\"Talk03_Start\"},Duration{2}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_End\"},Duration{2}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Well, yeah... What's the big deal?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101002/1948E98A"
        },
        [10100211] = {
          Camera = "321.105469,367.106934,155.726562,0.001201,-4.999698,-131.971817,50.0,560.205811,false,Manual,3.0",
          ContentFR = "Alors vous connaissez... Une femme, qui s’appelle Sibylle. Certains l’appellent « Commandante ». Elle doit se trouver dans ce pays... Je dois la retrouver.",
          DialogueId = 10100211,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1948E9B4",
          LookAt = {
            [1] = "100001:n(200003)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 10100212,
          SpeakNpcId = 100001,
          Subtitle = "Do you know this woman called Sibylle? Others refer to her as the "Chief," and she's supposed to be in this country... I need to find her.",
          TalkActionId = {
            [1] = "200002:Talk03_End",
            [2] = "\n100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E9B4"
        },
        [10100212] = {
          Camera = "109.613281,-278.998535,123.344238,0.001196,-0.900663,111.229919,35.0,350.570953,false,Manual,3.0",
          ContentFR = "Des Sibylle, il y en a à la pelle. Mais celle qu’on appelle « Commandante », il n’y en a qu’une. Tu veux vraiment la trouver ? Qu’est-ce qui t’a gelé le cerveau ?",
          DialogueId = 10100212,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "1948E9DE",
          NextDialogue = 10100213,
          RelatedWikiId = {
            [1] = 303003
          },
          Scripts = "SEQ{\nPlayAnimation{_delay{4},ActorId{200003},AnimationId{\"Talk03_End\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{200003},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Sibylle is a common name, but there's only one that's linked with the title "Chief." You want to find her? How did you lose your mind to the blizzard? I thought Charons are supposed to be resistant to cold temperatures.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E9DE"
        },
        [10100213] = {
          Camera = "94.464844,26.425293,178.743652,0.001218,-19.900541,-128.170197,36.276737,164.815262,false,Manual,2.909652",
          ContentFR = "Je ne plaisante pas. Elle détient peut-être... quelque chose qui compte plus que tout pour moi. Je dois savoir.",
          DialogueId = 10100213,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01",
            [2] = "200003:None",
            [3] = "200002:None"
          },
          GUID = "1948EA08",
          NextDialogue = 10100214,
          Scripts = "PARA{\nPlayAnimation{ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1.5}},\nPlayAnimation{_delay{5},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{5}},\nLookAt{_delay{5},LookAtDescription{\"100001:n(200003)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "I'm serious. She might've taken some...thing that's very important to me, so I must find her and get to the bottom of it.",
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA08"
        },
        [10100214] = {
          Camera = "67.046875,-72.922852,121.009277,0.001219,8.898916,104.827866,36.0,149.916138,false,Manual,2.8",
          ContentFR = "Espionnage, assassinat, rébellion... Rien qu’avec ce que tu viens de dire, les soldats de l’Empire auraient trois bonnes raisons de t’arrêter. Si tu veux vraiment rencontrer la Commandante, évite de foncer tête baissée.",
          DialogueId = 10100214,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "61.769531,-52.95752,124.242676,0.001221,8.898916,104.827972,36.0,132.852249,false,Manual,2.8",
          GUID = "1948EA32",
          NextDialogue = 10100215,
          Scripts = "SEQ{\nPlayAnimation{_delay{6},ActorId{200003},AnimationId{\"Think_End\"},Duration{2}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Espionage, assassination, defiance... With what you've just said, the Imperial soldiers could just arrest you for these three reasons alone. If you really want to find the Chief, I'd advise you not to rush into it.",
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA32"
        },
        [10100215] = {
          Camera = "90.78125,-235.538574,124.035156,0.001194,-0.900574,106.602898,35.000008,299.733246,false,Manual,2.8",
          ContentFR = "Dernier avertissement. Si tu ne veux pas finir en chair à Souillés, suis-nous.",
          DialogueId = 10100215,
          GUID = "1948EA5C",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextOptions = {
            [1] = 101002151,
            [2] = 101002152
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{3.8},TargetPosition{\"92.84375,-269.014404,124.547852,0.001194,-0.900574,106.602898,35.000008,299.733246,false,Manual,2.8\"},duration{4.5}},\nTurnTo{_delay{3.5},TurnToDescription{\"200003:p(180)\"}},\nPlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Angry01_End\"},Duration{2}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "For the last time, if you don't want to end up as Filthoid fodder, come with us.",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA5C"
        },
        [10100216] = {
          Camera = "-22.671875,234.560547,176.765625,0.00112,-9.999943,-80.167923,40.0,330.076355,false,Manual,2.602004",
          ContentFR = "Merci de m’avoir {性别:sauvé|sauvée}. Mais...",
          DialogueId = 10100216,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200003:Uninterested01"
          },
          GUID = "1948EA86",
          NextDialogue = 10100217,
          Scripts = "SetRotation{SetRotationDescription{"200003:p(25)"}}",
          SpeakNpcId = 100001,
          Subtitle = "Thanks for saving my life. But—",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948EA86"
        },
        [10100217] = {
          Camera = "-22.671875,234.560547,176.765625,0.00112,-9.999943,-80.167923,40.0,330.076355,false,Manual,2.602004",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Mais tu doutes. Tu te dis : « Ces deux inconnues n’ont aucune raison de m’aider. Elles cachent sûrement autre chose. »",
          DialogueId = 10100217,
          FinalCamera = "-15.765625,235.758301,176.765625,0.001125,-9.999943,-80.167831,40.0,173.539764,false,Manual,4.0",
          GUID = "1948EAB0",
          NextDialogue = 10100218,
          SpeakNpcId = 200003,
          Subtitle = "You're worried, and suspicious — "These two strangers must be up to something."",
          TalkActionId = {
            [1] = "200003:SpecialUnInterested_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101002/1948EAB0"
        },
        [10100218] = {
          Camera = "-15.765625,235.758301,176.765625,0.001125,-9.999943,-80.167831,40.0,173.539764,false,Manual,4.0",
          ContentFR = "... !",
          DialogueId = 10100218,
          Duration = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          FinalCamera = "-15.765625,235.758301,176.765625,0.001126,-9.999936,-80.167801,40.0,330.134827,false,Manual,6.0",
          GUID = "1948EADA",
          NextDialogue = 10100219,
          Scripts = "PlayAnimation{_delay{1},ActorId{200003},AnimationId{"SpecialUnInterested_End"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "...!",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "200002:Talk03_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101002/1948EADA"
        },
        [10100219] = {
          Camera = "-267.855469,347.076172,80.553223,0.001206,2.999996,-51.764427,35.0,515.485901,false,Manual,2.8",
          ContentFR = "Alors reste ici, {性别:seul|seule}, à réfléchir si tu as quoi que ce soit qui mérite qu’on s’intéresse à toi.",
          DialogueId = 10100219,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "1948EB04",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 10100220,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.5},TargetPosition{\"-292.558594,327.608887,68.172363,0.001206,2.99999,-51.764473,35.0,519.91864,false,Manual,2.8\"},Blend{\"easeInQuad\"},duration{12}},\nMoveTo{_delay{1},ActorId{200003},TargetPoint{\"P10100218Kami\"},MoveSpeed{60}},\nSEQ{\nTurnTo{_delay{1.5},TurnToDescription{\"200002:p(150)\"}},\nMoveTo{_delay{0.5},ActorId{200002},TargetPoint{\"P10100218Bai\"},MoveSpeed{201}}\n}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Then stay here and mull it over by yourself, if you think there's anything about you that's worth anyone's time.",
          VoiceName = "voice/$Locale$/story/1002/101002/1948EB04"
        },
        [10100220] = {
