        [10100301] = {
          ContentFR = "Tu es {性别:couvert|couverte} d’égratignures... Tu tiens le coup ?",
          DialogueId = 10100301,
          GUID = "1948F8A2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100302,
          SpeakNpcId = 200002,
          Subtitle = "You seem to be all bruises and cuts, are you alright?",
          VoiceName = "voice/$Locale$/story/1002/101003/1948F8A2"
        },
        [10100302] = {
          ContentFR = "Ça va. Je ne sens déjà plus la douleur.",
          DialogueId = 10100302,
          ExStoryInfo = "Player",
          GUID = "1948F8CC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10100303,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. The pain's gone now.",
          VoiceName = "voice/$Locale$/story/1002/101003/1948F8CC"
        },
        [10100303] = {
          ContentFR = "T’as dû vivre un sacré cauchemar... Mais pas d’inquiétude !",
          DialogueId = 10100303,
          GUID = "1948F8F6",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100304,
          SpeakNpcId = 200002,
          Subtitle = "Something really bad must've happened to you... But no worries!",
          VoiceName = "voice/$Locale$/story/1002/101003/1948F8F6"
        },
        [10100304] = {
          ContentFR = "Désormais, Snow te protège ! Moi, la grandiose, l’unique, la radieuse Snow, je suis—",
          DialogueId = 10100304,
          GUID = "1948F920",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "You're under my wing now! Snow will protect you! After all, Snow is—",
          VoiceName = "voice/$Locale$/story/1002/101003/1948F920"
        },
        [10100305] = {
          ContentFR = "Waaaaah— !! Là-bas, c’est... c’est c’est c’est quoi ça ?!",
          DialogueId = 10100305,
          GUID = "1948F94A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Woooaaah—!! What is that over there?!",
          VoiceName = "voice/$Locale$/story/1002/101003/1948F94A"
        },
        [10100400] = {
