          FacialId = {
            [1] = "200002:Unhappy02"
          },
          FinalCamera = "1682.876953,720.09375,451.056152,0.000121,-11.19806,178.377457,25.0,1350.0,false,Manual,1.2",
          GUID = "1949090A",
