          SpeakNpcId = 200002,
          Subtitle = "Phew, thank goodness we took them down...",
          VoiceName = "voice/$Locale$/story/1002/101004/19490934"
        },
        [10100403] = {
          Camera = "338.273438,401.17749,114.637207,0.000239,-8.396604,68.781586,35.0,166.80806,false,Manual,4.0",
          ContentFR = "Moi, peur ?! P-Pas du tout ! Je... je me faisais juste du souci pour ce pauvre conducteur !",
          DialogueId = 10100403,
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "1949095E",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 10100405,
          SpeakNpcId = 200002,
          Subtitle = "I'm not afraid! I... I was just worried about that poor driver!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101004/1949095E"
        },
        [10100404] = {
          Camera = "338.273438,401.17749,114.637207,0.000239,-8.396604,68.781586,35.0,166.80806,false,Manual,4.0",
          ContentFR = "Ça... ça, c’était pour tester ton incroyable potentiel ! Une petite épreuve, quoi !",
          DialogueId = 10100404,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Shock01"
