          NextDialogue = 10100405,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Shock_Start\"},Duration{0.1}},\nPlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Shock_End\"},Duration{0.1}},\nPlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{0.1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Well... that was because you seemed so talented, so I decided to give you a simple test...",
          VoiceName = "voice/$Locale$/story/1002/101004/19490988"
        },
        [10100405] = {
          Camera = "366.103516,691.627686,81.682129,0.000208,5.202363,-84.999977,35.0,315.269531,false,Manual,6.0",
