            [2] = 301006
          },
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Confident_End\"},Duration{0.1}},\nPlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Think_Start\"},Duration{0.1}},\nPlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Think_End\"},Duration{0.1}},\nPlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Explain01_Start\"},Duration{0.1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "The south of Hyperborea, under a huge Heaventree? It's far, far away, over 1,500 kilometres from here.",
