          Scripts = "PARA{\nCameraMoveTo{_delay{3.5},TargetPosition{\"5370.160156,1657.839844,1799.607666,-4.000001,-17.798576,-166.386627,35.0,5477.637207,false,Manual,1.2\"},duration{0}},\nCameraMoveTo{_delay{3.6},TargetPosition{\"5673.675781,1731.34375,1899.862793,-5.000006,-17.798576,-166.386658,35.0,5477.637207,false,Manual,1.2\"},duration{5}}\n}",
          SnapShot = "HEART",
