          Subtitle = "(But who... and why would they bring me here?)",
          ToFinalCameraBlendTime = 3.4,
          VoiceName = "voice/$Locale$/story/1002/101004/19490AD8"
        },
        [10100501] = {
          ContentFR = "Voilà les portes de la cité ! Colle-toi à nous, on te fera passer discrètement !",
          DialogueId = 10100501,
          GUID = "19491972",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10100502,
          SpeakNpcId = 200002,
          Subtitle = "The city gate is just up ahead. Follow behind us, we'll get you in!",
          VoiceName = "voice/$Locale$/story/1002/101005/19491972"
        },
        [10100502] = {
          ContentFR = "Et surtout, pas un mot de trop. S’il y a un problème, notre infaillible Camilla saura arranger ça !",
          DialogueId = 10100502,
          GUID = "1949199C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100503,
          SpeakNpcId = 200002,
          Subtitle = "And keep your mouth shut. If anything comes up, our almighty Camilla will take care of it!",
          VoiceName = "voice/$Locale$/story/1002/101005/1949199C"
        },
        [10100503] = {
