          ContentFR = "Quelle île ? Y en a des centaines au sud.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100607,
          GUID = "19492AD6",
          NextDialogue = 10100608,
          Scripts = "SEQ{\nSetLocation{ActorId{200002},TargetPoint{\"P101006Bai\"},Visibility{\"Show\"}},\nSetLocation{ActorId{200003},TargetPoint{\"P101006Kami\"},Visibility{\"Show\"}},\nSetLocation{ActorId{100001},TargetPoint{\"P101006Player\"},Visibility{\"Show\"}}\n}",
