        },
        [10100610] = {
          Camera = "318.783203,25.541016,175.118164,0.001212,-9.69867,-171.999939,35.0,431.538452,false,Manual,4.0",
          ContentFR = "Oui, cet enfant est l’{性别:orphelin|orpheline} de mon cousin. Ils ont été attaqués par des Souillés en venant de Malverne... Toute la famille a péri, {性别:il n’a survécu|elle n’a survécue} que par miracle.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100610,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile01",
            [2] = "200003:None"
          },
          GUID = "19492B54",
          LookAt = {
            [1] = "100001:n(200071)",
            [2] = "200003:n(200071)",
            [3] = "200002:n(200071)"
          },
          NextDialogue = 10100612,
          Scripts = "PARA{\nPARA{\nMoveTo{ActorId{200002},TargetPoint{\"P101006Bai\"},MoveSpeed{10},Visibility{\"Show\"}},\nPlayAnimation{_delay{6},ActorId{200003},AnimationId{\"Talk01_End\"},Duration{1}}\n},\nSEQ{\nCameraMoveTo{_delay{4},TargetPosition{\"-1080.685547,-5501.387695,2266.973145,0.0012,-9.499632,139.245468,80.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-1126.948242,-5555.071289,2266.972412,0.0012,-9.499632,139.245468,80.0,100000.0,false,DoNotOverride,2.8\"},Blend{\"easeInOutQuad\"},duration{12}}\n}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Ah, yes, this is my cousin's child. They were attacked by Filthoids on their way from Marberg. My cousin died... But this kid miraculously survived.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200003:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101006/19492B54"
        },
        [10100611] = {
          Camera = "-1080.685547,-5501.387695,2266.973145,0.0012,-9.499632,139.245468,80.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... {性别:Il|Elle} vient du sud, {性别:envoyé|envoyée} par le Domaine Vivar pour une livraison. Mais le pont était verglacé, la charrette a basculé, et les Souillés ont dévoré la cargaison...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100611,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "-1126.948242,-5555.071289,2266.972412,0.0012,-9.499632,139.245468,80.0,100000.0,false,DoNotOverride,2.8",
          GUID = "19492B7E",
          LookAt = {
            [1] = "200002:n(200071)m100001:n(200071)"
          },
          NextDialogue = 10100612,
          Scripts = "SEQ{\nSetLocation{ActorId{200002},TargetPoint{\"P101006Bai\"},Visibility{\"Show\"}},\nSetLocation{ActorId{200003},TargetPoint{\"P101006Kami\"},Visibility{\"Show\"}},\nSetLocation{ActorId{100001},TargetPoint{\"P101006Player\"},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "...{性别:He|She}'s from the south, sent by the Vivar Winery to deliver goods. The bridge was slippery, so the cart overturned, and some Filthoids destroyed this poor thing's cargo and luggage.",
          TalkActionId = {
            [1] = "200071:Confident_End",
            [2] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101006/19492B7E"
        },
        [10100612] = {
          Camera = "318.783203,25.541016,175.118164,0.001212,-9.69867,-171.999939,35.0,431.538452,false,Manual,4.0",
          ContentFR = "Je ferai refaire le permis de circulation au plus vite. Mais cette pauvre âme est traumatisée. Ayez un peu de compassion, {性别:laissez-le|laissez-la} au moins entrer manger un repas chaud.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100612,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19492BA8",
          LookAt = {
            [1] = "200002:n(200071)",
            [2] = "100001:n(200071)"
          },
          NextOptions = {
            [1] = 101006121,
            [2] = 101006122
          },
          Scripts = "PlayAnimation{ActorId{200003},AnimationId{"Talk02_Start"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "I'll reapply for the travel permit soon, but the child is quite shaken. Please, have mercy on this poor thing, let {性别:him|her} in for a warm meal.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101006/19492BA8"
        },
        [10100613] = {
          Camera = "-184.384766,162.758789,125.498535,0.001232,0.301116,-34.69698,38.839439,410.389923,false,Manual,2.4",
          ContentFR = "{性别:Hé, oh... tu n’es plus un gamin, arrête de pleurnicher !|Hé, oh... pourquoi tu pleures ? Zut, on nous a jamais dit quoi faire avec une demoiselle en larmes !}",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100613,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "19492BD2",
          LookAt = {
            [1] = "100001:n(200071)",
            [2] = "200071:n(100001)"
          },
          NextDialogue = 10100614,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200071},AnimationId{\"Talk01_Start\"},Duration{2}},\nPlayAnimation{_delay{2},ActorId{200071},AnimationId{\"Talk01_End\"},Duration{1}}\n}",
          SpeakNpcId = 200071,
          SpeakNpcName = "UI_Npc_Name_Man_4",
          Subtitle = "{性别:Whoa... aren't you a bit old to be a crybaby, mate? Stop it...|Whoa... why are you crying? Darn it, Chief never told us how to deal with tearful young ladies!}",
          TalkActionId = {
            [1] = "200003:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101006/19492BD2"
        },
        [10100614] = {
          Camera = "-0.116211,61.776855,134.516113,0.001232,2.701039,-32.100098,35.0,203.17984,false,Manual,3.0",
          ContentFR = "Avant, on aurait pu fermer les yeux. Mais... vous savez bien, Madame Camilla, le pays entier traque ces soi-disant « Déçus » je ne sais plus quoi, alors la Commandante a ordonné des fouilles serrées partout.",
          DialogueId = 10100614,
          GUID = "19492BFC",
          LookAt = {
            [1] = "200071:n(200003)"
          },
          NextDialogue = 10100615,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{_delay{2.6},ActorId{200071},AnimationId{\"Disagree\"},Duration{2.8}},\nPlayAnimation{ActorId{200071},AnimationId{\"Think_Start\"},Duration{6.5}},\nPlayAnimation{ActorId{200071},AnimationId{\"Think_End\"},Duration{0.5}},\nPlayAnimation{ActorId{200071},AnimationId{\"Talk01_Start\"},Duration{2.8}},\nPlayAnimation{ActorId{200071},AnimationId{\"Talk01_End\"},Duration{2}},\nLookAt{LookAtDescription{\"200071:p(P10100601)\"}}\n},\nCameraMoveTo{_delay{8},TargetPosition{\"1739.045898,-629.733398,519.800781,0.001235,-15.497944,171.899292,13.316677,2460.969238,false,Manual,1.2\"},duration{0}},\nCameraMoveTo{_delay{8.1},TargetPosition{\"1723.026367,-742.312988,519.800049,0.001235,-15.497944,171.899292,13.316677,2460.969238,false,Manual,1.2\"},Blend{\"easeInOutQuad\"},duration{10}}\n}",
          SpeakNpcId = 200071,
          SpeakNpcName = "UI_Npc_Name_Man_4",
          Subtitle = "This would've been a simple matter in the past, Ms Camilla, but... you know, recently that "Fork Shakens" or something is wanted nationwide, so the Chief specifically asked for strict security checks across towns.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101006/19492BFC"
        },
        [10100615] = {
          Camera = "71.237305,19.397461,134.438965,0.001202,0.399996,-170.399307,35.0,165.0,false,Manual,4.0",
          ContentFR = "... On dit les « Déchus ». Et je jure sur mon honneur, moi, Camilla Scarlet, qu’{性别:il|elle} n’a strictement rien à voir avec eux.",
          DialogueId = 10100615,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Smile02",
            [2] = "100001:Smile01"
          },
          GUID = "19492C26",
          LookAt = {
            [1] = "200071:n(200003)"
          },
          NextDialogue = 10100616,
          RelatedWikiId = {
            [1] = 101004
          },
          Scripts = "PARA{\nSetLocation{ActorId{200002},TargetPoint{\"P101006Bai\"},Visibility{\"Hide\"}},\nSEQ{\nPlayAnimation{ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{2.6}},\nPlayAnimation{ActorId{200003},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{ActorId{200003},AnimationId{\"Explain02_Start\"},Duration{3}},\nPlayAnimation{ActorId{200003},AnimationId{\"Explain02_End\"},Duration{3}},\nPlayAnimation{ActorId{200003},AnimationId{\"DisagreeHead\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200003,
          Subtitle = "...It's the Forsakens. I tell you what — I, Camilla Scarlet, on my honour, assure you that {性别:he|she} has nothing to do with the Forsakens.",
          VoiceName = "voice/$Locale$/story/1002/101006/19492C26"
        },
        [10100616] = {
          Camera = "-365.87207,335.160156,119.696777,0.001258,-1.199463,-44.99984,35.000008,640.0,false,Manual,10.0",
          ContentFR = "Bon... si c’est votre parole, j’ai confiance. Mais surtout, {性别:surveillez-le|surveillez-la} bien ! Pas d’ennuis en ville, sinon la Commandante nous tombera dessus tous les deux.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100616,
          ExStoryInfo = "Player",
          GUID = "19492C50",
          NextDialogue = 10100617,
          Scripts = "PARA{\nSetLocation{ActorId{200002},TargetPoint{\"P101006Bai\"},Visibility{\"Show\"}},\nSEQ{\nPlayAnimation{_delay{5},ActorId{200071},AnimationId{\"Talk01_Start\"},Duration{4.8}},\nPlayAnimation{ActorId{200071},AnimationId{\"Talk01_End\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200071,
          SpeakNpcName = "UI_Npc_Name_Man_4",
          Subtitle = "Alright, I trust you, Ms Camilla. But remember, keep a close eye on this kid and don't let {性别:him|her} stir up any trouble in town. If the Chief finds out about this, we'll both be in for it.",
          TalkActionId = {
            [1] = "200071:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/101006/19492C50"
        },
        [10100617] = {
          Camera = "318.783203,25.541016,175.118164,0.001212,-9.69867,-171.999939,35.0,431.538452,false,Manual,10.0",
          ContentFR = "Merci de votre indulgence. Hé... la prochaine fois que vous viendrez aux Asphodèles, je vous offrirai la tournée.",
          DialogueId = 10100617,
          FacialId = {
            [1] = "200002:Happy01",
            [2] = "100001:Smile02"
          },
          GUID = "19492C7A",
          LookAt = {
            [1] = "200071:n(200003)",
            [2] = "200003:n(200071)",
            [3] = "200002:n(200071)",
            [4] = "100001:n(200071)"
          },
          Scripts = "PARA{\nPlayAnimation{ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{200003},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Thank you very much. Next time you come to The Asphodel, it's on the house.",
          VoiceName = "voice/$Locale$/story/1002/101006/19492C7A"
        },
        [10100701] = {
          ContentFR = "Pas d’ennuis en ville, compris ?",
          DialogueId = 10100701,
          GUID = "19493A42",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_Man_4",
          Subtitle = " Don't cause any trouble in town, you hear me?",
          VoiceName = "voice/$Locale$/story/1002/101007/19493A42"
        },
        [10100801] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0",
          ContentFR = "Jolie prestation.",
          DialogueId = 10100801,
          GUID = "19494AAA",
          LookAt = {
