          DialogueId = 10101101,
          Duration = 1.3,
          GUID = "19497BE2",
          SpeakNpcId = 200005,
          SpeakNpcName = "UI_Npc_Name_Man_14",
          Subtitle = "Who's there?",
          VoiceName = "voice/$Locale$/story/1002/101011/19497BE2"
        },
        [10101102] = {
          ContentFR = "Hum, hum ! Je suis le Rédempteur Immaculé ☆ Roi Démon de la Lumière. Écoute bien, cet humain...",
          DialogueId = 10101102,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "19497C0C",
          SpeakNpcId = 200002,
          Subtitle = "Um, ahem! I am the Pure-white Redeemer ☆ Demon King of Light. Listen well, this person...",
          VoiceName = "voice/$Locale$/story/1002/101011/19497C0C"
        },
        [10101103] = {
