          VoiceName = "voice/$Locale$/story/1002/101015/1949BDAC"
        },
        [10101601] = {
          Camera = "-27.178654,-555.624878,53.106678,0.001023,6.799945,85.991287,35.000008,541.773254,false,Manual,2.8",
          ContentFR = "Cette chambre vient d’être nettoyée, tu pourras y passer la nuit.",
          DialogueId = 10101601,
          FacialId = {
            [1] = "200006:Smile01"
          },
