            [6] = 201006
          },
          SpeakNpcId = 200006,
          SpeakNpcName = "UI_Npc_Name_Woman_5",
          Subtitle = "This room has just been cleaned up. You can stay here tonight.",
          TalkActionId = {
            [1] = "200006:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CDEA"
        },
        [10101602] = {
          Camera = "-104.615982,62.744629,161.785751,0.001225,-15.299227,-48.170513,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Trop bien !",
          DialogueId = 10101602,
          FacialId = {
            [1] = "100001:Satisfy01",
            [2] = "200002:Smile02"
          },
          GUID = "1949CE14",
          LookAt = {
            [1] = "200002:n(200006)"
          },
          NextDialogue = 10101603,
          Scripts = "PlayAnimation{_delay{0.8},ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Cool!",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "200006:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101016/1949CE14"
        },
        [10101603] = {
          Camera = "9.080318,-196.48999,134.954025,0.001162,-2.098801,82.004311,35.000008,182.297424,false,Manual,1.993266",
          ContentFR = "Ne le prends pas mal, en réalité Monsieur Henrik n’est pas si avide d’argent. C’est juste que nous avons eu beaucoup de soucis ces derniers temps... Sinon, il n’aurait jamais pensé à vendre le vieux manoir pour joindre les deux bouts.",
          DialogueId = 10101603,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "9.080318,-196.48999,134.954025,0.001162,-0.498747,82.004166,35.000008,182.297424,false,Manual,1.993266",
          GUID = "1949CE3E",
          LookAt = {
            [1] = "200002:n(200006)"
          },
          NextDialogue = 10101604,
          Scripts = "SEQ{\nPlayAnimation{_delay{3.2},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{2.2}},\nPlayAnimation{ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          SpeakNpcName = "UI_Npc_Name_Woman_5",
          Subtitle = "Don't be upset, Mr Henrik isn't really that greedy. It's just we've been quite strapped for cash lately, otherwise he wouldn't consider selling his old house to make ends meet.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CE3E"
        },
        [10101604] = {
          Camera = "514.823242,883.764648,19.116735,0.001284,15.399822,113.199203,20.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Il est resté à l’abandon quelques années, mais après un bon coup de balai, ça va encore. Au moins, Il te protégera du froid !",
          DialogueId = 10101604,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "514.823242,883.764648,19.116735,0.001299,21.399582,117.397598,20.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1949CE68",
          LookAt = {
            [1] = "200006:n(200002)"
          },
          NextDialogue = 10101605,
          SpeakNpcId = 200006,
          SpeakNpcName = "UI_Npc_Name_Woman_5",
          Subtitle = "It's been neglected for years, but after a good clean, it's not half bad, right? At least it keeps out the chill!",
          TalkActionId = {
            [1] = "200006:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CE68"
        },
        [10101605] = {
          Camera = "-2.861805,-359.476807,84.442955,0.001134,6.300248,88.226242,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh, j’ai oublié de me présenter. Je m’appelle Psyche. Je vis à la Maison d’Hypnos, et j’aide parfois Monsieur Henrik dans ses tâches.",
          DialogueId = 10101605,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "1949CE92",
          NextOptions = {
            [1] = 101016051
          },
          RelatedWikiId = {
            [1] = 201007
          },
          Scripts = "PARA{\nLookAt{_delay{0.7},LookAtDescription{\"200006:n(100001)\"}},\nPlayAnimation{_delay{3},ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          SpeakNpcName = "UI_Npc_Name_Woman_5",
          Subtitle = "Oh, I haven't introduced myself. I'm Psyche, a lodger at the Hypnos' House. And sometimes I help Mr Henrik around.",
          VoiceName = "voice/$Locale$/story/1002/101016/1949CE92"
        },
        [10101606] = {
          Camera = "27.138054,-156.057861,139.726425,0.001145,-0.899987,94.422188,35.000008,151.066788,false,Manual,6.0",
          ContentFR = "{nickname}... C’est un nom peu courant dans cette ville.",
          DialogueId = 10101606,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Shock01"
          },
          FinalCamera = "22.871933,-157.254639,139.726349,0.001144,-0.899987,89.422119,35.000008,151.066788,false,Manual,6.0",
          GUID = "1949CEBC",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10101607,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200006},AnimationId{\"Explain02_End\"},Duration{2.3}},\nPlayAnimation{ActorId{200006},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "... That's quite an uncommon name in this city.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CEBC"
        },
        [10101607] = {
          Camera = "1.366581,-117.323242,128.956024,0.001123,6.301252,86.81572,30.0,246.598358,false,DoNotOverride,6.0",
          ContentFR = "Monsieur Henrik a dit que tu n’es pas d’ici. Alors, d’où viens-tu ? Et tes vêtements... je n’en ai jamais vu de pareils.",
          DialogueId = 10101607,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "-3.820999,-117.098145,128.956009,0.001121,6.301252,83.615379,30.0,246.598358,false,DoNotOverride,6.0",
          GUID = "1949CEE6",
          NextDialogue = 10101608,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200006},AnimationId{\"Think_End\"},Duration{1.8}},\nPlayAnimation{ActorId{200006},AnimationId{\"Talk02_Start\"},Duration{1.7}},\nPlayAnimation{ActorId{200006},AnimationId{\"Talk02_End\"},Duration{0.8}},\nPlayAnimation{ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "Mr Henrik mentioned you're not a local. Where are you from? Your outfit is quite unfamiliar to me.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CEE6"
        },
        [10101608] = {
          Camera = "-119.057526,53.523438,152.974731,0.001128,-7.099667,-35.000065,35.0,216.15033,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "D’une petite île, très loin au sud.",
          DialogueId = 10101608,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "-142.615875,70.019287,156.556641,0.001128,-7.099694,-35.000011,35.0,235.859222,false,Manual,6.0",
          GUID = "1949CF10",
          NextDialogue = 10101609,
          SpeakNpcId = 100001,
          Subtitle = "A small island, far, far to the south.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CF10"
        },
        [10101609] = {
          Camera = "-501.263092,171.315674,65.855347,0.001166,3.698513,-26.395926,35.0,608.684143,false,Manual,2.494663",
          ContentFR = "Le sud... je vois ! L’endroit où il y a toutes les saisons, même le printemps ! Et une île... alors tu as sûrement vu l’océan. On raconte qu’il est plus vaste qu’une centaine de Lacs du Deuil réunis...",
          DialogueId = 10101609,
          FacialId = {
            [1] = "200006:Happy01"
          },
          FinalCamera = "-503.960846,165.880859,65.855438,0.001167,3.698513,-23.395102,35.0,608.684143,false,Manual,2.494663",
          GUID = "1949CF3A",
          NextDialogue = 10101610,
          RelatedWikiId = {
            [1] = 301005
          },
          Scripts = "PARA{\nSEQ{\nPlayAnimation{_delay{1.2},ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{2.8}},\nPlayAnimation{ActorId{200006},AnimationId{\"Explain02_End\"},Duration{3}},\nPlayAnimation{ActorId{200006},AnimationId{\"Think_Start\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200006,
          Subtitle = "The South — I know it! It's a place with four seasons, including spring! And an island... you must have seen the "ocean." I've heard it's even bigger than a hundred Lamenting Lakes put together...",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CF3A"
        },
        [10101610] = {
          Camera = "-104.615982,62.744629,161.785751,0.001225,-15.299227,-48.170513,20.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 10101610,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-104.615982,62.744629,161.785751,0.001222,-16.499994,-51.000015,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1949CF64",
          NextOptions = {
            [1] = 101016101,
            [2] = 101016102
          },
          Scripts = "PARA{\nPlayNormalSound{EventPath{\"event:/sfx/common/story/01/hungry\"},PlayAs2D{false}},\nLookAt{_delay{0.5},LookAtDescription{\"200006:n(200002)\"}},\nLookAt{_delay{1},LookAtDescription{\"100001:n(200006)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "(Stomach growls)",
          ToFinalCameraBlendTime = 1.5,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CF64"
        },
        [10101611] = {
          Camera = "-104.615982,62.744629,161.785751,0.001222,-16.499994,-51.000015,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "M... même pas ! Le peuple Luno n’est pas aussi fragile que vous, on n’a pas le ventre vide pour si peu !",
          DialogueId = 10101611,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          GUID = "1949CF8E",
          LookAt = {
            [1] = "200002:p(P10101601)",
            [2] = "200006:n(200002)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10101612,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{1}},\nPlayAnimation{ActorId{200002},AnimationId{\"Angry01_End\"},Duration{1}},\nPlayAnimation{ActorId{200002},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "O-Of course not! We luno folks aren't as fragile as you... We don't get hungry so easily.",
          VoiceName = "voice/$Locale$/story/1002/101016/1949CF8E"
        },
        [10101612] = {
          Camera = "19.240356,-248.929688,148.129822,0.001204,-4.699122,90.242226,35.000008,232.110077,false,Manual,6.0",
          ContentFR = "... Vous avez faim ? Attendez un peu, je vais vous chercher de quoi manger !",
          DialogueId = 10101612,
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "1949CFB8",
          LookAt = {
            [1] = "200006:n(200002)",
            [2] = "100001:n(200006)",
            [3] = "200002:n(200006)"
          },
          NextDialogue = 10101613,
          Scripts = "PARA{\nTurnTo{_delay{3},TurnToDescription{\"200006:p(-150)\"}},\nMoveTo{_delay{6},_click{true},ActorId{200006},TargetPoint{\"P10101612Saiqi\"},MoveSpeed{400},Visibility{\"Hide\"}},\nCameraMoveTo{_delay{4.5},TargetPosition{\"17.315308,-248.963501,148.129822,0.001204,-4.699095,91.0,35.000008,146.735443,false,Manual,8.0\"},duration{2}},\nLookAt{_delay{2},LookAtDescription{\"200006:n(200006)\"}},\nCameraMoveTo{_delay{8},TargetPosition{\"-37.588226,45.485596,139.596191,0.001205,-1.698975,-59.999969,35.000008,175.44841,false,Manual,5.0\"},duration{0}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "...Are you hungry? I'll get you something to eat. Be right back!",
          TalkActionId = {
            [1] = "200006:Think_End",
            [2] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101016/1949CFB8"
        },
        [10101613] = {
          Camera = "-60.662338,-53.026855,76.228203,0.001223,6.199516,-64.1409,25.000002,82.790894,false,Manual,6.0",
          ContentFR = "Franchement... qui aurait cru que ce tenancier si rustre et morose ait à son service une fille aussi serviable et pleine de cœur...",
          DialogueId = 10101613,
          FacialId = {
            [1] = "200002:Smile01",
            [2] = "100001:Satisfy01"
          },
          FinalCamera = "-65.389259,-55.179199,76.228287,0.001223,6.199516,-62.741081,25.000002,84.377983,false,Manual,6.0",
          GUID = "1949CFE2",
          LookAt = {
            [1] = "200002:n(200006)",
            [2] = "100001:n(200006)",
            [3] = "200006:n(200006)"
          },
          NextDialogue = 10101614,
          SpeakNpcId = 200002,
          Subtitle = "Who'd have thought such a rude and gloomy innkeeper would have such a nice and helpful kid working for him...",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CFE2"
        },
        [10101614] = {
          Camera = "390.112488,2686.977783,149.298599,0.001179,0.600053,-100.143715,50.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Grâce à elle, on a enfin trouvé un toit. Allons nous reposer un peu, je suis crevée moi aussi !",
          DialogueId = 10101614,
          FacialId = {
            [1] = "200002:Smile02",
            [2] = "100001:Satisfy01"
          },
          FinalCamera = "390.112488,2686.977783,221.628708,0.001179,0.600053,-100.143715,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1949D00C",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Thanks to her, we've finally found a place to stay. Let's rest a bit — I'm quite tired too!",
          ToFinalCameraBlendTime = 9,
          TurnTo = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101016/1949D00C"
        },
        [10101701] = {
          Camera = "246.411194,114.218262,109.373657,0.001183,-13.29721,-168.309631,50.000011,93.339378,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Trop de choses se sont enchaînées... Des rêves étranges, ce mystérieux manteau blanc, Sibylle, et "n° 0"... Tout semble lié, mais je n’arrive pas à assembler les pièces.",
          DialogueId = 10101701,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "246.411194,114.218262,113.977905,0.001183,-2.89725,-167.911087,50.000011,301.668488,false,Manual,8.0",
          GUID = "1949DE52",
          NextDialogue = 10101702,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 405001,
            [4] = 304001,
            [5] = 204002,
            [6] = 201001,
            [7] = 201002,
            [8] = 101005
          },
          Scripts = "SitOrStand{ActorId{100001},State{"Sit"}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(So much has happened... Weird dreams, that mysterious man in a white cloak, Sibylle, and "No. 0"... They all seem to be connected somehow, but I can't figure it out.)",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DE52"
        },
        [10101702] = {
          Camera = "32.615486,-85.951172,141.394852,0.001194,-10.600405,119.473099,50.000011,174.121933,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "La seule certitude, c’est que j’ai perdu Berry...",
          DialogueId = 10101702,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "20.154007,-63.900879,136.737762,0.001195,-11.20041,119.473099,50.000011,174.121933,false,Manual,22.0",
          GUID = "1949DE7C",
          NextDialogue = 10101703,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The only thing I'm certain of is that I've lost touch with Berry...)",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DE7C"
        },
        [10101703] = {
          Camera = "521.906738,-420.427246,557.736206,0.001077,-34.294342,143.62709,35.000008,749.64917,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... Si elle a réussi à s’échapper, elle doit tout faire pour me retrouver... Mais je dois aussi envisager le pire : que Sibylle l’ait emmenée avec la XIIIᵉ Légion.",
          DialogueId = 10101703,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "459.354492,-374.35791,505.258728,0.001073,-34.094299,144.027039,35.000008,749.64917,false,Manual,4.0",
          GUID = "1949DEA6",
          NextDialogue = 10101704,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...If she's managed to escape, she'd surely try everything to find me... Of course, I can't rule out the worst-case scenario that Sibylle has taken her to the Legion.)",
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DEA6"
        },
        [10101704] = {
          Camera = "-50.302734,-52.980469,119.29213,0.001284,-17.399469,87.817223,35.000011,114.672478,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Heureusement, Sibylle semble avoir besoin de Berry pour une raison que j’ignore. Elle ne devrait pas lui faire de mal.",
          DialogueId = 10101704,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "-50.302734,-52.980469,119.29213,0.001284,-6.599526,87.2173,35.000011,101.591904,false,Manual,6.0",
          GUID = "1949DED0",
          NextDialogue = 10101705,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The silver lining is, it seemed that Sibylle needed Berry for some reason, so she probably wouldn't harm her.)",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DED0"
        },
        [10101705] = {
          Camera = "-107.57486,-199.331177,124.529968,0.001198,-6.0,70.830925,35.0,247.426239,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Bref... Je dois trouver un moyen de gagner un peu d’argent à Givrelac, obtenir un permis de circulation, et seulement après décider de mes prochaines étapes.",
          DialogueId = 10101705,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "-112.579315,-197.591553,124.529968,0.001198,-6.0,70.830925,35.0,247.426239,false,Manual,2.5",
          GUID = "1949DEFA",
          NextDialogue = 10101801,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Anyway, I need to scrape together some money in Icelake, get a travel permit, and then plan for my next move.)",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DEFA"
        },
        [10101801] = {
          ContentFR = "Je suis rentrée.",
          DialogueId = 10101801,
          FacialId = {
            [1] = "100001:Shock01"
          },
