          GUID = "1949EF8C",
          NextDialogue = 10101807,
          SpeakNpcId = 100001,
          Subtitle = "...!!",
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101018/1949EF8C"
        },
        [10101807] = {
          Camera = "155.289749,17.776367,63.671951,0.001254,10.000004,108.81134,35.000011,302.230957,false,Manual,6.0",
          ContentFR = "Ce n’est rien. J’avais trop faim, j’ai mordu ma langue sans faire exprès. Ça fait mal, alors...",
          DialogueId = 10101807,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200006:Unhappy01"
          },
          GUID = "1949EFB6",
          NextDialogue = 10101808,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{"Explain02_Start"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. Just so hungry that I accidentally bit my tongue. It hurts, so...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949EFB6"
        },
        [10101808] = {
          Camera = "292.073364,582.838379,135.940063,0.00127,-2.89807,-120.987396,50.000011,514.955017,false,Manual,4.0",
          ContentFR = "Alors mange vite ce pain, et bois un peu de lait chaud. Tu verras, ça passera tout de suite, mais fais attention, ne te mords pas encore !",
          DialogueId = 10101808,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1949EFE0",
          NextDialogue = 10101809,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{200006},AnimationId{"DisagreeHead"},Duration{1}}",
          SpeakNpcId = 200006,
          Subtitle = "Then you better eat some bread and wash it down with some warm milk, that'll make you feel better — be careful, don't bite your tongue again.",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "200006:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949EFE0"
        },
        [10101809] = {
          Camera = "145.36499,-36.702637,169.322754,0.001274,-7.59989,106.215103,50.000011,344.345856,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Merci, Psyche.",
          DialogueId = 10101809,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "141.480316,-23.34375,167.466644,0.001274,-7.59989,106.215149,50.000011,344.345856,false,Manual,4.0",
          GUID = "1949F00A",
          NextDialogue = 10101810,
          SpeakNpcId = 100001,
          Subtitle = "...Thank you, Psyche.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101018/1949F00A"
        },
        [10101810] = {
          ContentFR = "Tu... es triste, n’est-ce pas ?",
          DialogueId = 10101810,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          GUID = "1949F034",
          NextDialogue = 10101811,
          SpeakNpcId = 200006,
          Subtitle = "Are you... sad?",
          VoiceName = "voice/$Locale$/story/1002/101018/1949F034"
        },
        [10101811] = {
          ContentFR = "... Hein ? Pourquoi ?",
          DialogueId = 10101811,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1949F05E",
          NextDialogue = 10101812,
          SpeakNpcId = 100001,
          Subtitle = "...Hmm?",
          VoiceName = "voice/$Locale$/story/1002/101018/1949F05E"
        },
        [10101812] = {
          Camera = "124.00592,396.694336,136.049347,0.001243,0.09998,-101.200462,60.000011,283.596039,false,Manual,8.429013",
          ContentFR = "Je le sens. Tu t’efforces de sourire, mais... tu n’es pas {性别:heureux|heureuse}.",
          DialogueId = 10101812,
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "1949F088",
          NextDialogue = 10101813,
          SpeakNpcId = 200006,
          Subtitle = "I can feel it. Even though you're trying to put on a smile, you're not happy.",
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949F088"
        },
        [10101813] = {
          ContentFR = "J’avoue que je suis un peu curieuse de ce que tu as traversé. Mais Monsieur Henrik m’a appris à ne jamais fouiller dans le passé des invités.",
          DialogueId = 10101813,
          FacialId = {
            [1] = "200006:Ahaha02"
          },
          GUID = "1949F0B2",
          NextDialogue = 10101814,
          Scripts = "PlayAnimation{_delay{3},ActorId{200006},AnimationId{"DisagreeHead"},Duration{2}}",
          SpeakNpcId = 200006,
          Subtitle = "I'm a bit curious about what you've been through, but Mr Henrik told me not to pry into our guests' pasts.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949F0B2"
        },
        [10101814] = {
          Camera = "387.223511,-833.958069,515.231628,0.000029,-22.073723,106.174774,35.0,1079.091919,false,Manual,1.2",
          ContentFR = "Alors... repose-toi d’abord. Tu auras le temps de réfléchir à ce que tu veux faire ensuite.",
          DialogueId = 10101814,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "423.065491,-957.536621,567.4104,0.000029,-22.073723,106.174774,35.0,1325.286621,false,Manual,1.2",
          GUID = "1949F0DC",
          NextDialogue = 10101815,
          Scripts = "PlayAnimation{_delay{2},ActorId{200006},AnimationId{"Talk02_Start"},Duration{2}}",
          SpeakNpcId = 200006,
          Subtitle = "Anyway... you can take a good rest here, and think about what to do next.",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101018/1949F0DC"
        },
        [10101815] = {
          ContentFR = "D’accord.",
          DialogueId = 10101815,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "1949F106",
          SpeakNpcId = 100001,
          Subtitle = "Thank you.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949F106"
        },
        [10101901] = {
          Camera = "-48.44191,-84.550293,158.135422,0.00125,-12.40057,63.821815,25.0,187.769821,false,Manual,4.0",
          ContentFR = "Psyche, j’aimerais te demander quelque chose.",
          DialogueId = 10101901,
          ExStoryInfo = "Player",
          GUID = "1949FF22",
          LookAt = {
            [1] = "100001:n(200006)",
            [2] = "200006:n(100001)"
          },
          NextDialogue = 10101902,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 405001,
            [4] = 201007
          },
          SpeakNpcId = 100001,
          Subtitle = "Psyche, I need to ask you something.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/1949FF22"
        },
        [10101902] = {
          ContentFR = "Il me faut de l’argent. Sais-tu s’il existe, dans cette cité, un endroit où {性别:un étranger|une étrangère} peut trouver du travail... sans qu’on pose trop de questions ?",
          DialogueId = 10101902,
          ExStoryInfo = "Player",
          GUID = "1949FF4C",
          NextDialogue = 10101903,
          SpeakNpcId = 100001,
          Subtitle = "I need some money. Is there any place in the city where an outsider might find work without too many questions asked about their past?",
          VoiceName = "voice/$Locale$/story/1002/101019/1949FF4C"
        },
        [10101903] = {
          Camera = "-38.717148,121.221191,133.893906,0.001216,0.400071,-64.497734,33.0,151.507431,false,Manual,6.0",
          ContentFR = "Laisse-moi réfléchir...",
          DialogueId = 10101903,
          FacialId = {
            [1] = "200006:Sad01"
          },
          GUID = "1949FF76",
          NextDialogue = 10101904,
          SpeakNpcId = 200006,
          Subtitle = "Let me see...",
          TalkActionId = {
            [1] = "200006:Think_Start",
            [2] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/1949FF76"
        },
        [10101904] = {
          Camera = "-38.717148,121.221191,133.893906,0.001216,0.400071,-64.497734,33.0,151.507431,false,Manual,6.0",
          ContentFR = "La plupart des gens ici travaillent à l’usine... Mais il faut un permis de circulation pour y entrer... Hmm... sinon, il y a peut-être...",
          DialogueId = 10101904,
          GUID = "1949FFA0",
          NextDialogue = 10101905,
          SpeakNpcId = 200006,
          Subtitle = "Most people here work in the factories... um, but they all ask to see a travel permit... Well, there's perhaps one place you could try—",
          VoiceName = "voice/$Locale$/story/1002/101019/1949FFA0"
        },
        [10101905] = {
          Camera = "-38.717148,121.221191,133.893906,0.001216,0.400071,-64.497734,33.0,151.507431,false,Manual,6.0",
          ContentFR = "La taverne <H>Les Asphodèles</>, tenue par Madame Camilla Scarlet. On y propose des missions, et les récompenses sont plutôt généreuses.",
          DialogueId = 10101905,
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "1949FFCA",
          NextDialogue = 10101906,
          RelatedWikiId = {
            [1] = 405003,
            [2] = 201004
          },
          SpeakNpcId = 200006,
          Subtitle = "Ms Camilla Scarlet's tavern, The Asphodel. You can take up commissions with handsome rewards there.",
          TalkActionId = {
            [1] = "200006:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/1949FFCA"
        },
        [10101906] = {
          ContentFR = "Mais attention, la plupart de ces missions sont dangereuses. Elles envoient parfois dans des zones où même les Veilleurs ne mettent pas les pieds. Et si tu tombes sur des Souillés errants...",
          DialogueId = 10101906,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "-90.181519,24.020996,149.167328,0.0012,-2.49905,-14.966633,40.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1949FFF4",
          NextDialogue = 10101907,
          RelatedWikiId = {
            [1] = 101006
          },
          SpeakNpcId = 200006,
          Subtitle = "But, those commissions are often quite dangerous... you might have to go to places even the local Escort would avoid, and you might encounter some wandering Filthoids...",
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101019/1949FFF4"
        },
        [10101907] = {
          Camera = "-48.44191,-84.550293,158.135422,0.00125,-12.40057,63.821815,25.0,187.769821,false,Manual,4.0",
          ContentFR = "Camilla Scarlet ? Je l’ai croisée aujourd’hui. J’ignorais que sa taverne servait aussi à ça.",
          DialogueId = 10101907,
          ExStoryInfo = "Player",
          GUID = "194A001E",
          NextDialogue = 10101908,
          Scripts = "SEQ{\nPlayAnimation{_delay{0.1},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Explain02_End\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Camilla Scarlet? I've met this lady once. Though I had no idea that her tavern also runs this sort of business.",
          VoiceName = "voice/$Locale$/story/1002/101019/194A001E"
        },
        [10101908] = {
          Camera = "-0.864502,1.519531,134.328049,0.001223,3.799798,92.402924,35.000011,82.431984,false,Manual,4.0",
          ContentFR = "Ça va aller. Je peux m’en occuper. Tu peux m’y emmener ?",
          DialogueId = 10101908,
          ExStoryInfo = "Player",
          GUID = "194A0048",
          SpeakNpcId = 100001,
          Subtitle = "It's okay, I can handle it. Can you take me there?",
          TalkActionId = {
            [1] = "100001:DisagreeHead",
            [2] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/194A0048"
        },
        [10102001] = {
          ContentFR = "Hein ? Après tout ce détour, vous finissez quand même par aller voir Camilla ?",
          DialogueId = 10102001,
          GUID = "194A0F8A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10102002,
          SpeakNpcId = 200002,
          Subtitle = "Huh? After all this running around, you're going back to Camilla?",
          VoiceName = "voice/$Locale$/story/1002/101020/194A0F8A"
        },
        [10102002] = {
          ContentFR = "Parfait, Snow connaît l’endroit comme sa poche ! Je vais vous y conduire !",
          DialogueId = 10102002,
          GUID = "194A0FB4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Then count Snow in! Snow's more than familiar with that place.",
          VoiceName = "voice/$Locale$/story/1002/101020/194A0FB4"
        },
        [10102101] = {
          Camera = "144.795166,-59.822609,177.998291,0.000184,-10.995027,-161.813614,35.000008,336.056366,false,Manual,3.399312",
          ContentFR = "Ton permis de circulation...",
          DialogueId = 10102101,
          GUID = "194A1FF2",
          NextDialogue = 10102102,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 201007,
            [4] = 201005,
            [5] = 101006
          },
          SpeakNpcId = 200008,
          Subtitle = "Your travel permit...",
          VoiceName = "voice/$Locale$/story/1002/101021/194A1FF2"
        },
        [10102102] = {
          Camera = "33.546387,-153.258987,93.952881,0.000002,16.403095,174.174957,38.839455,184.656097,false,Manual,2.8",
          ContentFR = "T’es sourd ou quoi ?! Montre-moi... ton foutu permis !",
          DialogueId = 10102102,
          FinalCamera = "-0.705322,-149.764832,97.867188,0.000001,18.403158,174.174957,38.839455,152.921875,false,Manual,2.8",
          GUID = "194A201C",
          NextDialogue = 10102103,
          SpeakNpcId = 200008,
          Subtitle = "Are you deaf? Show me your... travel permit!",
          ToFinalCameraBlendTime = 0.2,
          VoiceName = "voice/$Locale$/story/1002/101021/194A201C"
        },
        [10102103] = {
          Camera = "-158.199463,-84.212631,168.010742,0.000248,-21.796566,-50.423859,15.255159,136.628647,false,Manual,3.557573",
          ContentFR = "Pardon, monsieur... à mon âge je suis un peu lent. Un instant, je cherche... je cherche...",
          DialogueId = 10102103,
          GUID = "194A2046",
          NextDialogue = 10102104,
          Scripts = "PARA{\nPlayAnimation{_delay{4},ActorId{200009},AnimationId{\"Agree\"},Duration{2}},\nPlayAnimation{_delay{7},ActorId{200009},AnimationId{\"Agree\"},Duration{2}}\n}",
          SpeakNpcId = 200009,
          Subtitle = "Sorry, sir, I'm a bit slow at this age, please bear with me for a moment...",
          TalkActionId = {
            [1] = "200009:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/101021/194A2046"
        },
        [10102104] = {
          ContentFR = "Ah ! Le voilà, le voilà, tenez !",
          DialogueId = 10102104,
          GUID = "194A2070",
          NextDialogue = 10102105,
          SpeakNpcId = 200009,
          Subtitle = "Ah, here it is!",
          TalkActionId = {
            [1] = "200009:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/101021/194A2070"
        },
        [10102105] = {
          Camera = "-25.373291,-199.524673,197.259033,-5.000002,-19.596331,152.183594,35.000008,145.457977,false,Manual,3.557573",
          ContentFR = "Oh... ? Cette photo... c’est bien toi, le vieux débris ?",
          DialogueId = 10102105,
          FinalCamera = "-25.373291,-199.524673,190.776367,-5.000002,-19.596331,152.183594,35.000008,145.457977,false,Manual,3.557573",
          GUID = "194A209A",
          NextDialogue = 10102106,
          SpeakNpcId = 200008,
          Subtitle = "Huh...? Oh, is this you in the photo... you old codger?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101021/194A209A"
        },
        [10102106] = {
          ContentFR = "Oui, monsieur...",
          DialogueId = 10102106,
          GUID = "194A20C4",
          NextDialogue = 10102107,
          SpeakNpcId = 200009,
          Subtitle = "Yes, sir...",
          TalkActionId = {
            [1] = "200009:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/101021/194A20C4"
        },
        [10102107] = {
          Camera = "-324.333984,818.858521,893.822021,-5.000005,-35.792892,-76.391212,40.168049,228.342102,false,DoNotOverride,6.685584",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "On dirait plutôt un clébard ! Haha ! Hahahaha !",
          DialogueId = 10102107,
          FinalCamera = "-324.333984,818.858521,836.514404,-5.000005,-35.792892,-76.391212,40.168049,228.342102,false,DoNotOverride,6.685584",
          GUID = "194A20EE",
          NextDialogue = 10102108,
          SpeakNpcId = 200008,
          Subtitle = "How come it looks more like a mongrel to me, haha, hahaha!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101021/194A20EE"
        },
        [10102108] = {
          Camera = "-119.224854,-52.406082,82.172852,0.000047,14.206512,-47.991478,45.857548,255.974915,false,Manual,2.325034",
          ContentFR = "Hé, et si tu nous aboyais un coup, pour voir ?",
          DialogueId = 10102108,
          GUID = "194A2118",
          SpeakNpcId = 200010,
          Subtitle = "Oi, why don't you give us a bark, huh?",
          VoiceName = "voice/$Locale$/story/1002/101021/194A2118"
        },
        [10102201] = {
          ContentFR = "Non... tu ne peux pas.",
          DialogueId = 10102201,
          Duration = 2,
          GUID = "194A305A",
          SpeakNpcId = 200006,
          Subtitle = "Don't...",
          VoiceName = "voice/$Locale$/story/1002/101022/194A305A"
        },
        [10102202] = {
