          DialogueId = 10102204,
          Duration = 1.8,
          GUID = "194A3102",
          SpeakNpcName = "UI_Npc_Name_Man_13",
          Subtitle = "Father...",
          VoiceName = "voice/$Locale$/story/1002/101022/194A3102"
        },
        [10102205] = {
          ContentFR = "Bande d’ordures !",
          DialogueId = 10102205,
          Duration = 1.5,
          GUID = "194A312C",
          SpeakNpcName = "UI_Npc_Name_Man_13",
          Subtitle = "You bastards!",
