        [10102403] = {
          Camera = "125.824219,-225.558105,135.956543,0.000172,-1.798553,120.789757,50.0,356.306458,false,Manual,6.0",
          ContentFR = "Si vous venez d’au-delà d’Hyperborea, souvenez-vous bien, ne provoquez jamais les <H>Solariens</>.",
          DialogueId = 10102403,
          GUID = "194A5154",
          NextDialogue = 10102404,
          RelatedWikiId = {
