        },
        [10102501] = {
          Camera = "-237.39502,-776.429688,380.287109,0.000219,-20.598696,70.000015,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis, il m’a prise par surprise et m’a piqué l’argent que je venais de gagner. Cet imbécile, il ne laisse même pas les récupérateurs tranquilles ! Cet argent était pour plusieurs familles des taudis !",
          DialogueId = 10102501,
          FacialId = {
            [1] = "200011:Angry01"
          },
          FinalCamera = "-264.857361,-766.555664,380.287109,0.000222,-20.598696,70.000008,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "194A6192",
          NextDialogue = 10102502,
          Scripts = "PARA{\nPlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Angry01_Start\"},Duration{2}}\n}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "...And then, out of nowhere, he ambushed me and pinched the cash I'd just gotten. That rotter, doesn't even spare us scavengers!\nThat money was for several families' upkeep in the slums!",
          TalkActionId = {
            [1] = "200011:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101025/194A6192"
        },
        [10102502] = {
          Camera = "78.0,-7.4375,131.521484,0.000191,-2.398646,-161.013702,35.000008,175.980392,false,Manual,4.0",
          ContentFR = "Sans ce sac de pièces, tous, jeunes et vieux, devront se serrer la ceinture le mois prochain. Je ne sais pas où ce voleur a filé... Il me faut quelqu’un pour m’aider à le coincer.",
          DialogueId = 10102502,
          FacialId = {
            [1] = "200011:Sad01"
          },
          GUID = "194A61BC",
          LookAt = {
            [1] = "200003:n(200011)"
          },
          NextDialogue = 10102503,
          Scripts = "PlayAnimation{_delay{3},ActorId{200011},AnimationId{"Sigh_Start"},Duration{2}}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Without that bag of coins, all the young and old will have to tighten their belts even more next month. Ugh... I've no idea where the thief has run off to, I need someone to help me nab him.",
          TalkActionId = {
            [1] = "200011:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A61BC"
        },
        [10102503] = {
          Camera = "-197.983643,-228.263672,131.707031,0.000195,0.20134,50.188034,50.0,454.857483,false,Manual,5.0",
          ContentFR = "Ce n’est pas plutôt le travail du Bureau de la Sécurité ?",
          DialogueId = 10102503,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "194A61E6",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextDialogue = 10102504,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200003},AnimationId{\"SpecialUnInterested_Start\"},Duration{2}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Shouldn't this be something for the Security Bureau to handle?",
          VoiceName = "voice/$Locale$/story/1002/101025/194A61E6"
        },
        [10102504] = {
          Camera = "281.375,129.460938,170.882812,0.000218,-5.998777,-154.617096,62.0,422.431763,false,Manual,5.0",
          ContentFR = "Ah, d’ici que le Bureau de la Sécurité se préoccupe de nous, pauvres Charons, la glace du Lac du Deuil aura déjà fondu !",
          DialogueId = 10102504,
          FacialId = {
            [1] = "200011:Unacceptable01"
          },
          GUID = "194A6210",
          LookAt = {
            [1] = "200011:n(200003)"
          },
          NextDialogue = 10102505,
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Well, by the time the Security Bureau bothers with us Charons, the ice in Lamenting Lake would've all melted away!",
          TalkActionId = {
            [1] = "200011:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A6210"
        },
        [10102505] = {
          Camera = "-298.685974,-953.163086,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
          ContentFR = "Je vous en supplie, la plus gentille et belle Camilla... pourriez-vous demander à quelques Chasseurs de Phoxène de nous donner un petit coup de main... juste un tout petit coup de main ! Je sais que vous êtes la meilleure.",
          DialogueId = 10102505,
          FacialId = {
            [1] = "200011:Unacceptable01"
          },
          FinalCamera = "-302.263062,-951.791992,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
          GUID = "194A623A",
          NextDialogue = 10102506,
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Please, Ms Camilla, the kindest and most beautiful lady in Icelake, could you maybe ask some of the Phoxhunters here to\nlend a hand... Just one tiny favour! Pretty please!",
          TalkActionId = {
            [1] = "200011:Explain02_Start",
            [2] = "200003:SpecialUnInterested_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101025/194A623A"
        },
        [10102506] = {
          Camera = "10.047852,-140.40625,117.429688,0.000236,8.800841,67.194237,56.354355,240.957672,false,Manual,6.0",
          ContentFR = "Arrête de faire la charmeuse. Tu sais très bien que rien ici ne se fait gratuitement.",
          DialogueId = 10102506,
          GUID = "194A6264",
          NextDialogue = 10102507,
          SpeakNpcId = 200003,
          Subtitle = "Save it. You should know that nothing asked for here comes without a price.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A6264"
        },
        [10102507] = {
          Camera = "81.471924,-18.664062,159.626953,0.000213,-10.598773,-163.809616,48.734837,175.980392,false,Manual,4.0",
          ContentFR = "Alors… pourriez-vous au moins… proposer un petit arrangement… ou accepter un autre échange ? Attendez, comment disait-on déjà...",
          DialogueId = 10102507,
          GUID = "194A628E",
          NextDialogue = 10102508,
          Scripts = "PARA{\nPlayAnimation{_delay{1},ActorId{200011},AnimationId{\"SpecialHoldHelmet_Start\"},Duration{1}},\nPlayAnimation{_delay{4},ActorId{200011},AnimationId{\"SpecialHoldHelmet_End\"},Duration{1}},\nPlayAnimation{_delay{5.5},ActorId{200011},AnimationId{\"Think_Start\"},Duration{2}}\n}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Well then, can you maybe... give me a discount... or I could offer you something else! How does it go again—",
          TalkActionId = {
            [1] = "200011:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A628E"
        },
        [10102508] = {
          Camera = "-200.542847,-222.323242,136.585938,0.000182,1.001258,46.588379,70.000015,435.191498,false,Manual,6.0",
          ContentFR = "« L’information, c’est de l’or » ! Oui c’est ça, je gère tous les poubelles de Givrelac, alors si je tombe sur des infos intéressantes, vous serez la première à les savoir, d’accord ?",
          DialogueId = 10102508,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "194A62B8",
          Scripts = "PARA{\nPlayAnimation{_delay{4},ActorId{200011},AnimationId{\"Give\"},Duration{2}},\nLookAt{_delay{7},LookAtDescription{\"200003:p(P10102508Kami)\"}}\n}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Information is as good as gold! Right, I deal with all the rubbish bins in Icelake, so how about this —\nif I stumble upon any useful info, you'll be the first to know.",
          TalkActionId = {
            [1] = "200011:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A62B8"
        },
        [10102601] = {
          Camera = "-383.403992,-193.522461,142.960938,0.00126,-1.698579,31.40027,50.0,551.857117,false,DoNotOverride,4.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "C’est toi. Et toi, tu es... la fille des Frey ? Psyche, c’est bien ça ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10102601,
          FacialId = {
            [1] = "200003:None"
          },
          FinalCamera = "-384.137512,-192.352539,142.960938,0.00126,-1.698579,32.000465,50.0,269.649109,false,DoNotOverride,6.0",
          GUID = "194A71FA",
          LookAt = {
            [1] = "200011:n(100001)",
            [2] = "200003:n(100001)"
          },
          NextDialogue = 10102602,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 201007,
            [4] = 201005,
            [5] = 101006,
            [6] = 303003,
            [7] = 201004,
            [8] = 405003
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{3.6},TargetPosition{\"357.35022,109.896484,184.921875,0.001239,-7.699037,-166.997726,50.0,457.084625,false,Manual,3.5\"},duration{0}},\nCameraMoveTo{_delay{3.7},TargetPosition{\"362.855469,86.730469,184.289062,0.00124,-7.699037,-170.398438,50.0,627.00415,false,Manual,3.5\"},duration{6}},\nMoveTo{ActorId{200002},TargetPoint{\"P10102601Bai\"},MoveSpeed{30},Visibility{\"Show\"}},\nMoveTo{ActorId{100001},TargetPoint{\"P10102601Nvzhu\"},MoveSpeed{50},Visibility{\"Show\"}},\nMoveTo{ActorId{200006},TargetPoint{\"P10102601Saiqi\"},MoveSpeed{40},Visibility{\"Show\"}},\nLookAt{_delay{0.1},LookAtDescription{\"200003:n(200006)\"}},\nTurnTo{_delay{0.3},TurnToDescription{\"200011:p(100)\"}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Oh, it's you. And you're... the little girl from the Frey's? Psyche, isn't it?",
          ToFinalCameraBlendTime = 3.5,
          VoiceName = "voice/$Locale$/story/1002/101026/194A71FA"
        },
        [10102602] = {
          ContentFR = "Oui, Madame Camilla. Je loge pour le moment dans la Maison d’Hypnos.",
          DialogueId = 10102602,
          FacialId = {
            [1] = "200006:Happy02"
          },
          GUID = "194A7224",
          LookAt = {
            [1] = "200002:n(200003)",
            [2] = "200003:n(200006)",
            [3] = "200011:n(100001)"
          },
          NextDialogue = 10102603,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200006},AnimationId{\"AgreeHead\"},Duration{3}},\nPlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "Yes, Ms Camilla. I'm staying at the Hypnos' House for now.",
          VoiceName = "voice/$Locale$/story/1002/101026/194A7224"
        },
        [10102603] = {
          Camera = "-109.342285,-78.164062,166.683594,0.00123,-3.99997,36.028351,50.0,253.714981,false,Manual,3.5",
          ContentFR = "... Je vois.",
          DialogueId = 10102603,
          FacialId = {
            [1] = "100001:Smile01",
            [2] = "200006:Happy01"
          },
          GUID = "194A724E",
          NextDialogue = 10102604,
          SpeakNpcId = 200003,
          Subtitle = "...I see.",
          TalkActionId = {
            [1] = "200003:Think_Start",
            [2] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A724E"
        },
        [10102604] = {
          Camera = "53.717529,77.917969,151.150391,0.001249,-3.299029,-154.168152,60.000004,328.479401,false,Manual,5.0",
          ContentFR = "... Je suis venue avec {性别:un ami|une amie}. {性别:Il|Elle} cherche un emploi et veut devenir {性别:Chasseur de Phoxène|Chasseuse de Phoxène}.",
          DialogueId = 10102604,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          FinalCamera = "59.223877,66.544922,151.150391,0.001249,-3.299015,-154.168152,60.000004,266.16394,false,Manual,5.0",
          GUID = "194A7278",
          LookAt = {
            [1] = "100001:n(200006)",
            [2] = "200006:n(100001)"
          },
          NextDialogue = 10102605,
          RelatedWikiId = {
            [1] = 405004
          },
          Scripts = "PARA{\nTurnTo{TurnToDescription{\"200011:p(20)\"}},\nSEQ{\nLookAt{_delay{2.5},LookAtDescription{\"100001:n(200003)\"}},\nPlayAnimation{ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200006,
          Subtitle = "...I'm here with a friend. {性别:He|She} is looking for a job and wants to become a Phoxhunter.",
          TalkActionId = {
            [1] = "200006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101026/194A7278"
        },
        [10102605] = {
          Camera = "-333.986206,-132.207031,145.634766,0.001253,-3.999936,19.037998,50.000008,264.189575,false,Manual,4.109556",
          ContentFR = "Chasseur de Phoxène ! Alors vous êtes au bon endroit, justement, il y a un travail à pourvoir—",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10102605,
          FacialId = {
            [1] = "200011:Happy01"
          },
          GUID = "194A72A2",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextDialogue = 10102606,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200011},AnimationId{\"Shock_Start\"},Duration{1.3}},\nPlayAnimation{ActorId{200011},AnimationId{\"Shock_End\"},Duration{1.2}},\nPlayAnimation{ActorId{200011},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Then you came to the right place! There's a commission for Phoxhunters right now—",
          VoiceName = "voice/$Locale$/story/1002/101026/194A72A2"
        },
        [10102606] = {
          Camera = "-333.986206,-132.207031,145.634766,0.001253,-3.999936,19.037998,50.000008,264.189575,false,Manual,4.109556",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Pas maintenant, Margie.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10102606,
          Duration = 1,
          FinalCamera = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
          GUID = "194A72CC",
          LookAt = {
