        },
        [10102608] = {
          Camera = "-109.342285,-78.164062,166.683594,0.00123,-3.99997,36.028351,50.0,253.714981,false,Manual,3.5",
          ContentFR = "Déjà des amis... tu es plutôt populaire. Quant aux Chasseurs de Phoxène...",
          DialogueId = 10102608,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "194A7320",
          LookAt = {
            [1] = "200003:n(100001)"
          },
          NextDialogue = 10102609,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200003},AnimationId{\"Think_End\"},Duration{1.5}},\nPlayAnimation{ActorId{200003},AnimationId{\"Confident_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Already made friends... you're quite a charmer, aren't you?\nAs for Phoxhunters—",
          VoiceName = "voice/$Locale$/story/1002/101026/194A7320"
        },
        [10102609] = {
          Camera = "291.657104,98.844727,170.599609,0.001316,-5.498842,-164.352921,52.422081,496.264801,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Pour être claire, ce n’est pas un jeu d’enfants, et ce n’est pas facile non plus. Ici, personne ne demandera ton passé ni tes origines, mais chaque récompense a son risque.",
          DialogueId = 10102609,
          FacialId = {
            [1] = "200011:Unhappy01"
          },
          FinalCamera = "231.961548,82.132812,164.626953,0.001316,-5.498842,-164.352844,52.422081,430.432526,false,Manual,4.0",
          GUID = "194A734A",
          LookAt = {
            [1] = "200011:n(200003)",
            [2] = "200006:n(200003)",
            [3] = "200003:n(100001)"
          },
          NextOptions = {
            [1] = 101026091,
            [2] = 101026092
          },
          Scripts = "SEQ{\nPlayAnimation{ActorId{200003},AnimationId{\"Confident_End\"},Duration{2}},\nPlayAnimation{ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{2.5}},\nPlayAnimation{ActorId{200003},AnimationId{\"Talk02_End\"},Duration{1}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Let's get one thing straight — this isn't child's play, nor an easy gig. It's false that in this place,\nno one would probe into your past or background, but the rewards always come with risks.",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/101026/194A734A"
        },
        [10102610] = {
          Camera = "-294.801819,-157.509766,135.695312,0.001227,1.1999,33.90601,60.000004,460.630157,false,Manual,12.0",
          ContentFR = "Pas très robuste, mais {性别:déterminé|déterminée}.",
          DialogueId = 10102610,
          FacialId = {
            [1] = "200006:None",
            [2] = "200011:None"
          },
          GUID = "194A7374",
          LookAt = {
            [1] = "200011:n(200003)"
          },
          NextDialogue = 10102611,
          SpeakNpcId = 200003,
          Subtitle = "You don't look tough, though your courage is admirable.",
          TalkActionId = {
            [1] = "200003:Talk03_Start",
            [2] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A7374"
        },
        [10102611] = {
          Camera = "-43.718262,-1261.714844,610.828125,0.001481,-22.297657,82.031219,25.0,166.832703,false,DoNotOverride,22.0",
          ContentFR = "Tu es effectivement plus {性别:fort|forte} qu’un simple Charon, Je t’ai {性别:vu|vue} te battre. Mais pour devenir Chasseur de Phoxène, la force seule ne suffit pas... il te faut prouver que tu peux gérer toutes sortes d’imprévus et de clients.",
          DialogueId = 10102611,
          FinalCamera = "-98.231934,-1254.261719,610.828125,0.001477,-22.297657,82.031197,25.0,166.832703,false,DoNotOverride,22.0",
          GUID = "194A739E",
          NextDialogue = 10102612,
          Scripts = "SetLocation{ActorId{200011},TargetPoint{"P10102601Maer"},Visibility{"Show"}}",
          SpeakNpcId = 200003,
          Subtitle = "You're indeed stronger than the average Charons — I've seen you in a fight. But brute strength isn't enough to\nqualify you to be a Phoxhunter. You need to prove that you're capable of dealing with\nall possible contingencies and a very mixed group of clients.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101026/194A739E"
        },
        [10102612] = {
          Camera = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
          ContentFR = "Et justement, une occasion de le prouver vient de se présenter.",
          DialogueId = 10102612,
          GUID = "194A73C8",
          LookAt = {
            [1] = "200003:n(200011)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 10102613,
          SpeakNpcId = 200003,
          Subtitle = "It just so happens that a chance for that came just now.",
          VoiceName = "voice/$Locale$/story/1002/101026/194A73C8"
        },
        [10102613] = {
          ContentFR = "Ah... oui, oui !",
          DialogueId = 10102613,
          FacialId = {
            [1] = "200011:Happy01"
          },
          GUID = "194A73F2",
          NextDialogue = 10102614,
          Scripts = "PARA{\nPlayAnimation{_delay{1.2},ActorId{200011},AnimationId{\"AgreeHead\"},Duration{0.1}},\nTurnTo{_delay{2.2},TurnToDescription{\"200011:n(100001)\"}},\nLookAt{_delay{1.5},LookAtDescription{\"200003:n(100001)\"}},\nLookAt{_delay{2},LookAtDescription{\"100001:n(200011)\"}}\n}",
          SpeakNpcId = 200011,
          Subtitle = "Oh... right!",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A73F2"
        },
        [10102614] = {
          Camera = "73.365112,16.138672,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
          ContentFR = "Snow a entendu dire que quelqu’un venait de voler l’argent de cette dame ?",
          DialogueId = 10102614,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "72.002441,21.418945,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
          GUID = "194A741C",
          LookAt = {
            [1] = "200006:n(200011)",
            [2] = "200003:n(100001)",
            [3] = "100001:n(200011)",
            [4] = "200002:n(200011)"
          },
          Scripts = "SetLocation{ActorId{200002},TargetPoint{"P10102601Bai3"},Visibility{"Show"}}",
          SpeakNpcId = 200002,
          Subtitle = "Snow heard that someone swiped this lady's money bag.",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101026/194A741C"
        },
        [10102701] = {
          ContentFR = "Elle a l’air vraiment inquiète... je peux aider pour qu’on le retrouve plus vite.",
          DialogueId = 10102701,
          GUID = "194A8262",
          NextDialogue = 10102702,
          SpeakNpcId = 200006,
          Subtitle = "She seems quite distressed; I can lend a hand too so we can get it back sooner.",
          VoiceName = "voice/$Locale$/story/1002/101027/194A8262"
        },
        [10102702] = {
          ContentFR = "Non. C’est un simple test pour notre {性别:futur Chasseur de Phoxène|future Chasseuse de Phoxène}. Si tu n’as pas les capacités, devenir {性别:Chasseur de Phoxène|Chasseuse de Phoxène} te serait fatal.",
          DialogueId = 10102702,
          GUID = "194A828C",
          NextDialogue = 10102703,
          SpeakNpcId = 200003,
          Subtitle = "No, this is a simple test just for a prospective Phoxhunter. If you don't have the chops for it, becoming a Phoxhunter would kill you.",
          TurnTo = {
            [1] = "2000061:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101027/194A828C"
        },
        [10102703] = {
          ContentFR = "D’accord...",
          DialogueId = 10102703,
          GUID = "194A82B6",
          SpeakNpcId = 200006,
          Subtitle = "Okay...",
          VoiceName = "voice/$Locale$/story/1002/101027/194A82B6"
        },
        [10102801] = {
          ContentFR = "Tu... tu veux vraiment m’aider ?! Ouah... merci !",
          DialogueId = 10102801,
          GUID = "194A92CA",
          NextDialogue = 10102802,
          SpeakNpcId = 2000111,
          Subtitle = "You'd really help me out? Aww... thank you! You're like the {性别:brother|sister} I never had!",
          TurnTo = {
            [1] = "2000111:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101028/194A92CA"
        },
        [10102802] = {
          ContentFR = "Le voleur est parti vers l’ouest. Mais tu sais, Givrelac est un vrai labyrinthe, qui sait où il peut bien se cacher ? Allons d’abord chercher des indices !",
          DialogueId = 10102802,
          GUID = "194A92F4",
          SpeakNpcId = 2000111,
          Subtitle = "That scoundrel headed toward the north. But, you know, Icelake is like a huge maze, so I'm not sure where he's got to.\nLet's split up and have a look around.",
          VoiceName = "voice/$Locale$/story/1002/101028/194A92F4"
        },
        [10103001] = {
          ContentFR = "Eh ben, c’est immense et spacieux là-dessous ! Et bien plus chaud qu’en surface... presque comme un petit royaume secret !",
          DialogueId = 10103001,
          GUID = "194A92F5",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10103002,
          SpeakNpcId = 200011,
          Subtitle = "It's pretty roomy down here, even a bit warmer than above the ground...",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F5"
        },
        [10103002] = {
          ContentFR = "Chasser les bestioles, virer la puanteur, monter une tente... on pourrait carrément habiter ici !",
          DialogueId = 10103002,
          GUID = "194A92F6",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10103003,
          SpeakNpcId = 200011,
          Subtitle = "Wow, it's reeeaaally big, like a secret little kingdom! One could live here without paying a penny!",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F6"
        },
        [10103003] = {
          ContentFR = "Exactement ! Et regarde, {nickname}, vivre ici, c’est gratuit, pas besoin de loyer !",
          DialogueId = 10103003,
          ExStoryInfo = "Player",
          GUID = "194A92F7",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10103004,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F7"
        },
        [10103004] = {
          ContentFR = "Allez, on les met dehors, on prend leur territoire, et je me proclame Roi Démon ! Toi, je te nommerai...",
          DialogueId = 10103004,
          ExStoryInfo = "Player",
          GUID = "194AB3EE",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10103005,
          SpeakNpcId = 200002,
          Subtitle = "Let's turf these people out, seize their land, and I'll be the demon king here! I'll appoint you as...",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB3EE"
        },
        [10103005] = {
          ContentFR = "« {性别:Le Vaillant Guerrier Cyclope, Seigneur de Givrelac, et tout premier Duc des Égouts|La Vaillante Guerrière Cyclope, Souveraine de Givrelac, et toute première Duchesse des Égouts !} » !",
          DialogueId = 10103005,
          GUID = "194AB418",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103006,
          SpeakNpcId = 200002,
          Subtitle = "The Valiant Cyclopean Warrior, the Cold Lord of Icelake, the Inaugural Duke of the Sewers!",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB418"
        },
        [10103006] = {
          ContentFR = "C’est un peu long comme titre... faudrait réduire...",
          DialogueId = 10103006,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194AB419",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103007,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(That title's a bit of a mouthful, could use a polish. And dealing with the stench here should be no picnic...)",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB419"
        },
        [10103007] = {
          ContentFR = "Hein ! Mais pourquoi je réfléchis sérieusement à ça... ?",
          DialogueId = 10103007,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194AB46C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hold on, why am I even seriously thinking this through?)",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB46C"
        },
        [10103100] = {
