        [10103203] = {
          Camera = "-72.597656,23.658203,28.410049,-5.000005,4.600173,-116.69577,20.0,110.566429,false,Manual,3.0",
          ContentFR = "Stop, arrêtez ! Tenez, reprenez l’argent ! Ça fait des jours que j’ai rien mangé... j’ai craqué, c’est ma faute, c’est ma faute !",
          DialogueId = 10103203,
          FacialId = {
            [1] = "200053:CM_Sad01"
          },
          GUID = "194AD496",
          LookAt = {
            [1] = "200053:p(101032Haer2)"
          },
          NextDialogue = 10103204,
          Scripts = "PARA{\nMoveTo{ActorId{200011},TargetPoint{\"101032Maer\"},MoveSpeed{10},Visibility{\"Show\"}},\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}},\nLookAt{_delay{7},LookAtDescription{\"200053:p(101032Haer3)\"}}\n}",
          SpeakNpcId = 200053,
          Subtitle = "Tsk... If I hadn't been starved all day, I'd never have touched this bloody thing, let alone lost to you!",
          VoiceName = "voice/$Locale$/story/1002/101032/194AD496"
        },
        [10103204] = {
          Camera = "-94.212891,40.829102,88.263504,0.000059,6.830749,-10.009793,37.719067,200.074844,false,Manual,5.0",
          ContentFR = "Oh, t’as faim ? Devine quoi, tout le monde crève la dalle dans les taudis ! Et quand tu m’as arraché la bourse, t’avais pas l’air si désolé que ça !",
          DialogueId = 10103204,
          FacialId = {
            [1] = "200011:Angry01",
            [2] = "200002:None"
          },
          FinalCamera = "-35.111328,30.1875,96.309219,0.000059,7.630748,-10.209655,37.719067,200.074844,false,Manual,5.0",
          GUID = "194AD497",
          LookAt = {
            [1] = "200053:n(200053)"
          },
          NextDialogue = 10103205,
          Scripts = "SEQ{\nMoveTo{ActorId{200011},TargetPoint{\"101032Maer1\"},MoveSpeed{75},Visibility{\"Show\"}},\nPlayAnimation{_delay{0.2},ActorId{200011},AnimationId{\"Angry01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200011,
          Subtitle = "Hunger doesn't justify preying on others.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101032/194AD497"
        },
        [10103205] = {
          ContentFR = "Hmm... bon, on va faire simple, tu m’as collé quelques coups, je vais te rendre la politesse avec ma pelle. Ensuite, on est quittes, et tu files.",
          DialogueId = 10103205,
          FacialId = {
            [1] = "200011:Unhappy02"
          },
          GUID = "194AD498",
          NextDialogue = 10103206,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{200011},AnimationId{\"Angry01_End\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Talk02_Start\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Talk02_End\"},Duration{1}}\n}",
          SpeakNpcId = 200011,
          Subtitle = "What you stole wasn't just a money bag, it was a lifeline for many.",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD498"
        },
        [10103206] = {
          Camera = "-139.193359,186.579102,163.306274,0.000053,-6.999639,-86.690804,42.268261,484.233795,false,DoNotOverride,4.5",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "...",
          DialogueId = 10103206,
          FinalCamera = "-139.193359,186.579102,125.080658,0.000053,-6.999639,-86.690804,42.268261,484.233795,false,DoNotOverride,4.5",
          GUID = "194AD499",
          NextDialogue = 10103207,
          SpeakNpcId = 200053,
          Subtitle = "Ms Camilla? Did you follow us here to help...",
          TalkActionId = {
            [1] = "200053:Onground01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101032/194AD499"
        },
        [10103207] = {
          ContentFR = "D... d’accord...",
          DialogueId = 10103207,
          FacialId = {
            [1] = "200011:Confident02"
          },
          GUID = "194AD500",
          NextDialogue = 10103208,
          SpeakNpcId = 200053,
          Subtitle = "You've come all this way to Icelake, it'd be a shame to meet your maker in this sorry spot on your first day.",
          TalkActionId = {
