          VoiceName = "voice/$Locale$/story/1002/101032/194AD500"
        },
        [10103208] = {
          Camera = "-52.761719,11.763672,132.943054,0.000094,-0.169559,-14.100351,35.0,278.535767,false,DoNotOverride,20.0",
          ContentFR = "Margie, attention ! Il a encore quelque chose en main !",
          DialogueId = 10103208,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200061:Shock02"
          },
          GUID = "194AD501",
          LookAt = {
            [1] = "200011:n(200011)"
          },
          NextDialogue = 10103209,
          Scripts = "PARA{\nMoveTo{ActorId{200011},TargetPoint{\"101032Maer2\"},MoveSpeed{60},Visibility{\"Show\"}},\nCameraMoveTo{_delay{0.58},TargetPosition{\"53.642578,-14.963867,132.192307,0.000094,-0.169559,-14.100259,35.0,278.535767,false,DoNotOverride,20.0\"},duration{0.5}},\nLookAt{L_delay{0.5},LookAtDescription{\"200061:n(200011)\"}},\nPlayAnimation{_delay{0.5},ActorId{200061},AnimationId{\"Shock04_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200061,
          Subtitle = "Tsk, who's this then, some big shot? Ah, just a tavern-keeping old hen. What're you gonna do about it? Hand me over to the Security Bureau? Do you really think those high-ups give a d*mn about Charons...",
          VoiceName = "voice/$Locale$/story/1002/101032/194AD501"
        },
