        [10103212] = {
          Camera = "293.503906,-78.479492,65.005936,0.000021,-6.399265,28.796947,35.000015,210.573471,false,Manual,3.0",
          ContentFR = "Souviens-toi, quand une bête se roule sur le dos, c’est pas forcément de la soumission, parfois, c’est un piège. Baisse ta garde, et elle te mord.",
