        [10103213] = {
          Camera = "-152.814453,58.155273,149.325806,0.000007,-1.999777,-7.403456,35.000015,210.573471,false,Manual,3.0",
          ContentFR = "En ville aussi, il y a des bêtes. Margie, retiens bien ça, ne leur accorde jamais plus de pitié ou de confiance qu’il ne faut. Toi non plus, {nickname}.",
