            [2] = "200011:n(200003)",
            [3] = "200002:n(200003)",
            [4] = "100001:n(200003)"
          },
          NextDialogue = 10103402,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201008,
            [4] = 201004,
            [5] = 201005
          },
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0051_story_danger\"}},\nSEQ{\nLookAt{_delay{0.5},LookAtDescription{\"200003:n(200014)\"}},\nPlayAnimation{_delay{1},ActorId{200014},AnimationId{\"Agree\"},Duration{1}},\nLookAt{LookAtDescription{\"200003:n(200053)\"}}\n}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Take him to the Security Bureau. This has escalated beyond our control.",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 1.5,
          VoiceName = "voice/$Locale$/story/1002/101033/194AE527"
        },
        [10103402] = {
          Camera = "415.427734,94.491211,401.934753,8.000882,-38.599918,-167.192322,20.0,100000.0,false,Disable,2.8",
          ContentFR = "Qu... non !",
          DialogueId = 10103402,
          GUID = "194AE5A4",
