          Scripts = "PARA{\nMoveTo{ActorId{200011},TargetPoint{\"101034Maer\"},MoveSpeed{10},Visibility{\"Show\"}},\nPlayAnimation{ActorId{200053},AnimationId{\"Disagree\"},Duration{2}}\n}",
          SpeakNpcId = 200053,
          Subtitle = "Wha... NO!",
          VoiceName = "voice/$Locale$/story/1002/101033/194AE5A4"
        },
        [10103403] = {
