          CameraBlendCurve = "easeInQuad",
          ContentFR = "Je... je vous en supplie ! Punissez-moi comme vous voulez, mais pas ça !",
          DialogueId = 10103403,
          FinalCamera = "395.310547,89.914062,385.454681,8.001169,-38.599918,-167.191513,20.0,100000.0,false,Disable,2.8",
          GUID = "194AE5A5",
          NextDialogue = 10103404,
          Scripts = "PARA{\nCameraMoveTo{_delay{3.1},TargetPosition{\"-90.900391,-30.177734,166.986359,8.004912,-21.999964,-173.387054,20.0,100000.0,false,Disable,2.8\"},duration{0}},\nCameraMoveTo{_delay{3.2},TargetPosition{\"-96.953125,-30.886719,164.522675,8.005135,-21.999969,-173.387054,20.0,100000.0,false,Disable,2.8\"},blend{\"easeOutQuad\"},duration{3}}\n}",
          SpeakNpcId = 200053,
          Subtitle = "Please, I, I surrender, p—please don't take me there!",
          TalkActionId = {
            [1] = "200053:Sigh_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101033/194AE5A5"
        },
        [10103404] = {
