          Scripts = "SEQ{\nPlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Talk02_Start\"},Duration{2}},\nPlayAnimation{ActorId{200011},AnimationId{\"Talk02_End\"},Duration{2}}\n}",
          SpeakNpcId = 200011,
          TurnTo = {
