          },
          VoiceName = "voice/$Locale$/story/1002/101033/194AE5A7"
        },
        [10103406] = {
          Camera = "-149.457031,53.760742,152.14772,0.000171,-7.199832,-10.806184,30.0,281.974091,false,Manual,2.793246",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Ne t’approche pas !",
          DialogueId = 10103406,
          FinalCamera = "-149.193359,55.460938,152.14772,0.000171,-7.199832,-9.000023,30.0,119.391449,false,Manual,2.291237",
          GUID = "194AF564",
          LookAt = {
            [1] = "200003:n(200011)",
            [2] = "200014:n(200014)"
          },
          NextDialogue = 10103407,
          Scripts = "PARA{\nPlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Talk03_End\"},Duration{1}},\n}",
          SpeakNpcId = 200003,
          Subtitle = "Are you playing dumb or you really don't know? If you're not pretending, I almost envy such ignorance.",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101034/194AF564"
        },
        [10103407] = {
          Camera = "246.730469,-195.367188,140.170639,0.000167,-3.39987,126.987076,35.0,388.101501,false,Manual,5.0",
          ContentFR = "Il est bien plus dangereux que vous ne l’imaginez.",
          DialogueId = 10103407,
          GUID = "194AF565",
          LookAt = {
            [1] = "200014:n(200011)",
            [2] = "100001:p(101034Look3)"
          },
          NextDialogue = 10103408,
          SpeakNpcId = 200003,
          Subtitle = "It's an incurable blight, the root of the suffering of all Charons in Hyperborea.",
          TurnTo = {
            [1] = "200003:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF565"
        },
        [10103408] = {
          Camera = "-14.123047,-197.56543,134.434448,0.000166,1.999995,49.988125,40.000011,417.684204,false,DoNotOverride,5.0",
          ContentFR = "... Peu importe. Margie a récupéré son argent, et toi {nickname}, tu as fait tes preuves.",
          DialogueId = 10103408,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "194AF566",
          LookAt = {
