        [10103501] = {
          Camera = "-165.324219,313.250977,140.767822,0.000018,-4.657957,-60.556728,41.027447,1.5,false,Disable,1.2",
          ContentFR = "C’est bizarre... Camilla en a vu d’autres, mais là, elle a vraiment paniqué...",
          DialogueId = 10103501,
          FacialId = {
            [1] = "200011:Think01"
          },
          GUID = "194AF569",
          LookAt = {
            [1] = "200002:n(200011)",
            [2] = "100001:n(200011)"
          },
          NextDialogue = 10103502,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201008,
            [4] = 201005
          },
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"}}",
          SpeakNpcId = 200011,
          Subtitle = "No, please... I'm begging you! Don't send me there—",
          TalkActionId = {
            [1] = "200011:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF569"
        },
        [10103502] = {
          Camera = "-135.308594,-179.244141,147.530365,0.000016,-7.258025,49.643944,35.000008,1.5,false,Disable,1.2",
          ContentFR = "Et ce voleur aussi, il tremblait de partout d’un coup. Le Bureau de la Sécurité, c’est si effrayant que ça ?",
          DialogueId = 10103502,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "194AF570",
          NextDialogue = 10103503,
          SpeakNpcId = 200002,
          Subtitle = "He seemed terrified. I wonder what's in store for him at the Security Bureau.",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "200011:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF570"
        },
        [10103503] = {
          Camera = "-37.669922,74.164062,136.618378,0.000016,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
          ContentFR = "On dirait qu’il va prendre cher, en tout cas. Moi, je voulais juste récupérer mon argent et lui asséner deux-trois coups, pas déclencher tout ça...",
          DialogueId = 10103503,
          FacialId = {
            [1] = "200011:Unhappy01"
          },
          GUID = "194AF571",
          NextDialogue = 10103504,
          SpeakNpcId = 200011,
          Subtitle = "Mmm, they'll probably give him a really harsh telling-off. But more importantly, I must commend you.",
          TalkActionId = {
            [1] = "200002:Shock_End",
            [2] = "200011:SpecialHoldHelmet_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF571"
        },
        [10103504] = {
          Camera = "-165.324219,313.250977,140.767822,0.000018,-4.657957,-60.556728,41.027447,1.5,false,Disable,1.2",
          ContentFR = "Ah, j’allais oublier, ta récompense ! Tiens !",
          DialogueId = 10103504,
          FacialId = {
            [1] = "200011:Smile01"
          },
          GUID = "194AF572",
          NextDialogue = 10103505,
          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{"Give"},Duration{1}}",
          SpeakNpcId = 200011,
          Subtitle = "Heehee, you were on fire, my little minion! That brash thing, and yet we put him in his place!",
          TalkActionId = {
            [1] = "200011:SpecialHoldHelmet_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF572"
        },
        [10103505] = {
          ContentFR = "Héhé, merci infiniment ! Tu m’as sauvé la vie, {性别:mon frère d’une autre mère|ma sœur d'un autre père} !",
          DialogueId = 10103505,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200011:Smile02"
          },
          GUID = "194AF573",
          NextDialogue = 10103506,
          SpeakNpcId = 200011,
          Subtitle = "A little correction — it wasn't "we", you were hiding behind me the whole time.",
          TalkActionId = {
            [1] = "200011:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF573"
        },
        [10103506] = {
          Camera = "-33.322266,90.494141,136.335449,0.000018,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
          ContentFR = "Bon, je dois vite redistribuer ces pièces. Moi, d’habitude, je "m’approvisionne" un peu partout à Givrelac. Si tu as besoin de moi, il suffit de donner mon nom dans les taudis, et ils t'aideront à me trouver.",
          DialogueId = 10103506,
          GUID = "194AF574",
          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{"Explain02_Start"},Duration{1}}",
          SpeakNpcId = 200011,
          TalkActionId = {
            [1] = "200011:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF574"
        },
        [10103507] = {
          ContentFR = "Allez, petit larbin, allons vite revoir Camilla !",
          DialogueId = 10103507,
          GUID = "194AF575",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101034/194AF575"
        },
        [10103601] = {
          ContentFR = "Les Asphodèles sont juste au sud.",
          DialogueId = 10103601,
          Duration = 3,
          GUID = "194B160A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10103602,
          SpeakNpcId = 200006,
          Subtitle = "The Asphodel is just to the south.",
          VoiceName = "voice/$Locale$/story/1002/101036/194B160A"
        },
        [10103602] = {
          ContentFR = "Dépêchez-vous ! Snow vous attend sur la place !",
          DialogueId = 10103602,
          Duration = 4,
          GUID = "194B1634",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Come on! Snow will be waiting for you in the square!",
          VoiceName = "voice/$Locale$/story/1002/101036/194B1634"
        },
        [10103701] = {
          ContentFR = "Viens voir, toutes les missions des Chasseurs de Phoxène sont affichées sur ce panneau !",
          DialogueId = 10103701,
          Duration = 3,
          GUID = "194B2672",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Over here, all the commissions for Phoxhunters are listed on this board!",
          VoiceName = "voice/$Locale$/story/1002/101037/194B2672"
        },
        [10103801] = {
          Camera = "172.692993,-479.681641,69.009766,0.001296,4.999999,95.0,25.000006,357.352783,false,DoNotOverride,1.2",
          ContentFR = "Eh, mais c’est Snow ! Encore en train d’aider les Chasseurs de Phoxène ? Et cette fois, qu’as-tu fait ? T’as arrêté quelques centaines de bandits et déjoué une dizaine de complots infernaux ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103801,
          FinalCamera = "158.725586,-480.897461,69.009766,0.001297,4.999999,97.500046,25.000006,357.352783,false,DoNotOverride,1.2",
          GUID = "194B36DA",
          LookAt = {
            [1] = "200002:n(200065)",
            [2] = "200065:n(200002)"
          },
          NextDialogue = 10103802,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201005
          },
          Scripts = "PARA{\nSetLocation{ActorId{100001},TargetPoint{\"P101038Nvzhu1\"},Visibility{\"Hide\"}},\nSetLocation{ActorId{200011},TargetPoint{\"P101038Maer2\"},Visibility{\"Hide\"}},\nSetLocation{ActorId{200006},TargetPoint{\"P101038Saiqi2\"},Visibility{\"Hide\"}},\nCameraMoveTo{_delay{4.1},TargetPosition{\"-107.217896,-73.446289,64.6875,0.001309,12.399525,32.702034,30.000002,318.590363,false,Manual,2.5\"},duration{0}},\nMoveTo{ActorId{200002},TargetPoint{\"P10103801\"},MoveSpeed{50}},\nPARA{\nTurnTo{TurnToDescription{\"200065:n(200002)\"}},\nPlayAnimation{_delay{2},ActorId{200065},AnimationId{\"Talk02_Start\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200065,
          Subtitle = "Ah, hi Snow! Lending a hand to the Phoxhunters again? What is it this time —\nNabbed a few hundred bandits, thwarted a dozen dastardly schemes?",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101038/194B36DA"
        },
        [10103802] = {
          Camera = "297.337158,171.632812,207.998047,0.001337,-21.800159,-149.094604,40.000011,379.447693,false,Manual,2.0",
          ContentFR = "Aujourd’hui, je fais profil bas, j’ai juste attrapé un voleur.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103802,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "194B3704",
          NextDialogue = 10103803,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Explain02_Start\"},Duration{2.4}},\nPlayAnimation{ActorId{200002},AnimationId{\"Confident_Start\"},Duration{0.5}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Today I'm keeping it low-key, just nabbed a petty thief.",
          TalkActionId = {
            [1] = "200065:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B3704"
        },
        [10103803] = {
          Camera = "-15.678711,45.273438,123.974609,0.001306,6.799911,-0.799835,30.000002,169.71138,false,Manual,2.5",
          ContentFR = "Un seul ? Pour une fois ça paraît crédible, faut que je voie ça.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103803,
          GUID = "194B372E",
          NextDialogue = 10103804,
          SpeakNpcId = 200065,
          Subtitle = "Just one? That sounds almost believable, I've got to see this.",
          TalkActionId = {
            [1] = "200065:Think_Start",
            [2] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B372E"
        },
        [10103804] = {
          Camera = "174.522949,141.578125,137.132812,0.001337,-15.600308,-143.896393,35.0,212.370575,false,Manual,2.8",
          ContentFR = "J’ai jamais menti ! Viens, mon petit larbin, je te présente Monsieur Wells, le plus bosseur des Chasseurs de Phoxène !",
          DialogueId = 10103804,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "194B3758",
          NextDialogue = 10103805,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{2}},\nPlayAnimation{ActorId{200002},AnimationId{\"Angry01_End\"},Duration{0.9}},\nPARA{\nLookAt{LookAtDescription{\"200002:n(100001)\"}},\nPlayAnimation{ActorId{200002},AnimationId{\"Explain01_Start\"},Duration{1}}\n}\n},\nLookAt{_delay{3.3},LookAtDescription{\"200065:n(100001)\"}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "I've never fibbed before! Come here, my little minion. This is Mr Wells, the most hard-working Phoxhunter around here.",
          TalkActionId = {
            [1] = "200065:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B3758"
        },
        [10103805] = {
          Camera = "-188.142944,-38.378906,104.90625,0.001338,4.199221,13.510482,25.0,364.620758,false,Manual,1.3",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Bonjour, Monsieur Wells.",
          DialogueId = 10103805,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-188.142944,-38.378906,104.90625,0.001338,4.199221,13.510482,25.0,364.620758,false,Manual,1.9",
          GUID = "194B3782",
          LookAt = {
            [1] = "200065:n(100001)"
          },
          NextDialogue = 10103806,
          Scripts = "PARA{\nSEQ{\nSetLocation{ActorId{100001},TargetPoint{\"P101038Nvzhu1\"},Visibility{\"Show\"}},\nMoveTo{ActorId{100001},TargetPoint{\"P10103804Nvzhu\"},MoveSpeed{45}},\nLookAt{LookAtDescription{\"100001:n(200065)\"}}\n},\nSetLocation{ActorId{200002},TargetPoint{\"P101038Bai1\"},Visibility{\"Show\"}},\nCameraMoveTo{_delay{2.5},TargetPosition{\"261.814209,159.358398,186.162109,0.00138,-16.899855,-144.293823,30.0,322.336731,false,Manual,1.8\"},duration{0}},\nCameraMoveTo{_delay{2.6},TargetPosition{\"261.814209,159.358398,186.162109,0.001386,-13.699514,-144.293701,30.0,322.336731,false,Manual,1.8\"},duration{4}},\nLookAt{_delay{2.6},LookAtDescription{\"200002:n(200065)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Hello, Mr Wells.",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101038/194B3782"
        },
        [10103806] = {
          Camera = "-220.573608,96.777344,99.291016,0.001347,2.799155,-17.691002,30.000002,397.786072,false,Manual,2.5",
          ContentFR = "Alors c’était toi ? {性别:Tout|Toute} propre sur toi... Qui aurait pu imaginer que tu en étais capable ?",
          DialogueId = 10103806,
          GUID = "194B37AC",
          LookAt = {
            [1] = "200002:n(200065)",
            [2] = "100001:n(200065)"
          },
          NextDialogue = 10103807,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200065},AnimationId{\"Talk03_Start\"},Duration{3.4}},\nPlayAnimation{ActorId{200065},AnimationId{\"Talk03_End\"},Duration{1}},\nPlayAnimation{ActorId{200065},AnimationId{\"Disagree\"},Duration{1}}\n}",
          SpeakNpcId = 200065,
          Subtitle = "So it was you? Looking all neat and tidy, who'd have thought you had it in you?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B37AC"
        },
        [10103807] = {
          Camera = "284.5,160.327148,200.447266,0.001179,-15.600097,-147.194611,35.000011,345.690643,false,Manual,2.25",
          ContentFR = "Merci, ce n'était rien.",
          DialogueId = 10103807,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "194B37D6",
          NextDialogue = 10103808,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_End\"},Duration{0.9}},\nPlayAnimation{ActorId{100001},AnimationId{\"Talk02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, it was just a small thing.",
