        [10104009] = {
          Camera = "124.620239,-443.34668,310.703125,0.001321,-20.100447,76.801399,25.0,680.331482,false,Manual,1.2",
          ContentFR = "Donc même si Henrik offre cinq mille pièces d’argent, aucun Chasseur n’a accepté.",
          DialogueId = 10104009,
          GUID = "194B58FA",
          NextDialogue = 10104010,
          Scripts = "SEQ{\nPlayAnimation{_delay{3.3},ActorId{200003},AnimationId{\"Talk03_End\"},Duration{1}},\nPlayAnimation{ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "So, even with Henrik dangling 5,000 silver coins, no Phoxhunter's bitten by the end of the day.",
          VoiceName = "voice/$Locale$/story/1002/101040/194B58FA"
        },
        [10104010] = {
          Camera = "684.517334,308.858398,177.394531,0.00124,-5.298,-154.201248,54.56435,525.42511,false,Manual,3.0",
          ContentFR = "Les Chasseurs sont des aventuriers nés, mais pas des inconscients ! Et puis, qui sait si Henrik pourra vraiment payer ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104010,
          GUID = "194B5924",
          NextDialogue = 10104011,
          Scripts = "SEQ{\nPlayAnimation{_delay{2.5},ActorId{200065},AnimationId{\"Disagree\"},Duration{3.1}},\nPlayAnimation{ActorId{200065},AnimationId{\"Angry01_Start\"},Duration{1.9}},\nPlayAnimation{ActorId{200065},AnimationId{\"Angry01_End\"},Duration{1}},\nPlayAnimation{ActorId{200065},AnimationId{\"Explain01_Start\"},Duration{1}},\nPlayFacial{_delay{3},ActorId{200006},FacialId{\"Sad01\"}}\n}",
          SpeakNpcId = 200065,
          Subtitle = "Phoxhunters are born adventurers, but we're not reckless fools! The stone's very existence aside...\nWho knows if Henrik can even cough up the cash?",
          VoiceName = "voice/$Locale$/story/1002/101040/194B5924"
        },
        [10104011] = {
          Camera = "77.71582,492.297852,137.373047,0.001236,-2.698307,-72.790131,35.0,468.643616,false,Manual,2.0",
          ContentFR = "Tout le monde sait qu’il est presque en faillite, prêt à vendre le manoir de sa famille. Veut-il vraiment jouer le tout pour le tout avec les Éclats stellaires ? ... Attends une minute, depuis des années, leur commerce est interdit... comment ferait-il pour les vendre ?",
          DialogueId = 10104011,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "88.144165,495.515625,137.373047,0.001236,-2.698307,-72.790131,35.0,471.859924,false,Manual,6.0",
          GUID = "194B594E",
          NextDialogue = 10104012,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200065},AnimationId{\"Explain01_End\"},Duration{1}},\nPARA{\nTurnTo{TurnToDescription{\"200065:n(100001)\"}},\nLookAt{LookAtDescription{\"200065:n(100001)\"}},\nPlayAnimation{_delay{5.1},ActorId{200065},AnimationId{\"Think_Start\"},Duration{4.8}}\n},\nPlayAnimation{ActorId{200065},AnimationId{\"Think_End\"},Duration{0.3}},\nPlayAnimation{ActorId{200065},AnimationId{\"Disagree\"},Duration{5}},\nPlayAnimation{ActorId{200065},AnimationId{\"Shock_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200065,
          Subtitle = "Everyone knows he's recently gone bankrupt, even looking to sell off the family house. Is he planning to gamble it all on trading Crystallo? ...Wait a minute, Crystallo trading's been banned for years, how's he planning to unload it?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101040/194B594E"
        },
        [10104012] = {
          Camera = "291.697021,172.415039,146.613281,0.001243,-3.898467,-153.747192,35.000008,191.320923,false,DoNotOverride,12.430392",
