        [10104013] = {
          Camera = "-875.020996,-905.817383,491.335938,0.001335,-14.498169,42.003368,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Madame Camilla, combien coûte le voyage vers le sud que vous avez mentionné ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104013,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:None",
            [2] = "100001:Confident01"
          },
          FinalCamera = "-829.493042,-864.821289,475.5,0.001335,-14.498169,42.003773,30.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "194B59A2",
          LookAt = {
            [1] = "100001:n(200003)"
          },
          NextDialogue = 10104014,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Explain02_Start"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Ms Camilla, how much are those tickets to the South you mentioned earlier?",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200065:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B59A2"
        },
        [10104014] = {
          Camera = "261.244263,118.665039,141.974609,0.001213,-1.298371,39.241299,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "À peu près pareil. Tu es intéressé par cette mission ?",
          DialogueId = 10104014,
          GUID = "194B59CC",
          LookAt = {
            [1] = "200006:n(200003)"
          },
          NextOptions = {
            [1] = 101040141
          },
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "About the same price. Interested in taking on the commission?",
          VoiceName = "voice/$Locale$/story/1002/101040/194B59CC"
        },
        [10104015] = {
          Camera = "310.518433,147.504883,143.865234,0.001244,-2.898315,-165.541214,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Tu...",
          DialogueId = 10104015,
          Duration = 1.5,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Shock01"
          },
          GUID = "194B59F6",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10104016,
          SpeakNpcId = 200006,
          Subtitle = "...You...",
          TurnTo = {
            [1] = "200065:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B59F6"
        },
        [10104016] = {
          Camera = "261.87085,-103.149414,166.572266,0.001257,-8.298399,112.052223,35.000008,221.426971,false,Manual,2.0",
          ContentFR = "Vraiment ? {性别:Gamin|Gamine}, je ne plaisante pas, ce n’est pas un jeu d’enfant !",
          DialogueId = 10104016,
          ExStoryInfo = "Player",
          GUID = "194B5A20",
          LookAt = {
            [1] = "100001:n(200065)",
            [2] = "200006:n(200065)"
          },
          NextDialogue = 10104017,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_End\"},Duration{0.5}},\nTurnTo{TurnToDescription{\"100001:n(200065)\"}},\nLookAt{LookAtDescription{\"100001:n(200065)\"}}\n},\nSEQ{\nPlayAnimation{_delay{2.5},ActorId{200065},AnimationId{\"Explain01_Start\"},Duration{2}},\nPlayAnimation{ActorId{200065},AnimationId{\"Explain01_End\"},Duration{2}},\nPlayAnimation{ActorId{200065},AnimationId{\"Disagree\"},Duration{0.5}}\n}\n}",
          SpeakNpcId = 200065,
          Subtitle = "You serious? Kid, I'm not joking with you — this isn't child's play!",
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A20"
        },
        [10104017] = {
          ContentFR = "Merci, je comprends. Mais, Madame Camilla...",
          DialogueId = 10104017,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "194B5A4A",
          LookAt = {
            [1] = "100001:n(200065)"
          },
          NextDialogue = 10104018,
          Scripts = "PARA{\nLookAt{_delay{3},LookAtDescription{\"100001:n(200003)\"}},\nCameraMoveTo{_delay{3.2},TargetPosition{\"21.058167,-60.678711,137.054688,0.001258,0.301785,41.650921,60.000004,500.770081,false,DoNotOverride,19.947756\"},duration{0}},\nSetRotation{_delay{3.2},SetRotationDescription{\"200003:n(200006)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Thank you, I get it. But Ms Camilla...",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A4A"
        },
        [10104018] = {
          Camera = "586.407837,263.538086,166.693359,0.001254,-5.098381,-163.341629,60.0,424.533936,false,Manual,3.8",
          ContentFR = "Vous l’avez dit. Si je ne peux même pas gérer ça, comment trouverais-je... ce que j’ai perdu ?",
          DialogueId = 10104018,
          ExStoryInfo = "Player",
          GUID = "194B5A74",
          LookAt = {
            [1] = "100001:n(200003)",
            [2] = "200006:n(100001)"
          },
          NextDialogue = 10104019,
          Scripts = "PARA{\nPlayAnimation{_delay{2.5},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}},\nPlayFacial{_delay{5},ActorId{200006},FacialId{\"Smile01\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "You once told me — if I can't handle this, how am I supposed to find my family?",
          TurnTo = {
            [1] = "100001:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A74"
        },
        [10104019] = {
          Camera = "-127.626587,-169.432617,135.080078,0.001295,0.699917,38.798576,70.000015,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les Asphodèles n’intervient pas dans le choix des missions des clients ou des Chasseurs. Si tu es déterminé, je ne t’arrêterai pas.",
          DialogueId = 10104019,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "194B5A9E",
          LookAt = {
            [1] = "200065:n(200003)"
          },
          NextDialogue = 10104022,
          Scripts = "SEQ{\nPlayAnimation{_delay{5.3},ActorId{200003},AnimationId{\"Talk03_End\"},Duration{1.8}},\nPlayAnimation{ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "The Asphodel doesn't interfere with the choices of clients or Phoxhunters. If you're set on it, I won't stand in your way.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "200065:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A9E"
        },
        [10104020] = {
          Camera = "259.278076,116.387695,137.603516,0.001216,-0.898272,38.841999,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voici ta récompense pour avoir récupéré l’argent de Margie. Et prends ceci aussi.",
          DialogueId = 10104020,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194B5AC8",
          NextDialogue = 10104021,
          Scripts = "PlayAnimation{_delay{5},ActorId{200003},AnimationId{"Talk02_Start"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "Here's your due for getting Margie's money back. And take this with you as well.",
          TalkActionId = {
            [1] = "200003:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5AC8"
        },
        [10104021] = {
          Camera = "-501.142578,-406.078125,344.859375,0.001474,-14.701865,36.043182,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Reviens {性别:vivant|vivante}.",
          DialogueId = 10104021,
          FinalCamera = "-751.681763,-588.393555,426.658203,0.001474,-14.701865,36.043182,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194B5AF2",
          Scripts = "SEQ{\nPlayAnimation{ActorId{200003},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{ActorId{200003},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200003,
          Subtitle = "Make it back in one piece.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5AF2"
        },
        [10104022] = {
          ContentFR = "L’Éclat stellaire est un cristal <H>bleu-violet</> qui semble contenir des nébuleuses en mouvement. Dans la mine sombre, il se remarque facilement, tu ne pourras pas le rater.",
          DialogueId = 10104022,
          GUID = "194B5A9F",
          NextDialogue = 10104020,
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A9F"
        },
        [10104101] = {
          ContentFR = "... Éclat stellaire... Monsieur Henrik...",
          DialogueId = 10104101,
          GUID = "194B6812",
          SpeakNpcId = 200006,
          Subtitle = "...Crystallo of Stella... Mr Henrik...",
          VoiceName = "voice/$Locale$/story/1002/101041/194B6812"
        },
        [10104201] = {
          ContentFR = "{性别:Ne joue pas au héros, gamin|Ne fais pas l’héroïne, gamine}. Si les choses tournent mal, cours pour sauver ta peau.",
          DialogueId = 10104201,
          ExStoryInfo = "Player",
          GUID = "194B787A",
          SpeakNpcId = 200015,
          Subtitle = "Don't be a hero, kid. Run for your life if things get dicey.",
          VoiceName = "voice/$Locale$/story/1002/101042/194B787A"
        },
        [10104301] = {
          ContentFR = "Aux Asphodèles, on trouve bien plus que de l’alcool... bien plus. À condition, bien sûr, d’être prêt à en payer le prix.",
          DialogueId = 10104301,
          GUID = "194B88E2",
          NextOptions = {
            [1] = 101043011,
            [2] = 101043051,
            [3] = 101043091,
            [4] = 101043112
          },
          SpeakNpcId = 200003,
          Subtitle = "Back for a drink already?",
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_02"
        },
        [10104302] = {
          ContentFR = "Par où commencer... l’histoire est longue. Après la Grande Migration, 800 ans plus tôt, le premier Empereur de l’Empire a construit cette cité, parmi les premières de l’Empire.",
          DialogueId = 10104302,
          GUID = "194B890C",
          NextDialogue = 10104303,
          SpeakNpcId = 200003,
          Subtitle = "Where to begin... well, it's got a long history. Built by the Empire's first ruler after the Great Migration 800 years ago, it's among the first few cities of the empire.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B890C"
        },
        [10104303] = {
          ContentFR = "C’est aussi la plus grande ville au nord de l’Empire. Cent kilomètres plus au nord, après les Monts Vidofnir, c’est le territoire d’Askard.",
          DialogueId = 10104303,
          GUID = "194B8936",
          NextDialogue = 10104304,
          SpeakNpcId = 200003,
          Subtitle = "It's also the northernmost major city of the Empire. Just over a hundred kilometres further north, past the Vidofnir Mountains, and you're on Askard's turf.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8936"
        },
        [10104304] = {
          ContentFR = "Givrelac était réputée pour le Phoxène. La Fosse de Glevum, par exemple, était l’une des plus grandes mines d’Hyperborea. Maintenant, les veines sont épuisées, seules les anciennes usines fonctionnent encore tant bien que mal.",
          DialogueId = 10104304,
          GUID = "194B8960",
          NextDialogue = 10104305,
          SpeakNpcId = 200003,
          Subtitle = "Icelake used to be known for its Phoxene veins. Take Glevum Pit for example — one of Hyperborea's largest Phoxene mines back in the day. But now, the veins are spent, only the old factories are barely chugging along.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8960"
        },
        [10104305] = {
          ContentFR = "Mais ça, tu peux le lire dans les livres. Je te conseille d’observer par toi-même et d’écouter avec ton cœur pour savoir ce que cache vraiment cette cité sous la glace et la neige.",
          DialogueId = 10104305,
          GUID = "194B898A",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "But then, this is all stuff you can read about in books, things anyone could tell you. I'd suggest you look with your own eyes and listen with your heart, to find out what truly lurks beneath this city's snow and ice.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B898A"
        },
        [10104306] = {
          ContentFR = "Ce sont des bavards, pleins de vantardises. Certains cherchent juste à gagner leur vie, d’autres aiment l’aventure et le désordre. Tous finissent souvent blessés.",
          DialogueId = 10104306,
          GUID = "194B89B4",
          NextDialogue = 10104307,
          SpeakNpcId = 200003,
          Subtitle = "A bunch of cheap, noisy blighters keen on spinning yarns. Some of them became Phoxhunters to eke a living, some just fancy a bit of ruckus and adventure. One thing they have in common is they often end up more battered and bruised than not.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B89B4"
        },
        [10104307] = {
          ContentFR = "Honnêtement, j’ai souvent envie de les virer pour qu’ils mangent de la neige sale dehors et se prennent le vent glacial en pleine figure.",
          DialogueId = 10104307,
          GUID = "194B89DE",
          NextDialogue = 10104308,
          SpeakNpcId = 200003,
          Subtitle = "Truth be told, I've often wanted to give them the boot, let them munch on dirty snow and gulp the north wind outside.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B89DE"
        },
        [10104308] = {
          ContentFR = "Mais ils font quand même pas mal de choses que le Bureau de la Sécurité devrait gérer. Sans eux, peu de gens auraient le loisir de se poser tranquillement aux Asphodèles.",
          DialogueId = 10104308,
          GUID = "194B8A08",
          NextDialogue = 10104309,
          SpeakNpcId = 200003,
          Subtitle = "But then, they do manage a fair bit that ought to be the Security Bureau's job. Without them, likely not many in this city would have the luxury to kick back in my tavern.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A08"
        },
        [10104309] = {
          ContentFR = "Donc je les laisse papoter ici, c’est du donnant-donnant. Mais j’aimerais qu’ils parlent un peu moins fort et se battent moins.",
          DialogueId = 10104309,
          GUID = "194B8A32",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "So I let them gather and natter here, a bit of quid pro quo. Still, I do wish they'd keep it down a little and get into fewer brawls.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A32"
        },
        [10104310] = {
          ContentFR = "Personne ne t’a dit que c’est plutôt impoli de vouloir fouiner dans les secrets d’une dame sans raison ?",
          DialogueId = 10104310,
          GUID = "194B8A5C",
          NextDialogue = 10104311,
          SpeakNpcId = 200003,
          Subtitle = "Hasn't anyone told you it's rather rude to pry into a lady's secrets for no reason?",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A5C"
        },
        [10104311] = {
          ContentFR = "Mais si tu veux vraiment entendre mes histoires... il faudra d’abord payer le prix qui convient... hé hé.",
          DialogueId = 10104311,
          GUID = "194B8A86",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "Of course, I can share my stories with you — provided you can pay the right price... hehe.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A86"
        },
        [10104401] = {
          Camera = "937.774414,-120.576172,119.04834,0.000012,-1.999695,166.391983,35.0,762.45813,false,Manual,1.6",
          ContentFR = "Attendez !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104401,
          FinalCamera = "936.792969,-122.973145,119.04834,0.000012,-1.999695,163.999969,35.0,762.45813,false,Manual,5.0",
