          Scripts = "PARA{\nMoveTo{ActorId{200006},MoveSpeed{75},TargetPoint{\"P101044Saiqi1\"}},\nMoveTo{ActorId{100001},MoveSpeed{55},TargetPoint{\"P101044Nvzhu\"}},\nMoveTo{ActorId{200002},MoveSpeed{55},TargetPoint{\"P101044Bai\"}},\nCameraMoveTo{_delay{2.1},TargetPosition{\"-314.240234,-155.733398,118.795898,0.00002,-0.59952,20.992918,40.0,639.254089,false,Manual,2.0\"},duration{0}},\nCameraMoveTo{_delay{2.2},TargetPosition{\"-314.240234,-155.733398,118.795898,0.00002,-0.599424,20.999535,40.0,493.09787,false,Manual,2.0\"},duration{3}},\nMoveTo{_delay{2},ActorId{200006},MoveSpeed{300},TargetPoint{\"P101044Saiqi\"}},\nTurnTo{_delay{2.2},TurnToDescription{\"100001:n(200006)\"}},\nTurnTo{_delay{2.5},TurnToDescription{\"200002:n(200006)\"}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "Hold on, please!",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101044/194B994A"
        },
        [10104402] = {
          Camera = "214.22168,-132.881836,141.021973,0.000037,-1.199094,134.199219,35.0,230.308487,false,Manual,4.0",
          ContentFR = "Psyche ? Que fais-tu ici ?",
