        },
        [10104403] = {
          Camera = "-188.268555,-20.25293,121.632812,0.000053,0.600934,2.599361,30.000002,316.328461,false,Manual,2.5",
          ContentFR = "Je suis venue vous guider un peu... Je veux dire, pour aller à la Fosse de Glevum.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104403,
          FacialId = {
            [1] = "200006:Happy02"
          },
          GUID = "194B999E",
          NextDialogue = 10104404,
          Scripts = "PARA{PlayAnimation{ActorId{200006},AnimationId{"Explain02_Start"},Duration{4}},SEQ{LookAt{LookAtDescription{"200006:n(200002)"}},LookAt{_delay{1},LookAtDescription{"200006:n(100001)"}}}}",
          SpeakNpcId = 200006,
          Subtitle = "I thought I'd help show you the way. I mean... to Glevum Pit.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101044/194B999E"
        },
        [10104404] = {
          Camera = "-271.905273,-43.04541,1110.167236,0.000141,-2.599092,-179.809708,25.0,813.98584,false,DoNotOverride,1.2",
          ContentFR = "Snow connaît le chemin ! Mais... euh, c’est mieux d’être plusieurs, surtout quand on quitte la cité.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104404,
          FacialId = {
            [1] = "200002:Smile02"
          },
          FinalCamera = "-574.290039,-44.049316,1694.915527,0.000141,-2.599092,-179.809708,25.0,813.98584,false,DoNotOverride,1.2",
          GUID = "194B99C8",
          NextDialogue = 10104405,
          Scripts = "SEQ{\nPARA{\nPlayAnimation{ActorId{200002},AnimationId{\"Talk01_Start\"},Duration{1}},\nLookAt{LookAtDescription{\"100001:n(200002)\"}},\nLookAt{LookAtDescription{\"200002:n(200006)\"}}\n},\nSEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Talk01_End\"},Duration{0.1}},\nLookAt{LookAtDescription{\"100001:n(200006)\"}},\nLookAt{LookAtDescription{\"200002:n(200006)\"}},\nPlayAnimation{ActorId{200002},AnimationId{\"Agree\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Snow knows the way! But... it's nice to have some company, especially when we're heading out of town.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101044/194B99C8"
        },
        [10104405] = {
          Camera = "-80.464844,-28.455566,146.255371,0.000019,-2.199915,8.608652,35.000008,213.527512,false,Manual,4.0",
          ContentFR = "Oui, les étrangers se perdent facilement hors de la ville. J’ai vu que vous avez accepté la mission de Monsieur Henrik... notre mission, donc j’ai pensé que je pourrais donner un coup de main.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104405,
          FacialId = {
            [1] = "200006:Smile02"
          },
          GUID = "194B99F2",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextOptions = {
            [1] = 101044051,
            [2] = 101044052
          },
          Scripts = "SEQ{\nPlayAnimation{ActorId{200006},AnimationId{\"AgreeHead\"},Duration{2}},\nPlayAnimation{ActorId{200006},AnimationId{\"SpecialThink_Start\"},Duration{2}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "Yeah, outsiders can easily lose their way out there. I saw you accepted Mr Henrik's... our request, so I thought I should help out.",
          VoiceName = "voice/$Locale$/story/1002/101044/194B99F2"
        },
        [10104406] = {
          Camera = "618.545898,-425.736328,165.672852,0.000053,-5.400419,148.00415,25.0,705.171997,false,DoNotOverride,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Parfait, ça me fait aussi plaisir de marcher un peu. On y va ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104406,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "608.34375,-442.196289,165.672852,0.000051,-5.400419,149.999954,25.000002,715.606018,false,DoNotOverride,5.0",
          GUID = "194B9A1C",
          SpeakNpcId = 200006,
          Subtitle = "Actually, I was looking forward to a little walk myself, too. Shall we get going?",
          TalkActionId = {
            [1] = "200006:SpecialThink_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101044/194B9A1C"
        },
        [10104501] = {
          ContentFR = "Ouah... ça fait longtemps que je n’étais pas sortie de la cité.",
          DialogueId = 10104501,
          Duration = 3,
          GUID = "194BA9B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104502,
          SpeakNpcId = 200006,
          Subtitle = "Whoo... It's been a while since I've stepped out of the city.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9B2"
        },
        [10104502] = {
          ContentFR = "Les conifères recouverts de neige, le lac à perte de vue... les sommets des montagnes plongés dans les nuages... j’adore.",
          DialogueId = 10104502,
          Duration = 3,
          GUID = "194BA9DC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104503,
          SpeakNpcId = 200006,
          Subtitle = "The snow-draped conifers, the boundless lake... mountains with their peaks in the clouds... I love all this.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9DC"
        },
        [10104503] = {
          ContentFR = "Snow a plutôt l’âme d’une citadine ! Si seulement ces Souillés ne rôdaient pas à l’extérieur...",
          DialogueId = 10104503,
          Duration = 3,
          GUID = "194BAA06",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104504,
          SpeakNpcId = 200002,
          Subtitle = "Snow's more a city soul! If only the outskirts were free of those roaming Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA06"
        },
        [10104504] = {
          ContentFR = "C’est plus sûr à l’intérieur, c’est vrai. Mais j’aime bien… l’air ici.",
          DialogueId = 10104504,
          Duration = 3,
          GUID = "194BAA30",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104505,
          SpeakNpcId = 200006,
          Subtitle = "It's safer inside, indeed. But there's something about the... air out here.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA30"
        },
        [10104505] = {
          ContentFR = "Il y a une différence ? Moi, ça sent pareil...",
          DialogueId = 10104505,
          Duration = 3,
          GUID = "194BAA5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104506,
          SpeakNpcId = 200002,
          Subtitle = "Is there a difference? All smells the same to me...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA5A"
        },
        [10104506] = {
          ContentFR = "Mmm... l’air de Givrelac est toujours chargé de sang et de pleurs.",
          DialogueId = 10104506,
          Duration = 3,
          GUID = "194BAA84",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104507,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... The air in Icelake is always tinged with a scent of blood and echoes of weeping.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA84"
        },
        [10104507] = {
          ContentFR = "Ici, c’est l’odeur de la forêt, de la glace flottante, et le sifflement lointain des locomotives. Parfois, on aperçoit des cerfs blancs surgir de la forêt...",
          DialogueId = 10104507,
          Duration = 3,
          GUID = "194BAAAE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104508,
          SpeakNpcId = 200006,
          Subtitle = "Out here, it's the scent of the forest and drifting ice, and the distant sound of steam whistles. Occasionally, you might catch a glimpse of snow-white deer darting through the trees—",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAAE"
        },
        [10104508] = {
          ContentFR = "Alors qu’au détour des rues de Givrelac, ce sont des voleurs, des brigands... ou des mendiants qui gémissent.",
          DialogueId = 10104508,
          Duration = 3,
          GUID = "194BAAD8",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104509,
          SpeakNpcId = 200006,
          Subtitle = "While around Icelake's alleys, what darts out are thieves, bandits... or whimpering beggars.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAD8"
        },
        [10104509] = {
          ContentFR = "Et toi, {nickname} ? Parle-nous de ta ville natale ! Cette île, elle est comment ?",
          DialogueId = 10104509,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB02",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104510,
          SpeakNpcId = 200006,
          Subtitle = "What about your hometown, ? Tell us about it! What's that island like?",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB02"
        },
        [10104510] = {
          ContentFR = "L’air est fait de gravier doré et de romarin sur la côte...",
          DialogueId = 10104510,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104511,
          SpeakNpcId = 100001,
          Subtitle = "The "air" there is golden gravel and white rue flowers...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB2C"
        },
        [10104511] = {
          ContentFR = "C’est la brume marine de minuit et l’immense Arbre Céleste que Berr... ma famille et moi regardions chaque jour.",
          DialogueId = 10104511,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB56",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104512,
          SpeakNpcId = 100001,
          Subtitle = "It's misty sea fogs at midnight, and the massive Heaventree that Ber... my family and I used to gaze upon every day.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB56"
        },
        [10104512] = {
          ContentFR = "Mmm... si jamais tu retournes là-bas, transmets-leur mes salutations.",
          DialogueId = 10104512,
          Duration = 3,
          GUID = "194BAB80",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104513,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... if you ever make it back to your homeland, please send them my regards.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB80"
        },
        [10104513] = {
          ContentFR = "... Hmm, vous deux, c’est pas facile à suivre...",
          DialogueId = 10104513,
          Duration = 3,
          GUID = "194BABAA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104514,
          SpeakNpcId = 200002,
          Subtitle = "...Umm, you two are talking over my head...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABAA"
        },
        [10104514] = {
          ContentFR = "Tu comprendras mieux quand tu seras plus grande.",
          DialogueId = 10104514,
          Duration = 3,
          GUID = "194BABD4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104515,
          SpeakNpcId = 200006,
          Subtitle = "You'll get it when you're older.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABD4"
        },
        [10104515] = {
          ContentFR = "... Mais les Luno ne semblent jamais vraiment grandir, non ?",
          DialogueId = 10104515,
          Duration = 3,
          GUID = "194BABFE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...But then again, Lunos never really grow older, do you?",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABFE"
        },
        [10104601] = {
          Camera = "-114.347656,1810.079102,572.782715,0.00006,-15.999997,-93.351616,25.0,482.997925,false,DoNotOverride,1.2",
          ContentFR = "Voilà l’entrée de la Fosse de Glevum. Soyez {性别:prudents|prudentes}.",
          DialogueId = 10104601,
          FinalCamera = "-114.347656,1810.079102,540.30127,0.00006,-13.999989,-93.351624,25.0,482.997925,false,DoNotOverride,1.2",
          GUID = "194BBA1A",
          NextDialogue = 10104602,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201007,
            [4] = 201005,
            [5] = 301004,
            [6] = 406001
          },
          Scripts = "PARA{\nSEQ{\nMoveTo{ActorId{200006},TargetPoint{\"P10104603\"},MoveSpeed{50}},\nTurnTo{_delay{0.5},TurnToDescription{\"200006:p(180)\"}}\n},\nSEQ{\nMoveTo{ActorId{100001},TargetPoint{\"P10104602\"},MoveSpeed{60}},\nLookAt{LookAtDescription{\"100001:n(200006)\"}}\n},\nMoveTo{ActorId{200002},TargetPoint{\"P10104601\"},MoveSpeed{45}}\n}\n",
          SpeakNpcId = 200006,
          Subtitle = "The entrance to Glevum Pit is up ahead. Please be extra careful.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA1A"
        },
        [10104602] = {
          Camera = "-4.705078,-275.623535,148.607422,0.000054,-3.999943,59.446644,35.000008,204.586716,false,Manual,7.37621",
          ContentFR = "Merci, tu nous as vraiment bien aidés.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104602,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "194BBA44",
          NextDialogue = 10104603,
          Scripts = "PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{"Explain02_Start"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, you've been a tremendous help.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA44"
        },
        [10104603] = {
          ContentFR = "Vous deux, rentrez. Je peux continuer seul.",
          DialogueId = 10104603,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194BBA6E",
          NextDialogue = 10104604,
          Scripts = "PARA{\nLookAt{LookAtDescription{\"100001:n(200006)\"}},\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(200002)\"}},\nSEQ{\nCameraMoveTo{_delay{0.8},TargetPosition{\"-4.705078,-275.623535,148.607422,0.000054,-3.999943,59.446644,35.000008,204.586716,false,Manual,7.37621\"},duration{0}},\nCameraMoveTo{TargetPosition{\"25.423828,-300.893066,153.260254,0.000032,-17.799767,100.245705,35.000008,204.586716,false,Manual,7.37621\"},Blend{\"easeInOutQuad\"},duration{8}}\n}\n}",
          SpeakNpcId = 100001,
          Subtitle = "You two should head back now. I can take it from here on my own.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA6E"
        },
        [10104604] = {
          ContentFR = "... Euh... pas question !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104604,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "194BBA98",
          NextDialogue = 10104605,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"SpecialConfident_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "...Umm... no way!",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA98"
        },
        [10104605] = {
          ContentFR = "Ce Roi Démon ne peut pas fuir devant le combat et laisser son petit larbin penser qu’elle est faible. Psyche, viens aussi !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104605,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "194BBAC2",
          LookAt = {
            [1] = "200006:n(200002)"
          },
          NextDialogue = 10104606,
          Scripts = "PARA{\nLookAt{LookAtDescription{\"200002:n(100001)\"}},\nPlayAnimation{_delay{4.8},ActorId{200002},AnimationId{\"SpecialConfident_End\"},Duration{1}},\nPlayFacial{_delay{3},ActorId{200002},FacialId{\"Unhappy02\"}},\nPlayFacial{_delay{5},ActorId{200002},FacialId{\"Smile01\"}},\nLookAt{delay{8},LookAtDescription{\"200002:n(200006)\"}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "This Demon King can't just scarper from the battle and let the little minion think less of her. Psyche, you should also come with us!",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBAC2"
        },
        [10104606] = {
          Camera = "-28.857422,-67.701172,111.056641,0.000052,9.799764,-64.964821,40.000031,141.186768,false,Manual,8.987392",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Moi... ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104606,
          FacialId = {
            [1] = "200006:Shock01"
          },
          FinalCamera = "-16.4375,-94.304688,116.129395,0.000052,9.999759,-64.964989,40.000027,141.186768,false,Manual,8.987392",
          GUID = "194BBAEC",
          NextDialogue = 10104607,
          Scripts = "PlayAnimation{_delay{0.8},ActorId{200002},AnimationId{"Explain01_End"},Duration{0.1}}",
          SpeakNpcId = 200006,
          Subtitle = "Me...?",
          TalkActionId = {
            [1] = "200006:Think_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBAEC"
        },
        [10104607] = {
          Camera = "1137.132812,2278.000977,1126.149414,0.000085,-21.600649,-103.932426,25.0,168.419693,false,DoNotOverride,5.0",
          ContentFR = "Oui, viens avec le Roi Démon nettoyer ce repaire de monstres ! Psyche, tu n’as jamais vécu une telle aventure, n’est-ce pas ? Quel dommage ! Ta vie est incomplète !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104607,
          FacialId = {
            [1] = "200002:Smile02"
          },
          FinalCamera = "1278.716797,2242.87793,1126.149414,0.000085,-21.600649,-103.932632,25.0,168.419693,false,DoNotOverride,5.0",
          GUID = "194BBB16",
          NextDialogue = 10104608,
          Scripts = "SEQ{\nCameraMoveTo{_delay{8.5},TargetPosition{\"-44.302734,13.918945,72.365723,0.000042,12.799815,-75.562065,40.000027,260.261597,false,Manual,8.987392\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-31.933594,-11.705078,78.753418,0.000044,13.599787,-73.361298,40.000031,260.261597,false,Manual,8.987392\"},duration{15}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Yup — come with the Demon King to clear out this monster's den!\nI bet you've never been on such an adventure, right? What a pity! Your life is certainly incomplete!",
          ToFinalCameraBlendTime = 17,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBB16"
        },
        [10104608] = {
          ContentFR = "... Ah...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104608,
          Duration = 2,
          GUID = "194BBB40",
          LookAt = {
            [1] = "200006:n(200002)"
          },
          NextDialogue = 10104609,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200006},AnimationId{\"Think_End\"},Duration{0.5}}}",
          SpeakNpcId = 200006,
          Subtitle = "...Ah...",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBB40"
        },
        [10104609] = {
          Camera = "-4.705078,-275.623535,148.607422,0.000054,-3.999943,59.446644,35.000008,204.586716,false,Manual,7.37621",
          ContentFR = "... Bon, je viens.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104609,
          FacialId = {
            [1] = "200006:Smile01",
            [2] = "100001:Unhappy01"
          },
