            [2] = "100001:n(200006)"
          },
          NextOptions = {
            [1] = 101046091,
            [2] = 101046092
          },
          Scripts = "PARA{\nPlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{0.5}},\nPlayAnimation{_delay{5},ActorId{200006},AnimationId{\"Explain02_End\"},Duration{0.5}},\nPlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Think_Start\"},Duration{0.5}},\nPlayAnimation{ActorId{200002},AnimationId{\"Agree\"},Duration{0.5}}\n}\n",
          SpeakNpcId = 200006,
          Subtitle = "...Alright, I'm in.",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBB6A"
        },
        [10104610] = {
          Camera = "59.988281,-46.624023,150.626953,0.000005,-4.199733,-90.964828,40.000011,175.938858,false,Manual,8.987392",
          ContentFR = "Non, « une vie sans aventure est incomplète »... je crois qu’elle a raison.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104610,
          FacialId = {
            [1] = "200006:Satisfy01"
          },
          GUID = "194BBB94",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10104611,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{6.5}},\nPlayAnimation{ActorId{200006},AnimationId{\"Talk02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "No, "a life without adventure is certainly incomplete"... I think she's right.",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBB94"
        },
        [10104611] = {
          Camera = "-1093.402344,-90.92041,40.319336,0.000074,4.600064,-2.560578,40.000011,291.229248,false,DoNotOverride,8.987392",
          ContentFR = "Alors, je peux venir avec vous ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104611,
          FinalCamera = "-1163.527344,-87.78418,34.672363,0.000074,4.600064,-2.560578,40.000011,291.229248,false,DoNotOverride,8.987392",
          GUID = "194BBBBE",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10104612,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200006},AnimationId{\"Talk02_End\"},Duration{1.8}},\nPlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "So, may I join you on this adventure?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBBBE"
        },
        [10104612] = {
          Camera = "-54.855469,-231.366211,124.558594,0.000041,-12.799651,82.845856,35.000008,160.594696,false,Manual,7.37621",
          ContentFR = "Allons-y ! À Givrelac, la nuit tombe tôt, il faut se dépêcher.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104612,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "194BBBE8",
          LookAt = {
            [1] = "200002:n(200006)"
          },
          NextDialogue = 10104613,
          Scripts = "SetRotation{SetRotationDescription{"100001:n(200006)"}}",
          SpeakNpcId = 200002,
          Subtitle = "Let's go, let's go! It gets dark early in Icelake, we gotta hurry.",
          TalkActionId = {
            [1] = "200002:Talk03_Start",
            [2] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBBE8"
        },
        [10104613] = {
          Camera = "47.644531,26.861328,156.047852,-0.0,-5.199734,-84.16452,40.000023,241.163803,false,Manual,8.987392",
          ContentFR = "Oui !",
          DialogueId = 10104613,
          FacialId = {
            [1] = "200006:Smile01"
          },
          GUID = "194BBC12",
          LookAt = {
            [1] = "200006:n(100001)",
            [2] = "100001:n(200006)"
          },
          NextDialogue = 10104614,
          SpeakNpcId = 200006,
          Subtitle = "Right!",
          TalkActionId = {
            [1] = "200006:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBC12"
        },
        [10104614] = {
          Camera = "-3371.945312,1771.284668,1105.757324,0.000082,-14.000022,-33.965176,56.0,2477.148193,false,DoNotOverride,8.987392",
          ContentFR = "... Très bien. Faites attention, toutes les deux.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104614,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "194BBC3C",
          LookAt = {
            [1] = "100001:n(200006)"
          },
          Scripts = "SEQ{\nPlayAnimation{_delay{0.9},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}},\nPlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "...Alright then. Be careful, both of you.",
          TalkActionId = {
            [1] = "200006:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBC3C"
        },
        [10104701] = {
          ContentFR = "C’est verrouillé ? Regarde, je vais la fracasser !",
          DialogueId = 10104701,
          Duration = 3,
          GUID = "194BCA82",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104702,
          SpeakNpcId = 200002,
          Subtitle = "It's locked? Watch me bash it open!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCA82"
        },
        [10104702] = {
          Content = "（头槌砸门声）",
          DialogueId = 10104702,
          DisableMouth = 1,
          Duration = 2,
          GUID = "194BCA83",
          NextDialogue = 10104703,
          Subtitle = "*Sound of headbutting the door*",
          VoiceName = "sfx/common/story/01/tietougong"
        },
        [10104703] = {
          ContentFR = "... Aïe !",
          DialogueId = 10104703,
          Duration = 2,
          GUID = "194BCAD6",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104704,
          SpeakNpcId = 200002,
          Subtitle = "...Ouchie!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCAD6"
        },
        [10104704] = {
          ContentFR = "Une porte de cette épaisseur, on ne l’ouvrira pas par la force.",
          DialogueId = 10104704,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCB00",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104705,
          SpeakNpcId = 100001,
          Subtitle = "A door this thick is probably impervious to brute force.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB00"
        },
        [10104705] = {
          ContentFR = "Alors cherchons un autre passage autour.",
          DialogueId = 10104705,
          Duration = 3,
          GUID = "194BCB2A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104706,
          SpeakNpcId = 200006,
          Subtitle = "Then let's look around to see if there's another way in.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB2A"
        },
        [10104706] = {
          ContentFR = "Snow, ta tête te fait mal ? Laisse-moi t’aider—",
          DialogueId = 10104706,
          Duration = 3,
          GUID = "194BCB54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104707,
          SpeakNpcId = 200006,
          Subtitle = "Snow, does your head hurt? Let me help you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB54"
        },
        [10104707] = {
          ContentFR = "... Voilà, un petit souffle et ça va mieux.",
          DialogueId = 10104707,
          Duration = 3,
          GUID = "194BCB7E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104708,
          SpeakNpcId = 200006,
          Subtitle = "...There, a little puff to ease the pain.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB7E"
        },
        [10104708] = {
          ContentFR = "Oooh... tu es vraiment gentille. Quand ce Roi Démon prendra le contrôle de cet endroit, je te nommerai...",
          DialogueId = 10104708,
          Duration = 3,
          GUID = "194BCBA8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104709,
          SpeakNpcId = 200002,
          Subtitle = "Awww... you're such a nice person. When this Demon King conquers this place, I'll appoint you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBA8"
        },
        [10104709] = {
          ContentFR = "« La Douce Mage en Vert, Grande et Infaillible Maîtresse du Phoxène, première Grande Duchesse de la Fosse de Glevum » !",
          DialogueId = 10104709,
          Duration = 3,
          GUID = "194BCBD2",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104710,
          SpeakNpcId = 200002,
          Subtitle = "The Gentle Green-Cloaked Mage, the Wise Master of Phoxene, the Inaugural Grand Duke of Glevum Pit!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBD2"
        },
        [10104710] = {
          ContentFR = "Avant, j’étais {性别:Duc des Égouts|Duchesse des Égouts}... une Grande Duchesse est-il un rang supérieur {性别:au Duc|à la Duchesse} ?",
          DialogueId = 10104710,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCBFC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104711,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I was the Duke of the Sewers... is a grand duke a higher rank than a duke?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBFC"
        },
        [10104711] = {
          ContentFR = "Pourquoi Psyche a-t-elle un titre plus élevé ? Hein ! Et pourquoi je réfléchis sérieusement à ça ?",
          DialogueId = 10104711,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCC26",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(How come Psyche gets a higher title than me? Hold on, why am I seriously mulling this over again?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCC26"
        },
        [10104801] = {
          ContentFR = "« Guidé par Snow le Roi Démon, le petit larbin arrivé il y a peu à Givrelac est devenu {性别:un excellent Chasseur de Phoxène|une excellente Chasseuse de Phoxène} en un seul jour. »",
          DialogueId = 10104801,
          GUID = "194BDAEA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104802,
          SpeakNpcId = 200002,
          Subtitle = "Guided by Snow the Demon King, the little minion who just arrived in Icelake from afar has become a brilliant Phoxhunter in a mere day.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDAEA"
        },
        [10104802] = {
          ContentFR = "Une nouvelle page dans la légende de ce Roi Démon !",
          DialogueId = 10104802,
          GUID = "194BDB14",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104803,
          SpeakNpcId = 200002,
          Subtitle = "A new chapter of the legend of this Demon King!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB14"
        },
        [10104803] = {
          ContentFR = ""Chasseur de Phoxène"... c’est un nom original. Ils chassent vraiment du Phoxène ?",
          DialogueId = 10104803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDB3E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104804,
          SpeakNpcId = 100001,
          Subtitle = "Phoxhunter is a cool name... Do they all hunt something called Phox?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB3E"
        },
        [10104804] = {
          ContentFR = "Non, non ! De nos jours, les Chasseurs de Phoxène sont surtout des chasseurs de primes. Autrefois, ça avait un rapport avec le Phoxène...",
          DialogueId = 10104804,
          GUID = "194BDB68",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104805,
          SpeakNpcId = 200002,
          Subtitle = "Nah! Phoxhunters nowadays are actually bounty hunters. It has something to do with Phoxene a long time ago.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB68"
        },
        [10104805] = {
          ContentFR = "Oui, j’ai entendu dire que ce métier est né ici même, à Givrelac. ",
          DialogueId = 10104805,
          GUID = "194BDB92",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104806,
          SpeakNpcId = 200006,
          Subtitle = "Right, I heard it used to refer to a profession that originated right here in Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB92"
        },
        [10104806] = {
          ContentFR = "Apparemment, c’est parce que dans les Monts Vidofnir, les veines de l’Arbre Céleste regorgeaient de Phoxène que l’on pouvait vendre à bon prix...",
          DialogueId = 10104806,
          GUID = "194BDBBC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104807,
          SpeakNpcId = 200006,
          Subtitle = "It seemed to all start with the rich Heaventree veins in the Vidofnir Mountains, and the Phoxene on them could be sold for a good price...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBBC"
        },
        [10104807] = {
          ContentFR = "Exact ! Il y a très longtemps, beaucoup de gens prenaient le risque de partir en mission juste pour le Phoxène.",
          DialogueId = 10104807,
          GUID = "194BDBE6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104808,
          SpeakNpcId = 200002,
          Subtitle = "Exactly! So, a long, long time ago, many people braved the risks of collecting Phoxene for money.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBE6"
        },
        [10104808] = {
          ContentFR = "Mais ensuite, les grands marchands et l’Empire ont pris le contrôle des mines, et les gens ordinaires n’avaient presque plus accès au Phoxène...",
          DialogueId = 10104808,
          GUID = "194BDC10",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104815,
          SpeakNpcId = 200006,
          Subtitle = "But then the big merchants and the Empire took over the mines around here, and ordinary folk hardly had a chance with Phoxene anymore... After that, the local veins gradually ran dry.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC10"
        },
        [10104809] = {
          ContentFR = "Mais le métier de Chasseur de Phoxène, vivre de missions, est resté. C’est juste que les types de missions ont changé.",
          DialogueId = 10104809,
          GUID = "194BDC3A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104810,
          SpeakNpcId = 200002,
          Subtitle = "While Phoxhunters, who lived off commissions, remained as a profession. It's just that the types of commissions changed a lot since then.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC3A"
        },
        [10104810] = {
          ContentFR = "Il y a les grosses missions, comme protéger la ville des griffes des Souillés, et les petites... comme récupérer du pain tout juste sorti du four... des dents d’un chien !",
          DialogueId = 10104810,
          GUID = "194BDC64",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104811,
          SpeakNpcId = 200002,
          Subtitle = "There are big ones like protecting the city from the claws of Filthoids, and little ones like getting freshly baked bread back from a dog's mouth...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC64"
        },
        [10104811] = {
          ContentFR = "Récupérer du pain à un chien ?",
          DialogueId = 10104811,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDC8E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104812,
          SpeakNpcId = 100001,
          Subtitle = "Fighting dogs for bread?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC8E"
        },
        [10104812] = {
          ContentFR = "Et certaines missions sont encore plus terrifiantes, comme faire disparaître quelqu’un qu’on déteste...",
          DialogueId = 10104812,
          GUID = "194BDCB8",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104813,
          SpeakNpcId = 200002,
          Subtitle = "And some even more terrifying commissions like making sure a certain someone you don't like never shows up again...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCB8"
        },
        [10104813] = {
          ContentFR = "Mais le temps que tu ailles jusqu’aux Asphodèles, le pain n’a-t-il pas déjà été mangé par le chien ?",
          DialogueId = 10104813,
          GUID = "194BDCE2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104814,
          SpeakNpcId = 200006,
          Subtitle = "But by the time you make a trip down to The Asphodel, wouldn't the bread have been gobbled up by the dog already?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCE2"
        },
        [10104814] = {
          ContentFR = "Arrêtez avec vos histoires de chiens !",
          DialogueId = 10104814,
          GUID = "194BDD0C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "You're both missing the point here!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDD0C"
        },
        [10104815] = {
          ContentFR = "Puis les filons se sont peu à peu épuisés, comme ici dans la Fosse de Glevum...",
          DialogueId = 10104815,
          GUID = "194BDC11",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104816,
          SpeakNpcId = 200006,
          Subtitle = "After that, the local veins gradually ran dry, including this Glevum Pit...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC11"
        },
        [10104816] = {
          ContentFR = "Oui, dommage ! Sinon mon petit larbin aurait fait fortune avec le Phoxène.",
          DialogueId = 10104816,
          GUID = "194BDC12",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104809,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, what a pity! Otherwise my little minion could have made a fortune selling Phoxene.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC12"
        },
        [10104901] = {
          ContentFR = "Ça va ?",
          DialogueId = 10104901,
          ExStoryInfo = "Player",
          GUID = "194BEB52",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104902,
          SpeakNpcId = 100001,
          Subtitle = "Everything alright?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB52"
        },
        [10104902] = {
          ContentFR = "... !",
          DialogueId = 10104902,
          GUID = "194BEB7C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104903,
          SpeakNpcId = 200006,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB7C"
        },
        [10104903] = {
          ContentFR = "Je ne voyais plus rien tout à l’heure et j’ai fini par l’effrayer... Désolée !",
          DialogueId = 10104903,
          GUID = "194BEBA6",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104904,
          SpeakNpcId = 200006,
          Subtitle = "I suddenly couldn't see clearly back there and ended up startling that monster... I'm so sorry!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBA6"
        },
        [10104904] = {
          ContentFR = "Ça va mieux maintenant ?",
          DialogueId = 10104904,
          ExStoryInfo = "Player",
          GUID = "194BEBD0",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104905,
          SpeakNpcId = 100001,
          Subtitle = "Are you feeling better now?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBD0"
        },
        [10104905] = {
          ContentFR = "Oui, ça va.",
          DialogueId = 10104905,
          GUID = "194BEBFA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10104906,
          SpeakNpcId = 200006,
          Subtitle = "Yeah, I'm fine now.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBFA"
        },
        [10104906] = {
          ContentFR = "Bien. Si tu peux te battre, alors affrontons ce monstre ensemble.",
          DialogueId = 10104906,
          ExStoryInfo = "Player",
          GUID = "194BEC24",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104907,
          SpeakNpcId = 100001,
          Subtitle = "Great. If you're in the condition to fight, let's take on this monster together.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC24"
        },
        [10104907] = {
          ContentFR = "Compris ! Je ferai de mon mieux pour te soutenir.",
          DialogueId = 10104907,
          GUID = "194BEC4E",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Sure! I'll do my best to support you.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC4E"
        },
        [10105001] = {
          ContentFR = "J’ai entendu dire que même les bêtes les plus féroces peuvent être vaincues si on trouve leur <H>point faible</>.",
          DialogueId = 10105001,
          GUID = "194BFBB9",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105002,
          SpeakNpcId = 200006,
          Subtitle = "They say even the fiercest beasts can be brought down by targeting their weaknesses...",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBB9"
        },
        [10105002] = {
          ContentFR = "Ce doit être la même chose avec ce Souillé ! Restons calmes et cherchons son point faible.",
          DialogueId = 10105002,
          GUID = "194BFBBA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It must be the same with this Filthoid! Let's take a breath and find its weakness.",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBBA"
        },
        [10105101] = {
          ContentFR = "Il devient plus lent. {nickname}, <H>les parties qui ressemblent à ses épaules</> sont ses points faibles !",
          DialogueId = 10105101,
          ExStoryInfo = "Player",
          GUID = "194C0C4C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It's become slow. , those gems must be its weak points!",
          VoiceName = "voice/$Locale$/story/1002/101051/194C0C4C"
        },
        [10105201] = {
          ContentFR = "Il s’est arrêté — maintenant, c’est notre chance !",
          DialogueId = 10105201,
          GUID = "194C1C8A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105202,
          SpeakNpcId = 200006,
          Subtitle = "It's stopped — now's our chance!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1C8A"
        },
        [10105202] = {
          ContentFR = "Parfait... !",
          DialogueId = 10105202,
          GUID = "194C1CB4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Great...!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1CB4"
        },
        [10105301] = {
          ContentFR = "Éclat stellaire... Quelle beauté ! Pas étonnant que tout le monde le veuille.",
          DialogueId = 10105301,
          GUID = "194C2CF2",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "Crystallo of Stella... Look at its beauty! No wonder everyone wants a piece of it.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2CF2"
        },
        [10105302] = {
          ContentFR = "J’ai entendu un sacré vacarme tout à l’heure... C’est vous qui avez eu raison de ce monstre géant ? Pas mal du tout.",
          DialogueId = 10105302,
          GUID = "194C2D1C",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "What a commotion I just heard. So it was you guys that took out that giant thing? Impressive.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2D1C"
        },
        [10105401] = {
          Camera = "-29.328125,-255.251953,164.21875,0.001081,-14.107393,94.226692,50.000008,544.145996,false,Manual,5.0",
          ContentFR = "L’Étranger ?! Qu’est-ce que tu fabriques ? Comment se fait-il que l’Éclat stellaire soit entre tes mains ? C’est mon petit larbin qui l’avait—",
          DialogueId = 10105401,
          FacialId = {
            [1] = "200021:Smile02",
            [2] = "200002:Angry01"
          },
