          Scripts = "SEQ{\nLookAt{LookAtDescription{\"200021:n(200006)\"}},\nLookAt{LookAtDescription{\"200021:n(200061)\"}},\nPlayAnimation{ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{1}},\n}",
          SpeakNpcId = 200021,
          Subtitle = "You call the shots in your little crew, right? Tell me — why did you guys go to all this trouble for this Crystallo?",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3FD3"
        },
        [10105420] = {
          Camera = "-133.171875,185.023438,129.78125,0.001317,2.399193,-66.600601,45.000011,335.117126,false,Manual,8.0",
          ContentFR = "Je m’en doutais. Parfait, ça simplifie les choses. Pour certaines raisons, je dois emmener cet Éclat stellaire, mais si c’est pour la prime que tu es là, je peux te donner la même somme.",
          DialogueId = 10105420,
          FinalCamera = "-136.361328,183.650391,129.78125,0.001317,2.199164,-65.600883,45.000011,335.117126,false,Manual,8.0",
          GUID = "194C4078",
          LookAt = {
            [1] = "200021:n(200061)"
          },
          NextDialogue = 10105421,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Talk02_End\"},Duration{4}},\nPlayAnimation{ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{4}},\n}",
          SpeakNpcId = 200021,
          Subtitle = "That's false, everyone might hide away, but Outsider certainly can't.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4078"
        },
        [10105421] = {
          Camera = "-45.742188,-32.140625,140.254883,0.001334,-1.201505,104.203934,45.000023,134.353271,false,Manual,8.0",
          ContentFR = "Si tu as un moment, j’aimerais t’expliquer — tu es libre ce soir ?",
          DialogueId = 10105421,
          FinalCamera = "-45.742188,-32.140625,140.254883,0.001334,-1.201505,104.003983,47.0,134.353271,false,Manual,8.0",
          GUID = "194C4079",
          NextOptions = {
            [1] = 101054211,
            [2] = 101054212
          },
          SpeakNpcId = 200021,
          Subtitle = "If you've got a moment, I'd like to explain — Are you free tonight?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4079"
        },
        [10105422] = {
          Camera = "-56.242188,-98.783203,85.512695,0.000091,-2.001614,108.598442,35.000011,124.888115,false,Manual,2.8",
          ContentFR = "Oh, c’est facile. Avec Snow comme témoin, il ne pourra pas se défiler ! Et puis, Camilla a dit qu’il a un proche terrifiant à la maison, dont il a vraiment peur. ",
          DialogueId = 10105422,
          FinalCamera = "-45.761719,-99.34375,85.657227,0.000093,-1.001545,114.597237,35.000015,124.888115,false,Manual,2.8",
          GUID = "194C4080",
          LookAt = {
            [1] = "200002:n(200021)",
            [2] = "200021:n(200002)"
          },
          NextDialogue = 10105423,
          Scripts = "PlayAnimation{_delay{6.5},ActorId{200002},AnimationId{"Think_End"},Duration{1}},\n",
          SpeakNpcId = 200002,
          Subtitle = "Oh, that's easy. With Snow as a witness, he won't be able to weasel out! Besides, Camilla mentioned he's got a terrifying relative at home he's really scared of.",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "\n200021:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4080"
        },
        [10105423] = {
          Camera = "-2.09375,155.646484,180.238281,0.000153,-33.400742,-131.193481,35.000008,188.968185,false,Manual,5.0",
          ContentFR = "Menace-le de publier tous ses secrets devant chez lui, et il implorera ta clémence en un rien de temps.",
          DialogueId = 10105423,
          FinalCamera = "-0.138672,153.929688,180.238281,0.000153,-33.400742,-131.193481,35.000008,188.968185,false,Manual,5.0",
          GUID = "194C4081",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105424,
          Scripts = "SEQ{\nTurnTo{TurnToDescription{\"200002:n(200061)\"}},\nPlayAnimation{ActorId{200002},AnimationId{\"SpecialConfident_Start\"},Duration{1}},\n}",
          SpeakNpcId = 200002,
          Subtitle = "Just threaten to air his dirty laundry right on his doorstep, and he'll be begging for mercy in no time.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4081"
        },
        [10105424] = {
          Camera = "-192.289062,-117.390625,137.607422,0.001453,5.699383,-0.388946,50.0,162.415543,false,DoNotOverride,1.2",
          ContentFR = "... Pitié, je vous en supplie, Grand Roi Démon.",
          DialogueId = 10105424,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "194C4082",
          NextDialogue = 10105425,
          Scripts = "PARA{\nPlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayAnimation{ActorId{200021},AnimationId{\"Sigh_Start\"},Duration{1}},\n}\n",
          SpeakNpcId = 200021,
          Subtitle = "...Mercy, please, Your Demon King.",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          TurnTo = {
            [1] = "200002:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4082"
        },
        [10105425] = {
          Camera = "-1043.257812,-1602.347656,78.117188,0.001387,-0.599458,57.977047,50.0,1941.626953,false,Manual,10.0",
          ContentFR = "Rassurez-vous, tout le monde aux Asphodèles me connaît. Bon, j’ai encore quelques affaires à régler ici. Vous pouvez y aller sans moi.",
          DialogueId = 10105425,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "-1020.1875,-1634.185547,78.268555,0.001395,-0.599458,57.97691,50.000008,1941.626953,false,Manual,10.0",
          GUID = "194C4083",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105426,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Sigh_End\"},Duration{1}},\nTurnTo{TurnToDescription{\"200021:p(180)\"}},\n}",
          SpeakNpcId = 200021,
          Subtitle = "You can rest assured — everyone at The Asphodel knows me. Well, I've still got things to take care of here. You kids can go ahead without me.",
          TalkActionId = {
            [1] = "200061:Angry01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4083"
        },
        [10105426] = {
          Camera = "-24.691406,-252.042969,170.015625,0.001425,-5.800073,93.189316,60.000027,375.978333,false,Manual,8.0",
          ContentFR = "Tu comptes faire quoi ?",
          DialogueId = 10105426,
          ExStoryInfo = "Player",
          GUID = "194C40A2",
          NextDialogue = 10105427,
          Scripts = "SetLocation{ActorId{200002},TargetPoint{"P101054_BaiMove1"},Visibility{"Hide"}},",
          SpeakNpcId = 200061,
          Subtitle = "Er, how come you are as clueless as a newly hatched quail? I bet even that white little button mushroom beside you is even more informed.",
          VoiceName = "voice/$Locale$/story/1002/101054/194C40A2"
        },
        [10105427] = {
          Camera = "-24.691406,-252.042969,170.015625,0.001425,-5.800073,93.189316,60.000027,375.978333,false,Manual,8.0",
          ContentFR = "Regarde ces sacs. ",
          DialogueId = 10105427,
          GUID = "194C40CC",
          NextDialogue = 10105428,
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}},\nLookAt{LookAtDescription{\"200006:p(P101054_Watch)\"}},\nSEQ{\nTurnTo{TurnToDescription{\"200021:p(-90)\"}},\nLookAt{LookAtDescription{\"200061:p(P101054_Watch)\"}},\n},\n}\n",
          SpeakNpcId = 200021,
          Subtitle = "Of course, Snow's really smart—wait, what did you just call me? How rude!",
          VoiceName = "voice/$Locale$/story/1002/101054/194C40CC"
        },
        [10105428] = {
          Camera = "-1728.742188,5596.728516,1904.164062,0.001424,-17.799246,-151.3983,45.0,354.288879,false,DoNotOverride,10.0",
          ContentFR = "Sans ce monstre, leurs propriétaires seraient peut-être encore en train de se détendre aux Asphodèles, en sirotant un verre et en racontant des histoires.",
          DialogueId = 10105428,
          FinalCamera = "-1728.742188,5596.728516,1904.164062,0.001424,-17.799246,-151.3983,48.0,354.288879,false,DoNotOverride,10.0",
          GUID = "194C40F6",
          NextDialogue = 10105429,
          SpeakNpcId = 200021,
          Subtitle = "If it hadn't been for this monster, their owners might still be chilling at The Asphodel, sipping drinks and swapping stories.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101054/194C40F6"
        },
        [10105429] = {
          Camera = "-132.814453,-357.947266,210.344727,0.001424,-14.199464,73.163467,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je veux voir si je peux identifier leurs propriétaires et restituer leurs affaires à leur famille... maintenant que je suis là, je ne peux pas les laisser traîner.",
          DialogueId = 10105429,
          FinalCamera = "-130.597656,-350.683594,191.751953,0.001424,-11.999413,72.962524,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "194C4120",
          NextDialogue = 10105430,
          Scripts = "PARA{\nTurnTo{_delay{0.5},TurnToDescription{\"200021:n(200061)\"}},\nLookAt{_delay{1},LookAtDescription{\"200061:n(200021)\"}},\nLookAt{_delay{1.3},LookAtDescription{\"200006:n(200021)\"}},\n}",
          SpeakNpcId = 200021,
          Subtitle = "I want to see if I can identify them and return their belongings to their families… Now that I'm here, I can't just leave it be.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4120"
        },
        [10105430] = {
          Camera = "-132.251953,201.019531,133.736328,0.001431,1.600122,-68.005325,50.000008,389.24408,false,Manual,8.0",
          ContentFR = "Heureusement que ce sont vous, les "Daimons", qui êtes arrivés. Si c’étaient des gens ordinaires... ils auraient fini comme eux.",
          DialogueId = 10105430,
          FinalCamera = "-137.875,198.705078,133.736328,0.001431,1.80011,-66.605614,50.000008,389.24408,false,Manual,8.0",
          GUID = "194C414A",
          LookAt = {
            [1] = "200021:n(200061)"
          },
          NextDialogue = 10105431,
          Scripts = "PARA{\nSetLocation{ActorId{200002},TargetPoint{\"P101054_BaiMove1\"},Visibility{\"Show\"}},\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}},\n\n}",
          SpeakNpcId = 200021,
          Subtitle = "Simply put, "Awakening" is a stage of growth every Charon goes through, usually around adulthood. During Awakening, their body emits a very bright light — you must have some memory of it!",
          ToFinalCameraBlendTime = 7.5,
          TurnTo = {
            [1] = "200021:n(200061)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C414A"
        },
        [10105431] = {
          Camera = "-59.283203,-22.328125,148.204102,0.001411,-4.700071,97.800545,50.000008,130.215485,false,Manual,8.0",
          ContentFR = "<H>« Daimons »</> ?",
          DialogueId = 10105431,
          ExStoryInfo = "Player",
          GUID = "194C4174",
          NextDialogue = 10105432,
          SpeakNpcId = 200061,
          Subtitle = "After Awakening, some Charons become much stronger — like you, and gain the ability to use special magic! They are called "Daimons".",
          TalkActionId = {
            [1] = "200061:Think_Start",
            [2] = "\n200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4174"
        },
        [10105432] = {
          Camera = "-97.054688,115.751953,143.101562,0.001309,1.293119,-71.877045,52.0,276.944702,false,Manual,8.0",
          ContentFR = "Ce sont des Charons comme nous, qui ont traversé <H>« l’Éveil »</> et obtenu des pouvoirs spéciaux.",
          DialogueId = 10105432,
          FinalCamera = "-97.054688,115.751953,143.101562,0.001309,1.293119,-71.877045,50.0,276.944702,false,Manual,8.0",
          GUID = "194C419E",
          NextDialogue = 10105433,
          RelatedWikiId = {
            [1] = 303005
          },
          SpeakNpcId = 200021,
          Subtitle = "(It was that moment... No wonder I felt lighter than before, and my wounds must've healed around that time too.)",
          TalkActionId = {
            [1] = "200021:ExplainTwo_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101054/194C419E"
        },
        [10105433] = {
          Camera = "-201.890625,-594.59375,248.981445,0.001437,-12.600892,74.777382,50.0,368.690277,false,DoNotOverride,8.0",
          ContentFR = "Euh, pourquoi tu as l’air aussi perdu qu’un petit poussin tout juste sorti de l’œuf ? Je parie que même ce petit champignon blanc à côté de toi est plus informé.",
          DialogueId = 10105433,
          FinalCamera = "-201.890625,-594.59375,235.96582,0.001442,-12.000854,74.976952,50.0,368.690277,false,DoNotOverride,8.0",
          GUID = "194C41C8",
          NextDialogue = 10105434,
          Scripts = "PlayAnimation{_delay{1.2},ActorId{200021},AnimationId{"Think_Start"},Duration{1}},",
          SpeakNpcId = 200021,
          Subtitle = "(...As for my magic ability... could it be "Resonance"?)",
          TalkActionId = {
            [1] = "200021:ExplainTwo_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101054/194C41C8"
        },
        [10105434] = {
          Camera = "-60.347656,-156.458984,107.821289,0.001331,-7.906121,102.313034,50.000011,187.720139,false,Manual,5.0",
          ContentFR = "Bien sûr, Snow est super intelligente — attends, tu m’as appelé comment ?! Trop impoli !",
          DialogueId = 10105434,
          FacialId = {
            [1] = "200002:Happy02"
          },
          FinalCamera = "-61.121094,-153.123047,107.338867,0.001322,-8.106109,102.913803,50.000011,187.720139,false,Manual,5.0",
          GUID = "194C41F2",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105435,
          Scripts = "PARA{\nPlayFacial{_delay{4.5},ActorId{200002},FacialId{\"Angry01\"}},\nSEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Confident_Start\"},Duration{3}},\nPlayAnimation{ActorId{200002},AnimationId{\"Think_Start\"},Duration{2.7}},\nPlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{1}}\n},\nCameraMoveTo{_delay{5.5},TargetPosition{\"-56.050781,-151.96875,107.338867,0.001323,-9.30618,102.914429,50.000011,163.031174,false,Manual,5.0\"},duration{1}},\n}\n",
          SpeakNpcId = 200002,
          Subtitle = "Daimons are rare, so you guys are lucky ducks!",
          TalkActionId = {
            [1] = "200021:Think_End",
            [2] = "\n200002:Angry01_End"
          },
          ToFinalCameraBlendTime = 3.4,
          VoiceName = "voice/$Locale$/story/1002/101054/194C41F2"
        },
        [10105435] = {
          Camera = "-437.984375,565.548828,190.137695,0.001318,-9.399911,-52.879211,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas impoli, je suis juste honnête. Mon cœur est aussi pur que cet Éclat stellaire.",
          DialogueId = 10105435,
          FacialId = {
            [1] = "200021:Smile02",
            [2] = "\n200002:None"
          },
          FinalCamera = "-457.835938,550.085938,190.137695,0.001318,-9.39989,-51.879406,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194C421C",
          LookAt = {
            [1] = "200021:n(200002)"
          },
          NextDialogue = 10105436,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Talk01_Start\"},Duration{2}},\nPlayAnimation{ActorId{200021},AnimationId{\"Explain02_Start\"},Duration{1}}\n\n}",
          SpeakNpcId = 200021,
          Subtitle = "Most Charons aren't so lucky. At best, they get a bit sturdier. There are even some that might turn into scary monsters!\nThough I've never seen it myself.",
          TalkActionId = {
            [1] = "200002:Angry01_End",
            [2] = "\n200061:Think_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101054/194C421C"
        },
        [10105436] = {
          Camera = "-457.835938,550.085938,190.137695,0.001318,-9.39989,-51.879406,35.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Hmpf, je ne vais pas me rabaisser à discuter avec un petit personnage comme toi ! Viens ici, mon petit larbin, laisse ton Roi Démon t’éclairer. ",
          DialogueId = 10105436,
          FinalCamera = "-465.341797,544.189453,190.137695,0.001318,-9.399897,-51.879646,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "194C4246",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 10105437,
          Scripts = "PARA{\nSEQ{\nTurnTo{_delay{1},TurnToDescription{\"200002:p(-90)\"}},\nMoveTo{ActorId{200002},TargetPoint{\"P101054_BaiMove2\"},MoveSpeed{90},Visibility{\"Show\"}},\nTurnTo{TurnToDescription{\"200002:n(200061)\"}},\nPlayAnimation{ActorId{200002},AnimationId{\"Explain02_Start\"},Duration{1}}\n},\nSEQ{\nLookAt{LookAtDescription{\"200061:n(200002)\"}},\nTurnTo{_delay{1},TurnToDescription{\"200061:n(200002)\"}}\n}\n}",
          SpeakNpcId = 200002,
          Subtitle = "The button mushroom covers about most of it. Ordinary Charons might be able to handle small Filthoids if they give it their best shot, but huge ones like the one we just fought are deadly for them.",
          TalkActionId = {
            [1] = "200021:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "200006:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4246"
        },
        [10105437] = {
          Camera = "-353.777344,-47.939453,40.262695,0.001464,14.798335,24.421301,40.0,345.303528,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "En bref, "l’Éveil" est une étape de croissance que tout Charon traverse, en général à l’âge adulte. Au moment de l’Éveil, le corps émet une lumière très intense, tu dois sûrement t’en souvenir !",
          DialogueId = 10105437,
          ExStoryInfo = "Player",
          FinalCamera = "-360.898438,-30.494141,40.262695,0.001463,14.598415,21.022375,40.0,345.303528,false,Manual,2.8",
          GUID = "194C4270",
          LookAt = {
            [1] = "200061:n(200002)"
          },
          NextDialogue = 10105438,
          Scripts = "PARA{\nPlayAnimation{_delay{5.2},ActorId{200002},AnimationId{\"Explain01_Start\"},Duration{4.8}},\nPlayAnimation{_delay{10},ActorId{200002},AnimationId{\"Explain01_End\"},Duration{1.8}},\nPlayAnimation{_delay{11.8},ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "They were just trying to complete a commission...",
          TalkActionId = {
            [1] = "200061:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4270"
        },
        [10105438] = {
          Camera = "-101.375,79.515625,124.116211,0.001489,-19.999441,-142.798492,35.0,124.912491,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Après l’Éveil, certains Charons deviennent beaucoup plus forts, comme toi, et peuvent utiliser une magie spéciale ! Ce sont les "Daimons".",
          DialogueId = 10105438,
          ExStoryInfo = "Player",
          FinalCamera = "-101.375,79.515625,124.116211,0.001489,-19.999441,-142.798492,37.0,124.912491,false,Manual,8.0",
          GUID = "194C429A",
          NextDialogue = 10105439,
          RelatedWikiId = {
            [1] = 303003
          },
