          SnapShot = "MEMORY",
          SpeakNpcId = 200061,
          Subtitle = "I'll be back a bit late. Come find me at my place — it's among those shabby houses south of the city,\nthe one with a little bird drawn on the door.",
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C42C4"
        },
        [10105440] = {
          ContentFR = "... Quant à mon pouvoir... pourrait-il s’agir de la "Résonance" ?",
          DialogueId = 10105440,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194C42EE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10105435.T_Story_Recall_10105435'",
          NextDialogue = 10105441,
          Scripts = "PARA{\nLookAt{_delay{0.5},LookAtDescription{\"200006:n(200002)\"}},\n}",
          SnapShot = "MEMORY",
          SpeakNpcId = 200061,
          Subtitle = "And come alone — don't bring anyone unrelated.",
          VoiceName = "voice/$Locale$/story/1002/101054/194C42EE"
        },
        [10105441] = {
          Camera = "-245.439453,-114.015625,61.24707,0.001315,7.199019,57.799244,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les "Daimons" sont rares, vous avez donc beaucoup de chance !",
          DialogueId = 10105441,
          FinalCamera = "-242.505859,-115.867188,61.24707,0.001315,7.199019,57.799244,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "194C4318",
          LookAt = {
            [1] = "200002:n(200061)"
          },
          NextDialogue = 10105442,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Most Charons aren't so lucky. At best, they get a bit sturdier. There are even some that might turn into scary monsters!\nThough I've never seen it myself.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4318"
        },
        [10105442] = {
          Camera = "84.869141,80.519531,138.115234,0.000074,-0.799583,168.758072,50.0,167.178925,false,Manual,5.0",
          ContentFR = "La plupart des Charons n’ont pas cette chance. Au mieux, ils deviennent juste un peu plus résistants. On dit que certains deviennent même des monstres terrifiants... mais je n’en ai jamais vu !",
          DialogueId = 10105442,
          FacialId = {
            [1] = "200006:Sad01"
          },
          FinalCamera = "82.318359,69.537109,138.115234,0.000074,-0.799583,163.757156,50.0,167.178925,false,Manual,5.0",
          GUID = "194C4342",
          LookAt = {
            [1] = "200061:n(200061)"
          },
          NextDialogue = 10105443,
          Scripts = "PARA{\nTurnTo{TurnToDescription{\"200061:p(35)\"}},\nPlayAnimation{_delay{1.2},ActorId{200061},AnimationId{\"Think_Start\"},Duration{2.5}},\nPlayAnimation{_delay{10},ActorId{200006},AnimationId{\"SpecialThink_Start\"},Duration{1}},\nLookAt{_delay{3},LookAtDescription{\"200006:n(200006)\"}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "The button mushroom covers about most of it. Ordinary Charons might be able to handle small Filthoids if they give it their best shot, but huge ones like the one we just fought are deadly for them.",
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4342"
        },
        [10105443] = {
          Camera = "-119.701172,158.724609,129.237305,0.001394,1.886382,-66.264267,40.000023,309.032684,false,Manual,8.0",
          ContentFR = "Le petit champignon blanc a résumé l’essentiel. Les Charons ordinaires peuvent peut-être gérer de petits Souillés, mais des géants comme celui que nous venons de combattre sont mortels pour eux.",
          DialogueId = 10105443,
          FinalCamera = "-122.875,157.320312,129.237305,0.001394,1.886382,-65.464432,40.000023,309.032684,false,Manual,8.0",
          GUID = "194C436C",
          LookAt = {
            [1] = "200002:n(200021)",
            [2] = "200021:n(200061)",
            [3] = "200061:n(200061)"
          },
          NextDialogue = 10105444,
          Scripts = "PARA{\nTurnTo{_delay{1},TurnToDescription{\"200061:n(200021)\"}},\nSEQ{\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{6.3}},\nPlayAnimation{ActorId{200021},AnimationId{\"Confident_End\"},Duration{1.7}},\nPlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200021,
          Subtitle = "They were just trying to complete a commission...",
          TalkActionId = {
            [1] = "200006:SpecialThink_End",
            [2] = "\n200061:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200021:n(200061)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C436C"
        },
        [10105444] = {
          Camera = "-32.449219,-55.212891,133.299805,0.001344,1.001886,104.931633,50.0,169.448013,false,Manual,8.0",
          ContentFR = "Ils essayaient juste d’accomplir une mission...",
          DialogueId = 10105444,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200061:Sad01"
          },
          FinalCamera = "-32.449219,-55.212891,133.299805,0.001344,1.001886,104.931633,51.0,169.448013,false,Manual,8.0",
          GUID = "194C4396",
          LookAt = {
            [1] = "200061:n(200061)"
          },
          NextDialogue = 10105445,
          SpeakNpcId = 200061,
          Subtitle = "No, they were just trying to survive. Well, off you go. I'll handle the rest here.",
          TalkActionId = {
            [1] = "200061:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "200002:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4396"
        },
        [10105445] = {
          Camera = "86.544922,-391.478516,183.082031,0.001313,-9.799319,109.31813,35.000008,210.591583,false,DoNotOverride,10.0",
          ContentFR = "Non, ils essayaient juste de survivre. Allez, partez. Je vais m’occuper du reste. ",
          DialogueId = 10105445,
          FacialId = {
            [1] = "200061:None"
          },
          FinalCamera = "73.251953,-447.859375,181.362305,0.001316,-9.599339,106.918709,35.000011,210.591583,false,DoNotOverride,10.0",
          GUID = "194C43C0",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105446,
          Scripts = "SEQ{\nTurnTo{TurnToDescription{\"200021:p(180)\"}},\nMoveTo{_delay{0.5},ActorId{200021},TargetPoint{\"P101054_AoteMove2\"},MoveSpeed{90},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "I'll be back a bit late. Come find me at my place — it's among those shabby houses south of the city,\nthe one with a little bird drawn on the door.",
          TalkActionId = {
            [1] = "200021:Confident_End",
            [2] = "\n200061:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101054/194C43C0"
        },
        [10105446] = {
          Camera = "227.804688,530.064453,114.802734,0.000015,-1.793635,-114.596718,35.0,803.517822,false,DoNotOverride,4.0",
          ContentFR = "Je vais rentrer un peu plus tard, il se peut que les Asphodèles soit déjà fermé. Venez me trouver chez moi, c’est parmi ces maisons délabrées au sud de la cité, celle avec un petit oiseau sur la porte. ",
          DialogueId = 10105446,
          FinalCamera = "227.804688,530.064453,104.378906,0.000015,-1.393611,-114.396393,35.0,803.517822,false,DoNotOverride,4.0",
          GUID = "194C43EA",
          NextDialogue = 10105447,
          Scripts = "SEQ{\nTurnTo{_delay{2},TurnToDescription{\"200021:n(200061)\"}},\nPlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Think_Start\"},Duration{3}},\n}\n\n",
          SpeakNpcId = 200021,
          Subtitle = "I'll be back a bit late, might miss The Asphodel's closing time. Come and find me at my place — it's among those shabby houses south of the city, the one with a little bird drawn on the door.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101054/194C43EA"
        },
        [10105447] = {
          Camera = "-9.882812,4.484375,146.6875,0.000026,1.206198,-92.395676,50.0,241.293564,false,Manual,4.0",
          ContentFR = "Et viens {性别:seul|seule}, ne prends personne d’inutile avec toi.",
          DialogueId = 10105447,
          FinalCamera = "-9.882812,4.484375,146.6875,0.000026,1.406199,-92.39563,52.0,241.293564,false,Manual,4.0",
          GUID = "194C4414",
          LookAt = {
            [1] = "200021:n(200006)"
          },
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{"Think_End"},Duration{1}},\n",
          SpeakNpcId = 200021,
          Subtitle = "And come alone — don't bring anyone unrelated.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4414"
        },
        [10105501] = {
          ContentFR = "On dirait qu’il y a un chemin par là-bas ! Allons-y, cet endroit me donne la chair de poule...",
          DialogueId = 10105501,
          GUID = "194C4DC1",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105502,
          SpeakNpcId = 200002,
          Subtitle = "Anyone unrelated... Wait, he wasn't talking about me, was he?",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC1"
        },
        [10105502] = {
          ContentFR = "... Attends, quand il a dit « personne d’inutile », il ne parlait pas de moi, hein ?",
          DialogueId = 10105502,
          GUID = "194C4DC2",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Wait, when he said "anyone unrelated," he wasn't talking about me, was he?",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC2"
        },
        [10105601] = {
          ContentFR = "Ce petit passage n’a rien à voir avec la galerie qu’on a traversée tout à l’heure... on dirait plutôt que quelqu’un l’a creusé à la main.",
          DialogueId = 10105601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5E2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105602,
          SpeakNpcId = 100001,
          Subtitle = "This trail feels different from the one we passed through earlier, almost as if it's been hand-dug by someone.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E2A"
        },
        [10105602] = {
          ContentFR = "C’est vrai, tiens ! Y’a même plusieurs pioches qui traînent... On dirait bien que des aventuriers sont déjà passés par là !",
          DialogueId = 10105602,
          Duration = 3,
          GUID = "194C5E54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105603,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, there are even shovels lying around here... Looks like other adventurers have been here before us!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E54"
        },
        [10105603] = {
          ContentFR = "Hein, Psyche, pourquoi t’as l’air toute pâle ? Depuis tout à l’heure tu dis rien.",
          DialogueId = 10105603,
          Duration = 3,
          GUID = "194C5E7E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105604,
          SpeakNpcId = 200002,
          Subtitle = "Are you alright, Psyche? You look pale, and you've been so quiet since a while ago.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E7E"
        },
        [10105604] = {
          ContentFR = "Ah, m-moi ? J’ai l’air si mal que ça ?",
          DialogueId = 10105604,
          Duration = 3,
          GUID = "194C5EA8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10105605,
          SpeakNpcId = 200006,
          Subtitle = "Ah, have I?",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EA8"
        },
        [10105605] = {
          ContentFR = "Peut-être que... j’ai encore la chair de poule en repensant à ce monstre. Et si... si cette créature avait autrefois été...",
          DialogueId = 10105605,
          Duration = 3,
          GUID = "194C5ED2",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105606,
          SpeakNpcId = 200006,
          Subtitle = "I'm probably still a bit shaken from that monster we met back there.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5ED2"
        },
        [10105606] = {
          ContentFR = "Bah, ça sert à rien de flipper ! On est là avec toi !",
          DialogueId = 10105606,
          Duration = 3,
          GUID = "194C5EFC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105607,
          SpeakNpcId = 200002,
          Subtitle = "Relax! We're right here with you!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EFC"
        },
        [10105607] = {
          ContentFR = "Et puis, ce type a dit que mon petit larbin était {性别:un|une} "Daimon", super {性别:puissant|puissante}, pas vrai ? Même si dix autres Souillés déboulaient, ils ne feraient pas le poids face à {性别:lui|elle} !",
          DialogueId = 10105607,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F26",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105608,
          SpeakNpcId = 200002,
          Subtitle = "That Outsider said that my little minion is a strong "Daimon," right? So even if ten more Filthoids came at us, they'd be no match for {性别:him|her}.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F26"
        },
        [10105608] = {
          ContentFR = "Arrête un peu... je suis déjà à bout de forces, et Psyche faisait juste semblant d’être sûre d’elle.",
          DialogueId = 10105608,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F50",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105609,
          SpeakNpcId = 100001,
          Subtitle = "Rubbish. I'm nearly spent, and Psyche was just bluffing.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F50"
        },
        [10105609] = {
          ContentFR = "L’important c’est que vous n’ayez rien. Peut-être que j’aurais pas dû vous embarquer là-dedans...",
          DialogueId = 10105609,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F7A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105610,
          SpeakNpcId = 100001,
          Subtitle = "I'm just relieved you're both safe... Maybe I shouldn't have involved you two in such a dangerous event.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F7A"
        },
        [10105610] = {
          ContentFR = "Non ! Au contraire, cette "aventure"... je suis vraiment heureuse de l’avoir vécue.",
          DialogueId = 10105610,
          Duration = 3,
          GUID = "194C5FA4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105611,
          SpeakNpcId = 200006,
          Subtitle = "No, not at all! I'm really happy that I took part in such an adventure.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FA4"
        },
        [10105611] = {
          ContentFR = "Je n’aurais jamais imaginé quitter ma ville avec des {性别:amis|amies}, explorer l’inconnu, se mettre dans le pétrin, et affronter ensemble des ennemis terrifiants.",
          DialogueId = 10105611,
          Duration = 3,
          GUID = "194C5FCE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105612,
          SpeakNpcId = 200006,
          Subtitle = "I never thought I'd get out of town with friends, explore unknown places, get in trouble, and fight evil enemies together.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FCE"
        },
        [10105612] = {
          ContentFR = "... Maintenant que j’y repense, j’ai encore un peu la tête qui tourne, comme si j’avais fait un rêve en plein jour.",
          DialogueId = 10105612,
          Duration = 3,
          GUID = "194C5FF8",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105613,
          SpeakNpcId = 200006,
          Subtitle = "Now that I think about it, it all feels so unreal, like living a daydream.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FF8"
        },
        [10105613] = {
          ContentFR = "Tu vois ! Même Psyche est d’accord avec moi !",
          DialogueId = 10105613,
          Duration = 3,
          GUID = "194C6022",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10105614,
          SpeakNpcId = 200002,
          Subtitle = "See? Psyche agrees with me!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C6022"
        },
        [10105614] = {
          ContentFR = "...",
          DialogueId = 10105614,
          Duration = 3,
          GUID = "194C604C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/101056/194C604C"
        },
        [10105701] = {
          ContentFR = "Hé, là-bas... c’est pas Henrik ? Qu’est-ce qu’il fiche ici ?",
          DialogueId = 10105701,
          Duration = 3,
          GUID = "194C6E92",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Isn't that... Henrik over there? What's he doing here?",
          VoiceName = "voice/$Locale$/story/1002/101057/194C6E92"
        },
        [10105801] = {
