          },
          VoiceName = "voice/$Locale$/story/1002/101058/194C7F24"
        },
        [10105803] = {
          ContentFR = "Tu aurais dû rester à la Maison d’Hypnos, pas suivre {性别:ce gamin sorti|cette gamine sortie} de nulle part. Tu ignores tout {性别:de lui|d’elle}, et {性别:il|elle} n’en sait pas plus sur toi.",
          DialogueId = 10105803,
          ExStoryInfo = "Player",
          GUID = "194C7F4E",
          NextDialogue = 10105804,
          Scripts = "PARA{\nSEQ{\nSetLocation{ActorId{100001},TargetPoint{\"P10105801Nvzhu2\"},Visibility{\"Hide\"}},\nPlayAnimation{_delay{2},ActorId{200005},AnimationId{\"SpecialThink_End\"},Duration{4.5}},\nPlayAnimation{ActorId{200005},AnimationId{\"Disagree\"},Duration{4.5}},\nPlayAnimation{ActorId{200005},AnimationId{\"Explain01_Start\"},Duration{1}}\n},\nSEQ{\nCameraMoveTo{_delay{5.01},TargetPosition{\"-167.25,28.234863,129.733398,0.000074,6.0,-18.000011,35.0,195.174042,false,Manual,4.235867\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-167.25,28.234863,129.733398,0.000074,6.0,-18.000011,35.0,195.174042,false,Manual,4.235867\"},duration{8}}\n}\n}",
          SpeakNpcId = 200005,
          Subtitle = "You should've stayed at the Hypnos' House instead of fooling around with this sketchy brat.\nYou don't know {性别:his|her} backstory, and {性别:he|she} doesn't really know you that well.",
          TalkActionId = {
