          LookAt = {
            [1] = "200005:n(100001)"
          },
          NextOptions = {
            [1] = 101058131,
            [2] = 101058132
          },
          SpeakNpcId = 200005,
          Subtitle = "Tend your own garden and don't drag irrelevant people into your business. It's better for everyone.",
          VoiceName = "voice/$Locale$/story/1002/101058/194C80C8"
        },
        [10105814] = {
          Camera = "-248.442383,-210.168945,153.489746,0.000127,-3.200374,44.998043,35.000008,345.865082,false,Manual,5.41403",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Elle n’est pas votre fille. Et même si elle l’était, vous n’avez pas à lui refuser une si petite liberté. Vous savez à quel point ça l’a rendue heureuse de sortir un peu ?",
          DialogueId = 10105814,
          ExStoryInfo = "Player",
          FinalCamera = "-248.442383,-210.168945,153.489746,0.000127,-3.000386,39.998112,35.000008,345.865082,false,Manual,5.41403",
          GUID = "194C80F2",
          NextDialogue = 10105816,
          Scripts = "SEQ{\nMoveTo{ActorId{100001},TargetPoint{\"P10105801Nvzhu\"},MoveSpeed{90},Visibility{\"Show\"}},\nPlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{2.5}},\nPlayAnimation{ActorId{100001},AnimationId{\"Angry01_End\"},Duration{1}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "She is not your daughter. Even if she were, you shouldn't deprive her of such simple freedoms. Do you know how happy she was during our little trip?",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101058/194C80F2"
        },
        [10105815] = {
