          CameraBlendCurve = "easeInQuad",
          ContentFR = "On peut parler d’autre chose ? Par exemple... est-ce que vous êtes aussi "aimable" avec tout le monde ? Pas étonnant que votre fichu manoir ne trouve jamais preneur.",
          DialogueId = 10105815,
          ExStoryInfo = "Player",
          FinalCamera = "-248.442383,-210.168945,153.489746,0.000127,-3.000386,39.998112,35.000008,345.865082,false,Manual,5.41403",
          GUID = "194C811C",
          NextDialogue = 10105816,
          Scripts = "SEQ{\nMoveTo{ActorId{100001},TargetPoint{\"P10105801Nvzhu\"},MoveSpeed{90},Visibility{\"Show\"}},\nPlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{2.5}},\nPlayAnimation{ActorId{100001},AnimationId{\"Angry01_End\"},Duration{1}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Let's talk about something else then. For example, are you this polite and friendly to everyone? No wonder that house of yours never sells.",
          TalkActionId = {
            [1] = "200005:Talk03_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101058/194C811C"
        },
