          Scripts = "SEQ{\nPlayAnimation{ActorId{200005},AnimationId{\"Confident_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200005,
          Subtitle = "That's my problem. For you, the thing to worry about should be where to crash after tonight.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101058/194C8146"
        },
