          Duration = 3,
          GUID = "194C8FE0",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105905,
          SpeakNpcId = 200002,
          Subtitle = "You two are gonna have that secret little talk without me, huh? That Outsider is such a pest.",
          VoiceName = "voice/$Locale$/story/1002/101059/194C8FE0"
        },
        [10105905] = {
          ContentFR = "Pff, comme si ça m’intéressait ! Vas-y, file. Moi, je vais traîner du côté des Asphodèles.",
