          GUID = "194CA072",
          NextDialogue = 10106006,
          Scripts = "PlayAnimation{_delay{2},ActorId{200020},AnimationId{"Explain02_Start"},Duration{1}}",
          SpeakNpcId = 200020,
          SpeakNpcName = "UI_Npc_Name_Woman_6",
          Subtitle = "Was it in the dense woods where snow wolves prowl, or the swamp witch's tower?",
          TalkActionId = {
