          ContentFR = "Nulle part. Aujourd’hui, c’est l’anniversaire de la petite Fina. J’ai passé la journée à Givrelac.",
          DialogueId = 10106006,
          GUID = "194CA09C",
          NextDialogue = 10106007,
          Scripts = "PlayAnimation{_delay{3},ActorId{200021},AnimationId{"Explain01_Start"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "I didn't go anywhere. Today is Miss Fina's birthday, so I stayed in Icelake.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101060/194CA09C"
        },
        [10106007] = {
          Camera = "408.430054,-53.302734,170.0,0.000427,-26.592985,95.013817,35.0,98.302994,false,Manual,7.666935",
          ContentFR = "Tu dis toujours ça... mais il y a sans cesse de nouvelles cicatrices sur ton bras... kof, kof...",
          DialogueId = 10106007,
          FacialId = {
            [1] = "200020:Sad02"
          },
          GUID = "194CA0C6",
          NextDialogue = 10106008,
          Scripts = "PARA{\nLookAt{_delay{5.5},LookAtDescription{\"200020:p(P10106007)\"}},\nCameraMoveTo{_delay{4},TargetPosition{\"266.514587,-272.453125,133.09375,0.000453,-2.99999,60.838596,50.0,329.927887,false,Manual,4.0\"},duration{0}},\nCameraMoveTo{_delay{4.1},TargetPosition{\"246.190765,-308.873047,135.273438,0.000453,-2.99999,60.838596,50.0,329.927887,false,Manual,4.0\"},duration{2}},\nPlayAnimation{_delay{7},ActorId{200020},AnimationId{\"Explain02_Start\"},Duration{1.5}}\n}",
          SpeakNpcId = 200020,
