          GUID = "194CA216",
          LookAt = {
            [1] = "200021:n(200020)"
          },
          NextDialogue = 10106016,
          Scripts = "SEQ{\nCameraMoveTo{_delay{8.01},TargetPosition{\"355.009827,73.544922,110.5,5.000736,22.005701,-41.36306,27.0,74.508743,false,Manual,4.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"379.515869,98.34375,118.824219,5.001714,5.604962,-83.560081,27.0,240.362061,false,Manual,4.0\"},duration{15}}\n}",
          SpeakNpcId = 200020,
          Subtitle = "The nightingale yearned for the sky, but it was ever so dark. 'If only I could see the stars once,'\nshe wished silently, 'even but for a fleeting moment.'",
          TalkActionId = {
            [1] = "200020:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101060/194CA216"
        },
        [10106016] = {
          ContentFR = "À Givrelac, les nuits sont toujours couvertes... Alors tu m’as offert un ciel étoilé.",
