          FacialId = {
            [1] = "200021:Smile01"
          },
          GUID = "194CA240",
          NextDialogue = 10106017,
          SpeakNpcId = 200020,
          Subtitle = "Nights in Icelake are always so misty, so you... conjured up a starry sky.",
