          SpeakNpcId = 200021,
          Subtitle = "Are you alright? I'll get you some warm water.",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "200021:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101061/194CB12E"
        },
        [10106110] = {
          Camera = "590.448242,-478.587891,143.261719,0.000085,-4.187855,118.580727,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, ça va ! C’est juste que... je suis si contente que l’Étranger ait amené {性别:un ami|une amie}. Tu veux te joindre à notre goûter enchanté ? Il y a un délicieux gâteau tout sucré.",
          DialogueId = 10106110,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200020:Happy01"
          },
          GUID = "194CB158",
          LookAt = {
            [1] = "200020:n(200021)"
          },
          NextDialogue = 10106111,
          Scripts = "PARA{PlayAnimation{_delay{1.5},ActorId{200020},AnimationId{\"DisagreeHead\"},Duration{0.1}},\nLookAt{_delay{3.5},LookAtDescription{\"200020:n(100001)\"}},\nPlayAnimation{_delay{6.5},ActorId{200020},AnimationId{\"Talk02_Start\"},Duration{0.1}},\nPlayFacial{_delay{5.5},ActorId{200020},FacialId{\"Happy02\"}},\nCameraMoveTo{_delay{10.01},TargetPosition{\"564.798767,-304.822266,157.535156,0.000071,-6.187953,-116.819534,45.0,100000.0,false,DoNotOverride,4.42362\"},duration{0}},\nLookAt{_delay{10.5},LookAtDescription{\"100001:n(200021)\"}},\nPlayFacial{_delay{10.5},ActorId{100001},FacialId{\"Unhappy01\"}}\n}",
          SpeakNpcId = 200020,
          Subtitle = "It's okay, I'm fine! Just happy to have a friend of Outsider's over. Would you like to join our tea party? I'll treat you to cake.",
          TalkActionId = {
            [1] = "200020:Sigh_End",
            [2] = "200021:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101061/194CB158"
        },
        [10106111] = {
          Camera = "-41.242096,295.529297,143.277344,0.000096,-2.788821,-44.214836,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un... goûter ?",
          DialogueId = 10106111,
          ExStoryInfo = "Player",
          FinalCamera = "-36.621948,300.277344,143.277344,0.000096,-2.788821,-44.212944,45.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194CB182",
          LookAt = {
            [1] = "100001:p(P101060Cake)",
            [2] = "200020:n(100001)"
          },
          NextDialogue = 10106112,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{"Explain02_Start"},Duration{0.1}}",
          SpeakNpcId = 100001,
          Subtitle = "A tea party...?",
          TalkActionId = {
            [1] = "200020:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101061/194CB182"
        },
        [10106112] = {
          Camera = "476.360107,-433.447266,145.050781,0.000096,-1.787993,57.580418,20.000008,177.3125,false,Manual,4.42362",
          ContentFR = "Hum hum... Juste de l’eau et un gâteau. Mais laisse-la faire, et joue le jeu.",
          DialogueId = 10106112,
          FinalCamera = "471.813538,-440.609375,145.316406,0.000096,-1.787993,57.580303,20.000011,186.250793,false,Manual,4.42362",
          GUID = "194CB1AC",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          SpeakNpcId = 200021,
          Subtitle = "Ahem, it's actually water. Just play along, don't get hung up on the tiny details.",
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101061/194CB1AC"
        },
        [10106201] = {
          Camera = "206.667267,-212.755859,109.257812,0.000036,-8.399964,64.187279,50.000011,169.891953,false,Manual,8.124071",
          ContentFR = "...",
          DialogueId = 10106201,
          Duration = 6,
          ExStoryInfo = "Player",
          FacialId = {
