        },
        [10106202] = {
          Camera = "-6.599731,-145.632812,140.769531,0.000156,-3.591819,17.001183,30.0,555.360596,false,DoNotOverride,4.01182",
          ContentFR = "{性别:Monsieur|Mademoiselle}, ça ne va pas ?",
          DialogueId = 10106202,
          ExStoryInfo = "Player",
          FinalCamera = "-14.872528,-148.162109,141.300781,0.000156,-3.591819,17.001348,30.000002,555.360596,false,DoNotOverride,4.01182",
          GUID = "194CC0C4",
          LookAt = {
            [1] = "100001:n(200020)"
          },
          NextDialogue = 10106203,
          SpeakNpcId = 200020,
          Subtitle = "What's wrong, {性别:sir|miss}?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC0C4"
        },
        [10106203] = {
          Camera = "275.194794,306.837891,122.601562,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447",
          ContentFR = "Non... Ce gâteau est si sucré... il m’a rappelé quelqu’un. Ma famille. Elle mettait toujours... beaucoup, beaucoup de sucre dans ses plats.",
          DialogueId = 10106203,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "273.907379,326.357422,122.730469,0.000156,-0.389526,-86.226807,50.000008,393.914001,false,Manual,3.873447",
          GUID = "194CC0EE",
          NextDialogue = 10106204,
          Scripts = "SEQ{\nLookAt{_delay{2.5},LookAtDescription{\"100001:n(200020)\"}},\nPlayFacial{ActorId{100001},FacialId{\"Sad01\"}},\nLookAt{_delay{3.5},LookAtDescription{\"100001:p(P101060Cake)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Nothing. It's just that, the cake is quite sweet, which reminds me of my family... She used to season food with lots of sugar.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC0EE"
        },
        [10106204] = {
          ContentFR = "Sur notre petite île, nous avions du poisson, du sel... mais le sucre coûtait une fortune. Enfants, nous n’en goûtions jamais.",
          DialogueId = 10106204,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194CC118",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106204.T_Story_Recall_10106204'",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10106205,
          SpeakNpcId = 100001,
          Subtitle = "The small island we grew up on had plenty of fish and salt, but sugar was a rarity. So, when we were little,\nwe never really got to have any.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC118"
        },
        [10106205] = {
          Camera = "225.539108,-21.537109,188.570312,0.000213,-25.98712,-68.410789,50.0,111.523781,false,Manual,7.19876",
          ContentFR = "C’était une fille un peu plus âgée que moi. Toute jeune, elle aidait déjà le pêcheur du voisinage.",
          DialogueId = 10106205,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194CC142",
          NextDialogue = 10106206,
          Scripts = "PARA{\nLookAt{_delay{1.5},LookAtDescription{\"100001:p(P101062)\"}},\nSEQ{\nCameraMoveTo{_delay{0.8},TargetPosition{\"225.539108,-21.537109,188.570312,0.000213,-25.98712,-68.410789,50.0,111.523781,false,Manual,7.19876\"},duration{0}},\nCameraMoveTo{TargetPosition{\"225.539108,-21.537109,190.847656,0.000213,-25.98712,-68.410812,50.0,111.523781,false,Manual,7.19876\"},duration{8}}\n}\n}",
          SpeakNpcId = 100001,
          Subtitle = "She's only a few years older than me, but from a young age, she began working as a helper for the neighbouring fisherman.",
          VoiceName = "voice/$Locale$/story/1002/101062/194CC142"
        },
        [10106206] = {
          Camera = "-36.164703,179.021484,97.113281,0.000154,3.212634,-35.412941,35.000008,159.590256,false,DoNotOverride,19.0",
          ContentFR = "Un jour, ce pêcheur ramena des vivres de l’Empire, dont deux pots de sucre. Elle sacrifia la moitié d’un mois de salaire... pour en acheter un.",
          DialogueId = 10106206,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-41.269623,171.851562,97.113281,0.000154,3.212634,-35.412941,35.000008,159.590256,false,DoNotOverride,19.0",
          GUID = "194CC16C",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10106207,
          Scripts = "PARA{\nLookAt{_delay{0.1},LookAtDescription{\"100001:n(200021)\"}},\nLookAt{_delay{1.1},LookAtDescription{\"100001:n(200020)\"}},\nPlayAnimation{_delay{5.1},ActorId{100001},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{_delay{5.5},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "One time, that fisherman somehow got his hands on some imperial supplies, including two jars of sugar,\nand she traded half a month's wages for one small jar.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC16C"
        },
        [10106207] = {
          Camera = "275.194794,306.837891,122.601562,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447",
          ContentFR = "C’était la première fois qu’elle touchait à du sucre. Elle ne savait pas comment l’utiliser. Elle savait seulement que c’était une merveille. Alors... elle le versa tout entier dans une soupe de poisson.",
          DialogueId = 10106207,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          FinalCamera = "284.692383,307.464844,132.414062,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447",
          GUID = "194CC196",
          LookAt = {
            [1] = "100001:n(200020)"
          },
          NextDialogue = 10106208,
          Scripts = "PARA{\nPlayAnimation{_delay{1.1},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayAnimation{_delay{5.1},ActorId{100001},AnimationId{\"Talk01_End\"},Duration{1}},\nPlayAnimation{_delay{9.1},ActorId{100001},AnimationId{\"ScratchHead_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "It was the first time she got hold of any sugar, and she didn't know how to use it.\nSimply knowing that it was something valuable and delicious, she poured it all into the fish stew.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC196"
        },
        [10106208] = {
          Camera = "382.73764,-248.964844,152.820312,0.0,0.0,-179.999969,40.0,393.914001,false,Manual,3.873447",
          ContentFR = "Plus tard, quand nous avons grandi et que le sucre est devenu moins rare, elle continuait à en mettre des montagnes... comme par habitude.",
          DialogueId = 10106208,
          ExStoryInfo = "Player",
          FinalCamera = "328.098663,-248.964844,152.820312,0.0,0.0,-179.999969,40.0,393.914001,false,Manual,3.873447",
          GUID = "194CC1C0",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10106209,
          Scripts = "LookAt{_delay{2},LookAtDescription{"100001:n(100001)"}}",
          SpeakNpcId = 100001,
          Subtitle = "By the time we grew up and started earning more, sugar wasn't such a luxury anymore. But whenever she cooked,\nshe'd still add a lot of sugar out of habit.",
          TalkActionId = {
            [1] = "200021:Confident_End",
            [2] = "100001:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC1C0"
        },
        [10106209] = {
          Camera = "96.518188,-136.830078,134.59375,0.000123,1.799413,15.609182,35.000008,213.622009,false,Manual,7.38829",
          ContentFR = "Mais non ! J’imagine déjà l’odeur écœurante... Elle devrait présenter ses excuses. À toi... et surtout au sucre, et au poisson.",
          DialogueId = 10106209,
          FacialId = {
            [1] = "100001:None",
            [2] = "200021:Shock02"
          },
          GUID = "194CC1EA",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10106210,
          Scripts = "PARA{\nPlayAnimation{_delay{2.1},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{1}},\nPlayAnimation{_delay{3.1},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Goodness, that sounds horrible... I can almost smell that fishy, sickly-sweet odour. She owes you an apology; or at the very least, she owes the sugar and the fish an apology.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC1EA"
        },
        [10106210] = {
          Camera = "96.518188,-136.830078,134.59375,0.000123,1.799413,15.609182,35.000008,213.622009,false,Manual,7.38829",
          ContentFR = "Non, l’Étranger. Tu n’as pas compris l’histoire.",
          DialogueId = 10106210,
          FacialId = {
            [1] = "200021:None",
            [2] = "200020:Confident01"
          },
          FinalCamera = "90.803986,-143.320312,134.382812,0.000123,0.599335,20.609505,35.000008,213.622009,false,Manual,7.38829",
          GUID = "194CC214",
          LookAt = {
            [1] = "200020:n(200021)"
          },
          NextDialogue = 10106211,
          Scripts = "LookAt{_delay{0.5},LookAtDescription{"200021:n(200020)"}}",
          SpeakNpcId = 200020,
          Subtitle = "No, Outsider, you've missed the point of the story.",
          TalkActionId = {
            [1] = "200020:DisagreeHead",
            [2] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC214"
        },
        [10106211] = {
          Camera = "247.410675,-57.9375,168.519531,0.000134,-20.200529,35.800228,50.000008,111.523781,false,Manual,7.19876",
          ContentFR = "Cette demoiselle qui mettait toujours trop de sucre... c’était une magicienne, elle aussi.\nCar aux yeux de {nickname}, tout ce qui venait d’elle... était précieux. Même les plats trop sucrés pour être avalés.",
          DialogueId = 10106211,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200020:Happy02"
          },
          GUID = "194CC23E",
          LookAt = {
            [1] = "200020:n(100001)",
            [2] = "100001:n(200020)"
          },
          NextDialogue = 10106212,
          Scripts = "PARA{\nCameraMoveTo{_delay{10},TargetPosition{\"225.539108,-21.537109,188.570312,0.000213,-25.98712,-68.410789,50.0,111.523781,false,Manual,7.19876\"},duration{0}},\nPlayFacial{_delay{10},ActorId{100001},FacialId{\"Ahaha02\"}}\n}",
          SpeakNpcId = 200020,
          Subtitle = "I believe that lady who always used a lot of sugar when cooking was also a great magician. In our guest's eyes,\neverything related to her was good, even if the food was unbearably sweet.",
          TalkActionId = {
            [1] = "200020:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC23E"
        },
        [10106212] = {
          Camera = "90.803986,-143.320312,134.382812,0.000123,0.599335,20.609505,35.000008,213.622009,false,Manual,7.38829",
          ContentFR = "Bon, d’accord... Fina a raison. Mais alors, où est-elle maintenant ? Tu devrais lui faire goûter un vrai gâteau, pour lui montrer ce qu’est une douceur digne de ce nom.",
          DialogueId = 10106212,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194CC268",
          NextDialogue = 10106213,
          Scripts = "PARA{\nLookAt{_delay{2.5},LookAtDescription{\"200021:n(100001)\"}},\nLookAt{_delay{3.5},LookAtDescription{\"200020:n(100001)\"}},\nLookAt{_delay{3.5},LookAtDescription{\"100001:n(200021)\"}}\n}\n",
          SpeakNpcId = 200021,
          Subtitle = "Okay, whatever Fina says. So where is that girl now? Perhaps you can bring her some cake, let her know what normal sweets taste like.",
          TalkActionId = {
            [1] = "200020:Explain02_End",
            [2] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC268"
        },
        [10106213] = {
          Camera = "325.076691,-13.257812,187.945312,0.000222,-23.38699,-116.208672,50.0,136.090439,false,Manual,7.19876",
          ContentFR = "... Nous avons été séparés. Hier... ou peut-être bien plus tôt. Je ne sais plus.",
          DialogueId = 10106213,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200020:Shock02"
          },
          FinalCamera = "332.233704,1.279297,194.9375,0.000222,-23.38699,-116.208672,50.0,136.090439,false,Manual,7.19876",
          GUID = "194CC292",
          LookAt = {
            [1] = "200020:n(100001)",
            [2] = "200021:n(100001)"
          },
          NextDialogue = 10106214,
          Scripts = "PARA{\nSEQ{\nLookAt{_delay{2.5},LookAtDescription{\"100001:n(100001)\"},Duration{2}},\nPlayAnimation{_delay{2.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{0.1}}\n},\nCameraMoveTo{_delay{9},TargetPosition{\"247.410675,-57.9375,168.519531,0.000134,-20.200529,35.800228,50.000008,111.523781,false,Manual,7.19876\"},duration{0}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "We got separated and lost touch yesterday... or maybe longer ago. I'm not sure.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC292"
        },
        [10106214] = {
          Camera = "-172.923157,500.876953,222.921875,0.000144,-7.79205,-46.00008,30.0,555.360596,false,Manual,2.016998",
          ContentFR = "...",
          DialogueId = 10106214,
          Duration = 2,
          FacialId = {
            [1] = "200021:Sad01"
          },
          FinalCamera = "-181.140259,509.382812,224.539062,0.000144,-7.79205,-46.00008,30.0,555.360596,false,Manual,2.016998",
          GUID = "194CC2BC",
          NextDialogue = 10106215,
          SpeakNpcId = 200021,
          Subtitle = "...",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC2BC"
        },
        [10106215] = {
          Camera = "284.721039,-61.648438,146.964844,0.00016,-12.991326,53.627674,45.0,103.803047,false,Manual,22.0",
          ContentFR = "Alors tu dois la retrouver ! Parce que la famille, c’est comme les fleurs et les arbres, la neige et le vent, quoi qu’il arrive, ils doivent rester ensemble. Tu dois la retrouver !",
          DialogueId = 10106215,
          FacialId = {
            [1] = "200020:Disappoint01"
          },
          GUID = "194CC2E6",
          LookAt = {
            [1] = "100001:n(200020)"
          },
          NextDialogue = 10106216,
          Scripts = "SEQ{\nCameraMoveTo{_delay{4},TargetPosition{\"25.241394,353.103516,128.082031,0.000249,-0.186608,-55.60635,50.0,304.058929,false,DoNotOverride,7.19876\"},duration{0}},\nCameraMoveTo{TargetPosition{\"197.603165,430.265625,128.082031,0.000251,-1.186663,-77.204803,50.000008,304.058929,false,DoNotOverride,7.19876\"},duration{15}}\n}",
          SpeakNpcId = 200020,
          Subtitle = "Then you must find her...! Because family is like flowers and trees, snow and wind — they should be together no matter what.\nYou have to find her.",
          TalkActionId = {
            [1] = "200020:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC2E6"
        },
        [10106216] = {
          Camera = "248.2005,27.082031,94.667969,0.000281,16.61274,-81.408127,50.0,156.400558,false,Manual,7.19876",
          ContentFR = "Oui. Je la retrouverai. Je le jure.",
          DialogueId = 10106216,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "194CC310",
          NextDialogue = 10106217,
          SpeakNpcId = 100001,
          Subtitle = "Yeah, I will. I WILL find her.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC310"
        },
        [10106217] = {
          ContentFR = "Alors, Étranger... j’ai besoin d’argent. Une somme pour me loger et glaner des informations, et une autre, de côté, au cas où je devrais partir sur-le-champ retrouver ma famille.",
          DialogueId = 10106217,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194CC33A",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10106218,
          Scripts = "SEQ{\nLookAt{LookAtDescription{\"100001:n(200021)\"}},\nTurnTo{TurnToDescription{\"100001:n(200021)\"}},\nPlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "So, Outsider, I need money — for accommodation, information gathering, and some extra set apart\nin case I need to set off right away to find my family.",
          TalkActionId = {
            [1] = "200020:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC33A"
        },
        [10106218] = {
          Camera = "228.775543,-141.707031,208.621094,0.000132,-21.591455,46.226685,45.0,103.803047,false,DoNotOverride,22.0",
          ContentFR = "... Fina, il est temps de te reposer. {nickname} et moi devons discuter d’affaires plus sérieuses, des histoires de Chasseurs de Phoxène.",
          DialogueId = 10106218,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CC364",
          LookAt = {
            [1] = "200021:n(200020)",
            [2] = "100001:n(200020)"
          },
          NextDialogue = 10106219,
          Scripts = "PARA{\nLookAt{_delay{2.5},LookAtDescription{\"200021:n(200020)\"}},\nLookAt{_delay{3},LookAtDescription{\"200020:n(200021)\"}}\n}\n",
          SpeakNpcId = 200021,
          Subtitle = "...Time for bed, Fina.  and I have other matters to discuss — Phoxhunter stuff.",
          VoiceName = "voice/$Locale$/story/1002/101062/194CC364"
        },
        [10106219] = {
          Camera = "133.667862,436.431641,156.152344,0.000004,-4.200197,-71.19426,40.0,311.105316,false,DoNotOverride,1.670611",
          ContentFR = "D’accord... Bonne nuit à vous deux.",
          DialogueId = 10106219,
          FacialId = {
            [1] = "200020:Happy02"
          },
          FinalCamera = "128.757187,450.847656,157.261719,0.000005,-4.200197,-71.194244,40.000011,311.105316,false,DoNotOverride,1.670611",
          GUID = "194CC38E",
          LookAt = {
            [1] = "200021:n(200020)",
            [2] = "200020:n(200021)"
          },
          Scripts = "LookAt{_delay{2},LookAtDescription{"200020:n(100001)"}}",
          SpeakNpcId = 200020,
          Subtitle = "Okay, I'm going to bed now.",
          TalkActionId = {
            [1] = "200020:AgreeHead"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC38E"
        },
        [10106301] = {
          Camera = "-6.289551,163.633789,182.636719,0.000162,-9.200067,-82.733803,30.0,315.887299,false,Manual,2.2",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Passons aux choses sérieuses. Je parle de ce qui s’est passé aujourd’hui, dans la fosse.",
          DialogueId = 10106301,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          FinalCamera = "1.409424,177.989258,186.113281,0.000151,-7.200044,-80.799271,30.0,115.9599,false,Manual,2.4",
          GUID = "194CD102",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10106302,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 201009,
            [3] = 201010,
            [4] = 301004,
            [5] = 201007,
            [6] = 405002
          },
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt01/0020_story_sanatorium"}}",
          SpeakNpcId = 200021,
          Subtitle = "Time for a serious talk — about what happened at the pit earlier. I get where you're coming from, but I hope you'll hear me out too.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD102"
        },
        [10106302] = {
          Camera = "-134.704102,-202.952148,138.852539,0.000154,3.5,48.999954,35.0,313.251678,false,Manual,4.143779",
          ContentFR = "Désolé pour la mise en scène. J’ai dû te subtiliser l’Éclat stellaire afin d’écarter les curieux et pouvoir discuter seul à seul avec toi.",
          DialogueId = 10106302,
          FacialId = {
            [1] = "200021:Confident01",
            [2] = "100001:Think01"
          },
          GUID = "194CD103",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextOptions = {
            [1] = 101063031,
            [2] = 101063032
          },
          Scripts = "PARA{\nTurnTo{_delay{1},TurnToDescription{\"200021:p(180)\"}},\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{2}},\nCameraMoveTo{_delay{8},TargetPosition{\"-38.290527,76.382812,152.887695,0.00016,-1.800294,-79.190605,35.0,168.06105,false,Manual,3.5\"},duration{0}},\nPlayAnimation{ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "I'll get straight to the point: I don't trust Henrik Ethelred. Not one bit.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD103"
        },
        [10106304] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376",
          ContentFR = "Snow ? Non... Ce Petit Champi sait faire la part des choses, ça ne me dérange pas. Ce qui m’inquiète, c’est la fille en vert.",
          DialogueId = 10106304,
          FacialId = {
            [1] = "200021:Smile01",
            [2] = "100001:None"
          },
          GUID = "194CD104",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10106306,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{1}},\nPlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "And even if he's got the cash, his reasons for seeking the Crystallo of Stella are quite fishy. I suspect he's up to some shady business.",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD104"
        },
        [10106305] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376",
          ContentFR = "Si tu parles de la fille en vert, alors oui.",
          DialogueId = 10106305,
          FacialId = {
            [1] = "200021:Doubt01",
            [2] = "100001:None"
          },
          GUID = "194CD105",
          NextDialogue = 10106306,
          SpeakNpcId = 200021,
          Subtitle = "Do you know what Crystallo of Stella is? Nice-looking rocks that used to be popular for their looks — but that's not the whole story.\nIn some countries, they're used for... medicinal purposes.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD105"
        },
        [10106306] = {
          ContentFR = "Je l’ai déjà vue entrer et sortir de la Maison d’Hypnos. Je ne sais pas si elle est seulement une pensionnaire... ou l’assistante d’Henrik Ethelred.",
          DialogueId = 10106306,
          GUID = "194CD106",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106306.T_Story_Recall_10106306'",
          NextDialogue = 10106307,
          SpeakNpcId = 200021,
          Subtitle = "I've seen her going in and out of Hypnos' House. I don't know if she's just a regular lodger or some kind of assistant to Henrik Ethelred.",
          TalkActionId = {
            [1] = "200021:Think_Start",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD106"
        },
        [10106307] = {
          Camera = "-134.704102,-202.952148,138.852539,0.000154,3.5,48.999954,35.0,313.47171,false,Manual,2.264544",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Je vais être clair, Henrik n’est pas net. Je soupçonne des affaires louches.",
          DialogueId = 10106307,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "-108.404053,-223.467773,138.852539,0.000162,3.899915,58.900612,35.000011,319.900421,false,Manual,2.264544",
          GUID = "194CD12C",
          NextDialogue = 10106308,
          SpeakNpcId = 200021,
          Subtitle = "I'll cut to the chase: I don't trust Henrik Ethelred — I suspect he's up to something shady.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD12C"
        },
        [10106308] = {
          Camera = "15.576416,24.124023,175.081543,-0.0,-10.199944,-103.000977,35.000008,120.127426,false,Manual,3.0",
          ContentFR = "Des... affaires louches ?",
          DialogueId = 10106308,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "194CD12D",
          NextDialogue = 10106309,
          SpeakNpcId = 100001,
          Subtitle = "Something shady... like what?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD12D"
        },
        [10106309] = {
          Camera = "-129.019531,-207.28418,135.132324,0.000153,4.599757,50.60236,35.0,316.170074,false,Manual,2.264544",
          ContentFR = "Tu sais ce qu’il cherche, ces Éclats stellaires ? Des pierres jadis prisées pour leur beauté. Mais ce n’est qu’une façade. Dans certains pays, elles servaient de... médecine.",
          DialogueId = 10106309,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "194CD1AA",
          NextDialogue = 10106310,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{2}},\nPlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Explain01_End\"},Duration{1}},\nPlayAnimation{_delay{4.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}\n},\nSEQ{\nCameraMoveTo{_delay{8.01},TargetPosition{\"-22.538086,-15.713867,168.216797,0.000161,1.399533,51.603157,35.000008,99.769196,false,Manual,2.264544\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-15.511475,-6.851562,168.493164,0.000161,1.399533,51.603806,35.000008,84.787651,false,Manual,2.264544\"},duration{5}}\n}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Do you know anything about the Crystallo of Stella — the stuff he's after? They're beautiful rocks that were popular for their looks, but that's not the whole story. In some countries, they're used for... medicinal purposes.",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1AA"
        },
        [10106310] = {
          Camera = "-801.484619,-220.195312,860.855957,0.000049,-21.199219,35.871891,30.000008,2029.508545,false,Manual,1.2",
          ContentFR = "Il y a eu un cas grave de négligence médicale impliquant l’Éclat stellaire dans la province de Flagson. La moitié de la ville a sombré dans le chaos. C’est à ce moment-là que le commerce des Éclats stellaires a été interdit.",
          DialogueId = 10106310,
          FinalCamera = "-801.484619,-220.195312,902.421387,0.000049,-21.199219,35.871891,30.000008,2029.508545,false,Manual,1.2",
          GUID = "194CD1D4",
          NextOptions = {
            [1] = 10106311
          },
          RelatedWikiId = {
            [1] = 408005,
            [2] = 301004
          },
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Talk03_End\"},Duration{2}},\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{2}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "I've heard about those staying there — all young, not even twenty. The weird part? You see them go in, but never out.\nNo one knows where they end up.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1D4"
        },
        [10106311] = {
          ContentFR = "Donc il enfreint l’interdiction. J’en avais entendu parler.",
          DialogueId = 10106311,
          GUID = "10106311.0",
          NextDialogue = 10106312,
          Subtitle = "He's violating the ban. I've heard about it."
        },
        [10106312] = {
          Camera = "0.102539,187.96582,195.69873,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2",
          ContentFR = "Et encore... ça ne serait qu’un détail. À Givrelac, rares sont ceux qui ont vraiment les mains propres. Ce qui me trouble, ce sont les rumeurs autour de la Maison d’Hypnos.",
          DialogueId = 10106312,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "-0.895264,195.582031,197.388184,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2",
          GUID = "194CD1FE",
          NextDialogue = 10106313,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "That's not the half of it. How many folks on the streets of Icelake can truly claim clean hands? What really gets me are the rumours about the Hypnos' House.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1FE"
        },
        [10106313] = {
          Camera = "-2526.490234,772.758789,582.1875,0.000011,-9.199978,-15.202279,45.000023,2420.254639,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Les habitants disent aussi qu’Henrik et ses pensionnaires se comportent bizarrement, qu’ils évitent tout contact avec l’extérieur. Officiellement, c’est une auberge... mais en réalité, tous ceux qui y logent sont <H>choisis par Henrik lui-même</>.",
          DialogueId = 10106313,
          FinalCamera = "-2536.047363,737.591797,582.1875,0.000011,-9.199978,-15.202335,45.000023,2420.254639,false,Manual,1.2",
          GUID = "194CD228",
          NextDialogue = 10106314,
          SpeakNpcId = 200021,
          Subtitle = "People in the neighbourhood say that Henrik and his lodgers are a weird bunch. They keep to themselves, and though they call it an inn, Henrik's the one picking who stays.",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD228"
        },
        [10106314] = {
          Camera = "-118.642822,-24.229492,136.930176,0.000165,10.799492,27.794773,35.0,170.938126,false,Manual,1.623207",
          ContentFR = "Certains ont réussi à jeter un œil à l’intérieur : que des jeunes de moins de vingt ans. Plus étrange encore... on les voit entrer, jamais ressortir. Nul ne sait ce qu’ils deviennent.",
          DialogueId = 10106314,
          FinalCamera = "-87.214844,-7.525391,144.353027,0.000166,11.999521,27.99498,35.0,150.986908,false,Manual,1.623207",
          GUID = "194CD252",
          NextDialogue = 10106315,
          Scripts = "SEQ{\nPlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}},\nPlayAnimation{_delay{2.5},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Some have peeked inside — the lodgers there are all young people under twenty. Stranger still, you see them go in but never out. No one knows where those young lodgers end up.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD252"
        },
        [10106315] = {
          Camera = "1.409424,177.989258,193.487305,0.000134,-12.400058,-82.534454,30.000002,263.612305,false,Manual,2.2",
          ContentFR = "J’ai entendu, moi aussi, des rumeurs de "manoir hanté"... mais dit comme ça, c’est encore plus... inquiétant.",
          DialogueId = 10106315,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194CD27C",
          NextDialogue = 10106316,
          SpeakNpcId = 100001,
          Subtitle = "Yes, I've heard some "haunted house" rumours as well, makes you wonder... But speaking of which—",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD27C"
        },
        [10106316] = {
          ContentFR = "Au fait, pourquoi t’intéresser à tout ça ?",
          DialogueId = 10106316,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194CD27D",
          NextDialogue = 10106317,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{"Think_End"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "D**n it! If it wasn't for Fina, I'd have chucked him into Lamenting Lake to feed the fish.",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD27D"
        },
        [10106317] = {
          Camera = "-118.512451,-182.769531,140.193848,0.000153,4.599757,50.000011,35.0,272.898132,false,Manual,2.264544",
          ContentFR = "J’avais un camarade Chasseur de Phoxène, un jeune nommé Hunt. Il a disparu il y a un mois. La dernière à l’avoir vu est une petite récupératrice de la cité... devant la Maison d’Hypnos.",
          DialogueId = 10106317,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD2A6",
          NextDialogue = 10106318,
          Scripts = "SEQ{\nCameraMoveTo{_delay{5.01},TargetPosition{\"-637.433105,247.024414,212.966797,0.000224,14.600731,161.606003,15.000005,272.898132,false,DoNotOverride,2.264544\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-637.433105,247.024414,91.351562,0.000223,6.600879,161.406097,15.000005,272.898132,false,DoNotOverride,2.264544\"},duration{12}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "...But you're starting to suspect he's after Fina, aren't you?",
          TalkActionId = {
            [1] = "200021:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD2A6"
        },
        [10106318] = {
          Camera = "-599.96167,1241.567383,973.956787,0.000164,-31.200064,-54.605648,35.0,179.039703,false,DoNotOverride,7.148376",
          ContentFR = "Il y a quelques jours, je suis allé affronter Henrik. Même avec ma dague sous sa gorge, il a refusé de dire où se trouvait Hunt.",
          DialogueId = 10106318,
          FacialId = {
            [1] = "200021:Sad01"
          },
          FinalCamera = "-650.708252,1312.987305,1027.01709,0.000164,-31.200064,-54.605648,35.000008,179.039703,false,DoNotOverride,7.148376",
          GUID = "194CD2D0",
          NextDialogue = 10106319,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{1}},\nPlayAnimation{ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}},\nPlayAnimation{_delay{2.5},ActorId{200021},AnimationId{\"Talk03_End\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Angry01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Exactly. That's why I need to get to the bottom of Henrik's deal.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD2D0"
        },
        [10106319] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376",
          ContentFR = "Il s’est contenté de ricaner : « Tu sais mieux que moi ce qu’il en coûte à un Charon de s’en prendre à un Sola. Je sais que tu as une sœur... Si tu tiens à elle, mêle-toi de tes affaires. »",
          DialogueId = 10106319,
          FinalCamera = "-57.103516,-124.65625,146.576172,0.000175,5.599648,57.998432,35.0,179.039703,false,Manual,7.148376",
          GUID = "194CD2FA",
          NextDialogue = 10106320,
          Scripts = "PARA{\nPlayFacial{_delay{8.01},ActorId{100001},FacialId{\"Sad01\"}},\nSEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Angry01_End\"},Duration{1}},\nPlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}}\n},\nSEQ{\nCameraMoveTo{_delay{8.01},TargetPosition{\"33.62793,178.25293,208.352539,0.000216,-11.998771,-94.401909,55.000008,276.918182,false,Manual,7.148376\"},duration{0}},\nCameraMoveTo{TargetPosition{\"31.643555,152.46875,202.856445,0.000216,-11.998771,-94.401909,55.000008,246.001785,false,Manual,7.148376\"},duration{8}}\n}\n}",
          SpeakNpcId = 200021,
          Subtitle = "I'm worried about Psyche...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD2FA"
        },
        [10106320] = {
          Camera = "3519.108887,1585.492188,-165.398438,0.0,0.0,-94.298676,15.0,506.047913,false,DoNotOverride,1.2",
          ContentFR = "Ce fumier ! J’aurais voulu le jeter dans le Lac du Deuil, qu’il serve de festin aux poissons. Mais je dois découvrir ce qu’il a fait de Hunt... et quels secrets cache Henrik.",
          DialogueId = 10106320,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "194CD324",
          NextOptions = {
            [1] = 10106321
          },
          SpeakNpcId = 200021,
          Subtitle = "I mean the girl who went to the pit with me. She's a lodger at the Hypnos' House, a really nice girl...\nIf Henrik's up to no good, she could be in danger.",
          TalkActionId = {
            [1] = "200021:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD324"
        },
        [10106321] = {
          ContentFR = "Tu tiens vraiment à ton ami.",
          DialogueId = 10106321,
          GUID = "10106321.0",
          NextDialogue = 10106322,
          Subtitle = "You really care about your friend."
        },
        [10106322] = {
          Camera = "-113.647461,-178.358398,144.197266,0.000174,3.999752,51.800861,35.0,272.898132,false,Manual,3.476349",
          ContentFR = "... Ce n’est pas que pour Hunt. C’est surtout pour Fina. Je refuse de voir un proche vivre à nouveau dans la peur.",
          DialogueId = 10106322,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD3A0",
          NextDialogue = 10106323,
          Scripts = "PARA{\nPlayAnimation{_delay{3.5},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{1}},\nPlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "My original plan was to get the Crystallo of Stella from the pit and use them as an excuse to apologise to Henrik and investigate the inn.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3A0"
        },
        [10106323] = {
          Camera = "31.643555,152.46875,202.856445,0.000216,-11.998804,-94.401909,55.0,248.159653,false,Manual,7.148376",
          ContentFR = "Je comprends... Moi aussi, il y a quelqu’un qui m’inquiète, la fille en vert dont tu as parlé, Psyche.",
          DialogueId = 10106323,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194CD3A1",
          NextDialogue = 10106346,
          SpeakNpcId = 100001,
          Subtitle = "I thought no one would take the job, so I went off to sort out a cake first — didn't expect you newbies to throw a curveball.\nHow about we strike a deal?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3A1"
        },
        [10106325] = {
          Camera = "-72.05835,-160.591797,149.589355,0.000178,4.599668,58.198891,45.0,272.898132,false,Manual,5.157309",
          ContentFR = "Parfait. On dirait qu’on a un objectif commun.",
          DialogueId = 10106325,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CD3CC",
          NextDialogue = 10106326,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "What's this deal? You know I need the money.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3CC"
        },
        [10106326] = {
          ContentFR = "À l’origine, je comptais récupérer un Éclat stellaire dans la fosse, et m’en servir comme prétexte pour présenter mes excuses à Henrik. Ça m’aurait permis d’entrer dans l’auberge et d’observer les lieux.",
          DialogueId = 10106326,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD3F6",
          NextDialogue = 10106327,
          Scripts = "PlayAnimation{ActorId{200021},AnimationId{"Think_Start"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "I'd be pretty stupid to expect you to be some kind of saint. I mean — this is business.\nWhat I can offer you is another thing you might really need—",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3F6"
        },
        [10106327] = {
          Camera = "-1467.822266,2680.921875,479.816895,0.000082,-22.999664,-48.185631,35.0,565.117065,false,Manual,2.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Je pensais que personne n’accepterait cette mission, alors j’étais parti chercher un gâteau... Et voilà que vous, les {性别:petits nouveaux|petites nouvelles}, venez tout chambouler. Alors ? On fait affaire ?",
          DialogueId = 10106327,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "-1442.544678,2703.53418,479.816895,0.000082,-22.999664,-48.186123,35.0,565.117065,false,Manual,2.0",
          GUID = "194CD420",
          NextDialogue = 10106328,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Think_Start\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Sigh_Start\"},Duration{1}},\nPlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{1}},\nPlayAnimation{_delay{0.5},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{0}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "An "identity". A pass that allows you to move freely in Hyperborea, except for the high inner city behind the watchtowers —\nthat's reserved for the high and mighty.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD420"
        },
        [10106328] = {
          Camera = "15.664551,9.075195,174.650879,0.000171,-3.399993,66.602043,25.000002,54.401806,false,Manual,3.0",
          ContentFR = "Je peux t’obtenir quelque chose de bien plus précieux que de l’argent...",
          DialogueId = 10106328,
          FacialId = {
            [1] = "200021:Smile01"
          },
          GUID = "194CD44A",
          NextDialogue = 10106329,
          SpeakNpcId = 200021,
          Subtitle = "Many are willing to offer you money, but few would risk their lives to get you this.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD44A"
        },
        [10106329] = {
          Camera = "123.56665,72.790039,133.77002,0.000115,0.599902,-138.799866,30.0,88.840363,false,Manual,2.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Une "identité". Un permis de circulation qui te permet de circuler librement en Hyperborea, sauf dans la cité intérieure, derrière les grandes tours de garde, réservée aux élites.  ",
          DialogueId = 10106329,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "127.988281,67.745117,133.77002,0.00011,0.599889,-138.799866,30.0,218.134293,false,Manual,2.0",
          GUID = "194CD474",
          NextDialogue = 10106330,
          SpeakNpcId = 200021,
          Subtitle = "How did you know I needed that...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD474"
        },
        [10106330] = {
          Camera = "52.672607,-14.748047,167.826172,0.000079,-9.000058,-136.99884,30.000008,96.40477,false,Manual,1.828295",
          ContentFR = "Beaucoup seraient prêts à te payer en argent. Peu oseraient risquer leur vie pour t’offrir ça.",
          DialogueId = 10106330,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "194CD49E",
          NextOptions = {
            [1] = 10106331,
            [2] = 10106334
          },
          SpeakNpcId = 200021,
          Subtitle = "You're talking about a travel permit, right? How can you get one?",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD49E"
        },
        [10106331] = {
          ContentFR = "Comment as-tu su que j’en avais besoin... ?",
          DialogueId = 10106331,
          GUID = "10106331.0",
          NextDialogue = 10106332,
          Subtitle = "Just a guess. So you really don't have a travel permit, huh? Lucky you ran into me. Without one, you'd be in a world of trouble in Hyperborea, unless you just hide in a shadowy corner all day."
        },
        [10106332] = {
          Camera = "1.812988,-141.155273,152.519043,0.000166,0.799924,88.794739,25.0,179.039703,false,Manual,4.301303",
          ContentFR = "J’ai juste deviné. Donc tu n’as vraiment pas de permis de circulation ? Heureusement que tu es tombé sur moi, sinon à Hyperborea tu aurais été fichu... à moins de rester caché dans un coin sombre toute la journée.",
          DialogueId = 10106332,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194CD4C8",
          NextDialogue = 10106333,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Talk01_Start\"},Duration{1}},\nPlayAnimation{_delay{3.5},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"AgreeHead\"},Duration{2}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "(...He's trying to fish for information.)",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD4C8"
        },
        [10106333] = {
          Camera = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
          ContentFR = "... Il essaie de me soutirer des infos.",
          DialogueId = 10106333,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194CD4F2",
          NextOptions = {
            [1] = 10106337,
            [2] = 10106338
          },
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "Ah, got it. You're talking about getting a fake one, aren't you?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD4F2"
        },
        [10106334] = {
          ContentFR = "Un permis de circulation, donc. Et toi, comment tu t’en procures un ?",
          DialogueId = 10106334,
          GUID = "10106334",
          NextDialogue = 10106335,
          Subtitle = "Then I can also find someone to make one for me."
        },
        [10106335] = {
          Camera = "1.812988,-141.155273,152.519043,0.000166,0.799924,88.794739,25.0,179.039703,false,Manual,4.301303",
          ContentFR = "Comment tu t’en procures un ? Tu t’entends bien avec les gardes de Givrelac ?",
          DialogueId = 10106335,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD51C",
          NextDialogue = 10106336,
          Scripts = "SEQ{\nPlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Talk02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "How can you get one? Are you buddies with the guards in Icelake?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD51C"
        },
        [10106336] = {
          ContentFR = "Bien m’entendre, c’est beaucoup dire... Mais nous autres Chasseurs de Phoxène avons nos petites façons.",
          DialogueId = 10106336,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CD546",
          NextOptions = {
            [1] = 10106337,
            [2] = 10106338
          },
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Can't say I am, but we Phoxhunters have our ways.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD546"
        },
        [10106337] = {
          ContentFR = "Oh, je vois... Tu parles d’un faux, pas vrai ?",
          DialogueId = 10106337,
          GUID = "10106337",
          NextDialogue = 10106339,
          Subtitle = "Ah, got it. You're talking about getting a fake one, aren't you?"
        },
        [10106338] = {
          ContentFR = "Alors je peux très bien trouver quelqu’un d’autre pour m’en fabriquer un.",
          DialogueId = 10106338,
          GUID = "10106338",
          NextDialogue = 10106339,
          Subtitle = "Then I can also find someone to make one for me."
        },
        [10106339] = {
          Camera = "123.935547,5.261719,672.55127,0.001522,-78.772713,-167.208313,25.0,326.395905,false,DoNotOverride,2.217901",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Dans cette ville, il est des choses que l’argent n’achète pas, surtout celles qui peuvent te brûler les doigts. Ce qui permet de les obtenir, c’est ce fil invisible qu’on appelle les connexions entre les gens.",
          DialogueId = 10106339,
          FacialId = {
            [1] = "200021:None",
            [2] = "100001:None"
          },
          FinalCamera = "140.303955,8.964844,757.100586,0.001522,-78.772713,-167.208313,25.0,326.395905,false,DoNotOverride,2.217901",
          GUID = "194CD570",
          NextDialogue = 10106340,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.1},TargetPosition{\"-39.0,7.46582,5875.651855,0.000019,-90.0,0.000027,20.0,326.395905,false,DoNotOverride,2.217901\"},duration{0}},\nCameraMoveTo{_delay{4.2},TargetPosition{\"-39.0,7.46582,6107.878906,0.000248,-90.0,-0.000109,20.0,326.395905,false,DoNotOverride,2.217901\"},blend{\"easeOutQuad\"},duration{4}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "There are things in this city that money can't buy, especially if they could land you in hot water.\nWhat you need is that \"invisible thread\" of connections between people.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD570"
        },
        [10106340] = {
          Camera = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
          ContentFR = "En Hyperborea... sans permis de circulation, impossible d’avancer.",
          DialogueId = 10106340,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194CD59A",
          NextDialogue = 10106341,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Without a travel permit, it's indeed difficult to get around in Hyperborea.)",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59A"
        },
        [10106341] = {
          Camera = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Cet échange, qu’est-ce que tu veux en retour ? Que je t’offre l’Éclat stellaire ?",
          DialogueId = 10106341,
          ExStoryInfo = "Player",
          FinalCamera = "66.709229,-7.40918,165.228027,0.000144,-5.398807,-135.095779,35.000008,114.245468,false,Manual,3.628265",
          GUID = "194CD59B",
          NextDialogue = 10106342,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Alright. So what do I need to do for this deal? Just let go of the Crystallo?",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59B"
        },
        [10106342] = {
          Camera = "16.160889,-237.400391,148.03125,0.000132,1.599944,92.399918,35.0,306.557922,false,Manual,2.071165",
          ContentFR = "Non. L’éclat est à toi, tu peux toujours l’échanger contre des pièces d’argent auprès d’Henrik. Ce que je veux... c’est que tu trouves un moyen d’entrer dans la Maison d’Hypnos, et que tu découvres ce qu’ils cachent.",
          DialogueId = 10106342,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CD59C",
          NextDialogue = 10106343,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain01_End\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "No, you can have it. All I need from you is one thing: while delivering the Crystallo, find a way to investigate the Hypnos' House.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59C"
        },
        [10106343] = {
          Camera = "70.744141,-0.792969,168.705566,0.000141,-7.000274,-136.200241,35.0,121.432114,false,Manual,2.071165",
          ContentFR = "Tu n’es pas d’ici. Il ne se méfiera pas de toi. Peut-être que tu réussiras à découvrir quelque chose.",
          DialogueId = 10106343,
          FinalCamera = "65.674561,-5.65332,167.844727,0.000145,-7.000274,-136.200256,35.000008,121.432114,false,Manual,2.071165",
          GUID = "194CD59D",
          NextDialogue = 10106344,
          SpeakNpcId = 200021,
          Subtitle = "Is that all?",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59D"
        },
        [10106344] = {
          ContentFR = "Ça me paraît simple. Troquer un peu d’espionnage contre un permis de circulation... marché conclu.",
          DialogueId = 10106344,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "194CD59E",
          NextDialogue = 10106345,
          SpeakNpcId = 100001,
          Subtitle = "Aren't you worried I'll just take the Crystallo and run?",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59E"
        },
        [10106345] = {
          Camera = "766.177124,137.326172,160.495605,0.000145,-2.799988,-174.8013,30.0,821.970154,false,Manual,1.2",
          ContentFR = "Simple, oui. Mais sois {性别:prudent|prudente}. Demain midi, reviens ici avec ce que tu auras appris.",
          DialogueId = 10106345,
          FinalCamera = "843.248169,144.335938,164.278809,0.000145,-2.799988,-174.8013,30.0,821.970154,false,Manual,1.2",
          GUID = "194CD59F",
          Scripts = "PARA{\nPlayAnimation{ActorId{200021},AnimationId{\"AgreeHead\"},Duration{2}},\nPlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{1}}}",
          SpeakNpcId = 200021,
          Subtitle = "I trust you.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59F"
        },
        [10106346] = {
          ContentFR = "Si tu compromets nos affaires, ou si quelqu’un commence à se poser des questions... tu sais ce que ça entraînerait.",
          DialogueId = 10106346,
          GUID = "194CD3A3",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106346.T_Story_Recall_10106346'",
          NextDialogue = 10130001,
          SnapShot = "MEMORY",
          SpeakNpcId = 200005,
          VoiceName = "voice/$Locale$/story/1002/101058/194C8021"
        },
        [10106401] = {
          ContentFR = "Repose-toi. Demain, à midi, je t’attends ici.",
          DialogueId = 10106401,
          GUID = "194CE16A",
          SpeakNpcId = 200021,
          Subtitle = "Better go get some rest. I'll be here at 12:00 tomorrow waiting for you.",
          VoiceName = "voice/$Locale$/story/1002/101064/194CE16A"
        },
        [10106501] = {
          Camera = "1342.068604,-1311.530273,220.426514,-0.001037,-2.0155,135.017212,35.000008,130.587296,false,DoNotOverride,1.200001",
          ContentFR = "Berry... tant de choses se sont passées aujourd’hui.",
          DialogueId = 10106501,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "1296.370605,-1357.253906,220.427002,-0.001037,-2.0155,135.017212,35.000008,130.587296,false,DoNotOverride,1.200001",
          GUID = "194CF1D2",
          NextDialogue = 10106502,
          Scripts = "PARA{\nMoveTo{ActorId{100001},TargetPoint{\"P101065Nvzhu3\"},MoveSpeed{70},Visibility{\"Show\"}},\nTurnTo{_delay{4},TurnToDescription{\"100001:p(180)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Berry... so much has happened today.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101065/194CF1D2"
        },
        [10106502] = {
          Camera = "52.611328,-106.246094,216.994141,-0.001068,-30.616068,105.614693,45.0,130.587296,false,DoNotOverride,1.200001",
          ContentFR = "De là où tu es, peux-tu voir la lune ? La même que moi, en cet instant ?",
          DialogueId = 10106502,
          ExStoryInfo = "Player",
          GUID = "194CF1FC",
          LookAt = {
            [1] = "100001:p(P101065Nvzhu1)"
          },
          NextDialogue = 10106503,
          SpeakNpcId = 100001,
          Subtitle = "Can you see the moon from where you are, the very same moon that I'm looking at?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101065/194CF1FC"
        },
        [10106503] = {
          Camera = "151.07959,227.739746,23.063232,-0.00107,24.9841,-112.175705,25.000006,130.587296,false,DoNotOverride,1.200001",
          ContentFR = "... Demain, nous continuerons de vivre. {性别:Tous|Toutes} les deux.",
          DialogueId = 10106503,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "162.402832,255.521484,20.136963,-0.001067,22.184078,-112.175461,25.000006,130.587296,false,DoNotOverride,1.200001",
          GUID = "194CF226",
          LookAt = {
            [1] = "100001:p(P101065Nvzhu2)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Tomorrow, we will still survive.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101065/194CF226"
        },
        [10106601] = {
          ContentFR = "... Le jour s’est levé. Il est temps de partir pour la Maison d’Hypnos.",
          DialogueId = 10106601,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194D023A",
          GuideFacialId = "Afraid",
