          Scripts = "PARA{\nPlayAnimation{delay{1.2},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{1}},\nPlayNormalSound{_click{false},_delay{2},EventPath{\"event:/sfx/common/story/01/konck_door_nvzhu\"},PlayAs2D{false}},\nPlayAnimation{delay{2.2},ActorId{100001},AnimationId{\"Angry01_End\"},Duration{1}}\n}",
