        },
        [10106703] = {
          Camera = "-86.024658,92.782227,128.178589,0.001248,-4.999971,12.501308,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qu’est-ce que tu viens faire ici ? Je t’avais dit de filer au matin.",
          DialogueId = 10106703,
          FinalCamera = "-90.269287,111.916992,128.178589,0.00125,-4.999971,12.502479,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194D12CC",
          NextDialogue = 10106704,
          SpeakNpcId = 200005,
          Subtitle = "What are you doing here? Didn't I ask you to leave in the morning?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101067/194D12CC"
        },
        [10106704] = {
          ContentFR = "J’ai trouvé ce que vous vouliez, l’<H>Éclat stellaire</>.",
          DialogueId = 10106704,
          ExStoryInfo = "Player",
          GUID = "194D12F6",
          NextDialogue = 10106705,
          SpeakNpcId = 100001,
          Subtitle = "I've got what you were looking for, the Crystallo of Stella.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101067/194D12F6"
        },
        [10106705] = {
          ContentFR = "Personne ne t’a demandé de venir. Va aux Asphodèles, et donne-le à Camilla Scarlet.",
          DialogueId = 10106705,
          GUID = "194D1320",
          NextDialogue = 10106706,
          SpeakNpcId = 200005,
          Subtitle = "No one asked you to come here. Go to The Asphodel and give it to Camilla Scarlet.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101067/194D1320"
        },
        [10106706] = {
          Camera = "43.533447,190.366211,124.659058,0.001232,1.999995,-65.366714,15.0,73.0,false,Manual,2.8",
          ContentFR = "Je ne suis pas d’ici, je ne connais pas vos règles à Givrelac. Chez moi, un marché c’est simple : argent contre marchandise, dans la main.",
          DialogueId = 10106706,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "43.533447,190.366211,132.331177,0.001219,-1.200071,-66.367569,15.000005,73.0,false,Manual,2.8",
          GUID = "194D134A",
          NextDialogue = 10106707,
          Scripts = "SEQ{\nPlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1.8}},\nPlayAnimation{ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "I'm a stranger here, not too familiar with Icelake's ways. In where I come from, a deal means cash in one hand, goods in the other.",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101067/194D134A"
        },
        [10106707] = {
          Camera = "15.884277,-55.96582,118.667114,0.001188,0.0,83.499969,22.000006,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Si cela ne vous intéresse pas, Monsieur Henrik, je trouverai bien un autre acheteur.",
          DialogueId = 10106707,
          ExStoryInfo = "Player",
          FinalCamera = "8.491455,-55.133789,118.667114,0.001188,0.0,83.499969,22.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "194D1374",
          NextDialogue = 10106708,
          Scripts = "PARA{\nTurnTo{_delay{1},TurnToDescription{\"100001:p(120)\"}},\nLookAt{_delay{1.2},LookAtDescription{\"100001:p(P10106701)\"}},\nPlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "If you're not interested, Mr Henrik, I might just go looking for another buyer.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101067/194D1374"
