        },
        [10106903] = {
          Camera = "548.792969,-679.199219,191.576172,0.000134,-15.199936,70.598717,30.0,329.993164,false,Manual,3.110344",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "{nickname} ?! Mais... qu’est-ce que tu fais ici ? Henrik est au courant ? ... Viens vite avec moi.",
          DialogueId = 10106903,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Shock01"
          },
          FinalCamera = "548.792969,-679.199219,182.640625,0.000134,-15.199936,70.598717,30.0,329.993164,false,Manual,3.110344",
          GUID = "194D33C6",
          LookAt = {
            [1] = "200006:n(100001)",
            [2] = "200045:n(100001)"
          },
          NextDialogue = 10106904,
          Scripts = "PARA{\nSetLocation{ActorId{100001},TargetPoint{\"P101069Nvzhu3\"},Visibility{\"Show\"}},\nMoveTo{_delay{0.1},ActorId{100001},TargetPoint{\"P101069Nvzhu2\"},MoveSpeed{70},Visibility{\"Show\"}},\nCameraMoveTo{_delay{5.8},TargetPosition{\"620.515625,-151.44223,98.601562,0.000176,0.599984,-72.797096,50.0,221.792267,false,Manual,9.747352\"},duration{0}},\nPlayAnimation{_delay{2},ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "? What are you doing here? Does Mr Henrik know about this...? Ah, please come with me.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101069/194D33C6"
        },
        [10106904] = {
          Camera = "574.537109,-151.818848,105.101562,0.000176,-3.599967,-55.999626,30.0,238.777985,false,Manual,2.5",
          ContentFR = "Elisa, attends-moi un instant, je reviens tout de suite.",
          DialogueId = 10106904,
          Duration = 2,
          FacialId = {
            [1] = "200006:Happy02"
          },
          FinalCamera = "578.134766,-149.392853,105.101562,0.000176,-3.599967,-55.999626,30.0,240.854767,false,Manual,2.5",
          GUID = "194D33F0",
          LookAt = {
            [1] = "200006:n(200045)",
            [2] = "200045:n(200006)"
          },
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200006},AnimationId{"Explain01_Start"},Duration{1}}",
          SpeakNpcId = 200006,
          Subtitle = "Could you wait here for a moment, Elisa? I'll be right back.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101069/194D33F0"
        },
        [10107001] = {
          Camera = "118.46875,153.970703,155.228516,0.000001,-1.999538,-127.20298,70.0,235.416611,false,Manual,8.483248",
          ContentFR = "Monsieur Henrik n’aime pas que des étrangers entrent ici sans autorisation... et toi, tu t’es déjà disputé avec lui. S’il te voit...",
          DialogueId = 10107001,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "118.46875,153.970703,152.742188,0.000001,-1.999538,-127.20298,70.0,235.416611,false,Manual,8.483248",
          GUID = "194D43DA",
          NextDialogue = 10107002,
          RelatedWikiId = {
            [1] = 301004,
            [2] = 405002,
            [3] = 201006,
            [4] = 201007,
            [5] = 201009
          },
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0050_story_saiqi_grow_flower\"}},\nLookAt{_delay{6},LookAtDescription{\"200006:p(P101070Saiqi3)\"}}\n}\n",
          SpeakNpcId = 200006,
          Subtitle = "Mr Henrik doesn't allow outsiders to come in, and you two got off on the wrong foot back then. If he sees you...",
          TalkActionId = {
            [1] = "200006:DisagreeHead"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D43DA"
        },
        [10107002] = {
          Camera = "-11.103516,535.533691,150.160156,0.0,-3.999349,-87.40229,35.0,549.519409,false,Manual,4.291738",
          ContentFR = "Tu es venu pour le logement, n’est-ce pas ? Ne t’inquiète pas, cache-toi ici un instant. Je vais plaider ta cause auprès de Monsieur Henrik. Il acceptera sûrement que tu restes quelques jours de plus.",
          DialogueId = 10107002,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "-11.103516,535.533691,148.048828,0.0,-3.999328,-87.402275,35.0,549.519409,false,Manual,4.291738",
          GUID = "194D43DB",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextOptions = {
            [1] = 101070021
          },
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200006},AnimationId{"Explain02_Start"},Duration{0.1}}",
          SpeakNpcId = 200006,
          Subtitle = "You're here for the lodging stuff, aren't you? Don't worry, just hide here for a bit. I'll talk to Mr Henrik again.\nHe'll surely let you stay a few more days.",
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1002/101070/194D43DB"
        },
        [10107003] = {
          Camera = "-5.626953,58.096191,144.837891,0.000018,2.200605,-108.797859,35.000008,93.94474,false,Manual,8.483248",
          ContentFR = "Vraiment ? C’est merveilleux... ! Mais cet homme est tellement... autoritaire. Comment as-tu fait ?",
          DialogueId = 10107003,
          FacialId = {
            [1] = "200006:Happy01",
            [2] = "100001:Smile01"
          },
          GUID = "194D4404",
          NextOptions = {
            [1] = 101070031,
            [2] = 101070032
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{8.2},TargetPosition{\"-28.324219,26.407959,145.527344,0.000018,1.800424,16.803524,35.000008,93.94474,false,Manual,8.483248\"},duration{0}},\nPlayFacial{_delay{4.2},ActorId{200006},FacialId{\"Unhappy01\"}},\nPlayAnimation{_delay{8.3},ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "Ah, really? That's great! But that man is so... domineering. How did you make that happen?",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4404"
        },
        [10107004] = {
          Camera = "-18.091797,61.085693,144.837891,0.000013,2.400675,-101.197495,35.0,93.94474,false,Manual,8.483248",
          ContentFR = "Vraiment ? Je n’aurais jamais cru qu’il puisse être aussi... sensible.",
          DialogueId = 10107004,
          FacialId = {
            [1] = "200006:Shock01"
          },
          GUID = "194D442E",
          NextDialogue = 10107005,
          SpeakNpcId = 200006,
          Subtitle = "Really? I wouldn't have pegged Mr Outsider as someone so sensitive.",
          VoiceName = "voice/$Locale$/story/1002/101070/194D442E"
        },
        [10107005] = {
          Camera = "-239.527344,-76.267822,140.667969,0.000016,-1.799365,15.204763,35.000008,357.107239,false,Manual,1.688559",
          ContentFR = "Il est... un peu différent de ce que son apparence effrontée laisse penser. Quoi qu’il en soit...",
          DialogueId = 10107005,
          ExStoryInfo = "Player",
          FinalCamera = "-258.751953,-81.134766,141.289062,0.000016,-1.7994,14.20407,35.000008,357.107239,false,Manual,1.688559",
          GUID = "194D4458",
          NextDialogue = 10107032,
          SpeakNpcId = 100001,
          Subtitle = "He's... a bit different than his brash exterior suggests. Anyway...",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D4458"
        },
        [10107006] = {
          Camera = "-5.626953,58.096191,144.837891,0.000018,2.200605,-108.797859,35.000008,93.94474,false,Manual,8.483248",
          ContentFR = "Quoi ?! C’est vrai ? Il a besoin de médicaments ? J’en ai ici, tu pourrais lui en porter...",
          DialogueId = 10107006,
          FacialId = {
            [1] = "200006:Shock01"
          },
          GUID = "194D4482",
          NextDialogue = 10107007,
          SpeakNpcId = 200006,
          Subtitle = "Really? Does he need any medicine? I've got some. Can you bring it to him?",
          VoiceName = "voice/$Locale$/story/1002/101070/194D4482"
        },
        [10107007] = {
          Camera = "-451.320312,-14.900146,146.650391,0.000003,-2.799394,3.99817,40.0,549.519409,false,Manual,4.291738",
          ContentFR = "Pas besoin ! Il a ce qu’il faut chez lui. Quoi qu’il en soit...",
          DialogueId = 10107007,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:None",
            [2] = "100001:Happy02"
          },
          FinalCamera = "-492.1875,-17.756348,148.652344,0.000003,-2.799394,3.998163,40.0,549.519409,false,Manual,4.291738",
          GUID = "194D44AC",
          NextDialogue = 10107032,
          SpeakNpcId = 100001,
          Subtitle = "That's alright! He's got his own supply at home. Anyway...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101070/194D44AC"
        },
        [10107008] = {
          Camera = "-10.556641,523.596924,149.322266,0.0,-3.999328,-87.402275,35.0,549.519409,false,Manual,4.291738",
          ContentFR = "Oui. Tout le monde est là pour se soigner... moi y compris.",
          DialogueId = 10107008,
          FacialId = {
            [1] = "200006:Happy01",
            [2] = "100001:None"
          },
          FinalCamera = "-11.103516,535.533691,150.160156,0.0,-3.999349,-87.40229,35.0,549.519409,false,Manual,4.291738",
          GUID = "194D44D6",
          LookAt = {
            [1] = "200006:p(P101070Saiqi1)"
          },
          NextDialogue = 10107009,
          SpeakNpcId = 200006,
          Subtitle = "Yes. Everyone's recovering from some conditions here... me included.",
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D44D6"
        },
        [10107009] = {
          Camera = "-20.644531,3.659912,145.527344,0.000015,0.800341,28.803095,35.000008,93.944733,false,Manual,8.483248",
          ContentFR = "Et toi, ça va ? Tu ne m’avais pas dit que tu étais malade...",
          DialogueId = 10107009,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "194D4500",
          NextDialogue = 10107010,
          Scripts = "SetRotation{SetRotationDescription{"100001:p(19)"}}",
          SpeakNpcId = 100001,
          Subtitle = "Are you doing okay? You didn't tell me you were sick...",
          TalkActionId = {
            [1] = "100001:Explain02_Start",
            [2] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4500"
        },
        [10107010] = {
          Camera = "71.65625,83.940186,147.439453,0.000008,0.000321,-127.996948,50.0,160.507706,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 10107010,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "82.693359,98.06543,147.439453,0.000008,0.000321,-127.996948,50.0,160.507706,false,Manual,22.0",
          GUID = "194D452A",
          NextDialogue = 10107011,
          Scripts = "PARA{\nSetRotation{SetRotationDescription{\"100001:p(-19)\"}},\nLookAt{_delay{1},LookAtDescription{\"200006:p(P101070Saiqi2)\"}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200006:SpecialThink_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101070/194D452A"
        },
        [10107011] = {
          ContentFR = "Ce n’est rien, juste une broutille. Hier encore, je suis allée avec toi jusqu’à la fosse. Tu n’as pas à t’en faire.",
          DialogueId = 10107011,
          GUID = "194D4554",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10107012,
          Scripts = "PlayAnimation{_delay{1},ActorId{200006},AnimationId{"DisagreeHead"},Duration{1}}",
          SpeakNpcId = 200006,
          Subtitle = "It's nothing serious, just a minor ailment. I was even strong enough to explore the pit with you, remember? Don't worry about me.",
          TalkActionId = {
            [1] = "200006:SpecialThink_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4554"
        },
        [10107012] = {
          Camera = "-451.320312,-14.900146,146.650391,0.000003,-2.799394,3.99817,40.0,549.519409,false,Manual,4.291738",
          ContentFR = "D’accord... tant que tu vas bien, ça me rassure.",
          DialogueId = 10107012,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:None"
          },
          FinalCamera = "-492.1875,-17.756348,148.652344,0.000003,-2.799394,3.998163,40.0,549.519409,false,Manual,4.291738",
          GUID = "194D457E",
          NextDialogue = 10107013,
          SpeakNpcId = 100001,
          Subtitle = "Good, I'm glad you're okay.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101070/194D457E"
        },
        [10107013] = {
          Camera = "-32.240234,44.838135,145.527344,0.000015,2.000453,6.202501,35.0,93.94474,false,Manual,8.483248",
          ContentFR = "... Alors tous les pensionnaires de la Maison d’Hypnos souffrent d’une certaine maladie...",
          DialogueId = 10107013,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194D45A8",
          NextDialogue = 10107032,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...So, all the lodgers at the Hypnos' House suffer from some kind of illness.)",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D45A8"
        },
        [10107014] = {
          ContentFR = "Nous avons eu quelques différends par le passé, et j’aimerais apaiser les choses. Si possible, j’aimerais lui rendre visite à l’avenir.",
          DialogueId = 10107014,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "194D45D2",
          NextDialogue = 10107015,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{"ScratchHead_End"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "I've got off on the wrong foot with Mr Henrik, so I'm looking to mend fences with him.\nIf there's a chance, I'd like to visit him in the future.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D45D2"
        },
        [10107015] = {
          Camera = "16.691406,22.081543,148.732422,0.000052,-2.199649,-135.59375,25.0,75.553604,false,Manual,3.314391",
          ContentFR = "Vraiment ? Monsieur Henrik est presque toujours à la maison ! Si tu en as envie, tu peux venir quand tu veux, du moment qu’il est d’accord.",
          DialogueId = 10107015,
          FacialId = {
            [1] = "200006:Happy01",
            [2] = "100001:None"
          },
          GUID = "194D45FC",
          NextDialogue = 10107016,
          SpeakNpcId = 200006,
          Subtitle = "Really? Mr Henrik is almost always at home! You're welcome to visit anytime if he says it's okay!",
          VoiceName = "voice/$Locale$/story/1002/101070/194D45FC"
        },
        [10107016] = {
          Camera = "16.691406,22.081543,148.732422,0.000052,-2.199649,-135.59375,25.0,75.553604,false,Manual,3.314391",
          ContentFR = "... Et si tu acceptes de passer de temps en temps, pour raconter à tout le monde des histoires de ta ville natale, le Sud, l’océan, tous ces endroits que nous n’avons jamais vus… oh, je suis sûre que ça les rendrait tellement heureux !",
          DialogueId = 10107016,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Happy02"
          },
          FinalCamera = "21.3125,26.552246,148.972656,0.000052,-2.199649,-135.993698,25.0,75.553604,false,Manual,3.314391",
          GUID = "194D4626",
          NextDialogue = 10107017,
          SpeakNpcId = 200006,
          Subtitle = "If you'd be willing to come here often and share stories about your hometown — the South, the ocean...\nAll those places we've never been... everyone here would be thrilled!",
          TalkActionId = {
            [1] = "200006:Explain02_Start",
            [2] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D4626"
        },
        [10107017] = {
          Camera = "-32.240234,44.838135,145.527344,0.000015,2.000453,6.202501,35.0,93.94474,false,Manual,8.483248",
          ContentFR = "... Henrik est présent la plupart du temps... ce qui veut dire que la maison est placée sous sa surveillance quasi permanente.",
          DialogueId = 10107017,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194D4650",
          NextDialogue = 10107032,
          Scripts = "PlayAnimation{_delay{5},ActorId{100001},AnimationId{"Think_End"},Duration{1}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Henrik is almost always here... which means this place is under his watch most of the time.)",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4650"
        },
        [10107018] = {
          Camera = "-239.527344,-76.267822,140.667969,0.000016,-1.799352,15.204823,35.000008,357.107239,false,Manual,4.7",
          ContentFR = "Hier soir, Monsieur Henrik avait l’air très contrarié. Il ne t’a pas mal parlé, au moins ?",
          DialogueId = 10107018,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01",
            [2] = "200006:None"
          },
          FinalCamera = "-258.751953,-81.134766,141.289062,0.000016,-1.799365,14.20413,35.000008,357.107239,false,Manual,4.773073",
          GUID = "194D467A",
          NextDialogue = 10107019,
          SpeakNpcId = 100001,
          Subtitle = "Mr Henrik seemed quite upset last night. He didn't give you a hard time, did he?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D467A"
        },
        [10107019] = {
          Camera = "98.041016,134.36499,152.681641,0.000016,-2.19958,-125.604164,55.000008,235.416611,false,Manual,10.570968",
          ContentFR = "Non, non, pas du tout. Monsieur Henrik est seulement un peu... maladroit avec les mots. Il passe presque tout son temps enfermé dans son bureau, plongé dans ses recherches... il parle rarement aux autres.",
          DialogueId = 10107019,
          FinalCamera = "114.261719,157.031006,153.753906,0.000001,-2.199615,-125.60421,55.0,235.416611,false,Manual,4.291738",
          GUID = "194D46A4",
          NextDialogue = 10107020,
          Scripts = "PARA{\nPlayAnimation{_delay{1.5},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{0.1}},\nPlayAnimation{_delay{4.5},ActorId{200006},AnimationId{\"Talk02_Start\"},Duration{0.1}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "No, I'm fine. Mr Henrik is just a bit... inarticulate. After all, he spends most of his time alone in his office doing research,\nhardly ever talks to anyone...",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101070/194D46A4"
        },
        [10107020] = {
          Camera = "-81.09375,-42.923584,148.824219,0.000015,-1.59948,29.204563,35.0,182.723816,false,Manual,8.483248",
          ContentFR = "Tant mieux... À propos, sais-tu sur quoi portent ses recherches ?",
          DialogueId = 10107020,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194D46CE",
          NextDialogue = 10107021,
          SpeakNpcId = 100001,
          Subtitle = "Good to hear. Speaking of which, do you know what kind of research he's doing in there all the time?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D46CE"
        },
        [10107021] = {
          Camera = "69.644531,85.531006,147.439453,0.000017,0.000321,-126.796516,50.000008,160.507706,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 10107021,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "79.910156,99.261475,147.439453,0.000017,0.000321,-126.796455,50.000008,160.507706,false,Manual,22.0",
          GUID = "194D46F8",
          NextDialogue = 10107022,
          Scripts = "LookAt{_delay{1},LookAtDescription{"200006:p(P101070Saiqi1)"}}",
          SpeakNpcId = 200006,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200006:Talk02_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101070/194D46F8"
        },
        [10107022] = {
          ContentFR = "Je... je ne sais pas... Désolée.",
          DialogueId = 10107022,
          FacialId = {
            [1] = "200006:Sad01"
          },
          GUID = "194D4722",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10107023,
          SpeakNpcId = 200006,
          Subtitle = "I... I don't know... sorry.",
          TalkActionId = {
            [1] = "200006:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4722"
        },
        [10107023] = {
          Camera = "-451.320312,-14.900146,146.650391,0.000003,-2.799394,3.99817,40.0,549.519409,false,Manual,4.291738",
          ContentFR = "Ce n’est rien, je demandais juste.",
          DialogueId = 10107023,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "194D474C",
          NextDialogue = 10107024,
          SpeakNpcId = 100001,
          Subtitle = "That's alright, I was just curious.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D474C"
        },
        [10107024] = {
          Camera = "-32.240234,44.838135,145.527344,0.000015,2.000453,6.202501,35.0,93.94474,false,Manual,8.483248",
          ContentFR = "... Psyche me cache quelque chose. Sans doute parce qu’Henrik lui interdit d’en parler. Je ferais mieux de ne pas insister.",
          DialogueId = 10107024,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "194D4776",
          NextDialogue = 10107032,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Psyche is withholding something — must be on Henrik's demand. Better not push her.)",
          VoiceName = "voice/$Locale$/story/1002/101070/194D4776"
        },
        [10107025] = {
          Camera = "-2118.955078,-2194.391602,277.945312,0.0,-14.59985,2.400021,15.000005,223.056076,false,DoNotOverride,1.2",
          ContentFR = "Monsieur Henrik devrait sortir d’un instant à l’autre... Je vais descendre.",
          DialogueId = 10107025,
          Duration = 5,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:None",
            [2] = "100001:None"
          },
          FinalCamera = "-2120.978516,-1932.643066,83.693359,0.0,-14.999996,0.0,15.000005,223.056076,false,DoNotOverride,4.0",
          GUID = "194D47A0",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10107026,
          Scripts = "SetLocation{ActorId{100001},TargetPoint{"P101070Nvzhu"},Visibility{"Show"}}",
          SpeakNpcId = 100001,
          Subtitle = "Mr Henrik should be out any minute. I gotta go downstairs.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101070/194D47A0"
        },
        [10107026] = {
          Camera = "-11.103516,535.533691,150.160156,0.0,-3.999349,-87.40229,35.0,549.519409,false,Manual,4.291738",
          ContentFR = "Tu pars déjà... ?",
          DialogueId = 10107026,
          FacialId = {
            [1] = "200006:Shock01"
          },
          FinalCamera = "-11.103516,535.533691,148.048828,0.0,-3.999328,-87.402275,35.0,549.519409,false,Manual,4.291738",
          GUID = "194D47CA",
          LookAt = {
            [1] = "100001:n(200006)"
          },
          NextDialogue = 10107027,
          SpeakNpcId = 200006,
          Subtitle = "Are you leaving already...?",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200006:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D47CA"
        },
        [10107027] = {
          ContentFR = "Tiens, prends ces gâteaux. Tu pourras les manger si tu as faim... Ah, attends une seconde !",
          DialogueId = 10107027,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          GUID = "194D47F4",
          NextDialogue = 10107028,
          Scripts = "PARA{\nPlayAnimation{_delay{2.5},ActorId{200006},AnimationId{\"Give\"},Duration{0.1}},\nCameraMoveTo{_delay{5.2},TargetPosition{\"47.285156,-29.424316,156.810547,0.000016,-5.399353,-177.393768,35.000008,93.944733,false,Manual,8.483248\"},duration{0}}\n}",
          SpeakNpcId = 200006,
          Subtitle = "Take these pieces of bread with you, for when you're hungry... Oh, just a moment!",
          TurnTo = {
            [1] = "100001:n(200006)"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D47F4"
        },
        [10107028] = {
          Camera = "56.011719,16.459229,147.570312,0.00007,-24.799234,-153.798203,35.000008,93.94474,false,Manual,8.483248",
          ContentFR = "Emporte aussi ceci.",
          DialogueId = 10107028,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Flower_2.T_Guide_Chapter01_Flower_2'}",
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "194D481E",
          NextDialogue = 10107029,
          SpeakNpcId = 200006,
          Subtitle = "And take this too.",
          TalkActionId = {
            [1] = "200006:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D481E"
        },
        [10107029] = {
          Camera = "47.285156,-29.424316,156.810547,0.000016,-5.399353,-177.393768,35.000008,93.944733,false,Manual,8.483248",
          ContentFR = "Maman disait que porter une fleur sur soi porte chance.",
          DialogueId = 10107029,
          FacialId = {
            [1] = "200006:Happy02"
          },
          GUID = "194D4848",
          NextOptions = {
            [1] = 101070291
          },
          SpeakNpcId = 200006,
          Subtitle = "Mum always said, having a flower on you brings good luck.",
          VoiceName = "voice/$Locale$/story/1002/101070/194D4848"
        },
        [10107030] = {
          Camera = "-2.109375,-33.825195,151.314453,0.000132,-2.799592,0.983848,20.000008,62.706528,false,Manual,2.0",
          ContentFR = "... Il est temps de descendre pour récolter quelques informations.",
          DialogueId = 10107030,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194D4872",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Time to collect some intel downstairs.)",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4872"
        },
        [10107031] = {
          Content = "（……虽然这里有很多同龄人，但赛琪看起来依旧有些孤独。有机会的话，在离开冰湖城之前，多来陪她说说话吧。）",
          DialogueId = 10107031,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Smile02"
          },
          GUID = "194D489C",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Even though there are many of her age here, Psyche still seems a bit lonely. Maybe I should try to make some time for her\nbefore leaving Icelake.)",
          VoiceName = "voice/$Locale$/story/1002/101070/194D489C"
        },
        [10107032] = {
