        [10107101] = {
          Camera = "-123.40625,-31.072693,50.783203,0.000002,5.499996,-2.799134,20.0,536.5802,false,Manual,1.2",
          ContentFR = "La porte du bureau a déjà quelques années, mais elle est impeccable, luisante, sans une trace de poussière. Le bouton ne bouge pas d’un poil. Évidemment, elle est verrouillée de l’intérieur.",
          DialogueId = 10107101,
          DisableMouth = 1,
          FinalCamera = "-123.40625,-31.072693,60.292969,0.000002,7.500012,-2.799135,20.0,536.5802,false,Manual,1.2",
          GUID = "194D546B",
          LookAt = {
            [1] = "200019:n(100001)"
          },
          NextDialogue = 10107102,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 405002
          },
          SnapShot = "HEART",
          Subtitle = "(The office door is old yet spotless and polished. The doorknob won't budge an inch. Clearly, it's been locked from the inside.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 6
        },
        [10107102] = {
          Camera = "-81.755859,184.659851,161.341797,0.000044,-6.200008,-36.196159,40.0,349.444244,false,Manual,5.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Ne touche pas à cette porte.",
          DialogueId = 10107102,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "-83.671875,182.037048,161.373047,0.000044,-6.200008,-36.196159,40.0,349.444244,false,Manual,5.0",
          GUID = "194D546C",
          NextDialogue = 10107103,
          Scripts = "PARA{\nPlayAnimation{ActorId{200019},AnimationId{\"Explain01_Start\"},Duration{1}},\nTurnTo{_delay{0.8},TurnToDescription{\"100001:n(200019)\"}}\n}",
          SpeakNpcId = 200019,
          Subtitle = "...Don't touch that door.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101071/194D546C"
        },
        [10107103] = {
          Camera = "282.953125,16.883362,138.378906,0.000045,-0.999564,171.800415,40.0,264.652649,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Le bureau... est interdit. Personne, à part Monsieur Henrik Ethelred, ne peut y entrer.",
          DialogueId = 10107103,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "282.763672,15.521912,138.628906,0.000045,-0.999564,171.800415,40.0,264.652649,false,Manual,8.0",
          GUID = "194D5496",
          LookAt = {
            [1] = "100001:n(200019)"
          },
          NextOptions = {
            [1] = 101071031,
            [2] = 101071032
          },
          Scripts = "PlayAnimation{_delay{5},ActorId{200019},AnimationId{"Disagree"},Duration{1}},\n",
          SpeakNpcId = 200019,
          Subtitle = "The office... is off-limits. No one but Mr Henrik Ethelred is allowed inside.",
          TalkActionId = {
            [1] = "200019:Explain01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101071/194D5496"
        },
        [10107104] = {
          Camera = "199.689453,-10.062744,97.814453,0.000077,11.599525,153.204163,40.000011,200.297836,false,Manual,4.087842",
          ContentFR = "Ne te laisse pas aller... à la curiosité inutile.",
          DialogueId = 10107104,
          FinalCamera = "208.019531,-14.27124,95.898438,0.000078,11.599511,153.204163,40.000011,212.59935,false,Manual,4.087842",
          GUID = "194D54C0",
          NextDialogue = 10107105,
          Scripts = "PlayAnimation{_delay{1.8},ActorId{200019},AnimationId{"Talk01_Start"},Duration{1}}",
          SpeakNpcId = 200019,
          Subtitle = "No need... for unnecessary curiosity.",
          TalkActionId = {
            [1] = "200019:Disagree"
          },
          ToFinalCameraBlendTime = 3.5,
          VoiceName = "voice/$Locale$/story/1002/101071/194D54C0"
        },
        [10107105] = {
          Camera = "390.625,575.312744,19.304688,0.000079,2.99999,-125.595558,25.0,116.605362,false,Manual,2.125575",
          ContentFR = "Il n’y a rien d’intéressant... Cet endroit n’apporte que le malheur.",
          DialogueId = 10107105,
          FinalCamera = "390.625,575.312744,29.46875,0.000079,2.99999,-125.595558,25.0,534.811157,false,Manual,1.2",
          GUID = "194D54EA",
          NextOptions = {
            [1] = 101071051
          },
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200019},AnimationId{"Disagree"},Duration{1}}",
          SpeakNpcId = 200019,
          Subtitle = "There's nothing interesting there... only misfortune.",
          TalkActionId = {
            [1] = "200019:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101071/194D54EA"
        },
        [10107106] = {
          Camera = "70.351562,-398.249817,694.277344,0.0,-0.800252,89.591064,25.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Nettoyer. Tout dépoussiérer. Chaque jour, chaque étagère, chaque porte. Tout doit être impeccable.",
          DialogueId = 10107106,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "71.666016,-197.30661,698.957031,0.0,-0.800252,89.591064,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194D5514",
          NextOptions = {
            [1] = 101071061,
            [2] = 101071062
          },
          SpeakNpcId = 200019,
          Subtitle = "...Cleaning, dusting... Every day, every shelf, every door... Everything gets wiped down.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 9.5,
          VoiceName = "voice/$Locale$/story/1002/101071/194D5514"
        },
        [10107107] = {
          Camera = "385.044922,13.178589,149.109375,0.000046,-3.499994,174.201569,45.0,406.956116,false,Manual,8.0",
          ContentFR = "Tu ne comprends pas. C’est une "habitude"... Remplir sa vie d’activités régulières, c’est ça l’habitude.",
          DialogueId = 10107107,
          GUID = "194D553E",
          NextDialogue = 10107108,
          Scripts = "PlayAnimation{_delay{2},ActorId{200019},AnimationId{"Explain01_Start"},Duration{1}}",
          SpeakNpcId = 200019,
          Subtitle = "You don't get it. It's a "habit"... Filling life with regular tasks, that's what "habit" is.",
          TalkActionId = {
            [1] = "200019:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101071/194D553E"
        },
        [10107108] = {
          Camera = "-1277.564453,-593.944031,1182.701172,0.000064,-13.100098,20.401525,20.0,406.956116,false,Manual,8.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Comme moi qui nettoie tout ici chaque jour, ou Psyche qui arrose ses fleurs deux fois par jour. Les habitudes remplissent le vide en soi.",
          DialogueId = 10107108,
          FinalCamera = "-1291.347656,-556.815186,1182.701172,0.000064,-13.100098,20.401525,20.0,406.956116,false,Manual,8.0",
          GUID = "194D5568",
          NextOptions = {
            [1] = 101071081
          },
          Scripts = "SEQ{\nCameraMoveTo{_delay{4.1},TargetPosition{\"1046.738281,2345.742188,621.460938,0.0,0.0,89.999992,20.0,406.956116,false,Manual,8.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"1046.738281,2380.742188,621.460938,0.0,0.0,89.999977,20.0,406.956116,false,Manual,8.0\"},blend{\"easeOutQuad\"},duration{4}}\n}",
          SpeakNpcId = 200019,
          Subtitle = "Like how I clean here daily, or how Psyche waters her flowers twice a day. Habit fills the void inside.",
          TalkActionId = {
            [1] = "200019:Explain01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101071/194D5568"
        },
        [10107109] = {
          Camera = "-16.667969,120.591003,143.160156,0.000053,-2.999635,-29.59416,40.000011,267.37149,false,Manual,8.0",
          ContentFR = "Il a l’air très discipliné, ce serait un bon exemple à suivre.",
          DialogueId = 10107109,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          FinalCamera = "-15.384766,122.856628,143.160156,0.000054,-2.999635,-29.59416,40.000011,267.37149,false,Manual,8.0",
          GUID = "194D5592",
          NextDialogue = 10107110,
          Scripts = "SetRotation{SetRotationDescription{"100001:n(200019)"}}",
          SpeakNpcId = 100001,
          Subtitle = "He seems quite disciplined, probably a good role model for me.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101071/194D5592"
        },
        [10107110] = {
          Camera = "385.076172,13.593933,149.109375,0.000046,-3.5,175.201523,45.0,406.956116,false,Manual,8.0",
          ContentFR = "Monsieur Henrik ? Bien sûr qu’il en a. Voyons voir...",
          DialogueId = 10107110,
          GUID = "194D55BC",
          LookAt = {
            [1] = "100001:n(200019)"
          },
          NextDialogue = 10107111,
          Scripts = "SEQ{\nPlayAnimation{_delay{2.7},ActorId{200019},AnimationId{\"Agree\"},Duration{1.3}},\nPlayAnimation{ActorId{200019},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200019,
          Subtitle = "Mr Henrik? He does have some habits. Let me see...",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101071/194D55BC"
        },
        [10107111] = {
          ContentFR = "Quand il épluche une pomme, la peau ne doit pas se casser. Le nombre de pas entre la salle de bain et le bureau doit être pair. Chaque mois, il sort exactement à vingt heures le 20 du mois, puis revient pour vérifier trois fois la porte.",
          DialogueId = 10107111,
          GUID = "194D55E6",
          NextDialogue = 10107112,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200019},AnimationId{\"Think_End\"},Duration{1.5}},\nPlayAnimation{ActorId{200019},AnimationId{\"Talk02_Start\"},Duration{2.3}},\nPlayAnimation{ActorId{200019},AnimationId{\"Talk02_End\"},Duration{0.5}},\nPlayAnimation{ActorId{200019},AnimationId{\"Explain01_Start\"},Duration{3.5}},\nPlayAnimation{ActorId{200019},AnimationId{\"Explain01_End\"},Duration{0.5}},\nPlayAnimation{ActorId{200019},AnimationId{\"Talk01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200019,
          Subtitle = "When peeling apples, the peel mustn't break; the number of steps from the bathroom to the office has to be even;\nevery month, he goes out precisely at 5 PM on the 20th, then returns to double-check the door lock three times.",
          VoiceName = "voice/$Locale$/story/1002/101071/194D55E6"
        },
        [10107112] = {
          ContentFR = "... Mais je pense que ces habitudes sont trop personnelles, elles n’ont probablement pas beaucoup de valeur pour toi...",
          DialogueId = 10107112,
          GUID = "194D5610",
          NextOptions = {
            [1] = 101071121
          },
          Scripts = "PlayAnimation{_delay{3.8},ActorId{200019},AnimationId{"Disagree"},Duration{1}}",
          SpeakNpcId = 200019,
          Subtitle = "...These habits are quite personal though, I doubt they'd offer much for you to learn from...",
          TalkActionId = {
            [1] = "200019:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101071/194D5610"
        },
        [10107113] = {
          Camera = "158.138672,64.692383,167.386719,0.000077,-16.300076,-38.189926,35.000008,103.258133,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Donc, <H>Monsieur Henrik sort régulièrement de la maison à vingt heures le 20 de chaque mois</>.",
          DialogueId = 10107113,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "158.138672,64.692383,167.386719,0.000077,-16.100033,-38.189838,38.0,103.258133,false,Manual,8.0",
          GUID = "194D563A",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...So, Henrik regularly gets out of the house at 5 PM on the 20th every month.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5.5,
          VoiceName = "voice/$Locale$/story/1002/101071/194D563A"
        },
        [10107201] = {
          ContentFR = "... Non, ce n’est toujours pas assez propre. Il faut encore passer un coup...",
          DialogueId = 10107201,
          GUID = "194D64AA",
          SpeakNpcId = 200019,
          Subtitle = "...No, it's still not clean enough. It needs another wipe...",
          VoiceName = "voice/$Locale$/story/1002/101072/194D64AA"
        },
        [10107301] = {
          Camera = "-301.548828,432.195496,122.458984,0.000016,-3.400054,-55.403923,30.0,388.496887,false,DoNotOverride,1.2",
          ContentFR = "Pourquoi ? Non seulement tu es parti, mais même la montre que tu m’as offerte s’est arrêtée...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10107301,
          GUID = "194D7512",
          NextDialogue = 10107302,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 405002
          },
          Scripts = "PARA{\nMoveTo{ActorId{100001},TargetPoint{\"P101073Nvzhu\"},MoveSpeed{50},Visibility{\"Show\"}},\nCameraMoveTo{_delay{2.5},TargetPosition{\"-100.728516,-221.564697,150.214844,0.000027,-5.199918,64.396835,30.0,296.067078,false,Manual,1.2\"},duration{0}},\nCameraMoveTo{_delay{2.7},TargetPosition{\"-98.554688,-222.534592,150.214844,0.000028,-5.199918,62.0,30.0,158.217514,false,Manual,1.881333\"},duration{1.5}}\n}",
          SpeakNpcId = 700049,
          Subtitle = "...Why? Not only did you leave me, but even the pocket watch you gave me has stopped...",
          TalkActionId = {
            [1] = "700049:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101073/194D7512"
        },
        [10107302] = {
          Camera = "-378.818359,64.798508,155.345703,0.0001,-1.599999,-39.999985,16.0,404.409393,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Ce n’est pas grave... Bientôt, nous pourrons nous revoir... Hunt...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10107302,
          FinalCamera = "-364.181641,84.655518,155.345703,0.0001,-1.60006,-36.398785,16.0,404.409393,false,Manual,1.2",
          GUID = "194D753C",
          NextOptions = {
            [1] = 101073021
          },
          Scripts = "CameraMoveTo{_delay{6},TargetPosition{"-81.96875,-143.749664,122.654297,0.000146,3.399931,70.201393,50.0,231.458694,false,Manual,8.0"},duration{0}}",
          SpeakNpcId = 700049,
          Subtitle = "...It's alright... We'll meet again very soon... Hunt...",
          TalkActionId = {
            [1] = "700049:Explain02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101073/194D753C"
        },
        [10107303] = {
