          TurnTo = {
            [1] = "700049:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101073/194D7566"
        },
        [10107304] = {
          Camera = "-48.914062,175.870911,147.699219,-0.999999,-5.800107,-71.391937,30.0,289.5177,false,Manual,3.0",
          ContentFR = "Tu... qui es-tu... Je ne t’ai jamais vue. Tu viens de l’extérieur ? Tu écoutes aux portes ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10107304,
          GUID = "194D7590",
          NextOptions = {
            [1] = 101073041,
            [2] = 101073051
          },
          SpeakNpcId = 700049,
          Subtitle = "...Who are you...? I haven't seen you before. Are you from the outside? Were you eavesdropping?",
          TalkActionId = {
            [1] = "700049:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101073/194D7590"
        },
        [10107305] = {
          Camera = "-48.914062,175.870911,147.699219,-0.999999,-5.800107,-71.391937,30.0,289.5177,false,Manual,3.0",
          ContentFR = "Non... non, je ne te parlais pas !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10107305,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "194D75BA",
          NextOptions = {
            [1] = 101073051
          },
          SpeakNpcId = 700049,
          Subtitle = "No... no, I wasn't talking to you!!",
          TalkActionId = {
            [1] = "700049:Shock_End",
            [2] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101073/194D75BA"
        },
        [10107306] = {
          Camera = "-972.828125,-115.521408,201.955078,0.0,0.0,0.0,20.0,961.833435,false,Manual,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... Je ne sais pas... Je ne sais rien...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10107306,
          FinalCamera = "-1006.197266,-115.521408,201.955078,0.0,0.0,0.0,20.0,1023.64502,false,Manual,1.2",
          GUID = "194D75E4",
          NextDialogue = 10107307,
          SpeakNpcId = 700049,
          Subtitle = "I don't know... I don't know anything...",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700049:Disagree"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101073/194D75E4"
        },
        [10107307] = {
          Camera = "-1021.921875,1143.978638,148.681641,0.000042,-1.399991,-43.605011,25.0,388.496887,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... Éloigne-toi de moi ! Sinon je vais crier... !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10107307,
          FinalCamera = "-1011.439453,1154.975708,148.681641,0.000042,-1.399991,-43.605011,25.0,388.496887,false,DoNotOverride,1.2",
          GUID = "194D760E",
          NextOptions = {
            [1] = 101073071
          },
          SpeakNpcId = 700049,
          Subtitle = "...Please, stay away from me!! Or I'll scream...!",
          TalkActionId = {
            [1] = "700049:Sigh_Start"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101073/194D760E"
        },
        [10107308] = {
          Camera = "-49.619141,-81.934937,172.09375,0.000008,-11.400118,73.387161,50.0,170.835754,false,Manual,8.0",
          ContentFR = "... L’Étranger avait raison, <H>Hunt, le Chasseur de Phoxène disparu, a bien vécu ici.</> Mais les résidents gardent le secret sur sa destination.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10107308,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "-49.619141,-81.934937,172.871094,0.00001,-11.400118,73.786942,54.0,170.835754,false,Manual,8.0",
          GUID = "194D7638",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Outsider was right. Hunt, the missing Phoxhunter, used to live here. But the lodgers here are tight-lipped about his whereabouts.)",
          TalkActionId = {
            [1] = "700049:Sigh_End",
            [2] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101073/194D7638"
        },
