        [10107507] = {
          Camera = "-167.167969,51.11853,198.707031,0.000024,-21.200073,-26.397516,30.0,216.660995,false,Manual,2.611802",
          Content = "看得出来，您很重视这条项链，我还是不要夺人所好了。况且您家还蛮宽敞的，风景也很好，我还想多住几天。",
          DialogueId = 10107507,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "194D96DE",
          NextDialogue = 10107508,
          SpeakNpcId = 100001,
          Subtitle = "I can see this necklace means a lot to you, so I'd rather not take it. Besides, your place is roomy and has a great view,\nso I'd like to stay a bit longer.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101075/194D96DE"
        },
        [10107508] = {
