        },
        [10107509] = {
          Camera = "284.646484,567.699097,81.810547,0.000231,1.499991,-114.718117,35.0,524.155823,false,Manual,2.0",
          CameraBlendCurve = "easeOutQuad",
          Content = "我的字典里本没有“谢”这个字。但是……谢谢。",
          DialogueId = 10107509,
          FinalCamera = "294.712891,563.059692,81.810547,0.000231,1.499991,-114.718117,35.0,524.155823,false,Manual,2.0",
          GUID = "194D9732",
          SpeakNpcId = 200005,
          Subtitle = "I rarely say this, but... thank you.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200005:Sigh_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101075/194D9732"
        },
        [10107601] = {
          ContentFR = "Même si je n’ai pas pu entrer dans le bureau, j’ai tout de même obtenu quelques informations utiles. Allons voir l’Étranger.",
          DialogueId = 10107601,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "194DA64A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Though I couldn't get into the office, I've managed to gather some useful intel. Time to see Outsider.)",
          VoiceName = "voice/$Locale$/story/1002/101076/194DA64A"
        },
        [10107701] = {
          ContentFR = "... Tu peux partir.",
          DialogueId = 10107701,
          GUID = "194DB6B2",
          SpeakNpcId = 200005,
          Subtitle = "...You may leave now.",
          VoiceName = "voice/$Locale$/story/1002/101077/194DB6B2"
        },
        [10107801] = {
          Camera = "65.014893,170.40332,135.817871,0.000002,0.199913,-108.797142,35.000008,268.171082,false,Manual,2.5",
          ContentFR = "Alors, ton enquête a donné quoi ?",
          DialogueId = 10107801,
          GUID = "194DC71A",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10107802,
          RelatedWikiId = {
            [1] = 405002,
            [2] = 201006,
            [3] = 201009
          },
          SpeakNpcId = 200021,
          Subtitle = "How did the investigation go?",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101078/194DC71A"
        },
        [10107802] = {
          Camera = "65.560059,-249.484375,189.850098,0.000052,-11.599819,106.60054,50.0,318.930939,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Je n’ai pas pu tirer tout ça au clair... mais j’ai quand même appris deux ou trois choses :",
          DialogueId = 10107802,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "65.560059,-249.484375,178.057129,0.000056,-8.799653,106.200897,50.0,318.930939,false,Manual,8.0",
          GUID = "194DC744",
          NextDialogue = 10107822,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Explain02_End"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Couldn't get to the bottom of his story, but I did make some discoveries:",
          TalkActionId = {
            [1] = "100001:Explain02_Start",
            [2] = "200021:Explain01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC744"
        },
        [10107803] = {
          Camera = "1189.584106,604.688477,170.366699,0.000005,-4.598602,-147.196106,50.0,1392.620972,false,Manual,2.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Donc, c’est en fait un sanatorium ? Et ils croient bon de cacher ça... Les Charons vivent peut-être des vies dures, mais je n’ai jamais entendu dire qu’on leur interdisait de se soigner.",
          DialogueId = 10107803,
          FacialId = {
            [1] = "200021:Think01"
          },
          FinalCamera = "1200.925171,586.398438,170.366699,0.000005,-4.198578,-148.9953,50.0,1392.620972,false,Manual,2.0",
          GUID = "194DC76E",
          NextDialogue = 10107804,
          SpeakNpcId = 200021,
          Subtitle = "So, it's actually a sanatorium? What's there to hide about that... I mean it's false that Charons lead hard lives, but seeking medical help isn't forbidden.",
          TalkActionId = {
            [1] = "200021:Think_Loop"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC76E"
        },
        [10107804] = {
          Camera = "50.672363,-207.507812,149.698242,0.000068,-4.399932,103.400955,50.0,283.317688,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Sans doute. Mais j’ai appris que quelqu’un là-bas connaissait ton ami disparu, Hunt. Il souffrait d’une maladie ?",
          DialogueId = 10107804,
          ExStoryInfo = "Player",
          FinalCamera = "53.417969,-206.854492,149.698242,0.000068,-4.399932,103.600983,50.0,283.317688,false,Manual,8.0",
          GUID = "194DC798",
          NextDialogue = 10107805,
          SpeakNpcId = 100001,
          Subtitle = "...Right. I also learned that someone there knew your missing friend, Hunt. Was he ill?",
          TalkActionId = {
            [1] = "200021:Think_End",
            [2] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC798"
        },
        [10107805] = {
          Camera = "58.947021,52.992188,159.153809,0.000141,-3.399597,-114.527229,50.0,156.960281,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Hunt ? Il était en pleine forme juste avant sa disparition... Ces pensionnaires, de quoi sont-ils atteints exactement ?",
          DialogueId = 10107805,
          FacialId = {
            [1] = "200021:Sad01"
          },
          FinalCamera = "55.699463,54.472656,159.153809,0.000141,-3.399597,-114.526909,50.0,156.960281,false,Manual,5.0",
          GUID = "194DC7C2",
          NextDialogue = 10107806,
          SpeakNpcId = 200021,
          Subtitle = "Hunt was quite healthy before he disappeared... So, what illnesses do those lodgers have?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC7C2"
        },
        [10107806] = {
          Camera = "79.582275,-27.611328,142.373535,0.000048,-1.999777,128.673859,50.0,117.062347,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Je n’en sais rien. Ils refusent d’en parler... ou alors, plus probablement, c’est Henrik qui leur interdit de le faire.",
          DialogueId = 10107806,
          ExStoryInfo = "Player",
          FinalCamera = "77.580566,-29.212891,142.404785,0.000048,-1.999777,128.673859,50.0,117.062347,false,Manual,5.0",
          GUID = "194DC7EC",
          NextDialogue = 10107807,
          Scripts = "PlayAnimation{_delay{4},ActorId{100001},AnimationId{"Think_Start"},Duration{1}},\n",
          SpeakNpcId = 100001,
          Subtitle = "No idea. They refused to talk. Or more likely, Henrik forbids them to.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC7EC"
        },
        [10107807] = {
          Camera = "80.641602,238.647461,126.317871,0.000025,2.400033,-107.99295,50.0,344.498932,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Alors Henrik viserait les "malades" en particulier ? ... Tch. Voilà qui devient encore plus inquiétant. Je vais rajouter quelques verrous et dire à Fina de bien verrouiller la porte chaque jour. Mais pour Hunt... qu’est-ce que ça peut vouloir dire ?",
          DialogueId = 10107807,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "87.012207,236.456055,126.317871,0.000026,2.400019,-109.392738,50.0,344.498932,false,Manual,8.0",
          GUID = "194DC816",
          NextDialogue = 10107822,
          Scripts = "SEQ{\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Think_Start\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Is Henrik targeting the sick? ...Tsk, that's even more disturbing. I'm gonna have to add extra locks\nand remind Fina to lock the door all the time. Anyway, what exactly happened to Hunt...",
          TalkActionId = {
            [1] = "200021:Talk02_End",
            [2] = "\n100001:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC816"
        },
        [10107808] = {
          Camera = "55.737305,-204.126953,179.219727,0.000041,-12.200015,106.799362,35.000008,272.835724,false,Manual,3.5",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "C’est le bureau d’Henrik. Les pensionnaires m’ont dit que c’était une zone interdite, seul lui a le droit d’y entrer. La porte est solidement verrouillée, surveillée... et Henrik lui-même s’y trouvait. J’ai {性别:préféré|préférée} ne pas faire de geste imprudent.",
          DialogueId = 10107808,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "58.665283,-203.246094,173.740723,0.000045,-11.199952,107.399513,35.000008,272.835724,false,Manual,3.5",
          GUID = "194DC840",
          NextDialogue = 10107809,
          SpeakNpcId = 100001,
          Subtitle = "That's Henrik's office. The lodgers say it's off-limits — nobody but Henrik himself can get in.\nThe door is securely locked, and watched... Plus, Henrik himself is in there, I didn't want to be hasty.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC840"
        },
        [10107809] = {
          Camera = "407.116943,680.535156,112.411133,0.00012,-0.599486,-123.112785,50.0,874.564331,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Sage décision. Si Henrik perdait les pédales, impossible de prévoir ce qui se passerait.",
          DialogueId = 10107809,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "418.284668,673.166016,112.411133,0.00012,-0.599486,-123.512886,50.0,874.564331,false,Manual,8.0",
          GUID = "194DC86A",
          NextDialogue = 10107810,
          SpeakNpcId = 200021,
          Subtitle = "Smart decision. If Henrik lost it, who knows what might happen.",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "\n200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5.5,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC86A"
        },
        [10107810] = {
          Camera = "49.244873,-76.416016,137.729492,0.000063,-0.800129,106.602776,50.000008,152.069763,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Mais cette pièce n’a pas qu’une seule entrée. En quittant les lieux, j’ai {性别:observé|observée} le bâtiment... Il semble que la salle soit reliée à la <H>cheminée</> du toit.",
          DialogueId = 10107810,
          ExStoryInfo = "Player",
          FinalCamera = "49.244873,-76.416016,141.102051,0.000064,-1.800171,106.602867,55.0,152.069763,false,Manual,5.0",
          GUID = "194DC894",
          NextDialogue = 10107811,
          SpeakNpcId = 100001,
          Subtitle = "But the locked door isn't the only entrance to that room. When I left, I scoped out the house...\nIt appears the room connects to the chimney on the roof.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "\n200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC894"
        },
        [10107811] = {
          Camera = "34.452881,118.300781,137.70752,0.000011,1.799891,-104.40377,35.000008,222.029785,false,Manual,3.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Même ça, tu l’as remarqué... Décidément, j’ai bien fait de m’associer avec toi. Il ne nous reste qu’à trouver un moment où Henrik sera absent...",
          DialogueId = 10107811,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "37.026123,117.637695,137.92627,0.000011,1.799891,-104.40377,35.000008,222.029785,false,Manual,3.0",
          GUID = "194DC8BE",
          NextDialogue = 10107822,
          SpeakNpcId = 200021,
          Subtitle = "That's impressive! I'm so glad I found you to team up with. So, we just need to find a time when Henrik isn't around...",
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "200021:AgreeHead"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC8BE"
        },
        [10107812] = {
          Camera = "542.043457,-395.053711,99.608398,0.0,0.0,139.199432,30.0,357.262421,false,Manual,3.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "En discutant avec les pensionnaires, j’ai appris qu’il a une habitude particulière : chaque 20 du mois, à vingt heures, il sort du manoir.",
          DialogueId = 10107812,
          ExStoryInfo = "Player",
          FinalCamera = "559.420654,-374.921875,99.608398,0.0,0.0,139.199432,30.0,616.33313,false,Manual,3.0",
          GUID = "194DC8E8",
          NextDialogue = 10107813,
          SpeakNpcId = 100001,
          Subtitle = "I chatted with the lodgers there and dug out some intel: Henrik has a peculiar routine—\nHe always leaves the house at 5 PM on the 20th of every month.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC8E8"
        },
        [10107813] = {
          ContentFR = "Parfait. Autrement dit, c’est notre fenêtre d’action pour l’observer... ou nous introduire dans la Maison d’Hypnos.",
          DialogueId = 10107813,
          GUID = "194DC912",
          NextDialogue = 10107822,
          Scripts = "SEQ{\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Think_Start\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Great! That's our window of opportunity to investigate him. We need to figure out how to secretly follow him...\nor sneak into the Hypnos' House...",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101078/194DC912"
        },
        [10107814] = {
          Camera = "14.019775,37.094727,157.077148,0.000169,-2.399801,-97.506111,50.0,127.094246,false,Manual,5.0",
          ContentFR = "... Bien. Alors le plan est clair : le 20 de ce mois, pendant qu’Henrik sera dehors, nous tenterons de pénétrer dans son bureau verrouillé par la cheminée. Personne n’y a accès à part lui, nous ne serons pas découverts.",
          DialogueId = 10107814,
          FinalCamera = "14.019775,37.094727,157.077148,0.00017,-2.599795,-98.306206,55.0,127.094246,false,Manual,5.0",
          GUID = "194DC93C",
          NextDialogue = 10107815,
          SpeakNpcId = 200021,
          Subtitle = "...So, here's our plan: On the 20th of this month, while Henrik is out, we'll try and get into the locked office through the chimney. That room is exclusive to Henrik, so we won't be noticed.",
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC93C"
        },
        [10107815] = {
          Camera = "35.024658,132.529297,133.211426,0.000002,3.599892,-103.6017,50.0,237.958099,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Tu as l’esprit affûté, {nickname}. J’en viendrais presque à envisager un partenariat à long terme. D’ailleurs, puisque vous avez réussi à éliminer le monstre dans la fosse, tu dois avoir de solides compétences au combat rapproché, non ?",
          DialogueId = 10107815,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "41.333984,130.958008,133.211426,0.000002,3.599892,-105.001938,50.0,237.958099,false,Manual,8.0",
          GUID = "194DC966",
          NextDialogue = 10107816,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_End\"},Duration{1}},\nPlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
