          },
          NextDialogue = 10108004,
          SpeakNpcId = 100005,
          Subtitle = "Let's hear the worse one first.",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE83E"
        },
        [10108004] = {
          ContentFR = "L’unité restée sur l’Île du Purgatoire a fouillé les environs pendant trois jours, mais elle n’a trouvé aucune trace de {性别:ce garçon|cette fille} qui accompagnait le n° 0.",
          DialogueId = 10108004,
          ExStoryInfo = "Player",
          GUID = "194DE868",
          NextDialogue = 10108005,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100006},AnimationId{\"Shock_Start\"},Duration{1}},\nPlayAnimation{_delay{4.5},ActorId{100006},AnimationId{\"Shock_End\"},Duration{1}}\n}",
          SpeakNpcId = 100006,
          Subtitle = "The unit left on Purgatorio Island has been searching the area for three days, but they've yet to find any trace of that {性别:boy|girl} who was with No. 0.",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE868"
        },
        [10108005] = {
          Camera = "-92.738281,622.456055,9.740234,0.0001,-14.199403,67.99823,35.000008,179.265518,false,Manual,3.175064",
          ContentFR = "Nous avons immédiatement exploré les eaux voisines après sa chute de la falaise. En théorie, {性别:il, mort ou vif|elle, morte ou vive}, n’aurait pas pu dériver très loin... sauf si...",
          DialogueId = 10108005,
          ExStoryInfo = "Player",
          GUID = "194DE892",
          NextDialogue = 10108006,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100006},AnimationId{\"Explain01_Start\"},Duration{1}},\nPlayAnimation{_delay{3.5},ActorId{100006},AnimationId{\"Explain01_End\"},Duration{1}},\nPlayAnimation{_delay{3},ActorId{100006},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100006,
          Subtitle = "We searched the nearby waters immediately after {性别:he|she} fell off the cliff. Theoretically speaking, {性别:he|she} shouldn't have drifted far. Unless...",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE892"
        },
        [10108006] = {
          Camera = "-46.48291,518.056641,12.158203,0.000022,5.999481,-87.199181,25.000002,1007.337402,false,Manual,1.2",
