        [10108318] = {
          Camera = "137.707031,-41.043945,135.595703,0.00014,3.398955,147.20549,35.0,100000.0,false,Disable,2.8",
          Content = "别装傻。",
          DialogueId = 10108318,
          GUID = "194E1B44",
          NextDialogue = 10108319,
          SpeakNpcId = 200021,
          Subtitle = "What is Resonance? I'm not following.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B44"
        },
        [10108319] = {
          Camera = "635.107422,652.389893,188.712891,0.000178,-5.600987,-134.588898,50.0,100000.0,false,Disable,2.8",
          Content = "在废矿的时候，我就感到有什么在试图“引导”我的行动，这和传说中的“和鸣之力”很像……只是那股力量细微很多，没那么容易察觉。",
          DialogueId = 10108319,
          Duration = 1.5,
          FinalCamera = "755.806641,504.501465,188.712891,0.000165,-5.600953,-146.790039,50.0,100000.0,false,Disable,2.8",
          GUID = "194E1B6E",
          NextDialogue = 10108320,
          Scripts = "PlayAnimation{_delay{4},ActorId{200021},AnimationId{"Talk01_End"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B6E"
        },
        [10108320] = {
          Camera = "195.578125,-68.083252,108.217285,0.000174,6.198751,154.617676,35.0,150.691696,false,Manual,4.0",
          Content = "在场的另外两个小姑娘都不是“骸”，那就只能是你了。刚刚，我更加确信了这点。",
          DialogueId = 10108320,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "193.171875,-73.229248,108.217285,0.000174,6.198751,154.617676,35.0,150.691696,false,Manual,4.0",
          GUID = "194E1B6F",
          NextOptions = {
            [1] = 10108321
          },
          SpeakNpcId = 200021,
          Subtitle = "Just some rumours I've heard. They say the last person with that power wreaked havoc across the Empire.\nYour power, though much weaker, is very similar to the legendary power of Resonance.",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B6F"
        },
        [10108321] = {
          Content = "……你又是从哪儿听说的？",
          DialogueId = 10108321,
          GUID = "10108321",
          NextDialogue = 10108322,
          Subtitle = "I felt it back in the pit. You didn't intend to, but I felt a strong force — your effort to impact me with your will."
        },
        [10108322] = {
          Camera = "140.34375,35.236084,169.851074,0.00014,-4.801233,169.202744,50.0,100000.0,false,Disable,2.8",
          Content = "…………",
          DialogueId = 10108322,
          GUID = "194E1B98",
          NextDialogue = 10108323,
          SpeakNpcId = 200021,
          Subtitle = "Noted. Thanks for the heads-up.",
          TalkActionId = {
            [1] = "200021:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B98"
        },
        [10108323] = {
          Camera = "-122.808594,351.115967,244.380371,0.000146,-18.200684,-67.394974,50.0,100000.0,false,Disable,2.8",
          Content = "听过一些坊间传闻而已，海伯利亚十几年前就出过一个拥有“和鸣之力”的家伙。你的力量……虽然细微，但和传说中的和鸣之力很像。",
          DialogueId = 10108323,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "-115.972656,311.899902,232.541016,0.000153,-18.400692,-66.794907,50.0,100000.0,false,Disable,2.8",
          GUID = "194E1B99",
          NextDialogue = 10108324,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"}}",
          SpeakNpcId = 200021,
          Subtitle = "Don't play dumb.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B99"
        },
        [10108324] = {
          Camera = "47.087891,110.528076,141.211914,0.000135,-7.000274,-84.190117,50.0,100000.0,false,Disable,2.8",
          Content = "你说……和鸣之力是一种“引导”的力量？",
          DialogueId = 10108324,
          ExStoryInfo = "Player",
          GUID = "194E1B9A",
          NextDialogue = 10108325,
          SpeakNpcId = 100001,
          Subtitle = "Back in the pit, I felt a strong force — your effort to impact me with your will. What else could it be but the legendary Resonance?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9A"
        },
        [10108325] = {
          Camera = "144.796875,-61.763916,100.844727,0.000195,12.0,147.402008,35.0,282.419678,false,Manual,15.0",
          Content = "嗯，“引导”——或者极端一点说，“操控”。",
          DialogueId = 10108325,
          FinalCamera = "140.300781,-68.811523,100.844727,0.000195,12.0,147.402008,35.0,282.419678,false,Manual,15.0",
          GUID = "194E1B9B",
          NextDialogue = 10108326,
          SpeakNpcId = 200021,
          Subtitle = "...Where did you hear about it?",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9B"
        },
        [10108326] = {
          Camera = "95.589844,65.102783,147.506836,0.000202,2.999286,175.006119,35.0,138.980881,false,Manual,5.0",
          Content = "你没意识到吗？你的魔法会影响身边的“骸”，增幅他们的力量——甚至，极端情况下，让他们按照你的意志行动。",
          DialogueId = 10108326,
          Duration = 1.5,
          GUID = "194E1B9C",
          NextDialogue = 10108327,
          SpeakNpcId = 200021,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9C"
        },
        [10108327] = {
          Camera = "191.621094,-89.93457,109.277344,0.000199,6.198478,148.808563,35.0,401.024139,false,Manual,11.157635",
          Content = "当然，你如今的力量很微弱，还远远到不了那种程度。",
          DialogueId = 10108327,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194E1B9D",
          NextDialogue = 10108328,
          SpeakNpcId = 200021,
          Subtitle = "Just some rumours I've heard. They say the last person with that power wreaked havoc across the Empire. Your power, though much weaker, is very similar to that legendary power of Resonance.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9D"
        },
        [10108328] = {
          Camera = "32.6875,29.662109,128.611328,0.000209,-4.201447,-62.396164,25.0,65.99147,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          Content = "（……操控？该不会是那个时候，和贝蕾——）",
          DialogueId = 10108328,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "18.273438,57.231689,130.894531,0.000209,-4.201447,-62.396164,35.0,130.879471,false,Manual,5.0",
          GUID = "194E1B9E",
          NextOptions = {
            [1] = 10108329,
            [2] = 10108332
          },
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "If your power was noticed by the wrong people, you could get in trouble.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9E"
        },
        [10108329] = {
          Content = "引导和操控他人……听起来很危险。 ",
          DialogueId = 10108329,
          GUID = "10108329",
          ImprPlusId = 1007,
          NextDialogue = 10108330,
          Subtitle = "Noted. Thanks for the heads-up."
        },
        [10108330] = {
          Camera = "162.910156,-71.224854,104.924805,0.000222,9.998556,149.005325,35.0,100.0,false,Manual,11.0",
          Content = "嗯。所以我说尽量少在人前显露，以免惹上不必要的麻烦。",
          DialogueId = 10108330,
          GUID = "194E1B9F",
          NextDialogue = 10108331,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9F"
        },
        [10108331] = {
          Camera = "528.824219,335.385986,-75.997559,0.000308,13.795157,-147.790375,35.0,264.565613,false,Manual,5.0",
          Content = "毕竟……上个拥有这种力量的家伙，可是把整个帝国搅得血雨腥风的，下场也凄惨得很，被吊死在迪斯玛尼亚的广场上。",
          DialogueId = 10108331,
          FinalCamera = "528.824219,335.385986,-26.985352,0.000309,9.999997,-147.789948,35.0,264.565613,false,Manual,5.0",
          GUID = "194E1C13",
          NextOptions = {
            [1] = 10108335
          },
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C13"
        },
        [10108332] = {
          Content = "引导和操控他人……听起来很好玩。 ",
          DialogueId = 10108332,
          GUID = "10108332",
          ImprPlusId = 1010,
          NextDialogue = 10108333
        },
        [10108333] = {
          Camera = "191.621094,-89.93457,109.277344,0.000199,6.198478,148.808563,35.0,401.024139,false,Manual,11.157635",
          Content = "唉，你这外乡人是真的觉得自己命很大啊。",
          DialogueId = 10108333,
          ExStoryInfo = "Player",
          GUID = "194E1C14",
          NextDialogue = 10108334,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C14"
        },
        [10108334] = {
          Camera = "471.207031,400.690186,-72.977539,0.000308,13.795151,-140.000015,35.0,625.0,false,Manual,5.0",
          Content = "上个拥有这种力量的家伙，可是把整个帝国搅得血雨腥风的，下场也凄惨得很。你也不想被吊死在迪斯玛尼亚的广场上吧？",
          DialogueId = 10108334,
          FinalCamera = "528.824219,335.385986,-75.997559,0.000308,13.795157,-147.790375,35.0,264.565613,false,Manual,5.0",
          GUID = "194E1C15",
          NextOptions = {
            [1] = 10108335
          },
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C15"
        },
        [10108335] = {
          Content = "好吧，谢谢你的忠告。我会谨慎使用和鸣之力。",
          DialogueId = 10108335,
          GUID = "10108335",
          NextDialogue = 10108336
        },
        [10108336] = {
          Camera = "662.0625,-196.700195,127.136719,0.000301,-2.808314,161.416794,35.0,1282.889648,false,Manual,11.157635",
          Content = "好了，太阳也快下山了。回去吧，待会儿还有场“硬仗”要打。",
          DialogueId = 10108336,
          FinalCamera = "734.255859,-220.97583,130.874023,0.000301,-2.808314,161.416794,35.0,1282.889648,false,Manual,11.157635",
          GUID = "194E1C16",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C16"
        },
        [10108337] = {
          Camera = "-158.597656,636.088623,270.316406,0.000033,-15.400197,-73.59948,50.0,340.220642,false,DoNotOverride,2.0",
          ContentFR = "Pas mal, tes compétences au combat s’améliore plus vite que je ne pensais. Si vite, tu deviens déjà {性别:un Chasseur de Phoxène|une Chasseuse de Phoxène} autonome. Ah, les jeunes d’aujourd'hui ont vraiment du talent.",
          DialogueId = 10108337,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-173.53125,686.955078,284.919434,0.000033,-15.40019,-73.599449,50.0,340.220642,false,DoNotOverride,2.0",
          GUID = "194E1C17",
          NextDialogue = 10108338,
          Scripts = "PlayAnimation{_delay{6.2},ActorId{200021},AnimationId{"Talk03_Start"},Duration{1}}\n",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C17"
        },
        [10108338] = {
          Camera = "-5360.410156,-7622.796875,10140.634766,0.000062,-10.601491,16.198198,15.000005,340.220642,false,DoNotOverride,2.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Allez, le soleil se couche. Retour à Givrelac pour retrouver le Petit Champi. J’espère que tout s’est bien passé de son côté.",
          DialogueId = 10108338,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "-5071.761719,-7538.956055,10084.37793,0.000067,-10.601498,16.198914,15.000005,340.220642,false,DoNotOverride,2.0",
          GUID = "194E1C18",
          SpeakNpcId = 200021,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C18"
        },
        [10108401] = {
          Content = "说起来，你的父母是什么人？",
          DialogueId = 10108401,
          Duration = 4,
          GUID = "194E298A",
          NextDialogue = 10108402,
          SpeakNpcId = 200021,
          Subtitle = "By the way, what do your parents do?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E298A"
        },
        [10108402] = {
          Content = "怎么突然问这个？",
          DialogueId = 10108402,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E29B4",
          NextDialogue = 10108403,
          SpeakNpcId = 100001,
          Subtitle = "Why do you ask?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E29B4"
        },
        [10108403] = {
          Content = "当然是因为和鸣之力很特别啊。卡戎之民的魔法，大多与血脉有关。没准你就大有来头。",
          DialogueId = 10108403,
          Duration = 4,
          GUID = "194E29DE",
          NextDialogue = 10108404,
          SpeakNpcId = 200021,
          Subtitle = "Well, because the power of Resonance is quite special, isn't it? The magical abilities among Charons often relate to their bloodline. Who knows, you might be from some prestigious background.",
          VoiceName = "voice/$Locale$/story/1002/101084/194E29DE"
        },
        [10108404] = {
          Content = "其实我也不知道……我从记事起就和贝蕾相依为命。其他的，就不太清楚了。",
          DialogueId = 10108404,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A08",
          NextDialogue = 10108405,
          SpeakNpcId = 100001,
          Subtitle = "Truth is, I don't know... It's always been just Berry and me since my earliest memories. I don't remember any other family members.",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A08"
        },
        [10108405] = {
          Content = "这样啊……",
          DialogueId = 10108405,
          Duration = 4,
          GUID = "194E2A32",
          NextDialogue = 10108406,
          SpeakNpcId = 200021,
          Subtitle = "Ah, I see...",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A32"
        },
        [10108406] = {
          Content = "哎，我说，那如果以后你发现自己其实是什么亲王啊公爵啊流落在外的私生子，可别把我这个贫贱之交忘了哦。",
          DialogueId = 10108406,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A5C",
          NextDialogue = 10108407,
          SpeakNpcId = 200021,
          Subtitle = "Hey, if you ever find out you're actually some prince or duke's secret love child, don't forget about this poor old friend of yours, alright?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A5C"
        },
        [10108407] = {
          Content = "哈，最好真的像你说的那样。",
          DialogueId = 10108407,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A86",
          SpeakNpcId = 100001,
          Subtitle = "Hah, that would be nice, wouldn't it?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A86"
        },
        [10108501] = {
          Camera = "-42.287598,160.495117,57.3396,0.000126,10.999991,-81.999931,30.0,334.989777,false,Manual,1.27223",
          ContentFR = "Enfin !",
          DialogueId = 10108501,
          FacialId = {
            [1] = "200064:Happy01"
          },
          FinalCamera = "13.111328,278.30957,57.3396,0.000129,10.799983,-83.399635,30.0,351.555328,false,Manual,1.27223",
          GUID = "194E39F2",
          LookAt = {
            [1] = "100001:n(200064)",
            [2] = "200021:n(200064)"
          },
          NextDialogue = 10108502,
          RelatedWikiId = {
            [1] = 201009,
            [2] = 201005,
            [3] = 201006,
            [4] = 405002
          },
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}},\nPlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_nvzhu_aote_walk\"},PlayAs2D{true}},\nSEQ{\nMoveTo{ActorId{100001},TargetPoint{\"P10108509\"},MoveSpeed{30}},\nPlayAnimation{ActorId{100001},AnimationId{\"Confident_Start\"},Duration{0.1}}\n},\nMoveTo{ActorId{200021},TargetPoint{\"P10108508\"},MoveSpeed{35}},\nPlayNormalSound{_delay{4.5},EventPath{\"event:/sfx/common/story/01/talk_bai_from_garbage_can\"},PlayAs2D{true}},\nPlayAnimation{_delay{4.5},ActorId{200064},AnimationId{\"Bai_SpecialConfident_Start\"},Duration{1}},\nCameraMoveTo{_delay{6.1},TargetPosition{\"13.111328,278.30957,57.3396,0.000126,10.999,-81.999947,30.0,235.618515,false,Manual,2.41798\"},duration{1}}\n}",
          SpeakNpcId = 200064,
          Subtitle = "Finally!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101085/194E39F2"
        },
        [10108502] = {
          Camera = "-115.567871,-338.226562,281.567627,0.000205,-25.200125,66.302895,40.000011,546.789001,false,Manual,2.0",
          ContentFR = "Tu es vraiment insupportable l’Étranger ! Me faire monter la garde ici... Les grands talents de ce Roi Démon sont faits pour mener des chasses, pas pour surveiller cet homme morose !",
          DialogueId = 10108502,
          FacialId = {
            [1] = "200064:Doubt01"
          },
          FinalCamera = "-99.011719,-300.50293,244.98291,0.000237,-21.799927,66.303619,40.000011,483.54599,false,Manual,2.0",
          GUID = "194E3A1C",
          LookAt = {
            [1] = "200064:n(200021)"
          },
          NextDialogue = 10108503,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200064},AnimationId{\"SpecialConfident_End\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{200064},AnimationId{\"Talk03_Start\"},Duration{1}},\nPlayAnimation{_delay{4},ActorId{200064},AnimationId{\"Talk03_End\"},Duration{1}},\nPlayAnimation{ActorId{200064},AnimationId{\"Angry01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200064,
          Subtitle = "You're such a pest, Outsider! Making me stand watch here... This Demon King's great talents are meant for leading hunts, not keeping tabs on that gloomy man!",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3A1C"
        },
        [10108503] = {
          Camera = "-98.271973,73.517578,107.652588,0.000086,12.605715,-48.246983,50.0,203.457687,false,Manual,8.0",
          ContentFR = "C’est parce que vous avez un don particulier pour agir en toute discrétion, Ô Roi Démon. Regardez-nous, nous sommes si grands et maladroits que Henrik nous repérerait en un clin d’œil.",
          DialogueId = 10108503,
          FacialId = {
            [1] = "200021:Smile02",
            [2] = "100001:Smile02"
          },
          FinalCamera = "-97.125,82.003906,106.376465,0.000081,12.805723,-50.447262,50.0,211.465363,false,Manual,8.0",
          GUID = "194E3A46",
          NextDialogue = 10108504,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{3.3}},\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_End\"},Duration{1.6}},\nPlayAnimation{ActorId{200021},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "That's because, you have a special gift for acting by stealth, "Your Majesty." Look at us, all big and clumsy, we'd be spotted by Henrik in no time.",
          TalkActionId = {
            [1] = "200064:Bai_Idle"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3A46"
        },
        [10108504] = {
          Camera = "28.857422,-61.823242,137.124268,0.000146,-17.4002,77.194801,50.0,180.819702,false,Manual,8.0",
          ContentFR = "Hum, tu sais flatter mon génie... Attends ! Mais tu veux juste dire que je suis petite, n’est-ce pas !",
          DialogueId = 10108504,
          FacialId = {
            [1] = "200064:Happy02"
          },
          FinalCamera = "32.961914,-44.213867,131.525879,0.000162,-17.200184,76.594582,50.0,160.226791,false,Manual,8.0",
          GUID = "194E3A70",
          NextDialogue = 10108505,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200064},AnimationId{\"Think_Start\"},Duration{5.5}},\nPARA{\nPlayAnimation{ActorId{200064},AnimationId{\"Angry01_Start\"},Duration{0.1}},\nPlayFacial{ActorId{200064},FacialId{\"Angry01\"}},\n}\n}",
          SpeakNpcId = 200064,
          Subtitle = "Hmph, smart of you to have recognised my greatness — wait! That's just a roundabout way of calling me short!!",
          TalkActionId = {
            [1] = "200021:Explain02_End",
            [2] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3A70"
        },
        [10108505] = {
          Camera = "38.050293,248.716797,38.96167,0.000147,18.199257,-84.5942,50.000008,342.942749,false,Manual,5.0",
          ContentFR = "Non, non ! Mais comment ! Vous êtes la plus grande et la plus imposante ! Les portes de Givrelac ont été construites spécialement pour vous...",
          DialogueId = 10108505,
          FacialId = {
            [1] = "100001:Smile01",
            [2] = "\n200021:Smile02",
            [3] = "\n200064:None"
          },
          GUID = "194E3A9A",
          LookAt = {
            [1] = "200021:n(200064)"
          },
          NextDialogue = 10108506,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{2}},\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "No, not at all. You're the tallest and mightiest, the towering Icelake gates were practically built for you—",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3A9A"
        },
        [10108506] = {
          Camera = "60.727051,51.9375,152.414551,0.000019,2.799865,-98.874046,50.0,131.065063,false,Manual,5.0",
          ContentFR = "Chut ! ... Il sort.",
          DialogueId = 10108506,
          FacialId = {
