          },
          NextDialogue = 10108507,
          Scripts = "PARA{\nLookAt{_delay{0.5},LookAtDescription{\"200021:n(200005)\"}},\nPlayNormalSound{_delay{1.5},EventPath{\"event:/sfx/common/story/01/open_door\"},PlayAs2D{false}},\nMoveTo{_delay{2},ActorId{200005},TargetPoint{\"P10108513\"},MoveSpeed{50},Visibility{\"Show\"}},\nCameraMoveTo{_delay{1},TargetPosition{\"-619.688477,9.079102,95.974609,0.000186,6.999994,-5.877481,50.0,659.644531,false,Manual,1.940181\"},duration{0}},\nCameraMoveTo{_delay{1.1},TargetPosition{\"-569.95166,3.961914,135.299072,0.000186,6.0,-5.87748,55.0,1300.198608,false,Manual,3\"},blend{\"easeOutQuad\"},duration{3.5}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Shh! ...He's coming out.",
          TalkActionId = {
