          VoiceName = "voice/$Locale$/story/1002/101085/194E3AC4"
        },
        [10108507] = {
          Camera = "2583.134277,-2696.768555,147.770508,0.000162,-0.599848,131.59877,75.0,546.963013,false,Manual,5.763931",
          ContentFR = "C’est pile vingt heures ! Si jamais il change de métier, il pourrait directement faire horloge humaine sur la place !",
