            [2] = "200064:n(200005)",
            [3] = "200021:n(200005)"
          },
          NextDialogue = 10108508,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.1},TargetPosition{\"-285.275879,187.663086,153.557129,0.000161,-2.999962,-46.199238,40.0,414.905426,false,Manual,5.0\"},duration{0}},\nCameraMoveTo{_delay{4.2},TargetPosition{\"-290.962402,182.308594,125.536133,0.00016,-0.399771,-46.798653,40.0,414.905426,false,Manual,5.0\"},duration{6}},\nSEQ{\nSetLocation{_delay{3.9},ActorId{200064},TargetPoint{\"P10108511\"},Visibility{\"Show\"}},\nMoveTo{ActorId{200064},TargetPoint{\"P10108506\"},MoveSpeed{250},Visibility{\"Show\"}},\nPlayAnimation{ActorId{200064},AnimationId{\"Bai_Idle\"},Duration{1}}\n},\nSEQ{\nSetLocation{ActorId{200005},TargetPoint{\"P10108512\"},Visibility{\"Show\"}},\nMoveTo{ActorId{200005},TargetPoint{\"P10108507\"},MoveSpeed{90},Visibility{\"Hide\"}}\n}\n}",
          SpeakNpcId = 200064,
          Subtitle = "Right on 5 o'clock! If he ever changes careers again, he could offer time-telling services in the town square!",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "100001:p(-90)",
            [2] = "200021:p(-150)"
          },
          VoiceName = "voice/$Locale$/story/1002/101085/194E3AEE"
        },
        [10108508] = {
          Camera = "116.26709,-175.134766,180.025146,0.000202,-11.999685,135.292267,50.0,217.784042,false,Manual,8.0",
          ContentFR = "... On suit le plan initial. Snow et moi, on suit Henrik, et l’Étranger, tu passes par la cheminée pour entrer dans son bureau. On se retrouve ensuite devant chez toi.",
          DialogueId = 10108508,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "109.785156,-183.363281,180.025146,0.000209,-11.399647,132.891342,50.0,217.784042,false,Manual,8.0",
          GUID = "194E3B18",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10108509,
          Scripts = "PARA{\nSetLocation{ActorId{100001},TargetPoint{\"P10108515\"},Visibility{\"Show\"}},\nSetLocation{ActorId{200064},TargetPoint{\"P10108506\"},Visibility{\"Hide\"}},\nSetRotation{SetRotationDescription{\"100001:n(200021)\"}},\nTurnTo{_delay{0.5},TurnToDescription{\"200021:n(100001)\"}},\nPlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"Talk02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "...Stick to the original plan. Snow and I will tail Henrik, and Outsider, you sneak into Henrik's office through the chimney.\nWe'll meet up at your doorstep afterwards.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3B18"
        },
        [10108509] = {
          Camera = "-241.65918,-80.399414,95.142334,0.000212,10.400014,6.301726,40.000011,305.268982,false,Manual,8.0",
