        [10108603] = {
          Camera = "-420.242188,1030.288574,153.051758,0.000451,-5.40005,-65.79657,35.000008,393.519836,false,Manual,5.0",
          ContentFR = "Tu as vu ça ? Henrik vient de jeter quelque chose...",
          DialogueId = 10108603,
          FacialId = {
            [1] = "200061:Think01",
            [2] = "200002:Confident01"
          },
          FinalCamera = "-420.242188,1030.288574,153.051758,0.000449,-5.40005,-66.396866,37.0,393.519836,false,Manual,5.0",
          GUID = "194E4A5A",
          LookAt = {
            [1] = "200002:n(200002)",
            [2] = "200061:n(200061)"
          },
          NextDialogue = 10108604,
          Scripts = "PARA{\nPlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}},\nSetLocation{ActorId{200005},TargetPoint{\"P101087\"},Visibility{\"Hide\"}},\n}",
          SpeakNpcId = 200002,
          Subtitle = "Did you see that? Henrik just threw something in there...",
          TalkActionId = {
            [1] = "200061:Think_Start"
          },
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101086/194E4A5A"
        },
        [10108604] = {
          Camera = "-353.188477,838.447754,93.205078,0.00045,2.199717,-57.194374,35.000008,200.357056,false,Manual,4.0",
          Content = "这一定就是他的惊天大秘密！小仆从，你在这里守着，我来把它捞出来——",
          DialogueId = 10108604,
          Duration = 7,
          FacialId = {
            [1] = "200002:Shock01",
            [2] = "200061:None"
          },
          GUID = "194E4A84",
          NextDialogue = 10108605,
          Scripts = "PARA{\nPlayAnimation{_delay{1.5},ActorId{200002},AnimationId{\"Shock_Start\"},Duration{1}},\nPlayAnimation{_delay{4.7},ActorId{200002},AnimationId{\"Shock_End\"},Duration{1}},\nLookAt{_delay{5.2},LookAtDescription{\"200002:p(P10108607)\"}},\nMoveTo{_delay{6},_click{true},ActorId{200002},TargetPoint{\"P10108607\"},MoveSpeed{220},Visibility{\"Show\"}},\nLookAt{_delay{6.8},LookAtDescription{\"200061:n(200002)\"}},\nCameraMoveTo{_delay{6.7},TargetPosition{\"114.113281,475.86377,111.717285,0.000451,-0.000273,151.003693,35.0,297.982849,false,Manual,1.8\"},duration{0}},\nCameraMoveTo{_delay{6.8},TargetPosition{\"116.96875,481.013184,111.717285,0.000451,-0.000273,149.999954,35.0,370.722229,false,Manual,1.8\"},duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "This has gotta be his horrible secret! You stay here, I'll go fish it out—",
          TalkActionId = {
            [1] = "200002:Talk02_End",
            [2] = "200061:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101086/194E4A84"
        },
        [10108605] = {
          Camera = "-294.443359,996.944824,136.692383,0.00046,2.199457,-90.197632,50.0,334.402466,false,Manual,8.0",
          DialogueId = 10108605,
          GUID = "194E4A85",
          LookAt = {
            [1] = "200061:n(200002)",
            [2] = "200002:p(P10108607)"
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{2},TargetPosition{\"835.770508,-296.196289,342.833984,0.000465,4.999445,129.995544,17.854052,671.069458,false,DoNotOverride,1.6\"},duration{0}},\nCameraMoveTo{_delay{2.1},TargetPosition{\"835.770508,-296.196289,1176.641113,0.000465,4.999445,129.995544,17.854052,671.069458,false,DoNotOverride,1.6\"},blend{\"easeInOutQuad\"},duration{6}},\nMoveTo{_delay{1.5},ActorId{200061},TargetPoint{\"P10108607\"},MoveSpeed{220},Visibility{\"Show\"}},\nMoveTo{_delay{1.8},ActorId{200002},TargetPoint{\"P10108605\"},MoveSpeed{210},Visibility{\"Show\"}},\nPlayNormalSound{_delay{4},EventPath{\"event:/sfx/common/story/01/bai_enter_water\"},PlayAs2D{false}}\n}",
          Subtitle = "Snow, get back here. This water is freezing, even for a Charon."
        },
        [10108606] = {
          DialogueId = 10108606,
          DisableMouth = 1,
          GUID = "194E4A86",
          Scripts = "PARA{\nPlayNormalSound{EventPath{\"event:/sfx/common/story/01/bai_enter_water\"},PlayAs2D{false}},\nSEQ{\nSetLocation{ActorId{200061},TargetPoint{\"P10108703\"},Visibility{\"Show\"}},\nSetRotation{SetRotationDescription{\"200061:p(30)\"}}\n},\nSEQ{\nSetLocation{ActorId{200002},TargetPoint{\"P10108707\"},Visibility{\"Show\"}},\nSetRotation{SetRotationDescription{\"200061:p(-120)\"}}\n}\n}",
          Subtitle = "Nah, this is nothing for us Luno... I'm going in!"
        },
        [10108701] = {
