        [10108702] = {
          Camera = "273.503906,-374.988281,160.387207,0.000097,-24.6012,119.005333,50.0,237.679596,false,Manual,8.0",
          ContentFR = "Maintenant vient le moment le plus palpitant...",
          DialogueId = 10108702,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "194E5AC2",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "\n200002:n(100001)"
          },
          NextDialogue = 10108703,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{"Confident_Start"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Now comes the most exciting moment...",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5AC2"
        },
        [10108703] = {
          Camera = "316.876953,-129.027344,62.571777,0.000082,0.799904,-159.144867,50.0,143.733337,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "« Après mille péripéties, le Roi Démon et son fidèle serviteur ont enfin récupéré le précieux trésor des eaux profondes. Le cœur rempli d’espoir, ils ouvrent la boîte... et découvrent »—",
          DialogueId = 10108703,
          ExStoryInfo = "Player",
          FinalCamera = "314.959961,-129.743164,62.599609,0.000082,0.799883,-159.544861,57.0,143.733337,false,Manual,5.0",
          GUID = "194E5AEC",
          LookAt = {
            [1] = "200002:p(P10108701)"
          },
          NextDialogue = 10108704,
          Scripts = "PARA{\nMoveTo{ActorId{100001},TargetPoint{\"P10108703\"},MoveSpeed{5},Visibility{\"Hide\"}},\nSEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Talk03_Start\"},Duration{4.7}},\nPlayAnimation{ActorId{200002},AnimationId{\"Confident_Start\"},Duration{2.6}},\nPlayAnimation{ActorId{200002},AnimationId{\"Confident_End\"},Duration{1.3}},\nPlayAnimation{ActorId{200002},AnimationId{\"Talk01_Start\"},Duration{2.3}},\nPlayAnimation{ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200002,
          Subtitle = "Through great trials and hardships, the Demon king and her minion finally retrieved a precious treasure from the deep waters. With hopeful hearts and anxious breaths, they opened the box, only to find—",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/101087/194E5AEC"
        },
        [10108704] = {
          Camera = "742.229492,179.731445,413.833496,0.000161,-34.997704,-137.795181,30.0,317.800873,false,DoNotOverride,5.0",
          ContentFR = "Quoi ! Vide !",
          DialogueId = 10108704,
          FacialId = {
            [1] = "100001:Shock02",
            [2] = "200002:Shock02"
          },
          GUID = "194E5B16",
          LookAt = {
            [1] = "100001:p(P10108701)"
          },
          NextDialogue = 10108705,
          Scripts = "PARA{\nSetLocation{ActorId{200002},TargetPoint{\"P10108702\"},Visibility{\"Show\"}},\nSetLocation{ActorId{100001},TargetPoint{\"P10108703\"},Visibility{\"Show\"}},\nMoveTo{_delay{1.7},ActorId{100001},TargetPoint{\"P10108704\"},MoveSpeed{50},Visibility{\"Show\"}},\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}},\n\n}",
          SpeakNpcId = 200002,
          Subtitle = "Huh?! It's empty!",
          TalkActionId = {
            [1] = "200002:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B16"
        },
        [10108705] = {
          ContentFR = "Une boîte finement sculptée, lourde à tenir. Mais comme dit Snow, elle est vide.",
          DialogueId = 10108705,
          DisableMouth = 1,
          GUID = "194E5B40",
          IsBlack = 1,
          NextDialogue = 10108706,
          Scripts = "PARA{\nMoveTo{ActorId{100001},TargetPoint{\"P10108706\"},MoveSpeed{100},Visibility{\"Show\"}},\nPlayNormalSound{EventPath{\"event:/sfx/common/story/01/openbox\"},PlayAs2D{true}}\n}",
          Subtitle = "(It's an intricately carved box, feeling surprisingly heavy in your hands. But as Snow said, it's empty inside.)",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B40"
        },
        [10108706] = {
          ContentFR = "Non, pas complètement vide ! Il reste une substance... <H>une poudre visqueuse</> ressemblant à du sel. La majorité s’est dissoute dans l’eau, mais un peu reste au fond.",
          DialogueId = 10108706,
          DisableMouth = 1,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "194E5B6A",
          IsBlack = 1,
          LookAt = {
            [1] = "200002:p(P10108701)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10108707,
          Subtitle = "(Not completely empty, though! There's some sort of residue. Seems to be some slimy powder resembling salt. Most of it has dissolved into the water, but a small amount remains at the bottom of the box.)",
          TurnTo = {
            [1] = "100001:p(22)"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B6A"
        },
        [10108707] = {
          Camera = "98.9375,-272.827148,113.293945,0.001215,-14.999996,19.799967,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... elle n’est pas vide. Elle contenait quelque chose... une poudre, sans doute.",
          DialogueId = 10108707,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
