            [2] = "200002:n(200021)"
          },
          NextDialogue = 10109003,
          SpeakNpcId = 200021,
          Subtitle = "If that list means "go missing", your friend Psyche might be next.",
          TalkActionId = {
            [1] = "200021:Talk03_Start",
            [2] = "200002:Shock_End"
          },
          ToFinalCameraBlendTime = 9,
