        },
        [10109003] = {
          Camera = "143.380615,51.583008,147.531738,0.000069,-1.199982,-144.201019,40.0,274.454834,false,Manual,5.0",
          ContentFR = "Mmh... Henrik est revenu au pire moment. Si j’avais eu juste quelques minutes de plus... C’est de ma faute, à trop traîner sur cette serrure de cheminée. Ce... fumier ! Je savais qu’il n’était pas un homme de confiance.",
          DialogueId = 10109003,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "132.862061,65.048828,147.531738,0.00007,-1.199941,-138.801163,40.0,274.454834,false,Manual,5.0",
          GUID = "194E8C4E",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10109004,
          Scripts = "PARA{\nPlayAnimation{_delay{3.5},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{0.1}},\nPlayAnimation{_delay{6},ActorId{200021},AnimationId{\"Angry01_Start\"},Duration{0.1}}\n}\n",
          SpeakNpcId = 200021,
          Subtitle = "Ugh, Henrik came back at an inconvenient time. If I had a few more minutes... It's my fault, I wasted a lot of time with that chimney.\nThat piece of ****! I knew he was up to no good.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 12.5,
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8C4E"
        },
        [10109004] = {
          Camera = "182.130371,-23.287109,254.786621,0.000186,-44.200417,167.992661,50.0,272.284515,false,Manual,8.0",
          ContentFR = "Qu’est-ce qu’on fait alors ? {nickname}, Psyche est une fille bien... il faut la sauver !",
          DialogueId = 10109004,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Unacceptable01",
            [2] = "100001:Unacceptable01"
          },
          FinalCamera = "178.129395,-38.544922,254.786621,0.000188,-44.000259,164.590942,50.000008,272.284515,false,Manual,8.0",
          GUID = "194E8C78",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)",
            [3] = "200021:n(200002)"
          },
          NextDialogue = 10109005,
          SpeakNpcId = 200002,
          Subtitle = "What do we do now? , Psyche is a good kid, we have to find a way to save her!",
          TalkActionId = {
            [1] = "200002:Angry01_Start",
            [2] = "200021:Angry01_End"
          },
          ToFinalCameraBlendTime = 5.5,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8C78"
        },
        [10109005] = {
          Camera = "-154.219482,-87.605469,159.164062,0.000126,-5.801665,12.215151,35.000008,199.764572,false,Manual,5.0",
          ContentFR = "... Je pars tout de suite à la Maison d’Hypnos.",
          DialogueId = 10109005,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "194E8CA2",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200021:n(100001)"
          },
          NextDialogue = 10109006,
          SpeakNpcId = 100001,
          Subtitle = "...I'm going to the Hypnos' House right now.",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8CA2"
        },
        [10109006] = {
          Camera = "114.775879,41.625977,143.989258,0.000065,0.999987,-141.600128,50.000008,229.941086,false,Manual,8.0",
          ContentFR = "Ne fonce pas tête baissée. Nous avons encore cinq jours, rentrons d’abord nous préparer.",
          DialogueId = 10109006,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194E8CCC",
          NextDialogue = 10109007,
          SpeakNpcId = 200021,
          Subtitle = "Don't rush into it. We still have five days, let's go back and get well-prepared first.",
          TalkActionId = {
            [1] = "200021:DisagreeHead",
            [2] = "100001:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8CCC"
        },
        [10109007] = {
          Camera = "-54.203369,-87.207031,170.859375,0.000122,-15.201439,29.00316,50.0,139.404022,false,DoNotOverride,3.698512",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Non... il vaut mieux agir tôt que tard. Je ne peux pas rester là à... regarder...",
          DialogueId = 10109007,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-8.238281,-62.397461,154.720703,0.00012,-15.201385,28.40259,34.0,139.404022,false,DoNotOverride,3.698512",
          GUID = "194E8CF6",
          NextDialogue = 10109008,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Sigh_Start"},Duration{1}},\n",
          SpeakNpcId = 100001,
          Subtitle = "No, it's always better to act sooner rather than later to save someone. I can't just...",
