        },
        [10109008] = {
          DialogueId = 10109008,
          Duration = 5,
          GUID = "194E8CF7",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10109008.T_Story_Recall_10109008'",
