          GUID = "194E8E46",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10109019,
          Scripts = "SEQ{\nCameraMoveTo{_delay{3.1},TargetPosition{\"-197.588135,-214.482422,168.834473,0.00004,-5.4005,39.598293,50.0,307.64679,false,Manual,5.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-193.860352,-218.898438,168.834473,0.000039,-5.400439,41.598377,50.0,307.64679,false,Manual,5.0\"},duration{2.5}},\n}",
          SpeakNpcId = 100001,
          Subtitle = "Thank you, I've calmed down. I'll make some preparations... But tomorrow, I still need to go see Psyche.",
