          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          FinalCamera = "-213.689941,-320.035156,204.094727,0.000066,-12.400939,52.793026,35.000008,304.896423,false,DoNotOverride,1.969391",
          GUID = "194E8E70",
          NextDialogue = 10109020,
          Scripts = "LookAt{_delay{1.5},LookAtDescription{"200002:n(200021)"}}",
          SpeakNpcId = 100001,
          Subtitle = "...Don't worry, I've eased things with Henrik. I'll just pretend I know nothing.",
