          NextDialogue = 10109502,
          SpeakNpcId = 200006,
          Subtitle = "It's a cave... My dad once took me there when I was little.",
          VoiceName = "voice/$Locale$/story/1002/101095/194EDE02"
        },
        [10109502] = {
          ContentFR = "Tant d’années ont passé depuis...",
          DialogueId = 10109502,
          GUID = "194EDE2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...It's been so long...",
