        },
        [10109601] = {
          ContentFR = "Nous y voilà.",
          DialogueId = 10109601,
          ExStoryInfo = "Player",
          GUID = "194EEE6A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10109602,
          SpeakNpcId = 100001,
          Subtitle = "We've arrived.",
          VoiceName = "voice/$Locale$/story/1002/101096/194EEE6A"
        },
        [10109602] = {
          ContentFR = "Sous les racines... il y a une petite boîte enterrée. {nickname}, tu veux bien m’aider à la chercher ?",
          DialogueId = 10109602,
          ExStoryInfo = "Player",
          GUID = "194EEEBE",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "There should be a small box buried under that tree.",
          VoiceName = "voice/$Locale$/story/1002/101096/194EEEBE"
        },
        [10109701] = {
          Camera = "-190.949219,140.849609,112.655273,0.000004,-12.601363,-7.686144,50.0,234.678116,false,Manual,8.0",
          DialogueId = 10109701,
