  {
    MinKey = 10109802,
    MaxKey = 10111801,
    Loader = function()
      return {
        [10109802] = {
          ContentFR = "Même si nous devions parfois jouer à cache-cache avec les Souillés, j’attendais toujours ces moments avec impatience.",
          DialogueId = 10109802,
          GUID = "194F0F64",
          NextDialogue = 10109803,
          SpeakNpcId = 200006,
          Subtitle = "Despite the occasional hide-and-seek with the Filthoids, I always looked forward to coming here.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F64"
        },
        [10109803] = {
          ContentFR = "J’aimais les plaques de glace flottantes et les montagnes… mais ce que je préférais, c’était voir les trains passer en grondant.",
          DialogueId = 10109803,
          GUID = "194F0F8E",
          NextDialogue = 10109804,
          SpeakNpcId = 200006,
          Subtitle = "Because I loved the floating ice and mountains here, and more so, I loved watching the trains roar by.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F8E"
        },
        [10109804] = {
          ContentFR = "Tu aimes les trains ?",
          DialogueId = 10109804,
          ExStoryInfo = "Player",
          GUID = "194F0FB8",
          NextDialogue = 10109805,
          SpeakNpcId = 100001,
          Subtitle = "You like trains?",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0FB8"
        },
        [10109805] = {
          ContentFR = "Oui. Ce qui me fascine, c’est leur destination... le sud.",
          DialogueId = 10109805,
          GUID = "194F0FE2",
          NextDialogue = 10109806,
          SpeakNpcId = 200006,
          Subtitle = "Yeah. I'm fascinated by their destination... the "South".",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0FE2"
        },
        [10109806] = {
          ContentFR = "Dans les livres, il est écrit que là-bas, rien ne ressemble à Givrelac.",
          DialogueId = 10109806,
          GUID = "194F100C",
          NextDialogue = 10109807,
          SpeakNpcId = 200006,
          Subtitle = "I've read that it's nothing like Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F100C"
        },
        [10109807] = {
          ContentFR = "Le soleil y est plus chaud, et l’on peut voir les saisons changer.",
          DialogueId = 10109807,
          GUID = "194F1036",
          NextDialogue = 10109808,
          SpeakNpcId = 200006,
          Subtitle = "The sun's warmer there, and you get to see seasons change.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1036"
        },
        [10109808] = {
          ContentFR = "Quand vient le printemps, la glace et la neige disparaissent, et des fleurs éclosent partout, jusque dans les plaines sauvages.",
          DialogueId = 10109808,
          GUID = "194F1060",
          NextDialogue = 10109809,
          SpeakNpcId = 200006,
          Subtitle = "When spring comes, the ice and snow melt away, and there are flowers everywhere, even in the wilds.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1060"
        },
        [10109809] = {
          ContentFR = "Je me disais toujours : si seulement je pouvais monter dans l’un de ces trains, j’arriverais enfin là-bas...",
          DialogueId = 10109809,
          GUID = "194F108A",
          NextDialogue = 10109810,
          SpeakNpcId = 200006,
          Subtitle = "I always dreamed that if I could catch a train, I could actually get there.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F108A"
        },
        [10109810] = {
          ContentFR = "Mais mon père m’a dit que c’était un vœu trop ambitieux.",
          DialogueId = 10109810,
          GUID = "194F10B4",
          NextDialogue = 10109811,
          SpeakNpcId = 200006,
          Subtitle = "But Dad told me, it was not a dream we could afford.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F10B4"
        },
        [10109811] = {
          ContentFR = "Parce que... vous êtes des Charons ?",
          DialogueId = 10109811,
          ExStoryInfo = "Player",
          GUID = "194F10DE",
          NextDialogue = 10109812,
          SpeakNpcId = 100001,
          Subtitle = "Because... you're Charons?",
          VoiceName = "voice/$Locale$/story/1002/101098/194F10DE"
        },
        [10109812] = {
          ContentFR = "Oui. Et puis Papa et Maman n’étaient que de simples fleuristes. Nous étions pauvres, et n’avions pas les moyens d’acheter un billet.",
          DialogueId = 10109812,
          GUID = "194F1108",
          SpeakNpcId = 200006,
          Subtitle = "Yes. And also because Mum and Dad are just ordinary gardeners. We were poor and didn't have the means to board that train.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1108"
        },
        [10109901] = {
          Camera = "43.035156,-369.824219,5.117188,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Alors, le jour où tu as frappé à la porte de la Maison d’Hypnos, j’ai été si surprise... car je n’avais presque jamais rencontré quelqu’un venant d’ailleurs que Givrelac.",
          DialogueId = 10109901,
          FacialId = {
            [1] = "200027:Smile02"
          },
          FinalCamera = "50.992188,-403.761719,-0.895508,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
          GUID = "194F1FA2",
          LookAt = {
            [1] = "100001:n(200027)",
            [2] = "200027:n(100001)"
          },
          NextDialogue = 10109902,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 301005,
            [3] = 405002,
            [4] = 201007,
            [5] = 201006,
            [6] = 201001
          },
          Scripts = "SEQ{\nPARA{\nTurnTo{TurnToDescription{\"200027:p(45)\"}},\nTurnTo{TurnToDescription{\"100001:p(-45)\"}},\nLookAt{LookAtDescription{\"200027:n(100001)\"}},\nLookAt{LookAtDescription{\"200027:n(100001)\"}}\n},\nPlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{2}}\n}",
          SpeakNpcId = 200027,
          Subtitle = "So, the day you showed up at the door of the Hypnos' House, I was thrilled... I've never met anyone outside Icelake.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101099/194F1FA2"
        },
        [10109902] = {
          Camera = "-194.089844,43.5625,83.087891,0.000346,-1.60116,21.496424,40.0,226.073593,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Depuis, je me demande en secret : à quoi ressemble ton pays natal ? As-tu vu l’océan de tes propres yeux ? Est-il vraiment vaste comme cent lacs réunis ?",
          DialogueId = 10109902,
          FinalCamera = "-148.476562,62.945312,79.891602,0.000346,-0.001072,17.102312,40.000011,162.126846,false,Manual,4.0",
          GUID = "194F1FCC",
          LookAt = {
            [1] = "200027:n(100001)"
          },
          NextDialogue = 10109903,
          Scripts = "\nSEQ{\nPlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}},\nPlayAnimation{ActorId{200027},AnimationId{\"Talk02_Start\"},Duration{1}}\n}\n",
          SpeakNpcId = 200027,
          Subtitle = "I've always secretly wondered what your homeland is like. Have you seen the ocean with your own eyes? Is it as large as a hundred lakes put together?",
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1002/101099/194F1FCC"
        },
        [10109903] = {
