          Camera = "556.611328,700.994141,428.892578,0.000123,-21.00264,-125.02404,30.0,294.274872,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Assez ! Assez ! Je me rends ! Mais ce n’est pas moi, je le jure !",
          DialogueId = 10110201,
          FacialId = {
            [1] = "200004:Sad01"
          },
          FinalCamera = "505.554688,628.949219,394.939453,0.00012,-21.202627,-125.424011,30.0,294.274872,false,Manual,22.0",
          GUID = "194F50DA",
          LookAt = {
            [1] = "200004:n(100001)",
            [2] = "100001:n(200004)"
          },
          NextDialogue = 10110202,
          Scripts = "PARA{\nPlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Think_Start\"},Duration{2}},\nCameraMoveTo{_delay{3},TargetPosition{\"63.138672,-228.014648,186.216797,0.00006,-7.199675,109.79966,35.0,130.287109,false,Manual,3.749117\"},duration{0}},\nCameraMoveTo{_delay{3.1},TargetPosition{\"63.138672,-228.014648,186.216797,0.000054,-12.399627,106.79998,35.0,399.040039,false,Manual,3.749117\"},blend{\"easeOutQuad\"},duration{3.5}}\n}",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Alright, alright, I surrender! But it wasn't me, I swear!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101102/194F50DA"
        },
        [10110202] = {
          Camera = "63.138672,-228.014648,186.216797,0.000054,-12.399627,106.79998,35.0,399.040039,false,Manual,3.749117",
          ContentFR = "Toi ?",
          DialogueId = 10110202,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01",
            [2] = "200004:None"
          },
          GUID = "194F5104",
          NextDialogue = 10110203,
          SpeakNpcId = 100001,
          Subtitle = "It's you?",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5104"
        },
        [10110203] = {
          ContentFR = "Très bien. Je vous fais confiance, Madame Camilla. Mais souvenez-vous : surveillez {性别:le|la} bien. Et surtout, pas d’histoires en ville, si la Commandante nous tombe dessus, on aura tous les deux de gros ennuis.",
          DialogueId = 10110203,
          ExStoryInfo = "Player",
          GUID = "194F512E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110203.T_Story_Recall_10110203'",
          NextDialogue = 10110204,
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_Man_4",
          Subtitle = "Alright, I trust you, Ms Camilla. But remember, keep a close eye on this kid and don't let {性别:him|her} stir up any trouble in town. If the Chief finds out about this, we'll both be in for it.",
          VoiceName = "voice/$Locale$/story/1002/101006/19492C50"
        },
        [10110204] = {
          Camera = "47.769531,188.458008,134.702148,0.000103,0.398248,-107.229118,35.0,362.075562,false,Manual,3.0",
          ContentFR = "Merde ! Je ne m’attendais pas à te croiser... Écoute, {性别:frèrot|sœurette}, je t’en prie, ne dis rien à personne, d’accord ?",
          DialogueId = 10110204,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F5158",
          NextDialogue = 10110205,
          Scripts = "PARA{\nPlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Disagree\"},Duration{1}},\nPlayAnimation{_delay{3},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Drat! Didn't expect to run into you... Do me a favour, {性别:mate|miss}, keep this between us, will you?",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5158"
        },
        [10110205] = {
          Camera = "64.769531,6.819336,122.332031,0.000111,7.997714,119.570648,35.0,362.075562,false,DoNotOverride,22",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Cette personne, c’est...",
          DialogueId = 10110205,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock02"
          },
          FinalCamera = "49.960938,32.921875,126.546875,0.000111,8.397717,119.570648,35.0,362.075562,false,DoNotOverride,22",
          GUID = "194F5182",
          LookAt = {
            [1] = "100001:p(P101102Bag)"
          },
          NextDialogue = 10110206,
          Scripts = "PARA{\nCameraMoveTo{_delay{2},TargetPosition{\"-23.076172,112.924805,193.445312,0.000089,-33.602196,-42.428871,35.0,362.075562,false,Manual,22.0\"},duration{0}},\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0051_story_danger\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Who is this...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5182"
        },
        [10110206] = {
          Camera = "74.595703,85.75,141.061523,0.000114,1.99839,-111.626167,35.0,100000.0,false,Disable,2.8",
          ContentFR = "Arrête, arrête ! Voici ton sac d’argent ! Ça fait plusieurs jours que je n’ai pas eu un vrai repas, je me suis laissé emporter... Ah, j’ai eu tort, désolé !",
          DialogueId = 10110206,
          GUID = "194F51AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110206.T_Story_Recall_10110206'",
          NextDialogue = 10110207,
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Tsk... If I hadn't been starved all day, I'd never have touched this bloody thing, let alone lost to you!",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD496"
        },
        [10110207] = {
          Camera = "49.960938,32.921875,126.546875,0.000111,8.397717,119.570648,35.0,362.075562,false,Manual,22.0",
          ContentFR = "Tu l’as exécuté ? Il... il ne méritait pas de mourir.",
          DialogueId = 10110207,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          GUID = "194F51D6",
          LookAt = {
            [1] = "100001:n(200004)"
          },
          NextDialogue = 10110208,
          Scripts = "CameraMoveTo{_delay{1.5},TargetPosition{"53.412109,-207.308594,178.919922,0.000045,-11.599839,106.600044,35.000008,338.707367,false,Manual,4.0"},duration{0}},",
          SpeakNpcId = 100001,
          Subtitle = "...He may be a thief, but he doesn't deserve to be killed for this!",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F51D6"
        },
        [10110208] = {
          Camera = "2442.902344,1375.00293,-15.568359,0.000018,1.799891,-157.005646,50.0,546.458801,false,Manual,1.2",
          ContentFR = "Chut ! Je t’ai dit que ce n’était pas moi. Je ne faisais que transporter son corps discrètement.",
          DialogueId = 10110208,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "2446.085938,1367.493164,-15.568359,0.000015,1.799891,-157.005661,50.0,2902.307617,false,Manual,4.0",
          GUID = "194F5200",
          NextDialogue = 10110209,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Keep it down! I told you, it wasn't me. I was just trying to sneak the body out.",
          TalkActionId = {
            [1] = "200004:Talk01_Start",
            [2] = "100001:Angry01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5200"
        },
        [10110209] = {
          ContentFR = "Je m’appelle Kevin. On s’est déjà croisés... je fais partie des Veilleurs des Faubourgs de Givrelac. Et lui, c’est Hal... un ancien voisin, on se connaît depuis qu’on est gosses.",
          DialogueId = 10110209,
          GUID = "194F522A",
          NextDialogue = 10110210,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "My name's Kevin. We've met before — I'm in the outskirts escort... And this poor soul here is Hal, my old neighbour. We've known each other since we were kids.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F522A"
        },
        [10110210] = {
          Camera = "155.150391,89.697266,40.088867,0.000099,0.594261,-127.181572,25.0,379.426514,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Sa mère est morte jeune. Il a passé sa vie à se battre plus qu’à manger... Ma famille m’interdisait de fréquenter les Charons, mais comme on avait grandi ensemble, je l’aidais de temps en temps.",
          DialogueId = 10110210,
          FinalCamera = "155.150391,89.697266,40.088867,0.000105,18.793825,-127.379799,25.0,379.426514,false,Manual,22.0",
          GUID = "194F5254",
          NextDialogue = 10110211,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.2},TargetPosition{\"108.958984,10.623047,103.797852,0.000077,19.595867,-129.596573,35.000008,184.886414,false,Manual,22.0\"},duration{0}},\nPlayAnimation{_delay{2},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{2}},\nSEQ{\nLookAt{LookAtDescription{\"200004:p(P101102Bag)\"}},\nLookAt{_delay{2},LookAtDescription{\"200004:n(100001)\"}}\n}\n}",
          SpeakNpcId = 200004,
          Subtitle = "He lost his mother at an early age and had been getting into countless brawls ever since. My family doesn't allow me to interact with Charons, but he was an old friend from when I was a kid, so I'd sometimes help him out...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5254"
        },
        [10110211] = {
          Camera = "189.996094,-133.302734,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Puis un jour, il est venu me voir, l’air louche. Je pensais qu’il avait encore des dettes ou que son ivrogne de père l’avait frappé. Mais non... il m’a dit qu’il présentait des signes de <W>Dégradation</>.",
          DialogueId = 10110211,
          FinalCamera = "190.324219,-114.291016,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463",
          GUID = "194F527E",
          LookAt = {
            [1] = "200004:n(100001)"
          },
          NextDialogue = 10110212,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.1},TargetPosition{\"204.705078,100.296875,134.578125,0.0,0.0,-179.999954,35.0,180.0,false,Manual,4.146463\"},duration{0}},\nCameraMoveTo{_delay{4.2},TargetPosition{\"204.707031,113.621094,134.578125,0.0,-0.200008,-179.399948,35.0,180.0,false,Manual,4.146463\"},blend{\"easeOutQuad\"},duration{4}},\nSEQ{\nPlayAnimation{_delay{0.1},ActorId{200004},AnimationId{\"Talk01_End\"},Duration{1}}\n}\n}",
          SpeakNpcId = 200004,
          Subtitle = "One day, he came to me, acting all weird. I thought he'd racked up debts again, or that he came to moan about being hit again by his drunkard dad. But to my surprise, he said he was showing signs of Deterioration...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F527E"
        },
        [10110212] = {
          Camera = "32.447266,-94.166016,150.726562,0.000106,-6.001796,98.975403,35.000011,165.117889,false,Manual,4.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Dégradation ? Qu’est-ce que c’est exactement ?",
          DialogueId = 10110212,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "27.117188,-60.277344,147.863281,0.000109,-4.801753,98.975227,35.000008,165.117889,false,Manual,4.0",
          GUID = "194F52A8",
          NextDialogue = 10110213,
          SpeakNpcId = 100001,
          Subtitle = "What exactly is "Deterioration"?",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F52A8"
        },
        [10110213] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
          ContentFR = "Quoi ? T’es {性别:un|une} Charon et tu ne sais pas ce que c’est ? Tu es sûr d’être de l’Empire ?",
          DialogueId = 10110213,
          GUID = "194F52D2",
          NextOptions = {
            [1] = 10110214,
            [2] = 10110216
          },
          SpeakNpcId = 200004,
          Subtitle = "As a Charon, you don't know about Deterioration? Are you really a native?",
          TalkActionId = {
            [1] = "200004:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52D2"
        },
        [10110214] = {
          ContentFR = "Je viens d’un village reculé, je n’ai pas beaucoup d’informations...",
          DialogueId = 10110214,
          GUID = "10110214",
          ImprPlusId = 1007,
          NextDialogue = 10110215
        },
        [10110215] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
          ContentFR = "Ah oui, Camilla en avait parlé, ça s’explique alors.",
          DialogueId = 10110215,
          GUID = "194F52FC",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          Subtitle = "Ah right, Camilla did mention something about that. Makes sense then.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52FC"
        },
        [10110216] = {
          ContentFR = "Tu poses trop de questions... fais gaffe, sinon je vais raconter ce que j’ai vu aujourd’hui à...",
          DialogueId = 10110216,
          GUID = "10110216",
          ImprPlusId = 1010,
          NextDialogue = 10110217
        },
        [10110217] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
          ContentFR = "Ah ! Non, non, je ne poserai plus de questions, s’il te plaît, ne le dis à personne !",
          DialogueId = 10110217,
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F5326",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          Subtitle = "Alright, alright! I won't ask any more questions! Please don't tell anyone!",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5326"
        },
        [10110218] = {
          Camera = "774.716797,904.916992,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8",
          ContentFR = "La <W>Dégradation</>, c’est une maladie propre aux Charons. Quand ça te tombe dessus, c’est incurable.",
          DialogueId = 10110218,
          FinalCamera = "819.070312,866.855469,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8",
          GUID = "194F5350",
          NextDialogue = 10110219,
          SpeakNpcId = 200004,
          Subtitle = "So Deterioration is a peculiar disease that only Charons might suffer from. Once you've got it, there's no cure.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5350"
        },
        [10110219] = {
          Camera = "59.294922,60.157227,158.963867,0.000116,1.398187,-107.029724,35.0,201.991119,false,Manual,6.0",
          ContentFR = "Vers l’adolescence, la plupart d’entre vous éveillent un pouvoir. Mais parfois, ça tourne mal.",
          DialogueId = 10110219,
          FinalCamera = "54.453125,61.650391,158.963867,0.000116,1.398222,-105.829933,35.0,197.159012,false,Manual,6.0",
          GUID = "194F537A",
          NextDialogue = 10110220,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.1},TargetPosition{\"14.539062,-57.106445,149.019531,0.000111,-4.801684,98.370796,35.0,159.591751,false,Manual,6.0\"},duration{0}},\nCameraMoveTo{_delay{4.2},TargetPosition{\"24.572266,-55.670898,149.019531,0.000112,-5.201646,97.571365,35.000008,165.538956,false,Manual,6.0\"},duration{4}}\n}",
          SpeakNpcId = 200004,
          Subtitle = "You folks usually awaken some kind of power around your teens, but not everyone's that lucky.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F537A"
        },
        [10110220] = {
          ContentFR = "Il y a toujours quelques pauvres malheureux qui, d’une manière ou d’une autre, ratent leur éveil et deviennent des <W>Souillés</>. Mais à la différence des Souillés ordinaires, ils sont bien plus puissants, une seule de ces créatures pourrait mettre en difficulté toute une escouade de Veilleurs.",
          DialogueId = 10110220,
          GUID = "194F53A4",
          NextDialogue = 10110221,
          RelatedWikiId = {
            [1] = 303003
          },
          SpeakNpcId = 200004,
          Subtitle = "There are always a few poor wretches who somehow get it wrong and turn into Filthoids — but way stronger than the regular Filthoids out there; a whole escort might not even be able to take one down.",
          VoiceName = "voice/$Locale$/story/1002/101102/194F53A4"
        },
        [10110221] = {
          Camera = "582.199219,778.926758,7556.786133,0.000033,22.586451,-62.627708,15.000007,179.344406,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Si un Dégradé apparaît en ville... c’est tout le quartier qui est condamné.",
          DialogueId = 10110221,
          FinalCamera = "731.279297,485.125,7697.886719,0.000031,23.186407,-63.027958,15.000007,179.344406,false,DoNotOverride,22.0",
          GUID = "194F53CE",
          NextDialogue = 10110222,
          SpeakNpcId = 200004,
          Subtitle = "If a Deteriorator appears in the city... the entire neighbourhood is doomed.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F53CE"
        },
        [10110222] = {
          Camera = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0",
          ContentFR = "Voilà pourquoi tant de Solariens haïssent les Charons. Ils disent que c’est le sang impur qui attire le malheur... Et les Dégradés sont vus comme les pires démons parmi les Charons.",
          DialogueId = 10110222,
          FacialId = {
            [1] = "200004:None"
          },
          GUID = "194F53F8",
          NextDialogue = 10110223,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{"Talk01_Start"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "Now you get why so many people hate Charons, right? Everyone says it's the evil magic coursing through Charon veins that brings such disaster. The Deteriorators are considered the most evil among all Charons.",
          TalkActionId = {
            [1] = "200004:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F53F8"
        },
        [10110223] = {
          Camera = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0",
          ContentFR = "Franchement, j’y crois pas complètement. Mais... pourquoi fallait-il que ça tombe sur Hal ?",
          DialogueId = 10110223,
          GUID = "194F5422",
          NextDialogue = 10110224,
          Scripts = "SEQ{\nLookAt{LookAtDescription{\"200004:p(P101102Bag)\"}},\nPlayAnimation{ActorId{200004},AnimationId{\"Disagree\"},Duration{2}},\nLookAt{_delay{2},LookAtDescription{\"200004:n(100001)\"}}\n}",
          SpeakNpcId = 200004,
          Subtitle = "Honestly, I'm not entirely sold on this, but... sigh! How come such a rare thing had to happen to Hal?",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5422"
        },
        [10110224] = {
          Camera = "59.203125,-199.486328,172.362305,0.000048,-11.20041,106.99884,35.000008,100000.0,false,Disable,4.0",
          ContentFR = "Il y a deux semaines, il est venu me voir, paniqué. Mais je ne pouvais pas le cacher. Protéger un Dégradé, c’est comme abriter un membre des Déchus, peine capitale assurée. Alors je lui ai juste donné de quoi manger, et je l’ai renvoyé.",
          DialogueId = 10110224,
          GUID = "194F544C",
          NextDialogue = 10110225,
          Scripts = "CameraMoveTo{_delay{11},TargetPosition{"74.595703,85.75,141.061523,0.000111,4.598363,-113.225594,35.0,100000.0,false,Disable,2.8"},duration{0}}",
          SpeakNpcId = 200004,
          Subtitle = "About two weeks ago, he came to me all in a flap, but what could I do? Harbouring a Deteriorator is as severe as sheltering a member of the Forsakens — one wrong move could cost you your life. All I could do was give him some food and tell him to sort himself out.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F544C"
        },
        [10110225] = {
          Camera = "81.287109,-34.47168,231.873047,0.000089,-31.399204,-132.789673,35.000008,100000.0,false,Disable,4.0",
          ContentFR = "Plus tard, j’ai appris qu’il s’était fait prendre en train de voler. Et quand ils ont découvert ce qu’il était... ils l’ont livré direct au Bureau de la Sécurité.",
          DialogueId = 10110225,
          GUID = "194F5476",
          NextOptions = {
            [1] = 10110226
          },
          SpeakNpcId = 200004,
          Subtitle = "Later I heard he got nabbed for stealing and was found to be a Deteriorator. They took him straight to the Security Bureau.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5476"
        },
        [10110226] = {
          ContentFR = "Que se passe-t-il lorsque tu es envoyé au Bureau de la Sécurité ?",
          DialogueId = 10110226,
          GUID = "194F5477",
          NextDialogue = 10110227
        },
        [10110227] = {
          Camera = "777.373047,-100.292969,25.057617,0.000009,4.599859,172.998215,40.000011,332.596619,false,Manual,22.0",
          ContentFR = "Je t’ai déjà dit qu’il n’y avait aucun remède pour les Dégradés. Tu crois qu’il va lui arriver quoi ? On le transfère aux Veilleurs et ensuite... eh bien, tu vois.",
          DialogueId = 10110227,
          GUID = "194F54A0",
          NextDialogue = 10110228,
          SpeakNpcId = 200004,
          Subtitle = "Like I said, there's no cure for Deteriorators. What else could happen? They get handed over to the Escort, and then... well, you know.",
          TalkActionId = {
            [1] = "200004:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54A0"
        },
        [10110228] = {
          Camera = "-30.980469,-249.970703,249.849609,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
          ContentFR = "Il l’a bien cherché, d’une certaine manière... Mais il avait été mon ami quelques années. Je ne pouvais pas supporter l’idée de le laisser dans une morgue glaciale. Alors je l’ai... sorti discrètement. Mon intention était de l’enterrer au bord du Lac du Deuil, là où repose sa mère.",
          DialogueId = 10110228,
          FinalCamera = "-23.003906,-235.451172,235.890625,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
          GUID = "194F54CA",
          NextDialogue = 10110229,
          Scripts = "PARA{\nLookAt{LookAtDescription{\"200004:p(P101102Bag)\"}},\nSetLocation{ActorId{100001},TargetPoint{\"P101102Nvzhu2\"},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 200004,
          Subtitle = "Although he pretty much had it coming... But still, we were friends for a few years. I couldn't bear the thought of him lying in a cold morgue, so I sneaked him out... I was gonna bury him by Lamenting Lake, right next to his mother.",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "200004:p(-110)"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54CA"
        },
        [10110229] = {
          Camera = "49.005859,-190.758789,170.493164,0.000064,-9.500171,103.609756,40.000023,322.94809,false,Manual,3.0",
          ContentFR = "Attends. Je veux savoir... Entre les premiers signes de la Dégradation et sa manifestation complète... il se passe quoi ? Quels symptômes apparaissent ?",
          DialogueId = 10110229,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194F54F4",
          NextDialogue = 10110230,
          Scripts = "PARA{\nLookAt{_delay{1},LookAtDescription{\"200004:n(100001)\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Hold on, I'm curious — what symptoms would appear between the onset of Deterioration and its full development?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54F4"
        },
        [10110230] = {
          Camera = "29.394531,154.411133,135.935547,0.000082,4.298655,-102.209503,40.000011,300.548492,false,Manual,4.0",
          ContentFR = "Comment veux-tu que je sache ? Enfin... j’ai entendu dire que certains deviennent extrêmement violents. D’autres, plus malheureux, commencent à perdre peu à peu leurs sens : la vue, l’ouïe, ce genre de choses.",
          DialogueId = 10110230,
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F551E",
          NextDialogue = 10110231,
          RelatedWikiId = {
            [1] = 303006
          },
          Scripts = "SEQ{\nTurnTo{TurnToDescription{\"200004:n(100001)\"}},\nPlayAnimation{_delay{1.5},ActorId{200004},AnimationId{\"Think_Start\"},Duration{1}},\nPlayAnimation{_delay{5},ActorId{200004},AnimationId{\"Think_End\"},Duration{1}},\n}",
          SpeakNpcId = 200004,
          Subtitle = "How should I know? Oh, but I've heard that some would turn extremely violent, and some poor souls would gradually lose their senses, like going blind or deaf or something, perhaps.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F551E"
        },
        [10110231] = {
          ContentFR = "Ce n’est que ce qu’on raconte. Si ça t’intéresse vraiment, demande plutôt à un médecin. Mais toi, tu as déjà survécu à l’éveil. Alors pourquoi t’inquiéter de ça ?",
          DialogueId = 10110231,
          FacialId = {
            [1] = "200004:None"
          },
          GUID = "194F5548",
          NextDialogue = 10110232,
          Scripts = "PlayAnimation{_delay{3},ActorId{200004},AnimationId{"Talk01_Start"},Duration{2}}\n",
          SpeakNpcId = 200004,
          Subtitle = "This is all just hearsay though. If you're curious about it, better ask a doctor. But it seems to me you've already awakened successfully, why do you care?",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5548"
        },
        [10110232] = {
          Camera = "71.007812,-49.522461,222.453125,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "...",
          DialogueId = 10110232,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          FinalCamera = "60.40625,-24.273438,208.739258,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
          GUID = "194F5572",
          NextDialogue = 10110233,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5572"
        },
        [10110233] = {
          ContentFR = "Ah ! J’ai eu un petit vertige, j’ai raté la marche. Merci de m’avoir rattrapée !",
          DialogueId = 10110233,
          GUID = "194F559C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110233.T_Story_Recall_10110233'",
          NextDialogue = 10110234,
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "Uh! I got a little dizzy and didn't see the step, thank you.",
          VoiceName = "voice/$Locale$/story/1002/101013/19499D06"
        },
        [10110234] = {
          ContentFR = "Tout à coup, ma vue s’est troublée... et j’ai fini par affoler cette créature. Je suis désolée...",
          DialogueId = 10110234,
          GUID = "10110234.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110234.T_Story_Recall_10110234'",
          NextDialogue = 10110235,
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "I suddenly couldn't see clearly back there and ended up startling that monster... I'm so sorry!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBA6"
        },
        [10110235] = {
          ContentFR = "Psyche... Depuis quand est-ce que tu ne vois plus clair ?",
          DialogueId = 10110235,
          ExStoryInfo = "Player",
          GUID = "10110235.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110235.T_Story_Recall_10110235'",
          NextDialogue = 10110236,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "Your eyes... When did you lose your sight?",
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE42"
        },
        [10110236] = {
          ContentFR = "Depuis quand... exactement... ?",
          DialogueId = 10110236,
          GUID = "10110236.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110236.T_Story_Recall_10110236'",
          NextDialogue = 10110237,
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "When was it...",
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE6C"
        },
        [10110237] = {
          Camera = "19.232422,44.570312,117.50293,0.000166,18.198389,104.808296,35.000008,162.592728,false,Manual,22.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "... Et si la cécité de Psyche était un symptôme de la Dégradation ? Se pourrait-il que tous les "pensionnaires" de la Maison d’Hypnos soient des Dégradés ?",
          DialogueId = 10110237,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "29.253906,6.640625,104.633789,0.000168,17.198368,104.608376,35.000008,162.592728,false,Manual,22.0",
          GUID = "194F5644",
          NextDialogue = 10110238,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Could Psyche's sight loss be a symptom of Deterioration... Could all the "lodgers" at the Hypnos' House be Deteriorators?)",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5644"
        },
        [10110238] = {
          Camera = "37.144531,202.914062,126.870117,0.000128,3.900086,-105.196716,40.0,278.887787,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Monsieur, je veux me renseigner sur quelqu’un, et j’espère que tu me répondras honnêtement. Tu vois cet appareil photo ? Si tu refuses, je pourrais très bien en confier la pellicule au Bureau de la Sécurité, je suis {性别:sûr|sûre} qu’ils sauraient quoi en faire.",
          DialogueId = 10110238,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "50.792969,198.213867,126.870117,0.000126,3.900086,-107.797836,40.0,278.887787,false,Manual,3.0",
          GUID = "194F566E",
          NextDialogue = 10110239,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.1},TargetPosition{\"72.476562,-210.320312,168.837891,0.000193,-9.201282,108.579414,35.000008,371.235565,false,Manual,3.0\"},duration{0}},\nCameraMoveTo{_delay{4.2},TargetPosition{\"59.669922,-214.0625,168.837891,0.000192,-9.801321,105.5793,35.000008,371.235565,false,Manual,3.0\"},blend{\"easeOutQuad\"},duration{4}},\nPlayAnimation{_delay{4.2},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Sir, I'd like to inquire about someone, and I hope you'll be frank and supportive. See this camera? If you refuse, I might just hand it over to the Security Bureau — they'd surely be interested.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F566E"
        },
        [10110239] = {
          Camera = "62.695312,-35.460938,197.44043,0.000168,-15.401721,-165.42247,35.000008,239.561539,false,Manual,22.0",
          ContentFR = "Par pitié, épargne-moi... Si tu veux percer des secrets militaires, tu n’as pas besoin de harceler un simple soldat comme moi, je fais juste le guet !",
          DialogueId = 10110239,
          FacialId = {
            [1] = "200004:Sad01"
          },
          FinalCamera = "78.841797,-97.880859,197.44043,0.000168,-18.601685,-166.822098,35.000011,239.561539,false,Manual,22.0",
          GUID = "194F5698",
          NextDialogue = 10110240,
          SpeakNpcId = 200004,
          Subtitle = "Good grief! Cut me some slack... If you're digging for some military secrets, you don't need to corner a mere foot soldier like me — I'm basically just a gatekeeper!",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5698"
        },
        [10110240] = {
          Camera = "24.123047,-69.332031,126.121094,0.000172,2.398667,98.17495,35.000011,177.910553,false,Manual,4.0",
          ContentFR = "Henrik Ethelred, le tenancier de la Maison d’Hypnos, au nord de Givrelac. Qu’est-ce que tu sais de lui ? Je veux tout entendre, sans exception.",
          DialogueId = 10110240,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194F56C2",
          NextDialogue = 10110241,
          SpeakNpcId = 100001,
          Subtitle = "Do you know anything about Henrik Ethelred, the owner of the Hypnos' House in the north of the city? I mean ANYTHING, and I'd like to hear them all, sir.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F56C2"
        },
        [10110241] = {
          Camera = "121.794922,416.958008,140.132812,0.000136,-2.801443,-106.219742,35.000008,100000.0,false,Disable,2.8",
          ContentFR = "Henrik Ethelred... Ce n’est pas juste un aubergiste ? L’un de mes supérieurs le connaît un peu. Il a eu quelques démêlés avec la justice autrefois, mais ces dernières années, il est resté tranquille. Rien à signaler.",
          DialogueId = 10110241,
          FacialId = {
            [1] = "200004:None"
          },
          FinalCamera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          GUID = "194F56EC",
          NextDialogue = 10110242,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{"Think_Start"},Duration{2}}\n",
          SpeakNpcId = 200004,
          Subtitle = "Henrik Ethelred... isn't he just an inn owner? Oh, my superior does have some connection with him. He's got a bit of a history, but has been a law-abiding citizen these past years.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F56EC"
        },
        [10110242] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          ContentFR = "Oh, par contre, il a fichu caractère. Plus d’une fois, il a jeté dehors des voyageurs venus loger chez lui. Mais bon... paraît que déjà, à l’époque où il exerçait son vrai métier, il n’était pas commode. Sauf qu’à ce moment-là, il avait encore sa famille pour le tempérer.",
          DialogueId = 10110242,
          GUID = "194F5716",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "Oh, that man's got quite the temper, not a rare occasion he's shut the door on travellers. But that's just how he is — even back in his proper job days, he wasn't a nice guy either, though at least back then he had his family to keep him in check.",
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5716"
        },
        [10110243] = {
          ContentFR = "Parle-moi en détail de "ses antécédents".",
          DialogueId = 10110243,
          GUID = "10110243",
          NextDialogue = 10110246
        },
        [10110244] = {
          ContentFR = "Parle-moi de "son ancien métier".",
          DialogueId = 10110244,
          GUID = "10110244.0",
          NextDialogue = 10110251
        },
        [10110245] = {
          ContentFR = "Parle-moi de "sa famille".",
          DialogueId = 10110245,
          GUID = "10110245.0",
          NextDialogue = 10110254
        },
        [10110246] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          ContentFR = "Voyons... Ça remonte à quoi... quatorze, quinze ans ? Henrik Ethelred a commis un meurtre à <H>Rougerive</>, dans la province de Flagson.",
          DialogueId = 10110246,
          GUID = "194F5740",
          NextDialogue = 10110247,
          RelatedWikiId = {
            [1] = 408006
          },
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"}}",
          SpeakNpcId = 200004,
          Subtitle = "Well, it was... what, some fourteen, fifteen years ago? Henrik Ethelred committed a murder up in Scarletriver, Flagson.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5740"
        },
        [10110247] = {
          Camera = "48.828125,-238.466797,197.088867,0.000132,-14.601796,105.386505,35.000008,394.862823,false,Manual,4.0",
          ContentFR = "La victime était un Charon. Oui, et un Charon déjà atteint par la <W>Dégradation</> ... Comme on vient d’en parler. Ce n’était pas considéré comme un crime grave, donc il n’a fait que quelques mois de prison avant d’être libéré.",
          DialogueId = 10110247,
          GUID = "194F576A",
          NextDialogue = 10110248,
          SpeakNpcId = 200004,
          Subtitle = "The victim was a Charon, one with signs of Deterioration — like I just said. Not a major crime though, so he only served a few months before getting released.",
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F576A"
        },
        [10110248] = {
          Camera = "11.783203,35.181641,158.039062,0.000169,-12.8009,95.373573,35.000008,83.272263,false,Manual,5.0",
          ContentFR = "Pourquoi il a fait ça ?",
          DialogueId = 10110248,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "194F5794",
          NextDialogue = 10110249,
          SpeakNpcId = 100001,
          Subtitle = "Why would he do that?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5794"
        },
        [10110249] = {
          Camera = "781.091797,122.442383,14.25293,0.00013,1.998233,-169.017654,25.0,182.242599,false,Manual,22",
          ContentFR = "... Aucune idée. Mais enfin, c’est humain d’avoir peur, et même de haïr les Dégradés, non ?",
          DialogueId = 10110249,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "781.091797,122.442383,33.219727,0.00013,0.0,-169.01709,25.0,182.242599,false,Manual,22",
          GUID = "194F57BE",
          NextDialogue = 10110250,
          SpeakNpcId = 200004,
          Subtitle = "...I don't know. But any Mortalan would fear and despise a Deteriorator, I guess.",
          TalkActionId = {
            [1] = "200004:Disagree",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F57BE"
        },
        [10110250] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
          ContentFR = "Je tiens ça de mon supérieur. Et puis, ça date, et ce n’est pas arrivé ici. Alors si je me trompe sur les détails, tu ne m’en veux pas, hein ?",
          DialogueId = 10110250,
          GUID = "194F57E8",
          NextDialogue = 10110261,
          Scripts = "PlayAnimation{_delay{4},ActorId{200004},AnimationId{"Talk01_End"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "I just heard this from my superior. It's been a long time and it didn't happen locally, so don't hold it against me if I've got some details wrong!",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F57E8"
        },
        [10110251] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
          ContentFR = "Tous les anciens de Givrelac savent qu’Henrik a été, autrefois, un <H>médecin</> très réputé. Un vrai praticien de talent, au point que même les nobles de la cité intérieure venaient le consulter.",
          DialogueId = 10110251,
          GUID = "194F5812",
          NextDialogue = 10110252,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"}}",
          SpeakNpcId = 200004,
          Subtitle = "The older folks in Icelake all know that Henrik was once a renowned doctor. Quite the skilled medic, he was, even the nobles from the inner city would go to him.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5812"
        },
        [10110252] = {
          Camera = "327.693359,662.063477,356.859375,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
          ContentFR = "Mais un jour, sans qu’on sache trop pourquoi, il a fermé son cabinet au sommet de sa renommée. Deux ans plus tard, il l’a rouvert... mais la plaque indiquait "auberge".",
          DialogueId = 10110252,
          FinalCamera = "350.828125,717.59375,368.043945,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
          GUID = "194F583C",
          NextDialogue = 10110253,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{"Think_Start"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "But then something happened, and he shut down his clinic at the height of his fame, only to reopen it as an inn a couple of years later.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F583C"
        },
        [10110253] = {
          Camera = "62.0,13.855469,151.842773,0.000098,1.998315,-117.01268,35.000008,143.588394,false,Manual,5.149117",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "D’ailleurs... en y repensant, c’était à peu près à l’époque où il a eu ses ennuis à Rougerive...",
          DialogueId = 10110253,
          FinalCamera = "100.847656,-14.870117,151.862305,0.000107,6.598201,-135.012131,35.000011,143.588394,false,Manual,5.149117",
          GUID = "194F5866",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "Oh, come to think of it, that was right around the time he got in trouble in Scarletriver...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5866"
        },
        [10110254] = {
          Camera = "37.912109,160.816406,132.972656,0.000113,2.998043,-103.822327,35.000008,305.385315,false,Manual,2.8",
          ContentFR = "Il avait une femme et une fille. Une famille ordinaire, rien de spécial. Sa femme est morte très tôt, et c’est lui qui a élevé sa fille seul.",
          DialogueId = 10110254,
          GUID = "194F5890",
          NextDialogue = 10110255,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"}}",
          SpeakNpcId = 200004,
          Subtitle = "He had a wife and a daughter, they were just an ordinary family of three. But then his wife passed away quite early, and he raised his daughter on his own.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5890"
        },
        [10110255] = {
          Camera = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
          ContentFR = "Quant à sa fille... comment elle s’appelait déjà ? Heidi ? Hayley ? J’ai oublié. Bref, elle était partie avec lui en voyage à Rougerive, mais elle n’en est jamais revenue.",
          DialogueId = 10110255,
          GUID = "194F58BA",
          NextDialogue = 10110256,
          RelatedWikiId = {
            [1] = 201006
          },
          SpeakNpcId = 200004,
          Subtitle = "As for his daughter... what's her name? Heidi? Hayley? I don't quite remember — anyway, she went on a trip to Scarletriver with Henrik but never returned with him.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F58BA"
        },
        [10110256] = {
          Camera = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
          ContentFR = "Il n’évoque jamais sa fille. Un jour, mon supérieur lui en a parlé autour d’un verre... Henrik a brisé son verre et s’est levé en claquant la porte.",
          DialogueId = 10110256,
          GUID = "194F58E4",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "He never talks about his daughter. One year, my superior asked about her over drinks, and Henrik just smashed his glass and stormed off.",
          VoiceName = "voice/$Locale$/story/1002/101102/194F58E4"
        },
        [10110257] = {
          Camera = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
          ContentFR = "Pfiu... Je te jure, je t’ai dit tout ce que je savais et tout ce que j’avais entendu. Tu pourrais me laisser tranquille, maintenant ? Rends-moi au moins la pellicule... Bon sang, toi qui as l’air si aimable, comment tu peux être aussi {性别:sournois|sournoise} ?",
          DialogueId = 10110257,
          GUID = "194F590E",
          NextOptions = {
            [1] = 10110258,
            [2] = 10110259
          },
          Scripts = "SEQ{\nTurnTo{TurnToDescription{\"200004:n(100001)\"}},\nPlayAnimation{ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{2}},\n}",
          SpeakNpcId = 200004,
          Subtitle = "Whew, I swear, I've told you everything I know and have heard about. Can you please let me off now? Just give me the film — darn it, you look nice, how could you be so cunning!",
          VoiceName = "voice/$Locale$/story/1002/101102/194F590E"
        },
        [10110258] = {
          ContentFR = "{性别:Désolé|Désolée} pour tout à l’heure. En fait, je plaisantais. Je ne t’ai pas vraiment pris en photo...",
          DialogueId = 10110258,
          GUID = "10110258",
          ImprPlusId = 1009,
          NextDialogue = 10110260
        },
        [10110259] = {
          ContentFR = "Je garde la pellicule pour l’instant. Je te la rendrai la prochaine fois que je viendrai chercher des infos.",
          DialogueId = 10110259,
          GUID = "10110259",
          ImprPlusId = 1006,
          NextDialogue = 10110260
        },
        [10110260] = {
          Camera = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
          ContentFR = "À la prochaine.",
          DialogueId = 10110260,
          ExStoryInfo = "Player",
          GUID = "194F5938",
          Scripts = "PARA{\nCameraMoveTo{_delay{4.2},TargetPosition{\"201.574219,-68.02832,168.996094,0.000123,-2.201465,-165.821976,35.000008,243.340027,false,Manual,4.0\"},duration{0}},\nSEQ{\nLookAt{LookAtDescription{\"100001:n(100001)\"}},\nTurnTo{TurnToDescription{\"100001:p(180)\"}},   \nMoveTo{ActorId{100001},TargetPoint{\"P101102Nvzhu3\"},MoveSpeed{80},Visibility{\"Show\"}}\n}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Well, take care, sir.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5938"
        },
        [10110261] = {
          DialogueId = 10110261,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 10110257,
          GUID = "194F5717",
          NextOptions = {
            [1] = 10110243,
            [2] = 10110244,
            [3] = 10110245
          }
        },
        [10110301] = {
          ContentFR = "Hein ? Tu pars comme ça ? Où est-ce que tu vas, hé !",
          DialogueId = 10110301,
          GUID = "194F6142",
          NextDialogue = 10110302,
          SpeakNpcId = 200004,
          Subtitle = "Hey! You're just gonna leave like that? Where are you going?! Oi!",
          VoiceName = "voice/$Locale$/story/1002/101103/194F6142"
        },
        [10110302] = {
          ContentFR = "Tu m’as promis de ne rien répéter, pas vrai ? Tu dois tenir parole...",
          DialogueId = 10110302,
          GUID = "194F616C",
          SpeakNpcId = 200004,
          Subtitle = "You promised not to tell anyone, didn't you? You have to stick to your word...",
          VoiceName = "voice/$Locale$/story/1002/101103/194F616C"
        },
        [10110401] = {
          ContentFR = "... Hé, mais... mais qu’est-ce que tu fais encore là ? Tu m’as foutu une de ces trouilles !",
          DialogueId = 10110401,
          GUID = "194F71AA",
          SpeakNpcId = 200004,
          Subtitle = "You're still here?! Scared me half to death.",
          VoiceName = "voice/$Locale$/story/1002/101104/194F71AA"
        },
        [10110501] = {
          Camera = "668.771606,50.456543,139.82666,0.000123,-1.999995,86.357468,45.0,207.220764,false,Manual,2.5",
          ContentFR = "Tout est prêt.",
          DialogueId = 10110501,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194F8212",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10110502,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 201007,
            [3] = 405002,
            [4] = 303006
          },
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}},\nSEQ{\nMoveTo{ActorId{200021},TargetPoint{\"P101105Aote\"},MoveSpeed{75},Visibility{\"Show\"}},\nPlayAnimation{ActorId{200021},AnimationId{\"Confident_Start\"},Duration{1}}\n},\nLookAt{_delay{1},LookAtDescription{\"100001:n(200021)\"}},\nCameraMoveTo{_delay{1.6},TargetPosition{\"614.092041,-84.750488,127.766602,0.000123,-3.400054,86.35746,35.0,365.6586,false,Manual,2.5\"},duration{0}},\nCameraMoveTo{_delay{1.7},TargetPosition{\"614.092041,-84.750488,156.081787,0.000124,-6.0,86.35746,35.0,364.392914,false,Manual,3.227706\"},blend{\"easeOutQuad\"},duration{3}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "It is all set.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F8212"
        },
        [10110502] = {
          Camera = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
          ContentFR = "J’ai un ami dans la cité intérieure, son carrosse passera par ici ce soir. Dès que Psyche sortira, on la fera monter et on la conduira hors des murs pour la mettre à l’abri. Même Henrik n’aurait pas le cran d’attaquer un carrosse d’un noble.",
          DialogueId = 10110502,
          GUID = "194F823C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10110503,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}},\nPlayAnimation{ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{2}},\nPlayAnimation{ActorId{200021},AnimationId{\"Talk02_End\"},Duration{2}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "I've squared things with a friend from the inner city, he will send his coach around here tonight. Once Psyche shows up, we'll take her out of town and lay low for a while. Henrik wouldn't dare rob a nob's coach.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F823C"
        },
        [10110503] = {
          ContentFR = "Ensuite... on improvisera.",
          DialogueId = 10110503,
          GUID = "194F8266",
          NextDialogue = 10110504,
          SpeakNpcId = 200021,
          Subtitle = "After that... we'll have to play it by ear.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8266"
        },
        [10110504] = {
          Camera = "597.891357,-27.287598,177.053955,0.000212,-9.60052,80.358948,40.0,340.8461,false,Manual,5.0",
          ContentFR = "Tu es vraiment plein de ressources.",
          DialogueId = 10110504,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "194F8290",
          NextDialogue = 10110505,
          SpeakNpcId = 100001,
          Subtitle = "You really have a wide network, don't you?",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8290"
        },
        [10110505] = {
          Camera = "722.716003,214.500488,130.546387,0.000153,5.999351,-137.03714,30.0,171.684738,false,Manual,6.0",
          ContentFR = "Ha ! Il faut bien tirer parti de toutes les saloperies que j’ai vécues ces dernières années. Mais... tu es {性别:sûr|sûre} qu’elle viendra ?",
          DialogueId = 10110505,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194F82BA",
          NextDialogue = 10110506,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{4}},\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_End\"},Duration{2}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Ha, got to make the most of all the cr*p I've been through these years. But are you sure she'll come?",
          VoiceName = "voice/$Locale$/story/1002/101105/194F82BA"
        },
        [10110506] = {
          Camera = "636.023804,126.125488,194.547607,0.000064,-21.999287,69.385223,35.000008,165.235214,false,Manual,22.0",
          ContentFR = "... Je n’en sais rien. Si elle ne vient pas, on passera au plan B.",
          DialogueId = 10110506,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:None",
            [2] = "100001:None"
          },
          GUID = "194F82E4",
          NextDialogue = 10110507,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{2}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "...I'm not sure. Anyway, if she doesn't show up, we'll go with plan B.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F82E4"
        },
        [10110507] = {
          Camera = "752.663208,304.167969,134.771973,0.000159,0.799091,-134.831451,30.000008,255.753464,false,Manual,3.0",
          ContentFR = "Foncer dans la Maison d’Hypnos et exposer les crimes d’Henrik ? Ha ! On dirait un roman de cape et d’épée...",
          DialogueId = 10110507,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194F830E",
          NextDialogue = 10110508,
          SpeakNpcId = 200021,
          Subtitle = "We break into the Hypnos' House and confront Henrik with his crimes — ha, sounds like the story of a hero from some pulp novel.",
          TalkActionId = {
            [1] = "200021:Angry01_Start",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F830E"
        },
        [10110508] = {
          ContentFR = "Mais sois {性别:prêt|prête} : même si on parvient à sauver Psyche ce soir, elle... ne tiendra pas longtemps. Tu te souviens de ce qu’on a vu dans la fosse ? C’est ce qui l’attend, inévitablement.",
          DialogueId = 10110508,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          GUID = "194F8338",
          NextDialogue = 10110509,
          SpeakNpcId = 200021,
          Subtitle = "But don't get your hopes up. Even if we manage to save Psyche today, she... won't last much longer. Remember the thing we saw in the pit? That's her inevitable fate.",
          TalkActionId = {
            [1] = "200021:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8338"
        },
        [10110509] = {
          Camera = "597.891357,-27.287598,177.053955,0.000213,-9.60052,80.35907,40.0,340.8461,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... On avisera, étape par étape.",
          DialogueId = 10110509,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200021:None"
          },
          FinalCamera = "595.481689,-41.476074,179.486816,0.000213,-9.60052,80.359016,40.0,340.8461,false,Manual,5.0",
          GUID = "194F8362",
          NextDialogue = 10110510,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{2}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "...One thing at a time.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101105/194F8362"
        },
        [10110510] = {
          Camera = "752.663208,304.167969,134.771973,0.000159,0.799091,-134.831451,30.000008,255.753464,false,Manual,3.0",
          ContentFR = "... D’accord. D’ailleurs, les Dégradés, ce n’est pas censé être le travail des Veilleurs ? Qu’est-ce qui a bien pu arriver à Henrik pour qu’il en arrive là...",
          DialogueId = 10110510,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194F838C",
          NextDialogue = 10110511,
          SpeakNpcId = 200021,
          Subtitle = "...Right. Speaking of which, aren't the Deteriorators usually handled by the Escort? What on earth has Henrik gone through to end up doing things like this...",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F838C"
        },
        [10110511] = {
          Camera = "594.983521,34.920898,147.270508,0.000067,-8.200632,79.375977,30.000008,567.112122,false,Manual,3.0",
          ContentFR = "Je crois... que j’ai compris pourquoi.",
          DialogueId = 10110511,
          ExStoryInfo = "Player",
          FinalCamera = "617.869507,29.944824,148.867676,0.000067,-6.800539,83.778389,30.000008,242.72731,false,Manual,3.0",
          GUID = "194F838D",
          NextOptions = {
            [1] = 10110512
          },
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101105/194F838D"
        },
        [10110512] = {
          ContentFR = "– Révéler les informations obtenues auprès de Kevin.",
          DialogueId = 10110512,
          GUID = "10110512.0",
          NextDialogue = 10110513
        },
        [10110513] = {
          Camera = "960.668701,-341.848633,606.558594,0.000024,-38.601192,121.190224,30.000002,362.012939,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Henrik était médecin, mais il a fermé son cabinet sans explication. Il avait une fille, disparue à Rougerive. Et dans la même ville, il a assassiné un Dégradé...",
          DialogueId = 10110513,
          FacialId = {
            [1] = "200021:Think01"
          },
          FinalCamera = "896.82605,-237.447266,505.624023,0.000011,-40.001194,121.590363,30.000002,362.012939,false,Manual,22.0",
          GUID = "194F83B6",
          NextDialogue = 10110514,
          SpeakNpcId = 200021,
          Subtitle = "...Henrik used to be a doctor, but he shut down his practice for some reason; he had a daughter, but she went missing in Scarletriver; Henrik murdered a Deteriorator in Scarletriver...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101105/194F83B6"
        },
        [10110514] = {
          Camera = "673.087097,200.460449,158.318604,0.00003,-18.200924,80.989754,30.000013,71.430817,false,Manual,22.0",
          ContentFR = "Exact. Et surtout, ces trois événements ont eu lieu la même année. Ça ne peut pas être une coïncidence.",
          DialogueId = 10110514,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Doubt01"
          },
          GUID = "194F83E0",
          NextDialogue = 10110515,
          SpeakNpcId = 100001,
          Subtitle = "Right. More importantly, these three events happened in the same year, so they must be correlated.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F83E0"
        },
        [10110515] = {
          Camera = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
          ContentFR = "Si les pensionnaires de la Maison d’Hypnos sont vraiment tous des Dégradés... Oui, je vois où tu veux en venir.",
          DialogueId = 10110515,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "194F840A",
          NextDialogue = 10110516,
          SpeakNpcId = 200021,
          Subtitle = "And the lodgers at the Hypnos' House are likely all Deteriorators... Hmm, I see what you're getting at.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F840A"
        },
        [10110516] = {
          Camera = "684.15155,260.363281,147.201416,0.000142,-1.401261,-120.639412,30.000002,200.0,false,Manual,3.0",
          ContentFR = "Sa fille a sans doute trouvé la mort à Rougerive, probablement à cause d’un Dégradé. De là est née sa haine, une rancune qui ne s’est jamais éteinte, même des années plus tard...",
          DialogueId = 10110516,
          GUID = "194F8434",
          NextDialogue = 10110517,
          SpeakNpcId = 200021,
          Subtitle = "Henrik's daughter was likely killed in Scarletriver, possibly by a Deterioration, sparking Henrik's deep-seated hatred towards them, which even after so many years, hasn't faded...",
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8434"
        },
        [10110517] = {
          ContentFR = "Alors, il a trouvé un moyen de capturer certains Dégradés, pour ensuite les exécuter de sa propre main. C'est ta conclusion, hein ?",
          DialogueId = 10110517,
          GUID = "194F845E",
          NextDialogue = 10110518,
          SpeakNpcId = 200021,
          Subtitle = "So, he somehow managed to control some of the Deteriorations and administer his own brand of justice — that's your conclusion, right?",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F845E"
        },
        [10110518] = {
          Camera = "649.498047,158.819336,162.394043,0.000159,-15.000577,73.956459,30.000002,106.04982,false,Manual,2.113648",
          ContentFR = "... Oui. Mais peu importe ses raisons, peu importe ce que deviennent les Dégradés à la fin... Nous devons—",
          DialogueId = 10110518,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "194F8488",
          NextDialogue = 10110519,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{2}},\nPlayAnimation{ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{2}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "...Yes. But regardless of what he's gone through, or what the Deteriorators would eventually become, we must—",
          VoiceName = "voice/$Locale$/story/1002/101105/194F8488"
        },
        [10110519] = {
          Camera = "964.300659,-14.221191,117.446289,0.000137,-2.199826,147.753998,20.0,107.293198,false,Manual,15.0",
          ContentFR = "Aaaahhh— !",
          DialogueId = 10110519,
          GUID = "194F8489",
          LookAt = {
            [1] = "200021:p(P101105Bai)",
            [2] = "100001:p(P101105Bai)"
          },
          NextDialogue = 10110520,
