        [10110601] = {
          Camera = "-24.092529,-443.466797,251.954834,0.000135,-4.199583,87.351624,25.0,1.5,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Vous êtes enfin là ! J’ai eu une peur bleue !",
          DialogueId = 10110601,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-19.506348,-348.400391,223.084106,0.000123,-22.200073,87.351807,25.0,1.5,false,DoNotOverride,22.0",
