          },
          NextDialogue = 10110602,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 201007,
            [3] = 405002,
            [4] = 303006
          },
          Scripts = "PARA{\nSEQ{\nSetLocation{ActorId{100001},TargetPoint{\"P10110602\"},Visibility{\"Show\"}}\n}\n,SEQ{\nMoveTo{ActorId{200021},MoveSpeed{90},TargetPoint{\"P10110601\"}},PlayAnimation{_delay{0.3},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{1}}\n},\nPlayAnimation{_delay{0.7},ActorId{200002},AnimationId{\"Sigh_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "You're finally here!! You've no idea how scary it was!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101106/194F927A"
        },
        [10110602] = {
          Camera = "-58.66626,184.545898,58.416016,0.000013,9.599646,-71.385262,25.000002,245.13945,false,Manual,22.0",
          ContentFR = "C’était toi qui poussais des cris tout à l’heure ? Qu’est-ce qui s’est passé ?",
          DialogueId = 10110602,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "194F92A4",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10110603,
          Scripts = "PARA{\nSetLocation{ActorId{200021},TargetPoint{\"P10110603\"},Visibility{\"Show\"}},\nPlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{1}},\nPlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Sigh_End\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Was that you shrieking just now? What happened?",
          VoiceName = "voice/$Locale$/story/1002/101106/194F92A4"
        },
        [10110603] = {
          Camera = "3.640381,-208.794922,183.625,0.000189,-20.999163,86.982307,50.000011,313.724945,false,DoNotOverride,3.0",
          ContentFR = "Je faisais exactement ce que vous m’aviez demandé, je surveillais les alentours... et comme vous l’aviez prévu, Psyche est sortie ! Alors j’ai couru vers elle pour l’attraper et la ramener vers vous.",
          DialogueId = 10110603,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "194F92CE",
          NextDialogue = 10110604,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{3.8}},PlayAnimation{ActorId{200002},AnimationId{\"Angry01_End\"},Duration{4.2}},PlayAnimation{ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "I was just keeping watch here as you asked me to... And just like you expected, Psyche came out! I ran to her, ready to take her to you.",
          VoiceName = "voice/$Locale$/story/1002/101106/194F92CE"
        },
        [10110604] = {
          Camera = "5.263672,-60.99707,136.059082,0.000133,-20.999565,92.985939,35.000008,170.151947,false,Manual,22.0",
          ContentFR = "Mais tout à coup, elle s’est jetée sur moi, les yeux fous... Heureusement que moi, la grande Snow, j’ai des réflexes divins ! Mais... est-ce que c’était vraiment Psyche ? Elle n’avait plus rien de son air habituel... elle ressemblait à... une bête sauvage !",
          DialogueId = 10110604,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "2.735596,-5.030273,114.464722,0.000139,-19.799591,92.585823,35.000008,170.151947,false,Manual,22.0",
          GUID = "194F92F8",
          NextDialogue = 10110605,
          Scripts = "SEQ{\nPlayAnimation{ActorId{200002},AnimationId{\"Shock_Start\"},Duration{3.7}},\nPlayAnimation{ActorId{200002},AnimationId{\"Shock_End\"},Duration{6.3}},\nPlayAnimation{ActorId{200002},AnimationId{\"Disagree\"},Duration{3}},\nPlayAnimation{ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "But she suddenly lunged at me, looking all scary... Lucky I was quick on my feet! But... was that really Psyche? She was nothing like her usual self, more like... a wild beast!",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 0.4,
          VoiceName = "voice/$Locale$/story/1002/101106/194F92F8"
        },
        [10110605] = {
