          Scripts = "SEQ{\nTurnTo{TurnToDescription{\"200021:p(65)\"}},PlayAnimation{ActorId{200021},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "Oh no... Deterioration's started!",
          TalkActionId = {
