          Scripts = "SEQ{\nSetLocation{ActorId{200021},TargetPoint{\"P101108Aote3\"},Visibility{\"Show\"}},\nSetRotation{SetRotationDescription{\"200021:n(200005)\"}}\n}\n",
          SpeakNpcId = 200005,
          Subtitle = "...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB446"
        },
        [10110808] = {
          ContentFR = "... La Maison d’Hypnos... abritait les Dégradés... des enfants rejetés par le destin...",
          DialogueId = 10110808,
          GUID = "194FB470",
          LookAt = {
            [1] = "200005:p(P10110802)"
          },
          NextDialogue = 10110809,
          RelatedWikiId = {
            [1] = 405002,
            [2] = 303006
          },
          Scripts = "LookAt{_dealy{1},LookAtDescription{"200005:n(200005)"}},",
          SpeakNpcId = 200005,
          Subtitle = "The Hypnos' House shelters... Deteriorators... those forsaken by fate...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB470"
        },
        [10110809] = {
          Camera = "112.929688,70.482422,87.875,0.00013,-23.000366,23.190859,25.000006,670.426025,false,DoNotOverride,4.0",
          ContentFR = "Leur sort... devait être... une balle glaciale...",
          DialogueId = 10110809,
          GUID = "194FB49A",
          NextDialogue = 10110810,
          SpeakNpcId = 200005,
          Subtitle = "Their destined end... was supposed to be... a cold bullet...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB49A"
        },
        [10110810] = {
          Camera = "164.302734,13.386597,50.255859,0.00003,22.395601,166.592819,35.000008,164.206451,false,Manual,7.5",
          ContentFR = "Oui. En Hyperborea pour les Charons tout signe de Dégradation est immédiatement puni, on emmène l’affligé pour l’exécuter, avant qu’il ne devienne un Souillé. Attends... tu veux dire que...",
          DialogueId = 10110810,
          FacialId = {
            [1] = "200021:Sad01"
          },
          GUID = "194FB4C4",
          LookAt = {
            [1] = "200005:n(200005)"
          },
          NextDialogue = 10110811,
          Scripts = "PlayAnimation{_delay{9.5},ActorId{200021},AnimationId{"Sigh_Start"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "Right. In Hyperborea, any Charons showing signs of Deterioration will be taken away immediately to prevent them from turning into Filthoids. Wait, are you saying...",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101108/194FB4C4"
        },
        [10110811] = {
          Camera = "372.853516,484.305298,136.691406,0.0,0.0,89.999985,15.0,868.29187,false,DoNotOverride,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... Leurs familles... ne pouvaient pas... s’y résoudre... Elles m’ont demandé... de leur donner une fin... digne... douce...",
          DialogueId = 10110811,
          FinalCamera = "372.853516,570.94812,136.691406,0.0,0.0,89.999985,17.5,868.29187,false,DoNotOverride,4.0",
          GUID = "194FB4EE",
          LookAt = {
            [1] = "200061:n(200005)"
          },
          NextDialogue = 10110812,
          Scripts = "PARA{\nCameraMoveTo{_delay{6.6},TargetPosition{\"385.876953,1184.178467,198.099609,0.0,0.0,89.999985,20.0,868.29187,false,DoNotOverride,4.0\"},duration{0}},\nCameraMoveTo{_delay{6.7},TargetPosition{\"385.876953,1316.043457,198.099609,0.0,0.0,89.999985,22.5,868.29187,false,DoNotOverride,4.0\"},blend{\"easeOutQuad\"},duration{5}},\nSEQ{\nSetLocation{ActorId{200021},TargetPoint{\"P101108Aote4\"},Visibility{\"Show\"}},\nSetRotation{SetRotationDescription{\"200021:n(200005)\"}}\n}\n}",
          SpeakNpcId = 200005,
          Subtitle = "...Their families... didn't have the heart to see... So they hoped... that I could...",
          TalkActionId = {
            [1] = "200021:Sigh_End"
          },
          ToFinalCameraBlendTime = 6.5,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB4EE"
        },
        [10110812] = {
          Camera = "473.628906,1123.418335,230.330078,0.0,0.0,0.0,35.0,164.206451,false,DoNotOverride,7.5",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... Qu’ils s’en aillent... en restant eux-mêmes.",
          DialogueId = 10110812,
          FinalCamera = "468.494141,1123.418335,230.330078,0.0,0.0,0.0,35.0,164.206451,false,DoNotOverride,7.5",
          GUID = "194FB518",
          NextDialogue = 10110813,
          Scripts = "PARA{\nCameraMoveTo{_delay{2.1},TargetPosition{\"332.396484,1123.968628,289.537109,0.0,0.0,0.0,20.0,164.206451,false,DoNotOverride,7.5\"},duration{0}},\nCameraMoveTo{_delay{2.2},TargetPosition{\"321.052734,1123.968628,289.537109,0.0,0.0,0.0,20.0,164.206451,false,DoNotOverride,7.5\"},duration{2}},\nCameraMoveTo{_delay{4.3},TargetPosition{\"300.822266,955.277466,245.894531,0.0,0.0,0.0,10.0,164.206451,false,DoNotOverride,7.5\"},duration{0}},\nCameraMoveTo{_delay{4.4},TargetPosition{\"275.3125,955.277466,245.894531,0.0,0.0,0.0,10.0,164.206451,false,DoNotOverride,7.5\"},blend{\"easeOutQuad\"},duration{3}}\n}",
          SpeakNpcId = 200005,
          Subtitle = "Help end their misery... in a decent, gentle way...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB518"
        },
        [10110813] = {
          Camera = "364.259766,-56.860779,113.087891,0.000055,10.399625,-82.59729,15.0,149.347931,false,Manual,1.2",
          ContentFR = "Comme... ce jour-là, avec Hayley...",
          DialogueId = 10110813,
          FinalCamera = "361.480469,-57.074036,113.087891,0.000058,10.399625,-85.597328,15.0,46.371769,false,Manual,2.188352",
          GUID = "194FB542",
          NextDialogue = 10110814,
          SpeakNpcId = 200005,
          Subtitle = "Just like... how I... sent away Hayley...",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB542"
        },
        [10110814] = {
          Camera = "146.675781,107.209351,63.904297,0.000043,10.599551,-114.99369,30.000008,58.469177,false,Manual,22.0",
          ContentFR = "... Attends... Vous voulez dire que l’affaire de Rougerive, le Dégradé qu’on croyait assassiné... c’était votre fille ? Votre fille, Hayley ?!",
          DialogueId = 10110814,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200061:Shock01"
          },
          FinalCamera = "141.306641,95.676819,66.283203,0.000045,10.999548,-113.993042,30.000008,58.469177,false,Manual,22.0",
          GUID = "194FB56C",
          NextDialogue = 10110815,
          SpeakNpcId = 200061,
          Subtitle = "...Are you saying... that Deteriorator in Scarletriver... was your daughter Hayley?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB56C"
        },
        [10110815] = {
          Camera = "7.115234,146.331909,155.232422,-5.000005,-37.004673,-27.967878,20.000011,106.21656,false,DoNotOverride,3.0",
          ContentFR = "... Tu sais ça aussi... Ce n’était que... le dernier sursaut... d’un père désespéré...",
          DialogueId = 10110815,
          GUID = "194FB596",
          LookAt = {
            [1] = "200005:n(200061)"
          },
          NextDialogue = 10110816,
          RelatedWikiId = {
            [1] = 201006
          },
          Scripts = "LookAt{_delay{3},LookAtDescription{"200005:p(P10110802)"}}",
          SpeakNpcId = 200005,
          Subtitle = "...You know about that too... That was merely... the last desperate struggle... of a father in despair...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB596"
        },
        [10110816] = {
          Camera = "61.728516,24.99762,106.603516,0.000052,17.397959,-151.616104,35.0,66.756615,false,DoNotOverride,4.0",
          ContentFR = "Nous t’avons jugé trop vite... Nous nous sommes trompés à ton sujet, Henrik. Pardonne-nous.",
          DialogueId = 10110816,
          GUID = "194FB5C0",
          NextDialogue = 10110817,
          Scripts = "PlayAnimation{_delay{4.5},ActorId{200021},AnimationId{"Explain02_Start"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "We've been wrong about you all along... We're truly sorry, Mr Henrik.",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB5C0"
        },
        [10110817] = {
          Camera = "-88.710938,13.800842,156.517578,0.000078,-25.799891,20.60397,25.0,66.756615,false,DoNotOverride,4.0",
          ContentFR = "... Ne me pardonnez pas...",
          DialogueId = 10110817,
          GUID = "194FB5EA",
          LookAt = {
            [1] = "200005:n(200021)"
          },
          NextDialogue = 10110818,
          Scripts = "SetLocation{ActorId{200021},TargetPoint{"P101108Aote3"},Visibility{"Show"}},",
          SpeakNpcId = 200005,
          Subtitle = "...Do not... forgive...",
          TalkActionId = {
            [1] = "200021:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101108/194FB5EA"
        },
        [10110818] = {
          Camera = "-592.291016,-163.594299,286.255859,0.0,0.0,89.999985,15.0,78.653053,false,DoNotOverride,2.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "J’ai guidé chacun d’eux... vers le sommeil... C’est mon péché... impardonnable...",
          DialogueId = 10110818,
          FinalCamera = "-592.291016,-125.502869,286.255859,0.0,0.0,89.999954,18.0,78.653053,false,DoNotOverride,2.0",
          GUID = "194FB614",
          NextDialogue = 10110819,
          Scripts = "PARA{\nSetLocation{ActorId{200021},TargetPoint{\"P101108Aote4\"},Visibility{\"Hide\"}},\nCameraMoveTo{_delay{3.1},TargetPosition{\"-758.84375,-464.784851,67.259766,0.000049,-9.999997,89.999992,20.0,78.653053,false,DoNotOverride,2.0\"},duration{0}},\nCameraMoveTo{_delay{3.2},TargetPosition{\"-758.84375,-384.849854,53.855469,0.00005,-3.999991,89.999962,20.0,78.653053,false,DoNotOverride,2.0\"},blend{\"easeOutQuad\"},duration{4}}\n}",
          SpeakNpcId = 200005,
          Subtitle = "I brought them... to sleep... This is my unforgivable sin...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB614"
        },
        [10110819] = {
          Camera = "160.949219,75.923035,61.925781,0.000051,15.199233,-138.792435,18.000004,38.56216,false,DoNotOverride,22",
          ContentFR = "Et Psyche, alors... ?",
          DialogueId = 10110819,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200061:Sad01"
          },
          GUID = "194FB63E",
          NextDialogue = 10110820,
          Scripts = "SetLocation{ActorId{200021},TargetPoint{"P101108Aote4"},Visibility{"Show"}}",
          SpeakNpcId = 200061,
          Subtitle = "Then what happened to Psyche...?",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB63E"
        },
        [10110820] = {
          Camera = "49.150391,56.432068,87.480469,0.000103,-16.60022,15.224733,30.0,212.168549,false,Manual,4.0",
          ContentFR = "... J’ai tenté... avec l’Éclat stellaire... une dernière fois...",
          DialogueId = 10110820,
          GUID = "194FB668",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110820.T_Story_Recall_10110820'",
          LookAt = {
            [1] = "200005:n(200005)"
          },
          NextDialogue = 10110821,
          RelatedWikiId = {
            [1] = 403002
          },
          SpeakNpcId = 200005,
          Subtitle = "I tried... with the Crystallo of Stella...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB668"
        },
        [10110821] = {
          Camera = "49.150391,56.432068,87.480469,0.000104,-16.60022,15.224788,30.0,212.168549,false,Manual,4.0",
          ContentFR = "Mais je n’ai pas pu... enrayer la Dégradation...",
          DialogueId = 10110821,
          GUID = "194FB692",
          NextDialogue = 10110822,
          SpeakNpcId = 200005,
          Subtitle = "But still... couldn't avert... Deterioration...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB692"
        },
        [10110822] = {
          Camera = "49.150391,56.432068,87.480469,0.000104,-16.60022,15.224788,30.0,212.168549,false,DoNotOverride,22",
          ContentFR = "J’aurais dû... comme toujours... l’accompagner jusqu’au bout... Mais cette enfant... elle était si spéciale...",
          DialogueId = 10110822,
          FinalCamera = "49.150391,56.432068,87.480469,0.000105,-14.200106,15.425169,30.000002,212.168549,false,DoNotOverride,22",
          GUID = "194FB6BC",
          LookAt = {
            [1] = "200005:p(P10110802)"
          },
          NextDialogue = 10110823,
          SpeakNpcId = 200005,
          Subtitle = "I was supposed to let her go... like all the others... but that child was so special...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB6BC"
        },
        [10110823] = {
          ContentFR = "Elle connaissait son sort... et malgré tout, elle continuait de sourire... Des mois durant, elle a brillé... comme un rayon de soleil... dans ce recoin... abandonné des dieux... Comme Hayley... autrefois...",
          DialogueId = 10110823,
          GUID = "194FB6E6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110823.T_Story_Recall_10110823'",
          NextDialogue = 10110824,
          Scripts = "PARA{\nSetLocation{ActorId{200021},TargetPoint{\"P101108Aote4\"},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 200005,
          Subtitle = "She knew what was coming, yet she's always worn... a smile... For months, she shone like a ray of sunlight... in this... godforsaken place... just like my Hayley...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB6E6"
        },
        [10110824] = {
          Camera = "-793.369141,305.333496,141.117188,0.0,0.0,91.0,25.0,64.625702,false,DoNotOverride,3.0",
          ContentFR = "... Je suis trop vieux... Je n’ai pas eu la force... de recommencer...",
          DialogueId = 10110824,
          FinalCamera = "-796.826172,305.333496,141.117188,0.0,0.0,89.0,25.0,64.625702,false,DoNotOverride,3.0",
          GUID = "194FB710",
          NextDialogue = 10110825,
          Scripts = "PARA{\nCameraMoveTo{_delay{2.6},TargetPosition{\"-1051.294922,84.778625,89.935547,0.000001,-2.999962,46.000069,20.0,64.625702,false,DoNotOverride,3.0\"},duration{0}},\nCameraMoveTo{_delay{2.7},TargetPosition{\"-1054.726562,88.218262,89.935547,0.000001,-2.999908,43.999973,20.0,64.625702,false,DoNotOverride,3.0\"},duration{2.5}}\n}",
          SpeakNpcId = 200005,
          Subtitle = "I'm old... I couldn't... do it again...",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB710"
        },
        [10110825] = {
          Camera = "214.019531,188.597473,38.626953,0.000023,11.498903,-119.800552,20.000008,66.756615,false,DoNotOverride,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Alors tu as hésité. Et dans ce moment de faiblesse, Psyche a perdu la raison. Elle t’a attaqué... et s’est enfuie.",
          DialogueId = 10110825,
          FinalCamera = "214.019531,188.597473,38.626953,0.000024,12.098812,-125.20121,20.000008,66.756615,false,DoNotOverride,4.0",
          GUID = "194FB73A",
          NextDialogue = 10110826,
          SpeakNpcId = 200021,
          Subtitle = "...So in your hesitation, you missed the last window. Psyche lost her mind, attacked you, and ran away.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB73A"
        },
        [10110826] = {
          Camera = "90.787109,25.72345,76.884766,0.000089,9.199021,-96.900833,30.000013,150.0,false,DoNotOverride,4.0",
          ContentFR = "N... non... ce n’est pas possible... !",
          DialogueId = 10110826,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "194FB764",
          NextDialogue = 10110827,
          Scripts = "PARA{\nPlayAnimation{_delay{2.5},ActorId{200002},AnimationId{\"Sigh_Start\"},Duration{1}},\nSetLocation{ActorId{200021},TargetPoint{\"P101108Aote7\"},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "I can't believe all this...!",
          TalkActionId = {
            [1] = "200002:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101108/194FB764"
        },
        [10110827] = {
          Camera = "234.738281,193.986938,31.15625,0.000068,14.59791,-132.609695,35.000008,1141.186523,false,Manual,22",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Vous... Daimons... vous pouvez l’arrêter...",
          DialogueId = 10110827,
          FinalCamera = "226.222656,184.724487,34.431641,0.000068,14.59791,-132.609695,35.000008,1141.186523,false,Manual,22",
          GUID = "194FB78E",
          LookAt = {
            [1] = "200005:n(200061)"
          },
          NextDialogue = 10110828,
          Scripts = "SEQ{\nCameraMoveTo{_delay{2.2},TargetPosition{\"175.121094,112.294922,57.634766,0.000084,12.59758,-133.406189,35.000011,84.857964,false,Manual,3.0\"},duration{0}},\nCameraMoveTo{_delay{0.1},TargetPosition{\"168.296875,105.074829,59.853516,0.000084,12.397572,-130.606537,35.000011,71.607964,false,Manual,3.0\"},blend{\"easeOutQuad\"},duration{2.5}}\n}",
          SpeakNpcId = 200005,
          Subtitle = "You're Daimons... you can... stop that child...",
          TalkActionId = {
            [1] = "200002:Sigh_End"
          },
          ToFinalCameraBlendTime = 2.2,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB78E"
        },
        [10110828] = {
          ContentFR = "Elle est si douce... Faire du mal aux autres... c’est la dernière chose qu’elle voudrait...",
          DialogueId = 10110828,
          GUID = "194FB7B8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110823_2.T_Story_Recall_10110823_2'",
          LookAt = {
            [1] = "200005:n(200005)"
          },
          Scripts = "PARA{\nSetLocation{ActorId{200002},TargetPoint{\"P101108Bai5\"},Visibility{\"Show\"}},\nSetLocation{ActorId{200021},TargetPoint{\"P101108Aote5\"},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 200005,
          Subtitle = "She has such a gentle soul... hurting others is the last thing she'd want...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB7B8"
        },
        [10110829] = {
          Camera = "255.0,93.0,161.751953,-26.036255,-90.0,14.036263,20.0,141.431259,false,DoNotOverride,4.0",
          ContentFR = "Je vous en prie... sauvez... Psyche...",
          DialogueId = 10110829,
          FinalCamera = "255.0,93.0,191.751953,-26.036255,-90.0,14.036263,20.0,141.431259,false,DoNotOverride,4.0",
          GUID = "194FB7E2",
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/01/enrike_death"},PlayAs2D{true}}",
          SpeakNpcId = 200005,
          Subtitle = "Please... save... Psyche...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB7E2"
        },
        [10110830] = {
          Camera = "207.0,97.0,450.820312,-12.0,-90.0,0.0,20.0,141.431259,false,DoNotOverride,4.0",
          ContentFR = "Sauvez... Hayley...",
          DialogueId = 10110830,
          FinalCamera = "207.0,97.0,550.619141,-12.0,-90.0,0.0,20.0,141.431259,false,DoNotOverride,4.0",
          GUID = "194FB80C",
          SpeakNpcId = 200005,
          Subtitle = "Save... my Hayley...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB80C"
        },
        [10110831] = {
          Camera = "252.439453,60.507812,27.751953,0.000142,17.999992,-160.391937,30.0,207.242523,false,Manual,10.0",
          ContentFR = "Monsieur Henrik ! ... ouin...",
          DialogueId = 10110831,
          GUID = "194FB836",
          Scripts = "PlayAnimation{_delay{4.5},ActorId{200002},AnimationId{"Sigh_Start"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Mr Henrik!",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB836"
        },
        [10110832] = {
          ContentFR = "Partons. Nous devons faire vite.",
          DialogueId = 10110832,
          GUID = "194FB860",
          SpeakNpcId = 200021,
          Subtitle = "Let's go... we must hurry.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101108/194FB860"
        },
        [10110901] = {
          Camera = "141.478516,-28.77478,20.587891,0.000128,-1.596734,146.783646,18.0,61.395397,false,Manual,3.0",
          ContentFR = "Vous... vous partez chercher Psyche ?",
          DialogueId = 10110901,
          GUID = "194FC3B2",
          LookAt = {
            [1] = "200045:n(100001)"
          },
          NextDialogue = 10110902,
