          ContentFR = "... Mais quand j’ai voulu lui rendre sa gentillesse, il était déjà trop tard.",
          DialogueId = 10110904,
          GUID = "194FC430",
          NextDialogue = 10110905,
          SpeakNpcId = 200045,
          Subtitle = "...But by the time I wanted to return her kindness, it was already too late.",
          TalkActionId = {
            [1] = "200045:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC430"
        },
        [10110905] = {
