        },
        [10111004] = {
          ContentFR = "Argh— !!",
          DialogueId = 10111004,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "194FD498",
          SpeakNpcId = 100001,
          Subtitle = "Argh—!! (gasp)",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD498"
        },
        [10111005] = {
          ContentFR = "Le vent est trop fort... je ne peux pas m’approcher... !",
          DialogueId = 10111005,
          ExStoryInfo = "Player",
          GUID = "194FD499",
          SpeakNpcId = 100001,
          Subtitle = "Resonance isn't working... What should I do?",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD499"
        },
        [10111006] = {
          ContentFR = "Reviens, c’est trop dangereux ! Merde... si ça continue, nous allons tous y rester...",
          DialogueId = 10111006,
          Duration = 4.5,
          GUID = "194FD500",
          SpeakNpcId = 200021,
          Subtitle = "Don't waste your energy; Resonance can't stop Deterioration!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD500"
        },
        [10111007] = {
          ContentFR = "Elle a perdu la raison. Préparez-vous au combat !",
          DialogueId = 10111007,
          Duration = 2.5,
          GUID = "194FD516",
          SpeakNpcId = 200021,
          Subtitle = "She's lost her mind, get ready to fight!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD516"
        },
        [10111101] = {
          ContentFR = "Psyche, tu m’entends ?",
          DialogueId = 10111101,
          ExStoryInfo = "Player",
          GUID = "194FE482",
          NextDialogue = 10111102,
          SpeakNpcId = 100001,
          Subtitle = "Psyche, can you hear me?",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE482"
        },
        [10111102] = {
          ContentFR = "Réponds-moi...",
          DialogueId = 10111102,
          ExStoryInfo = "Player",
          GUID = "194FE4AC",
          NextDialogue = 10111103,
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4AC"
        },
        [10111103] = {
          ContentFR = "Tu l’as dit toi-même... il y a tant de choses que tu veux encore accomplir...",
          DialogueId = 10111103,
          ExStoryInfo = "Player",
          GUID = "194FE4D6",
          NextDialogue = 10111104,
          SpeakNpcId = 100001,
          Subtitle = "You said it yourself, there's so much you want to do...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4D6"
        },
        [10111104] = {
          ContentFR = "Tu quitteras Givrelac, pour découvrir d’autres horizons...",
          DialogueId = 10111104,
          ExStoryInfo = "Player",
          GUID = "194FE500",
          NextDialogue = 10111105,
          SpeakNpcId = 100001,
          Subtitle = "You'll leave Icelake for those unseen places—",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE500"
        },
        [10111105] = {
          ContentFR = "... Tu iras sur une petite île, y bâtir une maison au bord de la mer...",
          DialogueId = 10111105,
          ExStoryInfo = "Player",
          GUID = "194FE52A",
          NextDialogue = 10111106,
          SpeakNpcId = 100001,
          Subtitle = "...You'll go to a small island, where you can build a few houses by the sea...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE52A"
        },
        [10111106] = {
          ContentFR = "... Tu planteras des fleurs blanches autour de cette maison...",
          DialogueId = 10111106,
          ExStoryInfo = "Player",
          GUID = "194FE554",
          NextDialogue = 10111107,
          SpeakNpcId = 100001,
          Subtitle = "...and grow white flowers around them...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE554"
        },
        [10111107] = {
          ContentFR = "... Et sous un large chapeau, tu parleras à tes amis de la neige de Givrelac...",
          DialogueId = 10111107,
          ExStoryInfo = "Player",
          GUID = "194FE57E",
          NextDialogue = 10111108,
          SpeakNpcId = 100001,
          Subtitle = "...Talk about the snow in Icelake with your friends, while shading yourself with a wide-brimmed sunhat...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE57E"
        },
        [10111108] = {
          ContentFR = "Réponds-moi, Psyche...",
          DialogueId = 10111108,
          ExStoryInfo = "Player",
          GUID = "194FE5A8",
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE5A8"
        },
        [10111201] = {
          ContentFR = "Psyche, je suis venu te ramener à la maison.",
          DialogueId = 10111201,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194FF4EA",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, I'm here to take you home.",
          VoiceName = "voice/$Locale$/story/1002/101127/1950EB02"
        },
        [10111301] = {
          ContentFR = "C’est... ma maison ?",
          DialogueId = 10111301,
          GUID = "191B889A",
          SpeakNpcId = 200006,
          Subtitle = "Is this... my home?",
          VoiceName = "voice/$Locale$/story/1002/101113/191B889A"
        },
        [10111401] = {
          ContentFR = "Chéri, regarde... Psyche nous sourit.",
          DialogueId = 10111401,
          GUID = "191B88C4",
          NextDialogue = 10111402,
          SpeakNpcId = 200039,
          Subtitle = "Honey, look, Psyche is smiling at us.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88C4"
        },
        [10111402] = {
          ContentFR = "... Je me demande si la venue de cet enfant au monde est une bénédiction... ou une malédiction.",
          DialogueId = 10111402,
          GUID = "191B88EE",
          NextDialogue = 10111403,
          SpeakNpcId = 200038,
          Subtitle = "...I wonder whether this child's birth in this world was a blessing or a curse.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88EE"
        },
        [10111403] = {
          ContentFR = "... Oui. Nous ne sommes pas venus au monde sous une pluie de bénédictions.",
          DialogueId = 10111403,
          GUID = "191B8918",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...Yes, we weren't born with blessings.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B8918"
        },
        [10111501] = {
          ContentFR = "Maman ! J’avais promis à Psyche de l’inviter aujourd’hui pour jouer avec mes blocs...",
          DialogueId = 10111501,
          GUID = "191BB9D2",
          NextDialogue = 10111502,
          SpeakNpcId = 200040,
          Subtitle = "Mum! I promised Psyche I'd bring her home today to play with blocks...",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9D2"
        },
        [10111502] = {
          ContentFR = "Qui t’a dit de jouer avec elle ? Je t’ai répété mille fois d’éviter ces gens impurs. Tu veux mourir, frappé par la magie noire ?",
          DialogueId = 10111502,
          GUID = "191BB9FC",
          NextDialogue = 10111503,
          SpeakNpcId = 200041,
          Subtitle = "Who says you can play with her? How many times have I told you to stay away from these unclean people? Do you want to be killed by dark magic?",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9FC"
        },
        [10111503] = {
          ContentFR = "Regarde-moi ça... les blocs sont tous salis. Jette-les immédiatement !",
          DialogueId = 10111503,
          GUID = "191BBA26",
          SpeakNpcId = 200041,
          Subtitle = "Ugh, now these blocks are all dirty. Throw them away now!",
          VoiceName = "voice/$Locale$/story/1002/101115/191BBA26"
        },
        [10111601] = {
          ContentFR = "Ce jour-là... pleine d’injustice et d’incompréhension, je me suis lavée toute la nuit... jusqu’à ce que ma peau se mette à saigner.",
          DialogueId = 10111601,
          GUID = "191BBA50",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "That day, feeling wronged and confused, I bathed all night until my skin bled.",
          VoiceName = "voice/$Locale$/story/1002/101116/191BBA50"
        },
        [10111701] = {
          ContentFR = "Non, monsieur, vous vous trompez ! Ma fille a toujours été raisonnable, elle n’aurait jamais volé le collier d’un client, encore moins l’avoir caché dans un pot de fleurs !",
          DialogueId = 10111701,
          GUID = "191BCA3A",
          NextDialogue = 10111702,
          SpeakNpcId = 200039,
          Subtitle = "So what if he hit your daughter? It was all because your daughter's stuff was an eyesore, wasn't it?",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA3A"
        },
        [10111702] = {
          ContentFR = "Assez ! Y a-t-il seulement un seul gosse de Charon qui ait les mains propres ?",
          DialogueId = 10111702,
          GUID = "191BCA64",
          NextDialogue = 10111703,
          SpeakNpcId = 200043,
          Subtitle = "Exactly. And it was just a pot of flowers, so cut the whimper, you little twerp. Don't get your filthy tears on my uniform.",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA64"
        },
        [10111703] = {
          ContentFR = "Bon, puisqu’elle est si innocente, qu’elle le prouve : qu’elle brise elle-même tous ces pots de fleurs. Et on verra bien.",
          DialogueId = 10111703,
          GUID = "191BCA8E",
          NextDialogue = 10111704,
          SpeakNpcId = 200044,
          Subtitle = "What are you still doing here? The Security Bureau isn't a place for your nonsense.",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA8E"
        },
        [10111704] = {
          ContentFR = "... Parce que nous sommes des "Enfants du Démon".",
          DialogueId = 10111704,
          GUID = "191BDAA2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...It's all because, we are "demon's children."",
          VoiceName = "voice/$Locale$/story/1002/101117/191BDAA2"
        },
        [10111801] = {
          ContentFR = "Aaah... pourquoi... ?",
          DialogueId = 10111801,
          GUID = "191BDACC",
          NextDialogue = 10111802,
          SpeakNpcId = 200039,
          Subtitle = "Aargh... why...",
          VoiceName = "voice/$Locale$/story/1002/101118/191BDACC"
        }
      }
    end
  },
  {
