    Loader = function()
      return {
        [10111802] = {
          ContentFR = "Elle est si gentille... et nous, nous avons toujours vécu droitement, sans jamais faire de mal à personne... Pourquoi tout ça est tombé sur nous ?",
          DialogueId = 10111802,
          GUID = "191BDAF6",
          NextDialogue = 10111803,
