          DialogueId = 10111904,
          GUID = "191BEB88",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10111905,
          SpeakNpcId = 200006,
          Subtitle = "Yes, I'm aware.",
          VoiceName = "voice/$Locale$/story/1002/101119/191BEB88"
        },
        [10111905] = {
