          DialogueId = 10112100,
          GUID = "19508891",
          VoiceName = "voice/$Locale$/story/1002/101121/19508891"
        },
        [10112101] = {
          Camera = "-1315.217285,639.65625,36.358154,-0.0,-14.999996,-34.000755,14.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tu as déjà contemplé toute ta vie. Une naissance marquée du sceau de la malédiction... et une fin vide de sens.",
          DialogueId = 10112101,
          FacialId = {
            [1] = "200052:Smile01",
            [2] = "200006:Shock01"
          },
          FinalCamera = "-1353.548462,665.503906,107.660645,-0.0,-8.800411,-34.000824,12.0,100000.0,false,DoNotOverride,2.8",
          GUID = "19508892",
          LookAt = {
            [1] = "200052:n(200006)",
            [2] = "200006:n(200052)"
          },
          NextDialogue = 10112102,
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}},\nCameraMoveTo{_delay{6.1},TargetPosition{\"-544.991699,42.441406,167.733154,0.00007,-27.399405,-23.990501,20.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "You've witnessed your entire life. A cursed beginning, and a meaningless end.",
          TalkActionId = {
            [1] = "200052:Explain01_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101121/19508892"
        },
        [10112102] = {
          Camera = "-1207.813599,500.523438,177.099365,0.000065,-6.399019,-1.789612,35.0,229.405197,false,Manual,6.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tout cela n’a aucun sens, toujours ce sourire factice pour complaire aux autres. Crois-tu être si désintéressée ? Non... tu mendiais lâchement leur pitié, leur mémoire... qu’ils se souviennent encore de toi, comme avant !",
          DialogueId = 10112102,
          FinalCamera = "-1212.987305,506.90625,177.723389,0.000065,-6.399019,-3.700013,35.0,229.405197,false,Manual,6.0",
          GUID = "195088BC",
          NextDialogue = 10112103,
          Scripts = "SEQ{\nSetLocation{ActorId{200052},TargetPoint{\"101121Point9\"},Visibility{\"Show\"}},\nPlayAnimation{ActorId{200052},AnimationId{\"Explain01_End\"},Duration{2}},\nLookAt{LookAtDescription{\"200006:n(200006)\"}},\nPlayAnimation{ActorId{200052},AnimationId{\"Explain02_Start\"},Duration{4.5}},\nPlayAnimation{ActorId{200052},AnimationId{\"Explain02_End\"},Duration{3.5}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "It's all meaningless — how you've always appeased others with a fake smile. Are you really that selfless? No, you're just cowardly begging for their pity, for them to remember you — as before you turned into a monster!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101121/195088BC"
        },
        [10112103] = {
          Camera = "-1059.955688,483.929688,169.242188,0.000069,-5.50003,148.198685,35.0,83.151031,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tout cela n’a aucun sens, leur compassion et leurs souvenirs sont si éphémères. Ils se faneront, rongés par le temps. Toi, tu pourriras dans la terre, jusqu’à être effacée à jamais.",
          DialogueId = 10112103,
          FacialId = {
            [1] = "200006:Sad01"
          },
          FinalCamera = "-1072.286011,464.078125,169.407227,0.000071,-5.099966,147.198303,35.000008,517.215454,false,Manual,4.0",
          GUID = "195088E6",
          NextDialogue = 10112104,
          Scripts = "PARA{\nSetLocation{ActorId{200052},TargetPoint{\"101121Point8\"},Visibility{\"Show\"}},\nLookAt{_delay{2},LookAtDescription{\"200006:n(200006)\"}},\nLookAt{_delay{0},LookAtDescription{\"200052:n(200052)\"}},\nPlayAnimation{_delay{2.0},ActorId{200006},AnimationId{\"Sigh_Start\"},Duration{1}},\nSetLocation{_delay{2.2},ActorId{200052},TargetPoint{\"101121Point10\"},Visibility{\"Show\"}},\nSetRotation{_delay{2.3},SetRotationDescription{\"200052:p(-90)\"}},\nPlayAnimation{_delay{2.3},ActorId{200052},AnimationId{\"Talk03_Start\"},Duration{1}},\nLookAt{_delay{2.3},LookAtDescription{\"200052:n(200052)\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "It's all meaningless — their fleeting pity and memories will soon wither and decay with time, leaving you rotting in the ground, utterly forgotten.",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E6"
        },
        [10112104] = {
          Camera = "-749.858276,899.738281,124.033691,0.00006,3.599072,-132.19986,80.0,607.756409,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Que crois-tu ? De quoi t’indignes-tu ? ... Je comprends. Tu veux me vaincre. Tu rêves qu’en me tuant, ta vie retrouve son cours... et ces jours paisibles que tu chérissais tant.",
          DialogueId = 10112104,
          FinalCamera = "-829.983887,811.878906,132.056641,0.000061,3.999062,-132.799957,80.0,450.437531,false,Manual,4.0",
          GUID = "195088E7",
          NextDialogue = 10112105,
          Scripts = "PARA{\nSetLocation{_delay{0.3},ActorId{200052},TargetPoint{\"101121Point11\"},Visibility{\"Show\"}},\nSetRotation{SetRotationDescription{\"200052:p(90)\"}},\nPlayAnimation{_delay{2},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{1}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          TalkActionId = {
            [1] = "200052:Talk01_Start",
            [2] = "200006:Sigh_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E7"
        },
        [10112105] = {
          Camera = "-804.349976,160.710938,171.24585,0.000067,-3.400027,138.804932,40.0,569.174194,false,Manual,7.455382",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tu te trompes. La Dégradation est irréversible. <W>Si je meurs, toi aussi tu disparaîtras !</>",
          DialogueId = 10112105,
          FacialId = {
            [1] = "200006:Sad01"
          },
          FinalCamera = "-805.726074,158.953125,171.24585,0.000065,-2.80005,141.806,40.0,194.718216,false,Manual,7.455382",
          GUID = "195088E8",
          NextDialogue = 10112106,
          Scripts = "PARA{\nSetLocation{_delay{0.3},ActorId{200052},TargetPoint{\"101121Point7\"},Visibility{\"Show\"}},\nSetRotation{SetRotationDescription{\"200052:p(-180)\"}},\nPlayAnimation{ActorId{200052},AnimationId{\"Talk01_End\"},Duration{1}},\nPlayAnimation{_delay{3},ActorId{200052},AnimationId{\"DisagreeHead\"},Duration{1}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E8"
        },
        [10112106] = {
          Camera = "-1489.189087,539.398438,161.23291,0.000026,0.999865,-3.197937,80.0,363.719818,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Abandonne-toi à moi... cède aux <W>instincts</> de ce corps. Deviens la bête... et toute cette absurdité ne pourra plus jamais te faire souffrir.",
          DialogueId = 10112106,
          FinalCamera = "-1433.880493,544.535156,162.192383,0.000026,1.599849,-1.997895,80.0,388.982208,false,Manual,4.0",
          GUID = "195088E9",
          LookAt = {
            [1] = "200052:n(200006)",
            [2] = "200006:n(200052)"
          },
          NextDialogue = 10112107,
          Scripts = "PARA{\nSetLocation{_delay{0.1},ActorId{200052},TargetPoint{\"101121Point5\"},Visibility{\"Show\"}},\nSetRotation{SetRotationDescription{\"200052:p(-180)\"}},\nSEQ{\nPlayAnimation{_delay{2},ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{1}},\nPlayAnimation{_delay{4},ActorId{200006},AnimationId{\"Explain02_End\"},Duration{1}}\n}\n}",
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "Just be a beast... none of this absurdity can hurt you anymore...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E9"
        },
        [10112107] = {
