          DialogueId = 10112301,
          Duration = 2.2,
          GUID = "1950A962",
          SpeakNpcId = 200006,
          Subtitle = "Right... My time... has already... come to an end.",
          VoiceName = "voice/$Locale$/story/1002/101123/1950A962"
        },
        [10112302] = {
          ContentFR = "... Mon temps est écoulé...",
