        },
        [10112303] = {
          ContentFR = "C’est toi... {nickname}...",
          DialogueId = 10112303,
          Duration = 0.6,
          ExStoryInfo = "Player",
          GUID = "1950A9B6",
          SpeakNpcId = 200006,
          Subtitle = "It's you... (...)",
