        },
        [10112304] = {
          ContentFR = "Lève-toi...",
          DialogueId = 10112304,
          Duration = 1.1,
          ExStoryInfo = "Player",
          GUID = "1950A9E0",
          SpeakNpcId = 100001,
          Subtitle = "Stand up...",
          VoiceName = "voice/$Locale$/story/1002/101123/1950A9E0"
        },
        [10112305] = {
          ContentFR = "Ne cède pas à ce monde froid et sans âme !",
          DialogueId = 10112305,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1950AA0A",
          SpeakNpcId = 100001,
          Subtitle = "Stand up...",
          VoiceName = "voice/$Locale$/story/1002/101123/1950AA0A"
        },
        [10112306] = {
          ContentFR = "Je... je...",
          DialogueId = 10112306,
          Duration = 1.4,
          GUID = "1950AA34",
          SpeakNpcId = 200006,
          Subtitle = "I...",
          VoiceName = "voice/$Locale$/story/1002/101123/1950AA34"
        },
        [10112401] = {
          Content = "赛琪，不要放弃。",
          DialogueId = 10112401,
          ExStoryInfo = "Player",
          GUID = "1950B9CA",
          NextDialogue = 10112402,
          SpeakNpcId = 100001,
          Subtitle = "Psyche, don't lose hope.",
          VoiceName = "voice/$Locale$/story/1002/101124/1950B9CA"
        },
        [10112402] = {
          Content = "是你……({nickname}……）",
          DialogueId = 10112402,
          ExStoryInfo = "Player",
          GUID = "1950B9F4",
          NextDialogue = 10112403,
          SpeakNpcId = 200006,
          Subtitle = "It's you... (...)",
          VoiceName = "voice/$Locale$/story/1002/101124/1950B9F4"
        },
        [10112403] = {
          Content = "站起来……",
          DialogueId = 10112403,
          ExStoryInfo = "Player",
          GUID = "1950BA1E",
          NextDialogue = 10112404,
          SpeakNpcId = 100001,
          Subtitle = "Stand up...",
          VoiceName = "voice/$Locale$/story/1002/101124/1950BA1E"
        },
        [10112404] = {
          Content = "不要向这个冷冰冰的世界投降！",
          DialogueId = 10112404,
          ExStoryInfo = "Player",
          GUID = "1950BA48",
          NextDialogue = 10112405,
          SpeakNpcId = 100001,
          Subtitle = "Don't yield to this cold, unfeeling world!",
          VoiceName = "voice/$Locale$/story/1002/101124/1950BA48"
        },
        [10112405] = {
          Content = "我……",
          DialogueId = 10112405,
          GUID = "1950BA72",
          SpeakNpcId = 200006,
          Subtitle = "I...",
          VoiceName = "voice/$Locale$/story/1002/101124/1950BA72"
        },
        [10112501] = {
          ContentFR = "Es-tu folle ?! Que fais-tu ?! Si tu me tues, tu disparaîtras toi aussi !",
          DialogueId = 10112501,
          GUID = "1950CA5B",
          NextDialogue = 10112502,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "What are you doing?!",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA5B"
        },
        [10112502] = {
          ContentFR = "Ce sont eux qui t’ont méprisée, qui t’ont blessée ! Et pourtant... c’est moi que tu veux anéantir ?!",
          DialogueId = 10112502,
          GUID = "1950CA5C",
          NextDialogue = 10112503,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "They were the ones who scorned and hurt you! Yet, you choose to destroy me?!",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA5C"
        },
        [10112503] = {
          ContentFR = "Pourquoi refuserais-tu d’obéir à ce corps... de détruire, de réduire tout en cendres ?",
          DialogueId = 10112503,
          GUID = "1950CA86",
          NextDialogue = 10112504,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA86"
        },
        [10112504] = {
          ContentFR = "Non... Ce n’est pas vrai. Car je me souviens...",
          DialogueId = 10112504,
          GUID = "1950CA87",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Deterioration is irreversible. Even in my destruction, what could you possibly alter?",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA87"
        },
        [10112601] = {
          ContentFR = "Psyche, te souviens-tu de ton vœu le plus cher ?",
          DialogueId = 10112601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1950DA9A",
          NextDialogue = 10112602,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0063_story_saiqi_last_word"}}",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, you've always cherished a wish, haven't you?",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DA9A"
        },
        [10112602] = {
          ContentFR = "Oui... je m’en souviens.",
          DialogueId = 10112602,
          Duration = 3,
          GUID = "1950DAEE",
          NextDialogue = 10112603,
          SpeakNpcId = 200006,
          Subtitle = "Yes, I remember now.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DAEE"
        },
        [10112603] = {
          ContentFR = "Quitter cet endroit... voyager vers un monde plus vaste.",
          DialogueId = 10112603,
          Duration = 3,
          GUID = "1950DB18",
          NextDialogue = 10112604,
          SpeakNpcId = 200006,
          Subtitle = "I want to leave here.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DB18"
        },
        [10112604] = {
          ContentFR = "Trouver une terre chaude, où les fleurs s’épanouissent sans fin.",
          DialogueId = 10112604,
          Duration = 3,
          GUID = "1950DB42",
          NextDialogue = 10112605,
          SpeakNpcId = 200006,
          Subtitle = "I want to go to a place where flowers bloom in warmth.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DB42"
        },
        [10112605] = {
          ContentFR = "J’y arriverai. Oui... j’y arriverai.",
          DialogueId = 10112605,
          Duration = 3,
          GUID = "1950DB6C",
          SpeakNpcId = 200006,
          Subtitle = "I will make it there.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DB6C"
        },
        [10112701] = {
          ContentFR = "Psyche, je suis venu te ramener à la maison.",
          DialogueId = 10112701,
          Duration = 4,
          GUID = "1950EB02",
          SpeakNpcId = 200006,
          Subtitle = "Psyche, I'm here to take you home."
        },
        [10112801] = {
          Camera = "-36.540039,376.152344,60.15918,0.000317,-22.003235,66.798752,30.000002,149.816666,false,Manual,3.0",
          ContentFR = "À la fin... j’ai quand même fini... par vous blesser... Je suis désolée...",
          DialogueId = 10112801,
          FacialId = {
            [1] = "200058:Sad01",
            [2] = "200002:Sad01",
            [3] = "200021:Unhappy02"
          },
          FinalCamera = "-29.402344,355.261719,78.488281,0.000229,-2.801416,73.999947,30.0,149.816666,false,Manual,1.6",
          GUID = "1950FB6A",
          LookAt = {
            [1] = "200021:n(200058)",
            [2] = "100001:n(200058)"
          },
          NextDialogue = 10112802,
          Scripts = "PARA{\nCameraMoveTo{_delay{6},TargetPosition{\"-16.544922,430.765625,63.105469,0.000328,8.596722,63.206375,30.000002,60.626308,false,Manual,3.0\"},duration{0}},\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0063_story_saiqi_last_word\"}}\n}",
          SpeakNpcId = 200058,
          Subtitle = "I've hurt you anyway... I'm so sorry...",
          TalkActionId = {
            [1] = "200058:BossSaiqi_Story_HurtCrouch",
            [2] = "100001:Nvzhu_Story_CrouchWithFlower"
          },
          ToFinalCameraBlendTime = 7,
