        },
        [10112802] = {
          Camera = "-59.855469,504.785156,53.325195,0.000286,5.795135,-23.848738,30.000008,101.19162,false,Manual,3.0",
          ContentFR = "Ce n’est rien. On rentre ensemble. Ils m’ont demandé de te dire... qu’ils t’attendent tous.",
          DialogueId = 10112802,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "-49.298828,499.199219,54.499023,0.000288,5.795135,-27.449614,30.000002,131.424332,false,Manual,3.0",
          GUID = "1950FB94",
          NextDialogue = 10112803,
          SpeakNpcId = 100001,
          Subtitle = "It's okay. Let's go home together. They wanted me to tell you, they're all waiting for you.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101128/1950FB94"
        },
        [10112803] = {
