        [10112805] = {
          Camera = "-108.393555,292.796875,44.162109,0.000281,15.398524,4.358887,30.0,154.570709,false,Manual,22",
          ContentFR = "... L’Étranger soi-disant prodige aux mille pouvoirs, tu ne disais pas que ton cerveau était dix mille fois plus brillant que le mien ? Alors trouve une solution, vite !",
          DialogueId = 10112805,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          GUID = "1950FC12",
          LookAt = {
            [1] = "200021:n(200002)"
          },
          NextDialogue = 10112806,
          Scripts = "PARA{\nPlayAnimation{_delay{1.7},ActorId{200002},AnimationId{\"Shock_End\"},Duration{1}},\nTurnTo{_delay{3.2},TurnToDescription{\"200002:n(200021)\"}},\nPlayAnimation{_delay{5.5},ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{1}},\nCameraMoveTo{TargetPosition{\"-108.697266,296.777344,44.162109,0.000282,15.398524,4.358962,30.0,280.124451,false,Manual,22\"},duration{2}},\n}",
          SpeakNpcId = 200002,
          Subtitle = "...Outsider, aren't you a know-it-all? Didn't you say your brain was a million times smarter than mine? Do something, now!",
          VoiceName = "voice/$Locale$/story/1002/101128/1950FC12"
        },
