        [10112808] = {
          Camera = "10.84375,395.707031,70.392578,0.000096,6.798859,-81.43161,35.000008,119.350891,false,Manual,22.0",
          ContentFR = "Quoi ?! Petit larbin, tu y es allé trop fort—",
          DialogueId = 10112808,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          FinalCamera = "15.981445,361.625,74.5,0.000093,7.598865,-81.031349,35.000008,119.350891,false,Manual,22.0",
          GUID = "1950FC3D",
          NextDialogue = 10112809,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Shock_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101128/1950FC3D"
        },
        [10112809] = {
          Camera = "8.78125,264.457031,83.086914,0.00015,-10.402186,77.949188,20.0,269.900269,false,Manual,3.0",
          ContentFR = "... N-Non... ce n’était pas {nickname}... c’est moi... qui ai choisi... de me tuer... Parce que... sous cet aspect-là... je ne veux pas... vivre comme ça...",
          DialogueId = 10112809,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200058:None"
          },
          FinalCamera = "0.195312,266.089844,83.086914,0.00016,-10.002196,76.74765,20.0,269.900269,false,Manual,3.0",
          GUID = "1950FC3E",
          NextDialogue = 10112810,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{"-6.788086,416.898438,77.085938,0.000188,-8.402095,75.941383,20.000008,91.919563,false,Manual,3.0"},duration{0}},",
          SpeakNpcId = 200058,
          Subtitle = "It was her own choice. She destroyed that body of Filthoid herself. She declared to fate in this brutal way that she wouldn't yield.",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101128/1950FC3E"
        },
        [10112810] = {
          Camera = "4.859375,460.746094,65.638672,0.000274,7.997727,-29.042561,30.000002,69.741608,false,Manual,10.038425",
          ContentFR = "Ressaisis-toi, Psyche. Tu m’as dit un jour que tu rêvais d’un lieu chaud, éclatant de fleurs en pleine floraison.",
          DialogueId = 10112810,
          ExStoryInfo = "Player",
          GUID = "1950FC90",
          NextDialogue = 10112811,
          SpeakNpcId = 100001,
          Subtitle = "Chin up, Psyche. You dreamt of going to a place warm and full of blooming flowers.",
          VoiceName = "voice/$Locale$/story/1002/101128/1950FC90"
        },
        [10112811] = {
          Camera = "-2298.602539,-3842.25,192.349609,0.000252,0.798449,-38.671951,80.0,1609.318115,false,Manual,4.0",
          ContentFR = "Tu disais toujours... « là où il y a des fleurs, il se passe de belles choses ».",
          DialogueId = 10112811,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          FinalCamera = "-2226.009766,-3751.175781,192.349609,0.000252,0.798449,-38.271557,80.0,1609.318115,false,Manual,4.0",
          GUID = "1950FCBA",
          NextDialogue = 10112812,
          Scripts = "SetLocation{ActorId{200002},TargetPoint{"P101128Bai1"},Visibility{"Show"}}",
          SpeakNpcId = 100001,
          Subtitle = "You've said it yourself — flowers bring good luck.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101128/1950FCBA"
        },
        [10112812] = {
          Camera = "13.830078,390.085938,14.71582,10.806623,27.18866,92.147942,25.000002,125.33342,false,Manual,4.0",
          ContentFR = "Oui... là-bas... ce doit être... si beau...",
          DialogueId = 10112812,
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200058:Shock01"
          },
          GUID = "1950FCE4",
          NextDialogue = 10112813,
          SpeakNpcId = 200058,
          Subtitle = "Yes, it must be... a beautiful place.",
          VoiceName = "voice/$Locale$/story/1002/101128/1950FCE4"
        },
        [10112813] = {
          Camera = "-59.855469,504.785156,53.325195,0.000294,5.795142,-23.848715,30.000013,138.63237,false,Manual,3.0",
          ContentFR = "Non, ne te fie pas à mes mots. Tu dois le voir de tes propres yeux.",
          DialogueId = 10112813,
          ExStoryInfo = "Player",
          GUID = "1950FD0E",
          NextDialogue = 10112814,
          SpeakNpcId = 100001,
          Subtitle = "No, don't take my word for it, you have to see it for yourself.",
          VoiceName = "voice/$Locale$/story/1002/101128/1950FD0E"
        },
        [10112814] = {
          Camera = "-0.991211,442.316406,60.057617,0.000278,12.996394,71.551292,25.000002,58.67511,false,Manual,6.0",
          ContentFR = "Tu sais... pourquoi j’aime tant les fleurs ?",
          DialogueId = 10112814,
          FacialId = {
            [1] = "200058:Sad01"
          },
          FinalCamera = "-0.991211,442.316406,60.057617,0.000275,8.596339,29.352036,25.000002,37.979053,false,Manual,6.0",
          GUID = "1950FD38",
          NextDialogue = 10112815,
          Scripts = "PARA{\nCameraMoveTo{_delay{3.0},TargetPosition{\"-0.991211,442.316406,60.057617,0.000275,8.596339,29.352036,25.000002,37.979053,false,Manual,6.0\"},duration{0}},\nCameraMoveTo{_delay{3.1},TargetPosition{\"-0.991211,442.316406,60.057617,0.000274,15.196166,-15.44876,25.000002,88.778671,false,Manual,6.0\"},blend{\"easeOutQuad\"},duration{3}}\n}",
          SpeakNpcId = 200058,
          Subtitle = "Do you know... why I love flowers?",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101128/1950FD38"
        },
        [10112815] = {
          Camera = "-103.455078,522.871094,134.970703,0.000312,-23.004848,-26.640802,25.000006,4089.927734,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Parce que leurs graines, portées par le souffle léger du vent, voyagent au loin... elles franchissent les murs, les montagnes... rien ne peut les arrêter.",
          DialogueId = 10112815,
          FacialId = {
            [1] = "200058:None"
          },
          FinalCamera = "-1856.353516,1398.453125,977.069336,0.000313,-23.604845,-25.838488,25.000006,4089.927734,false,Manual,22.0",
          GUID = "1950FD62",
          SpeakNpcId = 200058,
          Subtitle = "Because their seeds, carried by the gentle wind, travel to distant lands... Over city walls, over mountains... nothing can stop them.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101128/1950FD62"
        },
        [10112901] = {
          ContentFR = "J’ai encore... un dernier vœu—",
          DialogueId = 10112901,
          Duration = 3,
          GUID = "1950FD63",
          SpeakNpcId = 200058,
          Subtitle = "I have one last wish—"
        },
        [10112902] = {
          ContentFR = "Oui. Je t’écoute.",
          DialogueId = 10112902,
          Duration = 0.8,
          ExStoryInfo = "Player",
          GUID = "1950FD64",
          SpeakNpcId = 100001,
          Subtitle = "I'm all ears."
        },
        [10112903] = {
          ContentFR = "Cible manquée. À cette distance, impossible de confirmer l’état de la cible ou de l’otage.",
          DialogueId = 10112903,
          Duration = 1,
          GUID = "1950FD65",
          SpeakNpcId = 700065,
          Subtitle = "Target missed. Unable to confirm the status of either target or hostage from this range."
        },
        [10112904] = {
          ContentFR = "... Préparez-vous au combat frontal !",
          DialogueId = 10112904,
          Duration = 1,
          GUID = "1950FD66",
          Subtitle = "...Prepare for direct engagement!"
        },
        [10113001] = {
          Camera = "-90.074219,755.777344,469.635742,0.000111,-25.499575,-93.596069,25.0,467.444916,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          Content = "好在秽蚀者的行动路线朝向城外，未造成大范围人员伤亡，我们运气不错。",
