          FacialId = {
            [1] = "100001:Shock02",
            [2] = "200002:Shock02",
            [3] = "200021:Angry01",
            [4] = "2000581:Close"
          },
          FinalCamera = "-95.249023,668.898438,428.417969,0.000102,-26.099579,-95.596054,25.0,467.444916,false,Manual,22.0",
          GUID = "19511C3A",
          LookAt = {
            [1] = "100001:n(2000581)"
