        },
        [10113002] = {
          Camera = "82.416016,128.960938,14.348633,-3.000001,-0.400782,-132.985641,30.000002,214.526855,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你好，我是第六军团下属，科赛托斯行省卫戍部队准尉，黎瑟·费西尔。",
          DialogueId = 10113002,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "67.181641,112.957031,9.427734,-3.0,9.399194,-131.986374,30.000002,821.013916,false,Manual,3.0",
          GUID = "19511C64",
          LookAt = {
            [1] = "100304:n(100001)",
            [2] = "200002:n(100304)",
            [3] = "200021:n(100304)"
          },
          NextDialogue = 10113003,
          RelatedWikiId = {
            [1] = 201011
          },
          Scripts = "PARA{\nLookAt{_delay{1},LookAtDescription{\"100001:n(100304)\"}},\nCameraMoveTo{_delay{5},TargetPosition{\"-171.574219,-159.355469,93.070312,-3.000002,14.99738,-143.982834,30.000002,169.915115,false,Manual,3.0\"},duration{0}}\n}",
          SpeakNpcId = 100304,
          SpeakNpcName = "UI_Npc_Name_FemaleOfficer",
          Subtitle = "Greetings, I am Rhythm Fischer, Warrant Officer of the Cocytus Escort of the 6th Legion.",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101130/19511C64"
        },
        [10113003] = {
          Camera = "-345.591797,-227.671875,150.0,0.000125,-11.999351,20.399422,18.0,718.595093,false,Manual,3.0",
          Content = "我接到紧急情报，外围北区出现“秽蚀”事件。秽蚀者异常凶险，我们不确定它是真的被击毙了，还是短暂休眠。你们即刻撤离此地，接下来由我们应付。",
          DialogueId = 10113003,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-348.543945,-229.019531,150.953125,0.000126,-16.799225,24.99777,18.0,718.595093,false,Manual,3.0",
          GUID = "19511C8E",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10113004,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100304},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100304,
          SpeakNpcName = "UI_Npc_Name_FemaleOfficer",
          Subtitle = "I have received an alert of a Deterioration outbreak in the eastern periphery. The Deteriorator is a grave threat; it's unclear if it's truly dead or merely in a dormant state. Immediate evacuation is advised; we'll take over from here.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101130/19511C8E"
        },
        [10113004] = {
          Camera = "-161.636719,-90.765625,127.488281,0.00052,4.203223,-9.400385,35.0,132.664047,false,Manual,3.0",
          ContentFR = "...",
          DialogueId = 10113004,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "19511CB8",
          NextDialogue = 10113005,
          Scripts = "SEQ{\nTurnTo{_delay{1},TurnToDescription{\"100001:n(100304)\"}},\nPlayAnimation{ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Crouch_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/19511CB8"
        },
        [10113005] = {
          Camera = "-161.636719,-90.765625,127.488281,0.00052,4.203223,-9.400385,35.0,132.664047,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          Content = "……不必了，长官。您出手之前，我们已经解决了。它已经凉了，透了，您也不用再浪费子弹了。",
          DialogueId = 10113005,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "-161.636719,-90.765625,127.488281,0.000524,4.003215,-14.402719,35.0,319.412994,false,Manual,3.0",
          GUID = "19511CE2",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "100304:n(200021)"
          },
          NextDialogue = 10113006,
          Scripts = "PARA{\nPlayAnimation{_delay{0.5},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{1}},\nLookAt{_delay{1},LookAtDescription{\"100001:n(200021)\"}},\nCameraMoveTo{_delay{3},TargetPosition{\"-42.216797,-134.367188,154.807617,0.000533,-0.196989,-13.007848,35.0,126.183968,false,Manual,3.0\"},duration{0}}\n}",
          SpeakNpcId = 200021,
          Subtitle = "No need, ma'am. We've taken care of it before you came. It's dead as a doornail now, no need to waste more of your bullets.",
          TalkActionId = {
            [1] = "100304:Explain01_End"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101130/19511CE2"
        },
        [10113006] = {
          Camera = "-195.787109,-176.09375,124.895508,0.00054,1.402545,-144.774109,25.0,115.146286,false,Manual,22.0",
          Content = "“已经解决”？",
          DialogueId = 10113006,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "-201.873047,-180.394531,124.880859,0.00054,2.802508,-144.973618,25.0,115.146286,false,Manual,22.0",
          GUID = "19511D0C",
          NextDialogue = 10113007,
          Scripts = "PlayAnimation{ActorId{200021},AnimationId{"Talk02_End"},Duration{1}},",
          SpeakNpcId = 100304,
          Subtitle = "Really? That explains why this target was more stable than the average Filthoids.",
          TalkActionId = {
            [1] = "100304:Talk03_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101130/19511D0C"
        },
        [10113007] = {
          Camera = "-201.873047,-180.394531,124.880859,0.00054,2.802508,-144.973618,25.0,115.146286,false,Manual,22.0",
          Content = "的确没有生命体征了。难怪这次的目标比大多数秽兽都要稳定。",
          DialogueId = 10113007,
          GUID = "19511D35",
          NextDialogue = 10113008,
          Scripts = "SEQ{\nLookAt{LookAtDescription{\"100304:n(2000581)\"}},\nCameraMoveTo{TargetPosition{\"-276.560547,-230.78125,137.651367,0.00053,-23.796835,47.828102,50.0,371.84317,false,Manual,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-281.869141,-238.039062,141.693359,0.000539,-23.996824,53.828442,50.0,371.84317,false,Manual,22.0\"},duration{3}},\nStopTalkGroup{ActorId{100304},Duration{0.5}},\nPlayAnimation{ActorId{100304},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/19511D35"
        },
        [10113008] = {
          Camera = "-281.869141,-238.039062,141.693359,0.000539,-23.996824,53.828442,50.0,371.84317,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Mais... vous deux seulement ? À vos tenues, on dirait des Chasseurs de Phoxène, je me trompe ?",
          DialogueId = 10113008,
          FinalCamera = "-228.296875,-218.578125,139.045898,0.000541,-1.196676,20.028727,35.0,371.84317,false,Manual,22.0",
          GUID = "19511D36",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10113009,
          Scripts = "SEQ{\nSetLocation{ActorId{700065},TargetPoint{\"P101130soldier\"},Visibility{\"Hide\"}},\nLookAt{LookAtDescription{\"100304:n(200021)\"}},\nPlayAnimation{_delay{0.5},ActorId{100304},AnimationId{\"Think_End\"},Duration{1}},\nStopTalkGroup{ActorId{100304},Duration{0.5}},\nLookAt{_delay{1},LookAtDescription{\"100304:n(100001)\"}},\n}",
          SpeakNpcId = 100304,
          Subtitle = "However... was it only you two? Given your outfits, are you Phoxhunters?",
          TalkActionId = {
            [1] = "100001:Angry01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101130/19511D36"
        },
        [10113009] = {
          ContentFR = "Comme vous pouvez le constater.",
          DialogueId = 10113009,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "19511D60",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10113010,
          Scripts = "SetLocation{ActorId{700065},TargetPoint{"P101130soldier"},Visibility{"Show"}}",
          SpeakNpcId = 200021,
          Subtitle = "Precisely.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/19511D60"
        },
        [10113010] = {
          Camera = "-197.794922,-170.070312,134.780273,0.000507,0.002964,-142.999863,35.000008,124.303391,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Non, ce n’est pas ça ! Madame, lors de ma précédente reconnaissance, bien que de loin, j’ai vu ces Charons utiliser la <W>magie</>...",
          DialogueId = 10113010,
          FinalCamera = "-197.794922,-170.070312,134.780273,0.000507,-0.597013,-133.199646,35.000008,395.571716,false,Manual,4.0",
          GUID = "19511D8A",
          NextDialogue = 10113011,
          Scripts = "PARA{\nLookAt{_delay{1},LookAtDescription{\"100304:n(700108)\"}},\nLookAt{LookAtDescription{\"700108:n(100304)\"}},\nPlayAnimation{ActorId{700108},AnimationId{\"Disagree\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{700108},AnimationId{\"Angry01_Start\"},Duration{1}},\nLookAt{_delay{2},LookAtDescription{\"700108:n(200021)\"}}\n}",
          SpeakNpcId = 700065,
          SpeakNpcName = "UI_Npc_Name_Man_1",
          Subtitle = "That's not it! Ma'am, I saw it! Though from a distance, I saw these Charons... they used magic...",
          TalkActionId = {
            [1] = "200021:Talk01_End"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101130/19511D8A"
        },
        [10113011] = {
          Camera = "-413.662109,-507.15625,157.617188,0.000528,-7.39734,53.794216,25.0,603.134277,false,Manual,4.0",
          ContentFR = "Ils... ils sont peut-être les complices du Dégradé ! Ces minables, toujours des mages impurs, aucun n’est digne de confiance ! À mon avis, il faudrait tous les—",
          DialogueId = 10113011,
          GUID = "19511DB4",
          LookAt = {
            [1] = "100001:n(700065)",
            [2] = "700108:n(200021)"
          },
          NextDialogue = 10113012,
          Scripts = "LookAt{_delay{5},LookAtDescription{"700108:n(100001)"}}",
          SpeakNpcId = 700065,
          SpeakNpcName = "UI_Npc_Name_Man_1",
          Subtitle = "They might be accomplices of the Deteriorator! These low-life beings, all wicked sorcerers! They should all be...",
          VoiceName = "voice/$Locale$/story/1002/101130/19511DB4"
        },
        [10113012] = {
