        [10113013] = {
          Camera = "-266.094727,-223.230469,137.535156,0.000535,-1.997038,-130.19101,35.0,103.198799,false,Manual,22.0",
          ContentFR = "Euh... n-non... Madame, je parlais d’eux ! Enfin, pas de tous les Charons, bien sûr... Je ne voulais rien insinuer !",
