        [10113015] = {
          Camera = "-339.033203,-227.824219,136.402344,0.000588,-7.200924,7.438437,25.0,501.611572,false,Manual,4.0",
          ContentFR = "Merci pour votre aide à la Légion. Venez avec nous au Bureau de la Sécurité, une compensation vous sera attribuée.",
