        [10113019] = {
          Camera = "-171.146484,-171.667969,128.313477,0.000041,3.600391,27.023533,50.0,140.984863,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Si elle s’est enfuie si loin de la ville... c’était pour épargner les foules.",
          DialogueId = 10113019,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          FinalCamera = "-144.888672,-157.828125,130.180664,0.000041,3.200374,26.42301,50.000008,140.984863,false,Manual,22.0",
          GUID = "19511F04",
          NextDialogue = 10113020,
          SpeakNpcId = 100001,
          Subtitle = "She... was trying to keep away from the crowds, that's why she ran towards the outskirts so desperately.",
