          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Jusqu’à son dernier souffle, elle a tout donné... pour protéger les autres...",
          DialogueId = 10113020,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "-80.609375,-198.324219,229.099609,0.000058,-47.39949,79.996841,25.000002,235.984589,false,Manual,22.0",
