        },
        [10113023] = {
          Camera = "-318.40918,-288.792969,134.553711,0.000583,-3.50069,42.051529,35.000008,361.092285,false,Manual,4.0",
          ContentFR = "Tu ne vas pas bien ? Es-tu {性别:blessé|blessée} ? Dois-je appeler un médecin militaire ?",
          DialogueId = 10113023,
          GUID = "19511FAC",
          NextDialogue = 10113024,
          SpeakNpcId = 100304,
          Subtitle = "Are you alright? Injured perhaps? Should I arrange a military medic for you?",
          VoiceName = "voice/$Locale$/story/1002/101130/19511FAC"
        },
        [10113024] = {
          Camera = "-43.249023,-230.039062,139.522461,0.000592,5.699356,27.05097,35.000008,145.830688,false,Manual,4.0",
          ContentFR = "Non, non, pas du tout. Mon {性别:ami|amie} a seulement eu une petite frayeur. Une bonne boisson chaude aux Asphodèles et {性别:il sera remis|elle sera remise} sur pied.",
          DialogueId = 10113024,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "19511FD6",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = "200021:n(100304)"
          },
          NextDialogue = 10113025,
          Scripts = "SetLocation{ActorId{700065},TargetPoint{"P101130soldier2"},Visibility{"Show"}}",
          SpeakNpcId = 200021,
          Subtitle = "Not at all, ma'am. My friend is just a bit shaken, we'll be fine after a few warm drinks at the Asphodel.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/19511FD6"
        },
        [10113025] = {
          Camera = "159.128906,-260.046875,192.414062,0.000568,-16.500391,136.848602,35.000011,145.830688,false,Manual,22.0",
          ContentFR = "Pour la compensation, on verra plus tard. On a une autre mission qui presse, alors on vous laisse.",
          DialogueId = 10113025,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          GUID = "1951202A",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextOptions = {
            [1] = 10113026,
            [2] = 10113028
          },
          SpeakNpcId = 200021,
          Subtitle = "We'll talk about the reward another time. We're pressed for time with an upcoming task, we'll take our leave now.",
          TalkActionId = {
            [1] = "200021:Talk02_Start",
            [2] = "100304:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/1951202A"
        },
        [10113026] = {
          ContentFR = "– Rester calme et se taire, inutile d’attirer plus encore l’attention de la Légion.",
          DialogueId = 10113026,
          GUID = "10113026",
          ImprPlusId = 1006,
          NextDialogue = 10113027,
          Subtitle = "(Calm down and remain silent — it's unwise to draw more attention from the Legion.)"
        },
        [10113027] = {
          Camera = "-139.688477,-91.050781,121.101562,-4.000003,8.402478,-13.154885,35.0,104.579765,false,Manual,4.0",
          ContentFR = "... Partons.",
          DialogueId = 10113027,
          ExStoryInfo = "Player",
          FacialId = {
