        [10113115] = {
          Camera = "-163.218521,132.791336,42.427734,-5.000002,15.199219,2.797176,35.000008,419.357452,false,Manual,3.5",
          ContentFR = "Allez, {性别:si tu veux pleurer, lâche-toi, frérot.|si tu veux pleurer, lâche-toi, tu n’as pas à faire semblant d’être forte.}",
          DialogueId = 10113115,
