          NextDialogue = 10113116,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0039_story_saiqi_see_flower"}}",
          SpeakNpcId = 200021,
          Subtitle = "If you wanna cry, go ahead.",
          VoiceName = "voice/$Locale$/story/1002/101131/19512DC9"
        },
        [10113116] = {
          Camera = "-163.218521,132.791336,42.427734,-5.000002,15.199219,2.797176,35.000008,419.357452,false,Manual,3.5",
          ContentFR = "Avec ce vent, je n’entendrai rien. Et si jamais j’entends un son... je dirai que c’était un piaf qui criait.",
          DialogueId = 10113116,
          GUID = "19512E1C",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10113117,
          Scripts = "LookAt{_delay{2},LookAtDescription{"200021:p(Psky)"}}",
          SpeakNpcId = 200021,
          Subtitle = "The wind here is so strong, I can't hear a thing. Even if I do hear some noise, it's just the sparrows chirping.",
          VoiceName = "voice/$Locale$/story/1002/101131/19512E1C"
        },
        [10113117] = {
          Camera = "63.788624,80.274666,117.046875,0.000101,-0.000061,28.195601,35.0,46.83934,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Ce genre de choses, j’en ai déjà vu bien trop souvent. Mais je me fixe une règle : « une seule nuit pour les larmes. »",
          DialogueId = 10113117,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          FinalCamera = "63.788624,80.274666,117.046875,0.000101,-0.20007,39.394825,35.0,46.83934,false,Manual,22.0",
          GUID = "19512E46",
          NextOptions = {
            [1] = 101131171,
            [2] = 101131172,
            [3] = 101131173
          },
          SpeakNpcId = 200021,
          Subtitle = "...I've seen this kind of thing countless times. But I tell myself, you've only got one night for tears.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101131/19512E46"
        },
        [10113118] = {
          Camera = "-335.797272,127.216934,-109.182617,0.000001,25.397947,-1.404929,18.0,177.065216,false,DoNotOverride,4.0",
          ContentFR = "Quoi qu’il en soit... continue de vivre. Elle aurait sûrement voulu que tu accueilles demain avec un sourire.",
          DialogueId = 10113118,
          FacialId = {
            [1] = "200021:Smile01",
            [2] = "100001:Sad01"
          },
          FinalCamera = "-335.797272,127.216934,-109.182617,-0.0,27.198065,-11.406103,18.0,177.065216,false,DoNotOverride,4.0",
          GUID = "19512E70",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10113119,
          Scripts = "LookAt{_delay{1},LookAtDescription{"100001:n(200021)"}}",
          SpeakNpcId = 200021,
          Subtitle = "Anyway, pull yourself together. That girl would surely wish for you to face tomorrow with a smile.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101131/19512E70"
        },
        [10113119] = {
          Camera = "120.312851,41.066757,142.761719,0.000036,-18.602785,115.999886,25.0,177.065216,false,DoNotOverride,22.0",
          ContentFR = "Même si... ce monde nous a jadis trompés.",
          DialogueId = 10113119,
          FacialId = {
            [1] = "200021:Sad01"
          },
          FinalCamera = "144.905304,-9.377659,161.657227,0.000035,-18.402769,116.000282,25.0,177.065216,false,DoNotOverride,22.0",
          GUID = "19512E9A",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{2.5},TargetPosition{\"-755.637817,-1039.825317,553.05957,0.000116,7.197414,-70.024422,15.000005,177.065216,false,DoNotOverride,4.0\"},duration{0}},\nCameraMoveTo{_delay{2.6},TargetPosition{\"-682.158203,-1241.995117,580.22168,0.000116,7.197414,-70.024422,15.000005,177.065216,false,DoNotOverride,4.0\"},blend{\"easeOutQuad\"},duration{6}}\n}",
