          Scripts = "SEQ{\nPlayAnimation{_delay{0.7},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}},\nPlayAnimation{_delay{0.7},ActorId{100001},AnimationId{\"Explain02_End\"},Duration{1}},\nPlayAnimation{_delay{0.7},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}}\n}",
