        },
        [10113208] = {
          Camera = "-28.738281,-34.265625,100.193298,0.000496,-47.571659,80.167305,25.0,572.451843,false,Manual,22.0",
          ContentFR = "On s’acharne à retenir quelque chose, et pourtant, ça nous échappe comme le sable entre nos doigts.",
