          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          GUID = "19513EAE",
          NextDialogue = 10113212,
          Scripts = "PARA{\nMoveTo{_delay{0.5},ActorId{100001},MoveSpeed{60},TargetPoint{\"101132Point2\"}},\nMoveTo{ActorId{100012},MoveSpeed{120},TargetPoint{\"101132Point7\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Where are you going...?",
          VoiceName = "voice/$Locale$/story/1002/101132/19513EAE"
        },
        [10113212] = {
          Camera = "-591.296875,-251.023438,103.546082,0.00011,-16.800714,40.389046,35.000008,501.351562,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Comme toi, je pars pour mon propre voyage.",
          DialogueId = 10113212,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-1168.667969,-987.226562,848.928101,0.000121,-38.400719,51.188854,35.000011,501.351562,false,Manual,22.0",
          GUID = "19513ED8",
          NextDialogue = 10113213,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Like you, I'm starting my own journey.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101132/19513ED8"
        },
        [10113213] = {
          Camera = "218.238281,11.238281,-190.407471,0.000003,21.597883,-176.59758,20.000008,501.349915,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Attends ! Qui... qui es-tu vraiment ?!",
          DialogueId = 10113213,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "167.128906,8.203125,-170.148376,0.000003,21.597883,-176.59758,20.000008,501.349915,false,Manual,22.0",
          GUID = "19513F02",
          NextDialogue = 10113214,
          Scripts = "PARA{\nSetLocation{ActorId{100012},TargetPoint{\"101132Point8\"},Visibility{\"Show\"}},\nMoveTo{ActorId{100001},MoveSpeed{50},TargetPoint{\"101132Point5\"}}\n}",
          SpeakNpcId = 100001,
          Subtitle = "Wait! Who... who are you?!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101132/19513F02"
        },
        [10113214] = {
          Camera = "-320.191406,-84.808594,164.884644,0.000057,-32.81023,166.785141,20.000008,501.349915,false,Manual,22.0",
          ContentFR = "Mon nom est...",
          DialogueId = 10113214,
          ExStoryInfo = "EXPlayer",
          GUID = "19513F2C",
          NextDialogue = 10113215,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "My name is...",
          TurnTo = {
            [1] = "100012:p(150)"
          },
          VoiceName = "voice/$Locale$/story/1002/101132/19513F2C"
        },
        [10113215] = {
          Camera = "-320.191406,-84.808594,164.884644,0.000057,-32.81023,166.785141,20.000008,501.349915,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Peut-être que nos chemins se croiseront à nouveau un jour.",
          DialogueId = 10113215,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-349.851562,-138.621094,164.884644,0.000032,-33.21019,133.384689,20.000008,501.349915,false,Manual,22.0",
          GUID = "19513F56",
          Scripts = "PARA{\nCameraMoveTo{_delay{2.5},TargetPosition{\"-37.894531,54.429688,-37.144287,0.000067,13.593162,-176.994934,12.0,350.231415,false,Manual,3.0\"},duration{0}},\nCameraMoveTo{_delay{2.6},TargetPosition{\"-30.320312,11.925781,-39.521667,0.000067,12.993198,172.805191,12.0,350.231415,false,Manual,3.0\"},blend{easeOutQuad},duration{3}}\n}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Our paths may cross again one day.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101132/19513F56"
        },
        [10113301] = {
          ContentFR = "Dans ce rêve qui s’effondre encore une fois, cette voix s’est fait entendre à travers le vent.",
          DialogueId = 10113301,
          Duration = 3.5,
          GUID = "19514D72",
          NextDialogue = 10113302,
          Subtitle = "Once again in the collapsing dream, that voice whispered through the wind.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514D72"
        },
        [10113302] = {
          ContentFR = "Cette fois, je peux enfin l’entendre clairement.",
          DialogueId = 10113302,
          Duration = 3.5,
          GUID = "19514D9C",
          NextDialogue = 10113303,
          Subtitle = "Only this time, I finally made it out.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514D9C"
        },
        [10113303] = {
          ContentFR = "Comme les racines d’un arbre absorbant chaque goutte d’eau, je m’efforce de graver ce nom dans ma mémoire.",
          DialogueId = 10113303,
          Duration = 4,
          GUID = "19514DC6",
          NextDialogue = 10113304,
          Subtitle = "Like tree roots absorbing every drop of water, I tried my best to engrave that name in my mind.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DC6"
        },
        [10113304] = {
          ContentFR = "... Ce nom...",
          DialogueId = 10113304,
          Duration = 3,
          GUID = "19514DF0",
          Subtitle = "{性别:Her|His} name was—",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DF0"
        },
        [10113401] = {
          Camera = "-1818.244629,451.75,65.15918,0.0,3.799989,1.999787,35.0,269.181396,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "J’ai connu la douleur... j’ai goûté à la haine. Elles m’ont épuisée... accablée...",
          DialogueId = 10113401,
          FacialId = {
            [1] = "2000591:Happy02"
          },
          FinalCamera = "-1818.244629,451.75,77.947998,0.0,6.0,1.999786,35.0,921.225525,false,Manual,1.2",
          GUID = "19515DDA",
          NextDialogue = 10113402,
          Scripts = "PARA{\nCameraMoveTo{_delay{3},TargetPosition{\"-986.794189,356.464844,129.88501,0.000031,5.799336,133.697769,30.000002,425.998016,false,Manual,22.0\"},duration{0}},\nPlayAnimation{_delay{3.1},ActorId{2000591},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 2000591,
          Subtitle = "Pain and hatred have been my acquaintances. They've wearied and grieved me—",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101134/19515DDA"
        },
        [10113402] = {
          Camera = "-1751.68335,1248.289062,55.207764,-0.0,4.000004,-50.000027,15.0,425.998016,false,DoNotOverride,1.2",
          ContentFR = "<H>Mais je me réjouis encore... d’avoir vu le jour dans ce monde.</>",
          DialogueId = 10113402,
          FinalCamera = "-1650.423584,1127.605469,35.868652,-0.0,4.000004,-50.000027,15.0,425.998016,false,DoNotOverride,1.2",
          GUID = "19515E04",
          NextDialogue = 10113403,
          SpeakNpcId = 2000591,
          Subtitle = "Yet, I find joy in having existed in this world.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101134/19515E04"
        },
        [10113403] = {
          Camera = "-1283.367798,582.753906,176.219971,0.000078,-2.599427,-26.997437,35.0,144.372665,false,Manual,4.831013",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "C’est mon choix.",
          DialogueId = 10113403,
          FinalCamera = "-1286.140259,577.761719,176.219971,0.000078,-2.599427,-28.997461,35.0,896.028748,false,Manual,4.092557",
          GUID = "19515E2E",
          SpeakNpcId = 2000591,
          Subtitle = "This is my choice.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101134/19515E2E"
        },
        [10113501] = {
