        },
        [10113901] = {
          Content = "本次技术性测试剧情流程已结束。",
          DialogueId = 10113901,
          Duration = 5,
          GUID = "1951AFE2",
          VoiceName = "voice/$Locale$/story/1002/101139/1951AFE2"
        },
        [10114001] = {
          ContentFR = "Déjà de retour ? Vous n’étiez pas censés suivre Henrik ?",
          DialogueId = 10114001,
          GUID = "1951C04A",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101140/1951C04A"
        },
        [10114201] = {
          ContentFR = "Il vaut mieux aller dormir tôt... sinon vous serez fatigué demain.",
          DialogueId = 10114201,
          GUID = "1951E11A",
          SpeakNpcId = 200020,
          VoiceName = "voice/$Locale$/story/1002/101142/1951E11A"
        },
        [10114301] = {
          ContentFR = "Si Monsieur Henrik est d’accord, tu pourrais revenir passer un peu de temps avec moi ?",
          DialogueId = 10114301,
          GUID = "1951F182",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101143/1951F182"
        },
        [10114401] = {
