          Duration = 3,
          GUID = "1955052C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101191/1955052C"
        },
        [10119201] = {
          Content = "这些脚印是刚踩上去的，沿着这些湿漉漉的脚印追上去准没错。",
          DialogueId = 10119201,
          Duration = 3,
          GUID = "1955156A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101192/1955156A"
        },
        [10119301] = {
          Content = "这是……新鲜的血迹？他受伤了？",
          DialogueId = 10119301,
          Duration = 3,
          GUID = "195525D2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10122001,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101193/195525D2"
        },
        [10119302] = {
          Content = "他或许被什么袭击了……我们也谨慎一些。",
          DialogueId = 10119302,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195525FC",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101193/195525FC"
        },
        [10119401] = {
          Content = "果然……他惊扰了这里的秽兽群，以至遭到了围攻。",
          DialogueId = 10119401,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955363A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101194/1955363A"
        },
        [10119501] = {
          ContentFR = "Je n’en peux plus... je me rends...",
          DialogueId = 10119501,
          Duration = 3,
          GUID = "10119501.0",
          NextDialogue = 10119502,
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Die"
        },
        [10119502] = {
          ContentFR = "Hé hé, tu cours plus si vite maintenant !",
          DialogueId = 10119502,
          Duration = 3,
          GUID = "195546A2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10119503,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101195/195546A2"
        },
        [10119503] = {
          ContentFR = "{nickname}, viens m’aider à le plaquer !",
          DialogueId = 10119503,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195546CC",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101195/195546CC"
        },
        [10119601] = {
          ContentFR = "Cette porte semble intacte, juste verrouillée...",
          DialogueId = 10119601,
          Duration = 3,
          GUID = "1955570A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10119602,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/1955570A"
        },
        [10119602] = {
          ContentFR = "Sérieusement, pourquoi ont-ils besoin de toutes ces mesures de sécurité pour un vieux trou abandonné ?",
          DialogueId = 10119602,
          Duration = 3,
          GUID = "19555734",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10119603,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101196/19555734"
        },
        [10119603] = {
          ContentFR = "... Probablement pour éviter que quelqu’un ne se fasse attaquer par des Souillés.",
          DialogueId = 10119603,
          Duration = 3,
          GUID = "1955575E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10119604,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/1955575E"
        },
        [10119604] = {
          ContentFR = "Tentons notre chance ! Cherchons une clé ou quelque chose qui puisse l’ouvrir dans le coin.",
          DialogueId = 10119604,
          Duration = 3,
          GUID = "19555788",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/19555788"
        },
        [10119701] = {
          Content = "哇……原来矿坑里还有这种好东西？要是让玛尔洁知道了，她还不得乐开花！",
          DialogueId = 10119701,
          Duration = 3,
          GUID = "19556772",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10119702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101197/19556772"
        },
        [10119702] = {
          Content = "但是这矿石很硬吧，玛尔洁小姐的铲子说不定会被磕坏的。",
          DialogueId = 10119702,
          Duration = 3,
          GUID = "1955679C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101197/1955679C"
        },
        [10119801] = {
          Content = "{nickname}，我也来帮忙吧！",
          DialogueId = 10119801,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195577DA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10119802,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/195577DA"
        },
        [10119802] = {
          Content = "不用。赛琪，趁“魔王大人”没看着……我们平分了怎么样？",
          DialogueId = 10119802,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19557804",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10119803,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101198/19557804"
        },
        [10119803] = {
          Content = "你拿着就好！可以给自己买点漂亮衣服什么的，我……没什么需要用钱的地方。",
          DialogueId = 10119803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955782E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/1955782E"
        },
        [10119901] = {
          Content = "这是什么？",
          DialogueId = 10119901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19558842",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101199/19558842"
        },
        [10120001] = {
          Content = "唔……是开门的机关！藏得好严实。",
          DialogueId = 10120001,
          Duration = 3,
          GUID = "195598AA",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101200/195598AA"
        },
        [10120101] = {
          Content = "怎么这么多……呃……呃呃……",
          DialogueId = 10120101,
          Duration = 3,
          GUID = "1955A912",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A912"
        },
        [10120102] = {
          Content = "从我大腿上下来，白。你这样我动不了了……你先回冰湖城吧，我不会笑话你的。",
          DialogueId = 10120102,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A93C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120103,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A93C"
        },
        [10120103] = {
          Content = "不不不不回去，没没没没有经历过冒冒冒险的人生一定是不不不不不完整的！",
          DialogueId = 10120103,
          Duration = 3,
          GUID = "1955A966",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120104,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A966"
        },
        [10120104] = {
          Content = "好呀，那我就陪着{nickname}和魔王大人一起，把人生变“完整”一点吧。",
          DialogueId = 10120104,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A990",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10120105,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A990"
        },
        [10120105] = {
          Content = "刚刚我应该没有拖后腿……所以接下来，我想也不会有问题的！",
          DialogueId = 10120105,
          Duration = 3,
          GUID = "1955A9BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120106,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9BA"
        },
        [10120106] = {
          Content = "嗯，我们继续往前走吧。",
          DialogueId = 10120106,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A9E4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10120107,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9E4"
        },
        [10120107] = {
          Content = "（只是一些寻常的秽兽，远不如净界岛那一次来得凶险……）",
          DialogueId = 10120107,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955AA0E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10120108,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955AA0E"
        },
        [10120108] = {
          Content = "（仔细回想贝蕾教过的防身技巧，谨慎地挥出每一次剑——可以做到的。）",
          DialogueId = 10120108,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955AA38",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955AA38"
        },
