        [10120401] = {
          ContentFR = "Hé, là-bas c’est le Lac du Deuil ! On n’avait pas dit qu’on allait en ville ?",
          DialogueId = 10120401,
          GUID = "1955DA4A",
          NextDialogue = 10120402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA4A"
        },
        [10120402] = {
          ContentFR = "Errer {性别:tout seul|toute seule} comme ça, c’est dangereux ! Reviens vite, Snow t’attend ici !",
          DialogueId = 10120402,
          GUID = "1955DA74",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA74"
        },
        [10120501] = {
          ContentFR = "Hé, où tu vas ? La ville, c’est de ce côté !",
          DialogueId = 10120501,
          GUID = "1955EAB2",
          NextDialogue = 10120502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101205/1955EAB2"
        },
        [10120502] = {
          ContentFR = "Là-bas, c’est infesté de Souillés, ils vont t’avaler tout cru ! Viens vite par ici !",
          DialogueId = 10120502,
          GUID = "1955EADC",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101205/1955EADC"
        },
        [10120601] = {
          ContentFR = "Alors c’est ça, une "cité"... Je n’en avais jamais vu avant.",
          DialogueId = 10120601,
          DisableMouth = 1,
          GUID = "1955FB1A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10120602,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB1A"
        },
        [10120602] = {
          ContentFR = "Mais où aller maintenant ?... Je ferais mieux de retrouver Snow et cette Madame Camilla.",
          DialogueId = 10120602,
          DisableMouth = 1,
          GUID = "1955FB44",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB44"
        },
        [10120701] = {
          Content = "呜哇哇，过不去了！怎么回事，连下水道也在和我们作对……",
          DialogueId = 10120701,
          GUID = "19560B82",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101207/19560B82"
        },
        [10120702] = {
          Content = "让“缄默侦探”看看——这里有个水阀！他一定对水阀做了手脚！",
          DialogueId = 10120702,
          GUID = "19560BAC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120703,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101207/19560BAC"
        },
        [10120703] = {
          Content = "也就是说，这里的水位是<H>水阀</>控制的……",
          DialogueId = 10120703,
          GUID = "19560BD6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101207/19560BD6"
        },
        [10120801] = {
          Content = "前面还有个水阀！",
          DialogueId = 10120801,
          GUID = "19561BEA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101208/19561BEA"
        },
        [10120901] = {
          Content = "那个坏蛋刚刚就是钻到这个洞里去了，我们也跟上！",
          DialogueId = 10120901,
          GUID = "19562C52",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120902,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101209/19562C52"
        },
        [10120902] = {
          ContentFR = "Oh, ça me revient ! Dans le Guide d’entretien des égouts trouvé dans la poubelle n° 8, il est écrit que les égouts attirent parfois des Souillés qui aiment la chaleur et l’humidité.",
          DialogueId = 10120902,
          GUID = "19562C7C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10118603,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101209/19562C7C"
        },
