        [10125201] = {
          ContentFR = "Cette personne... j’ai l’impression de l’avoir déjà vu quelque part...",
          DialogueId = 10125201,
          DisableMouth = 1,
          GUID = "1958EDCA",
          GuideFacialId = "Shock",
