          GUID = "19591F02",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101255/19591F02"
        },
        [10125601] = {
          ContentFR = "C’est sûrement le dernier passage...",
          DialogueId = 10125601,
          DisableMouth = 1,
          GUID = "19592F6A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10125602,
