        },
        [10125922] = {
          Camera = "284.724609,1376.494141,-241.195312,-2.5,6.600879,85.189873,9.202867,72.421944,false,DoNotOverride,3.0",
          ContentFR = "La Mer du Silence... est l’origine et le repos des Charons. Les âmes des défunts y retournent, celles des vivants en émergent. Ainsi la vie circule, sans fin ni rupture.",
          DialogueId = 10125922,
          FacialId = {
            [1] = "200076:Smile01"
          },
          FinalCamera = "284.724609,1376.494141,-128.970703,-2.499999,6.600879,89.999962,9.202867,72.421944,false,DoNotOverride,3.0",
          GUID = "19596414",
          NextDialogue = 10125923,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101259/19596414"
        },
        [10125923] = {
          Camera = "145.720703,154.630859,133.727539,-2.499969,-10.399044,108.20134,30.0,99.420395,false,Manual,4.0",
          ContentFR = "Alors, si c’est ainsi...",
          DialogueId = 10125923,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "1959643E",
          NextOptions = {
            [1] = 101259231,
            [2] = 101259232
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101259/1959643E"
        },
        [10125924] = {
          Camera = "550.920898,582.548828,29.561523,-5.000001,-21.600601,-133.792847,10.000003,698.191711,false,Manual,11.0",
          ContentFR = "Si quelqu’un d’autre m’avait posé la question, voici ce que j’aurais répondu : le cycle de la vie et de la mort est une loi inviolable. Aucun pouvoir humain ne saurait le briser.",
          DialogueId = 10125924,
          FacialId = {
            [1] = "200076:None"
          },
          FinalCamera = "550.920898,582.548828,29.561523,-5.000004,-1.800445,-136.792801,10.000003,698.191711,false,Manual,11.0",
          GUID = "19596468",
          NextDialogue = 10125925,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101259/19596468"
        },
        [10125925] = {
          Camera = "550.920898,582.548828,29.561523,-5.000004,-1.800445,-136.792801,10.000003,698.191711,false,Manual,11.0",
          ContentFR = "Mais toi... toi, mon enfant, je sens en toi un destin exceptionnel.",
          DialogueId = 10125925,
          FacialId = {
            [1] = "200076:Smile01"
          },
          GUID = "19596492",
          NextDialogue = 10125926,
          Scripts = "PARA{\nCameraMoveTo{_delay{4.1},TargetPosition{\"152.515625,319.517578,95.349609,-5.000006,10.198612,-101.407249,32.500004,193.806732,false,Manual,4.0\"},duration{0}},\nCameraMoveTo{_delay{4.2},TargetPosition{\"147.56543,293.683594,100.081055,-5.000004,10.198612,-100.40712,32.500004,193.806732,false,Manual,4.0\"},blend{\"easeOutQuad\"},duration{4}},\nTurnTo{_delay{4},TurnToDescription{\"200076:p(-180)\"}},\nPlayAnimation{_delay{5.5},ActorId{200076},AnimationId{\"Talk02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/19596492"
        },
        [10125926] = {
          Camera = "708.042969,-427.089844,232.430664,-5.000006,-12.598386,132.779541,18.000004,1651574.625,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Un jour, quand tu auras acquis une force suffisante, quand tu pourras affronter la vérité du monde et même défier les lois qui le régissent...",
          DialogueId = 10125926,
          FinalCamera = "708.042969,-427.089844,232.430664,-5.000006,-7.998356,118.776794,18.000004,1651574.625,false,DoNotOverride,22.0",
          GUID = "195964BC",
          NextDialogue = 10125927,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101259/195964BC"
        },
        [10125927] = {
          ContentFR = "Peut-être alors pourras-tu marcher dans le fleuve de la vie et, à son terme, dans la Mer du Silence... revoir les âmes passées.",
          DialogueId = 10125927,
          GUID = "195964E6",
          NextOptions = {
            [1] = 101259271
          },
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/195964E6"
        },
        [10125928] = {
          Camera = "604.604492,4438.609375,-186.418945,0.000086,-1.000513,-99.205025,24.0,79896.75,false,Manual,22.0",
          ContentFR = "Hé hé... je ne suis qu’une observatrice sur le rivage. La réponse à cette question, seule, tu dois la découvrir.",
          DialogueId = 10125928,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19596510",
          NextDialogue = 10125929,
          Scripts = "CameraMoveTo{_delay{3.0},TargetPosition{"154.625,310.175781,110.634766,0.000082,4.398683,-105.211761,25.0,196.124695,false,Manual,4.0"},duration{0}}",
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/19596510"
        },
        [10125929] = {
          Camera = "131.395508,182.603516,129.605469,0.000109,-12.600892,102.794952,25.0,56.213341,false,Manual,22.0",
          ContentFR = "Si ton cœur la désire vraiment, alors poursuis ton chemin. Même si la route est incertaine, avance avec détermination.",
          DialogueId = 10125929,
          FacialId = {
            [1] = "100001:Shock02"
          },
          FinalCamera = "134.668945,169.046875,132.874023,0.000097,-13.400926,103.79464,25.0,83.006569,false,Manual,22.0",
          GUID = "1959653A",
