          },
          Scripts = "PARA{\nLookAt{_delay{1},LookAtDescription{\"100001:n(100304)\"}},\nCameraMoveTo{_delay{5},TargetPosition{\"-171.574219,-159.355469,93.070312,-3.000002,14.99738,-143.982834,30.000002,169.915115,false,Manual,3.0\"},duration{0}}\n}",
