          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101308/195BD044"
        },
        [10130901] = {
          ContentFR = "Argh ! La route est bouchée par ces horribles pics de cristal jaunes !",
          DialogueId = 10130901,
          GUID = "195BD045",
          NextDialogue = 10130902,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101309/195BD045"
        },
        [10130902] = {
          ContentFR = "Ces barils de poudre devraient faire l’affaire.",
          DialogueId = 10130902,
          GUID = "195BD046",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101309/195BD046"
        },
        [10130903] = {
          ContentFR = "Mieux vaut reculer un peu, et <H>tirer dessus</> pour déclencher l’explosion.",
          DialogueId = 10130903,
          GUID = "195BD047",
          IsBlack = 1,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101309/195BD047"
        },
        [10131001] = {
          ContentFR = "Ça a marché ! ... Oh ! Tu vas bien ? Roi Démon, pourquoi tu t’accroupis comme ça ? Tu es blessée ?",
          DialogueId = 10131001,
          GUID = "195BD048",
          NextDialogue = 10131002,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD048"
        },
        [10131002] = {
          ContentFR = "Hein ?! N... non ! Ce n’était qu’une petite e-explosion ! J’étais... en train d’étudier le terrain ! Hé hé...",
          DialogueId = 10131002,
          GUID = "195BD049",
          NextDialogue = 10131003,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD049"
        },
        [10131003] = {
          ContentFR = "Chut !",
          DialogueId = 10131003,
          GUID = "195BD050",
          NextDialogue = 10131004,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD050"
        },
        [10131004] = {
          ContentFR = "Grrrroaaar—",
          DialogueId = 10131004,
          GUID = "195BD051",
          NextDialogue = 10131005,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD051"
        },
        [10131005] = {
          ContentFR = "... On dirait qu’il y a quelque chose au fond de la fosse.",
          DialogueId = 10131005,
          GUID = "195BD052",
          NextDialogue = 10131006,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD052"
        },
        [10131006] = {
          ContentFR = "Le carnet parlait d’un Souillé spécial, tapi dans ces galeries... Restons {性别:prudents|prudentes} et ne nous éparpillons pas.",
          DialogueId = 10131006,
          GUID = "195BD053",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD053"
        },
        [10131101] = {
          ContentFR = "Regardez ! Ce gros cristal au milieu... il brille ! Et si c’était l’Éclat stellaire qu’on cherche ?!",
          DialogueId = 10131101,
          GUID = "195BD054",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101311/195BD054"
        },
        [10131201] = {
          ContentFR = "Grrrroaaar—",
          DialogueId = 10131201,
          GUID = "195BD055",
          NextDialogue = 10131202,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD055"
        },
        [10131202] = {
          ContentFR = "C’est encore ce bruit !",
          DialogueId = 10131202,
          GUID = "195BD056",
          NextDialogue = 10131203,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101312/195BD056"
        },
        [10131203] = {
          ContentFR = "Waaah ! Mais pourquoi y en a-t-il autant d’un coup ?! ... Euh... euh-euhhh...",
          DialogueId = 10131203,
          GUID = "195BD057",
          NextDialogue = 10131204,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101312/195BD057"
        },
        [10131204] = {
          ContentFR = "Ce sont sûrement les détonations qui les ont attirés...",
          DialogueId = 10131204,
          GUID = "195BD058",
          NextDialogue = 10120102,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101312/195BD058"
        },
        [10131301] = {
          Camera = "775.768799,-65.358398,179.694336,0.000056,-1.399676,-179.401596,20.0,100000.0,false,Disable,2.8",
          ContentFR = "Bombe de Lumière Radieuse — Laissez le Rédempteur Immaculé sauver le monde ! BOUM !",
          DialogueId = 10131301,
          GUID = "195BD059",
          NextDialogue = 10131302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD059"
        },
        [10131302] = {
          ContentFR = "Pas besoin de « boum », les Souillés sont déjà morts.",
          DialogueId = 10131302,
          GUID = "195BD060",
          NextDialogue = 10131303,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD060"
        },
        [10131303] = {
          ContentFR = "Oh... vraiment ? Alors, montre au Roi Démon ses glorieux butins !",
          DialogueId = 10131303,
          GUID = "195BD061",
          NextDialogue = 10131304,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD061"
        },
        [10131304] = {
          ContentFR = "Camilla disait que l’Éclat stellaire est un cristal bleu-violet parcouru de nébuleuses en mouvement... Celui-ci ressemble plutôt à une simple Argentite.",
          DialogueId = 10131304,
          GUID = "195BD062",
          NextDialogue = 10131305,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD062"
        },
        [10131305] = {
          ContentFR = "Pff... nul.",
          DialogueId = 10131305,
          GUID = "195BD063",
          NextDialogue = 10131307,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD063"
        },
        [10131306] = {
          ContentFR = "De l’<H>Argentite</> ? Quand j’étais petite, le tailleur d’à côté me disait qu’on pouvait l’utiliser pour des pigments ou des <H>teintures</>.",
          DialogueId = 10131306,
          GUID = "195BD064",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD064"
        },
        [10131307] = {
          ContentFR = "Petit larbin, montre-la à <H>Luno, la forgeronne</> quand tu auras le temps ! Mais pour l’instant, laissez le Roi Démon vous guider toujours plus loin dans les profondeurs !",
          DialogueId = 10131307,
          GUID = "195BD065",
          NextDialogue = 10131308,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD065"
        },
        [10131308] = {
          ContentFR = "Oui, oui... À vos ordres, Roi Démon.",
          DialogueId = 10131308,
          GUID = "195BD066",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD066"
        },
        [10131401] = {
          ContentFR = "Ces pics de cristal jaunes... ils renfermaient plein de pierres étincelantes !",
          DialogueId = 10131401,
          GUID = "195BD067",
          NextDialogue = 10131402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD067"
        },
        [10131402] = {
          ContentFR = "On dirait presque qu’elles avaient été soigneusement cachées là, comme de précieux trésors...",
          DialogueId = 10131402,
          GUID = "195BD068",
          NextDialogue = 10131403,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD068"
        },
        [10131403] = {
          ContentFR = "Hé hé, Psyche, tu cacherais pas toi aussi des trésors quelque part ?",
          DialogueId = 10131403,
          GUID = "195BD069",
          NextDialogue = 10131404,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD069"
        },
        [10131404] = {
          ContentFR = "Hé hé... c’est un secret.",
          DialogueId = 10131404,
          GUID = "195BD070",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD070"
        },
