            [2] = 11010108
          },
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Kill it. Listen to its death throes, bathe in its blood, and embrace the sweet release of death.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110101/1B900984"
        },
        [11010107] = {
          ContentFR = "Se boucher les oreilles pour ignorer cette voix étrange",
          DialogueId = 11010107,
          GUID = "1B9009AE",
          Subtitle = "(Cover your ears to shut out that strange voice)"
        },
        [11010108] = {
          ContentFR = "Trouver un moyen de sortir d’ici",
          DialogueId = 11010108,
          GUID = "1B9009D8",
          Subtitle = "(Find a way to leave this place)"
        },
        [11010116] = {
          ContentFR = "... Quoi qu’il en soit, je dois fuir d’ici et me débarrasser de ces pensées horribles qui s’accrochent à moi comme une peste.",
          DialogueId = 11010116,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B900B28",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...Anyway, I must get out of here, and get rid of these terrible thoughts that cling to me like a plague.)",
          VoiceName = "voice/$Locale$/story/1002/110101/1B900B28"
        },
        [11010117] = {
          ContentFR = "... {nickname2}, réveille-toi !",
          DialogueId = 11010117,
          Duration = 3,
          GUID = "1B900B52",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "..., wake up!",
