        },
        [11010203] = {
          ContentFR = "Capitaine, vous êtes enfin de retour parmi nous !",
          DialogueId = 11010203,
          Duration = 3,
          GUID = "1B90196E",
          NextDialogue = 11010204,
          SpeakNpcId = 110019,
          Subtitle = "Captain! You're finally back with us!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B90196E"
        },
        [11010204] = {
          ContentFR = "Le Souillé est presque vaincu ! Allez, finissez-le !",
          DialogueId = 11010204,
          Duration = 3,
          GUID = "1B901998",
          NextDialogue = 11010205,
          SpeakNpcId = 110019,
          Subtitle = "That Filthoid is on its last breath! Keep it up and finish it!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901998"
        },
        [11010205] = {
          ContentFR = "Urien, reculez à l’arrière avec moi ! Votre blessure s’ouvre à nouveau !",
