            [1] = "110022:Unhappy02"
          },
          FinalCamera = "-292.988281,35.451172,92.174561,0.000087,14.401064,-31.38052,35.000008,203.273438,false,Manual,22.0",
          GUID = "1B901A16",
          NextDialogue = 11010208,
          RelatedWikiId = {
            [1] = 204001
          },
          Scripts = "PARA{\nSEQ{\nLookAt{_delay{0.1},LookAtDescription{\"110022:p(P11010207Nanzhu1)\"}},\nLookAt{_delay{1},LookAtDescription{\"110022:p(P11010207Nanzhu2)\"}},\nLookAt{_delay{0.5},LookAtDescription{\"110022:n(110022)\"}},\nPlayFacial{ActorId{110022},FacialId{\"Shock01\"}},\nPlayFacial{_delay{0.5},ActorId{110022},FacialId{\"Close\"}},\n},\nMoveTo{_delay{0.1},ActorId{110022},TargetPoint{\"EX01_FixSimple_02_1\"},MoveSpeed{60},Visibility{\"Show\"}},\nPlayAnimation{_delay{4},ActorId{110022},AnimationId{\"Sigh_Start\"},Duration{1}}\n}",
          SpeakNpcId = 110022,
          Subtitle = "It's done... Argh...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/110102/1B901A16"
        },
        [11010208] = {
          Camera = "2388.339844,-2981.808594,458.513428,-15.00156,-8.397245,129.407578,25.0,2843.594727,false,Manual,1.2",
          ContentFR = "<W>Tes mains sont couvertes de ce liquide gluant, tu ne sais plus si c’est du mucus du Souillé ou ses entrailles. Pourtant, une étrange joie parcourt ton âme.</>",
          DialogueId = 11010208,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "2351.246094,-2936.632812,449.885864,-15.00156,-8.397245,129.407578,25.0,2843.594727,false,Manual,1.2",
          GUID = "1B901A40",
          NextOptions = {
            [1] = 11010209
          },
          Scripts = "PARA{\nSEQ{\nCameraMoveTo{_delay{8.01},TargetPosition{\"-123.753906,-213.164062,171.865601,-18.021496,-9.205872,95.011742,45.0,100.319092,false,DoNotOverride,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-161.269531,-210.820312,183.930786,-18.022604,-14.005917,79.809784,45.0,100.319092,false,DoNotOverride,22.0\"},duration{20}}\n},\nPARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\n}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Your hands are drenched in wet, slimy filth, uncertain whether it's the Filthoid's secretions or its innards. Yet, a sudden joy tingles through your soul, bringing an inexplicable elation.",
          TalkActionId = {
            [1] = "110022:Sigh_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110102/1B901A40"
        },
        [11010209] = {
          ContentFR = "– Tais-toi ! Ce n’est pas ce que je ressens !",
          DialogueId = 11010209,
          GUID = "1B901A6A",
          NextDialogue = 11010210,
          Subtitle = "(Shut up! That was not how I felt!)"
        },
        [11010210] = {
          Camera = "-299.773438,-22.185547,-5.160034,-18.018326,38.192356,-12.391366,30.0,100.319092,false,DoNotOverride,22.0",
          ContentFR = "<W>Ne résiste pas. Je suis ce que tu es vraiment, ton instinct de mort. Un jour, tu suivras mon chemin et obéiras à la volonté ancestrale...</>",
          DialogueId = 11010210,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-298.789062,-47.498047,-11.343872,-18.018387,40.392326,-2.390289,30.000002,100.319092,false,DoNotOverride,22.0",
          GUID = "1B901A94",
          NextOptions = {
            [1] = 11010211
          },
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Do not resist, because I am what you actually are. I am your instinct for death. One day you shall follow my lead and obey the ancient will...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110102/1B901A94"
        },
        [11010211] = {
          ContentFR = "Refuser de se laisser emporter par ses délires et s’efforcer de rester lucide",
          DialogueId = 11010211,
          GUID = "1B901ABE",
          NextDialogue = 11010212,
          Subtitle = "(You refuse to let the ramblings erode your will and try to stay sane.)"
        },
        [11010212] = {
          Camera = "-241.761719,-58.371094,187.967773,0.000089,-23.197569,-2.984956,35.000008,116.737953,false,Manual,4.707314",
          ContentFR = "...",
          DialogueId = 11010212,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Pain01"
          },
          FinalCamera = "-253.742188,-57.75,193.109009,0.000089,-23.197569,-2.984956,35.000008,129.145432,false,Manual,5.70814",
          GUID = "1B901AE8",
          Scripts = "PostProcess{MaterailInstance{"None"}}",
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Sigh_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110102/1B901AE8"
        },
        [11010215] = {
          ContentFR = "... Cette voix agaçante s'est enfin tue.",
          DialogueId = 11010215,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B901B66",
          NextDialogue = 11010216,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...That annoying voice has finally stopped.)",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901B66"
        },
        [11010216] = {
          ContentFR = "Je ferais mieux de vérifier ce qui est arrivé aux autres.",
          DialogueId = 11010216,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B901B90",
          SpeakNpcId = 110022,
          Subtitle = "I should go check on the others.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901B90"
        },
        [11010221] = {
          ContentFR = "Hfff... Docteur Daphne, on peut considérer notre mission terminée, non ? ",
          DialogueId = 11010221,
          Duration = 3,
          GUID = "1B901C62",
          SpeakNpcId = 110019,
          Subtitle = "Hssss... Dr Daphne, we've completed our mission, right?",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901C62"
        },
        [11010222] = {
          ContentFR = "... Non, tant qu’on ne rentre pas vivant, la mission n’est pas finie !",
          DialogueId = 11010222,
          Duration = 3,
          GUID = "1B901C8C",
          SpeakNpcId = 110005,
          Subtitle = "...No, not until when we get back alive.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901C8C"
        },
        [11010223] = {
          ContentFR = "Ça va, Daphne. Calme-toi... ça va aller, respire...",
          DialogueId = 11010223,
          Duration = 3,
          GUID = "1B901CB6",
          SpeakNpcId = 110005,
          Subtitle = "It's alright, Daphne. Calm down. Everything's going to be okay. Come down.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901CB6"
        },
        [11010224] = {
          ContentFR = "Ah ! Vous êtes revenu !",
          DialogueId = 11010224,
          Duration = 3,
          GUID = "1B901CE0",
          SpeakNpcId = 110005,
          Subtitle = "You're back!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901CE0"
        },
        [11010225] = {
          ContentFR = "... Vite, réveille-toi ! Si ça continue, tu vas mourir !",
          DialogueId = 11010225,
          Duration = 3,
          GUID = "1B90191A",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Wake up!! Or you'll die!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B90191A"
        },
        [11010226] = {
          ContentFR = "Capitaine !",
          DialogueId = 11010226,
          Duration = 3,
          GUID = "1B901944",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Captain!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901944"
        },
        [11010227] = {
          ContentFR = "Ah, {性别2:le capitaine est réveillé|la capitaine est réveillée} !",
          DialogueId = 11010227,
          Duration = 3,
          GUID = "1B901945",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Whoa, Captain's awake!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901945"
        },
        [11010301] = {
          Camera = "-101.755859,41.945312,134.13269,0.000056,-2.6,-29.789253,35.000008,251.174286,false,Manual,14",
          ContentFR = "... Pas {性别2:blessé|blessée} ?",
          DialogueId = 11010301,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          FinalCamera = "-99.96875,45.089844,134.13269,0.000056,-2.6,-29.789253,35.000008,251.174286,false,Manual,14",
          GUID = "1B902982",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11010302,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012
          },
          Scripts = "SEQ{\nTurnTo{TurnToDescription{\"110005:n(110022)\"}},\nPlayAnimation{ActorId{110005},AnimationId{\"Explain02_Start\"},Duration{0}}\n}",
          SpeakNpcId = 110005,
          Subtitle = "...Are you injured?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902982"
        },
        [11010302] = {
          Camera = "181.714844,-51.582031,136.406006,0.000081,-3.999717,173.611221,35.000008,237.587646,false,Manual,14",
          ContentFR = "Ça va.",
          DialogueId = 11010302,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9029AC",
          LookAt = {
            [1] = "110022:n(110005)"
          },
          NextDialogue = 11010303,
          SpeakNpcId = 110022,
          Subtitle = "I'm all right.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B9029AC"
        },
        [11010303] = {
          Camera = "-41.207031,-17.558594,131.959473,0.000208,-0.800314,-17.784134,35.0,195.280243,false,Manual,22.0",
          ContentFR = "Heureux de l’entendre. Quand ce Souillé vous a attaqué, je croyais que...",
          DialogueId = 11010303,
          FacialId = {
            [1] = "110005:Happy01"
          },
          FinalCamera = "-26.443359,-22.296875,131.742676,0.000208,-0.800321,-17.784128,35.0,195.280243,false,Manual,22.0",
          GUID = "1B9029D6",
          NextDialogue = 11010304,
          SpeakNpcId = 110005,
          Subtitle = "Good to hear that. When you got tangled up by that Filthoid, I thought I'd never...",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110103/1B9029D6"
        },
        [11010304] = {
          ContentFR = "... Enfin, l’important c’est que vous allez bien.",
          DialogueId = 11010304,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B902A00",
          NextDialogue = 11010305,
          SpeakNpcId = 110005,
          Subtitle = "...I'm just glad to see you're okay.",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A00"
        },
        [11010305] = {
          Camera = "-194.214844,180.058594,138.991333,0.000214,-4.200006,-43.389214,35.000008,195.280243,false,Manual,22.0",
          ContentFR = "Mais... nous ne sommes plus nombreux, et ceux qui ont survécu sont gravement blessés.",
          DialogueId = 11010305,
          FacialId = {
            [1] = "110005:Sad01"
          },
          FinalCamera = "-202.876953,170.601562,138.991333,0.000215,-4.200006,-41.389534,35.000008,195.280243,false,Manual,22.0",
          GUID = "1B902A2A",
          NextDialogue = 11010306,
          Scripts = "SEQ{\nLookAt{LookAtDescription{\"110005:p(fix03hurt)\"}}\n}",
          SpeakNpcId = 110005,
          Subtitle = "...There are so few of us left. And those who survived are heavily wounded.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A2A"
        },
        [11010306] = {
          Camera = "3.195312,-10.464844,135.754272,0.000049,-2.400326,-29.395937,35.0,139.800323,false,Manual,22.0",
          ContentFR = "Si vous avez le temps, pourriez-vous parler avec les blessés ?",
          DialogueId = 11010306,
          GUID = "1B902A54",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11010307,
          Scripts = "SEQ{\nCameraMoveTo{_delay{6},TargetPosition{\"79.023438,-32.414062,128.774658,0.000204,1.19906,172.210541,35.0,189.147873,false,Manual,22.0\"},duration{0}},\nPlayAnimation{ActorId{110022},AnimationId{\"AgreeHead\"},Duration{1}}\n}",
          SpeakNpcId = 110005,
          Subtitle = "If you have the time, would you stay and talk to the wounded?",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A54"
        },
        [11010307] = {
          Camera = "-201.763672,334.066406,336.065674,0.000205,-27.598082,-57.980461,26.0,189.147873,false,Manual,22.0",
          ContentFR = "Merci. Je dois aller chercher quelque chose, alors je compte sur vous pour veiller sur eux. Les soldats vous regardent avec respect, vos encouragements leur feront du bien.",
          DialogueId = 11010307,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          FinalCamera = "-201.763672,334.066406,304.138428,0.000206,-27.598082,-57.980148,26.0,189.147873,false,Manual,22.0",
          GUID = "1B902A7E",
          NextDialogue = 11010308,
          SpeakNpcId = 110005,
          Subtitle = "Thank you. I'm heading back to find something, so please take care of them for the time being. The soldiers look up to you. Your encouragement will make them feel better.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A7E"
        },
        [11010308] = {
          Camera = "188.039062,-56.824219,140.151245,0.000181,-4.200928,174.81337,35.0,189.147873,false,Manual,22.0",
          ContentFR = "Tu vas où ?",
          DialogueId = 11010308,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902AA8",
          NextDialogue = 11010309,
          SpeakNpcId = 110022,
          Subtitle = "Where are you going?",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902AA8"
        },
        [11010309] = {
          Camera = "-31.5,-4.214844,98.260132,0.000095,10.799259,-24.393532,35.0,155.397324,false,Manual,22.0",
          ContentFR = "La carte montre plusieurs entrepôts proches. On pourrait y trouver des trousses de premiers soins si nous avons de la chance.",
          DialogueId = 11010309,
          GUID = "1B902AD2",
          NextDialogue = 11010310,
          Scripts = "SEQ{\nCameraMoveTo{_delay{3.5},TargetPosition{\"-4824.253906,-1793.578125,399.504517,0.000149,-14.800787,8.606606,35.0,100000.0,false,Manual,22.0\"},duration{0}}\n}",
          SpeakNpcId = 110005,
          Subtitle = "The battle map shows several warehouses near our location. We might find some first-aid kits there if we're lucky.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902AD2"
        },
        [11010310] = {
          Camera = "-19.5,-9.617188,101.238037,0.000106,10.999233,-24.590504,35.000008,169.901962,false,Manual,22.0",
          ContentFR = "J’ai épuisé tous mes coagulants et analgésiques, mais certains soldats n’ont pas été soignés... leurs blessures ne peuvent plus attendre.",
          DialogueId = 11010310,
          FacialId = {
            [1] = "110005:Sad01"
          },
          FinalCamera = "-8.886719,-14.484375,103.508179,0.000106,10.999233,-24.590261,35.000008,169.901962,false,Manual,22.0",
          GUID = "1B902AFC",
          NextDialogue = 11010311,
          SpeakNpcId = 110005,
          Subtitle = "I'm already out of coagulants and painkillers, but some of the soldiers haven't been treated yet... Their injuries can't afford any more delays.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902AFC"
        },
        [11010311] = {
          Camera = "87.443359,-59.851562,132.342285,0.000173,-0.600893,160.005676,35.000008,196.017685,false,Manual,22.0",
          ContentFR = "Tu restes ici. J’y vais.",
          DialogueId = 11010311,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902B26",
          NextDialogue = 11010312,
          Scripts = "PlayAnimation{_delay{1},ActorId{110022},AnimationId{"DisagreeHead"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "You should stay. I'll go.",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902B26"
        },
        [11010312] = {
          Camera = "-147.375,86.609375,133.640381,0.000178,-1.801148,-38.594769,35.0,100000.0,false,Manual,22.0",
          ContentFR = "C’est le travail du médecin—",
          DialogueId = 11010312,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          GUID = "1B902B50",
          NextDialogue = 11010313,
          SpeakNpcId = 110005,
          Subtitle = "This is the medic's job—",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902B50"
        },
        [11010313] = {
          Camera = "87.443359,-59.851562,132.342285,0.000173,-0.600893,160.005676,35.000008,196.017685,false,Manual,22.0",
          ContentFR = "Reste ici. Tu n’es pas assez forte pour gérer les Souillés seule. On ne peut pas perdre notre unique médecin.",
          DialogueId = 11010313,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902B7A",
          NextDialogue = 11010314,
          SpeakNpcId = 110022,
          Subtitle = "And the medic stays. You aren't strong enough to deal with the Filthoids out there alone. We can't afford to lose our only medic.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902B7A"
        },
        [11010314] = {
          Camera = "-114.242188,52.828125,134.584595,0.000186,-2.000849,-30.397076,35.000008,203.938095,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 11010314,
          Duration = 2,
          FinalCamera = "-79.822266,32.675781,133.191162,0.000186,-2.000849,-30.397076,35.000008,203.938095,false,Manual,22.0",
          GUID = "1B902BA4",
          NextDialogue = 11010315,
          SpeakNpcId = 110005,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110005:Explain02_End",
            [2] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902BA4"
        },
        [11010315] = {
          ContentFR = "Compris... je suivrai vos ordres.",
          DialogueId = 11010315,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B902BCE",
          NextDialogue = 11010316,
          SpeakNpcId = 110005,
          Subtitle = "Understood... I'll follow your orders.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902BCE"
        },
        [11010316] = {
          ContentFR = "Votre radio fonctionne toujours ?",
          DialogueId = 11010316,
          GUID = "1B902BF8",
          NextDialogue = 11010317,
          SpeakNpcId = 110005,
          Subtitle = "Is your radio still working?",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902BF8"
        },
        [11010317] = {
          Camera = "103.357422,-46.015625,131.054077,0.000209,-0.60077,165.802734,35.0,189.147873,false,Manual,22.0",
          ContentFR = "Oui, elle fonctionne.",
          DialogueId = 11010317,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902C22",
          NextDialogue = 11010318,
          SpeakNpcId = 110022,
          Subtitle = "Yes, it still works.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902C22"
        },
        [11010318] = {
          Camera = "-200.285156,169.671875,157.805542,0.000194,-7.601222,-43.996536,35.0,203.938095,false,Manual,22.0",
          ContentFR = "Parfait. Restez en communication, nous resterons en contact.",
          DialogueId = 11010318,
          GUID = "1B902C4C",
          SpeakNpcId = 110005,
          Subtitle = "Then please stay on the channel so we can keep in touch.",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902C4C"
        },
        [11010401] = {
          ContentFR = "Ces ordures... !",
          DialogueId = 11010401,
          Duration = 3,
          GUID = "1B9039EA",
          NextOptions = {
            [1] = 11010402,
            [2] = 11010404,
            [3] = 11010406
          },
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012
          },
          SpeakNpcId = 110044,
          Subtitle = "Damn those friggin' rotters!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B9039EA"
        },
        [11010402] = {
          ContentFR = "Ça va, tu n’es pas trop blessé ?",
          DialogueId = 11010402,
          GUID = "1B903A14",
          ImprPlusId = 1009,
          NextDialogue = 11010403,
          Subtitle = "Are you okay?"
        },
        [11010403] = {
          ContentFR = "Capitaine ! Je vais bien, je peux encore bouger... Hfff—",
          DialogueId = 11010403,
          Duration = 3,
          GUID = "1B903A3E",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Captain! I'm fine, I can still move... HSSSSS—",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903A3E"
        },
        [11010404] = {
          ContentFR = "Je n’ai pas réussi à vous protéger...",
          DialogueId = 11010404,
          GUID = "1B903A68",
          ImprPlusId = 1007,
          NextDialogue = 11010405,
          Subtitle = "I failed to protect you. I'm sorry."
        },
        [11010405] = {
          ContentFR = "Non, Capitaine ! Vous avez fait de votre mieux !",
          DialogueId = 11010405,
          Duration = 3,
          GUID = "1B903A92",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Please don't say that, Captain! You did your best!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903A92"
        },
        [11010406] = {
          ContentFR = "Tu en veux à qui ? Qui est-ce que tu insultes ?",
          DialogueId = 11010406,
          GUID = "1B903ABC",
          ImprPlusId = 1010,
          NextDialogue = 11010407,
          Subtitle = "Who are you cursing at?"
        },
        [11010407] = {
          ContentFR = "À part ces maudits Déchus, qui d’autre ?",
          DialogueId = 11010407,
          Duration = 3,
          GUID = "1B903AE6",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Who else could it be? The bastards who call themselves The Forsakens.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903AE6"
        },
        [11010408] = {
          ContentFR = "Ces monstres ont osé utiliser les Souillés comme arme... Les Déchus sont des monstres, tout comme leurs Souillés !",
          DialogueId = 11010408,
          Duration = 3,
          GUID = "1B903B10",
          NextDialogue = 11010409,
          RelatedWikiId = {
            [1] = 101004
          },
          SpeakNpcId = 110044,
          Subtitle = "Those despicable cowards are using Filthoids as their weapon... The Forsakens are monsters, just like their Filthoid pets!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B10"
        },
        [11010409] = {
          ContentFR = "Et les supérieurs ne valent pas mieux, pas un seul mot sur les Souillés dans le manuel de mission !",
          DialogueId = 11010409,
          Duration = 3,
          GUID = "1B903B3A",
          NextDialogue = 11010410,
          SpeakNpcId = 110044,
          Subtitle = "And those blasted airheads giving us the orders are just as bad. The mission brief mentioned nothing about the Filthoid hordes down here.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B3A"
        },
        [11010410] = {
          ContentFR = "... Je suis désolé. Je n’aurais pas dû exprimer ma frustration devant vous, Capitaine.",
          DialogueId = 11010410,
          Duration = 3,
          GUID = "1B903B64",
          NextDialogue = 11010411,
          SpeakNpcId = 110044,
          Subtitle = "...Sorry about that. I shouldn't have vented my frustration in front of you, Captain.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B64"
        },
        [11010411] = {
          ContentFR = "Ce n’est pas grave. Il vaut mieux laisser libre cours à ses émotions que de rester muet.",
          DialogueId = 11010411,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B903B8E",
          NextDialogue = 11010412,
          SpeakNpcId = 110022,
          Subtitle = "It's alright. Letting out emotions is better than being unable to speak at all.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B8E"
        },
        [11010412] = {
          ContentFR = "Haha ! Vous savez toujours comment réconforter quelqu’un, Capitaine !",
          DialogueId = 11010412,
          Duration = 3,
          GUID = "1B903BB8",
          NextDialogue = 11010413,
          SpeakNpcId = 110044,
          Subtitle = "Hah! You always know how to soothe people, Captain!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903BB8"
        },
        [11010413] = {
          ContentFR = "Heureusement que vous étiez là... sinon on y serait tous passés.",
          DialogueId = 11010413,
          Duration = 3,
          GUID = "1B903BE2",
          NextDialogue = 11010414,
          SpeakNpcId = 110044,
          Subtitle = "And thank goodness we have you. We thought we were goners.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903BE2"
        },
        [11010414] = {
          ContentFR = "C’est juste qu’on est trop inexpérimentés. Si le <H>Commandant Avar</> était là... Il aurait trouvé une solution.",
          DialogueId = 11010414,
          Duration = 3,
          GUID = "1B903C0C",
          SpeakNpcId = 110044,
          Subtitle = "It's just that we're too green. If only Commander Avar were here... As a veteran, he must have a way to get us out.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C0C"
        },
        [11010415] = {
          ContentFR = "Commandant Avar... toujours pas de nouvelles.",
          DialogueId = 11010415,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B903C36",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Sir Avar... Still no words from him.)",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C36"
        },
        [11010416] = {
          ContentFR = "Faites attention... je vous attends ici.",
          DialogueId = 11010416,
          GUID = "1B903C37",
          SpeakNpcId = 110005,
          Subtitle = "Please be careful. I'll be waiting for you right here.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C37"
        },
        [11010501] = {
          ContentFR = "Docteur... Docteur Daphne... nous sommes coincés ici, ça sent la fin. Si jamais je ne m’en sors pas ici, pourriez-vous m’enterrer... s’il vous plaît ?",
          DialogueId = 11010501,
          Duration = 3,
          GUID = "1B904A52",
          NextOptions = {
            [1] = 11010502,
            [2] = 11010504
          },
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012
          },
          SpeakNpcId = 110045,
          Subtitle = "Doctor... Dr Daphne... We're stuck in this bloody dump. Please, Dr Daphne, if I don't make it, do me a favour and bury me...",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904A52"
        },
        [11010502] = {
          ContentFR = "Ne parle pas trop, ça pourrait aggraver tes blessures.",
          DialogueId = 11010502,
          GUID = "1B904A7C",
          ImprPlusId = 1007,
          NextDialogue = 11010503,
          Subtitle = "Don't be discouraged. It'll worsen your wounds."
        },
        [11010503] = {
          ContentFR = "Nous n’avons plus d’analgésiques... alors je dois râler un peu pour me sentir mieux.",
          DialogueId = 11010503,
          Duration = 3,
          FinalCamera = "19.119141,-1903.257812,170.347046,0.000149,-8.797147,-118.375465,35.0,100000.0,false,Manual,22.0",
          GUID = "1B904AA6",
          NextDialogue = 11010506,
          SpeakNpcId = 110045,
          Subtitle = "We're out of painkillers... so I have to grumble a bit to make myself feel better.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110105/1B904AA6"
        },
        [11010504] = {
          ContentFR = "Bien, continue à élever la voix pour attirer les Souillés.",
          DialogueId = 11010504,
          GUID = "1B904AD0",
          ImprPlusId = 1010,
          NextDialogue = 11010505,
          Subtitle = "Right, keep raising your voice to attract the Filthoids."
        },
        [11010505] = {
          ContentFR = "Désolée, Capitaine... je me tais. Sans analgésiques, je ne peux que râler un peu pour me sentir mieux.",
          DialogueId = 11010505,
          Duration = 3,
          FinalCamera = "19.119141,-1903.257812,170.347046,0.000149,-8.797147,-118.375465,35.0,100000.0,false,Manual,22.0",
          GUID = "1B904AFA",
          NextDialogue = 11010506,
          SpeakNpcId = 110045,
          Subtitle = "Sorry, Captain. I'll zip it. With no painkillers left, I can only grumble a little to help distract me from the pain.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110105/1B904AFA"
        },
        [11010506] = {
          ContentFR = "Tout à l’heure, Docteur Daphne et vous avez couvert notre retraite... elle va bien ?",
          DialogueId = 11010506,
          Duration = 3,
          GUID = "1B904B24",
          NextDialogue = 11010507,
          SpeakNpcId = 110045,
          Subtitle = "Dr Daphne and you covered our retreat just then. How is she?",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B24"
        },
        [11010507] = {
          ContentFR = "Elle va bien. C’est elle qui m’a demandé de venir vous voir.",
          DialogueId = 11010507,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B904B4E",
          NextDialogue = 11010508,
          SpeakNpcId = 110022,
          Subtitle = "She's all right. She told me to come check on all of you.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B4E"
        },
        [11010508] = {
          ContentFR = "Tant mieux... Elle, une jeune dame de haute naissance, aurait pu rester tranquillement à l’Académie d’Alchimie, mais non, elle a choisi de se faire muter dans la XIIIᵉ Légion et de subir tout ça. Je ne comprends pas ce qu’elle a dans la tête.",
          DialogueId = 11010508,
          Duration = 3,
          GUID = "1B904B78",
          NextDialogue = 11010509,
          RelatedWikiId = {
            [1] = 101007
          },
          SpeakNpcId = 110045,
          Subtitle = "Good to hear that. *sigh* A high-born lady like her could've stayed at the Academy, but no, she chose to serve with the 13th Legion. What was she thinking?",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B78"
        },
        [11010509] = {
          ContentFR = "... « Gloire et loyauté éternelles à notre Empereur » ? Ces aristocrates rabâchent toujours la même chose, mais là, coincés dans ce trou, je me demande s’ils ne regrettent pas leur enthousiasme.",
          DialogueId = 11010509,
          Duration = 3,
          GUID = "1B904BA2",
          NextDialogue = 11010510,
          SpeakNpcId = 110045,
          Subtitle = "..."Eternal glory and loyalty to our Emperor!" Those aristocrats say that all the time. I wonder if any of them would still be so keen on that when they're actually in a filth pit like this.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904BA2"
        },
        [11010510] = {
          ContentFR = "Mais Docteur Daphne est vraiment douée en médecine et parle si gentiment... Capitaine, il faut que vous la protégiez, ne la laissez pas mourir ici.",
          DialogueId = 11010510,
          Duration = 3,
          GUID = "1B904BCC",
          SpeakNpcId = 110045,
          Subtitle = "But Dr Daphne has real medical skills and a soft, pretty voice. We gotta keep her safe, Captain. Don't want her to die here.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904BCC"
        },
        [11010618] = {
          ContentFR = "Il y a bien quelques caisses de ravitaillement dans l’entrepôt.",
          DialogueId = 11010618,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B905D84",
          NextDialogue = 11010619,
          SpeakNpcId = 110022,
          Subtitle = "The warehouse does have a few military supply crates.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905D84"
        },
        [11010619] = {
          ContentFR = "Très bien. Mais avant de fouiller, assurez-vous qu’il n’y ait pas de pièges autour.",
          DialogueId = 11010619,
          Duration = 3,
          GUID = "1B905DAE",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110005,
          Subtitle = "Great. But before your search, make sure the crates are safe to be approached.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905DAE"
        },
        [11010621] = {
          ContentFR = "C’est bon, j’ai les médicaments. Rien d’anormal.",
          DialogueId = 11010621,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B905E02",
          NextDialogue = 11010622,
          SpeakNpcId = 110022,
          Subtitle = "I got it. The medicine appears to be in good condition.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E02"
        },
        [11010622] = {
          ContentFR = "Merci ! Faites attention sur le chemin du retour. Il pourrait encore y avoir des Souillés dans les parages.",
          DialogueId = 11010622,
          Duration = 3,
          GUID = "1B905E2C",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110005,
          Subtitle = "That's great! Thank you! Be careful on your way back. Filthoids are probably lurking around this place.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E2C"
        },
        [11010623] = {
          ContentFR = "Je me demande ce que sont devenus les autres…",
          DialogueId = 11010623,
          Duration = 3,
          GUID = "1B905E56",
          SpeakNpcId = 110026,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Wonder how the other guys are doing...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E56"
        },
        [11010624] = {
          ContentFR = "Ces sales bêtes vont payer pour ce qu’elles ont fait.",
          DialogueId = 11010624,
          Duration = 3,
          GUID = "1B905E80",
          SpeakNpcId = 110057,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Gotta make those rotters pay.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E80"
        },
        [11010625] = {
          ContentFR = "Maudits Souillés... maudits Déchus...",
          DialogueId = 11010625,
          Duration = 3,
          GUID = "1B905EAA",
          SpeakNpcId = 110024,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Damn those Filthoids... Damn The Forsakens...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905EAA"
        },
        [11010626] = {
          ContentFR = "Ne pas dormir… je dois tenir…",
          DialogueId = 11010626,
          Duration = 3,
          GUID = "1B905ED4",
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Can't fall asleep... Can't die here...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905ED4"
        },
        [11010627] = {
          ContentFR = "Hsss... mon bras ne répond plus...",
          DialogueId = 11010627,
          Duration = 3,
          GUID = "1B905EFE",
          SpeakNpcId = 110027,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Hsss— I can't feel my arm...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905EFE"
        },
        [11010628] = {
          ContentFR = "Heureusement que {性别2:le|la} capitaine est indemne. On a encore une chance.",
          DialogueId = 11010628,
          Duration = 3,
          GUID = "1B905F28",
          SpeakNpcId = 110027,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Thank goodness our Captain is all right. We're gonna make it.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905F28"
        },
        [11010701] = {
          Camera = "-181.388672,-39.609375,130.604614,-0.015137,-0.715817,67.630249,35.0,171.964966,false,Manual,22.0",
          ContentFR = "Ah, vous êtes de retour !",
          DialogueId = 11010701,
          Duration = 3,
          GUID = "1B906B22",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextOptions = {
            [1] = 11010702
          },
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 101004
          },
          Scripts = "PARA{\nMoveTo{_delay{0.5},ActorId{110022},TargetPoint{\"pNanzhumove\"},MoveSpeed{80},Visibility{\"Show\"}},\nCameraMoveTo{_delay{1.5},TargetPosition{\"-101.953125,413.027344,207.724121,-0.015137,-12.916167,-98.55867,35.0,155.193787,false,Manual,22.0\"},duration{0}},\nPlayAnimation{ActorId{110005},AnimationId{\"Explain02_Start\"},Duration{3}}\n}",
          SpeakNpcId = 110005,
          Subtitle = "You're back!",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906B22"
        },
        [11010702] = {
          ContentFR = "Remettre les médicaments à Daphne",
          DialogueId = 11010702,
          GUID = "1B906B4C",
          NextDialogue = 11010703,
          Subtitle = "(Give the medicine to Daphne)"
        },
        [11010703] = {
          Camera = "-362.734375,-126.394531,148.611084,0.000269,-5.800961,36.800026,35.0,396.962982,false,Manual,22.0",
          ContentFR = "Parfait, cela devrait aider à stabiliser les blessés.",
          DialogueId = 11010703,
          Duration = 3,
          FinalCamera = "-358.041016,-122.882812,148.015259,0.000269,-5.800961,36.800026,35.0,396.962982,false,Manual,22.0",
          GUID = "1B906B76",
          SpeakNpcId = 110005,
          Subtitle = "Great, this would help stabilise the wounded.",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906B76"
        },
        [11010704] = {
          Camera = "-38.066406,117.800781,137.944946,0.000298,-5.401026,-146.592728,29.45373,261.978973,false,Manual,22.0",
          ContentFR = "Des nouvelles des Loups Blancs ?",
          DialogueId = 11010704,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B906BA0",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11010705,
          Scripts = "SetLocation{ActorId{110022},TargetPoint{"pNanzhumove"},Visibility{"Show"}}",
          SpeakNpcId = 110022,
          Subtitle = "Any news from the Snow Wolves?",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906BA0"
        },
        [11010705] = {
          Camera = "-191.169922,2.410156,140.592285,0.000278,-3.600862,52.200577,35.0,130.402435,false,Manual,22.0",
          ContentFR = "Toujours rien. Pendant votre absence, j’ai tenté de joindre le Commandant Avar des Loups Blancs, ainsi que le Commandant en Chef Fulvis, mais toutes les communications sont coupées.",
          DialogueId = 11010705,
          Duration = 3,
          GUID = "1B906BCA",
          NextDialogue = 11010706,
          Scripts = "SEQ{\nPlayAnimation{ActorId{110005},AnimationId{\"DisagreeHead\"},Duration{1.5}},\nCameraMoveTo{TargetPosition{\"-744.447266,-1296.125,176.616455,0.000267,-8.001067,112.406685,35.0,100000.0,false,Manual,22.0\"},duration{0},_delay{2}},\nCameraMoveTo{TargetPosition{\"-847.738281,-1338.699219,176.616455,0.000268,-8.001067,112.406708,35.0,100000.0,false,Manual,22.0\"},duration{3}}\n}",
          SpeakNpcId = 110005,
          Subtitle = "Not yet. While you were away, I tried reaching out to Commander Avar of the Snow Wolves and Chief Commander Fulvis, but none of the comm channels were working.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906BCA"
        },
        [11010706] = {
          Camera = "-515.240234,50.238281,106.900269,0.000249,0.398227,-7.393137,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Continue d’essayer. En attendant, voyons si l’on peut trouver un endroit plus sûr pour les blessés.",
          DialogueId = 11010706,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B906BF4",
          NextDialogue = 11010707,
          Scripts = "PARA{\nSEQ{\nTurnTo{TurnToDescription{\"110022:n(110005)\"}},\nLookAt{LookAtDescription{\"110022:n(110005)\"}}\n},\nCameraMoveTo{_delay{1.5},TargetPosition{\"-129.167969,149.335938,131.636841,0.000255,-1.001859,-106.992546,35.0,190.165726,false,Manual,22.0\"},duration{0}}\n}",
          SpeakNpcId = 110022,
          Subtitle = "Keep trying. And meanwhile, let's see if we can find a safer place for the wounded.",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906BF4"
        },
        [11010707] = {
          Camera = "-365.529297,-63.316406,169.275757,0.000246,-12.001523,22.80418,35.0,312.469208,false,Manual,22.0",
          ContentFR = "... J’ai peut-être une idée.",
          DialogueId = 11010707,
          Duration = 3,
          FinalCamera = "-346.34375,-87.652344,150.890503,0.000338,-7.800048,30.019533,35.0,100000.0,false,Manual,22.0",
          GUID = "1B906C1E",
          NextDialogue = 11010708,
          Scripts = "SEQ{\nPlayAnimation{ActorId{110005},AnimationId{\"Explain02_Start\"},Duration{3}},\nPlayAnimation{ActorId{110005},AnimationId{\"Explain02_End\"},Duration{1}}\n}",
          SpeakNpcId = 110005,
          Subtitle = "...Actually, I have a plan.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C1E"
        },
        [11010708] = {
          Camera = "-346.34375,-87.652344,150.890503,0.000338,-7.800048,30.019533,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Laquelle ?",
          DialogueId = 11010708,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B906C48",
          NextDialogue = 11010709,
          SpeakNpcId = 110022,
          Subtitle = "What is it?",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C48"
        },
        [11010709] = {
          Camera = "-346.34375,-87.652344,150.890503,0.000338,-7.800048,30.019533,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Regardez cette carte.",
          DialogueId = 11010709,
          Duration = 3,
          FinalCamera = "-286.345703,-87.492188,152.207397,0.000344,-7.199763,40.221565,35.0,100000.0,false,Manual,22.0",
          GUID = "1B906C72",
          NextDialogue = 11010710,
          SpeakNpcId = 110005,
          Subtitle = "Take a look at this map.",
          TalkActionId = {
            [1] = "110005:Explain01_Start"
          },
          ToFinalCameraBlendTime = 60,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C72"
        },
        [11010710] = {
          ContentFR = "Nous sommes coincés dans la zone de stockage, la sortie est bloquée. Mais il reste un endroit que nous n’avons pas vérifié... <H>les souterrains</>.",
          DialogueId = 11010710,
          Duration = 3,
          GUID = "1B906C9C",
          NextDialogue = 11010711,
          SpeakNpcId = 110005,
          Subtitle = "We're currently in the storage area where the exit is blocked. However, there are some underground tunnels that we haven't checked yet.",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C9C"
        },
        [11010711] = {
          ContentFR = "La plupart des cités et forteresses impériales possèdent un vaste réseau d’égouts. Ces dix dernières années, ils ont même été agrandis pour servir d’abris en cas de bombardement.",
          DialogueId = 11010711,
          Duration = 3,
          GUID = "1B906CC6",
          NextDialogue = 11010712,
          SpeakNpcId = 110005,
          Subtitle = "Most imperial cities and fortresses have elaborate networks of underground sewers. In recent years, some of these tunnels were expanded and reinforced to serve as air raid shelters.",
          TalkActionId = {
            [1] = "110005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906CC6"
        },
        [11010712] = {
          ContentFR = "Si nous avons de la chance et que les Déchus n’y ont pas tendu d’embuscade... nous pourrions y transférer les blessés pour qu’ils se reposent. Ces tunnels débouchent aussi hors de la forteresse, ce qui faciliterait un éventuel secours.",
          DialogueId = 11010712,
          Duration = 3,
          GUID = "1B906CF0",
          NextDialogue = 11010713,
          SpeakNpcId = 110005,
          Subtitle = "If we're lucky enough and The Forsakens didn't set up any ambushes, maybe we could get the wounded there to rest and recover. Besides, the sewer tunnels run all the way outside the fortress, so if our reinforcements arrive, they can easily get to us.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906CF0"
        },
        [11010713] = {
          ContentFR = "Bien sûr... ces tunnels peuvent être dangereux. Si vous jugez le plan acceptable, permettez-moi d’aller explorer les souterrains.",
          DialogueId = 11010713,
          Duration = 3,
          GUID = "1B906D1A",
          NextDialogue = 11010714,
          SpeakNpcId = 110005,
          Subtitle = "Of course... the tunnels might be risky as well. If you think it's feasible, allow me to scout ahead first.",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D1A"
        },
        [11010714] = {
          Camera = "-132.943359,121.832031,131.186157,0.000256,0.3982,-111.990349,35.0,190.165726,false,Manual,22.0",
          ContentFR = "Ça vaut le coup d’essayer. Mais t’envoyer seule en éclaireur, c’est trop risqué.",
          DialogueId = 11010714,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-138.074219,112.890625,131.25708,0.000256,-0.401793,-110.989861,35.0,190.165726,false,Manual,22.0",
          GUID = "1B906D44",
          NextDialogue = 11010715,
          SpeakNpcId = 110022,
          Subtitle = "It's worth a try, but we can't risk having our medic do this alone.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D44"
        },
        [11010715] = {
          Camera = "-765.152344,-143.957031,167.94812,-0.001739,-7.41055,15.226987,35.0,100000.0,false,Manual,22.0",
          ContentFR = "À présent, nous ne sommes plus que deux en état de bouger. Les Souillés peuvent surgir d’un moment à l’autre. Vous devez rester pour protéger les blessés.",
          DialogueId = 11010715,
          Duration = 3,
          FinalCamera = "-794.794922,3.945312,167.952271,-0.001739,-7.41055,2.827789,35.0,100000.0,false,Manual,22.0",
          GUID = "1B906D6E",
          NextDialogue = 11010716,
          SpeakNpcId = 110005,
          Subtitle = "But now only the two of us can move or act... And the Filthoids might attack this place anytime. You should stay and keep the squad safe.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D6E"
        },
        [11010716] = {
          Camera = "-236.480469,-19.691406,150.981567,0.000378,-8.399657,44.019459,35.0,178.234528,false,Manual,22.0",
          ContentFR = "Je... je ne suis pas une éclaireuse de métier, mais j’ai appris quelques techniques, alors...",
          DialogueId = 11010716,
          Duration = 3,
          FinalCamera = "-229.025391,-12.492188,149.450317,0.000378,-8.399657,44.019459,35.0,178.234528,false,Manual,22.0",
          GUID = "1B906D98",
          NextDialogue = 11010717,
          SpeakNpcId = 110005,
          Subtitle = "I may not be a professional scout, but over time I've picked up some useful skills, so...",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D98"
        },
        [11010717] = {
          Camera = "-134.585938,137.484375,132.803467,0.00038,-2.599795,-102.382423,28.0,178.234528,false,Manual,22.0",
          ContentFR = "Très bien. Fais attention et avance prudemment. Si tu croises l’ennemi, évite tout affrontement direct.",
          DialogueId = 11010717,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-135.685547,132.480469,132.570435,0.00038,-2.599795,-102.382423,28.0,178.234528,false,Manual,22.0",
          GUID = "1B906DC2",
          NextDialogue = 11010718,
          SpeakNpcId = 110022,
          Subtitle = "...Alright, be careful down there. Make sure to sidestep any confrontation with the enemies.",
          TalkActionId = {
            [1] = "110005:Explain02_End",
            [2] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906DC2"
        },
        [11010718] = {
          Camera = "-229.025391,-12.492188,146.342163,0.000379,-7.399601,41.019707,35.0,178.234528,false,Manual,22.0",
          ContentFR = "Entendu. Je resterai en contact par radio, de votre côté continuez à tenter de joindre les autres. Si je ne donne plus signe de vie au bout d’une demi-heure... menez-les ailleurs.",
          DialogueId = 11010718,
          Duration = 3,
          GUID = "1B906DEC",
          NextDialogue = 11010719,
          SpeakNpcId = 110005,
          Subtitle = "Understood. I'll stay on the radio while you keep contacting the others. And if I lose contact for more than half an hour, please... lead the squad to find another way.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906DEC"
        },
        [11010719] = {
          Camera = "-216.220703,27.652344,122.164429,0.000382,5.200349,33.623096,35.0,178.234528,false,Manual,22.0",
          ContentFR = "N’aie pas peur, Daphne. Leur survie dépend de toi... n’aie pas peur.",
          DialogueId = 11010719,
          Duration = 3,
          FacialId = {
            [1] = "110005:Iyada01"
          },
          FinalCamera = "-208.587891,32.714844,122.998535,0.000381,5.200349,33.623184,35.0,178.234528,false,Manual,22.0",
          GUID = "1B906E16",
          SpeakNpcId = 110005,
          Subtitle = "Don't be scared, Daphne. Everyone's survival depends on you... Don't be scared.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906E16"
        },
