          SpeakNpcId = 110010,
          Subtitle = "Hang in there, kid!",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909DD4"
        },
        [11011011] = {
          ContentFR = "Commandant Avar !",
          DialogueId = 11011011,
          ExStoryInfo = "EXPlayer",
          GUID = "1B909DFE",
          NextDialogue = 11011012,
          SpeakNpcId = 110022,
          Subtitle = "Sir Avar!",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909DFE"
        },
        [11011012] = {
          ContentFR = "Hmm. Je suis là. Concentre-toi sur ce qui est devant toi, je couvre tes arrières.",
          DialogueId = 11011012,
          GUID = "1B909E28",
          SpeakNpcId = 110010,
          Subtitle = "Focus on the fight. I've got your six.",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E28"
        },
        [11011013] = {
          ContentFR = "Nous avons repoussé les Souillés et sécurisé un point de repli... mais il ne tiendra pas longtemps.",
          DialogueId = 11011013,
          ExStoryInfo = "EXPlayer",
          GUID = "1B909E52",
          NextDialogue = 11011014,
          SpeakNpcId = 110022,
          Subtitle = "We've repelled the Filthoids and set up a temporary shelter, but I don't think this place will hold.",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E52"
        },
        [11011014] = {
          ContentFR = "Daphne a prodigué les premiers soins, mais vu l’état des blessés, ils sont hors de combat pour le moment.",
