    Loader = function()
      return {
        [11011016] = {
          ContentFR = "Commandant Avar ! Ha... ha... vous êtes venu ! Je le savais... vous allez mener l’assaut... prendre cette maudite forteresse...",
          DialogueId = 11011016,
          GUID = "1B909ED0",
          NextDialogue = 11011017,
