        [11011411] = {
          Camera = "49.17527,197.511719,119.335083,0.000004,17.003107,-77.610802,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Je vais forcer la porte. {nickname2}, descends et aide-moi à couper l’alimentation. Il faut sortir Vic de là.",
          DialogueId = 11011411,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "28.606674,187.460938,128.160645,-2.0,1.602922,-90.009247,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B90DF75",
          NextDialogue = 11011412,
          Scripts = "PARA{\nPlayAnimation{ActorId{110010},AnimationId{\"Awa_Story_Operate_Start\"},Duration{2}},\nPlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/console\"},PlayAs2D{true}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "I'll take care of the door. , get down there, and help me shut down the device to save Vic.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90DF75"
        },
        [11011412] = {
          Camera = "-4.312927,-138.851562,142.460938,0.001032,1.402832,76.977753,30.000002,213.29274,false,Manual,11.73743",
          ContentFR = "Suis mes directives. Plus nous serons rapides, plus Vic aura de chances de survivre. Compris ?",
          DialogueId = 11011412,
          Duration = 3,
          GUID = "1B90DFC8",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          Scripts = "SEQ{PlayAnimation{ActorId{110010},AnimationId{\"Awa_Story_Operate_End\"},Duration{2}},\nTurnTo{TurnToDescription{\"110010:p(45)\"}},\nPlayAnimation{ActorId{110022},AnimationId{\"AgreeHead\"},Duration{1}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "Follow my lead. The quicker we are, the higher our chances of saving our comrade. Understood?",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90DFC8"
        },
        [11011413] = {
          ContentFR = "J’ai trouvé Vic... il n’y a plus que son corps.",
          DialogueId = 11011413,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90DFF2",
          NextDialogue = 11011414,
          SpeakNpcId = 110022,
          Subtitle = "I found Vic... Vic's body.",
