        },
        [11011415] = {
          ContentFR = "On continue.",
          DialogueId = 11011415,
          Duration = 3,
          GUID = "1B90E046",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 11011418,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Continue the mission.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E046"
        },
        [11011416] = {
          Content = "除了独立供能的中央控制室，整座要塞运转需要的月髓液都在这里。",
          DialogueId = 11011416,
          Duration = 3,
          GUID = "1B90E047",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 11011417,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Besides the independently powered central control room, this place stores all the Phoxichor that powers the whole fortress.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E047"
        },
        [11011417] = {
          Content = "破坏这里的动力装置，要塞中的大部分机关就会停止运转。",
          DialogueId = 11011417,
          Duration = 3,
          GUID = "1B90E048",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "If we destroy the power unit here, we'll disable most of the facilities in the fortress.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E048"
        },
        [11011418] = {
          ContentFR = "Ces systèmes doivent tomber... Vic ne doit pas mourir pour rien.",
          DialogueId = 11011418,
          Duration = 3,
          GUID = "1B90E0C4",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "We must shut down the systems... We can't let Vic die in vain.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E0C4"
        },
        [11011419] = {
          Content = "哦？已经处理好一个了吗，小心些，我好像听到秽兽靠过来的声音了。",
          DialogueId = 11011419,
          Duration = 3,
          GUID = "1B90E0EE",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E0EE"
        },
        [11011420] = {
          Content = "好，{nickname2}，动力链接已经断开了，我们得趁现在去把整个动力装置都毁了。",
          DialogueId = 11011420,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E118",
          NextDialogue = 11011421,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E118"
        },
        [11011421] = {
          Content = "核心的动力炉就在下面，小心些……",
          DialogueId = 11011421,
          Duration = 3,
          GUID = "1B90E142",
          NextDialogue = 11011422,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E142"
        },
        [11011422] = {
          Content = "有些脏东西围过来了……事办妥了再上来集合！",
          DialogueId = 11011422,
          Duration = 3,
          GUID = "1B90E16C",
          NextDialogue = 11011423,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E16C"
        },
        [11011423] = {
          Content = "好……",
          DialogueId = 11011423,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E196",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E196"
        },
        [11011424] = {
          Content = "我会逐个解锁防护屏障，等信号亮起，你就把月髓舱打碎！",
          DialogueId = 11011424,
          Duration = 3,
          GUID = "1B90E1C0",
          NextDialogue = 11011425,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "I'll disable the protective barriers one by one. When the signal light's on, smash the Phoxichor tank as fast as you can!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C0"
        },
        [11011425] = {
          Content = "有些月髓舱可能会配备自毁装置，如果听到倒计时响起，就终止行动，马上离开。",
          DialogueId = 11011425,
          Duration = 3,
          GUID = "1B90E1C1",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Some Phoxichor tanks may be equipped with self-destruct devices; if you hear a timer, evacuate immediately.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C1"
        },
        [11011426] = {
          Content = "就是现在，打碎它！",
          DialogueId = 11011426,
          Duration = 3,
          GUID = "1B90E1C2",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Now! Smash it!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C2"
        },
        [11011427] = {
          Content = "干得不错，我们还有两个要处理。",
          DialogueId = 11011427,
          Duration = 3,
          GUID = "1B90E1C3",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Excellent work. We got two more tanks to go.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C3"
        },
        [11011428] = {
          Content = "2号月髓舱的屏障解锁了，上吧！",
          DialogueId = 11011428,
          Duration = 3,
          GUID = "1B90E1C4",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "The 2nd one has been disabled. Now!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C4"
        },
        [11011429] = {
          Content = "呼……还有最后一个，你那儿还行吗？",
          DialogueId = 11011429,
          Duration = 3,
          GUID = "1B90E1C5",
          NextDialogue = 11011430,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Whew... One more left. You okay down there?",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C5"
        },
        [11011430] = {
          Content = "没问题。",
          DialogueId = 11011430,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E1C6",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 110022,
          Subtitle = "No problems here.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C6"
        },
        [11011432] = {
          Content = "好了，3号，最后一个！",
          DialogueId = 11011432,
          GUID = "1B90E2E7",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Alright, this is the last one!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E2E7"
        },
        [11011433] = {
          Content = "……自毁倒计时？",
          DialogueId = 11011433,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E2E8",
          NextDialogue = 11011434,
          SpeakNpcId = 110022,
          Subtitle = "...A self-destruct timer?",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E2E8"
        },
        [11011434] = {
          Content = "动力室要爆炸了，快走！",
          DialogueId = 11011434,
          GUID = "1B90E2E9",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "The engine room is about to explode. Evacuate now!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E2E9"
        },
        [11011501] = {
          Camera = "-3498.970215,-247.755859,536.716064,0.000177,-3.999144,9.997116,28.000006,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Excellent travail, {性别2:petit, tu es vraiment le meilleur de ta promotion|petite, tu es vraiment la meilleure de ta promotion}.",
          DialogueId = 11011501,
          Duration = 3,
          FinalCamera = "-3509.919434,-185.644531,536.716064,0.000178,-3.999144,9.9973,28.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90EE62",
          LookAt = {
            [1] = "110022:n(110010)",
            [2] = "110010:n(110022)"
          },
          NextDialogue = 11011502,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 408007,
            [6] = 101004
          },
          Scripts = "PARA{MoveTo{ActorId{110022},TargetPoint{\"fix0901\"},MoveSpeed{100},Visibility{true}},\nMoveTo{ActorId{110010},TargetPoint{\"fix0902\"},MoveSpeed{100},Visibility{true}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "Fantastic job, kid — you are indeed the best among your peers.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110022:n(110010)",
            [2] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EE62"
        },
        [11011502] = {
          Camera = "-965.651367,-347.652344,275.614258,0.000212,-8.998596,17.793779,28.000006,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 11011502,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-965.651367,-347.652344,253.155212,0.000212,-8.998596,17.793997,28.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90EE8C",
          NextDialogue = 11011503,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EE8C"
        },
        [11011503] = {
          ContentFR = "Parfait, la plupart des armes défensives de la forteresse sont hors service. Les autres escouades devraient s’en sortir un peu mieux.",
          DialogueId = 11011503,
          Duration = 3,
          GUID = "1B90EEB6",
          NextDialogue = 11011504,
          Scripts = "PARA{\nPlayAnimation{_delay{1},ActorId{110022},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{_delay{3},ActorId{110010},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "Okay, most of the defensive weapons within the fortress have been disabled. The rest of our squads should have an easier time.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EEB6"
        },
        [11011504] = {
          Camera = "25.622559,-213.152344,121.84137,0.000183,-0.799159,111.990997,28.000006,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu tiens le coup ? Si oui, on se bouge pour secourir les autres... Attends, nouveau contact.",
          DialogueId = 11011504,
          Duration = 3,
          GUID = "1B90EEE0",
          NextDialogue = 11011505,
          Scripts = "PARA{\nLookAt{_delay{5},LookAtDescription{\"110010:n(110010)\"}},\nPlayAnimation{_delay{6},ActorId{110010},AnimationId{\"Call_Start\"},Duration{0}},\nTurnTo{_delay{8},TurnToDescription{\"110010:p(-100)\"},AnimationId{\"Call_Rotation\"}},\nPlayAnimation{_delay{3},ActorId{110022},AnimationId{\"AgreeHead\"},Duration{0}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "So can you continue? Let's go if you can, we've got other comrades to rescue— Hold on, new communication coming in.",
          TalkActionId = {
            [1] = "110010:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EEE0"
        },
        [11011505] = {
          Camera = "-291.589355,80.037109,133.797607,0.000191,-3.399064,-26.402853,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 11011505,
          DialoguePanelType = "None",
          Duration = 3,
          GUID = "1B90EF0A",
          NextDialogue = 11011506,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/signal_on"},PlayAs2D{true}}",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EF0A"
        },
        [11011506] = {
          ContentFR = "Avar, où es-tu ?",
          DialogueId = 11011506,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B90EF34",
          NextDialogue = 11011507,
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Avar, where are you?",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EF34"
        },
        [11011507] = {
          Camera = "-206.013672,0.410156,134.678345,0.000218,-0.399088,4.196889,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 11011507,
          Duration = 3,
          FinalCamera = "-214.72998,-0.222656,134.739075,0.000218,-0.399088,4.196893,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90EF5E",
          NextDialogue = 11011508,
          SpeakNpcId = 110010,
          Subtitle = "...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EF5E"
        },
        [11011508] = {
          ContentFR = "Le temps en Hyperborea aujourd’hui.",
          DialogueId = 11011508,
          Duration = 3,
          GUID = "1B90EF88",
          NextDialogue = 11011509,
          SpeakNpcId = 110010,
          Subtitle = "The weather in Hyperborea today.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EF88"
        },
        [11011509] = {
          ContentFR = "Comment ? Même la voix du Commandant en Chef tu ne la reconnais plus ?",
          DialogueId = 11011509,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B90EFB2",
          NextDialogue = 11011510,
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What's your problem? Can't even recognise the chief commander's voice?",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EFB2"
        },
        [11011510] = {
          ContentFR = "Le temps.",
          DialogueId = 11011510,
          Duration = 3,
          GUID = "1B90EFDC",
          NextDialogue = 11011511,
          SpeakNpcId = 110010,
          Subtitle = "Weather.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EFDC"
        },
        [11011511] = {
          Camera = "-2040.53125,-6.380859,581.50824,0.000221,-14.198993,-1.000641,28.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il pleut ce soir. Pff... même les sculptures en marbre de la galerie ont plus de souplesse que ton esprit. Maintenant, fais le point sur ton escouade.",
          DialogueId = 11011511,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "-2039.224609,68.435547,581.508057,0.000221,-14.198993,-1.000641,28.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F006",
          NextDialogue = 11011512,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "It's raining tonight. Tsk, I've seen marble sculptures in the gallery with more flexibility than your mind. Now, report on your squad.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F006"
        },
        [11011512] = {
          ContentFR = "Grâce à votre "brillante" décision, les Loups Blancs et Griffons n’ont pas été complètement anéanties. Et vous, vous avez de nouvelles informations ?",
          DialogueId = 11011512,
          Duration = 3,
          GUID = "1B90F030",
          NextDialogue = 11011513,
          Scripts = "SEQ{\nCameraMoveTo{_delay{5},TargetPosition{\"-192.069824,-58.894531,124.695801,0.0,5.00006,44.395386,28.000006,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-189.639648,-61.367188,124.695801,0.0,5.00006,44.395386,28.000006,100000.0,false,DoNotOverride,2.8\"},duration{15}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "Thanks to your "brilliant" decision-making, the Snow Wolves and the Griffins haven't been completely annihilated yet. What, got any new insight?",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F030"
        },
        [11011513] = {
          Camera = "-488.78418,56.402344,85.289307,0.000219,2.801054,-12.005161,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Assez avec ton ton sarcastique. Tu devrais avoir honte de la tournure qu’a prise cette bataille.",
          DialogueId = 11011513,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FacialId = {
            [1] = "110022:Angry01"
          },
          FinalCamera = "-486.660645,66.390625,85.289307,0.000219,2.801054,-12.005161,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F05A",
          NextDialogue = 11011514,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Enough with your snide attitude. You should be ashamed of how this battle has turned out.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F05A"
        },
        [11011514] = {
          Camera = "-208.61084,-34.998047,124.695801,0.0,3.399972,25.594477,28.000006,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’aimerais bien, mais si vos mesures de sécurité et vos plans avaient été un minimum fiables, nos soldats fêteraient cette victoire dans la salle de commande centrale, au lieu de finir allongés sur des plaques de métal froid.",
          DialogueId = 11011514,
          Duration = 3,
          FinalCamera = "-200.800781,-31.255859,125.210022,0.000001,3.399972,25.59412,28.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F084",
          NextDialogue = 11011515,
          Scripts = "SEQ{\nCameraMoveTo{_delay{9},TargetPosition{\"-185.694336,-6.542969,120.360779,0.000021,-4.200409,-22.200596,28.000006,227.13504,false,Manual,5.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-187.672852,-11.392578,120.360779,0.000021,-4.200409,-22.200596,28.000008,230.463089,false,Manual,5.0\"},duration{8}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "I would like to achieve glory, sir. If you exercised proper secrecy and came up with a more credible plan, our soldiers would be popping champagne bottles in the central control room at this very moment instead of waiting for body bags.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F084"
        },
        [11011515] = {
          Camera = "29.431152,-206.160156,126.804016,0.000153,-2.399432,116.400375,30.000002,100000.0,false,DoNotOverride,7.0",
          ContentFR = "Avar Hrodland, je te préviens, surveille ton ton envers ton supérieur !",
          DialogueId = 11011515,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "32.746094,-204.517578,126.804016,0.000153,-2.399432,116.400375,30.000002,251.510284,false,Manual,7.0",
          GUID = "1B90F0AE",
          NextDialogue = 11011516,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Avar Hrodland, I'm warning you — Watch your tone when speaking to your superior!",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F0AE"
        },
        [11011516] = {
          Camera = "-208.043457,19.533203,102.896729,0.0,19.597855,-8.78466,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Antonius Fulvis, je te préviens aussi, arrête de jouer avec la vie de mes hommes.",
          DialogueId = 11011516,
          Duration = 3,
          FinalCamera = "-199.971191,18.289062,105.804749,0.0,19.597855,-8.78466,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F0D8",
          NextDialogue = 11011517,
          SpeakNpcId = 110010,
          Subtitle = "Antonius Fulvis, I'm also warning you — Stop wasting the lives of my comrades.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F0D8"
        },
        [11011517] = {
          Camera = "-563.553223,-958.021484,11.975342,0.000025,6.998976,54.007206,23.560806,1033.296143,false,Manual,1.2",
          ContentFR = "Je n’ai pas le temps pour ça maintenant. Où en est la mission ?",
          DialogueId = 11011517,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "-581.693359,-944.851562,11.975342,0.000025,6.998976,54.007206,23.560806,1046.946777,false,Manual,1.2",
          GUID = "1B90F102",
          NextDialogue = 11011518,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "I have no time for this right now. I am here to demand a progress update on the mission.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F102"
        },
        [11011518] = {
          ContentFR = "Les deux escouades ont été prises en embuscade, pertes lourdes. Je vais d’abord chercher les soldats disparus, nous regrouper dans la zone de traitement, en attendant votre soutien.",
          DialogueId = 11011518,
          Duration = 3,
          GUID = "1B90F12C",
          NextDialogue = 11011519,
          SpeakNpcId = 110010,
          Subtitle = "The two squads have been ambushed and suffered heavy losses. I'm preparing to search and rescue the missing soldiers first, then regroup in the processing area, waiting for your support.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F12C"
        },
        [11011519] = {
          Camera = "-270.909668,32.457031,122.689575,0.000147,-2.000118,-13.794167,19.449591,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Votre mission consiste en un assaut d’infiltration rapide. Pas question de vous arrêter à votre guise.",
          DialogueId = 11011519,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "-269.342773,38.851562,122.689575,0.000147,-2.000118,-13.794167,19.449591,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F156",
          NextDialogue = 11011520,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Your mission is a rapid infiltration assault. No field officer of mine is permitted to make their own bloody choices.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F156"
        },
        [11011520] = {
          Camera = "29.431152,-206.160156,126.804016,0.000153,-2.399432,116.400375,30.000002,251.282959,false,Manual,7.0",
          ContentFR = "Dévier du plan alertera toute la forteresse. Je vous ordonne de suivre la trajectoire prévue et d’attaquer directement la salle de commande centrale.",
          DialogueId = 11011520,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "29.431152,-206.160156,126.804016,0.000153,-2.399432,116.400436,30.000002,100000.0,false,Manual,7.0",
          GUID = "1B90F180",
          NextDialogue = 11011521,
          Scripts = "SEQ{\nCameraMoveTo{_delay{6},TargetPosition{\"-210.144531,17.427734,117.606079,0.000155,-1.599268,-27.397795,35.0,262.759705,false,Manual,10.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-179.064941,1.080078,116.625427,0.000155,-1.599268,-29.197746,35.000008,228.661591,false,Manual,10.0\"},duration{8}}\n}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Straying off the planned course of action will only alert the entire fortress. I order you to stick to the plan and launch a direct assault on the central control room.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F180"
        },
        [11011521] = {
          Camera = "-283.299316,-15.771484,105.371338,0.000157,8.200632,8.003107,35.0,100000.0,false,DoNotOverride,10.0",
          ContentFR = "Tu te rends compte de ce que tu dis ? Les ennemis sont déjà en embuscade, ils attendent pour nous exterminer ! On a perdu plus de quatre-vingts pour cent de nos hommes ! Ça ne te suffit pas ?",
          DialogueId = 11011521,
          FinalCamera = "-274.317871,-14.511719,106.678589,0.000157,8.200632,8.003121,35.0,100000.0,false,DoNotOverride,10.0",
          GUID = "1B90F1AA",
          NextDialogue = 11011522,
          Scripts = "SEQ{\nCameraMoveTo{_delay{2},TargetPosition{\"-186.463867,18.255859,110.615173,0.000163,22.600508,-5.198188,35.000008,62.163586,false,Manual,10.0\"},duration{0}},\nSEQ{\nCameraMoveTo{_delay{6.5},TargetPosition{\"-2030.179199,-717.564453,858.498047,0.000213,-19.7997,18.80571,30.0,62.163586,false,DoNotOverride,10.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-2227.331543,-784.722656,933.480164,0.000214,-19.7997,18.805719,30.0,62.163586,false,DoNotOverride,10.0\"},duration{0.1}}\n}\n}",
          SpeakNpcId = 110010,
          Subtitle = "Are you even listening to yourself? Alert the fortress? They're already in ambush positions, waiting to wipe us all out! We've sustained eighty percent casualties — eight zero! Isn't that enough for you!?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F1AA"
        },
        [11011522] = {
          Camera = "-2227.331543,-784.722656,933.480164,0.000214,-19.7997,18.805719,30.0,62.163586,false,DoNotOverride,10.0",
          ContentFR = "Des pertes ? Oublie tes fichues pertes. Tout ce que je sais, c’est que vous avez pris un retard considérable !",
          DialogueId = 11011522,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B90F1D4",
          NextDialogue = 11011523,
          Scripts = "SEQ{\nCameraMoveTo{_delay{5},TargetPosition{\"-127.570801,-135.820312,123.863464,0.000167,-1.599453,2.200026,35.0,62.163586,false,DoNotOverride,10.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-127.746582,-131.263672,123.863464,0.000167,-1.599453,2.200026,35.0,62.163586,false,DoNotOverride,10.0\"},duration{8}}\n}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Casualties? Forget about your bloody casualties. All I know is that you're significantly behind schedule!",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F1D4"
        },
        [11011523] = {
          Camera = "12.281738,-219.625,91.564148,0.000186,6.800532,103.001862,15.0,62.163586,false,DoNotOverride,10.0",
          ContentFR = "Tu as déshonoré la bannière de la Légion, les soldats hyperboréens ne sont pas des lâches qui s’arrêteraient à cause de pertes insignifiantes comme celles-ci !",
          DialogueId = 11011523,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "2.466797,-221.894531,91.564148,0.000186,6.800532,103.001961,15.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F1FE",
          NextDialogue = 11011524,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "You've brought shame to the legion's banner — the soldiers of Hyperborea are not cowards who would stop because of trivial losses like this!",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F1FE"
        },
        [11011524] = {
          Camera = "-3204.455566,-1025.527344,215.10437,0.000155,-0.199339,5.802845,30.0,62.163586,false,DoNotOverride,10.0",
          ContentFR = "De l’Empereur Dis Ier jusqu’au Commandant de Légion Quintus, architecte de l’offensive de l’Élégie Divine, aucun commandant d’Hyperborea n’a jamais reculé devant les pertes.",
          DialogueId = 11011524,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "-3217.544434,-896.724609,215.104126,0.000155,-0.199339,5.802853,30.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F228",
          NextDialogue = 11011525,
          RelatedWikiId = {
            [1] = 201021
          },
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "From Emperor Dis I to Legion Chief Quintus, the mastermind of the Divine Elegy offensive, no Hyperborean commander ever baulked at taking losses.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F228"
        },
        [11011525] = {
          Camera = "-199.996582,27.865234,134.139771,-2.0,-2.199765,-22.991972,28.0,62.163586,false,DoNotOverride,10.0",
          ContentFR = "Je t’ai confié l’élite de la XIIIe Légion. Tu devrais avoir largement assez de ressources pour prendre cette forteresse insignifiante.",
          DialogueId = 11011525,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "-201.352539,24.6875,134.018982,-2.0,-2.199765,-22.991972,28.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F252",
          NextDialogue = 11011526,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "I gave you the elites of the 13th Legion. You should have more than enough resources to take this puny fort.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F252"
        },
        [11011526] = {
          Camera = "-201.352539,24.6875,134.018982,-2.0,-2.199765,-22.991972,28.0,62.163586,false,DoNotOverride,10.0",
          ContentFR = "...",
          DialogueId = 11011526,
          GUID = "1B90F27C",
          NextOptions = {
            [1] = 11011527,
            [2] = 11011529,
            [3] = 11011533
          },
          SpeakNpcId = 110010,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F27C"
        },
        [11011527] = {
          ContentFR = "Rester silencieux",
          DialogueId = 11011527,
          GUID = "1B90F2A6",
          ImprPlusId = 1006,
          NextDialogue = 11011528,
          Subtitle = "(Stay silent)"
        },
        [11011528] = {
          ContentFR = "On peut continuer la mission, mais il nous faut un soutien supplémentaire.",
          DialogueId = 11011528,
          Duration = 3,
          GUID = "1B90F2D0",
          NextDialogue = 11011535,
          SpeakNpcId = 110010,
          Subtitle = "We can continue the mission, but only with additional support.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F2D0"
        },
        [11011529] = {
          ContentFR = "Si nous avons assez de soutien, on a une chance de victoire. Une victoire en votre nom, Commandant.",
          DialogueId = 11011529,
          GUID = "1B90F2FA",
          ImprPlusId = 1008,
          NextDialogue = 11011530,
          Subtitle = "Receiving enough support gives us a better chance of victory. A victory in your name, sir."
        },
        [11011530] = {
          Camera = "-120.756348,-24.742188,128.990662,-2.0,-4.799799,-34.392021,28.0,62.163586,false,DoNotOverride,10.0",
          ContentFR = "Commandant Fulvis, si nous tombons tous ici, vos talents tactiques ne suffiront pas à prendre cette forteresse. Vous devrez en répondre.",
          DialogueId = 11011530,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-111.863281,-36.107422,127.6828,-2.0,-4.799799,-34.392021,28.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F324",
          NextDialogue = 11011531,
          Scripts = "SEQ{\nCameraMoveTo{_delay{7},TargetPosition{\"-49.350586,-85.533203,128.152405,-1.999999,-4.399707,-32.791218,28.000006,62.163586,false,DoNotOverride,10.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-43.35791,-89.382812,127.603882,-1.999999,-4.399707,-32.791218,28.000006,62.163586,false,DoNotOverride,10.0\"},duration{15}}\n}",
          SpeakNpcId = 110022,
          Subtitle = "Commander Fulvis, if we all fall here, your tactical acumen alone won't stand a chance to take this fortress. And you'll surely have to answer for such a failure.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F324"
        },
        [11011531] = {
          ContentFR = "Nous sommes vos soldats qui combattons pour la gloire de l’Empire, pas vos ennemis.",
          DialogueId = 11011531,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90F34E",
          NextDialogue = 11011532,
          SpeakNpcId = 110022,
          Subtitle = "We are your soldiers who fight for the glory of the Empire, not your enemies.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F34E"
        },
        [11011532] = {
          Camera = "-885.801758,-247.560547,331.117859,-2.0,-16.999998,14.005773,28.0,261.438629,false,DoNotOverride,3.0",
          ContentFR = "Et qui est-ce ? Oh, c’est toi, {nickname2}, {性别2:le protégé préféré|la protégée préférée} d’Avar et Capitaine des Griffons ?",
          DialogueId = 11011532,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-782.422363,-221.78125,310.503784,-2.0,-16.999992,14.006827,28.0,261.438629,false,DoNotOverride,3.0",
          GUID = "1B90F378",
          NextDialogue = 11011535,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "And who is this? Oh, it's you, , Avar's favourite protege and the Captain of the Griffins, I presume?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F378"
        },
        [11011533] = {
          ContentFR = "Si vous êtes si courageux, pourquoi ne pas venir vous-même au front ?",
          DialogueId = 11011533,
          GUID = "1B90F379",
          ImprPlusId = 1010,
          NextDialogue = 11011534,
          Subtitle = "Since you're so full of courage, why don't you come to the front yourself?"
        },
        [11011534] = {
          Camera = "-885.801758,-247.560547,331.117859,-2.0,-16.999998,14.005773,28.0,261.438629,false,DoNotOverride,3.0",
          ContentFR = "Et qui est-ce ? Oh, c’est toi, {nickname2}, {性别2:le protégé préféré|la protégée préférée} d’Avar et Capitaine des Griffons ?",
          DialogueId = 11011534,
