          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "La tourelle 4 ? Capitaine, vous êtes {性别2:sûr|sûre} ? Avec toutes ces hordes de Souillés en chemin... à si peu, on n’y arrivera jamais.",
          DialogueId = 11011811,
          FinalCamera = "-571.740234,443.087891,124.264893,0.000065,-3.199527,-67.400917,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91213E",
          LookAt = {
            [1] = "110022:n(110043)"
          },
          NextDialogue = 11011812,
          Scripts = "SEQ{\nLookAt{_delay{0.7},LookAtDescription{\"110043:n(110016)\"}},\nLookAt{_delay{0.7},LookAtDescription{\"110043:n(110022)\"}}\n}",
          SpeakNpcId = 110043,
          Subtitle = "Turret 4? Are you sure about that, Captain? That's pretty far, and god knows how many Filthoids there are along the way. There aren't many of us... Can we make it?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91213E"
        },
        [11011812] = {
