        },
        [11011820] = {
          Camera = "-159.664062,-158.019531,125.479492,0.000141,0.999134,-63.800842,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Si le sacrifice d’un Charon peut apaiser votre colère, prenez la mienne. Mais laissez-moi vous expliquer...",
          DialogueId = 11011820,
          FinalCamera = "-149.302734,-179.078125,125.887695,0.000141,0.999134,-63.800903,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B9122B8",
          NextDialogue = 11011821,
          Scripts = "SetLocation{ActorId{110043},TargetPoint{"fix1101"},Visibility{"Show"}}",
          SpeakNpcId = 110034,
          SpeakNpcName = "UI_Npc_KarongGirl",
          Subtitle = "If sacrificing one Charon can quell your anger, then take me. But first, please, let me explain...",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/110118/1B9122B8"
        },
        [11011821] = {
          Camera = "-591.692383,40.896484,136.615845,0.000137,-4.400848,-20.596607,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Katya, non !",
          DialogueId = 11011821,
          FinalCamera = "-591.692383,40.896484,136.615845,0.000137,-4.600863,-17.99663,35.000011,100000.0,false,DoNotOverride,2.8",
