        },
        [11011839] = {
          Camera = "-331.882812,3.074219,121.966187,0.000118,-1.199463,-90.33371,35.000019,244.838531,false,Manual,2.8",
          ContentFR = "Vieil homme, puisque vous connaissez bien les égouts, montrez-nous le chemin.",
          DialogueId = 11011839,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9125D6",
          LookAt = {
            [1] = "110017:n(110022)"
          },
          NextDialogue = 11011840,
          Scripts = "PlayAnimation{_delay{6},ActorId{110017},AnimationId{"Agree"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "I've heard you're familiar with these sewers. Please lead the way then.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9125D6"
        },
        [11011840] = {
          Camera = "410.171875,-492.808594,467.956604,0.000058,-23.799349,145.841736,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Restez vigilants et surveillez-les de près. Au moindre geste suspect, repli immédiat.",
          DialogueId = 11011840,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "644.256836,-651.65625,592.720764,0.000058,-23.799349,145.841736,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912600",
          SpeakNpcId = 110022,
          Subtitle = "Stay alert and keep a close watch on them. If anything seems amiss, we pull out immediately.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912600"
        },
        [11011841] = {
          ContentFR = "Tenez-vous tranquille ! {性别2:Le|La} capitaine a dit pas de mouvements brusques, compris ?",
          DialogueId = 11011841,
          Duration = 3,
          GUID = "1B91262A",
          NextDialogue = 11011842,
          SpeakNpcId = 110015,
          Subtitle = "Behave! Captain's orders — no sudden moves or funny business, alright?"
        },
        [11011842] = {
          ContentFR = "Mais si je ne bouge pas… comment pourrais-je vous guider ?",
          DialogueId = 11011842,
          Duration = 3,
          GUID = "1B912654",
          NextDialogue = 11011843,
          SpeakNpcId = 110034,
          Subtitle = "But if I'm not allowed to move, how am I supposed to lead the way...?"
        },
        [11011843] = {
          ContentFR = "Ah oui, c’est vrai.",
          DialogueId = 11011843,
          Duration = 3,
          GUID = "1B91267E",
          NextDialogue = 11011844,
          SpeakNpcId = 110015,
          Subtitle = "Right, you have a point there."
        },
        [11011844] = {
          ContentFR = "Vous n’avez pas besoin d’être ainsi sur vos gardes. Nous, les Charons, sommes aussi des gens ordinaires, avec des familles que nous avons hâte de revoir.",
          DialogueId = 11011844,
          Duration = 3,
          GUID = "1B9126A8",
          NextDialogue = 11011845,
          SpeakNpcId = 110034,
          Subtitle = "There's no need to so on guard. We Charons are ordinary people too, with families we're desperate to see again."
        },
        [11011845] = {
          ContentFR = "Soupir... Katya...",
          DialogueId = 11011845,
          GUID = "1B9126D2",
          NextDialogue = 11011846,
          SpeakNpcId = 110017,
          Subtitle = "...*sigh* Katya..."
        },
        [11011846] = {
          ContentFR = "... Capitaine, pourquoi m’avez-vous arrêté !?",
          DialogueId = 11011846,
          GUID = "1B9126FC",
          NextDialogue = 11011847,
          SpeakNpcId = 110016,
          Subtitle = "...Captain, why did you stop me!?"
        },
        [11011847] = {
          ContentFR = "Tous les Charons ne sont pas des Déchus, rappelle-toi, le Commandant Avar est un Charon. Même s’ils étaient des Déchus, ils ont plus de valeur vivants que morts. ",
          DialogueId = 11011847,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912726",
          NextDialogue = 11011848,
          SpeakNpcId = 110022,
          Subtitle = "Not all Charons are rebels from The Forsakens — Commander Avar is a Charon, remember? And even if they are, they'd be worth more to us alive."
        },
        [11011848] = {
          ContentFR = "... Une petite voix intérieure te dit peut-être le contraire, Marco, mais ne l’écoute pas. Ne laisse pas tes émotions obscurcir ton jugement.",
          DialogueId = 11011848,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912750",
          SpeakNpcId = 110022,
          Subtitle = "...An inner voice might tell you otherwise, Marco, but don't listen to it. Don't let emotions cloud your judgment."
        },
        [11011849] = {
          Camera = "-206.832031,-274.033203,151.986694,0.000304,-7.786074,84.022697,30.000002,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... Merci.",
          DialogueId = 11011849,
          Duration = 1,
          GUID = "1B91277A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11011850,
          SpeakNpcId = 110034,
          Subtitle = "Thank you...",
          VoiceName = "voice/$Locale$/story/1002/110118/1B91277A"
        },
        [11011850] = {
          Camera = "316.260742,671.15625,590.656799,0.000295,-32.38599,-125.777397,30.000002,100000.0,false,DoNotOverride,22.0",
          ContentFR = "C’est à moi que tu parles ?",
          DialogueId = 11011850,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "248.001953,576.443359,518.394348,0.000295,-32.38599,-125.777397,30.000002,100000.0,false,DoNotOverride,22.0",
          GUID = "1B9127A4",
          NextDialogue = 11011851,
          SpeakNpcId = 110022,
          Subtitle = "You're talking to me?",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110022:p(-150)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127A4"
        },
        [11011851] = {
          Camera = "-178.519531,165.578125,130.494019,0.000272,-1.986786,-88.369873,35.000011,223.924484,false,Manual,4.0",
          ContentFR = "Oui. Vous ne m’avez pas humiliée en me fouillant devant tout le monde, et je vous en suis très reconnaissante. Il est rare {性别2:qu’un officier impérial|qu’une officière impériale} respecte la dignité d'une Charon comme moi.",
          DialogueId = 11011851,
          GUID = "1B9127CE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011852,
          SpeakNpcId = 110034,
          Subtitle = "Yes. You didn't let your man frisk me, and I really appreciate it — it's rare to see an Imperial officer respect the dignity of a Charon girl like me.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127CE"
        },
        [11011852] = {
          Camera = "-164.408203,79.375,128.996338,0.000276,-0.386739,-87.568512,39.0,140.506577,false,Manual,4.0",
          ContentFR = "Votre bonté ne sera pas oubliée.",
          DialogueId = 11011852,
          GUID = "1B9127F8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Your kindness will reap a just reward.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127F8"
        },
        [11011901] = {
          Camera = "-144.767578,-92.228821,263.461792,0.000099,-22.001951,-14.432684,35.000023,62.085716,false,DoNotOverride,10.0",
          ContentFR = "... Quoi ? Les renforts ont du retard ?",
          DialogueId = 11011901,
          Duration = 3,
          FinalCamera = "-215.302734,-74.076721,286.28595,0.0001,-22.001951,-14.432749,35.000023,62.085716,false,DoNotOverride,10.0",
          GUID = "1B913002",
          NextDialogue = 11011902,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201015,
            [6] = 408007
          },
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/signal_on"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "...What did you say!? The reinforcements are delayed!?",
          TalkActionId = {
            [1] = "110010:Call_Loop"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110119/1B913002"
        },
        [11011902] = {
          Camera = "224.40625,-305.362305,41.080444,-19.999933,31.393705,120.334618,18.0,215.299194,false,Manual,15.0",
          ContentFR = "Les Narvals ont été retardés par quelques manœuvres des Déchus sur le pont. On est coincés ici.",
          DialogueId = 11011902,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "243.134766,-256.964966,50.642212,-19.999929,34.393909,140.333755,18.0,215.299194,false,Manual,15.0",
          GUID = "1B91302C",
          NextDialogue = 11011903,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "The Forsakens sabotaged the Narwhals at the bridge. Now we're stuck here.",
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91302C"
        },
        [11011903] = {
          ContentFR = "Tu veux que j’attaque la salle de commande centrale avec ces quelques rescapés ? Fulvis, tu rêves ! Là-dedans, il y a les <H>Messagers</> des <H>Brumaires</> !",
          DialogueId = 11011903,
          Duration = 3,
          GUID = "1B913056",
          NextDialogue = 11011904,
          RelatedWikiId = {
            [1] = 101004
          },
          Scripts = "SEQ{\nCameraMoveTo{_delay{6.5},TargetPosition{\"252.482422,-28.591492,307.02533,0.000023,-41.604187,-127.463921,30.0,257.429108,false,DoNotOverride,15.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"274.126953,-47.164124,307.02533,0.000027,-41.60405,-137.662704,30.0,257.429108,false,DoNotOverride,15.0\"},duration{12}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "You expect me to break into the central control room with just two battered squads and directly confront their Messenger? You can't be serious, Fulvis. The enemies are Daimons, and god knows how many more ambushes lie ahead!",
          VoiceName = "voice/$Locale$/story/1002/110119/1B913056"
        },
        [11011904] = {
          Camera = "193.941406,-262.665161,172.085999,0.000077,-6.004569,117.326279,35.0,77.099098,false,Manual,15.0",
          ContentFR = "Messagers ou je ne sais quoi, la Légion ne vous nourrit pas par bonté, vous êtes faits pour ces moments-là. Et puis vous n’êtes pas seul, {nickname2} est avec vous, aussi fort qu’un Daimon.",
          DialogueId = 11011904,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "190.306641,-252.121216,171.00824,0.000077,-6.004569,117.326279,35.0,77.099098,false,Manual,15.0",
          GUID = "1B913080",
          NextDialogue = 11011905,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "So what if they are Daimons? You're one too! Besides, don't you have  on your side, who's as strong as any Daimon?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110119/1B913080"
        },
        [11011905] = {
          Camera = "-76.609375,-108.222046,132.998901,0.000015,1.195543,0.126938,12.0,77.099098,false,Manual,15.0",
          ContentFR = "La salle de commande centrale est juste devant. Moins de cinquante mètres depuis la tourelle 4 où vous êtes.",
          DialogueId = 11011905,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FacialId = {
            [1] = "110010:Angry01"
          },
          FinalCamera = "-44.5625,-111.956238,132.312683,0.000015,1.195543,0.126938,12.0,77.099098,false,Manual,15.0",
          GUID = "1B9130AA",
          NextDialogue = 11011906,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "The central control room is just right ahead. It's less than fifty yards away from the Turret you're at.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9130AA"
        },
        [11011906] = {
          Camera = "257.480469,-189.943848,143.340332,-0.0,8.794633,169.723068,40.0,77.099098,false,Manual,15.0",
          ContentFR = "Encore cinquante mètres et nous pourrons offrir la victoire à Sa Majesté ! Ce n’est pas compliqué, non ?",
          DialogueId = 11011906,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "245.064453,-188.491089,146.559082,-0.0,8.794633,169.723068,40.0,77.099098,false,Manual,15.0",
          GUID = "1B9130D4",
          NextDialogue = 11011907,
          Scripts = "PlayNormalSound{_delay{8},EventPath{"event:/sfx/common/story/ex01/signal_off"},PlayAs2D{true}}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Fifty yards further, and we can dedicate the victory to His Majesty! What's so hard about that?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9130D4"
        },
        [11011907] = {
          Camera = "245.064453,-188.491089,146.559082,-0.0,8.794633,169.723068,40.0,77.099098,false,Manual,15.0",
          ContentFR = "...",
          DialogueId = 11011907,
          Duration = 1,
          FacialId = {
            [1] = "110010:None"
          },
          GUID = "1B9130FE",
          LookAt = {
            [1] = "110022:n(110022)"
          },
          NextDialogue = 11011908,
          Scripts = "SEQ{\nPlayAnimation{ActorId{110010},AnimationId{\"Call_End\"},Duration{1}},\nTurnTo{_delay{1},TurnToDescription{\"110010:p(170)\"}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9130FE"
        },
        [11011908] = {
          Camera = "-69.640625,-56.848694,130.207397,-1.0,1.597315,-43.641903,18.000004,100000.0,false,DoNotOverride,20.0",
          ContentFR = "{nickname2} ? Tout se passe bien de ton côté ?",
          DialogueId = 11011908,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-103.9375,-27.777588,128.908508,-1.0,1.597315,-43.44199,18.000004,100000.0,false,DoNotOverride,20.0",
          GUID = "1B913128",
          LookAt = {
            [1] = "110010:p(BP_EX01FixSimple12P)"
          },
          NextDialogue = 11011909,
          Scripts = "PlayAnimation{_delay{1},ActorId{110010},AnimationId{"Talk01_Start"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "? How are things going on your side?",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110119/1B913128"
        },
        [11011909] = {
          Camera = "-13.794922,-59.895142,111.804016,0.000078,20.79701,-163.038177,22.0,100000.0,false,DoNotOverride,5.0",
          ContentFR = "Simon s’est sacrifié. Grâce à lui, j’ai réussi à sauver les autres.",
          DialogueId = 11011909,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B913152",
          NextDialogue = 11011910,
          SpeakNpcId = 110022,
          Subtitle = "Simon sacrificed himself. Thanks to him, I managed to save the rest.",
          TalkActionId = {
            [1] = "110010:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110119/1B913152"
        },
        [11011910] = {
          Camera = "-13.794922,-59.895142,111.804016,0.000078,20.79701,-163.038177,22.0,100000.0,false,DoNotOverride,5.0",
          ContentFR = "On a aussi rencontré quelques réfugiés Charons capturés par les Déchus. Ce sont eux qui nous ont conduits jusqu’ici.",
          DialogueId = 11011910,
          Duration = 8,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-4.126953,-57.571289,122.111938,0.000078,2.796942,-148.23848,22.000011,424.359375,false,DoNotOverride,5.0",
          GUID = "1B91317C",
          NextDialogue = 11011911,
          SpeakNpcId = 110022,
          Subtitle = "We also met a few Charon refugees enslaved by The Forsakens. They led us here.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91317C"
        },
        [11011911] = {
          Camera = "-161.328125,-202.881226,167.300476,0.000099,-11.803092,-148.037811,40.0,424.358032,false,DoNotOverride,5.0",
          ContentFR = "Des réfugiés ? J’espère qu’ils ne sont pas des Déchus déguisés.",
          DialogueId = 11011911,
          Duration = 3,
          FinalCamera = "-156.371094,-210.830078,167.300476,0.000099,-11.803092,-148.037811,40.0,424.358032,false,DoNotOverride,5.0",
          GUID = "1B9131A6",
          NextDialogue = 11011912,
          SpeakNpcId = 110010,
          Subtitle = "Refugees? Not Forsakens rebels in disguise, I hope.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9131A6"
        },
        [11011912] = {
          Camera = "1204.801758,464.393738,813.957642,0.000043,-27.002495,-153.843018,40.0,100000.0,false,Manual,5.0",
          ContentFR = "C’est pour ça que j’ai demandé aux soldats de les surveiller. S’ils sont civils, ils sont plus en sécurité avec nous. S’ils sont des Déchus, on les ramènera vivants pour interrogatoire à la capitale.",
          DialogueId = 11011912,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "1220.620117,432.180267,813.957642,0.000043,-27.002495,-153.843018,40.0,100000.0,false,Manual,5.0",
          GUID = "1B9131D0",
          NextDialogue = 11011913,
          SpeakNpcId = 110022,
          Subtitle = "That's why I asked the soldiers to keep an eye on them. If they are indeed civilians, they'd be safer with us. If they turn out to be from the Forsakens, we'll detain them and bring them back to the capital.",
          TalkActionId = {
            [1] = "110022:Talk02_End",
            [2] = "110010:Talk03_Start"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9131D0"
        },
        [11011913] = {
          Camera = "87.085938,-80.530945,111.064758,-2.000001,24.197323,-65.246292,25.000002,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Si ce sont des ennemis, leur présence freinera les Déchus embusqués, ils réfléchiront à deux fois avant d’attaquer pour ne pas mettre leurs camarades en danger. Bien pensé.",
          DialogueId = 11011913,
          Duration = 3,
          FinalCamera = "91.947266,-92.697449,116.917236,-2.000001,24.197323,-65.246323,25.000002,100000.0,false,DoNotOverride,22.0",
          GUID = "1B9131FA",
          NextDialogue = 11011914,
          SpeakNpcId = 110010,
          Subtitle = "In that case, the ambushing Forsakens may think twice about attacking for fear of harming their fellows. Mm, you made a smart decision.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9131FA"
        },
        [11011914] = {
          Camera = "-445.671875,693.834045,67.956787,-1.0,3.597447,-59.841167,35.0,100000.0,false,Manual,5.0",
          ContentFR = "De notre côté... Nos renforts ont rencontré un problème en chemin et ne peuvent pas venir... Et nous avons reçu l’ordre de poursuivre la mission.",
          DialogueId = 11011914,
          Duration = 3,
          FinalCamera = "-368.775391,561.49176,77.580078,-1.0,3.597447,-59.841167,35.0,100000.0,false,Manual,5.0",
          GUID = "1B913224",
          NextDialogue = 11011915,
          Scripts = "PlayAnimation{_delay{3},ActorId{110010},AnimationId{"Confident_Start"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "As for this side... Our reinforcements met a problem on the way here and can't make it... And we're ordered to continue the mission.",
          TalkActionId = {
            [1] = "110010:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110119/1B913224"
        },
        [11011915] = {
          ContentFR = "Bien reçu.",
          DialogueId = 11011915,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91324E",
          NextDialogue = 11011916,
          SpeakNpcId = 110022,
          Subtitle = "I heard.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110119/1B91324E"
        },
        [11011916] = {
          Camera = "-4.320312,-54.229919,156.435608,2.0,-15.402834,-158.041519,40.0,60.997154,false,Manual,12.0",
          ContentFR = "... Regarde le bon côté, on touche presque au but. Élimine tout obstacle, ouvre la salle de commande centrale, insère la clé, récupère les accès pour la console de commande, et c’est terminé. C’est tout ce qui nous sépare de chez nous.",
          DialogueId = 11011916,
          Duration = 3,
          FinalCamera = "-13.175781,-57.801208,153.804443,2.0,-15.402834,-158.041519,40.0,60.997154,false,Manual,12.0",
          GUID = "1B913278",
          NextDialogue = 11011936,
          Scripts = "SEQ{\nCameraMoveTo{_delay{6},TargetPosition{\"-46.275391,-86.162109,142.679993,-1.0,4.799451,-24.651934,45.0,129.592651,false,DoNotOverride,5.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-33.478516,-92.035095,143.405212,-1.0,4.799451,-24.651691,45.0,129.592651,false,DoNotOverride,5.0\"},duration{5}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "...Look on the bright side, the mission is almost done. Knock out everything that gets in the way, breach the central control room, insert the key, we reclaim access, and then mission accomplished. That's all that stands between us and home.",
          TalkActionId = {
            [1] = "110022:Talk03_End",
            [2] = "110010:Confident_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110119/1B913278"
        },
        [11011917] = {
          Camera = "-22.394531,-48.055237,156.619995,0.00007,-7.800322,-164.04863,35.0,100000.0,false,Manual,22.0",
          Content = "……所以当务之急是解决前面的屏障吧。用这门炮轰开如何？",
          DialogueId = 11011917,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-14.953125,-45.923645,157.682129,0.00007,-7.800322,-164.04863,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9132A2",
          NextDialogue = 11011918,
          SpeakNpcId = 110022,
          Subtitle = "...So the first thing to do now is disable the barrier up ahead, right? How does this cannon work?",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A2"
        },
        [11011918] = {
          Camera = "-4.816406,-6.338318,179.877502,0.000095,-1.000575,-45.047215,35.0,100000.0,false,Manual,22.0",
          Content = "这门炮作为底火的月髓刚好用光了，我正准备——",
          DialogueId = 11011918,
          Duration = 3,
          FinalCamera = "-21.675781,10.563416,180.294556,0.000095,-1.800533,-45.047245,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9132A3",
          NextDialogue = 11011919,
          SpeakNpcId = 110010,
          Subtitle = "The cannon just ran out of Phoxichor primers. I was about to—",
          TalkActionId = {
            [1] = "110022:Talk02_End",
            [2] = "110010:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A3"
        },
        [11011919] = {
          Camera = "-54.783203,111.192444,135.942932,0.000055,-2.400723,-155.452408,35.0,100000.0,false,Manual,22.0",
          Content = "小长官，小长官！",
          DialogueId = 11011919,
          Duration = 3,
          FinalCamera = "-70.373047,102.649536,128.868347,0.000056,-0.40057,-152.8535,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9132A4",
          LookAt = {
            [1] = "110022:n(110017)，110017:n(110022"
          },
          NextDialogue = 11011920,
          SpeakNpcId = 110017,
          Subtitle = "Sir! Sir!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110022:n(110017)，110017:n(110022"
          },
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A4"
        },
        [11011920] = {
          Content = "听起来那位长官好像需要月髓，我知道最近放月髓的仓库在哪里。我可以带您去。",
          DialogueId = 11011920,
          Duration = 3,
          GUID = "1B9132A5",
          NextDialogue = 11011921,
          SpeakNpcId = 110017,
          Subtitle = "It sounds like you need Phoxichor. I know where the nearest storage is. I can take you there.",
          TalkActionId = {
            [1] = "110017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A5"
        },
        [11011921] = {
          Camera = "-6.033203,-285.19043,132.766541,0.000062,-1.800199,143.14183,35.0,100000.0,false,Manual,22.0",
          Content = "……嗯……",
          DialogueId = 11011921,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-15.679688,-316.977051,130.002502,0.000064,-2.599884,137.739395,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9132A6",
          NextDialogue = 11011922,
          SpeakNpcId = 110022,
          Subtitle = "...Okay.",
          TalkActionId = {
            [1] = "110017:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A6"
        },
        [11011922] = {
          Content = "你跟我一起。",
          DialogueId = 11011922,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9132A7",
          LookAt = {
            [1] = "110022:n(110034)"
          },
          NextDialogue = 11011923,
          SpeakNpcId = 110022,
          Subtitle = "And you. Come with us.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A7"
        },
        [11011923] = {
          Camera = "-209.833984,-22.960693,135.643921,0.000057,-2.800658,-139.652802,35.0,100000.0,false,Manual,22.0",
          Content = "……已经带您平安抵达了这里，您还是不肯信任我吗。",
          DialogueId = 11011923,
          Duration = 3,
          FinalCamera = "-164.667969,15.409241,138.542725,0.000057,-2.800658,-139.652802,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9132A8",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11011924,
          SpeakNpcId = 110034,
          Subtitle = "...You still don't trust me? Even after I brought you here safely?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A8"
        },
        [11011924] = {
          Content = "抱歉，只是稍微有点……没事，我和您一起就是了。",
          DialogueId = 11011924,
          Duration = 3,
          GUID = "1B9132A9",
          SpeakNpcId = 110034,
          Subtitle = "...Fine, I'll go with you.",
          TalkActionId = {
            [1] = "110034:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132A9"
        },
        [11011925] = {
          Content = "就是这儿了，长官。",
          DialogueId = 11011925,
          Duration = 3,
          GUID = "1B9132AA",
          NextDialogue = 11011926,
          SpeakNpcId = 110017,
          Subtitle = "Here it is, sir.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132AA"
        },
        [11011926] = {
          Content = "长官，我来帮您拿着吧。没关系，我什么重活都干过，力气很大的。",
          DialogueId = 11011926,
          Duration = 3,
          GUID = "1B9132AB",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011927,
          SpeakNpcId = 110034,
          Subtitle = "Allow me to carry that for you, sir. I've done all kinds of heavy work and have great strength.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132AB"
        },
        [11011927] = {
          Content = "……呃，不用吗……",
          DialogueId = 11011927,
          Duration = 3,
          GUID = "1B9132AC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "...Er, sure you don't want my help...?",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9132AC"
        },
        [11011928] = {
          ContentFR = "Le Phoxichor est magnifique, limpide et scintillant.",
          DialogueId = 11011928,
          Duration = 3,
          GUID = "1B913470",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011929,
          SpeakNpcId = 110034,
          Subtitle = "The Phoxichor looks beautiful, all crystal and glistening.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B913470"
        },
        [11011929] = {
          ContentFR = "Si seulement ce n’était pas pour tuer des gens...",
          DialogueId = 11011929,
          Duration = 3,
          GUID = "1B91349A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011930,
          SpeakNpcId = 110034,
          Subtitle = "If only it weren't used for killing.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B91349A"
        },
        [11011930] = {
          ContentFR = "... Oui.",
          DialogueId = 11011930,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9134C4",
          SpeakNpcId = 110022,
          Subtitle = "...True.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C4"
        },
        [11011931] = {
          Content = "好，找齐了。",
          DialogueId = 11011931,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9134C5",
          NextDialogue = 11011932,
          SpeakNpcId = 110022,
          Subtitle = "That's all of them.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C5"
        },
        [11011932] = {
          Content = "长官，我们是不是很快就可以回家了？",
          DialogueId = 11011932,
          Duration = 3,
          GUID = "1B9134C6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011933,
          SpeakNpcId = 110034,
          Subtitle = "Sir, does that mean we're going home soon?",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C6"
        },
        [11011933] = {
          Content = "也许吧，但愿如此。",
          DialogueId = 11011933,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9134C7",
          NextDialogue = 11011934,
          SpeakNpcId = 110022,
          Subtitle = "I hope so.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C7"
        },
        [11011934] = {
          Content = "如果能活着回去，我想去服装店，买好多好多以前不舍得买的衣服。",
          DialogueId = 11011934,
          Duration = 3,
          GUID = "1B9134C8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011935,
          SpeakNpcId = 110034,
          Subtitle = "If I make it back alive, I'm going to a fashion boutique to buy all the dresses I've dreamed of.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C8"
        },
        [11011935] = {
          Content = "如果能有一双漂亮的袜子就更好了。",
          DialogueId = 11011935,
          Duration = 3,
          GUID = "1B9134C9",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "And it would be nice to have a pair of pretty stockings, too.",
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C9"
        },
        [11011936] = {
          Camera = "1265.860352,2012.351807,591.866943,-0.0,-10.39929,-120.446251,35.0,86.916473,false,DoNotOverride,2.2",
          ContentFR = "Le problème, c’est que la porte de la salle de commande centrale ne peut pas s’ouvrir de l’extérieur...",
          DialogueId = 11011936,
          Duration = 4,
          FinalCamera = "1315.114258,1983.400879,591.866943,-0.0,-10.39929,-120.446251,35.0,86.916473,false,DoNotOverride,2.2",
          GUID = "1B913279",
          NextDialogue = 11011937,
          SpeakNpcId = 110010,
          Subtitle = "The trouble is, though, we can't open the door to the central control room from the outside...",
          TalkActionId = {
            [1] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110119/1B913279"
        },
        [11011937] = {
          Camera = "262.451172,-426.251709,296.255249,0.000046,1.597902,-39.643715,35.0,100000.0,false,DoNotOverride,5.0",
          ContentFR = "Voilà pourquoi vous êtes en train de régler cette tourelle...",
          DialogueId = 11011937,
          Duration = 7,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "289.830078,-393.212524,296.255249,0.000046,1.597902,-39.643715,35.0,100000.0,false,DoNotOverride,5.0",
          GUID = "1B91327A",
          LookAt = {
            [1] = "110022:n(110010)"
          },
          NextDialogue = 11018402,
          SpeakNpcId = 110022,
          Subtitle = "That's why you're adjusting this cannon now...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91327A"
        },
        [11011939] = {
          Camera = "106.029297,82.120117,148.969055,0.000085,0.198506,-84.237144,35.000011,62.085716,false,DoNotOverride,10.0",
          ContentFR = "Commandant, on a trouvé des Bidons de Phoxichor dans un entrepôt proche, et les avons connectés aux dernières Roues Phoxynamo, comme vous l’avez demandé.",
          DialogueId = 11011939,
          FinalCamera = "108.123047,61.345215,149.04126,0.000085,0.198506,-84.237144,35.000011,62.085716,false,DoNotOverride,10.0",
          GUID = "1B91327C",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11011940,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110020,
          Subtitle = "Sir, we've found some Phoxichor Canisters at a nearby warehouse, and got them connected to the remaining Phoxynamo Wheels as you instructed.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91327C"
        },
        [11011940] = {
          Camera = "37.863281,-121.802368,173.759277,0.000092,-6.001612,-26.831324,35.000011,62.085716,false,DoNotOverride,10.0",
          ContentFR = "Parfait... ça devrait suffire pour amener la tourelle près de la salle de commande centrale.",
          DialogueId = 11011940,
          FinalCamera = "43.78125,-124.801086,173.06073,0.000092,-6.001612,-26.831289,35.000011,62.085716,false,DoNotOverride,10.0",
          GUID = "1B91327D",
          Scripts = "SEQ{\nPlayNormalSound{_delay{5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}},\nPlayAnimation{ActorId{110010},AnimationId{\"Call_End\"},Duration{0}}\n}\n",
          SpeakNpcId = 110010,
          Subtitle = "Excellent. That should be enough to move this cannon near the central control room.",
          TalkActionId = {
            [1] = "110010:AgreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91327D"
        },
        [11012001] = {
          ContentFR = "Bien joué. En avant ! Plaçons le canon au meilleur endroit pour bombarder la salle de commande centrale.",
          DialogueId = 11012001,
          Duration = 3,
          GUID = "1B91406A",
          SpeakNpcId = 110010,
          Subtitle = "Well done. Now let's move the cannon to an optimal spot to bombard the central control room.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B91406A"
        },
        [11012002] = {
          Content = "嗯，多亏了这两位难民的帮助。",
          DialogueId = 11012002,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B914094",
          SpeakNpcId = 110022,
          Subtitle = "Thanks to the help of these two refugees.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B914094"
        },
        [11012003] = {
          ContentFR = "Surveille le canon ! Ne les laisse pas l’endommager !",
          DialogueId = 11012003,
          Duration = 3,
          GUID = "1B9140BE",
          SpeakNpcId = 110010,
          Subtitle = "Keep the cannon from the Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B9140BE"
        },
        [11012004] = {
          Content = "我们找个轰击中心区屏障的最佳位置。你盯着点，别让秽兽把炮台弄坏了。",
          DialogueId = 11012004,
          Duration = 3,
          GUID = "1B9140E8",
          SpeakNpcId = 110010,
          Subtitle = "Let's find an optimal spot to bombard the barrier of the central area. Stay vigilant and protect the turret from the Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/110120/1B9140E8"
        },
        [11012005] = {
          Content = "当心秽兽！",
          DialogueId = 11012005,
          Duration = 3,
          GUID = "1B914112",
          SpeakNpcId = 110010,
          Subtitle = "Heads up! Filthoids approaching!",
          VoiceName = "voice/$Locale$/story/1002/110120/1B914112"
        },
        [11012006] = {
          Content = "又来了，保护炮台！",
          DialogueId = 11012006,
          Duration = 3,
          GUID = "1B91413C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 110010,
          Subtitle = "Another wave! Defend the turret!",
          VoiceName = "voice/$Locale$/story/1002/110120/1B91413C"
        },
        [11012101] = {
          Content = "这里视野不错，停下吧。",
          DialogueId = 11012101,
          Duration = 3,
          GUID = "1B9150D2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 11012102,
          SpeakNpcId = 110010,
          Subtitle = "We have a clear view from here. This is our stop.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9150D2"
        },
        [11012102] = {
          Content = "接下来，我们就用这门月髓炮轰击前面的屏障。",
          DialogueId = 11012102,
          Duration = 3,
          GUID = "1B9150FC",
          SpeakNpcId = 110010,
          Subtitle = "Next, we'll use the Phoxichor cannon to blow apart the barrier ahead.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9150FC"
        },
        [11012103] = {
          Content = "有秽兽被吸引过来了，直接开炮吧。",
          DialogueId = 11012103,
          Duration = 3,
          GUID = "1B915126",
          SpeakNpcId = 110010,
          Subtitle = "Some Filthoids picked up the scent. Just fire away.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B915126"
        },
        [11012104] = {
          Content = "好硬的屏障。",
          DialogueId = 11012104,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B915150",
          NextDialogue = 11012105,
          SpeakNpcId = 110022,
          Subtitle = "What a tough barrier...",
          VoiceName = "voice/$Locale$/story/1002/110121/1B915150"
        },
        [11012105] = {
          Content = "连月髓炮都能抗住，工程炼金院那帮人的技术还真是有两下子……",
          DialogueId = 11012105,
          Duration = 3,
          GUID = "1B91517A",
          NextDialogue = 11012106,
          SpeakNpcId = 110010,
          Subtitle = "Took a Phoxichor cannon shot with barely a dent. Those guys at the Aeolipile have some real skills...",
          VoiceName = "voice/$Locale$/story/1002/110121/1B91517A"
        },
        [11012106] = {
          Content = "不要停，继续轰击，记得换高爆弹。",
          DialogueId = 11012106,
          Duration = 3,
          GUID = "1B9151A4",
          NextDialogue = 11012107,
          SpeakNpcId = 110010,
          Subtitle = "Don't stop, keep firing! Use the high explosive shells!",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9151A4"
        },
        [11012107] = {
          Content = "就算轰不破这面屏障，我们也能让里面的家伙自己把门打开。",
          DialogueId = 11012107,
          Duration = 3,
          GUID = "1B9151CE",
          SpeakNpcId = 110010,
          Subtitle = "Even if we fail to tear down the barrier, continious fire can force the enemies from the inside to open the gate themselves.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9151CE"
        },
        [11012108] = {
          Content = "有什么人从侧边跑出来了——是同盟的家伙！",
          DialogueId = 11012108,
          Duration = 3,
          GUID = "1B9151F8",
          NextDialogue = 11012109,
          SpeakNpcId = 110015,
          Subtitle = "Someone's running out from the side gate — it's the Forsakens!",
          VoiceName = "voice/$Locale$/story/1002/110121/1B9151F8"
        },
        [11012109] = {
          Content = "差不多了，过去看看吧。",
          DialogueId = 11012109,
          Duration = 3,
          GUID = "1B915222",
          SpeakNpcId = 110010,
          Subtitle = "That should do it. Let's go check it out.",
          VoiceName = "voice/$Locale$/story/1002/110121/1B915222"
        },
        [11012110] = {
          Content = "喂，别玩儿了，快来这边！",
          DialogueId = 11012110,
          Duration = 3,
          GUID = "1B91524C",
          SpeakNpcId = 110010,
          Subtitle = "Hey, quit fooling around. Get over here!",
          VoiceName = "voice/$Locale$/story/1002/110121/1B91524C"
        },
        [11012201] = {
          Camera = "-507.54541,-397.79126,-135.757874,0.000019,-8.799681,31.148724,35.0,100000.0,false,Manual,22.0",
          Content = "他们真的自己打开了门……",
          DialogueId = 11012201,
          Duration = 3,
          FinalCamera = "-65.992188,-135.824219,-212.646179,0.000021,-7.799652,29.548767,35.0,100000.0,false,Manual,22.0",
          GUID = "1B91618C",
          NextDialogue = 11012202,
          SpeakNpcId = 110010,
          Subtitle = "They've actually opened the gate from the inside...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110122/1B91618C"
        },
        [11012202] = {
          Content = "留在里面受到的冲击更大，他们多半撑不住的。",
          DialogueId = 11012202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91618D",
          NextDialogue = 11012203,
          SpeakNpcId = 110022,
          Subtitle = "The blast impact was far stronger inside. They would've perished had they not opened it.",
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110122/1B91618D"
        },
        [11012203] = {
          ContentFR = "{nickname2} et moi passons devant. Les autres, suivez prudemment !",
          DialogueId = 11012203,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91618E",
          SpeakNpcId = 110010,
          Subtitle = "Captain  and I are taking the lead. Everyone else, fall in behind us!",
          VoiceName = "voice/$Locale$/story/1002/110122/1B91618E"
        },
        [11012301] = {
          Content = "蹲下干什么？怎么不走了？",
          DialogueId = 11012301,
          Duration = 3,
          GUID = "1B9171F4",
          IsBlack = 1,
          NextDialogue = 11012302,
          SpeakNpcId = 110015,
          Subtitle = "What's wrong? Why squatting down?",
          VoiceName = "voice/$Locale$/story/1002/110123/1B9171F4"
        },
        [11012302] = {
          ContentFR = "Katya ?",
          DialogueId = 11012302,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9171F5",
          IsBlack = 1,
          SpeakNpcId = 110022,
          Subtitle = "Katya?",
          VoiceName = "voice/$Locale$/story/1002/110123/1B9171F5"
        },
        [11012303] = {
          ContentFR = "{性别2:Mon cher capitaine|Ma chère capitaine}, patience... laissez-moi juste me préparer...",
          DialogueId = 11012303,
          Duration = 3,
          GUID = "1B9171F6",
          IsBlack = 1,
          NextDialogue = 11012304,
          SpeakNpcId = 110034,
          Subtitle = "Easy, sir. I'm just doing some preparation—",
          VoiceName = "voice/$Locale$/story/1002/110123/1B9171F6"
        },
        [11012304] = {
          ContentFR = "Voilà, prête !",
          DialogueId = 11012304,
          Duration = 3,
          GUID = "1B917220",
          IsBlack = 1,
          SpeakNpcId = 110034,
          Subtitle = "Now, I'm ready.",
          VoiceName = "voice/$Locale$/story/1002/110123/1B917220"
        },
        [11012401] = {
          Camera = "34.176025,-39.523438,173.482391,0.000113,-24.600769,-88.793587,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Espèce de folle ! Qu’est-ce qui te fait rire ? Tu trahis {性别2:le|la} capitaine après tout ce {性别2:qu’il|qu’elle} a fait pour toi, et tu n’as pas le moindre remords ?",
          DialogueId = 11012401,
          Duration = 1,
          FacialId = {
            [1] = "110009:Smile01"
          },
          FinalCamera = "45.875854,-39.736328,173.482391,0.000107,-24.800785,-95.193405,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91820A",
          NextDialogue = 11012402,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201013,
            [3] = 201015,
            [4] = 408007,
            [5] = 101004
          },
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0062_story_kajia_jazz\"},RelatedRegionId{102102}},\nSEQ{\nLookAt{_delay{4.6},LookAtDescription{\"110009:n(110015)\"}},\nSEQ{\nCameraMoveTo{_delay{0.3},TargetPosition{\"-123.187927,27.958496,162.47821,0.000124,-10.800598,-50.990803,20.000008,214.123978,false,Manual,9.156517\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-118.514038,31.491699,162.47821,0.000128,-11.200587,-53.590874,20.0,214.123978,false,Manual,9.156517\"},duration{8}}\n},\nTurnTo{TurnToDescription{\"110009:n(110015)\"},AnimationId{\"Talk03_Rotation\"}}\n}\n}",
          SpeakNpcId = 110015,
          Subtitle = "You crazy girl! What are you laughing at? Is this how you repay the Captain's kindness? Don't you feel guilty at all?",
          TalkActionId = {
            [1] = "110015:Angry01_Start",
            [2] = "110009:Talk03_Loop"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "110015:n(110009)"
          },
          VoiceName = "voice/$Locale$/story/1002/110124/1B91820A"
        },
        [11012402] = {
          ContentFR = "Des remords... ? Ha ! T’as bu trop de mixtures de ton Académie ? Elles t’ont grillé les neurones ou quoi ?",
          DialogueId = 11012402,
          Duration = 1,
          GUID = "1B918234",
          NextDialogue = 11012403,
          SpeakNpcId = 110009,
          Subtitle = "Guilty...? Ha, have you had too many alchemical concoctions from your Academy that damaged your brain?",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918234"
        },
        [11012403] = {
          Camera = "260.713257,-90.661621,58.734558,8.00024,13.399219,-178.404022,25.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Oh, attends, si, je dois avouer une faute. Pour berner {性别2:ton stupide petit|ta stupide petite} capitaine, j’ai attribué aux Déchus tous les crimes que l’Empire avait commis contre nous. Ah, mes pauvres camarades Déchus, pardonnez-moi ! Voilà mon grand remords !",
          DialogueId = 11012403,
          FacialId = {
            [1] = "110009:Happy01"
          },
          FinalCamera = "258.15625,-50.303223,64.266418,8.001002,12.999065,-169.203247,25.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91825E",
          NextDialogue = 11012404,
          Scripts = "SEQ{\t\nPlayAnimation{_delay{2},ActorId{110009},AnimationId{\"Talk03_End\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"Talk02_Start\"},Duration{1}},\nPlayAnimation{_delay{5},ActorId{110009},AnimationId{\"Talk02_End\"},Duration{1}},\nPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"Explain02_Start\"},Duration{1}}\n}",
          SpeakNpcId = 110009,
          Subtitle = "Oh wait, I do feel guilty about one thing — to manipulate that stupid captain of yours, I lied about The Forsakens and blamed them for what the Empire did to us. I'm so sorry to The Forsakens!",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91825E"
        },
        [11012404] = {
          Camera = "47.596252,-59.071777,179.024414,0.0,-15.604331,172.020538,30.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Toi— !",
          DialogueId = 11012404,
          Duration = 3,
          GUID = "1B918288",
          NextDialogue = 11012405,
          SpeakNpcId = 110015,
          Subtitle = "You—!",
          TalkActionId = {
            [1] = "110015:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110124/1B918288"
        },
        [11012405] = {
          Camera = "107.89502,-52.999512,167.227966,0.000065,-17.19899,-137.611404,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Tiens tiens... mais qui voilà ? {性别2:Mon cher capitaine|Ma chère capitaine} !",
          DialogueId = 11012405,
          Duration = 2,
          GUID = "1B9182B2",
          LookAt = {
            [1] = "110009:n(110022)",
            [2] = "110015:n(110022)"
          },
          NextDialogue = 11012406,
          Scripts = "PARA{\nMoveTo{_delay{1.01},ActorId{110022},TargetPoint{\"BP_Fix14Move01\"},MoveSpeed{70},Visibility{\"Show\"}},\nPlayAnimation{_delay{2},ActorId{110009},AnimationId{\"Talk03_Start\"},Duration{1}},\nTurnTo{_delay{2.2},TurnToDescription{\"110009:n(110022)\"},AnimationId{\"Talk03_Rotation\"}},\nSEQ{\nCameraMoveTo{_delay{1.5},TargetPosition{\"247.434814,177.582031,241.001526,5.000789,-24.998772,-136.609848,15.610328,100000.0,false,Manual,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"270.668091,154.250488,238.401855,5.00087,-25.198746,-140.009369,15.610328,100000.0,false,Manual,22.0\"},duration{8}}\n}\n}",
          SpeakNpcId = 110009,
          Subtitle = "Oh, look what the cat dragged in. Hello, dear sir.",
          TalkActionId = {
            [1] = "110015:Angry01_End",
            [2] = "110009:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110124/1B9182B2"
        },
        [11012406] = {
          Camera = "-115.365784,-116.604004,153.945862,0.000102,-8.398161,58.59742,25.0,210.838287,false,Manual,9.970624",
          ContentFR = "Je vais m’en charger.",
          DialogueId = 11012406,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9182DC",
          LookAt = {
            [1] = "110022:n(110015)"
          },
          NextDialogue = 11012407,
          SpeakNpcId = 110022,
          Subtitle = "I'll take it from here.",
          TalkActionId = {
            [1] = "110009:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110124/1B9182DC"
        },
        [11012407] = {
          ContentFR = "Alors, qu’est-ce que tu veux de moi ? Me faire la leçon, montrer à quel point les officiers hyperboréens savent pardonner ? Ou peut-être que tu as pitié de cette pauvre fille qui a été "égarée" et que tu essaies de me sauver de mes "péchés" ?",
          DialogueId = 11012407,
          FacialId = {
            [1] = "110009:Happy01"
          },
          GUID = "1B918306",
          LookAt = {
            [1] = "110022:n(110009)"
          },
          NextDialogue = 11012408,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{_delay{0.25},ActorId{110009},AnimationId{\"Talk02_Start\"},Duration{3}}, \t\nPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"Talk02_End\"},Duration{1}}, \nPlayAnimation{_delay{4},ActorId{110009},AnimationId{\"Confident_Start\"},Duration{4}}\n},\nSEQ{\nCameraMoveTo{_delay{1.5},TargetPosition{\"50.555542,84.171387,71.75116,5.000197,8.604228,-107.607498,15.610331,100000.0,false,Manual,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"60.200439,80.97168,70.87262,5.000216,8.204218,-108.407532,15.610331,100000.0,false,Manual,22.0\"},duration{8}}\n}\n}",
          SpeakNpcId = 110009,
          Subtitle = "So what are you doing here? Come to show off the benevolence of a Hyperborean officer? Or perhaps you pity this poor girl who's been led "astray," trying to save me from my "sins"?",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918306"
        },
        [11012408] = {
          Camera = "66.784729,-41.81543,164.458191,0.000175,-20.396324,-111.40432,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Oh ! J’ai compris, tu veux rejoindre les Déchus, pas vrai ? Besoin d’une recommandation ?",
          DialogueId = 11012408,
          FacialId = {
            [1] = "110009:Shock01"
          },
          FinalCamera = "74.0578,-44.788574,164.458191,0.000176,-20.996336,-116.603729,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918330",
          NextDialogue = 11012409,
          Scripts = "PlayFacial{_delay{3},ActorId{110009},FacialId{"Smile01"}}",
          SpeakNpcId = 110009,
          Subtitle = "Oh, I get it! You want to join The Forsakens, right? Need a reference?",
          TalkActionId = {
            [1] = "110009:Confident_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918330"
        },
        [11012409] = {
          Camera = "139.056091,287.382324,595.817444,0.000163,-53.397076,-119.639305,15.610332,100000.0,false,Manual,22.0",
          ContentFR = "Hé, vous avez entendu ? {性别2:Votre cher|Votre chère} capitaine veut devenir {性别2:un|une} des nôtres !",
          DialogueId = 11012409,
          Duration = 3,
          FinalCamera = "156.030762,317.214355,642.029114,0.000163,-53.397076,-119.639305,15.610332,100000.0,false,Manual,22.0",
          GUID = "1B91835A",
          LookAt = {
            [1] = "110009:p(BP_Fix14Move03)"
          },
          NextOptions = {
            [1] = 11012410,
            [2] = 11012412,
            [3] = 11012414,
            [4] = 11012417
          },
          SpeakNpcId = 110009,
          Subtitle = "Hey — you guys hear that? Your captain wants to join The Forsakens!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91835A"
        },
        [11012410] = {
          ContentFR = "Inutile de crier, personne ne t’écoutera.",
          DialogueId = 11012410,
          GUID = "1B918384",
          ImprPlusId = 1006,
          NextDialogue = 11012411,
          Subtitle = "Save it. No one would give you any attention."
        },
        [11012411] = {
          Camera = "54.121704,-48.700684,112.361572,0.000127,17.4041,-101.210175,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Oh non... Quelle tristesse... Bouhouhou...",
          DialogueId = 11012411,
          Duration = 3,
          FacialId = {
            [1] = "110009:Unhappy01"
          },
          FinalCamera = "63.299988,-50.780273,112.361572,0.000119,18.004063,-107.010971,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B9183AE",
          NextDialogue = 11012419,
          Scripts = "SEQ{\t\nLookAt{LookAtDescription{\"110009:n(110022)\"}},\n\tPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayFacial{_delay{2.5},ActorId{110009},FacialId{\"Smile01\"}}\n\t\t\t\t\t}",
          SpeakNpcId = 110009,
          Subtitle = "Oh, no. This is so sad. Boohoo whoo.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9183AE"
        },
        [11012412] = {
          ContentFR = "Oui, je suis {性别2:intéressé|intéressée}. Alors, qui est ton contact ?",
          DialogueId = 11012412,
          GUID = "1B9183D8",
          ImprPlusId = 1008,
          NextDialogue = 11012413,
          Subtitle = "Yeah, I'm interested. Who's your contact?"
        },
        [11012413] = {
          Camera = "54.121704,-48.700684,112.361572,0.000127,17.4041,-101.210175,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "{性别2:Mon chéri|Ma chérie}, t’es vraiment nul à ce petit jeu-là. Oublie ça, tu n’auras rien de moi. Trahir ses camarades et vendre des infos à l’ennemi, ça n’existe que dans VOTRE Légion.",
          DialogueId = 11012413,
          Duration = 3,
          FacialId = {
            [1] = "110009:Happy02"
          },
          FinalCamera = "63.299988,-50.780273,112.361572,0.000119,18.004063,-107.010971,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918402",
          LookAt = {
            [1] = "110009:n(110022)",
            [2] = "110022:n(110009)"
          },
          NextDialogue = 11012419,
          Scripts = "SEQ{\t\nLookAt{LookAtDescription{\"110009:n(110022)\"}},\n\tPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"DisagreeHead\"},Duration{1}}\n\t\t\t\t\t}",
          SpeakNpcId = 110009,
          Subtitle = "Oh honey, you really suck at this. Save it — you won't get anything from me. Lowlives who betray their comrades and sell intel to their enemy only exist in your beloved Legion.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918402"
        },
        [11012414] = {
          ContentFR = "Tu as eu de nombreuses occasions de tendre une embuscade. Pourquoi avoir attendu ?",
          DialogueId = 11012414,
          GUID = "1B91842C",
          ImprPlusId = 1007,
          NextDialogue = 11012415,
          Subtitle = "You had many chances for an ambush. Why played the long game?"
        },
        [11012415] = {
          Camera = "46.445557,-47.61377,108.603271,0.000125,21.20381,-96.211113,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Parce que tu es toujours sur tes gardes. Même en tête-à-tête, je n’avais pas d’ouverture. Alors j’ai attendu. J’ai même joué les alliées pour gagner ta confiance, jusqu’à ce que tu baisses enfin la garde.",
          DialogueId = 11012415,
          Duration = 3,
          FacialId = {
            [1] = "110009:Syouganai01"
          },
          FinalCamera = "54.121704,-48.700684,112.361572,0.000123,18.604048,-104.010506,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918456",
          LookAt = {
            [1] = "110009:n(110022)",
            [2] = "110022:n(110009)"
          },
          NextDialogue = 11012416,
          Scripts = "SEQ{\t\nLookAt{LookAtDescription{\"110009:n(110022)\"}},\n\tPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"DisagreeHead\"},Duration{1}}\n\t\t\t\t\t}",
          SpeakNpcId = 110009,
          Subtitle = "Because you're always so on guard. I couldn't find a chance, even while we were alone. I had to bide my time patiently. Even offered you help a couple of times to lower your guard.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918456"
        },
        [11012416] = {
          Camera = "89.683167,-149.077637,145.866699,5.000385,-11.796221,136.384216,15.610328,100000.0,false,Manual,22.0",
          ContentFR = "Et puis, c’est bien plus amusant comme ça ! La trahison d’un proche, ça fait bien plus mal qu’un coup de couteau d’un inconnu, tu ne trouves pas ?",
          DialogueId = 11012416,
          Duration = 3,
          FacialId = {
            [1] = "110009:Smile01"
          },
          FinalCamera = "84.397888,-154.758789,145.202393,5.000216,-11.596308,132.184692,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B918480",
          NextDialogue = 11012419,
          SpeakNpcId = 110009,
          Subtitle = "And it's more fun this way! Betrayal by a trusted friend is far more memorable than a stab from a stranger, isn't it?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918480"
        },
        [11012417] = {
          ContentFR = "Donner un coup de poing en pleine figure pour la faire taire",
          DialogueId = 11012417,
          GUID = "1B9184AA",
          ImprPlusId = 1010,
          NextDialogue = 11012418,
          Subtitle = "(Give her a punch to shut her up)"
        },
        [11012418] = {
          Camera = "53.920044,104.336914,141.410339,0.00019,-8.595615,-111.008072,15.610335,100000.0,false,Manual,22.0",
          ContentFR = "Aïe ! Mais {性别2:arrêtez-le|arrêtez-la} ! Un soldat armé qui frappe une pauvre fille sans défense !",
          DialogueId = 11012418,
          Duration = 3,
          FacialId = {
            [1] = "110009:Angry02"
          },
          FinalCamera = "66.364197,136.741699,146.657166,0.00019,-8.595615,-111.008026,15.610335,100000.0,false,Manual,22.0",
          GUID = "1B9184D4",
          LookAt = {
            [1] = "110022:n(110009)"
          },
          NextDialogue = 11012419,
          Scripts = "SEQ{\t\nLookAt{LookAtDescription{\"110009:n(110022)\"}},\n\tPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayAnimation{_delay{5},ActorId{110009},AnimationId{\"Shock02_End\"},Duration{1}}\n\t\t\t\t\t}",
          SpeakNpcId = 110009,
          Subtitle = "Oww, it hurts! Someone do something about this! An armed soldier's hitting a helpless young girl!",
          TalkActionId = {
            [1] = "110009:Shock02_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9184D4"
        },
        [11012419] = {
          Camera = "25.013306,-51.197266,163.60907,0.000128,-13.195823,97.192642,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Tu...",
          DialogueId = 11012419,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Angry01"
          },
          GUID = "1B9184FE",
          LookAt = {
            [1] = "110009:n(110022)",
            [2] = "110022:n(110009)"
          },
          NextDialogue = 11012420,
          SpeakNpcId = 110022,
          Subtitle = "You...",
          VoiceName = "voice/$Locale$/story/1002/110124/1B9184FE"
        },
        [11012420] = {
          Camera = "64.016296,8.083984,162.781921,0.000138,-12.196129,-101.411896,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Quoi, tu fais les gros yeux comme un taureau furieux ? Oh pardon, {性别2:mon|ma} capitaine, j’avais oublié, tu préfères quand je parle comme ça, pas vrai ?",
          DialogueId = 11012420,
          Duration = 3,
          FacialId = {
            [1] = "110009:Smile01"
          },
          FinalCamera = "76.841187,4.975586,162.781921,0.000145,-12.796161,-107.212456,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918528",
          NextDialogue = 11012421,
          Scripts = "SEQ{\t\n\tPlayAnimation{_delay{3},ActorId{110009},AnimationId{\"Talk02_End\"},Duration{0}},\n\tPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"Explain02_Start\"},Duration{1}}\n\t\t}",
          SpeakNpcId = 110009,
          Subtitle = "Aww, you look like an angry bull. I'm so sorry, sir! I forgot you like it better when I talk like this.",
          TalkActionId = {
            [1] = "110009:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918528"
        },
        [11012421] = {
          Camera = "67.383972,-41.145508,109.074097,0.000133,16.40362,124.389236,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... Assez. Arrête de faire semblant et réponds à ma question.",
          DialogueId = 11012421,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "59.581787,-46.003906,109.074097,0.000143,15.403538,117.789177,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918552",
          NextDialogue = 11012422,
          SpeakNpcId = 110022,
          Subtitle = "...Cut the act, and answer my question.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918552"
        },
        [11012422] = {
          Camera = "42.844299,111.979004,130.528442,0.000137,-0.596098,-96.811264,35.0,240.549789,false,Manual,17.359072",
          ContentFR = "D’accord, d’accord ! Demande toujours... mais je répondrai seulement si l’envie me prend.",
          DialogueId = 11012422,
          Duration = 3,
          FacialId = {
            [1] = "110009:Happy02"
          },
          FinalCamera = "50.505554,110.991699,130.528442,0.000137,-0.796106,-100.811478,35.0,240.549789,false,Manual,17.359072",
          GUID = "1B91857C",
          NextDialogue = 11012423,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{ActorId{110009},AnimationId{\"AgreeHead\"},Duration{0}}\n},\nSEQ{\nCameraMoveTo{_delay{2.01},TargetPosition{\"102.134827,-40.521973,197.003082,0.000074,-39.395588,-134.808945,15.610332,100000.0,false,Manual,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"118.157654,-59.834961,197.003082,0.000108,-39.795586,-143.40889,15.610332,100000.0,false,Manual,22.0\"},duration{15}}\n}\n}",
          SpeakNpcId = 110009,
          Subtitle = "Sure! Ask away. I'll answer whenever I feel like it.",
          TalkActionId = {
            [1] = "110009:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91857C"
        },
        [11012423] = {
          Camera = "67.383972,-41.145508,109.074097,0.000133,16.40362,124.389236,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Après tout ça, j’ai bien droit à une explication. Tu voulais frapper la Légion Hyperboréenne ? Ou bien c’était moi que tu visais ?",
          DialogueId = 11012423,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "59.581787,-46.003906,109.074097,0.000143,15.403538,117.789177,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B9185A6",
          NextDialogue = 11012424,
          Scripts = "SEQ{\t\n\tPlayAnimation{_delay{2},ActorId{110022},AnimationId{\"Explain01_Start\"},Duration{6}}\n\t\t}",
          SpeakNpcId = 110022,
          Subtitle = "I deserve to know why you stabbed us in the back after I helped you. Is it out of plain hatred for the Hyperborean Legion, or an assassination attempt targeting me specifically?",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9185A6"
        },
        [11012424] = {
          Camera = "50.555542,84.171387,71.75116,5.000197,8.604228,-107.607498,15.610331,100000.0,false,Manual,22.0",
          ContentFR = "Ah, ça ! Très bien, je vais te dire, considère ça comme un petit cadeau pour m’avoir bien divertie.",
          DialogueId = 11012424,
          FacialId = {
            [1] = "110009:Smile01"
          },
          FinalCamera = "60.200439,80.97168,70.87262,5.000216,8.204218,-108.407532,15.610331,100000.0,false,Manual,22.0",
          GUID = "1B9185D0",
          NextDialogue = 11012425,
          Scripts = "SEQ{\t\n\tPlayAnimation{_delay{1},ActorId{110009},AnimationId{\"AgreeHead\"},Duration{4}},\n\tPlayAnimation{ActorId{110009},AnimationId{\"Talk03_Start\"},Duration{6}}\n\t\t}",
          SpeakNpcId = 110009,
          Subtitle = "If this is your question... Sure, I can answer that — given that you've been naive enough to fall for my trick.",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9185D0"
        },
        [11012425] = {
          Camera = "70.837952,-130.941895,139.360352,5.001442,-5.595973,131.590164,15.0,174.765015,false,Manual,8.726983",
          ContentFR = "Les Déchus veulent voir crever tous les chiens d’Hyperborea... et de préférence massacrés par leurs propres joujoux de guerre. Notre cadeau enflammé t’a plu ?",
          DialogueId = 11012425,
          Duration = 3,
          FinalCamera = "65.503906,-135.757812,138.734558,5.001442,-5.595973,131.590164,15.0,174.765015,false,Manual,8.726983",
          GUID = "1B9185FA",
          NextDialogue = 11012426,
          SpeakNpcId = 110009,
          Subtitle = "The Forsakens simply want all Hyperborean dogs to die here, and preferably at the hands of the killing machines they created — I hope you enjoyed our fiery gift.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9185FA"
        },
        [11012426] = {
          Camera = "58.501587,-26.595215,105.298645,0.000128,17.4041,-101.210243,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Quant à moi... Évidemment, je suis venue pour <H>toi</> !",
          DialogueId = 11012426,
          Duration = 3,
          FacialId = {
            [1] = "110009:Happy02"
          },
          FinalCamera = "56.160217,-38.411133,109.074097,0.000128,17.4041,-101.210243,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918624",
          NextDialogue = 11012427,
          Scripts = "SEQ{\nCameraMoveTo{_delay{5.01},TargetPosition{\"43.346985,-69.564941,139.947693,0.000127,-0.395782,105.19191,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"37.646606,-48.572266,139.797546,0.000127,-0.395782,105.191254,35.0,100000.0,false,DoNotOverride,22.0\"},duration{3}}\n}",
          SpeakNpcId = 110009,
          Subtitle = "As for me... Well, I personally came for you!",
          TalkActionId = {
            [1] = "110009:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918624"
        },
        [11012427] = {
          Camera = "58.501587,-26.595215,105.298645,0.000128,17.4041,-101.210243,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "On m’a dit que {性别2:le meilleur élève|la meilleure élève} de l’École Militaire Impériale {性别2:le fameux Faucheur Pâle|la fameuse Faucheuse Pâle}, était posté à la Forteresse de Lonza. Comment aurais-je pu rater ça, {性别2:mon cher|ma chère} ?",
          DialogueId = 11012427,
          Duration = 3,
          FacialId = {
            [1] = "110009:Smile01"
          },
          FinalCamera = "56.160217,-38.411133,109.074097,0.000128,17.4041,-101.210243,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91864E",
          NextDialogue = 11012428,
          Scripts = "SEQ{\nCameraMoveTo{_delay{9.01},TargetPosition{\"279.34082,526.726074,556.351196,0.000154,-35.996132,-112.204155,30.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"297.749146,571.827637,591.737976,0.000135,-35.996117,-112.203873,30.0,100000.0,false,DoNotOverride,22.0\"},duration{15}}\n}",
          SpeakNpcId = 110009,
          Subtitle = "I heard that you, the top graduate of the Imperial Military College, who is also known as the "Pale Reaper," were coming to Lonza Fortress. How could I not come have a good look at the Pale Reaper myself?",
          TalkActionId = {
            [1] = "110009:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91864E"
        },
        [11012428] = {
          ContentFR = "Tu as entendu parler de moi ? On s’est déjà rencontrés ?",
          DialogueId = 11012428,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B918678",
          NextDialogue = 11012429,
          Scripts = "PlayAnimation{_delay{1},ActorId{110009},AnimationId{"Talk01_End"},Duration{3}}",
          SpeakNpcId = 110022,
          Subtitle = "You've heard about me? Have we met before?",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918678"
        },
        [11012429] = {
          Camera = "59.763062,-49.09668,176.350708,0.000166,-19.596434,116.988365,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Hihi... devine !",
          DialogueId = 11012429,
          FacialId = {
            [1] = "110009:Happy01",
            [2] = "110022:None"
          },
          FinalCamera = "17.108765,-59.740234,176.350708,0.000137,-19.796442,93.389694,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B9186A2",
          NextDialogue = 11012430,
          SpeakNpcId = 110009,
          Subtitle = "Hehe, that's for you to guess.",
          TalkActionId = {
            [1] = "110009:Explain01_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9186A2"
        },
        [11012430] = {
          ContentFR = "D’après mes sources, notre {性别2:grand Faucheur Pâle|grande Faucheuse Pâle} n’a que quelques années de souvenirs. Tu ignores tout de ton passé... même l’endroit d’où tu viens.",
          DialogueId = 11012430,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9186CC",
          NextDialogue = 11012431,
          Scripts = "PARA{\nPlayAnimation{_delay{2},ActorId{110009},AnimationId{\"Think_Start\"},Duration{13}},\nSEQ{\nCameraMoveTo{_delay{5.01},TargetPosition{\"68.789917,-13.603516,81.309998,0.000153,24.602831,-104.008942,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"92.808777,-22.250977,81.309998,0.00013,24.002684,-118.007851,35.0,100000.0,false,DoNotOverride,22.0\"},duration{18}}\n}\n}",
          SpeakNpcId = 110009,
          Subtitle = "My sources said that our great {性别2:Mr|Miss} Pale Reaper only has a few years' worth of memories. You know nothing of your past. You don't even know where you came from.",
          TalkActionId = {
            [1] = "110009:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110124/1B9186CC"
        },
        [11012431] = {
          Camera = "66.198914,9.57666,168.016846,0.000119,-21.996002,147.583939,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "...",
          DialogueId = 11012431,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Angry01"
          },
          FinalCamera = "61.727417,2.568848,168.016846,0.000122,-21.795979,140.583939,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B9186F6",
          NextDialogue = 11012432,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110009:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9186F6"
        },
        [11012432] = {
          Camera = "211.526978,350.025391,6.514038,0.000125,12.404128,-112.807137,15.610332,100000.0,false,Manual,22.0",
          ContentFR = "Allez, jouons ! Devine, suis-je ta voisine d’enfance ? Ton ennemie jurée ? Ou bien...",
          DialogueId = 11012432,
          Duration = 3,
          FinalCamera = "299.082275,312.626953,6.514038,0.000124,11.604074,-121.206917,15.610332,100000.0,false,Manual,22.0",
          GUID = "1B918720",
          NextDialogue = 11012433,
          Scripts = "SEQ{\t\n\tPlayAnimation{_delay{2},ActorId{110009},AnimationId{\"Talk01_End\"},Duration{0}},\n\tPlayAnimation{_delay{2},ActorId{110009},AnimationId{\"Think_Start\"},Duration{5}}\n\t\t}",
          SpeakNpcId = 110009,
          Subtitle = "Let's play a game then! Now, honey, take a guess — was I your neighbour, an old nemesis—",
          TalkActionId = {
            [1] = "110009:Talk01_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918720"
        },
        [11012433] = {
          Camera = "52.758484,-76.275391,111.210327,0.000158,22.203632,-111.603455,15.000005,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Une parfaite inconnue qui te hait juste parce qu’Hyperborea t’adule... et qui veut briser tout ce que ton peuple chérit ?",
          DialogueId = 11012433,
          Duration = 3,
          FinalCamera = "64.058716,-81.423828,111.210327,0.000149,22.203619,-125.00338,15.000005,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91874A",
          NextDialogue = 11012434,
          SpeakNpcId = 110009,
          Subtitle = "Or a complete stranger? Maybe I just hate you for being one of Hyperborea's honorable people, and I simply wish to destroy that which they cherish?",
          TalkActionId = {
            [1] = "110009:Confident_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91874A"
        },
        [11012434] = {
          Camera = "195.732178,301.745117,385.913788,0.000154,-36.996174,-121.203201,30.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "...",
          DialogueId = 11012434,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Pain01"
          },
          FinalCamera = "330.787842,524.716797,582.327881,0.000154,-36.996174,-121.203201,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918774",
          NextDialogue = 11012435,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Sigh_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918774"
        },
        [11012435] = {
          Camera = "24.656494,7.404297,190.805542,-0.002769,-61.608364,102.005478,15.610328,100000.0,false,Manual,22.0",
          ContentFR = "W>Ta tête te fait mal, pas vrai ? Écoute... Les paroles de cette folle grouillent dans ton crâne comme des sangsues affamées, rongeant ton crâne, suçotant ta cervelle.</>",
          DialogueId = 11012435,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "0.038208,11.194824,204.206421,-5.00001,-64.807861,70.004921,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B91879E",
          NextDialogue = 11012436,
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},\nPostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Your head hurts, right? The jabbering of this mad girl is worming through your skull like a leech sucking at your brains.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91879E"
        },
        [11012436] = {
          Camera = "36.141357,29.718262,149.925659,-0.002777,-12.206906,146.405396,15.610331,100000.0,false,Manual,22.0",
          ContentFR = "<W>Regarde. Dans ta main, ton épée... oui, ta fidèle lame. La garde est encore tiède de ta paume. Tu connais par cœur la sensation, la chair qui cède, la résistance infime quand l’acier s’enfonce.</>",
          DialogueId = 11012436,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "19.049377,14.672852,139.228333,-0.002778,11.392994,99.206146,15.610331,100000.0,false,Manual,22.0",
          GUID = "1B9187C8",
          NextDialogue = 11012437,
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},\nPostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "See, you have a sword in your hand. That's right — it's the one you've wielded in countless battles. The hilt still carries your warmth. You're familiar with the slick feeling and the subtle tug of resistance when its blade slices through flesh.",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9187C8"
        },
        [11012437] = {
          Camera = "21.503967,-78.260254,143.286499,-10.000029,-24.608084,-64.792946,15.610331,100000.0,false,Manual,22.0",
          ContentFR = "<W>Un geste, et tu pourrais lui trancher la gorge. Sa bouche immonde ne vomirait plus que des gargouillis de douleur.</>",
          DialogueId = 11012437,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "36.730774,-74.067871,146.035278,-10.002868,-12.007807,-82.793266,15.610331,100000.0,false,Manual,22.0",
          GUID = "1B9187F2",
          NextDialogue = 11012438,
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},\nPostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "You can easily slit this creature's throat and make its detestable lips gurgle and whimper in pain.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9187F2"
        },
        [11012438] = {
          Camera = "12.627441,-61.455566,63.949219,-24.997759,29.588535,90.003098,15.610331,100000.0,false,Manual,22.0",
          ContentFR = "Encore... cette voix ! Pourquoi maintenant...",
          DialogueId = 11012438,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Pain01"
          },
          FinalCamera = "-13.80426,-63.097656,74.73175,-24.995596,22.388308,73.20163,15.610331,100000.0,false,Manual,22.0",
          GUID = "1B91881C",
          NextOptions = {
            [1] = 11012439,
            [2] = 11012440
          },
          Scripts = "PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(It's... that voice again! Why now...?)",
          TalkActionId = {
            [1] = "110009:Confident_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91881C",
          bForbidSkipOptions = true
        },
        [11012439] = {
          ContentFR = "Essayer de résister à la voix",
          DialogueId = 11012439,
          GUID = "1B918846",
          NextDialogue = 11012451,
          Subtitle = "(Try to stay rational)"
        },
        [11012440] = {
          ContentFR = "Suivre la voix et poser la main sur l’épée",
          DialogueId = 11012440,
          GUID = "1B918870",
          NextDialogue = 11012441,
          Subtitle = "(Follow the voice and reach for the sword)"
        },
        [11012441] = {
          Camera = "46.395996,104.947266,140.937012,0.000127,-5.595858,-100.208458,15.610328,100000.0,false,Manual,22.0",
          ContentFR = "Pourquoi tu te tais ? Tu faisais {性别2:le beau donneur|la belle donneuse} de leçons tout à l’heure. T’as perdu ta langue, {性别2:mon chéri|ma chérie} ?",
          DialogueId = 11012441,
          Duration = 3,
          FinalCamera = "61.274414,101.967773,140.937012,0.000126,-6.195862,-102.008621,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B91889A",
          LookAt = {
            [1] = "110022:n(110009)",
            [2] = "110009:n(110022)"
          },
          NextDialogue = 11012442,
          Scripts = "PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}",
          SpeakNpcId = 110009,
          Subtitle = "Why suddenly so quiet? You seemed ready to lecture me. Cat got your tongue, honey?",
          TalkActionId = {
            [1] = "110009:Talk01_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91889A"
        },
        [11012442] = {
          Camera = "21.829651,1.994629,185.932617,-0.002807,-46.00626,103.005737,15.610328,100000.0,false,Manual,22.0",
          ContentFR = "<W>Je suis ton plus ancien instinct, l’élan qui sommeille en toi. Ne me rejette pas. C’est moi qui t’ai donné ta force, celle qui t’a rendu invincible au combat.</>",
          DialogueId = 11012442,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "18.443298,16.547363,170.50415,-0.002807,-45.806274,103.205795,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B9188C4",
          NextDialogue = 11012443,
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},\nPostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "I am the origin of your soul, the impulse within the deepest recesses of your mind. Do not refuse me... Listen — I am the one who gave you power and made you invincible in battle.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9188C4"
        },
        [11012443] = {
          Camera = "72.286804,42.974121,53.70752,-0.002806,23.989386,-155.191223,15.610331,100000.0,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "<W>Sors ton épée. Cette lame acérée qui n’attend que ça.</>",
          DialogueId = 11012443,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Pain01"
          },
          FinalCamera = "72.286804,42.974121,53.70752,-0.002805,24.989229,-116.590668,15.610331,100000.0,false,Manual,22.0",
          GUID = "1B9188EE",
          NextOptions = {
            [1] = 11012444,
            [2] = 11012445
          },
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},\nPostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Unsheathe your sword, the one that bears the killing razor.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9188EE",
          bForbidSkipOptions = true
        },
        [11012444] = {
          ContentFR = "Essayer de résister à la voix",
          DialogueId = 11012444,
