        [11012464] = {
          Camera = "19.489258,-42.568848,150.775452,0.000048,-10.000312,-80.187958,55.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "<W>Quelqu’un veut ta mort... et il se cache parmi les tiens, dans la Légion.</>",
          DialogueId = 11012464,
          Duration = 3,
          FinalCamera = "2.376709,-35.279297,168.227814,0.000068,-22.400539,-64.191711,35.0,100000.0,false,DoNotOverride,22.0",
