        },
        [11012465] = {
          Camera = "-124.95282,-100.157227,169.175629,0.000139,-10.795749,52.190491,35.0,202.832306,false,Manual,22.0",
          ContentFR = "Qu’est-ce que tu viens de dire ?",
          DialogueId = 11012465,
