          },
          FinalCamera = "-132.01178,-93.834961,169.175629,0.000146,-10.795749,46.590034,35.0,202.832306,false,Manual,22.0",
          GUID = "1B918C60",
          NextDialogue = 11012466,
          Scripts = "PostProcess{MaterailInstance{"None"}}",
          SpeakNpcId = 110022,
          Subtitle = "What did you say?",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918C60"
        },
        [11012466] = {
          Camera = "-270.096924,-220.964355,332.621887,0.000151,-35.795891,35.78912,15.610332,100000.0,false,Manual,22.0",
          ContentFR = "Les secrets ne se chuchotent qu’une fois. Hihi... bon voyage, {性别2:mon|ma} capitaine.",
          DialogueId = 11012466,
          Duration = 3,
          FacialId = {
            [1] = "110009:Happy02"
          },
          FinalCamera = "-291.60144,-236.469727,351.73877,0.000151,-35.795891,35.78912,15.610332,100000.0,false,Manual,22.0",
          GUID = "1B918C8A",
          LookAt = {
            [1] = "110022:n(110009)",
            [2] = "110009:n(110022)"
          },
          SpeakNpcId = 110009,
          Subtitle = "Secrets are meant to be whispered once. Take care, sir.",
          TalkActionId = {
            [1] = "110009:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918C8A"
        },
        [11012467] = {
          ContentFR = "{性别2:Mon chéri|Ma chérie}, te revoilà ? Aurais-tu changé d’avis, si {性别2:pressé|pressée} d’entendre mon secret ?",
          DialogueId = 11012467,
          Duration = 3,
          GUID = "1B918CB4",
          NextDialogue = 11012468,
          SpeakNpcId = 110009,
          Subtitle = "You're back, honey. Changed your mind already? Desperate to hear out the secret?",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CB4"
        },
        [11012468] = {
          ContentFR = "Mais quel dommage... je ne suis plus d’humeur à parler.",
          DialogueId = 11012468,
          Duration = 3,
          GUID = "1B918CDE",
          SpeakNpcId = 110009,
          Subtitle = "Sorry to disappoint, but I'm no longer in the mood for sharing.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CDE"
        },
        [11012469] = {
          ContentFR = "{性别2:Mon chéri|Ma chérie}, je sais ce que tu veux demander.",
          DialogueId = 11012469,
          Duration = 3,
          GUID = "1B918D08",
          NextDialogue = 11012470,
          SpeakNpcId = 110009,
          Subtitle = "I know what you want, honey.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D08"
        },
        [11012470] = {
          ContentFR = "Mais hélas... pauvre petite prisonnière que je suis, je n’ai plus le cœur à bavarder.",
          DialogueId = 11012470,
          Duration = 3,
          GUID = "1B918D32",
          SpeakNpcId = 110009,
          Subtitle = "But I'm just a poor little captive now, not in the mood to talk.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D32"
        },
        [11012501] = {
          ContentFR = "<W>Oui... c’est bien... serre fort la garde de ton épée. Voilà, comme ça. Maintenant, vise sa gorge...</>",
          DialogueId = 11012501,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B919272",
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "That's right — you've made the right choice. Grip the hilt tightly. Yes, just like that. Now aim at the creature's throat...",
          VoiceName = "voice/$Locale$/story/1002/110125/1B919272"
        },
        [11012502] = {
          ContentFR = "Tu... tu es {性别2:fou|folle} ?",
          DialogueId = 11012502,
          Duration = 3,
          GUID = "1B91929C",
          SpeakNpcId = 110009,
          Subtitle = "Are... Are you insane?",
          VoiceName = "voice/$Locale$/story/1002/110125/1B91929C"
        },
        [11012503] = {
          ContentFR = "<W>Oui. Plante-la. N’hésite pas.</>",
          DialogueId = 11012503,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9192C6",
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Yes, do it. Do not hesitate.",
          VoiceName = "voice/$Locale$/story/1002/110125/1B9192C6"
        },
        [11012504] = {
          ContentFR = "Aaaaah... AAAAHHH !",
          DialogueId = 11012504,
          Duration = 3,
          GUID = "1B9192F0",
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/kill"},PlayAs2D{true}}",
          SpeakNpcId = 110009,
          Subtitle = "Ahhh... Ahhhhhh!!",
          VoiceName = "voice/$Locale$/story/1002/110125/1B9192F0"
        },
        [11012505] = {
          ContentFR = "{nickname2}... Bon sang, qu’est-ce que tu as fait ?!",
          DialogueId = 11012505,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91931A",
          SpeakNpcId = 110010,
          Subtitle = "...My god, what have you done!?",
          VoiceName = "voice/$Locale$/story/1002/110125/1B91931A"
        },
        [11012506] = {
          ContentFR = "<W>Lui aussi. Ce vieillard inutile n’est qu’un fardeau.</>",
          DialogueId = 11012506,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B919344",
          Scripts = "PARA{PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'\"}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "This one too. The old fool is just dead weight.",
          VoiceName = "voice/$Locale$/story/1002/110125/1B919344"
        },
        [11012507] = {
          ContentFR = "Argh... kof, kof... !",
          DialogueId = 11012507,
          Duration = 3,
          GUID = "1B91936E",
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/kill"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "Argh... Arrrgh...",
          VoiceName = "voice/$Locale$/story/1002/110125/1B91936E"
        },
        [11012508] = {
          ContentFR = "<W>Les autres également...</>",
          DialogueId = 11012508,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B919398",
          Scripts = "SEQ{PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'\"}},\nPlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},\nPlayNormalSound{_delay{2},EventPath{\"event:/sfx/common/story/ex01/kill\"},PlayAs2D{true}}\n\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "And the others too...",
          VoiceName = "voice/$Locale$/story/1002/110125/1B919398"
        },
        [11012509] = {
          ContentFR = "<W>Oui... renonce à cette raison inutile, et suis ma voix...</>",
          DialogueId = 11012509,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9193C2",
          Scripts = "SEQ{PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'\"}},\nPlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},\nPlayNormalSound{_delay{2},EventPath{\"eevent:/sfx/common/story/ex01/kill\"},PlayAs2D{true}}\n}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "That's right! Forget about meaningless reason. Just follow my lead...",
          VoiceName = "voice/$Locale$/story/1002/110125/1B9193C2"
        },
        [11012510] = {
          ContentFR = "Capitaine ! Commandant Avar ! {性别2:Le|La} capitaine a {性别2:perdu|perdue} la tête ! N’approchez pas ! À l’aide ! ARRÊTEZ ! NON !",
          DialogueId = 11012510,
          Duration = 3,
          GUID = "1B9193EC",
          Scripts = "PlayNormalSound{_delay{4},EventPath{"event:/sfx/common/story/ex01/kill"},PlayAs2D{true}}",
          Subtitle = "Captain! Commander Avar! The Captain's gone mad! Stay away from me! Help! STOP! NOOOO!",
          VoiceName = "voice/$Locale$/story/1002/110125/1B9193EC"
        },
        [11012601] = {
          ContentFR = "Tout devint silencieux.",
          DialogueId = 11012601,
          Duration = 3,
          GUID = "1B91A2DA",
          NextDialogue = 11012602,
          Subtitle = "Everything fell silent.",
          VoiceName = "voice/$Locale$/story/1002/110126/1B91A2DA"
        },
        [11012602] = {
          ContentFR = "Non... pas un vrai silence. Tous les sons s’étaient fondus dans mes mains, une chaleur qui s’écoulait goutte à goutte sur le sol.",
          DialogueId = 11012602,
          Duration = 3,
          GUID = "1B91A304",
          Subtitle = "No, not dead silent. It's just that every noise had coalesced into a warmth flowing down my arms, dripping to the floor.",
          VoiceName = "voice/$Locale$/story/1002/110126/1B91A304"
        }
      }
    end
  },
  {
    MinKey = 11012603,
    MaxKey = 11014302,
    Loader = function()
      return {
        [11012603] = {
          ContentFR = "C’était le sable du temps qui s’écoulait. Le cri de la vie. Le battement d’un embryon dans le liquide maternel. L’écho immémorial qui sommeillait dans mon cœur.",
          DialogueId = 11012603,
          Duration = 3,
          GUID = "1B91A32E",
          NextDialogue = 11012604,
          Subtitle = "It was the sound of passing time, the roar of life that once was, the heartbeat of an embryo, and an ancient echo sealed deeply within my heart.",
          VoiceName = "voice/$Locale$/story/1002/110126/1B91A32E"
        },
        [11012604] = {
          ContentFR = "J’avais l’impression de ne faire plus qu’un avec cette voix primordiale.",
          DialogueId = 11012604,
          Duration = 3,
          GUID = "1B91A358",
          NextDialogue = 11012605,
          Subtitle = "I felt as though I had become one with this primal voice.",
          VoiceName = "voice/$Locale$/story/1002/110126/1B91A358"
        },
        [11012605] = {
          ContentFR = "Ploc... ploc... ploc...",
          DialogueId = 11012605,
          Duration = 3,
          GUID = "1B91A382",
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/blood"},PlayAs2D{true}}",
