        },
        [11012608] = {
          Camera = "46.395996,104.947266,140.937012,0.000127,-5.595858,-100.208458,15.610328,100000.0,false,Manual,22.0",
          ContentFR = "Hé ! Qu’est-ce qui te prend de hurler comme ça ? Tu m’as fichu une de ces peurs !",
          DialogueId = 11012608,
          Duration = 3,
          FacialId = {
            [1] = "110009:Angry02"
          },
          GUID = "1B91A400",
          NextDialogue = 11012609,
          SpeakNpcId = 110009,
          Subtitle = "What's gotten into you? You scared me!",
