          GUID = "1B91B396",
          NextDialogue = 11012704,
          SpeakNpcId = 110016,
          Subtitle = "I'm not sure how many assassins like her are waiting for us.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B396"
        },
        [11012704] = {
          Camera = "46.73317,22.289551,100.649963,0.000001,-0.600401,128.79567,35.0,306.210999,false,DoNotOverride,2.8",
          ContentFR = "Oui, la mort est une éventualité, pour vous, pour moi... pour nous tous probablement.",
          DialogueId = 11012704,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91B3C0",
          NextDialogue = 11012705,
          Scripts = "SEQ{\nCameraMoveTo{_delay{6},TargetPosition{\"-715.534119,-231.225586,435.199829,0.000164,-24.854435,20.828472,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-728.478149,-197.20166,435.199829,0.000164,-24.854435,20.828472,28.0,100000.0,false,DoNotOverride,2.8\"},duration{8}}\n}",
          SpeakNpcId = 110022,
          Subtitle = "Yes, death is a real possibility — for you, me, and probably all of us.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B3C0"
        },
        [11012705] = {
          Camera = "-29.131302,115.791504,118.524841,0.000012,-1.199846,58.998951,35.000008,111.172409,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 11012705,
          Duration = 3,
          FinalCamera = "-19.824371,131.277832,118.146606,0.000012,-1.199846,58.998951,35.000008,111.172409,false,DoNotOverride,2.8",
          GUID = "1B91B3EA",
          NextDialogue = 11012706,
