        },
        [11012725] = {
          Camera = "431.175476,-72.250488,84.118408,0.000063,-1.799133,150.597992,30.0,501.809082,false,DoNotOverride,5.0",
          ContentFR = "Bien. Préparez-vous, on y va.",
          DialogueId = 11012725,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "423.409973,-86.030762,84.118408,0.000063,-1.799133,150.597992,30.0,501.809082,false,DoNotOverride,5.0",
          GUID = "1B91B732",
          NextDialogue = 11012726,
