        },
        [11012728] = {
          Camera = "945.344116,-1229.479492,133.784607,18.00058,3.599988,-54.103123,40.0,517.956055,false,DoNotOverride,2.8",
          ContentFR = "Hein ? Vous comptez m’interroger encore ?",
          DialogueId = 11012728,
          Duration = 3,
          FinalCamera = "947.904724,-1227.703125,128.575073,18.001308,3.599988,-54.103092,40.000011,517.956055,false,DoNotOverride,2.8",
          GUID = "1B91B7B0",
          LookAt = {
            [1] = "110009:n(110010)"
          },
          NextDialogue = 11012729,
          SpeakNpcId = 110009,
          Subtitle = "Oh? Are you going to interrogate me?",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B7B0"
        },
        [11012729] = {
          Camera = "118.784447,-241.756836,89.649658,0.000005,-0.800109,96.800201,40.0,306.210999,false,DoNotOverride,2.8",
          ContentFR = "Non. On a vu combien elle est rusée. Ses informations ne feraient que brouiller notre jugement.",
          DialogueId = 11012729,
          Duration = 3,
          GUID = "1B91B7DA",
          NextDialogue = 11012730,
          SpeakNpcId = 110010,
          Subtitle = "No. I've seen how crafty this girl is. Her "intel" will only mess with our judgment.",
          TalkActionId = {
            [1] = "110010:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B7DA"
        },
        [11012730] = {
          Camera = "-789.535461,-296.212402,464.083984,0.000203,-23.79784,22.699654,30.0,517.956055,false,DoNotOverride,2.8",
          ContentFR = "Voici le plan : on se sépare en deux groupes. {nickname2} et moi partons en reconnaissance. Les autres se préparent et attaquent sur signal. Si on recule, retournez à la tourelle 4. Leon, tu restes en arrière pour surveiller les prisonniers.",
          DialogueId = 11012730,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-781.463074,-320.651367,464.959229,0.000203,-23.79784,22.699654,30.0,517.956055,false,DoNotOverride,2.8",
          GUID = "1B91B804",
          NextDialogue = 11012731,
          Scripts = "CameraMoveTo{_delay{12},TargetPosition{"-17.339386,56.376953,117.153992,0.000212,-6.797513,-111.697014,30.0,162.966705,false,Manual,2.8"},duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "Here's the plan: we split into two groups.  and I will scout ahead. The rest prepare and initiate the assault upon our signal. If we call it off, retreat to Turret 4. Leon, you stay back and guard the captives.",
          TalkActionId = {
            [1] = "110010:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B804"
        },
        [11012731] = {
          Camera = "-98.234558,-1429.317871,556.726807,0.999999,-18.052231,84.232918,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, commandant !",
          DialogueId = 11012731,
          Duration = 3,
          GUID = "1B91B82E",
          NextDialogue = 11012732,
          SpeakNpcName = "UI_Npc_All",
          Subtitle = "Yes, sir!",
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B82E"
        },
        [11012732] = {
          Camera = "-256.189758,59.020996,94.610657,0.000061,0.40014,23.996672,45.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Allons-y. Voyons quelles surprises Les Déchus nous ont préparées.",
          DialogueId = 11012732,
          Duration = 3,
          GUID = "1B91B858",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          Scripts = "TurnTo{TurnToDescription{"110010:p(-90)"}}\n",
          SpeakNpcId = 110010,
          Subtitle = "Let's move, and see what surprises The Forsakens have prepared for us.",
          TalkActionId = {
            [1] = "110010:Explain01_End",
            [2] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B858"
        },
        [11012801] = {
          Camera = "-28.373993,232.864197,143.277283,0.000001,-0.799959,-78.595703,40.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous êtes blessé, ça va ?",
          DialogueId = 11012801,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-30.631805,244.058456,143.436707,0.000001,-0.799959,-78.59536,40.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C3AA",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012802,
          SpeakNpcId = 110022,
          Subtitle = "You're injured, are you alright?",
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C3AA"
        },
        [11012802] = {
          Camera = "188.697754,-74.170662,131.45105,0.0,0.200022,129.200867,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une égratignure, rien de plus. Avec un peu de repos, ça ira. Cette gamine faisait semblant d’être menaçante, un chat de gouttière se serait mieux défendu.",
          DialogueId = 11012802,
          Duration = 3,
          FinalCamera = "162.229492,-95.300224,131.45105,-0.0,-0.199947,123.201126,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C3D4",
          NextDialogue = 11012803,
          Scripts = "SEQ{PlayAnimation{ActorId{110010},AnimationId{"Talk03_Start"},Duration{3}},PlayAnimation{ActorId{110010},AnimationId{"Talk03_End"},Duration{1}}}",
          SpeakNpcId = 110010,
          Subtitle = "Just a scratch; it'll heal soon. That little girl was just bluffing. Even a stray cat would've put up a better fight.",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C3D4"
        },
        [11012803] = {
          Camera = "-27.459442,206.711151,132.750061,0.000008,12.399866,105.204865,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mince... où est-ce que je l’ai mise... Je l’avais laissée ici pourtant...",
          DialogueId = 11012803,
          Duration = 3,
          FinalCamera = "-25.208466,200.122574,131.222473,0.000008,12.399866,105.204865,35.000015,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C3FE",
          NextDialogue = 11012804,
          SpeakNpcId = 110010,
          Subtitle = "Ugh, where did it go? I thought I had it right here...",
          TalkActionId = {
            [1] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C3FE"
        },
        [11012804] = {
          Camera = "-40.992615,407.549622,173.946289,0.000029,-9.399583,-88.996246,40.000011,313.388489,false,Manual,5.0",
          ContentFR = "Vous avez perdu quelque chose ?",
