          Duration = 3,
          FinalCamera = "-18.376434,229.534744,148.295166,0.00003,6.399894,112.800598,35.000023,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C452",
          NextDialogue = 11012806,
          SpeakNpcId = 110010,
          Subtitle = "Just a mere photo. Why don't you go interrogate that girl? She seems to be after you.",
          TalkActionId = {
            [1] = "110010:DisagreeHead",
            [2] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C452"
        },
        [11012806] = {
