        [11013601] = {
          Camera = "24.972092,-317.416016,82.76947,-5.000005,-5.79909,57.7701,15.000005,570.333496,false,DoNotOverride,20.0",
          ContentFR = "Fulvis... tu ne changeras jamais.",
          DialogueId = 11013601,
          Duration = 2,
          FinalCamera = "33.176193,-322.681641,81.920593,-5.000005,-5.79909,57.770142,15.000005,570.333496,false,DoNotOverride,20.0",
          GUID = "1B9246EA",
          NextDialogue = 11013602,
          SpeakNpcId = 110010,
          Subtitle = "Fulvis... you scheming bastard.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9246EA"
        },
        [11013602] = {
          Camera = "167.782227,328.865234,78.688873,-5.000004,0.40139,-85.618973,15.0,570.333496,false,DoNotOverride,20.0",
          ContentFR = "Tous ces faux documents, c’est ton œuvre, n’est-ce pas ? J’avais cru que vous autres aristocrates du Sénat ne vous abaisseriez pas à de telles manigances. Visiblement, je m’étais trompé.",
          DialogueId = 11013602,
          Duration = 3,
          FacialId = {
            [1] = "110022:Close"
          },
          FinalCamera = "157.87233,328.103516,77.819336,-5.000004,0.40139,-85.618973,15.0,570.333496,false,DoNotOverride,20.0",
          GUID = "1B924714",
          NextDialogue = 11013603,
          Scripts = "SEQ{\nCameraMoveTo{_delay{8},TargetPosition{\"183.857132,-9.058594,30.570129,-0.001556,18.806358,83.179565,55.0,209.993301,false,Manual,9.0\"},duration{0}},CameraMoveTo{TargetPosition{\"185.70015,6.349609,35.855255,-0.001556,18.806358,83.179565,55.0,209.993301,false,Manual,9.0\"},duration{6}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "You fabricated all this "evidence," didn't you? I didn't know you old-line aristocrats would stoop to such nasty tricks.",
          TalkActionId = {
            [1] = "110022:Die"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924714"
        },
        [11013603] = {
          Camera = "132.141647,116.539062,60.872101,-15.005561,5.400951,-79.810699,35.000011,570.333496,false,DoNotOverride,20.0",
          ContentFR = "Je ne suis pas comme ces vieux fossiles. Pour un pragmatique comme moi, peu importe le moyen, du moment qu’il fonctionne.",
          DialogueId = 11013603,
          Duration = 3,
          FinalCamera = "132.141647,116.539062,52.458649,-15.005593,5.400944,-79.810684,35.000011,570.333496,false,DoNotOverride,20.0",
          GUID = "1B92473E",
          NextDialogue = 11013604,
          SpeakNpcId = 110011,
          Subtitle = "I'm nothing like those stubborn old fools. I'm a pragmatist and would do anything that works.",
          TalkActionId = {
            [1] = "110011:DisagreeHead"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92473E"
        },
        [11013604] = {
          Camera = "148.312668,2233.953125,666.561768,-0.001619,-68.792679,61.391247,39.663486,100000.0,false,Manual,22.0",
          ContentFR = "Mais dis-moi... n’est-ce pas ton élève {性别2:préféré|préférée} qui gît là ? C’est toi qui as fait ça ?",
          DialogueId = 11013604,
          Duration = 5,
          FacialId = {
            [1] = "110011:Smile01"
          },
          FinalCamera = "165.08638,2264.316406,568.964294,-0.001626,-67.592896,61.591228,39.663486,100000.0,false,Manual,22.0",
          GUID = "1B924768",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013605,
          SpeakNpcId = 110011,
          Subtitle = "Isn't this your favourite protege? You did this?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924768"
        },
        [11013605] = {
          Camera = "151.53949,105.84375,142.877136,-0.001525,-17.594362,56.191444,60.0,100000.0,false,DoNotOverride,4.0",
          ContentFR = "Eh. Je voulais seulement préparer le terrain pour un marché entre nous. Inutile qu’il y ait un témoin de plus.",
          DialogueId = 11013605,
          Duration = 3,
          GUID = "1B924792",
          NextDialogue = 11013606,
          Scripts = "SEQ{\nCameraMoveTo{_delay{5},TargetPosition{\"-2055.0979,-34.339844,173.937714,0.0,-2.394063,-0.00531,40.0,100000.0,false,DoNotOverride,4.0\"},duration{0}},CameraMoveTo{TargetPosition{\"-2055.097656,18.054688,173.937714,0.0,-2.394063,-0.00531,40.0,100000.0,false,DoNotOverride,4.0\"},duration{8}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "Heh, I was just setting the stage for a deal with you. I don't think we need a third person for this.",
          TalkActionId = {
            [1] = "110011:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B924792"
        },
        [11013606] = {
