          },
          NextDialogue = 11013640,
          Scripts = "PARA{\nPlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/faluxi_step\"},PlayAs2D{true}},\nSEQ{\nLookAt{LookAtDescription{\"110012:n(110012)\"}},\nMoveTo{_delay{1.5},ActorId{110012},TargetPoint{\"pFalumove19\"},MoveSpeed{120},Visibility{\"Hide\"}}\n},\nPARA{\nTurnTo{_delay{2.5},TurnToDescription{\"100346:p(-140)\"}},\nTurnTo{_delay{2.5},TurnToDescription{\"100343:p(-100)\"}},\nTurnTo{_delay{2.5},TurnToDescription{\"100344:p(-60)\"}},\nTurnTo{_delay{2.5},TurnToDescription{\"100342:p(90)\"}},\nTurnTo{_delay{2.5},TurnToDescription{\"100340:p(124)\"}},\nTurnTo{_delay{2.5},TurnToDescription{\"100341:p(150)\"}}\n},\nPARA{\nMoveTo{_delay{4},ActorId{100346},TargetPoint{\"BP_EX01_FixSimple_19_shibin01\"},MoveSpeed{120},Visibility{\"Hide\"}},\nMoveTo{_delay{4},ActorId{100343},TargetPoint{\"BP_EX01_FixSimple_19_shibin02\"},MoveSpeed{120},Visibility{\"Hide\"}},\nMoveTo{_delay{4},ActorId{100344},TargetPoint{\"BP_EX01_FixSimple_19_shibin03\"},MoveSpeed{120},Visibility{\"Hide\"}},\nMoveTo{_delay{4},ActorId{100342},TargetPoint{\"BP_EX01_FixSimple_19_shibin04\"},MoveSpeed{120},Visibility{\"Hide\"}},\nMoveTo{_delay{4},ActorId{100340},TargetPoint{\"BP_EX01_FixSimple_19_shibin05\"},MoveSpeed{120},Visibility{\"Hide\"}},\nMoveTo{_delay{4},ActorId{100341},TargetPoint{\"BP_EX01_FixSimple_19_shibin06\"},MoveSpeed{120},Visibility{\"Hide\"}}\n}\n}",
          SpeakNpcId = 110012,
          Subtitle = "Yes, sir. I shall wait outside the door.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924810"
        },
        [11013609] = {
          Camera = "-427.870239,2258.052734,924.980835,0.000026,-20.399008,-74.736588,35.000011,271.648438,false,DoNotOverride,2.652164",
          ContentFR = "Dis-moi plutôt pourquoi tu as fabriqué ces faux témoignages. Tu crois vraiment que les hauts gradés sont tous des imbéciles ?",
          DialogueId = 11013609,
          Duration = 3,
          FinalCamera = "-427.870239,2258.052734,892.516418,0.000027,-20.399042,-74.737274,35.000011,271.648438,false,DoNotOverride,20.0",
          GUID = "1B92483A",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013610,
          SpeakNpcId = 110010,
          Subtitle = "Now, why bother making up all this false evidence? You really think the higher-ups are that stupid?",
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92483A"
        },
        [11013610] = {
          Camera = "-89.605194,-418.919922,28.023407,-10.014737,8.201615,53.252785,35.0,271.651154,false,DoNotOverride,20.0",
          ContentFR = "Justement parce qu’il y a des gens intelligents au sommet qu’ils feignent l’ignorance. Réfléchis, Avar, si j’ose aller aussi loin, c’est bien parce que quelqu’un le veut.",
          DialogueId = 11013610,
          Duration = 3,
          GUID = "1B924864",
          NextDialogue = 11013611,
          Scripts = "PARA{\nSEQ{\nCameraMoveTo{_delay{5},TargetPosition{\"-427.870239,2258.052734,892.516418,0.000025,-20.399035,-74.737183,35.000011,271.648438,false,DoNotOverride,20.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-412.960815,2203.416016,871.454102,0.000026,-20.399035,-74.737061,35.000011,271.648438,false,DoNotOverride,20.0\"},duration{6}}\n},\nMoveTo{_delay{5},ActorId{110011},TargetPoint{\"EX01_FixSimple_19point01\"},MoveSpeed{105},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 110011,
          Subtitle = "Of course not. They're actually smart enough to turn a blind eye and play along. Use your head, Avar. Why do you think I dare to make this bold move? It's naturally because someone wants me to.",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924864"
        },
        [11013611] = {
          Camera = "199.207306,49.052734,103.883209,-0.001587,-1.196615,95.62352,35.0,439.465851,false,DoNotOverride,22.0",
          ContentFR = "Et puisque tu es déjà un homme mort, je vais avoir la bonté de t’éclairer avant ton dernier souffle.",
          DialogueId = 11013611,
          Duration = 3,
          FinalCamera = "196.638626,75.138672,103.335693,-0.001587,-1.196615,95.62352,35.0,439.465851,false,DoNotOverride,22.0",
          GUID = "1B92488E",
          NextDialogue = 11013612,
          Scripts = "PlayAnimation{_delay{1},ActorId{110011},AnimationId{"Talk03_Start"},Duration{6}}",
          SpeakNpcId = 110011,
          Subtitle = "Since you're a goner already, I'll show some mercy so you won't die a fool.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92488E"
        },
        [11013612] = {
          Camera = "34.140366,-340.748047,894.160034,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0",
          ContentFR = "Quand Sa Majesté monta sur le trône, à l’époque où le Duc Servius faisait office de régent, ils ont trahi les règles séculaires d’Hyperborea, en greffant trop de branches pourries à l’arbre de l’Empire.",
          DialogueId = 11013612,
          Duration = 3,
          FinalCamera = "195.783936,-345.769531,815.577393,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0",
          GUID = "1B9248B8",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013613,
          RelatedWikiId = {
            [1] = 201017
          },
          Scripts = "SEQ{\nCameraMoveTo{_delay{7},TargetPosition{\"-742.495117,843.439453,633.784912,0.00004,-27.596544,-31.344604,30.0,271.651154,false,DoNotOverride,20.0\"},duration{0}},CameraMoveTo{TargetPosition{\"-832.090454,898.013672,688.620361,0.00004,-27.596523,-31.344666,30.0,271.651154,false,DoNotOverride,20.0\"},duration{8}}\n}",
          SpeakNpcId = 110011,
          Subtitle = "When His Majesty was first crowned, Duke Servius was our Imperial Regent. But the Regency strayed from established Hyperborean traditions and grafted too many useless scions onto the great Imperial oak.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110010:n(110011)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B9248B8"
        },
        [11013613] = {
          Camera = "195.79921,146.666016,102.814026,-0.001556,-1.197421,101.018288,35.000011,216.948959,false,Manual,8.0",
          ContentFR = "Ils ont même inventé ce soi-disant titre de "Charon Couronné", vous laissant entrer au Conseil Stratégique et dans les Légions, allant jusqu’à vous confier des postes élevés... quelle absurdité.",
          DialogueId = 11013613,
          Duration = 3,
          FacialId = {
            [1] = "110011:Unhappy01"
          },
          FinalCamera = "194.398621,153.863281,102.660858,-0.001556,-1.197421,101.018288,35.000011,216.948959,false,Manual,8.0",
          GUID = "1B9248E2",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013614,
          RelatedWikiId = {
            [1] = 101008
          },
          Scripts = "LookAt{_delay{6.5},LookAtDescription{"110011:n(110011)"}}",
          SpeakNpcId = 110011,
          Subtitle = "Those fools allowed Charons into the Military Council and the Legion, and even appointed a few — like you — into high offices. This is ridiculous.",
          TalkActionId = {
            [1] = "110011:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9248E2"
        },
        [11013614] = {
          Camera = "-129.604523,471.810547,-28.501526,0.000752,21.988857,-30.575706,23.640343,100000.0,false,DoNotOverride,2.654159",
          ContentFR = "Même si Sa Majesté a depuis reconnu ses erreurs, ces branches corrompues demeurent. Moi, je ne fais que l’aider à émonder l’arbre.",
          DialogueId = 11013614,
          Duration = 3,
          FinalCamera = "-40.557144,495.207031,55.238251,-10.00088,13.201608,-42.578636,30.0,229.467407,false,DoNotOverride,22.0",
          GUID = "1B92490C",
          NextDialogue = 11013615,
          Scripts = "PARA{\nPlayAnimation{_delay{12},ActorId{110011},AnimationId{\"Angry02_Start\"},Duration{10}},\nPlayAnimation{_delay{16},ActorId{110011},AnimationId{\"Angry02_End\"},Duration{0}},\nCameraMoveTo{_delay{10},TargetPosition{\"46.070709,353.451172,80.537964,0.000758,-1.611453,15.627573,23.640345,100000.0,false,DoNotOverride,2.65416\"},duration{0}}\n}\n",
          SpeakNpcId = 110011,
          Subtitle = "Though His Majesty is now aware of these mistakes, they continue to plague us. I'm merely helping him prune the oak.",
          ToFinalCameraBlendTime = 12,
          TurnTo = {
            [1] = "110011:p(45)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B92490C"
        },
        [11013615] = {
          Camera = "52.397644,381.144531,96.864655,0.0,-0.198417,-44.378803,30.000019,229.46875,false,Manual,22.0",
          ContentFR = "... Alors tout ça, c’est parce que tu ne supportes pas que je sois un Charon.",
          DialogueId = 11013615,
          Duration = 3,
          FinalCamera = "60.468475,373.251953,96.8255,0.0,-0.198417,-44.378376,30.000019,229.46875,false,Manual,22.0",
          GUID = "1B924936",
          NextDialogue = 11013616,
          SpeakNpcId = 110010,
          Subtitle = "...So you went through all the trouble, just because you don't like Charons?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924936"
        },
        [11013616] = {
          Camera = "-819.513733,862.818359,733.592957,0.000003,-32.798332,-28.176556,30.0,229.467407,false,DoNotOverride,22.0",
          ContentFR = "Dans ce cas, tu aurais dû le dire tout de suite, au lieu d’en arriver là. Si tu me laisses sortir vivant, je trouverai bien un moyen de prendre ma retraite plus tôt. Je ne te gênerai plus jamais.",
          DialogueId = 11013616,
          Duration = 3,
          FacialId = {
            [1] = "110011:None"
          },
          FinalCamera = "-931.609741,922.859375,815.540222,0.000003,-32.798332,-28.176556,30.0,229.467407,false,DoNotOverride,22.0",
          GUID = "1B924960",
          NextDialogue = 11013617,
          Scripts = "SEQ{\nPlayAnimation{_delay{4},ActorId{110010},AnimationId{\"Talk01_End\"},Duration{0}},\nPlayAnimation{_delay{4},ActorId{110011},AnimationId{\"Talk03_Start\"},Duration{10}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "You should've told me earlier. There's no need for such an elaborate ruse. Just let me off this time, and I'll retire early and stay out of your way forever.",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924960"
        },
        [11013617] = {
          Camera = "153.246658,302.361328,94.305695,-10.00189,5.400207,-63.975967,28.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Et si tu veux que je t’apporte ma loyauté, je peux aussi. Il suffirait de rejeter sur {性别2:lui|elle} la fuite des plans de bataille. Nous serions blanchis tous les deux, et même félicités pour avoir démasqué un espion. Et puis...",
          DialogueId = 11013617,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "157.790649,293.052734,95.28479,-10.00189,5.400207,-63.975967,28.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B92498A",
          NextDialogue = 11013618,
          Scripts = "SEQ{\nCameraMoveTo{_delay{6},TargetPosition{\"549.498535,2849.632812,-810.490845,5.001147,-28.793985,-88.214127,50.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{TargetPosition{\"552.933838,2849.892578,-810.754639,5.001147,-28.793985,-88.214127,50.0,100000.0,false,DoNotOverride,22.0\"},duration{10}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "If you need my loyalty, I can do that too. We can blame {性别2:him|her} for leaking our battle plans. Both of us walk away clean. Hell, we might even get a reward for uncovering a spy. And...",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92498A"
        },
        [11013618] = {
          Camera = "-13.393326,461.294922,163.357544,-0.000366,-19.199892,-42.771851,21.125469,100000.0,false,Manual,22.0",
          ContentFR = "... Tu aurais gagné un vieux chien docile, prêt à t’obéir.",
          DialogueId = 11013618,
          Duration = 3,
          FinalCamera = "-13.393326,461.294922,154.910889,-0.000366,-19.199892,-42.771851,21.125469,100000.0,false,Manual,22.0",
          GUID = "1B92498B",
          NextDialogue = 11013619,
          Scripts = "SEQ{\nPlayAnimation{_delay{4},ActorId{110011},AnimationId{\"Talk03_End\"},Duration{0}},\nPARA{LookAt{LookAtDescription{\"110011:n(110010)\"}},\nTurnTo{TurnToDescription{\"110011:n(110010)\"}}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "You'll gain an old dog obedient enough to follow your orders.",
          TalkActionId = {
            [1] = "110010:Talk01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92498B"
        },
        [11013619] = {
          Camera = "168.977859,253.941406,61.364716,-8.000504,16.603903,108.03064,21.125483,146.883423,false,Manual,5.0",
          ContentFR = "Ah ! Qui aurait cru que toi aussi tu tomberais si bas ? Mais tu te berces d’illusions, Avar. Tu vaux bien plus mort que vivant.",
          DialogueId = 11013619,
          Duration = 3,
          FacialId = {
            [1] = "110011:Smile01",
            [2] = "110010:Think01"
          },
          FinalCamera = "168.977859,253.941406,58.862396,-8.000504,16.603903,108.03064,21.125483,146.883423,false,Manual,5.0",
          GUID = "1B9249B4",
          NextDialogue = 11013620,
          Scripts = "SEQ{\nCameraMoveTo{_delay{10},TargetPosition{\"118.145653,292.558594,103.879425,-3.0,-0.795013,-46.971291,30.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"124.55114,285.693359,103.749207,-3.0,-0.795013,-46.971291,30.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}\n}\n\t",
          SpeakNpcId = 110011,
          Subtitle = "Hah, how quaint, Avar — didn't expect you to stoop this low too. But you don't know the half of it, Avar. You're worth far more to us dead than alive.",
          TalkActionId = {
            [1] = "110011:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9249B4"
        },
        [11013620] = {
          Camera = "156.654633,254.740234,116.599792,-8.003376,-6.396171,107.63237,35.0,146.883423,false,DoNotOverride,5.0",
          ContentFR = "Réfléchis ! Imagine ce qui se passera quand l’Empire entier apprendra qu’un officier Charon a trahi la Légion pour rejoindre les Déchus, et causé la mort de tant de jeunes soldats d’élite...",
          DialogueId = 11013620,
          Duration = 3,
          FacialId = {
            [1] = "110010:None"
          },
          FinalCamera = "148.843872,279.322266,115.388702,-8.003376,-6.396171,107.63237,35.0,146.883423,false,DoNotOverride,5.0",
          GUID = "1B9249DE",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013621,
          Scripts = "SEQ{\nPlayAnimation{_delay{3},ActorId{110011},AnimationId{\"Sigh_Start\"},Duration{10}},\nPlayAnimation{ActorId{110011},AnimationId{\"Sigh_End\"},Duration{3}}\n}\n",
          SpeakNpcId = 110011,
          Subtitle = "Use your head! Imagine the uproar if it came out that a high-ranking Charon officer defected and joined The Forsakens, resulting in the deaths of many of our best young soldiers.",
          TalkActionId = {
            [1] = "110011:Talk02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9249DE"
        },
        [11013621] = {
          Camera = "169.007309,92.732422,41.227081,-10.000513,6.204441,84.826546,21.125471,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Les Charons Couronnés sont déjà sous le feu des critiques. Crois-tu qu’ils pourront encore garder leurs sièges après un tel scandale ? Pense à notre chère supérieure... Tu sais combien de vautours guettent sa chute.",
          DialogueId = 11013621,
          Duration = 3,
          FinalCamera = "139.76091,94.824219,46.366302,-10.000513,6.204441,84.826546,21.125471,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924A08",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013622,
          Scripts = "SEQ{\nPlayAnimation{_delay{5},ActorId{110011},AnimationId{\"Talk03_End\"},Duration{5}},\nPlayAnimation{ActorId{110011},AnimationId{\"Talk02_Start\"},Duration{0}}\n}\n",
          SpeakNpcId = 110011,
          Subtitle = "High-ranking Charons are already a thorn in many's flesh. Such a scandal will discredit them. Take our beloved superior — do you know how many people wish to see her crash and burn?",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A08"
        },
        [11013622] = {
          Camera = "9.816498,408.683594,91.287811,-0.001526,-0.599793,-38.348438,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Sibylle ? Tu veux la faire tomber... Tu vises son commandement ?",
          DialogueId = 11013622,
          Duration = 3,
          FinalCamera = "11.8965,401.550781,91.224274,-0.001526,-0.599793,-38.34877,35.0,100000.0,false,Manual,22.0",
          GUID = "1B924A32",
          NextDialogue = 11013623,
          SpeakNpcId = 110010,
          Subtitle = "You mean Sibylle? You wish her gone... You're after her position and power?",
          TalkActionId = {
            [1] = "110011:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A32"
        },
        [11013623] = {
          Camera = "54.786392,-620.46875,9.960114,0.000071,7.403973,84.185303,22.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Peut-être. Peut-être davantage. Mais ce ne sont plus tes affaires.",
          DialogueId = 11013623,
          Duration = 3,
          FinalCamera = "27.690643,-617.716797,9.960114,0.000071,7.403973,84.185303,22.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924A5C",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013624,
          Scripts = "PARA{\nMoveTo{_delay{5},ActorId{110011},TargetPoint{\"EX01_FixSimple_19point02\"},MoveSpeed{65},Visibility{\"Show\"}},\nCameraMoveTo{_delay{6},TargetPosition{\"110.352188,24.90625,106.656708,0.000074,-3.195859,90.185249,40.000023,100000.0,false,DoNotOverride,22.0\"},duration{0}}\n}",
          SpeakNpcId = 110011,
          Subtitle = "Perhaps. Maybe I want more. But that's no longer your concern.",
          TalkActionId = {
            [1] = "110011:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A5C"
        },
        [11013624] = {
          Camera = "-62.074799,-566.730469,491.808014,-0.001556,-31.999592,75.647636,16.661533,100000.0,false,Manual,22.0",
          ContentFR = "Attends !",
          DialogueId = 11013624,
          Duration = 3,
          GUID = "1B924A86",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013625,
          SpeakNpcId = 110010,
          Subtitle = "Wait!",
          TurnTo = {
            [1] = "110010:n(110011)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A86"
        },
        [11013625] = {
          Camera = "-62.074799,-566.730469,491.808014,-0.001556,-31.999592,75.647636,16.661533,100000.0,false,Manual,22.0",
          ContentFR = "Parlons d’autre chose... <H>n° 0</>.",
          DialogueId = 11013625,
          Duration = 3,
          FacialId = {
            [1] = "110011:None"
          },
          GUID = "1B924AB0",
          NextDialogue = 11013626,
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{"175.50206,126.912109,133.876068,-0.001556,-18.199461,67.248505,40.000011,100000.0,false,DoNotOverride,22.0"},duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "We should talk about one more thing... About No. 0.",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924AB0"
        },
        [11013626] = {
          Camera = "151.601776,151.322266,102.676727,-0.001556,-4.801548,-108.713249,23.660721,100000.0,false,Manual,22.0",
          ContentFR = "... Oh ?",
          DialogueId = 11013626,
          Duration = 3,
          GUID = "1B924ADA",
          NextDialogue = 11013627,
          Scripts = "TurnTo{_delay{2},TurnToDescription{"110011:p(180)"}}",
          SpeakNpcId = 110011,
          Subtitle = "...Oh?",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924ADA"
        },
        [11013627] = {
          Camera = "63.279358,-238.914062,88.206848,-0.002014,-2.614016,77.062973,23.660721,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Elle est l’arme la plus précieuse de la XIIIᵉ Légion. Sibylle la détient, certes. Mais pour mener à bien le <H>Projet Nouvel Héritier</>, il manque encore l’élément essentiel : le <H>"Catalyseur"</>.",
          DialogueId = 11013627,
          Duration = 3,
          FinalCamera = "-60.852264,-120.474609,97.3927,-0.002014,-5.013919,43.262783,23.660721,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924B04",
          NextDialogue = 11013628,
          RelatedWikiId = {
            [1] = 403003
          },
          SpeakNpcId = 110010,
          Subtitle = "She is the most precious weapon of the 13th Legion. Sibylle controls her now, but to complete the Second Scion Program, she still needs the crucial "Catalyst"...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B04"
        },
        [11013628] = {
          Camera = "155.250778,120.773438,83.251434,10.002668,12.003586,50.623306,21.125479,95.12989,false,Manual,2.8",
          ContentFR = "Sibylle t’a envoyé chercher le Catalyseur à Flagson, mais il me semble que tes recherches n’ont pas été très fructueuses.",
          DialogueId = 11013628,
          Duration = 3,
          FinalCamera = "159.07251,125.427734,84.532227,10.002668,12.003586,50.623306,21.125483,89.517586,false,Manual,2.8",
          GUID = "1B924B2E",
          NextDialogue = 11013629,
          SpeakNpcId = 110010,
          Subtitle = "Sibylle has ordered you to find the Catalyst in Flagson. But your search doesn't seem to be enjoying much success.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B2E"
        },
        [11013629] = {
          Camera = "99.726173,78.669922,83.391571,-10.008635,12.003312,-82.168861,21.125483,99.930809,false,Manual,2.8",
          ContentFR = "Qu’est-ce que tu essaies de dire ? Va droit au but.",
          DialogueId = 11013629,
          Duration = 3,
          FinalCamera = "100.516411,72.925781,84.624756,-10.008635,12.003312,-82.168861,21.125483,99.930809,false,Manual,2.8",
          GUID = "1B924B58",
          NextDialogue = 11013630,
          SpeakNpcId = 110011,
          Subtitle = "Get to the point, Avar.",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B58"
        },
        [11013630] = {
          Camera = "-540.700623,825.572266,22.562286,-5.000006,2.003171,-46.767361,40.000023,271.651154,false,DoNotOverride,10.0",
          ContentFR = "Fulvis, il existe plus d’un chemin vers le commandement. Même si ton petit numéro parvient à écarter Sibylle, qui te dit que l’Empereur te choisira pour la remplacer ?",
          DialogueId = 11013630,
          Duration = 3,
          FinalCamera = "-522.103577,843.160156,24.800446,-5.000006,2.003171,-46.767361,40.000023,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924B82",
          NextDialogue = 11013631,
          Scripts = "PlayAnimation{_delay{6},ActorId{110010},AnimationId{"Talk01_End"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "There are many paths to power, Fulvis. Even if this charade pushes Sibylle off her seat, how can you be sure the Emperor will let you take her place?",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B82"
        },
        [11013631] = {
          Camera = "188.38916,374.509766,107.291229,-10.011471,-3.196467,-95.968758,40.000011,271.651154,false,DoNotOverride,13.0",
          ContentFR = "Ce qu’il te faut, c’est un mérite unique, inégalable.",
          DialogueId = 11013631,
          Duration = 3,
          FinalCamera = "186.448547,355.947266,106.248871,-10.011503,-3.196467,-95.968758,40.000011,271.651154,false,DoNotOverride,13.0",
          GUID = "1B924BAC",
          NextDialogue = 11013632,
          SpeakNpcId = 110010,
          Subtitle = "You need some kind of unparalleled credit to propel you to the Legion's head.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924BAC"
        },
        [11013632] = {
          Camera = "96.940521,78.816406,89.251038,-10.007017,12.402838,-85.163452,40.000023,271.651154,false,DoNotOverride,10.0",
          ContentFR = "Continue.",
          DialogueId = 11013632,
          Duration = 3,
          GUID = "1B924BD6",
          NextDialogue = 11013633,
          SpeakNpcId = 110011,
          Subtitle = "I'm listening.",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924BD6"
        },
        [11013633] = {
          Camera = "-2118.515137,-306.582031,571.609009,0.00001,-10.997062,16.436613,40.0,271.651154,false,DoNotOverride,10.0",
          ContentFR = "Le Projet Nouvel Héritier est vital pour l’Empire. Il vaut bien plus qu’une centaine de forteresses de Lonza. Si tu trouves le Catalyseur, la dernière pièce du puzzle, la capitale tout entière scandera ton nom, Antonius Fulvis.",
          DialogueId = 11013633,
          Duration = 3,
          FinalCamera = "-2147.418945,-208.613281,571.609009,0.00001,-10.997062,16.436708,40.0,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924C00",
          NextDialogue = 11013634,
          SpeakNpcId = 110010,
          Subtitle = "The Second Scion Program is too important to the Empire. It's worth far more than a hundred Lonza Fortresses combined. If you find the "Catalyst," which is the final piece of the puzzle, the entire capital will chant your name — Antonius Fulvis.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C00"
        },
        [11013634] = {
          Camera = "206.033554,354.041016,73.645569,0.000024,1.20283,-101.165855,40.0,271.651154,false,DoNotOverride,10.0",
          ContentFR = "Voilà l’exploit qui te propulsera au sommet. Et, par un heureux hasard, j’en connais l’emplacement. Aujourd’hui, je suis prêt à te le céder.",
          DialogueId = 11013634,
          Duration = 3,
          FinalCamera = "201.324173,330.189453,74.156342,0.000024,1.20283,-101.165855,40.0,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924C2A",
          NextDialogue = 11013635,
          Scripts = "SEQ{\nCameraMoveTo{_delay{8},TargetPosition{\"-29.667725,-114.439453,111.371826,0.000021,-2.396822,48.637676,60.0,271.651154,false,DoNotOverride,10.0\"},duration{0}},CameraMoveTo{TargetPosition{\"-10.139755,-92.255859,109.041138,0.000021,-2.396822,48.637676,60.0,271.651154,false,DoNotOverride,10.0\"},duration{8}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "It's the unparalleled credit you need. And I, by circumstance and chance, happen to know of its whereabouts. I am willing to concede this to you.",
          TalkActionId = {
            [1] = "110011:Talk03_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C2A"
        },
        [11013635] = {
          Camera = "85.258636,144.519531,44.719849,0.000028,19.801844,-82.964874,40.000027,271.651154,false,DoNotOverride,10.0",
          ContentFR = "Là, tu commences à m’intéresser.",
          DialogueId = 11013635,
          Duration = 3,
          FinalCamera = "86.617958,133.511719,48.716034,0.000028,19.801844,-82.964874,40.000027,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924C54",
          NextDialogue = 11013636,
          SpeakNpcId = 110011,
          Subtitle = "Now we're talking.",
          TalkActionId = {
            [1] = "110011:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C54"
        },
        [11013636] = {
          Camera = "99.722374,88.037109,96.940674,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0",
          ContentFR = "C’est ma proposition. En échange, je veux ta promesse : épargne-moi, ainsi que mes soldats.",
          DialogueId = 11013636,
          Duration = 3,
          GUID = "1B924C7E",
          NextDialogue = 11013637,
          Scripts = "SEQ{\nCameraMoveTo{_delay{8},TargetPosition{\"150.76915,147.746094,105.232941,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0\"},duration{0}},CameraMoveTo{TargetPosition{\"157.346924,153.925781,105.611877,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0\"},duration{8}}\n}",
          SpeakNpcId = 110010,
          Subtitle = "That would be my end of the deal. All I ask in return is for you to spare me and my troops — my daughter is among them, so I have to make sure they're safe.",
          TalkActionId = {
            [1] = "110011:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C7E"
        },
        [11013637] = {
          Camera = "116.448387,93.667969,95.850342,0.000025,5.602879,-99.561935,40.0,271.651154,false,DoNotOverride,10.0",
          ContentFR = "Quel brave commandant, toujours soucieux de ses hommes ! Très bien. Alors, dis-moi ici et maintenant où se trouve le Catalyseur. Pas de ruse, pas de délai. Tu n’as aucun moyen de négocier.",
          DialogueId = 11013637,
          Duration = 3,
          GUID = "1B924CA8",
          NextDialogue = 11013638,
          Scripts = "SEQ{\nCameraMoveTo{_delay{5},TargetPosition{\"-608.948547,3198.607422,754.886475,0.000048,-12.996736,-70.159851,40.0,271.651154,false,DoNotOverride,10.0\"},duration{0}},CameraMoveTo{TargetPosition{\"-547.46936,3220.791016,754.886475,0.000048,-12.996736,-70.159851,40.0,271.651154,false,DoNotOverride,10.0\"},duration{8}}\n}",
          SpeakNpcId = 110011,
          Subtitle = "What a loving father! Alright, tell me where the "Catalyst" is, here and now, and don't try to pull any tricks — you don't have leverage.",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B924CA8"
        },
        [11013638] = {
          Camera = "56.335129,-55.574219,108.552826,0.000057,-1.196704,55.040733,60.0,271.651154,false,Manual,20.0",
          ContentFR = "D’accord. Il est...",
          DialogueId = 11013638,
          Duration = 3,
          FinalCamera = "61.549301,-48.115234,108.362793,0.000057,-1.196704,55.040733,60.0,271.651154,false,Manual,20.0",
          GUID = "1B924CD2",
          NextDialogue = 11013639,
          SpeakNpcId = 110010,
          Subtitle = "Fine. It's at...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924CD2"
        },
        [11013639] = {
          Camera = "116.628403,103.859375,152.601593,0.000028,-21.397213,-99.75634,60.000019,271.651154,false,DoNotOverride,20.0",
          ContentFR = "Hmm. Je vois. Et maintenant, il ne me reste plus qu’une dernière chose à faire...",
          DialogueId = 11013639,
          Duration = 3,
          FinalCamera = "114.449196,91.181641,147.562653,0.000028,-21.397213,-99.75634,60.000019,271.651154,false,DoNotOverride,20.0",
          GUID = "1B924CFC",
          SpeakNpcId = 110011,
          Subtitle = "Oh, thanks. As for now, I just need one last thing...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924CFC"
        },
        [11013640] = {
          DialogueId = 11013640,
          DialoguePanelType = "None",
          Duration = 6,
          GUID = "1B924811",
          IsBlack = 1,
          NextDialogue = 11013609
        },
        [11013701] = {
          ContentFR = "Souviens-toi, Avar, on ne fait jamais confiance à un pragmatique.",
          DialogueId = 11013701,
          Duration = 3,
          GUID = "1B925752",
          SpeakNpcId = 110011,
          Subtitle = "Remember, Avar, never trust a pragmatist.",
          VoiceName = "voice/$Locale$/story/1002/110137/1B925752"
        },
        [11013702] = {
          ContentFR = "Falsi, tu restes. Nettoie-moi ça.",
          DialogueId = 11013702,
          Duration = 3,
          GUID = "1B92577C",
          IsBlack = 1,
          NextDialogue = 11013703,
          SpeakNpcId = 110011,
          Subtitle = "Stay behind, Falsi. Clean up this mess.",
          VoiceName = "voice/$Locale$/story/1002/110137/1B92577C"
        },
        [11013703] = {
          ContentFR = "À vos ordres.",
          DialogueId = 11013703,
          Duration = 3,
          GUID = "1B9257A6",
          IsBlack = 1,
          NextDialogue = 11019301,
          SpeakNpcId = 110012,
          Subtitle = "Yes, sir.",
          VoiceName = "voice/$Locale$/story/1002/110137/1B9257A6"
        },
        [11013705] = {
          ContentFR = "... Un micro-enregistreur ? {性别2:Il|Elle} avait ça sur {性别2:lui|elle} ?",
          DialogueId = 11013705,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9257FA",
          IsBlack = 1,
          NextDialogue = 11013706,
          Scripts = "StopNormalSound{EventPath{"event:/sfx/common/story/ex01/searchcloth"},PlayAs2D{true}}",
          SpeakNpcId = 110012,
          Subtitle = "...A mini recording device...? Why would {性别2:he|she} have this?",
          VoiceName = "voice/$Locale$/story/1002/110137/1B9257FA"
        },
        [11013706] = {
          ContentFR = "Lieutenant-colonel Avar Hrodland, aucune instruction reçue. Précepte n° 17 de la Légion Hyperboréenne : « Obéir aux ordres, faire confiance à ses camarades : voilà ce qui assure ta survie sur le champ de bataille. »",
          DialogueId = 11013706,
          Duration = 3,
          GUID = "1B925824",
          IsBlack = 1,
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Lieutenant Colonel Avar Hrodland, you have yet to enter any command. Motto 17 of the Hyperborean Legion: Obeying orders and trusting your comrades give you a better chance of survival on the battlefield.",
          VoiceName = "voice/$Locale$/story/1002/110137/1B925824"
        },
        [11013801] = {
          ContentFR = "<W>... Ne sombre pas dans le néant éternel...</>",
          DialogueId = 11013801,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9267BA",
          NextDialogue = 11013802,
          Scripts = "PARA{\nPlayNormalSound{\nEventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}\n}}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Do not indulge in the eternal void...",
          VoiceName = "voice/$Locale$/story/1002/110138/1B9267BA"
        },
        [11013802] = {
          ContentFR = "<W>... Réveille-toi...</>",
          DialogueId = 11013802,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9267E4",
          NextDialogue = 11013803,
          Scripts = "PARA{\nPlayNormalSound{\nEventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}\n}}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Wake up...",
          VoiceName = "voice/$Locale$/story/1002/110138/1B9267E4"
        },
        [11013803] = {
          ContentFR = "<W>... Avant que le sang ne coule à flots comme des rivières en crue... rien n’est terminé...</>",
          DialogueId = 11013803,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B92680E",
          Scripts = "PARA{\nPlayNormalSound{\nEventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}},PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}\n}}",
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Before blood flows like swollen rivers... This is far from over...",
          VoiceName = "voice/$Locale$/story/1002/110138/1B92680E"
        },
        [11013901] = {
          ContentFR = "... Je suis... encore en vie.",
          DialogueId = 11013901,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B927822",
          SpeakNpcId = 110022,
          Subtitle = "...I'm still... alive.",
          VoiceName = "voice/$Locale$/story/1002/110139/1B927822"
        },
        [11014001] = {
          Content = "（阿瓦尔已经没有任何生命迹象。他身上除了寻常的军刀、战术手电、损坏的通讯器外，什么都没有。）",
          DialogueId = 11014001,
          Duration = 3,
          GUID = "1B92888A",
