        [11014005] = {
          Camera = "-501.787109,-1215.910156,49.703491,0.000052,38.595211,59.516899,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Soldats de la XIIIᵉ Légion, stationnés à la Forteresse de Lonza. À compter de ce jour, Daphne Theodore, ex-infirmière des Griffons, est déclarée espionne des Déchus.",
          DialogueId = 11014005,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "-580.382324,-1169.650391,49.703491,0.000052,38.595211,59.516899,35.000008,100000.0,false,Manual,22.0",
          GUID = "1B928932",
          NextDialogue = 11014006,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/signal_on"},PlayAs2D{true}}",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_Broadcast",
          Subtitle = "Attention to all 13th Legion soldiers in Lonza Fortress. Daphne Theodore, the former Medic of Squad Griffins, is now classified as a Forsakens spy.",
          ToFinalCameraBlendTime = 10,
