          DialogueId = 11014410,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B92CBA4",
          NextDialogue = 11014411,
          SpeakNpcId = 110005,
          Subtitle = "Let's rest here until the medicine takes effect... I'll explain everything that happened outside.",
          TalkActionId = {
            [1] = "110005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CBA4"
        },
        [11014411] = {
          ContentFR = "Pas complètement nettoyé ? Il en reste un ?",
          DialogueId = 11014411,
          GUID = "1B92CBCE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
          NextDialogue = 11014412,
          SnapShot = "MEMORY",
          SpeakNpcId = 110012,
          Subtitle = "One of them got away?",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CBCE"
        },
        [11014412] = {
          ContentFR = "Oui, une femme, l’infirmière Daphne Theodore. Les blessés du détachement ont retardé le combat, elle a pu s’échapper.",
          DialogueId = 11014412,
          GUID = "1B92CBF8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
          NextDialogue = 11014413,
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Yes, ma'am. A female medic named Daphne Theodore. The vanguard squads fought back fiercely, allowing her to escape.",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CBF8"
        },
        [11014413] = {
          ContentFR = "Maintenant, les Narvals commencent à entrer dans la forteresse, mais personne d’autre ne doit savoir que nous avons éliminé l’avant-garde. Si Daphne demande de l’aide, la situation se compliquera.",
          DialogueId = 11014413,
          GUID = "1B92CC22",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
          NextDialogue = 11014414,
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "The Narwhals are entering the fortress. But no one else must know that we cleaned up the vanguards. The situation may turn for the worse if Daphne contacts them for help.",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CC22"
        },
        [11014414] = {
          ContentFR = "De plus, la situation est délicate : la Commandante Sibylle arrive à la Forteresse de Lonza. Heureusement, le plus important, Avar, est déjà hors-jeu.",
          DialogueId = 11014414,
          GUID = "1B92CC4C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
          NextDialogue = 11014415,
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "The situation is delicate. Chief Sibylle is en route to Lonza Fortress after hearing the battle has turned. Luckily, Avar is already out of the picture.",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CC4C"
        },
        [11014415] = {
          ContentFR = "Quant à Daphne... vous voulez qu’on fasse quoi exactement ?",
          DialogueId = 11014415,
          Duration = 1,
          GUID = "1B92CC76",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
          NextDialogue = 11014416,
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "As for Daphne, what do you want us to do with her...?",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CC76"
        },
        [11014416] = {
          ContentFR = "Transmettez l’ordre du Commandant Fulvis : verrouillage total de la forteresse, recherche et élimination de Daphne Theodore. Motif : elle a conspiré avec les Déchus, infiltré la Légion comme espionne et compromis le plan d’assaut.",
          DialogueId = 11014416,
          GUID = "1B92CCA0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014416.T_Story_Recall_11014416'",
          NextDialogue = 11014417,
          SnapShot = "MEMORY",
          SpeakNpcId = 110012,
          Subtitle = "Relay Commander Fulvis's order: lock down the fortress, find, and eliminate Daphne Theodore. As for the charges… claim she conspired with The Forsakens, infiltrated the Legion as a spy, and compromised the fortress assault.",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CCA0"
        },
        [11014417] = {
          ContentFR = "Reçu.",
          DialogueId = 11014417,
          Duration = 1,
          GUID = "1B92CCCA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014416.T_Story_Recall_11014416'",
          NextDialogue = 11014418,
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Yes, ma'am.",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CCCA"
        },
        [11014418] = {
          Camera = "21.570557,242.439941,39.389038,0.000078,-1.799837,-165.480621,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... Après ça...",
          DialogueId = 11014418,
          Duration = 1,
          GUID = "1B92CCF4",
          NextDialogue = 11014419,
          SpeakNpcId = 110005,
          Subtitle = "...And after that...",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CCF4"
        },
        [11014419] = {
          Camera = "-398.801025,-793.505371,51.414673,0.000073,6.400146,-113.874435,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "J’ai vérifié l’état de mes coéquipiers tout en me dirigeant vers la salle de commande centrale. J’ai eu de la chance, j’ai évité tous les soldats.",
          DialogueId = 11014419,
          FinalCamera = "-325.535645,-825.931152,51.414673,0.000073,6.400146,-113.870964,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B92CD1E",
          NextDialogue = 11014420,
          SpeakNpcId = 110005,
          Subtitle = "I checked on our squad mates while making my way to the central control room. Luckily, I avoided all the soldiers.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CD1E"
        },
        [11014420] = {
          Camera = "182.500244,280.225098,23.764893,0.000076,0.00127,-168.670517,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Mais peu importaient mes soins, mes coéquipiers étaient perdus. La plupart avaient été touchés par un tir fatal, ironie du sort... le tir parfait ne venait pas de l’ennemi, mais de nos propres hommes !",
          DialogueId = 11014420,
          FacialId = {
            [1] = "110005:Sad01"
          },
          GUID = "1B92CD48",
          NextDialogue = 11014421,
          SpeakNpcId = 110005,
          Subtitle = "But it was too late for most. They all suffered precise, fatal shots — ironically from our own men rather than the enemies.",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CD48"
        },
        [11014421] = {
          Camera = "11.563477,253.448242,41.453857,0.0,-1.000336,-159.073059,44.319668,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Voilà tout ce que je sais... Maintenant, c’est à vous de me raconter ce qui s’est passé dans la salle de commande.",
          DialogueId = 11014421,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          GUID = "1B92CD72",
          NextDialogue = 11014422,
          SpeakNpcId = 110005,
          Subtitle = "That's all I know... Now, tell me what happened in the central control room.",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CD72"
        },
        [11014422] = {
          Camera = "-156.207275,-25.750488,52.009644,0.000024,-6.59982,73.919052,35.000011,498.109375,false,Manual,22.0",
          ContentFR = "Je te dirai plus tard, ce n’est pas le moment.",
          DialogueId = 11014422,
          ExStoryInfo = "EXPlayer",
          GUID = "1B92CD9C",
          NextDialogue = 11014423,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{"DisagreeHead"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "I'll explain later, now isn't the right time.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CD9C"
        },
        [11014423] = {
          Camera = "-121.629395,166.033203,40.3479,0.000025,-1.599514,54.320049,35.000011,121.370598,false,Manual,22.0",
          ContentFR = "Mais tu as raison. Tous les soldats dans cette forteresse sont désormais des ennemis. Ils suivent les ordres de Fulvis, qui veut nous éliminer.",
          DialogueId = 11014423,
          ExStoryInfo = "EXPlayer",
          GUID = "1B92CDC6",
          NextDialogue = 11014424,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{"Explain02_Start"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "But you were right about the situation — every soldier in this fortress is now our enemy. Fulvis has ordered them to eliminate us.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CDC6"
        },
        [11014424] = {
          ContentFR = "Fulvis... c’est le traître qui a transmis le plan aux Déchus et causé tant de pertes parmi nos troupes.",
          DialogueId = 11014424,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Unhappy02"
          },
          GUID = "1B92CDF0",
          NextDialogue = 11014425,
          SpeakNpcId = 110022,
          Subtitle = "Fulvis... He's the despicable traitor who leaked our plans to The Forsakens. He's the one who decimated our squads.",
          TalkActionId = {
            [1] = "110022:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CDF0"
        },
        [11014425] = {
          Camera = "24.118896,279.948242,42.161743,0.000046,-3.600493,-154.483551,35.000011,163.920853,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 11014425,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          GUID = "1B92CE1A",
          NextDialogue = 11014426,
          SpeakNpcId = 110005,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE1A"
        },
        [11014426] = {
          Camera = "-121.629395,166.033203,40.3479,0.000025,-1.599514,54.320049,35.000011,121.370598,false,Manual,22.0",
          ContentFR = "Je vais presque mieux, merci. Ton médicament a été efficace.",
          DialogueId = 11014426,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:None"
          },
          GUID = "1B92CE44",
          LookAt = {
            [1] = "110005:n(110022)"
          },
          NextDialogue = 11014427,
          SpeakNpcId = 110022,
          Subtitle = "Thanks to your medicine, I'm feeling much better.",
          TalkActionId = {
            [1] = "110022:AgreeHead",
            [2] = "110005:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE44"
        },
        [11014427] = {
          Camera = "93.17627,284.239258,43.509888,0.000075,-3.800051,-161.083466,35.000011,498.106201,false,Manual,22.0",
          ContentFR = "Très bien. Puisque vous ne voulez pas en parler maintenant, je suppose que vous avez vos raisons. Mais puis-je poser une question ?",
          DialogueId = 11014427,
          FacialId = {
            [1] = "110005:Sad02"
          },
          GUID = "1B92CE6E",
          NextDialogue = 11014428,
          SpeakNpcId = 110005,
          Subtitle = "Fine. You must have your own reasons for withholding the information. But there's one thing I must know—",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE6E"
        },
        [11014428] = {
          Camera = "24.118896,279.948242,42.161743,0.000046,-3.600493,-154.483551,35.000011,176.170731,false,Manual,22.0",
          ContentFR = "<H>Mon père</>... Avar... a-t-il accompli sa mission ?",
          DialogueId = 11014428,
          Duration = 1,
          GUID = "1B92CE98",
          NextOptions = {
            [1] = 11014429
          },
          Scripts = "CameraMoveTo{_delay{4},TargetPosition{"-50.351318,192.186523,25.357666,0.000096,10.599087,-179.679947,46.347988,74.418938,false,Manual,22.0"},duration{0}}",
          SpeakNpcId = 110005,
          Subtitle = "My father... Avar... Did he complete his mission?",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE98"
        },
        [11014429] = {
          ContentFR = "Il l’a fait.",
          DialogueId = 11014429,
          GUID = "1B92CEC2",
          NextDialogue = 11014430,
          Subtitle = "He did."
        },
        [11014430] = {
          Camera = "-40.314697,258.415039,36.010864,0.000067,0.599554,-141.683044,31.485687,107.665756,false,Manual,22.0",
          ContentFR = "... Merci.",
          DialogueId = 11014430,
          Duration = 1,
          FacialId = {
            [1] = "110005:Smile01"
          },
          GUID = "1B92CEEC",
          NextDialogue = 11014431,
          SpeakNpcId = 110005,
          Subtitle = "...Thank you.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CEEC"
        },
        [11014431] = {
          Camera = "7.207031,193.45166,173.61792,0.000137,-45.79509,179.723953,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Adieu, papa.",
          DialogueId = 11014431,
          Duration = 1,
          FacialId = {
            [1] = "110005:Sad01"
          },
          FinalCamera = "46.467285,193.266113,213.983521,0.000137,-45.79509,179.723953,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B92CF16",
          NextDialogue = 11014432,
          Scripts = "LookAt{LookAtDescription{"110005:p(P11014401)"}}",
          SpeakNpcId = 110005,
          Subtitle = "Farewell, Dad.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CF16"
        },
        [11014432] = {
          Camera = "825.23584,-925.32959,105.616943,0.000043,-7.198575,129.922852,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Allons-y. Tant que nous serons vivants, nous trouverons un moyen de faire payer Fulvis.",
          DialogueId = 11014432,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B92CF40",
          LookAt = {
            [1] = "110005:n(110022)"
          },
          SpeakNpcId = 110022,
          Subtitle = "Let's go. So long as we're alive, we'll find a chance to make Fulvis pay.",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110005:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CF40"
        },
        [11014601] = {
          ContentFR = "Daphne Theodore et un complice non identifié se cachent actuellement dans les égouts, près du Réservoir n° 1.",
          DialogueId = 11014601,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B92EAFA",
          NextDialogue = 11014602,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Daphne Theodore and an unknown accomplice are currently hiding in the sewers near Reservoir 1.",
          VoiceName = "voice/$Locale$/story/1002/110146/1B92EAFA"
        },
        [11014602] = {
          ContentFR = "Ouvrez les vannes du Réservoir n° 1 et forcez-les à sortir !",
          DialogueId = 11014602,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B92EB24",
          NextDialogue = 11014603,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Initiate the flooding of Reservoir 1 to force them out.",
          VoiceName = "voice/$Locale$/story/1002/110146/1B92EB24"
        },
        [11014603] = {
          ContentFR = "On nous a repérés... Il faut fuir avant que tout soit inondé !",
          DialogueId = 11014603,
          Duration = 3,
          GUID = "1B92EB4E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          Subtitle = "They found us... We need to get out before this section floods completely!",
          VoiceName = "voice/$Locale$/story/1002/110146/1B92EB4E"
        },
        [11014701] = {
          ContentFR = "Niveau d’eau au-dessus du seuil de sécurité. Impossible d’ouvrir la porte. Veuillez d’abord réduire le niveau d’eau.",
          DialogueId = 11014701,
          Duration = 3,
          GUID = "1B92FB62",
          NextDialogue = 11014702,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Current water level exceeds safety threshold. Safety gate will remain closed. Reduce water level to reopen.",
          VoiceName = "voice/$Locale$/story/1002/110147/1B92FB62"
        },
        [11014702] = {
          ContentFR = "Ils contrôlent les arrivées d’eau... Mais comme c’est un réservoir, il doit forcément y avoir un système d’évacuation !",
          DialogueId = 11014702,
          Duration = 3,
          GUID = "1B92FB8C",
          NextDialogue = 11018915,
          SpeakNpcId = 110005,
          Subtitle = "They're controlling the inlets... But since this is a reservoir, it must also have drainage outlets.",
          VoiceName = "voice/$Locale$/story/1002/110147/1B92FB8C"
        },
        [11014803] = {
          ContentFR = "Ils ne peuvent pas être loin ! Faites descendre les derniers Souillés dans les tunnels !",
          DialogueId = 11014803,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B930C1E",
          NextDialogue = 11014804,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "They can't be far! Herd the remaining Filthoids into the tunnels!",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C1E"
        },
        [11014804] = {
          ContentFR = "Scellez toutes les sorties des égouts. Dès que les traîtres remonteront, exécution immédiate.",
          DialogueId = 11014804,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B930C48",
          NextDialogue = 11014805,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Seal all exits. Once they surface, we'll eliminate the traitors.",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C48"
        },
        [11014805] = {
          ContentFR = "Dépêchez-vous, le temps presse !",
          DialogueId = 11014805,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B930C72",
          NextDialogue = 11014806,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Hurry up! We're running out of time!",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C72"
        },
        [11014806] = {
          ContentFR = "... Alors dépêchons-nous aussi !",
          DialogueId = 11014806,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B930C9C",
          SpeakNpcId = 110022,
          Subtitle = "...We should hurry up too!",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C9C"
        },
        [11014901] = {
          ContentFR = "Le niveau d’eau baisse !",
          DialogueId = 11014901,
          Duration = 3,
          GUID = "1B931C32",
          SpeakNpcId = 110005,
          Subtitle = "The water's receding!",
          VoiceName = "voice/$Locale$/story/1002/110149/1B931C32"
        },
        [11015001] = {
          ContentFR = "Encore une dernière vanne !",
          DialogueId = 11015001,
          Duration = 3,
          GUID = "1B932C9A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          Subtitle = "Just one more valve!",
          VoiceName = "voice/$Locale$/story/1002/110150/1B932C9A"
        },
        [11015101] = {
          Camera = "5.064453,-47.199432,146.200714,0.000109,-3.600404,17.225021,35.0,100000.0,false,Disable,22.0",
          ContentFR = "On est en sécurité... pour l’instant.",
          DialogueId = 11015101,
          Duration = 3,
          FinalCamera = "29.699219,-39.826668,144.779388,0.000113,-2.00018,14.432239,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933D02",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015102,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201016,
            [6] = 408007,
            [7] = 101004
          },
          SpeakNpcId = 110005,
          Subtitle = "We should be safe for now...",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D02"
        },
        [11015102] = {
          ContentFR = "Là-bas, ça doit être la sortie. Mais...",
          DialogueId = 11015102,
          Duration = 3,
          GUID = "1B933D2C",
          NextDialogue = 11015103,
          SpeakNpcId = 110005,
          Subtitle = "The exit should be up ahead, but...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D2C"
        },
        [11015103] = {
          Camera = "184.916016,-61.012665,145.951035,0.000085,-1.799372,155.628265,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Ils nous attendent sûrement en embuscade.",
          DialogueId = 11015103,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "207.275391,-71.141312,146.722122,0.000085,-1.799372,155.428955,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933D56",
          NextDialogue = 11015104,
          SpeakNpcId = 110022,
          Subtitle = "They're definitely waiting to ambush us there.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D56"
        },
        [11015104] = {
          Camera = "50.191406,-61.684036,121.714935,0.000108,8.400572,23.04035,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Vous êtes grièvement {性别2:blessé|blessée}... Avons-nous vraiment une chance ? Et même si on sort de la forteresse, la Légion ne nous laissera jamais en paix... Nous serons des fugitifs à jamais, constamment en fuite devant des assassins...",
          DialogueId = 11015104,
          Duration = 3,
          FinalCamera = "32.810547,-69.076233,118.901154,0.000109,7.400571,23.039328,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933D80",
          NextOptions = {
            [1] = 11015105,
            [2] = 11015107,
            [3] = 11015110
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{"Explain02_End"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "You're heavily wounded... Is there any chance of us escaping this place...? Even if we make it out, the Legion will hunt us down... We'll be fugitives forever, constantly dodging assassins...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D80"
        },
        [11015105] = {
          ContentFR = "On n’a qu’à s’installer ici, vivre dans les égouts pour toujours.",
          DialogueId = 11015105,
          GUID = "1B933DAA",
          ImprPlusId = 1010,
          NextDialogue = 11015106,
          Subtitle = "Maybe we should just live in the sewers forever."
        },
        [11015106] = {
          Camera = "39.349609,-74.855362,160.701706,0.000115,-7.799802,25.839321,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Mais ici, il n’y a ni vivres ni vêtements suffisants... Non, s’il vous plaît, réfléchissons ensemble à une vraie solution !",
          DialogueId = 11015106,
          Duration = 3,
          FinalCamera = "23.103516,-82.726669,163.175507,0.000116,-8.599856,25.63818,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933DD4",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015111,
          SpeakNpcId = 110005,
          Subtitle = "But this place doesn't have enough food or clothing — Please, let us figure something out!",
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933DD4"
        },
        [11015107] = {
          ContentFR = "On fonce dehors et on se bat jusqu’à la mort.",
          DialogueId = 11015107,
          GUID = "1B933DFE",
          ImprPlusId = 1007,
          NextDialogue = 11015108,
          Subtitle = "We should just head out and fight to the death."
        },
        [11015108] = {
          Camera = "39.349609,-74.855362,160.701706,0.000115,-7.799802,25.839321,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Impossible... Même avec vous, vu vos blessures, nous n’avons aucune chance...",
          DialogueId = 11015108,
          Duration = 3,
          FinalCamera = "23.103516,-82.726669,163.175507,0.000116,-8.599856,25.63818,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933E28",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015109,
          SpeakNpcId = 110005,
          Subtitle = "No... You might be a skilled soldier, but you're heavily wounded. We wouldn't stand a chance...",
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933E28"
        },
        [11015109] = {
          ContentFR = "... Il doit bien y avoir une autre solution...",
          DialogueId = 11015109,
          Duration = 3,
          GUID = "1B933E52",
          NextDialogue = 11015111,
          SpeakNpcId = 110005,
          Subtitle = "...Do you have another idea...?",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933E52"
        },
        [11015110] = {
          ContentFR = "... Calmons-nous. On finira par trouver un moyen.",
          DialogueId = 11015110,
          GUID = "1B933E7C",
          ImprPlusId = 1009,
          NextDialogue = 11015111,
          Subtitle = "...Let's take a deep breath. We'll come up with something."
        },
        [11015111] = {
          Camera = "184.492188,-49.928711,137.304932,0.000086,2.99945,161.84729,35.0,100000.0,false,Disable,22.0",
          ContentFR = "...",
          DialogueId = 11015111,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "200.958984,-55.329666,136.396576,0.000086,1.799379,162.846802,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933EA6",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015112,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933EA6"
        },
        [11015112] = {
          ContentFR = "Enlève ton uniforme.",
          DialogueId = 11015112,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933ED0",
          NextDialogue = 11015113,
          SpeakNpcId = 110022,
          Subtitle = "Take off your clothes.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B933ED0"
        },
        [11015113] = {
          Camera = "-17.943359,-63.457489,146.000702,0.000093,-3.202395,18.475502,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Quoi ?",
          DialogueId = 11015113,
          Duration = 3,
          FinalCamera = "-0.720703,-57.570724,144.94313,0.000094,-3.00238,17.275826,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933EFA",
          NextDialogue = 11015114,
          SpeakNpcId = 110005,
          Subtitle = "What?",
          TalkActionId = {
            [1] = "110005:Shock04_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933EFA"
        },
        [11015114] = {
          Camera = "489.007812,-334.206299,292.918701,0.000068,-19.202305,139.670319,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Enlève ton uniforme et échange avec moi.",
          DialogueId = 11015114,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "445.892578,-297.610748,273.224854,0.000065,-19.402313,139.27037,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933F24",
          NextDialogue = 11015115,
          SpeakNpcId = 110022,
          Subtitle = "We're switching outfits.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F24"
        },
        [11015115] = {
          ContentFR = "Ils pensent que je suis {性别2:mort|morte} dans la salle de commande centrale. Ils ignorent qui est {性别2:ton|ta} complice, donc la seule cible qu’ils peuvent identifier, c’est toi.",
          DialogueId = 11015115,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F4E",
          NextDialogue = 11015116,
          SpeakNpcId = 110022,
          Subtitle = "They think I died in the central control room and they have no idea who your accomplice is. You are the only target they can identify.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F4E"
        },
        [11015116] = {
          ContentFR = "Si je me déguise en toi et que je sors en courant, l’uniforme de médecin est trop voyant pour qu’ils ne réagissent pas. Tu profiteras du chaos pour t’échapper.",
          DialogueId = 11015116,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F78",
          NextDialogue = 11015117,
          Scripts = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{"Talk02_End"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "I'll wear your uniform and make a run out there. The medic's uniform is conspicuous enough to draw their attention. You'll make your escape during the chaos.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F78"
        },
        [11015117] = {
          Camera = "30.167969,-51.420792,112.9972,0.000112,8.79729,16.678789,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Vous... vous êtes {性别2:sérieux|sérieuse} ? Nos corps n’ont rien à voir, ils verront vite que ce n’est pas moi !",
          DialogueId = 11015117,
          Duration = 3,
          FinalCamera = "49.683594,-45.570618,123.095779,0.000108,7.997291,16.280628,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933FA2",
          NextDialogue = 11015118,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{"Shock04_End"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "Are you serious? We're completely different sizes! They'll quickly realise they're chasing the wrong person!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FA2"
        },
        [11015118] = {
          Camera = "174.623047,-31.802631,151.059662,0.000112,-2.002987,168.472702,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Chaque seconde de confusion, c’est une seconde de gagnée pour toi. C’est décidé, Daphne. Ne trahis pas les dernières volontés du Commandant Avar.",
          DialogueId = 11015118,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "182.253906,-34.744297,148.60463,0.000112,-1.403016,167.073715,35.0,100000.0,false,Disable,22.0",
          GUID = "1B933FCC",
          SpeakNpcId = 110022,
          Subtitle = "The longer I can distract them, the better your chances. This is the plan, Daphne. Honour Sir Avar's last wishes.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FCC"
        },
        [11015119] = {
          ContentFR = "N’hésite pas, dépêche-toi.",
          DialogueId = 11015119,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933FF6",
          SpeakNpcId = 110022,
          Subtitle = "Don't hesitate, hurry up.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FF6"
        },
        [11015120] = {
          ContentFR = "... Non.",
          DialogueId = 11015120,
          Duration = 2,
          GUID = "1B934020",
          SpeakNpcId = 110005,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934020"
        },
        [11015121] = {
          ContentFR = "Merci... d’avoir respecté les dernières volontés de mon père.",
          DialogueId = 11015121,
          Duration = 3,
          GUID = "1B93404A",
          SpeakNpcId = 110005,
          Subtitle = "Thank you for respecting my father's wish.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93404A"
        },
        [11015122] = {
          ContentFR = "Mais... pourriez-vous, cette fois, écouter <H>mon souhait</> ?",
          DialogueId = 11015122,
          Duration = 3,
          GUID = "1B934074",
          SpeakNpcId = 110005,
          Subtitle = "But could you at least hear my wishes?",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934074"
        },
        [11015123] = {
          ContentFR = "À Dismania, il pleut souvent. Quand j’étais petite, mes camarades détestaient la pluie : elle abîmait leurs coiffures et salissait leurs jolies robes neuves.",
          DialogueId = 11015123,
          Duration = 3,
          FacialId = {
            [1] = "110005:Sad01"
          },
          GUID = "1B93409E",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015124,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201016,
            [6] = 408007,
            [7] = 101004
          },
          SpeakNpcId = 110005,
          Subtitle = "Dismania is a rainy place. When I was a little girl, all my friends hated the rain because it would mess with their hair and soil their pretty dresses.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B93409E"
        },
        [11015124] = {
          ContentFR = "Mais moi, je ne la détestais pas. Parce qu’elle ne tombait jamais sur mes épaules. À mes yeux, la pluie, ce n’était que les ronds d’eau sous mes bottes, ou les gouttelettes glissant le long d’un parapluie.",
          DialogueId = 11015124,
          Duration = 3,
          GUID = "1B9340C8",
          NextDialogue = 11015125,
          SpeakNpcId = 110005,
          Subtitle = "But I didn't hate the rain, because it never reached my shoulders. In my eyes, the rain was just little ripples sprouting around my boots and droplets dripping off the brolly.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340C8"
        },
        [11015125] = {
          ContentFR = "En grandissant, j’ai compris... Ce n’était pas la pluie que j’aimais. C’était parce que mon père était là, et qu’il prenait toute la pluie pour moi.",
          DialogueId = 11015125,
          Duration = 3,
          GUID = "1B9340F2",
          NextDialogue = 11015126,
          SpeakNpcId = 110005,
          Subtitle = "But as I grew older, I realised that rain wasn't that nice. It used to look nice, only because my dad was there to bear it for me.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340F2"
        },
        [11015126] = {
          ContentFR = "Papa... était un homme si bon, mais aussi incroyablement têtu. Toujours prêt à se sacrifier pour les autres, toujours...",
          DialogueId = 11015126,
          Duration = 3,
          GUID = "1B93411C",
          NextDialogue = 11015128,
          SpeakNpcId = 110005,
          Subtitle = "My dad is such a kind man, and such a stubborn one too. He always put others first. Always.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93411C"
        },
        [11015127] = {
          ContentFR = "...",
          DialogueId = 11015127,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934146",
          NextDialogue = 11015128,
          SpeakNpcId = 110022,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934146"
        },
        [11015128] = {
          ContentFR = "Avant ma naissance, il a rejoint la Légion pour "mériter" maman, risquant sa vie au combat. Plus tard, il nous a quittées, maman et moi, afin de "ne pas gâcher mon avenir".",
          DialogueId = 11015128,
          Duration = 3,
          GUID = "1B934170",
          NextDialogue = 11015129,
          SpeakNpcId = 110005,
          Subtitle = "Before I was born, he joined the Legion and fought hard to prove himself worthy of my mom. After I grew up, he left us because he didn't want to "soil my future."",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934170"
        },
        [11015129] = {
          ContentFR = "Dans la rue, il me défendait de l’appeler papa. Mais au fond d’une taverne, au cœur de la nuit, il criait nos noms, à maman et moi, en pleurant, ivre mort... Il portait toujours tout le poids du monde sur ses épaules...",
          DialogueId = 11015129,
          Duration = 3,
          GUID = "1B93419A",
          NextDialogue = 11015130,
          SpeakNpcId = 110005,
          Subtitle = "...In public, he'd scowl and forbid me to call him Dad. But deep in the night, he'd drunkenly shout mine and my mother's name, crying — He was always bearing the weight of everything on his own...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93419A"
        },
        [11015130] = {
          ContentFR = "Mais jamais il ne m’a demandé si c’était vraiment ce que je voulais... Tout comme vous, à cet instant, ne me demandez pas si je veux vivre en portant le poids de votre sacrifice !",
          DialogueId = 11015130,
          Duration = 3,
          GUID = "1B9341C4",
          SpeakNpcId = 110005,
          Subtitle = "But he never asked if I wanted any of this... Just like you never asked if I wanted to live knowing you sacrificed yourself for me!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341C4"
        },
        [11015131] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Ni lui, ni vous, n’avez compris... que je n’ai jamais souhaité qu’on me protège du vent et de la pluie au prix de sa propre vie. Ce que je voulais vraiment, c’est...",
          DialogueId = 11015131,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          GUID = "1B9341EE",
          NextDialogue = 11015132,
          SpeakNpcId = 110005,
          Subtitle = "Neither of you know what I actually wanted... I never wished for a hero who'd shield me from the rain. My wish is that...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341EE"
        },
        [11015132] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Disable,22.0",
          ContentFR = "S’il n’y a qu’une petite ombrelle pour abriter une seule personne... alors laissez-moi marcher à vos côtés, sous la pluie.",
          DialogueId = 11015132,
          Duration = 3,
          FinalCamera = "54.34375,-11.712122,143.421494,0.000139,-0.282503,0.470605,35.0,100000.0,false,Disable,22.0",
          GUID = "1B934218",
          NextDialogue = 11015133,
          SpeakNpcId = 110005,
          Subtitle = "If there's only room for one under the brolly, I'll brave the rain with you all.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934218"
        },
        [11015133] = {
          ContentFR = "Mon souhait est que nous nous en sortions et que nous continuions à vivre, <H>ensemble</>.",
          DialogueId = 11015133,
          Duration = 3,
          FacialId = {
            [1] = "110005:Smile01"
          },
          GUID = "1B934242",
          NextDialogue = 11015134,
          SpeakNpcId = 110005,
          Subtitle = "I wish that we make it out and live on, together.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934242"
        },
        [11015134] = {
          Camera = "148.310547,4.638587,138.830399,0.000143,6.517544,-170.927872,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Daphne...",
          DialogueId = 11015134,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "160.496094,6.583258,134.802444,0.000143,6.317535,-170.927872,35.0,100000.0,false,Disable,22.0",
          GUID = "1B93426C",
          NextDialogue = 11015135,
          SpeakNpcId = 110022,
          Subtitle = "Daphne...",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93426C"
        },
        [11015135] = {
          Camera = "54.921875,23.440533,140.073502,0.000153,1.11843,-18.329687,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Réfléchissons encore... Il doit y avoir un autre moyen. Il y a toujours un autre moyen !",
          DialogueId = 11015135,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          FinalCamera = "70.310547,18.636772,139.925446,0.000152,2.918505,-16.931318,35.0,100000.0,false,Disable,22.0",
          GUID = "1B934296",
          NextDialogue = 11015136,
          SpeakNpcId = 110005,
          Subtitle = "Let's think together… There has to be another way!",
          TalkActionId = {
            [1] = "110005:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934296"
        },
        [11015136] = {
          Camera = "-35.435547,164.474655,360.730713,0.000111,20.917017,-153.732254,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Fulvis veut nous faire taire, et il s’en sert comme prétexte en nous accusant d’espionnage. Ainsi, il laisse à nos camarades le soin de nous exécuter...",
          DialogueId = 11015136,
          Duration = 3,
          FinalCamera = "-35.435547,164.474655,327.571594,0.000111,20.717014,-153.73233,35.0,100000.0,false,Disable,22.0",
          GUID = "1B9342C0",
          NextDialogue = 11015137,
          SpeakNpcId = 110005,
          Subtitle = "Fulvis wants us silenced. That's our situation. He's labelled us as spies so that our fellow soldiers would kill us for him...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342C0"
        },
        [11015137] = {
          ContentFR = "Des Griffons et des Loups Blancs, il ne reste plus que nous deux. Tous les soldats de la forteresse obéissent à Fulvis et à son adjudante, Falsi... Toute la forteresse est sous leur contrôle...",
          DialogueId = 11015137,
          Duration = 3,
          GUID = "1B9342EA",
          NextDialogue = 11015138,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{"Think_End"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "We're the only ones left from the Griffins and Snow Wolves. Every soldier here follows Fulvis and his adjutant Falsi... Every soldier in the fortress...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342EA"
        },
        [11015138] = {
          Camera = "43.673828,56.272556,139.847488,0.000149,0.117582,-27.726179,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Attendez... je crois que j’ai une idée ! Papa m’a souvent répété qu’une retraite stratégique pouvait servir de couverture à une avancée. Parfois, les plus grands risques mènent à la victoire.",
          DialogueId = 11015138,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "58.037109,42.618416,142.168106,0.000149,1.317605,-24.925119,35.0,100000.0,false,Disable,22.0",
          GUID = "1B934314",
          NextDialogue = 11015139,
          SpeakNpcId = 110005,
          Subtitle = "Wait, I have an idea...! Father once said a strategic retreat could be a cover for an advance. Sometimes the greatest risks lead to victory.",
          TalkActionId = {
            [1] = "110005:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934314"
        },
        [11015139] = {
          Camera = "7.253906,20.019621,143.611893,0.00015,-1.08212,-15.727008,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Il nous reste encore une option... Nous pouvons nous rendre.",
          DialogueId = 11015139,
          Duration = 3,
          GUID = "1B93433E",
          NextOptions = {
            [1] = 11015140,
            [2] = 11015142
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{"Explain01_End"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "We still have one option... We can turn ourselves in.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93433E"
        },
        [11015140] = {
          ContentFR = "Tu veux aller te livrer à Fulvis ?",
          DialogueId = 11015140,
          GUID = "1B934368",
          NextDialogue = 11015141,
          Subtitle = "You want to surrender to Fulvis?"
        },
        [11015141] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Non... pas à Fulvis. À <H>quelqu’un d’autre</>.",
          DialogueId = 11015141,
          Duration = 3,
          GUID = "1B934392",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          Subtitle = "No, not to Fulvis. To someone else...",
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934392"
        },
        [11015142] = {
          ContentFR = "Te livrer... à quelqu’un d’autre ?",
          DialogueId = 11015142,
          GUID = "1B9343BC",
          NextDialogue = 11015143,
          Subtitle = "Turn ourselves in... to someone else?"
        },
        [11015143] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Oui !",
          DialogueId = 11015143,
          Duration = 3,
          GUID = "1B9343E6",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          Subtitle = "Exactly!",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B9343E6"
        },
        [11015145] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Vous souvenez-vous de ce qu’a dit Falsi, dans sa transmission ?",
          DialogueId = 11015145,
          Duration = 3,
          FinalCamera = "48.234375,29.943214,125.579117,0.000142,6.717955,-19.329165,35.0,100000.0,false,Disable,22.0",
          GUID = "1B93443A",
          NextDialogue = 11015146,
          SpeakNpcId = 110005,
          Subtitle = "Remember what Falsi said in the broadcast?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93443A"
        },
        [11015146] = {
          ContentFR = "Scellez toutes les sorties. Dès que les traîtres remonteront, exécution immédiate.",
          DialogueId = 11015146,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B934464",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015147,
          SpeakNpcId = 110012,
          Subtitle = "Seal all exits. Once they surface, we'll eliminate the traitors.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934464"
        },
        [11015147] = {
          ContentFR = "Dépêchez-vous ! Le temps presse !",
          DialogueId = 11015147,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B93448E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
          NextDialogue = 11015148,
          SpeakNpcId = 110012,
          Subtitle = "Hurry up! We're running out of time!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93448E"
        },
        [11015148] = {
          Camera = "-171.576172,354.275269,321.845215,0.000118,-24.091339,-52.323902,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Puisque la Forteresse de Lonza est déjà sous la coupe de Fulvis, nous capturer n’est qu’une question de temps. Alors pourquoi Falsi se montre-t-elle si pressée ?",
          DialogueId = 11015148,
          Duration = 3,
          FinalCamera = "-196.277344,386.265381,339.917847,0.000119,-24.091339,-52.323936,35.0,100000.0,false,Disable,22.0",
          GUID = "1B9344B8",
          NextDialogue = 11015149,
          SpeakNpcId = 110005,
          Subtitle = "Lonza Fortress is currently under Fulvis's full control. We're little more than rats in a cage. Then why is Falsi in such a hurry?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344B8"
        },
        [11015149] = {
          ContentFR = "Et rappelez-vous, je vous ai dit avoir surpris un soldat murmurer que...",
          DialogueId = 11015149,
          Duration = 3,
          GUID = "1B9344E2",
          NextDialogue = 11015150,
          SpeakNpcId = 110005,
          Subtitle = "Do you remember what I overheard earlier from one of the soldiers—",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344E2"
        },
        [11015150] = {
          ContentFR = "La situation est délicate : la Commandante Sibylle arrive à la Forteresse de Lonza.",
          DialogueId = 11015150,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B93450C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015151,
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Chief Sibylle is en route to Lonza Fortress after hearing the battle has turned.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93450C"
        },
        [11015151] = {
          Camera = "154.445312,44.61274,163.534317,0.000121,-6.890936,-151.527649,35.0,100000.0,false,Disable,22.0",
          ContentFR = "... Tu veux donc chercher la protection de Sibylle.",
          DialogueId = 11015151,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "177.171875,56.903561,166.748993,0.000123,-8.491031,-151.927643,35.0,100000.0,false,Disable,22.0",
          GUID = "1B934536",
          NextDialogue = 11015152,
          SpeakNpcId = 110022,
          Subtitle = "...So you want to seek protection from Sibylle?",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934536"
        },
        [11015152] = {
          Camera = "31.996094,51.468288,139.671326,0.000175,-0.491391,-24.739786,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Oui.",
          DialogueId = 11015152,
          Duration = 3,
          GUID = "1B934560",
          NextDialogue = 11015153,
          SpeakNpcId = 110005,
          Subtitle = "Correct.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934560"
        },
        [11015153] = {
          Camera = "179.789062,39.516891,181.891464,0.000178,-14.491817,-158.539825,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Mais Fulvis a déjà forgé des accusations et préparé de faux témoignages... Attends... Je comprends, voilà pourquoi tu parlais de nous rendre.",
          DialogueId = 11015153,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93458A",
          NextDialogue = 11015154,
          SpeakNpcId = 110022,
          Subtitle = "But Fulvis has already condemned us and even fabricated evidence... Wait, I get why you want to turn ourselves in.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93458A"
        },
        [11015154] = {
          Camera = "42.076172,35.060333,133.820343,0.000195,2.508544,-21.337816,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Exactement ! La Commandante Sibylle est, elle aussi, issue de l’Académie d’Alchimie. Et d’après ce que je sais, elle ne tolérerait jamais la trahison, même venant de ses plus proches.",
          DialogueId = 11015154,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "28.144531,40.503914,129.73497,0.000195,2.508482,-21.537373,35.0,100000.0,false,Disable,22.0",
          GUID = "1B9345B4",
          NextDialogue = 11015155,
          SpeakNpcId = 110005,
          Subtitle = "Mm-hmm! Chief Sibylle is also a graduate of the Academy. From what I know of her, she wouldn't tolerate betrayal from anyone, not even those she holds dear.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345B4"
        },
        [11015155] = {
          Camera = "-191.923828,110.773376,292.437317,0.000252,-26.092831,-22.740551,35.0,100000.0,false,Disable,22.0",
          ContentFR = "... Mais pour cette raison même, elle mène toujours ses enquêtes à fond. Elle ne condamne jamais sans preuve solide, et elle ne laisserait pas exécuter des suspects avant d’avoir tout éclairci.",
          DialogueId = 11015155,
          Duration = 3,
          FinalCamera = "-139.972656,126.843193,222.647064,0.000272,-16.892361,-30.148384,35.0,100000.0,false,Disable,22.0",
          GUID = "1B9345DE",
          NextDialogue = 11015156,
          SpeakNpcId = 110005,
          Subtitle = "...Which is also why Sibylle would carefully review any acts of treason. She would not make any hasty decisions to execute the suspects because she'd want to get to the bottom of it.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345DE"
        },
        [11015156] = {
          ContentFR = "Si nous parvenons à l’approcher, le plus probable est qu’elle nous enferme dans la Prison Militaire. On dit que ses murs sont si épais qu’aucun oiseau ne saurait en sortir... Mais, de ce fait, personne ne pourra non plus venir nous faire taire.",
          DialogueId = 11015156,
          Duration = 3,
          GUID = "1B934608",
          NextDialogue = 11015157,
          SpeakNpcId = 110005,
          Subtitle = "If we manage to meet her, she's most likely to throw us into the Imperial Prison. The Prison is reputedly so well guarded that even a fly could not escape the place. But it'll also keep out anyone who wishes to silence us.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934608"
        },
        [11015157] = {
          ContentFR = "Cette prison deviendrait alors le lieu le plus sûr. Et pendant l’interrogatoire, nous pourrons prouver notre innocence. C’est notre seule chance.",
          DialogueId = 11015157,
          Duration = 3,
          GUID = "1B934632",
          NextDialogue = 11015158,
          SpeakNpcId = 110005,
          Subtitle = "The Imperial Prison will be our safest refuge. We can prove our innocence during interrogations. This is our only chance to survive.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934632"
        },
        [11015158] = {
          Camera = "47.939453,49.246361,119.444901,0.000288,8.907598,-26.339521,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Cela ternira votre honneur, évidemment... Être interrogé pour espionnage laisse toujours des traces. Mais si nous tenons bon, nous pourrons laver nos noms et démasquer les véritables traîtres.",
          DialogueId = 11015158,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          FinalCamera = "27.193359,59.519375,115.815987,0.000286,7.707581,-26.338728,35.0,100000.0,false,Disable,22.0",
          GUID = "1B93465C",
          NextDialogue = 11015159,
          SpeakNpcId = 110005,
          Subtitle = "Your reputation will suffer though, as you'll be interrogated for espionage... But once we endure the questioning, we will be able to clear our names and bring the real traitors to justice.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93465C"
        },
        [11015159] = {
          Camera = "243.919922,32.791145,139.274689,0.00031,-0.492122,-160.143555,35.0,100000.0,false,Disable,22.0",
          ContentFR = "... Être jugés pour espionnage... Y a-t-il une chance que cela fuite hors de la Légion ? Que la nouvelle parvienne jusqu’à la famille royale ?",
          DialogueId = 11015159,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "259.697266,38.494522,139.446808,0.000309,-1.092161,-160.143555,35.0,100000.0,false,Disable,22.0",
          GUID = "1B934686",
          NextDialogue = 11015160,
          SpeakNpcId = 110022,
          Subtitle = "...Being questioned for espionage... Any chance that word gets out beyond the Legion? Perhaps the royal family will hear of this?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934686"
        },
        [11015160] = {
          Camera = "49.503906,51.240067,154.416092,0.000309,-5.89185,-28.343378,35.0,100000.0,false,Disable,22.0",
          ContentFR = "Sa Majesté Julius a toujours accordé la plus haute importance à l’armée. Et comme il a lui-même fondé la XIIIᵉ Légion, je pense que oui...",
          DialogueId = 11015160,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          FinalCamera = "49.503906,51.240067,138.708191,0.000309,0.108293,-28.74304,35.0,100000.0,false,Disable,22.0",
          GUID = "1B9346B0",
          NextDialogue = 11015161,
          RelatedWikiId = {
            [1] = 201018
          },
          SpeakNpcId = 110005,
          Subtitle = "The army has always been the focus of Emperor Julius. Moreover, His Majesty personally founded the 13th Legion. I believe it will reach his ears...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346B0"
        },
        [11015161] = {
          Camera = "132.001953,71.535721,136.665466,0.000171,6.118688,-133.138336,35.0,100000.0,false,Disable,22.0",
          ContentFR = "... Dans ce cas, peut-être que <H>cette personne</> pourra nous venir en aide.",
          DialogueId = 11015161,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "143.138672,83.421745,135.787506,0.000172,4.518669,-132.938339,35.0,100000.0,false,Disable,22.0",
          GUID = "1B9346DA",
          NextDialogue = 11015162,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{"Think_End"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "Then perhaps... that person can help us.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346DA"
        },
        [11015162] = {
          ContentFR = "Très bien. Suivons ton plan. Allons trouver Sibylle.",
          DialogueId = 11015162,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934704",
          SpeakNpcId = 110022,
          Subtitle = "Alrigh, let's go with your plan and find Sibylle.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934704"
        },
        [11015163] = {
          ContentFR = "On n’a plus une seconde à perdre, allons-y !",
          DialogueId = 11015163,
          Duration = 3,
          GUID = "1B93472E",
          SpeakNpcId = 110005,
          Subtitle = "Time's against us. Let's move!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93472E"
        },
        [11015201] = {
          ContentFR = "Ainsi, j’ai saisi sa main et nous avons avancé vers ce mince rayon de lumière filtrant à travers l’entrebâillement de la porte.",
          DialogueId = 11015201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D6A",
          NextDialogue = 11015202,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "And thus, I took her hand and we stepped towards that narrow beam of sunlight piercing through the door's gap.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D6A"
        },
        [11015202] = {
          ContentFR = "Comme si nous avions franchi le seuil d’un tombeau étincelant...",
          DialogueId = 11015202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D94",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "It felt as though we were stepping into a shimmering grave of our own making...",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D94"
        },
        [11015203] = {
          ContentFR = "Épuisant nos dernières forces pour semer nos poursuivants, nous avons fini par croiser la Commandante Sibylle, arrivée tout juste à la forteresse.",
          DialogueId = 11015203,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DBE",
          NextDialogue = 11015204,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "We expended our last ounces of strength evading our pursuers, in time to meet Chief Sibylle, who had just arrived at the fortress.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DBE"
        },
        [11015204] = {
          ContentFR = "Et, comme Daphne l’avait prédit, nous avons été conduits ici.",
          DialogueId = 11015204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DE8",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "And just as Daphne had predicted, we were escorted to this very place.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DE8"
        },
        [11015301] = {
          Camera = "89.232414,-2.948067,11.488281,0.999996,-1.199982,-0.798315,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une histoire passionnante... mais qui contredit en tout point les témoignages des Narvals. Puisque vous prétendez que vous et Avar Hrodland êtes innocents, alors...",
          DialogueId = 11015301,
          Duration = 1,
          GUID = "1B935DD2",
          NextDialogue = 11019310,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201019
          },
          Scripts = "PARA{\nSEQ{\nCameraMoveTo{_delay{2.5},TargetPosition{\"-93.449196,-7.990425,2.617188,0.0,1.599883,0.401891,35.000008,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-134.447235,-8.27565,1.480469,0.0,1.599883,0.401891,35.000008,100000.0,false,DoNotOverride,2.8\"},duration{8}}\n},\nPlayOrStopBGM{PlayType{\"Play\"},\nSoundType{\"SOUND_BGM\"},\nEventPath{\"event:/bgm/cbt02/0043_story_empire\"},RelatedRegionId{102104}},\nPlayAnimation{ActorId{110039},AnimationId{\"Sit_Start\"},Duration{1}}\n}",
          SpeakNpcId = 110039,
          Subtitle = "What a riveting story, which completely contradicts the testimonies provided by the Narwhals. Since you claim that you and Avar Hrodland are innocent—",
          TurnTo = {
            [1] = "110022:n(110039)"
          },
          VoiceName = "voice/$Locale$/story/1002/110153/1B935DD2"
        },
        [11015307] = {
          Camera = "175.138626,16.254257,-15.015625,0.000019,25.795355,-21.761339,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Savez-vous seulement ce que vous êtes en train d’affirmer ?",
          DialogueId = 11015307,
          Duration = 3,
          GUID = "1B935ECE",
          NextDialogue = 11015308,
          SpeakNpcId = 110039,
          Subtitle = "...Do you have any idea what you just said?",
          VoiceName = "voice/$Locale$/story/1002/110153/1B935ECE"
        },
        [11015308] = {
          Camera = "389.865051,85.663879,11.320312,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfaitement. J’accuse officiellement Antonius Fulvis d’être l’instigateur des événements de la Forteresse de Lonza.",
          DialogueId = 11015308,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Unhappy02"
          },
          FinalCamera = "378.377686,84.125763,12.214844,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1B935EF8",
          NextDialogue = 11015309,
          SpeakNpcId = 110022,
          Subtitle = "I absolutely do. I'm formally accusing Antonius Fulvis of orchestrating the events at Lonza Fortress.",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110039:Sit_Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935EF8"
        },
        [11015309] = {
          Camera = "138.132721,33.639923,-21.648438,0.000026,20.39575,-25.164968,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et savez-vous ce qui vous attend si votre accusation contre le Colonel Fulvis s’avère infondée ?",
          DialogueId = 11015309,
          Duration = 3,
          FinalCamera = "144.695236,30.554977,-26.570312,0.000028,20.395737,-25.163847,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1B935F22",
          NextDialogue = 11015310,
          SpeakNpcId = 110039,
          Subtitle = "Then are you aware of the consequences if your accusation against Colonel Fulvis are proven false?",
          TalkActionId = {
            [1] = "110022:Talk02_End",
            [2] = "110039:Sit_Talk03ToTalkR_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935F22"
        },
        [11015310] = {
          Camera = "149.444336,-10.450867,-8.71875,0.000056,9.995599,-179.96492,25.0,100000.0,false,DoNotOverride,2.8",
