          SpeakNpcName = "UI_Npc_DreamAware",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110158/1B93B100"
        },
        [11015901] = {
          Camera = "-68.808594,-818.875,282.347656,0.000035,-15.198877,68.960663,30.000002,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Comme vous le voyez, Madame la Geôlière, je suis Daphne Theodore, la fille d’Avar Hrodland...",
          DialogueId = 11015901,
          Duration = 3,
          GUID = "1B93C042",
          LookAt = {
            [1] = "0:n(110005)"
          },
          NextDialogue = 11015902,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "As you can see, ma'am, I am Daphne Theodore, daughter of Avar Hrodland...",
          TurnTo = {
            [1] = "0:n(110005)"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C042"
        },
        [11015902] = {
          ContentFR = "Mon père... avec {nickname2}... avait prévu de se partager la récompense de la vente des informations aux Déchus...",
          DialogueId = 11015902,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93C06C",
          LookAt = {
            [1] = "110005:n(0)"
          },
          NextDialogue = 11015903,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "My father... and ... they planned to split the payment for selling intel to The Forsakens...",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          TurnTo = {
            [1] = "110005:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C06C"
        },
        [11015903] = {
          ContentFR = "... Mais au cœur de la forteresse... à cause d’un désaccord sur le partage...",
          DialogueId = 11015903,
          Duration = 3,
          GUID = "1B93C096",
          NextDialogue = 11015904,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "...But at the heart of the fortress... They disAgreeHeadd on the division of the spoils...",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C096"
        },
        [11015904] = {
          ContentFR = "Mon père... a été...",
          DialogueId = 11015904,
          Duration = 3,
          GUID = "1B93C0C0",
          NextDialogue = 11015905,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "My father... was...",
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C0C0"
        },
        [11015905] = {
          ContentFR = "... a été piégé et assassiné par {nickname2}...",
          DialogueId = 11015905,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93C0EA",
          NextDialogue = 11015906,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "He was killed in a ruse woven by  ...",
          TalkActionId = {
            [1] = "110005:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C0EA"
        },
        [11015906] = {
          ContentFR = "Et après... {性别2:il|elle} m’a trompée... sur les véritables circonstances de la mort de mon père...",
          DialogueId = 11015906,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93C114",
          NextDialogue = 11015907,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "{性别2:He|She} then deceived me about how my father died...",
          TalkActionId = {
            [1] = "110005:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C114"
        },
        [11015907] = {
          ContentFR = "Aujourd’hui, j’ai conduit l’assassin devant vous, Madame la Geôlière... et je vous implore de rendre un verdict juste et équitable...",
          DialogueId = 11015907,
          Duration = 3,
          GUID = "1B93C13E",
          NextDialogue = 11015908,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "I've brought the murderer to you, ma'am... I humbly request you to deliver a fair and just verdict...",
          TalkActionId = {
            [1] = "110005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C13E"
        },
        [11015908] = {
          ContentFR = "... Tu n’es pas Daphne.",
          DialogueId = 11015908,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93C168",
          SpeakNpcId = 110022,
          Subtitle = "...You're not Daphne.",
          TalkActionId = {
            [1] = "0:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C168"
        },
        [11016001] = {
          Camera = "657.027344,-647.62207,449.714844,0.000194,-31.196772,156.787415,25.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Comme vous le voyez, Madame la Geôlière, je suis la console de commande de la salle de commande centrale de la Forteresse de Lonza...",
          DialogueId = 11016001,
          Duration = 3,
          GUID = "1B93D0AA",
          NextDialogue = 11019317,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/poweron"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "As you can see, ma'am, I am the control panel in the central control room of Lonza Fortress...",
          VoiceName = "voice/$Locale$/story/1002/110160/1B93D0AA"
        },
        [11016005] = {
          ContentFR = "Précepte n° 18 de la Légion Hyperboréenne : après une victoire trop facile... vient presque toujours une embuscade de l’ennemi...",
          DialogueId = 11016005,
          Duration = 3,
          GUID = "1B93D152",
          NextDialogue = 11016006,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Motto 18 of the Hyperborean Legion: An unexpectedly easy victory often leads to an impending ambush...",
          VoiceName = "voice/$Locale$/story/1002/110160/1B93D152"
        },
        [11016006] = {
          ContentFR = "... Même dans mes rêves, tu trouves encore le moyen de réciter tes fichus préceptes !",
          DialogueId = 11016006,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93D17C",
          Scripts = "StopNormalSound{EventPath{"event:/sfx/common/story/ex01/poweron"},PlayAs2D{true}}",
          SpeakNpcId = 110022,
          Subtitle = "...Um, can't believe you have to recite those mottos even in my dreams.",
          VoiceName = "voice/$Locale$/story/1002/110160/1B93D17C"
        },
        [11016101] = {
          Camera = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
          ContentFR = "Tous les jugements se font au nom de la justice.",
          DialogueId = 11016101,
          Duration = 3,
          GUID = "1B93E112",
          NextDialogue = 11016102,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          Subtitle = "All verdicts are in the name of justice.",
          TalkActionId = {
            [1] = "110032:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110161/1B93E112"
        },
        [11016102] = {
          Camera = "-11.319336,897.331055,144.578125,0.000127,5.398841,86.191856,17.134987,100000.0,false,Manual,22.0",
          ContentFR = "Tu répondras à toutes les questions avec exactitude. Aucune fausseté, aucune dissimulation ne sera tolérée.",
          DialogueId = 11016102,
          Duration = 3,
          GUID = "1B93E13C",
          NextDialogue = 11019017,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          Subtitle = "All questions must be answered absent falsehood. I tolerate no fabrication, alteration, or concealment of the truth.",
          VoiceName = "voice/$Locale$/story/1002/110161/1B93E13C"
        },
        [11016201] = {
          Camera = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
          Content = "龙莎要塞一役中，先遣队伍全军覆没，是否与你有关？",
          DialogueId = 11016201,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B93F17A",
          NextDialogue = 11016202,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "The vanguard squads were obliterated in the battle of Lonza Fortress. Were you the architect of their doom?",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F17A"
        },
        [11016202] = {
          Camera = "-11.319336,897.331055,144.578125,0.000127,5.398841,86.191856,17.134987,100000.0,false,Manual,22.0",
          Content = "好好感受吧！因为某些人的背叛，他们不得不这样死去！",
          DialogueId = 11016202,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B93F1A4",
          NextDialogue = 11016203,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Feel their agony! Betrayal led them to untimely deaths.",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F1A4"
        },
        [11016203] = {
          Camera = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
          Content = "若你背弃了同胞的正义，就被秽兽的利爪撕碎！",
          DialogueId = 11016203,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B93F1CE",
          NextDialogue = 11016204,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Should you betray the justice of your comrades, these Filthoids' claws shall tear you to pieces!",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F1CE"
        },
        [11016204] = {
          Camera = "13.287109,114.423828,114.03125,-0.000825,14.198904,-86.82589,17.134987,100000.0,false,Manual,22.0",
          Content = "（他们就是被这些怪物……富尔维斯……甚至用这样的怪物来对付自己的同胞……！）",
          DialogueId = 11016204,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93F1F8",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(They were killed by these monsters... Fulvis... He actually unleashed these monsters upon his own comrades...!)",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F1F8"
        },
        [11016301] = {
          ContentFR = "Dernière question. La mort d’Avar Hrodland... est-ce ton œuvre ?",
          DialogueId = 11016301,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B9401E2",
          NextDialogue = 11016302,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "One last question. Are you the cause of Avar Hrodland's demise?",
          VoiceName = "voice/$Locale$/story/1002/110163/1B9401E2"
        },
        [11016302] = {
          ContentFR = "Même s’il a trahi l’Empire, il t’a toujours fait confiance. Dis-moi... où étais-tu quand les flammes l’ont englouti ?",
          DialogueId = 11016302,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B94020C",
          NextDialogue = 11016305,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Despite his faults, he trusted you. Where were you when he was consumed by flames?",
          VoiceName = "voice/$Locale$/story/1002/110163/1B94020C"
        },
        [11016303] = {
          Content = "（是的……他<H>的的确确</>那样信任我……）",
          DialogueId = 11016303,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B940236",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Yes... He truly trusted me...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B940236"
        },
        [11016304] = {
          Content = "（在完成复仇之前，我必须活下去……不能让这个女人杀了我……）",
          DialogueId = 11016304,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B940260",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(I must survive... to avenge him... I cannot let this woman kill me...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B940260"
        },
        [11016305] = {
          ContentFR = "Si tu trahis la justice de ton camarade, que ce brasier infernal te réduise en cendres !",
          DialogueId = 11016305,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B94028A",
          NextDialogue = 11019052,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Should you betray the loyalty of friendship, these infernal flames shall burn you to ashes!",
          VoiceName = "voice/$Locale$/story/1002/110163/1B94028A"
        },
        [11016306] = {
          ContentFR = "Justice... Justice... Elle n’arrête pas d'en parler...",
          DialogueId = 11016306,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9402B4",
          NextDialogue = 11016307,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Justice... justice... That's what she keeps talking about...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B9402B4"
        },
        [11016307] = {
          ContentFR = "Le moment est venu... de lui révéler <H>toute la vérité</> de ce jour-là...",
          DialogueId = 11016307,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9402DE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Time to reveal the truth of that day...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B9402DE"
        },
        [11016401] = {
          ContentFR = "Madame la Geôlière, pour la justice qui brûle en votre cœur...",
          DialogueId = 11016401,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94124A",
          NextDialogue = 11016402,
          SpeakNpcId = 110022,
          Subtitle = "Ma'am, to satisfy the justice you seek—",
          VoiceName = "voice/$Locale$/story/1002/110164/1B94124A"
        },
        [11016402] = {
          ContentFR = "Permettez-moi de vous exposer la vérité. Tout ce qui s’est réellement passé ce jour-là, dans la salle de commande centrale.",
          DialogueId = 11016402,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B941274",
          SpeakNpcId = 110022,
          Subtitle = "Allow me to tell you the truth... of what unfolded in the central control room that day.",
          VoiceName = "voice/$Locale$/story/1002/110164/1B941274"
        },
        [11016501] = {
          Camera = "-12.243164,-221.074219,149.612579,0.001641,-5.409393,88.605331,35.932411,100000.0,false,Manual,22.0",
          ContentFR = "... !",
          DialogueId = 11016501,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Close"
          },
          FinalCamera = "-14.769531,-324.904297,159.446762,0.001641,-5.209378,88.605347,35.932411,257.489166,false,Manual,22.0",
          GUID = "1B9422B2",
          LookAt = {
            [1] = "110039:n(110022)"
          },
          NextDialogue = 11016502,
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{102104}},\nPlayFacial{_delay{0.5},ActorId{110022},FacialId{\"Pain01\"}}\n}",
          SpeakNpcId = 110022,
          Subtitle = "...!!",
          TalkActionId = {
            [1] = "110022:Weita_Story_Awake_Start",
            [2] = "110039:Sit_Idle_Loop"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110165/1B9422B2"
        },
        [11016502] = {
          Camera = "43.549805,139.308594,128.25798,0.001613,-1.609104,-101.194138,36.903526,100000.0,false,Manual,22.0",
          ContentFR = "... Pourquoi t’es-tu réveillé ? J’allais atteindre un point crucial de mon interrogatoire !",
          DialogueId = 11016502,
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "52.8125,137.478516,128.257767,0.001613,-1.209135,-100.994232,36.903526,100000.0,false,Manual,22.0",
          GUID = "1B9422DC",
          LookAt = {
            [1] = "110022:n(110039)"
          },
          NextDialogue = 11016503,
          SpeakNpcId = 110039,
          Subtitle = "...Why did you wake up? My questioning had just reached a pivotal point!",
          TalkActionId = {
            [1] = "110022:Weita_Story_Awake_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110165/1B9422DC"
        },
        [11016503] = {
          Camera = "67.43457,-649.426758,129.53125,0.001605,-4.809197,104.412491,36.90353,100000.0,false,Manual,22.0",
          ContentFR = "Ce n’est rien, Madame la Geôlière. Je me souviens de tout ce que j’ai dit dans mes rêves. Mais c'est confidentiel, je demande à vous parler en privé.",
          DialogueId = 11016503,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942306",
          NextDialogue = 11016504,
          Scripts = "SitOrStand{ActorId{110022},State{"Sit"}}",
          SpeakNpcId = 110022,
          Subtitle = "It's alright, ma'am. I remember what I told you in my dreams.",
          VoiceName = "voice/$Locale$/story/1002/110165/1B942306"
        },
        [11016504] = {
          Camera = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,105.270081,false,Manual,22.0",
          ContentFR = "Je vais vous révéler exactement ce qui s’est passé ce jour-là. Et j’espère qu’après avoir entendu la vérité, vous laisserez votre propre justice guider votre jugement.",
          DialogueId = 11016504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942330",
          NextDialogue = 11016505,
          SpeakNpcId = 110022,
          Subtitle = "I'll tell you exactly what happened that day. Once you've heard the truth, I hope the justice within your heart will guide your decision.",
          VoiceName = "voice/$Locale$/story/1002/110165/1B942330"
        },
        [11016505] = {
          Camera = "32.214844,139.163086,128.258286,0.001612,-2.00912,-97.193909,36.903526,100000.0,false,Manual,22.0",
          ContentFR = "Parle.",
          DialogueId = 11016505,
          GUID = "1B94235A",
          NextDialogue = 11016506,
          SpeakNpcId = 110039,
          Subtitle = "Go ahead.",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110165/1B94235A"
        },
        [11016506] = {
          Camera = "-1.37793,-810.395508,591.001038,0.001542,-46.808487,89.804596,16.538609,100000.0,false,Manual,22.0",
          ContentFR = "Ce jour-là...",
          DialogueId = 11016506,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-0.708984,-729.607422,508.35968,0.001516,-44.60828,88.804398,16.538609,100000.0,false,Manual,22.0",
          GUID = "1B942384",
          NextDialogue = 11016601,
          SpeakNpcId = 110022,
          Subtitle = "On that day...",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110165/1B942384"
        },
        [11016601] = {
          ContentFR = "Nous devons avoir une vraie discussion.",
          DialogueId = 11016601,
          GUID = "1B94331A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016601.T_Story_Recall_11016601‘",
          NextDialogue = 11016602,
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"},RelatedRegionId{102104}}\n}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We need to have a *serious* discussion about this.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94331A"
        },
        [11016602] = {
          ContentFR = "Je vais être bref, le temps presse. Si nous ne pouvons toujours pas accéder à l'extérieur... je tirerai sur toi avec cette arme. Et toi, tu devras... faire semblant d’être {性别2:mort|morte}.",
          DialogueId = 11016602,
          GUID = "1B943344",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016603,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll make this short. Later, I'll shoot you with this gun, and you'll have to play dead.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943344"
        },
        [11016603] = {
          ContentFR = "Pour que la mise en scène soit crédible, il faudra que la balle atteigne sa cible. Pas les points vitaux, mais la douleur sera réelle. Tu dois tenir bon. Pas un cri.",
          DialogueId = 11016603,
          GUID = "1B94336E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016604,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To make it convincing enough, the shot will have to hit. It will miss your vitals but will really hurt. You must endure the pain silently.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94336E"
        },
        [11016604] = {
          ContentFR = "Que comptez-vous faire ?",
          DialogueId = 11016604,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943398",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016604.T_Story_Recall_11016604'",
          NextDialogue = 11016605,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "What are you going to do?",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943398"
        },
        [11016605] = {
          ContentFR = "Nous sommes coincés derrière cette porte, sans aucun contact avec l’extérieur. Fulvis est déjà en marche... à cette heure, il a probablement pris le contrôle de toute la forteresse.",
          DialogueId = 11016605,
          GUID = "1B9433C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016606,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We're trapped in here, with all contact to the outside world cut off. Fulvis is already on his way. We are running out of time.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433C2"
        },
        [11016606] = {
          ContentFR = "Seuls les morts restent silencieux pour toujours. Fulvis va me tuer, c’est certain. Quant à toi... tu as vu son complot, son faux dossier. Il ne te laissera jamais repartir {性别2:vivant|vivante}.",
          DialogueId = 11016606,
          GUID = "1B9433EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016607,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Only the dead keep silent forever. Fulvis will definitely kill me. We're both on this mission, and you've seen his fabricated evidence, so he surely won't spare you either.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433EC"
        },
        [11016607] = {
          ContentFR = "... !",
          DialogueId = 11016607,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943416",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016607.T_Story_Recall_11016607'",
          NextDialogue = 11016608,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943416"
        },
        [11016608] = {
          ContentFR = "Calme-toi. Je suis là.",
          DialogueId = 11016608,
          GUID = "1B943440",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016609,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "It's okay, I got you.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943440"
        },
        [11016609] = {
          ContentFR = "Si je "t’abats" et que je fais mine de rallier son camp... il baissera peut-être sa garde. Tu auras une chance de survivre. C’est ton seul espoir.",
          DialogueId = 11016609,
          GUID = "1B94346A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016610,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...If I "kill" you and feign allegiance to him, it'll lower his guard, allowing you to go unnoticed... It's the only way to ensure your survival.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94346A"
        },
        [11016610] = {
          ContentFR = "Non ! Commandant Avar, dès que la porte s’ouvrira, nous nous battrons ensemble !",
          DialogueId = 11016610,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943494",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016610.T_Story_Recall_11016610'",
          NextDialogue = 11016622,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "No, Sir Avar... Let's just fight our way out... There's got to be a way out!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943494"
        },
        [11016612] = {
          ContentFR = "J’irai parlementer avec Fulvis. Évidemment, ce sera sans doute inutile. Mais je ne veux pas négocier pour rien... je veux obtenir une chose essentielle.",
          DialogueId = 11016612,
          GUID = "1B9434E8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016613,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll try to negotiate with Fulvis, though I believe it's going to fail in the end, so don't get your hopes up. The negotiation is for a more important purpose—",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9434E8"
        },
        [11016613] = {
          ContentFR = "Des preuves.",
          DialogueId = 11016613,
          Duration = 3,
          GUID = "1B943512",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016613.T_Story_Recall_11016613'",
          NextDialogue = 11016614,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To collect evidence.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943512"
        },
        [11016614] = {
          ContentFR = "Tiens, prends cet enregistreur. Garde-le sur toi. Ce sera la pièce maîtresse qui fera tomber Fulvis.",
          DialogueId = 11016614,
          GUID = "1B94353C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016615,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Take this recording device. It'll provide the evidence needed to expose and destroy Fulvis.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94353C"
        },
        [11016615] = {
          Content = "决不能让士兵们冤屈的哭号，永远在龙莎要塞上空徘徊。",
          DialogueId = 11016615,
          GUID = "1B943566",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016616,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Without it, all you have is your word, which happens to be the most unconvincing evidence. The cries of our fallen comrades will be lost to the winds of Lonza Fortress.",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CD42"
        }
      }
    end
  },
  {
    MinKey = 11016616,
    MaxKey = 11018014,
    Loader = function()
      return {
        [11016616] = {
          ContentFR = "... Commandant Avar...",
          DialogueId = 11016616,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943590",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016616.T_Story_Recall_11016616'",
          NextDialogue = 11016617,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "...Sir Avar...",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943590"
        },
        [11016617] = {
          ContentFR = "Pourquoi cette tête ? Courage, {性别2:petit|petite} ! Un vrai soldat rit face à l’adversité.",
          DialogueId = 11016617,
          GUID = "1B9435BA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016617.T_Story_Recall_11016617'",
          NextDialogue = 11016618,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Why the long face? Cheer up, kid! A true soldier laughs at adversity.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9435BA"
        },
        [11016618] = {
          ContentFR = "...",
          DialogueId = 11016618,
          Duration = 2,
          GUID = "1B9435E4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016617.T_Story_Recall_11016617'",
          NextDialogue = 11016619,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9435E4"
        },
        [11016619] = {
          ContentFR = "{nickname2}, mon élève dont je suis si fier... pardonne-moi de t’avoir mêlée à tout ça.",
          DialogueId = 11016619,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94360E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016619.T_Story_Recall_11016619'",
          NextDialogue = 11016620,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'm proud to have been your instructor, ... And I'm sorry for dragging you into this mess.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94360E"
        },
        [11016620] = {
          ContentFR = "Mais tu dois survivre. Tu dois transmettre toute la vérité à la Commandante Sibylle, et à Sa Majesté. L’Empire tout entier doit savoir que chaque soldat ici a combattu jusqu’au dernier souffle, fidèle à son serment et à sa mission.",
          DialogueId = 11016620,
          GUID = "1B943638",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016620.T_Story_Recall_11016620'",
          NextDialogue = 11016621,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "You must survive. Bring the truth to Chief Sibylle and His Majesty. Let the entire Empire know that every soldier here held true to their creed and duty, and everyone fought till their very last breath.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943638"
        },
        [11016621] = {
          ContentFR = "... Toute gloire à l’Empereur !",
          DialogueId = 11016621,
          GUID = "1B943662",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016621.T_Story_Recall_11016621'",
          NextDialogue = 11016701,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...All glory to our Emperor.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943662"
        },
        [11016622] = {
          ContentFR = "Réfléchis. Dans notre état, encerclés comme nous le sommes, crois-tu vraiment que nous avons la moindre chance face aux gardes personnels de Fulvis ?",
          DialogueId = 11016622,
          GUID = "1B943495",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016623,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943495"
        },
        [11016623] = {
          ContentFR = "Si nous sommes cernés... nos chances frôlent le néant. Mais tant pis, quitte à mourir, autant—",
          DialogueId = 11016623,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943496",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016624,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943496"
        },
        [11016624] = {
          ContentFR = "Mourir, c’est facile. Continuer à vivre, mener à bien la mission, voilà ce qui est difficile. {nickname2}, c’est un ordre : toi {性别2:seul|seule} peux mener cette mission à bien.",
          DialogueId = 11016624,
          GUID = "1B943497",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016625,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943497"
        },
        [11016625] = {
          ContentFR = "Quant à moi... hmpf. Ma vie n’est pas encore fini. J’ai encore un rôle à jouer.",
          DialogueId = 11016625,
          GUID = "1B943498",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016612,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943498"
        },
        [11016701] = {
          Camera = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,109.538574,false,Manual,22.0",
          ContentFR = "Voilà ce qui s’est passé ce jour-là, dans la salle de commande centrale.",
          DialogueId = 11016701,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-3.560547,-173.319336,128.433594,0.001531,-4.805598,92.405151,36.903526,145.652008,false,Manual,22.0",
          GUID = "1B944382",
          NextDialogue = 11016702,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"},RelatedRegionId{102104}}",
          SpeakNpcId = 110022,
          Subtitle = "...That's exactly what happened in the central control room that day.",
          TalkActionId = {
            [1] = "110039:Sit_Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110167/1B944382"
        },
        [11016702] = {
          Camera = "570.384766,-248.601562,159.607712,0.001551,-7.005765,175.00383,19.596729,100000.0,false,Manual,22.0",
          ContentFR = "Commandant Avar, jusqu’à son dernier instant, a affronté un complot d’une ampleur démesurée. Il a sacrifié sa vie pour laisser derrière lui une preuve décisive... son ultime façon de servir la justice.",
          DialogueId = 11016702,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "566.180664,-300.931641,159.606354,0.001551,-7.005704,175.403824,19.596729,100000.0,false,Manual,22.0",
          GUID = "1B9443AC",
          NextDialogue = 11016703,
          SpeakNpcId = 110022,
          Subtitle = "Sir Avar fought valiantly, confronting a conspiracy far greater than any individual could withstand alone. He sacrificed his life to secure crucial evidence — his final act in defence of justice.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110167/1B9443AC"
        },
        [11016703] = {
          Camera = "-3.560547,-173.319336,123.261719,0.001521,-4.805598,92.405113,36.90353,148.063751,false,Manual,22.0",
          ContentFR = "Mais l’ennemi avait prévu chaque détail. À demi {性别2:inconscient|inconsciente}, j’ai senti l’adjudante de Fulvis, Falsi, m’arracher l’enregistreur.",
          DialogueId = 11016703,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9443D6",
          NextDialogue = 11016704,
          SpeakNpcId = 110022,
          Subtitle = "But, we underestimated the enemy's meticulousness. As I drifted in and out of consciousness, I sensed Fulvis's adjutant, Falsi, removing the recording device from me.",
          VoiceName = "voice/$Locale$/story/1002/110167/1B9443D6"
        },
        [11016704] = {
          Camera = "299.907227,-246.0,95.800987,-0.000854,42.006584,-179.996628,36.931984,100000.0,false,Manual,22.0",
          ContentFR = "Quand j’ai repris mes esprits, Fulvis contrôlait déjà toute la forteresse. Le défier alors, cela aurait été me condamner, Daphne et moi... et condamner la vérité à disparaître avec nous.",
          DialogueId = 11016704,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "299.907227,-268.0,95.800987,-0.000854,42.006584,-179.996628,36.931984,100000.0,false,Manual,22.0",
          GUID = "1B944400",
          NextDialogue = 11019102,
          SpeakNpcId = 110022,
          Subtitle = "By the time I fully regained consciousness, Fulvis had seized control of the fortress. Confronting him would have led to our deaths, and the truth would have been buried with us.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110167/1B944400"
        },
        [11016705] = {
          Camera = "76.907227,-660.533203,98.932999,-0.000916,-2.393981,100.607307,48.616428,100000.0,false,Manual,22.0",
          Content = "所以，我们选择用这种方式来见你。我相信，以你的手段，一定能得到那份证据，或者至少，得到法露茜的供词。",
          DialogueId = 11016705,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94442A",
          SpeakNpcId = 110022,
          Subtitle = "That's why we decided to come to you like this. I believe that you have the authority to recover that evidence, or at least secure a testimony from Falsi.",
          VoiceName = "voice/$Locale$/story/1002/110167/1B94442A"
        },
        [11016706] = {
          Camera = "101.0,-126.956055,72.582031,-0.000917,13.404778,137.606186,36.480843,158.868011,false,Manual,22.0",
          ContentFR = "Madame la Geôlière, vous parlez sans cesse de justice. Alors je vous le demande : arrêtez Falsi. C’est elle qui détient la vérité.",
          DialogueId = 11016706,
          ExStoryInfo = "EXPlayer",
          GUID = "1B944454",
          NextDialogue = 11019104,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{"75.275391,226.958008,101.472656,-0.000915,-0.995684,-100.79319,52.299137,718.026855,false,Manual,22.0"},duration{0}}",
          SpeakNpcId = 110022,
          Subtitle = "Warden Hellfire, I know you hold justice above all else, and I believe you possess the means to defend it. Please, go get Falsi. She holds the truth you want.",
          TalkActionId = {
            [1] = "110022:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110167/1B944454"
        },
        [11016707] = {
          Camera = "15.709961,-308.188477,107.445312,-0.000916,-1.595662,-98.792236,35.182564,169.208145,false,Manual,22.0",
          ContentFR = "Hyperborea est une vaste machine. Chaque pièce doit tourner selon la loi qui lui est assignée.",
          DialogueId = 11016707,
          GUID = "1B94447E",
          NextDialogue = 11016708,
          SpeakNpcId = 110039,
          Subtitle = "Hyperborea functions like a vast machine, requiring every component to operate flawlessly.",
          TalkActionId = {
            [1] = "110022:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110167/1B94447E"
        },
        [11016708] = {
          Camera = "-23.03125,453.560547,337.066406,-0.000917,-19.995569,-87.991684,27.483999,100000.0,false,Manual,22.0",
          ContentFR = "Mon rôle est de protéger cette loi, de protéger la justice qu’Hyperborea a établie. Et si quelqu’un tente de m’instrumentaliser pour la détourner, il en paiera le prix.",
          DialogueId = 11016708,
          FinalCamera = "-17.12207,284.929688,275.703125,-0.000917,-19.995569,-87.991684,27.483999,100000.0,false,Manual,22.0",
          GUID = "1B9444A8",
          NextDialogue = 11016709,
          SpeakNpcId = 110039,
          Subtitle = "My role is to uphold the law and protect the justice defined by Hyperborea. If anyone attempts to manipulate me to subvert this law, they will face severe consequences.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110167/1B9444A8"
        },
        [11016709] = {
          Camera = "-5.833984,-339.387695,101.292969,-0.000916,-0.200104,-90.570984,21.509014,135.908142,false,Manual,22.0",
          ContentFR = "J’irai enquêter sur Falsi. Mais si tu mens pour gagner du temps... tu connais les conséquences.",
          DialogueId = 11016709,
          FinalCamera = "-6.027344,-359.292969,101.292969,-0.000916,-0.200104,-90.570984,21.509014,119.777908,false,Manual,22.0",
          GUID = "1B9444D2",
          NextDialogue = 11016710,
          Scripts = "PlayAnimation{ActorId{110039},AnimationId{"Sit_Talk02_Start"},Duration{8}}",
          SpeakNpcId = 110039,
          Subtitle = "I will investigate Falsi. Be aware of the consequences if what you said proves to be false and a waste of my time.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110167/1B9444D2"
        },
        [11016710] = {
          Camera = "84.628906,-750.515625,122.24234,-0.001037,-2.992859,99.218079,63.232998,726.07959,false,Manual,22.0",
