        [11016801] = {
          Camera = "459.99707,183.754883,152.386719,0.000152,-2.992859,-102.205826,35.0,150.488785,false,DoNotOverride,22.0",
          ContentFR = "{nickname2}, la Geôlière Vulcera a donné l’ordre d’amener Mademoiselle Theodore.",
