          ExStoryInfo = "EXPlayer",
          GUID = "1B953B14",
          NextDialogue = 11018211,
          SnapShot = "MONSTER",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B14"
        },
        [11018211] = {
          ContentFR = "Non ! Je ne peux pas...",
          DialogueId = 11018211,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B3E",
          NextDialogue = 11018212,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B3E"
        },
        [11018212] = {
          ContentFR = "D’autres m’attendent. Je dois continuer... je dois avancer !",
          DialogueId = 11018212,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B68",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B68"
        },
        [11018301] = {
          ContentFR = "Tenez bon, {性别2:le|la} capitaine arrive !",
          DialogueId = 11018301,
          GUID = "1B954A02",
          SpeakNpcId = 110016,
          VoiceName = "voice/$Locale$/story/1002/110183/1B954A02"
        },
        [11018302] = {
          ContentFR = "Quand ils ont eu besoin d’ouvriers, ils nous ont arrachés à nos foyers et nous ont forcés à aider à reconstruire cette forteresse. Ils ont laissé les Solariens en paix et n’ont emmené que les Charons...",
