          SpeakNpcId = 110020,
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B26"
        },
        [11018504] = {
          ContentFR = "« Monica, la prochaine fois, je te bats au concours de tir. »... ha ha... quel idiot...",
          DialogueId = 11018504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B956B50",
          NextDialogue = 11018505,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B50"
        },
        [11018505] = {
          ContentFR = "Si j’avais su qu’il était rancunier... je l’aurais laissé gagner la dernière fois...",
          DialogueId = 11018505,
          GUID = "1B956B7A",
          NextDialogue = 11018506,
          SpeakNpcId = 110020,
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B7A"
        },
        [11018506] = {
          ContentFR = "... Monica, la prochaine bataille va être rude. Reste concentrée.",
