          DialogueId = 11018817,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959EAA",
          NextDialogue = 11018821,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959EAA"
        },
        [11018818] = {
