        },
        [11019307] = {
          ContentFR = "S’injecter la dose d’adrénaline",
          DialogueId = 11019307,
          GUID = "1B95EF0E",
          NextDialogue = 11019308
        },
        [11019308] = {
          ContentFR = "Ça devrait me maintenir debout un moment... Je dois sortir d’ici, vite !",
