        },
        [11019315] = {
          Camera = "-87.908264,37.815254,47.214844,5.000778,2.401037,-147.587677,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quant aux registres, si un officier avait subtilisé la clé d’accès du Commandant Avar, il aurait pu effacer ou falsifier certaines entrées à son nom.",
