          VoiceName = "voice/$Locale$/story/1200/120005/1E0AC05C"
        },
        [12000503] = {
          ContentFR = "Ouah, si direct ! Je croyais que tu dirais quelque chose comme : « Je cède mon billet à Rhythm. »",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000503,
          GUID = "1E0AC086",
          NextDialogue = 12000504,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120005/1E0AC086"
        },
        [12000504] = {
          ContentFR = "Pas dans son état actuel. Ça ne ferait que rouvrir ses blessures. Laissons-lui le temps de guérir. Nous l’inviterons plus tard, quand elle ira mieux.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000504,
          GUID = "1E0AC0B0",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120005/1E0AC0B0"
        },
        [12000505] = {
          Camera = "-3094.28418,465.570312,149.697754,0.000075,6.001161,-5.012456,30.0,100000.0,false,Manual,10.0",
          Content = "…………",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000505,
          Duration = 8,
          FinalCamera = "-3147.636719,627.79248,203.036865,0.000075,6.001161,-5.012456,30.0,100000.0,false,Manual,10.0",
          GUID = "1E0AC0B1",
          ToFinalCameraBlendTime = 8
        },
        [12000506] = {
          Content = "开个车，提示去聊一下",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000506,
          GUID = "1E0AC0B2",
          NextDialogue = 12000507
        },
        [12000507] = {
          Content = "开个车，提示去聊一下+1",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000507,
          GUID = "1E0AC0B3"
        },
        [12000601] = {
          ContentFR = "Avec la voix enchanteresse de Madame Violetta, ses aigus purs et puissants, sa maîtrise des vocalises, elle incarnera la fée à la perfection et portera cette œuvre intemporelle vers de nouveaux sommets !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000601,
          GUID = "1E0AD09A",
          NextDialogue = 12000602,
          SpeakNpcId = 220003,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD09A"
        },
        [12000602] = {
          ContentFR = "Mouais... Si tu veux mon avis, la troupe décline d’année en année. Aujourd’hui, leurs performances sont à peine écoutables.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000602,
          GUID = "1E0AD0C4",
          NextDialogue = 12000603,
          SpeakNpcId = 220004,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD0C4"
        },
        [12000603] = {
          ContentFR = "Alors pourquoi tu continues à acheter une place à chaque représentation ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000603,
          GUID = "1E0AD0EE",
          NextDialogue = 12000604,
          SpeakNpcId = 220003,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD0EE"
        },
        [12000604] = {
          ContentFR = "On ne peut juger qu’en venant écouter, non ? Et puis... c’est la seule distraction qui me reste dans la vie.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000604,
          GUID = "1E0AD118",
          SpeakNpcId = 220004,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD118"
        },
        [12000605] = {
          ContentFR = "Papa ! On va bientôt pouvoir entendre la magie des grandes sœurs avec leurs voix féeriques !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000605,
          GUID = "1E0AD142",
          NextDialogue = 12000606,
          SpeakNpcId = 220005,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD142"
        },
        [12000606] = {
          ContentFR = "Regarder l’opéra avec Papa, et puis un grand dîner après... Aujourd’hui, c’est le plus beau jour de ma vie !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000606,
          GUID = "1E0AD16C",
          SpeakNpcId = 220005,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD16C"
        },
        [12000607] = {
          ContentFR = "Hé, t’as entendu ? Pendant la Fête de la Chandelle d’Argent, il y a eu un meurtre dans l’opéra même ! La Légion a dû intervenir !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000607,
          GUID = "1E0AD196",
          NextDialogue = 12000608,
          SpeakNpcId = 220006,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD196"
        },
        [12000608] = {
          ContentFR = "Certains parlent de fantômes, d’autres de Déchus... ou même du monstre de la "Traque aux Charons" revenu à la vie. Mais tous ceux qui ont voulu enquêter se sont retrouvés bâillonnés par un ordre de silence !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000608,
          GUID = "1E0AD1C0",
          SpeakNpcId = 220006,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD1C0"
        },
        [12000701] = {
