            [2] = "210003:Excited02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E1109D0"
        },
        [12010313] = {
          Camera = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
          Content = "咦……你们两位已经认识了？",
          DialogueId = 12010313,
          FacialId = {
            [1] = "210004:Doubt01"
          },
          GUID = "1E1109FA",
          LookAt = {
            [1] = "200002:n(210004)"
          },
          NextDialogue = 12010314,
          SpeakNpcId = 210004,
          TalkActionId = {
            [1] = "210004:Explain02_Start",
            [2] = "210003:Excited02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E1109FA"
        },
        [12010314] = {
          Camera = "202.094421,-70.305641,138.647461,0.000175,-12.601808,127.792175,50.000008,318.602966,false,DoNotOverride,2.8",
          Content = "这就是光之魔王大人走到哪里散发到哪里的人格魅力！",
          DialogueId = 12010314,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "202.094421,-70.305641,138.647461,0.000182,-12.401793,125.792969,50.000011,318.602966,false,DoNotOverride,2.8",
          GUID = "1E110A24",
          LookAt = {
            [1] = "200002:n(210004)"
          },
          NextDialogue = 12010315,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120103/1E110A24"
        },
        [12010315] = {
          Content = "这位冰湖城来的魔王大人和本皎皎可是拜把子的交情！我会担起东道主的责任，好好带领他们，让他们宾至如归的！",
          DialogueId = 12010315,
          GUID = "1E110A4E",
          NextDialogue = 12010316,
          SpeakNpcId = 210003,
          TalkActionId = {
            [1] = "210003:SpecialHappy_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110A4E"
        },
        [12010316] = {
          Camera = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
          Content = "嗯，你对这片地界熟悉，交给你我却是放心。那你们随后到<H>百年春</>来找我就行。",
          DialogueId = 12010316,
          FacialId = {
            [1] = "210004:Smile01"
          },
          GUID = "1E110A78",
          NextDialogue = 12010317,
          SpeakNpcId = 210004,
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110A78"
        },
        [12010317] = {
          Camera = "-197.656311,99.099442,143.551758,0.000188,-4.202909,-1.79672,50.000008,572.522461,false,DoNotOverride,2.8",
          Content = "{nickname}，路上注意安全。逛得尽兴了再来即可。先前提到的委托，等你来了，我再把细节交代与你。",
          DialogueId = 12010317,
          FacialId = {
            [1] = "210004:Smile01"
          },
          GUID = "1E110AA2",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "210032:n(100001)",
            [4] = "200002:n(210004)"
          },
          NextDialogue = 12010318,
          Scripts = "SEQ{\nPlayAnimation{ActorId{210004},AnimationId{\"Explain02_End\"},Duration{1}},\nPlayAnimation{ActorId{210004},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 210004,
          VoiceName = "voice/$Locale$/story/1201/120103/1E110AA2"
        },
        [12010318] = {
          Camera = "221.316528,188.197891,147.143066,0.000172,-5.802731,-150.999084,50.000011,338.357025,false,DoNotOverride,2.8",
          Content = "我明白了。止流掌柜，您快去忙吧！",
          DialogueId = 12010318,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "1E110ACC",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110ACC"
        },
        [12010401] = {
          Camera = "1510.199219,3684.390625,1778.458984,0.000038,-13.800717,-84.392624,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "这就是你们说的诫碑了吧，让我瞧瞧——",
          DialogueId = 12010401,
          GUID = "1E11186A",
          NextDialogue = 12010402,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 203002,
            [5] = 405009
          },
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E11186A"
        },
        [12010402] = {
          Camera = "696.953125,-317.017578,277.799805,0.000066,-12.201128,149.811142,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "怎、怎么办，白完全看不懂……",
          DialogueId = 12010402,
          GUID = "1E111894",
          NextDialogue = 12010403,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111894"
        },
        [12010403] = {
          Camera = "-185.355469,366.291016,89.310547,0.00007,1.398802,-55.587837,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "我来给你们翻译——锦鲤皎皎的大风九章小课堂开始！为了在华胥玩得开心，大家一定要认真听哦！",
          DialogueId = 12010403,
          GUID = "1E1118BE",
          NextDialogue = 12010404,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E1118BE"
        },
        [12010404] = {
          Content = "最上面这行是<H>戕身害命，不可为也</>。任何伤害别人的行为在华胥都是绝对禁止的！",
          DialogueId = 12010404,
          GUID = "1E1118E8",
          NextDialogue = 12010405,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E1118E8"
        },
        [12010405] = {
          Content = "这条的惩罚最为严重，一定一定要小心哦。不然就会像刚刚看到的坏强盗一样，被一下子定在原地，化作晶尘。",
          DialogueId = 12010405,
          GUID = "1E111912",
          NextDialogue = 12010406,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111912"
        },
        [12010406] = {
          Content = "哇，这么吓人……",
          DialogueId = 12010406,
          GUID = "1E11193C",
          NextDialogue = 12010407,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E11193C"
        },
        [12010407] = {
          Content = "放心，只有坏人才需要害怕啦，好人才不用担心呢！",
          DialogueId = 12010407,
          GUID = "1E111966",
          NextDialogue = 12010408,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111966"
        },
        [12010408] = {
          Content = "多亏了大风九章，现在的华胥压根就不会有什么战争呀犯罪呀，大家都和睦融融的。我听说外面的世界可不是这样。",
          DialogueId = 12010408,
          GUID = "1E111990",
          NextDialogue = 12010409,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111990"
        },
        [12010409] = {
          Content = "这倒是。要是在冰湖城，有人犯了事，就只能指望治安署那些趾高气昂的士兵。",
          DialogueId = 12010409,
          GUID = "1E1119BA",
          NextDialogue = 12010410,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E1119BA"
        },
        [12010410] = {
          Content = "而且他们很少管卡戎和穷人的事，最后还是得靠我们自己去抓犯人。前几天好不容易遇到一个靠谱的大姐姐，最后还跑掉不干了……",
          DialogueId = 12010410,
          GUID = "1E1119E4",
          NextDialogue = 12010411,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E1119E4"
        },
        [12010411] = {
          Content = "华胥这些长得像冰原狼一样的，叫毕、毕什么的威风猛兽，可比冰湖城的治安署靠谱多啦！",
          DialogueId = 12010411,
          GUID = "1E111A0E",
          NextDialogue = 12010412,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A0E"
        },
        [12010412] = {
          Content = "是狴犴，不要再记错它们的名字了！",
          DialogueId = 12010412,
          GUID = "1E111A38",
          NextOptions = {
            [1] = 120104121,
            [2] = 120104122
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A38"
        },
        [12010413] = {
          Content = "当然，狴犴可是天命的使者！",
          DialogueId = 12010413,
          GUID = "1E111A62",
          NextDialogue = 12010415,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A62"
        },
        [12010414] = {
          Content = "这可不行！狴犴可是天命的使者。",
          DialogueId = 12010414,
          GUID = "1E111A8C",
          NextDialogue = 12010415,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A8C"
        },
        [12010415] = {
          Content = "这就要说到，为什么有龙氏是大家都很敬仰的存在啦。",
          DialogueId = 12010415,
          GUID = "1E111AB6",
          NextDialogue = 12010416,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111AB6"
        },
        [12010416] = {
          Content = "别卖关子啦，快说快说——",
          DialogueId = 12010416,
          GUID = "1E111AE0",
          NextDialogue = 12010417,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111AE0"
        },
        [12010417] = {
          Content = "一部分有龙氏到了成年左右的时间，会感应天命，被大风九章蒙召，化为狴犴。",
          DialogueId = 12010417,
          GUID = "1E111B0A",
          NextDialogue = 12010418,
          RelatedWikiId = {
            [1] = 303009
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B0A"
        },
        [12010418] = {
          Content = "（嗯？卡戎……<H>成年左右</>？）",
          DialogueId = 12010418,
          DisableMouth = 1,
          GUID = "1E111B34",
          NextDialogue = 12010419,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B34"
        },
        [12010419] = {
          Content = "再附赠一个知识点，其实狴犴只是大风九章最普通的执法者。",
          DialogueId = 12010419,
          GUID = "1E111B5E",
          NextDialogue = 12010420,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B5E"
        },
        [12010420] = {
          Content = "有一些更厉害的有龙氏，能够直接以人身进入大风九章，作为<H>应天尉</>活动着，代天命威慑躲在暗中的坏人，让他们不敢造次！",
          DialogueId = 12010420,
          GUID = "1E111B88",
          NextDialogue = 12010421,
          RelatedWikiId = {
            [1] = 405010
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B88"
        },
        [12010421] = {
          Content = "对于那种非常棘手的坏人，应天尉就会出动，将他们缉拿，威风凛凛！",
          DialogueId = 12010421,
          GUID = "1E111BB2",
          NextDialogue = 12010422,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111BB2"
        },
        [12010422] = {
          Content = "不过……当然还是希望你们永远不要遇到应天尉！",
          DialogueId = 12010422,
          GUID = "1E111BDC",
          NextDialogue = 12010423,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111BDC"
        },
        [12010423] = {
          Content = "好啦，对于第一条诫律的解说到此为止！接下来——",
          DialogueId = 12010423,
          GUID = "1E111C06",
          NextDialogue = 12010424,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C06"
        },
        [12010424] = {
          Content = "眩晕屏幕特效",
          DialogueId = 12010424,
          GUID = "1E111C30",
          NextDialogue = 12010425,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C30"
        },
        [12010425] = {
          Content = "…………？",
          DialogueId = 12010425,
          GUID = "1E111C5A",
          NextDialogue = 12010426,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C5A"
        },
        [12010426] = {
          Content = "（总觉得……那块诫碑，像是在<H>呼唤</>我一样……）",
          DialogueId = 12010426,
          DisableMouth = 1,
          GUID = "1E111C84",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C84"
        },
        [12010427] = {
          Content = "你触摸了诫碑，忽然你的脑内传来了一阵眩晕。",
          DialogueId = 12010427,
          GUID = "1E111CAE",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111CAE"
        },
        [12010428] = {
          DialogueId = 12010428,
          GUID = "1E111CD8",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111CD8"
        },
        [12010429] = {
          Camera = "265.414062,55.289062,169.237793,0.000002,-24.800047,-172.198669,11.88,100000.0,false,Manual,2.8",
          Content = "接下来，我要来讲第二条啦！大风九章的第二条即是——",
          DialogueId = 12010429,
          GUID = "1E111D02",
          NextOptions = {
            [1] = 120104291,
            [2] = 120104292
          },
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 405009,
            [5] = 203002
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111D02"
        },
        [12010432] = {
          Content = "完全正确！",
          DialogueId = 12010432,
          GUID = "1E111D80",
          NextDialogue = 12010433,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111D80"
        },
        [12010433] = {
          Content = "小仆从，你什么时候偷偷学会了华胥文字？白都不知道！",
          DialogueId = 12010433,
          GUID = "1E111DAA",
          NextDialogue = 12010434,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111DAA"
        },
        [12010434] = {
          Content = "不，我不认识这些文字……",
          DialogueId = 12010434,
          GUID = "1E111DD4",
          NextDialogue = 12010435,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111DD4"
        },
        [12010435] = {
          Content = "刚刚我靠近诫碑时，脑海里突然冒出来了一个声音，告诉了我这些内容。你知道这是什么情况吗？",
          DialogueId = 12010435,
          GUID = "1E111DFE",
          NextDialogue = 12010436,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111DFE"
        },
        [12010436] = {
          Content = "从来没有听说过这种事情……不对，等等！",
          DialogueId = 12010436,
          GUID = "1E111E28",
          NextDialogue = 12010437,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111E28"
        },
        [12010437] = {
          Content = "有过这样的传说，大风九章的奠基者，也是悬衡派的创始人<H>飏</>，在史书中留下了“天人相感，阴阳相和”的评价。",
          DialogueId = 12010437,
          GUID = "1E111E52",
          NextDialogue = 12010438,
          RelatedWikiId = {
            [1] = 203003
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111E52"
        },
        [12010438] = {
          Content = "据说，她能够与上天，与世间万物相感应，挟飞仙以遨游！好像和你的情况有点相似。",
          DialogueId = 12010438,
          GUID = "1E111E7C",
          NextDialogue = 12010439,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111E7C"
        },
        [12010439] = {
          Content = "正是这位先辈，最后带着很多德高望重的祖先一起，祭献了身躯，化为大风九章流转不息的根基。",
          DialogueId = 12010439,
          GUID = "1E111EA6",
          NextDialogue = 12010440,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111EA6"
        },
        [12010440] = {
          Content = "白突然有了一个想法！莫非，小仆从就是这位前辈的不知道第几十代曾曾曾曾孙？",
          DialogueId = 12010440,
          GUID = "1E111ED0",
          NextOptions = {
            [1] = 120104401,
            [2] = 120104402
          },
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111ED0"
        },
        [12010441] = {
          Content = "诶，是吗？但是{性别：他|她}看着也不像华胥人呢……",
          DialogueId = 12010441,
          GUID = "1E111EFA",
          NextDialogue = 12010443,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111EFA"
        },
        [12010442] = {
          Content = "总而言之，大风九章的内容就是以上这些啦。止流大当家交代我的任务完成了，接下来，我带你们去百年春吧！",
          DialogueId = 12010442,
          GUID = "1E111F24",
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F24"
        },
        [12010443] = {
          Content = "一段时间后……",
          DialogueId = 12010443,
          GUID = "1E111EFB",
          NextDialogue = 12010442
        },
        [12010451] = {
          Content = "跟我来！诫碑在这个方向哦！",
          DialogueId = 12010451,
          Duration = 4,
          GUID = "1E111F26",
          NextDialogue = 12010452,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F26"
        },
        [12010452] = {
          Content = "锦鲤皎皎，他们刚刚提到的烛什么阴之灾……是什么呀？",
          DialogueId = 12010452,
          Duration = 4,
          GUID = "1E111F27",
          NextDialogue = 12010453,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F27"
        },
        [12010453] = {
          Content = "唔，简而言之，就是一个害得大家没法好好做生意的很坏很坏的灾害。",
          DialogueId = 12010453,
          Duration = 4,
          GUID = "1E111F28",
          NextDialogue = 12010454,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F28"
        },
        [12010454] = {
          Content = "不过你们放心，止流大当家已经在着手解决了！只要大当家一出手，事情都会咻的一下好起来的！",
          DialogueId = 12010454,
          Duration = 4,
          GUID = "1E111F29",
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F29"
        },
        [12010500] = {
          Content = "一直听你们说百年春，那里到底是什么样的地方哇？",
          DialogueId = 12010500,
          Duration = 2,
          GUID = "1E1128A8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 12010501,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E1128A8"
        },
        [12010501] = {
          Content = "那可是织星客在烟津渡的最大据点，囊括了来自五湖四海的商品，可气派啦。",
          DialogueId = 12010501,
          Duration = 2,
          GUID = "1E1128D2",
          NextDialogue = 12010502,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E1128D2"
        },
        [12010502] = {
          Content = "说起来，开旅游团好像也是一门不错的生意经……没错没错，赶紧记在小本本上。",
          DialogueId = 12010502,
          Duration = 2,
          GUID = "1E1128FC",
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E1128FC"
        },
        [12010503] = {
          Content = "吼————",
          DialogueId = 12010503,
          Duration = 2,
          GUID = "1E112926",
          NextDialogue = 12010504,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112926"
        },
        [12010504] = {
          Content = "（刚刚那是……？）",
          DialogueId = 12010504,
          Duration = 2,
          GUID = "1E112950",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 12010505,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112950"
        },
        [12010505] = {
          Content = "糟糕——是玄色狴犴！",
          DialogueId = 12010505,
          Duration = 2,
          GUID = "1E11297A",
          NextDialogue = 12010506,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E11297A"
        },
        [12010506] = {
          Content = "那是什么？！——诶，人呢？",
          DialogueId = 12010506,
          Duration = 4,
          GUID = "1E1129A4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E1129A4"
        },
        [12010507] = {
          Content = "咤——走、赶紧走开 ——",
          DialogueId = 12010507,
          Duration = 3,
          GUID = "1E1129CE",
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120105/1E1129CE"
        },
        [12010508] = {
          Camera = "-2086.416992,-1506.259277,1044.228516,0.000102,-15.798794,37.99028,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "上天庇佑，白龙神君庇佑！你们还好吗？",
          DialogueId = 12010508,
          FinalCamera = "-2543.464355,680.419128,896.21582,0.000097,-15.59871,-11.41056,28.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1129F8",
          LookAt = {
            [1] = "210033:n(100001)"
          },
          NextDialogue = 12010509,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 303008,
            [5] = 303009
          },
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120105/1E1129F8"
        },
        [12010509] = {
          Content = "你还好吗？你的声音都在颤抖……明明自己也怕得要死，怎么还来凑热闹呀！",
          DialogueId = 12010509,
          GUID = "1E112A22",
          NextDialogue = 12010510,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112A22"
        },
        [12010510] = {
          Camera = "-309.597839,264.643616,19.609375,0.000098,-13.798676,-30.610697,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "我并无大碍，只是被那骇人的双目瞪上一眼，腿有点麻，缓缓就好了。但你们看起来是刚来此地的外乡人，不能将你们置之不理。",
          DialogueId = 12010510,
          GUID = "1E112A4C",
          NextOptions = {
            [1] = 120105101,
            [2] = 120105102
          },
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112A4C"
        },
        [12010511] = {
          Content = "其实你再晚来两步，小仆从唰唰两下就能解决啦，{性别：他|她}很厉害的！",
          DialogueId = 12010511,
          GUID = "1E112A76",
          NextDialogue = 12010512,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112A76"
        },
        [12010512] = {
          Content = "这样吗，那太好了……",
          DialogueId = 12010512,
          GUID = "1E112AA0",
          NextDialogue = 12010513,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112AA0"
        },
        [12010513] = {
          Content = "但是，刚刚那是怎么回事？白没认错吧，华胥的执法者怎么突然冒出来攻击我们？！",
          DialogueId = 12010513,
          GUID = "1E112ACA",
          NextDialogue = 12010514,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112ACA"
        },
        [12010514] = {
          Content = "事先说明，白可没有做什么违法乱纪的坏事——虽然现在说这个好像也已经晚了……",
          DialogueId = 12010514,
          GUID = "1E112AF4",
          NextDialogue = 12010515,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112AF4"
        },
        [12010515] = {
          Content = "怎、怎么办，小仆从，我们是不是得赶紧潜逃？你的水性怎么样？",
          DialogueId = 12010515,
          GUID = "1E112B1E",
          NextDialogue = 12010516,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B1E"
        },
        [12010516] = {
          Content = "噗嗤……烟津渡周围的水域如此广阔，光靠游，一天一夜也游不出几里。",
          DialogueId = 12010516,
          GUID = "1E112B48",
          NextDialogue = 12010517,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B48"
        },
        [12010517] = {
          Content = "你们不必惊慌。玄色狴犴与狴犴仅仅是外形近似，但它们并非华胥的执法者，而是<H>烛阴之灾</>影响下紊乱失序的产物。",
          DialogueId = 12010517,
          GUID = "1E112B72",
          NextDialogue = 12010518,
          RelatedWikiId = {
            [1] = 303010
          },
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B72"
        },
        [12010518] = {
          Content = "这些玄色狴犴神志浑浊暴虐，不受大风九章的控制。攻击它们不会招致责罚。\n",
          DialogueId = 12010518,
          GUID = "1E112B9C",
          NextDialogue = 12010519,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B9C"
        },
        [12010519] = {
          Content = "只是最近这玄色狴犴袭人事件，是愈来愈频发了。我刚刚续上的香，这就又用完了……",
          DialogueId = 12010519,
          GUID = "1E112BC6",
          NextDialogue = 12010520,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112BC6"
        },
        [12010520] = {
          Content = "玉笙姐姐！",
          DialogueId = 12010520,
          GUID = "1E112BF0",
          NextDialogue = 12010521,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112BF0"
        },
        [12010521] = {
          Content = "锦鲤皎皎，你怎在此处？",
          DialogueId = 12010521,
          GUID = "1E112C1A",
          NextDialogue = 12010522,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C1A"
        },
        [12010522] = {
          Content = "这两位是止流大当家从异国带来的贵客，我正在招待他们呢！只是途中发生了一些……咳咳、小变故。",
          DialogueId = 12010522,
          GUID = "1E112C44",
          NextDialogue = 12010523,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C44"
        },
        [12010523] = {
          Content = "玉笙姐姐，你要去百年春前续香吗？我们一起同行吧！",
          DialogueId = 12010523,
          GUID = "1E112C6E",
          NextDialogue = 12010524,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C6E"
        },
        [12010524] = {
          Content = "<H>香</>？",
          DialogueId = 12010524,
          GUID = "1E112C98",
          NextDialogue = 12010525,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C98"
        },
        [12010525] = {
          Content = "说起来，刚刚战斗时，好像有一阵异香飘过，然后仿佛有某种力量，帮我抵挡了对面的攻击……这就是你们说的香吗？",
          DialogueId = 12010525,
          GUID = "1E112CC2",
          NextDialogue = 12010526,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112CC2"
        },
        [12010526] = {
          Content = "确是如此。",
          DialogueId = 12010526,
          GUID = "1E112CEC",
          NextDialogue = 12010527,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112CEC"
        },
        [12010527] = {
          Content = "哎呀，原来你们还不知道<H>香</>的妙用，是我这个东道主失职了！",
          DialogueId = 12010527,
          GUID = "1E112D16",
          NextDialogue = 12010528,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D16"
        },
        [12010528] = {
          Content = "在华胥，香可不仅仅是装饰。它维持着大风九章的运转，也能让我们得到上天的庇佑。",
          DialogueId = 12010528,
          GUID = "1E112D40",
          NextDialogue = 12010529,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D40"
        },
        [12010529] = {
          Content = "刚刚，我见你们受袭心急，便将身上佩戴的香囊扔了出去，希望能对你们有所裨益。",
          DialogueId = 12010529,
          GUID = "1E112D6A",
          NextDialogue = 12010530,
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D6A"
        },
        [12010530] = {
          Content = "它虽然无法杀伤玄色狴犴，但足以帮我们抵挡一阵子。只是，香的作用发挥之后，必须到白龙祠堂去重新获取赐福。",
          DialogueId = 12010530,
          GUID = "1E112D94",
          NextDialogue = 12010531,
          RelatedWikiId = {
            [1] = 403005
          },
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D94"
        },
        [12010531] = {
          Content = "懂了懂了——也就是去白龙祠堂祈福，我们就不用那么害怕坏狴犴了，对吧！",
          DialogueId = 12010531,
          GUID = "1E112DBE",
          NextDialogue = 12010532,
          RelatedWikiId = {
            [1] = 405011
          },
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112DBE"
        },
        [12010532] = {
          Content = "当然，白龙祠堂前的香火可旺盛啦。走吧，带你们一起去见识见识！",
          DialogueId = 12010532,
          GUID = "1E112DE8",
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112DE8"
        },
        [12010533] = {
          Content = "喂喂，刚刚打起来之后，你怎么一溜烟地就跑不见了。",
          DialogueId = 12010533,
          GUID = "1E112E12",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12010534,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E12"
        },
        [12010534] = {
          Content = "毕竟我手无缚鸡之力……帮不上什么忙嘛。但是我有在一旁为你们摇旗呐喊哦！",
          DialogueId = 12010534,
          GUID = "1E112E3C",
          NextDialogue = 12010535,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E3C"
        },
        [12010535] = {
          Content = "这样说起来，第一次遇到白的时候，好像也发生过类似的事情呢。",
          DialogueId = 12010535,
          GUID = "1E112E66",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12010536,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E66"
        },
        [12010536] = {
          Content = "噗嗤，原来白魔王大人也这么不拘小节。",
          DialogueId = 12010536,
          GUID = "1E112E90",
          NextDialogue = 12010537,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E90"
        },
        [12010537] = {
          Content = "小、小仆从，你不要搞错了，那明明是在考验你的实力……",
          DialogueId = 12010537,
          GUID = "1E112EBA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120105/1E112EBA"
        },
        [12010601] = {
          Camera = "362.59375,523.266724,128.501953,0.000092,0.196914,-127.178719,35.000011,100000.0,false,Manual,2.8",
          Content = "前面就是啦，位于巨木之根，烟津渡区域规模最大的商会——百年春！",
          DialogueId = 12010601,
          Duration = 4,
          GUID = "1E11393A",
          NextDialogue = 12010602,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 303008
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120106/1E11393A"
        },
        [12010602] = {
          Content = "愿此香华云，直达太皓处，恳求大慈悲，施与众生乐。",
          DialogueId = 12010602,
          GUID = "1E113964",
          NextDialogue = 12010603,
          SpeakNpcName = "UI_CMName_Name_DevoutPilgrims",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113964"
        },
        [12010603] = {
          Content = "这么多人在祈愿……白龙神君回应得过来吗？",
          DialogueId = 12010603,
          GUID = "1E11398E",
          NextDialogue = 12010604,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120106/1E11398E"
        },
        [12010604] = {
          Content = "呵呵，<H>奉香</>可不能视为众人向白龙神君进行索取的仪式。",
          DialogueId = 12010604,
          GUID = "1E1139B8",
          NextDialogue = 12010605,
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120106/1E1139B8"
        },
        [12010605] = {
          Content = "先前说过，大风九章需要以“香”为介质去维持运转。",
          DialogueId = 12010605,
          GUID = "1E1139E2",
          NextDialogue = 12010606,
          RelatedWikiId = {
            [1] = 403005
          },
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120106/1E1139E2"
        },
        [12010606] = {
          Content = "人们向上天奉香维持着大风九章，大风九章的意志则化形为白龙神君。人们尊奉神君的意志，祂又通过香庇佑人们。",
          DialogueId = 12010606,
          GUID = "1E113A0C",
          NextDialogue = 12010607,
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A0C"
        },
        [12010607] = {
          Content = "愿望要靠勤耕不辍去一步步实现，白龙神君只是见证这一过程，千年皆是如此。",
          DialogueId = 12010607,
          GUID = "1E113A36",
          NextDialogue = 12010608,
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A36"
        },
        [12010608] = {
          Content = "不过，偶尔也会出现几位福星，能够得到白龙神君的青睐，获得意想不到的好处呢。",
          DialogueId = 12010608,
          GUID = "1E113A60",
          NextDialogue = 12010609,
          SpeakNpcId = 210033,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A60"
        },
        [12010609] = {
          Content = "哎？白有点好奇。来都来了，白也想体验一下！",
          DialogueId = 12010609,
          GUID = "1E113A8A",
          NextDialogue = 12010610,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A8A"
        },
        [12010610] = {
          Content = "那，你去找香案边上的那位！他是<H>悬衡派</>的香官，负责主持祠堂的秩序。",
          DialogueId = 12010610,
          GUID = "1E113AB4",
          NextDialogue = 12010611,
          RelatedWikiId = {
            [1] = 407006
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113AB4"
        },
        [12010611] = {
          Content = "悬衡派……你好像说过，是那位“天人相感”的大风九章奠基者开创的门派？",
          DialogueId = 12010611,
          GUID = "1E113ADE",
          NextDialogue = 12010612,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113ADE"
        },
        [12010612] = {
          Content = "没错！看来{nickname}有认真听课，我很欣慰哦。",
          DialogueId = 12010612,
          GUID = "1E113B08",
          NextDialogue = 12010613,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B08"
        },
        [12010613] = {
          Content = "在上古时期，悬衡派最先发现了香的神奇功效，并作为独门秘方一直传承了下来。",
          DialogueId = 12010613,
          GUID = "1E113B32",
          NextDialogue = 12010614,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B32"
        },
        [12010614] = {
          Content = "直至今日，悬衡派也一直负责着华胥境内的奉香事宜。一路上看到的香炉都是他们的手笔。",
          DialogueId = 12010614,
          GUID = "1E113B5C",
          NextDialogue = 12010615,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B5C"
        },
        [12010615] = {
          Content = "每人每天能找悬衡派的官员无偿领取三支香。你们也去试试看吧！",
          DialogueId = 12010615,
          GUID = "1E113B86",
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B86"
        },
        [12010616] = {
          Content = "愿你善根常驻。",
          DialogueId = 12010616,
          GUID = "1E113BB0",
          Scripts = "SEQ{\nPlayAnimation{ActorId{210034},AnimationId{\"Pray_Start\"},Duration{1.83}},\nPlayAnimation{ActorId{210034},AnimationId{\"Pray_Loop\"},Duration{1}},\nPlayAnimation{ActorId{210034},AnimationId{\"Pray_End\"},Duration{1.87}}\n}",
          SpeakNpcId = 210034,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113BB0"
        },
        [12010617] = {
          Content = "来，最后一段路啦！",
          DialogueId = 12010617,
          Duration = 2,
          GUID = "1E113BDA",
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120106/1E113BDA"
        },
        [12010701] = {
          Camera = "520.380859,617.213379,-28.979492,0.000073,13.797665,-129.582932,35.000008,100000.0,false,Manual,2.8",
          Content = "前面就是百年春的办事处！止流大当家现在估计就在上面等着你们呢。我就带路到这里了，你们自己上去吧。",
          DialogueId = 12010701,
          GUID = "1E1149A2",
          NextDialogue = 12010702,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 406004
          },
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120107/1E1149A2"
        },
        [12010702] = {
          Camera = "325.501953,283.450684,112.541016,0.000078,0.797322,-149.78244,35.000008,100000.0,false,Manual,2.8",
          Content = "我的铺位在这里，有空要来找我玩哦。如果想买什么，给你们打九九九八折！",
          DialogueId = 12010702,
          GUID = "1E1149CC",
          NextDialogue = 12010703,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120107/1E1149CC"
        },
        [12010703] = {
          Content = "等等——多少？我没听错吧？怎么这么小气！",
          DialogueId = 12010703,
          GUID = "1E1149F6",
          NextDialogue = 12010704,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120107/1E1149F6"
        },
        [12010704] = {
          Content = "毕竟约定过了，要成为华胥第一的织星客嘛！",
          DialogueId = 12010704,
          GUID = "1E114A20",
          NextDialogue = 12010705,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A20"
        },
        [12010705] = {
          Content = "锦鲤皎皎没有角，已经输在起跑线上了。如果不加倍地投机取巧，锱铢必较，勤能补拙，是达不到这个目标的！",
          DialogueId = 12010705,
          GUID = "1E114A4A",
          NextDialogue = 12010706,
          SpeakNpcId = 210003,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A4A"
        },
        [12010706] = {
          Content = "原、原来是这样吗……",
          DialogueId = 12010706,
          GUID = "1E114A74",
          NextDialogue = 12010707,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A74"
        },
        [12010707] = {
          Content = "让你到处带坏别的皎皎，这下知道错了吧。",
          DialogueId = 12010707,
          GUID = "1E114A9E",
          NextDialogue = 12010708,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A9E"
        },
        [12010708] = {
          Content = "咳咳……小仆从，我们赶紧走吧，别让金主大人久等了！",
          DialogueId = 12010708,
          GUID = "1E114AC8",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114AC8"
        },
        [12010709] = {
          Camera = "-10.451172,-172.71875,172.462891,0.000043,-13.01181,100.396614,24.0,100000.0,false,Manual,22.0",
          Content = "……适才情绪激动，如今冷静下来仔细想想，确是我做得不妥了。",
          DialogueId = 12010709,
          FacialId = {
            [1] = "210006:CM_Sad01"
          },
          GUID = "1E114AF2",
          LookAt = {
            [1] = "210005:n(210006)",
            [2] = "210033:n(210006)"
          },
          NextDialogue = 12010710,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 406004
          },
          SpeakNpcId = 210005,
          TalkActionId = {
            [1] = "210006:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114AF2"
        },
        [12010710] = {
          Content = "实在是我病急乱投医，昏了头才会从外面雇来个底细不清的人，还想凭一己之力闯一闯，将货物运到对面去。",
          DialogueId = 12010710,
          GUID = "1E114B1C",
          NextDialogue = 12010711,
          SpeakNpcId = 210005,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B1C"
        },
        [12010711] = {
          Camera = "-23.115234,32.113281,166.745117,0.000075,-7.412141,88.993202,35.0,100000.0,false,Manual,22.0",
          Content = "结果那武人是个花架子，非但应付不来玄色狴犴，还是个心术不正、鸡鸣狗盗之徒，平白惹出这么多事端。我在这里给乡亲父老们赔礼了！",
          DialogueId = 12010711,
          GUID = "1E114B46",
          LookAt = {
            [1] = "210006:n(210005)"
          },
          NextDialogue = 12010712,
          SpeakNpcId = 210005,
          TalkActionId = {
            [1] = "210006:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B46"
        },
        [12010712] = {
          Camera = "142.71875,232.458008,189.438477,0.000114,-18.212145,-157.608566,24.0,100000.0,false,Manual,22.0",
          Content = "您也不必如此自责。大家这些天心急如焚，百年春都看在眼里。",
          DialogueId = 12010712,
          GUID = "1E114B70",
          LookAt = {
            [1] = "210005:n(210033)",
            [2] = "210006:n(210033)"
          },
          NextDialogue = 12010713,
          SpeakNpcId = 210022,
          TalkActionId = {
            [1] = "210033:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B70"
        },
        [12010713] = {
          Content = "目前我们也在积极寻找对策，早日化解当下的危机，让大家的生意可以重回正轨。",
          DialogueId = 12010713,
          GUID = "1E114B9A",
          NextDialogue = 12010714,
          SpeakNpcId = 210022,
          TalkActionId = {
            [1] = "210033:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B9A"
        },
        [12010714] = {
          Camera = "-47.478516,-40.796875,121.547852,0.000145,2.387158,110.985695,35.0,100000.0,false,Manual,22.0",
          Content = "只是，这禁行令还要延续多久呢？我们织星客等得起，货可等不起啊……",
          DialogueId = 12010714,
          FacialId = {
            [1] = "210005:Unacceptable01"
          },
          GUID = "1E114BC4",
          LookAt = {
            [1] = "210006:n(210005)",
            [2] = "210033:n(210005)"
          },
          NextDialogue = 12010715,
          RelatedWikiId = {
            [1] = 407007
          },
          SpeakNpcId = 210006,
          TalkActionId = {
            [1] = "210005:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114BC4"
        },
        [12010715] = {
          Content = "这个时节的药草，要趁刚摘下来，还沾着露水的新鲜劲，才能卖出个好价钱。放在篮子里，那是日日都在贬值啊。",
          DialogueId = 12010715,
          FacialId = {
            [1] = "210005:CM_Idle"
          },
          GUID = "1E114BEE",
          NextDialogue = 12010716,
          SpeakNpcId = 210006,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114BEE"
        },
        [12010716] = {
          Camera = "-53.175781,137.40918,147.086914,0.000151,-8.01328,-123.215157,35.0,100000.0,false,Manual,22.0",
