          Scripts = "SEQ{\nPlayAnimation{_delay{1.5},ActorId{210004},AnimationId{\"Explain01_End\"},Duration{1}},\nPlayAnimation{_delay{3.5},ActorId{210004},AnimationId{\"Talk03_Start\"},Duration{1}},\n}",
          SpeakNpcId = 210004,
          VoiceName = "voice/$Locale$/story/1201/120109/1E116AC6"
        },
        [12010904] = {
          Camera = "-91.798035,-58.921486,145.460938,0.001206,-6.398227,74.011063,35.0,283.8638,false,Manual,4.0",
          Content = "但由于玄色狴犴肆虐，通讯断绝，至今还未送来。可能需要你亲自去取。",
