          Duration = 5,
          GUID = "1E117BAC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120110/1E117BAC"
        },
        [12011101] = {
