          GUID = "1E118BC0",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E118BC0"
        },
        [12011201] = {
