          Duration = 2,
          GUID = "1E119BAA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 12011202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120112/1E119BAA"
        },
        [12011202] = {
