          Camera = "622.662109,-1112.847656,421.122559,0.000177,-10.60076,113.988228,40.0,243.196228,false,DoNotOverride,3.746801",
          Content = "只能在这附近转转，看看有没有机会见到那位虬先生了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012115,
          FinalCamera = "841.544922,-1591.740234,696.769043,0.000171,-15.400682,114.189644,40.0,243.196228,false,DoNotOverride,3.746801",
          GUID = "1E12319E",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1201/120121/1E12319E"
        },
        [12012201] = {
          Content = "你——简直欺人太甚！！",
          DialogueId = 12012201,
          Duration = 2,
          GUID = "1E123FBA",
          NextDialogue = 12012202,
          SpeakNpcId = 210011,
          SpeakNpcName = "？？？",
          VoiceName = "voice/$Locale$/story/1201/120122/1E123FBA"
        },
        [12012202] = {
          Content = "小仆从，对面好像起了什么争执！我们赶紧过去看看热闹！",
          DialogueId = 12012202,
          Duration = 3,
          GUID = "1E123FE4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120122/1E123FE4"
        },
        [12012301] = {
          Camera = "353.783203,574.717773,227.101074,0.000003,-5.60001,-117.193687,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "今日在这里，我横竖也要讨个说法——",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012301,
          GUID = "1E125022",
          NextDialogue = 12012302,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012
          },
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125022"
        },
        [12012302] = {
          Content = "你诓骗家父签下了假契书，害得佘家家财尽散。母亲受此打击也一病不起，郁郁而终。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012302,
          GUID = "1E12504C",
          NextDialogue = 12012303,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E12504C"
        },
        [12012303] = {
          Content = "贪了人钱财性命，自己却脱身事外……这黑市还有没有王法存在？！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012303,
          GUID = "1E125076",
          NextDialogue = 12012304,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125076"
        },
        [12012304] = {
          Content = "您说笑呢——大风九章，不就是这华胥的王法？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012304,
          GUID = "1E1250A0",
          NextDialogue = 12012305,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1250A0"
        },
        [12012305] = {
          Content = "那狴犴，应天尉，都双目如炬地盯着咱呢。咱要是敢作奸犯科，早就被狴犴给逮了去了。还能站在这里说话？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012305,
          GUID = "1E1250CA",
          NextDialogue = 12012306,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1250CA"
        },
        [12012306] = {
          Content = "诫条刻在那儿呢：毁约背盟，不可为也。咱只是照章办事，遵纪守法的小百姓一个呀。你血口喷人，咱心善，姑且不追究了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012306,
          GUID = "1E1250F4",
          NextDialogue = 12012307,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1250F4"
        },
        [12012307] = {
          Content = "你……你怎么恶人先告状！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012307,
          GUID = "1E12511E",
          NextDialogue = 12012308,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E12511E"
        },
        [12012308] = {
          Content = "要是正常的生意盈亏，我们便也认下了。但你事后拿出的那份契书，分明是在诓骗、敲诈！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012308,
          GUID = "1E125148",
          NextDialogue = 12012309,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125148"
        },
        [12012309] = {
          Content = "哎呀，令尊签字画押时……莫非不识字？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012309,
          GUID = "1E125172",
          NextDialogue = 12012310,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125172"
        },
        [12012310] = {
          Content = "（群众哄笑声。）",
          DialogueId = 12012310,
          GUID = "1E12519C",
          NextDialogue = 12012311,
          VoiceName = "voice/$Locale$/story/1201/120123/1E12519C"
        },
        [12012311] = {
          Content = "别强词夺理了！你看父亲年老眼花，故意把利息的“三倍”写成“三十倍”，还把“十”写得像芝麻一样小——",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012311,
          GUID = "1E1251C6",
          NextDialogue = 12012312,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1251C6"
        },
        [12012312] = {
          Content = "天地良心，你敢对白龙神君发誓，你不是故意诓骗家父吗？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012312,
          GUID = "1E1251F0",
          NextDialogue = 12012313,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1251F0"
        },
        [12012313] = {
          Content = "小姑娘，这我可就要给你上一课了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012313,
          GUID = "1E12521A",
          NextDialogue = 12012314,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E12521A"
        },
        [12012314] = {
          Content = "这普天之下，率土之滨，凡是可为的，皆属大风九章默许的。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012314,
          GUID = "1E125244",
          NextDialogue = 12012315,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125244"
        },
        [12012315] = {
          Content = "大风九章只管咱们是否守契，又不管这契文怎么写。莫说这“十”字是大是小，就算我给它上面画根麻花，我照样好端端地站在这儿。你又能拿我如何？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012315,
          GUID = "1E12526E",
          NextDialogue = 12012316,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E12526E"
        },
        [12012316] = {
          Content = "你……！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012316,
          GUID = "1E125298",
          NextDialogue = 12012317,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125298"
        },
        [12012317] = {
          Content = "今天我就站在这里不走了。我要让每个路过的客人都知道你的所作所为！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012317,
          GUID = "1E1252C2",
          NextDialogue = 12012318,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1252C2"
        },
        [12012318] = {
          Content = "（议论纷纷的嘈杂音。）",
          DialogueId = 12012318,
          GUID = "1E1252EC",
          NextDialogue = 12012319,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1252EC"
        },
        [12012319] = {
          Content = "好了好了。大伙儿都围在这里，照这样下去，这生意没法做啦。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012319,
          GUID = "1E125316",
          NextDialogue = 12012320,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125316"
        },
        [12012320] = {
          Content = "听好了，咱也不是什么恶贯满盈的主。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012320,
          GUID = "1E125340",
          NextDialogue = 12012321,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125340"
        },
        [12012321] = {
          Content = "本来这生意，就该买定离手，风险自负。今儿个我欣赏你这小姑娘的骨气，就破例给你一个翻盘的机会。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012321,
          GUID = "1E12536A",
          NextDialogue = 12012322,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E12536A"
        },
        [12012322] = {
          Content = "……你说。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012322,
          GUID = "1E125394",
          NextDialogue = 12012323,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125394"
        },
        [12012323] = {
          Content = "看到我手下这弱不禁风的小兄弟了吗？按照我们黑市的规矩，你若是能在单挑中赢了他，我便把令尊的欠款连本带息地如数奉还。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012323,
          GUID = "1E1253BE",
          NextDialogue = 12012324,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1253BE"
        },
        [12012324] = {
          Content = "单挑？可是华胥禁武，又怎会允许私下械斗……？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012324,
          GUID = "1E1253E8",
          NextDialogue = 12012325,
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E1253E8"
        },
        [12012325] = {
          Content = "瞧您说的。这只是点到为止的切磋，双方只用招式，不伤皮肉，怎会惊动狴犴和应天尉呢。有大风九章护着，您也不用怕自己的性命出什么差池。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012325,
          GUID = "1E125412",
          NextDialogue = 12012326,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125412"
        },
        [12012326] = {
          Content = "您若是担心咱使什么手段，可以当场起草一份契书，条款都由您亲自书写，总能放心了吧。要是这点胆量都没有，那还请您不要打扰此地生意了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012326,
          GUID = "1E12543C",
          NextDialogue = 12012327,
          SpeakNpcId = 210009,
          VoiceName = "voice/$Locale$/story/1201/120123/1E12543C"
        },
        [12012327] = {
          Content = "……好，我答应！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012327,
          GUID = "1E125466",
          SpeakNpcId = 210011,
          VoiceName = "voice/$Locale$/story/1201/120123/1E125466"
        },
        [12012401] = {
          Content = "他答应得这么爽快……怕是有诈。",
          DialogueId = 12012401,
          Duration = 2,
          GUID = "1E12608A",
          NextDialogue = 12012402,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120124/1E12608A"
        },
        [12012402] = {
          Content = "呜哇，围观的人越来越多了……可恶，踮起脚都看不到。",
          DialogueId = 12012402,
          Duration = 3,
          GUID = "1E1260B4",
          NextDialogue = 12012403,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120124/1E1260B4"
        },
        [12012403] = {
          Content = "小仆从，我们挤到前排去吧。",
          DialogueId = 12012403,
          Duration = 2,
          GUID = "1E1260DE",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120124/1E1260DE"
        },
        [12012501] = {
          Camera = "353.783203,574.717773,227.101074,0.000003,-5.60001,-117.193687,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "随着双方揖礼，比试正式开始。",
          DialogueId = 12012501,
          GUID = "1E1270F2",
          NextDialogue = 12012511,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012
          },
          VoiceName = "voice/$Locale$/story/1201/120125/1E1270F2"
        },
        [12012502] = {
          Content = "小仆从，我看不太明白。但好像……那个姑娘占了上风？那她是不是有翻盘的机会了！",
          DialogueId = 12012502,
          GUID = "1E12711C",
          NextDialogue = 12012503,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120125/1E12711C"
        },
        [12012503] = {
          Content = "总感觉黑市的人在隐藏自己的实力……",
          DialogueId = 12012503,
          GUID = "1E127146",
          NextDialogue = 12012504,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120125/1E127146"
        },
        [12012504] = {
          Content = "不好。那个人，在故意往她刀口上撞——！",
          DialogueId = 12012504,
          GUID = "1E127170",
          NextDialogue = 12012512,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120125/1E127170"
        },
        [12012505] = {
          Content = "他、他为什么要干这种事情？！",
          DialogueId = 12012505,
          GUID = "1E12719A",
          NextDialogue = 12012510,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120125/1E12719A"
        },
        [12012506] = {
          Content = "原来如此……这样大风九章会判定那女孩伤了人，狴犴会惩罚她！",
          DialogueId = 12012506,
          GUID = "1E1271C4",
          NextDialogue = 12012507,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120125/1E1271C4"
        },
        [12012507] = {
          Content = "糟糕，她控制不住自己的力道了。必须在事态发酵之前分开他们！",
          DialogueId = 12012507,
          GUID = "1E1271EE",
          NextDialogue = 12012508,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120125/1E1271EE"
        },
        [12012508] = {
          Content = "嗷呜——",
          DialogueId = 12012508,
          GUID = "1E127218",
          VoiceName = "voice/$Locale$/story/1201/120125/1E127218"
        },
        [12012509] = {
          Content = "由于你的及时救援，黑市商人只“蹭”到了肋下的一处伤口。\n狴犴击伤年轻姑娘以示惩戒，随后在凛风中隐去。",
          DialogueId = 12012509,
          Duration = 4,
          GUID = "1E127242",
          VoiceName = "voice/$Locale$/story/1201/120125/1E127242"
        },
        [12012510] = {
          Content = "对于触犯诫律者，狴犴会从凛风中突现，施以惩戒。",
          DialogueId = 12012510,
          GUID = "1E12726C",
          NextDialogue = 12012506,
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FCB0"
        },
        [12012511] = {
