          VoiceName = "voice/$Locale$/story/1201/120140/1E136A52"
        },
        [12014022] = {
          Content = "她的伤势现在怎么样了？",
          DialogueId = 12014022,
          GUID = "1E136A7C",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014023,
