          },
          Scripts = "PARA{\nLookAt{LookAtDescription{\"210013:n(200002)\"}},\nLookAt{_delay{4.1},LookAtDescription{\"210013:n(100001)\"}},\n}",
          SpeakNpcId = 210013,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BCC"
        },
        [12014031] = {
          Camera = "59.27887,-13.943413,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          Content = "它由华胥独特的水土蕴养出。以无处不在的香料做引，有些人临终时的执念会化为一种叫做“无由生”的特殊生灵。",
          DialogueId = 12014031,
          FinalCamera = "60.464428,-21.080315,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          GUID = "1E136BF6",
          NextDialogue = 12014032,
          RelatedWikiId = {
            [1] = 303012
          },
          SpeakNpcId = 210013,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BF6"
        },
        [12014032] = {
          Camera = "-147.81781,5.32869,142.967773,0.000243,-4.796145,-93.967758,35.000011,86.214539,false,Manual,7.41853",
          Content = "虞泉即为无由生的栖居之地。只有心思澄澈的儿童，或是受到它们邀请的人类，能够踏入虞泉的界域。",
          DialogueId = 12014032,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-147.885712,4.413391,142.889648,0.000242,-4.796145,-93.967621,35.000008,80.332993,false,Manual,7.41853",
          GUID = "1E136C20",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014033,
          SpeakNpcId = 210013,
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C20"
        },
        [12014033] = {
          Camera = "-294.044525,50.440552,165.479492,0.000202,-16.597221,-20.770725,40.0,289.488281,false,Manual,6.491352",
          Content = "听起来很神奇的样子……！那我和小仆从可以去这个地方吗？",
          DialogueId = 12014033,
          FacialId = {
            [1] = "200002:Happy02"
          },
          FinalCamera = "-294.044525,50.440552,165.479492,0.000197,-17.597284,-17.170553,40.0,289.488281,false,Manual,6.491352",
          GUID = "1E136C4A",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "200002:n(210013)"
          },
          NextDialogue = 12014034,
          Scripts = "PARA{\nPlayAnimation{_delay{3.1},ActorId{200002},AnimationId{\"SpecialHappy_Start\"},Duration{1}},\nPlayFacial{_delay{2.5},ActorId{100001},FacialId{\"Happy01\"}}\n}",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "100001:p(-75)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C4A"
        },
        [12014034] = {
          Camera = "139.226379,128.650238,49.652344,0.000156,11.202827,-146.769257,40.0,369.932373,false,Manual,6.0",
          Content = "自然可以。跟紧了，我为你们引路。",
          DialogueId = 12014034,
          GUID = "1E136C74",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          Scripts = "SEQ{\nLookAt{_delay{0.5},LookAtDescription{\"210013:n(100001)\"}},\nPlayAnimation{_delay{1.1},ActorId{210013},AnimationId{\"Baiheng_Story_Special01_Start\"},Duration{1}},\nPlayAnimation{ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}\n}",
          SpeakNpcId = 210013,
          TalkActionId = {
