          Content = "若你们看到它们受困，还请施以援手……那边的小无由生为此可是日夜痛哭不已唷。",
          DialogueId = 12015532,
          FinalCamera = "81.046371,94.984283,109.258301,0.000052,-25.15588,33.813671,45.000011,118.771225,false,Manual,8.928488",
          GUID = "1E146238",
