        [12018404] = {
          Camera = "-52.819229,197.234238,148.239014,0.000148,5.597148,-120.211037,35.000011,164.675781,false,Manual,6.0",
          Content = "兵贵神速。若是为了无谓的口舌，耽误了最佳时机，那猎物可就要逃了。",
          DialogueId = 12018404,
          FacialId = {
            [1] = "210012:Doubt01"
          },
          GUID = "1E163968",
          NextDialogue = 12018405,
          Scripts = "PlayAnimation{_delay{1},ActorId{210012},AnimationId{"Talk03ToThink_End"},Duration{2}},",
          SpeakNpcId = 210012,
          VoiceName = "voice/$Locale$/story/1201/120184/1E163968"
        },
        [12018405] = {
          Camera = "-63.644783,133.544785,118.57605,0.000155,11.196975,138.185074,35.000011,122.361931,false,Manual,6.0",
          Content = "那是你要考虑的。我只在意这次行动有没有危险，以及——是否正当。",
          DialogueId = 12018405,
          FacialId = {
            [1] = "100001:Angry01"
          },
          FinalCamera = "-63.644783,133.544785,118.57605,0.000169,16.996433,-169.21553,35.000011,122.361931,false,Manual,6.0",
          GUID = "1E163992",
