          GUID = "1E169B85",
          NextDialogue = 12019051,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B85"
        },
        [12019051] = {
          Content = "用意很明显了。顺着机关块亮起的顺序前行，就能破解当下的困局。",
          DialogueId = 12019051,
          GUID = "1E169B86",
          NextDialogue = 12019052,
          SpeakNpcId = 210012,
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B86"
        },
        [12019052] = {
          Content = "……这种事情不需要你提醒，我们小仆从也知道！",
          DialogueId = 12019052,
          GUID = "1E169B87",
          NextDialogue = 12019053,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B87"
        },
        [12019053] = {
          Content = "好，那我试试。",
          DialogueId = 12019053,
          GUID = "1E169B88",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B88"
        },
        [12019054] = {
          Content = "哇啊啊啊啊，这些机关块怎么还会动，要是不小心踩空就摔下去了！",
