          GUID = "1E169B92",
          NextDialogue = 12019057,
          SpeakNpcId = 210012,
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B92"
        },
        [12019057] = {
          Content = "哼，轮不到你来说！",
          DialogueId = 12019057,
          GUID = "1E169B93",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B93"
        },
        [12019058] = {
          Content = "呀！哪里冒出来的家伙，会动……还打我们！",
          DialogueId = 12019058,
          GUID = "1E169B94",
          NextDialogue = 12019059,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B94"
        },
        [12019059] = {
