        },
        [12019202] = {
          Content = "虬先生不知道掉到哪里去了……",
          DialogueId = 12019202,
          GUID = "1E16BC54",
          NextDialogue = 12019203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC54"
        },
        [12019203] = {
