          DialogueId = 12019203,
          GUID = "1E16BC7E",
          NextDialogue = 12019204,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC7E"
        },
        [12019204] = {
          Content = "等等，小仆从！前面有人！",
