          GUID = "1E1DFD30",
          NextDialogue = 12030521,
          Scripts = "SEQ{\nPlayFacial{ActorId{211001},FacialId{\"Happy02\"}},\nPlayAnimation{ActorId{211001},AnimationId{\"AgreeHead\"},Duration{1}},\nPlayFacial{ActorId{211001},FacialId{\"None\"}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFD30"
        },
        [12030521] = {
          Camera = "-253.641113,416.605469,138.781738,0.000156,-6.998512,-71.883408,24.419483,1094.441895,false,Manual,15.0",
          ContentFR = "C’est simple ! Un joueur est le Glouton, les autres sont des patates grillées. Le Glouton ferme les yeux et compte pendant que les patates vont se cacher.",
          DialogueId = 12030521,
          FinalCamera = "-240.412598,376.173828,133.561035,0.000156,-6.998512,-71.883408,24.419483,1094.441895,false,Manual,15.0",
          GUID = "1E1DFD5A",
          NextDialogue = 12030522,
          SpeakNpcId = 211011,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFD5A"
        },
        [12030522] = {
          ContentFR = "Quand il a fini de compter jusqu’à soixante, il ouvre les yeux et part à la chasse. S’il en attrape une — miam — il la dévore !",
          DialogueId = 12030522,
          GUID = "1E1DFD84",
          NextDialogue = 12030523,
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFD84"
        },
        [12030523] = {
          ContentFR = "S’il dévore toutes les patates en trois minutes, il gagne. Sinon, il tombe dans les pommes de faim, et les patates remportent la partie !",
          DialogueId = 12030523,
          GUID = "1E1DFDAE",
          NextDialogue = 12030524,
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFDAE"
        },
        [12030524] = {
          Camera = "-58.322266,-105.651367,119.556152,0.000138,0.401116,79.010231,35.000019,178.36145,false,Manual,2.8",
          ContentFR = "Mais... des patates, ça ne bouge pas... Pourquoi elles courent ?",
          DialogueId = 12030524,
          FinalCamera = "-56.606445,-96.818359,119.618652,0.000138,0.401116,79.010231,35.000019,159.390686,false,Manual,2.8",
          GUID = "1E1DFDD8",
          NextDialogue = 12030525,
          Scripts = "PARA{\nPlayFacial{ActorId{211001},FacialId{\"Think01\"}},\nPlayAnimation{ActorId{211001},AnimationId{\"Think_Start\"},Duration{1}},\nPlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_CuteHairAction_Loop\"},Duration{1}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFDD8"
        },
        [12030525] = {
          Camera = "-157.704102,-477.165039,108.151855,0.000125,-0.99884,82.013466,35.000015,251.595764,false,Manual,22.0",
          ContentFR = "Ah ouais, c’est vrai... Celles de ma maman, elles restent dans l’assiette.",
          DialogueId = 12030525,
          GUID = "1E1DFE02",
          NextDialogue = 12030526,
          SpeakNpcId = 211010,
          TalkActionId = {
            [1] = "211010:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE02"
        },
        [12030526] = {
          ContentFR = "Mais... c’est pas ça le plus important !",
          DialogueId = 12030526,
          GUID = "1E1DFE2C",
          NextDialogue = 12030527,
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE2C"
        },
        [12030527] = {
          Camera = "-27.393555,-102.768555,119.618652,0.000139,-0.198916,89.009705,35.000019,159.390686,false,Manual,2.8",
          ContentFR = "Attends… j’ai compris ! Ce sont des patates magiques... bénies par un gentil magicien !",
          DialogueId = 12030527,
          FinalCamera = "-26.844238,-70.899414,119.508301,0.000139,-0.198916,89.009674,35.000019,129.833313,false,Manual,2.8",
          GUID = "1E1DFE56",
          NextDialogue = 12030528,
          Scripts = "PARA{\nLookAt{LookAtDescription{\"211001:n(211011)\"}},\nPlayAnimation{ActorId{211001},AnimationId{\"Think_End\"},Duration{1}},\nPlayFacial{ActorId{211001},FacialId{\"None\"}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE56"
        },
        [12030528] = {
          ContentFR = "Ohhh ! Alors moi, je veux être la plus forte patate magique !",
          DialogueId = 12030528,
          GUID = "1E1DFE80",
          NextDialogue = 12030529,
          SpeakNpcId = 211010,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE80"
        },
        [12030529] = {
          ContentFR = "Des patates magiques... ça doit être trop bon...",
          DialogueId = 12030529,
          GUID = "1E1DFEAA",
          NextDialogue = 12030530,
          SpeakNpcId = 211013,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFEAA"
        },
        [12030530] = {
          Camera = "-224.390625,-505.521484,146.001465,0.000133,-7.598578,76.013123,35.000019,329.374176,false,Manual,22.0",
          ContentFR = "Parfait ! Alors nous, on sera les patates. Et Fina, toi, tu seras le Glouton ! Ça te va ?",
          DialogueId = 12030530,
          FinalCamera = "-229.759766,-527.399414,148.927734,0.000134,-7.398529,76.212738,35.000019,329.374176,false,Manual,22.0",
          GUID = "1E1DFED4",
          NextDialogue = 12030531,
          SpeakNpcId = 211011,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFED4"
        },
        [12030531] = {
          Camera = "-94.611328,-127.818359,128.793945,0.000135,-2.398503,70.012207,35.000019,329.374176,false,Manual,22.0",
          ContentFR = "Oui ! Alors je ferme les yeux... et je commence à compter... Un... deux... trois...",
          DialogueId = 12030531,
          FinalCamera = "-89.286133,-113.015625,128.135254,0.000136,-2.398503,70.212196,35.000019,329.374176,false,Manual,22.0",
          GUID = "1E1DFEFE",
          Scripts = "PlayFacial{_delay{2},ActorId{211001},FacialId{"Confident02"}}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFEFE"
        },
        [12030532] = {
          Content = "转场，小孩们消失，出现三个调查点（没有先后顺序）",
          DialogueId = 12030532,
          GUID = "1E1DFF28",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFF28"
        },
        [12030601] = {
          ContentFR = "Hmm... où se cachent donc ces patates grillées... ?",
          DialogueId = 12030601,
          GUID = "1E1E0A7A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0A7A"
        },
        [12030605] = {
          ContentFR = "Point d’intérêt n° 1",
          DialogueId = 12030605,
          GUID = "1E1E0B22",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0B22"
        },
        [12030610] = {
          ContentFR = "Oh... ce n’est qu’une planche branlante.",
          DialogueId = 12030610,
          GUID = "1E1E0BF4",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0BF4"
        },
        [12030615] = {
          ContentFR = "Point d’intérêt n° 2",
          DialogueId = 12030615,
          GUID = "1E1E0CC6",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0CC6"
        },
        [12030620] = {
          ContentFR = "Hein ? Petite, tu veux quelque chose ?",
          DialogueId = 12030620,
          GUID = "1E1E0D98",
          NextDialogue = 12030621,
          SpeakNpcId = 211016,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0D98"
        },
        [12030621] = {
          ContentFR = "Ah ! Désolée... je t’ai pris pour une patate grillée...",
          DialogueId = 12030621,
          GUID = "1E1E0DC2",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0DC2"
        },
        [12030625] = {
          ContentFR = "Point d’intérêt n° 3",
          DialogueId = 12030625,
          GUID = "1E1E0E6A",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0E6A"
        },
        [12030630] = {
          ContentFR = "Miaouuu.",
          DialogueId = 12030630,
          GUID = "1E1E0F3C",
          NextDialogue = 12030631,
          SpeakNpcId = 211008,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0F3C"
        },
        [12030631] = {
          ContentFR = "Oh, quel joli petit chat... Miaou, miaou... Ah ! Mais non, je dois chercher les patates grillées ! J’allais oublier !",
          DialogueId = 12030631,
          GUID = "1E1E0F66",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0F66"
        },
        [12030635] = {
          ContentFR = "Point bonus caché : interaction avec le protagoniste",
          DialogueId = 12030635,
          GUID = "1E1E100E",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E100E"
        },
        [12030640] = {
          ContentFR = "Hein ? {性别:Monsieur|Mademoiselle} Licorne ? Qu’est-ce que tu fais là ?",
          DialogueId = 12030640,
          GUID = "1E1E10E0",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E10E0"
        },
        [12030641] = {
          ContentFR = "Haha... Salut, Fina ! Je... je me promenais par ici. Quelle coïncidence, pas vrai ?",
          DialogueId = 12030641,
          GUID = "1E1E110A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E110A"
        },
        [12030642] = {
          ContentFR = "Je vois ! Ravie de te croiser. Mais Fina joue à un jeu en ce moment. La prochaine fois, on fera un vrai goûter ensemble, d’accord ?",
          DialogueId = 12030642,
          GUID = "1E1E1134",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1134"
        },
        [12030643] = {
          ContentFR = "Avec plaisir !",
          DialogueId = 12030643,
          GUID = "1E1E115E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E115E"
        },
        [12030645] = {
          ContentFR = "(Les trois points d’intérêt sont explorés. L’écran s’assombrit légèrement.)",
          DialogueId = 12030645,
          GUID = "1E1E11B2",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E11B2"
        },
        [12030650] = {
          ContentFR = "Et comme ça... trois minutes s’étaient déjà écoulées.",
          DialogueId = 12030650,
          GUID = "1E1E1284",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1284"
        },
        [12030701] = {
          Camera = "-360.602539,-341.077148,99.427734,0.000126,-3.59912,46.511829,35.000015,355.657684,false,DoNotOverride,22.0",
          ContentFR = "Héhé, les patates magiques ont gagné !",
          DialogueId = 12030701,
          FinalCamera = "-409.727051,-288.272461,99.427734,0.000127,-3.19909,37.711613,35.000015,355.657684,false,DoNotOverride,22.0",
          GUID = "1E1E1AE2",
          LookAt = {
