          },
          NextDialogue = 12030702,
          SpeakNpcId = 211011,
          TalkActionId = {
            [1] = "211011:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1AE2"
        },
        [12030702] = {
          ContentFR = "Oui ! Les trois patates sont sauves, et le Glouton a encore le ventre vide.",
          DialogueId = 12030702,
          GUID = "1E1E1B0C",
          LookAt = {
            [1] = "211001:n(211010)"
          },
          NextDialogue = 12030703,
          SpeakNpcId = 211010,
          TalkActionId = {
            [1] = "211010:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1B0C"
        },
        [12030703] = {
          Camera = "-131.468262,-22.850586,110.526367,0.000134,4.400882,43.107666,35.000015,355.657684,false,DoNotOverride,22.0",
          ContentFR = "Hmm... alors soit je suis trop lente... soit vous êtes vraiment trop malines, mes patates !",
          DialogueId = 12030703,
          FacialId = {
            [1] = "211001:Happy01"
          },
          GUID = "1E1E1B36",
          LookAt = {
            [1] = "211001:n(211001)",
            [2] = "211013:n(211001)"
          },
          NextDialogue = 12030704,
          Scripts = "SEQ{\nPARA{\nPlayFacial{ActorId{211001},FacialId{\"Disappoint01\"},Duration{1.3}},\nPlayAnimation{ActorId{211001},AnimationId{\"Explain02_Start\"},Duration{1.3}}\n},\nPlayFacial{ActorId{211001},FacialId{\"Happy02\"},Duration{1.3}}\n}",
          SpeakNpcId = 211001,
          TalkActionId = {
            [1] = "211010:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1B36"
        },
        [12030704] = {
          Camera = "-495.039551,-191.916016,131.40332,0.000119,-5.799226,20.708221,35.000015,355.657684,false,DoNotOverride,22.0",
          ContentFR = "C’est pas grave, Fina. Moi aussi, la première fois, j’ai pas réussi à croquer une seule patate...",
          DialogueId = 12030704,
          GUID = "1E1E1B60",
          LookAt = {
            [1] = "211001:n(211013)"
          },
          NextDialogue = 12030705,
          Scripts = "SEQ{\nPlayFacial{ActorId{211001},FacialId{\"None\"},Duration{1.3}},\nPlayAnimation{_delay{3},ActorId{211013},AnimationId{\"Explain02_Start\"},Duration{1.3}}\n}",
          SpeakNpcId = 211013,
          TalkActionId = {
            [1] = "211001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1B60"
        },
        [12030705] = {
          ContentFR = "Exactement ! Allez, on rejoue ! Cette fois, tu vas sûrement en croquer une !",
          DialogueId = 12030705,
          GUID = "1E1E1B8A",
          LookAt = {
            [1] = "211011:n(211001)",
            [2] = "211010:n(211010)",
            [3] = "211001:n(211011)"
          },
          NextDialogue = 12030706,
          Scripts = "SEQ{\nPlayAnimation{ActorId{211011},AnimationId{\"Agree\"},Duration{1.5}},\nPlayAnimation{_delay{3},ActorId{211011},AnimationId{\"Confident_Start\"},Duration{3}}\n}",
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1B8A"
        },
        [12030706] = {
          Camera = "-114.803711,-76.038086,121.975098,0.000119,-0.199209,59.907368,35.000015,355.657684,false,DoNotOverride,22.0",
          ContentFR = "Oui ! Je vais donner le meilleur de moi-même !",
          DialogueId = 12030706,
          GUID = "1E1E1BB4",
          Scripts = "SEQ{\nPARA{\nPlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1.5}},\nPlayFacial{ActorId{211001},FacialId{\"Smile01\"}}\n}\n}",
          SpeakNpcId = 211001,
          TalkActionId = {
