          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1BB4"
        },
        [12030707] = {
          ContentFR = "(Transition — les enfants disparaissent à nouveau. Deux nouveaux points d’intérêt apparaissent.)",
          DialogueId = 12030707,
          GUID = "1E1E1BDE",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E1BDE"
        },
        [12030801] = {
          ContentFR = "Cette fois... Fina doit absolument croquer au moins une patate grillée !",
          DialogueId = 12030801,
          GUID = "1E1E2B4A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2B4A"
        },
        [12030802] = {
          ContentFR = "Point d’intérêt n° 1",
          DialogueId = 12030802,
          GUID = "1E1E2B74",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2B74"
        },
        [12030803] = {
          Camera = "-85.531738,-346.707031,141.083008,0.000031,-16.992765,70.74736,14.158036,355.657684,false,DoNotOverride,22.0",
          ContentFR = "Couic-couic !",
          DialogueId = 12030803,
          GUID = "1E1E2B9E",
          NextDialogue = 12030804,
          SpeakNpcId = 211009,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2B9E"
        },
        [12030804] = {
          ContentFR = "Ah ! Pardon, Madame la Souris... Je ne voulais pas déranger votre petite réunion de famille !",
          DialogueId = 12030804,
          GUID = "1E1E2BC8",
          SpeakNpcId = 211001,
          TalkActionId = {
            [1] = "211001:Explain02_Start"
          },
