        },
        [12030805] = {
          ContentFR = "Point d’intérêt n° 2",
          DialogueId = 12030805,
          GUID = "1E1E2BF2",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2BF2"
        },
        [12030806] = {
          Camera = "-13.528439,144.419495,152.811523,0.000043,-19.598845,-113.979996,35.0,407.218628,false,DoNotOverride,4.0",
          ContentFR = "Miaou ?",
          DialogueId = 12030806,
          GUID = "1E1E2C1C",
