          SpeakNpcId = 211008,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2C1C"
        },
        [12030807] = {
          ContentFR = "Tiens... encore toi, mon petit chat !",
          DialogueId = 12030807,
          GUID = "1E1E2C46",
          LookAt = {
            [1] = "211001:n(211008)"
          },
          SpeakNpcId = 211001,
          TalkActionId = {
            [1] = "211001:Feina_Story_Wish_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2C46"
        },
        [12030808] = {
          ContentFR = "(Après avoir visité les deux lieux.)",
          DialogueId = 12030808,
          GUID = "1E1E2C70",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2C70"
        },
        [12030809] = {
          Camera = "3.253949,287.413086,119.643555,0.000092,-0.998888,-95.98925,35.000008,407.218628,false,DoNotOverride,4.0",
          ContentFR = "Oooh... toujours aucune trace des patates grillées...",
          DialogueId = 12030809,
          GUID = "1E1E2C9A",
          NextDialogue = 12030810,
          Scripts = "SEQ{\nPARA{\nPlayAnimation{ActorId{211001},AnimationId{\"Sigh_Start\"}},\nPlayFacial{ActorId{211001},FacialId{\"Syouganai01\"}}\n},\nPlayAnimation{_delay{3},ActorId{211001},AnimationId{\"Sigh_End\"}},\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2C9A"
        },
        [12030810] = {
          ContentFR = "Peut-être que ce jeu est vraiment trop difficile pour moi...",
          DialogueId = 12030810,
          GUID = "1E1E2CC4",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2CC4"
        },
        [12030811] = {
          ContentFR = "Elle baisse les yeux sur son livre de contes, posé contre elle.",
          DialogueId = 12030811,
          GUID = "1E1E2CEE",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E2CEE"
        },
        [12030901] = {
          Camera = "-69.249512,169.701172,119.054199,0.000114,2.200639,-59.584778,35.000011,113.605156,false,DoNotOverride,6.0",
          ContentFR = "Mais dans les histoires... les héros n’abandonnent jamais. Peu importe les obstacles, avec leurs amis, ils trouvent toujours la force d’aller plus loin !",
          DialogueId = 12030901,
          GUID = "1E1E3BB2",
          NextDialogue = 12030902,
          Scripts = "PARA{\nPlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}},\nPlayFacial{ActorId{211001},FacialId{\"Think01\"}}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E3BB2"
        },
        [12030902] = {
          Camera = "21.739258,184.106445,139.543457,0.000111,-7.199613,-110.180969,35.000011,113.605156,false,DoNotOverride,6.0",
          ContentFR = "Mais oui ! Des amis... Je peux demander de l’aide à mes amis magiques !\nLe Grand Magicien a le meilleur flair du monde entier... Lui, il saura retrouver ces patates grillées !",
          DialogueId = 12030902,
          GUID = "1E1E3BDC",
          NextDialogue = 12030903,
          Scripts = "SEQ{\nPARA{\nPlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_End\"}},\nPlayFacial{ActorId{211001},FacialId{\"Shock01\"}}\n},\nPARA{\nPlayFacial{_delay{5},ActorId{211001},FacialId{\"Happy01\"}}\n}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E3BDC"
        },
