          Scripts = "SEQ{\nTurnTo{_delay{0},TurnToDescription{\"211003:n(211001)\"}},\nMoveTo{ActorId{211003},TargetPoint{\"feinafx12_moveto01\"},MoveSpeed{120},Visibility{\"Show\"}},\nLookAt{_delay{1},LookAtDescription{\"211003:n(211001)\"}},\nPARA{\nPlayFacial{_delay{1},ActorId{211003},FacialId{\"Smile01\"}},\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"Confident_Start\"}},\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Explain02_End\"}}\n}\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7DFA"
        },
        [12031306] = {
          Camera = "-192.03418,66.044922,95.960938,0.000107,3.599728,-25.255419,35.000015,231.188461,false,DoNotOverride,4.5",
          ContentFR = "Oui ! Je suis en plein voyage d’aventure !",
          DialogueId = 12031306,
          GUID = "1E1E7E24",
          NextDialogue = 12031307,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{211001},AnimationId{\"Explain02_Start\"}},\nPlayFacial{_delay{1},ActorId{211003},FacialId{\"Smile01\"}}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7E24"
        },
        [12031307] = {
          Camera = "-192.03418,66.044922,95.960938,0.000107,3.599728,-25.255419,35.000015,231.188461,false,DoNotOverride,4.5",
          ContentFR = "Ce matin radieux, le petit rossignol parvint jusqu’au fameux Royaume des Ordures ! Il frappa de son bec pointu contre les grandes portes : toc toc... « Y a-t-il quelqu’un ? »",
          DialogueId = 12031307,
          FinalCamera = "-108.570312,19.859375,113.807129,0.000116,-1.200071,-32.455395,35.000015,231.188461,false,DoNotOverride,4.5",
          GUID = "1E1E7E4E",
          NextDialogue = 12031308,
          Scripts = "PARA{\nCameraMoveTo{_delay{10.01},TargetPosition{\"-268.510742,359.411621,112.427979,0.000042,2.200202,-57.851643,35.000008,431.40448,false,DoNotOverride,2.8\"},duration{0}},\nPlayFacial{_delay{3},ActorId{211003},FacialId{\"Satisfy01\"}},\nPlayAnimation{_delay{1},ActorId{211001},AnimationId{\"Feina_Story_CuteHairAction_Loop\"}},\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"Confident_End\"}},\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7E4E"
        },
        [12031308] = {
          Camera = "53.371582,-201.73291,119.283203,0.000088,-2.599857,109.347733,35.000011,198.553635,false,DoNotOverride,4.5",
          ContentFR = "« Oh ! Mais c’est le petit rossignol ! Bienvenue, bienvenue ! » Et les portes du Royaume des Ordures s’ouvrirent en grand devant elle !",
          DialogueId = 12031308,
          GUID = "1E1E7E78",
          NextDialogue = 12031309,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"Explain01_Start\"}},\nPlayAnimation{_delay{3},ActorId{211003},AnimationId{\"Explain01_End\"}}\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7E78"
        },
        [12031309] = {
          Camera = "-122.83252,43.303711,127.951172,0.000087,-7.399813,-27.451759,35.000011,198.553635,false,DoNotOverride,4.5",
          ContentFR = "Et c’est la Princesse aux Doigts d’Or qui accueillit le petit rossignol ! Une princesse capable de transformer les déchets les plus banals en trésors inestimables...",
          DialogueId = 12031309,
          FinalCamera = "-208.64209,87.388184,140.554932,0.000097,-7.999845,-27.251091,35.000011,307.262146,false,DoNotOverride,4.5",
          GUID = "1E1E7EA2",
          NextDialogue = 12031310,
          Scripts = "PARA{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}},\nPlayFacial{_delay{3},ActorId{211003},FacialId{\"Smile01\"}},\nPlayFacial{_delay{6},ActorId{211003},FacialId{\"Shock01\"}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7EA2"
        },
        [12031310] = {
          Camera = "14.431152,-138.814453,120.02417,0.000095,-3.39987,115.548187,35.000011,307.262146,false,DoNotOverride,4.5",
          ContentFR = "Euh ! Petite Fina, pardon mais... tu peux pas me donner un autre rôle ? "Princesse", c’est un peu gênant...",
          DialogueId = 12031310,
          GUID = "1E1E7ECC",
          NextDialogue = 12031311,
          Scripts = "PARA{\nPlayAnimation{_delay{3},ActorId{211003},AnimationId{\"ScratchHead_Start\"}},\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Ahaha02\"}},\nPlayAnimation{_delay{1},ActorId{211001},AnimationId{\"Feina_Story_CuteHairAction_End\"}},\nPlayFacial{_delay{5},ActorId{211003},FacialId{\"Sad02\"}},\nPlayAnimation{_delay{6},ActorId{211003},AnimationId{\"ScratchHead_End\"}},\nPlayAnimation{_delay{7},ActorId{211003},AnimationId{\"DisagreeHead\"}}\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7ECC"
        },
        [12031311] = {
          Camera = "-149.603516,63.429688,133.592773,0.000105,-7.599821,-31.252092,35.000011,307.262146,false,DoNotOverride,4.5",
          ContentFR = "Ah ? Alors, quel titre voudrais-tu, Mademoiselle Margie ?",
          DialogueId = 12031311,
          GUID = "1E1E7EF6",
          NextDialogue = 12031312,
          Scripts = "PARA{\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"Shock01\"}},\nPlayFacial{_delay{3},ActorId{211001},FacialId{\"Smile01\"}},\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Smile01\"}}}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7EF6"
        },
        [12031312] = {
          Camera = "5.123535,-124.944336,98.38916,0.000106,5.400091,110.747116,35.000011,307.262146,false,DoNotOverride,4.5",
          ContentFR = "Appelle-moi... la « Détective Taciturne » !",
          DialogueId = 12031312,
          GUID = "1E1E7F20",
          NextDialogue = 12031313,
          Scripts = "PARA{\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Confident02\"}},\nPlayAnimation{_delay{0},ActorId{211003},AnimationId{\"ConfidentLR_Start\"}},\nPlayAnimation{_delay{1},ActorId{211001},AnimationId{\"Explain02_End\"}},\nPlayFacial{_delay{3},ActorId{211003},FacialId{\"Happy02\"}},\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F20"
        },
        [12031313] = {
          Camera = "-128.556641,-42.028809,97.801025,0.000109,4.600009,-10.652984,35.000015,307.262146,false,DoNotOverride,4.5",
          ContentFR = "D’accord ! Et donc, le petit rossignol rencontra la brillante Détective Taciturne : « Bonjour, Détective ! Fina voudrait être ton amie. On peut jouer ensemble ? »",
          DialogueId = 12031313,
          GUID = "1E1E7F4A",
          NextDialogue = 12031314,
          Scripts = "PARA{\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"Happy01\"}},\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"ConfidentR_End\"}},\nSEQ{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"AgreeHead\"}},\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}}\n}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F4A"
        },
        [12031314] = {
          Camera = "11.094727,-128.317383,143.341797,0.000121,-10.000031,112.346825,35.000011,293.683075,false,DoNotOverride,4.5",
          ContentFR = "« Bien sûr ! » répondit la détective, tapotant la casserole sur sa tête. « À partir d’aujourd’hui, tu seras... mon Petit Assistant ! »",
          DialogueId = 12031314,
          GUID = "1E1E7F74",
          NextDialogue = 12031315,
          Scripts = "PARA{\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Happy02\"}},\nSEQ{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"AgreeHead\"}},\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"SpecialHoldHelmet_Start\"}},\nPlayAnimation{_delay{3},ActorId{211003},AnimationId{\"SpecialHoldHelmet_End\"}},\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Confident02\"}}\n}\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F74"
        },
        [12031315] = {
          Camera = "-38.45166,0.020508,114.371826,0.000105,-0.600066,-45.252876,35.000011,120.0,false,DoNotOverride,4.5",
          ContentFR = "« Petit Assistant »... ? C’est mon nouveau rôle ?",
          DialogueId = 12031315,
          GUID = "1E1E7F9E",
          NextDialogue = 12031316,
          Scripts = "PARA{\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"Shock01\"}},\nPlayFacial{_delay{3},ActorId{211001},FacialId{\"Happy02\"}}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F9E"
        },
        [12031316] = {
          Camera = "33.406738,-173.764648,123.195068,0.000108,-4.399994,102.947136,35.000011,120.0,false,DoNotOverride,4.5",
          ContentFR = "Exactement ! Tous les grands détectives ont un super assistant à leurs côtés.",
          DialogueId = 12031316,
          GUID = "1E1E7FC8",
          NextDialogue = 12031317,
          Scripts = "PARA{\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"ConfidentLR_Start\"}},\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Feina_Story_Wish_End\"}},\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"Smile02\"}},\nPlayFacial{_delay{3},ActorId{211001},FacialId{\"Smile01\"}}\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7FC8"
        },
        [12031317] = {
          Camera = "-124.683594,50.607422,131.177734,0.000107,-7.000397,-33.257271,35.000015,231.188461,false,DoNotOverride,4.5",
          ContentFR = "Alors... qu’est-ce que doit faire un Petit Assistant ?",
          DialogueId = 12031317,
          GUID = "1E1E7FF2",
          NextDialogue = 12031318,
          Scripts = "PARA{\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"Happy01\"}},\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"Agree\"}},\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"Smile01\"}}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7FF2"
        },
        [12031318] = {
          Camera = "13.251953,-312.11084,97.703125,0.000099,0.99994,93.545998,35.000011,231.188461,false,DoNotOverride,4.5",
          ContentFR = "Pour tout te dire, je mène une enquête énorme ! Une bande de sales kidnappeurs d’enfants a refait surface... Ils préparent un mauvais coup à Givrelac, mais personne ne s’en est aperçu.",
          DialogueId = 12031318,
          FinalCamera = "6.855957,-246.094727,98.700195,0.0001,1.599931,96.14592,35.000011,231.188461,false,DoNotOverride,4.5",
          GUID = "1E1E801C",
          NextDialogue = 12031319,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"ConfidentLRToExplainL_Start\"}},\nPlayAnimation{_delay{3},ActorId{211003},AnimationId{\"ConfidentLRToExplainL_End\"}},\nPlayAnimation{_delay{2},ActorId{211003},AnimationId{\"ConfidentLR_End\"}}\n},\nPlayFacial{_delay{4},ActorId{211003},FacialId{\"Confident01\"}}\n}",
          SpeakNpcId = 211003,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E801C"
        },
        [12031319] = {
          Camera = "7.620117,-146.29248,102.274414,0.000101,2.99988,109.746193,35.000011,231.188461,false,DoNotOverride,4.5",
          ContentFR = "Regarde : dans la grosse poubelle n° 3, j’ai trouvé cette preuve ! Cette marque est exactement la même que celle du crime d’il y a un an !",
          DialogueId = 12031319,
          GUID = "1E1E8046",
          NextDialogue = 12031320,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{_delay{0},ActorId{211003},AnimationId{\"Give\"}},\nPlayAnimation{_delay{3},ActorId{211003},AnimationId{\"Talk02_Start\"}},\nPlayAnimation{_delay{6},ActorId{211003},AnimationId{\"Talk02_End\"}},\n},\nPlayFacial{_delay{3},ActorId{211003},FacialId{\"Think01\"}}\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8046"
        },
        [12031320] = {
          ContentFR = "Mais le Bureau de la Sécurité a dit que ça ne comptait pas comme preuve... Alors moi, la Détective Taciturne, j’ai décidé de les retrouver, de briser leur complot et de protéger tous les enfants de Givrelac !",
          DialogueId = 12031320,
          GUID = "1E1E8070",
          NextDialogue = 12031321,
          Scripts = "SEQ{\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Unhappy02\"}},\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"DisagreeHead\"}},\nPlayAnimation{_delay{1},ActorId{211003},AnimationId{\"Angry02_Start\"}},\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Confident02\"}},\nPlayAnimation{_delay{5},ActorId{211003},AnimationId{\"Angry02_End\"}},\nPlayAnimation{_delay{0},ActorId{211003},AnimationId{\"Confident_Start\"}}\n}",
          SpeakNpcId = 211003,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8070"
        },
        [12031321] = {
          Camera = "0.609863,-390.711426,114.49585,0.000112,-0.000246,91.142174,35.000015,440.047546,false,DoNotOverride,4.5",
          ContentFR = "Petit Assistant, on va travailler ensemble ! J’ai déjà fouillé les poubelles n° 1 à 5. Maintenant je file à la n° 6... ce qui veut dire que la n° 7, c’est ta mission !",
          DialogueId = 12031321,
          FinalCamera = "-2.351074,-242.245605,114.412109,0.000112,-0.200261,91.142151,35.000015,440.047546,false,DoNotOverride,4.5",
          GUID = "1E1E809A",
          NextDialogue = 12031322,
          Scripts = "PARA{\nPlayFacial{_delay{0},ActorId{211003},FacialId{\"Smile02\"}},\nLookAt{_delay{5},LookAtDescription{\"211003:p(feinafx12_lookat01)\"}},\nPlayFacial{_delay{5},ActorId{211003},FacialId{\"Smile01\"}},\nLookAt{_delay{6},LookAtDescription{\"211001:p(feinafx12_lookat01)\"}}\n}",
          SpeakNpcId = 211003,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E809A"
        },
        [12031322] = {
          Camera = "-166.953125,48.82959,124.791748,0.000113,-4.000059,-23.054798,35.000011,231.188461,false,DoNotOverride,4.5",
          ContentFR = "Entendu, Mademoiselle ! Petit Assistant Fina... accepte la mission !",
          DialogueId = 12031322,
          GUID = "1E1E80C4",
          Scripts = "SEQ{\nPARA{\nLookAt{_delay{0},LookAtDescription{\"211001:n(211003)\"}},\nLookAt{_delay{1},LookAtDescription{\"211003:n(211001)\"}}\n},\nPARA{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"AgreeHead\"}},\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Explain02_Start\"}}\n}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E80C4"
        },
        [12031323] = {
          Content = "调查垃圾桶1（小垃圾桶）\n（这里如果想细节一些的话可以给地图上所有垃圾桶编个号，用于设计与玛尔洁相关的内容。不方便的话确保大小和文案描述一致就行了）",
          DialogueId = 12031323,
          GUID = "1E1E80EE",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E80EE"
        },
        [12031350] = {
          Content = "湛蓝的天空【补充需求】",
          DialogueId = 12031350,
          GUID = "1E1E80EF",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E80EF"
        },
        [12031401] = {
          Camera = "-222.93663,-4.119965,77.036377,0.000147,5.602271,18.947176,35.000008,242.208893,false,DoNotOverride,2.8",
          ContentFR = "Beurk... que des déchets... Mais non, je ne dois pas avoir peur ! Je suis le courageux Petit Assistant de la grande Détective Taciturne. Je dois être forte et accomplir ma mission !",
          DialogueId = 12031401,
          GUID = "1E1E8DBA",
          NextDialogue = 12031402,
          Scripts = "SEQ{\nPARA{\nLookAt{_delay{0},LookAtDescription{\"211001:p(QuestPoint_Feina02fx13)\"}},\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"Shock02\"}}\n},\nPARA{\nCameraMoveTo{_delay{4.01},TargetPosition{\"-128.022781,66.455872,85.407471,0.000122,13.602055,-6.65639,35.000008,184.110672,false,DoNotOverride,2.8\"},duration{0}},\nPlayFacial{_delay{4},ActorId{211001},FacialId{\"Confident01\"}},\nPlayAnimation{_delay{4},ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}}\n}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8DBA"
        },
        [12031402] = {
          ContentFR = "Voyons voir... tiens, un bout de papier. Peut-être un indice ?",
          DialogueId = 12031402,
          GUID = "1E1E8DE4",
          NextDialogue = 12031403,
          Scripts = "SEQ{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Give\"}},\nPlayAnimation{_delay{2},ActorId{211001},AnimationId{\"Think_Start\"}}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8DE4"
        },
        [12031403] = {
          ContentFR = "« Il suffit de saisir l’air du temps, et chacun peut devenir le prochain grand patron... » Hein ? C’est quoi, un « air du temps » ? ... Enfin, un grand patron ne se rabaisserait pas à kidnapper des enfants.",
          DialogueId = 12031403,
          GUID = "1E1E8E0E",
          NextDialogue = 12031404,
          Scripts = "PARA{\nSEQ{\nPlayFacial{_delay{2},ActorId{211001},FacialId{\"Shock01\"}},\nPlayFacial{_delay{2},ActorId{211001},FacialId{\"Disappoint01\"}},\nPlayFacial{_delay{2},ActorId{211001},FacialId{\"Happy01\"}},\nPlayFacial{_delay{3},ActorId{211001},FacialId{\"Shock01\"}},\n},\nPlayAnimation{_delay{5},ActorId{211001},AnimationId{\"Think_End\"}}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E0E"
        },
        [12031404] = {
          ContentFR = "Et celui-là dit...",
          DialogueId = 12031404,
          GUID = "1E1E8E38",
          NextDialogue = 12031405,
          Scripts = "PARA{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Give\"}},\nPlayFacial{_delay{0},ActorId{211001},FacialId{\"None\"}}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E38"
        },
        [12031405] = {
          Camera = "-156.79039,1.709183,91.499512,0.000147,7.401883,17.145016,35.000011,278.655243,false,DoNotOverride,2.8",
          ContentFR = "« Tous les citoyens de Givrelac se souviennent de l’ascension fulgurante — et de la chute soudaine — de la famille Glenville... » Hein !?",
          DialogueId = 12031405,
          FinalCamera = "-108.686592,16.733475,98.225098,0.000142,7.601891,17.344889,35.000011,130.0,false,DoNotOverride,2.8",
          GUID = "1E1E8E62",
          NextDialogue = 12031406,
          Scripts = "PARA{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Think_Start\"}},\nPlayFacial{_delay{5.01},ActorId{211001},FacialId{\"Shock02\"}},\nCameraMoveTo{_delay{5.01},TargetPosition{\"-96.672791,18.322319,115.384521,0.000154,1.601871,16.545654,35.000011,109.004112,false,DoNotOverride,2.8\"},duration{0}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E62"
        },
        [12031406] = {
          ContentFR = "... Ouf, rien sur maman ou moi. « Secrets du passé »... qu’est-ce que ça veut dire ? Bon... ça n’a sûrement rien à voir avec l’affaire de la Détective Taciturne. Mieux vaut faire comme si je n’avais rien vu.",
          DialogueId = 12031406,
          GUID = "1E1E8E8C",
          Scripts = "SEQ{\nPARA{\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"DisagreeHead\"}},\nPlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Syouganai01\"}}\n},\nPARA{\nPlayAnimation{_delay{3},ActorId{211001},AnimationId{\"Explain02_Start\"}},\nPlayFacial{_delay{3},ActorId{211001},FacialId{\"Disappoint01\"}},\nPlayAnimation{_delay{6},ActorId{211001},AnimationId{\"Explain02_End\"}},\nPlayFacial{_delay{5},ActorId{211001},FacialId{\"Smile01\"}}\n}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E8C"
        },
        [12031407] = {
          ContentFR = "Fina continue de fouiller les papiers, mais ne trouve rien d’utile.",
          DialogueId = 12031407,
          GUID = "1E1E8EB6",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8EB6"
        },
        [12031408] = {
          ContentFR = "Retour vers Margie",
          DialogueId = 12031408,
          GUID = "1E1E8EE0",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8EE0"
        },
        [12031501] = {
