        [12032202] = {
          Camera = "-297.106384,-36.227322,125.762207,0.000083,2.59916,-5.271038,35.0,296.228882,false,Manual,1.4",
          ContentFR = "Oui, merci de t’inquiéter ! Mais cette fille...",
