          ContentFR = "Mais... quand j’ai dit que je savais faire un peu de magie, elle a souri. Et je l’ai bien vu, c’était un vrai sourire. Un sourire sincère. Les mauvais sorciers, eux, ne sourient jamais comme ça.",
          DialogueId = 12032205,
          FinalCamera = "-82.042175,-125.063324,139.085938,0.000125,-4.602113,49.317894,35.000008,159.098129,false,Manual,2.8",
          GUID = "1E1F11A2",
          NextDialogue = 12032206,
          Scripts = "PARA{\nLookAt{LookAtDescription{\"211001:n(211001)\"}},\nPlayAnimation{ActorId{211001},AnimationId{\"Think_Start\"},Duration{1}},\nPlayFacial{ActorId{211001},FacialId{\"Think01\"}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11A2"
        },
        [12032206] = {
