          ContentFR = "À ce moment-là, je m’étais promis qu’une fois grande, si je rencontrais un enfant dans le besoin, je ferais la même chose que lui.",
          DialogueId = 12032207,
          GUID = "1E1F11F6",
          NextDialogue = 12032208,
          Scripts = "PARA{\nPlayAnimation{ActorId{211001},AnimationId{\"Talk03_Start\"},Duration{1}},\nPlayFacial{ActorId{211001},FacialId{\"Sad01\"}}\n}",
          SpeakNpcId = 211001,
