          GUID = "1E1F7394",
          NextDialogue = 12032803,
          Scripts = "SEQ{\nPlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Confident_Start\"}},\nPlayAnimation{_delay{2},ActorId{211012},AnimationId{\"Confident_End\"}}\n}",
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F7394"
        },
        [12032803] = {
