          ContentFR = "... Très bien. Alors cherchons ensemble. Mais promets-moi de ne pas t’éloigner de moi.",
          DialogueId = 12033304,
          GUID = "1E1FC5F0",
          NextDialogue = 12033305,
          Scripts = "PARA{\nPlayAnimation{_delay{0},ActorId{100001},AnimationId{\"AgreeHead\"}},\nPlayFacial{ActorId{100001},FacialId{\"Happy01\"}}\n}",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC5F0"
        },
        [12033305] = {
          Camera = "-96.779709,-151.616333,144.003418,0.000136,-5.001925,104.710579,50.0,242.830399,false,Manual,1.0",
          ContentFR = "Hein ? Vous cherchez quelqu’un ? Je viens aussi !",
          DialogueId = 12033305,
          FinalCamera = "-96.779709,-151.616333,144.003418,0.000136,-5.001925,104.710579,50.0,560.6521,false,Manual,4.0",
          GUID = "1E1FC61A",
          NextDialogue = 12033306,
          Scripts = "PARA{\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(211011)\"}},\nLookAt{_delay{1},LookAtDescription{\"211001:n(211011)\"}},\nLookAt{_delay{0},LookAtDescription{\"211010:n(211011)\"}},\nLookAt{_delay{0.2},LookAtDescription{\"211012:n(100001)\"}},\nLookAt{_delay{0.7},LookAtDescription{\"211011:n(100001)\"}},\nLookAt{_delay{0.6},LookAtDescription{\"211013:n(211011)\"}},\n}",
          SpeakNpcId = 211011,
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC61A"
        },
        [12033306] = {
          ContentFR = "Moi aussi !",
          DialogueId = 12033306,
          GUID = "1E1FC644",
          NextDialogue = 12033307,
          Scripts = "LookAt{_delay{0.6},LookAtDescription{"211013:n(100001)"}}",
          SpeakNpcId = 211013,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC644"
        },
        [12033307] = {
          Camera = "-214.859619,538.500977,141.89502,0.000199,-5.601991,-88.089539,35.0,560.6521,false,Manual,4.0",
          ContentFR = "Non, vous deux, vous restez ici.",
          DialogueId = 12033307,
          GUID = "1E1FC66E",
          NextDialogue = 12033308,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{"Confident_Start"}}",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC66E"
        },
        [12033308] = {
          Camera = "-151.192551,-29.119432,139.736328,0.000225,-6.202235,101.306007,35.000008,560.6521,false,Manual,22.0",
          ContentFR = "Quoi ?! Tu nous prends pour des bébés ? On joue au Glouton dans Givrelac depuis dix ans — on a jamais perdu ! Si quelqu’un peut retrouver ce garçon, c’est bien nous ! Allez, décrivez-le-moi !",
          DialogueId = 12033308,
          GUID = "1E1FC698",
          NextDialogue = 12033309,
          Scripts = "PARA{\nPlayAnimation{_delay{0},ActorId{211011},AnimationId{\"Talk03_Start\"}},\nPlayFacial{ActorId{211011},FacialId{\"CM_Angry01\"}}\n}",
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC698"
        },
        [12033309] = {
          Camera = "-283.217163,387.314117,81.605469,0.000261,5.997555,-75.884804,35.000015,341.991852,false,Manual,4.0",
          ContentFR = "C’est un garçon, à peu près de cette taille. Cheveux blancs courts, yeux verts, et il porte le même uniforme scolaire que moi.",
          DialogueId = 12033309,
          GUID = "1E1FC6C2",
          NextDialogue = 12033310,
          Scripts = "PARA{\nPlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Explain02_Start\"}},\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(211012)\"}},\nLookAt{_delay{1},LookAtDescription{\"211001:n(211012)\"}},\nPlayAnimation{_delay{0},ActorId{211011},AnimationId{\"Talk03_End\"}}\n}",
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC6C2"
        },
        [12033310] = {
          Camera = "-259.942474,67.673576,90.111328,0.000218,6.797206,91.514595,35.000008,341.991852,false,Manual,4.0",
          ContentFR = "D’accord... Et vous vous êtes séparés où exactement ?",
          DialogueId = 12033310,
          GUID = "1E1FC6EC",
          NextDialogue = 12033311,
          Scripts = "PlayFacial{_delay{2},ActorId{211011},FacialId{"CM_Idle"}}",
          SpeakNpcId = 211011,
          TurnTo = {
            [1] = "211011:n(211012)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC6EC"
        },
        [12033311] = {
          ContentFR = "Dans la ruelle, près de la taverne.",
          DialogueId = 12033311,
          GUID = "1E1FC716",
          NextDialogue = 12033312,
          Scripts = "SEQ{\nPlayAnimation{_delay{0},ActorId{211012},AnimationId{\"Explain02_End\"}},\nTurnTo{_delay{1},TurnToDescription{\"211012:n(211011)\"}}\n}",
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC716"
        },
        [12033312] = {
          Camera = "-438.694794,219.296844,103.061523,0.000218,1.397532,20.50848,25.0,560.6521,false,Manual,4.0",
          ContentFR = "Davy et moi, on empilait des cailloux juste à l’entrée de cette ruelle. On n’a vu aucun garçon comme ça.",
          DialogueId = 12033312,
          GUID = "1E1FC740",
          NextDialogue = 12033313,
          Scripts = "PARA{\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(211011)\"}},\nLookAt{_delay{1},LookAtDescription{\"211001:n(211011)\"}},\nLookAt{_delay{0},LookAtDescription{\"211010:n(211011)\"}},\nLookAt{_delay{0.2},LookAtDescription{\"211012:n(211010)\"}},\nLookAt{_delay{0.7},LookAtDescription{\"211011:n(211010)\"}},\nLookAt{_delay{0.6},LookAtDescription{\"211013:n(211010)\"}},\n}",
          SpeakNpcId = 211010,
          TurnTo = {
            [1] = "211010:n(211012)",
            [2] = "211013:n(211010)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC740"
        },
        [12033313] = {
          ContentFR = "Moi non plus...",
          DialogueId = 12033313,
          GUID = "1E1FC76A",
          NextDialogue = 12033314,
          Scripts = "PlayAnimation{_delay{0},ActorId{211013},AnimationId{"Talk01_Start"}},",
          SpeakNpcId = 211013,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC76A"
        },
        [12033314] = {
          Camera = "-115.656433,-8.532393,142.876465,0.000173,-11.202848,117.306786,18.0,433.05719,false,Manual,4.0",
          ContentFR = "Alors il a dû filer de l’autre côté.",
          DialogueId = 12033314,
          GUID = "1E1FC794",
          NextDialogue = 12033315,
          Scripts = "PARA{\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(211011)\"}},\nLookAt{_delay{1},LookAtDescription{\"211001:n(211011)\"}},\nLookAt{_delay{0},LookAtDescription{\"211010:n(211011)\"}},\nLookAt{_delay{0.2},LookAtDescription{\"211012:n(211011)\"}},\nLookAt{_delay{0.7},LookAtDescription{\"211011:n(211011)\"}},\nLookAt{_delay{0.6},LookAtDescription{\"211013:n(211011)\"}},\n}",
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC794"
        },
        [12033315] = {
          ContentFR = "Ah, attends ! Je me souviens ! Près du carrefour, à côté de la taverne, il y avait une voiture arrêtée. Mark adore s’y faufiler pour klaxonner en douce. S’il y était aujourd’hui, il a peut-être vu quelque chose !",
          DialogueId = 12033315,
          GUID = "1E1FC7BE",
          NextDialogue = 12033316,
          Scripts = "PlayAnimation{_delay{0},ActorId{211013},AnimationId{"Talk01_End"}}",
          SpeakNpcId = 211013,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC7BE"
        },
        [12033316] = {
          ContentFR = "Bonne idée ! Allons lui demander !",
          DialogueId = 12033316,
          GUID = "1E1FC7E8",
          Scripts = "PlayOrStopBGM{PlayType{"Stop"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0051_story_danger"}}",
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC7E8"
        },
        [12033317] = {
          ContentFR = "(Les enfants détalent.)\nPrès de la ruelle des Asphodèles, près d’une vieille voiture. Cassandra, Freda, Kori, Davy et un nouveau garçon, Mark, se regroupent.",
          DialogueId = 12033317,
          GUID = "1E1FC812",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC812"
        },
        [12033401] = {
          Camera = "-105.724152,605.271057,208.438477,0.00007,-13.321648,-104.470268,35.000011,453.640076,false,DoNotOverride,12.0",
          ContentFR = "Hein ? Mais qu’est-ce que vous faites tous dehors ? J’allais justement venir vous chercher pour jouer !",
          DialogueId = 12033401,
          FinalCamera = "-89.904701,598.424988,208.438477,0.000069,-13.321682,-107.869789,35.000011,453.640076,false,DoNotOverride,12.0",
          GUID = "1E1FD5DA",
          NextDialogue = 12033402,
          Scripts = "PARA{\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(211014)\"}},\nLookAt{_delay{1},LookAtDescription{\"211001:n(211014)\"}},\nLookAt{_delay{0},LookAtDescription{\"211010:n(211014)\"}},\nLookAt{_delay{0.2},LookAtDescription{\"211012:n(211014)\"}},\nLookAt{_delay{0.7},LookAtDescription{\"211011:n(211014)\"}},\nLookAt{_delay{0.6},LookAtDescription{\"211013:n(211014)\"}},\nPlayAnimation{_delay{0.5},ActorId{211014},AnimationId{\"Talk03_Start\"}}\n}",
          SpeakNpcId = 211014,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD5DA"
        },
        [12033402] = {
          Camera = "-450.762573,18.759333,154.709473,0.000131,-11.121706,41.12257,35.000011,316.938934,false,DoNotOverride,3.5",
          ContentFR = "On cherche quelqu’un.",
          DialogueId = 12033402,
          GUID = "1E1FD604",
          NextDialogue = 12033403,
          Scripts = "PARA{\nLookAt{_delay{0.6},LookAtDescription{\"211014:n(211010)\"}},\nPlayAnimation{_delay{0.5},ActorId{211010},AnimationId{\"Explain01_Start\"}},\nPlayAnimation{_delay{1},ActorId{211014},AnimationId{\"Talk03_End\"}}\n}",
          SpeakNpcId = 211010,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD604"
        },
        [12033403] = {
          Camera = "-76.398384,420.032104,170.840576,0.000102,-13.921988,-126.06813,35.000015,689.353516,false,DoNotOverride,12.0",
          ContentFR = "Quoi ?! Vous jouez au Glouton sans moi ?!",
          DialogueId = 12033403,
          GUID = "1E1FD62E",
          NextDialogue = 12033404,
          Scripts = "SEQ{\nPlayAnimation{_delay{0.2},ActorId{211014},AnimationId{\"Shock_Start\"}},\nPlayAnimation{_delay{4},ActorId{211014},AnimationId{\"Shock_End\"}}\n}",
          SpeakNpcId = 211014,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD62E"
        },
        [12033404] = {
          Camera = "-190.92775,502.22348,189.769531,0.000107,-13.321833,-95.471069,35.000011,689.353516,false,DoNotOverride,12.0",
          ContentFR = "Mais non ! On aide cette jolie demoiselle à retrouver quelqu’un. Un garçon en uniforme, comme elle.",
          DialogueId = 12033404,
          GUID = "1E1FD658",
          NextDialogue = 12033405,
          Scripts = "SEQ{\nPARA{\nPlayAnimation{_delay{0.5},ActorId{211011},AnimationId{\"Disagree\"}},\nPlayAnimation{_delay{0.5},ActorId{211010},AnimationId{\"Explain01_End\"}}\n},\nLookAt{_delay{0.2},LookAtDescription{\"211011:n(211014)\"}}\n}",
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD658"
        },
        [12033405] = {
          ContentFR = "Il s’est sûrement perdu par ici. Tu n’as rien remarqué ?",
          DialogueId = 12033405,
          GUID = "1E1FD682",
          NextDialogue = 12033406,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{211011},AnimationId{"Talk02_Start"}}",
          SpeakNpcId = 211011,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD682"
        },
        [12033406] = {
          Camera = "-184.196564,208.952484,88.146484,0.000141,7.678321,-144.26712,35.000011,198.340698,false,DoNotOverride,12.0",
          ContentFR = "Oh ! Tu parles d’un petit aux cheveux blancs, non ? Oui, je l’ai vu !",
          DialogueId = 12033406,
          GUID = "1E1FD6AC",
          NextDialogue = 12033407,
          Scripts = "PARA{\nSEQ{\nPlayAnimation{_delay{0.5},ActorId{211014},AnimationId{\"Think_Start\"}},\nPlayAnimation{_delay{2.5},ActorId{211014},AnimationId{\"Think_End\"}},\nPlayAnimation{_delay{1},ActorId{211014},AnimationId{\"Agree\"}}\n},\nPlayAnimation{_delay{0.5},ActorId{211011},AnimationId{\"Talk02_End\"}}\n}",
          SpeakNpcId = 211014,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD6AC"
        },
        [12033407] = {
          ContentFR = "J’étais dans la voiture, à klaxonner pour rigoler... Il passait par là, et ça l’a fait sursauter d’un bond ! Je voulais m’excuser, mais quand je suis descendu, il avait déjà filé...",
          DialogueId = 12033407,
          GUID = "1E1FD6D6",
          NextDialogue = 12033408,
          Scripts = "SEQ{\nPlayAnimation{_delay{0.5},ActorId{211014},AnimationId{\"Talk03_Start\"}},\nPlayAnimation{_delay{3},ActorId{211014},AnimationId{\"Talk03_End\"}},\nPlayAnimation{_delay{3.5},ActorId{211014},AnimationId{\"Sigh_Start\"}},\nPlayAnimation{_delay{3},ActorId{211014},AnimationId{\"Sigh_End\"}},\n}",
          SpeakNpcId = 211014,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD6D6"
        },
        [12033408] = {
          Camera = "-145.854355,386.006195,242.959961,0.000151,-26.721802,-114.066803,35.000011,198.340698,false,DoNotOverride,12.0",
          ContentFR = "Quoi ?! Dans quelle direction il est parti ?",
          DialogueId = 12033408,
          GUID = "1E1FD700",
          NextDialogue = 12033409,
          Scripts = "PARA{\nLookAt{_delay{0.5},LookAtDescription{\"211014:n(211012)\"}},\nSEQ{\nMoveTo{ActorId{211012},TargetPoint{\"Feinafx33moveto01\"},MoveSpeed{100},Visibility{\"Show\"}},\nPlayAnimation{_delay{0.5},ActorId{211012},AnimationId{\"Confident_Start\"}}\n}\n}",
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD700"
        },
        [12033409] = {
          ContentFR = "Je l’ai vu courir vers la grande porte. Franchement, il est gonflé pour un gamin de la cité intérieure, d’y aller tout seul...",
          DialogueId = 12033409,
          GUID = "1E1FD72A",
          NextDialogue = 12033410,
          Scripts = "SEQ{\nPlayAnimation{_delay{0.5},ActorId{211014},AnimationId{\"Talk02_Start\"}},\nPlayAnimation{_delay{5},ActorId{211014},AnimationId{\"Talk02_End\"}}\n}",
          SpeakNpcId = 211014,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD72A"
        },
        [12033410] = {
          Camera = "-429.89566,116.990479,117.795654,0.000124,-1.722382,0.522152,35.000011,202.363037,false,DoNotOverride,2.8",
          ContentFR = "La porte... tu veux dire la porte de la cité intérieure ou bien—",
          DialogueId = 12033410,
          GUID = "1E1FD754",
          NextDialogue = 12033411,
          Scripts = "SEQ{\nPlayAnimation{_delay{2},ActorId{211012},AnimationId{\"Confident_End\"}},\nLookAt{_delay{0.5},LookAtDescription{\"211012:n(211011)\"}}\n}",
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD754"
        },
        [12033411] = {
          Camera = "-138.852493,413.402557,174.547852,0.000144,-10.322205,-112.074112,35.000011,360.37265,false,DoNotOverride,2.8",
          ContentFR = "Mais non, la grande porte de la cité ! Moi, j’oserais jamais regarder trop longtemps celle de la cité intérieure...",
          DialogueId = 12033411,
          FinalCamera = "-138.852493,413.402557,174.547852,0.000148,-12.722095,-116.674217,35.000011,360.37265,false,DoNotOverride,2.8",
          GUID = "1E1FD77E",
          NextDialogue = 12033412,
          Scripts = "SEQ{\nPlayAnimation{_delay{0},ActorId{211014},AnimationId{\"Talk01_Start\"}},\nPlayAnimation{_delay{3},ActorId{211014},AnimationId{\"Talk01_End\"}}\n}",
          SpeakNpcId = 211014,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD77E"
        },
        [12033412] = {
          Camera = "-237.754028,239.283752,119.808838,0.000117,-0.121919,-71.676437,35.000011,86.998222,false,DoNotOverride,2.8",
          ContentFR = "Quoi ?! Mais c’est super dangereux là-bas... Qu’est-ce qu’on fait maintenant... !?",
          DialogueId = 12033412,
          FinalCamera = "-237.754028,239.283752,119.808838,0.000117,-0.121919,-71.676437,35.000011,212.450943,false,DoNotOverride,3.2",
          GUID = "1E1FD7A8",
          NextDialogue = 12033413,
          Scripts = "SEQ{\nPARA{\nLookAt{_delay{0.5},LookAtDescription{\"211001:n(211012)\"}},\nPlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Sad02\"}}\n},\nLookAt{_delay{0.5},LookAtDescription{\"211012:n(211014)\"}}}",
          SpeakNpcId = 211012,
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD7A8"
        },
        [12033413] = {
          ContentFR = "Ah, j’ai trouvé ! On peut engager un Chasseur de Phoxène pour nous escorter hors de la cité ! Paraît qu’avec assez d’argent, ils acceptent n’importe quoi !",
          DialogueId = 12033413,
          GUID = "1E1FD7D2",
          NextDialogue = 12033414,
          Scripts = "SEQ{\nPARA{\nLookAt{_delay{0.5},LookAtDescription{\"211012:n(211001)\"}},\nPlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Shock01\"}},\nPlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Talk03_Start\"}}\n},\nPlayAnimation{_delay{2},ActorId{211012},AnimationId{\"Talk02_Start\"}}\n}",
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD7D2"
        },
        [12033414] = {
          Camera = "-371.668549,102.6278,152.601807,0.000084,-9.521973,1.526568,35.000011,259.37915,false,DoNotOverride,3.5",
          ContentFR = "Mais... {性别:Monsieur|Mademoiselle} Licorne est {性别:un Chasseur de Phoxène ! Et un très fort|une Chasseuse de Phoxène ! Et une très forte}, en plus !",
          DialogueId = 12033414,
          GUID = "1E1FD7FC",
          NextDialogue = 12033415,
          Scripts = "PARA{\nPlayAnimation{_delay{0.5},ActorId{211012},AnimationId{\"Talk02_End\"}},\nPARA{\nPlayFacial{_delay{0.5},ActorId{100001},FacialId{\"Smile01\"}}\n},\nSEQ{\nLookAt{_delay{0.5},LookAtDescription{\"211001:n(211012)\"}},\nPlayAnimation{_delay{0.5},ActorId{211001},AnimationId{\"Explain02_Start\"}}\n},\nSEQ{\nTurnTo{_delay{0},TurnToDescription{\"211011:n(100001)\"}},\nLookAt{_delay{0.5},LookAtDescription{\"211011:n(100001)\"}}\n},\nSEQ{\nTurnTo{_delay{0},TurnToDescription{\"211013:n(100001)\"}},\nLookAt{_delay{0.5},LookAtDescription{\"211013:n(100001)\"}}\n},\nSEQ{\nTurnTo{_delay{0},TurnToDescription{\"211013:n(100001)\"}},\nLookAt{_delay{0.5},LookAtDescription{\"211013:n(100001)\"}}\n}\n}",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD7FC"
        },
        [12033415] = {
          Camera = "-296.6315,90.475662,114.222412,0.000088,5.677895,23.727402,35.000011,177.889099,false,DoNotOverride,3.5",
          ContentFR = "Hein ?! Vraiment ?! Alors tu peux m’aider à chercher, n’est-ce pas ? Je t’en supplie, {性别:Monsieur|Mademoiselle} {nickname} ! Je paierai, promis !",
          DialogueId = 12033415,
          FinalCamera = "-296.6315,90.475662,114.222412,0.000088,5.07789,27.32766,35.000011,177.889099,false,DoNotOverride,3.5",
          GUID = "1E1FD826",
          NextDialogue = 12033416,
          Scripts = "PARA{\nPlayAnimation{_delay{0.5},ActorId{211001},AnimationId{\"Explain02_End\"}},\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(211012)\"}},\nSEQ{\nTurnTo{_delay{0},TurnToDescription{\"211012:n(100001)\"}},\nLookAt{_delay{0.5},LookAtDescription{\"211012:n(100001)\"}}\n}\n}",
          SpeakNpcId = 211012,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD826"
        },
        [12033416] = {
          Camera = "-296.6315,90.475662,114.222412,0.000088,5.07789,27.32766,35.000011,177.889099,false,DoNotOverride,3.5",
          ContentFR = "... D’accord. Puisque Fina tient à aider, j’accepte ta requête.",
          DialogueId = 12033416,
          GUID = "1E1FD850",
          NextDialogue = 12033417,
          Scripts = "SEQ{\nPARA{\nPlayFacial{_delay{0.5},ActorId{100001},FacialId{\"Close\"}},\nPlayAnimation{_delay{0.5},ActorId{100001},AnimationId{\"Talk03_End\"}}\n},\nPARA{\nPlayFacial{_delay{3},ActorId{100001},FacialId{\"Smile01\"}}\n}\n}",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD850"
        },
        [12033417] = {
          Camera = "-151.644821,327.130096,181.968506,0.000056,-15.922331,-98.076088,35.000011,227.608078,false,DoNotOverride,2.8",
          ContentFR = "Alors nous aussi, on va—",
          DialogueId = 12033417,
