          SpeakNpcId = 211037,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2007BA"
        },
        [12033706] = {
          ContentFR = "Regarde, boss ! Deux bestioles bizarres là-bas... C’est pas des Souillés, quand même ?!",
          DialogueId = 12033706,
          GUID = "1E2007E4",
          NextDialogue = 12033707,
          Scripts = "SEQ{\nPlayAnimation{ActorId{211037},AnimationId{\"Think_End\"}},\nPARA{\nTurnTo{_delay{0},TurnToDescription{\"211037:n(211007)\"}},\nTurnTo{_delay{0.5},TurnToDescription{\"211038:n(211007)\"}},\nTurnTo{_delay{3},TurnToDescription{\"211039:n(211007)\"}}\n}\n}",
          SpeakNpcId = 211039,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2007E4"
        },
        [12033707] = {
