          VoiceName = "voice/$Locale$/story/1201/120114/1E20080E"
        },
        [12033708] = {
          Camera = "-2936.262695,253.024292,-96.198242,0.000075,-4.800557,-24.382278,35.000008,267.529114,false,DoNotOverride,2.8",
          ContentFR = "Ah bon ? J’en ai jamais vu avec cette tête-là...",
          DialogueId = 12033708,
          GUID = "1E200838",
          NextDialogue = 12033709,
          Scripts = "PARA{\nPlayAnimation{_delay{2.5},ActorId{211037},AnimationId{\"Angry01_End\"}},\nSEQ{\nPlayAnimation{_delay{0.5},ActorId{211039},AnimationId{\"Talk03_Start\"}},\nPlayAnimation{_delay{2.5},ActorId{211039},AnimationId{\"Talk03_End\"}}\n}\n}",
          SpeakNpcId = 211039,
          VoiceName = "voice/$Locale$/story/1201/120114/1E200838"
        },
        [12033709] = {
          Camera = "-2712.877686,127.540527,-141.259766,0.000156,0.998758,-172.586914,35.000011,544.833557,false,DoNotOverride,12.0",
          ContentFR = "Moi non plus. Ça doit être une espèce rare.",
          DialogueId = 12033709,
          GUID = "1E200862",
          NextDialogue = 12033710,
          SpeakNpcId = 211037,
          VoiceName = "voice/$Locale$/story/1201/120114/1E200862"
        },
        [12033710] = {
          Camera = "-1975.500122,112.498108,-95.56543,0.000173,-4.801363,-175.988037,35.000011,544.833557,false,DoNotOverride,12.0",
          ContentFR = "J’ai entendu dire que les rares, ça se revend très cher ! On devrait pas les capturer ? Ça rapporterait gros !",
          DialogueId = 12033710,
          GUID = "1E20088C",
          NextDialogue = 12033711,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{211039},AnimationId{"Talk02_Start"}}",
          SpeakNpcId = 211039,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20088C"
        },
        [12033711] = {
          ContentFR = "Pas bête, ça... T’as plus de cervelle que j’croyais. Allez les gars ! Armez-vous, on les chope !",
          DialogueId = 12033711,
          GUID = "1E2008B6",
          Scripts = "PlayAnimation{_delay{7.5},ActorId{211037},AnimationId{"Angry01_Start"}}",
          SpeakNpcId = 211037,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2008B6"
        },
        [12033712] = {
          ContentFR = "Une partie de la bande s’éloigne, laissant seulement deux gardes avec Savio.",
          DialogueId = 12033712,
          GUID = "1E2008E0",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2008E0"
        },
        [12033801] = {
          ContentFR = "C’est le moment... !",
          DialogueId = 12033801,
          GUID = "1E20177A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20177A"
        },
        [12033802] = {
          ContentFR = "Le protagoniste fonce, engageant les bandits restants. Fina se précipite vers Savio.",
          DialogueId = 12033802,
          GUID = "1E2017A4",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2017A4"
        },
        [12033803] = {
