          ContentFR = "Savio ! Réveille-toi, ça va ?!",
          DialogueId = 12033803,
          FinalCamera = "31.312517,53.192848,143.547852,-18.000196,15.799729,27.200317,35.000008,112.97599,false,Manual,2.8",
          GUID = "1E2017CE",
          NextDialogue = 12033805,
          Scripts = "PARA{\nPlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Sad01\"}},\nPlayAnimation{_delay{0.5},ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2017CE"
        },
        [12033804] = {
          Camera = "31.312517,53.192848,143.547852,-18.000196,15.799729,27.200317,35.000008,112.97599,false,Manual,2.8",
          ContentFR = "Mais dehors, les autres bandits entendent le vacarme et reviennent en trombe.",
          DialogueId = 12033804,
          FinalCamera = "-462.511353,-198.426529,435.666016,-18.002155,-15.800631,31.003305,35.000008,296.476868,false,Manual,22.0",
          GUID = "1E2017F8",
          ToFinalCameraBlendTime = 2,
          TurnTo = {
            [1] = "211001:p(170)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E2017F8"
        },
        [12033805] = {
          Camera = "307.06311,389.990509,165.030273,19.998463,4.917798,10.989902,35.000015,564.832214,false,Manual,22.0",
          ContentFR = "Bordel ! C’est qui ces deux {性别:morveux|morveuses} ?! Vous croyez pouvoir me voler ma prise et vous en tirer {性别:vivants|vivantes} ?!",
          DialogueId = 12033805,
          FinalCamera = "321.14917,392.725159,166.266602,19.998463,4.917798,10.989902,35.000015,564.832214,false,Manual,22.0",
          GUID = "1E201822",
          NextDialogue = 12033807,
          Scripts = "SEQ{\nPARA{\n\nMoveTo{ActorId{211037},TargetPoint{\"CinPoint_FN36b_Moveto01\"},MoveSpeed{220},Visibility{\"Show\"}},\nMoveTo{ActorId{211038},TargetPoint{\"CinPoint_FN36b_Moveto02\"},MoveSpeed{220},Visibility{\"Show\"}},\nMoveTo{_delay{0},ActorId{211039},TargetPoint{\"CinPoint_FN36b_Moveto03\"},MoveSpeed{220},Visibility{\"Show\"}}\n},\nPARA{\nPlayAnimation{_delay{3.0},ActorId{211001},AnimationId{\"Feina_Story_Wish_End\"}},\nPlayAnimation{_delay{3.0},ActorId{211037},AnimationId{\"Angry01_Start\"}}\n}\n}",
          SpeakNpcId = 211037,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E201822"
        },
        [12033806] = {
          ContentFR = "La mêlée explose. Plusieurs foncent sur Fina. Le protagoniste tente de l’intercepter mais est débordé.",
          DialogueId = 12033806,
          GUID = "1E20184C",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20184C"
        },
        [12033807] = {
          Camera = "385.469147,335.746613,191.395508,15.003618,3.517841,33.39724,35.000015,564.832214,false,Manual,22.0",
          ContentFR = "Fina ! Attention !",
          DialogueId = 12033807,
          FinalCamera = "-93.919144,34.563732,169.15918,15.00191,-0.68209,29.795591,35.000011,564.832214,false,Manual,22.0",
          GUID = "1E201876",
          NextDialogue = 12033809,
          Scripts = "PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Shock01"}}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E201876"
        },
        [12033808] = {
          ContentFR = "Fina sursaute, la peur dans les yeux... mais très vite, son regard s’affermit.",
          DialogueId = 12033808,
          GUID = "1E2018A0",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2018A0"
        },
        [12033809] = {
          Camera = "220.127319,165.86731,158.923828,0.000001,1.599992,-145.198242,35.000019,99.650665,false,Manual,2.799999",
          ContentFR = "Fina... a grandi. Je ne suis plus un petit oisillon sans défense...",
          DialogueId = 12033809,
          FinalCamera = "200.113861,151.653381,183.478516,0.000002,-2.999962,-145.595749,35.000019,78.705475,false,Manual,2.799999",
          GUID = "1E2018CA",
          Scripts = "\nPARA{\nTurnTo{_delay{5.01},TurnToDescription{\"211001:n(211037)\"}},\nPlayFacial{_delay{1.0},ActorId{211001},FacialId{\"Think01\"}},\nPlayFacial{_delay{8.05},ActorId{211001},FacialId{\"None\"}},\nPlayAnimation{_delay{0.5},ActorId{211037},AnimationId{\"Angry01_End\"}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2018CA"
        },
        [12033810] = {
          ContentFR = "Je peux protéger les autres, moi aussi !",
          DialogueId = 12033810,
          GUID = "1E2018F4",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2018F4"
        },
        [12033811] = {
          Content = "菲娜站在塞维欧前方，翻开魔法书\n这时塞维欧醒过来，模模糊糊地睁开眼睛，看到了菲娜召唤出的蝴蝶，惊讶地睁大了眼睛",
          DialogueId = 12033811,
          GUID = "1E20191E",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20191E"
        },
        [12033812] = {
          ContentFR = "Grande sœur... Serafina ?",
          DialogueId = 12033812,
          GUID = "1E201948",
          SpeakNpcId = 211015,
          VoiceName = "voice/$Locale$/story/1201/120114/1E201948"
        },
        [12033813] = {
          Content = "闪回塞维欧小时候的记忆，第一视角看着飞舞的蝴蝶，背景里有菲娜模糊的身影\n回到现实",
          DialogueId = 12033813,
          GUID = "1E201972",
          VoiceName = "voice/$Locale$/story/1201/120114/1E201972"
        },
        [12033814] = {
          ContentFR = "Venez, mes amis ! Ensemble, protégeons tout le monde !",
          DialogueId = 12033814,
          GUID = "1E20199C",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20199C"
        },
        [12033815] = {
          Content = "菲娜正脸特写，四个召唤兽围在她身边",
          DialogueId = 12033815,
          GUID = "1E2019C6",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2019C6"
        },
        [12033816] = {
          ContentFR = "(Le combat commence : Fina est jouable, le protagoniste apparaît comme partenaire.)",
          DialogueId = 12033816,
          GUID = "1E2019F0",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2019F0"
        },
        [12033850] = {
          ContentFR = "Fina... tu maîtrises une magie aussi puissante ?",
          DialogueId = 12033850,
          GUID = "1E201F84",
          NextDialogue = 12033851,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E201F84"
        },
        [12033851] = {
          ContentFR = "Ce n’est pas moi… ce sont mes amis qui viennent m’aider !",
          DialogueId = 12033851,
          GUID = "1E201FAE",
          NextDialogue = 12033852,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E201FAE"
        },
        [12033852] = {
          ContentFR = "Incroyable... alors je compte sur toi pour couvrir mes arrières.",
          DialogueId = 12033852,
          GUID = "1E201FD8",
          NextDialogue = 12033853,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E201FD8"
        },
        [12033853] = {
          ContentFR = "D’accord !",
          DialogueId = 12033853,
          GUID = "1E202002",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E202002"
        },
        [12033854] = {
          ContentFR = "(Le combat se termine.)",
          DialogueId = 12033854,
          GUID = "1E20202C",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20202C"
        },
        [12033901] = {
          Camera = "-117.482666,346.205109,243.077148,0.000074,-30.400671,-45.985844,18.0,100000.0,false,Manual,22.0",
          ContentFR = "On a gagné... {性别:Monsieur|Mademoiselle} Licorne, on a battu les vilains bandits !",
          DialogueId = 12033901,
          FinalCamera = "-98.261375,326.185089,226.790039,0.000075,-30.400665,-46.185848,18.0,100000.0,false,Manual,22.0",
          GUID = "1E2027E2",
          NextDialogue = 12033902,
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}},\nLookAt{_delay{0.5},LookAtDescription{\"100001:n(211001)\"}},\nLookAt{_delay{1},LookAtDescription{\"211001:n(100001)\"}},\nLookAt{_delay{1},LookAtDescription{\"211015:n(211001)\"}},\nPlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"}},\nCameraMoveTo{_delay{3},TargetPosition{\"59.929974,253.824341,119.731445,0.000051,-13.800601,-49.38739,25.0,224.769989,false,Manual,4.0\"},duration{0}},\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2027E2"
        },
        [12033902] = {
          Camera = "142.19931,-3.867684,97.571289,0.0001,-0.400755,86.011314,25.0,215.530014,false,Manual,4.0",
          ContentFR = "Oui, et c’est grâce au courage de notre petite Fina.",
          DialogueId = 12033902,
          GUID = "1E20280C",
          NextDialogue = 12033903,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{"Explain01_Start"}}",
