          VoiceName = "voice/$Locale$/story/1201/120114/1E20280C"
        },
        [12033903] = {
          Camera = "142.19931,-3.867684,97.571289,0.0001,-0.400755,86.011314,25.0,215.530014,false,Manual,4.0",
          ContentFR = "Héhé...",
          DialogueId = 12033903,
          FinalCamera = "142.19931,-3.867684,97.571289,0.0001,-0.400755,86.011314,25.0,215.530014,false,Manual,4.0",
