        },
        [12034105] = {
          Camera = "-876.449036,601.317261,201.322266,0.000065,-11.157715,-19.005154,30.0,173.055267,false,DoNotOverride,8.0",
          ContentFR = "Exactement ! C’est moi qui les ai embauchés. Ce ne sont pas des méchants !",
          DialogueId = 12034105,
          FinalCamera = "-876.449036,601.317261,217.300781,0.000066,-10.35766,-19.005308,30.0,173.055267,false,DoNotOverride,8.0",
          GUID = "1E20495A",
          NextDialogue = 12034106,
          SpeakNpcId = 211012,
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "211012:p(-180)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E20495A"
        },
        [12034106] = {
          Camera = "-261.812439,310.25946,99.939453,0.000086,-2.357686,-2.005544,35.0,688.037964,false,Manual,4.0",
          ContentFR = "... Très bien. Nous allons emmener ces bandits.",
          DialogueId = 12034106,
          FinalCamera = "-261.654846,314.867767,99.939453,0.000086,-2.357686,-1.605461,35.0,688.037964,false,Manual,4.0",
          GUID = "1E204984",
          NextDialogue = 12034107,
          SpeakNpcName = "UI_FNNpc_Name_SoldierPSD",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E204984"
        },
        [12034107] = {
          Camera = "199.814636,389.031067,112.981445,0.000071,1.842389,7.599753,50.0,198.341919,false,Manual,5.0",
          ContentFR = "Hmpf... cette fichue Charon récupératrice qui arrêtait pas de venir nous bassiner avec ses histoires de brigands au Lac du Deuil... On pensait qu’elle radotait, mais finalement elle disait vrai.",
          DialogueId = 12034107,
          FinalCamera = "199.727524,389.644745,112.981445,0.000072,2.04239,8.399999,55.0,198.341919,false,Manual,5.0",
