          VoiceName = "voice/$Locale$/story/1201/120114/1E208A7C"
        },
        [12034503] = {
          ContentFR = "Cassandra est partie faire des courses. Alors j’ai pensé t’apporter mon cadeau de remerciement en avance !",
          DialogueId = 12034503,
          GUID = "1E208AA6",
          NextDialogue = 12034504,
          Scripts = "PARA{\nPlayAnimation{_delay{0.5},ActorId{211015},AnimationId{\"Explain02_End\"}},\nPlayAnimation{_delay{3},ActorId{211015},AnimationId{\"Talk02_End\"}}\n}",
