        [12034701] = {
          Camera = "67.369461,704.07135,163.671875,0.000133,0.9707,-140.685501,28.000008,150.821991,false,Manual,10.0",
          ContentFR = "Tu sais quoi ? En sortant du magasin, je suis tombée sur {性别:Monsieur le|Mademoiselle la} Borgne ! Hé hé... Aujourd’hui, c’est moi qui régale ! J’ai pris des gâteaux, des biscuits et des bonbons, mangez tant que vous voulez !",
