          ContentFR = "{性别:Monsieur|Mademoiselle} Licorne... Tu te souviens de l’histoire du petit rossignol ?",
          DialogueId = 12034705,
          FinalCamera = "-131.751953,167.669998,125.972656,0.000117,-4.42978,-85.28421,35.0,152.132278,false,Manual,2.799999",
