        [12034706] = {
          Camera = "-133.403595,189.181717,129.325195,0.000126,-3.629699,-86.884636,55.000008,157.409622,false,Manual,2.8",
          ContentFR = "Pour vivre libre et protéger sa nouvelle famille, le rossignol avait trouvé le courage d’arracher le cœur de la bête... Mais il n’avait pas pensé qu’en faisant ça, un petit innocent perdrait sa famille.",
          DialogueId = 12034706,
          FinalCamera = "-132.252869,168.031204,127.981934,0.000126,-3.629699,-86.884636,55.000008,146.218048,false,Manual,2.8",
          GUID = "1E20ABF4",
          NextDialogue = 12034707,
          Scripts = "PARA{\nPlayAnimation{ActorId{211001},AnimationId{\"Shy01_End\"},Duration{1}},\nPlayFacial{ActorId{211001},FacialId{\"Sad01\"}}\n}",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20ABF4"
        },
        [12034707] = {
          Camera = "-152.890121,280.265839,135.861328,0.000102,-5.429713,-95.086906,28.0,289.881348,false,Manual,2.8",
          ContentFR = "Savio... il ne sait pas. C’est à cause de moi qu’il a perdu ses parents. Si un jour il l’apprend... il va me détester, non ?",
          DialogueId = 12034707,
          FinalCamera = "-152.054337,290.041656,136.793945,0.000102,-5.42972,-94.886803,28.0,289.881348,false,Manual,2.8",
          GUID = "1E20AC1E",
          NextDialogue = 12034708,
          Scripts = "\nPlayAnimation{ActorId{211001},AnimationId{\"Shy02_Start\"},Duration{1}}\n",
          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AC1E"
        },
        [12034708] = {
          Camera = "-54.464836,-58.781464,137.340332,0.000137,-3.229825,122.725037,55.000019,280.639313,false,Manual,2.8",
          ContentFR = "Tu te rappelles l’histoire que je lui ai racontée ? Ce n’était pas le rossignol le vrai coupable... mais ce <H>monstre invisible</> qu’on appelle « Préjugé ».",
          DialogueId = 12034708,
          FinalCamera = "-65.446648,-41.691383,136.194824,0.000137,-3.229825,122.725037,55.000019,265.368195,false,Manual,2.8",
          GUID = "1E20AC48",
          NextDialogue = 12034709,
          Scripts = "PARA{\nPlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}},\nPlayFacial{ActorId{100001},FacialId{\"Smile01\"}}\n}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AC48"
        },
        [12034709] = {
          ContentFR = "Si Savio a compris ce que je voulais dire, alors le jour où il découvrira la vérité... il saura que ce n’était pas ta faute.",
          DialogueId = 12034709,
          GUID = "1E20AC72",
          NextDialogue = 12034710,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Talk03ToThink_Start\"},Duration{1}},\nPlayFacial{ActorId{100001},FacialId{\"None\"}}\n}",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AC72"
        },
        [12034710] = {
          Camera = "-89.602119,72.514511,130.676758,0.000117,-1.429961,130.515015,35.0,135.543976,false,Manual,2.8",
          ContentFR = "Et puis, pour l’instant, vous êtes encore des enfants. Mange bien, dors tôt, amuse-toi avec tes amis autour d’un goûter... Les choses compliquées, tu les affronteras quand tu seras grande.",
          DialogueId = 12034710,
          FinalCamera = "-98.979286,83.485565,130.317871,0.000119,-1.429961,130.514984,35.000008,135.543976,false,Manual,2.8",
          GUID = "1E20AC9C",
          NextDialogue = 12034711,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{"Think_End"},Duration{1}}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AC9C"
        },
        [12034711] = {
