          NextDialogue = 20000506,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{"10.674805,-22.738281,62.996094,0.000332,-4.200955,-11.227787,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}}",
          SpeakNpcId = 200025,
          Subtitle = "You should watch what you say! ",
