        },
        [20000512] = {
          Camera = "-448.745361,204.227051,210.797119,0.000268,-16.801117,-22.812357,80.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... C’est bien ça. L’odeur d’une <H>arme légendaire</> ! Dis-moi, {性别:gamin|gamine}, cacherais-tu une arme extraordinaire ?",
