          GUID = "3211C6E6",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextOptions = {
            [1] = 200006151,
            [2] = 200006152
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{3.1},TargetPosition{\"-277.723358,-99.678711,81.074387,0.000378,1.599985,26.80905,25.0,272.329132,false,Manual,1.32502\"},duration{0}},\nCameraMoveTo{_delay{3.2},TargetPosition{\"-291.878387,-106.830566,80.631393,0.000378,1.599985,26.80905,25.0,272.329132,false,Manual,1.32502\"},blend{\"easeOutQuad\"},duration{3}}\n}",
          SpeakNpcId = 200002,
          Subtitle = "My little minion, you must stick with me. After I conquer the world, you'll be the leader of my legion! Just you wait and see!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C6E6"
        },
        [20000618] = {
          Camera = "-100.573456,-44.273193,82.943001,0.000289,2.394917,38.210751,50.0,255.910919,false,Disable,2.8",
          ContentFR = "Hmmm... disons... vingt lettres de louange signées de la main du Roi Démon chaque jour ? Oh, bah, on verra bien. Une chose est sûre : je ne te laisserai jamais tomber.",
          DefaultLookAt = "Self",
          DialogueId = 20000618,
          Duration = 3,
          GUID = "3211C764",
          NextDialogue = 20000619,
          SpeakNpcId = 200002,
          Subtitle = "Hmm... How about 20 letters of praise written by this Demon King? Anyway, we can talk about the details when the time comes. All you need to know is that I'll never let you down.",
          TalkActionId = {
