          NextDialogue = 20001802,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200018/3212897A"
        },
        [20001802] = {
          ContentFR = "Snow, reste derrière nous. Avançons seulement quand le vent se calme un peu.",
          DialogueId = 20001802,
          ExStoryInfo = "Player",
          GUID = "321289A4",
