          GUID = "32130CE4",
          NextDialogue = 20002603,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc2",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CE4"
        },
        [20002603] = {
          ContentFR = "Ne... ne paniquez pas... Les Veilleurs arrivent bientôt !",
          DialogueId = 20002603,
          GUID = "32130D0E",
          NextDialogue = 20002604,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc3",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D0E"
        },
        [20002604] = {
          ContentFR = "Et vous, n’essayez pas de profiter du chaos pour entrer. Montrez vos permis de circulation !",
          DialogueId = 20002604,
          GUID = "32130D38",
          NextDialogue = 20002605,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc4",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D38"
        },
        [20002605] = {
          ContentFR = "Pitié, laissez-nous entrer ! On a vraiment juste perdu notre permis de circulation par accident !",
          DialogueId = 20002605,
          GUID = "32130D62",
          NextDialogue = 20002606,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc5",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D62"
        },
        [20002606] = {
          ContentFR = "Vous pensez encore aux permis de circulation ?! Dehors on est condamnés de toute façon, autant forcer le passage !",
          DialogueId = 20002606,
          GUID = "32130D8C",
          NextDialogue = 20002607,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc6",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D8C"
        },
        [20002607] = {
          ContentFR = "Halte ! Arrêtez ou je tire !",
          DialogueId = 20002607,
          GUID = "32130DB6",
          NextDialogue = 20002608,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc7",
          VoiceName = "voice/$Locale$/story/2001/200026/32130DB6"
        },
        [20002608] = {
          ContentFR = "Tire donc ! Fais du bruit et attire le Dégradé, qu’on crève tous ensemble !",
