        [20005304] = {
          Camera = "-174.296875,-493.421875,69.123047,0.0,-9.999956,-157.999863,50.0,274.526611,false,Manual,2.0",
          ContentFR = "Ouah ! Le cochon géant est réel... et il parle ! Le Roi Démon décrète que nous devons l’écouter ! Et puis ces types étaient louches, de toute façon...",
          DialogueId = 20005304,
          GUID = "3214C830",
          Scripts = "PARA{\nPlayFacial{_delay{1},ActorId{200002},FacialId{\"Shock01\"}},\nPlayAnimation{_delay{4},ActorId{200002},AnimationId{\"SpecialConfident_Start\"},Duration{1}},\nCameraMoveTo{_delay{4},TargetPosition{\"-480.78125,-711.425781,30.280273,0.000005,-2.99999,64.808571,25.0,222.467651,false,Manual,2.0\"},duration{0}},\nCameraMoveTo{_delay{4.1},TargetPosition{\"-480.78125,-711.425781,58.818359,0.000003,-7.999968,64.807953,25.0,391.569885,false,Manual,2.0\"},blend{\"easeInOutQuad\"},duration{4}}\n}",
