        [20005408] = {
          Camera = "-472.675781,-861.3125,125.09082,-3.000003,-4.399693,67.000412,50.0,1228.478149,false,DoNotOverride,1.847697",
          ContentFR = "Bonjour ! Je m’appelle Truffle. Je viens de très, très loin. Et voici Filbert, ma meilleure amie et ma partenaire. Merci beaucoup d’avoir aidé à sauver les Géniemon et d’avoir mis ces vilains chasseurs en fuite !",
          DialogueId = 20005408,
          FinalCamera = "-458.234375,-820.003906,125.068359,-3.000002,-4.399693,67.001587,50.0,1228.478149,false,DoNotOverride,1.847697",
          GUID = "3214D940",
          NextDialogue = 20005409,
          Scripts = "PARA{\nCameraMoveTo{_delay{5},TargetPosition{\"-138.240234,216.488281,55.927734,-3.000001,21.599953,-21.991064,30.0,1228.478149,false,DoNotOverride,1.847697\"},duration{0}},\nLookAt{_delay{5.5},LookAtDescription{\"200074:n(200086)\"}}\n}",
