          VoiceName = "voice/$Locale$/story/2001/200054/3214DB8C"
        },
        [20005423] = {
          Camera = "-44.972656,-76.457031,81.133789,2.000004,2.99999,-132.004791,35.000008,161.618286,false,Manual,4.88291",
          ContentFR = "Tiens, prends ça, un Délice Yum ! Tous les Géniemon en raffolent. Avec un peu de chance, un seul morceau suffira pour qu’il t’accompagne. Sinon... eh bien, donne-lui-en plusieurs, et il finira par te suivre.",
          DialogueId = 20005423,
          GUID = "3214DBB6",
