        [20005430] = {
          Camera = "326.640625,181.09375,97.236328,-5.000004,-1.599883,-150.400177,30.0,310.625153,false,Manual,1.2",
          ContentFR = "Il dit que tu lui sembles familier, qu’il se sent en sécurité près de toi. Il veut rester avec toi. Protège-le, et il pourra t’aider quand tu en auras besoin.",
