        },
        [20005705] = {
          Camera = "64.671875,111.317383,101.9104,-0.000031,9.201856,170.022354,35.000008,161.309708,false,Manual,12.0",
          ContentFR = "Mais les gardes à la porte sont si sévères... Dès que je m’approche, ils se mettent à hurler « Permis de circulation ! » comme des petits chiots effrayés.",
          DialogueId = 20005705,
          FinalCamera = "55.654297,112.968506,103.494141,-0.00003,9.801861,169.622452,35.000008,161.309708,false,Manual,12.0",
          GUID = "321509FA",
          NextDialogue = 20005706,
          Scripts = "SEQ{\nPARA{\nPlayFacial{_delay{0.5},ActorId{200074},FacialId{\"Sad01\"}}\n},\nPARA{\nPlayFacial{_delay{4.5},ActorId{200074},FacialId{\"Unhappy01\"}},\nPlayAnimation{_delay{4.5},ActorId{200074},AnimationId{\"Think_End\"}}\n}\n}",
