        [20005710] = {
          ContentFR = "Comment faire entrer Truffle à Givrelac ? C’est simple, en trois étapes :\n1) Aller aux Asphodèles.\n2) Demander de l’aide à Camilla.",
          DialogueId = 20005710,
          GUID = "32150ACC",
          VoiceName = "voice/$Locale$/story/2001/200057/32150ACC"
        },
        [20005711] = {
          Camera = "186.849121,350.689453,139.634766,0.000105,-3.997586,-21.968235,35.0,214.900024,false,Manual,2.5",
          ContentFR = "Tu veux que je fasse entrer une petite fille et un énorme cochon, sans permis, pour traquer des chasseurs de Géniemon ?",
          DialogueId = 20005711,
          FinalCamera = "211.255615,398.773438,139.634766,0.000105,-1.797426,-36.767586,35.0,214.900024,false,Manual,2.5",
