        [20005713] = {
          Camera = "105.950684,106.310547,143.28125,0.000089,-0.195924,25.407034,35.0,296.233398,false,Manual,3.5",
          ContentFR = "Je suis une femme d’affaires, pas une philanthrope. Techniquement, je ne devrais pas accepter ta demande aussi absurde. Cela dit, tu m’as parlé d’une certaine Truffle, et son amie s’appelle Filbert, elles viennent de très loin...",
          DialogueId = 20005713,
          FinalCamera = "126.168945,116.245117,143.28125,0.000089,0.004084,25.406322,35.0,296.233398,false,Manual,3.5",
          GUID = "32150B4A",
          NextDialogue = 20005714,
          Scripts = "PARA{\nCameraMoveTo{_delay{10.01},TargetPosition{\"329.772583,250.364258,155.642578,0.0001,5.403574,13.413886,35.0,65.400925,false,Manual,3.5\"},duration{0}},\nSEQ{\nPlayAnimation{ActorId{700248},AnimationId{\"Talk03ToTalkL_Start\"}},\nPlayAnimation{_delay{2},ActorId{700248},AnimationId{\"Talk03ToTalkL_End\"}}\n},\nPlayAnimation{_delay{10.1},ActorId{700248},AnimationId{\"Talk03ToThink_Start\"},Duration{1}}\n}",
          SpeakNpcId = 700248,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150B4A"
        },
        [20005714] = {
          Camera = "162.299316,114.061523,175.494141,0.000119,-6.196505,33.218781,35.0,247.15065,false,Manual,3.5",
          ContentFR = "Cela correspond parfaitement à certaines informations dont je dispose. Faire une faveur pour elle ne me pose pas de problème, mais je ne peux absolument pas garantir leur sécurité une fois en ville.",
          DialogueId = 20005714,
          FinalCamera = "31.679077,26.966797,192.6875,0.000139,-8.796512,33.820679,35.0,386.063599,false,Manual,12.0",
          GUID = "32150B74",
          Scripts = "PARA{\nCameraMoveTo{_delay{10.01},TargetPosition{\"223.292969,158.923828,146.234375,0.000157,-1.396685,-143.179001,35.0,73.960266,false,Manual,12.0\"},duration{0}},\nCameraMoveTo{_delay{12.1},TargetPosition{\"332.739868,241.896484,171.638672,0.000163,-6.796741,21.82086,35.0,73.960266,false,Manual,12.0\"},duration{0}},\nPlayFacial{_delay{10.1},ActorId{100001},FacialId{\"Smile02\"}},\nPlayFacial{_delay{12.1},ActorId{700248},FacialId{\"Smile02\"}},\nSEQ{\nPlayAnimation{_delay{1.1},ActorId{700248},AnimationId{\"Talk03ToThink_End\"}},\nPlayAnimation{_delay{4.1},ActorId{700248},AnimationId{\"Talk03_End\"}},\nPlayAnimation{_delay{4.1},ActorId{700248},AnimationId{\"Confident_Start\"}}\n}\n}",
          SpeakNpcId = 700248,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150B74"
        },
        [20005715] = {
          ContentFR = "Troisième étape : refermer les portes des Asphodèles derrière Truffle.",
