          },
          NextDialogue = 20005721,
          Scripts = "SEQ{\nPARA{\nPlayAnimation{_delay{0.1},ActorId{200074},AnimationId{\"Talk02_Start\"}},\nPlayFacial{_delay{1.1},ActorId{200074},FacialId{\"Smile02\"}}\n},\nPlayAnimation{_delay{4.1},ActorId{200074},AnimationId{\"Talk02_End\"}},\n}",
          SpeakNpcId = 200074,
