        },
        [20005721] = {
          Camera = "326.630066,314.076172,119.080078,-0.000763,-0.992235,160.615051,35.000008,86.408539,false,Manual,12.0",
          ContentFR = "Ah, parlons-en ! On doit aller chercher ces vilains. Givrelac est bien plus grand que je pensais, il faut se dépêcher !",
          DialogueId = 20005721,
          GUID = "32150C9A",
          NextDialogue = 20005722,
          Scripts = "PARA{\nCameraMoveTo{_delay{2.01},TargetPosition{\"405.59903,285.685547,124.849609,-0.000763,-5.39227,160.014969,35.000008,216.630737,false,Manual,12.0\"},duration{0}},\nSEQ{\nPlayFacial{_delay{0.3},ActorId{200074},FacialId{\"Shock01\"}},\nPARA{\nPlayAnimation{_delay{2.1},ActorId{200074},AnimationId{\"Explain02_Start\"}},\nPlayFacial{_delay{2.1},ActorId{200074},FacialId{\"Confident01\"}}\n},\nPlayAnimation{_delay{5.1},ActorId{200074},AnimationId{\"Explain02_End\"}}\n}\n}",
