        },
        [20005723] = {
          Camera = "427.671539,393.154297,128.347656,-0.000763,-6.992433,-162.983078,35.000008,216.630737,false,Manual,12.0",
          ContentFR = "J’ai l’unique Filbert ! Son flair est incroyable, elle peut sentir les Géniemon aux alentours et repérer les chasseurs !",
          DialogueId = 20005723,
          FinalCamera = "427.671539,393.154297,128.347656,-0.000763,-8.192443,-154.983536,35.000008,216.630737,false,Manual,12.0",
          GUID = "32150CEE",
          LookAt = {
            [1] = "200074:n(200086)"
          },
          Scripts = "PARA{\nPlayFacial{_delay{2.1},ActorId{200074},FacialId{\"Happy01\"}},\nPlayAnimation{_delay{4.1},ActorId{200074},AnimationId{\"Confident_Start\"}}\n}",
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200074:p(45)"
          },
          VoiceName = "voice/$Locale$/story/2001/200057/32150CEE"
        },
        [20005801] = {
          ContentFR = "Allons en hauteur, là où l’odeur se répand le mieux.",
          DialogueId = 20005801,
          GUID = "321519BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/321519BA"
        },
        [20005802] = {
          ContentFR = "Ah ! Filbert a flairé quelque chose, regardez par là !",
          DialogueId = 20005802,
          GUID = "321519E4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/321519E4"
        },
        [20005803] = {
          ContentFR = "C’est bien ici... mais aucun Géniemon à l’horizon, seulement...",
          DialogueId = 20005803,
          GUID = "32151A0E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A0E"
        },
        [20005804] = {
          ContentFR = "Oh non ! Leurs pièges... Ces vilains sont déjà partis !",
          DialogueId = 20005804,
          GUID = "32151A38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005805,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A38"
        },
        [20005805] = {
          ContentFR = "Allons un peu plus loin, là où il y a moins de monde, l’odeur sera plus facile à suivre.",
          DialogueId = 20005805,
          GUID = "32151A62",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A62"
        },
        [20005901] = {
          ContentFR = "Ici, ici, {性别:Monsieur|Mademoiselle}, doucement, marche lentement, fais attention à ne pas glisser.",
          DialogueId = 20005901,
          GUID = "32152A22",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200059/32152A22"
        },
        [20005902] = {
          ContentFR = "Euh... ici aussi, il y a un piège.",
          DialogueId = 20005902,
          GUID = "32152A4C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005903,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200059/32152A4C"
        },
        [20005903] = {
          ContentFR = "Groin…",
          DialogueId = 20005903,
          GUID = "32152A76",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005904,
          SpeakNpcId = 200086,
          VoiceName = "voice/$Locale$/story/2001/200059/32152A76"
        },
        [20005904] = {
          ContentFR = "Allez, Filbert, ne te décourage pas, on essaie l’endroit suivant.",
          DialogueId = 20005904,
          GUID = "32152AA0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200059/32152AA0"
        },
        [20006001] = {
          Camera = "606.297791,-918.271484,784.640625,0.000207,-7.459188,79.056267,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "C’est... l’entrée des égouts ?",
          DialogueId = 20006001,
          FinalCamera = "541.89978,-1160.757812,832.416992,0.000208,-8.459162,77.455727,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153A8A",
          NextDialogue = 20006002,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153A8A"
        },
        [20006002] = {
          Camera = "-38.9104,-306.495117,391.232422,0.000209,-8.45895,-1.344757,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "Oui. Il y a beaucoup d’humidité et peu de monde ici, c’est un bon endroit pour que des Géniemon apparaissent.",
          DialogueId = 20006002,
          FinalCamera = "-508.082397,-300.290039,450.730469,0.000209,-7.058932,-0.744781,35.000019,174.116943,false,Manual,12.0",
          GUID = "32153AB4",
          NextDialogue = 20006003,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153AB4"
        },
        [20006003] = {
          Camera = "-768.485962,-608.558594,293.948242,0.000155,-2.058947,167.054123,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "Mais aux deux autres endroits, les Géniemon ont déjà été capturés. J’ai un mauvais pressentiment pour celui-ci aussi....",
          DialogueId = 20006003,
          FinalCamera = "-796.652222,-602.085938,292.908691,0.000155,-0.458948,167.453751,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153ADE",
          NextDialogue = 20006004,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153ADE"
        },
        [20006004] = {
          Camera = "-913.889771,-785.241211,282.312012,0.000156,-6.059081,28.454039,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "Ah ! Un piège encore intact ! Il y a un Géniemon à l’intérieur !",
          DialogueId = 20006004,
          FinalCamera = "-932.27832,-741.113281,282.15332,0.000157,-6.459043,18.853708,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153B08",
          NextDialogue = 20006005,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200074:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B08"
        },
        [20006005] = {
          Camera = "-264.765686,-875.787109,308.994629,0.000174,-6.859033,150.453903,35.000015,733.116943,false,Manual,22.0",
          ContentFR = "Super, cette fois on est arrivés à temps. D’abord on le libère, puis on attend que les chasseurs apparaissent.",
          DialogueId = 20006005,
          FinalCamera = "-222.946228,-1021.376953,416.390625,0.000172,-15.459046,141.053696,35.000015,733.116943,false,Manual,22.0",
          GUID = "32153B32",
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B32"
        },
        [20006006] = {
          ContentFR = "Après quelques instants d’agitation, le Géniemon pris au piège est délivré. Toutefois... son attitude paraît... peu accueillante.",
          DialogueId = 20006006,
          GUID = "32153B5C",
          VoiceName = "voice/$Locale$/story/2001/200060/32153B5C"
        },
        [20006007] = {
          Camera = "-348.273315,-725.485352,348.286133,0.000093,-9.591675,168.57576,35.0,1674.542114,false,Manual,22.0",
          ContentFR = "Ne crains rien, petit Géniemon. Le Grand Roi Démon, mon petit larbin et la Chasseuse de Chasseurs de Géniemon sommes venus te sauver ! Maintenant file, mets-toi à l’abri !",
          DialogueId = 20006007,
          FacialId = {
