          VoiceName = "voice/$Locale$/story/2001/200060/32153CD6"
        },
        [20006016] = {
          Camera = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
          ContentFR = "Hein ? Il s’est recaché dans le piège ? Est-ce qu’il a tellement peur de nous qu’il croit être en sécurité là-dedans ?",
          DialogueId = 20006016,
          FinalCamera = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
          GUID = "32153D00",
