        [20006023] = {
          Camera = "-687.931763,-671.883789,322.655273,0.000069,-2.197053,176.775879,35.0,174.116943,false,Manual,12.0",
          ContentFR = "Ici, il sent l’odeur des autres Géniemon capturés, c’est pour ça qu’il refuse de s’éloigner.",
