        },
        [20006031] = {
          ContentFR = "D’accord !",
          DialogueId = 20006031,
          GUID = "32153F76",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200060/32153F76"
        },
        [20006032] = {
          Camera = "-593.543457,-336.325195,269.372559,0.000176,-9.390683,-128.619858,35.000008,268.984894,false,Manual,12.0",
          ContentFR = "J’ai bien envie de leur casser la figure tout de suite, mais bon, on gardera ça pour plus tard !",
          DialogueId = 20006032,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "-632.141357,-384.262695,260.398438,0.000174,-8.190715,-130.618393,35.000008,268.984894,false,Manual,12.0",
          GUID = "32153FA0",
          NextDialogue = 20006033,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FA0"
        },
        [20006033] = {
          Camera = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
          ContentFR = "Je pensais que nous avions déjà capturé tous les Géniemon de Givrelac, mais il semble que nous en ayons attrapé un autre...",
          DialogueId = 20006033,
          GUID = "32153FCA",
          NextDialogue = 20006034,
          SpeakNpcId = 200075,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FCA"
        },
        [20006034] = {
          Camera = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          ContentFR = "Nous devons encore sortir de la cité, c’est là qu’on en attrape le plus. Mais cette gamine qui monte sur son cochon, quand est-ce qu’elle va enfin bouger ?",
          DialogueId = 20006034,
          FinalCamera = "-443.855225,194.355469,326.509277,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          GUID = "32153FF4",
          NextDialogue = 20006035,
          SpeakNpcId = 200087,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FF4"
        },
        [20006035] = {
          ContentFR = "T’inquiète pas, elle partira. Elle ne va pas pouvoir rester bien longtemps devant la cité.",
          DialogueId = 20006035,
          GUID = "3215401E",
          NextDialogue = 20006036,
          SpeakNpcId = 200075,
          TalkActionId = {
            [1] = "200075:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/3215401E"
        },
        [20006036] = {
          ContentFR = "Ouais, avec le froid et les Souillés, elle risque de bien vite rentrer en pleurant.",
          DialogueId = 20006036,
          GUID = "32154048",
          NextDialogue = 20006037,
          SpeakNpcId = 200087,
          TalkActionId = {
            [1] = "200075:Talk02_End",
            [2] = "200087:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154048"
        },
        [20006037] = {
          ContentFR = "Tant mieux !",
          DialogueId = 20006037,
          GUID = "32154072",
          SpeakNpcId = 200075,
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154072"
        },
        [20006101] = {
          Camera = "-1302.360229,-832.505859,345.045898,0.000178,-0.789761,21.978495,35.0,1674.542114,false,Manual,2.8",
          ContentFR = "Ils retournent dans les égouts ! Allez, on les suit vite !",
          DialogueId = 20006101,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32154AF2",
