        },
        [20006728] = {
          Camera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          ContentFR = "Yiiip !",
          DialogueId = 20006728,
          FinalCamera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B1D0",
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1D0"
        },
        [20006801] = {
          ContentFR = "Finalement, les Géniemon furent conduits jusqu’aux Asphodèles, les clients de la taverne prirent la fuite, renversant chaises et verres dans la précipitation. Camilla fronça les sourcils et se demanda si laisser {nickname} entrer en ville n’avait pas été une énorme erreur.",
          DialogueId = 20006801,
          Duration = 5,
          GUID = "3215BDCA",
          VoiceName = "voice/$Locale$/story/2001/200068/3215BDCA"
        },
        [20006901] = {
          ContentFR = "Puis, au fil des jours, le froncement de sourcils de Camilla finit par s’adoucir...",
          DialogueId = 20006901,
          Duration = 3,
          GUID = "3215CE32",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE32"
        },
        [20006902] = {
          Camera = "-77.774261,-546.844727,210.810547,-0.000763,-8.992114,80.412018,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Eh bien, Camilla, sers-moi un Spécial Piquero. Par ce froid, un petit remontant chauffé par de vraies flammes, c’est ce qu’il nous faut.",
          DialogueId = 20006902,
          GUID = "3215CE5C",
          LookAt = {
            [1] = "700253:n(700248)",
            [2] = "700254:n(700253)"
          },
          NextDialogue = 20006903,
          Scripts = "PARA{\nPlayFacial{_delay{3.5},ActorId{700248},FacialId{\"Confident01\"}},\nPlayAnimation{_delay{3.1},ActorId{700248},AnimationId{\"Talk03_Start\"}}\n}",
          SpeakNpcId = 700253,
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE5C"
        },
        [20006903] = {
          ContentFR = "Au début, je pensais que cette petite chose était maléfique... mais sa flamme est parfaite pour chauffer une bonne boisson, c’est génial !",
          DialogueId = 20006903,
          GUID = "3215CE86",
          LookAt = {
            [1] = "700253:n(700253)"
          },
          NextDialogue = 20006904,
          SpeakNpcId = 700253,
          TalkActionId = {
            [1] = "700253:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE86"
        },
        [20006904] = {
          Camera = "-270.673706,295.446289,221.228516,-0.000763,-10.792361,-56.385796,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Triste sort, Wells, ô triste sort, Wells.",
          DialogueId = 20006904,
          GUID = "3215CEB0",
          NextDialogue = 20006905,
          SpeakNpcId = 700254,
          TalkActionId = {
            [1] = "700254:Sigh_Start",
            [2] = "700253:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEB0"
        },
        [20006905] = {
          Camera = "-37.503937,-47.555664,133.710938,-0.000763,-2.992312,-78.38279,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Toi qui vois seulement que le feu du Piquero réchauffe la boisson et réconforte le ventre, tu ignores sa vraie valeur : il fend l’obscurité, éclaire mes écrits la nuit et m’inspire !",
          DialogueId = 20006905,
          GUID = "3215CEDA",
          NextDialogue = 20006906,
          SpeakNpcId = 700254,
          TalkActionId = {
            [1] = "700254:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEDA"
        },
        [20006906] = {
          Camera = "-89.716675,175.708008,152.642578,-0.000763,-3.992218,-88.380859,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Pi-que-ro. Trois syllabes sublimes : la lumière de ma plume, l’ardeur de ma création ! Mon péché, mon salut !",
          DialogueId = 20006906,
          GUID = "3215CF04",
          SpeakNpcId = 700254,
          TalkActionId = {
            [1] = "700254:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CF04"
        },
        [20007001] = {
          Camera = "410.60437,303.494141,154.748047,0.000089,0.396813,37.710804,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Certains arrosent leurs fleurs avec des Gouttines, d’autres s’endorment grâce à M. Bonne Nuit... et maintenant, même mon commerce dépend d’un Piquero.",
          DialogueId = 20007001,
          FinalCamera = "262.071167,223.890625,147.691406,0.000094,-1.403686,36.110554,35.000011,369.08606,false,Manual,12.0",
          GUID = "3215DE9A",
          NextDialogue = 20007002,
          Scripts = "PARA{\nSEQ{\nTurnTo{_delay{2},TurnToDescription{\"700248:p(180)\"}},\nPlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Confident_Start\"},Duration{1}}\n},\nPlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}\n}",
          SpeakNpcId = 700248,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DE9A"
        },
        [20007002] = {
          ContentFR = "C’est drôle comme les choses changent. Hier encore, on parlait d’extraire le Phoxène des Géniemon, et maintenant, les gens en achètent exprès pour les nourrir et mieux s’en faire des amis.",
          DialogueId = 20007002,
          GUID = "3215DEC4",
          LookAt = {
            [1] = "100001:n(200074)",
            [2] = "200002:n(200074)"
          },
          NextDialogue = 20007003,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{700248},AnimationId{\"Confident_End\"},Duration{1}},\nPARA{\nPlayAnimation{_delay{1.5},ActorId{700248},AnimationId{\"Talk02_Start\"},Duration{1}},\nPlayFacial{_delay{7.5},ActorId{700248},FacialId{\"Smile02\"}}\n},\nPlayFacial{_delay{1.0},ActorId{700248},FacialId{\"None\"}}\n}",
          SpeakNpcId = 700248,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEC4"
        },
        [20007003] = {
          Camera = "855.156494,437.582031,235.363281,-0.000335,-12.202781,-167.746658,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "C’est grâce à Truffle et Filbert. Si Filbert sait vivre avec les humains, les Géniemon aussi le peuvent.",
          DialogueId = 20007003,
          GUID = "3215DEEE",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007004,
          Scripts = "SEQ{\nPlayAnimation{_delay{1},ActorId{700248},AnimationId{\"Talk02_End\"},Duration{1}}\n}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEEE"
        },
        [20007004] = {
          Camera = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,169.08606,false,Manual,12.0",
          ContentFR = "Et si les Géniemon peuvent coexister avec nous, peut-être qu’un jour Charons et Solariens trouveront aussi un terrain d’entente.",
          DialogueId = 20007004,
          GUID = "3215DF18",
          NextDialogue = 20007005,
          Scripts = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{"Smile01"}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF18"
        },
        [20007005] = {
          Camera = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Haha, je ne sais pas si tu es {性别:naïf|naïve} ou simplement {性别:porteur|porteuse} d’une grande vision. En tout cas, j’attends ce jour avec curiosité. Mais pour l’instant... il est temps de dire au revoir à cette petite voyageuse.",
          DialogueId = 20007005,
          FinalCamera = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DF42",
          NextDialogue = 20007006,
          Scripts = "SEQ{\nPlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Sigh_Start\"},Duration{2}},\nPlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Sigh_End\"},Duration{1}}}",
          SpeakNpcId = 700248,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF42"
        },
        [20007006] = {
          Camera = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Ouinnn... Truffle, tu ne peux pas rester à Givrelac ? Le Roi Démon de la Lumière a enfin trouvé quelqu’un pour scander ses titres ensemble !",
          DialogueId = 20007006,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "3215DF6C",
          NextDialogue = 20007007,
          SpeakNpcId = 200002,
          TurnTo = {
            [1] = "200074:p(30)"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF6C"
        },
        [20007007] = {
          ContentFR = "Ne pleure pas, Snow. Ça fait longtemps que je suis partie à l’aventure, il est temps de rentrer. Puis ces anciens chasseurs se sont reconvertis en chercheurs sur les Géniemon, tu peux leur demander de chanter tes titres avec toi.",
          DialogueId = 20007007,
          GUID = "3215DF96",
          NextDialogue = 20007008,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF96"
        },
        [20007008] = {
          Camera = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Non, ils n’ont pas ta voix, et ils ne peuvent pas me faire faire un tour sur Filbert comme toi. {nickname}, bouge-toi et aide-moi à convaincre Truffle de rester !",
          DialogueId = 20007008,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          GUID = "3215DFC0",
          NextOptions = {
            [1] = 200070081
          },
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "700248:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFC0"
        },
        [20007009] = {
          Camera = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Héhé, je reviendrai de temps en temps, promis. Et laisse-moi te dire un petit secret, l’endroit lointain où je retourne, c’est en fait l’Église Élyséenne.",
          DialogueId = 20007009,
          FacialId = {
            [1] = "200002:CM_Idle"
          },
          FinalCamera = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DFEA",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007010,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFEA"
        },
        [20007010] = {
          Camera = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Quand Filbert et moi cherchons de la nourriture, on traverse parfois, par des montagnes non gardées pour atteindre l’Hyperborea. Au début, j'avais un peu peur, après tout, l’Église et l’Empire ont toujours été en guerre...",
          DialogueId = 20007010,
          GUID = "3215E014",
          NextDialogue = 20007011,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E014"
        },
        [20007011] = {
          ContentFR = "Mais après vous avoir rencontré, je n’ai plus peur.",
          DialogueId = 20007011,
          GUID = "3215E03E",
          NextDialogue = 20007012,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E03E"
        },
        [20007012] = {
          ContentFR = "Parce que si tu peux trouver un moyen pour que les Géniemon et les humains vivent ensemble en amis, alors je crois qu’un jour, tu sauras aussi rapprocher les Charons et les Solariens, et peut-être même faire en sorte que l’Empire et l’Église cessent enfin de se battre.",
          DialogueId = 20007012,
          GUID = "3215E068",
          NextDialogue = 20007013,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E068"
        },
        [20007013] = {
          ContentFR = "Comme ça, plus personne n’aura faim !",
          DialogueId = 20007013,
          GUID = "3215E092",
          NextDialogue = 20007014,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E092"
        },
        [20007014] = {
          ContentFR = "Et quand ce jour viendra, viens me voir au sud avec Snow et Madame Camilla. On mangera des Chapeaux-de-Rubis tout roses, on sentira la brise chaude de la mer et on regardera plein d’étoiles qu’on ne voit pas ici. Ce sera trop bien, comme quand je suis venue ici ! Je vous attendrai !",
          DialogueId = 20007014,
          GUID = "3215E0BC",
          NextDialogue = 20007015,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0BC"
        },
        [20007015] = {
          ContentFR = "D’accord, je vais faire de mon mieux.",
          DialogueId = 20007015,
          GUID = "3215E0E6",
          NextDialogue = 20007016,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0E6"
        },
        [20007016] = {
          ContentFR = "On se le jure sur le petit doigt !",
          DialogueId = 20007016,
          GUID = "3215E110",
          NextOptions = {
            [1] = 200070161
          },
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E110"
        },
        [20007017] = {
          ContentFR = "Et avec Filbert aussi !",
          DialogueId = 20007017,
          GUID = "3215E13A",
          NextDialogue = 20007018,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E13A"
        },
        [20007018] = {
          ContentFR = "Les sabots de Filbert sont trop gros pour un petit doigt...",
          DialogueId = 20007018,
          GUID = "3215E164",
          NextDialogue = 20007019,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E164"
        },
        [20007019] = {
          ContentFR = "Alors tiens juste son sabot, ça marche quand même ! Allez, ensemble : promis sur le petit doigt, pour toujours !",
          DialogueId = 20007019,
          GUID = "3215E18E",
          NextDialogue = 20007020,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E18E"
        },
        [20007020] = {
          ContentFR = "Groin !",
          DialogueId = 20007020,
          GUID = "3215E1B8",
          SpeakNpcId = 200086,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E1B8"
        },
        [20007101] = {
          ContentFR = "Je suis... le premier chercheur en Géniemon de Givrelac ! Si vous avez des questions sur ces créatures, vous pouvez me demander — Ah, c’est toi... Euh, je peux t’aider ?",
          DialogueId = 20007101,
          GUID = "3215EF02",
          NextOptions = {
            [1] = 200071011,
            [2] = 200071012,
            [3] = 200071013
          },
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF02"
        },
        [20007102] = {
          ContentFR = "Tu veux parler de ce Géniemon réputé pour son intelligence ?",
          DialogueId = 20007102,
          GUID = "3215EF2C",
          NextDialogue = 20007103,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF2C"
        },
        [20007103] = {
          ContentFR = "Les archives sont très maigres. Je ne l’ai vu qu’une seule fois. On raconte qu’il ne se montre qu’à ceux qu’il juge dignes.",
          DialogueId = 20007103,
          GUID = "3215EF56",
          NextDialogue = 20007104,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF56"
        },
        [20007104] = {
          ContentFR = "En revanche, tu devrais pouvoir le localiser en suivant les traces qu’il laisse.",
          DialogueId = 20007104,
          GUID = "3215EF80",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF80"
        },
        [20007105] = {
          ContentFR = "Bien mieux que celle d’un chasseur de Géniemon. Maintenant, des gens viennent me poser des questions, j’ai l’air d’un vrai savant.",
          DialogueId = 20007105,
          GUID = "3215EFAA",
          NextDialogue = 20007106,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFAA"
        },
        [20007106] = {
          ContentFR = "Merci d’avoir été indulgent avec moi, toi et Truffle. Vraiment, merci.",
          DialogueId = 20007106,
          GUID = "3215EFD4",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFD4"
        },
        [20007107] = {
          Content = "若干道深深的刻痕，似是某种尖锐物体留下的痕迹。",
          DialogueId = 20007107,
          GUID = "3215EFD5"
        },
        [20007108] = {
          Content = "写着“禁区危险，严禁通行”的告示。贴了厚厚一叠，似乎是当老告示变旧了就会贴一张新告示上去。最新的一张告示落款是新历1004年，也就是二十年前——格雷姆矿场应当就是在那时彻底废弃的。",
          DialogueId = 20007108,
          GUID = "3215EFD6"
        },
        [21000101] = {
          Content = "背白白进场台词（测试用）",
          DialogueId = 21000101,
          GUID = "34925112",
          TalkActionId = {
            [1] = "900005:Beibao_Start"
          }
        },
        [21000102] = {
          Content = "背白白退场台词（测试用）",
          DialogueId = 21000102,
          GUID = "3492513C",
          TalkActionId = {
            [1] = "900005:Beibao_Finish"
          }
        },
        [50000101] = {
          ContentFR = "Hé, c’est à toi que je parle ! Tu as bien ton permis sur toi ?",
          DialogueId = 50000101,
          Duration = 3,
          GUID = "7D2B8592",
          SpeakNpcId = 700111,
          Subtitle = "Travel permit check — oi, I'm talking to you! Got your travel permit on you?",
          VoiceName = "voice/$Locale$/env/700002/7D2B8592"
        },
        [50000201] = {
          ContentFR = "{性别:Un Chasseur de Phoxène|Une Chasseuse de Phoxène} ? Je n’aurais jamais cru que l’un d’eux atteindrait cet endroit... Tu dois avoir, toi aussi, ce qu’il faut pour devenir {性别:un héros|une héroïne}.",
          DialogueId = 50000201,
          Duration = 4,
          GUID = "7D2B95FA",
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          VoiceName = "voice/$Locale$/env/700003/7D2B95FA"
        },
        [50000301] = {
          ContentFR = "Tout ça, c’est la faute de Grandet ! Qu’est-ce que je suis censé faire maintenant... Hein ? Qu’est-ce que tu regardes ? Je n’ai aucune mission pour toi aujourd’hui !",
          DialogueId = 50000301,
          Duration = 3,
          GUID = "7D2BA662",
          SpeakNpcId = 700004,
          Subtitle = "D*mn it, it's all Grandet's fault! What am I supposed to do now... Hm? What are you looking at? I've got no work for you today!",
          VoiceName = "voice/$Locale$/env/700004/7D2BA662"
        },
        [50000401] = {
          ContentFR = "Je suis... Annie ?",
          DialogueId = 50000401,
          Duration = 3,
          GUID = "7D2BB6CA",
          SpeakNpcId = 700032,
          Subtitle = "My name is... Annie?",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700032/7D2BB6CA"
        },
        [50000501] = {
          ContentFR = "Dès que je serai rétablie, je reprendrai la route pour une nouvelle aventure.",
          DialogueId = 50000501,
          Duration = 3,
          GUID = "7D2BC732",
          SpeakNpcId = 700005,
          Subtitle = "As soon as I'm back in form, I'm off on another adventure.",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BC732"
        },
        [50000601] = {
          ContentFR = "Qu’est-ce que je pourrais offrir à maman... ? Elle doit être impatiente de me revoir.",
          DialogueId = 50000601,
          Duration = 3,
          GUID = "7D2BD79A",
          SpeakNpcId = 700005,
          Subtitle = "What gift should I get for Elsa... She must've missed me terribly.",
          TalkActionId = {
            [1] = "700005:Think_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BD79A"
        },
        [50000701] = {
          ContentFR = "Annie... Annie !",
          DialogueId = 50000701,
          Duration = 3,
          GUID = "7D2BE802",
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          VoiceName = "voice/$Locale$/env/700006/7D2BE802"
        },
        [50000801] = {
          ContentFR = "Les fleurs sont magnifiques aujourd’hui... Je devrais en garder quelques-unes pour cette enfant.",
          DialogueId = 50000801,
          Duration = 3,
          GUID = "7D2BF86A",
          SpeakNpcId = 700007,
          Subtitle = "The flowers today are quite lovely. I should save a few for that kid.",
          TalkActionId = {
            [1] = "700007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700007/7D2BF86A"
        },
        [50000901] = {
          ContentFR = "Bonjour. Cette fleur s’accorde parfaitement avec votre tenue... Si elle était encore là, elle aurait dit la même chose.",
          DialogueId = 50000901,
          Duration = 5,
          GUID = "7D2C08D2",
          SpeakNpcId = 700203,
          Subtitle = "Good day, you look great with this flower... That kid would have said so, if she were still here.",
          VoiceName = "voice/$Locale$/env/700007/7D2C08D2"
        },
        [50001001] = {
          ContentFR = "Avec votre allure, ce serait un crime de ne pas porter mes créations.",
          DialogueId = 50001001,
          Duration = 3,
          GUID = "7D2C193A",
          SpeakNpcId = 700008,
          Subtitle = "Hello, gorgeous! I bet you'd be a vision in our apparel.",
          VoiceName = "voice/$Locale$/env/700008/7D2C193A"
        },
        [50001101] = {
          ContentFR = "Les meilleurs fruits de notre domaine ! Nulle part ailleurs vous ne trouverez un savoir-faire aussi raffiné !",
          DialogueId = 50001101,
          Duration = 3,
          GUID = "7D2C29A2",
          SpeakNpcId = 700009,
          Subtitle = "Try these fine fruits from our orchard — grown with unmatched cultivation techniques!",
          TalkActionId = {
            [1] = "700009:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700009/7D2C29A2"
        },
        [50001201] = {
          ContentFR = "Ah... O-Oh, je... euh...",
          DialogueId = 50001201,
          Duration = 2,
          GUID = "7D2C3A0A",
          SpeakNpcId = 700010,
          Subtitle = "Ah... whoa, I... um...",
          VoiceName = "voice/$Locale$/env/700010/7D2C3A0A"
        },
        [50001301] = {
          ContentFR = "Hmm... j’ai décidé, toi, tu seras le sujet d’expérience n° 1 !",
          DialogueId = 50001301,
          Duration = 3,
          GUID = "7D2C4A72",
          SpeakNpcId = 700011,
          Subtitle = "Hmm... I've made up my mind — hello, Test subject No. 1!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C4A72"
        },
        [50001401] = {
          ContentFR = "{nickname} ! Je suis content de te voir ! Moi, je continue à apprendre plein de nouvelles choses tous les jours. Alors... on continue à progresser ensemble, d’accord ?",
          DialogueId = 50001401,
          Duration = 4,
          GUID = "7D2C5ADA",
          SpeakNpcId = 700011,
          Subtitle = "lovely to see you again! I'm trying my best to learn new things every day, let's keep at it!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C5ADA"
        },
        [50001501] = {
          ContentFR = "Tu... Charon... un des miens...",
          DialogueId = 50001501,
          Duration = 6,
          GUID = "7D2C6B42",
          SpeakNpcId = 700012,
          Subtitle = "Are we... the same kind?",
          VoiceName = "voice/$Locale$/env/700012/7D2C6B42"
        },
        [50001601] = {
          ContentFR = "J’en ai vu, des choses qu’on préfère cacher dans l’ombre... Et les "démons" ne sont pas toujours ceux qu’on croit.\n... Parfois, entre les Solariens et les Charons, je ne sais plus lesquels sont les véritables démons.",
          DialogueId = 50001601,
          Duration = 4,
          GUID = "7D2C7BAA",
          SpeakNpcId = 700013,
          Subtitle = "I've witnessed deeds that daylight never sees, and not all are the work of \"demons\".\n...Sometimes, between humans and Charons, I can't tell which is the true demon.",
          VoiceName = "voice/$Locale$/env/700013/7D2C7BAA"
        },
        [50001701] = {
          ContentFR = "Pff ! Sale idiote ! On verra bien combien de temps encore tu pourras jouer les fortes têtes !",
          DialogueId = 50001701,
          Duration = 4,
          GUID = "7D2C8C12",
          SpeakNpcId = 700014,
          Subtitle = "Pah! Stupid hag! Let's see how long you can keep this charade up!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/env/700014/7D2C8C12"
        },
        [50001801] = {
          ContentFR = "Par tous les Cieux ! Comment un être aussi doux que moi a-t-il pu tomber victime d’un spectre voleur d’inspiration ?! Une telle injustice ferait pleurer même les cieux !",
          DialogueId = 50001801,
          Duration = 4,
          GUID = "7D2C9C7A",
          SpeakNpcId = 700015,
          Subtitle = "Good grief! Who'd have thought a gentle soul like myself would be beset by an inspiration-stealing spectre?! Such wretchedness would surely draw heaven's own tears!",
          VoiceName = "voice/$Locale$/env/700015/7D2C9C7A"
        },
        [50001901] = {
          ContentFR = "Quelle perte de temps ! Organiser des évènements aussi creux... On ferait mieux d’avoir une demi-journée de repos !",
          DialogueId = 50001901,
          Duration = 3,
          GUID = "7D2CACE2",
          SpeakNpcId = 700016,
          Subtitle = "What a drag! Who arranged these pointless events? I'd rather have half a day off!",
          VoiceName = "voice/$Locale$/env/700016/7D2CACE2"
        },
        [50002001] = {
          ContentFR = "« Sous la pluie, les fleurs de maman se sont fanées... Alors le ciel a semé de petites fleurs dans les flaques, pour lui présenter ses excuses. »",
          DialogueId = 50002001,
          Duration = 3,
          GUID = "7D2CBD4A",
          NextDialogue = 50002002,
          SpeakNpcId = 700017,
          Subtitle = ""The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles."",
          VoiceName = "voice/$Locale$/env/700017/7D2CBD4A"
        },
        [50002002] = {
          ContentFR = "Vous savez ? Ce petit poème s’intitule Excuses, et il a été écrit par l’un de mes élèves... il n’a que six ans.",
          DialogueId = 50002002,
          Duration = 3,
          GUID = "7D2CBD74",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called "Apology", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700017/7D2CBD74"
        },
        [50002101] = {
          ContentFR = "Les pierres jetées contre les lois de la nature finissent toujours par retomber sur celui qui les lance.",
          DialogueId = 50002101,
          Duration = 3,
          GUID = "7D2CCDB2",
          SpeakNpcId = 700018,
          Subtitle = "The rocks cast against the laws of nature will inevitably fall back on one's own head.",
          TalkActionId = {
            [1] = "700018:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/env/700018/7D2CCDB2"
        },
        [50002201] = {
          ContentFR = "Où a-t-il bien pu disparaître...",
          DialogueId = 50002201,
          Duration = 3,
          GUID = "7D2CDE1A",
          SpeakNpcId = 700019,
          Subtitle = "Where could he have gone off to...",
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700019/7D2CDE1A"
        },
        [50002301] = {
          ContentFR = "J’espère que la crème de champignons préparée ce soir réchauffera un peu le cœur de Madame.",
          DialogueId = 50002301,
          Duration = 4,
          GUID = "7D2CEE82",
          SpeakNpcId = 700020,
          Subtitle = "I hope tonight's creamy mushroom soup will bring some comfort to her ladyship.",
          TalkActionId = {
            [1] = "700020:Agree"
          },
          VoiceName = "voice/$Locale$/env/700020/7D2CEE82"
        },
        [50002401] = {
          ContentFR = "Pauvre femme... Elle a complètement perdu la tête.",
          DialogueId = 50002401,
          Duration = 3,
          GUID = "7D2CFEEA",
          NextDialogue = 50002402,
          SpeakNpcId = 700023,
          Subtitle = "Poor thing, having lost her mind like that.",
          VoiceName = "voice/$Locale$/env/700023/7D2CFEEA"
        },
        [50002402] = {
          ContentFR = "Pas étonnant que sa fille ait fini par partir.",
          DialogueId = 50002402,
          Duration = 3,
          GUID = "7D2CFF14",
          SpeakNpcId = 700024,
          Subtitle = "No wonder her daughter had left.",
          VoiceName = "voice/$Locale$/env/700024/7D2CFF14"
        },
        [50002501] = {
          ContentFR = "Toutes les poubelles de la cité sont sous ma garde. Et crois-moi, on y trouve de tout ! Des bottes en daim portées à peine deux fois, des lys encore frais... et même les fragments de rêves brisés de quelqu’un.",
          DialogueId = 50002501,
          Duration = 3,
          GUID = "7D2D0F52",
          SpeakNpcId = 700115,
          Subtitle = "I oversee all the rubbish bins around the city, and oh, the treasures to be found in each of them! Nearly new deerskin boots, still-fresh lilies, and the fragments of someone's shattered dreams...",
          TalkActionId = {
            [1] = "700115:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700022/7D2D0F52"
        },
        [50002601] = {
          ContentFR = "Le train pour la prochaine station va partir. Billets en vente ici — Quoi ? Pas d’argent ? Alors cessez de rêver et dégagez d’ici !",
          DialogueId = 50002601,
          Duration = 5,
          GUID = "7D2D0F53",
          SpeakNpcId = 700021,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700021:Confident_Start"
          }
        },
        [50002701] = {
          ContentFR = "La canalisation n° 13 est en réparation. Bon sang... il y a bien trop de rats là-dedans.",
          DialogueId = 50002701,
          Duration = 4,
          GUID = "7D2D3022",
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700069/7D2D3022"
        },
        [50002801] = {
          ContentFR = "Dégage, sale Charon !",
          DialogueId = 50002801,
          DialoguePanelType = "{type:Bubble;style:ExcitedBubble}",
          Duration = 3,
          GUID = "7D2D408A",
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!",
          VoiceName = "voice/$Locale$/env/700068/7D2D408A"
        },
        [50002901] = {
          ContentFR = "Argh... pourquoi ces taches de sang ne veulent-elles pas partir ?",
          DialogueId = 50002901,
          Duration = 3,
          GUID = "7D2D50F2",
          SpeakNpcId = 700067,
          Subtitle = "Ugh... why won't this bloodstain come off?",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700067/7D2D50F2"
        },
        [50003001] = {
          Content = "凶猛的狼咆哮着 撕咬着狡猾的狗",
          DialogueId = 50003001,
          Duration = 3,
          GUID = "7D2D615A",
          NextDialogue = 50003002,
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D615A"
        },
        [50003002] = {
          Content = "狡猾的狗呜咽着 啃食着腐朽的肉",
          DialogueId = 50003002,
          Duration = 3,
          GUID = "7D2D6184",
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D6184"
        },
        [50003101] = {
          Content = "您也喜欢这些百合吗？",
          DialogueId = 50003101,
          Duration = 3,
          GUID = "7D2D71C2",
          SpeakNpcId = 700072,
          TalkActionId = {
            [1] = "700072:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700072/7D2D71C2"
        },
        [50003201] = {
          ContentFR = "« Hors de la ville, les Souillés nous dévorent, en ville, les fermiers nous tondent sans répit. Les chiens festoient de pain blanc, les moutons Charon broutent l’herbe jaunie... »",
          DialogueId = 50003201,
          Duration = 3,
          GUID = "7D2D822A",
          NextDialogue = 50003202,
          SpeakNpcId = 700073,
          Subtitle = "♪ "Monsters beyond the walls feast on our flesh; the ones within shear our fleece. While the hounds dine on fine white loaves; we lowly sheep are content with chewing grass..."",
          TalkActionId = {
            [1] = "700073:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700073/7D2D822A"
        },
        [50003202] = {
          ContentFR = "Bon sang ! Où as-tu appris cette chanson... ? Un jour, elle va nous faire exécuter tous les deux !",
          DialogueId = 50003202,
          Duration = 3,
          GUID = "7D2D8254",
          NextDialogue = 50003203,
          SpeakNpcId = 700074,
          Subtitle = "Whoa, whoa! Where did you learn that ditty... you're going to get us both killed one of these days!",
          TalkActionId = {
            [1] = "700074:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D8254"
        },
        [50003203] = {
          ContentFR = "Oh ! {性别:Cher client|Chère cliente}, désirez-vous acheter quelque chose ? Tout ici est fait main par mes soins, qualité irréprochable garantie !",
          DialogueId = 50003203,
          Duration = 3,
          GUID = "7D2D827E",
          SpeakNpcId = 700074,
          Subtitle = "Ah, welcome! What can I get you, dear customer? Each piece here is crafted by my own hands, top-notch quality guaranteed!",
          TalkActionId = {
            [1] = "700074:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D827E"
        },
        [50003301] = {
          Content = "真好呀！真好！生活这么美好，怎么大家都愁眉苦脸的呢？我们生活在一个幸福的世界里，多么幸运！",
          DialogueId = 50003301,
          Duration = 3,
          GUID = "7D2D9292",
          SpeakNpcId = 700075,
          TalkActionId = {
            [1] = "700075:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/env/700075/7D2D9292"
        },
        [50003401] = {
          Content = "呜呜……爸爸妈妈，你们在哪里……我好想你们……",
          DialogueId = 50003401,
          Duration = 3,
          GUID = "7D2DA2FA",
          SpeakNpcId = 700076,
          TalkActionId = {
            [1] = "700076:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700076/7D2DA2FA"
        },
        [50003501] = {
          Content = "这是我在广场那边买的纪念品！他们说来冰湖城绝不能错过……",
          DialogueId = 50003501,
          Duration = 3,
          GUID = "7D2DB362",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2DB362"
        },
        [50003601] = {
          Content = "求您了……再多给两个子儿吧，只给这个数，我连过冬的炭火都买不起啊……",
          DialogueId = 50003601,
          Duration = 3,
          GUID = "7D2DC3CA",
          NextDialogue = 50003602,
          SpeakNpcId = 700078,
          TalkActionId = {
            [1] = "700078:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700078/7D2DC3CA"
        },
        [50003602] = {
          Content = "子爵大人要最好的皮料！要从最健壮的头狼身上剥下的顶级货！懂了吗蠢蛋！你的这些残次品只配给乞丐穿！",
          DialogueId = 50003602,
          Duration = 3,
          GUID = "7D2DC3F4",
          SpeakNpcId = 700079,
          TalkActionId = {
            [1] = "700079:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700079/7D2DC3F4"
        },
        [50003701] = {
          ContentFR = "Pop-corn ! Cigarettes ! Breuvages forts ! Vous avez perdu quelque chose ? J’ai rien vu, moi ! Je le jure !",
          DialogueId = 50003701,
          Duration = 4,
          GUID = "7D2DD432",
          SpeakNpcId = 700080,
          Subtitle = "Popcorn! Cigs! Booze! Lost something, you say? Didn't see it! I swear!",
          VoiceName = "voice/$Locale$/env/700080/7D2DD432"
        },
        [50003801] = {
          ContentFR = "Si chaque Charon pouvait vivre aussi longtemps que moi... je ne serais pas aussi seule.",
          DialogueId = 50003801,
          Duration = 7,
          GUID = "7D2DE49A",
          SpeakNpcId = 700081,
          Subtitle = "If every Charon could live as long as I have, I wouldn't feel so alone.",
          VoiceName = "voice/$Locale$/env/700081/7D2DE49A"
        },
        [50003901] = {
          ContentFR = "Ne vous fiez pas à mon bras cassé, je peux encore transporter des marchandises. Qu’est-ce qu’il vous faut ?",
          DialogueId = 50003901,
          Duration = 3,
          GUID = "7D2DF502",
          SpeakNpcId = 700082,
          TalkActionId = {
            [1] = "700082:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700082/7D2DF502"
        },
        [50004001] = {
          ContentFR = "... (Lunoeggy griffonne rapidement « Salut » sur sa petite ardoise.)",
          DialogueId = 50004001,
          Duration = 3,
          GUID = "7D2E056A",
          SpeakNpcId = 900008,
          VoiceName = "voice/$Locale$/env/900008/7D2E056A"
        },
        [50004101] = {
          ContentFR = "J’ai accepté une nouvelle mission récemment. Comme d’habitude : 80 pour toi, 20 pour moi. On part dès que j’ai fini cette bouteille, ça te va ?",
          DialogueId = 50004101,
          Duration = 3,
          GUID = "7D2E15D2",
          SpeakNpcId = 200015,
          TalkActionId = {
            [1] = "200015:Agree"
          },
          VoiceName = "voice/$Locale$/env/200015/7D2E15D2"
        },
        [50004201] = {
          ContentFR = "Envie d’un verre ?",
          DialogueId = 50004201,
          Duration = 3,
          GUID = "7D2E263A",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_01"
        },
        [50004301] = {
          ContentFR = "« ♪ Rossignol aux ailes brisées, ne pleure plus... »",
          DialogueId = 50004301,
          Duration = 3,
          GUID = "7D2E36A2",
          NextDialogue = 50004302,
          SpeakNpcId = 700142,
          TalkActionId = {
            [1] = "700142:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36A2"
        },
        [50004302] = {
          ContentFR = "« ♪ Cher petit rossignol, ne t’endors pas pour toujours... »",
          DialogueId = 50004302,
          Duration = 3,
          GUID = "7D2E36CC",
          SpeakNpcId = 700142,
          TalkActionId = {
            [1] = "700142:Explain02_End"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36CC"
        },
        [50004401] = {
          ContentFR = "Va... va-t’en... si tu n’achètes pas de Phoxène, ne reste pas ici... et n’attire pas ces foutus soldats sur moi...",
          DialogueId = 50004401,
          Duration = 4,
          GUID = "7D2E470A",
          SpeakNpcId = 700113,
          TalkActionId = {
            [1] = "700113:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700113/7D2E470A"
        },
        [50004501] = {
          ContentFR = "Danse ! Allez, danse ! La vie n’a pas de sens, alors balance toutes tes préoccupations à la poubelle et danse avec moi jusqu’au matin !",
          DialogueId = 50004501,
          Duration = 3,
          GUID = "7D2E5772",
          SpeakNpcId = 700129,
          VoiceName = "voice/$Locale$/env/700129/7D2E5772"
        },
        [50004601] = {
          ContentFR = "Monsieur... L’allocation impériale de ce mois-ci... Ah, elle n’a toujours pas été approuvée... kof kof... Ce n’est rien, je vais avancer l’argent de ma poche... Désolé pour le dérangement...",
          DialogueId = 50004601,
          Duration = 4,
          GUID = "7D2E67DA",
          SpeakNpcId = 700070,
          TalkActionId = {
            [1] = "700070:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700070/7D2E67DA"
        },
        [50004701] = {
          ContentFR = "Des infos sur des trésors... à ne manquer sous aucun prétexte !",
          DialogueId = 50004701,
          Duration = 3,
          GUID = "7D2E7842",
          SpeakNpcId = 700048,
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E7842"
        },
        [50004801] = {
          ContentFR = "L’association des pêcheurs recrute ! Viens jeter l’hameçon avec nous !",
          DialogueId = 50004801,
          Duration = 3,
          GUID = "7D2E88AA",
          SpeakNpcId = 700048,
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E88AA"
        },
        [50004901] = {
          ContentFR = "Tant que c’est bien désinfecté, ça fera un plat savoureux !",
          DialogueId = 50004901,
          Duration = 3,
          GUID = "7D2E9912",
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700116/7D2E9912"
        },
        [50005001] = {
          ContentFR = "Pff. Une nouvelle tête.",
          DialogueId = 50005001,
          Duration = 3,
          GUID = "7D2EA97A",
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EA97A"
        },
        [50005101] = {
          ContentFR = "Qu’est-ce que tu veux ?",
          DialogueId = 50005101,
          Duration = 3,
          GUID = "7D2EB9E2",
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Agree"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EB9E2"
        },
        [50005201] = {
          ContentFR = "Être fidèle à ses désirs... fidèle à ses désirs... fidèle à ses désirs... Mais qu’est-ce que ça veut dire, exactement, être fidèle à ses désirs...",
          DialogueId = 50005201,
          Duration = 4,
          GUID = "7D2ECA4A",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2ECA4A"
        },
        [50005301] = {
          Content = "开往下一站的列车即将出发，如有购票需求请您在此处办理——什么？没钱？那就一边儿去！",
          DialogueId = 50005301,
          Duration = 4,
          GUID = "7D2D1FBA",
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700147:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700021/7D2D1FBA"
        },
        [50005401] = {
          ContentFR = "Hahaha ! Elle court plus vite qu’une souris, dis donc !",
          DialogueId = 50005401,
          Duration = 3,
          GUID = "7D2EEB1A",
          SpeakNpcId = 700089
        },
        [50005501] = {
          ContentFR = "Eh, sale Charon, t’attends quoi ? Va donc rattraper ton petit morveux !",
          DialogueId = 50005501,
          Duration = 3,
          GUID = "7D2EFB82",
          SpeakNpcId = 700088,
          TalkActionId = {
            [1] = "700088:Confident_Start"
          }
        },
        [50005601] = {
          ContentFR = "Peut-être qu’il faudrait une planche un peu plus grande, non... ?",
          DialogueId = 50005601,
          Duration = 3,
          GUID = "7D2F0BEA",
          SpeakNpcId = 700143
        },
        [50100101] = {
          Content = "针头线脑，香脂香囊，走过路过不要错过——",
          DialogueId = 50100101,
          GUID = "7D6B9BD2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6B9BD2"
        },
        [50100201] = {
          Content = "来看看华胥特色纪念品喽，给亲朋好友带一份吧！",
          DialogueId = 50100201,
          GUID = "7D6BAC3A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BAC3A"
        },
        [50100301] = {
          Content = "海的那边……是什么样子呢？",
          DialogueId = 50100301,
          GUID = "7D6BBCA2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBCA2"
        },
        [50100311] = {
          Content = "工头昨天心情好，给我们都发了赏钱！",
          DialogueId = 50100311,
          GUID = "7D6BBE46",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE46"
        },
        [50100312] = {
          Content = "那有什么！出船之前，老板来请吃了茶呢！",
          DialogueId = 50100312,
          GUID = "7D6BBE70",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE70"
        },
        [50100401] = {
          Content = "腰酸背痛啊，抽空得找人好好按按……",
          DialogueId = 50100401,
          GUID = "7D6BCD0A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BCD0A"
        },
        [50100501] = {
          Content = "这箱货物贵重，先包上一层软垫再搬吧。",
          DialogueId = 50100501,
          GUID = "7D6BDD72",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BDD72"
        },
        [50100601] = {
          Content = "这些木簪花钿，好看是好看，可我不会用呢。",
          DialogueId = 50100601,
          GUID = "7D6BEDDA",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BEDDA"
        },
        [50100701] = {
          Content = "香料丝绸茶叶油膏器皿……种类也太多了！",
          DialogueId = 50100701,
          GUID = "7D6BFE42",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BFE42"
        },
        [50100801] = {
          Content = "沉月香卖完了？怎么可能，昨天才进的货！",
          DialogueId = 50100801,
          GUID = "7D6C0EAA",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C0EAA"
        },
        [50100901] = {
          Content = "点数清，码数齐，今日开市不慌矣~",
          DialogueId = 50100901,
          GUID = "7D6C1F12",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C1F12"
        },
        [50101001] = {
          Content = "不愧是织星客的故乡，华胥果真名不虚传。",
          DialogueId = 50101001,
          GUID = "7D6C2F7A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C2F7A"
        },
        [50101101] = {
          Content = "山清水秀，在此品一盏香茗，妙趣横生呐~",
          DialogueId = 50101101,
          GUID = "7D6C3FE2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C3FE2"
        },
        [50101201] = {
          Content = "说好打赌输了就欠我三根糖葫芦，你不许耍赖。",
          DialogueId = 50101201,
          GUID = "7D6C504A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C504A"
        },
        [50101202] = {
          Content = "放心，明日阿娘给了零花钱就来请你！",
          DialogueId = 50101202,
          GUID = "7D6C5074",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C5074"
        },
        [50101203] = {
          Content = "浮星埠是一年比一年热闹了啊……",
          DialogueId = 50101203,
          GUID = "7D6C509E",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C509E"
        },
        [50101301] = {
          Content = "诶呀！撞得我发髻都散啦！",
          DialogueId = 50101301,
          GUID = "7D6C60B2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C60B2"
        },
        [50101401] = {
          Content = "嘿！小友走路别分心，撞到人可不好！",
          DialogueId = 50101401,
          GUID = "7D6C711A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C711A"
        },
        [50101501] = {
          Content = "绸缎齐整，杂粮归铺，心才安……",
          DialogueId = 50101501,
          GUID = "7D6C8182",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C8182"
        },
        [50101601] = {
          Content = "祖传山参，百年阿胶，价优物美待君选！",
          DialogueId = 50101601,
          GUID = "7D6C91EA",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C91EA"
        },
        [50101701] = {
          Content = "好东西不贱卖哈，总有眼尖识货人！",
          DialogueId = 50101701,
          GUID = "7D6CA252",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CA252"
        },
        [50101801] = {
          Content = "瓷器娇贵，客人轻拿轻放~",
          DialogueId = 50101801,
          GUID = "7D6CB2BA",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CB2BA"
        },
        [50101901] = {
          Content = "再便宜点，我直接拿了。",
          DialogueId = 50101901,
          GUID = "7D6CC322",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CC322"
        },
        [50102001] = {
          Content = "瓶子看着精致……没什么瑕疵吧？",
          DialogueId = 50102001,
          GUID = "7D6CD38A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CD38A"
        },
        [50102101] = {
          Content = "称点桂花糕，我带回去给娘子吃~",
          DialogueId = 50102101,
          GUID = "7D6CE3F2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CE3F2"
        },
        [50102201] = {
          Content = "这匹布料柔软顺滑，做成里衣定是舒适。",
          DialogueId = 50102201,
          GUID = "7D6CF45A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CF45A"
        },
        [50102301] = {
          Content = "神君鉴上，我雪霁立誓一生不负初晴，如……",
          DialogueId = 50102301,
          GUID = "7D6D04C2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D04C2"
        },
        [50102401] = {
          Content = "嘘！后面的话不许你说！我都明白……",
          DialogueId = 50102401,
          GUID = "7D6D152A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D152A"
        },
        [50102501] = {
          Content = "白龙神君保佑此次出航平安无虞！",
          DialogueId = 50102501,
          GUID = "7D6D2592",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D2592"
        },
        [50102601] = {
          Content = "小女愿家中长辈身体康健，福寿绵长。",
          DialogueId = 50102601,
          GUID = "7D6D35FA",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D35FA"
        },
        [50102701] = {
          Content = "明先生最近可是在哪发了大财？",
          DialogueId = 50102701,
          GUID = "7D6D4662",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D4662"
        },
        [50102702] = {
          Content = "侥幸而已！还是江先生的生意更稳当。",
          DialogueId = 50102702,
          GUID = "7D6D468C",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D468C"
        },
        [50102801] = {
          Content = "下次出航得往赫墨北边再走一走……",
          DialogueId = 50102801,
          GUID = "7D6D56CA",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D56CA"
        },
        [50102901] = {
          Content = "明明已经让了极大的利，为何销量还是……",
          DialogueId = 50102901,
          GUID = "7D6D6732",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D6732"
        },
        [50103001] = {
          Content = "我才加入织星客，凡事劳请前辈多指点！",
          DialogueId = 50103001,
          GUID = "7D6D779A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D779A"
        },
        [50103002] = {
          Content = "客气了，若有问题便尽管问吧。",
          DialogueId = 50103002,
          GUID = "7D6D77C4",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77C4"
        },
        [50103003] = {
          Content = "您说我是要继续追资还是见好就收呢？",
          DialogueId = 50103003,
          GUID = "7D6D77EE",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77EE"
        },
        [50103101] = {
          Content = "新来的哥儿，皮子肥不肥？",
          DialogueId = 50103101,
          GUID = "7D6D8802",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D8802"
        },
        [50103201] = {
          Content = "穷地方来的，没挂多少老居米子。",
          DialogueId = 50103201,
          GUID = "7D6D986A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D986A"
        },
        [50103301] = {
          Content = "客人来看看？爬山头来的正经古董。",
          DialogueId = 50103301,
          GUID = "7D6DA8D2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DA8D2"
        },
        [50103401] = {
          Content = "以前都只做洋庄，好不容易才运回国的！",
          DialogueId = 50103401,
          GUID = "7D6DB93A",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DB93A"
        },
        [50103501] = {
          Content = "风里有太皓的意志，只需静下心感受……",
          DialogueId = 50103501,
          GUID = "7D6DC9A2",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DC9A2"
        },
        [50103601] = {
          Content = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
          DialogueId = 50103601,
          GUID = "7D6DDA0A",
          SpeakNpcId = 701039,
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DDA0A"
        },
        [50103701] = {
          Content = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
          DialogueId = 50103701,
          GUID = "7D6DEA72",
          SpeakNpcId = 701040,
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DEA72"
        },
        [50103801] = {
          Content = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
          DialogueId = 50103801,
          GUID = "7D6DFADA",
          SpeakNpcId = 701041,
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DFADA"
        }
      }
    end
  },
  {
