          DialogueId = 51000102,
          GUID = "7FAC643C",
          NextDialogue = 51000103
        },
        [51000103] = {
          ContentFR = "Tiens, bois donc cette soupe ! C’est une recette de ma ville natale, Rougerive. Je parie que tu n’as jamais goûté à ça.",
