          GUID = "7FAC64E4",
          NextDialogue = 51000108,
          SpeakNpcId = 700020
        },
        [51000107] = {
          ContentFR = "{性别:Petit ingrat|Petite ingrate} ! Tu ne sais pas reconnaître les bonnes choses quand elles te sont offertes.",
          DialogueId = 51000107,
          GUID = "7FAC650E",
          NextDialogue = 51000108,
          SpeakNpcId = 700020
        },
        [51000108] = {
