        },
        [51000204] = {
          ContentFR = "Sans attendre ton avis, elle pose devant toi un bol fumant. Tu as presque l’impression qu’elle va t’attraper par la nuque pour t’obliger à avaler la première cuillerée—",
          DialogueId = 51000204,
          GUID = "7FAC74F8"
        },
        [51000205] = {
          ContentFR = "La richesse du bouillon crémeux et parfumé aux champignons glisse dans ta gorge, apportant une chaleur réconfortante.",
          DialogueId = 51000205,
          GUID = "7FAC7522",
          NextDialogue = 51000206
        },
        [51000206] = {
          ContentFR = "Alors ? Je ne t’ai pas menti, hein ! Tante Sally ne déçoit jamais, haha !",
          DialogueId = 51000206,
          GUID = "7FAC754C",
          NextDialogue = 51000208,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51000207] = {
          ContentFR = "{性别:Petit ingrat|Petite ingrate} ! Tu ne sais pas reconnaître les bonnes choses quand elles te sont offertes.",
          DialogueId = 51000207,
          GUID = "7FAC7576",
          NextDialogue = 51000208,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51000208] = {
          ContentFR = "Sa Seigneurie boit ma soupe depuis qu’elle est toute jeune fille. Voilà bientôt quarante ans que ça dure.",
          DialogueId = 51000208,
          GUID = "7FAC75A0",
          NextDialogue = 51000209,
          SpeakNpcId = 700020
        },
        [51000209] = {
          ContentFR = "... Hélas... Dame Hilin... Je me demande si sa santé s’améliorera un jour.",
          DialogueId = 51000209,
          GUID = "7FAC75CA",
          NextDialogue = 51000210,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51000210] = {
          ContentFR = "Le sourire qui illuminait ses yeux se fane doucement, remplacé par l’éclat humide des larmes.",
          DialogueId = 51000210,
          GUID = "7FAC75F4",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51000301] = {
          ContentFR = "Où a-t-il bien pu disparaître...",
          DialogueId = 51000301,
          GUID = "7FAC84E2",
          NextDialogue = 51000302,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          }
        },
        [51000302] = {
          ContentFR = "Son regard mélancolique se perd au loin. Elle ne réagit pas à ton approche.",
          DialogueId = 51000302,
          GUID = "7FAC850C",
          NextOptions = {
            [1] = 510003021,
            [2] = 510003022,
            [3] = 510003023
          },
          bForbidSkipOptions = true
        },
        [51000303] = {
          ContentFR = "Les étoffes sont raffinées, la coupe élégante : un signe d’ancienne opulence.",
          DialogueId = 51000303,
          GUID = "7FAC8536",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000304] = {
          ContentFR = "Ses yeux restent fixés sur les portes de la cité, comme si elle attendait un retour depuis longtemps différé.",
          DialogueId = 51000304,
          GUID = "7FAC8560",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000305] = {
          ContentFR = "Ses prunelles vieillies débordent de tristesse, témoignant d’une attente longue et vaine.",
          DialogueId = 51000305,
          GUID = "7FAC858A",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000306] = {
          ContentFR = "Elle te jette un bref regard, puis détourne la tête, indifférente à tes propos.",
          DialogueId = 51000306,
          GUID = "7FAC85B4"
        },
        [51000307] = {
          ContentFR = "... Toi... qui es-tu ?",
          DialogueId = 51000307,
          GUID = "7FAC85DE",
          NextDialogue = 51000308,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_End"
          }
        },
        [51000308] = {
          ContentFR = "Je ne t’ai jamais vu. Viens-tu d’un village voisin ?",
          DialogueId = 51000308,
          GUID = "7FAC8608",
          NextDialogue = 51000309,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51000309] = {
          ContentFR = "As-tu entendu parler d’un Charon nommé Hamel Dickinson ? Il est né ici, à Givrelac. Quand je l’ai connu, il avait dix-neuf ans, des cheveux châtain clair... Mais aujourd’hui, il aurait mon âge.",
          DialogueId = 51000309,
          GUID = "7FAC8632",
          NextDialogue = 51000310,
          SpeakNpcId = 700019
        },
        [51000310] = {
          ContentFR = "J’ai quitté Givrelac il y a quarante ans. Depuis, je n’ai plus jamais eu de nouvelles de lui. Je suis revenue... mais nul ne semble se souvenir de lui.",
          DialogueId = 51000310,
          GUID = "7FAC865C",
          NextDialogue = 51000311,
          SpeakNpcId = 700019
        },
        [51000311] = {
          ContentFR = "Il est né ici. Même s’il a quitté la cité, il n’a pas dû partir bien loin. Dis-moi, {性别:jeune homme|jeune femme}... l’as-tu rencontré ?",
          DialogueId = 51000311,
          GUID = "7FAC8686",
          NextOptions = {
            [1] = 510003111
          },
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51000312] = {
          ContentFR = "... Je vois.",
          DialogueId = 51000312,
          GUID = "7FAC86B0",
          NextDialogue = 51000313,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Agree"
          }
        },
        [51000313] = {
          ContentFR = "Mais si un jour tu le croises, pourrais-tu lui transmettre un message ?",
          DialogueId = 51000313,
          GUID = "7FAC86DA",
          NextDialogue = 51000314,
          SpeakNpcId = 700019
        },
        [51000314] = {
          ContentFR = "« Hilin est revenue à Givrelac. Elle t’attend toujours. Elle attend la raison d’un retard de quarante ans. »",
          DialogueId = 51000314,
          GUID = "7FAC8704",
          NextDialogue = 51000315,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_Start"
          }
        },
        [51000315] = {
          ContentFR = "Et si tu ne le trouves que l’an prochain, demande-lui pourquoi il a quarante et un ans de retard. L’année suivante, quarante-deux... Je compte les années, une par une.",
          DialogueId = 51000315,
          GUID = "7FAC872E",
          NextDialogue = 51000316,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_End"
          }
        },
        [51000316] = {
          ContentFR = "Dame Hilin paraît accablée. C’est sûrement la femme que Sally évoquait. Peut-être existe-t-il un moyen de les aider.",
          DialogueId = 51000316,
          GUID = "7FAC8758"
        },
        [51000401] = {
          ContentFR = "Annie... Annie !",
          DialogueId = 51000401,
          GUID = "7FAC954A",
          NextDialogue = 51000402,
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000402] = {
          ContentFR = "Ah... te revoilà, ma précieuse fille !",
          DialogueId = 51000402,
          GUID = "7FAC9574",
          NextDialogue = 51000403,
          SpeakNpcId = 700006,
          Subtitle = "Ah, you're back, my dear daughter!"
        },
        [51000403] = {
          ContentFR = "Une femme bloque ton passage. Ses yeux secs et vides scrutent ton visage, comme si elle s’efforçait de retrouver quelque chose en toi.",
          DialogueId = 51000403,
          GUID = "7FAC959E",
          NextOptions = {
            [1] = 510004031,
            [2] = 510004032,
            [3] = 510004033
          },
          Subtitle = "(A woman stops you. Her dry, vacant eyes roam over you, as if desperately searching for something inside of you.)",
          bForbidSkipOptions = true
        },
        [51000404] = {
          ContentFR = "Je savais que tu reviendrais ! Comment as-tu pu m’abandonner ainsi !",
          DialogueId = 51000404,
          GUID = "7FAC95C8",
          NextDialogue = 51000493,
          SpeakNpcId = 700006,
          Subtitle = "I knew you'd come back! How could you leave me like that!",
          TalkActionId = {
            [1] = "700006:Shock_End"
          }
        },
        [51000405] = {
          ContentFR = "La femme est perdue dans son monde, rien de ce que tu dis ne semble l’atteindre.",
          DialogueId = 51000405,
          GUID = "7FAC95F2",
          Subtitle = "(The woman is lost in her own world, and no matter what you say, it's futile.)"
        },
        [51000406] = {
          ContentFR = "Tu dis que tu n’es pas Annie...",
          DialogueId = 51000406,
          GUID = "7FAC961C",
          NextDialogue = 51000407,
          SpeakNpcId = 700006,
          Subtitle = "You just said you're not Annie...",
          TalkActionId = {
            [1] = "700006:Disagree"
          }
        },
        [51000407] = {
          ContentFR = "C’est ma faute ! Tout est de ma faute ! C’est moi qui ai poussé Annie à partir... Elle est ma seule fille, nous n’avons toujours été que toutes les deux. Si tu m’aides à la retrouver, je ferai tout ce que tu voudras !",
          DialogueId = 51000407,
          GUID = "7FAC9646",
          NextOptions = {
            [1] = 510004071,
            [2] = 51000002
          },
          SpeakNpcId = 700006,
          Subtitle = "It's all my fault! I pushed Annie away... She's all I have, it's been just us two all along. I'll do anything for you if you find my baby!",
          TalkActionId = {
            [1] = "700006:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51000408] = {
          ContentFR = "Merci... merci infiniment...",
          DialogueId = 51000408,
          GUID = "7FAC9670",
          SpeakNpcId = 700006,
          Subtitle = "Thank you. Thank you so much...",
          TalkActionId = {
            [1] = "700006:Explain02_End"
          }
        },
        [51000409] = {
          ContentFR = "Je compte sur toi...",
          DialogueId = 51000409,
          GUID = "7FAC969A",
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000420] = {
          ContentFR = "Bonjour... vous n’auriez pas vu... ?",
          DialogueId = 51000420,
          GUID = "7FAC969B",
          NextDialogue = 51000421,
          SpeakNpcId = 100001
        },
        [51000421] = {
          ContentFR = "Oui, j’ai tout vu. Cette femme vous a pris pour sa fille, n’est-ce pas ? Je te conseille de ne pas trop t’approcher. Elle... enfin, tu vois...",
          DialogueId = 51000421,
          GUID = "7FAC969C",
          NextDialogue = 51000422,
          SpeakNpcId = 700232
        },
        [51000422] = {
          ContentFR = "La femme touche sa tête d’un geste significatif.",
          DialogueId = 51000422,
          GUID = "7FAC969D",
          NextDialogue = 51000423
        },
        [51000423] = {
          ContentFR = "Elle a un problème mental. Elle est là depuis plus d’un an.",
          DialogueId = 51000423,
          GUID = "7FAC969E",
          NextDialogue = 51000424,
          SpeakNpcId = 700232
        },
        [51000424] = {
          ContentFR = "Ce n’est pas très gentil. Elle a sûrement perdu sa fille et sa douleur l’a rendue ainsi.",
          DialogueId = 51000424,
          GUID = "7FAC969F",
          NextDialogue = 51000425,
          SpeakNpcId = 100001
        },
        [51000425] = {
          ContentFR = "Peut-être... Mais la fille est partie depuis longtemps. Si elle était encore là, quelqu’un l’aurait retrouvée.",
          DialogueId = 51000425,
          GUID = "7FAC96A0",
          NextDialogue = 51000426,
          SpeakNpcId = 700232
        },
        [51000426] = {
          ContentFR = "Merci... mais j’ai promis de l’aider, alors je vais chercher quand même.",
          DialogueId = 51000426,
          GUID = "7FAC96A1",
          SpeakNpcId = 100001
        },
        [51000427] = {
          ContentFR = "Une fille disparue ? Je ne sais pas trop... mais hier, j’ai vu une petite près des portes de la cité.",
          DialogueId = 51000427,
          GUID = "7FAC96A2",
          NextDialogue = 51000428,
          SpeakNpcId = 700233
        },
        [51000428] = {
          ContentFR = "Elle avait l’air bizarre. Peut-être que c’est elle, ou pas... difficile à dire.",
          DialogueId = 51000428,
          GUID = "7FAC96A3",
          SpeakNpcId = 700233
        },
        [51000429] = {
          ContentFR = "La fille de l’autre côté de la rue... Il paraît qu’elle a été sauvée par un médecin, non ?",
          DialogueId = 51000429,
          GUID = "7FAC96A4",
          NextDialogue = 51000430,
          SpeakNpcId = 100001
        },
        [51000430] = {
          ContentFR = "Tu parles de la petite un peu perdue dans sa tête ? Oui. Une certaine Docteur Eleanor l’a amenée ici, il y a quelques jours.",
          DialogueId = 51000430,
          GUID = "7FAC96A5",
          NextDialogue = 51000431,
          SpeakNpcId = 700234
        },
        [51000431] = {
          ContentFR = "Savez-vous où je peux trouver cette Docteur Eleanor ?",
          DialogueId = 51000431,
          GUID = "7FAC96A6",
          NextDialogue = 51000432,
          SpeakNpcId = 100001
        },
        [51000432] = {
          ContentFR = "Elle n’est pas d’ici. C’est une médecin itinérante. Pas de chance... Je l’ai vue quitter la cité ce matin. Si tu prends la route du Lac du Deuil, tu la rattraperas peut-être.",
          DialogueId = 51000432,
          GUID = "7FAC96A7",
          SpeakNpcId = 700234
        },
        [51000433] = {
          ContentFR = "Merci, noble âme. Sans vous, j’étais perdue... Les malades de Vivar m’attendent encore.",
          DialogueId = 51000433,
          GUID = "7FAC96A8",
          NextDialogue = 51000434,
          SpeakNpcId = 700235
        },
        [51000434] = {
          ContentFR = "Vous êtes médecin ? Seriez-vous la Docteur Eleanor ?",
          DialogueId = 51000434,
          GUID = "7FAC96A9",
          NextDialogue = 51000435,
          SpeakNpcId = 100001
        },
        [51000435] = {
          ContentFR = "C’est bien moi... Vous me cherchiez ?",
          DialogueId = 51000435,
          GUID = "7FAC96AA",
          NextDialogue = 51000436,
          SpeakNpcId = 700235
        },
        [51000436] = {
          ContentFR = "On m’a dit que vous aviez secouru une jeune fille, dans les montagnes au nord.",
          DialogueId = 51000436,
          GUID = "7FAC96AB",
          NextDialogue = 51000437,
          SpeakNpcId = 100001
        },
        [51000437] = {
          ContentFR = "Ah, oui. Vous l’avez donc croisée à Givrelac ? Comment va-t-elle ?",
          DialogueId = 51000437,
          GUID = "7FAC96AC",
          NextDialogue = 51000438,
          SpeakNpcId = 700235
        },
        [51000438] = {
          ContentFR = "Elle semble en bonne santé... mais elle a tout oublié. Dites-moi, avait-elle quelque chose avec elle quand vous l’avez trouvée ? Un objet, peut-être lié à son identité ?",
          DialogueId = 51000438,
          GUID = "7FAC96AD",
          NextDialogue = 51000439,
          SpeakNpcId = 100001
        },
        [51000439] = {
          ContentFR = "En effet. J’avais l’intention de chercher sa famille quand j’aurai terminé ma tournée auprès des malades... Si vous acceptez de m’aider, ce serait une bénédiction.",
          DialogueId = 51000439,
          GUID = "7FAC96AE",
          NextDialogue = 51000440,
          SpeakNpcId = 700235
        },
        [51000440] = {
          ContentFR = "Tenez. C’est ce qu’elle portait sur elle.",
          DialogueId = 51000440,
          GUID = "7FAC96AF",
          NextDialogue = 51000441,
          SpeakNpcId = 700235
        },
        [51000441] = {
          ContentFR = "Je dois y aller. Encore merci pour m’avoir sauvé la vie.",
          DialogueId = 51000441,
          GUID = "7FAC96B0",
          NextDialogue = 51000443,
          SpeakNpcId = 700235
        },
        [51000442] = {
          ContentFR = "Objet obtenu : Journal abîmé",
          DialogueId = 51000442,
          GUID = "7FAC96B1",
          NextDialogue = 51000443
        },
        [51000443] = {
          ContentFR = "Si ce journal dit vrai... alors tout est enfin clair.",
          DialogueId = 51000443,
          GUID = "7FAC96B2",
          NextDialogue = 51000444
        },
        [51000444] = {
          ContentFR = "Et par la même occasion, le mystère entourant la fille d’Elsa trouve sa réponse...",
          DialogueId = 51000444,
          GUID = "7FAC96B3",
          NextDialogue = 51000445
        },
        [51000445] = {
          ContentFR = "Annie est morte dans la tempête. Mais l’autre survivante, Alice, a hérité de ses vêtements. Elle a survécu aux montagnes, mais les fortes fièvres successives lui ont fait perdre la mémoire.",
          DialogueId = 51000445,
          GUID = "7FAC96B4"
        },
        [51000490] = {
          ContentFR = "... Annie, de quoi parles-tu ? Maman a préparé ta salade de Baies boréales et ton pudding à la crème préférés...",
          DialogueId = 51000490,
          GUID = "7FACA3E4",
          NextDialogue = 51000491,
          SpeakNpcId = 700006,
          Subtitle = "...Annie, what are you talking about? Mum's made your favourite, Borealberry Salad and Cream Pudding..."
        },
        [51000491] = {
          ContentFR = "Rentre à la maison. Maman ne te grondera plus, je ne te forcerai plus à devenir une dame de la haute société. Tout ce que je veux, c’est que tu sois en sécurité...",
          DialogueId = 51000491,
          GUID = "7FACA40E",
          NextDialogue = 51000492,
          SpeakNpcId = 700006,
          Subtitle = "Come back home, sweetheart. Mum won't be hard on you anymore, no more forcing you into being a lady of high society. All I want is for my baby to be safe..."
        },
        [51000492] = {
          ContentFR = "La femme semble mentalement instable. On devine qu’elle a perdu sa fille. Essaie de la calmer.",
          DialogueId = 51000492,
          GUID = "7FACA438",
          NextOptions = {
            [1] = 510004921
          },
          SpeakNpcId = 700006,
          Subtitle = "(The woman appears deeply distressed, seemingly having lost her daughter. Try to gently calm her down.)",
          bForbidSkipOptions = true
        },
        [51000493] = {
          ContentFR = "Tu sais que ce n’est qu’un petit jeu pour la rassurer. Il va falloir maintenant la calmer pour de bon. Elle semble avoir perdu sa fille.",
          DialogueId = 51000493,
          GUID = "7FACA462",
          NextOptions = {
            [1] = 510004921
          },
          RestartTag = 51000493,
          Subtitle = "(You're merely humouring her. Now, better gently coax her into calmness. It appears she has lost her daughter.)",
          bForbidSkipOptions = true
        },
        [51000501] = {
          Content = "拜托你了……",
          DialogueId = 51000501,
          GUID = "7FACA5B2",
          NextOptions = {
            [1] = 510005011
          },
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000502] = {
          ContentFR = "Par tous les saints ! Tu as retrouvé Annie ?",
          DialogueId = 51000502,
          GUID = "7FACA5DC",
          NextOptions = {
            [1] = 510005021
          },
          SpeakNpcId = 700006,
          Subtitle = "My goodness! Have you found Annie?",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000503] = {
          ContentFR = "...",
          DialogueId = 51000503,
          GUID = "7FACA606",
          NextDialogue = 51000504,
          SpeakNpcId = 700006,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700006:Shock_End"
          }
        },
        [51000504] = {
          ContentFR = "Mensonges... Des mensonges, encore des mensonges !",
          DialogueId = 51000504,
          GUID = "7FACA630",
          NextDialogue = 51000591,
          SpeakNpcId = 700006,
          Subtitle = "Nonsense... That's utter nonsense!",
          TalkActionId = {
            [1] = "700006:Disagree"
          }
        },
        [51000505] = {
          ContentFR = "Dis-moi, comment une enfant pourrait-elle survivre sans sa mère...",
          DialogueId = 51000505,
          GUID = "7FACA65A",
          NextDialogue = 51000506,
          Scripts = "SEQ{\nMoveTo{ActorId{700006},TargetPoint{\"Point_510005_Aier2\"},MoveSpeed{150},Visibility{\"Show\"}},\nMoveTo{ActorId{700006},TargetPoint{\"Point_510005_Aier\"},MoveSpeed{150},Visibility{\"Hide\"}}\n}",
          SpeakNpcId = 700006,
          Subtitle = "How do you think a child can manage without her mother..."
        },
        [51000506] = {
          ContentFR = "Elsa glisse une bourse dans tes bras, puis s’éloigne d’une démarche vacillante. Des larmes et un sourire tordu se mêlent sur son visage émacié, avant que sa silhouette ne disparaisse dans la brume",
          DialogueId = 51000506,
          GUID = "7FACA684",
          NextDialogue = 51000507,
          Subtitle = "(Elsa strides off, as if ushered by an unseen force, her tears mingling with a smile on her weary face, vanishing into the distance soon.)"
        },
        [51000507] = {
          ContentFR = "Un mensonge bienveillant n’apporte qu’un répit illusoire. Seule la vérité peut être affrontée. Le temps est le plus doux des remèdes... peut-être qu’un jour, elle guérira.",
          DialogueId = 51000507,
          GUID = "7FACA6AE",
          Subtitle = "(In her haste, she leaves behind a small box — meant as a gift for the kind soul who helps seek out her daughter.)\n(After your endeavours on her behalf, this reward is duly yours.)"
        },
        [51000590] = {
          ContentFR = "J’ai été une mauvaise mère... Me voilà à attendre bêtement les bras croisés, à supplier les autres d’agir à ma place. Ma Annie a dû m’attendre si longtemps. Peu importe... je pars la retrouver, je pars la chercher moi-même...",
          DialogueId = 51000590,
          GUID = "7FACB44C",
          NextDialogue = 51000505,
          SpeakNpcId = 700006,
          Subtitle = "I've been a terrible mother — how could I just wait here for others to help me? My Annie must've waited for me for so long...\nIt's okay, I'll set off to find her now... I'll find my baby on my own..."
        },
        [51000591] = {
          ContentFR = "Ma douce Annie... elle était si obéissante, si tendre... Jamais elle n’aurait abandonné sa mère ! Tu mens, sale {性别:menteur|menteuse} !",
          DialogueId = 51000591,
          GUID = "7FACB476",
          NextDialogue = 51000590,
          SpeakNpcId = 700006,
          Subtitle = "My Annie... My sweet Annie, she'd never leave her mother like this! You're lying, you dirty liar!"
        },
        [51000601] = {
          Camera = "-234.948181,323.855713,130.964355,0.00001,-3.599974,-48.399338,32.0,100000.0,false,Manual,2.8",
          Content = "拜托你了……",
          DialogueId = 51000601,
          GUID = "7FACB61A",
          LookAt = {
            [1] = "700006:n(0)"
          },
          NextOptions = {
            [1] = 510006011
          },
          Scripts = "TurnTo{TurnToDescription{"700006:n(100001)"}}",
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000602] = {
          Camera = "-110.428955,187.104736,199.557129,0.00006,-12.599321,-55.19915,32.0,500.0,false,Manual,2.8",
          ContentFR = "... Par les cieux... Un miracle... le miracle que j’attendais...",
          DialogueId = 51000602,
          FinalCamera = "-95.131409,197.827637,199.557129,0.000059,-12.799316,-54.799076,32.0,500.0,false,Manual,2.8",
          GUID = "7FACB644",
          LookAt = {
            [1] = "700006:n(700196)"
          },
          NextDialogue = 51000603,
          Scripts = "MoveTo{ActorId{700196},TargetPoint{"Point200203_Alice"},MoveSpeed{150},Visibility{"Show"}}",
          SpeakNpcId = 700006,
          Subtitle = "Oh my God, miracles do happen...",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          },
          ToFinalCameraBlendTime = 3
        },
        [51000603] = {
          ContentFR = "Laisse ta mère te regarder... J’ai cru devenir folle tant tu m’as manqué ! Hein ? Tu sembles différente... plus maigre qu’avant...",
          DialogueId = 51000603,
          FacialId = {
            [1] = "700006:CM_Happy01"
          },
          GUID = "7FACB66E",
          NextDialogue = 51000604,
          SpeakNpcId = 700006,
          Subtitle = "Let Mum have a good look at you, sweetie... I've missed you so much that I almost lost my mind! Hm? You seem a bit different... Much thinner than before..."
        },
        [51000604] = {
          Camera = "98.233093,31.165039,150.292969,0.000063,-2.599365,-39.19735,32.0,150.0,false,Manual,2.8",
          ContentFR = "Ce n’est rien, ce n’est rien... J’ai préparé ta salade de Baies boréales et ton pudding à la crème préférés. Rentrons à la maison, mon enfant, tout est derrière nous désormais...",
          DialogueId = 51000604,
          GUID = "7FACB698",
          NextDialogue = 51000605,
          SpeakNpcId = 700006,
          Subtitle = "It's okay, I've made your favourite Borealberry Salad and Cream Pudding; let's go home, my baby, everything's okay now...",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000605] = {
          ContentFR = "Merci, jeune âme charitable. Voici ta récompense. J’ai cru ne jamais revoir ma Annie... Merci, merci infiniment...",
          DialogueId = 51000605,
          GUID = "7FACB6C2",
          NextDialogue = 51000690,
          SpeakNpcId = 700006,
          Subtitle = "Bless you, kind soul. This is for you. I thought I'd never see my Annie again. Thank you, thank you so much..."
        },
        [51000606] = {
          ContentFR = "Ma précieuse fille... Tant que tu ne quittes pas ta maman, elle fera tout pour toi, absolument tout...",
          DialogueId = 51000606,
          GUID = "7FACB6EC",
          SpeakNpcId = 700006,
          Subtitle = "My precious daughter... As long as you don't leave me, I'll do anything for you..."
        },
        [51000690] = {
          ContentFR = "Les larmes de joie ruissellent sur son visage. Elle ne cesse de te remercier, encore et encore. Quand les pleurs s’éteindront, il ne restera plus qu’un avenir heureux... peut-être.",
          DialogueId = 51000690,
          GUID = "7FACC4B4",
          Subtitle = "(Tears of joy stream down the woman's face as she utters her gratitude repeatedly. After the tears dry, a mother and a child will live happily ever after... hopefully.)"
        },
        [51000701] = {
          ContentFR = "...",
          DialogueId = 51000701,
          GUID = "7FACC682",
          NextOptions = {
            [1] = 510007011
          },
          SpeakNpcId = 700032,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          }
        },
        [51000702] = {
          ContentFR = "Je... j’ai la tête embrumée. Honnêtement, je ne sais pas qui je suis, ni où je me trouve...",
          DialogueId = 51000702,
          GUID = "7FACC6AC",
          NextDialogue = 51000703,
          SpeakNpcId = 700032,
          Subtitle = "I... my head's all foggy. I don't know who I am or where I am..."
        },
        [51000703] = {
          ContentFR = "Une médecin bienveillante m’a ramenée des montagnes au nord. Elle a dit que j’avais eu une forte fièvre qui m’a endommagé le cerveau, et que c’est pour ça que j’ai perdu la mémoire...",
          DialogueId = 51000703,
          GUID = "7FACC6D6",
          NextOptions = {
            [1] = 510007031,
            [2] = 510007032,
            [3] = 510007033
          },
          SpeakNpcId = 700032,
          Subtitle = "I was rescued by a kind travelling doctor from the snowy mountains up north. He said I had suffered a severe fever,\nwhich impaired my memory...",
          bForbidSkipOptions = true
        },
        [51000705] = {
          ContentFR = "Ces derniers jours, je me souviens seulement de la tempête de neige dans laquelle j’avançais péniblement... Maintenant, je viens juste de me remettre de ma maladie, je ne peux même pas sortir de la cité. Peux-tu m’aider à enquêter ?",
          DialogueId = 51000705,
          GUID = "7FACC72A",
          NextOptions = {
            [1] = 510007051,
            [2] = 51000002
          },
          SpeakNpcId = 700032,
          Subtitle = "The only thing I could remember these past few days was the relentless blizzard\nas I struggled to make my way across the mountain... But right now I'm in no condition to go anywhere.\nCould you help me with the investigation?",
          TalkActionId = {
            [1] = "700032:Explain01_Start"
          },
          bForbidSkipOptions = true
        },
        [51000706] = {
          ContentFR = "À part la médecin qui m’a sauvée, tu es {性别:le seul|la seule} à tendre la main à une fille sans le sou comme moi. Je ne sais quoi dire d’autre... merci...",
          DialogueId = 51000706,
          GUID = "7FACC754",
          NextDialogue = 51000790,
          SpeakNpcId = 700032,
          Subtitle = "Apart from the kind doctor who saved me, you are the only one willing to offer a helping hand to a penniless girl like me.\nI don't know what else to say but thank you...",
          TalkActionId = {
            [1] = "700032:Explain01_End"
          }
        },
        [51000707] = {
          ContentFR = "Des nouvelles ?",
          DialogueId = 51000707,
          GUID = "7FACC77E",
          SpeakNpcId = 700032,
          Subtitle = "Did you find anything?"
        },
        [51000790] = {
          ContentFR = "Tiens, j’ai trouvé cette lettre dans ma poche. Je n’ai aucun souvenir de cette lettre... mais peut-être que c’est un indice utile ?",
          DialogueId = 51000790,
          GUID = "7FACD51C",
          NextDialogue = 51000791,
          SpeakNpcId = 700032,
          Subtitle = "Oh, the doctor said he found this letter on me, though I have no memory of it... This might serve as a clue, hopefully."
        },
        [51000791] = {
          ContentFR = "Les indices commencent à se relier : Madame Elsa, qui cherche sa fille à la limite de la folie, et cette jeune fille amnésique... sans oublier la lettre apparemment adressée à une mère.",
          DialogueId = 51000791,
          GUID = "7FACD546",
          NextDialogue = 51000792,
          Subtitle = "(The threads begin to connect between the two individuals you've recently come across — Ms Elsa,\nwho's been driven near to madness in search of her daughter, and this amnesiac girl.)\n(And then there's the letter, seemingly penned to a mother.)"
        },
        [51000792] = {
          ContentFR = "Tu supposes que la jeune fille amnésique pourrait être la fille disparue d’Elsa, Annie.",
          DialogueId = 51000792,
          GUID = "7FACD570",
          NextDialogue = 51000793,
          Subtitle = "(The thought crosses your mind that the girl bereft of memory might very well be Elsa's missing daughter, Annie.)"
        },
        [51000793] = {
          ContentFR = "Tu devrais l’emmener voir Elsa pour confirmation. Mais Elsa prend chaque jeune passant pour Annie... Mieux vaut d’abord collecter plus de preuves.",
          DialogueId = 51000793,
          GUID = "7FACD59A",
          NextDialogue = 51000794,
          Subtitle = "(Intuition suggests bringing her to Elsa for recognition, yet Elsa's delusion leads her to see Annie in every youthful face... Gathering more substantial evidence of the girl's identity seems the prudent course at the moment.)"
        },
        [51000794] = {
          ContentFR = "Pour découvrir l’histoire de la jeune fille, il faudra retrouver la médecin qui l’a sauvée.",
          DialogueId = 51000794,
          GUID = "7FACD59B"
        },
        [51000801] = {
          ContentFR = "Vous êtes revenu {性别:sain et sauf|saine et sauve}. Alors ? Avez-vous découvert quelque chose ?",
          DialogueId = 51000801,
          GUID = "7FACD6EA",
          NextDialogue = 51000802,
          SpeakNpcId = 700032,
          Subtitle = "You've returned safely. Did you find anything?",
          TalkActionId = {
            [1] = "700032:Agree"
          }
        },
        [51000802] = {
          ContentFR = "La jeune fille te fixe, fragile et seule. Pendant ce temps, Elsa sombre dans la folie, hantée par la disparition de sa fille... Si seulement cette enfant était Annie...",
          DialogueId = 51000802,
          GUID = "7FACD714",
          NextDialogue = 51000890,
          Subtitle = "(The girl standing before you is all alone, and Ms Elsa has been driven to the brink of madness by her daughter's disappearance...)\n(You find yourself wishing she were Annie.)"
        },
        [51000803] = {
          ContentFR = "... Qu’est-ce que... c’est ?",
          DialogueId = 51000803,
          GUID = "7FACD73E",
          NextDialogue = 51000893,
          SpeakNpcId = 700032,
          Subtitle = "...What's this...",
          TalkActionId = {
            [1] = "700032:Shock_Start"
          }
        },
        [51000804] = {
          ContentFR = "Je... je me souviens !",
          DialogueId = 51000804,
          GUID = "7FACD768",
          NextDialogue = 51000805,
          SpeakNpcId = 700032,
          Subtitle = "...It's all coming back to me now...",
          TalkActionId = {
            [1] = "700032:Shock_End"
          }
        },
        [51000805] = {
          ContentFR = "Je m’appelle Alice. Étudiante en archéologie à Aethyrie...",
          DialogueId = 51000805,
          GUID = "7FACD792",
          NextDialogue = 51000806,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "My name is Alice, I'm an archaeology student from Iserl...",
          TalkActionId = {
            [1] = "700032:Talk02_Start"
          }
        },
        [51000806] = {
          ContentFR = "Je menais des fouilles dans les Monts Vidofnir quand la tempête m’a piégée plusieurs jours. J’ai vite perdu mon chemin...",
          DialogueId = 51000806,
          GUID = "7FACD7BC",
          NextDialogue = 51000807,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "I was conducting a survey in the Vidofnir Mountains when I got caught in a snowstorm that lasted for days, and soon I lost my way..."
        },
        [51000807] = {
          ContentFR = "C’est alors que j’ai rencontré Annie. Elle était à l’agonie. Nous avons lutté ensemble, nous soutenant mutuellement pour survivre. Elle m’avait promis de m’accueillir chez elle, à Givrelac, une fois la neige calmée...",
          DialogueId = 51000807,
          GUID = "7FACD7E6",
          NextDialogue = 51000808,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Later on, I met Annie, who was clinging to life by a mere thread. Together, we struggled to live on for several days.\nWe encouraged each other to try to survive, and she invited me to visit her home in Icelake after the storm..."
        },
        [51000808] = {
          ContentFR = "Mais ses blessures étaient trop graves. Elle n’a pas survécu. Avant de mourir, elle m’a tendu son manteau... Elle voulait que je reste au chaud, que je sorte vivante de ces montagnes...",
          DialogueId = 51000808,
          GUID = "7FACD810",
          NextDialogue = 51000809,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "But she was so seriously injured and didn't make it... In the end, she gave me her coat,\nhoping that I would make it out of the snowy mountains alive...",
          TalkActionId = {
            [1] = "700032:Talk02_End"
          }
        },
        [51000809] = {
          ContentFR = "Annie...",
          DialogueId = 51000809,
          GUID = "7FACD83A",
          NextDialogue = 51000810,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Annie...Thank you...",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          }
        },
        [51000810] = {
          ContentFR = "Merci... Je n’oublierai jamais Annie.",
          DialogueId = 51000810,
          GUID = "7FACD864",
          NextDialogue = 51000811,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Thank you... I will always remember Annie.",
          TalkActionId = {
            [1] = "700032:Explain02_End"
          }
        },
        [51000811] = {
          ContentFR = "Alice serre le manteau contre elle, douce relique du sacrifice d’une amie. Tu la quittes, décidé à annoncer la vérité à Elsa.",
          DialogueId = 51000811,
          GUID = "7FACD88E",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "(Alice gently strokes the clothing which is a testament of one girl protecting the other.)\n(You bid farewell to Alice and get ready to tell Elsa the truth.)"
        },
        [51000812] = {
          ContentFR = "Dès que je serai rétablie, je reprendrai la route pour une nouvelle aventure.",
          DialogueId = 51000812,
          GUID = "7FACD8B8",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Once I've recovered, I will start my next adventure."
        },
        [51000813] = {
          ContentFR = "Ton nom est Annie. J’ai retrouvé ta mère. La lettre dans ta poche lui est destinée.",
          DialogueId = 51000813,
          GUID = "7FACD8E2",
          NextDialogue = 51000894,
          SpeakNpcId = 100001,
          Subtitle = "Your name is Annie. I've found your mother, and that letter you're carrying is meant for her."
        },
        [51000814] = {
          ContentFR = "Merci ! Elle doit s’inquiéter pour moi...",
          DialogueId = 51000814,
          GUID = "7FACD90C",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Thank you! She must be worried about me."
        },
        [51000815] = {
          ContentFR = "Quand ma mère ira mieux, je l’emmènerai voir la beauté du vaste monde !",
          DialogueId = 51000815,
          GUID = "7FACD936",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Once my mother gets better, I'll take her to see the beauty in the great outdoors!"
        },
        [51000890] = {
          ContentFR = "Tu te souviens : Elsa avait dit n’avoir qu’une fille, son unique famille. Un doute terrible traverse ton esprit, et si tu n’avais <H>jamais trouvé</> le journal d’Alice...",
          DialogueId = 51000890,
          GUID = "7FACE584",
          NextDialogue = 51000891,
          Subtitle = "(Recalling Elsa's words about how she and her daughter were the only two in their family, a dreadful thought crosses your mind —)\n(if you had never seen Alice's diary...)"
        },
        [51000891] = {
          ContentFR = "La jeune fille aurait retrouvé un foyer chaleureux. Elsa aurait retrouvé sa "fille". <H>Ce serait le dénouement idéal... mais toutes deux ont droit à la vérité.</>",
          DialogueId = 51000891,
          GUID = "7FACE5AE",
          NextDialogue = 51000892,
          Subtitle = "(Then the girl would have a warm hearth to return to, and Elsa would have her "daughter" back.)\n(This seems like the perfect ending — except, they both have the right to know the truth...)"
        },
        [51000892] = {
          ContentFR = "Dois-tu leur révéler la réalité, ou laisser l’illusion réconfortante perdurer ?",
          DialogueId = 51000892,
          GUID = "7FACE5D8",
          NextOptions = {
            [1] = 510008921,
            [2] = 510008121
          },
          Subtitle = "(The dilemma stands: to unveil the harsh truth or perpetuate the comforting falsehood?)",
          bForbidSkipOptions = true
        },
        [51000893] = {
          ContentFR = "Attends... c’est mon écriture...",
          DialogueId = 51000893,
          GUID = "7FACE602",
          NextDialogue = 51000804,
          SpeakNpcId = 700032,
          Subtitle = "This is... something I wrote..."
        },
        [51000894] = {
          ContentFR = "Annie... Alors c’est comme ça que je m’appelle. Étrange... ça me semble presque étranger.",
          DialogueId = 51000894,
          GUID = "7FACE62C",
          NextDialogue = 51000895,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Annie... So that's my name. Has a strange ring to it..."
        },
        [51000895] = {
          ContentFR = "Désolée, je n’ai aucun souvenir... Merci ! Merci du fond du cœur ! Emmène-moi voir ma mère, je suis sûre qu’elle voudra te remercier !",
          DialogueId = 51000895,
          GUID = "7FACE656",
          NextOptions = {
            [1] = 510008141
          },
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Sorry, I really don't remember a thing... Thank you, really, thank you so much! Could you take me to my mother? She will definitely give you a ton of thank-you gifts!",
          bForbidSkipOptions = true
        },
        [51000901] = {
          ContentFR = "{性别:Un nouveau client|Une nouvelle cliente} ! Qu’est-ce qui vous amène ici ? Mais si c’est un peu de divertissement que vous cherchez, vous avez frappé à la bonne porte : chez Martin, impossible d’être déçu !",
          DialogueId = 51000901,
          GUID = "7FACE752",
          NextDialogue = 51000902,
          SpeakNpcId = 700022,
          Subtitle = "A new customer! What brings you here? But if you're looking for some fun, you've come to the right place with Martin!",
          TalkActionId = {
            [1] = "700022:Talk01_Start"
          }
        },
        [51000902] = {
          ContentFR = "L’homme en face de toi exécute une révérence extravagante, puis, comme par magie, fait apparaître une ribambelle d’objets disparates.",
          DialogueId = 51000902,
          GUID = "7FACE77C",
          NextDialogue = 51000903,
          SpeakNpcId = 700022,
          Subtitle = "(The man in front of you performs an extravagant bow, then magically displays a bunch of scattered goods.)"
        },
        [51000903] = {
          ContentFR = "Servez-vous, laissez-vous guider par le goût de Martin ! Des merveilles que vous avez vues... et d’autres que vous n’auriez jamais imaginées. Ajoutez un soupçon de surprise à votre quotidien !",
          DialogueId = 51000903,
          GUID = "7FACE7A6",
          SpeakNpcId = 700022,
          Subtitle = "Feel free to choose. Trust Martin's choice! You can find everything here, seen or unseen, occasionally spicing up your life!",
          TalkActionId = {
            [1] = "700022:Talk01_End"
          },
          TalkOptions = {
            [1] = 510009031,
            [2] = 510009032,
            [3] = 510009033
          }
        },
        [51000904] = {
          ContentFR = "Quelle impolitesse ! Savoir estimer une valeur ne signifie pas avoir du goût, mon trésor.",
          DialogueId = 51000904,
          GUID = "7FACE7D0",
          SpeakNpcId = 700022,
          Subtitle = "You're quite impolite. Being able to appraise doesn't mean you have good taste, sweetheart.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000905] = {
          ContentFR = "Et laisser ces trouvailles toutes seules, n’est-ce pas un crime ? Je ne fais que leur offrir un nouveau foyer.",
          DialogueId = 51000905,
          GUID = "7FACE7FA",
          SpeakNpcId = 700022,
          Subtitle = "Isn't letting them go to waste also a crime? I just want to find a home for them all.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000906] = {
          ContentFR = "Oh... ça, c’est un secret de métier. Alors, qu’avez-vous à offrir en échange ?",
          DialogueId = 51000906,
          GUID = "7FACE824",
          SpeakNpcId = 700022,
          Subtitle = "Nah-ah. That's a trade secret. So, have you thought about what you'd like to exchange with me?",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000907] = {
          ContentFR = "Tu parcours ses articles du regard, puis secoues la tête, {性别:déçu|déçue}.",
          DialogueId = 51000907,
          GUID = "7FACE84E",
          Subtitle = "(You look at his goods and sadly shake your head.)",
          TalkOptions = {
            [1] = 510009072
          }
        },
        [51000908] = {
          ContentFR = "Alors je ne suis sans doute pas celui que vous cherchez. Mais je saurai attendre le jour où vous viendrez enfin honorer Martin de votre présence.",
          DialogueId = 51000908,
          GUID = "7FACE878",
          SpeakNpcId = 700022,
          Subtitle = "Then I'm probably not the person you need, but I'll wait for the day you extend your patronage."
        },
        [51000909] = {
          ContentFR = "J’ai compris ! Vous êtes de ceux qu’on croise rarement dans Givrelac...",
          DialogueId = 51000909,
          GUID = "7FACE8A2",
          NextDialogue = 51000910,
          SpeakNpcId = 700022,
          Subtitle = "I got it! You're a rare kind of person in Icelake…",
          TalkActionId = {
            [1] = "700022:Think_Start"
          }
        },
        [51000910] = {
          ContentFR = "{性别:Ni un miséreux venu négocier quelques maigres vivres, ni un noble avide|Ni une miséreuse venue négocier quelques maigres vivres, ni une noble avide} des secrets de ses voisins. Vous n’attendez rien de Martin... vous n’avez même jamais entendu mon nom, n’est-ce pas ?",
          DialogueId = 51000910,
          GUID = "7FACE8CC",
          SpeakNpcId = 700022,
          Subtitle = "You're neither a slum dweller here to buy cheap supplies nor a noble interested in the private lives of your neighbors.\nYou have no desire or need for Martin. You've never even heard my name, have you?",
          TalkActionId = {
            [1] = "700022:Think_End"
          },
          TalkOptions = {
            [1] = 510009101,
            [2] = 510009102,
            [3] = 510009103
          }
        },
        [51000911] = {
          ContentFR = "Alors laissez-moi me présenter ! Je suis le Roi des Récupérateurs de Givrelac, le confident de chaque poubelle, l’ambassadeur et le héraut des rebuts oubliés.",
          DialogueId = 51000911,
          GUID = "7FACE8F6",
          NextDialogue = 51000990,
          SpeakNpcId = 700022,
          Subtitle = "Then allow me to introduce myself! I am the King of Scavengers in Icelake, the confidant brother of every rubbish bin, and the best spokesperson and promoter of discarded items.",
          TalkActionId = {
            [1] = "700022:Confident_Start"
          }
        },
        [51000912] = {
          ContentFR = "Car voyez-vous, les ordures recèlent mille secrets. Si l’on sait patienter et se salir les mains... elles révèlent à qui veut bien écouter les histoires des foyers qu’elles ont quittés.",
          DialogueId = 51000912,
          GUID = "7FACE920",
          SpeakNpcId = 700022,
          Subtitle = "In fact, rubbish bins hide all sorts of secrets. As long as you're patient enough and don't mind the hard work,\nthey will continue to share with you the secrets of their households.",
          TalkActionId = {
            [1] = "700022:Confident_End"
          }
        },
        [51000913] = {
          ContentFR = "La curiosité vous pique ? Excellent. Je le savais, mes bricoles ne suffiraient pas à vous séduire. Mais Martin a ses propres méthodes.",
          DialogueId = 51000913,
          GUID = "7FACE94A",
          NextDialogue = 51000991,
          SpeakNpcId = 700022,
          Subtitle = "Now you get intrigued? That's great. I know ordinary goods won't impress you, but Martin has his ways.",
          TalkActionId = {
            [1] = "700022:Explain01_Start"
          }
        },
        [51000914] = {
          ContentFR = "Si vous les restituez à leur propriétaire, vous comprendrez mieux cette cité. Et même si vous n’y gagnez rien, au moins votre curiosité sera assouvie.",
          DialogueId = 51000914,
          GUID = "7FACE974",
          NextDialogue = 51000915,
          SpeakNpcId = 700022,
          Subtitle = "If you can help find their owners, you might understand this city better. Even if you get nothing, at least you satisfy your curiosity.",
          TalkActionId = {
            [1] = "700022:Explain01_End"
          }
        },
        [51000915] = {
          ContentFR = "Martin sort de nulle part quelques objets indéfinissables, puis vous adresse un clin d’œil complice.",
          DialogueId = 51000915,
          GUID = "7FACE99E",
          NextDialogue = 51000916,
          Subtitle = "(Martin produces some indescribable things and winks at you.)"
        },
        [51000916] = {
          ContentFR = "Alors, {性别:tenté|tentée} ?",
          DialogueId = 51000916,
          GUID = "7FACE9C8",
          SpeakNpcId = 700022,
          Subtitle = "Want to give it a try?",
          TalkActionId = {
            [1] = "700022:Talk01_Start"
          }
        },
        [51000917] = {
          ContentFR = "Bonne chance dans votre enquête, détective.",
          DialogueId = 51000917,
          GUID = "7FACE9F2",
          SpeakNpcId = 700022,
          Subtitle = "Good luck, Detective.",
          TalkActionId = {
            [1] = "700022:Talk01_End"
          }
        },
        [51000918] = {
          ContentFR = "Tout se passe bien, détective ?",
          DialogueId = 51000918,
          GUID = "7FACEA1C",
          SpeakNpcId = 700022,
          Subtitle = "Everything going well, Detective?"
        },
        [51000990] = {
          ContentFR = "Quant à mon nom... inutile de le redire : je suis Martin.",
          DialogueId = 51000990,
          GUID = "7FACF5EC",
          NextDialogue = 51000912,
          SpeakNpcId = 700022,
          Subtitle = "My name probably speaks for itself. I am Martin."
        },
        [51000991] = {
          ContentFR = "Je vous propose des énigmes. Considérez-les comme les cicatrices de quelqu’un... ou des objets perdus.",
          DialogueId = 51000991,
          GUID = "7FACF616",
          NextDialogue = 51000914,
          SpeakNpcId = 700022,
          Subtitle = "I'm willing to sell "puzzles" to you. You can treat them as "someone's scars" or "lost items"."
        },
        [51001001] = {
          Camera = "30.150391,500.332031,170.427734,0.000075,-9.398094,-93.777969,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Au loin, tu aperçois une personne habillée en marchand au guichet. Elle semble être en plein différend avec la vendeuse de billets.",
          DialogueId = 51001001,
          GUID = "7FACF7BA",
          LookAt = {
            [1] = "700021:n(700033)"
          },
          NextDialogue = 51001002,
          Subtitle = "(You see a person dressed as a vendor at the ticket counter, seemingly in a dispute with the ticket seller.)"
        },
        [51001002] = {
          Camera = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
          ContentFR = "Je peux même pas poser une question ? Ta mère ne t’a pas appris les bonnes manières ?!",
          DialogueId = 51001002,
          GUID = "7FACF7E4",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001003,
          SpeakNpcId = 700033,
          Subtitle = "Can't I even ask? Didn't your mother teach you manners?!",
          TalkActionId = {
            [1] = "700033:Angry01_Start"
          }
        },
        [51001003] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentFR = "Oh très bien, monsieur. Alors, après que je vous ai poliment annoncé le prix, que comptez-vous faire ?",
          DialogueId = 51001003,
          GUID = "7FACF80E",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001090,
          SpeakNpcId = 700021,
          Subtitle = "Oh alright, sir. So, after I politely tell you the ticket price, what do you plan to do?",
          TalkActionId = {
            [1] = "700021:Talk01_Start"
          }
        },
        [51001004] = {
          Camera = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
          ContentFR = "C-Comment sais-tu que je n’ai pas...",
          DialogueId = 51001004,
          GUID = "7FACF838",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001005,
          SpeakNpcId = 700033,
          Subtitle = "H...How do you know I don't have...",
          TalkActionId = {
            [1] = "700033:Angry01_End"
          }
        },
        [51001005] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentFR = "Dégagez, grand riche des taudis.",
          DialogueId = 51001005,
          GUID = "7FACF862",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001091,
          SpeakNpcId = 700021,
          Subtitle = "Off you go, you shack-dwelling tycoon.",
          TalkActionId = {
            [1] = "700021:Talk01_End"
          }
        },
        [51001006] = {
          Camera = "319.767578,148.608398,91.180664,0.000064,-0.797267,-149.347275,35.0,400.0,false,Manual,2.8",
          ContentFR = "Le marchand part en tremblant des lèvres, tandis que la vendeuse de billets te lance un regard méprisant.",
          DialogueId = 51001006,
          GUID = "7FACF88C",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001007,
          Scripts = "MoveTo{ActorId{700033},TargetPoint{"Point200202_Shangfan"},MoveSpeed{150},Visibility{"Hide"}}",
          Subtitle = "(The vendor leaves, lips trembling, while the ticket seller snorts arrogantly, glancing disdainfully at you.)"
        },
        [51001007] = {
          ContentFR = "Et toi ? Qu’est-ce que tu veux ? Ne me fais pas perdre mon temps, sinon tu finiras comme lui, à ramper dans ton trou à rats.",
          DefaultLookAt = "Self",
          DialogueId = 51001007,
          GUID = "7FACF8B6",
          LookAt = {
            [1] = "0:n(700021)"
          },
          SpeakNpcId = 700021,
          Subtitle = "What about you? What do you want? I advise you not to waste my time, or you'll slink back into your rat hole just like him.",
          TalkActionId = {
            [1] = "700021:Talk03_Start"
          },
          TalkOptions = {
            [1] = 510010071,
            [2] = 510010072
          },
          TurnTo = {
            [1] = "700021:n(0)"
          }
        },
        [51001008] = {
          ContentFR = "Encore un ! Tes histoires ne m’impressionnent pas. Alors avant que je t’adresse mes salutations les plus sincères, tu ferais mieux de disparaître au plus vite !",
          DialogueId = 51001008,
          GUID = "7FACF8E0",
          SpeakNpcId = 700021,
          Subtitle = "Not another one! Before I send you my sincerest regards, you'd better disappear quickly!",
          TalkActionId = {
            [1] = "700021:Talk03_End"
          }
        },
        [51001009] = {
          ContentFR = "Q-Quoi... je ne comprends pas ce que tu dis !",
          DialogueId = 51001009,
          GUID = "7FACF90A",
          NextDialogue = 51001010,
          SpeakNpcId = 700021,
          Subtitle = "W...What are you talking about? I don't understand!",
          TalkActionId = {
            [1] = "700021:Talk03_End"
          }
        },
        [51001010] = {
          ContentFR = "Tu sors le "déchet" de Martin, une boîte d’étoiles en papier. Tu en déplie une : c’est clairement un billet périmé.",
          DialogueId = 51001010,
          GUID = "7FACF934",
          Subtitle = "(You take out the \"scrap\" you got from Martin, a jar of pentagonal stars made of paper.)\n(You unfold one to find out it's clearly an expired ticket.)"
        },
        [51001012] = {
          ContentFR = "...",
          DialogueId = 51001012,
          GUID = "7FACF988",
          NextDialogue = 51001013,
          SpeakNpcId = 700021,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700021:Shock_Start"
          }
        },
        [51001013] = {
          ContentFR = "Elle semble complètement abasourdie. Deux larmes coulent bientôt sur le visage hautain de cette vendeuse de billets.",
          DialogueId = 51001013,
          GUID = "7FACF9B2",
          NextDialogue = 51001014,
          Subtitle = "(She seems extremely shocked. Before you know it, tears are streaming down the face of this haughty ticket seller.)"
        },
        [51001014] = {
          ContentFR = "Pourquoi... pourquoi me montrer ça à nouveau ?",
          DialogueId = 51001014,
          GUID = "7FACF9DC",
          NextDialogue = 51001015,
          SpeakNpcId = 700021,
          Subtitle = "Why... Why do you have to show this to me again?",
          TalkActionId = {
            [1] = "700021:Shock_End"
          }
        },
        [51001015] = {
          ContentFR = "Pourquoi me rappeler un rêve impossible à réaliser ?",
          DialogueId = 51001015,
          GUID = "7FACFA06",
          NextDialogue = 51001016,
          SpeakNpcId = 700021,
          Subtitle = "Why remind me of dreams that can't be fulfilled?",
          TalkActionId = {
            [1] = "700021:Disagree"
          }
        },
        [51001016] = {
          ContentFR = "Chaque jour, je regarde les trains passer et je rêve de les prendre comme ces gens importants... mais je n’ai que des billets invendus.",
          DialogueId = 51001016,
          GUID = "7FACFA30",
          NextDialogue = 51001017,
          SpeakNpcId = 700021,
          Subtitle = "Every day, I watch trains roar in and out. I hope to ride them like those high officials, but all I have are unsold tickets.",
          TalkActionId = {
            [1] = "700021:Explain02_Start"
          }
        },
        [51001017] = {
          ContentFR = "Certains n’ont jamais vu de billets de leur vie. J’ai eu un peu de chance, je peux tenir dans mes mains ce billet qui ne sert à rien...",
          DialogueId = 51001017,
          GUID = "7FACFA5A",
          NextDialogue = 51001018,
          SpeakNpcId = 700021,
          Subtitle = "Some people live their entire lives without seeing a ticket. I'm luckier because at least I get to hold an unfulfillable entry pass every day."
        },
        [51001018] = {
          ContentFR = "Mais ma chance s’arrête là. Il y a dans ce monde des vœux que même les étoiles ne peuvent réaliser. C’est pour ça que je les ai jetés...",
          DialogueId = 51001018,
          GUID = "7FACFA84",
          SpeakNpcId = 700021,
          Subtitle = "But that's where my luck ends. In this world, there are wishes even stars can't fulfill. I realised this, and that's why I threw them away...",
          TalkActionId = {
            [1] = "700021:Explain02_End"
          },
          TalkOptions = {
            [1] = 510010181,
            [2] = 510010182,
            [3] = 510010183,
            [4] = 510010184
          }
        },
        [51001019] = {
          ContentFR = "Alors qui construira cette échelle pour moi ? La Fée marraine ?",
          DialogueId = 51001019,
          GUID = "7FACFAAE",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "Then who will build this ladder to heaven for me? The Fairy Godmother?"
        },
        [51001020] = {
          ContentFR = "Tu as raison... en quoi suis-je différente d’eux ?",
          DialogueId = 51001020,
          GUID = "7FACFAD8",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "You're right. How am I any different from them?"
        },
        [51001021] = {
          ContentFR = "Oui... je ne peux pas perdre ce travail que je déteste mais qui me fait vivre.",
          DialogueId = 51001021,
          GUID = "7FACFB02",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "You're right... I can't lose this job that I hate yet make a living from."
        },
        [51001022] = {
          ContentFR = "Je suis un peu désabusée, mais pas encore folle... quoique ce jour ne soit peut-être pas si loin.",
          DialogueId = 51001022,
          GUID = "7FACFB2C",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "I might be disillusioned with the world, but I'm not crazy yet, though that day might not be far off."
        },
        [51001023] = {
          ContentFR = "La vendeuse récupère les billets pliés en étoiles, trouve un endroit sec et brûle ces papiers porteurs de vœux.",
          DialogueId = 51001023,
          GUID = "7FACFB56",
          NextDialogue = 51001024,
          SpeakNpcId = 700021,
          Subtitle = "(The ticket seller takes the ticket stars from your hand, finds a dry place, and sets these wish-bearing papers on fire.)"
        },
        [51001024] = {
          ContentFR = "Je criais toujours après ceux qui voulaient partir en les traitant de rêveurs,",
          DialogueId = 51001024,
          GUID = "7FACFB80",
          NextDialogue = 51001025,
          SpeakNpcId = 700021,
          Subtitle = "I always scold those who want to leave as dreamers,",
          TalkActionId = {
            [1] = "700021:Explain01_Start"
          }
        },
        [51001025] = {
          ContentFR = "mais peut-être que celle qui doit se réveiller de ce rêve, c’est moi.",
          DialogueId = 51001025,
          GUID = "7FACFBAA",
          NextDialogue = 51001026,
          SpeakNpcId = 700021,
          Subtitle = "but maybe it's me who should wake up from the dream.",
          TalkActionId = {
            [1] = "700021:Explain01_End"
          }
        },
        [51001026] = {
          ContentFR = "Depuis ce jour, Jessica reste immobile dans le hall, ses réponses mécaniques rappelant le fonctionnement d’une billetterie automatique.",
          DialogueId = 51001026,
          GUID = "7FACFBD4",
          Subtitle = "(From then on, Jessica just sat indifferently in the ticket hall, giving mechanical responses to anyone who asked like a ticket machine.)"
        }
      }
    end
  },
  {
    MinKey = 51001027,
    MaxKey = 51002014,
    Loader = function()
      return {
        [51001027] = {
          ContentFR = "...",
          DialogueId = 51001027,
          GUID = "7FACFBFE",
          SpeakNpcId = 700021,
          Subtitle = "..."
        },
        [51001090] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentFR = "Allez-vous gentiment sortir une fortune pour acheter votre billet, ou allez-vous fouiller vos poches vides et me donner des ordres ?",
          DialogueId = 51001090,
          GUID = "7FAD0654",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001004,
          SpeakNpcId = 700021,
          Subtitle = "Will you politely pull out a huge amount of money to buy a ticket, or will you fiddle with your empty pockets and boss me around?"
        },
        [51001091] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentFR = "Ce temps-là est parfait pour vous : vous pouvez vous réchauffer avec un petit feu dans votre abri, ou rêver que grand-mère vous emmène en train où vous voulez. Et cessez de vous ridiculiser devant moi !",
          DialogueId = 51001091,
          GUID = "7FAD067E",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001006,
          SpeakNpcId = 700021,
          Subtitle = "This weather is just right for you to strike a match and call for grandma, dreaming that she takes you on a train.\nGo wherever you like in your dream, and stop shaming yourself in front of me!"
        },
        [51001092] = {
          ContentFR = "Le bon côté, c’est qu’elle n’est plus aussi colérique et vulgaire qu’avant.",
          DialogueId = 51001092,
          GUID = "7FAD06A8",
          Subtitle = "(But the good thing is she was no longer as temperamental and foul-mouthed as before.)"
        },
        [51001101] = {
          ContentFR = "Un Souillé errant tenait un journal dans sa gueule. Après l’avoir vaincu, tu récupères le journal...",
          DialogueId = 51001101,
          GUID = "7FAD0822",
          NextDialogue = 51001102,
          Subtitle = "(A Filthoid, wandering from nowhere, clutched a notebook in its jaws. After defeating the Filthoid, you picked up the notebook...)"
        },
        [51001102] = {
          ContentFR = "Si ce journal dit vrai... alors tout est enfin clair.",
          DialogueId = 51001102,
          GUID = "7FAD084C",
          NextDialogue = 51001103,
          Subtitle = "(If what's written in this diary is true, then the real identity of the amnesiac girl becomes quite clear.)\n(Likewise revealed is the fate of Ms Elsa's missing daughter, Annie...)"
        },
        [51001103] = {
          ContentFR = "Annie est morte dans la tempête. Mais l’autre survivante, Alice, a hérité de ses vêtements. Elle a survécu aux montagnes, mais les fortes fièvres successives lui ont fait perdre la mémoire.",
          DialogueId = 51001103,
          GUID = "7FAD0876",
          Subtitle = "(...Annie has tragically passed away, while the other girl, Alice, who ended up with Annie's clothes, has survived.)\n(Although Alice made it through the ordeal in the snowy mountains, the severe fevers she suffered afterwards took away her memories.)"
        },
        [51001201] = {
          ContentFR = "{性别:Un Chasseur de Phoxène|Une Chasseuse de Phoxène} ? Je n’aurais jamais cru que l’un d’eux atteindrait cet endroit... Tu dois avoir, toi aussi, ce qu’il faut pour devenir {性别:un héros|une héroïne}.",
          DialogueId = 51001201,
          GUID = "7FAD188A",
          NextDialogue = 51001212,
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001202] = {
          ContentFR = "Eh oui. À part ce vieux fou que je suis, plus personne ne prend la peine d’élever des oiseaux à plumes d’or, de nos jours.",
          DialogueId = 51001202,
          GUID = "7FAD18B4",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Well, who else but this old geezer would bother keeping these birds nowadays.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001203] = {
          ContentFR = "Les manger ? Tu sais seulement à quel point ces oiseaux sont précieux pour un mineur ?!",
          DialogueId = 51001203,
          GUID = "7FAD18DE",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Are you insane?? Do you have any idea how precious these birds are to a miner?!",
          TalkActionId = {
            [1] = "700003:Disagree"
          }
        },
        [51001204] = {
          ContentFR = "Les mineurs s’appuient de plus en plus sur les gadgets high-tech bricolés par l’Académie d’Alchimie... au point d’oublier les méthodes traditionnelles.",
          DialogueId = 51001204,
          GUID = "7FAD1908",
          NextOptions = {
            [1] = 510012041,
            [2] = 510012042,
            [3] = 510012043
          },
          SpeakNpcId = 700003,
          Subtitle = "Miners today have grown so reliant on the high-tech gadgets from the Alchemy Academy, that they have forgotten the old ways.",
          bForbidSkipOptions = true
        },
        [51001205] = {
          ContentFR = "Exactement. Leur sensibilité exceptionnelle aux gaz toxiques en faisait un compagnon indispensable dans nos anciennes expéditions. On emmenait toujours l’un d’eux avec nous sous terre, pour vérifier si les galeries étaient sûres.",
          DialogueId = 51001205,
          GUID = "7FAD1932",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Exactly, their amazing sensitivity to harmful gases made them a must-have for us miners in the old days.\nWe'd always have one by our side underground to help detect whether the tunnels were safe.",
          TalkActionId = {
            [1] = "700003:Agree"
          }
        },
        [51001206] = {
          ContentFR = "Bien dit. Il n’y a plus beaucoup de jeunes capables d’une telle réflexion, de nos jours.",
          DialogueId = 51001206,
          GUID = "7FAD195C",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Well said. Quite rare to find young folks with such insight these days.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001207] = {
          ContentFR = "Hmpf. Je fais tout cela pour les mineurs, pas pour obtenir l’approbation des autres.",
          DialogueId = 51001207,
          GUID = "7FAD1986",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Hmph, I do what I do for us miners' sake. I don't need others' approval.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001208] = {
          ContentFR = "Les outils sans âme peuvent faillir... voire te trahir. Mais un compagnon auquel tu as offert ton affection sera toujours là pour affronter les épreuves à tes côtés.",
          DialogueId = 51001208,
          GUID = "7FAD19B0",
          NextDialogue = 51001209,
          SpeakNpcId = 700003,
          Subtitle = "Soulless tools may fail you, or even betray you. It's the companion you've always cherished that will stand by you through every trial.",
          TalkActionId = {
            [1] = "700003:Think_Start"
          }
        },
        [51001209] = {
          ContentFR = "Le jour où les détecteurs de l’Académie tomberont en panne, ce seront peut-être encore ces compagnons loyaux qui sauveront la vie des mineurs...",
          DialogueId = 51001209,
          GUID = "7FAD19DA",
          NextDialogue = 51001210,
          SpeakNpcId = 700003,
          Subtitle = "Should the day come when the Academy's fancy tools give out, it may well be these loyal friends that save miners' lives...",
          TalkActionId = {
            [1] = "700003:Think_End"
          }
        },
        [51001210] = {
          ContentFR = "Le vieux mineur pose son regard sur un monticule de terre non loin. Ses lèvres bougent, comme s’il voulait dire quelque chose... mais tout ce qui s’échappe de sa bouche est un profond soupir.",
          DialogueId = 51001210,
          GUID = "7FAD1A04",
          Subtitle = "(The old miner's gaze settles on a nearby mound, his lips trembling with unvoiced thoughts, culminating in nothing but a weary sigh.)"
        },
        [51001211] = {
          ContentFR = "Il reste silencieux. De temps à autre, il sort de ses pensées pour pousser un long soupir. Était-ce un hommage à un compagnon disparu... ou une lamentation face à un monde qui change trop vite ?",
          DialogueId = 51001211,
          GUID = "7FAD1A2E",
          Subtitle = "(In silence, the elder periodically snaps from his thoughts, letting out a lingering sigh.)\n(It's unclear whether it's a tribute to a fallen comrade or a lament for the changing times.)"
        },
        [51001212] = {
          Content = "老人温柔地注视着空中的一小片黑点，你顺着他的视线远眺，看到了一群离去的飞鸟。待到所有鸟群飞走后，老人才转身继续与你交谈。",
          DialogueId = 51001212,
          GUID = "7FAD188B",
          NextOptions = {
            [1] = 510012011,
            [2] = 510012012
          },
          bForbidSkipOptions = true
        },
        [51001301] = {
          ContentFR = "Maudite Camilla ! Vieille harpie aveugle, incapable de reconnaître un bon alcool !",
          DialogueId = 51001301,
          GUID = "7FAD28F2",
          NextDialogue = 510013013,
          SpeakNpcId = 700014,
          Subtitle = "Blasted Camilla! Stupid hag! She has no idea what good stuff is like!"
        },
        [51001302] = {
          ContentFR = "Pff ! Qu’est-ce que ça peut te faire ?",
          DialogueId = 51001302,
          GUID = "7FAD291C",
          NextDialogue = 51001304,
          SpeakNpcId = 700014,
          Subtitle = "Pah! What's it to you? Are you her lawyer? If not, mind your own business!"
        },
        [51001303] = {
          ContentFR = "Argh ! Tu vas payer pour ça ! Donne-moi ton argent ! Tu m’as presque cassé le nez !",
          DialogueId = 51001303,
          GUID = "7FAD2946",
          NextDialogue = 51001304,
          SpeakNpcId = 700014,
          Subtitle = "Ugh! You must pay for this! Nearly broke my nose, you!"
        },
        [51001304] = {
          ContentFR = "Pressé de voler à son secours, hein ? Ah ! Je vois... tu fais partie de ces imbéciles du fan-club de Camilla ! Pathétique... vous êtes tous complètement dupés par cette femme hypocrite !",
          DialogueId = 51001304,
          GUID = "7FAD2970",
          NextOptions = {
            [1] = 510013041,
            [2] = 510013042,
            [3] = 510013043
          },
          SpeakNpcId = 700014,
          Subtitle = "Quick to her defence, are we? Ah, I get it, you're one of those "Camilla fan club" idiots! Pathetic losers, all bamboozled by that phoney!",
          bForbidSkipOptions = true
        },
        [51001305] = {
          ContentFR = "Tout à l’heure tu fanfaronnais bien, et maintenant quoi ? Le froid t’a enfin réveillé les idées ? Tu vois clair dans son jeu, cette vieille peau ?",
          DialogueId = 51001305,
          GUID = "7FAD299A",
          SpeakNpcId = 700014,
          Subtitle = "What's the matter? Cat got your tongue? Has your stupidity-fueled trust started to waver at last? Wake up!"
        },
        [51001306] = {
          ContentFR = "Qu... Qu’est-ce que tu racontes...",
          DialogueId = 51001306,
          GUID = "7FAD29C4",
          NextDialogue = 510013061,
          SpeakNpcId = 700014,
          Subtitle = "An articulate argument; clearly, you're not a local. Let me guess —\nYou've never ventured beyond The Asphodel for a tipple since landing in Icelake, have you?"
        },
        [51001307] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          ContentFR = "Si tu comparais un peu, tu verrais que son alcool n’a rien à faire à Givrelac.",
          DialogueId = 51001307,
          GUID = "7FAD29EE",
          LookAt = {
            [1] = "700014:n(100001)",
            [2] = "100001:n(700014)"
          },
          NextDialogue = 51001308,
          SpeakNpcId = 700014,
          Subtitle = "If you shopped around, you'd notice that Camilla's brews are an odd fit for Icelake.",
          TalkActionId = {
            [1] = "700014:Explain01_Start"
          }
        },
        [51001308] = {
          ContentFR = "Tous les taverniers de Givrelac travaillent avec moi. Mon savoir-faire est reconnu partout ! Elle seule a refusé de rejoindre mes rangs, bornée comme pas deux ! Tu ne trouves pas ça suspect, toi ?!",
          DialogueId = 51001308,
          GUID = "7FAD2A18",
          NextDialogue = 51001309,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{700014},AnimationId{"Explain02_End"},Duration{0}}",
          SpeakNpcId = 700014,
          Subtitle = "All tavern owners but her in the city are my clients. My stuff is celebrated, but she's always turned me down. What a stubborn mule!\nThere must be something fishy in there, don't you think?!",
          TalkActionId = {
            [1] = "700014:Explain02_Start"
          }
        },
        [51001309] = {
          ContentFR = "La vérité, c’est que mon alcool coûte deux fois moins cher que celui de Camilla, et il a exactement le même goût, je le garantis ! Goûte un peu, tu verras ce que c’est qu’un vrai bon plan.",
          DialogueId = 51001309,
          GUID = "7FAD2A42",
          NextOptions = {
            [1] = 510013091,
            [2] = 510013092
          },
          Scripts = "PARA{\nCameraMoveTo{_delay{5},TargetPosition{\"87.344482,-123.555176,125.176514,0.000141,5.699588,170.405472,35.000008,177.462952,false,Manual,5.0\"},duration{0}},\nLookAt{_delay{5.2},LookAtDescription{\"100001:n(100001)\"}},\nPlayAnimation{_delay{5.5},ActorId{100001},AnimationId{\"Think_Start\"},Duration{0.5}},\nPlayAnimation{_delay{5.5},ActorId{700014},AnimationId{\"Talk01_End\"},Duration{0.5}}\n}",
          SpeakNpcId = 700014,
          Subtitle = "Fact is, my fermented drinks are half the price of Camilla's, and they taste nearly the same, I assure you!\nJust give it a try, and you'll understand what the word \"bargain\" really means.",
          TalkActionId = {
            [1] = "700014:Talk01_Start"
          }
        },
        [51001310] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          ContentFR = "Haha ! Enfin {性别:un expert|une experte}. Merci de ta confiance !",
          DialogueId = 51001310,
          GUID = "7FAD2A6C",
          NextDialogue = 51001311,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{700014},AnimationId{"Agree"},Duration{1}}",
          SpeakNpcId = 700014,
          Subtitle = "Thanks for the purchase!",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51001311] = {
          Camera = "35.446289,521.132324,214.651123,0.000094,-12.499997,-89.999947,45.0,696.082092,false,Manual,5.0",
          ContentFR = "Minute. Attends un peu.",
          DialogueId = 51001311,
          GUID = "7FAD2A96",
          LookAt = {
            [1] = "700014:n(200003)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001312,
          Scripts = "PARA{\nMoveTo{_delay{1},ActorId{200003},TargetPoint{\"PDien1\"},MoveSpeed{60},Visibility{\"Show\"}},\nSEQ{\nCameraMoveTo{_delay{1},TargetPosition{\"35.446289,521.132324,214.651123,0.000096,-10.999998,-89.999939,45.0,388.895966,false,Manual,5.0\"},duration{3}},\nCameraMoveTo{TargetPosition{\"-104.617432,-216.151855,139.375488,0.000126,-2.100092,62.600006,35.0,384.123901,false,Manual,5.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-146.654297,-177.086426,138.553223,0.000128,-0.500031,40.001247,35.0,272.58197,false,Manual,5.0\"},duration{2.5}}\n},\nTurnTo{_delay{2.5},TurnToDescription{\"100001:n(200003)\"}},\nTurnTo{_delay{5},TurnToDescription{\"700014:n(200003)\"}},\nLookAt{_delay{6.5},LookAtDescription{\"200003:n(100001)\"}},\nPlayAnimation{_delay{6.7},ActorId{200003},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200003
        },
        [51001312] = {
          ContentFR = "Petit conseil, à Givrelac, peu importe qui parle, ne crois jamais plus de la moitié de ce qu’il dit.",
          DialogueId = 51001312,
          GUID = "7FAD2AC0",
          NextDialogue = 51001315,
          SpeakNpcId = 200003
        },
        [51001313] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          ContentFR = "Mais enfin, comment tu peux savoir si tu n’essaies pas...",
          DialogueId = 51001313,
          GUID = "7FAD2AEA",
          NextDialogue = 51001314,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{700014},AnimationId{"Disagree"},Duration{1}}",
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Talk01_Start",
            [2] = "100001:Think_End"
          }
        },
        [51001314] = {
          Camera = "35.446289,521.132324,214.651123,0.000094,-12.499997,-89.999947,45.0,696.082092,false,Manual,5.0",
          ContentFR = "Pas mal. Tu as encore un minimum de bon sens, ça rassure.",
          DialogueId = 51001314,
          GUID = "7FAD2B14",
          LookAt = {
            [1] = "700014:n(200003)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001315,
          Scripts = "PARA{\nMoveTo{_delay{1},ActorId{200003},TargetPoint{\"PDien1\"},MoveSpeed{60},Visibility{\"Show\"}},\nSEQ{\nCameraMoveTo{_delay{1},TargetPosition{\"35.446289,521.132324,214.651123,0.000096,-10.999998,-89.999939,45.0,388.895966,false,Manual,5.0\"},duration{3}},\nCameraMoveTo{TargetPosition{\"-104.617432,-216.151855,139.375488,0.000126,-2.100092,62.600006,35.0,384.123901,false,Manual,5.0\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-122.449951,-202.495117,138.553223,0.000128,-1.900083,50.401207,35.0,272.58197,false,Manual,5.0\"},duration{2.5}}\n},\nTurnTo{_delay{2.5},TurnToDescription{\"100001:n(200003)\"}},\nTurnTo{_delay{5},TurnToDescription{\"700014:n(200003)\"}},\nLookAt{_delay{6.5},LookAtDescription{\"200003:n(100001)\"}},\nPlayAnimation{_delay{6.7},ActorId{200003},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 200003
        },
        [51001315] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          ContentFR = "Toi ! Qu’est-ce que tu veux encore ? Tu n’as pas mieux à faire que de saboter mon commerce ?",
          DialogueId = 51001315,
          GUID = "7FAD2B3E",
          LookAt = {
            [1] = "200003:n(700014)"
          },
          NextDialogue = 51001316,
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          }
        },
        [51001316] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          ContentFR = "Ne t’y trompe pas, ton commerce ne m’intéresse pas. Si je viens, c’est pour une autre affaire.",
          DialogueId = 51001316,
          GUID = "7FAD2B68",
          NextDialogue = 51001317,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200003},AnimationId{"Disagree"},Duration{1}}",
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_End",
            [2] = "700014:Angry01_End"
          },
          TurnTo = {
            [1] = "100001:p(-30)"
          }
        },
        [51001317] = {
          ContentFR = "Depuis quelque temps, certains vendent de la camelote sous mon nom. Ils prétendent que c’est la nouvelle « spécialité des Asphodèles », ou que « ça s’arrache au comptoir, même pas le temps d’y goûter ».",
          DialogueId = 51001317,
          GUID = "7FAD2B92",
          NextDialogue = 51001318,
          Scripts = "PlayAnimation{_delay{3},ActorId{200003},AnimationId{"Explain01_End"},Duration{1}}",
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001318] = {
          ContentFR = "Or, dans les affaires, tout repose sur la réputation. La qualité de nos boissons, c’est l’image des Asphodèles. Je ne peux pas laisser des escrocs la salir.",
          DialogueId = 51001318,
          GUID = "7FAD2BBC",
          NextDialogue = 51001319,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51001319] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          ContentFR = "Et... Et qu’est-ce que ça a à voir avec moi ? J’ai pas le temps de régler tes histoires !",
          DialogueId = 51001319,
          GUID = "7FAD2BE6",
          NextDialogue = 51001320,
          Scripts = "PlayAnimation{_delay{3},ActorId{700014},AnimationId{"Sigh_End"},Duration{1}}",
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Sigh_Start"
          }
        },
        [51001320] = {
          ContentFR = "Allez, dégage, moi j’ai un commerce à faire tourner !",
          DialogueId = 51001320,
          GUID = "7FAD2C10",
          NextDialogue = 51001321,
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Confident_Start"
          }
        },
        [51001321] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          ContentFR = "Pas si vite. Quand les Asphodèles ont refusé ton offre, j’ai fait garder un échantillon de ta marchandise. Devine quoi ?",
          DialogueId = 51001321,
          GUID = "7FAD2C3A",
          NextDialogue = 51001322,
          SpeakNpcId = 200003
        },
        [51001322] = {
          ContentFR = "Tes bouteilles ont exactement la même composition que ces contrefaçons. Tu crois vraiment que c’est un hasard ?",
          DialogueId = 51001322,
          GUID = "7FAD2C64",
          NextDialogue = 51001323,
          SpeakNpcId = 200003
        },
        [51001323] = {
          Camera = "-209.837891,-298.262207,123.758301,0.000147,1.099674,42.806149,35.000008,408.143951,false,Manual,5.0",
          ContentFR = "Qu’est-ce que tu insinues ?! Tu mens ! Moi, vendre des faux ?! Tu racontes ça juste parce que tu crains que ma gnôle te pique tes clients !",
          DialogueId = 51001323,
          GUID = "7FAD2C8E",
          NextOptions = {
            [1] = 510013231,
            [2] = 510013232
          },
          Scripts = "PARA{\n\nCameraMoveTo{_delay{5},TargetPosition{\"87.344482,-123.555176,125.176514,0.000141,5.699588,170.405472,35.000008,177.462952,false,Manual,5.0\"},duration{0}},\nMoveTo{_delay{6},ActorId{200003},TargetPoint{\"PDien1\"},MoveSpeed{10},Visibility{\"Hide\"}},\nTurnTo{_delay{6},TurnToDescription{\"700014:p(60)\"}},\nLookAt{_delay{6},LookAtDescription{\"100001:n(700014)\"}},\nLookAt{_delay{7},LookAtDescription{\"100001:n(100001)\"}},\nPlayAnimation{_delay{7.2},ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}}\n}",
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          bForbidSkipOptions = true
        },
        [51001324] = {
          Camera = "-126.292969,-236.144531,121.561768,0.000212,4.098496,38.002239,35.0,288.862579,false,Manual,5.0",
          ContentFR = "Faux alcool ?! Tu traites mes produits de faux ?! J’ai compris. Vous êtes de mèche {性别:tous|toutes} les deux, à me salir exprès !",
          DialogueId = 51001324,
          GUID = "7FAD2CB8",
          LookAt = {
            [1] = "700014:n(100001)"
          },
          NextDialogue = 51001325,
          SpeakNpcId = 700014
        },
        [51001325] = {
          Camera = "186.59668,149.714844,103.179443,0.000225,1.098103,-121.993439,35.0,286.170746,false,Manual,5.0",
          ContentFR = "Très bien ! Je vais vous prouver que c’est pas du faux !",
          DialogueId = 51001325,
          FinalCamera = "202.597412,139.721191,94.749023,0.000225,1.098103,-121.993439,35.0,166.090637,false,Manual,5.0",
          GUID = "7FAD2CE2",
          NextDialogue = 51001327,
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51001326] = {
          Camera = "-126.292969,-236.144531,121.561768,0.000212,4.098496,38.002239,35.0,288.862579,false,Manual,5.0",
          ContentFR = "Boire ? ... Très bien ! Je vais lui montrer !",
          DialogueId = 51001326,
          GUID = "7FAD2D0C",
          LookAt = {
            [1] = "700014:n(100001)"
          },
          NextDialogue = 51001327,
          SpeakNpcId = 700014
        },
        [51001327] = {
          ContentFR = "Dean saisit un tonneau à deux mains et se met à boire à grandes gorgées.",
          DialogueId = 51001327,
          GUID = "7FAD2D36",
          IsBlack = 1,
          LookAt = {
            [1] = "200003:n(700014)",
            [2] = "100001:n(700014)"
          },
          NextDialogue = 51001328,
          Scripts = "MoveTo{ActorId{200003},TargetPoint{"PDien1"},MoveSpeed{100},Visibility{"Show"}}"
        },
        [51001328] = {
          Camera = "-58.997803,-300.757812,211.441162,0.000378,-35.900509,52.402233,35.000008,288.862579,false,Manual,5.0",
          ContentFR = "Mais avant même d’avoir fini, son corps vacille comme frappé d’un coup de poing. Il s’effondre lourdement, tandis que le liquide renversé empeste la pièce.",
          DialogueId = 51001328,
          FinalCamera = "-163.664062,-436.681641,303.508057,0.000378,-35.900513,52.404461,35.000008,288.862579,false,Manual,5.0",
          GUID = "7FAD2D60",
          LookAt = {
            [1] = "700014:n(700014)"
          },
          NextOptions = {
            [1] = 510013281
          },
          TalkActionId = {
            [1] = "700014:Onground02",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10
        },
        [51001329] = {
          Camera = "-139.912598,-187.989746,131.374023,0.00013,0.499936,50.203888,35.0,272.58197,false,Manual,5.0",
          ContentFR = "Je l’avais dit, Givrelac n’est pas une cité paisible. Ici, il faut toujours garder l’œil ouvert si tu veux survivre.",
          DialogueId = 51001329,
          GUID = "7FAD2D8A",
          LookAt = {
            [1] = "200003:n(100001)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001330,
          SpeakNpcId = 200003,
          TurnTo = {
            [1] = "100001:p(30)"
          }
        },
        [51001330] = {
          ContentFR = "Hélas... si on le laisse là, il risque d’y passer. Autant le faire conduire à l’hôpital. Ensuite, je réglerai mes comptes avec lui.",
          DialogueId = 51001330,
          GUID = "7FAD2DB4",
          NextDialogue = 51001331,
          SpeakNpcId = 200003
        },
        [51001331] = {
          ContentFR = "Et si un jour tu veux boire autre chose que la "bonne affaire" de Dean, les Asphodèles t’accueilleront toujours. Chez nous, la qualité vaut son prix.",
          DialogueId = 51001331,
          GUID = "7FAD2DDE",
          SpeakNpcId = 200003
        },
        [51001332] = {
          ContentFR = "Le meilleur alcool de la région ? C’est bien sûr aux Asphodèles.",
          DialogueId = 51001332,
          GUID = "7FAD2E08",
          NextDialogue = 51001333,
          SpeakNpcId = 790009,
          TalkActionId = {
            [1] = "790009:Talk02_Start"
          }
        },
        [51001333] = {
          ContentFR = "Ici, le parfum est enivrant, le goût riche et rond. Et surtout... une douceur en bouche, un arrière-goût qui s’attarde longtemps.",
          DialogueId = 51001333,
          GUID = "7FAD2E32",
          NextDialogue = 51001334,
          SpeakNpcId = 790009
        },
        [51001334] = {
          ContentFR = "On dit que le bon vin est le plus cruel des amants... ah, il m’en faut encore un verre...",
          DialogueId = 51001334,
          GUID = "7FAD2E5C",
          SpeakNpcId = 790009,
          TalkActionId = {
            [1] = "790009:Talk02_End"
          }
        },
        [51001335] = {
          ContentFR = "Tu crois que les Asphodèles, c’est juste pour les boissons ? Détrompe-toi.",
          DialogueId = 51001335,
          GUID = "7FAD2E86",
          NextDialogue = 51001336,
          SpeakNpcId = 790010,
          TalkActionId = {
            [1] = "790010:Talk03_Start"
          }
        },
        [51001336] = {
          ContentFR = "Ici, tu n’as pas à craindre d’être embarqué dans une bagarre d’ivrognes, ni de te faire cogner par un fou sorti de nulle part.",
          DialogueId = 51001336,
          GUID = "7FAD2EB0",
          NextDialogue = 51001337,
          SpeakNpcId = 790010
        },
        [51001337] = {
          ContentFR = "C’est le territoire de Camilla. Son nom suffit à faire taire les fauteurs de trouble.",
          DialogueId = 51001337,
          GUID = "7FAD2EDA",
          SpeakNpcId = 790010,
          TalkActionId = {
            [1] = "790010:Talk03_End"
          }
        },
        [51001338] = {
          ContentFR = "Snif... snif snif...",
          DialogueId = 51001338,
          GUID = "7FAD2F04",
          NextDialogue = 51001339,
          SpeakNpcId = 790011,
          TalkActionId = {
            [1] = "790011:Sigh_Start"
          }
        },
        [51001339] = {
          ContentFR = "L’amour... quel goût a-t-il vraiment ? Était-ce l’extase quand j’ai rejoint le Fan Club de Camilla ? Ou bien le chagrin écrasant quand j’ai appris qu’elle l’avait dissous ?",
          DialogueId = 51001339,
          GUID = "7FAD2F2E",
          NextDialogue = 51001340,
          SpeakNpcId = 790011
        },
        [51001340] = {
          ContentFR = "Snif... seul le sourire de Dame Camilla pourra recoller les morceaux de mon cœur brisé !",
          DialogueId = 51001340,
          GUID = "7FAD2F58",
          SpeakNpcId = 790011,
          TalkActionId = {
            [1] = "790011:Sigh_End"
          }
        },
        [51001401] = {
          ContentFR = "« Sous la pluie, les fleurs de maman se sont fanées... Alors le ciel a semé de petites fleurs dans les flaques, pour lui présenter ses excuses. »",
          DialogueId = 51001401,
          GUID = "7FAD395A",
          NextDialogue = 51001402,
          SpeakNpcId = 700017,
          Subtitle = ""The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles."",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          }
        },
        [51001402] = {
          ContentFR = "Vous savez ? Ce petit poème s’intitule Excuses, et il a été écrit par l’un de mes élèves... il n’a que six ans.",
          DialogueId = 51001402,
          GUID = "7FAD3984",
          NextOptions = {
            [1] = 510014021,
            [2] = 510014022,
            [3] = 510014023
          },
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called "Apology", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51001403] = {
          ContentFR = "Autour de Sunny, les enfants portent des vêtements élégants : à n’en pas douter, ils sont issus de familles nobles.",
          DialogueId = 51001403,
          GUID = "7FAD39AE",
          NextDialogue = 51001404,
          Subtitle = "(The children around Sunny are in finery, presumably from aristocratic families.)"
        },
        [51001404] = {
          ContentFR = "Haha, pour tout vous dire, ce n’est pas le seul poème de ce genre. Leur créativité me surprend toujours autant.",
          DialogueId = 51001404,
          GUID = "7FAD39D8",
          NextDialogue = 51001405,
          SpeakNpcId = 700017,
          Subtitle = "Haha, actually, there are many more like this one, and their creativity never ceases to amaze me.",
          TalkActionId = {
            [1] = "700017:Explain01_Start"
          }
        },
        [51001405] = {
          ContentFR = "J’ai toujours pensé qu’une imagination débordante et une créativité sans limite... c’est ce qu’il y a de plus précieux chez un enfant.",
          DialogueId = 51001405,
          GUID = "7FAD3A02",
          NextDialogue = 51001406,
          SpeakNpcId = 700017,
          Subtitle = "I've always believed that unfettered creativity and imagination are a child's most precious qualities.",
          TalkActionId = {
            [1] = "700017:Explain01_End"
          }
        },
        [51001406] = {
          ContentFR = "Mais pour les nobles, une enseignante comme moi est sans doute la moins compétente qu’on puisse trouver.",
          DialogueId = 51001406,
          GUID = "7FAD3A2C",
          NextOptions = {
            [1] = 510014061
          },
          RestartTag = 51001406,
          SpeakNpcId = 700017,
          Subtitle = "It's just that, to the nobility, a tutor like me is deemed quite incompetent.",
          bForbidSkipOptions = true
        },
        [51001407] = {
          ContentFR = "Oh, l’heure du cours approche, je ne peux pas m’attarder davantage.",
          DialogueId = 51001407,
          GUID = "7FAD3A56",
          NextDialogue = 51001408,
          SpeakNpcId = 700017,
          Subtitle = "Ah, it's nearly time for class. Excuse me, I have to go now."
        },
        [51001408] = {
          ContentFR = "Sunny jette un coup d’œil à sa montre, s’excuse d’un signe de tête et s’éloigne en hâte.",
          DialogueId = 51001408,
          GUID = "7FAD3A80",
          SpeakNpcId = 700017,
          Subtitle = "(Sunny glanced at her pocket watch, excused herself, and hurried off.)"
        },
        [51001409] = {
          ContentFR = "Haha... merci pour vos paroles. Je n’ai jamais regretté mon choix, même si cela devait me coûter mon emploi.",
          DialogueId = 51001409,
          GUID = "7FAD3AAA",
          NextDialogue = 51001410,
          SpeakNpcId = 700017,
          Subtitle = "Haha, thank you. I've never once regretted my choice, even if it costs me my job.",
          TalkActionId = {
            [1] = "700017:Agree"
          }
        },
        [51001410] = {
          ContentFR = "Après mon départ, mes élèves devront se consacrer à la récitation des Lois Impériales et à la préparation des examens de la Légion.",
          DialogueId = 51001410,
          GUID = "7FAD3AD4",
          NextDialogue = 51001411,
          SpeakNpcId = 700017,
          Subtitle = "In the future, my students will have to embark on a path filled with Imperial Law recitations and military test preparations."
        },
        [51001411] = {
          ContentFR = "C’est ma dernière leçon. Je dois leur dire que, peu importe la dureté ou la monotonie de la réalité qu’ils auront à affronter... je serai toujours fière de leurs rêves.",
          DialogueId = 51001411,
          GUID = "7FAD3AFE",
          NextDialogue = 51001490,
          SpeakNpcId = 700017,
          Subtitle = "This being our final lesson, I must let them know — no matter the cruelty or drudgery of the reality ahead,\nI'll forever be proud of their dreams.",
          TalkActionId = {
            [1] = "700083:Think_End",
            [2] = "700084:Think_End",
            [3] = "700085:Confident_End"
          }
        },
        [51001412] = {
          ContentFR = "Bien sûr ! J’ai reçu le plus beau cadeau du monde !",
          DialogueId = 51001412,
          GUID = "7FAD3B28",
          NextDialogue = 51001413,
          SpeakNpcId = 700017,
          Subtitle = "Absolutely! I've received the most amazing gift in the world!",
          TalkActionId = {
            [1] = "700017:Agree"
          }
        },
        [51001413] = {
          ContentFR = "« Ma professeure dit que je suis une étoile dans le ciel, et qu’elle n’est que mon reflet dans la mer. »",
          DialogueId = 51001413,
          GUID = "7FAD3B52",
          NextDialogue = 51001414,
          SpeakNpcId = 700017,
          Subtitle = ""My teacher says I'm a star in the sky, and she's just my reflection in the sea at night."",
          TalkActionId = {
            [1] = "700017:Explain01_Start"
          }
        },
        [51001414] = {
          ContentFR = "« Mais entre le ciel et la mer, il y a dix mille mètres... Ce n’est pas bien. »",
          DialogueId = 51001414,
          GUID = "7FAD3B7C",
          NextDialogue = 51001415,
          SpeakNpcId = 700017,
          Subtitle = ""But heavens and seas are so far apart — that doesn't seem right.""
        },
        [51001415] = {
          ContentFR = "Alors j’ai dit : « Regarde ! Une étoile filante ! »",
          DialogueId = 51001415,
          GUID = "7FAD3BA6",
          NextDialogue = 51001416,
          SpeakNpcId = 700017,
          Subtitle = ""So I say: 'Look! A shooting star zooming by!'"",
          TalkActionId = {
            [1] = "700017:Explain01_End"
          }
        },
        [51001416] = {
          ContentFR = "Vous savez ? Ce petit poème s’intitule Rencontre, et il a été écrit par l’un de mes élèves de six ans.",
          DialogueId = 51001416,
          GUID = "7FAD3BD0",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called "Come to You", and it's written by a six-year-old student of mine."
        },
        [51001417] = {
          ContentFR = "Je me demande ce que font ces enfants, maintenant... Ils ont sûrement bien grandi.",
          DialogueId = 51001417,
          GUID = "7FAD3BFA",
          SpeakNpcId = 700017,
          Subtitle = "I wonder what those kids have been up to lately. They must have grown taller, haven't they?"
        },
        [51001490] = {
          ContentFR = "À la fin du cours, les enfants agitent leurs petites mains pour dire au revoir. Sunny les regarde s’éloigner, un sourire attendri aux lèvres.",
          DialogueId = 51001490,
          GUID = "7FAD47F4",
          NextOptions = {
            [1] = 510014901,
            [2] = 510014902
          },
          Scripts = "PARA{\nMoveTo{ActorId{700083},MoveSpeed{150},TargetPoint{\"Point_Sangni_nearby_YNF01\"},Visibility{\"Hide\"}},\nMoveTo{ActorId{700084},MoveSpeed{150},TargetPoint{\"Point_Sangni_nearby_YNF02\"},Visibility{\"Hide\"}},\nMoveTo{ActorId{700085},MoveSpeed{150},TargetPoint{\"Point_Sangni_nearby_YNM01\"},Visibility{\"Hide\"}}\n}",
          Subtitle = "(As Sunny's class concluded, the children waved goodbye. Sunny smiles warmly as she watches them leave.)",
          bForbidSkipOptions = true
        },
        [51001501] = {
          ContentFR = "Argh... pourquoi ces taches de sang ne veulent-elles pas partir ?",
          DialogueId = 51001501,
          GUID = "7FAD49C2",
          NextDialogue = 51001502,
          SpeakNpcId = 700067,
          Subtitle = "Ugh... why won't this bloodstain come off?",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          }
        },
        [51001502] = {
          ContentFR = "Si je ne nettoie pas ça, je vais encore me faire frapper et insulter...",
          DialogueId = 51001502,
          GUID = "7FAD49EC",
          SpeakNpcId = 700067,
          Subtitle = "I don't wanna get beaten up for this again...",
          TalkActionId = {
            [1] = "700067:Sigh_End"
          },
          TalkOptions = {
            [1] = 510015021,
            [2] = 510015022,
            [3] = 510015023
          }
        },
        [51001503] = {
          ContentFR = "Quoi ? Qu’est-ce que tu racontes ?",
          DialogueId = 51001503,
          GUID = "7FAD4A16",
          NextDialogue = 51001504,
          SpeakNpcId = 700067,
          Subtitle = "What was that?"
        },
        [51001504] = {
          ContentFR = "Pff... je n’ai pas la tête à discuter. Attends que j’aie fini de nettoyer.",
          DialogueId = 51001504,
          GUID = "7FAD4A40",
          NextDialogue = 51001505,
          SpeakNpcId = 700067,
          Subtitle = "Oof, I'm swamped right now. Maybe talk to me after I'm done cleaning."
        },
        [51001505] = {
          ContentFR = "L’homme frotte avec acharnement, poussant la serpillière rêche d’un geste épuisé. Ce n’est qu’au bord de l’effondrement qu’il parvient enfin à faire disparaître la tache.",
          DialogueId = 51001505,
          GUID = "7FAD4A6A",
          NextDialogue = 51001506,
          Subtitle = "(He scrubs hard with the rough cloth, over and over, finally removing the bloodstain just as he's about to collapse from exhaustion.)"
        },
        [51001506] = {
          ContentFR = "Pfiou... Ces deux-là se sont battus avec une violence inouïe. Il y avait du sang partout... quelle horreur à nettoyer.",
          DialogueId = 51001506,
          GUID = "7FAD4A94",
          NextDialogue = 51001507,
          SpeakNpcId = 700067,
          Subtitle = "*sigh* That fight earlier was brutal, blood splattered everywhere. Such a nightmare to clean up.",
          TalkActionId = {
            [1] = "700067:Talk01_Start"
          }
        },
        [51001507] = {
          ContentFR = "C’est plus facile quand c’est une exécution nette, ou avec du poison... Au moins, il n’y a presque pas de sang.",
          DialogueId = 51001507,
          GUID = "7FAD4ABE",
          SpeakNpcId = 700067,
          Subtitle = "Much easier when it's a quick kill, or with poison — hardly any mess.",
          TalkActionId = {
            [1] = "700067:Talk01_End"
          },
          TalkOptions = {
            [1] = 510015071
          }
        },
        [51001508] = {
          ContentFR = "Et alors ? Facile de faire la morale quand on n’est pas à ma place. Occupe-toi de tes affaires.",
          DialogueId = 51001508,
          GUID = "7FAD4AE8",
          SpeakNpcId = 700067,
          Subtitle = "Who asked you? Easy to judge when you're not in my shoes. Mind your own business!"
        },
        [51001509] = {
          ContentFR = "Qu’est-ce que tu veux que j’y fasse ? Quand c’est sale, il faut nettoyer. Et si ce n’est pas bien fait, c’est coups et insultes.",
          DialogueId = 51001509,
          GUID = "7FAD4B12",
          NextDialogue = 51001510,
          SpeakNpcId = 700067,
          Subtitle = "What choice do I have? When the floor's dirty, I gotta clean it, or it's beatings and scoldings for me.",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          }
        },
        [51001510] = {
          ContentFR = "Au début, j’avais de la peine pour eux... mais on ne peut pas tout supporter. J’essaie déjà de rester en vie, alors le reste...",
          DialogueId = 51001510,
          GUID = "7FAD4B3C",
          NextDialogue = 51001511,
          SpeakNpcId = 700067,
          Subtitle = "I used to feel sorry for them, but there's only so much sympathy to go around.\nI'm struggling to keep myself alive — can't afford to worry about others!",
          TalkActionId = {
            [1] = "700067:Sigh_End"
          }
        },
        [51001511] = {
          ContentFR = "Avec le temps, le sang n’est plus qu’un liquide rouge. S’endurcir, c’est plus simple... sinon, la vie devient impossible.",
          DialogueId = 51001511,
          GUID = "7FAD4B66",
          NextDialogue = 51001512,
          SpeakNpcId = 700067,
          Subtitle = "Over time, blood's just another red spill to me. Being numb helps me make it through the day...",
          TalkActionId = {
            [1] = "700067:Explain01_Start"
          }
        },
        [51001512] = {
          ContentFR = "Bon, assez parlé. J’ai encore une autre zone à nettoyer...",
          DialogueId = 51001512,
          GUID = "7FAD4B90",
          SpeakNpcId = 700067,
          Subtitle = "Alright, I should get back to work. There's another mess waiting for me...",
          TalkActionId = {
            [1] = "700067:Explain01_End"
          }
        },
        [51001513] = {
          ContentFR = "Bon, assez parlé. J’ai encore une autre zone à nettoyer...",
          DialogueId = 51001513,
          GUID = "7FAD4BBA",
          SpeakNpcId = 700067,
          Subtitle = "Alright, I should get back to work. There’s another mess waiting for me..."
        },
        [51001601] = {
          ContentFR = "Dégage, sale Charon !",
          DialogueId = 51001601,
          GUID = "7FAD5A2A",
          NextDialogue = 51001602,
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!"
        },
        [51001602] = {
          ContentFR = "Devant toi, un homme Charon vêtu d’un uniforme en lambeaux fixe les passants d’un regard chargé de haine.",
          DialogueId = 51001602,
          GUID = "7FAD5A54",
          NextOptions = {
            [1] = 510016021,
            [2] = 510016022,
            [3] = 510016023
          },
          Subtitle = "(Dressed in ragged military garb, the Charon man before you sends menacing glares towards the passersby.)",
          bForbidSkipOptions = true
        },
        [51001603] = {
          ContentFR = "Hé ! Qu’est-ce que tu fais ?! Tu veux te battre ou quoi ?!",
          DialogueId = 51001603,
          GUID = "7FAD5A7E",
          NextDialogue = 51001604,
          SpeakNpcId = 700068,
          Subtitle = "Oi! What are you doing?! Looking for trouble?!"
        },
        [51001604] = {
          ContentFR = "Toi aussi, tu as des cornes... comme nous.",
          DialogueId = 51001604,
          GUID = "7FAD5AA8",
          NextDialogue = 51001608,
          SpeakNpcId = 100001,
          Subtitle = "You've got horns too, just like us."
        },
        [51001605] = {
          ContentFR = "Oh, {性别:quel grand saint|quelle grande sainte} tu fais ! Va donc prêcher ça au Bureau de la Sécurité, ils sauront te faire taire.",
          DialogueId = 51001605,
          GUID = "7FAD5AD2",
          NextDialogue = 51001606,
          SpeakNpcId = 700068,
          Subtitle = "Look at that, a saint here! Why not enlighten the security bureau with your little sermon?\nMaybe they'll reward you with a free lesson on how to watch your mouth."
        },
        [51001606] = {
          ContentFR = "Et tu crois vraiment qu’ils te traiteraient avec respect si tu étais à ma place ?",
          DialogueId = 51001606,
          GUID = "7FAD5AFC",
          NextDialogue = 51001608,
          SpeakNpcId = 100001,
          Subtitle = "Think the security bureau would show you any respect if you were in my shoes?"
        },
        [51001607] = {
          ContentFR = "Un Charon, moi aussi ? Tu plaisantes ? Tu crois qu’on est pareils, toi et moi ? Quelle blague !",
          DialogueId = 51001607,
          GUID = "7FAD5B26",
          NextDialogue = 51001608,
          SpeakNpcId = 700068,
          Subtitle = "How dare you! Who do you think you're talking to? You think you and I are the same kind?"
        },
        [51001608] = {
          ContentFR = "Tu veux que je te dise ? Tous les Charons ne se ressemblent pas !",
          DialogueId = 51001608,
          GUID = "7FAD5B50",
          NextDialogue = 51001609,
          SpeakNpcId = 700068,
          Subtitle = "For your information, we Charons aren't all cut from the same cloth!"
        },
        [51001609] = {
          ContentFR = "Depuis que je suis gamin, je m’impose les standards des Solariens. Je n’ai jamais traîné avec les autres Charons. Tu en connais beaucoup, toi, des Charons qui parlent comme moi ? Je te le dis : c’est un accent dismanien parfait.",
          DialogueId = 51001609,
          GUID = "7FAD5B7A",
          NextDialogue = 51001691,
          SpeakNpcId = 700068,
          Subtitle = "Since I was a kid, I've held myself to human standards, and never mingled with other Charons.\nEver met a Charon who speaks like I do? Just so you know, this is a standard Dismania accent!"
        },
        [51001610] = {
          ContentFR = "Tu es {性别:jaloux|jalouse}, hein ? C’est bien mérité !",
          DialogueId = 51001610,
          GUID = "7FAD5BA4",
          NextDialogue = 51001692,
          SpeakNpcId = 700068,
          Subtitle = "Jealous, huh? Well, I've earned this!"
        },
        [51001611] = {
          ContentFR = "Tu comprends maintenant ? Je suis bien plus Sola que n’importe lequel d’entre vous. C’est pour ça que je suis devenu officier, pendant que toi, tu traînes en haillons comme {性别:un mendiant|une mendiante}.",
          DialogueId = 51001611,
          GUID = "7FAD5BCE",
          NextDialogue = 51001612,
          SpeakNpcId = 700068,
          Subtitle = "Got it? I'm more human than any of you could ever be, that's why I've become an officer, while you roam around in rags like a beggar."
        },
        [51001612] = {
          ContentFR = "Allez, assez perdu de temps. Si je discute avec toi, c’est uniquement parce que j’ai le cœur aussi noble que celui d’un Sola. Considère ça comme une leçon gratuite. Maintenant, dégage et va mendier ailleurs, je ne veux plus te voir, tu me portes malheur.",
          DialogueId = 51001612,
          GUID = "7FAD5BF8",
          NextOptions = {
            [1] = 510016121
          },
          RestartTag = 51001612,
          SpeakNpcId = 700068,
          Subtitle = "Alright, I've indulged you this long only because my heart's as big as any human's. Consider this as a gratis lesson for you Charons.\nNow shoo, take your lowlife vibes away from me.",
          bForbidSkipOptions = true
        },
        [51001613] = {
          ContentFR = "Hein ? Qu’est-ce que tu viens de dire ?",
          DialogueId = 51001613,
          GUID = "7FAD5C22",
          NextDialogue = 51001614,
          SpeakNpcId = 700068,
          Subtitle = "Huh? What did you say?"
        },
        [51001614] = {
          ContentFR = "J’ai entendu dire qu’Hyperborea décernait un titre prestigieux, celui de Charon Couronné, aux plus méritants.",
          DialogueId = 51001614,
          GUID = "7FAD5C4C",
          NextDialogue = 51001615,
          SpeakNpcId = 100001,
          Subtitle = "I've heard about this "Laurelled Charon" medal that Hyperborea grants to the most distinguished Charons."
        },
        [51001615] = {
          ContentFR = "Un officier aussi vaillant, loyal et à l’accent irréprochable que toi doit forcément en avoir une. J’aimerais tellement la voir de mes propres yeux.",
          DialogueId = 51001615,
          GUID = "7FAD5C76",
          NextDialogue = 51001616,
          SpeakNpcId = 100001,
          Subtitle = "Someone as brave, loyal, and with an impeccable accent like you must have one. I'd be thrilled to finally see it!"
        },
        [51001616] = {
          ContentFR = "... Je... je l’ai oubliée chez moi ! Une autre fois !",
          DialogueId = 51001616,
          GUID = "7FAD5CA0",
          NextDialogue = 51001617,
          SpeakNpcId = 700068,
          Subtitle = "...I... must've left it at home! Maybe next time!"
        },
        [51001617] = {
          ContentFR = "Vraiment ? Je vous admire, mon officier !",
          DialogueId = 51001617,
          GUID = "7FAD5CCA",
          NextDialogue = 51001693,
          SpeakNpcId = 100001,
          Subtitle = "Is that so? I truly admire you, sir!"
        },
        [51001618] = {
          ContentFR = "Bien sûr que oui !",
          DialogueId = 51001618,
          GUID = "7FAD5CF4",
          NextDialogue = 51001619,
          SpeakNpcId = 700068,
          Subtitle = "Of course!"
        },
        [51001619] = {
          ContentFR = "On dit aussi qu’il y a là-bas une célèbre fontaine appelée « Mythaine »...",
          DialogueId = 51001619,
          GUID = "7FAD5D1E",
          NextDialogue = 51001620,
          SpeakNpcId = 100001,
          Subtitle = "There's that famous "Maidé Upp" fountain in the inner city, isn't there?"
        },
        [51001620] = {
          ContentFR = "Je n’aurai sans doute jamais la chance d’y mettre les pieds. Dis-moi au moins, la statue près de la fontaine, c’est un lion ou un loup ? S’il te plaît, je veux vraiment savoir !",
          DialogueId = 51001620,
          GUID = "7FAD5D48",
          NextDialogue = 51001621,
          SpeakNpcId = 100001,
          Subtitle = "A lowly Charon like me will probably never get to see it. Could you tell me if the statue by the fountain is a lion or a wolf\nPlease, sir, I'm dying to be enlightened!"
        },
        [51001621] = {
          ContentFR = "Laisse-moi réfléchir... Oui, c’est un lion. Un lion, évidemment !",
          DialogueId = 51001621,
          GUID = "7FAD5D72",
          NextDialogue = 51001622,
          SpeakNpcId = 700068,
          Subtitle = "Err... it's... a lion. Right, a lion!"
        },
        [51001622] = {
          ContentFR = "Officier... tu es sûr ? Un ami m’a dit que...",
          DialogueId = 51001622,
          GUID = "7FAD5D9C",
          NextDialogue = 51001623,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure, sir? Because a friend of mine said..."
        },
        [51001623] = {
          ContentFR = "Ah, non, attends... Je n’ai pas bien dormi cette nuit, j’ai mal à la tête. Maintenant que j’y pense, c’est un loup ! Oui, un loup — je suis passé devant ce matin même, {性别:satisfait|satisfaite} ?",
          DialogueId = 51001623,
          GUID = "7FAD5DC6",
          NextDialogue = 51001624,
          SpeakNpcId = 700068,
          Subtitle = "Ah, wait... had a rough night, headache's killing me! Now that I think about it, it's a wolf — walked by it just this morning, happy now?"
        },
        [51001624] = {
          ContentFR = "Un sourire admiratif reste figé sur ton visage, mais dans ta tête, mille émotions s’entrechoquent : d’abord la colère, puis l’incompréhension, pour ne laisser place qu’à la pitié.",
          DialogueId = 51001624,
          GUID = "7FAD5DF0",
          NextDialogue = 51001625,
          Subtitle = "(A veneer of admiration remains on your face, yet a whirlwind of emotions sweeps through your mind—)\n(from initial anger to bewilderment, settling finally on pity.)"
        },
        [51001625] = {
          ContentFR = "J’ai bien peur que ta mémoire te joue vraiment des tours... Parce que la fontaine « Mythaine », je l’ai inventée. Elle n’existe pas.",
          DialogueId = 51001625,
          GUID = "7FAD5E1A",
          NextDialogue = 51001626,
          SpeakNpcId = 100001,
          Subtitle = "Seems your memory's still playing tricks on you. Because there's no "Maidé Upp" fountain — it's actually a made-up fountain."
        },
        [51001626] = {
          ContentFR = "Espèce de... de {性别:petit insolent|petite insolente}... ! Tu oses te moquer de moi ?!",
          DialogueId = 51001626,
          GUID = "7FAD5E44",
          NextDialogue = 51001627,
          SpeakNpcId = 700068,
          Subtitle = "You crafty little twerp...! How dare you—!"
        },
        [51001627] = {
          ContentFR = "Ayant anticipé sa réaction, tu esquives sans peine le coup de poing qu’il t’adresse, ivre de rage.",
          DialogueId = 51001627,
          GUID = "7FAD5E6E",
          NextDialogue = 51001628,
          Subtitle = "(Anticipating his move, you nimbly dodged the man's furious punch.)"
        },
        [51001628] = {
          ContentFR = "Au revoir, mon officier. La prochaine fois, j’espère que tu pourras encore m’apprendre des choses sur la cité intérieure.",
          DialogueId = 51001628,
          GUID = "7FAD5E98",
          SpeakNpcId = 100001,
          Subtitle = "Goodbye, sir. Hope I can pick your brain about the inner city again some other time."
        },
        [51001629] = {
          ContentFR = "DÉGAGE ! Je ne veux plus jamais te voir ! DÉGAGE !",
          DialogueId = 51001629,
          GUID = "7FAD5EC2",
          SpeakNpcId = 700068,
          Subtitle = "Scram!! Don't let me catch sight of you again!! Beat it!!!"
        },
        [51001690] = {
          ContentFR = "Quoi ? Encore toi ? Je t’ai pourtant dit de déguerpir !",
          DialogueId = 51001690,
          GUID = "7FAD68C4",
          SpeakNpcId = 700068,
          Subtitle = "What, you again? Didn't I tell you to get out of my sight?"
        },
        [51001691] = {
          ContentFR = "Mes amis Solariens disent qu’à m’entendre, ils ne devineraient jamais que je suis un Charon. Ils disent que je parle exactement comme eux.",
          DialogueId = 51001691,
          GUID = "7FAD68EE",
          NextDialogue = 51001610,
          SpeakNpcId = 700068,
          Subtitle = "My human friends all say they can't tell that I'm actually a Charon from the way I speak. They say I sound just like one of them."
        },
        [51001692] = {
          ContentFR = "Pendant trois ans, tous les matins, je lisais L’Actualité d’Hyperborea pendant deux heures, à corriger mon accent... et à lire les horreurs commises par ces minables Charons, ces incapables que nous sommes censés être.",
          DialogueId = 51001692,
          GUID = "7FAD6918",
          NextDialogue = 51001611,
          SpeakNpcId = 700068,
          Subtitle = "For three years straight, I'd start every morning reading \"Hyperborean News\" for two hours,\nfine-tuning my accent while cringing at the crimes some Charon had disgracefully committed."
        },
        [51001693] = {
          ContentFR = "On raconte que les Charons Couronnés ont le droit de résider dans la cité intérieure. Tu dois sûrement y posséder un manoir splendide, comme dans les contes — avec des majordomes et des domestiques par dizaines !",
          DialogueId = 51001693,
          GUID = "7FAD6942",
          NextDialogue = 51001618,
          SpeakNpcId = 100001,
          Subtitle = "I've heard that Laurelled Charons are entitled to live in the inner city. You must own a splendid mansion there,\nlike something out of a storybook — with legions of butlers and servants!"
        },
        [51001701] = {
          ContentFR = "La canalisation n° 13 est en réparation. Bon sang... il y a bien trop de rats là-dedans.",
          DialogueId = 51001701,
          GUID = "7FAD6A92",
          NextDialogue = 51001702,
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          }
        },
        [51001702] = {
          ContentFR = "Dutton lève les yeux vers toi. Une odeur nauséabonde s’échappe de ses vêtements, si forte que tu recules instinctivement d’un pas, luttant contre la nausée.",
          DialogueId = 51001702,
          GUID = "7FAD6ABC",
          NextDialogue = 51001703,
          Subtitle = "(Dutton looks up, reeking so strongly that you're forced to step back. You manage to stifle a gag.)",
          TalkActionId = {
            [1] = "700069:Sigh_End"
          }
        },
        [51001703] = {
          ContentFR = "Hé ! Pourquoi tu t’éloignes ? Quand on bosse dans les égouts, c’est normal de sentir un peu fort.",
          DialogueId = 51001703,
          GUID = "7FAD6AE6",
          NextOptions = {
            [1] = 510017031,
            [2] = 510017032,
            [3] = 510017033
          },
          SpeakNpcId = 700069,
          Subtitle = "Hey! That was a bit uncalled for. Comes with the territory when you work in sewers, doesn't it?",
          bForbidSkipOptions = true
        },
        [51001704] = {
          ContentFR = "Ne te fie pas à ce que tu vois. Il y a encore quelques années, la plupart des gens m’appelaient avec respect « Docteur Dutton ».",
          DialogueId = 51001704,
          GUID = "7FAD6B10",
          NextDialogue = 51001705,
          SpeakNpcId = 700069,
          Subtitle = "You might not believe it, but there was a time people respectfully addressed me as "Doctor Dutton"."
        },
        [51001705] = {
          ContentFR = "Tu comprends sans doute ce que ce titre représentait pour un Charon né dans les taudis.",
          DialogueId = 51001705,
          GUID = "7FAD6B3A",
          NextDialogue = 51001706,
          SpeakNpcId = 700069,
          Subtitle = "You get what that title means to a Charon who's come up from the slums, right?"
        },
        [51001706] = {
          ContentFR = "J’ai soigné d’innombrables Charons à l’hôpital central... même des nobles faisaient le déplacement pour une consultation.",
          DialogueId = 51001706,
          GUID = "7FAD6B64",
          NextDialogue = 51001707,
          SpeakNpcId = 700069,
          Subtitle = "I've treated countless Charons at the central hospital; even the nobility sought me out for consultations.",
          TalkActionId = {
            [1] = "700069:Explain02_Start"
          }
        },
        [51001707] = {
          ContentFR = "Si tu ne me crois pas, demande donc aux jeunes Charons : leurs parents leur répétaient sans cesse de prendre exemple sur moi.",
          DialogueId = 51001707,
          GUID = "7FAD6B8E",
          NextDialogue = 51001708,
          SpeakNpcId = 700069,
          Subtitle = "Don't take my word for it — go ask the younger Charons. Their folks always told them to model themselves on me.",
          TalkActionId = {
            [1] = "700069:Explain02_End"
          }
        },
        [51001708] = {
          ContentFR = "À l’époque, j’étais un vrai maniaque de la propreté... le moindre grain de poussière entre deux carreaux me rendait fou.",
          DialogueId = 51001708,
          GUID = "7FAD6BB8",
          NextOptions = {
            [1] = 510017081
          },
          RestartTag = 51001708,
          SpeakNpcId = 700069,
          Subtitle = "I was quite a stickler for cleanliness back then; a single speck of dust between the tiles would drive me nuts...",
          bForbidSkipOptions = true
        },
        [51001709] = {
          ContentFR = "Je réparais des gens, aujourd’hui je répare des tuyaux... au fond, ça revient au même, non ?",
          DialogueId = 51001709,
          GUID = "7FAD6BE2",
          NextDialogue = 51001710,
          SpeakNpcId = 700069,
          Subtitle = "I used to patch up people, and now I patch up pipes. Not much difference, eh?",
          TalkActionId = {
            [1] = "700069:Think_Start"
          }
        },
        [51001710] = {
          ContentFR = "Dutton esquisse un sourire tranquille, comme s’il tournait sans rancune la page d’un passé douloureux.",
          DialogueId = 51001710,
          GUID = "7FAD6C0C",
          Subtitle = "(Dutton gave a serene smile, seemingly turning a page on some tough memories without a grudge.)",
          TalkActionId = {
            [1] = "700069:Think_End"
          }
        },
        [51001711] = {
          ContentFR = "Imagine la scène : un passant s’effondre, frappé par une urgence vitale, juste devant un médecin... et ce médecin choisit bravement de le sauver.",
          DialogueId = 51001711,
          GUID = "7FAD6C36",
          NextDialogue = 51001712,
          SpeakNpcId = 700069,
          Subtitle = "Picture this: a pedestrian collapsed from an acute condition right in front of a doctor, who heroically opted to save him.",
          TalkActionId = {
            [1] = "700069:Explain01_Start"
          }
        },
        [51001712] = {
          ContentFR = "Tu veux connaître la suite ? Passe-moi plutôt cette clé à molette.",
          DialogueId = 51001712,
          GUID = "7FAD6C60",
          NextDialogue = 51001713,
          SpeakNpcId = 700069,
          Subtitle = "Curious about what happened next? Hand me that wrench first—"
        },
        [51001713] = {
          ContentFR = "Le miracle n’a pas eu lieu. Ce qui est arrivé, c’est un procès colossal pour faute médicale. Pour préserver sa réputation, l’hôpital a dû licencier un employé.",
          DialogueId = 51001713,
          GUID = "7FAD6C8A",
          NextDialogue = 51001714,
          SpeakNpcId = 700069,
          Subtitle = "No miracle happened, just a massive lawsuit for medical malpractice.\nFor the sake of the hospital's reputation, an employee had to be fired.",
          TalkActionId = {
            [1] = "700069:Explain01_End"
          }
        },
        [51001714] = {
          ContentFR = "Et cet homme-là, qui ne savait rien faire d’autre que soigner... s’est retrouvé dans les égouts.",
          DialogueId = 51001714,
          GUID = "7FAD6CB4",
          NextDialogue = 51001715,
          SpeakNpcId = 700069,
          Subtitle = "Imagine that—someone who knew nothing but how to heal, ending up in the sewer pipes.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          }
        },
        [51001715] = {
          ContentFR = "Au moins, ce passage ici a guéri ma vieille obsession de la propreté en quelques mois. C’est déjà ça.",
          DialogueId = 51001715,
          GUID = "7FAD6CDE",
          NextDialogue = 51001716,
          SpeakNpcId = 700069,
          Subtitle = "Funny enough, a few months down here cured me of that intense fixation with cleanliness. A silver lining, am I right?",
          TalkActionId = {
            [1] = "700069:Sigh_End"
          }
        },
        [51001716] = {
          ContentFR = "Et puis bon... ce boulot me permet de ne pas mourir de faim dans la rue. Je devrai juste rembourser mes dettes jusqu’à ce qu’on me mette en terre.",
          DialogueId = 51001716,
          GUID = "7FAD6D08",
          NextOptions = {
            [1] = 510017161
          },
          SpeakNpcId = 700069,
          Subtitle = "At least this gig keeps me from starving on the streets, though I'll be paying debts till I'm six feet under.",
          bForbidSkipOptions = true
        },
        [51001717] = {
          ContentFR = "Dutton tourne le dos et resserre consciencieusement les nouvelles vis de la canalisation. Il balance ses bras avec habitude et énergie, comme s’il n’avait même pas entendu ta question.",
          DialogueId = 51001717,
          GUID = "7FAD6D32",
          NextDialogue = 51001718,
          Subtitle = "(Dutton turns, focusing on tightening the screws of the replacement pipe with his wrench,)\n(his arms swinging skillfully, seemingly oblivious to your question.)"
        },
        [51001718] = {
          ContentFR = "Dans le silence assourdissant qui suit, la réponse est pourtant évidente pour vous deux.",
          DialogueId = 51001718,
          GUID = "7FAD6D5C",
          Subtitle = "(Yet, in the echoing silence that ensues, the answer is clear to both of you without a word spoken.)"
        },
        [51001719] = {
          ContentFR = "Aïe... ! Il y a vraiment trop de rats, là-dedans !",
          DialogueId = 51001719,
          GUID = "7FAD6D86",
          SpeakNpcId = 700069,
          Subtitle = "Ow...! The rats are taking over down here!"
        },
        [51001801] = {
          ContentFR = "Eh, j’ai entendu dire que tu t’étais bien débrouillé à la Fosse de Glevum. Avec un tel talent, ça te dirait qu’on fasse un boulot ensemble ? Tu prends 80 %, je prends 20. Qu’en dis-tu ?",
          DialogueId = 51001801,
          GUID = "7FAD7AFA",
          NextOptions = {
            [1] = 510018011,
            [2] = 510018012
          },
          SpeakNpcId = 200015,
          Subtitle = "Hey, kid! Word's got around about your big score at Glevum Pit. Really impressive, I'd say! How about you and I team up for a gig?\nI'll take a 20% cut, you keep 80%. What do you say?",
          bForbidSkipOptions = true
        },
        [51001802] = {
          ContentFR = "Parfait, on y va alors.",
          DialogueId = 51001802,
          GUID = "7FAD7B24",
          NextDialogue = 51001803,
          SpeakNpcId = 200015,
          Subtitle = "Alright, let's get going then.",
          TalkActionId = {
            [1] = "200015:Agree"
          }
        },
        [51001803] = {
          ContentFR = "Camilla, mets-moi ça sur ta note, je te rembourse quand j’aurai la récompense.",
          DialogueId = 51001803,
          GUID = "7FAD7B4E",
          LookAt = {
            [1] = "200015:n(200003)",
            [2] = "200003:n(200015)"
          },
          NextDialogue = 51001804,
          SpeakNpcId = 200015,
          Subtitle = "Camilla, put the drink on my tab. I'll pay you back once I get the reward.",
          TurnTo = {
            [1] = "200015:n(200003)",
            [2] = "200003:n(200015)"
          }
        },
        [51001804] = {
          ContentFR = "Comme d’habitude, alors ta montre reste ici en garantie.",
          DialogueId = 51001804,
          GUID = "7FAD7B78",
          NextDialogue = 51001805,
          SpeakNpcId = 200003,
          Subtitle = "Same as always then, your pocket watch stays here as collateral."
        },
        [51001805] = {
          ContentFR = "Pas de souci. {nickname}, on y va et on revient vite.",
          DialogueId = 51001805,
          GUID = "7FAD7BA2",
          SpeakNpcId = 200015,
          Subtitle = "Sure, sure. let's make short work of this.",
          TurnTo = {
            [1] = "200015:n(0)"
          }
        },
        [51001901] = {
          ContentFR = "Avant même d’entrer aux Asphodèles, tu entends déjà des jurons résonner à travers la salle, comme si toute la cité devait entendre sa colère.",
          DialogueId = 51001901,
          GUID = "7FAD8B62",
          NextDialogue = 51001902,
          Subtitle = "(Before even enter The Asphodel, you already hear the echoing curse words, as if wanting the whole city to listen to his rage.)"
        },
        [51001902] = {
          ContentFR = "Tu as encore le culot de montrer ta tête ! J’ai été si stupide... j’aurais dû faire plus que te chasser !",
          DialogueId = 51001902,
          GUID = "7FAD8B8C",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001903,
          SpeakNpcId = 700047,
          Subtitle = "How dare you show yourself in front of my face! I was such a fool. I should have done more than just kick you out!",
          TalkActionId = {
            [1] = "700047:Angry01_Start"
          }
        },
        [51001903] = {
          ContentFR = "Tu parades avec notre nom depuis des années... et mes lettres de mise en garde ? Tu les as brûlées ?",
          DialogueId = 51001903,
          GUID = "7FAD8BB6",
          NextDialogue = 51001904,
          SpeakNpcId = 700047,
          Subtitle = "You paraded around with our family name for so many years. Did you use my warning letters as kindling?",
          TalkActionId = {
            [1] = "700047:Angry01_End"
          }
        },
        [51001904] = {
          ContentFR = "Oui, oui... vous avez raison, mais ce nom, après tout, c’est ce que vous...",
          DialogueId = 51001904,
          GUID = "7FAD8BE0",
          NextDialogue = 51001905,
          SpeakNpcId = 200015,
          Subtitle = "Yes, yes, you are right, but after all, that surname is what you...",
          TalkActionId = {
            [1] = "200015:Shock_Start"
          }
        },
        [51001905] = {
          ContentFR = "Wells, tête baissée comme un enfant puni, reste immobile tandis que l’homme le pointe du doigt.",
          DialogueId = 51001905,
          GUID = "7FAD8C0A",
          NextDialogue = 51001906,
          Subtitle = "(Wells, like a child who's misbehaved, stands with his head bowed in front of an old man, allowing the latter's finger to jab at him.)"
        },
        [51001906] = {
          ContentFR = "Ferme-la ! Tu n’as aucun talent et tu prétends être un Chasseur de Phoxène ? L’argent et la renommée ? Tu ne les mérites pas ! Tu cours partout comme un chien... maintenant toute la cité intérieure prend les Wells pour une blague !",
          DialogueId = 51001906,
          GUID = "7FAD8C34",
          NextDialogue = 51001907,
          SpeakNpcId = 700047,
          Subtitle = "Shut up! You have no talent, yet you try to be a Phoxhunter. Do you really think you deserve this money and fame?\nRunning around like a dog for others. The inner city now sees the Wells family as a joke!",
          TalkActionId = {
            [1] = "200015:Shock_End"
          }
        },
        [51001907] = {
          ContentFR = "Je pensais juste... si je réussis un jour, peut-être que vous reverrez votre jugement sur Sara et moi...",
          DialogueId = 51001907,
          GUID = "7FAD8C5E",
          NextDialogue = 51001908,
          SpeakNpcId = 200015,
          Subtitle = "I was just thinking, if I make something of myself someday, maybe you'll reconsider things about me and Sara—",
          TalkActionId = {
            [1] = "200015:Explain02_Start"
          }
        },
        [51001908] = {
          ContentFR = "Comment oses-tu prononcer son nom ! Oublie-la ! Toi et ma fille, il n’y aura jamais de retour possible ! Jamais !",
          DialogueId = 51001908,
          GUID = "7FAD8C88",
          NextDialogue = 51001909,
          SpeakNpcId = 700047,
          Subtitle = "How dare you mention her name! Forget about it. You and my daughter will never get back together, never!",
          TalkActionId = {
            [1] = "700047:Angry01_Start"
          }
        },
        [51001909] = {
          ContentFR = "Et ne dis pas que je ne t’ai pas prévenu : si tu poses un pied dans la cité intérieure, je te brise les jambes.",
          DialogueId = 51001909,
          GUID = "7FAD8CB2",
          NextDialogue = 51001910,
          SpeakNpcId = 700047,
          Subtitle = "Don't say I didn't warn you. If you dare step foot in the inner city, I'll break your legs.",
          TalkActionId = {
            [1] = "700047:Angry01_End"
          }
        },
        [51001910] = {
          ContentFR = "Oui, oui...",
          DialogueId = 51001910,
          GUID = "7FAD8CDC",
          NextDialogue = 51001911,
          SpeakNpcId = 200015,
          Subtitle = "Yeah, yeah...",
          TalkActionId = {
            [1] = "200015:Explain02_End"
          }
        },
        [51001911] = {
          ContentFR = "L’homme, voyant Wells hocher la tête sans fin, devient encore plus furieux. Son regard se pose finalement sur toi qui vient d’entrer dans les Asphodèles.",
          DialogueId = 51001911,
          GUID = "7FAD8D06",
          NextDialogue = 51001912,
          Subtitle = "(The old man, glaring at the nodding Wells, grows even more infuriated,)\n(looking around and finally setting his eyes on you, who just enters The Asphodel.)"
        },
        [51001912] = {
          ContentFR = "Et toi, Charon ? J’en ai vu des comme toi, rêvant de gloire en tant que Chasseur de Phoxène, pour ensuite espérer devenir un Charon Couronné...",
          DialogueId = 51001912,
          GUID = "7FAD8D30",
          NextDialogue = 51001990,
          SpeakNpcId = 700047,
          Subtitle = "And you, a Phoxhunter? I've seen many like you, dreaming of making a name for yourself as a Phoxhunter, and becoming a laurelled Charon.",
          TalkActionId = {
            [1] = "700047:Explain01_Start"
          }
        },
        [51001913] = {
          ContentFR = "Vous avez raison... mais {nickname} est vraiment capable, pas comme moi...",
          DialogueId = 51001913,
          GUID = "7FAD8D5A",
          NextDialogue = 51001914,
          SpeakNpcId = 200015,
          Subtitle = "Father-in-law,  is a capable one, not a loser like me..."
        },
        [51001914] = {
          ContentFR = "Ferdinand Wells, ce qui s’est passé entre vous deux ne me regarde pas. Mais si vous continuez à déranger nos invités pour rien, je devrai vous faire sortir.",
          DialogueId = 51001914,
          GUID = "7FAD8D84",
          NextDialogue = 51001915,
          SpeakNpcId = 200003,
          Subtitle = "Mr. Ferdinand Wells, I had no right to interfere what happened between you two. But if you keep\nharassing my other guests for no reason like this, The Asphodel might have to show you the door.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51001915] = {
          ContentFR = "Camilla, assise derrière le comptoir, souffle un anneau de fumée. Ses paroles désinvoltes résonnent pourtant avec force dans la salle vide.",
          DialogueId = 51001915,
          GUID = "7FAD8DAE",
          NextDialogue = 51001991,
          Subtitle = "(Camilla, sitting behind the counter, puffs out a ring of smoke. Her casual words echoing powerfully in the empty tavern.)",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51001916] = {
          ContentFR = "Hmpf.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51001916,
          GUID = "7FAD8DD8",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001917,
          SpeakNpcId = 700047,
          Subtitle = "Hmph.",
          TalkActionId = {
            [1] = "700047:Disagree"
          }
        },
        [51001917] = {
          ContentFR = "Le vieil homme continue de pointer Wells et de jurer. Peut-être vaut-il mieux attendre qu’il se calme pour parler à nouveau.",
          DialogueId = 51001917,
          GUID = "7FAD8E02",
          Subtitle = "(The elder didn't quite catch what you said, and continued to curse Wells. Maybe it's better to wait a bit for him to calm down.)"
        },
        [51001918] = {
          ContentFR = "... Hmpf.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51001918,
          GUID = "7FAD8E2C",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001919,
          SpeakNpcId = 700047,
          Subtitle = "...Hmph.",
          TalkActionId = {
            [1] = "700047:Disagree"
          }
        },
        [51001919] = {
          ContentFR = "L’homme, réduit au silence par tes paroles, jette un dernier regard noir et sort en claquant la porte.",
          DialogueId = 51001919,
          GUID = "7FAD8E56",
          NextDialogue = 51001920,
          Scripts = "MoveTo{ActorId{700047},TargetPoint{"TargetPoint_LeaveTavern"},MoveSpeed{90},Visibility{"Hide"}}",
          Subtitle = "(The elder is left speechless by your words, and glares fiercely before storming out.)"
        },
        [51001920] = {
          ContentFR = "Désolé pour tout ce remue-ménage... Mon beau-père... Monsieur Ferdinand Wells n’était pas venu dans la cité extérieure depuis des années.",
          DialogueId = 51001920,
          GUID = "7FAD8E80",
          LookAt = {
            [1] = "200015:n(0)"
          },
          NextDialogue = 51001992,
          SpeakNpcId = 200015,
          Subtitle = "Sorry for causing everyone so much trouble. Well, my father-in-law... I mean Mr. Ferdinand Wells hasn't been to the outer city for years.",
          TalkActionId = {
            [1] = "200015:Sigh_Start"
          }
        },
        [51001921] = {
          ContentFR = "Pas grave. Si quelques insultes pouvaient nous abattre, nous ne serions pas ici. On m’a dit que vous aviez été blessé pendant une mission. Ça va ?",
          DialogueId = 51001921,
          GUID = "7FAD8EAA",
          NextDialogue = 51001922,
          SpeakNpcId = 100001,
          Subtitle = "It's alright. We wouldn't be here today if we gave in to every slight or insult.\nAnyway, I heard you were injured recently during a commission. Are you okay?"
        },
        [51001922] = {
          ContentFR = "Ce n’est rien. Heureusement, cette montre m’a protégé d’une blessure mortelle.",
          DialogueId = 51001922,
          GUID = "7FAD8ED4",
          NextDialogue = 51001923,
          SpeakNpcId = 200015,
          Subtitle = "It's nothing. Luckily this thing saved me from being fatally injured.",
          TalkActionId = {
            [1] = "200015:Explain01_Start"
          }
        },
        [51001923] = {
          ContentFR = "Wells sort une montre de poche finement travaillée, le cadran fissuré, les aiguilles tordues de façon exagérée, au point qu’il est devenu impossible de refermer le boîtier.",
          DialogueId = 51001923,
          GUID = "7FAD8EFE",
          NextOptions = {
            [1] = 510019231,
            [2] = 510019232
          },
          Subtitle = "(Wells takes out a finely crafted pocket watch from his chest. The dial is covered in cracks,)\n(and the hands are twisted upwards in an exaggerated manner, making closing the watch cover a mere wish.)",
          TalkActionId = {
            [1] = "200015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51001924] = {
          ContentFR = "Il l’a faite lui-même. Il y a dix ans, tout le monde connaissait Todd Wells, le prodige horloger. Il était presque devenu un Charon Couronné grâce à son talent.",
          DialogueId = 51001924,
          GUID = "7FAD8F28",
          NextDialogue = 51001925,
          SpeakNpcId = 200003,
          Subtitle = "He made it himself. Over a decade ago, there wasn't a soul who hadn't heard of Todd Wells, the prodigy clockmaker.\nBack then, his craftsmanship almost won him the title of Laurelled Charon.",
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001925] = {
          ContentFR = "Une pièce magnifique... dommage qu’elle soit cassée.",
          DialogueId = 51001925,
          GUID = "7FAD8F52",
          NextDialogue = 51001926,
          SpeakNpcId = 100001,
          Subtitle = "Such a beautifully crafted watch. It's a pity it cracked like that.",
          TalkActionId = {
            [1] = "200003:Explain01_End"
          }
        },
        [51001926] = {
          ContentFR = "Haha, oui, mais les aiguilles étaient déjà cassées depuis longtemps. Je la garde juste comme souvenir.",
          DialogueId = 51001926,
          GUID = "7FAD8F7C",
          NextDialogue = 51001927,
          SpeakNpcId = 200015,
          Subtitle = "Haha. Actually the hands had been broken for a long time, you know. I just keep it with me as a memento.",
          TalkActionId = {
            [1] = "200015:Sigh_Start"
          }
        },
        [51001927] = {
          ContentFR = "Pourquoi ne pas essayer de la réparer ?",
          DialogueId = 51001927,
          GUID = "7FAD8FA6",
          NextDialogue = 51001928,
          SpeakNpcId = 100001,
          Subtitle = "Why don't you try to fix it then?"
        },
        [51001928] = {
          ContentFR = "Mon beau-père a coupé l’accès aux outils et matériaux, impossible de la réparer.",
          DialogueId = 51001928,
          GUID = "7FAD8FD0",
          NextDialogue = 51001929,
          SpeakNpcId = 200015,
          Subtitle = "The tools and materials needed for repairs were cut off by my father-in-law, so even if I wanted to fix it, I just couldn't.",
          TalkActionId = {
            [1] = "200015:Sigh_End"
          }
        },
        [51001929] = {
          ContentFR = "... Tout ne se répare pas juste parce qu’on veut et qu’on y met de la force.",
          DialogueId = 51001929,
          GUID = "7FAD8FFA",
          NextDialogue = 51001930,
          SpeakNpcId = 200015,
          Subtitle = "...It's the way it is. Not everything can be fixed just because you want to and put effort into it.",
          TalkActionId = {
            [1] = "200015:Talk01_Start"
          }
        },
        [51001930] = {
          Content = "……",
          DialogueId = 51001930,
          GUID = "7FAD9024",
          NextDialogue = 51001931,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51001931] = {
          ContentFR = "Bref, merci d’être intervenu. Sans toi, mes oreilles n’y auraient pas résisté.",
          DialogueId = 51001931,
          GUID = "7FAD904E",
          NextDialogue = 51001932,
          SpeakNpcId = 200015,
          TalkActionId = {
            [1] = "200015:Talk01_End"
          }
        },
        [51001932] = {
          ContentFR = "Allez, ce soir c’est moi qui régale. Tu ouvres ces fûts là-bas, je m’occupe de ceux-ci !",
          DialogueId = 51001932,
          GUID = "7FAD9078",
          NextDialogue = 51001934,
          SpeakNpcId = 200015,
          TalkActionId = {
            [1] = "200015:Explain02_Start"
          }
        },
        [51001933] = {
          ContentFR = "Allez, bois ! À la tienne !",
          DialogueId = 51001933,
          GUID = "7FAD90A2",
          SpeakNpcId = 200015,
          Subtitle = "Come on, let's drink and party all night!"
        },
        [51001934] = {
          ContentFR = "...",
          DialogueId = 51001934,
          GUID = "7FAD9079",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200015:Explain02_End"
          }
        },
        [51001935] = {
          Camera = "122.0,278.0,139.0,0.000007,0.0,-95.0,35.0,200.0,false,Manual,2.8",
          ContentFR = "Tu ouvres tous les fûts, te retournes et vois Wells lever son verre, le sourire large et familier.",
          DialogueId = 51001935,
          FinalCamera = "102.0,278.0,139.0,0.000007,0.0,-95.0,35.0,350.0,false,Manual,2.8",
          GUID = "7FAD907A",
          Scripts = "TurnTo{_delay{1.5},TurnToDescription{"100001:n(700207)"}}",
          TalkActionId = {
            [1] = "700207:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51001936] = {
          ContentFR = "Pourtant, sous ce rire, ses doigts serrent la montre à gousset brisée, une pointe de mélancolie qui semble, tout comme la montre elle-même, impossible à réparer facilement.",
          DialogueId = 51001936,
          Duration = 4,
          GUID = "7FAD907B"
        },
        [51001990] = {
          ContentFR = "Laisse-moi te dire quelque chose. <H>Givrelac n’a pas eu beaucoup de Charons Couronnés vivants depuis des années.</> Les Charons finissent seulement par pourrir dans une ruelle sombre !",
          DialogueId = 51001990,
          GUID = "7FAD99FC",
          NextDialogue = 51001913,
          SpeakNpcId = 700047,
          Subtitle = "Let me tell you something. Icelake hasn't had many living laurelled Charons for years. Charons only end up rotting in some dark alley!",
          TalkActionId = {
            [1] = "700047:Explain01_End"
          }
        },
        [51001991] = {
          ContentFR = "On a l’impression que la température de la pièce monte légèrement à cause de la fumée.",
          DialogueId = 51001991,
          GUID = "7FAD9A26",
          NextOptions = {
            [1] = 510019911,
            [2] = 510019912,
            [3] = 510019913
          },
          RestartTag = 51001915,
          Subtitle = "(As if the temperature in The Asphodel rose significantly in the smoke.)",
          bForbidSkipOptions = true
        },
        [51001992] = {
          ContentFR = "Il est un peu... attaché aux traditions. Ne prends pas ses paroles trop à cœur.",
          DialogueId = 51001992,
          GUID = "7FAD9A50",
          NextDialogue = 51001921,
          SpeakNpcId = 200015,
          Subtitle = "Let's just say he's more... traditional. Don't take his words to heart.",
          TalkActionId = {
            [1] = "200015:Sigh_End"
          }
        },
        [51002001] = {
          ContentFR = "Amis de passage, arrêtez-vous un instant ! Contre quelques pièces, vous repartirez avec un indice menant au fabuleux trésor caché d’une île du sud !",
          DialogueId = 51002001,
          GUID = "7FAD9BCA",
          NextDialogue = 51002002,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you will get something unimaginable!\nYes, the clue to the secret treasure of a southern island!",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002002] = {
          ContentFR = "Quoi, vous comptez vraiment vous contenter chaque jour de pain rassis et de vin éventé ? Lancez-vous donc dans l’aventure, saisissez votre chance, changez votre destin !",
          DialogueId = 51002002,
          GUID = "7FAD9BF4",
          NextDialogue = 51002003,
          SpeakNpcId = 700048,
          Subtitle = "Are you really content with cold bread and stale wine every day? Why not embark on an adventure, seize the opportunity, and change your life!",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002003] = {
          ContentFR = "L’homme qui t’interpelle, un vieillard en haillons au ton exalté, respire l’opportunisme. Mais son assurance excessive le rend plutôt suspect.",
          DialogueId = 51002003,
          GUID = "7FAD9C1E",
          NextOptions = {
            [1] = 510020031,
            [2] = 510020032,
            [3] = 510020033
          },
          Subtitle = "(The middle-aged man in front of you is spouting opportunistic rhetoric.)\n(But his ragged appearance and oddly passionate speech make him seem untrustworthy.)",
          bForbidSkipOptions = true
        },
        [51002004] = {
          ContentFR = "Ah, mais regardez-moi... je ne suis plus qu’un tas de vieilles guibolles. Autant laisser cette chance à la jeunesse !",
          DialogueId = 51002004,
          GUID = "7FAD9C48",
          NextDialogue = 51002005,
          SpeakNpcId = 700048,
          Subtitle = "Oh, I'm just an old man. I'd rather give the opportunity to the younger generation.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002005] = {
          ContentFR = "Hé, si j’avais encore votre âge, j’aurais déjà empaqueté mes affaires et pris la mer !",
          DialogueId = 51002005,
          GUID = "7FAD9C72",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "If I were your age, I'd surely be packing my stuff and setting off right now."
        },
        [51002006] = {
          ContentFR = "Tiens donc, vous êtes {性别:intéressé|intéressée} ? Vous savez reconnaître une occasion quand elle se présente.",
          DialogueId = 51002006,
          GUID = "7FAD9C9C",
          NextDialogue = 51002007,
          SpeakNpcId = 700048,
          Subtitle = "What, you are interested? You do know how to seize opportunities.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002007] = {
          ContentFR = "J’aime les jeunes {性别:futés|futées} comme vous. Alors, pour vous, je peux bien lâcher un petit indice... gratuitement.",
          DialogueId = 51002007,
          GUID = "7FAD9CC6",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "I like smart kids like you, so I can indeed reveal a thing or two for free.",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002008] = {
          ContentFR = "Comment pouvez-vous dire ça ? Vous ne m’avez même pas écouté ! Quelle impolitesse !",
          DialogueId = 51002008,
          GUID = "7FAD9CF0",
          NextDialogue = 51002009,
          SpeakNpcId = 700048,
          Subtitle = "What are you talking about? You accuse me of defraudation without even hearing me out. Where are your manners?",
          TalkActionId = {
            [1] = "700048:Disagree"
          }
        },
        [51002009] = {
          ContentFR = "Puisque vous m’accusez d’être un escroc, laissez-moi au moins vous ouvrir les yeux.",
          DialogueId = 51002009,
          GUID = "7FAD9D1A",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "Since you think I'm a swindler, let me tell you a few things to set things straight."
        },
        [51002010] = {
          ContentFR = "Je ne suis pas natif de Givrelac. Je suis né sur une île au sud de l’Empire.",
          DialogueId = 51002010,
          GUID = "7FAD9D44",
          NextDialogue = 51002011,
          SpeakNpcId = 700048,
          Subtitle = "Actually, I'm not a local from Icelake. I was born on an island in the southern part of the Empire.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002011] = {
          ContentFR = "Notre île était dominée par un immense Arbre Céleste, invisible sur la plupart des cartes.",
          DialogueId = 51002011,
          GUID = "7FAD9D6E",
          NextDialogue = 51002012,
          SpeakNpcId = 700048,
          Subtitle = "Our island was covered by a giant Heaventree, that you couldn't find on any ordinary map."
        },
        [51002012] = {
          ContentFR = "Dans une grotte secrète, il y avait la statue d’une déesse plus belle que toutes les femmes de ce monde ! On dit que le trésor repose juste derrière elle.",
          DialogueId = 51002012,
          GUID = "7FAD9D98",
          NextDialogue = 51002013,
          SpeakNpcId = 700048,
          Subtitle = "There's a secret cave on the island with a statue of a goddess more beautiful than any woman you've ever seen!\nLegend has it that the treasure is hidden right behind this goddess statue.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002013] = {
          ContentFR = "Mais... pour savoir en quoi consiste ce trésor exactement, il faudra m’offrir quelques pièces de plus.",
          DialogueId = 51002013,
          GUID = "7FAD9DC2",
          NextOptions = {
            [1] = 510020131
          },
          RestartTag = 51002013,
          SpeakNpcId = 700048,
          Subtitle = "As for what this treasure is, if you want to hear more, just a few silver coins will suffice.",
          bForbidSkipOptions = true
        },
        [51002014] = {
          ContentFR = "Ça ressemble fort à l’Île du Purgatoire. Cet homme est sûrement un escroc. Inutile de perdre plus de temps.",
          DialogueId = 51002014,
          GUID = "7FAD9DEC",
          NextDialogue = 51002015,
          SpeakNpcId = 100001,
          Subtitle = "(It sounds a lot like Purgatorio Island. This guy is probably a swindler. Best not to waste any time on him.)"
        }
      }
    end
  },
  {
    MinKey = 51002015,
    MaxKey = 51003321,
    Loader = function()
      return {
        [51002015] = {
          ContentFR = "Laissez tomber. Je n’ai pas assez de pièces pour les jeter à la première fable venue.",
          DialogueId = 51002015,
          GUID = "7FAD9E16",
          SpeakNpcId = 100001,
          Subtitle = "Forget it. My coins are in short supply so I can't throw them around just to hear something."
        },
        [51002016] = {
          ContentFR = "Cet îlot du sud... il est bien dominé par un Arbre Céleste gigantesque ? On l’appelle l’Île du Purgatoire, n’est-ce pas ?",
          DialogueId = 51002016,
          GUID = "7FAD9E40",
          NextDialogue = 51002017,
          SpeakNpcId = 100001,
          Subtitle = "This southern island you're talking about, does it have a giant Heaventree near it, and do they call it Purgatorio Island?"
        },
        [51002017] = {
          ContentFR = "... !",
          DialogueId = 51002017,
          GUID = "7FAD9E6A",
          NextDialogue = 51002018,
          SpeakNpcId = 700048,
          Subtitle = "!!!"
        },
        [51002018] = {
          ContentFR = "Comment connais-tu ce nom ?",
          DialogueId = 51002018,
          GUID = "7FAD9E94",
          NextDialogue = 51002019,
          SpeakNpcId = 700048,
          Subtitle = "How do you know that name?",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002019] = {
          ContentFR = "C’était chez moi.",
          DialogueId = 51002019,
          GUID = "7FAD9EBE",
          NextDialogue = 51002020,
          SpeakNpcId = 100001,
          Subtitle = "That was my home."
        },
        [51002020] = {
          ContentFR = "... Toi aussi tu viens de là-bas ? Attends... ils laissent désormais les villageois partir ?",
          DialogueId = 51002020,
          GUID = "7FAD9EE8",
          NextDialogue = 51002021,
          SpeakNpcId = 700048,
          Subtitle = "...You're from there too? Have they stopped preventing villagers from leaving?",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002021] = {
          ContentFR = "Bon, inutile de te mentir. À vingt ans, je suis parti pêcher au large. En voyant la côte de l’Empire, sinueuse comme les châteaux et les selles de mes livres, j’ai eu un déclic.",
          DialogueId = 51002021,
          GUID = "7FAD9F12",
          NextDialogue = 51002022,
          SpeakNpcId = 700048,
          Subtitle = "Tell you what, when I was twenty, I went out to fish on the sea. I looked at the coastline of the Empire,\nwhich was winding like the saddles and castles I'd read about in books."
        },
        [51002022] = {
          ContentFR = "Au lieu de rentrer avec ma pêche, j’ai continué vers l’est, jusqu’à atteindre ce rivage. Mais la vie ici n’était pas vraiment ce que j’avais imaginé...",
          DialogueId = 51002022,
          GUID = "7FAD9F3C",
          NextDialogue = 51002023,
          SpeakNpcId = 700048,
          Subtitle = "So, instead of taking my catch home as usual, I kept heading east, to this side of the coast.\nBut life here turned out to be a bit different from what I had imagined..."
        },
        [51002023] = {
          ContentFR = "Ça fait plus de dix ans. Et maintenant, je n’ai même plus de quoi payer le voyage du retour. Alors je me débrouille avec mon éloquence...",
          DialogueId = 51002023,
          GUID = "7FAD9F66",
          NextDialogue = 51002024,
          SpeakNpcId = 700048,
          Subtitle = "It's been over a decade, and now I can't even scrape together enough for the fare back. I can only make ends meet with my eloquence.",
          TalkActionId = {
            [1] = "700048:Sigh_Start"
          }
        },
        [51002024] = {
          ContentFR = "Puisque tu viens de l’île aussi... dis-moi, la maison tout à l’est du village, est-ce que tu sais si ses habitants vont bien ?",
          DialogueId = 51002024,
          GUID = "7FAD9F90",
          NextDialogue = 51002025,
          SpeakNpcId = 700048,
          Subtitle = "So, since you're also from Purgatorio Island, do you know how the family at the easternmost part of the village is doing?",
          TalkActionId = {
            [1] = "700048:Sigh_End"
          }
        },
        [51002025] = {
          ContentFR = "Tu lui racontes l’attaque des Souillés et la fuite des villageois par bateau.",
          DialogueId = 51002025,
          GUID = "7FAD9FBA",
          NextDialogue = 51002026,
          SpeakNpcId = 100001,
          Subtitle = "(You told him about the village being attacked by Filthoids, with most villagers escaping by boat.)"
        },
        [51002026] = {
          ContentFR = "Quoi... ?!",
          DialogueId = 51002026,
          GUID = "7FAD9FE4",
          NextDialogue = 51002027,
          SpeakNpcId = 700048,
          Subtitle = "What the..."
        },
        [51002027] = {
          ContentFR = "Mais... d’après toi, ils ont réussi à s’échapper ? Alors tant mieux... tant mieux...",
          DialogueId = 51002027,
          GUID = "7FADA00E",
          NextDialogue = 51002028,
          SpeakNpcId = 700048,
          Subtitle = "But you just said they all escaped, right? Thank god... As long as they've got away...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002028] = {
          ContentFR = "Dis, si jamais tu retournes sur l’Île du Purgatoire, pourrais-tu jeter un œil près de ma vieille maison ? Voir s’il reste quelque chose...",
          DialogueId = 51002028,
          GUID = "7FADA038",
          NextDialogue = 51002029,
          SpeakNpcId = 700048,
          Subtitle = "By the way, if you ever get a chance to go back to Purgatorio Island, could you check near my old house to see if there's anything left?"
        },
        [51002029] = {
          ContentFR = "Et s’il n’y a vraiment rien, rapporte-moi n’importe quoi. Même un brin d’herbe ferait l’affaire.",
          DialogueId = 51002029,
          GUID = "7FADA062",
          NextDialogue = 51002030,
          SpeakNpcId = 700048,
          Subtitle = "If you can't find anything, just bring back something for me. Anything will do, even a blade of grass.",
          TalkActionId = {
            [1] = "700048:Explain02_Start"
          }
        },
        [51002030] = {
          ContentFR = "D’accord.",
          DialogueId = 51002030,
          GUID = "7FADA08C",
          SpeakNpcId = 100001,
          Subtitle = "Sure."
        },
        [51002031] = {
          ContentFR = "Ah... quand j’étais jeune, partir était si difficile, et maintenant, quand j’aimerais rentrer, je n’en ai plus la possibilité...",
          DialogueId = 51002031,
          GUID = "7FADA0B6",
          NextDialogue = 51002032,
          SpeakNpcId = 700048,
          Subtitle = "It was so hard to leave when I was young, and now I can't go back...",
          TalkActionId = {
            [1] = "700048:Explain02_End"
          }
        },
        [51002032] = {
          ContentFR = "Prends soin de toi.",
          DialogueId = 51002032,
          GUID = "7FADA0E0",
          SpeakNpcId = 100001,
          Subtitle = "Take care."
        },
        [51002101] = {
          ContentFR = "Ça doit être ici, la maison de Brunetto. Voyons s’il reste quelque chose que je puisse lui rapporter.",
          DialogueId = 51002101,
          Duration = 3,
          GUID = "7FADAC32",
          NextDialogue = 51002102,
          SpeakNpcId = 100001,
          Subtitle = "This must be Brunetto's house."
        },
        [51002102] = {
          ContentFR = "Tiens... un coffre. Peut-être qu’il contient un souvenir à lui ramener.",
          DialogueId = 51002102,
          Duration = 4,
          GUID = "7FADAC5C",
          NextDialogue = 51002103,
          SpeakNpcId = 100001,
          Subtitle = "This book... Could it be his? Might as well take it back to him."
        },
        [51002103] = {
          ContentFR = "Pas de chance, il est fermé... Allons chercher la clé dans les environs.",
          DialogueId = 51002103,
          Duration = 2.5,
          GUID = "7FADAC86",
          SpeakNpcId = 100001
        },
        [51002104] = {
          ContentFR = "Vu la forme, cette clé devrait convenir. Essayons.",
          DialogueId = 51002104,
          Duration = 2,
          GUID = "7FADAC87",
          SpeakNpcId = 100001
        },
        [51002105] = {
          Camera = "183.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La clé tourne lentement. Le barillet rouillé résiste, grinçant d’un bruit strident. Quand le couvercle s’ouvre enfin, le vacarme attire aussitôt une meute de Souillés qui te barre le passage.",
          DialogueId = 51002105,
          FinalCamera = "186.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC88",
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Think_Start\"},Duration{2}},\nCameraMoveTo{_delay{3},TargetPosition{\"-55.90625,-613.697266,78.0,0.0,0.0,72.803268,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nPARA{\nCameraMoveTo{_delay{3},TargetPosition{\"-127.292969,-843.583984,77.028931,0.0,0.0,72.203499,35.0,100000.0,false,DoNotOverride,2.8\"},duration{7}},\nSetLocation{ActorId{700208},TargetPoint{\"MovePoint_700208\"},Visibility{\"Show\"}},\nSetLocation{ActorId{700209},TargetPoint{\"MovePoint_700209\"},Visibility{\"Show\"}},\nSEQ{\nPlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},\nTurnTo{_delay{2},TurnToDescription{\"100001:p(-130)\"}}\n}\n}\n}",
          ToFinalCameraBlendTime = 3
        },
        [51002106] = {
          Camera = "-160.396484,-385.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les Souillés ne t’ont pas posé de réelle difficulté. Pourtant, ce bref affrontement a réveillé en toi une étrange familiarité. Un souvenir ancien refait surface : tu entends presque deux enfants se chamailler devant cette maison.",
          DialogueId = 51002106,
          FinalCamera = "-160.396484,-404.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC89",
          NextDialogue = 51002107,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002107] = {
          Camera = "119.585938,-26.257812,128.0,-0.0,-9.999997,-145.798935,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ça me revient... Quand j’étais gosse, je me suis {性别:battu|battue} avec l’enfant qui vivait ici. Son nom m’échappe... mais en y repensant, ça devait être le petit-fils de Brunetto.",
          DialogueId = 51002107,
          FinalCamera = "119.585938,-26.257812,128.0,0.0,-9.999997,-138.598923,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8A",
          NextDialogue = 51002108,
          Scripts = "TurnTo{_delay{3},TurnToDescription{"100001:n(700211)"}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002108] = {
          Camera = "-180.842773,-670.0,18.0,0.000018,4.000004,83.599602,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je ne sais plus ce qui avait déclenché la bagarre. Mais je me souviens encore de nos dernières piques avant d’en venir aux poings... Ce garnement m’a traité de cyclope, et moi je l’ai traité de crapaud aux yeux globuleux.",
          DialogueId = 51002108,
          GUID = "7FADAC8B",
          NextDialogue = 51002109,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Think_Start\"},Duration{2}},\nCameraMoveTo{_delay{3},TargetPosition{\"88.632812,-31.105469,133.52002,0.000039,-12.79989,-135.199905,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nPlayAnimation{_delay{1},ActorId{700211},AnimationId{\"Angry01_Start\"},Duration{1}},\n}",
          SpeakNpcId = 100001
        },
        [51002109] = {
          Camera = "-143.595703,-312.263672,94.0,0.0,0.0,57.398624,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Haha... J’étais sacrément {性别:insolent|insolente}. Pourtant, je crois que je n’étais même pas si en colère. J’avais encore Berry à mes côtés, après tout...",
          DialogueId = 51002109,
          GUID = "7FADAC8C",
          NextDialogue = 51002110,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Sigh_Start\"},Duration{3}},\nPlayAnimation{ActorId{100001},AnimationId{\"Sigh_End\"},Duration{2}},\nPlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}\n}",
          SpeakNpcId = 100001
        },
        [51002110] = {
          Camera = "70.748047,32.113281,1751.04126,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et plus tard... je crois qu’on s’est réconciliés. J’ai le souvenir de nous deux perchés sur le toit de la maison...",
          DialogueId = 51002110,
          FinalCamera = "70.748047,32.113281,1859.0,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8D",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 7
        },
        [51002111] = {
          Camera = "51.001041,365.471497,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah, oui, c’était là. Quelques jours plus tard, il est revenu avec un sac de provisions pour s’excuser. J’étais prêt à l’envoyer balader... mais quand j’ai vu ce pain énorme, assez pour trois, j’ai laissé tomber ma fierté.",
          DialogueId = 51002111,
          FinalCamera = "14.224466,404.913452,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8E",
          NextDialogue = 51002112,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002112] = {
          Camera = "-78.281792,63.089108,96.67688,0.000094,-0.099919,90.79702,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, on est restés là, tous les trois, à mâcher ce pain dur et brûlé, en regardant le soleil décliner et les pêcheurs rentrer au village.",
          DialogueId = 51002112,
          FinalCamera = "-123.657745,62.460995,96.67688,0.000094,-0.099919,90.797005,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8F",
          NextDialogue = 51002113,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002113] = {
          Camera = "-182.640976,408.587311,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis, ce petit morveux s’est mis à s’étouffer, enchaînant les hoquets. On a éclaté de rire. La dispute s’est terminée comme ça.",
          DialogueId = 51002113,
          FacialId = {
            [1] = "700210:Ahaha02"
          },
          FinalCamera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC90",
          NextDialogue = 51002114,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002114] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Au final... on peux dire que je connais Brunetto depuis ce jour-là, en quelque sorte.",
          DialogueId = 51002114,
          FacialId = {
            [1] = "700210:Smile02"
          },
          GUID = "7FADAC91",
          NextDialogue = 51002115,
          SpeakNpcId = 700210
        },
        [51002115] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et s’il n’y a vraiment rien, rapporte-moi n’importe quoi. Même un brin d’herbe ferait l’affaire.",
          DialogueId = 51002115,
          GUID = "7FADAC92",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030106.T_Story_Recall_10030106'",
          NextDialogue = 51002116,
          SpeakNpcId = 700048
        },
        [51002116] = {
          Camera = "167.319687,115.790215,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il voulait que je lui rapporte n’importe quoi... Peut-être que je pourrais ajouter quelque chose de plus. Les poissons de ce coin sont bien dodus en cette saison.",
          DialogueId = 51002116,
          FinalCamera = "181.948135,137.309357,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC93",
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002117] = {
          ContentFR = "Voilà. Avec ça, son mal du pays devrait être un peu apaisé.",
          DialogueId = 51002117,
          Duration = 3,
          GUID = "7FADAC94",
          NextDialogue = 51002118,
          SpeakNpcId = 100001
        },
        [51002118] = {
          ContentFR = "Le petit-fils, je l’ai connu en me battant... et le grand-père, en me faisant arnaquer. Ah... quelle drôle de destinée.",
          DialogueId = 51002118,
          Duration = 4,
          GUID = "7FADAC95",
          SpeakNpcId = 100001
        },
        [51002201] = {
          ContentFR = "Amis de passage ! Pour quelques pièces, rejoignez l’Association des pêcheurs de Givrelac et profitez de conseils de maîtres avec des décennies d’expérience— Ah ! C’est toi...",
          DialogueId = 51002201,
          GUID = "7FADBC9A",
          NextDialogue = 51002202,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you can join the Icelake Fishermen's Mutual Aid Society\nto get the best and latest— Oh! It's you..."
        },
        [51002202] = {
          ContentFR = "Ceci devrait t’appartenir, non ?",
          DialogueId = 51002202,
          GUID = "7FADBCC4",
          NextDialogue = 51002203,
          SpeakNpcId = 100001,
          Subtitle = "Is this yours?"
        },
        [51002203] = {
          ContentFR = "Ah ! ... Oui ! C’est bien ce vieux livre que je lisais sans cesse étant enfant. C’est en feuilletant ces pages que j’ai rêvé de quitter notre îlot minuscule...",
          DialogueId = 51002203,
          GUID = "7FADBCEE",
          NextDialogue = 51002204,
          SpeakNpcId = 700048,
          Subtitle = "Jesus! Yes, this is the book I used to read over and over again when I was a kid. I thought about coming to the land because of it...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002204] = {
          ContentFR = "Merci. Merci infiniment. Ce soir, je vais le relire d’un bout à l’autre. Mais pour l’instant... soupir, il faut bien continuer à gagner sa croûte.",
          DialogueId = 51002204,
          GUID = "7FADBD18",
          NextDialogue = 51002205,
          SpeakNpcId = 700048,
          Subtitle = "Thank you. Thank you so much. I need to give it a good read tonight. But for now, *sigh* making a living is more important.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002205] = {
          ContentFR = "Prends soin de toi. Et évite d’arnaquer les gens, d’accord ? Tiens, prends aussi ça, du poisson séché de l’Île du Purgatoire.",
          DialogueId = 51002205,
          GUID = "7FADBD42",
          NextDialogue = 51002206,
          SpeakNpcId = 100001,
          Subtitle = "Take care, and don't be a swindler anymore.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002206] = {
          ContentFR = "... Oh. Merci. Merci du fond du cœur...",
          DialogueId = 51002206,
          GUID = "7FADBD6C",
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, those who are interested in Icelake Fishermen's Mutual Aid Society can learn more about it. We have decades of fishing experience from veteran fishermen. Fishing is great either serving as a hobby or a job!"
        },
        [51002207] = {
          ContentFR = "Amis de passage ! L’Association des pêcheurs de Givrelac recrute. Que ce soit par passion ou pour le métier, la pêche, c’est le bonheur garanti !",
          DialogueId = 51002207,
          GUID = "7FADBD96",
          NextDialogue = 51002208,
          SpeakNpcId = 700048
        },
        [51002208] = {
          ContentFR = "Tiens donc, {nickname} ! Ça fait plaisir de croiser {性别:un|une} compatriote. On échangera nos techniques de pêche à l’occasion ?",
          DialogueId = 51002208,
          GUID = "7FADBD97",
          NextDialogue = 51002209,
          SpeakNpcId = 700048
        },
        [51002209] = {
          ContentFR = "Avec plaisir, une prochaine fois.",
          DialogueId = 51002209,
          GUID = "7FADBDC0",
          SpeakNpcId = 100001
        },
        [51002301] = {
          ContentFR = "{性别:Jeune homme|Jeune femme}, as-tu des nouvelles de Hamel Dickinson ?",
          DialogueId = 51002301,
          GUID = "7FADCD02",
          NextOptions = {
            [1] = 510023011
          },
          SpeakNpcId = 700019
        },
        [51002302] = {
          ContentFR = "Le journal découvert dans la Fosse de Glevum porte ce nom : Hamel Dickinson.",
          DialogueId = 51002302,
          GUID = "7FADCD2C",
          NextDialogue = 51002303
        },
        [51002303] = {
          ContentFR = "Pour peu que tu aies raison, le monstre qui hante ces galeries... n’est autre que lui.",
          DialogueId = 51002303,
          GUID = "7FADCD56",
          NextDialogue = 51002304
        },
        [51002304] = {
          ContentFR = "À l’évocation de ce nom, un éclat traverse ses yeux voilés par l’âge. Pour Dame Hilin, Hamel Dickinson n’est pas un simple souvenir : ce nom porte un poids immense. Elle attend ta réponse avec une lueur d’espoir fébrile.",
          DialogueId = 51002304,
          GUID = "7FADCD80",
          NextOptions = {
            [1] = 510023041,
            [2] = 510023042
          },
          bForbidSkipOptions = true
        },
        [51002305] = {
          ContentFR = "...",
          DialogueId = 51002305,
          GUID = "7FADCDAA",
          NextDialogue = 51002306,
          SpeakNpcId = 700019
        },
        [51002306] = {
          ContentFR = "Elle le lit en silence, mot après mot. Des larmes coulent de ses yeux plissés.",
          DialogueId = 51002306,
          GUID = "7FADCDD4",
          NextDialogue = 51002307
        },
        [51002307] = {
          ContentFR = "Puis elle serre le journal contre sa poitrine, comme pour enlacer un amour perdu.",
          DialogueId = 51002307,
          GUID = "7FADCDFE",
          NextDialogue = 51002308
        },
        [51002308] = {
          ContentFR = "... Merci, {性别:jeune homme|jeune femme}. Merci de m’avoir rendu ce secret enfoui depuis quarante ans.",
          DialogueId = 51002308,
          GUID = "7FADCE28",
          NextDialogue = 51002309,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51002309] = {
          ContentFR = "S’il te plaît, va voir ma servante Sally pour ta récompense. J’aimerais rester seule un moment...",
          DialogueId = 51002309,
          GUID = "7FADCE52",
          NextDialogue = 51002310,
          SpeakNpcId = 700019
        },
        [51002310] = {
          ContentFR = "Elle tourne le dos. Sa silhouette voûtée se perd dans la lumière froide.",
          DialogueId = 51002310,
          GUID = "7FADCE7C"
        },
        [51002311] = {
          Content = "……",
          DialogueId = 51002311,
          GUID = "7FADCEA6",
          SpeakNpcId = 700019
        },
        [51002312] = {
          Content = "抱歉，我没听过这个名字。如果以后有消息，我会回来找你的。",
          DialogueId = 51002312,
          GUID = "7FADCED0",
          NextDialogue = 51002313,
          SpeakNpcId = 100001
        },
        [51002313] = {
          Content = "好……好，谢谢你，年轻人。",
          DialogueId = 51002313,
          GUID = "7FADCEFA",
          NextDialogue = 51002314,
          SpeakNpcId = 700019
        },
        [51002314] = {
          Content = "我备好了一份薄礼，请你到我家去找我的女仆莎莉吧，就说是希琳夫人让你来的。",
          DialogueId = 51002314,
          GUID = "7FADCF24",
          NextDialogue = 51002315,
          SpeakNpcId = 700019
        },
        [51002315] = {
          Content = "去吧，愿你一路顺风……",
          DialogueId = 51002315,
          GUID = "7FADCF4E",
          SpeakNpcId = 700019
        },
        [51002320] = {
          ContentFR = "Mon enfant, tu es donc {性别:ce Chasseur de Phoxène nommé|cette Chasseuse de Phoxène nommée} {nickname} ? Dame Hilin m’a demandé de te remettre ta récompense en avance.",
          DialogueId = 51002320,
          GUID = "7FADD020",
          NextDialogue = 51002321,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002321] = {
          ContentFR = "Si jamais tu entends parler de Hamel Dickinson, n’hésite pas à le dire rapidement à Dame Hilin.",
          DialogueId = 51002321,
          GUID = "7FADD04A",
          NextDialogue = 51002322,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002322] = {
          ContentFR = "Soupir. Depuis l’année dernière, sa santé décline de plus en plus... Je crains qu’il ne lui reste plus beaucoup de temps. La question de Hamel est son ultime souci...",
          DialogueId = 51002322,
          GUID = "7FADD074",
          NextOptions = {
            [1] = 51002323
          },
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002323] = {
          ContentFR = "Pouvez-vous me raconter ce qui s’est passé avec Hamel Dickinson ?",
          DialogueId = 51002323,
          GUID = "51002323.0",
          NextDialogue = 51002404
        },
        [51002401] = {
          ContentFR = "Merci, mon enfant. Voilà une petite récompense pour tout ce que tu as fait pour nous.",
          DialogueId = 51002401,
          GUID = "7FADDD6A",
          NextDialogue = 51002402,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002402] = {
          ContentFR = "Hélas... Sa Seigneurie dépérit depuis l’an dernier. Elle n’a plus beaucoup de jours devant elle. L’histoire de Monsieur Dickinson ... c’était sa dernière préoccupation.",
          DialogueId = 51002402,
          GUID = "7FADDD94",
          NextDialogue = 51002403,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002403] = {
          ContentFR = "Ce n’est certes pas la bonne nouvelle que nous espérions, mais Tante Sally tient quand même à te remercier, tu as comblé son dernier souhait.",
          DialogueId = 51002403,
          GUID = "7FADDDBE",
          NextOptions = {
            [1] = 510024031
          },
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002404] = {
          ContentFR = "Hélas... je suppose qu’il n’y a plus de raison de garder des secrets maintenant.",
          DialogueId = 51002404,
          GUID = "7FADDDE8",
          NextDialogue = 51002405,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002405] = {
          ContentFR = "Tu l’auras peut-être deviné, mais Monsieur Dickinson était le grand amour de Dame Hilin il y a quarante ans. À l’époque, elle n’était pas encore "dame", on l’appelait Mademoiselle Hilin, une jeune fille vive et passionnée.",
          DialogueId = 51002405,
          GUID = "7FADDE12",
          NextDialogue = 51002406,
          SpeakNpcId = 700020
        },
        [51002406] = {
          ContentFR = "Comme dans toutes ces histoires, plus la différence de rang était grande, plus leur attachement était obstiné. Ils s’accrochaient l’un à l’autre contre l’avis du monde entier.",
          DialogueId = 51002406,
          GUID = "7FADDE3C",
          NextDialogue = 51002407,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002407] = {
          ContentFR = "On raconte que l’amour est comme une flamme : plus on tente de l’éteindre, plus il s’enflamme. Mais ces histoires ne disent pas à quel point, face à la dure réalité, quand la digue cède, cette flamme peut devenir dérisoire.",
          DialogueId = 51002407,
          GUID = "7FADDE66",
          NextDialogue = 51002408,
          SpeakNpcId = 700020
        },
        [51002408] = {
          ContentFR = "Quand la nouvelle parvint aux oreilles du maître, le directeur de la Fosse de Glevum, nommé par les Éolipyliens, Hamel Dickinson n’eut pas de bénédiction. Il reçut une raclée.",
          DialogueId = 51002408,
          GUID = "7FADDE90",
          NextDialogue = 51002409,
          SpeakNpcId = 700020
        },
        [51002409] = {
          ContentFR = "Ce n’était pas seulement à cause de sa condition sociale : le maître avait déjà arrangé pour Mademoiselle un mariage de convenance, avec un noble de la province de Flagson, une alliance parfaite entre nouveaux riches et vieille noblesse déclinante, où chacun y trouvait son compte.",
          DialogueId = 51002409,
          GUID = "7FADDEBA",
          NextDialogue = 51002410,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002410] = {
          ContentFR = "Pourtant, elle n’abandonna pas. Elle me confia une lettre pour Hamel Dickinson, lui donnant rendez-vous le 26 avril, à minuit, sur la Place de la Paix d’Argent.",
          DialogueId = 51002410,
          GUID = "7FADDEE4",
          NextDialogue = 51002411,
          SpeakNpcId = 700020
        },
        [51002411] = {
          ContentFR = "C’était le jour de l’anniversaire de son père, la maison entière serait absorbée par la fête, et elle comptait s’échapper.",
          DialogueId = 51002411,
          GUID = "7FADDF0E",
          NextDialogue = 51002412,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002412] = {
          ContentFR = "Elle était prête à tout quitter, du moment qu’Hamel venait.",
          DialogueId = 51002412,
          GUID = "7FADDF38",
          NextOptions = {
            [1] = 510024141
          },
          SpeakNpcId = 700020
        },
        [51002415] = {
          ContentFR = "Non. Elle l’attendit jusqu’à l’aube. Et à la place, ce fut son père furieux qui l’y trouva. Peu après, elle fut mariée de force à Flagson.",
          DialogueId = 51002415,
          GUID = "7FADDFB6",
          NextDialogue = 51002416,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002416] = {
          ContentFR = "Heureusement, son mari s’avéra bon avec elle. Elle vécut quarante années paisibles. Comme si Hamel Dickinson n’avait jamais existé.",
          DialogueId = 51002416,
          GUID = "7FADDFE0",
          NextDialogue = 51002417,
          SpeakNpcId = 700020
        },
        [51002417] = {
          ContentFR = "Jusqu’à ce qu’il y a un an, son mari décède... Et depuis, la santé de Madame n’a cessé de décliner. Un jour, elle m’a confié qu’avant de quitter ce monde, elle voulait revenir à Givrelac... pour chercher une réponse qu’elle n’avait jamais obtenue. C’est là que j’ai compris : elle n’avait en réalité jamais oublié Hamel Dickinson. Il était devenu comme une écharde plantée dans son cœur.",
          DialogueId = 51002417,
          GUID = "7FADE00A",
          NextDialogue = 51002418,
          SpeakNpcId = 700020
        },
        [51002418] = {
          ContentFR = "Nous nous sommes installées ici, à Givrelac. Mais nul ici ne se souvenait de lui. Quelques vieux mineurs se rappelaient seulement l’avoir aperçu... il y a quarante ans.",
          DialogueId = 51002418,
          GUID = "7FADE034",
          NextDialogue = 51002419,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002419] = {
          ContentFR = "Soupir. Je me demande si Dame Hilin pourra voir s’accomplir son dernier souhait de son vivant.",
          DialogueId = 51002419,
          GUID = "7FADE05E",
          NextDialogue = 51002420,
          SpeakNpcId = 700020
        },
        [51002420] = {
          ContentFR = "Ce ne sont que de vieux souvenirs... Je t’ai peut-être parlé trop longtemps, ça me rappelle que je commence à vieillir.",
          DialogueId = 51002420,
          GUID = "7FADE088",
          NextDialogue = 51002421,
          SpeakNpcId = 700020
        },
        [51002421] = {
          ContentFR = "Tu es un {性别:Chasseur de Phoxène|Chasseuse de Phoxène}, tu dois être très {性别:occupé|occupée} par tes missions, je ne vais donc pas te retenir plus longtemps.",
          DialogueId = 51002421,
          GUID = "7FADE0B2",
          NextDialogue = 51002422,
          SpeakNpcId = 700020
        },
        [51002422] = {
          ContentFR = "Elle n’obtiendra probablement jamais la réponse.",
          DialogueId = 51002422,
          GUID = "7FADE0DC",
          NextDialogue = 51002423
        },
        [51002423] = {
          ContentFR = "Hamel s’est aventuré dans les profondeurs de la Fosse de Glevum pour Dame Hilin, où il est devenu un Souillé, une créature si terrifiante qu’elle est devenue une légende pendant quarante ans. Il a fini par être tué, une vérité bien trop cruelle pour une vieille femme dont le temps est compté.",
          DialogueId = 51002423,
          GUID = "7FADE106",
          NextDialogue = 51002424
        },
        [51002424] = {
          ContentFR = "Cette vérité cruelle restera à jamais enfouie dans les profondeurs de la fosse, tandis que Dame Hilin poursuivra sa vie avec espoir jusqu’à ses derniers jours. Peut-être est-ce là la fin la plus heureuse que l’on puisse espérer.",
          DialogueId = 51002424,
          GUID = "7FADE130"
        },
        [51002425] = {
          ContentFR = "Nous n’aurions jamais imaginé... qu’il avait tenté de la rejoindre. C’est précisément parce qu’il voulait honorer sa promesse qu’il est descendu dans cette fosse... Je ne sais pas si, pour elle, c’est une forme de réconfort... ou une cruauté de plus.",
          DialogueId = 51002425,
          GUID = "7FADE15A",
          NextDialogue = 51002426,
          SpeakNpcId = 700020
        },
        [51002426] = {
          ContentFR = "... Et maintenant, voyant Dame Hilin dans cet état, je ne sais vraiment pas comment la consoler...",
          DialogueId = 51002426,
          GUID = "7FADE184",
          NextDialogue = 51002427,
          SpeakNpcId = 700020
        },
        [51002427] = {
          ContentFR = "Bon... je vais préparer le dîner. J’espère juste que ma soupe pourra la faire se sentir un peu mieux.",
          DialogueId = 51002427,
          GUID = "7FADE1AE",
          NextDialogue = 51002428,
          SpeakNpcId = 700020
        },
        [51002428] = {
          ContentFR = "Ainsi, même si la vérité fut implacable, Dame Hilin a pu trouver sa réponse avant de s’éteindre. Plutôt que d’emporter le doute dans la tombe. Peut-être était-ce, malgré tout, la seule fin possible... et la plus douce qu’elle pouvait espérer.",
          DialogueId = 51002428,
          GUID = "7FADE1D8"
        },
        [51002432] = {
          ContentFR = "Hélas... je suppose qu’il n’y a plus de raison de garder des secrets maintenant.",
          DialogueId = 51002432,
          GUID = "51002432.0",
          NextDialogue = 51002433,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
