          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002443] = {
          ContentFR = "Heureusement, son mari s’avéra bon avec elle. Elle vécut quarante années paisibles. Comme si Hamel Dickinson n’avait jamais existé.",
          DialogueId = 51002443,
          GUID = "51002443.0",
          NextDialogue = 51002444,
          SpeakNpcId = 700020
        },
        [51002444] = {
          ContentFR = "Jusqu’à ce qu’il y a un an, son mari décède... Et depuis, la santé de Madame n’a cessé de décliner. Un jour, elle m’a confié qu’avant de quitter ce monde, elle voulait revenir à Givrelac... pour chercher une réponse qu’elle n’avait jamais obtenue. C’est là que j’ai compris : elle n’avait en réalité jamais oublié Hamel Dickinson. Il était devenu comme une écharde plantée dans son cœur.",
          DialogueId = 51002444,
          GUID = "51002444.0",
          NextDialogue = 51002445,
          SpeakNpcId = 700020
        },
        [51002445] = {
          ContentFR = "Nous nous sommes installées ici, à Givrelac. Mais nul ici ne se souvenait de lui. Quelques vieux mineurs se rappelaient seulement l’avoir aperçu... il y a quarante ans.",
          DialogueId = 51002445,
          GUID = "51002445.0",
          NextDialogue = 51002425,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002501] = {
          ContentFR = "Va... va-t’en... si tu n’achètes pas de Phoxène, ne reste pas ici... et n’attire pas ces foutus soldats sur moi...",
          DialogueId = 51002501,
          GUID = "7FADEDD2",
          NextDialogue = 51002502,
          SpeakNpcId = 700113,
          TalkActionId = {
            [1] = "700113:Shock_Start"
          }
        },
        [51002502] = {
          ContentFR = "L’homme, pourtant bâti comme un colosse, se recroqueville dans un coin. Son regard fuyant trahit sa nervosité. À ses côtés, un sac rempli de Phoxènes qu’il semble vouloir vendre à tout prix... mais il hésite encore à demander de l’aide.",
          DialogueId = 51002502,
          GUID = "7FADEDFC",
          TalkActionId = {
            [1] = "700113:Shock_End"
          },
          TalkOptions = {
            [1] = 510025021,
            [2] = 510025022,
            [3] = 510025023,
            [4] = 510025024
          }
        },
        [51002503] = {
          ContentFR = "Ayez pitié... Faites comme si je n’existais pas... Dès que j’ai vendu ce Phoxène, je quitte Givrelac pour de bon, je le jure !",
          DialogueId = 51002503,
          GUID = "7FADEE26",
          SpeakNpcId = 700113
        },
        [51002504] = {
          ContentFR = "À ces mots, l’homme agrippe son sac et s’enfuit. Tu parviens à l’arrêter de justesse et, après lui avoir expliqué qu’il s’agissait d’une plaisanterie, il t’avoue à voix basse ses véritables difficultés.",
          DialogueId = 51002504,
          GUID = "7FADEE50"
        },
        [51002505] = {
          ContentFR = "Trouve-moi un acheteur et je te laisse 70 %... Non, 80 % ! Je t’en supplie, aide-moi !",
          DialogueId = 51002505,
          GUID = "7FADEE7A",
          SpeakNpcId = 700113,
          TalkActionId = {
            [1] = "700113:Sigh_Start"
          }
        },
        [51002506] = {
          ContentFR = "Tu acceptes sa requête, mais son attitude nerveuse et les traces rouge sombre séchées sur son sac ne laissent guère de doute : cette cargaison de Phoxène n’a pas une origine très nette.",
          DialogueId = 51002506,
          GUID = "7FADEEA4",
          TalkActionId = {
            [1] = "700113:Sigh_End"
          }
        },
        [51002601] = {
          ContentFR = "Magnifique, {nickname} n’est pas là aujourd’hui...",
          DialogueId = 51002601,
          GUID = "7FADFE3A",
          NextDialogue = 51002602,
          SpeakNpcId = 700111,
          TalkActionId = {
            [1] = "700111:Think_Start"
          }
        },
        [51002602] = {
          ContentFR = "Tu me cherchais ?",
          DialogueId = 51002602,
          GUID = "7FADFE64",
          NextDialogue = 51002603,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700111:Think_End"
          }
        },
        [51002603] = {
          ContentFR = "... Hein ?! Ah ! Tu tombes toujours du ciel, toi !",
          DialogueId = 51002603,
          GUID = "7FADFE8E",
          NextOptions = {
            [1] = 510026031
          },
          SpeakNpcId = 700111,
          TurnTo = {
            [1] = "700111:n(0)"
          },
          bForbidSkipOptions = true
        },
        [51002604] = {
          ContentFR = "Quoi... tu te fiches de moi ? Tu veux juste me balancer une corvée dans les pattes, hein ?",
          DialogueId = 51002604,
          GUID = "7FADFEB8",
          SpeakNpcId = 700111,
          TalkActionId = {
            [1] = "700111:Disagree"
          }
        },
        [51002605] = {
          ContentFR = "Près du portail, le téléphone sonne brusquement. Kevin sursaute comme un lapin effarouché et se précipite pour décrocher.",
          DialogueId = 51002605,
          GUID = "7FADFEE2",
          NextDialogue = 51002606,
          TurnTo = {
            [1] = "700111:p(90)"
          }
        },
        [51002606] = {
          ContentFR = "Ici Kevin... Quoi ? Des mouvements suspects en ville ? Compris, j’arrive !",
          DialogueId = 51002606,
          GUID = "7FADFF0C",
          NextDialogue = 51002607,
          SpeakNpcId = 700111,
          TalkActionId = {
            [1] = "700111:Agree"
          }
        },
        [51002607] = {
          ContentFR = "... Ça doit être le type dont tu me parlais. Allez, montre-moi le chemin.",
          DialogueId = 51002607,
          GUID = "7FADFF36",
          Scripts = "SEQ{TurnTo{TurnToDescription{"700111:n(0)"}},PlayAnimation{ActorId{700111},AnimationId{"Think_Start"},Duration{2}}}",
          SpeakNpcId = 700111
        },
        [51002701] = {
          Camera = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tiens donc... mais c’est pas notre ancien mineur modèle, Larry ? T’étais toujours entouré de tes copains. Où sont-ils passés, aujourd’hui ?",
          DialogueId = 51002701,
          GUID = "7FAE0EA2",
          NextDialogue = 51002702,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700112:Talk01_Start",
            [2] = "100001:Confident_Start"
          },
          TurnTo = {
            [1] = "700114:n(700112)"
          }
        },
        [51002702] = {
          Camera = "11.023438,10.769531,127.256836,0.0,0.0,8.403177,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les... Veilleurs ?!",
          DialogueId = 51002702,
          FinalCamera = "39.697266,15.063477,127.256836,0.0,0.0,8.403239,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAE0ECC",
          NextDialogue = 51002703,
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700114:Shock_Start",
            [2] = "700112:Talk01_End",
            [3] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 1
        },
        [51002703] = {
          Camera = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peu importe. Toi, en revanche... tu sais que l’extraction et la vente clandestine de Phoxène sont interdites, pas vrai ? J’ai reçu l’ordre de— Attends... qu’est-ce que c’est que ces taches de sang sur ton sac ?",
          DialogueId = 51002703,
          GUID = "7FAE0EF6",
          NextDialogue = 51002704,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700114:Shock_End",
            [2] = "700112:Talk01_Start"
          }
        },
        [51002704] = {
          Camera = "-24.264648,5.625977,122.256836,0.0,0.0,8.403694,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je... je...",
          DialogueId = 51002704,
          GUID = "7FAE0F20",
          NextDialogue = 51002705,
          Scripts = "SEQ{LookAt{LookAtDescription{"700114:n(100001)"}},LookAt{LookAtDescription{"700114:n(700114)"}}}",
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700112:Talk01_End"
          }
        },
        [51002705] = {
          Camera = "121.136719,-1.510742,123.537598,0.000002,0.399996,-168.191696,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas un geste ! {nickname}, aide-moi !",
          DialogueId = 51002705,
          GUID = "7FAE0F4A",
          Scripts = "SEQ{PlayAnimation{ActorId{700112},AnimationId{"Angry01_Start"},Duration{2}},LookAt{LookAtDescription{"700112:n(100001)"}},PlayAnimation{ActorId{100001},AnimationId{"Talk03_Start"},Duration{1}}}",
          SpeakNpcId = 700112
        },
        [51002801] = {
          Camera = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Toi... espèce de traître ! Tu m’as vendu aux soldats !",
          DialogueId = 51002801,
          GUID = "7FAE1F0A",
          NextDialogue = 51002802,
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700114:Sigh_Start"
          }
        },
        [51002802] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Silence ! Les mains bien visibles... tiens-les bien écartées et lâche ce sac !",
          DialogueId = 51002802,
          GUID = "7FAE1F34",
          NextDialogue = 51002803,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700112:Angry01_Start"
          }
        },
        [51002803] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le canon braqué contre son front, Larry hésite. Puis ses doigts se desserrent et le sac s’écrase au sol. Le Phoxène s’en échappe, luisant... et couvert de sang.",
          DialogueId = 51002803,
          GUID = "7FAE1F5E",
          NextDialogue = 51002804,
          TalkActionId = {
            [1] = "700114:Sigh_End",
            [2] = "700112:Angry01_End"
          }
        },
        [51002804] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Bon sang. Tu les as tués à coups de pierres ? Tes propres compagnons ?",
          DialogueId = 51002804,
          GUID = "7FAE1F88",
          NextDialogue = 51002805,
          SpeakNpcId = 700112
        },
        [51002805] = {
          Camera = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est eux qui ont attaqué les premiers ! Je... je me suis défendu !",
          DialogueId = 51002805,
          GUID = "7FAE1FB2",
          NextDialogue = 51002806,
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700114:Sigh_Start"
          }
        },
        [51002806] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peu importe que tu t’en défendes ou non, ça ne dépend pas de moi. Tu viens avec nous.",
          DialogueId = 51002806,
          GUID = "7FAE1FDC",
          NextDialogue = 51002807,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700114:Sigh_End",
            [2] = "700112:Talk01_Start"
          }
        },
        [51002807] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas ma faute... pas ma faute ! C’est ce sac de Phoxène, tout est de sa faute ! Si on ne l’avait pas trouvé, on serait encore ensemble... tous vivants... tous...",
          DialogueId = 51002807,
          GUID = "7FAE2006",
          NextDialogue = 51002808,
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700114:Disagree",
            [2] = "700112:Talk01_End"
          }
        },
        [51002808] = {
          Camera = "121.290039,-83.856445,144.21875,0.000003,-0.999905,-165.995453,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Soupir...",
          DialogueId = 51002808,
          GUID = "7FAE2030",
          NextDialogue = 51002809,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700112:Disagree"
          }
        },
        [51002809] = {
          Camera = "-3.327148,-490.567383,115.4375,0.000011,0.0,94.803833,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avant que j’oublie, merci, {nickname}, d’avoir aidé les Veilleurs. Voici ta récompense.",
          DialogueId = 51002809,
          GUID = "7FAE205A",
          Scripts = "SEQ{PARA{TurnTo{TurnToDescription{"700112:n(100001)"}},TurnTo{TurnToDescription{"100001:n(700112)"}}},PlayAnimation{ActorId{700112},AnimationId{"Agree"},Duration{1}},PlayAnimation{ActorId{700112},AnimationId{"Talk01_Start"},Duration{1}}}",
          SpeakNpcId = 700112
        },
        [51002810] = {
          ContentFR = "Kevin s’éloigne, emmenant Larry à travers la neige.",
          DialogueId = 51002810,
          Duration = 2,
          GUID = "7FAE2084",
          NextDialogue = 51002811
        },
        [51002811] = {
          ContentFR = "Les "pierres ensanglantées" tombent dans le silence, leur histoire macabre bientôt recouverte par un autre flocon de Givrelac.",
          DialogueId = 51002811,
          Duration = 4,
          GUID = "7FAE20AE"
        },
        [51002901] = {
          ContentFR = "Un homme à la voix puissante tient l’assemblée captive. Ses récitations théâtrales arrachent des rires aux habitués.",
          DialogueId = 51002901,
          GUID = "7FAE2F72",
          NextDialogue = 51002902
        },
        [51002902] = {
          ContentFR = "Des spectres surgis des montagnes profondes ! Des fantômes échappés du lac de glace lui-même !",
          DialogueId = 51002902,
          GUID = "7FAE2F9C",
          NextDialogue = 51002903,
          SpeakNpcId = 700015
        },
        [51002903] = {
          ContentFR = "Ils approchent ! Ils se rapprochent !",
          DialogueId = 51002903,
          GUID = "7FAE2FC6",
          NextDialogue = 51002904,
          SpeakNpcId = 700015
        },
        [51002904] = {
          ContentFR = "Ah, te voilà.",
          DialogueId = 51002904,
          GUID = "7FAE2FF0",
          NextOptions = {
            [1] = 510029041
          },
          SpeakNpcId = 200003
        },
        [51002905] = {
          ContentFR = "Pour le moment, je n’ai pas de contrat officiel pour toi, mais...",
          DialogueId = 51002905,
          GUID = "7FAE301A",
          NextDialogue = 51002906,
          SpeakNpcId = 200003
        },
        [51002906] = {
          ContentFR = "... Vous ne pouvez pas imaginer !",
          DialogueId = 51002906,
          GUID = "7FAE3044",
          NextDialogue = 51002907,
          SpeakNpcId = 700015
        },
        [51002907] = {
          ContentFR = "Un spectre ! Une ombre muette qui traverse les portes comme si elles n’existaient pas !",
          DialogueId = 51002907,
          GUID = "7FAE306E",
          NextDialogue = 51002908,
          SpeakNpcId = 700015
        },
        [51002908] = {
          ContentFR = "Comme tu peux l’entendre, il y en a toujours un qui se met dans de beaux draps...",
          DialogueId = 51002908,
          GUID = "7FAE3098",
          NextOptions = {
            [1] = 510029081
          },
          SpeakNpcId = 200003
        },
        [51002909] = {
          ContentFR = "Monsieur Buck. Incapable de tenir l’alcool... alors il se gave de lait et de jus de fruits. Son métier ? Dramaturge raté. Mais pour bavarder, il mérite la palme. Regarde-le, il marmonne sans s’arrêter.",
          DialogueId = 51002909,
          GUID = "7FAE30C2",
          NextDialogue = 51002910,
          SpeakNpcId = 200003
        },
        [51002910] = {
          ContentFR = "Tu le vois bien, il est incapable d’être clair. Peut-être que toi, tu arriveras à décoder ses balivernes.",
          DialogueId = 51002910,
          GUID = "7FAE30EC",
          NextOptions = {
            [1] = 510029101
          },
          RestartTag = 51002910,
          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51002911] = {
          ContentFR = "Ne sois pas déçu. À Givrelac, pas plus de cinq personnes comprennent un mot de ses délires.",
          DialogueId = 51002911,
          GUID = "7FAE3116",
          SpeakNpcId = 200003
        },
        [51002912] = {
          ContentFR = "Avec ton esprit vif, tu dois bien être la seule personne ici capable de comprendre ce qu’il raconte.",
          DialogueId = 51002912,
          GUID = "7FAE3140",
          SpeakNpcId = 200003
        },
        [51003001] = {
          ContentFR = "Tu tends l’oreille pour écouter les envolées lyriques du dramaturge.",
          DialogueId = 51003001,
          GUID = "7FAE3FDA",
          NextDialogue = 51003002
        },
        [51003002] = {
          ContentFR = "Les nuits des poètes sont interminables... et celles des dramaturges ne font pas exception ! Nos plumes tracent le rythme des hommes, et nos cœurs battent à l’unisson avec la lune et la marée !",
          DialogueId = 51003002,
          GUID = "7FAE4004",
          NextDialogue = 51003003,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          }
        },
        [51003003] = {
          ContentFR = "Quand tombent les ténèbres, je rejette l’éclat aveuglant du soleil, le vacarme du monde et les pensées agitées. Alors seulement vient l’heure où je puis converser intimement avec l’univers !",
          DialogueId = 51003003,
          GUID = "7FAE402E",
          NextOptions = {
            [1] = 510030031,
            [2] = 510030032
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          },
          bForbidSkipOptions = true
        },
        [51003004] = {
          ContentFR = "Ah ! Peut-être ai-je offensé, sans le savoir, la déesse de l’inspiration... soit le dieu du sommeil a décidé de se jouer de moi ! Autrement, comment aurais-je pu laisser filer le temps sans même m’en rendre compte ?",
          DialogueId = 51003004,
          GUID = "7FAE4058",
          NextDialogue = 51003005,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_Start"
          }
        },
        [51003005] = {
          ContentFR = "J’aurais dû accueillir l’aube avec des pages couvertes de mots et de vers. Mais au lieu de cela, je me suis réveillé... reposé, certes, mais l’âme vide, et devant moi, des feuillets vierges !",
          DialogueId = 51003005,
          GUID = "7FAE4082",
          NextOptions = {
            [1] = 510030051,
            [2] = 510030052
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_End"
          },
          bForbidSkipOptions = true
        },
        [51003006] = {
          ContentFR = "Dans mes songes enivrants, j’ai entendu des pas discrets, légers comme la danse des fées. Et un parfum de fruits mûrs nappés de miel m’a caressé les sens !",
          DialogueId = 51003006,
          GUID = "7FAE40AC",
          NextDialogue = 51003007,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Explain01_Start"
          }
        },
        [51003007] = {
          ContentFR = "Peut-être étais-je perdu dans mes rêves... Mais ces sons et ces senteurs m’ont ramené à la réalité. Ils étaient insaisissables, flottant tout autour de moi... et pourtant, j’en suis certain : ils existaient vraiment !",
          DialogueId = 51003007,
          GUID = "7FAE40D6",
          NextOptions = {
            [1] = 510030071,
            [2] = 510030072
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51003008] = {
          ContentFR = "Ce ne sont pas des hallucinations ! Mais je n’arrive pas à en saisir les traces, à percer ce mystère... Fantômes ? Spectres ? Illusions ?",
          DialogueId = 51003008,
          GUID = "7FAE4100",
          NextDialogue = 51003009,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Disagree"
          }
        },
        [51003009] = {
          ContentFR = "Ma pauvre bicoque n’a pas changé d’un poil... Pourtant, on m’a volé ce que j’ai de plus précieux : mon inspiration, ma raison de vivre ! À ce rythme, mes rêves vont s’écrouler...",
          DialogueId = 51003009,
          GUID = "7FAE412A",
          NextOptions = {
            [1] = 510030091,
            [2] = 510030092
          },
          SpeakNpcId = 700015,
          bForbidSkipOptions = true
        },
        [51003010] = {
          ContentFR = "Les nuits d’un dramaturge ne sauraient être sacrifiées au sommeil ! Qui parmi vous répondra à mon appel ? Qui pourchassera ce voleur d’inspiration, afin que mon chef-d’œuvre voie le jour ?",
          DialogueId = 51003010,
          GUID = "7FAE4154",
          NextDialogue = 51003011,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_Start"
          }
        },
        [51003011] = {
          ContentFR = "Je vous offrirai la gloire... Peut-être même le rôle du héros dans ma prochaine pièce ! Montrez-moi votre talent, et je chanterai vos exploits, ô Chasseur de Phoxène !",
          DialogueId = 51003011,
          GUID = "7FAE417E",
          NextOptions = {
            [1] = 510030111,
            [2] = 510030112
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51003012] = {
          ContentFR = "Ça n’aura sans doute aucun profit, mais c’est divertissant. Tu t’en charges ou pas ?",
          DialogueId = 51003012,
          GUID = "7FAE41A8",
          NextOptions = {
            [1] = 510030121,
            [2] = 510030122
          },
          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51003013] = {
          ContentFR = "Oh ! {性别:Un champion|Une championne} répond à mon appel ! Voilà peut-être le prélude d’une nouvelle épopée !",
          DialogueId = 51003013,
          GUID = "7FAE41D2",
          NextDialogue = 51003014,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          },
          TurnTo = {
            [1] = "700015:n(0)"
          }
        },
        [51003014] = {
          ContentFR = "Je suis avide de savoir ce que vous allez découvrir... Revenez me conter vos aventures !",
          DialogueId = 51003014,
          GUID = "7FAE41FC",
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          }
        },
        [51003101] = {
          ContentFR = "Camila a dit que Monsieur Buck ne boit jamais... Alors ? Quelqu’un a mis de l’alcool dans son lait ?",
          DialogueId = 51003101,
          GUID = "7FAE5042",
          NextDialogue = 51003102,
          SpeakNpcId = 100001
        },
        [51003102] = {
          ContentFR = "Mmmh... Il y a une empreinte collante sur la bouteille. Elle est minuscule... On dirait une main d’enfant.",
          DialogueId = 51003102,
          GUID = "7FAE506C",
          SpeakNpcId = 100001
        },
        [51003103] = {
          ContentFR = "Ces traces vont de la rue jusqu’à la fenêtre. Et à l’intérieur, la neige a fondu... Aucun effort pour dissimuler les preuves. C’était juste un enfant.",
          DialogueId = 51003103,
          GUID = "7FAE5096",
          SpeakNpcId = 100001
        },
        [51003104] = {
          ContentFR = "On dirait bien qu’un enfant a mis de l’alcool dans le lait pour saouler Monsieur Buck. Cherchons d’autres indices.",
          DialogueId = 51003104,
          Duration = 4,
          GUID = "7FAE50C0",
          SpeakNpcId = 100001
        },
        [51003105] = {
          ContentFR = "Excusez-moi... Est-ce que des enfants viennent parfois voir Monsieur Buck ?",
          DialogueId = 51003105,
          GUID = "7FAE50EA",
          NextDialogue = 51003106,
          SpeakNpcId = 100001
        },
        [51003106] = {
          ContentFR = "Des enfants ? Chez Buck ? Allons donc ! Ce type passe son temps <H>entre sa maison, la taverne et le théâtre</>. Et quand il ouvre la bouche, c’est un charabia de théâtre de seconde zone !",
          DialogueId = 51003106,
          GUID = "7FAE5114",
          NextDialogue = 51003107,
          SpeakNpcId = 700213
        },
        [51003107] = {
          ContentFR = "Pas que les enfants, hein. Nous non plus, on n’a pas envie de lui parler. On n’y comprend rien et il nous tape sur les nerfs. Il a fait quelque chose de mal ? Je le savais, je l’ai toujours trouvé louche !",
          DialogueId = 51003107,
          GUID = "7FAE513E",
          NextDialogue = 51003108,
          SpeakNpcId = 700213
        },
        [51003108] = {
          ContentFR = "La vieille femme enchaîne les reproches : trop vieux pour ne pas avoir de vrai métier, cloîtré chez lui, pas de femme, pas d’amis... Tu ne parviens à t’éclipser qu’une fois qu’elle est complètement à bout de souffle.",
          DialogueId = 51003108,
          GUID = "7FAE5168",
          NextDialogue = 51003109
        },
        [51003109] = {
          ContentFR = "Il vit reclus, personne ne sait rien de lui. Si un enfant a découvert qu’il s’endormait facilement avec de l’alcool... c’est qu’il l’a appris ailleurs.",
          DialogueId = 51003109,
          GUID = "7FAE5192",
          NextDialogue = 51003110,
          SpeakNpcId = 100001
        },
        [51003110] = {
          ContentFR = "Pas d’enfants aux Asphodèles, ni autour de sa maison... Il reste une possibilité, le théâtre.",
          DialogueId = 51003110,
          GUID = "7FAE51BC",
          SpeakNpcId = 100001
        },
        [51003111] = {
          ContentFR = "Un jeune Charon frissonne près du guichet, vendant affiches, billets, bières et pop-corn.",
          DialogueId = 51003111,
          GUID = "7FAE51E6",
          NextDialogue = 51003112
        },
        [51003112] = {
          ContentFR = "Un enfant qui vend du pop-corn... Et si c’était lui qui avait saoulé Buck ?",
          DialogueId = 51003112,
          GUID = "7FAE5210",
          SpeakNpcId = 100001
        },
        [51003113] = {
          ContentFR = "Monsieur Buck passe tout son temps au théâtre. Il a forcément croisé cet enfant plus d’une fois. Il a probablement refusé qu’on lui vendre de la bière à chaque fois...",
          DialogueId = 51003113,
          Duration = 3,
          GUID = "7FAE523A",
          NextDialogue = 51003114,
          SpeakNpcId = 100001
        },
        [51003114] = {
          ContentFR = "Et ce pop-corn sur la manche de l’enfant ? Ils correspondent exactement à ce que j’ai trouvé sous la fenêtre de Monsieur Buck. Tout l’accuse. Il est temps de discuter.",
          DialogueId = 51003114,
          Duration = 4,
          GUID = "7FAE5264",
          SpeakNpcId = 100001
        },
        [51003115] = {
          ContentFR = "Hic ! Encore une ! Pff, vingt bouteilles, c’est rien du tout ! Allez, servez !",
          DialogueId = 51003115,
          GUID = "7FAE528E",
          NextDialogue = 51003116,
          SpeakNpcId = 700214
        },
        [51003116] = {
          ContentFR = "Un ivrogne... Et si c’était lui qui avait saoulé Buck ?",
          DialogueId = 51003116,
          GUID = "7FAE52B8",
          SpeakNpcId = 100001
        },
        [51003117] = {
          ContentFR = "Papa, ça a quel goût, le pop-corn ? Je peux goûter ?",
          DialogueId = 51003117,
          GUID = "7FAE52E2",
          LookAt = {
            [1] = "700215:n(700219)",
            [2] = "700219:n(700215)"
          },
          NextDialogue = 51003118,
          SpeakNpcId = 700215
        },
        [51003118] = {
          ContentFR = "Non, ma fille. Une demoiselle ne mange pas de cochonneries. Après l’opéra, je t’emmènerai dîner au restaurant Paix d’Argent.",
          DialogueId = 51003118,
          GUID = "7FAE530C",
          NextDialogue = 51003119,
          SpeakNpcId = 700219,
          TalkActionId = {
            [1] = "700219:Talk03_Start"
          }
        },
        [51003119] = {
          ContentFR = "D’accord...",
          DialogueId = 51003119,
          GUID = "7FAE5336",
          NextDialogue = 51003120,
          SpeakNpcId = 700215,
          TalkActionId = {
            [1] = "700219:Talk03_End"
          }
        },
        [51003120] = {
          ContentFR = "Une gamine qui rêvait de pop-corn. Et si c’était elle ?",
          DialogueId = 51003120,
          GUID = "7FAE5360",
          SpeakNpcId = 100001
        },
        [51003301] = {
          ContentFR = "Atchoum ! On dirait qu’il fait encore plus froid...",
          DialogueId = 51003301,
          GUID = "7FAE7112",
          NextDialogue = 51003302,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_Start"
          }
        },
        [51003302] = {
          ContentFR = "Même pour un Charon, il y a des limites au froid. Ce soir, il fera au moins vingt degrés de moins... Et sûrement des enfants vont encore mourir de froid... Soupir...",
          DialogueId = 51003302,
          GUID = "7FAE713C",
          NextDialogue = 51003303,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_End"
          }
        },
        [51003303] = {
          ContentFR = "Bonjour.",
          DialogueId = 51003303,
          GUID = "7FAE7166",
          NextDialogue = 51003304,
          SpeakNpcId = 100001
        },
        [51003304] = {
          ContentFR = "Bienvenue, honorable {性别:spectateur|spectatrice} ! Après trois heures d’opéra, vous devez avoir faim ! Voulez-vous quelque chose à grignoter et à boire ?",
          DialogueId = 51003304,
          GUID = "7FAE7190",
          NextDialogue = 51003305,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003305] = {
          ContentFR = "Ou peut-être avez-vous été {性别:ému|émue} par la performance exceptionnelle et aimeriez-vous jeter un coup d’œil à une affiche signée par les comédiens ?",
          DialogueId = 51003305,
          GUID = "7FAE71BA",
          NextOptions = {
            [1] = 510033051,
            [2] = 510033052
          },
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003306] = {
          ContentFR = "Montre-moi ce que tu vends.",
          DialogueId = 51003306,
          GUID = "7FAE71E4",
          NextDialogue = 51003307,
          SpeakNpcId = 100001
        },
        [51003307] = {
          ContentFR = "Une affiche dédicacée par Vitti, des albums souvenirs des Contes de Givrelac, de l’eau glacée des glaciers, du pop-corn édition spéciale théâtre... et de la bière rafraîchissante !",
          DialogueId = 51003307,
          GUID = "7FAE720E",
          NextDialogue = 51003308,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_Start"
          }
        },
        [51003308] = {
          ContentFR = "Pas d’inquiétude ! Cela ne contient presque pas d’alcool et ne vous rendra pas ivre !",
          DialogueId = 51003308,
          GUID = "7FAE7238",
          NextDialogue = 51003309,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_End"
          }
        },
        [51003309] = {
          ContentFR = "Ça, j’en doute... Tu connais Monsieur Buck ?",
          DialogueId = 51003309,
          GUID = "7FAE7262",
          NextDialogue = 51003310,
          SpeakNpcId = 100001
        },
        [51003310] = {
          ContentFR = "Bien sûr ! C’est un habitué. Un noble, mais respectueux des enfants Charons comme moi. Un homme bien, croyez-moi.",
          DialogueId = 51003310,
          GUID = "7FAE728C",
          NextDialogue = 51003311,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Agree"
          }
        },
        [51003311] = {
          ContentFR = "Je sais que certains se moquent de lui. Mais comparé à ces gens-là, Monsieur Buck mérite vraiment le respect.",
          DialogueId = 51003311,
          GUID = "7FAE72B6",
          NextDialogue = 51003312,
          SpeakNpcId = 700080
        },
        [51003312] = {
          ContentFR = "C’est peut-être vrai, mais je doute que cela te donne le droit de t’introduire chez lui par la fenêtre et verser de la bière dans son lait.",
          DialogueId = 51003312,
          GUID = "7FAE72E0",
          NextDialogue = 51003313,
          SpeakNpcId = 100001
        },
        [51003313] = {
          ContentFR = "Qu... Comment tu sais ça... ?",
          DialogueId = 51003313,
          GUID = "7FAE730A",
          NextDialogue = 51003321,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Shock_Start"
          }
        },
        [51003314] = {
          ContentFR = "Monsieur Buck a l’habitude d’écrire ses œuvres la nuit. Tes actions ont fait qu’il n’a rien écrit depuis un mois, alors il m’a engagé pour trouver le "voleur d’inspiration".",
          DialogueId = 51003314,
          GUID = "7FAE7334",
          NextOptions = {
            [1] = 510033141
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700080:Shock_End"
          },
          bForbidSkipOptions = true
        },
        [51003315] = {
          ContentFR = "Tu hésites, tes mots se brouillent. Il te faut reformuler ta pensée.",
          DialogueId = 51003315,
          GUID = "7FAE735E"
        },
        [51003316] = {
          ContentFR = "Tes ventes ne suffisent pas à couvrir tes besoins pendant l’hiver. Monsieur Buck, même pauvre, reste un noble, sa maison est chauffée. Alors tu t’y es introduit pour survivre au froid.",
          DialogueId = 51003316,
          GUID = "7FAE7388",
          NextDialogue = 51003317,
          SpeakNpcId = 100001
        },
        [51003317] = {
          ContentFR = "Quant à savoir pourquoi tu as choisi Monsieur Buck, c’est parce que tu savais qu’une goutte d’alcool suffisait à l’endormir. Tu pourrais alors dormir chez lui sans avoir peur de mourir de froid. Ai-je raison ?",
          DialogueId = 51003317,
          GUID = "7FAE73B2",
          NextDialogue = 51003318,
          SpeakNpcId = 100001
        },
        [51003318] = {
          ContentFR = "... Vous êtes {性别:un vrai|une vraie} détective. Tout est vrai.",
          DialogueId = 51003318,
          GUID = "7FAE73DC",
          NextDialogue = 51003319,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003319] = {
          ContentFR = "Vous pouvez m’arrêter. Je suis vraiment désolé pour ce que j’ai fait. Mais si je ne l’avais pas fait, je serais mort dehors.",
          DialogueId = 51003319,
          GUID = "7FAE7406",
          NextDialogue = 51003320,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          }
        },
        [51003320] = {
          ContentFR = "Ce n’est pas à moi d’en décider. Je vais te conduire à mon client.",
          DialogueId = 51003320,
          GUID = "7FAE7430",
          SpeakNpcId = 100001
        },
        [51003321] = {
          ContentFR = "Comme je le pensais.",
          DialogueId = 51003321,
          GUID = "7FAE730B",
          NextDialogue = 51003314,
          SpeakNpcId = 100001
        }
      }
    end
  },
  {
