        },
        [51003406] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah, petit filou, je sais comment l’on se moque de moi dans l’ombre, on m’insulte, on me traite de dramaturge sans valeur dont les œuvres ne voient jamais la lumière.",
          DialogueId = 51003406,
          GUID = "7FAE824C",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003407,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          }
        },
        [51003407] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Même en parant mes phrases des plus belles parures, je n’ai pas su gagner leur estime, ils refusent d’écouter, refusent de comprendre... Pourtant, qui donc parle encore vrai de nos jours ?",
          DialogueId = 51003407,
          GUID = "7FAE8276",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003408,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk03_Start"
          }
        },
        [51003408] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Monsieur, je ne saisis pas ce que vous voulez dire.",
          DialogueId = 51003408,
          GUID = "7FAE82A0",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003409,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Talk03_End",
            [2] = "700103:Disagree"
          }
        },
        [51003409] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je veux dire que toi, tu ne m’as jamais pris pour un rêveur idiot, pour cela, tu as mon respect. Si l’hiver t’a été si cruel, pourquoi ne pas être venu me voir plus tôt ?",
          DialogueId = 51003409,
          GUID = "7FAE82CA",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003410,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Agree"
          }
        },
        [51003410] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je te préparerai une chambre. Si tu le souhaites, prends mes manuscrits pour histoires du soir, même si je ne garantis pas qu’elles te feront dormir.",
          DialogueId = 51003410,
          GUID = "7FAE82F4",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003411,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Explain01_Start"
          }
        },
        [51003411] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous voulez vraiment m’héberger... ? Je ne mérite pas tant, mais je peux vous rendre service, faire des petites tâches, payer ma dette en travaillant pour vous...",
          DialogueId = 51003411,
          GUID = "7FAE831E",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003412,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Explain01_End",
            [2] = "700103:Explain02_Start"
          }
        },
        [51003412] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci pour tout ce que vous avez fait, noble {性别:Chasseur de Phoxène|Chasseuse de Phoxène} ! Détective averti de Givrelac, vous êtes sans pareil, j’y gagne une histoire touchante et, mieux encore, deux véritables amis.",
          DialogueId = 51003412,
          GUID = "7FAE8348",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003413,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          },
          TurnTo = {
            [1] = "700102:n(100001)"
          }
        },
        [51003413] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah ! L’inspiration me submerge ! Il me faut noter tout cela sur-le-champ, et si mes vers voyagent, votre nom sera loué à travers les siècles !",
          DialogueId = 51003413,
          GUID = "7FAE8372",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk01_Start"
          }
        },
        [51003414] = {
          ContentFR = "Les deux s’en vont ensemble, chacun a obtenu ce qu’il souhaitait. Reste à voir si la prochaine pièce de Monsieur Buck tiendra les promesses de son enthousiasme.",
          DialogueId = 51003414,
          Duration = 4,
          GUID = "7FAE839C"
        },
        [51003501] = {
          Camera = "-813.361816,168.229736,207.784668,0.000003,-6.799986,-16.405685,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Gloire au sacrifice, hommage à la compassion, et louange à la Paix d’Argent, gardienne qui nous protégea de la peste, de l’ignorance et de la menace des démons.",
          DialogueId = 51003501,
          GUID = "7FAE91E2",
          NextDialogue = 51003520,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_Start"
          }
        },
        [51003502] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Emma ? Emma !? À quoi penses-tu encore ?",
          DialogueId = 51003502,
          GUID = "7FAE920C",
          LookAt = {
            [1] = "700016:n(700086)"
          },
          NextDialogue = 51003503,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_End",
            [2] = "700086:Confident_Start"
          }
        },
        [51003503] = {
          Camera = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh, pardon maîtresse ! J’y vais tout de suite !",
          DialogueId = 51003503,
          GUID = "7FAE9236",
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700086:Confident_End",
            [2] = "700016:Shock_Start"
          }
        },
        [51003504] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu es ailleurs ces temps-ci. La prochaine fois, tâche de rester concentrée.",
          DialogueId = 51003504,
          GUID = "7FAE9260",
          NextDialogue = 510035041,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Sigh_Start"
          }
        },
        [51003505] = {
          ContentFR = "Pff... c’est trop ennuyeux... Je me demande ce que Mamie est en train de faire...",
          DialogueId = 51003505,
          GUID = "7FAE928A",
          NextOptions = {
            [1] = 510035051,
            [2] = 510035052,
            [3] = 510035053
          },
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003506] = {
          ContentFR = "Enfin bon... j’ai mes raisons. Je peux te les dire, mais tu dois promettre de ne rien répéter.",
          DialogueId = 51003506,
          GUID = "7FAE92B4",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035061
          },
          RestartTag = 51003506,
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003507] = {
          ContentFR = "Franchement, un peu oui.",
          DialogueId = 51003507,
          GUID = "7FAE92DE",
          SpeakNpcId = 700016
        },
        [51003508] = {
          ContentFR = "Bon... d’accord, je vais te le dire.",
          DialogueId = 51003508,
          GUID = "7FAE9308",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextDialogue = 51003509,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_Start"
          }
        },
        [51003509] = {
          ContentFR = "Le mois dernier, je me suis faufilée dans les taudis. Et là, dans une ruelle, j’ai rencontré une vieille dame mystérieuse ! Elle s’appelle Belinda.",
          DialogueId = 51003509,
          GUID = "7FAE9332",
          NextDialogue = 51003510,
          SpeakNpcId = 700016
        },
        [51003510] = {
          ContentFR = "Elle a des doigts magiques, elle sait tresser des coiffures incroyables, colorer mes ongles avec des fleurs fraîches, et elle connaît des histoires que je n’avais jamais entendues de ma vie !",
          DialogueId = 51003510,
          GUID = "7FAE935C",
          NextDialogue = 51003511,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_End"
          }
        },
        [51003511] = {
          ContentFR = "Elle ne me fait jamais la leçon, elle ne me prend pas de haut. La première fois déjà, quand elle m’a serrée dans ses bras, j’ai eu l’impression de retrouver ma propre grand-mère...",
          DialogueId = 51003511,
          GUID = "7FAE9386",
          NextDialogue = 51003512,
          SpeakNpcId = 700016
        },
        [51003512] = {
          ContentFR = "Alors où est le problème ? Pourquoi ne pas dire simplement à tout le monde que tu as une nouvelle amie ?",
          DialogueId = 51003512,
          GUID = "7FAE93B0",
          NextDialogue = 51003513,
          SpeakNpcId = 100001
        },
        [51003513] = {
          ContentFR = "Parce que... Mamie Belinda a des cornes. Si mes parents, mes camarades ou les professeurs l’apprenaient, elle risquerait d’avoir des ennuis...",
          DialogueId = 51003513,
          GUID = "7FAE93DA",
          NextDialogue = 51003514,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_Start"
          }
        },
        [51003514] = {
          ContentFR = "On devait se voir aujourd’hui, mais l’école a ajouté cette commémoration au dernier moment. Du coup je ne peux pas y aller... Est-ce que tu pourrais lui apporter cette poupée à ma place ?",
          DialogueId = 51003514,
          GUID = "7FAE9404",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035141,
            [2] = 51000002
          },
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003515] = {
          ContentFR = "Mince, je dois y aller, la maîtresse m’attend... Tu me promets de lui donner ? Merci !",
          DialogueId = 51003515,
          GUID = "7FAE942E",
          SpeakNpcId = 700016
        },
        [51003520] = {
          ContentFR = "Et maintenant, qu’Emma vienne offrir les fleurs du souvenir...",
          DialogueId = 51003520,
          GUID = "7FAE9500",
          NextDialogue = 51003502,
          SpeakNpcId = 700086
        },
        [51003601] = {
          Camera = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci, Madame Belinda... Je me sens déjà mieux. Si c’est ce que Robb voulait, alors je vais vivre bravement... pour lui.",
          DialogueId = 51003601,
          GUID = "7FAEA24A",
          NextDialogue = 51003602,
          SpeakNpcId = 700087,
          TalkActionId = {
            [1] = "700087:Explain02_Start"
          }
        },
        [51003602] = {
          Camera = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Courage, mon enfant. Nous sommes à tes côtés. Et si besoin est, la tente de Belinda te sera toujours ouverte.",
          DialogueId = 51003602,
          GUID = "7FAEA274",
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700087:Explain02_End",
            [2] = "700081:Explain01_Start"
          }
        },
        [51003604] = {
          ContentFR = "Bonjour ! Je ne t’ai jamais vu par ici. Tu viens d’arriver à Givrelac, peut-être ? Qu’est-ce qui t’amène chez la vieille Belinda ?",
          DialogueId = 51003604,
          GUID = "7FAEA2C8",
          NextOptions = {
            [1] = 510036041
          },
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain01_Start"
          }
        },
        [51003605] = {
          ContentFR = "La poupée est rudimentaire, mais on y devine les traits de Belinda. La vieille dame s’en empare avec une joie visible, la caressant avec tendresse.",
          DialogueId = 51003605,
          GUID = "7FAEA2F2",
          NextDialogue = 51003606,
          TalkActionId = {
            [1] = "700081:Explain01_End"
          }
        },
        [51003606] = {
          ContentFR = "Je sens encore l’odeur de la place sur ce jouet... Ah ! mais oui, c’est la semaine commémorative ! Comme le temps passe vite...",
          DialogueId = 51003606,
          GUID = "7FAEA31C",
          NextDialogue = 51003607,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003607] = {
          ContentFR = "Merci, mon enfant.",
          DialogueId = 51003607,
          GUID = "7FAEA346",
          NextDialogue = 51003608,
          SpeakNpcId = 700081
        },
        [51003608] = {
          ContentFR = "Belinda te fixe longuement, sans un mot.",
          DialogueId = 51003608,
          GUID = "7FAEA370",
          NextDialogue = 51003609
        },
        [51003609] = {
          ContentFR = "Tu portes un grand fardeau. Je sens sur toi l’odeur de la mer, l’étreinte des vagues... et la chaleur d’une main aimée, qui peu à peu s’éteint.",
          DialogueId = 51003609,
          GUID = "7FAEA39A",
          NextDialogue = 51003610,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003610] = {
          ContentFR = "Depuis ton arrivée ici, confusion et chagrin t’accompagnent. Tu caches tout ça au fond de ton cœur...",
          DialogueId = 51003610,
          GUID = "7FAEA3C4",
          NextDialogue = 51003611,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003611] = {
          ContentFR = "Pardonne ma franchise, mais... as-tu perdu quelqu’un de cher ?",
          DialogueId = 51003611,
          GUID = "7FAEA3EE",
          NextOptions = {
            [1] = 510036111,
            [2] = 510036112,
            [3] = 510036113
          },
          SpeakNpcId = 700081,
          bForbidSkipOptions = true
        },
        [51003612] = {
          ContentFR = "En effet. Il est rare que les Charons atteignent mon âge.",
          DialogueId = 51003612,
          GUID = "7FAEA418",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003613] = {
          ContentFR = "Tu es triste, mon enfant.",
          DialogueId = 51003613,
          GUID = "7FAEA442",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003614] = {
          ContentFR = "Tu souffres, mon enfant. Pas besoin de le nier, je le vois.",
          DialogueId = 51003614,
          GUID = "7FAEA46C",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003615] = {
          ContentFR = "Hélas, je n’ai pas de remède à t’offrir. Mais voici des paroles anciennes, peut-être t’apporteront-elles un peu de réconfort...",
          DialogueId = 51003615,
          GUID = "7FAEA496",
          NextDialogue = 51003616,
          SpeakNpcId = 700081
        },
        [51003616] = {
          ContentFR = "« Le voyageur chausse ses bottes et s’avance tandis que le fuseau de la Déesse du Destin resserre ses fils. Quand mille chemins se rejoignent, ce qui a été perdu revient doucement à portée de main. »",
          DialogueId = 51003616,
          GUID = "7FAEA4C0",
          NextOptions = {
            [1] = 510036161
          },
          RestartTag = 51003616,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          },
          bForbidSkipOptions = true
        },
        [51003617] = {
          ContentFR = "Va, mon enfant. Tu retrouveras sur ta route tout ce qui t’a été arraché.",
          DialogueId = 51003617,
          GUID = "7FAEA4EA",
          SpeakNpcId = 700081
        },
        [51003618] = {
          ContentFR = "C’est la fin de Le Fuseau de la Déesse du Destin. Le héros y retrouve, dans le Royaume des Reflets, tout ce qu’il avait perdu... Tu veux dire que nous nous reverrons ?",
          DialogueId = 51003618,
          GUID = "7FAEA514",
          NextDialogue = 51003619,
          SpeakNpcId = 100001
        },
        [51003619] = {
          ContentFR = "Considère ces mots comme un remerciement pour la poupée. Tu es {性别:intelligent|intelligente}, je le vois bien. Tu trouveras toi-même la réponse.",
          DialogueId = 51003619,
          GUID = "7FAEA53E",
          NextDialogue = 51003620,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003620] = {
          ContentFR = "Et puis... chaque personne qui parvient jusqu’ici pour la première fois reçoit un petit présent de ma part. Il me suffira d’un simple fil de fer portant ton empreinte... Pas besoin de se presser, je t’attendrai ici.",
          DialogueId = 51003620,
          GUID = "7FAEA568",
          NextDialogue = 51003621,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003621] = {
          ContentFR = "Mon empreinte... ? Je ne suis pas {性别:sûr|sûre} de comprendre, mais ça doit vouloir dire n’importe quel objet que j’ai touché ou porté, non ?",
          DialogueId = 51003621,
          GUID = "7FAEA592",
          NextDialogue = 51003622,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003622] = {
          ContentFR = "Dans la Fosse de Glevum, il doit y avoir plein de morceaux de fils de fer. J’irai voir.",
          DialogueId = 51003622,
          Duration = 3,
          GUID = "7FAEA5BC",
          SpeakNpcId = 100001
        },
        [51003630] = {
          ContentFR = "Le jeune Charon, les yeux encore humides, repart avec hésitation. Mais dans son regard brille désormais une volonté nouvelle.",
          DialogueId = 51003630,
          Duration = 4,
          GUID = "7FAEA70C",
          NextDialogue = 51003631
        },
        [51003631] = {
          ContentFR = "Après avoir serré Belinda dans ses bras, il s’éloigne à contrecœur.",
          DialogueId = 51003631,
          Duration = 2,
          GUID = "7FAEA736"
        },
        [51003701] = {
          ContentFR = "Belinda prend le fil entre ses doigts et le tord jusqu’à en faire un délicat profil de jeune fille. Il ressemble étrangement à Berenica.",
          DialogueId = 51003701,
          GUID = "7FAEB2B2",
          NextDialogue = 51003702
        },
        [51003702] = {
          ContentFR = "Je ne vois que des ombres... Je ne sais pas si cela ressemble à celle que tu chéris. Mais j’espère que cela t’apaisera un peu.",
          DialogueId = 51003702,
          GUID = "7FAEB2DC",
          NextDialogue = 51003703,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Disagree"
          }
        },
        [51003703] = {
          ContentFR = "Je souhaite de tout cœur que vous vous retrouviez.",
          DialogueId = 51003703,
          GUID = "7FAEB306",
          NextDialogue = 51003704,
          SpeakNpcId = 700081
        },
        [51003704] = {
          ContentFR = "Tu quittes sa tente, comprenant mieux pourquoi Emma tient tant à elle. Ses pouvoirs ne sont pas immenses, mais elle guérit les cœurs et console les âmes.",
          DialogueId = 51003704,
          GUID = "7FAEB330"
        },
        [51003705] = {
          Camera = "-279.652405,-157.0,151.0,0.000004,-6.0,21.800476,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bon... ça devrait faire l’affaire !",
          DialogueId = 51003705,
          FinalCamera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAEA5BD",
          NextDialogue = 51003706,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51003706] = {
          Camera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "H-H-H-Halte-là ! Ce trésor est à moi maintenant !",
          DialogueId = 51003706,
          GUID = "7FAEA5BE",
          NextDialogue = 51003707,
          Scripts = "SEQ{PlayAnimation{ActorId{100001},AnimationId{"Think_End"},Duration{1}},TurnTo{_delay{1},TurnToDescription{"100001:p(180)"}}}",
          SpeakNpcId = 700206
        },
        [51003707] = {
          Camera = "128.007935,301.234375,103.0,0.000009,0.0,-108.798302,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’un bond, la petite Luno surgit de nulle part, arrache le fil de fer de tes mains et s’enfuit en ricanant.",
          DialogueId = 51003707,
          GUID = "7FAEA5BF",
          NextDialogue = 51003708,
          Scripts = "MoveTo{ActorId{700206},TargetPoint{"QuestPoint_DJMove"},MoveSpeed{200},Visibility{"Show"}}"
        },
        [51003708] = {
          Camera = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hahaha ! J’ai enfin réussie ! Cette fois c’est moi la gagnante !",
          DialogueId = 51003708,
          GUID = "7FAEA5C0",
          NextDialogue = 51003709,
          SpeakNpcId = 700206
        },
        [51003709] = {
          Camera = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Même si tu ignores pourquoi Belinda a besoin de ce fil, tu ne peux pas la laisser filer avec ton bien. Il faut la rattraper et lui donner une petite leçon !",
          DialogueId = 51003709,
          GUID = "7FAEA5C1",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51003710] = {
          ContentFR = "Combat : Vaincre Lulu, pilleuse de loot",
          DialogueId = 51003710,
          GUID = "7FAEA5C2"
        },
        [51003711] = {
          Camera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Aïe aïe aïe ! Tout ça pour un vieux bout de ferraille... Fallait vraiment me frapper si fort ? Bouhouhou...",
          DialogueId = 51003711,
          GUID = "7FAEA5C3",
          SpeakNpcId = 700206
        },
        [51003712] = {
          ContentFR = "Après quelques efforts, tu récupères ton bien. Lulu, elle, a déjà disparu sans laisser de trace.",
          DialogueId = 51003712,
          Duration = 5,
          GUID = "7FAEA5C4",
          NextDialogue = 51003713
        },
        [51003713] = {
          ContentFR = "Tu secoues la tête et reprends ton chemin vers la tente de Belinda.",
          DialogueId = 51003713,
          GUID = "7FAEA5C5"
        },
        [51003721] = {
          Content = "打打打打打劫皎皎已逃走，任务失败，请重新开始。",
          DialogueId = 51003721,
          Duration = 3,
          GUID = "7FAEA5C6"
        },
        [51003801] = {
          ContentFR = "Tu... Charon... un des miens...",
          DialogueId = 51003801,
          GUID = "7FAEC31A",
          NextDialogue = 51003802,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Explain02_Start"
          }
        },
        [51003802] = {
          ContentFR = "La jeune fille devant toi murmure d’une voix éteinte. Son regard semble se poser sur toi... ou peut-être se perdre dans un lointain invisible.",
          DialogueId = 51003802,
          GUID = "7FAEC344",
          NextOptions = {
            [1] = 510038021,
            [2] = 510038022
          },
          TalkActionId = {
            [1] = "700012:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003803] = {
          ContentFR = "Tu... tu voudrais m’aider... ?",
          DialogueId = 51003803,
          GUID = "7FAEC36E",
          NextDialogue = 51003805,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Agree"
          }
        },
        [51003804] = {
          ContentFR = "Non... Je ne suis pas une Sola...",
          DialogueId = 51003804,
          GUID = "7FAEC398",
          NextDialogue = 51003805,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Disagree"
          }
        },
        [51003805] = {
          ContentFR = "Regarde, mes... cornes de démon.",
          DialogueId = 51003805,
          GUID = "7FAEC3C2",
          NextDialogue = 51003806,
          SpeakNpcId = 700012
        },
        [51003806] = {
          ContentFR = "La fille soulève ses mèches en désordre pour te montrer. On distingue seulement une tresse défaites à moitié, sans la moindre trace de corne. Il est évident qu’elle est une Sola, sans l’ombre d’un doute.",
          DialogueId = 51003806,
          GUID = "7FAEC3EC",
          NextDialogue = 51003807
        },
        [51003807] = {
          ContentFR = "Ce n’est que des cheveux.",
          DialogueId = 51003807,
          GUID = "7FAEC416",
          NextDialogue = 51003808,
          SpeakNpcId = 100001
        },
        [51003808] = {
          ContentFR = "Non, ce sont mes cornes... Elles sont juste dissimulées par un sort, alors tu crois voir des cheveux ! Mais eux les ont vues... deux cornes énormes, massives !",
          DialogueId = 51003808,
          GUID = "7FAEC440",
          NextOptions = {
            [1] = 510038081,
            [2] = 510038082
          },
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51003809] = {
          ContentFR = "C’est vrai ! Je ne sais pas comment l’expliquer, mais...",
          DialogueId = 51003809,
          GUID = "7FAEC46A",
          NextDialogue = 51003811,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Agree"
          }
        },
        [51003810] = {
          ContentFR = "Je... je ne saurais pas te l’expliquer, mais...",
          DialogueId = 51003810,
          GUID = "7FAEC494",
          NextDialogue = 51003811,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Disagree"
          }
        },
        [51003811] = {
          ContentFR = "C’est ce qu’ils disent, eux.",
