          GUID = "7FAEC4E8",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700012:Explain01_End"
          }
        },
        [51003813] = {
          Camera = "273.684082,-345.582031,101.247314,0.000134,0.0,134.992844,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Faye, te voilà ! Tu t’étais réfugiée dans la cité extérieure ! On t’a cherchée partout !",
          DialogueId = 51003813,
          GUID = "7FAEC512",
          LookAt = {
