          }
        },
        [51004914] = {
          ContentFR = "« J’étais une ménestrelle itinérante. Des personnes qui haïssaient les Charons m’ont kidnappée. Ils se sont moqués de moi, m’ont frappée, rasé les cheveux, lacéré la peau. »",
          DialogueId = 51004914,
          GUID = "7FAF79B4",
          NextDialogue = 510049141,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [51004915] = {
          ContentFR = "Alors pourquoi continuez-vous d’écrire ?",
          DialogueId = 51004915,
          GUID = "7FAF79DE",
          NextDialogue = 51004916,
          SpeakNpcId = 100001
        },
        [51004916] = {
          ContentFR = "Luna baisse la tête et continue d’écrire.",
          DialogueId = 51004916,
          GUID = "7FAF7A08",
          NextDialogue = 51004917
        },
        [51004917] = {
          ContentFR = "« Garder tout cela en moi me fait trop mal. »",
          DialogueId = 51004917,
          GUID = "7FAF7A32",
          NextOptions = {
            [1] = 510049171,
            [2] = 510049172,
            [3] = 510049173
          },
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004918] = {
          ContentFR = "« Oui... ça ne change rien. Je n’ose même pas montrer ce que j’écris, mais je ne peux pas m’empêcher d’écrire quelque chose. »",
          DialogueId = 51004918,
          GUID = "7FAF7A5C",
          NextDialogue = 51004919,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004919] = {
          ContentFR = "« Je ne peux plus chanter, et si je cessais d’écrire un jour, je perdrais la dernière chose précieuse que j’ai alors... je n’aurais plus rien. »",
          DialogueId = 51004919,
          GUID = "7FAF7A86",
          NextDialogue = 51004920,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004920] = {
          ContentFR = "Si vous ne vous sentez pas bien, occupez-vous avec quelque chose de concret. Ça vous fera du bien. Et vous pouvez continuer d’écrire, mais la prochaine fois, veillez à ne pas perdre vos feuilles.",
          DialogueId = 51004920,
          GUID = "7FAF7AB0",
          NextDialogue = 51004921,
          SpeakNpcId = 100001
        },
        [51004921] = {
          ContentFR = "La femme réfléchit un long moment, puis hoche la tête.",
          DialogueId = 51004921,
          GUID = "7FAF7ADA",
          NextDialogue = 51004922,
          TalkActionId = {
            [1] = "700010:Agree"
          }
        },
        [51004922] = {
          ContentFR = "« Merci de me l’avoir rendu, âme bienveillante. Voici un petit quelque chose en guise de remerciement. »",
          DialogueId = 51004922,
          GUID = "7FAF7B04",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004923] = {
          ContentFR = "« Merci, mais je ne suis qu’une lâche qui se plaint sur des bouts de papier. Je n’ai pas le courage de montrer ça à quelqu’un. »",
          DialogueId = 51004923,
          GUID = "7FAF7B2E",
          NextDialogue = 51004924,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          }
        },
        [51004924] = {
          ContentFR = "Être capable d’exprimer vos véritables sentiments sur papier, c’est déjà plus courageux que la plupart des gens. Mais veillez à ne pas perdre vos feuilles.",
          DialogueId = 51004924,
          GUID = "7FAF7B58",
          NextDialogue = 51004925,
          SpeakNpcId = 100001
        },
        [51004925] = {
          ContentFR = "Un léger sourire se dessine sur les lèvres de la femme. Elle hoche la tête, et ses yeux sont humides.",
          DialogueId = 51004925,
          GUID = "7FAF7B82",
          NextDialogue = 51004926
        },
        [51004926] = {
          ContentFR = "« Merci de me l’avoir rendu, âme bienveillante. Voici un petit quelque chose en guise de remerciement. »",
          DialogueId = 51004926,
          GUID = "7FAF7BAC",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004927] = {
          ContentFR = "La femme pousse un gémissement rauque, cachant son visage dans ses mains. Après un long moment, elle ouvre son sac en tremblant et te donne de l’argent.",
          DialogueId = 51004927,
          GUID = "7FAF7BD6",
          NextDialogue = 51004928,
          TalkActionId = {
            [1] = "700010:Sigh_Start"
          }
        },
        [51004928] = {
          ContentFR = "« Tout ceci est pour toi. S’il te plaît, rends-moi ce papier. »",
          DialogueId = 51004928,
          GUID = "7FAF7C00",
          NextDialogue = 51004929,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004929] = {
          ContentFR = "Tu hoches la tête avec satisfaction, si ce papier tombait entre de mauvaises mains, elle perdrait bien plus que de l’argent. Tu l’as protégée et mérites ta récompense.",
          DialogueId = 51004929,
          GUID = "7FAF7C2A"
        },
        [51004930] = {
          ContentFR = "Hngh... ouuuaah...",
          DialogueId = 51004930,
          GUID = "7FAF7C54",
          NextDialogue = 51004931,
          SpeakNpcId = 700010
        },
        [51004931] = {
          ContentFR = "Comme toujours, elle marmonne des mots incompréhensibles, évitant ton regard.",
          DialogueId = 51004931,
          GUID = "7FAF7C7E"
        },
        [51004935] = {
          Camera = "-843.349854,-34.817383,370.464844,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Tu veux mourir ou quoi ? Donne-moi ça !",
          DialogueId = 51004935,
          FinalCamera = "-635.633789,-118.727051,302.828857,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          GUID = "7FAF7C7F",
          NextDialogue = 51004936,
          SpeakNpcId = 700225,
          ToFinalCameraBlendTime = 10
        },
        [51004936] = {
          ContentFR = "Laisse-moi voir ce que tu as encore écrit, qu’est-ce que tu caches, hein ?",
          DialogueId = 51004936,
          GUID = "7FAF7C80",
          NextDialogue = 51004937,
          SpeakNpcId = 700226
        },
        [51004937] = {
          ContentFR = "La dernière fois c’était ta gorge qui n’obéissait pas... cette fois quoi ? Tes yeux ? Tes mains ? Les deux peut-être ?",
          DialogueId = 51004937,
          GUID = "7FAF7C81",
          NextDialogue = 51004938,
          SpeakNpcId = 700225
        },
        [51004938] = {
          ContentFR = "A... aah !",
          DialogueId = 51004938,
          GUID = "7FAF7C82",
          NextDialogue = 51004939,
          SpeakNpcId = 700010
        },
        [51004939] = {
          ContentFR = "La femme, entourée par les malfrats, se précipite pour ramasser les papiers éparpillés, mordant sa lèvre inférieure, le visage pâle, les yeux remplis de peur. Tu ignores la relation exacte qu’elle a avec eux, mais tu sais qu’elle est en danger.",
          DialogueId = 51004939,
          GUID = "7FAF7C83"
        },
        [51004941] = {
          ContentFR = "Luna te fait une petite révérence, peut-être pour te remercier, puis se remet rapidement à ramasser les papiers.",
          DialogueId = 51004941,
          GUID = "7FAF7C84",
          NextDialogue = 51004942
        },
        [51004942] = {
          ContentFR = "Ça va ? Que sont ces papiers ?",
          DialogueId = 51004942,
          GUID = "7FAF7C85",
          NextDialogue = 51004943,
          SpeakNpcId = 100001
        },
        [51004943] = {
          ContentFR = "A... ouuuh !",
          DialogueId = 51004943,
          GUID = "7FAF7C86",
          NextDialogue = 51004944,
          SpeakNpcId = 700010
        },
        [51004944] = {
          ContentFR = "Tu remarques que certains papiers portent le mot "Ordonnance"... Peut-être que cette femme est liée à <H>un indice que Margie t’a donné</> ?",
          DialogueId = 51004944,
          GUID = "7FAF7C87",
          NextOptions = {
            [1] = 510049011,
            [2] = 510049012
          },
          bForbidSkipOptions = true
        },
        [51004945] = {
          ContentFR = "Mm... mmm.",
          DialogueId = 51004945,
          GUID = "7FAF7C88",
          NextDialogue = 51004946,
          SpeakNpcId = 700010
        },
        [51004946] = {
          ContentFR = "Elle sourit doucement, comme pour te remercier.",
          DialogueId = 51004946,
          GUID = "7FAF7C89",
          NextDialogue = 51004947,
          SpeakNpcId = 700010
        },
        [51004947] = {
          ContentFR = "Je connaissais un médecin. Il n’est plus à Givrelac, mais je peux vérifier son ancien domicile. Peut-être y trouverons-nous un remède pour votre gorge.",
          DialogueId = 51004947,
          GUID = "7FAF7C8A",
          NextDialogue = 51004948,
          SpeakNpcId = 100001
        },
        [51004948] = {
          ContentFR = "Mm...",
          DialogueId = 51004948,
          GUID = "7FAF7C8B",
          NextDialogue = 51004949,
          SpeakNpcId = 700010
        },
        [51004949] = {
          ContentFR = "Luna baisse la tête, sachant que sa voix est probablement perdue. Mais en levant les yeux, une lueur d’espoir brille, comme pour dire : « Et si... ? »",
          DialogueId = 51004949,
          GUID = "7FAF7C8C"
        },
        [51004950] = {
          ContentFR = "Hngh... ouaaah !",
          DialogueId = 51004950,
          GUID = "7FAF7C8D",
          NextDialogue = 51004951,
          SpeakNpcId = 700010
        },
        [51004951] = {
          ContentFR = "Elle te regarde avec méfiance, secouant la tête en panique, comme pour dire « Je n’ai vraiment plus rien ! »",
          DialogueId = 51004951,
          GUID = "7FAF7C8E",
          NextDialogue = 51004952,
          SpeakNpcId = 700010
        },
        [51004952] = {
          ContentFR = "Ne vous inquiétez pas. Cette fois, je suis là pour aider, pas pour vous prendre votre argent.",
          DialogueId = 51004952,
          GUID = "7FAF7C8F",
          NextDialogue = 51004953,
          SpeakNpcId = 100001
        },
        [51004953] = {
          ContentFR = "Je connaissais un médecin. Il n’est plus à Givrelac, mais je peux vérifier son ancien domicile. Peut-être y trouverons-nous un remède pour votre gorge.",
          DialogueId = 51004953,
          GUID = "7FAF7C90",
          NextDialogue = 51004954,
          SpeakNpcId = 100001
        },
        [51004954] = {
          ContentFR = "Luna semble encore hésitante, elle ne te fait pas pleinement confiance.",
          DialogueId = 51004954,
          GUID = "7FAF7C91"
        },
        [51004955] = {
          ContentFR = "Sur une étagère :",
          DialogueId = 51004955,
          GUID = "7FAF7C92"
        },
        [51004956] = {
          ContentFR = "À Givrelac, certains rhumes étranges frappent rapidement comme le vent d’hiver, disparaissant tout aussi vite, mais les enfants en souffrent toujours.\n\nSoulagement Rapide : Remède contre le rhume",
          DialogueId = 51004956,
          Duration = 4,
          GUID = "7FAF7C93",
          IsBlack = 1,
          NextDialogue = 51004957
        },
        [51004957] = {
          ContentFR = "Ce n’est pas ça.",
          DialogueId = 51004957,
          Duration = 3,
          GUID = "7FAF7C94",
          SpeakNpcId = 100001
        },
        [51004958] = {
          ContentFR = "Sur une autre étagère :",
          DialogueId = 51004958,
          GUID = "7FAF7C95"
        },
        [51004959] = {
          ContentFR = "Une étrange ordonnance, à l’origine un traitement contre la Dégradation qui a raté. Des tests ultérieurs ont révélé des effets surprenants sur certaines maladies chroniques.",
          DialogueId = 51004959,
          Duration = 4,
          GUID = "7FAF7C96",
          IsBlack = 1,
          NextDialogue = 51004960
        },
        [51004960] = {
          ContentFR = "Ce n’est pas ça.",
          DialogueId = 51004960,
          Duration = 3,
          GUID = "7FAF7C97",
          SpeakNpcId = 100001
        },
        [51004961] = {
          ContentFR = "Par terre :",
          DialogueId = 51004961,
          GUID = "7FAF7C98"
        },
        [51004962] = {
          ContentFR = "Certains, par faim, ont mangé du Lotus d’hiver par erreur. Si le poison n’est pas trop fort, ce remède peut neutraliser les toxines.\n\nAntidote au Lotus d’hiver",
          DialogueId = 51004962,
          Duration = 5,
          GUID = "7FAF7C99",
          IsBlack = 1
        },
        [51004963] = {
          ContentFR = "Comment est-ce tombé par terre ? Cela pourrait aider Luna !",
          DialogueId = 51004963,
          Duration = 4,
          GUID = "7FAF7C9A",
          SpeakNpcId = 100001
        },
        [51004964] = {
          ContentFR = "Tu as obtenu une recette d’un remède qui pourrait aider avec la gorge de Luna.",
          DialogueId = 51004964,
          Duration = 3,
          GUID = "7FAF7C9B"
        },
        [51004965] = {
          ContentFR = "Si un jour votre voix revient... que chanterez-vous ?",
          DialogueId = 51004965,
          GUID = "7FAF7C9C",
          NextDialogue = 51004966,
          SpeakNpcId = 100001
        },
        [51004966] = {
          ContentFR = "Luna baisse la tête, plongée dans une longue réflexion.",
          DialogueId = 51004966,
          GUID = "7FAF7C9D",
          NextDialogue = 51004967,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004967] = {
          ContentFR = "« Je chanterais ce que j’ai dans le cœur, même si cela me coûte de nouveau ma voix. »",
          DialogueId = 51004967,
          GUID = "7FAF7C9E",
          NextDialogue = 51004968,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004968] = {
          ContentFR = "Tu réalises que si ce remède fonctionne, il pourrait ramener la voix de la ménestrelle... et avec elle, le danger qui l’a privée de sa voix.",
          DialogueId = 51004968,
          GUID = "7FAF7C9F",
          NextOptions = {
            [1] = 51004969,
            [2] = 51004970
          }
        },
        [51004969] = {
          ContentFR = "Donner le remède",
          DialogueId = 51004969,
          GUID = "7FAF7CA0",
          NextDialogue = 51004972
        },
        [51004970] = {
          ContentFR = "Garder le remède",
          DialogueId = 51004970,
          GUID = "7FAF7CA1",
          NextDialogue = 51004979
        },
        [51004971] = {
          ContentFR = "Branche 1",
          DialogueId = 51004971,
          GUID = "7FAF7CA2"
        },
        [51004972] = {
          ContentFR = "Ce remède vient d’un médecin que je connaissais. Il servait à traiter le poison du Lotus d’hiver. Essayez, ça pourrait sauver votre voix.",
          DialogueId = 51004972,
          GUID = "7FAF7CA3",
          NextDialogue = 51004973,
          SpeakNpcId = 100001
        },
        [51004973] = {
          ContentFR = "Ses mains tremblent légèrement en prenant la feuille froissée. Les yeux humides, elle s’incline plusieurs fois pour te remercier.",
          DialogueId = 51004973,
          GUID = "7FAF7CA4",
          NextDialogue = 51004974
        },
        [51004974] = {
          ContentFR = "Remède retiré de l’inventaire.",
          DialogueId = 51004974,
          GUID = "7FAF7CA5",
          NextDialogue = 51004975
        },
        [51004975] = {
          ContentFR = "Tu ignores si lui donner le remède était vraiment la bonne chose. Son efficacité est incertaine.",
          DialogueId = 51004975,
          GUID = "7FAF7CA6",
          NextDialogue = 51004976
        },
        [51004976] = {
          ContentFR = "Au final, c’est son choix. Tu te rassures ainsi.",
          DialogueId = 51004976,
          GUID = "7FAF7CA7"
        },
        [51004977] = {
          ContentFR = "Quête terminée. Remède retiré, récompense : bio de Luna débloquée.",
          DialogueId = 51004977,
          GUID = "7FAF7CA8"
        },
        [51004978] = {
          ContentFR = "Branche 2",
          DialogueId = 51004978,
          GUID = "7FAF7CA9"
        },
        [51004979] = {
          ContentFR = "Mon ancien médecin n’est plus à Givrelac. J’ai vérifié son ancien domicile, mais il a été vidé.",
          DialogueId = 51004979,
          GUID = "7FAF7CAA",
          NextDialogue = 51004980,
          SpeakNpcId = 100001
        },
        [51004980] = {
          ContentFR = "{性别:Désolé|Désolée}, je n’ai pas pu être plus utile.",
          DialogueId = 51004980,
          GUID = "7FAF7CAB",
          NextDialogue = 51004981,
          SpeakNpcId = 100001
        },
        [51004981] = {
          ContentFR = "Luna te sourit et tapote doucement ton épaule : « Ce n’est pas grave, merci d’avoir essayé. »",
          DialogueId = 51004981,
          GUID = "7FAF7CAC",
          NextDialogue = 51004982
        },
        [51004982] = {
          ContentFR = "Elle ignore le tumulte qui t’habite. Elle ne saura jamais que tu as retenu une part de vérité, non par cruauté, mais pour l’épargner d’un péril qu’elle n’aura peut-être jamais à affronter.",
          DialogueId = 51004982,
          GUID = "7FAF7CAD",
          NextDialogue = 51004983
        },
        [51004983] = {
          ContentFR = "Tu sais qu’elle continuera d’écrire, quoi qu’il en soit. Mais tu t’es convaincu d’avoir au moins réduit les risques, autant que possible. Du moins... c’est ce que tu t’efforces de croire.",
          DialogueId = 51004983,
          GUID = "7FAF7CAE"
        },
        [51005001] = {
          ContentFR = "Qui êtes-vous... ?",
          DialogueId = 51005001,
          GUID = "7FAF87FA",
          NextDialogue = 51005002,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700013:Explain01_Start"
          }
        },
        [51005002] = {
          ContentFR = "Devant toi, une femme d’âge mûr dépoussière les meubles avec une aisance méthodique. Elle semble étrangement familière avec la Maison d’Hypnos... un lieu pourtant déserté depuis longtemps.",
          DialogueId = 51005002,
          GUID = "7FAF8824",
          NextDialogue = 51005003,
          TalkActionId = {
            [1] = "700013:Explain01_End"
          }
        },
        [51005003] = {
          ContentFR = "Pardonnez mon intrusion. Je ne pensais pas croiser quelqu’un ici.",
          DialogueId = 51005003,
          GUID = "7FAF884E",
          NextDialogue = 51005004,
          SpeakNpcId = 700013
        },
        [51005004] = {
          ContentFR = "Je suis une employée de maison, engagée par Monsieur Henrik pour l’entretien et les réparations de la demeure. Aujourd’hui est un jour de service prévu par contrat.",
          DialogueId = 51005004,
          GUID = "7FAF8878",
          NextDialogue = 51005005,
          SpeakNpcId = 700013
        },
        [51005005] = {
          ContentFR = "Puis-je savoir qui vous êtes ?",
          DialogueId = 51005005,
          GUID = "7FAF88A2",
          NextDialogue = 51005006,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain02_Start"
          }
        },
        [51005006] = {
          ContentFR = "Je loue le vieux manoir à côté. Je voulais simplement vérifier que les portes et les fenêtres de cette maison étaient bien verrouillées.",
          DialogueId = 51005006,
          GUID = "7FAF88CC",
          NextDialogue = 51005007,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700013:Explain02_End"
          }
        },
        [51005007] = {
          ContentFR = "Mais... ne le saviez-vous pas ? Monsieur Henrik est décédé. Vous n’êtes plus tenue d’honorer ce contrat.",
          DialogueId = 51005007,
          GUID = "7FAF88F6",
          NextDialogue = 51005008,
          SpeakNpcId = 100001
        },
        [51005008] = {
          ContentFR = "Je le sais.",
          DialogueId = 51005008,
          GUID = "7FAF8920",
          NextDialogue = 51005009,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Agree"
          }
        },
        [51005009] = {
          ContentFR = "Mais Monsieur Henrik avait déjà réglé mes honoraires à l’avance. Tant que le contrat n’a pas pris fin, je ne ferai rien qui aille à l’encontre de mon devoir professionnel.",
          DialogueId = 51005009,
          GUID = "7FAF894A",
          NextDialogue = 51005010,
          SpeakNpcId = 700013
        },
        [51005010] = {
          ContentFR = "Il est quatre heures de l’après-midi. Je resterai trois heures, comme convenu.",
          DialogueId = 51005010,
          GUID = "7FAF8974",
          NextDialogue = 51005011,
          SpeakNpcId = 700013
        },
        [51005011] = {
          ContentFR = "Si vous avez besoin de quoi que ce soit, n’hésitez pas à me le demander.",
          DialogueId = 51005011,
          GUID = "7FAF899E",
          NextDialogue = 51005012,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain02_Start"
          }
        },
        [51005012] = {
          ContentFR = "En nettoyant, Lina découvre les profondes griffures laissées par Psyche lors de sa Dégradation... puis les traces de sang séché de Henrik.",
          DialogueId = 51005012,
          GUID = "7FAF89C8",
          NextOptions = {
            [1] = 510050121
          },
          RestartTag = 51005012,
          TalkActionId = {
            [1] = "700013:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005013] = {
          ContentFR = "Je ne juge pas la vie de mes employeurs. Je ne pense qu’à réparer, à rendre les lieux plus beaux.",
          DialogueId = 51005013,
          GUID = "7FAF89F2",
          NextDialogue = 51005014,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005014] = {
          ContentFR = "Sans un tremblement, elle frotte le sol tâché de sang. Chacun de ses gestes reste précis, efficace, imperturbable.",
          DialogueId = 51005014,
          GUID = "7FAF8A1C"
        },
        [51005015] = {
          ContentFR = "J’ai vu bien pire... Dans une demeure plus luxueuse encore. Son maître avait incendié son propre manoir, brûlant avec lui toute sa famille.",
          DialogueId = 51005015,
          GUID = "7FAF8A46",
          NextDialogue = 51005016,
          SpeakNpcId = 700013
        },
        [51005016] = {
          ContentFR = "Comparé à cela, ici... cela reste une maison. Au moins, Monsieur Henrik a su en préserver l’âme.",
          DialogueId = 51005016,
          GUID = "7FAF8A70",
          NextDialogue = 51005017,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Think_Start"
          }
        },
        [51005017] = {
          ContentFR = "Un léger trouble traverse enfin son visage d’ordinaire impassible. Derrière cette façade de rigueur se cache peut-être un cœur moins calme qu’il n’y paraît.",
          DialogueId = 51005017,
          GUID = "7FAF8A9A",
          NextOptions = {
            [1] = 510050171
          },
          TalkActionId = {
            [1] = "700013:Think_End"
          },
          bForbidSkipOptions = true
        },
        [51005018] = {
          ContentFR = "Il y a vingt ans, il était un médecin renommé. Moi, je n’étais qu’une servante dans la maison d’un vicomte. Le vicomte avait appelé Monsieur Henrik pour examiner sa femme. C’est ainsi que je l’ai rencontré... et je pensais ne jamais le revoir.",
          DialogueId = 51005018,
          GUID = "7FAF8AC4",
          NextDialogue = 51005019,
          SpeakNpcId = 700013
        },
        [51005019] = {
          ContentFR = "Mais sur le chemin du retour, un enfant Charon s’est effondré devant nous. Henrik l’a immédiatement soigné et m’a confié sa garde.",
          DialogueId = 51005019,
          GUID = "7FAF8AEE",
          NextDialogue = 51005020,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain01_Start"
          }
        },
        [51005020] = {
          ContentFR = "Il n’était pas seulement un grand médecin par son talent, mais parce qu’il ne faisait jamais de différence entre ses patients.",
          DialogueId = 51005020,
          GUID = "7FAF8B18",
          NextOptions = {
            [1] = 510050201,
            [2] = 510050202,
            [3] = 510050203
          },
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51005021] = {
          ContentFR = "Monsieur Henrik n’y attachait aucune importance. Mon estime pour lui n’a jamais changé.",
          DialogueId = 51005021,
          GUID = "7FAF8B42",
          NextOptions = {
            [1] = 510050231
          },
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51005022] = {
          ContentFR = "C’était sa plus grande noblesse.",
          DialogueId = 51005022,
          GUID = "7FAF8B6C",
          NextOptions = {
            [1] = 510050231
          },
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Agree"
          },
          bForbidSkipOptions = true
        },
        [51005023] = {
          ContentFR = "Je suis profondément peinée par ce qui lui est arrivé.",
          DialogueId = 51005023,
          GUID = "7FAF8B96",
          NextOptions = {
            [1] = 510050231
          },
          SpeakNpcId = 700013,
          bForbidSkipOptions = true
        },
        [51005024] = {
          ContentFR = "J’ai pourtant l’impression de n’avoir pas assez fait.",
          DialogueId = 51005024,
          GUID = "7FAF8BC0",
          NextDialogue = 51005025,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005025] = {
          ContentFR = "Monsieur Henrik voulait probablement maintenir une certaine distance. Je ne venais que rarement, autrement, nous nous serions déjà croisés.",
          DialogueId = 51005025,
          GUID = "7FAF8BEA",
          NextDialogue = 51005026,
          SpeakNpcId = 700013
        },
        [51005026] = {
          ContentFR = "Et je crois qu’il ne voudrait pas que je vienne trop souvent aujourd’hui non plus. Il est temps de rendre la clé à son véritable propriétaire. Je vais la déposer sur son bureau, sous votre regard.",
          DialogueId = 51005026,
          GUID = "7FAF8C14",
          NextOptions = {
            [1] = 510050261
          },
          RestartTag = 51005026,
          SpeakNpcId = 700013,
          bForbidSkipOptions = true
        },
        [51005027] = {
          ContentFR = "Rien ne te revient. Sans doute ton imagination.",
          DialogueId = 51005027,
          GUID = "7FAF8C3E"
        },
        [51005028] = {
          ContentFR = "La clé ressemble étrangement à celle que tu avais reçue de Margie.",
          DialogueId = 51005028,
          GUID = "7FAF8C68",
          NextDialogue = 51005029
        },
        [51005029] = {
          ContentFR = "Tu te rappelles l’avoir déjà vue sur Henrik, elle a dû se perdre dans le chaos de cette nuit-là, avant que Margie ne la ramasse par hasard.",
          DialogueId = 51005029,
          GUID = "7FAF8C92",
          NextOptions = {
            [1] = 510050291
          }
        },
        [51005030] = {
          ContentFR = "C’est celle qui ouvre le coffre où Monsieur Henrik gardait ses documents les plus précieux.",
          DialogueId = 51005030,
          GUID = "7FAF8CBC",
          NextDialogue = 51005031,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Think_Start"
          }
        },
        [51005031] = {
          ContentFR = "Il m’avait confié qu’en cas de malheur, ce coffre devait être ouvert, et son testament lu.",
          DialogueId = 51005031,
          GUID = "7FAF8CE6",
          NextDialogue = 51005032,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Think_End"
          }
        },
        [51005032] = {
          ContentFR = "Je n’avais jamais retrouvé cette clé... La savoir entre vos mains me rassure.",
          DialogueId = 51005032,
          GUID = "7FAF8D10",
          NextDialogue = 51005033,
          SpeakNpcId = 700013
        },
        [51005033] = {
          ContentFR = "Je vous prie donc d’être témoin, pendant que j’accomplis sa dernière volonté.",
          DialogueId = 51005033,
          GUID = "7FAF8D3A",
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain02_Start"
          }
        },
        [51005034] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le coffre s’ouvre. Lina prend le testament et, devant toi, le lit avec une gravité solennelle.",
          DialogueId = 51005034,
          GUID = "7FAF8D64",
          NextDialogue = 51005035
        },
        [51005035] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Henrik avait prévu sa fin. Son écriture reste calme, sauf lorsqu’il évoque la douleur d’avoir perdu sa fille. Puis viennent ses dernières volontés :",
          DialogueId = 51005035,
          GUID = "7FAF8D8E",
          NextDialogue = 51005036
        },
        [51005036] = {
          Camera = "-3490.197266,-340.706116,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Après ma mort, toutes mes propriétés reviendront à Madame Lina Bell. »",
          DialogueId = 51005036,
          FinalCamera = "-2771.669922,-330.52002,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DB8",
          NextDialogue = 51005037,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005037] = {
          Camera = "-956.953125,124.710449,851.333984,0.000029,-16.600037,26.61047,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« En remerciement de ses années de dévouement envers la Maison d’Hypnos et mes patients Charons. »",
          DialogueId = 51005037,
          FinalCamera = "-938.859375,88.569275,851.333984,0.000038,-16.600002,26.610426,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DE2",
          NextDialogue = 51005038,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005038] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Je lui exprime ma gratitude la plus sincère. Elle est une femme digne de respect. »",
          DialogueId = 51005038,
          GUID = "7FAF8E0C",
          NextDialogue = 51005039,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005039] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51005039,
          GUID = "7FAF8E36",
          NextDialogue = 510050391,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51005040] = {
          ContentFR = "Tu quittes seul le bureau. Submergée par les sanglots, Lina a besoin de solitude. Il serait cruel d’interrompre son deuil.",
          DialogueId = 51005040,
          Duration = 4,
          GUID = "7FAF8E60",
          NextDialogue = 51005041
        },
        [51005041] = {
          ContentFR = "Désormais, tu as une nouvelle propriétaire des lieux.",
          DialogueId = 51005041,
          Duration = 2,
          GUID = "7FAF8E8A"
        },
        [51005042] = {
          Camera = "460.455078,-127.329834,335.509766,0.000047,-28.799341,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Grâce à la connaissance approfondie de Lina de la Maison Hypnos, vous trouvez vite le coffre. Mais à côté, un petit coffret en bois attire ton regard.",
          DialogueId = 51005042,
          FinalCamera = "460.455078,-148.0,335.509766,0.000054,-28.799347,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EB4",
          NextDialogue = 51005043,
          ToFinalCameraBlendTime = 7
        },
        [51005043] = {
          Camera = "-372.582031,8.945923,112.0,0.0,0.0,0.208069,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu ouvres le coffret. À l’intérieur, une lettre au tracé élégant. Tu la prends et la lis à voix haute.",
          DialogueId = 51005043,
          FinalCamera = "-350.582031,9.078125,112.0,0.0,0.0,0.408069,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EDE",
          NextDialogue = 51005044,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "700098:n(100001)"
          }
        },
        [51005044] = {
          ContentFR = "Quand vous lirez cette lettre, nous aurons déjà quitté la Maison d’Hypnos.\nLa tragédie de Psyche a alerté les Veilleurs. Nous ne pouvions plus rester à Givrelac.\nAvant qu’ils n’arrivent, j’ai conduit tout le monde loin d’ici.\nNe soyez pas triste pour nous, et ne craignez pas que nous perdions le contrôle en sombrant dans la Dégradation.\n\nNous partons vers les terres sauvages, vers l’inconnu.\nPeut-être la mort nous attend-elle, ou bien un miracle encore invisible.\nMais jusqu’au bout, nous garderons espoir.\nC’est ce qu’elle nous a appris.\n\nEt... merci. Merci pour tout ce que vous avez fait.\n\nElisa Taylor",
          DialogueId = 51005044,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_200208;content:Reading_Content_200208}",
          GUID = "7FAF8F08",
          NextDialogue = 51005045
        },
        [51005045] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors... les enfants s’en sont sortis sains et saufs.",
          DialogueId = 51005045,
          GUID = "7FAF8F32",
          NextDialogue = 51005046,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "700098:p(140)"
          }
        },
        [51005046] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Lina reste silencieuse pendant un long moment, puis tente de glisser la clé dans la serrure. Mais ses mains tremblent tant qu’elle la laisse tomber plusieurs fois.",
          DialogueId = 51005046,
          GUID = "7FAF8F5C",
          NextDialogue = 51005047
        },
        [51005047] = {
          ContentFR = "... Faisons-le ensemble.",
          DialogueId = 51005047,
          GUID = "7FAF8F86",
          IsBlack = 1,
          NextDialogue = 51005048,
          SpeakNpcId = 100001
        },
        [51005048] = {
          ContentFR = "Pardonnez-moi... Merci.",
          DialogueId = 51005048,
          GUID = "7FAF8FB0",
          IsBlack = 1,
          SpeakNpcId = 700013
        },
        [51005101] = {
          ContentFR = "Ah, c’est toi, {nickname} !",
          DialogueId = 51005101,
          GUID = "7FAF9862",
          NextDialogue = 51005102,
          SpeakNpcId = 700115
        },
        [51005102] = {
          ContentFR = "Merci encore pour la dernière fois ! Les familles des taudis ont pu se nourrir grâce à l’argent que tu as aidé à leur donner, et elles m’ont chargé de te remercier.",
          DialogueId = 51005102,
          GUID = "7FAF988C",
          NextOptions = {
            [1] = 51005103
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005103] = {
          ContentFR = "Pas de quoi.",
          DialogueId = 51005103,
          GUID = "7FAF98B6",
          NextDialogue = 51005104
        },
        [51005104] = {
          ContentFR = "Ne sois pas si modeste ! Ça fait longtemps que je n’avais pas rencontré quelqu’un d’aussi serviable, capable et poli !",
          DialogueId = 51005104,
          GUID = "7FAF98E0",
          NextDialogue = 51005105,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005105] = {
          ContentFR = "Alors, comment tu trouves la vie à Givrelac jusqu’à présent ?",
          DialogueId = 51005105,
          GUID = "7FAF990A",
          NextOptions = {
            [1] = 510051051,
            [2] = 510051052,
            [3] = 510051053
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          },
          bForbidSkipOptions = true
        },
        [51005106] = {
          ContentFR = "Même si je suis d’accord que la vie est un chemin vers une destination, ce serait dommage d’ignorer le paysage sur le trajet !",
          DialogueId = 51005106,
          GUID = "7FAF9934",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005107] = {
          ContentFR = "Je comprends ABSOLUMENT ! Quand je suis arrivée à Givrelac, j’ai ressenti exactement la même chose ! Les règles sont bizarres et les gens le sont tout autant !",
          DialogueId = 51005107,
          GUID = "7FAF995E",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005108] = {
          ContentFR = "Hmm, alors ton village natal n’était pas très sûr... Tu n’es pas toi aussi {性别:un réfugié|une réfugiée}, j’espère ?",
          DialogueId = 51005108,
          GUID = "7FAF9988",
          NextDialogue = 51005109,
          SpeakNpcId = 700115
        },
        [51005109] = {
          ContentFR = "Bon, laissons ça de côté.",
          DialogueId = 51005109,
          GUID = "7FAF99B2",
          NextDialogue = 51005110,
          SpeakNpcId = 700115
        },
        [51005110] = {
          ContentFR = "Viens plutôt voir mes dernières trouvailles ! Des petites choses bizarres, mais si quelque chose te plaît, je te fais 20 % de réduction, pour te remercier de m’avoir aidée avec ce voleur.",
          DialogueId = 51005110,
          GUID = "7FAF99DC",
          NextDialogue = 51005111,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_Start"
          }
        },
        [51005111] = {
          ContentFR = "Tu te penches pour observer de plus près les "trouvailles" de Margie. Sur les petites étagères s’entassent divers objets, la plupart utilisés, mais soigneusement nettoyés.",
          DialogueId = 51005111,
          GUID = "7FAF9A06",
          NextOptions = {
            [1] = 510051111,
            [2] = 510051112,
            [3] = 510051113
          },
          TalkActionId = {
            [1] = "700115:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005112] = {
          ContentFR = "L’important, c’est le plaisir ! La valeur ne se mesure pas qu’en argent !",
          DialogueId = 51005112,
          GUID = "7FAF9A30",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005113] = {
          ContentFR = "Bien sûr que non ! Je suis honnête ! Ces objets ont été jetés par leurs propriétaires, les laisser à l’abandon serait un véritable crime, je veux juste leur donner une nouvelle maison !",
          DialogueId = 51005113,
          GUID = "7FAF9A5A",
          NextDialogue = 51005115,
          SpeakNpcId = 700115
        },
        [51005114] = {
          ContentFR = "Héhé, secret commercial !",
          DialogueId = 51005114,
          GUID = "7FAF9A84",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005115] = {
          ContentFR = "Il est difficile de refuser son offre généreuse et tu commences donc à fouiller les étagères pour trouver quelque chose d’utile.",
          DialogueId = 51005115,
          GUID = "7FAF9AAE",
          NextOptions = {
            [1] = 510051151,
            [2] = 510051152,
            [3] = 510051153
          },
          RestartTag = 51005115,
          bForbidSkipOptions = true
        },
        [51005116] = {
          ContentFR = "Si rien ne te plaît, tant pis ! Reviens la prochaine fois !",
          DialogueId = 51005116,
          GUID = "7FAF9AD8",
          SpeakNpcId = 700115
        },
        [51005117] = {
          ContentFR = "Pas mal ! Tu as un œil pour repérer la valeur et les trésors, on dirait que tu as le flair {性别:d’un vrai|d’une vraie} détective !",
          DialogueId = 51005117,
          GUID = "7FAF9B02",
          NextOptions = {
            [1] = 51005118
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005118] = {
          ContentFR = "Détective, vraiment ?",
          DialogueId = 51005118,
          GUID = "7FAF9B2C",
          NextDialogue = 51005119
        },
        [51005119] = {
          ContentFR = "Les objets que tu as choisis sont en apparence les moins précieux... littéralement, ils ne se vendraient pas pour quelques pièces. La plupart des gens ne leur prêteraient même pas attention. Mais paradoxalement, ce sont aussi les plus intéressants ici !",
          DialogueId = 51005119,
          GUID = "7FAF9B56",
          NextDialogue = 51005120,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_Start"
          }
        },
        [51005120] = {
          ContentFR = "Leur valeur réside dans... leurs histoires et secrets ! C’est justement pour ça que tu les as pris, non ? Je savais que tu avais l’œil !",
          DialogueId = 51005120,
          GUID = "7FAF9B80",
          NextDialogue = 51005121,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_End"
          }
        },
        [51005121] = {
          ContentFR = "Avec assez de patience et d’observation, tu peux découvrir les secrets derrière chaque objet !",
          DialogueId = 51005121,
          GUID = "7FAF9BAA",
          NextDialogue = 51005122,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005122] = {
          ContentFR = "Ne sous-estime jamais les poubelles. C’est là que se cachent la vérité et les mystères de la cité ! Moi, j’ai appris à la connaître petit à petit, en fouillant dans ses poubelles. ",
          DialogueId = 51005122,
          GUID = "7FAF9BD4",
          NextDialogue = 51005123,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          }
        },
        [51005123] = {
          ContentFR = "{性别:Curieux|Curieuse}, hein ? Tu veux en savoir plus sur cette cité ? Alors paie, et tu pourras repartir avec ces petites merveilles pour fouiller un peu !",
          DialogueId = 51005123,
          GUID = "7FAF9BFE",
          NextDialogue = 51005124,
