        [51005904] = {
          ContentFR = "Le Frère Aîné refuse de lâcher le coffre malgré tes coups, le Petit Frère s’accroche à ta jambe. Il est évident que c’est une tentative d’extorsion.",
          DialogueId = 51005904,
