          SpeakNpcId = 700069
        },
        [51007404] = {
          Content = "帮我拿下扳手——",
          DialogueId = 51007404,
          GUID = "7FB11238",
          SpeakNpcId = 700193
        },
        [51007405] = {
          Content = "总之，他的抢救不但没能请来奇迹，来的还是巨额赔偿金，医院为了名誉只好辞退了一个员工。",
          DialogueId = 51007405,
          GUID = "7FB11262",
          NextDialogue = 51007406,
          SpeakNpcId = 700194
        },
        [51007406] = {
          Content = "谁能想到呢，他竟然除了治病救人什么都不会，所以欢迎他的只有下水管道。",
          DialogueId = 51007406,
          GUID = "7FB1128C",
          NextDialogue = 51007407,
          SpeakNpcId = 700194
        },
        [51007407] = {
          Content = "好在当年怎么都没治好的洁癖，来这儿几个月就治好了。",
          DialogueId = 51007407,
          GUID = "7FB112B6",
          NextDialogue = 51007408,
          SpeakNpcId = 700194
        },
        [51007408] = {
          Content = "再者说，干这活儿也不至于被饿死在街上，不过就是得还债还到进棺材喽。",
          DialogueId = 51007408,
          GUID = "7FB112E0",
          NextDialogue = 51007409,
          SpeakNpcId = 700194
        },
        [51007409] = {
          Content = "如果再给你的人生重来一次的机会，你还会救他吗？",
          DialogueId = 51007409,
          GUID = "7FB1130A",
          NextDialogue = 51007410,
          SpeakNpcId = 700194
        },
        [51007410] = {
          Content = "（达顿转过身用扳手拧紧新换的螺丝，他甩着胳膊干得卖力又熟练，好像没听见你的问题。）",
          DialogueId = 51007410,
          GUID = "7FB11334",
          NextDialogue = 51007411
        },
        [51007411] = {
          Content = "（只是在如轰鸣般的沉默中，你和他都已经对答案心知肚明了。）",
          DialogueId = 51007411,
          GUID = "7FB1135E"
        },
        [51007415] = {
          Content = "哎呦……！里边这儿的老鼠也太多了！",
          DialogueId = 51007415,
          GUID = "7FB11406",
          SpeakNpcId = 700192
        },
        [51007501] = {
          ContentFR = "Hmm... j’ai décidé, toi, tu seras le sujet d’expérience n° 1 !",
          DialogueId = 51007501,
          GUID = "7FB12222",
          NextDialogue = 51007502,
          SpeakNpcId = 700011
        },
        [51007502] = {
          ContentFR = "Le garçon te regarde avec de grands yeux brillants d’excitation.",
          DialogueId = 51007502,
          GUID = "7FB1224C",
          NextOptions = {
            [1] = 51007503,
            [2] = 51007506,
            [3] = 51007509
          }
        },
        [51007503] = {
          ContentFR = "– Il porte un uniforme soigné, on dirait un élève.",
          DialogueId = 51007503,
          GUID = "7FB12276",
          ImprPlusId = 1003,
          NextDialogue = 51007504
        },
        [51007504] = {
          ContentFR = "C’est quel genre d’expérience ? C’est pour tes devoirs ?",
          DialogueId = 51007504,
          GUID = "7FB122A0",
          NextDialogue = 51007505,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007505] = {
          ContentFR = "Non ! C’est pour mon plaisir personnel ! Mon propre projet !",
          DialogueId = 51007505,
          GUID = "7FB122CA",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007506] = {
          ContentFR = "– Ce n’est pas très sûr pour un enfant d’être dehors tout seul.",
          DialogueId = 51007506,
          GUID = "7FB122F4",
          ImprPlusId = 1004,
          NextDialogue = 51007507
        },
        [51007507] = {
          ContentFR = "Petit, ce n’est pas très sûr de rester ici tout seul. Je te raccompagne ?",
          DialogueId = 51007507,
          GUID = "7FB1231E",
          NextDialogue = 51007508,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007508] = {
          ContentFR = "Oh ! Merci ! Tu es vraiment {性别:gentil|gentille} ! Mais je dois finir mon expérience avant de rentrer.",
          DialogueId = 51007508,
          GUID = "7FB12348",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007509] = {
          ContentFR = "Demander si il y a une récompense à la clé",
          DialogueId = 51007509,
          GUID = "7FB12372",
          ImprPlusId = 1001,
          NextDialogue = 51007510
        },
        [51007510] = {
          ContentFR = "Hein ? Ah... oui, bien sûr ! Tu peux prendre tout mon argent de poche !",
          DialogueId = 51007510,
          GUID = "7FB1239C",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007512] = {
          ContentFR = "Voilà le plan : je mène une étude scientifique sur les Charons ! Et devine quoi ? Tu es mon tout premier sujet d’expérience !",
          DialogueId = 51007512,
          GUID = "7FB123F0",
          NextDialogue = 51007513,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007513] = {
          ContentFR = "Pourquoi moi ?",
          DialogueId = 51007513,
          GUID = "7FB1241A",
          NextDialogue = 51007514,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Think_Start"
          }
        },
        [51007514] = {
          ContentFR = "Euh... c’est un tirage au sort ! Ça évite tout biais subjectif !",
          DialogueId = 51007514,
          GUID = "7FB12444",
          NextDialogue = 51007515,
          SpeakNpcId = 700011
        },
        [51007515] = {
          ContentFR = "Hum... d’abord, commençons par ton nom.",
          DialogueId = 51007515,
          GUID = "7FB1246E",
          NextOptions = {
            [1] = 51007516,
            [2] = 51007519
          },
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_End"
          }
        },
        [51007516] = {
          ContentFR = "Je suis {nickname}, Flamme de la Renaissance, {性别:Glorieux Gardien de Givrelac|Glorieuse Gardienne de Givrelac}, originaire de l’Île du Purgatoire !",
          DialogueId = 51007516,
          GUID = "7FB12498",
          ImprPlusId = 1005,
          NextDialogue = 51007517,
          Scripts = "SetTag{Tag{"XiAoTag"}, Value{"Value_1"}}"
        },
        [51007517] = {
          ContentFR = "Ouah... parle lentement... Flamme de... euh... Givrelac... Purg... quoi ?",
          DialogueId = 51007517,
          GUID = "7FB124C2",
          NextDialogue = 51007518,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          }
        },
        [51007518] = {
          ContentFR = "Trop compliqué ! Je vais t’appeler {$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle} !",
          DialogueId = 51007518,
          GUID = "7FB124EC",
          NextDialogue = 51007522,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007519] = {
          ContentFR = "Je m’appelle Sibylle.",
          DialogueId = 51007519,
          GUID = "7FB12516",
          ImprPlusId = 1003,
          NextDialogue = 51007520,
          Scripts = "SetTag{Tag{"XiAoTag"}, Value{"Value_2"}}"
        },
        [51007520] = {
          ContentFR = "Ce nom me rappelle quelque chose... je crois l’avoir entendu quelque part...",
          DialogueId = 51007520,
          GUID = "7FB12540",
          NextDialogue = 51007521,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Think_Start"
          }
        },
        [51007521] = {
          ContentFR = "Bon, peu importe ! {$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle}, on commence !",
          DialogueId = 51007521,
          GUID = "7FB1256A",
          NextDialogue = 51007522,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007522] = {
          ContentFR = "Pas de souci, le test est simple, il suffit juste de remplir ce questionnaire !",
          DialogueId = 51007522,
          GUID = "7FB12594",
          NextDialogue = 51007523,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007523] = {
          ContentFR = "Le garçon te tend une pile de papiers, tenant les feuilles à deux mains.",
          DialogueId = 51007523,
          GUID = "7FB125BE",
          NextDialogue = 51007524
        },
        [51007524] = {
          ContentFR = "Les bords sont irréguliers, comme arrachés d’un cahier, les pages sont couvertes d’une écriture enfantine mais soignée, numérotées jusqu’à trois chiffres.",
          DialogueId = 51007524,
          GUID = "7FB125E8",
          NextOptions = {
            [1] = 51007525,
            [2] = 51007527,
            [3] = 51007529
          }
        },
        [51007525] = {
          ContentFR = "Ton questionnaire est un peu long...",
          DialogueId = 51007525,
          GUID = "7FB12612",
          NextDialogue = 51007526
        },
        [51007526] = {
          ContentFR = "Ah bon ? Il n’y a que 777 questions !",
          DialogueId = 51007526,
          GUID = "7FB1263C",
          NextDialogue = 51007531,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007527] = {
          ContentFR = "Pour un questionnaire aussi long, il faudra sûrement me payer encore plus.",
          DialogueId = 51007527,
          GUID = "7FB12666",
          NextDialogue = 51007528
        },
        [51007528] = {
          ContentFR = "Mais... je n’ai plus d’argent... je peux te payer en plusieurs fois ?",
          DialogueId = 51007528,
          GUID = "7FB12690",
          NextDialogue = 51007531,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007529] = {
          ContentFR = "D’accord, je répondrai aussi en plusieurs fois... disons sur dix ans.",
          DialogueId = 51007529,
          GUID = "7FB126BA",
          NextDialogue = 51007530
        },
        [51007530] = {
          ContentFR = "Hein ? Dix ans !?",
          DialogueId = 51007530,
          GUID = "7FB126E4",
          NextDialogue = 51007531,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007531] = {
          ContentFR = "S’il te plaît, accepte ! Parmi tous les Charons de Givrelac, c’est toi qui as été {性别:choisi|choisie} ! Tu es {性别:l’élu|l’élue} !",
          DialogueId = 51007531,
          GUID = "7FB1270E",
          NextDialogue = 51007532,
          SpeakNpcId = 700011
        },
        [51007532] = {
          ContentFR = "Un grand Charon passe près de vous, et le garçon disparaît en un instant. Tu te retournes et le vois caché dans ton ombre.",
          DialogueId = 51007532,
          GUID = "7FB12738",
          IsBlack = 1,
          NextDialogue = 51007533
        },
        [51007533] = {
          ContentFR = "Quand le Charon s’éloigne, le garçon revient instantanément à sa position initiale. Comme si de rien n’était.",
          DialogueId = 51007533,
          GUID = "7FB12762",
          IsBlack = 1,
          NextDialogue = 51007534
        },
        [51007534] = {
          ContentFR = "Alors... tu es {性别:partant|partante} ?",
          DialogueId = 51007534,
          GUID = "7FB1278C",
          NextDialogue = 51007535,
          SpeakNpcId = 700011
        },
        [51007535] = {
          ContentFR = "Tu avais peur tout à l’heure ?",
          DialogueId = 51007535,
          GUID = "7FB127B6",
          NextDialogue = 51007536,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007536] = {
          ContentFR = "P-Pas du tout ! Je... je voulais juste être poli !",
          DialogueId = 51007536,
          GUID = "7FB127E0",
          NextDialogue = 51007537,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007537] = {
          ContentFR = "Tu sais, les chercheurs ne sont pas censés mentir.",
          DialogueId = 51007537,
          GUID = "7FB1280A",
          NextDialogue = 51007538,
          SpeakNpcId = 100001
        },
        [51007538] = {
          ContentFR = "Bon... peut-être un tout petit peu... Mais ce n’est pas important.",
          DialogueId = 51007538,
          GUID = "7FB12834",
          NextDialogue = 51007539,
          SpeakNpcId = 700011
        },
        [51007539] = {
          ContentFR = "Où en étions-nous... ah oui, le questionnaire ! Si tu ne veux pas répondre par écrit, je poserai juste quelques questions importantes à l’oral.",
          DialogueId = 51007539,
          GUID = "7FB1285E",
          NextDialogue = 51007540,
          SpeakNpcId = 700011
        },
        [51007540] = {
          ContentFR = "Si tu es libre maintenant, on peut commencer tout de suite !",
          DialogueId = 51007540,
          GUID = "7FB12888",
          SpeakNpcId = 700011
        },
        [51007543] = {
          ContentFR = "Super ! Alors écoute bien, première question !",
          DialogueId = 51007543,
          GUID = "7FB12906",
          NextDialogue = 51007544,
          SpeakNpcId = 700011
        },
        [51007544] = {
          ContentFR = "Question 1 : Pourquoi n’as-tu qu’une seule corne ?",
          DialogueId = 51007544,
          GUID = "7FB12930",
          NextOptions = {
            [1] = 51007545,
            [2] = 51007547,
            [3] = 51007550
          },
          SpeakNpcId = 700011
        },
        [51007545] = {
          ContentFR = "Je suis {性别:né|née} comme ça.",
          DialogueId = 51007545,
          GUID = "7FB1295A",
          NextDialogue = 51007546
        },
        [51007546] = {
          ContentFR = "Ah... donc c’est une différence naturelle. Intéressant...",
          DialogueId = 51007546,
          GUID = "7FB12984",
          NextDialogue = 51007553,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007547] = {
          ContentFR = "J’ai vendu l’autre pour de l’argent.",
          DialogueId = 51007547,
          GUID = "7FB129AE",
          NextDialogue = 51007548
        },
        [51007548] = {
          ContentFR = "Hein ? On peut vendre ses cornes ?!",
          DialogueId = 51007548,
          GUID = "7FB129D8",
          NextDialogue = 51007549,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Shock_Start"
          }
        },
        [51007549] = {
          ContentFR = "J’aimerais en acheter une pour mes recherches... !",
          DialogueId = 51007549,
          GUID = "7FB12A02",
          NextDialogue = 51007553,
          SpeakNpcId = 700011
        },
        [51007550] = {
          ContentFR = "Seuls les enfants intelligents peuvent voir l’autre.",
          DialogueId = 51007550,
          GUID = "7FB12A2C",
          NextDialogue = 51007551
        },
        [51007551] = {
          ContentFR = "Je ne crois pas à ces histoires pour enfants !",
          DialogueId = 51007551,
          GUID = "7FB12A56",
          NextDialogue = 51007552,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007552] = {
          ContentFR = "Mais… on dirait que les Charons peuvent aussi plaisanter...",
          DialogueId = 51007552,
          GUID = "7FB12A80",
          NextDialogue = 51007553,
          SpeakNpcId = 700011
        },
        [51007553] = {
          ContentFR = "Question 2 : Ta corne, elle est comment au toucher ? Tu peux me donner un petit échantillon ?",
          DialogueId = 51007553,
          GUID = "7FB12AAA",
          NextOptions = {
            [1] = 51007554,
            [2] = 51007556,
            [3] = 51007558
          },
          SpeakNpcId = 700011
        },
        [51007554] = {
          ContentFR = "Ça ferait mal, non.",
          DialogueId = 51007554,
          GUID = "7FB12AD4",
          NextDialogue = 51007555
        },
        [51007555] = {
          ContentFR = "Désolé... alors les Enfants du Démon ressentent aussi la douleur ? Ce n’est pas ce que mon père disait...",
          DialogueId = 51007555,
          GUID = "7FB12AFE",
          NextDialogue = 51007562,
          SpeakNpcId = 700011
        },
        [51007556] = {
          ContentFR = "Bien sûr. Cela sera 30 000 pièces d’argent.",
          DialogueId = 51007556,
          GUID = "7FB12B28",
          NextDialogue = 51007557
        },
        [51007557] = {
          ContentFR = "Hein ?! Euh... tant pis.",
          DialogueId = 51007557,
          GUID = "7FB12B52",
          NextDialogue = 51007562,
          SpeakNpcId = 700011
        },
        [51007558] = {
          ContentFR = "Vas-y touche, elle est empoisonnée.",
          DialogueId = 51007558,
          GUID = "7FB12B7C",
          NextDialogue = 51007559
        },
        [51007559] = {
          ContentFR = "Vraiment ? Quelle est la gravité du poison ? Y a-t-il un antidote ? Toi aussi tu serais empoisonné ?",
          DialogueId = 51007559,
          GUID = "7FB12BA6",
          NextDialogue = 51007560,
          SpeakNpcId = 700011
        },
        [51007560] = {
          ContentFR = "... Pas de poison, c’est une blague. Mais ça ferait mal, donc non.",
          DialogueId = 51007560,
          GUID = "7FB12BD0",
          NextDialogue = 51007561,
          SpeakNpcId = 100001
        },
        [51007561] = {
          ContentFR = "Alors, tes parents ressemblent à quoi ? Super effrayants ? Capables d’avaler une personne ?",
          DialogueId = 51007561,
          GUID = "7FB12BFA",
          NextDialogue = 51007562,
          SpeakNpcId = 700011
        },
        [51007562] = {
          ContentFR = "Puisque tu es {性别:un|une} enfant du Démon, à quoi ressemblent tes parents ? Ils sont super féroces... du genre à pouvoir avaler quelqu’un d’une seule bouchée ?",
          DialogueId = 51007562,
          GUID = "7FB12C24",
          NextOptions = {
            [1] = 51007563,
            [2] = 51007565,
            [3] = 51007567
          },
          SpeakNpcId = 700011
        },
        [51007563] = {
          ContentFR = "Probablement de simples Charons, j’imagine.",
          DialogueId = 51007563,
          GUID = "7FB12C4E",
          NextDialogue = 51007564
        },
        [51007564] = {
          ContentFR = "Oh... c’est ennuyeux.",
          DialogueId = 51007564,
          GUID = "7FB12C78",
          NextDialogue = 51007569,
          SpeakNpcId = 700011
        },
        [51007565] = {
          ContentFR = "Je ne les ai jamais vus.",
          DialogueId = 51007565,
          GUID = "7FB12CA2",
          NextDialogue = 51007566
        },
        [51007566] = {
          ContentFR = "« Pas de conclusion sans observation », tu as vraiment l’âme d’un chercheur !",
          DialogueId = 51007566,
          GUID = "7FB12CCC",
          NextDialogue = 51007569,
          SpeakNpcId = 700011
        },
        [51007567] = {
          ContentFR = "Ce sont des fées.",
          DialogueId = 51007567,
          GUID = "7FB12CF6",
          NextDialogue = 51007568
        },
        [51007568] = {
          ContentFR = "Ah, c’est marrant, un autre Charon m’avait dit la même chose il y a quelques années !",
          DialogueId = 51007568,
          GUID = "7FB12D20",
          NextDialogue = 51007569,
          SpeakNpcId = 700011
        },
        [51007569] = {
          ContentFR = "Il y a quelques années, j’ai rencontré un Charon très gentil. Il m’a dit qu’il était une "fée".",
          DialogueId = 51007569,
          GUID = "7FB12D4A",
          NextDialogue = 51007570,
          SpeakNpcId = 700011
        },
        [51007570] = {
          ContentFR = "Ce jour-là, il était pressé d’aller retrouver quelqu’un, alors je n’ai pas pu en apprendre davantage...",
          DialogueId = 51007570,
          GUID = "7FB12D74",
          NextDialogue = 51007571,
          SpeakNpcId = 700011
        },
        [51007571] = {
          ContentFR = "Mais c’est le premier qui m’ait donné une réponse différente à propos de l’origine des Charons, alors ça m’est toujours resté en tête. Dommage... je ne l’ai jamais retrouvé.",
          DialogueId = 51007571,
          GUID = "7FB12D9E",
          NextDialogue = 51007576,
          NextOptions = {
            [1] = 51007572,
            [2] = 51007574
          },
          SpeakNpcId = 700011
        },
        [51007572] = {
          ContentFR = "Il était vraiment une fée.",
          DialogueId = 51007572,
          GUID = "7FB12DC8",
          NextDialogue = 51007573,
          TriggerCondition = {
            ImprComp = {TalkTriggerId = 500080}
          }
        },
        [51007573] = {
          ContentFR = "Si vous dites tous les deux ça, alors ça doit être vrai !",
          DialogueId = 51007573,
          GUID = "7FB12DF2",
