          ContentFR = "Pardonnez mon audace. Permettez que j’emprunte une ligne, infime mais glorieuse, de votre épopée héroïque, pour me présenter.",
          DialogueId = 51009201,
          GUID = "7FB2390A",
          LookAt = {
            [1] = "230003:n(100001)"
          },
          NextDialogue = 51009202,
