            [1] = "230003:Explain02_Start"
          }
        },
        [51009202] = {
          Camera = "184.849121,-47.185059,77.377197,0.000079,-13.401609,165.810257,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je me nomme Amiette. Quant à mon métier... il serait une offense à l’art de le réduire en mots.",
          DialogueId = 51009202,
          FinalCamera = "155.654297,64.67334,157.197266,0.000115,-0.001284,-158.590393,35.0,100000.0,false,DoNotOverride,2.8",
