        },
        [51009205] = {
          Camera = "182.905762,56.904785,140.219238,0.000167,0.19811,-165.575302,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas de suspicion gratuite, je vous en prie. Je ne fais que hanter ces lieux, troublé par de profondes interrogations... <H>esthétiques</>.",
          DialogueId = 51009205,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "209.431152,63.451172,140.220459,0.000167,-0.001858,-166.175751,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB239B2",
          NextDialogue = 51009206,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "230003:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009206] = {
          ContentFR = "N’avez-vous pas remarqué ? Les armes d’aujourd’hui n’ont d’yeux que pour la puissance brute et le coût de production. La beauté de la forge, elle, est complètement oubliée !",
          DialogueId = 51009206,
          GUID = "7FB239DC",
          NextDialogue = 51009207,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Explain01_End"
          }
        },
        [51009207] = {
          Camera = "-2849.924805,472.516602,-933.664307,0.000118,-4.801397,-111.175285,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les armes n’étaient pas mon domaine de prédilection, mais regardez donc ! Les soldats de cette cité se sont faits vulgaires, grossiers.",
          DialogueId = 51009207,
          FinalCamera = "-2585.590332,363.479004,-933.664307,0.000116,-5.401429,-115.973396,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23A06",
          NextDialogue = 51009208,
          SpeakNpcId = 230003,
          ToFinalCameraBlendTime = 15
        },
        [51009208] = {
          Camera = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et je blâme l’Académie d’Alchimie d’Hyperborea ! À force de renoncer à l’esthétique, leurs porteurs deviennent eux-mêmes médiocres. Quand j’ai voulu corriger leurs armes, ils m’ont injustement puni...",
          DialogueId = 51009208,
          GUID = "7FB23A30",
          NextDialogue = 51009209,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Explain02_Start"
          }
        },
        [51009209] = {
          Camera = "107.540039,43.087402,155.901123,0.000135,-9.202333,39.223675,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Corriger » ? Tu as fait quelque chose d’interdit ?",
          DialogueId = 51009209,
          GUID = "7FB23A5A",
          NextDialogue = 51009210,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009210] = {
          Camera = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Interdit ? Pas du tout ! Je n’ai fait que modifier subtilement leurs armes et accessoires pendant un changement de garde. Quinze jours d’emprisonnement pour ça... n’est-ce pas démesuré ?",
          DialogueId = 51009210,
          GUID = "7FB23A84",
          NextDialogue = 51009211,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Angry01_Start"
          }
        },
        [51009211] = {
          ContentFR = "Certes, inculquer un sens esthétique au plus grand nombre est une tâche titanesque. Mais devons-nous abandonner pour autant ?",
          DialogueId = 51009211,
          GUID = "7FB23AAE",
          NextDialogue = 51009212,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Angry01_End"
          }
        },
        [51009212] = {
          Camera = "355.351074,108.127441,146.656494,0.000137,-3.402848,-172.570343,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je le jure au nom de l’Art ! De la plus légendaire des épées à la plus humble des lames, peu importe son prix ou son origine : toute arme doit refléter la beauté !",
          DialogueId = 51009212,
          GUID = "7FB23AD8",
          NextDialogue = 51009213,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Agree"
          }
        },
        [51009213] = {
          Camera = "179.876953,-270.89502,193.723389,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ? Voilà qui est intéressant. J’aime entendre parler avec passion.",
          DialogueId = 51009213,
          FinalCamera = "170.026367,-235.211914,187.194336,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
