        },
        [51009215] = {
          Camera = "77.210938,30.784668,120.665283,0.000054,-10.001801,93.224159,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Aujourd’hui, tout est bâclé. Les lignes forgées au marteau, les motifs créés par la trempe, l’équilibre au creux de la main... chaque détail devrait porter la marque de l’âme du forgeron.",
          DialogueId = 51009215,
          FacialId = {
            [1] = "230002:Happy01"
          },
          FinalCamera = "109.248535,35.82959,120.665283,0.000053,-10.801848,106.024544,35.0,100000.0,false,DoNotOverride,2.8",
