          GUID = "7FB23D4E",
          NextDialogue = 51009233,
          Scripts = "SEQ{\nPlayAnimation{ActorId{100001},AnimationId{\"Sigh_Start\"},Duration{2}},\nPlayAnimation{ActorId{100001},AnimationId{\"Sigh_End\"},Duration{2}}\n}",
