          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "100001:Shock_End"
          }
        },
        [51009432] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chaque recoin de ma demeure se retrouve rempli de lettres dès que j’ai le dos tourné.",
          DialogueId = 51009432,
          GUID = "7FB25EF0",
          NextDialogue = 51009433,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_End"
          }
        },
        [51009433] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas aux Veilleurs de s’occuper de ce genre d’affaires ?",
          DialogueId = 51009433,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB25F1A",
          NextDialogue = 51009434,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009434] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est ce que j’ai pensé moi aussi, au début. Mais les personnalités publiques doivent toujours marcher sur des œufs...",
          DialogueId = 51009434,
          GUID = "7FB25F44",
          NextDialogue = 51009435,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009435] = {
          ContentFR = "Une petite anecdote peut bien faire de moi le sujet favori des commérages... mais en tant qu’artiste, j’aimerais que l’on parle de mon art sur scène, pas de mes affaires de cœur. J’espère que tu comprends.",
          DialogueId = 51009435,
          GUID = "7FB25F6E",
          NextDialogue = 51009436,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009436] = {
          Camera = "124.308105,149.785156,166.572021,0.000009,-4.799984,-153.390015,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’accord, je vois. As-tu des pistes concernant l’expéditeur ?",
          DialogueId = 51009436,
          GUID = "7FB25F98",
          NextDialogue = 51009437,
          SpeakNpcId = 100001
        },
        [51009437] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai oublié de le préciser tout à l’heure : je sais en réalité où il habite. Les lettres sont anonymes, mais il n’a pas vraiment cherché à dissimuler son identité.",
          DialogueId = 51009437,
          GUID = "7FB25FC2",
          NextDialogue = 51009438,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009438] = {
          ContentFR = "Après tout, si l’on doit cacher son nom même dans une déclaration d’amour... comment espérer une réponse ?",
          DialogueId = 51009438,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB25FEC",
          NextDialogue = 51009439,
          SpeakNpcId = 700300
        },
        [51009439] = {
          Camera = "-642.584961,260.924316,353.573975,0.000005,-21.200073,-26.393641,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tout ce que je te demande, c’est de le trouver... et de lui adresser un petit "avertissement".",
          DialogueId = 51009439,
          GUID = "7FB26016",
          NextOptions = {
            [1] = 510093491,
            [2] = 510093492
          },
          SpeakNpcId = 700300
        },
        [51009440] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je savais que je pouvais compter sur toi.",
          DialogueId = 51009440,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB26040",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009441] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu sais... ce genre de personne pourrait mal interpréter la moindre attention. Cela pourrait même l’encourager à aller plus loin.",
          DialogueId = 51009441,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2606A",
          NextDialogue = 51009442,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009442] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vu comme ça, je comprends mieux.",
          DialogueId = 51009442,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB26094",
          NextDialogue = 51009443,
          SpeakNpcId = 100001
        },
        [51009443] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien, je te laisse t’en occuper.",
          DialogueId = 51009443,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB260BE",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009444] = {
          ContentFR = "Ah, j’allais oublier. Prends ceci, cela pourrait t’être utile.",
          DialogueId = 51009444,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          GUID = "7FB260E8",
          NextDialogue = 51009445,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009445] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce ruban...",
          DialogueId = 51009445,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB26112",
          NextDialogue = 51009446,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009446] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quelque chose ne va pas ?",
          DialogueId = 51009446,
          GUID = "7FB2613C",
          NextDialogue = 51009447,
          SpeakNpcId = 700300
        },
        [51009447] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... rien du tout. Je reviendrai bientôt.",
          DialogueId = 51009447,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26166",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009448] = {
          Camera = "695.307617,-554.236328,471.275024,0.000054,-20.794161,139.593384,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "L’adresse que m’a donnée Madame Violetta devrait être ici... Pourtant, il n’y a pas vraiment de logements dans le coin.",
          DialogueId = 51009448,
          GUID = "7FB26190",
          NextDialogue = 51009449,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700313:Think_Start"
          }
        },
        [51009449] = {
          ContentFR = "Il y a un soldat pas loin. Allons lui poser quelques questions.",
          DialogueId = 51009449,
          GUID = "7FB261BA",
          NextDialogue = 51009450,
          SpeakNpcId = 100001
        },
        [51009450] = {
          Camera = "232.955078,593.629395,162.682861,0.000058,-3.794279,-115.003006,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bonjour, j’aimerais vous demander quelque chose.",
          DialogueId = 51009450,
          GUID = "7FB261E4",
          NextDialogue = 51009451,
          Scripts = "MoveTo{ActorId{100001},TargetPoint{"Questpoint_Nvzhu_20023002"},MoveSpeed{150},Visibility{"Show"}}",
          SpeakNpcId = 100001
        },
        [51009451] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je suis occupé, revenez plus tard... C’est étrange, ça devrait marcher... Qu’est-ce qui arrive à ce vieux phonographe ?",
          DialogueId = 51009451,
          GUID = "7FB2620E",
          NextDialogue = 51009452,
          SpeakNpcId = 700313
        },
        [51009452] = {
          Camera = "408.029297,-87.160217,216.346191,0.000075,-13.994142,150.79335,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le soldat s’agite, visiblement contrarié, en manipulant un vieux phonographe posé à ses pieds.",
          DialogueId = 51009452,
          GUID = "7FB26238",
          NextDialogue = 51009453
        },
        [51009453] = {
          ContentFR = "Il est cassé ?",
          DialogueId = 51009453,
          GUID = "7FB26262",
          NextDialogue = 51009454,
          SpeakNpcId = 100001
        },
        [51009454] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas vraiment cassé... mais il commence à dater, alors il fonctionne parfois de travers. Je suis pourtant sûr qu’un petit coup suffisait à le remettre en marche...",
          DialogueId = 51009454,
          GUID = "7FB2628C",
          NextOptions = {
            [1] = 510093641
          },
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009455] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu sais bricoler ce genre de choses ? Très bien. Si tu arrives à le réparer, je te dirai tout ce que je sais.",
          DialogueId = 51009455,
          GUID = "7FB262B6",
          NextDialogue = 51009456,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Talk01_End"
          }
        },
        [51009456] = {
          Camera = "96.858398,213.679291,148.014893,0.00006,-3.794279,-114.800949,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Marché conclu.",
          DialogueId = 51009456,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB262E0",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Talk01_End"
          }
        },
        [51009457] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voilà, ça devrait fonctionner maintenant.",
          DialogueId = 51009457,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "7FB2630A",
          NextDialogue = 51009458,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009458] = {
          Camera = "490.863281,-71.149292,246.487061,0.000077,-14.394158,157.593735,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas mal ! Je vais enfin pouvoir écouter mes cassettes. Ah, la voix de Violetta... quel délice...",
          DialogueId = 51009458,
          GUID = "7FB26334",
          NextDialogue = 51009459,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700313:Shock_Start"
          }
        },
        [51009459] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Connaissez-vous Madame Violetta ?",
          DialogueId = 51009459,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2635E",
          NextDialogue = 51009460,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Shock_End"
          }
        },
        [51009460] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qui à Givrelac ne la connaît pas ? Son premier disque vaut une fortune ! J’économise depuis trois mois et je ne peux toujours pas me le payer... Alors je me rabats sur ces enregistrements bon marché.",
          DialogueId = 51009460,
          GUID = "7FB26388",
          NextDialogue = 51009461,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009461] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfait. Justement, ce que je voulais vous demander concerne Madame Violetta.",
          DialogueId = 51009461,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB263B2",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009462] = {
          ContentFR = "Après lui avoir fait promettre de garder le secret, tu lui expliques la situation : Violetta reçoit depuis quelque temps des lettres non désirées d’un admirateur trop insistant.)",
          DialogueId = 51009462,
          GUID = "7FB263DC"
        },
        [51009463] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi !? C’est scandaleux ! S’il se cache dans ce quartier, je vais le sortir de là et lui apprendre les bonnes manières !",
          DialogueId = 51009463,
          GUID = "7FB26406",
          NextDialogue = 51009464,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700313:Angry01_Start"
          }
        },
        [51009464] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce ne sera peut-être pas nécessaire...",
          DialogueId = 51009464,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB26430",
          NextDialogue = 51009465,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51009465] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Comment ça, pas nécessaire ? Je déteste ce genre d’individus qui troublent l’ordre public. Je connais pratiquement tous les habitants du coin. Donne-moi un indice, et je le retrouverai.",
          DialogueId = 51009465,
          GUID = "7FB2645A",
          NextDialogue = 51009466,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009466] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un indice, hein... Regardez plutôt cette lettre. Est-ce que cela vous dit quelque chose ?",
          DialogueId = 51009466,
          GUID = "7FB26484",
          NextDialogue = 51009467,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009467] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une lettre ? Fais voir ça.",
          DialogueId = 51009467,
          GUID = "7FB264AE",
          NextDialogue = 51009468,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Confident_End"
          }
        },
        [51009468] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009468,
          FinalCamera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB264D8",
          NextDialogue = 51009469,
          SpeakNpcId = 700313,
          ToFinalCameraBlendTime = 1
        },
        [51009469] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009469,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26502",
          NextDialogue = 51009470,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009470] = {
          ContentFR = "... Qu’y a-t-il ? Pourquoi ne dites-vous rien ?",
          DialogueId = 51009470,
          GUID = "7FB2652C",
          NextDialogue = 51009471,
          SpeakNpcId = 100001
        },
        [51009471] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est... c’est vraiment ça ? Non, impossible. Cette lettre est sincère, pleine de passion et d’émotion ! Rien à voir avec du harcèlement !",
          DialogueId = 51009471,
          GUID = "7FB26556",
          NextDialogue = 51009472,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009472] = {
          Camera = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On dirait bien que j’ai trouvé le coupable. Vous ne parliez pas de lui « apprendre les bonnes manières », tout à l’heure ?",
          DialogueId = 51009472,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB26580",
          NextDialogue = 51009473,
          SpeakNpcId = 100001
        },
        [51009473] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est un malentendu, forcément un malentendu ! Je jure que mes sentiments pour Violetta sont réels ! Et puis, n’est-ce pas bien connu qu’elle aime les déclarations enflammées ? Pourquoi verrait-elle ça comme du harcèlement ?",
          DialogueId = 51009473,
          GUID = "7FB265AA",
          NextDialogue = 51009474,
          SpeakNpcId = 700313
        },
        [51009474] = {
          ContentFR = "... Attends une seconde. <H>Est-ce que ce {性别:Chasseur de Phoxène|Chasseuse de Phoxène} m’aurait menti</>... ?",
          DialogueId = 51009474,
          GUID = "7FB265D4",
          NextDialogue = 51009475,
          SpeakNpcId = 700313
        },
        [51009475] = {
          ContentFR = "Je comprends maintenant ! C’est toi ! Tu n’as jamais été envoyé par Violetta, tu veux simplement nous séparer !",
          DialogueId = 51009475,
          GUID = "7FB265FE",
          NextDialogue = 51009476,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Angry01_Start"
          }
        },
        [51009476] = {
          ContentFR = "As-tu seulement la moindre preuve qu’elle t’a demandé de venir ? À mon avis, tu veux juste semer la discorde !",
          DialogueId = 51009476,
          GUID = "7FB26628",
          NextDialogue = 51009477,
          SpeakNpcId = 700313
        },
        [51009477] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tenter de briser le lien sacré qui unit Violetta à ses admirateurs ? Jamais ! Je vais t’apprendre à regretter ce que tu as fait !",
          DialogueId = 51009477,
          GUID = "7FB26652",
          NextDialogue = 51009478,
          SpeakNpcId = 700313
        },
        [51009478] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais qu’est-ce que vous racontez... ?",
          DialogueId = 51009478,
          GUID = "7FB2667C",
          NextDialogue = 51009479,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51009479] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mieux vaut calmer ce fan délirant avant que les choses ne dégénèrent.",
          DialogueId = 51009479,
          GUID = "7FB266A6",
          SpeakNpcId = 100001
        },
        [51009480] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violetta... Je suis désolé... Je suis trop faible pour te protéger...",
          DialogueId = 51009480,
          GUID = "7FB266D0",
          NextDialogue = 51009481,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009481] = {
          Camera = "172.162109,534.255371,170.810547,0.000068,-3.594264,-113.598976,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est bon, vous avez fini ? Regardez plutôt ceci.",
          DialogueId = 51009481,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "7FB266FA",
          NextDialogue = 51009482,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "700313:Stop01_End"
          }
        },
        [51009482] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est... c’est le ruban de Violetta ? Celui qu’elle porte depuis sa première représentation, il y a plus de dix ans...",
          DialogueId = 51009482,
          GUID = "7FB26724",
          NextDialogue = 51009483,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Shock_Start"
          }
        },
        [51009483] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous arrivez à le reconnaître aussi vite ?",
          DialogueId = 51009483,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB2674E",
          NextDialogue = 51009484,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51009484] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bien sûr que oui... Pourquoi est-ce que je raconte tout ça, d’ailleurs...",
          DialogueId = 51009484,
          GUID = "7FB26778",
          NextDialogue = 51009485,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Shock_End"
          }
        },
        [51009485] = {
          ContentFR = "Si c’est toi qui le portes, alors ça veut dire que j’ai vraiment été rejeté. Je ne la dérangerai plus. Je vous souhaite tout le bonheur du monde.",
          DialogueId = 51009485,
          GUID = "7FB267A2",
          NextOptions = {
            [1] = 510093951,
            [2] = 510093952
          },
          SpeakNpcId = 700313
        },
        [51009486] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Inutile d’en dire plus... Laisse donc un cœur brûlant pleurer seul dans l’ombre...",
          DialogueId = 51009486,
          GUID = "7FB267CC",
          NextDialogue = 51009487,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009487] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le soldat ne dit plus rien. Il se contente de pleurer en silence... Mieux vaut le laisser tranquille un moment.",
          DialogueId = 51009487,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB267F6",
          SpeakNpcId = 100001
        },
        [51009488] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Madame Violetta, me revoilà.",
          DialogueId = 51009488,
          GUID = "7FB26820",
          NextDialogue = 51009489,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009489] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci pour ton aide. J’en déduis que l’affaire est réglée ?",
          DialogueId = 51009489,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB2684A",
          NextDialogue = 51009490,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Talk02_Start"
          }
        },
        [51009490] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Il ne viendra plus t’importuner. Voici ton ruban — sans lui, j’aurais probablement été coincé dans cette histoire encore un bon moment.",
          DialogueId = 51009490,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26874",
          NextDialogue = 51009491,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700300:Talk02_End",
            [2] = "100001:Give"
          }
        },
        [51009491] = {
          ContentFR = "J’ai entendu dire que tu le portes depuis tes débuts... il y a plus de dix ans ?",
          DialogueId = 51009491,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2689E",
          NextDialogue = 51009492,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009492] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est exact. C’est un souvenir qu’une amie très chère m’a laissé. Elle était brillante, mais le destin ne l’a pas épargnée...",
          DialogueId = 51009492,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268C8",
          NextDialogue = 51009493,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Sigh_Start"
          }
        },
        [51009493] = {
          ContentFR = "Pour certaines raisons, elle n’a jamais pu accomplir son rêve. Moi, en revanche, j’en ai eu l’opportunité, alors j’ai voulu qu’elle brille à mes côtés, sur scène.",
          DialogueId = 51009493,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268F2",
          NextDialogue = 51009494,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009494] = {
          ContentFR = "C’est pourquoi, lors de ma toute première représentation, j’ai conçu moi-même l’affiche : une image en noir et blanc, traversée d’un unique éclat de violet.",
          DialogueId = 51009494,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2691C",
          NextDialogue = 51009495,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009495] = {
          ContentFR = "Tu as sans doute déjà entendu ce surnom — « Violetta aux mille visages ». Grâce à mon talent pour le maquillage, je peux me transformer entièrement et incarner chaque rôle avec un visage différent.",
          DialogueId = 51009495,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26946",
          NextDialogue = 51009496,
          SpeakNpcId = 700300
        },
        [51009496] = {
          ContentFR = "Mais il y a une chose qui ne change jamais : ce ruban. Je le porte à chacune de mes représentations. <H>Il est devenu ma signature.</>",
          DialogueId = 51009496,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26970",
          NextDialogue = 51009497,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_End"
          }
        },
        [51009497] = {
          Camera = "6.950195,47.361328,152.822266,0.000007,-4.600037,-165.990051,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je vois...",
          DialogueId = 51009497,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "7FB2699A",
          NextDialogue = 51009498,
          SpeakNpcId = 100001
        },
        [51009498] = {
          ContentFR = "Professeur !",
          DialogueId = 51009498,
          GUID = "7FB269C4",
          LookAt = {
            [1] = "100001:n(700306)",
            [2] = "700300:n(700306)"
          },
          NextDialogue = 51009499,
          SpeakNpcId = 700306
        },
        [51009499] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Fane, je t’ai déjà dit de ne pas crier ainsi.",
          DialogueId = 51009499,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB269EE",
          NextDialogue = 51009500,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009500] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je suis désolé... mais tu dois absolument voir ça !",
          DialogueId = 51009500,
          GUID = "7FB26A18",
          NextDialogue = 51009501,
          Scripts = "PARA{\nPlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}},\nSEQ{\nMoveTo{ActorId{700306},TargetPoint{\"QuestPoint_Fane_2002300701\"},MoveSpeed{250},Visibility{\"Show\"}},\nMoveTo{ActorId{700306},TargetPoint{\"QuestPoint_Fane_2002300702\"},MoveSpeed{250},Visibility{\"Show\"}},\nTurnTo{TurnToDescription{\"700306:n(700300)\"}}\n}\n}",
          SpeakNpcId = 700306
        },
        [51009501] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Encore une lettre ? Pourtant, je l’avais bien averti...",
          DialogueId = 51009501,
          FacialId = {
            [1] = "700300:CM_Angry01",
            [2] = "100001:Angry01"
          },
          GUID = "7FB26A42",
          NextDialogue = 51009502,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700306:Give",
            [2] = "100001:Think_Start",
            [3] = "700300:Confident_End"
          }
        },
        [51009502] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009502,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB26A6C",
          NextDialogue = 51009503,
          SpeakNpcId = 700300
        },
        [51009503] = {
          ContentFR = "Madame Violetta ?",
          DialogueId = 51009503,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26A96",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          },
          NextDialogue = 51009504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009504] = {
          ContentFR = "Seize ans... Cela fait déjà seize ans... Mais pourquoi... pourquoi s’en prendre à des innocents ?",
          DialogueId = 51009504,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26AC0",
          NextDialogue = 51009505,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700300:Disagree"
          }
        },
        [51009505] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu es pâle... tout va bien ?",
          DialogueId = 51009505,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          FinalCamera = "-143.32959,40.580566,146.557373,0.000003,-2.199983,-3.996218,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB26AEA",
          NextDialogue = 51009506,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 2
        },
        [51009506] = {
          ContentFR = "Pardonne-moi... J’ai été bien trop naïve. Je voulais éviter d’ébruiter l’affaire, mais la situation m’échappe désormais. Je vais devoir faire appel aux Veilleurs.",
          DialogueId = 51009506,
          GUID = "7FB26B14",
          NextDialogue = 51009507,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009507] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qu’est-ce qu’il s’est passé ?",
          DialogueId = 51009507,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26B3E",
          NextDialogue = 51009508,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009508] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Regarde plutôt ceci.",
          DialogueId = 51009508,
          GUID = "7FB26B68",
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700300:Give"
          }
        },
        [51009509] = {
          ContentFR = "« Violetta — ou devrais-je dire, Madame E.R.\nJe connais tous tes sales petits secrets depuis seize ans.\nRetrouve-moi seule, à minuit, près du bassin derrière l’entrée secondaire de Givrelac... sinon je ne garantis pas la sécurité de ton élève. »",
          DialogueId = 51009509,
          Duration = 5,
          GUID = "7FB26B92"
        },
        [51009510] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009510,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "7FB26BBC",
          NextDialogue = 51009511,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock02_Start"
          }
        },
        [51009511] = {
          Camera = "-143.32959,40.580566,146.557373,0.000003,-2.199983,-3.996218,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je crains que toutes ces lettres n’aient été qu’un leurre. Je me suis laissée berner.",
          DialogueId = 51009511,
          GUID = "7FB26BE6",
          NextDialogue = 51009512,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009512] = {
          ContentFR = "Je suis désolée, mais je dois partir. Ne t’en fais pas : la mission que je t’ai confiée est bel et bien terminée. Voici la récompense convenue.",
          DialogueId = 51009512,
          GUID = "7FB26C10",
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009513] = {
          ContentFR = "Il semblerait qu’une affaire d’enlèvement soit en train de se produire sous tes yeux. Bien que Violetta ait décidé de solliciter l’aide des Veilleurs, il serait peut-être judicieux de garder un œil sur l’évolution de cette affaire.",
          DialogueId = 51009513,
          GUID = "7FB26C3A",
          Scripts = "PlayOrStopBGM{_delay{10},PlayType{"Stop"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"}}"
        },
        [51009601] = {
          ContentFR = "S’il te plaît... aide-nous, je t’en supplie... !",
          DialogueId = 51009601,
          GUID = "7FB27AAA",
          SpeakNpcId = 700303
        },
        [51009602] = {
          ContentFR = "Un garçon tire sur ta manche, le visage marqué par l’inquiétude.",
          DialogueId = 51009602,
          GUID = "7FB27AD4",
          IsBlack = 1,
          NextDialogue = 510095121
        },
        [51009603] = {
          ContentFR = "Oncle Donat est malade... très malade...",
          DialogueId = 51009603,
          GUID = "7FB27AFE",
          NextDialogue = 51009604,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Sigh_Start"
          }
        },
        [51009604] = {
          ContentFR = "Tout le monde dit que tu es {性别:le plus fort|la plus forte} des Chasseurs de Phoxène... et aussi {性别:le plus gentil|la plus gentille}... Je t’en prie... sauve-le !",
          DialogueId = 51009604,
          GUID = "7FB27B28",
          NextDialogue = 51009605,
          SpeakNpcId = 700303
        },
        [51009605] = {
          ContentFR = "Il est malade ? Vous avez vu un médecin ?",
          DialogueId = 51009605,
          GUID = "7FB27B52",
          NextDialogue = 51009606,
          SpeakNpcId = 100001
        },
        [51009606] = {
          ContentFR = "Oui... mais le médecin a dit que... c’était déjà trop tard...",
          DialogueId = 51009606,
          GUID = "7FB27B7C",
          NextDialogue = 51009607,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Disagree"
          }
        },
        [51009607] = {
          ContentFR = "Je... je te donnerai tout l’argent que j’ai ! Et s’il n’y en a pas assez... je ferai n’importe quoi ! Tout ce qu’il faut !",
          DialogueId = 51009607,
          GUID = "7FB27BA6",
          SpeakNpcId = 700303
        },
        [51009608] = {
          ContentFR = "Où est-il maintenant ?",
          DialogueId = 51009608,
          GUID = "7FB27BD0",
          NextDialogue = 51009609,
          SpeakNpcId = 100001
        },
        [51009609] = {
          ContentFR = "Dans une ruelle de Brumelac. Viens, je vais t’y conduire !",
          DialogueId = 51009609,
          GUID = "7FB27BFA",
          SpeakNpcId = 700303
        },
        [51009610] = {
          Camera = "47.982422,-602.043945,9.373535,0.00001,7.999701,87.596718,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le garçon frappe à la porte, mais personne ne répond.",
          DialogueId = 51009610,
          GUID = "7FB27C24",
          IsBlack = 1,
          NextDialogue = 51009611
        },
        [51009611] = {
          ContentFR = "Hein ? C’est bizarre... Il était là il y a un instant...",
          DialogueId = 51009611,
          GUID = "7FB27C4E",
          NextDialogue = 51009612,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700303)"
          }
        },
        [51009612] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu sais où il aurait pu aller ?",
          DialogueId = 51009612,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB27C78",
          NextDialogue = 51009613,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700303:Sigh_End"
          },
          TurnTo = {
            [1] = "700303:n(100001)"
          }
        },
        [51009613] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Euh... oh oui ! ",
          DialogueId = 51009613,
          GUID = "7FB27CA2",
          NextDialogue = 51009614,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700303:Think_Start"
          }
        },
        [51009614] = {
          ContentFR = "Je crois qu’il disait souvent qu’il voulait retourner voir « la fosse ». Quelque chose comme... Glem... Glum... ?",
          DialogueId = 51009614,
          GUID = "7FB27CCC",
          NextDialogue = 51009615,
          SpeakNpcId = 700303
        },
        [51009615] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La Fosse de Glevum ?",
          DialogueId = 51009615,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB27CF6",
          NextDialogue = 51009616,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700303:Think_End",
            [2] = "100001:Talk02_Start"
          }
        },
        [51009616] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, c’est ça ! Tu vas y aller ? Laisse-moi venir avec toi !",
          DialogueId = 51009616,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB27D20",
          NextDialogue = 51009617,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Explain02_Start"
          }
        },
        [51009617] = {
          ContentFR = "Il est très malade... et j’ai peur que—",
          DialogueId = 51009617,
          GUID = "7FB27D4A",
          NextDialogue = 51009618,
          SpeakNpcId = 700303
        },
        [51009618] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est bien trop dangereux pour un enfant. Je ne peux pas t’emmener là-bas. Mais je te promets que si je le retrouve, je le ramènerai ici. Attends-moi simplement.",
          DialogueId = 51009618,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB27D74",
          NextDialogue = 51009619,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700303:Explain02_End",
            [2] = "100001:Disagree"
          }
        },
        [51009619] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’accord... Je compte sur toi !",
          DialogueId = 51009619,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB27D9E",
          NextDialogue = 51009620,
          SpeakNpcId = 700303
        },
        [51009620] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis-moi, Lars... comment est Donat ?",
          DialogueId = 51009620,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB27DC8",
          NextDialogue = 51009621,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009621] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est le plus gentil de tout Givrelac !",
          DialogueId = 51009621,
          GUID = "7FB27DF2",
          NextDialogue = 51009622,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700303:Confident_Start"
          }
        },
        [51009622] = {
          ContentFR = "Il partage toujours sa nourriture avec nous, et il utilise son propre argent pour acheter des vêtements et des livres aux enfants de Brumelac.",
          DialogueId = 51009622,
          GUID = "7FB27E1C",
          NextDialogue = 51009623,
          SpeakNpcId = 700303
        },
        [51009623] = {
          ContentFR = "Il répare les maisons et les meubles, apporte des médicaments aux malades, et offre un abri aux mendiants pendant les tempêtes de neige... Presque tout le monde ici lui doit quelque chose.",
          DialogueId = 51009623,
          GUID = "7FB27E46",
          NextDialogue = 51009624,
          SpeakNpcId = 700303
        },
        [51009624] = {
          ContentFR = "Et puis, et puis—",
          DialogueId = 51009624,
          GUID = "7FB27E70",
          NextDialogue = 51009625,
          SpeakNpcId = 700303
        },
        [51009625] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Euh, je voulais dire : à quoi ressemble-t-il ?",
          DialogueId = 51009625,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB27E9A",
          NextDialogue = 51009626,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          }
        },
        [51009626] = {
          Camera = "47.982422,-602.043945,9.373535,0.00001,7.999701,87.596718,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hein ? Oh... pardon !",
          DialogueId = 51009626,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB27EC4",
          NextDialogue = 51009627,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "100001:Sigh_End",
            [2] = "700303:Explain02_Start"
          }
        },
        [51009627] = {
          ContentFR = "Il a un peu plus de quarante ans, les cheveux bruns, plutôt grand et mince... et ses vêtements sont très usés.",
          DialogueId = 51009627,
          GUID = "7FB27EEE",
          NextDialogue = 51009628,
          SpeakNpcId = 700303
        },
        [51009628] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien, ça va bien m'aider.",
          DialogueId = 51009628,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB27F18",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [51009629] = {
          ContentFR = "Kof, kof...",
          DialogueId = 51009629,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB27F42",
          NextOptions = {
            [1] = 51009630
          },
          SpeakNpcId = 700301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009630] = {
          ContentFR = "Excuse-moi...",
          DialogueId = 51009630,
          GUID = "7FB27F6C",
          NextDialogue = 510095401
        },
        [51009631] = {
          ContentFR = "Tu es Donat ?",
          DialogueId = 51009631,
          FacialId = {
            [1] = "700301:CM_Idle"
          },
          GUID = "7FB27F96",
          NextDialogue = 51009632,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700301:Explain01_End"
          }
        },
        [51009632] = {
          ContentFR = "Et toi, tu es... ?",
          DialogueId = 51009632,
          GUID = "7FB27FC0",
          NextDialogue = 51009633,
          SpeakNpcId = 700301
        },
        [51009633] = {
          ContentFR = "Un garçon m’a demandé de venir te chercher.",
          DialogueId = 51009633,
          GUID = "7FB27FEA",
          NextDialogue = 51009634,
          SpeakNpcId = 100001
        },
        [51009634] = {
          ContentFR = "Ah... Lars, j’imagine. Ce petit s’inquiète toujours trop.",
          DialogueId = 51009634,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB28014",
          NextDialogue = 51009635,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009635] = {
          ContentFR = "Je voulais simplement revoir cet endroit... Autrefois, les Souillés l’infestaient et on ne pouvait pas approcher.",
          DialogueId = 51009635,
          FacialId = {
            [1] = "700301:CM_Idle"
          },
          GUID = "7FB2803E",
          NextDialogue = 51009636,
          SpeakNpcId = 700301
        },
        [51009636] = {
          ContentFR = "Mais j’ai entendu dire {性别:qu’un Chasseur de Phoxène très talentueux|qu’une Chasseuse de Phoxène très talentueuse} les avait éliminés... Alors j’ai profité de l’occasion pour revenir.",
          DialogueId = 51009636,
          GUID = "7FB28068",
          NextOptions = {
            [1] = 510096361,
            [2] = 510096362
          },
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009637] = {
          ContentFR = "Vraiment... ? Je te remercie — kof, kof !",
          DialogueId = 51009637,
          GUID = "7FB28092",
          NextDialogue = 51009638,
          SpeakNpcId = 700301
        },
        [51009638] = {
          ContentFR = "Désolé... Je dois aller un peu plus loin. Merci d’être venu jusqu’ici, mais dis à Lars que tout va bien. Je laisserai ta récompense aux Asphodèles plus tard. Kof...",
          DialogueId = 51009638,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB280BC",
          NextDialogue = 51009639,
          SpeakNpcId = 700301
        },
        [51009639] = {
          ContentFR = "Je n’ai éliminé que le plus gros des Souillés. Il pourrait encore en rester. Dans ton état, tu ne devrais pas avancer seul. Où veux-tu aller ? Je vais t’accompagner.",
          DialogueId = 51009639,
          GUID = "7FB280E6",
          NextDialogue = 51009640,
          SpeakNpcId = 100001
        },
        [51009640] = {
          ContentFR = "Tu... ferais ça ?",
          DialogueId = 51009640,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28110",
          NextDialogue = 51009641,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009641] = {
          ContentFR = "Oui. J’ai promis à Lars de te ramener sain et sauf.",
          DialogueId = 51009641,
          GUID = "7FB2813A",
          NextDialogue = 51009642,
          SpeakNpcId = 100001
        },
        [51009642] = {
          ContentFR = "Merci... merci, jeune {性别:ami|amie}.",
          DialogueId = 51009642,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB28164",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009643] = {
          Camera = "-375.460938,260.694336,170.375488,0.000148,-11.001406,-38.598434,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci, {性别:jeune homme|jeune femme}...",
          DialogueId = 51009643,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB2818E",
          NextDialogue = 51009644,
          SpeakNpcId = 700301,
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009644] = {
          Camera = "704.804688,1549.59082,762.798828,0.000162,-10.801759,-103.40123,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est encore plus délabré que dans mes souvenirs...",
          DialogueId = 51009644,
          FinalCamera = "704.804688,1549.59082,762.798828,0.000163,-10.801759,-103.401352,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB281B8",
          NextDialogue = 51009645,
          SpeakNpcId = 700301,
          ToFinalCameraBlendTime = 5
        },
        [51009645] = {
          Camera = "949.248047,585.90332,736.995117,0.000167,0.198089,-138.598633,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La porte principale est verrouillée. Heureusement, on peut encore passer par ce tuyau...",
          DialogueId = 51009645,
          GUID = "7FB281E2",
          SpeakNpcId = 700301
        },
        [51009646] = {
          ContentFR = "Kof... kof... kof...",
          DialogueId = 51009646,
          GUID = "7FB2820C",
          NextDialogue = 51009647,
          SpeakNpcId = 700301
        },
        [51009647] = {
          ContentFR = "Ça va ?",
          DialogueId = 51009647,
          GUID = "7FB28236",
          NextDialogue = 51009648,
          SpeakNpcId = 100001
        },
        [51009648] = {
          ContentFR = "Je... kof ça va... Continuons. L’endroit que je cherche est tout près.",
          DialogueId = 51009648,
          GUID = "7FB28260",
          NextDialogue = 51009649,
          SpeakNpcId = 700301
        },
        [51009649] = {
          ContentFR = "Tu sembles bien connaître les lieux.",
          DialogueId = 51009649,
          GUID = "7FB2828A",
          NextDialogue = 51009650,
          SpeakNpcId = 100001
        },
        [51009650] = {
          ContentFR = "Oui... J’étais mineur ici. Il y a seize ans, je marchais chaque jour dans ces galeries.",
          DialogueId = 51009650,
          GUID = "7FB282B4",
          NextDialogue = 51009651,
          SpeakNpcId = 700301
        },
        [51009651] = {
          ContentFR = "On passait dix, douze heures par jour là-dessous... Je connaissais chaque recoin par cœur, même les yeux fermés.",
          DialogueId = 51009651,
          GUID = "7FB282DE",
          SpeakNpcId = 700301
        },
        [51009652] = {
          ContentFR = "Mince... Il y a des Souillés tout autour...",
          DialogueId = 51009652,
          GUID = "7FB28308",
          SpeakNpcId = 700301
        },
        [51009653] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Heureusement... Elle n’a pas été endommagée. Merci, vraiment.",
          DialogueId = 51009653,
          GUID = "7FB28332",
          NextDialogue = 51009654,
          SpeakNpcId = 700301
        },
        [51009654] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sig... mon vieil ami. Je suis venu te voir...",
          DialogueId = 51009654,
          FinalCamera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2835C",
          NextDialogue = 51009655,
          SpeakNpcId = 700301,
          ToFinalCameraBlendTime = 5
        },
        [51009655] = {
          ContentFR = "C’est... une tombe ?",
          DialogueId = 51009655,
          GUID = "7FB28386",
          NextDialogue = 51009656,
          SpeakNpcId = 100001
        },
        [51009656] = {
          ContentFR = "On dirait un triste tas de pierres, hein ?",
          DialogueId = 51009656,
          GUID = "7FB283B0",
          NextDialogue = 51009657,
          SpeakNpcId = 700301
        },
        [51009657] = {
          Camera = "391.647461,354.068359,51.502441,0.000019,-5.200888,-159.003296,40.0,565.324158,false,Manual,2.8",
          ContentFR = "Il disait que j’étais son meilleur ami... et tout ce que j’ai pu lui offrir, c’est ce petit lopin de terre misérable.",
          DialogueId = 51009657,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB283DA",
          NextDialogue = 51009658,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009658] = {
          ContentFR = "Attends... c’est... Non... Pourquoi... ?",
          DialogueId = 51009658,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28404",
          NextDialogue = 51009659,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Shock_Start"
          }
        },
        [51009659] = {
          ContentFR = "Le visage de Donat, livide quelques instants plus tôt, se crispe soudain. Ses veines ressortent, son regard empli de choc et de douleur. Tu suis ses yeux — et vois, posé contre la pierre, un ruban violet.",
          DialogueId = 51009659,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2842E",
          NextDialogue = 51009660
        },
        [51009660] = {
          Camera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violette... pourquoi es-tu revenue ?",
          DialogueId = 51009660,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28458",
          NextDialogue = 51009661,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700301)"
          }
        },
        [51009661] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violette... ? Qui est-ce ?",
          DialogueId = 51009661,
          FacialId = {
