        },
        [51009662] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Soupir... {性别:Jeune ami|Jeune amie}, accepterais-tu d’écouter quelques histoires d’un autre temps ?",
          DialogueId = 51009662,
          GUID = "7FB284AC",
          NextDialogue = 51009663,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_End",
            [2] = "100001:Talk02_End"
          },
          TurnTo = {
