        },
        [51009666] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Désolé, petit... Je t’ai encore inquiété — kof... kof kof...",
          DialogueId = 51009666,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
