        },
        [51009717] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis... je peux te demander quelque chose ?",
          DialogueId = 51009717,
          GUID = "7FB28DB2",
          NextDialogue = 51009718,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Talk02_End"
          },
