          }
        },
        [51009718] = {
          Camera = "-204.549316,-144.984375,111.20166,0.000049,-3.59994,24.790976,40.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qu’y a-t-il ?",
          DialogueId = 51009718,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28DDC",
          NextDialogue = 51009719,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009719] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis... est-ce que tu crois qu’Oncle Donat est une "mauvaise" personne ?",
          DialogueId = 51009719,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28E06",
          NextOptions = {
            [1] = 510096291,
            [2] = 510096292,
            [3] = 510096293,
            [4] = 510096294
          },
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Explain02_Start"
          }
        },
        [51009720] = {
          Camera = "174.810547,-35.033203,84.850098,0.000033,-4.400117,168.992874,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... D’accord, c’est ce que tu penses. Je comprends. Merci... Tiens, prends ça — j’ai mis très longtemps à économiser cet argent !",
          DialogueId = 51009720,
          GUID = "7FB28E30",
          NextDialogue = 51009721,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51009721] = {
          Camera = "34.74585,-46.004883,96.84375,0.000042,-1.400134,16.193537,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce ruban violet... il a sans doute été laissé par Violette sur la tombe de Sig.",
          DialogueId = 51009721,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28E5A",
          NextDialogue = 51009722,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009722] = {
          ContentFR = "Cette jeune fille de dix-huit ans doit désormais être une femme d’âge mûr. Est-elle vraiment revenue à Givrelac ? Il faudrait peut-être se renseigner...",
          DialogueId = 51009722,
          GUID = "7FB28E84",
          Scripts = "PlayOrStopBGM{_delay{10},PlayType{"Stop"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt01/0036_story_renweidaozu"}}",
          SpeakNpcId = 100001
        },
        [51009723] = {
          Camera = "-1245.721924,-374.627869,402.247803,-8.001631,-17.80077,20.798534,23.337744,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Encore une nuit sans repos... impossible de trouver la paix !",
          DialogueId = 51009723,
          FinalCamera = "-1026.618896,-291.636963,327.767822,-8.001973,-14.000665,19.198555,23.337744,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB28EAE",
          NextDialogue = 51009724,
          Scripts = "SEQ{\nMoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{\"NvzhuPoint_20023200\"}},\nPlayFacial{ActorId{100001},FacialId{\"Angry01\"}}\n}",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          ToFinalCameraBlendTime = 3
        },
        [51009724] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ô pauvre âme... es-tu comme moi ? À errer dans ces couloirs glacés, le regard tourné vers l’horizon, cherchant l’éclat d’une étoile née de l’amour et de l’espérance...",
          DialogueId = 51009724,
          GUID = "7FB28ED8",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009725] = {
          ContentFR = "Tu entends une voix chanter à l’angle d’une rue. Tu regardes autour de toi, mais il n’y a personne. Veux-tu continuer à chercher ?",
          DialogueId = 51009725,
          GUID = "7FB28F02"
        },
        [51009726] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Da... da da...",
          DialogueId = 51009726,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB28F2C",
          NextDialogue = 51009727,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009727] = {
          ContentFR = "Qui est là ?!",
          DialogueId = 51009727,
          GUID = "7FB28F56",
          NextDialogue = 51009728,
          SpeakNpcId = 100001
        },
        [51009728] = {
          ContentFR = "Oh, pardon... je t’ai fait peur ? Je suis là, à cinq pas devant toi. Oui, par ici.",
          DialogueId = 51009728,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28F80",
          NextDialogue = 51009729,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009729] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bonsoir à toi, âme en peine qui ne trouve pas le sommeil.",
          DialogueId = 51009729,
          GUID = "7FB28FAA",
          NextOptions = {
            [1] = 510096391,
            [2] = 510096392,
            [3] = 510096393
          },
          Scripts = "SEQ{\nMoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{\"NvzhuPoint_20023201\"}},\nTurnTo{TurnToDescription{\"100001:n(700309)\"}}\n}",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009730] = {
          ContentFR = "Non, tu ne rêves pas. C’est bien moi qui te parle.",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009731] = {
          ContentFR = "Et pourquoi faudrait-il absolument que quelqu’un soit caché ici ? Ne puis-je pas simplement... parler, moi, une humble caisse ?",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009732] = {
          ContentFR = "Désolée de te décevoir, mais je ne réalise pas de vœux. Je ne suis qu’une simple caisse ordinaire.",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais... comment une caisse peut-elle parler ?",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis-moi... qu’est-ce qui est le plus difficile, selon toi : chanter ou parler ?",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309
        },
        [51009735] = {
          ContentFR = "Chanter, je suppose.",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001
        },
        [51009736] = {
          ContentFR = "Et pourtant, il existe de petites boîtes à musique qui chantent dès qu’on tourne leur clé. Parler est bien plus simple que chanter, non ? Et moi, je suis bien plus grande et plus robuste qu’une boîte à musique.",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309
        },
        [51009737] = {
          ContentFR = "Alors pourquoi ne pourrais-je pas te parler, tout comme toi, tu me parles en ce moment ?",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          ContentFR = "Mais...",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          ContentFR = "Je sais, cela te semble étrange.",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309
        },
        [51009740] = {
          ContentFR = "Tout le monde pense qu’une caisse ne devrait pas parler — tout comme un vieux tronc d’arbre ne devrait que renvoyer l’écho de ta voix. Mais, au fond, dis-moi honnêtement... qui n’a jamais rêvé d’une caisse qui lui répondrait vraiment ?",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309
        },
        [51009741] = {
          ContentFR = "Et puis... tu ne m’as pas ouvert tout de suite. Ce qui veut dire qu’au fond de toi, tu voulais peut-être que je te parle, pas vrai ?",
          DialogueId = 51009741,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB291A2",
          NextDialogue = 51009742,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009742] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009742,
          GUID = "7FB291CC",
          NextDialogue = 51009743,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009743] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On dirait que tu commences à accepter l’idée. Alors... veux-tu bien rester un peu pour discuter ?",
          DialogueId = 51009743,
          GUID = "7FB291F6",
          NextDialogue = 51009744,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009744] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "De quoi veux-tu parler ?",
          DialogueId = 51009744,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "7FB29220",
          NextDialogue = 51009745,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009745] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hmm... que dirais-tu de l’opéra donné avant-hier au Théâtre Galea ?",
          DialogueId = 51009745,
          GUID = "7FB2924A",
          NextDialogue = 51009746,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009746] = {
          ContentFR = "Il s’appelait Putini. Tu l’as vu ? Qu’as-tu pensé de la voix de la chanteuse principale ?",
          DialogueId = 51009746,
          GUID = "7FB29274",
          NextDialogue = 51009747,
          SpeakNpcId = 700309
        },
        [51009747] = {
          ContentFR = "Tu sais, je ne peux pas aller au théâtre... je ne suis qu’une caisse, après tout.",
          DialogueId = 51009747,
          GUID = "7FB2929E",
          NextDialogue = 51009748,
          SpeakNpcId = 700309
        },
        [51009748] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Désolé|Désolée}, je ne l’ai pas vu.",
          DialogueId = 51009748,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB292C8",
          NextDialogue = 51009749,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas grave. Personne ne t’en voudra. Mais si un jour tu en as l’occasion, va le voir — c’est une œuvre magnifique. L’héroïne, Putini, est belle, généreuse... et surtout, elle a le courage de poursuivre sa liberté.",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309
        },
        [51009750] = {
          ContentFR = "Moi aussi, j’aimerais être comme elle. Mais je ne suis qu’une simple caisse.",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309
        },
        [51009751] = {
          ContentFR = "Alors j’ai pris une décision.",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309
        },
        [51009752] = {
          ContentFR = "Quelle décision ?",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je veux partir en mer. Qui a décrété qu’une caisse devait rester dans un coin de rue ? Elle peut devenir un bateau, voguer au gré des flots... Je veux sentir le vent marin, chargé de sel et de sable.",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          ContentFR = "Mais quitter cet endroit signifie aussi tout perdre.",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309
        },
        [51009755] = {
          ContentFR = "Se libérer de sa cage, c’est aussi perdre son abri. Obtenir la liberté, c’est aussi affronter l’inconnu.",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, mon {性别:ami|amie}... dis-moi. Que devrais-je faire ?",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309
        },
        [51009757] = {
          ContentFR = "... Tu as raison.",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309
        },
        [51009758] = {
          ContentFR = "Merci d’avoir parlé avec une simple caisse, toi, l’âme bienveillante. L’aube approche... et avec elle, la magie qui anime ce vieux bois disparaît.",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309
        },
        [51009759] = {
          ContentFR = "Je te souhaite, non pas des nuits d’insomnie moins pénibles... mais que toutes tes nuits soient peuplées de doux rêves.",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309
        },
        [51009760] = {
          ContentFR = "Tu entends un léger frémissement — comme une petite fée qui s’envole de la chambre d’un enfant avant le lever du jour. Quand tu reprends tes esprits, Mademoiselle Caisse a disparu.",
          DialogueId = 51009760,
          GUID = "7FB294C0"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Cette voix dans la caisse... Je ne sais pas pourquoi, mais j’ai fini par me laisser entraîner dans sa conversation.",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est sans doute un enfant du quartier qui s’amusait. Je ne peux pas laisser ça sans suite — je devrais poser quelques questions autour de moi.",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001
        },
        [51009763] = {
          ContentFR = "Excuse-moi... qui es-tu ? Je t’ai vu tourner dans le coin depuis un moment.",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009764] = {
          ContentFR = "Tu cherches à passer une mission ? Suivi, collecte, livraison... j’accepte toutes sortes de missions — tant qu’elles sont légales.",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009765] = {
          ContentFR = "Une mission ?",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001
        },
        [51009766] = {
          ContentFR = "Hein ? Tu n’es pas là pour m’en confier une ?",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009767] = {
          ContentFR = "Bon... on dirait que la renommée de « Giselle la Chasseuse de Phoxène » n’est pas aussi éclatante que Camilla le prétendait.",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302
        },
        [51009768] = {
          ContentFR = "Giselle la Chasseuse de Phoxène... Oui, ce nom me dit quelque chose.",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001
        },
        [51009769] = {
          ContentFR = "Pas besoin de me flatter pour me faire plaisir.",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302
        },
        [51009770] = {
          ContentFR = "Non... je le pense vraiment.",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001
        },
        [51009771] = {
          ContentFR = "Tu racontes à Giselle l’histoire de la caisse qui parlait derrière sa maison.",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772
        },
        [51009772] = {
          ContentFR = "Donc... une caisse derrière chez moi t’a parlé, et t’a conseillé d’aller à l’opéra. Très bien, j’ai compris.",
          DialogueId = 51009772,
          GUID = "7FB296B8",
          NextDialogue = 51009773,
          SpeakNpcId = 700302
        },
        [51009773] = {
          ContentFR = "...",
          DialogueId = 51009773,
          GUID = "7FB296E2",
          NextDialogue = 51009774,
          SpeakNpcId = 100001
        },
        [51009774] = {
          ContentFR = "Ta réaction est... pas exactement celle à laquelle je m’attendais.",
          DialogueId = 51009774,
          GUID = "7FB2970C",
          NextDialogue = 51009775,
          SpeakNpcId = 100001
        },
        [51009775] = {
          ContentFR = "Ah bon ? C’est sûrement ma nature. Qu’il s’agisse d’un enfant caché dans une caisse ou d’une caisse qui parle vraiment, pour moi, les deux sont plausibles.",
          DialogueId = 51009775,
          GUID = "7FB29736",
          NextDialogue = 51009776,
          SpeakNpcId = 700302
        },
        [51009776] = {
          ContentFR = "Merci de m’avoir raconté ça. Je poserai quelques questions dans le voisinage.",
          DialogueId = 51009776,
          GUID = "7FB29760",
          NextDialogue = 51009777,
          SpeakNpcId = 700302
        },
        [51009777] = {
          ContentFR = "Oh, au fait... je crois savoir qui tu es. Tu es bien {nickname}, non ? La nouvelle étoile montante parmi les Chasseurs de Phoxène.",
          DialogueId = 51009777,
          GUID = "7FB2978A",
          NextOptions = {
            [1] = 510096871,
            [2] = 510096872,
            [3] = 510096873
          },
          SpeakNpcId = 700302
        },
        [51009778] = {
          ContentFR = "Je m’en doutais. Ravie de voir que mon instinct ne me trompe pas encore.",
          DialogueId = 51009778,
          GUID = "7FB297B4",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009779] = {
          ContentFR = "Détends-toi. Des nouveaux talents comme toi deviennent célèbres très vite.",
          DialogueId = 51009779,
          GUID = "7FB297DE",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009780] = {
          ContentFR = "Pas très subtil... mais au moins, c’est un surnom qui marque les esprits.",
          DialogueId = 51009780,
          GUID = "7FB29808",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009781] = {
          ContentFR = "Puisque tu sembles avoir un peu de temps... pourrais-tu m’aider ?",
          DialogueId = 51009781,
          GUID = "7FB29832",
          NextDialogue = 51009782,
          SpeakNpcId = 700302
        },
        [51009782] = {
          ContentFR = "J’ai besoin de certaines herbes. Je vais te donner une liste. Quand tu les auras, apporte-les simplement aux Asphodèles. Camilla t’y remettra la récompense.",
          DialogueId = 51009782,
          GUID = "7FB2985C",
          NextDialogue = 51009783,
          SpeakNpcId = 700302
        },
        [51009783] = {
          ContentFR = "Tu ne veux pas que je te les livre ici ?",
          DialogueId = 51009783,
          GUID = "7FB29886",
          NextDialogue = 51009784,
          SpeakNpcId = 100001
        },
        [51009784] = {
          ContentFR = "Non, pas besoin. Les Asphodèles suffiront.",
          DialogueId = 51009784,
          GUID = "7FB298B0",
          SpeakNpcId = 700302
        },
        [51009785] = {
          Camera = "777.87793,290.900391,409.416016,0.000004,-23.199877,-161.79744,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ça devrait suffire.",
          DialogueId = 51009785,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB298DA",
          NextDialogue = 51009786,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51009786] = {
          Camera = "104.59375,60.244141,114.90918,0.000007,-13.199702,-164.194138,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ces herbes... elles sont toutes très communes. Si Giselle est vraiment une Chasseuse de Phoxène, pourquoi m’avoir demandé de les ramasser à sa place ?",
          DialogueId = 51009786,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29904",
          NextDialogue = 51009787,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009787] = {
          ContentFR = "Maintenant que j’y repense, son attitude aussi était étrange...",
          DialogueId = 51009787,
          GUID = "7FB2992E",
          NextDialogue = 51009788,
          SpeakNpcId = 100001
        },
        [51009788] = {
          ContentFR = "Je ferais mieux d’apporter tout ça aux Asphodèles, et d’en profiter pour interroger Camilla.",
          DialogueId = 51009788,
          GUID = "7FB29958",
          SpeakNpcId = 100001
        },
        [51009789] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Eh bien, quelle surprise. Tu viens pour un verre ou c’est le travail qui t’amène ?",
          DialogueId = 51009789,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29982",
          NextDialogue = 51009790,
          SpeakNpcId = 200003
        },
        [51009790] = {
          ContentFR = "Je suis juste venu livrer ça. C’est Giselle qui m’a demandé d’apporter ces herbes ici.",
          DialogueId = 51009790,
          GUID = "7FB299AC",
          NextDialogue = 51009791,
          SpeakNpcId = 100001
        },
        [51009791] = {
          ContentFR = "Giselle ? Oui, elle est passée tout à l’heure — elle m’a même laissé un colis pour toi. Mais... quelque chose ne tourne pas rond. Qu’est-ce qu’elle t’avait demandé exactement ?",
          DialogueId = 51009791,
          GUID = "7FB299D6",
          NextDialogue = 51009792,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009792] = {
          ContentFR = "Tu expliques à Camilla que Giselle t’a chargé de cueillir des herbes.",
          DialogueId = 51009792,
          GUID = "7FB29A00",
          NextDialogue = 51009793
        },
        [51009793] = {
          ContentFR = "...",
          DialogueId = 51009793,
          GUID = "7FB29A2A",
          NextDialogue = 51009794,
          SpeakNpcId = 200003
        },
        [51009794] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il y a un problème ?",
          DialogueId = 51009794,
          GUID = "7FB29A54",
          NextDialogue = 51009795,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009795] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas vraiment un problème... mais j’ai du mal à comprendre pourquoi elle t’aurait confié ça.",
          DialogueId = 51009795,
          GUID = "7FB29A7E",
          NextDialogue = 51009796,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009796] = {
          ContentFR = "Ces plantes sont des remèdes de base contre le rhume. Elle aurait pu les cueillir elle-même en moins d’une matinée — ce n’est pas vraiment le genre de travail pour lequel on engage quelqu’un.",
          DialogueId = 51009796,
          GUID = "7FB29AA8",
          NextDialogue = 51009797,
          SpeakNpcId = 200003
        },
        [51009797] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est vrai, elle m’a dit elle-même qu’elle était une Chasseuse de Phoxène.",
          DialogueId = 51009797,
          GUID = "7FB29AD2",
          NextDialogue = 51009798,
          SpeakNpcId = 100001
        },
        [51009798] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Elle n’est pas une simple chasseuse : elle a même été capitaine chez les Veilleurs, avant de claquer la porte il y a seize ans, après un sale désaccord avec sa hiérarchie. Depuis, elle opère en solo. Elle est rapide, efficace, et suffisamment respectée pour ne pas avoir besoin d’aide sur une corvée pareille.",
          DialogueId = 51009798,
          GUID = "7FB29AFC",
          NextDialogue = 51009799,
          SpeakNpcId = 200003
        },
        [51009799] = {
          ContentFR = "Mais bref... inutile de se torturer l’esprit. La mission est en règle, et elle t’a bel et bien laissé quelque chose.",
          DialogueId = 51009799,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29B26",
          NextDialogue = 51009800,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009800] = {
          ContentFR = "Tiens, prends ça.",
          DialogueId = 51009800,
          GUID = "7FB29B50",
          NextDialogue = 51009801,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Give"
          }
        },
        [51009801] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est... la récompense ? Et une lettre ?",
          DialogueId = 51009801,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29B7A",
          SpeakNpcId = 100001
        },
        [51009802] = {
          ContentFR = "« Bonjour, {性别:mon cher ami|ma chère amie},\nMerci d’avoir tenu compagnie à une vieille caisse un peu folle jusqu’au bout de la nuit... et de m’avoir donné le courage de prendre la mer.\nPeut-être que ce que je fais n’est pas juste envers mes amies... ou mon professeur. Mais je suis sûre qu’elles comprendront. Le monde est vaste. Je les reverrai quelque part, sur une autre scène.\n\nEt s’il te plaît, ne blâme pas Giselle. C’était mon choix. J’espère seulement que mon égoïsme n’aura causé de tort à personne.\n\nAh... je me rends compte que je ne t’ai jamais dit mon nom.\nMais ce n’est plus important maintenant — je n’en aurai plus besoin. Voyons voir...\nSi un jour tu rencontres une fille qui s’appelle Putini... j’espère que tu me reconnaîtras. Moi, je te reconnaîtrai. »",
          DialogueId = 51009802,
          Duration = 10,
          GUID = "7FB29BA4"
        },
        [51009803] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On dirait que tu t’es fait une amie pour le moins... singulière. Je parie que l’histoire derrière tout ça vaut son pesant d’or.",
          DialogueId = 51009803,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29BCE",
          NextDialogue = 51009804,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009804] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas vraiment... Honnêtement, je ne sais même pas exactement ce qui s’est passé.",
          DialogueId = 51009804,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB29BF8",
          NextDialogue = 51009805,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200003:Talk02_End",
            [2] = "100001:ScratchHead_Start"
          }
        },
        [51009805] = {
          ContentFR = "Tu racontes à Camilla tout ce qui s’est passé ces deux derniers jours.",
          DialogueId = 51009805,
          GUID = "7FB29C22",
          IsBlack = 1,
          NextDialogue = 51009806
        },
        [51009806] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Putini...",
          DialogueId = 51009806,
          GUID = "7FB29C4C",
          NextDialogue = 51009807,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009807] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce nom te dit quelque chose ?",
          DialogueId = 51009807,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29C76",
          NextDialogue = 51009808,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ScratchHead_End"
          }
        },
        [51009808] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pris isolément, ce nom ne me dit rien... mais cette voix dans la caisse, elle a bien parlé d’un opéra, pas vrai ?",
          DialogueId = 51009808,
          GUID = "7FB29CA0",
          NextDialogue = 51009809,
          SpeakNpcId = 200003
        },
        [51009809] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Elle m’a même demandé ce que je pensais du rôle principal.",
          DialogueId = 51009809,
          GUID = "7FB29CCA",
          NextDialogue = 51009810,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009810] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Curieux... J’ai justement entendu quelques rumeurs à ce sujet.",
          DialogueId = 51009810,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29CF4",
          NextDialogue = 51009811,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009811] = {
          ContentFR = "Un client m’a confié qu’il avait assisté à la répétition générale de Putini. Et d’après lui, l’actrice principale n’était pas la même que celle qui est montée sur scène le soir de la première.",
          DialogueId = 51009811,
          GUID = "7FB29D1E",
          NextDialogue = 51009812,
          SpeakNpcId = 200003
        },
        [51009812] = {
          ContentFR = "D’après lui, l’interprète à la répétition était plus jeune — et très talentueuse, mais le soir de la première, c’est l’ancienne vedette qui est montée sur scène.",
          DialogueId = 51009812,
          GUID = "7FB29D48",
          NextDialogue = 51009813,
          SpeakNpcId = 200003
        },
        [51009813] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu veux dire que...",
          DialogueId = 51009813,
          GUID = "7FB29D72",
          NextDialogue = 51009814,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009814] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce ne sont que des bruits de comptoir, rien qui permette d’établir un lien certain entre les deux affaires.",
          DialogueId = 51009814,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29D9C",
          NextDialogue = 51009815,
          SpeakNpcId = 200003
        },
        [51009815] = {
          ContentFR = "Mais... si tu as un peu de temps devant toi, ça vaudrait peut-être le coup d’aller gratter plus loin. Moi aussi, j’aimerais bien connaître le fin mot de l’histoire.",
          DialogueId = 51009815,
          GUID = "7FB29DC6",
          NextDialogue = 51009816,
          SpeakNpcId = 200003
        },
        [51009816] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Camilla n’en sait pas plus que moi... Mais une chose est sûre : Giselle a eu un comportement étrange.",
          DialogueId = 51009816,
          GUID = "7FB29DF0",
          NextDialogue = 51009817,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200003:Talk02_End"
          }
        },
        [51009817] = {
          ContentFR = "La fille de la caisse... serait-elle l’actrice qui n’a jamais pu monter sur scène ? Et si oui, Giselle était-elle au courant depuis le début ?",
          DialogueId = 51009817,
          GUID = "7FB29E1A",
          NextDialogue = 51009818,
          SpeakNpcId = 100001
        },
        [51009818] = {
          ContentFR = "Je ne trouverai aucune réponse en restant ici. Autant aller interroger Giselle directement.",
          DialogueId = 51009818,
          GUID = "7FB29E44",
          SpeakNpcId = 100001
        },
        [51009819] = {
          Camera = "-459.554443,-130.776611,223.984375,0.000025,-13.400024,3.198126,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je l’avais dit ! Je l’avais prévenu !",
          DialogueId = 51009819,
          FacialId = {
            [1] = "700307:CM_Angry01"
          },
          GUID = "7FB29E6E",
          NextDialogue = 51009820,
          SpeakNpcId = 700307,
          TalkActionId = {
            [1] = "700307:Angry01_Start"
          }
        },
        [51009820] = {
          ContentFR = "On n’aurait jamais dû engager cette femme louche comme préceptrice ! On n’aurait jamais dû laisser Rosalind suivre ces fichus cours de chant !",
          DialogueId = 51009820,
          GUID = "7FB29E98",
          NextDialogue = 51009821,
          SpeakNpcId = 700307
        },
        [51009821] = {
          ContentFR = "C’est toi qui disais qu’il lui fallait une activité pour qu’elle arrête de traîner dehors toute la journée !",
          DialogueId = 51009821,
          FacialId = {
            [1] = "700308:CM_Sad01"
          },
          GUID = "7FB29EC2",
          NextDialogue = 51009822,
          SpeakNpcId = 700308,
          TalkActionId = {
            [1] = "700308:Explain01_Start"
          }
        },
        [51009822] = {
          ContentFR = "Oui, je voulais qu’elle reste tranquille à la maison — pas qu’elle recommence à courir partout jusqu’à attirer l’attention de ravisseurs !",
          DialogueId = 51009822,
          GUID = "7FB29EEC",
          NextDialogue = 51009823,
          SpeakNpcId = 700307,
          TalkActionId = {
            [1] = "700307:Angry01_End",
            [2] = "700308:Explain01_End"
          }
        },
        [51009823] = {
          ContentFR = "Et vous, bande d’incapables ! Vous appelez ça des Veilleurs ? On avait enfin une piste, et parce que vous êtes trop lents, les kidnappeurs se sont enfuis !",
          DialogueId = 51009823,
          GUID = "7FB29F16",
          NextDialogue = 51009824,
          Scripts = "PARA{\nTurnTo{TurnToDescription{\"700307:n(700313)\"}},\nTurnTo{TurnToDescription{\"700308:n(700313)\"}}\n}",
          SpeakNpcId = 700307
        },
        [51009824] = {
          ContentFR = "...",
          DialogueId = 51009824,
          GUID = "7FB29F40",
          NextDialogue = 51009825,
          SpeakNpcId = 700313
        },
        [51009825] = {
          ContentFR = "Pff... pourquoi est-ce que je perds mon temps à crier sur des imbéciles pareils ! Je vais retrouver ma fille moi-même !",
          DialogueId = 51009825,
          GUID = "7FB29F6A",
          NextDialogue = 51009826,
          Scripts = "PARA{\nLookAt{LookAtDescription{\"700307:n(700307)\"}},\nLookAt{LookAtDescription{\"700308:n(700308)\"}},\nMoveTo{ActorId{700307},MoveSpeed{150},TargetPoint{\"MagnusMPoint_20023205\"}},\nMoveTo{ActorId{700308},MoveSpeed{150},TargetPoint{\"MagnusFPoint_20023205\"}}\n}",
          SpeakNpcId = 700307
        },
        [51009826] = {
          Camera = "-238.418213,-514.537842,220.403809,0.000037,-12.999988,72.598557,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Ouf. Enfin parti.",
          DialogueId = 51009826,
          GUID = "7FB29F94",
          NextDialogue = 51009827,
          SpeakNpcId = 700313
        },
        [51009827] = {
          Camera = "77.355469,-517.516235,186.296875,0.000047,-11.199768,98.997734,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Veuillez rester à l’écart, s’il vous plaît. Cet endroit est interdit au public.",
          DialogueId = 51009827,
          GUID = "7FB29FBE",
          NextDialogue = 51009828,
          Scripts = "SEQ{\nMoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{\"NvzhuPoint_20023205\"}},\nTurnTo{TurnToDescription{\"100001:n(700313)\"}}\n}",
          SpeakNpcId = 700313
        },
        [51009828] = {
          Camera = "-445.371338,-206.447021,167.490234,0.00006,-10.999575,13.197603,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Désolé|Désolée}, j’ai entendu des cris... Que se passe-t-il ici ?",
          DialogueId = 51009828,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB29FE8",
          NextDialogue = 51009829,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009829] = {
          ContentFR = "Nous avons reçu un signalement : une personne aurait été kidnappée et retenue ici. Mais quand nous sommes arrivés, les lieux étaient déjà vides.",
          DialogueId = 51009829,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2A012",
          NextDialogue = 51009830,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009830] = {
          ContentFR = "Cette maison est désormais sous scellés. Si tu es simplement venu par curiosité, je te demanderai de ne pas t’approcher davantage.",
          DialogueId = 51009830,
          GUID = "7FB2A03C",
          NextDialogue = 51009831,
          SpeakNpcId = 700313
        },
        [51009831] = {
          ContentFR = "D’accord... Et ces deux personnes, c’était qui ?",
          DialogueId = 51009831,
          GUID = "7FB2A066",
          NextDialogue = 51009832,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009832] = {
          ContentFR = "Le Comte Magnus et son épouse — les parents de la victime. Je comprends qu’ils soient inquiets, mais... disons qu’ils sont fidèles à leur réputation.",
          DialogueId = 51009832,
          GUID = "7FB2A090",
          NextDialogue = 51009833,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009833] = {
          ContentFR = "On raconte qu’ils étaient très autoritaires avec leur fille. Peut-être que Mademoiselle Rosalind a fui pour échapper à leur emprise...",
          DialogueId = 51009833,
          GUID = "7FB2A0BA",
          NextDialogue = 51009834,
          SpeakNpcId = 700313
        },
        [51009834] = {
          ContentFR = "Hum hum. Assez bavardé. Si tu obtiens la moindre information, transmets-la aux Veilleurs.",
          DialogueId = 51009834,
          GUID = "7FB2A0E4",
          NextDialogue = 51009835,
          SpeakNpcId = 700313
        },
        [51009835] = {
          Camera = "-99.088623,-74.42334,133.572266,0.000056,-4.199521,-40.602531,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Giselle... et Mademoiselle Caisse... ne sont plus là.",
          DialogueId = 51009835,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2A10E",
          NextDialogue = 51009836,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009836] = {
          ContentFR = "Un enlèvement ? Est-ce que cela pourrait avoir un lien avec la lettre laissée à la taverne ?",
          DialogueId = 51009836,
          GUID = "7FB2A138",
          NextDialogue = 51009837,
          SpeakNpcId = 100001
        },
        [51009837] = {
          ContentFR = "Je n’ai aucune piste pour l’instant... Autant rester vigilant et voir ce qui se passera.",
          DialogueId = 51009837,
          GUID = "7FB2A162",
          SpeakNpcId = 100001
        },
        [51009838] = {
          ContentFR = "Da... da da...",
          DialogueId = 51009838,
          GUID = "7FB2A163",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009850] = {
          Camera = "-1567.962891,-185.177612,2329.811035,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          ContentFR = "Ces derniers jours à Givrelac ont été bien mouvementés... et maintenant, une affaire d’enlèvement est venue s’ajouter au chaos.",
          DialogueId = 51009850,
          FinalCamera = "-1614.97168,-559.773193,2467.275635,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A384",
          NextDialogue = 51009851,
          Scripts = "SetTag{Tag{"Huozai04Tag"},Value{"Value_1"}}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 5
        },
        [51009851] = {
          Camera = "389.291016,-7961.245117,-744.026855,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          ContentFR = "En y repensant bien, <H>plusieurs événements</> semblent liés d’une manière ou d’une autre.",
          DialogueId = 51009851,
          FinalCamera = "712.783569,-8322.950195,-679.47168,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3AE",
          NextDialogue = 51009852,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 5
        },
        [51009852] = {
          Camera = "1489.815308,3777.302246,3313.351074,0.000015,-35.199669,-107.997414,20.0,100000.0,false,Manual,2.8",
          ContentFR = "Mieux vaut faire le point... et essayer d’assembler les morceaux.",
          DialogueId = 51009852,
          FinalCamera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3D8",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 5
        },
        [51009853] = {
          Camera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          ContentFR = "Il y avait plus dans cette affaire que ce que l’on croyait. Et Violetta... elle connaît sûrement la vérité. Giselle a enlevé son élève pour la forcer à se montrer.",
          DialogueId = 51009853,
          GUID = "7FB2A402",
          NextDialogue = 51009854,
          SpeakNpcId = 100001
        },
        [51009854] = {
          ContentFR = "Si j’ai raison, elles doivent être ensemble en ce moment.",
          DialogueId = 51009854,
          GUID = "7FB2A42C",
          NextDialogue = 51009855,
          SpeakNpcId = 100001
        },
        [51009855] = {
          ContentFR = "Je dois me rendre sur place au plus vite... en espérant qu’il ne soit pas trop tard.",
          DialogueId = 51009855,
          GUID = "7FB2A456",
          SpeakNpcId = 100001
        },
        [51009856] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Tiens, t’es à l’heure finalement.",
          DialogueId = 51009856,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2A480",
          NextDialogue = 51009857,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009857] = {
          ContentFR = "...",
          DialogueId = 51009857,
          GUID = "7FB2A4AA",
          NextDialogue = 51009858,
          SpeakNpcId = 700300
        },
        [51009858] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi, tu comptes garder le silence ? Ce n’est pas un tribunal ici. Si tu attends qu’on te lise tes droits, tu risques d’attendre longtemps.",
          DialogueId = 51009858,
          GUID = "7FB2A4D4",
          NextDialogue = 51009859,
          SpeakNpcId = 700302
        },
        [51009859] = {
          ContentFR = "Et qu’est-ce que tu veux que je dise ? Vas-y, je t’écoute. Après un coup aussi bas, quelle réponse attends-tu exactement ?",
          DialogueId = 51009859,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB2A4FE",
          NextDialogue = 51009860,
          SpeakNpcId = 700300
        },
        [51009860] = {
          Camera = "148.300781,-316.230469,157.037598,0.999999,-5.400179,115.588638,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu te fous de moi ? Ou tu crois vraiment que tes crimes peuvent se maquiller aussi facilement que ton visage ? Tu penses qu’un peu de poudre peut tout effacer ?",
          DialogueId = 51009860,
          GUID = "7FB2A528",
          NextDialogue = 51009861,
          SpeakNpcId = 700302
        },
        [51009861] = {
          ContentFR = "Très bien... Laisse-moi rafraîchir ta mémoire.",
          DialogueId = 51009861,
          GUID = "7FB2A552",
          NextDialogue = 51009862,
          SpeakNpcId = 700302
        },
        [51009862] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Il y a seize ans, à Givrelac, un jeune homme nommé Sig a enlevé Enola Ruthford, la fille de Fabrice Ruthford, responsable de la Fosse de Glevum.",
          DialogueId = 51009862,
          GUID = "7FB2A57C",
          NextDialogue = 51009863,
          SpeakNpcId = 700302
        },
        [51009863] = {
          ContentFR = "Lorsqu’il a été acculé par les Veilleurs, Sig a résisté... et a accidentellement mis le feu à la maison. Enola est morte dans l’incendie, et Sig a été condamné à mort.",
          DialogueId = 51009863,
          GUID = "7FB2A5A6",
          NextDialogue = 51009864,
          SpeakNpcId = 700302
        },
        [51009864] = {
          Camera = "-314.688477,142.042969,142.037598,1.000012,-0.599793,-21.008369,40.559872,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, j’ai entendu parler de cette tragédie. Une histoire lamentable... que cette pauvre fille repose en paix.",
          DialogueId = 51009864,
          GUID = "7FB2A5D0",
          NextDialogue = 51009865,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009865] = {
          ContentFR = "Mais je ne suis arrivée à Givrelac que bien plus tard. En quoi cela me concerne-t-il ?",
          DialogueId = 51009865,
          GUID = "7FB2A5FA",
          NextDialogue = 51009866,
          SpeakNpcId = 700300
        },
        [51009866] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parce qu’il y a eu une survivante.",
          DialogueId = 51009866,
          GUID = "7FB2A624",
          NextDialogue = 51009867,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009867] = {
          ContentFR = "Un témoin affirme qu’il y avait trois personnes dans la maison ce soir-là : Sig, Enola... et la sœur de Sig, Violette, une fille du même âge qu’Enola.",
          DialogueId = 51009867,
          GUID = "7FB2A64E",
          NextDialogue = 51009868,
          SpeakNpcId = 700302
        },
        [51009868] = {
          ContentFR = "Dans le chaos, ce témoin a sorti une jeune fille des flammes — une fille qu’il croyait être Violette. Mais l’était-elle vraiment ?",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302
        },
        [51009869] = {
          ContentFR = "Arrête-moi si je me trompe : tu as tué Violette ce soir-là... puis tu as pris son nom pour tromper Donat et t’échapper de Givrelac, n’est-ce pas, Enola Ruthford ?",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Ah ! Intéressant scénario. Un polar de ce genre, c’est plutôt rare.",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          ContentFR = "Continue, j’aime bien les histoires.",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai passé des années à enquêter sur cette affaire. Un corps méconnaissable... une seule survivante... trop de coïncidences.",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          ContentFR = "Toutes les pièces étaient là, mais il manquait le fil conducteur.",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302
        },
        [51009874] = {
          ContentFR = "Si je n’avais pas été assignée à la protection de Fabrice Ruthford à l’époque — si je n’avais pas entendu sa fille chanter —",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "je n’aurais jamais fait le lien. Cette voix... je la reconnaîtrais entre mille. Voilà comment j’ai su qui tu étais vraiment, « Violetta aux mille visages ».",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302
        },
        [51009876] = {
          ContentFR = "J’ai même trouvé des moyens d’étudier tes habitudes... par exemple en envoyant quelqu’un t’apporter de fausses lettres pour t’observer.",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          ContentFR = "Donc ce soldat, c’était toi qui l’avais envoyé.",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          ContentFR = "Pas exactement. C’était vraiment un de tes admirateurs. Je n’ai fait que le pousser un peu dans cette direction. Grâce à lui, j’ai eu la confirmation.",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais il reste une chose que je ne comprends pas.",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302
        },
        [51009880] = {
          ContentFR = "Changer d’identité avec Violette n’aurait pas été possible sans leur coopération. Comment les as-tu convaincus ?",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je croyais que tu allais poser une question difficile... La réponse est simple.",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          ContentFR = "J’étais la fille de Fabrice Ruthford. Et tu sais ce que cela signifie de s’opposer à lui.",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          ContentFR = "Le pauvre Sig savait déjà qu’il n’en sortirait pas vivant... et connaissant mon père, Violette non plus n’avait aucune chance.",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300
        },
        [51009884] = {
          ContentFR = "Je leur ai proposé une solution : après avoir reçu la rançon, ils n’avaient qu’à gagner du temps, créer la confusion, et donner à Violette une chance de s’échapper.",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300
        },
        [51009885] = {
          ContentFR = "Pathétique, non ? Dans sa panique, il a affronté les Veilleurs seul, espérant qu’une fillette malade s’échapperait d’une maison en feu...",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          ContentFR = "J’ai saisi ma chance. J’ai tué cette pauvre enfant qui se trouvait sur mon chemin. J’ai pris son nom. J’ai laissé derrière moi cette maison pourrie... et mon père. J’ai laissé derrière moi tout ce qui m’empêchait de monter sur scène.",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009887,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302
        },
        [51009888] = {
          ContentFR = "Qu’y a-t-il, Giselle ? Tu poursuis cette vérité depuis des années... et maintenant que tu l’as, tu ne sembles pas ravie.",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300
        },
        [51009889] = {
          ContentFR = "T’es complètement folle... Tout ça, juste pour les projecteurs ?! Tu as tué deux personnes innocentes !",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          ContentFR = "Alors, que vas-tu faire ? Révéler mes crimes au grand jour pour ruiner ma réputation ? Ou bien... venger leur mort ici et maintenant ?",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          ContentFR = "... Je voulais seulement révéler la vérité... et te livrer aux Veilleurs.",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302
        },
        [51009892] = {
          ContentFR = "Giselle dégaine un poignard. La tension est palpable. Tu entends presque le cuir craquer sous la force de sa poigne, et le grincement de ses dents serrées.",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          ContentFR = "Si personne ne l’arrête, cette lame mettra bientôt fin à la plus belle voix de Givrelac... Quoi qu’il en soit, tu ne peux pas rester là à regarder quelqu’un commettre un meurtre.",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1
        },
        [51009894] = {
          ContentFR = "{nickname}... ? Qu’est-ce que tu fais ici ?",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300
        },
        [51009895] = {
          ContentFR = "Écarte-toi. Je ne laisserai pas une ordure comme elle vivre une minute de plus !",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          ContentFR = "Elle a complètement perdu les pédales... Je dois trouver un moyen de la calmer.",
          DialogueId = 51009896,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2AB10",
          SpeakNpcId = 100001
        },
        [51009897] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Calme-toi, Giselle. Il y a peut-être plus dans cette histoire que ce que tu crois.",
          DialogueId = 51009897,
          GUID = "7FB2AB3A",
          NextDialogue = 51009898,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009898] = {
          ContentFR = "Tu as entendu ce qu’elle vient d’avouer ?! Tu crois vraiment que je peux rester calme après ça ?!",
          DialogueId = 51009898,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2AB64",
          NextDialogue = 51009899,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009899] = {
          ContentFR = "Elle ne s’échappera pas, pas avec nous deux ici. Alors souffle un bon coup... et laisse-moi lui poser quelques questions.",
          DialogueId = 51009899,
          GUID = "7FB2AB8E",
          NextDialogue = 51009900,
          SpeakNpcId = 100001
        },
        [51009900] = {
          Camera = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009900,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2ABB8",
          NextDialogue = 51009901,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009901] = {
          ContentFR = "Très bien. Vas-y, pose-les.",
          DialogueId = 51009901,
          GUID = "7FB2ABE2",
          NextDialogue = 51009902,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk03_Start",
            [2] = "100001:Talk02R_End"
          },
          TurnTo = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          }
        },
        [51009902] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avant toute chose... Madame Violetta, est-ce que cet objet te dit quelque chose ?",
          DialogueId = 51009902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2AC0C",
          NextDialogue = 51009903,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009903] = {
          ContentFR = "C’est...",
          DialogueId = 51009903,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2AC36",
          NextDialogue = 51009904,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009904] = {
          ContentFR = "Violetta lève instinctivement la main vers l’arrière de sa tête. Ses doigts frôlent une texture familière... puis elle se fige, comme frappée par la réalité.",
          DialogueId = 51009904,
          GUID = "7FB2AC60",
          NextDialogue = 51009905,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt01/0036_story_renweidaozu"}}"
        },
        [51009905] = {
          ContentFR = "Vu ta réaction, je ne me trompais pas... C’est toi qui as déposé ce ruban sur la tombe de Sig, n’est-ce pas ?",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001
        },
        [51009906] = {
          ContentFR = "Tu m’avais dit qu’il appartenait à une amie très chère, et que si tu avais choisi de monter sur scène, c’était pour accomplir son rêve.",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          ContentFR = "Tu es vraiment {性别:un idiot naïf|une idiote naïve}. Je n’aurais jamais cru que tu pourrais gober une histoire aussi mielleuse.",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peut-être bien. C’est pour ça que je suis allé demander la vérité à Donat — en lui empruntant ce ruban.",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          ContentFR = "Il m’a parlé de Violette. Il a dit que c’était une fille incroyablement talentueuse. Sans la pauvreté ni la maladie, elle serait sans doute devenue une grande dramaturge.",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001
        },
        [51009910] = {
          ContentFR = "Le destin ne lui a pas souri, mais elle n’a jamais abandonné. Même clouée au lit, elle a continué à poursuivre son rêve, à sa façon.",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001
        },
        [51009911] = {
          ContentFR = "Elle voulait que la plus grande comédienne du monde joue son œuvre, et que l’histoire qu’elle avait écrite, la dernière et la plus belle, fasse le tour de tout Atlasia.",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001
        },
        [51009912] = {
          ContentFR = "Cette œuvre, c’était—",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Putini. Une pièce en trois actes. Elle a ensuite été adaptée en opéra.",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Exactement. Tu comprends maintenant que mentir davantage ne ferait qu’aggraver ta situation. Alors...",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu as raison... toute pièce mérite une fin.",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Vraiment ? C’est le moment que tu choisis pour citer un polar ?",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          ContentFR = "Si tous les spectateurs étaient aussi perspicaces que toi, les dramaturges n’auraient plus besoin de se casser la tête à rendre leurs intrigues plus simples.",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qu’est-ce que vous racontez tous les deux ? Que signifie tout ça ?",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est très simple, Giselle. Si Violetta avait vraiment considéré Violette comme un simple outil à jeter, pourquoi aurait-elle choisi un nom si proche du sien ?",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Laisse-moi te raconter ce que je crois : il y a seize ans, Sig a enlevé Enola Ruthford — celle qui se fait appeler aujourd’hui Violetta — pour réunir de quoi soigner sa sœur.",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          ContentFR = "Pendant sa captivité, Enola a rencontré Violette, malade et alitée. Et pendant ce court laps de temps, elles sont devenues amies.",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001
        },
        [51009922] = {
          ContentFR = "Mais leur bonheur n’a pas duré...",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001
        },
        [51009923] = {
          ContentFR = "Violette savait que ses jours étaient comptés. Elle ne voulait pas que son frère s’enfonce plus profondément dans l’erreur. Alors elle a écrit à Donat, l’ami de Sig, pour lui demander d’intervenir.",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001
        }
      }
    end
  },
  {
    MinKey = 51009924,
    MaxKey = 51010123,
    Loader = function()
      return {
        [51009924] = {
          ContentFR = "Comme elle l’espérait, Donat a fini par venir te trouver, Giselle, et t’a dénoncé l’enlèvement d’Enola. Mais à ce moment-là, je suppose que Violette était déjà...",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah... ironique, n’est-ce pas ? J’étais censée être une otage, et pourtant... ce furent les jours les plus heureux de ma vie.",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          ContentFR = "Sig m’avait attachée dans une pièce, mais il n’avait aucune intention de me faire du mal. Il ne faisait que marcher nerveusement de long en large.",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300
        },
        [51009927] = {
          ContentFR = "Je savais qu’il y avait une autre personne dans la maison — une jeune fille. Je l’entendais fredonner doucement, les jours où elle se sentait bien...",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300
        },
        [51009928] = {
          ContentFR = "Peut-être a-t-il compris qu’il ne pouvait pas s’occuper de deux personnes à la fois. Quelques jours plus tard, il m’a détachée et m’a laissée me déplacer librement au rez-de-chaussée.",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chaque fois qu’il sortait, je montais discrètement voir Violette à l’étage. Elle me lisait ses histoires, et moi, je les jouais — je leur donnais vie.",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300
        },
        [51009930] = {
          ContentFR = "« Mon bien-aimé, ne pleure pas pour moi ! En cette nuit sans sommeil, je mets les voiles sous la lumière argentée — »",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009931] = {
          ContentFR = "« Le vent gonfle ma voile, la marée embrasse mon aviron... le phare s’illumine dans la mer, et la lune brille si fort ! »",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009932] = {
          ContentFR = "Merci, Enola... C’était magnifique. Dans mon esprit, Putini t’a toujours ressemblé : passionnée, courageuse, toujours en quête de liberté...",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009933] = {
          ContentFR = "Merci ! J’ai un peu improvisé... Mais je connais un compositeur talentueux, Cavaradossi. Peut-être pourrait-il adapter Putini en opéra...",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009934] = {
          ContentFR = "... Mais je n’aurai sans doute jamais l’occasion de la chanter.",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009935] = {
          ContentFR = "J’ai dix-huit ans. Mon père m’a déjà trouvé un mari, un jeune officier de l’Académie d’Alchimie. Le mariage est dans deux mois.",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009936] = {
          ContentFR = "Je suppose que je finirai ma vie en poupée de porcelaine dans un salon... ou les mains plongées à jamais dans ces maudits flacons de Phoxichor.",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009937] = {
          ContentFR = "Non... non, Enola, ce n’est pas ce qui doit t’arriver. Ta voix est celle d’une alouette... Tu n’es pas faite pour un petit salon. Tu es faite pour la scène — la plus grande de toutes.",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009938] = {
          ContentFR = "Chaque personne qui aime chanter mérite de briller sous les projecteurs — qu’elle soit Sola ou Charon, riche ou pauvre...",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009939] = {
          ContentFR = "Je trouverai un moyen pour que mon frère te laisse partir. Mon corps me lâche déjà... Je ne sais pas si j’aurai le temps d’écrire la dernière scène de Putini...",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009940] = {
          ContentFR = "Mais Enola... promets-moi que tu monteras sur scène. Que tu feras entendre notre Putini au monde entier...",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009941] = {
          ContentFR = "« Chaque personne qui aime chanter mérite de briller sous les projecteurs. » C’était la dernière volonté de Violette... et c’est devenu ma raison de vivre.",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300
        },
        [51009942] = {
          ContentFR = "... Quand elle est morte, j’ai chanté le dernier acte de Putini devant Sig. Il était vidé par la douleur... mais dans ses yeux, j’ai vu une étincelle renaître des cendres.",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300
        },
        [51009943] = {
          ContentFR = "Nous avions encore une chance de faire vivre Violette à travers son œuvre. Sa joie, sa tristesse, son espoir, sa nostalgie — tout est dans cette pièce. Je voulais la faire connaître au monde. Je devais le faire.",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300
        },
        [51009944] = {
          ContentFR = "Nous étions toutes deux nées pour la scène. La maladie l’a emportée trop tôt, mais je porterai son âme sur chaque scène, dans chaque lumière.",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300
        },
        [51009945] = {
          ContentFR = "Alors, pour t’aider à échapper au contrôle de ton père... et pour accomplir la dernière volonté de Violette... Sig a accepté de jouer son rôle dans cette mise en scène.",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... impossible. Si tout cela est vrai, alors pourquoi a-t-elle dit tout ce qu’elle vient d’avouer... ?",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          ContentFR = "Parce que tu es venue ici avec ta version des faits déjà décidée, Giselle. Et Madame Violetta avait peur qu’en te contredisant, elle mette la vie de son élève Rosalind en danger.",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001
        },
        [51009948] = {
          ContentFR = "Qu... Quoi... ?",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai une requête... Je ne m’enfuirai pas, je te le promets. Mais accompagne-moi. J’aimerais te montrer un endroit.",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{"Stop"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt01/0036_story_renweidaozu"}}",
          SpeakNpcId = 700300
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’accord. Mais mieux vaut pour toi ne pas essayer de jouer à un petit jeu.",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tout a été reconstruit... Et pourtant, à mes yeux, chaque brique, chaque pierre est restée figée dans son état d’il y a seize ans.",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          ContentFR = "Violette... je suis revenue te voir. Et j’ai apporté avec moi notre œuvre.",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          ContentFR = "Quelqu’un a fini par comprendre notre histoire... Et étrangement, ça ne m’effraie pas. Je me sens presque soulagée. Peut-être parce que je peux enfin te le dire comme il faut... Pour Sig... je suis désolée.",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300
        },
        [51009954] = {
          ContentFR = "Violetta fit glisser ses doigts sur le mur, comme si elle confiait ses souvenirs à une amie disparue depuis longtemps. Peut-être avait-elle simplement senti que le moment des adieux était venu.",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci... de m’avoir laissée suivre mes caprices jusqu’au bout.",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          ContentFR = "Alors, Violetta... si tu as accepté de porter seule la faute, c’est aussi parce que la mort de Sig n’était pas prévue, n’est-ce pas ?",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          ContentFR = "... Fabrice Ruthford. C’était un homme froid et impitoyable. Les mineurs sous ses ordres mouraient presque de faim. Même les Veilleurs souffraient sous sa poigne de fer.",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Même envers sa propre fille, il ne faisait preuve d’aucune tendresse. Il rejetait tout ce qu’elle était, piétinait ses rêves, emprisonnait sa liberté... Il voulait la façonner selon la vie sans éclat qu’il avait planifiée pour elle.",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          ContentFR = "Et pourtant... quand sa fille est "morte", cet homme cruel a ignoré toute procédure judiciaire pour exécuter lui-même l’auteur de l’enlèvement — quitte à offrir à ses ennemis l’arme pour le destituer.",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300
        },
        [51009960] = {
          ContentFR = "J’avais imaginé mille plans pour envoyer une lettre au tribunal après m’être enfuie... Assez pour innocenter Sig. Mais ce à quoi je n’avais jamais pensé —",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300
        },
        [51009961] = {
          ContentFR = "... C’est que ton père t’aimait bien plus que tu ne le croyais.",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          ContentFR = "... Il y a eu tant de fois où j’ai voulu tout avouer. Mais Hyperborea n’était que le point de départ : son œuvre devait voyager à travers le monde. Je devais tenir ma promesse... ou du moins essayer.",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          ContentFR = "Alors quand tu es venue me trouver, Giselle... j’ai ressenti un étrange soulagement. J’ai formé de nombreux enfants talentueux, et eux pourront porter Putini encore plus loin que moi.",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          ContentFR = "Et il te suffisait... d’endosser la culpabilité aux yeux de Giselle, pour laver Sig d’un crime qui n’était pas le sien.",
          DialogueId = 51009964,
          GUID = "7FB2B638",
          NextDialogue = 51009965,
          SpeakNpcId = 100001
        },
        [51009965] = {
          ContentFR = "... Je te suivrai, Giselle. Mais seulement si tu libères Rosalind Magnus.",
          DialogueId = 51009965,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2B662",
          NextDialogue = 51009966,
          SpeakNpcId = 700300
        },
        [51009966] = {
          ContentFR = "Pour moi... pour Sig et pour Violette... il ne doit rien lui arriver.",
          DialogueId = 51009966,
          GUID = "7FB2B68C",
          NextDialogue = 51009967,
          SpeakNpcId = 700300
        },
        [51009967] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Elle a déjà quitté Givrelac.",
          DialogueId = 51009967,
          GUID = "7FB2B6B6",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009968,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009968] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi ?!",
          DialogueId = 51009968,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2B6E0",
          NextDialogue = 51009969,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Shock_Start"
          }
        },
        [51009969] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu étais son professeur de chant, tu sais donc ce qu’elle affrontait.",
          DialogueId = 51009969,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2B70A",
          NextDialogue = 51009970,
          SpeakNpcId = 700302
        },
        [51009970] = {
          ContentFR = "Une oiselle prête à se briser les ailes pour s’échapper de sa cage... Vous deux, vous vous ressemblez énormément.",
          DialogueId = 51009970,
          GUID = "7FB2B734",
          NextDialogue = 51009971,
          SpeakNpcId = 700302
        },
        [51009971] = {
          ContentFR = "Alors tout ce temps... tu me mentais.",
          DialogueId = 51009971,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B75E",
          NextDialogue = 51009972,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Shock_End"
          }
        },
        [51009972] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’était pas prévu. Je ne pensais pas que quelqu’un d’aussi proche de toi viendrait m’engager pour la "kidnapper". J’ai simplement... profité de l’occasion.",
          DialogueId = 51009972,
          GUID = "7FB2B788",
          NextDialogue = 51009973,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009973] = {
          ContentFR = "Alors ? Mon jeu d’actrice était convaincant, non ? Peut-être que je devrais songer à changer de métier.",
          DialogueId = 51009973,
          GUID = "7FB2B7B2",
          NextDialogue = 51009974,
          SpeakNpcId = 700302
        },
        [51009974] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu ne veux plus être une Chasseuse de Phoxène ?",
          DialogueId = 51009974,
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "7FB2B7DC",
          NextDialogue = 51009975,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009975] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Eh bien. Avec tout ce vacarme autour de "l’enlèvement" de la demoiselle Magnus, je vais devoir disparaître quelque temps de toute façon.",
          DialogueId = 51009975,
          GUID = "7FB2B806",
          NextDialogue = 51009976,
          SpeakNpcId = 700302
        },
        [51009976] = {
          ContentFR = "Quant à Violetta...",
          DialogueId = 51009976,
          GUID = "7FB2B830",
          NextDialogue = 51009977,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009977] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{nickname}, c’est toi qui vas décider. Puisque tu as découvert la vérité avant moi, c’est à toi de choisir ce qu’il adviendra d’elle.",
          DialogueId = 51009977,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2B85A",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009978,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009978] = {
          ContentFR = "Tu es sûre, Giselle ?",
          DialogueId = 51009978,
          GUID = "7FB2B884",
          NextDialogue = 51009979,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009979] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je n’en sais rien. <H>Si nous révélons la vérité, elle pourrait tout perdre — son nom, son rêve. Mais si nous gardons le silence... le nom de Sig ne sera jamais lavé.</>",
          DialogueId = 51009979,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B8AE",
          NextDialogue = 51009980,
          SpeakNpcId = 700302
        },
        [51009980] = {
          ContentFR = "Je ne sais plus quoi penser. Peut-être qu’il vaut mieux que ce soit toi qui décides.",
          DialogueId = 51009980,
          GUID = "7FB2B8D8",
          NextDialogue = 51009981,
          SpeakNpcId = 700302
        },
        [51009981] = {
          ContentFR = "Si c’est toi qui fais ce choix... je l’accepterai.",
          DialogueId = 51009981,
          GUID = "7FB2B902",
          NextOptions = {
            [1] = 510098911,
            [2] = 510098912
          },
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          },
          bForbidSkipOptions = true
        },
        [51009982] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Giselle.",
          DialogueId = 51009982,
          GUID = "7FB2B92C",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009983,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700302:Talk03_Start"
          }
        },
        [51009983] = {
          ContentFR = "Je t’écoute.",
          DialogueId = 51009983,
          GUID = "7FB2B956",
          NextDialogue = 51009984,
          SpeakNpcId = 700302
        },
        [51009984] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Est-ce qu’on ne pourrait pas simplement... ne rien dire ? Ne pas révéler toute cette histoire ?",
          DialogueId = 51009984,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2B980",
          NextDialogue = 51009985,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51009985] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sig a donné sa vie et son honneur pour que Violetta fasse vivre Putini. Je ne crois pas que ce soit ainsi qu’il voudrait que ça se termine.",
          DialogueId = 51009985,
          GUID = "7FB2B9AA",
          NextDialogue = 51009986,
          SpeakNpcId = 100001
        },
        [51009986] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... D’accord. Je comprends.",
          DialogueId = 51009986,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2B9D4",
          NextDialogue = 51009987,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Agree",
            [2] = "100001:Explain02_End"
          }
        },
        [51009987] = {
          ContentFR = "Giselle ?",
          DialogueId = 51009987,
          GUID = "7FB2B9FE",
          NextDialogue = 51009988,
          SpeakNpcId = 700300
        },
        [51009988] = {
          ContentFR = "C’est toi qui choisis. Alors je respecterai ta décision.",
          DialogueId = 51009988,
          GUID = "7FB2BA28",
          NextDialogue = 51009989,
          SpeakNpcId = 700302
        },
        [51009989] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je t’en suis profondément reconnaissante.",
          DialogueId = 51009989,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2BA52",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009990,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009990] = {
          ContentFR = "Dans ce cas, nous sommes d’accord.",
          DialogueId = 51009990,
          GUID = "7FB2BA7C",
          NextDialogue = 51009991,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009991] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh, et... accepteriez-vous de venir à la représentation dans deux jours ? Je vous réserverai les meilleures places.",
          DialogueId = 51009991,
          GUID = "7FB2BAA6",
          NextDialogue = 51009992,
          SpeakNpcId = 700300
        },
        [51009992] = {
          ContentFR = "Une représentation... ?",
          DialogueId = 51009992,
          GUID = "7FB2BAD0",
          NextDialogue = 51009993,
          SpeakNpcId = 700302
        },
        [51009993] = {
          ContentFR = "Oui, Putini. Considère-la comme une représentation d’adieu pour Rosalind. C’est sa pièce préférée.",
          DialogueId = 51009993,
          GUID = "7FB2BAFA",
          NextDialogue = 51010006,
          SpeakNpcId = 700300
        },
        [51009994] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je comprends ce que tu as fait, Violetta. Mais on ne peut pas laisser un homme être considéré comme un meurtrier, même après sa mort.",
          DialogueId = 51009994,
          GUID = "7FB2BB24",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009995,
          Scripts = "SEQ{\nTurnTo{TurnToDescription{\"100001:n(700300)\"}},\nPlayAnimation{ActorId{100001},AnimationId{\"Talk01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001
        },
        [51009995] = {
          ContentFR = "Sig n’est plus là. Mais nous avons encore la possibilité de laver son nom.",
          DialogueId = 51009995,
          GUID = "7FB2BB4E",
          NextDialogue = 51009996,
          SpeakNpcId = 100001
        },
        [51009996] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{nickname}... Merci.",
          DialogueId = 51009996,
          GUID = "7FB2BB78",
          NextDialogue = 51009997,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009997] = {
          ContentFR = "Sig t’a enlevée pour l’argent, oui. Mais ce n’est pas un meurtrier. La vérité doit être révélée.",
          DialogueId = 51009997,
          GUID = "7FB2BBA2",
          NextDialogue = 51009998,
          SpeakNpcId = 100001
        },
        [51009998] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violetta... une fois que ce sera public, tu risques de tout perdre : ta réputation, ta carrière...",
          DialogueId = 51009998,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2BBCC",
          NextDialogue = 51009999,
          SpeakNpcId = 100001
        },
        [51009999] = {
          ContentFR = "Je comprends. Mais c’est très bien ainsi... Pardon, Violette. Notre rêve devra continuer à vivre à travers ces enfants.",
          DialogueId = 51009999,
          GUID = "7FB2BBF6",
          NextDialogue = 51010000,
          SpeakNpcId = 700300
        },
        [51010000] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dans ce cas, nous sommes d’accord.",
          DialogueId = 51010000,
          GUID = "7FB2BC20",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51010001,
          SpeakNpcId = 700302
        },
        [51010001] = {
          ContentFR = "Une dernière chose...",
          DialogueId = 51010001,
          GUID = "7FB2BC4A",
          NextDialogue = 51010002,
          SpeakNpcId = 700300
        },
        [51010002] = {
          ContentFR = "Hmm ? Il est un peu tard pour changer d’avis.",
          DialogueId = 51010002,
          GUID = "7FB2BC74",
          NextDialogue = 51010003,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010003] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh non. Je voulais simplement vous inviter à une représentation, dans deux jours. Considérez-la comme mon chant du cygne. Je préparerai les meilleures places pour vous deux.",
          DialogueId = 51010003,
          GUID = "7FB2BC9E",
          NextDialogue = 51010004,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010004] = {
          ContentFR = "Ton chant du cygne, hein... ?",
          DialogueId = 51010004,
          GUID = "7FB2BCC8",
          NextDialogue = 51010005,
          SpeakNpcId = 700302
        },
        [51010005] = {
          ContentFR = "Oui. Putini. Tout a commencé avec cette pièce — et c’est ainsi que cela doit se terminer.",
          DialogueId = 51010005,
          GUID = "7FB2BCF2",
          NextDialogue = 51010006,
          SpeakNpcId = 700300
        },
        [51010006] = {
          ContentFR = "J’y serai.",
          DialogueId = 51010006,
          GUID = "7FB2BD1C",
          NextDialogue = 51010007,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51010007] = {
          ContentFR = "Une seule place suffira.",
          DialogueId = 51010007,
          GUID = "7FB2BD46",
          NextDialogue = 51010008,
          SpeakNpcId = 700302
        },
        [51010008] = {
          ContentFR = "...",
          DialogueId = 51010008,
          GUID = "7FB2BD70",
          NextDialogue = 51010009,
          SpeakNpcId = 700300
        },
        [51010009] = {
          ContentFR = "Ne te méprends pas, je viendrai. Mais disons que pour une "demi-fugitive", mieux vaut ne pas trop se faire remarquer.",
          DialogueId = 51010009,
          GUID = "7FB2BD9A",
          NextDialogue = 51010010,
          SpeakNpcId = 700302
        },
        [51010010] = {
          ContentFR = "Très bien. Je vais prévenir la troupe.",
          DialogueId = 51010010,
          GUID = "7FB2BDC4",
          NextDialogue = 51010011,
          SpeakNpcId = 700300
        },
        [51010011] = {
          ContentFR = "Dans ce cas... rendez-vous dans deux jours.",
          DialogueId = 51010011,
          GUID = "7FB2BDEE",
          SpeakNpcId = 700300
        },
        [51010012] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bonjour, Violetta.",
          DialogueId = 51010012,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2BE18",
          NextDialogue = 51010013,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51010013] = {
          ContentFR = "Vous voilà. Tenez, voici vos billets.",
          DialogueId = 51010013,
          GUID = "7FB2BE42",
          NextDialogue = 51010014,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51010014] = {
          ContentFR = "Eh bien, je ne vais pas me faire prier.",
          DialogueId = 51010014,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2BE6C",
          NextDialogue = 51010015,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010015] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentFR = "Allez-y. Faire voyager Putini à travers le monde était le dernier vœu de Violette. Elle ne m’en voudra pas d’offrir deux places.",
          DialogueId = 51010015,
          GUID = "7FB2BE96",
          NextDialogue = 51010016,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51010016] = {
          ContentFR = "C’est juste que...",
          DialogueId = 51010016,
          GUID = "7FB2BEC0",
          NextDialogue = 51010017,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010017] = {
          ContentFR = "... Tu penses à Mademoiselle Rosalind, n’est-ce pas ?",
          DialogueId = 51010017,
          GUID = "7FB2BEEA",
          NextDialogue = 51010018,
          SpeakNpcId = 100001
        },
        [51010018] = {
          ContentFR = "Mmh. C’était censé être sa représentation d’adieu. Mais j’ignore même si elle est toujours à Givrelac... ou si elle pourra assister à sa pièce préférée.",
          DialogueId = 51010018,
          GUID = "7FB2BF14",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700300:n(700302)"
          },
          NextDialogue = 51010019,
          SpeakNpcId = 700300
        },
        [51010019] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001564,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne me regarde pas. Pour éviter que ses parents ne la retrouvent, j’ai moi-même préféré ne pas connaître sa cachette.",
          DialogueId = 51010019,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2BF3E",
          NextOptions = {
            [1] = 510099291,
            [2] = 510099292
          },
          SpeakNpcId = 700302
        },
        [51010020] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentFR = "Espérons-le... Oh, {nickname}.",
          DialogueId = 51010020,
          FacialId = {
            [1] = "700302:CM_Idle",
            [2] = "700300:CM_Smile01"
          },
          GUID = "7FB2BF68",
          SpeakNpcId = 700300
        },
        [51010021] = {
          ContentFR = "Tu as relié entre eux trois événements qui semblaient sans lien... pour en faire une histoire à la fin heureuse. Ton esprit et ta détermination m’impressionnent.",
          DialogueId = 51010021,
          GUID = "7FB2BF92",
          NextDialogue = 51010022,
          SpeakNpcId = 700300
        },
        [51010022] = {
          ContentFR = "J’ai donc une autre mission à te proposer — elle concerne l’un de mes élèves. La récompense n’est pas un souci. Passe me voir au théâtre quand tu auras le temps.",
          DialogueId = 51010022,
          GUID = "7FB2BFBC",
          NextDialogue = 51010023,
          SpeakNpcId = 700300
        },
        [51010023] = {
          ContentFR = "Mais pas ce soir — ce soir appartient à la musique, et au grand départ. Laisse tes soucis derrière toi... et profite de cette nuit inoubliable.",
          DialogueId = 51010023,
          GUID = "7FB2BFE6",
          SpeakNpcId = 700300
        },
        [51010024] = {
          ContentFR = "Tu trouves les places réservées par Violetta et t’installes, attendant que le rideau se lève.",
          DialogueId = 51010024,
          GUID = "7FB2C010",
          NextDialogue = 51010025
        },
        [51010025] = {
          ContentFR = "Alors que les lumières s’éteignent peu à peu, une puissante voix de soprano s’élève derrière le rideau, emplissant la salle d’une magie indicible.",
          DialogueId = 51010025,
          GUID = "7FB2C03A",
          NextDialogue = 51010026
        },
        [51010026] = {
          ContentFR = "Le public retient son souffle. Ce silence profond te met presque mal à l’aise.",
          DialogueId = 51010026,
          GUID = "7FB2C064",
          NextDialogue = 51010027
        },
        [51010027] = {
          ContentFR = "Il est difficile de retenir tes exclamations face aux scènes les plus spectaculaires — tu crains qu’un soupir d’admiration n’interrompe l’enchantement.",
          DialogueId = 51010027,
          GUID = "7FB2C08E",
          NextDialogue = 51010028
        },
        [51010028] = {
          ContentFR = "Mais cette crainte s’évanouit vite — tant et si bien qu’au moment où le dernier son s’éteint, tu en oublies même d’applaudir.",
          DialogueId = 51010028,
          GUID = "7FB2C0B8"
        },
        [51010029] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouf... C’était vraiment une pièce magnifique. J’en ai presque oublié à quel point je déteste les endroits clos et bondés.",
          DialogueId = 51010029,
          GUID = "7FB2C0E2",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010030,
          SpeakNpcId = 700302
        },
        [51010030] = {
          ContentFR = "Je crois que je comprends enfin pourquoi la scène fascine autant les gens.",
          DialogueId = 51010030,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2C10C",
          NextDialogue = 51010031,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010031] = {
          ContentFR = "Espérons simplement que les gens arrêteront de me donner du fil à retordre... Je ne veux plus jamais avoir à "kidnapper" mes propres clients.",
          DialogueId = 51010031,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2C136",
          NextDialogue = 51010032,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start",
            [2] = "100001:Talk02R_End"
          }
        },
        [51010032] = {
          ContentFR = "Même si, pour être honnête, je ne suis pas mieux. Moi aussi, je me suis enfermée dans mes obsessions pendant des années.",
          DialogueId = 51010032,
          GUID = "7FB2C160",
          NextDialogue = 51010033,
          SpeakNpcId = 700302
        },
        [51010033] = {
          ContentFR = "Je suis {性别:curieux|curieuse}... pourquoi cette affaire te tenait-elle autant à cœur ?",
          DialogueId = 51010033,
          GUID = "7FB2C18A",
          NextDialogue = 51010034,
          SpeakNpcId = 100001
        },
        [51010034] = {
          ContentFR = "... Je peux ne pas répondre à ça ?",
          DialogueId = 51010034,
          GUID = "7FB2C1B4",
          NextDialogue = 51010035,
          SpeakNpcId = 700302
        },
        [51010035] = {
          ContentFR = "Tu n’es pas obligée d’en parler.",
          DialogueId = 51010035,
          GUID = "7FB2C1DE",
          NextDialogue = 51010036,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "700302:Confident_End"
          }
        },
        [51010036] = {
          ContentFR = "D’accord... inutile de faire des mystères avec quelqu’un d’aussi sincère que toi.",
          DialogueId = 51010036,
          GUID = "7FB2C208",
          NextDialogue = 51010037,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51010037] = {
          ContentFR = "Donat t’a sûrement raconté qu’il avait dénoncé Sig. Eh bien, la personne à qui il s’est adressé... c’était moi.",
          DialogueId = 51010037,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2C232",
          NextDialogue = 51010038,
          SpeakNpcId = 700302
        },
        [51010038] = {
          ContentFR = "Au départ, pour ne pas l’effrayer, je voulais aller négocier seule, libérer l’otage sans faire de vagues. Mais quand j’ai réalisé qu’il s’agissait de la fille de mon supérieur, j’ai hésité... et j’ai fini par faire un rapport.",
          DialogueId = 51010038,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2C25C",
          NextDialogue = 51010039,
          SpeakNpcId = 700302
        },
        [51010039] = {
          ContentFR = "La suite, tu la connais. Son père a refusé mon plan, a perdu son sang-froid, et a lancé l’assaut.",
          DialogueId = 51010039,
          GUID = "7FB2C286",
          NextDialogue = 51010040,
          SpeakNpcId = 700302
        },
        [51010040] = {
          ContentFR = "Si j’avais suivi mon instinct... peut-être que rien de tout cela ne serait arrivé.",
          DialogueId = 51010040,
          GUID = "7FB2C2B0",
          NextDialogue = 51010041,
          SpeakNpcId = 700302
        },
        [51010041] = {
          ContentFR = "Même si cela aurait rendu les choses plus difficiles pour Violetta, au moins Sig n’aurait pas été exécuté pour un crime qu’il n’avait pas commis.",
          DialogueId = 51010041,
          GUID = "7FB2C2DA",
          NextDialogue = 51010042,
          SpeakNpcId = 700302
        },
        [51010042] = {
          ContentFR = "Giselle...",
          DialogueId = 51010042,
          GUID = "7FB2C304",
          NextDialogue = 51010043,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700302:Talk02_End"
          }
        },
        [51010043] = {
          ContentFR = "Je comprends sa réaction. Aucun parent ne supporterait la mort de son enfant. Mais je ne peux pas approuver qu’on rende justice avant d’avoir découvert toute la vérité.",
          DialogueId = 51010043,
          GUID = "7FB2C32E",
          NextDialogue = 51010044,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Sigh_Start"
          }
        },
        [51010044] = {
          ContentFR = "Ce n’est pas pour ça que j’ai rejoint les Veilleurs.",
          DialogueId = 51010044,
          GUID = "7FB2C358",
          NextDialogue = 51010045,
          SpeakNpcId = 700302
        },
        [51010045] = {
          ContentFR = "Les Veilleurs ont perdu quelqu’un qui représentait vraiment la justice.",
          DialogueId = 51010045,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2C382",
          NextDialogue = 51010046,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51010046] = {
          ContentFR = "... Est-ce que c’était un compliment ?",
          DialogueId = 51010046,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2C3AC",
          NextDialogue = 51010047,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Sigh_End"
          }
        },
        [51010047] = {
          ContentFR = "Quoi qu’il en soit, c’est du passé. Maintenant que tout est terminé, je vais voir si je peux rendre publique une partie de la vérité sur l’affaire — tout en gardant secrète l’identité de Violetta.",
          DialogueId = 51010047,
          GUID = "7FB2C3D6",
          NextDialogue = 51010048,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51010048] = {
          ContentFR = "Sans Enola, tu n’auras aucune preuve pour convaincre les Veilleurs de rouvrir l’enquête.",
          DialogueId = 51010048,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C400",
          NextDialogue = 51010049,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010049] = {
          ContentFR = "Les Veilleurs ? Inutile. Je vais tout raconter à la presse. La rumeur est un juge bien plus puissant que des archives poussiéreuses.",
          DialogueId = 51010049,
          GUID = "7FB2C42A",
          NextDialogue = 51010050,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010050] = {
          ContentFR = "Tu crois que ça marchera vraiment... ?",
          DialogueId = 51010050,
          GUID = "7FB2C454",
          NextDialogue = 51010051,
          SpeakNpcId = 100001
        },
        [51010051] = {
          ContentFR = "Les gens adorent les secrets cachés. Croire qu’ils ont découvert ce qui se cache derrière les apparences les fait se sentir intelligents. Je vais juste... exploiter ça un peu.",
          DialogueId = 51010051,
          GUID = "7FB2C47E",
          NextDialogue = 51010052,
          SpeakNpcId = 700302
        },
        [51010052] = {
          ContentFR = "... Ah !",
          DialogueId = 51010052,
          GUID = "7FB2C4A8",
          IsBlack = 1,
          NextDialogue = 51010053,
          Scripts = "SEQ{\nMoveTo{ActorId{700305},TargetPoint{\"RosalindPoint1_20023305\"},MoveSpeed{250},Visibility{\"Show\"}},\nPARA{\nLookAt{LookAtDescription{\"100001:n(700305)\"}},\nLookAt{LookAtDescription{\"700302:n(700305)\"}},\nTurnTo{TurnToDescription{\"700305:n(100001)\"}}\n},\nPARA{\nPlayAnimation{ActorId{100001},AnimationId{\"Shock_Start\"},Duration{1}},\nPlayAnimation{ActorId{700302},AnimationId{\"Angry01_Start\"},Duration{1}},\nPlayAnimation{ActorId{700305},AnimationId{\"Explain02_Start\"},Duration{1}}\n}}",
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010053] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "P-Pardon, je ne regardais pas devant moi ! Tu vas bien ? Je ne t’ai pas fait mal ?",
          DialogueId = 51010053,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2C4D2",
          NextDialogue = 51010054,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010054] = {
          ContentFR = "Je vais bien. Faites juste attention, d’accord ?",
          DialogueId = 51010054,
          GUID = "7FB2C4FC",
          NextDialogue = 51010055,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010055] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mmm...",
          DialogueId = 51010055,
          GUID = "7FB2C526",
          NextDialogue = 51010056,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010056] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai quelque chose sur le visage ?",
          DialogueId = 51010056,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2C550",
          NextDialogue = 51010057,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010057] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, rien du tout... Hihi... Merci pour les herbes ! Oh non, je vais être en retard !",
          DialogueId = 51010057,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2C57A",
          NextDialogue = 51010058,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010058] = {
          ContentFR = "Des herbes... ? Attendez, vous avez fait tomber quelque chose !",
          DialogueId = 51010058,
          GUID = "7FB2C5A4",
          NextDialogue = 51010059,
          Scripts = "SEQ{\nMoveTo{ActorId{700305},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{250},Visibility{\"Hide\"}},\nPlayAnimation{ActorId{100001},AnimationId{\"Nvzhu_Story_StretchHand_Start\"},Duration{1}}\n}",
          SpeakNpcId = 100001
        },
        [51010059] = {
          ContentFR = "Garde-le ! C’est pour toi !",
          DialogueId = 51010059,
          GUID = "7FB2C5CE",
          NextDialogue = 51010060,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010060] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sérieusement... les jeunes, aujourd’hui, sont toujours aussi pressés.",
          DialogueId = 51010060,
          GUID = "7FB2C5F8",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010061,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010061] = {
          ContentFR = "Pourquoi m’a-t-elle laissé ça... ? Il y a une broderie dessus... C’est son nom ?",
          DialogueId = 51010061,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C622",
          NextDialogue = 51010062,
          SpeakNpcId = 100001
        },
        [51010062] = {
          ContentFR = "... Putini ?",
          DialogueId = 51010062,
          GUID = "7FB2C64C",
          NextDialogue = 51010063,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010063] = {
          ContentFR = "« Si un jour tu rencontres une fille qui s’appelle Putini... j’espère que tu me reconnaîtras. Moi, je te reconnaîtrai. »",
          DialogueId = 51010063,
          GUID = "7FB2C676",
          IsBlack = 1,
          NextDialogue = 51010064
        },
        [51010064] = {
          ContentFR = "Qu’est-ce qui te fait sourire comme ça ?",
          DialogueId = 51010064,
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "7FB2C6A0",
          NextDialogue = 51010065,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010065] = {
          ContentFR = "Si même toi tu ne l’as pas reconnue... peut-être que Violetta n’est pas la seule à avoir mille visages.",
          DialogueId = 51010065,
          GUID = "7FB2C6CA",
          NextDialogue = 51010066,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010066] = {
          ContentFR = "La vie ne se joue jamais en un seul acte. Nous nous reverrons sur une nouvelle scène. D’ici là... bon voyage à toi, Mademoiselle Caisse.",
          DialogueId = 51010066,
          GUID = "7FB2C6F4",
          IsBlack = 1,
          SpeakNpcId = 100001
        },
        [51010067] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51010067,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2C71E",
          NextDialogue = 51010068,
          SpeakNpcId = 100001
        },
        [51010068] = {
          ContentFR = "Bonjour, {nickname}. Pourquoi cette mine triste ?",
          DialogueId = 51010068,
          GUID = "7FB2C748",
          NextDialogue = 51010069,
          SpeakNpcId = 700300
        },
        [51010069] = {
          ContentFR = "Violetta...",
          DialogueId = 51010069,
          GUID = "7FB2C772",
          NextDialogue = 51010070,
          SpeakNpcId = 100001
        },
        [51010070] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentFR = "Allons, pas besoin d’en dire plus. C’est moi qui prends ma retraite, pas toi. Inutile d’avoir de la peine pour moi.",
          DialogueId = 51010070,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2C79C",
          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          ContentFR = "Tu n’as fait que ce que ferait toute personne fidèle à ses principes. Ne porte pas ce poids sur tes épaules. Dis-toi simplement que tu as aidé une fugueuse à rentrer chez elle.",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300
        },
        [51010072] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On dirait que tout le monde est là.",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{"GisellePoint_20023305"},MoveSpeed{150},Visibility{"Show"}}",
          SpeakNpcId = 700302
        },
        [51010073] = {
          ContentFR = "Parfait, Giselle, tiens — voici vos billets.",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          ContentFR = "Merci. J’ai déjà contacté mes anciens collègues des Veilleurs : ils n’interviendront pas avant la fin du spectacle.",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          ContentFR = "Je t’en suis très reconnaissante. La représentation va commencer, je dois aller en coulisses.",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          ContentFR = "Allons-y aussi. Même si c’est en partie de ma faute, j’avoue que j’attends avec impatience cette représentation d’adieu.",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302
        },
        [51010077] = {
          ContentFR = "Allons-y.",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001
        },
        [51010078] = {
          ContentFR = "Tu trouves les places réservées par Violetta et t’installes, attendant que le rideau se lève.",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079
        },
        [51010079] = {
          ContentFR = "Alors que les lumières s’éteignent peu à peu, une puissante voix de soprano s’élève derrière le rideau, emplissant la salle d’une magie indicible.",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080
        },
        [51010080] = {
          ContentFR = "Le public retient son souffle. Ce silence profond te met presque mal à l’aise.",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081
        },
        [51010081] = {
          ContentFR = "Il est difficile de retenir tes exclamations face aux scènes les plus spectaculaires — tu crains qu’un soupir d’admiration n’interrompe l’enchantement.",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082
        },
        [51010082] = {
          ContentFR = "Mais cette crainte s’évanouit vite —",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083
        },
        [51010083] = {
          ContentFR = "Tant et si bien qu’au moment où le dernier son s’éteint, tu en oublies même d’applaudir.",
          DialogueId = 51010083,
          GUID = "7FB2C9BE"
        },
        [51010084] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Giselle ! Tu me dois des explications !",
          DialogueId = 51010084,
          FacialId = {
            [1] = "700304:CM_Angry01"
          },
          GUID = "7FB2C9E8",
          NextDialogue = 51010085,
          SpeakNpcId = 700304,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700304:Angry01_Start"
          }
        },
        [51010085] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ? Et que pourrait bien vouloir savoir le grand Fabrice Ruthford ?",
          DialogueId = 51010085,
          GUID = "7FB2CA12",
          NextDialogue = 51010086,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010086] = {
          ContentFR = "Tu as signalé que Violetta était Enola, mais quand je suis arrivé en coulisses avec mes hommes... il n’y avait plus personne !",
          DialogueId = 51010086,
          GUID = "7FB2CA3C",
          NextDialogue = 51010087,
          SpeakNpcId = 700304
        },
        [51010087] = {
          ContentFR = "Ah, ça. Je ne m’attendais pas à ce que tu viennes en personne. Quelle implication, vraiment.",
          DialogueId = 51010087,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302
        },
        [51010088] = {
          ContentFR = "Ne joue pas au plus malin ! Je t’ordonne de me conduire à Enola, tout de suite !",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304
        },
        [51010089] = {
          ContentFR = "Il semble que tu oublies un détail : je ne fais plus partie des Veilleurs. Et toi non plus. J’ai simplement transmis une information... en tant que simple citoyenne.",
          DialogueId = 51010089,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CABA",
          NextDialogue = 51010090,
          SpeakNpcId = 700302
        },
        [51010090] = {
          ContentFR = "Je ne suis donc pas tenue d’obéir à tes ordres. Par contre... tu peux toujours engager « Giselle la Chasseuse de Phoxène ».",
          DialogueId = 51010090,
          GUID = "7FB2CAE4",
          NextDialogue = 51010091,
          SpeakNpcId = 700302
        },
        [51010091] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien ! Alors je vais t’engager !",
          DialogueId = 51010091,
          GUID = "7FB2CB0E",
          NextDialogue = 51010092,
          SpeakNpcId = 700304,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51010092] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfait. Je refuse la mission.",
          DialogueId = 51010092,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CB38",
          NextDialogue = 51010093,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk01_Start"
          }
        },
        [51010093] = {
          ContentFR = "Tu te moques de moi !?",
          DialogueId = 51010093,
          GUID = "7FB2CB62",
          NextDialogue = 51010094,
          SpeakNpcId = 700304
        },
        [51010094] = {
          ContentFR = "Disons que, puisque je suis actuellement suspectée d’avoir "kidnappé"la fille d’un comte, mon activité est suspendue.",
          DialogueId = 51010094,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CB8C",
          NextDialogue = 51010095,
          SpeakNpcId = 700302
        },
        [51010095] = {
          ContentFR = "Au fond, si tu avais accepté la solution pacifique que je proposais à l’époque, tout ceci n’aurait jamais eu lieu.",
          DialogueId = 51010095,
          GUID = "7FB2CBB6",
          NextDialogue = 51010096,
          SpeakNpcId = 700302
        },
        [51010096] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Je n’aurais jamais dû croire que tu pouvais retrouver Enola.",
          DialogueId = 51010096,
          GUID = "7FB2CBE0",
          NextDialogue = 51010097,
          SpeakNpcId = 700304,
          TalkActionId = {
            [1] = "700302:Talk01_End"
          }
        },
        [51010097] = {
          ContentFR = "Enola... ma fille... Je te retrouverai moi-même. Et toi, je ne veux plus jamais te revoir !",
          DialogueId = 51010097,
          GUID = "7FB2CC0A",
          NextDialogue = 51010098,
          SpeakNpcId = 700304
        },
        [51010098] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avec plaisir.",
          DialogueId = 51010098,
          GUID = "7FB2CC34",
          NextDialogue = 51010099,
          Scripts = "MoveTo{ActorId{700304},TargetPoint{"FabricePoint_20023305"},MoveSpeed{150},Visibility{"Hide"}}",
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010099] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Giselle, ça va ?",
          DialogueId = 51010099,
          FinalCamera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2CC5E",
          NextDialogue = 51010100,
          Scripts = "SEQ{\nMoveTo{ActorId{100001},TargetPoint{\"NvzhuPoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}},\nPARA{\nLookAt{LookAtDescription{\"100001:n(700302)\"}},\nLookAt{LookAtDescription{\"700302:n(100001)\"}}\n}\n}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 5
        },
        [51010100] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien. Je n’aurais jamais pu lui parler ainsi quand j’étais chez les Veilleurs. Ça fait un bien fou.",
          DialogueId = 51010100,
          GUID = "7FB2CC88",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010101,
          SpeakNpcId = 700302
        },
        [51010101] = {
          ContentFR = "C’était qui, exactement ?",
          DialogueId = 51010101,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2CCB2",
          NextDialogue = 51010102,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010102] = {
          ContentFR = "Fabrice Ruthford. Le père de Violetta. Toujours aussi impulsif qu’il y a seize ans.",
          DialogueId = 51010102,
          GUID = "7FB2CCDC",
          NextDialogue = 51010103,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010103] = {
          ContentFR = "Et Violetta ?",
          DialogueId = 51010103,
          GUID = "7FB2CD06",
          NextDialogue = 51010104,
          SpeakNpcId = 100001
        },
        [51010104] = {
          ContentFR = "Disparue. Quand Fabrice a débarqué, les coulisses étaient déjà vides.",
          DialogueId = 51010104,
          GUID = "7FB2CD30",
          NextDialogue = 51010105,
          SpeakNpcId = 700302
        },
        [51010105] = {
          ContentFR = "... Ah !",
          DialogueId = 51010105,
          GUID = "7FB2CD5A",
          IsBlack = 1,
          NextDialogue = 51010106,
          Scripts = "SEQ{\nMoveTo{ActorId{700305},TargetPoint{\"RosalindPoint1_20023305\"},MoveSpeed{250},Visibility{\"Show\"}},\nPARA{\nLookAt{LookAtDescription{\"100001:n(700305)\"}},\nLookAt{LookAtDescription{\"700302:n(700305)\"}},\nTurnTo{TurnToDescription{\"700305:n(100001)\"}}\n},\nPARA{\nPlayAnimation{ActorId{100001},AnimationId{\"Shock_Start\"},Duration{1}},\nPlayAnimation{ActorId{700302},AnimationId{\"Angry01_Start\"},Duration{1}},\nPlayAnimation{ActorId{700305},AnimationId{\"Explain02_Start\"},Duration{1}}\n}}",
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010106] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "P-Pardon, je ne regardais pas devant moi ! Tu vas bien ? Je ne t’ai pas fait mal ?",
          DialogueId = 51010106,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2CD84",
          NextDialogue = 51010107,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010107] = {
          ContentFR = "Je vais bien. Faites juste attention, d’accord ?",
          DialogueId = 51010107,
          GUID = "7FB2CDAE",
          NextDialogue = 51010108,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010108] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mmm...",
          DialogueId = 51010108,
          GUID = "7FB2CDD8",
          NextDialogue = 51010109,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010109] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai quelque chose sur le visage ?",
          DialogueId = 51010109,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2CE02",
          NextDialogue = 51010110,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010110] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, rien du tout... Hihi... Merci pour les herbes ! ",
          DialogueId = 51010110,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2CE2C",
          NextDialogue = 51010111,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010111] = {
          ContentFR = "L’heure tourne ! Tu vas être en retard !",
          DialogueId = 51010111,
          GUID = "7FB2CE56",
          NextDialogue = 51010112,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010112] = {
          ContentFR = "Oh non ! Je dois filer ! J’arrive, attendez-moi !",
          DialogueId = 51010112,
          GUID = "7FB2CE80",
          NextDialogue = 51010113,
          Scripts = "MoveTo{ActorId{700305},TargetPoint{"RosalindPoint2_20023305"},MoveSpeed{250},Visibility{"Hide"}}",
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010113] = {
          ContentFR = "Des herbes... ? Attendez, vous avez fait tomber quelque chose !",
          DialogueId = 51010113,
          GUID = "7FB2CEAA",
          NextDialogue = 51010114,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010114] = {
          ContentFR = "Garde-le ! C’est pour toi !",
          DialogueId = 51010114,
          GUID = "7FB2CED4",
