          DialogueId = 51011310,
          GUID = "7FB3930C",
          NextDialogue = 51011311,
          SpeakNpcId = 700341
        },
        [51011311] = {
          Content = "不，我不能说。请你离开这里吧，不要再来了。",
          DialogueId = 51011311,
          GUID = "7FB39336",
          NextDialogue = 51011317,
          SpeakNpcId = 700341
        },
        [51011312] = {
          Content = "城里应该有钟表匠吧，我们可以找他们帮忙。",
          DialogueId = 51011312,
          GUID = "7FB39360",
          ImprPlusId = 1003,
          NextDialogue = 51011313
        },
        [51011313] = {
          Content = "那请你……",
          DialogueId = 51011313,
          GUID = "7FB3938A",
          NextDialogue = 51011314,
          SpeakNpcId = 700341
        },
        [51011314] = {
          Content = "不……不可以相信外面的人。",
          DialogueId = 51011314,
          GUID = "7FB393B4",
          NextDialogue = 51011315,
          SpeakNpcId = 700341
        },
        [51011315] = {
          Content = "当我什么都没说过吧。",
          DialogueId = 51011315,
          GUID = "7FB393DE",
          NextDialogue = 51011316,
          SpeakNpcId = 700341
        },
        [51011316] = {
          Content = "请你离开这里，不要再来了。",
          DialogueId = 51011316,
          GUID = "7FB39408",
          NextDialogue = 51011317,
          SpeakNpcId = 700341
        },
        [51011317] = {
          Content = "（少女的情绪转变让你一时间不知道该如何应对，只能试图从她的眼神中得到更多信息。）",
          DialogueId = 51011317,
          GUID = "7FB39432",
          NextDialogue = 51011318
        },
        [51011318] = {
          Content = "（那是双充满迷茫与悲伤的眼睛，却又夹杂着一丝不易察觉的信念。你并不知道那信念从何而来，又意味着什么。但你明白这就是她守口如瓶的原因。）",
          DialogueId = 51011318,
          GUID = "7FB3945C"
        },
        [51011401] = {
          Content = "桌子……擦过了。地板……也擦过了。还剩……扶手，对，还有扶手。",
          DialogueId = 51011401,
          GUID = "7FB3A1FA",
          NextDialogue = 51011402,
          SpeakNpcId = 700340
        },
        [51011402] = {
          Content = "（少年絮絮自言自语着什么，面露急色，双手无所适从地比划着。）",
          DialogueId = 51011402,
          GUID = "7FB3A224",
          NextDialogue = 51011403
        },
        [51011403] = {
          Content = "……你让一让。",
          DialogueId = 51011403,
          GUID = "7FB3A24E",
          NextDialogue = 51011404,
          SpeakNpcId = 700340
        },
        [51011404] = {
          Content = "嗯？",
          DialogueId = 51011404,
          GUID = "7FB3A278",
          NextDialogue = 51011405,
          SpeakNpcId = 100001
        },
        [51011405] = {
          Content = "扶手，还没有擦。不要挡路。",
          DialogueId = 51011405,
          GUID = "7FB3A2A2",
          NextDialogue = 51011406,
          SpeakNpcId = 700340
        },
        [51011406] = {
          Content = "（顺着少年急切不安的视线，你看到了他凝视着的东西——楼梯扶手。但在你看来，那个扶手不算新，却光洁锃亮，一尘不染。）",
          DialogueId = 51011406,
          GUID = "7FB3A2CC",
          NextOptions = {
            [1] = 51011407,
            [2] = 51011411
          }
        },
        [51011407] = {
          Content = "不用擦了。我瞧着那个扶手还挺干净的。",
          DialogueId = 51011407,
          GUID = "7FB3A2F6",
          ImprPlusId = 1001,
          NextDialogue = 51011408
        },
        [51011408] = {
          Content = "不干净！那里我今天还没擦过，不能算干净……",
          DialogueId = 51011408,
          GUID = "7FB3A320",
          NextDialogue = 51011409,
          SpeakNpcId = 700340
        },
        [51011409] = {
          Content = "还有二楼的画框、书橱、落地灯……还有……",
          DialogueId = 51011409,
          GUID = "7FB3A34A",
          NextDialogue = 51011410,
          SpeakNpcId = 700340
        },
        [51011410] = {
          Content = "不要管我，拜托你……你就没有自己的事要忙吗？",
          DialogueId = 51011410,
          GUID = "7FB3A374",
          NextDialogue = 51011412,
          SpeakNpcId = 700340
        },
        [51011411] = {
          Content = "（让出道路。）",
          DialogueId = 51011411,
          GUID = "7FB3A39E",
          ImprPlusId = 1004,
          NextDialogue = 51011412
        },
        [51011412] = {
          Content = "（你识趣地耸耸肩，侧身让出一条道路，任由他徒劳奔忙。）",
          DialogueId = 51011412,
          GUID = "7FB3A3C8"
        },
        [51011501] = {
          Content = "好心人，求你帮帮我……给多少都可以……救救身无分文的老人家吧……",
          DialogueId = 51011501,
          GUID = "7FB3B262",
          SpeakNpcId = 700338
        },
        [51011601] = {
          Content = "末日将至啊……末日将至……",
          DialogueId = 51011601,
          GUID = "7FB3C2CA",
          SpeakNpcId = 700337
        },
        [51011701] = {
          Content = "哇，商户们工作得好认真！",
          DialogueId = 51011701,
          GUID = "7FB3D332",
          SpeakNpcId = 700336
        },
        [51011801] = {
          Content = "……",
          DialogueId = 51011801,
          GUID = "7FB3E39A",
          SpeakNpcId = 700339
        },
        [51011901] = {
          Content = "离我远一点……我什么都不知道！！",
          DialogueId = 51011901,
          GUID = "7FB3F402",
          SpeakNpcId = 700341
        },
        [51012001] = {
          Content = "……先别说话。这些台阶，还没擦干净。",
          DialogueId = 51012001,
          GUID = "7FB4046A",
          SpeakNpcId = 700340
        },
        [51012101] = {
          Content = "喵，喵喵！",
          DialogueId = 51012101,
          GUID = "7FB414D2",
          NextDialogue = 51012102,
          SpeakNpcId = 700334
        },
        [51012102] = {
          Content = "（离得老远，野猫就兴奋地叫着，一蹦一跳地朝你跑来。）",
          DialogueId = 51012102,
          GUID = "7FB414FC",
          NextDialogue = 51012103
        },
        [51012103] = {
          Content = "喵。",
          DialogueId = 51012103,
          GUID = "7FB41526",
          NextDialogue = 51012104,
          SpeakNpcId = 700334
        },
        [51012104] = {
          Content = "（它看起来很有精神，并不需要你陪它玩或者给它找吃的。而是围着你的脚转了两圈后跑向了休憩之所的方向，转头看着你，似乎想要你跟上去。） ",
          DialogueId = 51012104,
          GUID = "7FB41550",
          NextOptions = {
            [1] = 51012105,
            [2] = 51012106
          }
        },
        [51012105] = {
          Content = "（跟过去看看。）",
          DialogueId = 51012105,
          GUID = "7FB4157A"
        },
        [51012106] = {
          Content = "（以后再说。）",
          DialogueId = 51012106,
          GUID = "7FB415A4",
          Scripts = "SetOutport{FinishType{"Fail"}}"
        },
        [51012107] = {
          Content = "（野猫从休憩之所附近的草丛里叼出一条硬邦邦的冻鱼，歪头看着你，似乎那便是它的谢礼。）",
          DialogueId = 51012107,
          GUID = "7FB415CE",
          NextDialogue = 51012108
        },
        [51012108] = {
          Content = "（你捡起冻鱼，有什么叮叮当当地从冻鱼口中掉了出来——哦，那是几枚闪着暗淡光泽的铜币……）",
          DialogueId = 51012108,
          GUID = "7FB415F8",
          NextDialogue = 51012109
        },
        [51012109] = {
          Content = "你是记住了我的味道，所以给我准备了礼物吗？",
          DialogueId = 51012109,
          GUID = "7FB41622",
          NextDialogue = 51012110,
          SpeakNpcId = 100001
        },
        [51012110] = {
          Content = "喵——",
          DialogueId = 51012110,
          GUID = "7FB4164C",
          NextDialogue = 51012111,
          SpeakNpcId = 700335
        },
        [51012111] = {
          Content = "（野猫好似听懂了你的话一般长叫了一声，亲昵地用头蹭着你的脚。）",
          DialogueId = 51012111,
          GUID = "7FB41676",
          NextOptions = {
            [1] = 51012112,
            [2] = 51012113
          }
        },
        [51012112] = {
          Content = "谢谢你的好意。",
          DialogueId = 51012112,
          GUID = "7FB416A0",
          ImprPlusId = 1004,
          NextDialogue = 51012114
        },
        [51012113] = {
          Content = "给我找点更好的谢礼。",
          DialogueId = 51012113,
          GUID = "7FB416CA",
          ImprPlusId = 1005,
          NextDialogue = 51012114
        },
        [51012114] = {
          Content = "（野猫听罢点了点头，蹦跳着跑远了。虽然不知道它下次会给你带来什么，但你知道，接下来很长一段时间，你都会经常在休憩之所看到它了。）",
          DialogueId = 51012114,
          GUID = "7FB416F4"
        },
        [51012201] = {
          Content = "（既然它已经打算留在休憩之所，那就给它取个名字吧。）",
          DialogueId = 51012201,
          GUID = "7FB4253A"
        },
        [51012202] = {
          Content = "喵~喵——",
          DialogueId = 51012202,
          GUID = "7FB42564",
          NextDialogue = 51012203,
          SpeakNpcId = 888888
        },
        [51012203] = {
          Content = "（收到新名字后，它喵喵叫着围着你转圈，显然十分喜欢{catname}这个名字。）",
          DialogueId = 51012203,
          GUID = "7FB4258E",
          NextDialogue = 51012204
        },
        [51012204] = {
          Content = "好，那{catname}就是你以后的名字了。",
          DialogueId = 51012204,
          GUID = "7FB425B8",
          SpeakNpcId = 100001
        },
        [51100001] = {
          Content = "心诚不怕道路难，自有龙神保周全。前方崎岖污浊地，为还宏愿也向前、前、前面路过的那位有龙氏！留步、留步啊！",
          DialogueId = 51100001,
          GUID = "7FEC69EA"
        },
        [51100002] = {
          Content = "哎呀别左顾右盼了，老夫喊的就是你哇。",
          DialogueId = 51100002,
          GUID = "7FEC6A14",
          NextOptions = {
            [1] = 51100003,
            [2] = 51100006,
            [3] = 51100009
          },
          SpeakNpcId = 700319
        },
        [51100003] = {
          Content = "都有龙神护你周全了，为什么喊住我呢？",
          DialogueId = 51100003,
          GUID = "7FEC6A3E",
          ImprPlusId = 1208,
          NextDialogue = 51100004
        },
        [51100004] = {
          Content = "咳，龙神祂老人家是很忙的，又要帮我，又要帮他，要是一个没留神，没把我看住可怎么办？",
          DialogueId = 51100004,
          GUID = "7FEC6A68",
          NextDialogue = 51100005,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          }
        },
        [51100005] = {
          Content = "听天命前，多多少少也得尽点人事嘛！",
          DialogueId = 51100005,
          GUID = "7FEC6A92",
          NextDialogue = 51100015,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Talk01_End"
          }
        },
        [51100006] = {
          Content = "老先生，你遇到什么麻烦了吗？",
          DialogueId = 51100006,
          GUID = "7FEC6ABC",
          ImprPlusId = 1207,
          NextDialogue = 51100007
        },
        [51100007] = {
          Content = "好有礼貌的年轻人啊！我在这里站了半晌了，只有几个人愿意听我这个老骨头说的话。",
          DialogueId = 51100007,
          GUID = "7FEC6AE6",
          NextDialogue = 51100008,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Talk02_Start"
          }
        },
        [51100008] = {
          Content = "要是你能完完整整听我把话说完，还不跑，那就更好嘞！",
          DialogueId = 51100008,
          GUID = "7FEC6B10",
          NextDialogue = 51100015,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Talk02_End"
          }
        },
        [51100009] = {
          Content = "怪了，都死了那么久了……怎么还能看到我？",
          DialogueId = 51100009,
          GUID = "7FEC6B3A",
          ImprPlusId = 1210,
          NextDialogue = 51100010
        },
        [51100010] = {
          Content = "……",
          DialogueId = 51100010,
          GUID = "7FEC6B64",
          NextDialogue = 51100011,
          SpeakNpcId = 700319
        },
        [51100011] = {
          Content = "………………",
          DialogueId = 51100011,
          GUID = "7FEC6B8E",
          NextDialogue = 51100012,
          SpeakNpcId = 700319
        },
        [51100012] = {
          Content = "鬼啊！",
          DialogueId = 51100012,
          GUID = "7FEC6BB8",
          NextDialogue = 51100013,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Shock_Start"
          }
        },
        [51100013] = {
          Content = "开玩笑的，你看，我有影子也有脚。",
          DialogueId = 51100013,
          GUID = "7FEC6BE2",
          NextDialogue = 51100014,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700319:Shock_End"
          }
        },
        [51100014] = {
          Content = "唉哟……唉哟……要了我的老命了！下次别开这种玩笑了，就算把我吓死，我也不会把存款地址告诉你的！",
          DialogueId = 51100014,
          GUID = "7FEC6C0C",
          NextDialogue = 51100015,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Explain01_Start"
          }
        },
        [51100015] = {
          Content = "其实，是我有事要往尘漠石海跑一趟，但你瞧我，一大把年纪了，走到这里都够呛！",
          DialogueId = 51100015,
          GUID = "7FEC6C36",
          NextDialogue = 51100016,
          SpeakNpcId = 700319
        },
        [51100016] = {
          Content = "这一路上，先是半路杀出玄色狴犴伤人，老夫躲闪不及，本来已经认命，结果被冲出来执法的正统狴犴一尾巴丢出一丈远！",
          DialogueId = 51100016,
          GUID = "7FEC6C60",
          NextDialogue = 51100017,
          SpeakNpcId = 700319
        },
        [51100017] = {
          Content = "哎！我这脑袋脖子肩膀后背腰椎屁股胳膊腿哟！",
          DialogueId = 51100017,
          GUID = "7FEC6C8A",
          NextDialogue = 51100018,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Explain01_End"
          }
        },
        [51100018] = {
          Content = "岁月不饶人呐，要是放在年轻那会，站起来拍拍裤子也没事了，有胆子大的，还会趁狴犴执法的时候合照一张，够吹好几天了。",
          DialogueId = 51100018,
          GUID = "7FEC6CB4",
          NextDialogue = 51100019,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Sigh_Start"
          }
        },
        [51100019] = {
          Content = "但到了我这岁数，被黑狴犴咬一口，也就是两眼一闭，来生再做好汉，被白狴犴这一救，我这老骨头真要瘫在床上个把月喽……",
          DialogueId = 51100019,
          GUID = "7FEC6CDE",
          NextDialogue = 51100020,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100020] = {
          Content = "哦对了，我可没有说狴犴不好的意思，要是有个三长两短，那也是太皓的安排！太皓的安排怎么会错呢？你说呢，年轻人？",
          DialogueId = 51100020,
          GUID = "7FEC6D08",
          NextOptions = {
            [1] = 51100021,
            [2] = 51100023,
            [3] = 51100025
          },
          SpeakNpcId = 700319
        },
        [51100021] = {
          Content = "回家吧老先生，回家吧，现在外面太危险了。",
          DialogueId = 51100021,
          GUID = "7FEC6D32",
          ImprPlusId = 1207,
          NextDialogue = 51100022
        },
        [51100022] = {
          Content = "我也想哇，可如果在这里掉头，我就疑似对太皓不忠了！",
          DialogueId = 51100022,
          GUID = "7FEC6D5C",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100023] = {
          Content = "这么危险，还要坚持要出门，一定是有非常重要的事情吧？",
          DialogueId = 51100023,
          GUID = "7FEC6D86",
          ImprPlusId = 1209,
          NextDialogue = 51100024
        },
        [51100024] = {
          Content = "没想到你年纪轻轻，却是个知心人。人生中，总有几件事是不能退缩的。",
          DialogueId = 51100024,
          GUID = "7FEC6DB0",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Agree"
          }
        },
        [51100025] = {
          Content = "废话那么多，你不会是想碰瓷我吧？",
          DialogueId = 51100025,
          GUID = "7FEC6DDA",
          ImprPlusId = 1210,
          NextDialogue = 51100026
        },
        [51100026] = {
          Content = "胡说八道！碰瓷也得挑对象啊，老夫挑谁，也不会挑你这样满身绷带还在外面四处奔波的人啊！",
          DialogueId = 51100026,
          GUID = "7FEC6E04",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100027] = {
          Content = "总之，接下来前往尘漠石海的路只靠老夫自己是万万不可能了。",
          DialogueId = 51100027,
          GUID = "7FEC6E2E",
          NextDialogue = 51100028,
          SpeakNpcId = 700319
        },
        [51100028] = {
          Content = "所以啊，老夫候在这路边，就盼望着太皓保佑，送个古道热肠、身手了得，还不畏惧石海晶尘的勇士，把我安安全全地送到地方去……",
          DialogueId = 51100028,
          GUID = "7FEC6E58",
          NextDialogue = 51100029,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Confident_Start"
          }
        },
        [51100029] = {
          Content = "现在看来，那个人必定是你无疑了！",
          DialogueId = 51100029,
          GUID = "7FEC6E82",
          NextDialogue = 51100030,
          SpeakNpcId = 700319
        },
        [51100030] = {
          Content = "真是太皓保佑！太皓保佑啊！",
          DialogueId = 51100030,
          GUID = "7FEC6EAC",
          NextDialogue = 51100031,
          SpeakNpcId = 700319
        },
        [51100031] = {
          Content = "不过你放心，老夫不是不懂事的人。",
          DialogueId = 51100031,
          GUID = "7FEC6ED6",
          NextDialogue = 51100032,
          SpeakNpcId = 700319
        },
        [51100032] = {
          Content = "请神办事要献贡品，请人办事要给酬劳，把我送到地方，我一定会好好感谢你的！",
          DialogueId = 51100032,
          GUID = "7FEC6F00",
          NextOptions = {
            [1] = 51100033
          },
          RestartTag = 51100032,
          SpeakNpcId = 700319,
          TalkActionId = {
            [1] = "700319:Confident_End"
          }
        },
        [51100033] = {
          Content = "到底要不要付出时间和精力，护送老人前往一个危险之地呢。",
