        },
        [51100091] = {
          Content = "白龙神君真是仁慈！可凡是身在华胥者，皆要受到大风九章的约束，人的性情禀赋，依稀可能大概，还是得受此管教，不可随心而行吧……",
          DialogueId = 51100091,
          DisableMouth = 0,
          GUID = "7FEC78AE",
          IsBlack = 0,
          NextDialogue = 51100092,
          SpeakNpcId = 700319,
          bAllowClickSkipScript = false
        },
        [51100092] = {
          Content = "哦？那大风九章第九条，不也说要“垂聆天宪，恭肃为敬”？你先是冒犯于我，我念你神志不清，不予追究。",
          DialogueId = 51100092,
          DisableMouth = 0,
          GUID = "7FEC78D8",
          IsBlack = 0,
          NextDialogue = 51100093,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          bAllowClickSkipScript = false
        },
        [51100093] = {
          Content = "现在你神思清明，却又顶撞于我，该当何罪！",
          DialogueId = 51100093,
          DisableMouth = 0,
          GUID = "7FEC7902",
          IsBlack = 0,
          NextDialogue = 51100094,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          bAllowClickSkipScript = false
        },
        [51100094] = {
          Content = "这、这……",
          DialogueId = 51100094,
          DisableMouth = 0,
          GUID = "7FEC792C",
          IsBlack = 0,
          SpeakNpcId = 700319,
          bAllowClickSkipScript = false
        },
        [51100095] = {
          Content = "白龙神君发怒了！我要被狴犴执法了！救命啊！我只是嘴硬，其实也不想丢了老命啊！",
          DialogueId = 51100095,
          GUID = "7FEC7956",
          NextDialogue = 51100096,
          SpeakNpcId = 700319
        },
        [51100096] = {
          Content = "冷静点，仔细观察，这些狴犴的目标另有其人。",
          DialogueId = 51100096,
          GUID = "7FEC7980",
          NextDialogue = 51100097,
          SpeakNpcId = 100001
        },
        [51100097] = {
          Content = "{nickname}，又见面了！",
          DialogueId = 51100097,
          GUID = "7FEC79AA",
          NextDialogue = 51100098,
          SpeakNpcId = 700318
        },
        [51100098] = {
          Content = "这狴犴倒是会赶巧，只是这对手我已打到厌倦，劳烦你一回，帮我将他们驱赶干净吧！",
          DialogueId = 51100098,
          GUID = "7FEC79D4",
          SpeakNpcId = 700318
        },
        [51100104] = {
          Content = "究竟怎么了！白龙神君呢！白龙神君难道不保佑我了吗！",
          DialogueId = 51100104,
          GUID = "7FEC7AD0",
          NextDialogue = 51100105,
          SpeakNpcId = 700319
        },
        [51100105] = {
          Content = "这半路杀出的没头没脑没由来的家伙又是谁？",
          DialogueId = 51100105,
          GUID = "7FEC7AFA",
          NextDialogue = 51100106,
          SpeakNpcId = 700319
        },
        [51100106] = {
          Content = "这一切的一切的……到底怎么回事！",
          DialogueId = 51100106,
          GUID = "7FEC7B24",
          NextOptions = {
            [1] = 51100110,
            [2] = 51100107,
            [3] = 51100108,
            [4] = 51100109
          },
          SpeakNpcId = 700319
        },
        [51100107] = {
          Content = "你的一切症状都符合脑震荡的反应，你从来没碰到过真正的白龙神君。",
          DialogueId = 51100107,
          GUID = "7FEC7B4E",
          ImprPlusId = 1208,
          NextDialogue = 51100111
        },
        [51100108] = {
          Content = "当时你并非由白龙神君拯救，但你被这位过路人救下，捡回一条命，也是好事。",
          DialogueId = 51100108,
          GUID = "7FEC7B78",
          ImprPlusId = 1209,
          NextDialogue = 51100111
        },
        [51100109] = {
          Content = "我也不是你和白龙神君祈祷来的，但报酬我一样要收。",
          DialogueId = 51100109,
          GUID = "7FEC7BA2",
          ImprPlusId = 1206,
          NextDialogue = 51100111
        },
        [51100110] = {
          Content = "你猜我之前在笑什么？",
          DialogueId = 51100110,
          GUID = "7FEC7BCC",
          ImprPlusId = 1210,
          NextDialogue = 51100111
        },
        [51100111] = {
          Content = "我是谁？飘零人刻舟是也！当然，你要是还愿意称我为太皓，也不是不能照单全收！",
          DialogueId = 51100111,
          GUID = "7FEC7BF6",
          NextDialogue = 51100112,
          SpeakNpcId = 700318
        },
        [51100112] = {
          Content = "或者，你也可以把刚才的夸人话对着你救命恩人再说一遍？慈悲公允宽和……还有什么来着？",
          DialogueId = 51100112,
          GUID = "7FEC7C20",
          NextDialogue = 51100113,
          SpeakNpcId = 700318
        },
        [51100113] = {
          Content = "诶，老头儿，你还真的挺擅长夸人的！当初救下你时，你连自己是谁都说不出来，但那好听的话还是一箩筐一箩筐的，不比清醒时说的差！",
          DialogueId = 51100113,
          GUID = "7FEC7C4A",
          NextDialogue = 51100114,
          SpeakNpcId = 700318
        },
        [51100114] = {
          Content = "那、那我昏迷前看到的那些狴犴是……",
          DialogueId = 51100114,
          GUID = "7FEC7C74",
          NextDialogue = 51100115,
          SpeakNpcId = 700319
        },
        [51100115] = {
          Content = "看来你还不知道，常被狴犴“陪伴”的除了白龙神和应天尉，还有可能是被穷追不舍的飘零人。",
          DialogueId = 51100115,
          GUID = "7FEC7C9E",
          NextDialogue = 51100116,
          SpeakNpcId = 700318
        },
        [51100116] = {
          Content = "你你你你你你——",
          DialogueId = 51100116,
          GUID = "7FEC7CC8",
          NextDialogue = 51100117,
          SpeakNpcId = 700319
        },
        [51100117] = {
          Content = "怪不得怪不得！白龙神君才不会说什么人之天赋性情，只有你们这些法外狂徒，才满嘴的歪理邪说！",
          DialogueId = 51100117,
          GUID = "7FEC7CF2",
          NextDialogue = 51100118,
          SpeakNpcId = 700319
        },
        [51100118] = {
          Content = "可恨我一时被蒙蔽了双眼，竟没识出你的本来面目！",
          DialogueId = 51100118,
          GUID = "7FEC7D1C",
          NextDialogue = 51100119,
          SpeakNpcId = 700319
        },
        [51100119] = {
          Content = "喂！这么说就过分了吧！这老头儿，翻脸如翻书一般，你自己上下打量打量，能全须全尾地站在这，你还得谢我呢！",
          DialogueId = 51100119,
          GUID = "7FEC7D46",
          NextDialogue = 51100120,
          SpeakNpcId = 700318
        },
        [51100120] = {
          Content = "懒得和你掰扯，{nickname}，你怎么说？",
          DialogueId = 51100120,
          GUID = "7FEC7D70",
          NextOptions = {
            [1] = 51100125,
            [2] = 51100121
          },
          SpeakNpcId = 700318
        },
        [51100121] = {
          Content = "还是应该谢谢刻舟。",
          DialogueId = 51100121,
          GUID = "7FEC7D9A",
          ImprPlusId = 1207,
          NextDialogue = 51100122
        },
        [51100122] = {
          Content = "刻舟戏弄你确实不对，但不管怎么说，他是你的救命恩人，算上那枚叶子，他甚至准备多救你几次，不能和解吗？",
          DialogueId = 51100122,
          GUID = "7FEC7DC4",
          NextDialogue = 51100123,
          SpeakNpcId = 100001
        },
        [51100123] = {
          Content = "我自小被白龙神君和大风九章庇护长大，若没有狴犴奉天执法，还没遇见你，我就已经命丧玄色狴犴之口了。",
          DialogueId = 51100123,
          GUID = "7FEC7DEE",
          NextDialogue = 51100124,
          SpeakNpcId = 700319
        },
        [51100124] = {
          Content = "这飘零人或许救我一次，两次，三次，但和白龙神君相比，实在微不足道。我尊奉白龙神君，自然要和这群法外狂徒划清关系。",
          DialogueId = 51100124,
          GUID = "7FEC7E18",
          NextDialogue = 51100129,
          SpeakNpcId = 700319
        },
        [51100125] = {
          Content = "这未尝不是神的旨意。",
          DialogueId = 51100125,
          GUID = "7FEC7E42",
          ImprPlusId = 1208,
          NextDialogue = 51100126
        },
        [51100126] = {
          Content = "老先生认为生死都是太皓的安排，那么被飘零人救下自然也是白龙神君的旨意，从这个角度想，你理应坦然接受救命恩人是法外狂徒。",
          DialogueId = 51100126,
          GUID = "7FEC7E6C",
          NextDialogue = 51100127,
          SpeakNpcId = 100001
        },
        [51100127] = {
          Content = "嗯？乍一听把我都绕进去了，但飘零人，绝无可能被什么条条框框束缚。我救他，只是举手之劳，我戏弄他，也是因我看不惯他盲信。",
          DialogueId = 51100127,
          GUID = "7FEC7E96",
          NextDialogue = 51100128,
          SpeakNpcId = 700318
        },
        [51100128] = {
          Content = "我便弄不明白，这些人做什么要把自己迈出去的一步归功于上天的推动？ 人非草木，自己会动。你瞧他笃信白龙神，不也找了你护卫左右？",
          DialogueId = 51100128,
          GUID = "7FEC7EC0",
          NextDialogue = 51100129,
          SpeakNpcId = 700318
        },
        [51100129] = {
          Content = "放诞无礼！",
          DialogueId = 51100129,
          GUID = "7FEC7EEA",
          NextDialogue = 51100130,
          SpeakNpcId = 700319
        },
        [51100130] = {
          Content = "朽木脑袋！",
          DialogueId = 51100130,
          GUID = "7FEC7F14",
          NextDialogue = 51100131,
          SpeakNpcId = 700318
        },
        [51100131] = {
          Content = "……我尽力了，看来是不会出现握手言和的画面了。",
          DialogueId = 51100131,
          GUID = "7FEC7F3E",
          NextDialogue = 51100132,
          SpeakNpcId = 100001
        },
        [51100132] = {
          Content = "切！我才不愿将大好光阴浪费在这里，走吧，{nickname}，今日你我一定要好好切磋一场！",
          DialogueId = 51100132,
          GUID = "7FEC7F68",
          NextDialogue = 51100133,
          SpeakNpcId = 700318
        },
        [51100133] = {
          Content = "等等！",
          DialogueId = 51100133,
          GUID = "7FEC7F92",
          NextDialogue = 51100134,
          SpeakNpcId = 700319
        },
        [51100134] = {
          Content = "（老者将两份酬劳分别交给了你与刻舟。）",
          DialogueId = 51100134,
          GUID = "7FEC7FBC",
          NextDialogue = 51100135
        },
        [51100135] = {
          Content = "大风九章第二条，“夫人根基，定文为信”，我答应要给少年人酬劳，自然不会言而无信。",
          DialogueId = 51100135,
          GUID = "7FEC7FE6",
          NextDialogue = 51100136,
          SpeakNpcId = 700319
        },
        [51100136] = {
          Content = "大风九章第六条，“以我及人，制宜为义”，我虽厌憎你，但确实承你恩惠，这酬劳，就当做你我两清，从此井水不犯河水。",
          DialogueId = 51100136,
          GUID = "7FEC8010",
          NextDialogue = 51100137,
          SpeakNpcId = 700319
        },
        [51100137] = {
          Content = "（说完这句话，老者便不愿再假手他人，一个人迟缓却坚定地踏上了回程的道路，你不便跟上，默默目送他远去。）",
          DialogueId = 51100137,
          GUID = "7FEC803A",
          NextDialogue = 51100138
        },
        [51100138] = {
          Content = "说起来，最近许久不见你人影，为何出现在这里？",
          DialogueId = 51100138,
          GUID = "7FEC8064",
          NextDialogue = 51100139,
          SpeakNpcId = 100001
        },
        [51100139] = {
          Content = "烛阴之灾日益泛滥，这地方本来有悬衡派的香塔镇着，但最近越来越不顶用了，这老头儿会在里面迷路也并非偶然。",
          DialogueId = 51100139,
          GUID = "7FEC808E",
          NextDialogue = 51100140,
          SpeakNpcId = 700318
        },
        [51100140] = {
          Content = "被尘漠侵蚀的地域愈发扩大，这才让他走到天黑也走不出来。",
          DialogueId = 51100140,
          GUID = "7FEC80B8",
          NextDialogue = 51100141,
          SpeakNpcId = 700318
        },
        [51100141] = {
          Content = "我想着师兄说不定会奉命前来调查，才总是守在这里，没想到碰到这老头迷失其中，这人嘴皮子利索，倒也有趣。可惜……",
          DialogueId = 51100141,
          GUID = "7FEC80E2",
          NextDialogue = 51100142,
          SpeakNpcId = 700318
        },
        [51100142] = {
          Content = "（刻舟将钱袋子抛了抛，最终丢进你的怀中。）",
          DialogueId = 51100142,
          GUID = "7FEC810C",
          NextDialogue = 51100143
        },
        [51100143] = {
          Content = "这东西能换来好几瓶绝顶佳酿，我本应高兴……但我救人本不图报酬，不如给你。",
          DialogueId = 51100143,
          GUID = "7FEC8136",
          NextDialogue = 51100144,
          SpeakNpcId = 700318
        },
        [51100144] = {
          Content = "说来好笑，高高在上的龙神救人，换来的就是顶礼膜拜，感恩戴德，而飘零人救人，却总是冷嘲热讽，潦草打发。",
          DialogueId = 51100144,
          GUID = "7FEC8160",
          NextOptions = {
            [1] = 51100146,
            [2] = 51100145
          },
          SpeakNpcId = 700318
        },
        [51100145] = {
          Content = "但你们救下的生命都是等价的。",
          DialogueId = 51100145,
          GUID = "7FEC818A",
          ImprPlusId = 1207,
          NextDialogue = 51100147
        },
        [51100146] = {
          Content = "你觉得问心无愧，那就是值得。",
          DialogueId = 51100146,
          GUID = "7FEC81B4",
          ImprPlusId = 1209,
          NextDialogue = 51100147
        },
        [51100147] = {
          Content = "哈！我就知道你是同道中人，不消你说，我自然明白！",
          DialogueId = 51100147,
          GUID = "7FEC81DE",
          NextDialogue = 51100148,
          SpeakNpcId = 700318
        },
        [51100148] = {
          Content = "不管了，少思虑那些三天以后才会发生的事情，趁着良辰美景，不如对剑高歌！我想想，此情此景，再没比这一句更合适的了——",
          DialogueId = 51100148,
          GUID = "7FEC8208",
          NextDialogue = 51100149,
          SpeakNpcId = 700318
        },
        [51100149] = {
          Content = "梦亦妄生颠倒想，",
          DialogueId = 51100149,
          GUID = "7FEC8232",
          NextDialogue = 51100150,
          SpeakNpcId = 700318
        },
        [51100150] = {
          Content = "何如明月自由人！",
          DialogueId = 51100150,
          GUID = "7FEC825C",
          SpeakNpcId = 700318
        },
        [51101001] = {
          Content = "这次借的也不是一笔小数目啊……",
          DialogueId = 51101001,
          GUID = "7FED0DFA",
          SpeakNpcId = 700320
        },
        [51101002] = {
          Content = "那边两个人好像在吵什么东西，小仆从小仆从，我们快去阻止他们吧！",
          DialogueId = 51101002,
          GUID = "7FED0E24",
          SpeakNpcId = 900003
        },
        [51101003] = {
          Content = "来，这里是您的借贷契书，确认无误就在这里签字画押吧。",
          DialogueId = 51101003,
          GUID = "7FED0E4E",
          NextDialogue = 51101004,
          SpeakNpcId = 700320
        },
        [51101004] = {
          Content = "这次借的也不是一笔小数目啊。怎么，又想上哪里去看看了？",
          DialogueId = 51101004,
          GUID = "7FED0E78",
          NextDialogue = 51101005,
          SpeakNpcId = 700320
        },
        [51101005] = {
          Content = "哈哈，还是您懂我！这次啊，我想再去维德弗尼尔山那儿走一趟。山里的孩子许久没见我，怕是早就在盼着我了。",
          DialogueId = 51101005,
          GUID = "7FED0EA2",
          NextDialogue = 51101006,
          SpeakNpcId = 700321
        },
        [51101006] = {
          Content = "您还是一点没变啊。按照规定，这样一笔数额的借款必须留下贵重抵押物，您能接受吗？",
          DialogueId = 51101006,
          GUID = "7FED0ECC",
          NextDialogue = 51101007,
          SpeakNpcId = 700320
        },
        [51101007] = {
          Content = "晓得，就和以前一样嘛。",
          DialogueId = 51101007,
          GUID = "7FED0EF6",
          NextDialogue = 51101008,
          SpeakNpcId = 700321
        },
        [51101008] = {
          Content = "什么嘛，原来只是借钱啊，没意思没意思……",
          DialogueId = 51101008,
          GUID = "7FED0F20",
          NextDialogue = 51101009,
          SpeakNpcId = 900003
        },
        [51101009] = {
          Content = "（白扫兴地叹了口气，刚拉着你准备转身离开，就听到远处那名男子远远叫住了你们。他一跑一喘地赶到你的面前。）",
          DialogueId = 51101009,
          GUID = "7FED0F4A",
          NextDialogue = 51101010
        },
        [51101010] = {
          Content = "呼……呼……二位留步。",
          DialogueId = 51101010,
          GUID = "7FED0F74",
          NextDialogue = 51101011,
          SpeakNpcId = 700321
        },
        [51101011] = {
          Content = "自我介绍一下，我叫赵谦，是名织星客。",
          DialogueId = 51101011,
          GUID = "7FED0F9E",
          NextDialogue = 51101012,
          SpeakNpcId = 700321
        },
        [51101012] = {
          Content = "听闻二位少侠是百年春请来的武力高强的贵客，那个……若是二位得闲，可否请二位保护我走一遭，取一趟货？我会给报酬的！",
          DialogueId = 51101012,
          GUID = "7FED0FC8",
          NextOptions = {
            [1] = 51101013,
            [2] = 51101015
          },
          SpeakNpcId = 700321
        },
        [51101013] = {
          Content = "那我就帮帮你吧。",
          DialogueId = 51101013,
          GUID = "7FED0FF2",
          ImprPlusId = 1207,
          NextDialogue = 51101014
        },
        [51101014] = {
          Content = "太好了。放心，报酬绝对亏待不了你们。",
          DialogueId = 51101014,
          GUID = "7FED101C",
          NextDialogue = 51101017,
          SpeakNpcId = 700321
        },
        [51101015] = {
          Content = "你都要借钱了，还请得起护卫吗？",
          DialogueId = 51101015,
          GUID = "7FED1046",
          ImprPlusId = 1206,
          NextDialogue = 51101016
        },
        [51101016] = {
          Content = "古话说得好，千金散尽还复来嘛。钱这东西啊，只是个身外之物。要是为了省钱误了生意，那才是捡了芝麻丢了西瓜。",
          DialogueId = 51101016,
          GUID = "7FED1070",
          NextDialogue = 51101017,
          SpeakNpcId = 700321
        },
        [51101017] = {
          Content = "烛阴之灾的遗祸还遍布烟津渡，我人受点伤是小，货物丢了可就麻烦大了。",
          DialogueId = 51101017,
          GUID = "7FED109A",
          NextDialogue = 51101018,
          SpeakNpcId = 700321
        },
        [51101018] = {
          Content = "我听锦鲤皎皎说，织星客都是一群跑到大陆各个地方做生意的家伙，那你也一定去过很多地方吧？",
          DialogueId = 51101018,
          GUID = "7FED10C4",
          NextDialogue = 51101019,
          SpeakNpcId = 900003
        },
        [51101019] = {
          Content = "算不上多吧，也就去过各个国家的主要城市而已，阿特拉西亚大陆上，还有很多边边角角的村镇我没去过呢。",
          DialogueId = 51101019,
          GUID = "7FED10EE",
          NextDialogue = 51101020,
          SpeakNpcId = 700321
        },
        [51101020] = {
          Content = "那事情结束后，除了工钱，你还要跟本魔王大人讲讲你在其他国家碰到的好玩的事哦！",
          DialogueId = 51101020,
          GUID = "7FED1118",
          NextDialogue = 51101021,
          SpeakNpcId = 900003
        },
        [51101021] = {
          Content = "好嘞，没问题。那我们现在出发吧，先去农家处取我之前定好的一批蜜饯果子。",
          DialogueId = 51101021,
          GUID = "7FED1142",
          SpeakNpcId = 700321
        },
        [51101022] = {
          Content = "是玄色狴犴，有劳二位少侠了。",
          DialogueId = 51101022,
          Duration = 4,
          GUID = "7FED116C",
          NextDialogue = 51101023,
          SpeakNpcId = 700321
        },
        [51101023] = {
          Content = "哼哼，你就在本魔王大人身后躲好吧——小仆从，揍扁它们！",
          DialogueId = 51101023,
          Duration = 7,
          GUID = "7FED1196",
          SpeakNpcId = 200002
        },
        [51101024] = {
          Content = "身手果真了得！我们接着赶路吧，就在前方不远了。",
          DialogueId = 51101024,
          Duration = 7,
          GUID = "7FED11C0",
          SpeakNpcId = 700321
        },
        [51101025] = {
          Content = "二位在此稍事休息，我去找农家付个钱。",
          DialogueId = 51101025,
          GUID = "7FED11EA",
          NextDialogue = 51101026,
          SpeakNpcId = 700321
        },
        [51101026] = {
          Content = "一段时间后……",
          DialogueId = 51101026,
          GUID = "7FED1214",
          NextDialogue = 51101027
        },
        [51101027] = {
          Content = "取好了，这蜜饯果子可是我们华胥的特产，来尝一口呗。",
          DialogueId = 51101027,
          GUID = "7FED123E",
          NextDialogue = 51101028,
          SpeakNpcId = 700321
        },
        [51101028] = {
          Content = "咳，好甜……",
          DialogueId = 51101028,
          GUID = "7FED1268",
          NextDialogue = 51101029,
          SpeakNpcId = 100001
        },
        [51101029] = {
          Content = "慢点嚼，刚进口是会有点齁，吃到后面就习惯了。",
          DialogueId = 51101029,
          GUID = "7FED1292",
          NextDialogue = 51101030,
          SpeakNpcId = 700321
        },
        [51101030] = {
          Content = "唔，感觉是个挑人的零食呀，那个维什么什么山的人会买吗？",
          DialogueId = 51101030,
          GUID = "7FED12BC",
          NextDialogue = 51101031,
          SpeakNpcId = 900003
        },
        [51101031] = {
          Content = "嘿嘿，维德弗尼尔山脉那边既没多少水果，也没什么调味，更重要的是蜜饯耐储存不怕变质，在那儿很受欢迎呢。",
          DialogueId = 51101031,
          GUID = "7FED12E6",
          NextDialogue = 51101032,
          SpeakNpcId = 700321
        },
        [51101032] = {
          Content = "好了，吃完我们就去下一个地方吧。",
          DialogueId = 51101032,
          GUID = "7FED1310",
          SpeakNpcId = 700321
        },
        [51101033] = {
          Content = "一段时间后……",
          DialogueId = 51101033,
          GUID = "7FED133A",
          NextDialogue = 51101034
        },
        [51101034] = {
          Content = "诶？你怎么抱了一堆石头回来呀。",
          DialogueId = 51101034,
          GUID = "7FED1364",
          NextDialogue = 51101035,
          SpeakNpcId = 900003
        },
        [51101035] = {
          Content = "这可不是普通的石头，而是在烟津渡南边的湖里捞出来打磨后的温凉玉。",
          DialogueId = 51101035,
          GUID = "7FED138E",
          NextDialogue = 51101036,
          SpeakNpcId = 700321
        },
        [51101036] = {
          Content = "我这次准备从西北边的冰原借道去维德弗尼尔山，那冰原又乱又冷，每天都有人冻死在那。",
          DialogueId = 51101036,
          GUID = "7FED13B8",
          NextDialogue = 51101037,
          SpeakNpcId = 700321
        },
        [51101037] = {
          Content = "而温凉玉烧过之后就会发热一段时间，正好放在怀里暖和暖和身子。我在那卖过很多次了，抢手得很。",
          DialogueId = 51101037,
          GUID = "7FED13E2",
          NextDialogue = 51101038,
          SpeakNpcId = 700321
        },
        [51101038] = {
          Content = "这次买了不少，希望能帮到更多人吧……",
          DialogueId = 51101038,
          GUID = "7FED140C",
          NextDialogue = 51101039,
          SpeakNpcId = 700321
        },
        [51101039] = {
          Content = "好了好了，不说这些让人难过的事了，赶紧把东西搬到码头上吧。",
          DialogueId = 51101039,
          GUID = "7FED1436",
          SpeakNpcId = 700321
        },
        [51101040] = {
          Content = "辛苦啦，这一路上多亏了你们，才走得这么顺利。",
          DialogueId = 51101040,
          GUID = "7FED1460",
          NextDialogue = 51101041,
          SpeakNpcId = 700321
        },
        [51101041] = {
          Content = "来，我看看兜里的钱还剩多少……算了不数了，全给你们当报酬吧，毕竟拉着你们跟我跑东跑西的，天都黑了。",
          DialogueId = 51101041,
          GUID = "7FED148A",
          NextDialogue = 51101042,
          SpeakNpcId = 700321
        },
        [51101042] = {
          Content = "这么大方，那我就不客气啦！",
          DialogueId = 51101042,
          GUID = "7FED14B4",
          NextDialogue = 51101043,
          SpeakNpcId = 900003
        },
        [51101043] = {
          Content = "100，200，300……这也没多少嘛。",
          DialogueId = 51101043,
          GUID = "7FED14DE",
          NextDialogue = 51101044,
          SpeakNpcId = 900003
        },
        [51101044] = {
          Content = "啊哈哈……抱歉抱歉。我身上也只剩下一点路费了。",
          DialogueId = 51101044,
          GUID = "7FED1508",
          NextDialogue = 51101045,
          SpeakNpcId = 700321
        },
        [51101045] = {
          Content = "感觉你做织星客也有段时间了，为什么还要借钱做生意呢？",
          DialogueId = 51101045,
          GUID = "7FED1532",
          NextDialogue = 51101046,
          SpeakNpcId = 100001
        },
        [51101046] = {
          Content = "对哦，白见过的那些借钱的家伙都是一个个嘴上哭着穷，实际上藏了不少好宝贝！快，让白看看你压箱底的小金库！",
          DialogueId = 51101046,
          GUID = "7FED155C",
          NextDialogue = 51101047,
          SpeakNpcId = 900003
        },
        [51101047] = {
          Content = "好机灵的皎皎，那就给你们看看吧，要是有喜欢的，尽管拿去。",
          DialogueId = 51101047,
          GUID = "7FED1586",
          NextDialogue = 51101048,
          SpeakNpcId = 700321
        },
        [51101048] = {
          Content = "这都是些什么哇，一块碎掉的小珍珠……还有一朵干巴巴的花？想拿这些垃圾敷衍魔王大人，拿回去拿回去！",
          DialogueId = 51101048,
          GUID = "7FED15B0",
          NextOptions = {
            [1] = 51101049,
            [2] = 51101051
          },
          SpeakNpcId = 900003
        },
        [51101049] = {
          Content = "我想，这些东西的价值，在于它们背后的故事，对吗？",
          DialogueId = 51101049,
          GUID = "7FED15DA",
          ImprPlusId = 1209,
          NextDialogue = 51101050
        },
        [51101050] = {
          Content = "好眼力！",
          DialogueId = 51101050,
          GUID = "7FED1604",
          NextDialogue = 51101053,
          SpeakNpcId = 700321
        },
        [51101051] = {
          Content = "看来不打你一顿，你是不会承认自己其实是亿万富翁了。",
          DialogueId = 51101051,
          GUID = "7FED162E",
          ImprPlusId = 1210,
          NextDialogue = 51101052
        },
        [51101052] = {
          Content = "少侠收手，收手。听我说完。",
          DialogueId = 51101052,
          GUID = "7FED1658",
          NextDialogue = 51101053,
          SpeakNpcId = 700321
        },
        [51101053] = {
          Content = "这些是我赚到的最贵重的宝贝了，二位且听我慢慢道来。",
          DialogueId = 51101053,
          GUID = "7FED1682",
          NextDialogue = 51101054,
          SpeakNpcId = 700321
        },
        [51101054] = {
          Content = "这珍珠，是我在卢卡一位画家手里买到的。我本想在那里买点颜料带回华胥卖，却在画具店前碰到了一位徘徊的年轻人。",
          DialogueId = 51101054,
          GUID = "7FED16AC",
          NextDialogue = 51101055,
          SpeakNpcId = 700321
        },
        [51101055] = {
          Content = "一把没剩几根毛的画笔插在他乱糟糟的头发里，全身上下没有一处不沾着五颜六色的颜料，卢卡潮湿的空气让我离得老远都能闻到他身上散发出来的异味。",
          DialogueId = 51101055,
          GUID = "7FED16D6",
          NextDialogue = 51101056,
          SpeakNpcId = 700321
        },
        [51101056] = {
          Content = "呕呃……",
          DialogueId = 51101056,
          GUID = "7FED1700",
          NextDialogue = 51101057,
          SpeakNpcId = 900003
        },
        [51101057] = {
          Content = "哈哈哈，我当时也差不多这个反应。可能艺术家多少都会有些另类，我这种粗人是理解不了，但我能理解他眼神中的渴望。",
          DialogueId = 51101057,
          GUID = "7FED172A",
          NextDialogue = 51101058,
          SpeakNpcId = 700321
        },
        [51101058] = {
          Content = "他就那样在店门口从左边走到右边，抬头看看店内的颜料，又从右边走到左边，看看店内的画布。",
          DialogueId = 51101058,
          GUID = "7FED1754",
          NextDialogue = 51101059,
          SpeakNpcId = 700321
        },
        [51101059] = {
          Content = "最后他摸了摸口袋，叹了口气就转身要走，我这时候很快啊，立马过去拦住了他。",
          DialogueId = 51101059,
          GUID = "7FED177E",
          NextDialogue = 51101060,
          SpeakNpcId = 700321
        },
        [51101060] = {
          Content = "聊了一会我发现，我果然听不懂他讲的光泽、饱和、构图之类的专业术语。但我能听懂他是一位上不起学、买不起画具却想追求艺术的苦孩子。",
          DialogueId = 51101060,
          GUID = "7FED17A8",
          NextDialogue = 51101061,
          SpeakNpcId = 700321
        },
        [51101061] = {
          Content = "那不是我第一次去卢卡，也不是我第一次碰到穷画家，但却是我第一次看到一个闪闪发光的人。",
          DialogueId = 51101061,
          GUID = "7FED17D2",
          NextDialogue = 51101062,
          SpeakNpcId = 700321
        },
        [51101062] = {
          Content = "闪闪发光？卢卡的颜料这么厉害，都能反光了！",
          DialogueId = 51101062,
          GUID = "7FED17FC",
          NextDialogue = 51101063,
          SpeakNpcId = 900003
        },
        [51101063] = {
          Content = "不，我说的是眼神中的那种感觉。我喜欢他那充满朝气与希望的样子，就像华胥的年轻人一样。",
          DialogueId = 51101063,
          GUID = "7FED1826",
          NextDialogue = 51101064,
          SpeakNpcId = 700321
        },
        [51101064] = {
          Content = "也许是我羡慕那个样子，也许是我太久没回华胥了，结果就是我把那趟赚到的钱基本都给了他，他过意不去，就把他妈妈的珍珠手链给了我。",
          DialogueId = 51101064,
          GUID = "7FED1850",
          NextDialogue = 51101065,
          SpeakNpcId = 700321
        },
        [51101065] = {
          Content = "后来我去卢卡做生意都会顺路看看他，每次看到他获得新的成就，都能让我感到十分欣慰。",
          DialogueId = 51101065,
          GUID = "7FED187A",
          NextDialogue = 51101066,
          SpeakNpcId = 700321
        },
        [51101066] = {
          Content = "唯一可惜的是他送我的手链，被一场暴风雨卷进了海里，就剩下这一颗了。",
          DialogueId = 51101066,
          GUID = "7FED18A4",
          NextDialogue = 51101067,
          SpeakNpcId = 700321
        },
        [51101067] = {
          Content = "（赵谦讪讪的笑着，随后又用手小心翼翼地捧起那朵泛黄枯死的花。）",
          DialogueId = 51101067,
          GUID = "7FED18CE",
          NextDialogue = 51101068
        },
        [51101068] = {
          Content = "这朵花的故事说起来倒也简单，那时我在赫墨的沙漠中碰到了一名脱水的小姑娘。",
          DialogueId = 51101068,
          GUID = "7FED18F8",
          NextDialogue = 51101069,
          SpeakNpcId = 700321
        },
        [51101069] = {
          Content = "那地方偏得很，来不及送到附近的大型聚落，所以求医问路，安置小姑娘都比较麻烦。费了好一番功夫才救了回来。",
          DialogueId = 51101069,
          GUID = "7FED1922",
          NextDialogue = 51101070,
          SpeakNpcId = 700321
        },
        [51101070] = {
          Content = "后来我从小姑娘那了解到，她瘫倒的那片沙漠经常有人脱水而死，但为了生存，人们还是一个接一个地走入茫茫黄沙。",
          DialogueId = 51101070,
          GUID = "7FED194C",
          NextDialogue = 51101071,
          SpeakNpcId = 700321
        },
        [51101071] = {
          Content = "我救不了他们所有人，但花点钱雇人多找点水源还是能做到的。这朵花，便是小姑娘从那些水源蔓延出的绿洲中采下的。",
          DialogueId = 51101071,
          GUID = "7FED1976",
          NextDialogue = 51101072,
          SpeakNpcId = 700321
        },
        [51101072] = {
          Content = "这么一想，我这大半辈子虽然跑过不少地方，但赚的钱基本都在路上花掉了啊，哈哈哈哈哈。",
          DialogueId = 51101072,
          GUID = "7FED19A0",
          NextDialogue = 51101073,
          SpeakNpcId = 700321
        },
        [51101073] = {
          Content = "不过钱嘛，没了还能再赚，为了理想辛苦点也是值得的。",
          DialogueId = 51101073,
          GUID = "7FED19CA",
          NextDialogue = 51101074,
          SpeakNpcId = 700321
        },
        [51101074] = {
          Content = "理想？",
          DialogueId = 51101074,
          GUID = "7FED19F4",
          NextDialogue = 51101075,
          SpeakNpcId = 900003
        },
        [51101075] = {
          Content = "嗯，织星客最早的理想，也是最天真的理想。",
          DialogueId = 51101075,
          GUID = "7FED1A1E",
          NextDialogue = 51101076,
          SpeakNpcId = 700321
        },
        [51101076] = {
          Content = "你们看我指的这是什么？",
          DialogueId = 51101076,
          GUID = "7FED1A48",
          NextDialogue = 51101077,
          SpeakNpcId = 700321
        },
        [51101077] = {
          Content = "我知道我知道，是星星！",
          DialogueId = 51101077,
          GUID = "7FED1A72",
          NextDialogue = 51101078,
          SpeakNpcId = 900003
        },
        [51101078] = {
          Content = "我把它连起来呢？",
          DialogueId = 51101078,
          GUID = "7FED1A9C",
          NextDialogue = 51101079,
          SpeakNpcId = 700321
        },
        [51101079] = {
          Content = "唔嗯……",
          DialogueId = 51101079,
          GUID = "7FED1AC6",
          NextDialogue = 51101080,
          SpeakNpcId = 900003
        },
        [51101080] = {
          Content = "连起来是天象仪座，我们常常用它来确认方向。而这里连起来便是织星者座，也是我们织星客名称的由来。",
          DialogueId = 51101080,
          GUID = "7FED1AF0",
          NextDialogue = 51101081,
          SpeakNpcId = 700321
        },
        [51101081] = {
          Content = "阿特拉西亚大陆上的各个国家，城镇，就像这天上的星星一样，有的璀璨耀眼，有的黯淡无光。但它们都在那里。",
          DialogueId = 51101081,
          GUID = "7FED1B1A",
          NextDialogue = 51101082,
          SpeakNpcId = 700321
        },
        [51101082] = {
          Content = "也许看上去距离很远，彼此孤立，但只要连接起来，便会组成全新的“星座”。而我们织星客的足迹便是将这些“星星”连起来的线。",
          DialogueId = 51101082,
          GUID = "7FED1B44",
          NextDialogue = 51101083,
          SpeakNpcId = 700321
        },
        [51101083] = {
          Content = "遥远的过去，这片土地第一次响起人类的啼哭，他们一无所有，只有头顶这片星空。",
          DialogueId = 51101083,
          GUID = "7FED1B6E",
          NextDialogue = 51101084,
          SpeakNpcId = 700321
        },
        [51101084] = {
          Content = "未来的某天，也许人类又会回到一无所有的状态，但那些被织星客连起来的“线”并不会因此断掉。",
          DialogueId = 51101084,
          GUID = "7FED1B98",
          NextDialogue = 51101085,
          SpeakNpcId = 700321
        },
        [51101085] = {
          Content = "商品、文明与知识，将沿着这些线送到大陆的各个角落，送到那些需要它们的人手中。我们大地上的“群星”，也会变得越来越耀眼。",
          DialogueId = 51101085,
          GUID = "7FED1BC2",
          NextDialogue = 51101086,
          SpeakNpcId = 700321
        },
        [51101086] = {
          Content = "（赵谦说着说着笑了起来——恰巧碰上岸边传来的，悠长的鸣笛声。你想起他说过的“闪闪发光的人”，而此时此刻眼前的这位织星客，眼底似乎也有什么在闪闪发光。）",
          DialogueId = 51101086,
          GUID = "7FED1BEC",
          NextDialogue = 51101087
        },
        [51101087] = {
          Content = "船到了，我也该走了。希望未来的某天，我们能在这片大陆的某个角落重逢。",
          DialogueId = 51101087,
          GUID = "7FED1C16",
          NextDialogue = 51101088,
          SpeakNpcId = 700321
        },
        [51101088] = {
          Content = "后会有期。",
          DialogueId = 51101088,
          GUID = "7FED1C40",
          NextOptions = {
            [1] = 51101089
          },
          SpeakNpcId = 700321
        },
        [51101089] = {
          Content = "后会有期。",
          DialogueId = 51101089,
          GUID = "7FED1C6A"
        },
        [51101090] = {
          Content = "哦呦，这码头上货的地方怎么被这些小家伙占住了。咱们一块赶走它们吧。",
          DialogueId = 51101090,
          GUID = "7FED1C94",
          NextDialogue = 51101091,
          SpeakNpcId = 700321
        },
        [51101091] = {
          Content = "去去，呼略，去去，我们要往这放东西呢。",
          DialogueId = 51101091,
          GUID = "7FED1CBE",
          SpeakNpcId = 700321
        },
        [51102001] = {
          Camera = "645.011719,215.524414,95.914062,0.000001,-6.599854,-162.398209,35.0,651.573547,false,Manual,2.8",
          Content = "二位英雄请留步。",
