        [51103011] = {
          Content = "刚才我面向那边的时候，这牵机方枢的震动明显比其他方向要强一些。难道这震动，是在为我指明方向？",
          DialogueId = 51103011,
          GUID = "7FEE576A",
          NextDialogue = 51103012,
          SpeakNpcId = 100001
        },
        [51103012] = {
          Content = "哇——小仆从，那个方向该不会藏着什么大宝贝？！我们赶紧去看看吧！",
          DialogueId = 51103012,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "7FEE5794",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          }
        },
        [51103013] = {
          Camera = "-273.101562,182.818359,178.920898,0.00004,-6.843535,-26.529842,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "公尚师傅，你怎么在这？",
          DialogueId = 51103013,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FEE57BE",
          LookAt = {
            [1] = "100001:n(700323)",
            [2] = "200002:n(700323)"
          },
          NextDialogue = 51103014,
          SpeakNpcId = 100001
        },
        [51103014] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "大惊小怪的干什么？",
          DialogueId = 51103014,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FEE57E8",
          LookAt = {
            [1] = "700323:n(100001)"
          },
          NextDialogue = 51103015,
          SpeakNpcId = 700323
        },
        [51103015] = {
          Content = "我腿脚不好，懒得走动。察觉你们到了附近，便用牵机方枢指引你们过来。如何？这只是它千般妙用中的一种，要论其中更多门道……",
          DialogueId = 51103015,
          GUID = "7FEE5812",
          NextDialogue = 51103016,
          SpeakNpcId = 700323
        },
        [51103016] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "还以为有什么大宝贝，原来是你……没劲。",
          DialogueId = 51103016,
          GUID = "7FEE583C",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 51103017,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Sigh_Start"
          }
        },
        [51103017] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "叫我们过来，就是为了说这些吗？",
          DialogueId = 51103017,
          GUID = "7FEE5866",
          NextDialogue = 51103018,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51103018] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "唉，连机关的使用说明都不愿意听完。现在的年轻人，沉不下心来研究学问，着实浮躁啊。",
          DialogueId = 51103018,
          GUID = "7FEE5890",
          LookAt = {
            [1] = "200002:n(700323)"
          },
          NextDialogue = 51103019,
          SpeakNpcId = 700323,
          TalkActionId = {
            [1] = "200002:Sigh_End"
          }
        },
        [51103019] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我们小仆从日理万机，你再不说正题，我们可就要走了。",
          DialogueId = 51103019,
          GUID = "7FEE58BA",
          NextDialogue = 51103020,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Confident_Start"
          }
        },
        [51103020] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哎哎，可别走——",
          DialogueId = 51103020,
          GUID = "7FEE58E4",
          NextDialogue = 51103021,
          SpeakNpcId = 700323
        },
        [51103021] = {
          Content = "你二位怎么说也是机枢派荣誉学徒了。既然与我机枢派有缘，那我这引路人可得担起责任，让你们一品机枢之乐。",
          DialogueId = 51103021,
          GUID = "7FEE590E",
          NextDialogue = 51103022,
          SpeakNpcId = 700323
        },
        [51103022] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我在这里布置了数处机枢机关，皆为匠心打造，各有精妙设计。怎么样，是不是心动了，想赶紧体验一把？",
          DialogueId = 51103022,
          GUID = "7FEE5938",
          NextOptions = {
            [1] = 51103023,
            [2] = 51103024
          },
          SpeakNpcId = 700323
        },
        [51103023] = {
          Content = "呃，这个嘛……",
          DialogueId = 51103023,
          GUID = "7FEE5939",
          ImprPlusId = 1204,
          NextDialogue = 51103025
        },
        [51103024] = {
          Content = "没什么更实质性的好处吗？",
          DialogueId = 51103024,
          GUID = "7FEE5940",
          ImprPlusId = 1201,
          NextDialogue = 51103025
        },
        [51103025] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "唉，就知道你们年轻人会这样。",
          DialogueId = 51103025,
          GUID = "7FEE5962",
          NextDialogue = 51103026,
          SpeakNpcId = 700323,
          TalkActionId = {
            [1] = "700323:Disagree"
          }
        },
        [51103026] = {
          Content = "根据我收徒这么多年来的碰壁经验，没什么好处，你们年轻人是不会上钩的。放心，奖励我早就准备好了。",
          DialogueId = 51103026,
          GUID = "7FEE598C",
          NextDialogue = 51103027,
          SpeakNpcId = 700323
        },
        [51103027] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那就勉强答应你吧。",
          DialogueId = 51103027,
          GUID = "7FEE59B6",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [51103028] = {
          Content = "我们现在玩的这个很简单，找到附近的机枢球，用你手里的牵机方枢把它们引到这个坑里就行，试试看。",
          DialogueId = 51103028,
          Duration = 12,
          GUID = "7FEE59E0",
          SpeakNpcId = 700323
        },
        [51103029] = {
          Content = "不错，一点就通。",
          DialogueId = 51103029,
          Duration = 5,
          GUID = "7FEE5A0A",
          SpeakNpcId = 700323
        },
        [51103030] = {
          Content = "这个机枢考验的是你的记忆力，记住那些金色组件的位置，然后用牵机方枢把它们拉出来就行，也不难对吧。",
          DialogueId = 51103030,
          Duration = 12,
          GUID = "7FEE5A34",
          SpeakNpcId = 700323
        },
        [51103031] = {
          Content = "干得好，不愧是我授予了机枢派名誉学徒的人。拿上你应得的奖励吧。",
          DialogueId = 51103031,
          Duration = 7,
          GUID = "7FEE5A5E",
          SpeakNpcId = 700323
        },
        [51103032] = {
          Content = "这种机枢会稍微复杂一点，你可得看仔细了。",
          DialogueId = 51103032,
          Duration = 7,
          GUID = "7FEE5A88",
          NextDialogue = 51103033,
          SpeakNpcId = 700323
        },
        [51103033] = {
          Content = "这机枢门的位置会根据牵引的方向不同而产生变化，所以你得把它停在合适的位置，然后钻进去拿奖励，明白了吧？",
          DialogueId = 51103033,
          GUID = "7FEE5AB2",
          SpeakNpcId = 700323
        },
        [51103034] = {
          Camera = "259.686523,140.730469,196.319336,0.000266,-11.042141,-145.534332,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "感觉如何？",
          DialogueId = 51103034,
          GUID = "7FEE5ADC",
          LookAt = {
            [1] = "100001:n(700323)",
            [2] = "200002:n(700323)",
            [3] = "700323:n(100001)"
          },
          NextOptions = {
            [1] = 51103035,
            [2] = 51103037,
            [3] = 51103039
          },
          SpeakNpcId = 700323
        },
        [51103035] = {
          Content = "是有点好玩。",
          DialogueId = 51103035,
          GUID = "7FEE5ADD",
          ImprPlusId = 1202,
          NextDialogue = 51103036
        },
        [51103036] = {
          Camera = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哈哈，但凡体验过机枢之乐的人，无一不为其折服！别担心，我在烟津渡还布置了不少机枢，想玩的话管够。",
          DialogueId = 51103036,
          GUID = "7FEE5B06",
          NextDialogue = 51103042,
          SpeakNpcId = 700323,
          TalkActionId = {
            [1] = "700323:Agree"
          }
        },
        [51103037] = {
          Content = "奖励太少了。",
          DialogueId = 51103037,
          GUID = "7FEE5B07",
          ImprPlusId = 1201,
          NextDialogue = 51103038
        },
        [51103038] = {
          Camera = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "别担心，玩得越多，奖励就越多。我在烟津渡还布置了不少机枢，俗话说得好，积少成多嘛！",
          DialogueId = 51103038,
          GUID = "7FEE5B30",
          NextDialogue = 51103042,
          SpeakNpcId = 700323
        },
        [51103039] = {
          Content = "感觉不够……好玩……",
          DialogueId = 51103039,
          GUID = "7FEE5B31",
          ImprPlusId = 1205,
          NextDialogue = 51103040
        },
        [51103040] = {
          Camera = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "唉，没品，实在没品！你先别急，这些只是入门级别，六岁学童都能轻松过关。",
          DialogueId = 51103040,
          GUID = "7FEE5B5A",
          NextDialogue = 51103041,
          SpeakNpcId = 700323,
          TalkActionId = {
            [1] = "700323:Disagree"
          }
        },
        [51103041] = {
          Content = "好玩的还在后面呢！我在烟津渡还布置了不少机枢，再不济，为了奖励，你也多试试吧。",
          DialogueId = 51103041,
          GUID = "7FEE5B84",
          NextDialogue = 51103042,
          SpeakNpcId = 700323
        },
        [51103042] = {
          Camera = "259.686523,140.730469,196.319336,0.000266,-11.042141,-145.534332,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哎？原来我们一路上看到的那些机关块全都是你布置的。公尚师傅，你做这些到底有什么目的？",
          DialogueId = 51103042,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "7FEE5BAE",
          NextDialogue = 51103043,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          }
        },
        [51103043] = {
          Camera = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "目的？哈哈，这样想就落入俗套了。",
          DialogueId = 51103043,
          GUID = "7FEE5BD8",
          NextDialogue = 51103044,
          SpeakNpcId = 700323,
          TalkActionId = {
            [1] = "200002:Shock03_End"
          }
        },
        [51103044] = {
          Content = "也难免你们这样想，毕竟帝国的炼金术师搞研究都带着些军事目的，像工造局那些迂腐的老东西则是为了混口饭吃。",
          DialogueId = 51103044,
          GUID = "7FEE5C02",
          NextDialogue = 51103045,
          SpeakNpcId = 700323
        },
        [51103045] = {
          Content = "他们也不能说错，但目的性太强，便体会不到机枢中纯粹的乐趣。",
          DialogueId = 51103045,
          GUID = "7FEE5C2C",
          NextDialogue = 51103046,
          SpeakNpcId = 700323
        },
        [51103046] = {
          Camera = "259.686523,140.730469,196.319336,0.000266,-11.042141,-145.534332,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "公尚师傅研究机枢，就是因为有趣吗？",
          DialogueId = 51103046,
          GUID = "7FEE5C56",
          NextDialogue = 51103047,
          SpeakNpcId = 100001
        },
        [51103047] = {
          Camera = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "人生不过短短数十年，怎能蹉跎在无趣之物上呢？只有从本心出发，才能追寻“道”的极致啊。",
          DialogueId = 51103047,
          GUID = "7FEE5C80",
          NextDialogue = 51103048,
          SpeakNpcId = 700323,
          TalkActionId = {
            [1] = "700323:Agree"
          }
        },
        [51103048] = {
          Content = "说到这里，虽然秦虬那家伙老是狗嘴吐不出象牙……但也多亏了他，我这些年里才能无拘无束全心沉浸于机枢研究。",
          DialogueId = 51103048,
          GUID = "7FEE5CAA",
          NextDialogue = 51103049,
          SpeakNpcId = 700323
        },
        [51103049] = {
          Content = "哎，刚才这句话你可别告诉他啊，不然他尾巴都得翘到天上去。",
          DialogueId = 51103049,
          GUID = "7FEE5CD4",
          NextOptions = {
            [1] = 51103050,
            [2] = 51103051
          },
          SpeakNpcId = 700323
        },
        [51103050] = {
          Content = "好的。",
          DialogueId = 51103050,
          GUID = "7FEE5CD5",
          ImprPlusId = 1202,
          NextDialogue = 51103052
        },
        [51103051] = {
          Content = "师傅，你也不想这些话传到他耳朵里吧。",
          DialogueId = 51103051,
          GUID = "7FEE5CD6",
          ImprPlusId = 1205,
          NextDialogue = 51103052
        },
        [51103052] = {
          Content = "哈哈！好了好了，今天就到这里罢。我也得回去捣鼓别的发明了。",
          DialogueId = 51103052,
          FacialId = {
            [1] = "700323:CM_Happy01"
          },
          GUID = "7FEE5CFE",
          LookAt = {
            [1] = "700323:n(700323)"
          },
          NextDialogue = 51103053,
          Scripts = "MoveTo{ActorId{700323},TargetPoint{"TargetPoint200306_3"},MoveSpeed{70},Visibility{"Show"}}",
          SpeakNpcId = 700323
        },
        [51103053] = {
          Content = "对了，等我研究出来新的机枢，记得再来体验体验啊。",
          DialogueId = 51103053,
          GUID = "7FEE5D28",
          SpeakNpcId = 700323
        },
        [51103054] = {
          Content = "别急，我有新点子了。",
          DialogueId = 51103054,
          GUID = "7FEE5D29",
          SpeakNpcId = 700323
        },
        [51103055] = {
          Content = "公尚师傅，你怎么在这？",
          DialogueId = 51103055,
          GUID = "7FEE5D2A",
          NextDialogue = 51103014,
          SpeakNpcId = 100001
        },
        [51103056] = {
          Content = "公尚师傅，你怎么在这？",
          DialogueId = 51103056,
          GUID = "7FEE5D2B",
          NextDialogue = 51103014,
          SpeakNpcId = 100001
        },
        [51104001] = {
          Content = "小仆从小仆从，听我说！锦鲤皎皎告诉了本魔王一个天大的秘密——",
          DialogueId = 51104001,
          GUID = "7FEEFA2A",
          NextDialogue = 51104002,
          SpeakNpcId = 700324
        },
        [51104002] = {
          Content = "整个烟津渡最好吃最地道的小吃，就藏在这个码头的摊子里！这可是只有本地人才能知道的秘密，一般人她才不告诉！",
          DialogueId = 51104002,
          GUID = "7FEEFA54",
          NextDialogue = 51104003,
          SpeakNpcId = 700324
        },
        [51104003] = {
          Content = "就是前面的桂花糕摊位了，我们赶紧去看看吧！",
          DialogueId = 51104003,
          GUID = "7FEEFA7E",
          SpeakNpcId = 700324
        },
        [51104004] = {
          Camera = "-640.476562,-1148.253906,155.432617,0.000009,-1.399472,64.393364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哥，这边这边！",
          DialogueId = 51104004,
          GUID = "7FEEFAA8",
          LookAt = {
            [1] = "700326:n(700327)",
            [2] = "700328:n(700327)"
          },
          NextDialogue = 51104005,
          Scripts = "MoveTo{ActorId{700327},TargetPoint{"P51104004XiaoWu"},MoveSpeed{250},Visibility{"Show"}}",
          SpeakNpcId = 700327
        },
        [51104005] = {
          Content = "别跑那么快啊，等等我！",
          DialogueId = 51104005,
          GUID = "7FEEFAD2",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104006,
          Scripts = "MoveTo{ActorId{700326},TargetPoint{"P51104004XiaoWen"},MoveSpeed{250},Visibility{"Show"}}",
          SpeakNpcId = 700326,
          TurnTo = {
            [1] = "700327:n(700328)"
          }
        },
        [51104006] = {
          Camera = "359.076172,-369.277344,120.089844,0.000002,-2.199519,103.398605,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哥，我想吃这个。",
          DialogueId = 51104006,
          GUID = "7FEEFAFC",
          LookAt = {
            [1] = "700326:n(700327)",
            [2] = "700328:n(700327)"
          },
          NextDialogue = 51104007,
          SpeakNpcId = 700327,
          TurnTo = {
            [1] = "700326:n(700327)",
            [2] = "700327:n(700326)"
          }
        },
        [51104007] = {
          Content = "啊？桂花糕啊……明明说好不买这买那才带你出门的。",
          DialogueId = 51104007,
          FacialId = {
            [1] = "700326:Syouganai01"
          },
          GUID = "7FEEFB26",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104008,
          SpeakNpcId = 700326,
          TalkActionId = {
            [1] = "700326:Disagree"
          }
        },
        [51104008] = {
          Content = "我没有买这买那，今天从出门到现在我明明只让你买了一次蜂蜜糍耙。",
          DialogueId = 51104008,
          GUID = "7FEEFB50",
          LookAt = {
            [1] = "700326:n(700327)",
            [2] = "700328:n(700327)"
          },
          NextDialogue = 51104009,
          SpeakNpcId = 700327,
          TalkActionId = {
            [1] = "700327:Talk03_Start"
          }
        },
        [51104009] = {
          Content = "糍粑不好消化，刚吃完现在又要吃这桂花糕……",
          DialogueId = 51104009,
          FacialId = {
            [1] = "700326:Unhappy01"
          },
          GUID = "7FEEFB7A",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104010,
          SpeakNpcId = 700326,
          TalkActionId = {
            [1] = "700327:Talk03_End",
            [2] = "700326:Talk01_Start"
          }
        },
        [51104010] = {
          Content = "一会回家吃不下饭被阿娘骂事小，要是再晚上肚子胀到睡不着觉我可帮不了你。",
          DialogueId = 51104010,
          GUID = "7FEEFBA4",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104011,
          SpeakNpcId = 700326,
          TalkActionId = {
            [1] = "700326:Talk01_End"
          }
        },
        [51104011] = {
          Content = "我不管！今天吃不到桂花糕我就不回去了，到时候阿娘一着急你就惨咯。",
          DialogueId = 51104011,
          GUID = "7FEEFBCE",
          LookAt = {
            [1] = "700326:n(700327)",
            [2] = "700328:n(700327)"
          },
          NextDialogue = 51104012,
          SpeakNpcId = 700327,
          TalkActionId = {
            [1] = "700327:Angry01_Start"
          }
        },
        [51104012] = {
          Content = "行吧行吧，拗不过你。老板，要一份桂花糕。",
          DialogueId = 51104012,
          FacialId = {
            [1] = "700326:Syouganai01"
          },
          GUID = "7FEEFBF8",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104013,
          SpeakNpcId = 700326,
          TalkActionId = {
            [1] = "700327:Angry01_End"
          },
          TurnTo = {
            [1] = "700326:n(700328)",
            [2] = "700327:n(700328)"
          }
        },
        [51104013] = {
          Content = "好嘞。",
          DialogueId = 51104013,
          FacialId = {
            [1] = "700328:Smile01"
          },
          GUID = "7FEEFC22",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104014,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Give"
          }
        },
        [51104014] = {
          Content = "呃……老板，桂花糕能卖半份……啊不，三分之一份吗？出门带的铜币好像不够了……",
          DialogueId = 51104014,
          GUID = "7FEEFC4C",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104015,
          SpeakNpcId = 700326,
          TalkActionId = {
            [1] = "700326:Sigh_Start"
          }
        },
        [51104015] = {
          Content = "你这小家伙……罢了罢了。",
          DialogueId = 51104015,
          FacialId = {
            [1] = "700328:Syouganai01"
          },
          GUID = "7FEEFC76",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104016,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700326:Sigh_End"
          }
        },
        [51104016] = {
          Content = "我们家老爷子倒是交代过，要是有小孩子嘴馋也不用太计较，按老爷子说法，给你们两个小家伙出个谜语。",
          DialogueId = 51104016,
          GUID = "7FEEFCA0",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104017,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Think_Start"
          }
        },
        [51104017] = {
          Content = "要是你俩能猜上来啊，这桂花糕送你们一份也行。",
          DialogueId = 51104017,
          GUID = "7FEEFCCA",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104018,
          SpeakNpcId = 700328
        },
        [51104018] = {
          Content = "真的吗？",
          DialogueId = 51104018,
          GUID = "7FEEFCF4",
          LookAt = {
            [1] = "700326:n(700327)",
            [2] = "700328:n(700327)"
          },
          NextDialogue = 51104019,
          SpeakNpcId = 700327,
          TalkActionId = {
            [1] = "700327:Huanhu_Nan_Start",
            [2] = "700328:Think_End"
          }
        },
        [51104019] = {
          Content = "我骗你们两个小毛孩做什么。",
          DialogueId = 51104019,
          GUID = "7FEEFD1E",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104020,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk01_Start"
          }
        },
        [51104020] = {
          Content = "小武，快说谢谢叔叔！",
          DialogueId = 51104020,
          GUID = "7FEEFD48",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)",
            [3] = "700326:n(700327)"
          },
          NextDialogue = 51104021,
          SpeakNpcId = 700326,
          TalkActionId = {
            [1] = "700326:Talk01_Start"
          }
        },
        [51104021] = {
          Content = "哎，莫着急谢，先听谜面。山腰悬玉钩，树杪挂银舟。圆缺妆台镜，阴晴刈麦秋。",
          DialogueId = 51104021,
          GUID = "7FEEFD72",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextOptions = {
            [1] = 51104022,
            [2] = 51104024,
            [3] = 51104026
          },
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700326:Talk01_End"
          }
        },
        [51104022] = {
          Content = "盘子",
          DialogueId = 51104022,
          GUID = "7FEEFD9C",
          NextDialogue = 51104023
        },
        [51104023] = {
