        [51104026] = {
          Content = "月亮",
          DialogueId = 51104026,
          GUID = "7FEEFE44",
          NextDialogue = 51104027
        },
        [51104027] = {
          Content = "答案是……",
          DialogueId = 51104027,
          GUID = "7FEEFE6E",
          NextDialogue = 51104028,
          SpeakNpcId = 100001
        },
        [51104028] = {
          Content = "我知道我知道，是月亮！",
          DialogueId = 51104028,
          GUID = "7FEEFE98",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
