          NextDialogue = 51104032,
          Scripts = "PARA{\nMoveTo{ActorId{100001},TargetPoint{\"P51104031Avatar\"},MoveSpeed{80},Visibility{\"Show\"}},\nMoveTo{ActorId{700324},TargetPoint{\"P51104031White\"},MoveSpeed{80},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 100001
        },
        [51104032] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哟？看起来是外国客人，来给身边这位小朋友买点本地的桂花糕尝尝？",
          DialogueId = 51104032,
          GUID = "7FEEFF40",
          NextDialogue = 51104033,
          SpeakNpcId = 700328,
          TurnTo = {
            [1] = "700324:n(700328)",
            [2] = "100001:n(700328)"
          }
        },
        [51104033] = {
          Camera = "447.546875,110.363281,105.350098,0.000169,-6.799733,-128.996719,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "白才不是什么小朋友！听好了，你面前的可是将来要征服世界的光之魔王大人！",
          DialogueId = 51104033,
          FacialId = {
            [1] = "700324:Unhappy02"
          },
          GUID = "7FEEFF6A",
          LookAt = {
            [1] = "700328:n(700324)"
          },
          NextOptions = {
            [1] = 51104034,
            [2] = 51104035
          },
          SpeakNpcId = 700324,
          TalkActionId = {
            [1] = "700324:Angry02_Start"
          }
        },
        [51104034] = {
          Content = "我们也可以猜谜免单吗？",
          DialogueId = 51104034,
          GUID = "7FEEFF94",
          ImprPlusId = 1206,
          NextDialogue = 51104036
        },
        [51104035] = {
          Content = "刚才的两位小朋友好像参与了一些优惠活动？",
          DialogueId = 51104035,
          GUID = "7FEEFFBE",
          ImprPlusId = 1203,
          NextDialogue = 51104036
        },
        [51104036] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "呃……老爷子倒是没吩咐大人能不能猜谜免单啊……",
          DialogueId = 51104036,
          GUID = "7FEEFFE8",
          LookAt = {
            [1] = "700328:n(100001)"
          },
          NextDialogue = 51104037,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk01_Start",
            [2] = "700324:Bai_Idle"
          }
        },
        [51104037] = {
          Content = "算了，反正你也是打算给小朋友吃的吧？不在乎这一点了。",
          DialogueId = 51104037,
          GUID = "7FEF0012",
          NextDialogue = 51104038,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk01_End"
          }
        },
        [51104038] = {
          Camera = "447.546875,110.363281,105.350098,0.000169,-6.799733,-128.996719,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "喂，所以说谁是小朋友啊！",
          DialogueId = 51104038,
          FacialId = {
            [1] = "700324:Doubt01"
          },
          GUID = "7FEF003C",
          NextDialogue = 51104039,
          SpeakNpcId = 700324,
          TalkActionId = {
            [1] = "700324:Angry01_Start"
          }
        },
        [51104039] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "谜面吗……我想想。啊，这个吧——金粟满枝不染尘，暗香先报九秋春。莫嫌花小无颜色，曾引仙人月下寻。",
          DialogueId = 51104039,
          FinalDialogueId = 51104045,
          GUID = "7FEF0066",
          NextOptions = {
            [1] = 51104040,
            [2] = 51104042,
            [3] = 51104044
          },
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk02_Start"
          }
        },
        [51104040] = {
          Content = "百年春",
          DialogueId = 51104040,
          GUID = "7FEF0090",
          NextDialogue = 51104041
        },
        [51104041] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "要不客人您再想想？",
          DialogueId = 51104041,
          GUID = "7FEF00BA",
          NextOptions = {
            [1] = 51104204,
            [2] = 51104044
          },
          SpeakNpcId = 700328
        },
        [51104042] = {
          Content = "沉月香",
          DialogueId = 51104042,
          GUID = "7FEF00E4",
          NextDialogue = 51104043
        },
        [51104043] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "倒是有些接近了，再想想？",
          DialogueId = 51104043,
          GUID = "7FEF010E",
          NextOptions = {
            [1] = 51104203,
            [2] = 51104044
          },
          SpeakNpcId = 700328
        },
        [51104044] = {
          Content = "桂花",
          DialogueId = 51104044,
          GUID = "7FEF0138",
          NextDialogue = 51104045
        },
        [51104045] = {
          Content = "得了，就是这桂花糕的桂花……来，刚蒸好还冒着热气呢，您拿好。",
          DialogueId = 51104045,
          GUID = "7FEF0162",
          NextDialogue = 51104046,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk02_End",
            [2] = "700324:Angry02_End"
          }
        },
        [51104046] = {
          Content = "也不知道老爷子是怎么想的，做些糕点本就是小本营生，倒还是要猜谜白送些出去。这么一折腾啊，自己的养老钱都剩不下几个了哟。",
          DialogueId = 51104046,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterEast01_GuiHuaCake01.T_Guide_ChapterEast01_GuiHuaCake01'}",
          GUID = "7FEF018C",
          NextDialogue = 51104047,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Sigh_Start"
          }
        },
        [51104047] = {
          Camera = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你不同意这么做吗？",
          DialogueId = 51104047,
          GUID = "7FEF01B6",
          NextDialogue = 51104048,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51104048] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哦，客人你别误会，说了猜谜白送那自然就是白送。看着小孩子眼巴巴地站在一边流口水，拿胳膊擦擦又往身上抹，我也不忍心。",
          DialogueId = 51104048,
          GUID = "7FEF01E0",
          NextDialogue = 51104049,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Sigh_End",
            [2] = "100001:Think_End"
          }
        },
        [51104049] = {
          Content = "小孩嘛，能吃多少？送就送了。当初我举目无亲在这街头闲逛，要不是馋这一口桂花糕让老爷子注意到我，收留我做了个学徒，恐怕也……",
          DialogueId = 51104049,
          FacialId = {
            [1] = "700328:Happy01"
          },
          GUID = "7FEF020A",
          NextDialogue = 51104050,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk02_Start"
          }
        },
        [51104050] = {
          Content = "嗨，我跟客人您说这个干嘛……咱就是有点好奇，老爷子这猜谜送桂花糕的规矩，是为什么立的。",
          DialogueId = 51104050,
          FacialId = {
            [1] = "700328:None"
          },
          GUID = "7FEF0234",
          NextDialogue = 51104051,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk02_End"
          }
        },
        [51104051] = {
          Content = "不过老爷子不想说，咱也不多问。摊子和手艺都是人家的，回头客也都是冲着桂花李的招牌来的。这些东西传给我一个捡来的野小子，我已经知足了。",
          DialogueId = 51104051,
          GUID = "7FEF025E",
          NextDialogue = 51104052,
          SpeakNpcId = 700328
        },
        [51104052] = {
          Camera = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你好像是在抱怨，但其实心里很喜欢这位老爷子吧？",
          DialogueId = 51104052,
          GUID = "7FEF0288",
          NextDialogue = 51104053,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51104053] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哈哈……这位客人，不瞒您说，他供我吃住又教我手艺。我早就把他当父亲看待了。只是他平日里不许我叫爹，非让我叫他师父。",
          DialogueId = 51104053,
          GUID = "7FEF02B2",
          NextDialogue = 51104054,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51104054] = {
          Content = "这再造之恩，无以能报。我只希望一直给他养老，让他安安稳稳地颐享天年哟。",
          DialogueId = 51104054,
          GUID = "7FEF02DC",
          NextDialogue = 51104055,
          SpeakNpcId = 700328
        },
        [51104055] = {
          Camera = "470.919922,-447.367188,169.704102,0.000065,-7.799495,112.800148,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哟，小李，忙着呐？",
          DialogueId = 51104055,
          GUID = "7FEF0306",
          LookAt = {
            [1] = "100001:n(700332)",
            [2] = "700324:n(700332)",
            [3] = "700328:n(700332)"
          },
          NextDialogue = 51104056,
          Scripts = "MoveTo{ActorId{700332},TargetPoint{"P51104055ZhaoShu"},MoveSpeed{90},Visibility{"Show"}}",
          SpeakNpcId = 700332
        },
        [51104056] = {
          Content = "赵叔，您怎么来了？现做的桂花糕，给您包一份？",
          DialogueId = 51104056,
          GUID = "7FEF0330",
          LookAt = {
            [1] = "700332:n(700328)"
          },
          NextDialogue = 51104057,
          SpeakNpcId = 700328,
          TurnTo = {
            [1] = "700328:n(700332)"
          }
        },
        [51104057] = {
          Content = "不用不用，先招呼客人。闲下来了跟你家老爷子招呼一声，说好了上我那喝两杯，半晌了都没见人，再不来啊，我这好酒他可就尝不着喽。",
          DialogueId = 51104057,
          GUID = "7FEF035A",
          NextDialogue = 51104058,
          SpeakNpcId = 700332,
          TalkActionId = {
            [1] = "700332:Talk02_Start"
          }
        },
        [51104058] = {
          Content = "……这可奇怪了。老爷子这些年来，和人约好了时间从来只有提早登门，绝无迟到的道理。要是我不小心误了点，他还会用拐杖敲我哩。",
          DialogueId = 51104058,
          GUID = "7FEF0384",
          LookAt = {
            [1] = "100001:n(700328)",
            [2] = "700324:n(700328)"
          },
          NextDialogue = 51104059,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700332:Talk02_End",
            [2] = "700328:Talk01_Start"
          }
        },
        [51104059] = {
          Content = "不行，今日先收摊了。我得去找找老爷子。",
          DialogueId = 51104059,
          GUID = "7FEF03AE",
          NextDialogue = 51104060,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk01_End"
          }
        },
        [51104060] = {
          Content = "赵叔，您回家等着吧，我有了消息一定知会您。",
          DialogueId = 51104060,
          GUID = "7FEF03D8",
          NextDialogue = 51104061,
          SpeakNpcId = 700328,
          TalkActionId = {
            [1] = "700328:Talk02_Start"
