          GUID = "7FEF042C",
          NextDialogue = 51104063,
          SpeakNpcId = 100001,
          TurnTo = {
            [1] = "700328:n(100001)"
          }
        },
        [51104063] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那可帮大忙了。我知道老爷子可能去的地方，跟我来吧。",
          DialogueId = 51104063,
          GUID = "7FEF0456",
          LookAt = {
            [1] = "700328:n(100001)"
          },
          SpeakNpcId = 700328
        },
        [51104064] = {
          Content = "这些天煞的孽畜，娃娃不要怕，躲到爷爷身后来。",
          DialogueId = 51104064,
          GUID = "7FEF0480",
          NextDialogue = 51104065,
          SpeakNpcId = 700333
        },
        [51104065] = {
          Content = "哥，我怕……",
          DialogueId = 51104065,
          GUID = "7FEF04AA",
          NextDialogue = 51104066,
          SpeakNpcId = 700327
        },
        [51104066] = {
          Content = "别怕，拿好香囊，白龙神君会保佑我们的。",
          DialogueId = 51104066,
          GUID = "7FEF04D4",
          NextDialogue = 51104067,
          SpeakNpcId = 700326
        },
        [51104067] = {
          Content = "那是……刚刚的那两个孩子！",
          DialogueId = 51104067,
          GUID = "7FEF04FE",
          SpeakNpcId = 100001
        },
        [51104068] = {
          Content = "罪业伏诛！",
          DialogueId = 51104068,
          GUID = "7FEF0528",
          SpeakNpcId = 700325
        },
        [51104069] = {
          Content = "是煜明！",
          DialogueId = 51104069,
          GUID = "7FEF0552",
          SpeakNpcId = 100001
        },
        [51104070] = {
