        },
        [51104105] = {
          Content = "孩子，你还记得，你第一次带着师弟来买桂花糕，我给你出的谜面吗？",
          DialogueId = 51104105,
          GUID = "7FEF0B3A",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104106,
          SpeakNpcId = 700333
        },
        [51104106] = {
          Camera = "-86.242188,466.148438,64.947754,0.000178,-7.393345,-67.627014,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "风也愁，雨也愁，木樨归处秋复秋，无人共倚舟。",
          DialogueId = 51104106,
          GUID = "7FEF0B64",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700333:n(700325)"
          },
          NextDialogue = 51104107,
          SpeakNpcId = 700325
        },
        [51104107] = {
          Camera = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "记性真不错。当年你们怎么也猜不出来，那是当然。只是我老头子随口的感慨罢了，哪有什么谜底。",
          DialogueId = 51104107,
          GUID = "7FEF0B8E",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104108,
          SpeakNpcId = 700333
        },
        [51104108] = {
          Content = "这么多年过去，儿子没了，但我有了徒弟，朋友没了，我又认识了愿意陪我喝酒的老伙伴。可唯独那桂花旁的小村子，终究是回不去了。",
          DialogueId = 51104108,
          GUID = "7FEF0BB8",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104109,
          SpeakNpcId = 700333
        },
        [51104109] = {
          Content = "你还年轻，故人尚在，归处仍存，莫要像我老头子一般……",
          DialogueId = 51104109,
          GUID = "7FEF0BE2",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104110,
          SpeakNpcId = 700333
        },
        [51104110] = {
          Content = "就到这吧，剩下几步路老朽自己回去也无事。多谢几位英雄出手相助了。",
          DialogueId = 51104110,
          GUID = "7FEF0C0C",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          Scripts = "MoveTo{ActorId{700333},TargetPoint{"P51104110GuiHuaLi"},MoveSpeed{80},Visibility{"Show"}}",
          SpeakNpcId = 700333
        },
        [51104111] = {
          Camera = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "煜明，没想到在这又见面了。上次在听鸦原一别后，刻舟托我带话给你……",
          DialogueId = 51104111,
          GUID = "7FEF0C36",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700325:n(100001)",
            [3] = "700324:n(700325)"
          },
          NextDialogue = 51104112,
          SpeakNpcId = 100001
        },
        [51104112] = {
          Camera = "156.148438,383.179688,54.88623,0.000159,-8.793397,-104.439034,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "他的心思我早已知晓，恕难遂其心愿……劳烦你们二位了。",
          DialogueId = 51104112,
          GUID = "7FEF0C60",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104113,
          SpeakNpcId = 700325
        },
        [51104113] = {
          Camera = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "喂喂，我说，你们明明曾经那么要好，还一起买桂花糕吃。有什么误会真的不能说开嘛？",
          DialogueId = 51104113,
          GUID = "7FEF0C8A",
          LookAt = {
            [1] = "100001:n(700324)",
            [2] = "700325:n(700324)"
          },
          NextDialogue = 51104114,
          SpeakNpcId = 700324,
          TalkActionId = {
            [1] = "700324:Think_Start"
          }
        },
        [51104114] = {
          Camera = "156.148438,383.179688,54.88623,0.000159,-8.793397,-104.439034,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "……有人欲归家而故园不复。更有些人，故里虽在，却终不得回。",
          DialogueId = 51104114,
          GUID = "7FEF0CB4",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104115,
          SpeakNpcId = 700325,
          TalkActionId = {
            [1] = "700324:Think_End"
          }
        },
        [51104115] = {
          Content = "其中恩怨纠葛并非寥寥数语可以道明。更何况如今我需应天执法，他乃飘零中人，立场之别，已是天渊。",
          DialogueId = 51104115,
          GUID = "7FEF0CDE",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104116,
          SpeakNpcId = 700325
        },
        [51104116] = {
          Content = "多谢两位从中调解……怕是让你们失望了。",
          DialogueId = 51104116,
          GUID = "7FEF0D08",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)",
            [3] = "700325:n(100001)"
          },
          NextDialogue = 51104117,
          SpeakNpcId = 700325,
          TalkActionId = {
            [1] = "700325:Talk02_Start"
          }
        },
        [51104117] = {
          Camera = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "白听不明白，好像很深奥的样子……不过既然你想清楚了，那我和小仆从也不多说什么了。",
          DialogueId = 51104117,
          GUID = "7FEF0D32",
          LookAt = {
            [1] = "100001:n(700324)",
            [2] = "700325:n(700324)"
          },
          NextDialogue = 51104118,
          SpeakNpcId = 700324,
          TalkActionId = {
            [1] = "700325:Talk02_End"
          }
        },
        [51104118] = {
          Content = "那我们先走了。你保重好身体，不要太拼命了。",
          DialogueId = 51104118,
          GUID = "7FEF0D5C",
          NextDialogue = 51104119,
          Scripts = "PARA{\nMoveTo{_delay{3},ActorId{100001},TargetPoint{\"P51104118Avatar\"},MoveSpeed{80},Visibility{\"Show\"}},\nMoveTo{_delay{3},ActorId{700324},TargetPoint{\"P51104118White\"},MoveSpeed{80},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 100001
        },
        [51104119] = {
          Camera = "-1452.339844,-2423.003906,585.456543,0.000174,-7.592308,44.551308,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "师兄，山外山的大家都未曾怪你，你何必如此执拗？",
          DialogueId = 51104119,
          GUID = "7FEF0D86",
          IsBlack = 1,
          NextDialogue = 51104120,
          TurnTo = {
            [1] = "700325:p(90)"
          }
        },
        [51104120] = {
          Content = "罢了，今日我纵是与你大战三百回合也要带你回去！",
          DialogueId = 51104120,
          GUID = "7FEF0DB0",
          IsBlack = 1,
          NextDialogue = 51104121
        },
        [51104121] = {
          Content = "……此去一别，不复当年，这或许就是天意。",
          DialogueId = 51104121,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterEast01_GuiHuaCake02.T_Guide_ChapterEast01_GuiHuaCake02'}",
          GUID = "7FEF0DDA",
          NextDialogue = 51104122,
          SpeakNpcId = 700325,
          TalkActionId = {
            [1] = "700325:Explain02_Start"
          }
        },
        [51104122] = {
          Content = "故人尚在，归处仍存吗……终究只是个愿景罢了。",
          DialogueId = 51104122,
          GUID = "7FEF0E04",
          SpeakNpcId = 700325
        },
        [51104200] = {
          Content = "盘子",
          DialogueId = 51104200,
          GUID = "7FEF1AD0",
          NextDialogue = 51104202
        },
        [51104201] = {
          Content = "天之树",
          DialogueId = 51104201,
          GUID = "7FEF1AD1",
          NextDialogue = 51104202
        },
        [51104202] = {
          Content = "感觉不太对劲……",
          DialogueId = 51104202,
          GUID = "7FEF1AD2",
          NextOptions = {
            [1] = 51104026
          },
          SpeakNpcId = 100001
        },
        [51104203] = {
          Content = "百年春",
          DialogueId = 51104203,
          GUID = "7FEF0139",
          NextDialogue = 51104205
        },
        [51104204] = {
          Content = "沉月香",
          DialogueId = 51104204,
          GUID = "7FEF013A",
          NextDialogue = 51104206
        },
        [51104205] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "要不客人您再想想？",
          DialogueId = 51104205,
          GUID = "7FEF013B",
          NextOptions = {
            [1] = 51104044
          },
          SpeakNpcId = 700328
        },
        [51104206] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "倒是有些接近了，再想想？",
          DialogueId = 51104206,
          GUID = "7FEF013C",
          NextOptions = {
            [1] = 51104044
          },
          SpeakNpcId = 700328
        },
        [51105201] = {
          Content = "一年一度的银烛狂欢节结束了，一切似乎都回复平静。水仙平原也理应恢复到一如既往的喧嚣气氛。",
          DialogueId = 51105201,
          GUID = "7FEFBF0A",
          NextDialogue = 51105202
        },
        [51105202] = {
          Content = "但事实却并非如此……一连串的意外给本该人人尽兴的狂欢蒙上阴影。",
          DialogueId = 51105202,
          GUID = "7FEFBF34",
          NextDialogue = 51105203
        },
        [51105203] = {
          Content = "于是，一件略带喧闹的小事在狂欢结束后的某天，悄然发生。",
          DialogueId = 51105203,
          GUID = "7FEFBF5E"
        },
        [51105204] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          Content = "……唉，没什么动力啊，总感觉没玩够。",
          DialogueId = 51105204,
          GUID = "7FEFBF88",
          NextDialogue = 51105205,
          SpeakNpcId = 700349,
          TalkActionId = {
            [1] = "700349:Talk01_Start"
          }
        },
        [51105205] = {
          Camera = "391.339111,-304.583008,188.128906,0.00004,-11.199583,155.19725,35.0,305.677551,false,Manual,2.8",
          Content = "银烛狂欢就这么收场，真没意思，我一点灵感都没有了。",
          DialogueId = 51105205,
          GUID = "7FEFBFB2",
          LookAt = {
            [1] = "700350:n(700349)",
            [2] = "700349:n(700350)"
          },
          NextDialogue = 51105206,
          SpeakNpcId = 700350,
          TalkActionId = {
            [1] = "700350:Explain01_Start",
            [2] = "700349:Talk01_End"
          }
        },
        [51105206] = {
          Camera = "240.266602,24.936523,161.671875,0.000056,-2.399227,52.196819,35.0,204.573959,false,Manual,2.8",
          Content = "……",
          DialogueId = 51105206,
          FacialId = {
            [1] = "200003:Syouganai01"
          },
          GUID = "7FEFBFDC",
          NextDialogue = 51105207,
          SpeakNpcId = 200003
        },
        [51105207] = {
          Camera = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
          Content = "怎么回事，大家都一副无精打采的样子。按照以往来说，卡米拉应该开始让大家别瘫在座位上影响生意了。",
          DialogueId = 51105207,
          FacialId = {
            [1] = "700352:Doubt01"
          },
          GUID = "7FEFC006",
          LookAt = {
            [1] = "700352:n(700350)",
            [2] = "700349:n(700352)",
            [3] = "700350:n(700352)"
          },
          NextDialogue = 51105208,
          SpeakNpcId = 700352,
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105208] = {
          Camera = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
          Content = "结果就连卡米拉也懒得说话。",
          DialogueId = 51105208,
          GUID = "7FEFC030",
          NextDialogue = 51105209,
          SpeakNpcId = 700352
        },
        [51105209] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          Content = "啊！我知道了，一定是银烛狂欢大家玩得太累了，所以需要休息一段时间。",
          DialogueId = 51105209,
          FacialId = {
            [1] = "700352:Confident01"
          },
          GUID = "7FEFC05A",
          LookAt = {
            [1] = "700352:n(700349)"
          },
          NextDialogue = 51105210,
          SpeakNpcId = 700352,
          TalkActionId = {
            [1] = "700352:Think_End"
          }
        },
        [51105210] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          Content = "不是的，并且恰恰相反，是因为今年的银烛狂欢由于剧院发生的意外，没有最后的收尾就匆忙结束了。",
          DialogueId = 51105210,
          GUID = "7FEFC084",
          LookAt = {
            [1] = "700349:n(700352)"
          },
          NextDialogue = 51105211,
          SpeakNpcId = 700349,
          TalkActionId = {
            [1] = "700349:Disagree"
          }
        },
        [51105211] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          Content = "就总觉得……提不起劲啊，狂欢的氛围开始没多久，就戛然而止了。这比一开始没有开始狂欢还要难受。",
          DialogueId = 51105211,
          GUID = "7FEFC0AE",
          NextDialogue = 51105212,
          SpeakNpcId = 700349
        },
        [51105212] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          Content = "原来如此，也不是不能理解，就像很多时候我想要帮助别人，帮到一半才发现事情已经解决了一样，就是会很泄气！",
          DialogueId = 51105212,
          FacialId = {
            [1] = "700352:Think02"
          },
          GUID = "7FEFC0D8",
          NextDialogue = 51105213,
          SpeakNpcId = 700352
        },
        [51105213] = {
          Camera = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
          Content = "没错！就好像是最终消失了的梦中灵感、打到一半但是没有打出来的喷嚏……甚至我都想不出第三个合适的比喻来形容。",
          DialogueId = 51105213,
          GUID = "7FEFC102",
          LookAt = {
            [1] = "700350:n(700352)"
          },
          NextDialogue = 51105214,
          SpeakNpcId = 700350
        },
        [51105214] = {
          Camera = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
          Content = "总之就是，没有生机！",
          DialogueId = 51105214,
          GUID = "7FEFC12C",
          NextDialogue = 51105215,
          SpeakNpcId = 700350,
          TalkActionId = {
            [1] = "700350:Explain01_End"
          }
        },
        [51105215] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          Content = "听起来有些严重……",
          DialogueId = 51105215,
          FacialId = {
            [1] = "700352:Sad01"
          },
          GUID = "7FEFC156",
          LookAt = {
            [1] = "700352:n(700350)"
          },
          NextDialogue = 51105216,
          SpeakNpcId = 700352,
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105216] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          Content = "不行，我得想想办法，找人一起来帮帮忙，否则大家变不回之前正常的样子啦。",
          DialogueId = 51105216,
          GUID = "7FEFC180",
          LookAt = {
            [1] = "700352:n(700352)"
          },
          NextDialogue = 51105217,
          SpeakNpcId = 700352,
          TalkActionId = {
            [1] = "700352:Think_End"
          }
        },
        [51105217] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          Content = "该找谁呢……哦！她们，找她们准没错。毕竟她们一直以来都情绪稳定，不会受任何外界影响。",
          DialogueId = 51105217,
          FacialId = {
            [1] = "700352:None"
          },
          GUID = "7FEFC1AA",
          NextDialogue = 51105218,
          SpeakNpcId = 700352,
          TalkActionId = {
            [1] = "700352:Bai_Think2Confident"
          }
        },
        [51105218] = {
          Camera = "-310.544434,-605.483398,200.802734,0.000083,-9.19898,40.997597,35.0,588.773376,false,Manual,2.8",
          Content = "我只要问问她们是怎样不受外界影响，保持工作热情的，就一定能借助她们的心得，让整个冰湖城重新打起精神来。",
          DialogueId = 51105218,
          GUID = "7FEFC1D4",
          SpeakNpcId = 700352
        },
        [51105301] = {
          Camera = "457.37326,-586.730225,248.960373,0.000032,-15.000139,121.598587,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "三位前辈，如何让冰湖城焕发生机，就拜托你们了！",
          DialogueId = 51105301,
          GUID = "7FEFCF72",
          NextDialogue = 51105302,
          Scripts = "PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang"},RelatedRegionId{"210101"}}",
          SpeakNpcId = 700352
        },
        [51105302] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "喔，虽然老朽只懂如何锻造，但是看到白这么热情，确实不好推辞啊。",
          DialogueId = 51105302,
          FacialId = {
            [1] = "700353:Happy02"
          },
          GUID = "7FEFCF9C",
          NextDialogue = 51105303,
          SpeakNpcId = 700353
        },
        [51105303] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "虽然我一直为大家在休息时提供饮品和补给，但如果所有人一直都在休息的话，那也是不对的。",
          DialogueId = 51105303,
          GUID = "7FEFCFC6",
          NextDialogue = 51105304,
          SpeakNpcId = 700354
        },
        [51105304] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯嗯，白这份心意很好，冰湖城在我的记录里一直是北方的都市，要是大家都一直提不起劲，我就要把记录变成北方的睡城啦。",
          DialogueId = 51105304,
          GUID = "7FEFCFF0",
          NextDialogue = 51105305,
          SpeakNpcId = 700355
        },
        [51105305] = {
