          FacialId = {
            [1] = "700353:Confident02"
          },
          GUID = "7FEFD212",
          NextDialogue = 51105318,
          SpeakNpcId = 700353
        },
        [51105318] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "好，铁匠前辈，我之前没有干过这种活，你教一教我。",
          DialogueId = 51105318,
          FacialId = {
            [1] = "700353:CM_Idle"
          },
          GUID = "7FEFD23C",
          NextDialogue = 51105319,
          SpeakNpcId = 700352,
          TalkActionId = {
            [1] = "700352:AgreeHead"
          }
        },
        [51105319] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "简单的简单的，拿起铁锤，深吸一口气，砸——",
          DialogueId = 51105319,
          FacialId = {
            [1] = "700353:Smile02"
          },
          GUID = "7FEFD266",
          NextDialogue = 51105320,
          SpeakNpcId = 700353
        },
        [51105320] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "一边砸，一遍想着别人看到你锻造出的东西满意地露出笑容，就会产生动力。",
          DialogueId = 51105320,
          GUID = "7FEFD290",
          NextDialogue = 51105321,
          SpeakNpcId = 700353
        },
        [51105321] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "并且呀，有节奏地敲击铁锤，看着火花迸出，每锤一次都会涌现出成就感。",
          DialogueId = 51105321,
          GUID = "7FEFD2BA",
          NextDialogue = 51105322,
          SpeakNpcId = 700353
        },
        [51105322] = {
          Camera = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯……好的，我明白了，总的来说就是，挥舞铁锤会让人感到振奋。",
          DialogueId = 51105322,
          FacialId = {
            [1] = "700352:Happy02"
          },
          GUID = "7FEFD2E4",
          NextDialogue = 51105323,
          SpeakNpcId = 700352,
          TalkActionId = {
            [1] = "700352:SpecialConfident_Start"
          }
        },
        [51105323] = {
          Camera = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那么让白来试一试……呜哇，好重……",
          DialogueId = 51105323,
          FacialId = {
            [1] = "700352:Shock02"
          },
          GUID = "7FEFD30E",
          NextDialogue = 51105324,
