          TalkActionId = {
            [1] = "700352:SpecialConfident_End"
          }
        },
        [51105324] = {
          Content = "白举起铁锤，用力挥舞了起来。",
          DialogueId = 51105324,
          GUID = "7FEFD338",
          IsBlack = 1,
