          Duration = 5,
          GUID = "7FF027E0"
        },
        [51105900] = {
          Content = "这位前辈，想必你就是我在等的奇遇了！",
          DialogueId = 51105900,
          GUID = "7FF031B8",
          LookAt = {
            [1] = "701005:n(0)"
