          SpeakNpcId = 701005
        },
        [51105901] = {
          Content = "什么奇遇？我也能分点好处吗？",
          DialogueId = 51105901,
          GUID = "7FF031E2",
          ImprPlusId = 1206,
          NextDialogue = 51105902
        },
        [51105902] = {
          Content = "嗯？不行不行，没人说过奇遇还能跟别人分的啊？",
          DialogueId = 51105902,
          GUID = "7FF0320C",
          NextDialogue = 51105903,
          SpeakNpcId = 701005,
