          Content = "你们抄家伙是要去做什么坏事！",
          DialogueId = 51112003,
          GUID = "7FF41AFE",
          ImprPlusId = 1207,
          NextDialogue = 51112006
        },
        [51112004] = {
          Content = "（他们的目标看起来并不是你，所以还是把路让开为好。）",
          DialogueId = 51112004,
          GUID = "7FF41B28",
          ImprPlusId = 1206,
          NextDialogue = 51112006
        },
        [51112005] = {
          Content = "呦，几天不见，这么惨了啊。",
          DialogueId = 51112005,
          GUID = "7FF41B52",
          ImprPlusId = 1210,
          NextDialogue = 51112006
        },
        [51112006] = {
          Content = "原来是虬先生的贵客，有失远迎。",
          DialogueId = 51112006,
          GUID = "7FF41B7C",
          LookAt = {
            [1] = "701013:n(0)"
          },
          NextDialogue = 51112007,
          SpeakNpcId = 701013
        },
        [51112007] = {
          Content = "（领头的男子见到你后，对着你微微作揖，展现出与这黑市格格不入的风度。）",
          DialogueId = 51112007,
          GUID = "7FF41BA6",
          NextDialogue = 51112008
        },
        [51112008] = {
          Content = "既已被你撞见，那我便把此事说清为好，以免再生误会。",
          DialogueId = 51112008,
          GUID = "7FF41BD0",
          NextDialogue = 51112009,
          SpeakNpcId = 701013,
          TalkActionId = {
            [1] = "701013:Explain01_Start"
          }
        },
        [51112009] = {
          Content = "（他看出了你眼中的疑惑，微微侧身指向躺在地上的那位黑市商人。）",
          DialogueId = 51112009,
          GUID = "7FF41BFA",
          NextDialogue = 51112010
        },
        [51112010] = {
          Content = "他不久前做生意吃了亏，与人家争执中恼羞成怒，动了手脚，遂招致狴犴惩戒，沦为这幅半死不活的模样。",
          DialogueId = 51112010,
          GUID = "7FF41C24",
          NextOptions = {
            [1] = 51112011
          },
          RestartTag = 51112011,
          SpeakNpcId = 701013
        },
        [51112011] = {
          Content = "所以……你要带着这一帮人去报复别人？",
          DialogueId = 51112011,
          FailDialogue = 51112012,
          GUID = "7FF41C4E",
          ImprCheckId = 1122,
          NextDialogue = 51112013
        },
        [51112012] = {
          Content = "抱歉，无可奉告。",
          DialogueId = 51112012,
          GUID = "7FF41C78",
          SpeakNpcId = 701013
        },
        [51112013] = {
          Content = "呵呵，黑市从不会为了谁而去报复别人。愿赌服输，这是虬先生为黑市立下的规矩，也是他自己应该接受的现实。",
          DialogueId = 51112013,
          GUID = "7FF41CA2",
          NextDialogue = 51112014,
          SpeakNpcId = 701013
        },
        [51112014] = {
          Content = "输了，那就独自承受后果。活不活得下来，活下来又当如何，与他人无关。",
          DialogueId = 51112014,
          GUID = "7FF41CCC",
          NextDialogue = 51112015,
          SpeakNpcId = 701013,
          TalkActionId = {
            [1] = "701013:Explain01_End"
          }
        },
        [51112015] = {
          Content = "我还以为你们会更极端一些。",
          DialogueId = 51112015,
          GUID = "7FF41CF6",
          NextDialogue = 51112016,
          SpeakNpcId = 100001
        },
        [51112016] = {
          Content = "很多人都会有这样的误解，但黑市说到底也只是一个比较松散的组织。",
          DialogueId = 51112016,
          GUID = "7FF41D20",
          NextDialogue = 51112017,
          SpeakNpcId = 701013,
          TalkActionId = {
            [1] = "701013:Talk01_Start"
          }
        },
        [51112017] = {
          Content = "最后能留下来的，只有不受秩序约束，并有能力承担相应后果的人。",
          DialogueId = 51112017,
          GUID = "7FF41D4A",
          NextDialogue = 51112018,
          SpeakNpcId = 701013
        },
        [51112018] = {
          Content = "我们不怕输，吃完亏再爬起来便是。只怕那些输不起的人，顺风时践踏秩序，逆风时却乞求秩序的庇护，黑市的大门不对这种弱者敞开。",
          DialogueId = 51112018,
          GUID = "7FF41D74",
          NextDialogue = 51112019,
          SpeakNpcId = 701013
        },
        [51112019] = {
          Content = "所以话说到这里，小友也能明白我们这些人并不是去报复谁的了吧。",
          DialogueId = 51112019,
          GUID = "7FF41D9E",
          NextDialogue = 51112020,
          SpeakNpcId = 701013
        },
        [51112020] = {
          Content = "至于具体要去做什么……不过是在烛阴之灾止息后，去灾后的阴影里攫取一些利益罢了。",
          DialogueId = 51112020,
          GUID = "7FF41DC8",
          NextDialogue = 51112021,
          SpeakNpcId = 701013,
          TalkActionId = {
            [1] = "701013:Talk01_End"
          }
        },
        [51112021] = {
          Content = "（男人说完便带着身后众人离开，没走几步，他突然停了下来，转头看向你。）",
          DialogueId = 51112021,
          GUID = "7FF41DF2",
          NextDialogue = 51112022
        },
        [51112022] = {
          Content = "既是虬先生的贵客，那我便免费送你一句忠告吧。",
          DialogueId = 51112022,
          GUID = "7FF41E1C",
          NextDialogue = 51112023,
          SpeakNpcId = 701013,
          TalkActionId = {
            [1] = "701013:Talk02_Start"
          }
        },
        [51112023] = {
          Content = "有些无主之物，有能者自可得之。若是稍加留意，也许你便能在烟津渡寻得一些不错的宝贝，告辞。",
          DialogueId = 51112023,
          GUID = "7FF41E46",
          SpeakNpcId = 701013,
          TalkActionId = {
            [1] = "701013:Talk02_End"
          }
        },
        [51112024] = {
          Content = "有失远迎，是有什么生意要谈吗？",
          DialogueId = 51112024,
          GUID = "7FF41E70",
          SpeakNpcId = 701013
        },
        [51113000] = {
          Content = "嗯~前调粗犷，后调绵长，还是百年春的香地道儿。",
          DialogueId = 51113000,
          GUID = "7FF4BE90",
          NextDialogue = 51113001,
          SpeakNpcId = 701014,
          TalkActionId = {
            [1] = "701014:Confident_Start"
          }
        },
        [51113001] = {
          Content = "（面前这位男人说完举起一把香凑到鼻尖，猛吸一口，露出回味十足的表情。）",
          DialogueId = 51113001,
          GUID = "7FF4BEBA",
          NextDialogue = 51113002
        },
        [51113002] = {
          Content = "嗯~爽也爽也，太纯了！",
          DialogueId = 51113002,
          GUID = "7FF4BEE4",
          NextOptions = {
            [1] = 51113003,
            [2] = 51113004
          },
          SpeakNpcId = 701014,
          TalkActionId = {
            [1] = "701014:Confident_End"
          }
        },
        [51113003] = {
          Content = "（此人疯疯癫癫，还是别跟他有所牵连为好。）",
          DialogueId = 51113003,
          GUID = "7FF4BF0E",
          ImprPlusId = 1207,
          NextDialogue = 51113005
        },
        [51113004] = {
          Content = "你有问题，该叫应天尉了。",
          DialogueId = 51113004,
          GUID = "7FF4BF38",
          ImprPlusId = 1208,
          NextDialogue = 51113005
        },
        [51113005] = {
          Content = "诶诶诶，你这小朋友好生奇怪，见了我这华胥知名的品香大师不顶礼膜拜也就罢了，居然还做出这般无礼的反应。",
          DialogueId = 51113005,
          GUID = "7FF4BF62",
          LookAt = {
            [1] = "701014:n(0)"
          },
          NextOptions = {
            [1] = 51113006,
            [2] = 51113007
          },
          SpeakNpcId = 701014
        },
        [51113006] = {
          Content = "还整上优越感了。",
          DialogueId = 51113006,
          GUID = "7FF4BF8C",
          ImprPlusId = 1210,
          NextDialogue = 51113008
        },
        [51113007] = {
          Content = "好熟悉的骗子话术。",
          DialogueId = 51113007,
          GUID = "7FF4BFB6",
          ImprPlusId = 1206,
          NextDialogue = 51113008
        },
        [51113008] = {
          Content = "嘿，这我可得跟你好好说道说道了。",
          DialogueId = 51113008,
          GUID = "7FF4BFE0",
          NextDialogue = 51113009,
          SpeakNpcId = 701014,
          TalkActionId = {
            [1] = "701014:Talk01_Start"
          }
        },
        [51113009] = {
          Content = "点香这事，大部分人也就走个流程，却忽略了香本身就是一件艺术品的事实。",
          DialogueId = 51113009,
          GUID = "7FF4C00A",
          NextDialogue = 51113010,
          SpeakNpcId = 701014
        },
        [51113010] = {
          Content = "且说这百年春制的香……让我再闻一口啊……",
          DialogueId = 51113010,
          GUID = "7FF4C034",
          NextDialogue = 51113011,
          SpeakNpcId = 701014
        },
        [51113011] = {
          Content = "嗯~想必是用了浮星埠周遭的碧檀木，辅以青云艾、浮露草而成。",
          DialogueId = 51113011,
          GUID = "7FF4C05E",
          NextDialogue = 51113012,
          SpeakNpcId = 701014
        },
        [51113012] = {
          Content = "烟津渡自古以来便是华胥的航运要地，这里的水不仅养人，还造就了得天独厚的生态，百年春就地取材制香，妙哉妙哉。",
          DialogueId = 51113012,
          GUID = "7FF4C088",
          NextDialogue = 51113013,
          SpeakNpcId = 701014
        },
        [51113013] = {
          Content = "你闻闻，能体会到木头那种粗犷的，刺刺的感觉吗？",
          DialogueId = 51113013,
          GUID = "7FF4C0B2",
          NextDialogue = 51113014,
          SpeakNpcId = 701014,
          TalkActionId = {
            [1] = "701014:Talk01_End"
          }
        },
        [51113014] = {
          Content = "没有。",
          DialogueId = 51113014,
          GUID = "7FF4C0DC",
          NextDialogue = 51113015,
          SpeakNpcId = 100001
        },
        [51113015] = {
          Content = "好吧好吧，那你再闻闻这皓京产的香，能感觉到有什么不同吗？",
          DialogueId = 51113015,
          GUID = "7FF4C106",
          NextDialogue = 51113016,
          SpeakNpcId = 701014,
          TalkActionId = {
            [1] = "701014:Give"
          }
        },
        [51113016] = {
          Content = "（男人从怀里取出一根香，点燃后递到你的面前。）",
          DialogueId = 51113016,
          GUID = "7FF4C130",
          NextDialogue = 51113017
        },
        [51113017] = {
          Content = "还是没有。",
          DialogueId = 51113017,
          GUID = "7FF4C15A",
          NextDialogue = 51113018,
          SpeakNpcId = 100001
        },
        [51113018] = {
          Content = "皓京群山环绕，制香者常采山中原料炮制，所以那里产的香总带着一点苦涩。",
          DialogueId = 51113018,
          GUID = "7FF4C184",
          NextDialogue = 51113019,
          SpeakNpcId = 701014,
          TalkActionId = {
            [1] = "701014:Confident_Start"
          }
        },
        [51113019] = {
          Content = "但苦涩之后鼻腔之中便能嗅到一丝芬芳，就像攀登山崖的辛苦，在抵达顶峰之后一扫而空一样。",
          DialogueId = 51113019,
          GUID = "7FF4C1AE",
          NextDialogue = 51113020,
          SpeakNpcId = 701014
        },
        [51113020] = {
          Content = "以后你要是有机会去到皓京的山巅，想必就能理解我说的这种感觉了。",
          DialogueId = 51113020,
          GUID = "7FF4C1D8",
          NextDialogue = 51113021,
          SpeakNpcId = 701014
        },
        [51113021] = {
          Content = "（男人说完，突然向着远方猛吸了一口气。）",
          DialogueId = 51113021,
          GUID = "7FF4C202",
          NextDialogue = 51113022
        },
        [51113022] = {
          Content = "嘶……那边有股不一样的香气……",
          DialogueId = 51113022,
          GUID = "7FF4C22C",
          NextDialogue = 51113023,
          SpeakNpcId = 701014
        },
        [51113023] = {
          Content = "好了，闲话就说到这，我该继续寻香去了，有缘再会~",
          DialogueId = 51113023,
          GUID = "7FF4C256",
          LookAt = {
            [1] = "701014:n(701014)"
          },
          NextDialogue = 51113024,
          SpeakNpcId = 701014,
          TalkActionId = {
            [1] = "701014:Confident_End"
          }
        },
        [51113024] = {
          Content = "（他说完便向着远处狂奔，哪怕已经离了很远，你好像还是能听到他那爽也爽也的喊声。）",
          DialogueId = 51113024,
          GUID = "7FF4C280",
          Scripts = "MoveTo{ActorId{701014},TargetPoint{"WuYe_Target"},MoveSpeed{120},Visibility{"Hide"}}"
        },
        [51114000] = {
          Content = "这位{性别：小兄弟|姑娘}，请留步！可否帮个小忙？",
          DialogueId = 51114000,
          GUID = "7FF562A0",
          NextDialogue = 51114001,
          SpeakNpcId = 701015
        },
        [51114001] = {
          Content = "我的孩子吵着想吃梨，但眼下我不便离开，可否请你帮我买两个来？放心，报酬不会少了你的。",
          DialogueId = 51114001,
          GUID = "7FF562CA",
          NextOptions = {
            [1] = 51114002
          },
          RestartTag = 51114001,
          SpeakNpcId = 701015
        },
        [51114002] = {
          Content = "有报酬……",
          DialogueId = 51114002,
          FailDialogue = 51114003,
          GUID = "7FF562F4",
          ImprCheckId = 1123,
          NextDialogue = 51114004
        },
        [51114003] = {
          Content = "（有报酬你也懒得管。）",
          DialogueId = 51114003,
          GUID = "7FF5631E"
        },
        [51114004] = {
          Content = "好，我帮你买。",
          DialogueId = 51114004,
          GUID = "7FF56348",
          SpeakNpcId = 100001
        },
        [51114005] = {
          Content = "你按照男人的交代，去附近的水果铺子买了两只梨。",
          DialogueId = 51114005,
          GUID = "7FF56372",
          NextDialogue = 51114006
        },
        [51114006] = {
          Content = "只是当你回到原地的时候，这里的家长和小孩不知何时如同被复制一般变成了两组。",
          DialogueId = 51114006,
          GUID = "7FF5639C",
          NextDialogue = 51114007
        },
        [51114007] = {
          Content = "我把梨买回来了。",
          DialogueId = 51114007,
          GUID = "7FF563C6",
          NextDialogue = 51114008,
          SpeakNpcId = 100001
        },
        [51114008] = {
          Content = "谢谢{性别：小兄弟|姑娘}！",
          DialogueId = 51114008,
          GUID = "7FF563F0",
          NextDialogue = 51114009,
          SpeakNpcId = 701015
        },
        [51114009] = {
          Content = "哇，有梨吃了！",
          DialogueId = 51114009,
          GUID = "7FF5641A",
          NextDialogue = 51114010,
          SpeakNpcId = 701016
        },
        [51114010] = {
          Content = "梨……我也想吃……",
          DialogueId = 51114010,
          GUID = "7FF56444",
          NextDialogue = 51114011,
          SpeakNpcId = 701018
        },
        [51114011] = {
          Content = "你这孩子，怎么能馋别人的东西！",
          DialogueId = 51114011,
          GUID = "7FF5646E",
          NextDialogue = 51114012,
          SpeakNpcId = 701017
        },
        [51114012] = {
          Content = "无妨，恰好这里有两个梨，给孩子们一人一个吧。",
          DialogueId = 51114012,
          GUID = "7FF56498",
          NextDialogue = 51114013,
          SpeakNpcId = 701015
        },
        [51114013] = {
          Content = "（小杨伸手拿起了较大的那只梨。）",
          DialogueId = 51114013,
          GUID = "7FF564C2",
          NextDialogue = 51114014
        },
        [51114014] = {
          Content = "瞧瞧，你这孩子真不懂事，哥哥是客人，你应该把大的让给他。",
          DialogueId = 51114014,
          GUID = "7FF564EC",
          NextDialogue = 51114015,
          SpeakNpcId = 701015
        },
        [51114015] = {
          Content = "哥哥，给你……",
          DialogueId = 51114015,
          GUID = "7FF56516",
          NextDialogue = 51114016,
          SpeakNpcId = 701016
        },
        [51114016] = {
          Content = "（小杨苦着脸把大梨递给了小张，小张欢天喜地地接了过去。）",
          DialogueId = 51114016,
          GUID = "7FF56540",
          NextDialogue = 51114017
        },
        [51114017] = {
          Content = "不行，这怎么好意思！弟弟年纪小，你快把大的让给弟弟。",
          DialogueId = 51114017,
          GUID = "7FF5656A",
          NextDialogue = 51114018,
          SpeakNpcId = 701017
        },
        [51114018] = {
          Content = "还是给你吧，弟弟……",
          DialogueId = 51114018,
          GUID = "7FF56594",
          NextDialogue = 51114019,
          SpeakNpcId = 701018
        },
        [51114019] = {
          Content = "（小张把大梨还了回去，他脸上的笑容也随之转移到了小杨脸上。）",
          DialogueId = 51114019,
          GUID = "7FF565BE",
          NextDialogue = 51114020
        },
        [51114020] = {
          Content = "张兄不必客气，小张这年纪正是长身体的时候，该多吃点。",
          DialogueId = 51114020,
          GUID = "7FF565E8",
          NextDialogue = 51114021,
          SpeakNpcId = 701015
        },
        [51114021] = {
          Content = "这梨是你们买的，我们白拿来吃已经很惭愧了，怎么能还挑大的呢……",
          DialogueId = 51114021,
          GUID = "7FF56612",
          NextDialogue = 51114022,
          SpeakNpcId = 701017
        },
        [51114022] = {
