          DialogueId = 51114022,
          GUID = "7FF5663C",
          NextDialogue = 51114023,
          SpeakNpcId = 701016
        },
        [51114023] = {
          Content = "（两个孩子眼巴巴地看向你，似乎很希望你能结束这场推让。）",
          DialogueId = 51114023,
          GUID = "7FF56666",
          NextOptions = {
            [1] = 51114024,
            [2] = 51114026,
            [3] = 51114028
          }
        },
        [51114024] = {
          Content = "要不我再去买两个一样大的？",
          DialogueId = 51114024,
          GUID = "7FF56690",
          ImprPlusId = 1207,
          NextDialogue = 51114025
        },
        [51114025] = {
          Content = "再劳烦你就说不过去了……",
          DialogueId = 51114025,
          GUID = "7FF566BA",
          NextDialogue = 51114029,
          SpeakNpcId = 701015
        },
        [51114026] = {
          Content = "切成片大家分着吃吧。",
          DialogueId = 51114026,
          GUID = "7FF566E4",
          ImprPlusId = 1208,
          NextDialogue = 51114029
        },
        [51114027] = {
          Content = "万万不可，把梨切开就成了“分离”，不吉利的。",
          DialogueId = 51114027,
          GUID = "7FF5670E",
          NextDialogue = 51114028,
          SpeakNpcId = 701015
        },
        [51114028] = {
          Content = "我是外国人，我也长身体，两个都给我吃。",
          DialogueId = 51114028,
          GUID = "7FF56738",
          ImprPlusId = 1210,
          NextDialogue = 51114029
        },
        [51114029] = {
          Content = "这位{性别：小兄弟|姑娘}说话真是风趣……",
          DialogueId = 51114029,
          GUID = "7FF56762",
          NextDialogue = 51114030,
          SpeakNpcId = 701015
        },
        [51114030] = {
          Content = "真是对不住，我们光顾着推让，把你晾在一边了。",
          DialogueId = 51114030,
          GUID = "7FF5678C",
          NextDialogue = 51114031,
          SpeakNpcId = 701015
        },
        [51114031] = {
          Content = "来，{性别：小兄弟|姑娘}，请收下报酬吧。",
          DialogueId = 51114031,
          GUID = "7FF567B6",
          NextDialogue = 51114032,
