          NextDialogue = 51117029,
          Scripts = "MoveTo{ActorId{701023},TargetPoint{"YuXian_Target"},MoveSpeed{100},Visibility{"Show"}}",
          SpeakNpcId = 701023
        },
        [51117029] = {
          Camera = "-157.855469,429.066406,150.193359,0.000067,-5.60486,-83.644531,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我们正在辩论那个白色影子的真身呢！",
          DialogueId = 51117029,
          GUID = "7FF75392",
          LookAt = {
            [1] = "701021:n(701021)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117030,
          SpeakNpcId = 701021
        },
        [51117030] = {
          Content = "噢，这个呀，我已经知道啦。我昨天经过这里的时候恰好遇见了住在里面的姐姐，她说那个白色的影子是“鱼龙”。",
          DialogueId = 51117030,
          GUID = "7FF753BC",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(701023)"
          },
          NextDialogue = 51117031,
          SpeakNpcId = 701023,
          TalkActionId = {
            [1] = "701023:Explain01_Start"
          }
        },
        [51117031] = {
          Content = "她解释了一大堆什么“寄托”呀，“思念”呀什么的，我不太听得懂……反正就是类似于小宠物的东西啦！",
          DialogueId = 51117031,
          GUID = "7FF753E6",
          NextDialogue = 51117032,
          SpeakNpcId = 701023
        },
        [51117032] = {
          Content = "她还变了一只出来给我看呢，“鱼龙”摸上去就像水做的一样，凉凉的，可神奇了！",
          DialogueId = 51117032,
          GUID = "7FF75410",
          NextDialogue = 51117033,
          SpeakNpcId = 701023,
          TalkActionId = {
            [1] = "701023:Explain01_End"
          }
        },
        [51117033] = {
          Content = "什么？！",
          DialogueId = 51117033,
          GUID = "7FF7543A",
          LookAt = {
            [1] = "701021:n(701021)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117034,
          SpeakNpcId = 701021
        },
        [51117034] = {
          Content = "居、居然真的是小宠物……",
          DialogueId = 51117034,
          GUID = "7FF75464",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117035,
          SpeakNpcId = 701023
        },
        [51117035] = {
          Content = "没想到最后是这个{性别：大哥哥|大姐姐}猜对了……",
          DialogueId = 51117035,
          GUID = "7FF7548E",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)",
            [3] = "100001:n(100001)",
            [4] = "701023:n(100001)"
          },
          NextOptions = {
            [1] = 51117036,
            [2] = 51117040,
            [3] = 51117044
          },
          SpeakNpcId = 701021
        },
        [51117036] = {
          Content = "其实是因为我也见过那位姐姐，所以才能猜对的。",
          DialogueId = 51117036,
          GUID = "7FF754B8",
          ImprPlusId = 1207,
          NextDialogue = 51117037
        },
        [51117037] = {
          Content = "怎么你也见过？那我也要见。",
          DialogueId = 51117037,
          GUID = "7FF754E2",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117038,
          SpeakNpcId = 701021,
          TalkActionId = {
            [1] = "701021:Talk01_Start"
          }
        },
        [51117038] = {
          Content = "我也要，我也要！",
          DialogueId = 51117038,
          GUID = "7FF7550C",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117039,
          SpeakNpcId = 701022
        },
        [51117039] = {
          Content = "嗯……那下次我们带点好吃的去找那个姐姐玩，让她也给我们看看“鱼龙”吧~",
          DialogueId = 51117039,
          GUID = "7FF75536",
