          },
          NextDialogue = 51117047,
          SpeakNpcId = 701021,
          TalkActionId = {
            [1] = "701022:Talk01_End"
          }
        },
        [51117047] = {
          Content = "那你们还在这儿玩什么呀，赶快回去做功课啦。",
          DialogueId = 51117047,
          GUID = "7FF75686",
          LookAt = {
            [1] = "701021:n(701023)",
