            [4] = "701023:n(701023)"
          },
          NextDialogue = 51117048,
          SpeakNpcId = 701023
        },
        [51117048] = {
          Content = "（孩子们有说有笑地离开了。也许，下次见到扶疏的时候，可以把这件趣闻说给她听听。）",
          DialogueId = 51117048,
          GUID = "7FF756B0",
          Scripts = "PARA{\nMoveTo{ActorId{701021},TargetPoint{\"LanYe_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}},\nMoveTo{ActorId{701022},TargetPoint{\"WangNan_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}},\nMoveTo{ActorId{701023},TargetPoint{\"YuXian_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}}\n}"
        },
        [51118000] = {
          Content = "呜……怎么还没来……",
          DialogueId = 51118000,
          GUID = "7FF7F2E0",
          NextDialogue = 51118001,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Sigh_Start"
          }
        },
        [51118001] = {
          Content = "（小女孩半睁着眼睛，坐在屋檐下嘟囔着什么。当你经过的时候，她忽然一头栽倒在地。）",
          DialogueId = 51118001,
          GUID = "7FF7F30A",
          NextDialogue = 51118002
        },
        [51118002] = {
          Content = "哎？！",
          DialogueId = 51118002,
          GUID = "7FF7F334",
          NextDialogue = 51118003,
          SpeakNpcId = 100001
        },
        [51118003] = {
          Content = "（你连忙上前查看。被你拍了拍肩膀之后，小女孩睁开眼睛，从地上爬了起来。）",
          DialogueId = 51118003,
          GUID = "7FF7F35E",
          NextDialogue = 51118004
        },
        [51118004] = {
          Content = "唔……",
          DialogueId = 51118004,
          GUID = "7FF7F388",
          NextOptions = {
            [1] = 51118005
          }
        },
        [51118005] = {
          Content = "小妹妹，你还好吗？",
          DialogueId = 51118005,
          GUID = "7FF7F3B2",
          NextDialogue = 51118006
        },
        [51118006] = {
          Content = "啊，我没事，我只是太困了……谢谢你，{性别：大哥哥|大姐姐}。",
          DialogueId = 51118006,
          GUID = "7FF7F3DC",
          LookAt = {
            [1] = "701024:n(0)"
          },
          NextDialogue = 51118007,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Sigh_End"
          }
        },
        [51118007] = {
          Content = "既然困了，怎么不回去休息？",
          DialogueId = 51118007,
          GUID = "7FF7F406",
          NextDialogue = 51118008,
          SpeakNpcId = 100001
        },
        [51118008] = {
          Content = "我在等我哥哥！他是个织星客，平常总是在外面游历，但每年这个时候，他都会带礼物和信给我。",
          DialogueId = 51118008,
          GUID = "7FF7F430",
          NextDialogue = 51118009,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Talk02_Start"
          }
        },
        [51118009] = {
          Content = "不能在家里等吗？",
          DialogueId = 51118009,
          GUID = "7FF7F45A",
          NextDialogue = 51118010,
          SpeakNpcId = 100001
        },
        [51118010] = {
          Content = "那就会和他错过了。他每次来都不进家门，只会早早地把东西放在门口。等我起床看到的时候，他早就不见了。",
          DialogueId = 51118010,
          GUID = "7FF7F484",
          NextDialogue = 51118011,
          SpeakNpcId = 701024
        },
        [51118011] = {
          Content = "所以我今年打算在门口等着，一定要当面见到他！",
          DialogueId = 51118011,
          GUID = "7FF7F4AE",
          NextDialogue = 51118012,
          SpeakNpcId = 701024
        },
        [51118012] = {
          Content = "但我也不知道他会几点来，所以只好从三更天就开始等……哈欠……结果等到现在他也没来……哈欠……",
          DialogueId = 51118012,
          GUID = "7FF7F4D8",
          NextOptions = {
            [1] = 51118013
          },
          RestartTag = 51118012,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Talk02_End"
          }
        },
        [51118013] = {
          Content = "（想想该怎么帮助她。）",
          DialogueId = 51118013,
          FailDialogue = 51118014,
          GUID = "7FF7F502",
          ImprCheckId = 1126,
          NextDialogue = 51118015
        },
        [51118014] = {
          Content = "（哈欠……你也有点困了。）",
          DialogueId = 51118014,
          GUID = "7FF7F52C"
        },
        [51118015] = {
          Content = "会不会就是因为你在这里等着，所以他才不出现的？",
          DialogueId = 51118015,
          GUID = "7FF7F556",
          NextDialogue = 51118016,
          SpeakNpcId = 100001
        },
        [51118016] = {
          Content = "咦？什么意思？",
          DialogueId = 51118016,
          GUID = "7FF7F580",
          NextDialogue = 51118017,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Think_Start"
          }
        },
        [51118017] = {
          Content = "也许他是想要给你一个惊喜啊。",
          DialogueId = 51118017,
          GUID = "7FF7F5AA",
          NextDialogue = 51118018,
          SpeakNpcId = 100001
        },
        [51118018] = {
          Content = "可是比起惊喜，我更想见到他……",
          DialogueId = 51118018,
          GUID = "7FF7F5D4",
          NextDialogue = 51118019,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Think_End"
          }
        },
        [51118019] = {
          Content = "那我有个办法。",
          DialogueId = 51118019,
          GUID = "7FF7F5FE",
          NextDialogue = 51118020,
          SpeakNpcId = 100001
        },
        [51118020] = {
          Content = "你现在进屋去，假装休息。我到对面的角落帮你盯着这扇门，如果看到你哥哥出现，我就把他拦下来。怎么样？",
          DialogueId = 51118020,
          GUID = "7FF7F628",
          NextDialogue = 51118021,
          SpeakNpcId = 100001
        },
        [51118021] = {
          Content = "哈欠……咦？！所以，{性别：大哥哥|大姐姐}你要帮我等吗？好呀好呀，你真是个好人！",
          DialogueId = 51118021,
          GUID = "7FF7F652",
          NextDialogue = 51118022,
          SpeakNpcId = 701024
        },
        [51118022] = {
          Content = "你哥哥叫什么名字？",
          DialogueId = 51118022,
          GUID = "7FF7F67C",
          NextDialogue = 51118023,
          SpeakNpcId = 100001
        },
        [51118023] = {
          Content = "他叫朝雨。",
          DialogueId = 51118023,
          GUID = "7FF7F6A6",
          NextDialogue = 51118024,
          SpeakNpcId = 701024
        },
        [51118024] = {
          Content = "好的，我记住了。",
          DialogueId = 51118024,
          GUID = "7FF7F6D0",
          NextDialogue = 51118025,
          SpeakNpcId = 100001
        },
        [51118025] = {
          Content = "（女孩揉着眼睛，晃晃悠悠地进屋休息去了。你来到角落，悄悄观察周围的动静。）",
          DialogueId = 51118025,
          GUID = "7FF7F6FA"
        },
        [51118026] = {
          Content = "（果不其然，就在女孩离开后没多久，一位青年男子便现身了。他四下打量了一番，飞快地将一个包裹放在了门口，然后转身离去。）",
          DialogueId = 51118026,
          GUID = "7FF7F724",
          NextDialogue = 51118027
        },
        [51118027] = {
          Content = "等等！",
          DialogueId = 51118027,
          GUID = "7FF7F74E",
          LookAt = {
            [1] = "701025:n(0)"
          },
          NextDialogue = 51118028,
          SpeakNpcId = 100001
        },
        [51118028] = {
          Content = "哎？！",
          DialogueId = 51118028,
          GUID = "7FF7F778",
          NextDialogue = 51118029,
          SpeakNpcId = 701025,
          TalkActionId = {
            [1] = "701025:Shock_Start"
          }
        },
        [51118029] = {
          Content = "你就是朝雨吧！",
          DialogueId = 51118029,
          GUID = "7FF7F7A2",
          NextDialogue = 51118030,
          SpeakNpcId = 100001
        },
        [51118030] = {
          Content = "（听到这个名字，男子显得很惊讶。他愣了一会儿，然后才开口。）",
          DialogueId = 51118030,
          GUID = "7FF7F7CC",
          NextDialogue = 51118031,
          TalkActionId = {
            [1] = "701025:Shock_End"
          }
        },
        [51118031] = {
          Content = "不……我不是朝雨。",
          DialogueId = 51118031,
          GUID = "7FF7F7F6",
          NextDialogue = 51118032,
          SpeakNpcId = 701025,
          TalkActionId = {
            [1] = "701025:Talk01_Start"
          }
        },
        [51118032] = {
          Content = "你为何会知道这个名字？你认识他吗？",
          DialogueId = 51118032,
          GUID = "7FF7F820",
          NextDialogue = 51118033,
          SpeakNpcId = 701025
        },
        [51118033] = {
          Content = "我认识他的妹妹，他妹妹一直在等他出现。",
          DialogueId = 51118033,
          GUID = "7FF7F84A",
          NextDialogue = 51118034,
          SpeakNpcId = 100001
        },
        [51118034] = {
          Content = "是吗……原来青青一直坐在门口，是想见哥哥啊。",
          DialogueId = 51118034,
          GUID = "7FF7F874",
          NextDialogue = 51118035,
          SpeakNpcId = 701025,
          TalkActionId = {
            [1] = "701025:Talk01_End"
          }
        },
        [51118035] = {
          Content = "但她怕是等不到了。",
          DialogueId = 51118035,
          GUID = "7FF7F89E",
          NextDialogue = 51118036,
          SpeakNpcId = 701025
        },
        [51118036] = {
          Content = "为什么？你是谁？",
          DialogueId = 51118036,
          GUID = "7FF7F8C8",
          NextDialogue = 51118037,
          SpeakNpcId = 100001
        },
        [51118037] = {
          Content = "我是朝雨的旧友。几年前，我们在同一个商队出海远航时，不慎遭遇了海难。朝雨他……为了救不通水性的我，不幸去世了。",
          DialogueId = 51118037,
          GUID = "7FF7F8F2",
          NextDialogue = 51118038,
          SpeakNpcId = 701025,
          TalkActionId = {
            [1] = "701025:Talk02_Start"
          }
        },
        [51118038] = {
          Content = "这份救命之恩，我无以为报……但至少不忍看他疼爱的幼妹伤心，所以就想了这个办法。",
          DialogueId = 51118038,
          GUID = "7FF7F91C",
          NextDialogue = 51118039,
          SpeakNpcId = 701025
        },
        [51118039] = {
          Content = "在青青成年之前，我会假装成朝雨，每年给她送来礼物和信件。",
          DialogueId = 51118039,
          GUID = "7FF7F946",
          NextDialogue = 51118040,
          SpeakNpcId = 701025
        },
        [51118040] = {
          Content = "竟然是这样……",
          DialogueId = 51118040,
          GUID = "7FF7F970",
          NextDialogue = 51118041,
          SpeakNpcId = 100001
        },
        [51118041] = {
          Content = "是的……所以，还请你对青青保密。",
          DialogueId = 51118041,
          GUID = "7FF7F99A",
          NextDialogue = 51118042,
          SpeakNpcId = 701025,
          TalkActionId = {
            [1] = "701025:Talk02_End"
          }
        },
        [51118042] = {
          Content = "我明白了。",
          DialogueId = 51118042,
          GUID = "7FF7F9C4",
          SpeakNpcId = 100001
        },
        [51118043] = {
          Content = "（你思考了一会儿，然后敲了敲门。）",
          DialogueId = 51118043,
          GUID = "7FF7F9EE",
          NextOptions = {
            [1] = 51118044
          }
        },
        [51118044] = {
          Content = "青青？",
          DialogueId = 51118044,
          GUID = "7FF7FA18",
          NextDialogue = 51118045
        },
        [51118045] = {
          Content = "{性别：大哥哥|大姐姐}，怎么啦？咦，你手上那是——是哥哥来了吗？他在哪里？",
          DialogueId = 51118045,
          GUID = "7FF7FA42",
          LookAt = {
            [1] = "701024:n(0)"
          },
          NextDialogue = 51118046,
          SpeakNpcId = 701024
        },
        [51118046] = {
          Content = "他已经走了。",
          DialogueId = 51118046,
          GUID = "7FF7FA6C",
          NextDialogue = 51118047,
          SpeakNpcId = 100001
        },
        [51118047] = {
          Content = "什么？你不是答应我要拦下他的吗？呜呜……",
          DialogueId = 51118047,
          GUID = "7FF7FA96",
          NextOptions = {
            [1] = 51118048,
            [2] = 51118052
          },
          SpeakNpcId = 701024
        },
        [51118048] = {
          Content = "你哥哥工作很辛苦，不想让你担心。",
          DialogueId = 51118048,
          GUID = "7FF7FAC0",
          ImprPlusId = 1209,
          NextDialogue = 51118049
        },
        [51118049] = {
          Content = "他说自己常年风餐露宿，消瘦了不少，怕你看见会担心，所以才不露面。我看他好像很累，就没有强行拦下他。",
          DialogueId = 51118049,
          GUID = "7FF7FAEA",
          NextDialogue = 51118050,
          SpeakNpcId = 100001
        },
        [51118050] = {
          Content = "居然是这样……可是见不到他我会更担心呀，笨哥哥……",
          DialogueId = 51118050,
          GUID = "7FF7FB14",
          NextDialogue = 51118051,
          SpeakNpcId = 701024
        },
        [51118051] = {
          Content = "他说等他身体好一点，就一定会回来看你的。在那之前，你要照顾好自己。",
          DialogueId = 51118051,
          GUID = "7FF7FB3E",
          NextDialogue = 51118058,
          SpeakNpcId = 100001
        },
        [51118052] = {
          Content = "你哥哥在参加一场超级商战，分秒必争！",
          DialogueId = 51118052,
          GUID = "7FF7FB68",
          ImprPlusId = 1208,
          NextDialogue = 51118053
        },
        [51118053] = {
          Content = "“商战”……？那是什么？",
          DialogueId = 51118053,
          GUID = "7FF7FB92",
          NextDialogue = 51118054,
          SpeakNpcId = 701024
        },
        [51118054] = {
          Content = "商战就是一种比谁挣钱更多、更快的游戏。你哥哥想要赢下第一名，所以一秒钟都不能耽误呢！",
          DialogueId = 51118054,
          GUID = "7FF7FBBC",
          NextDialogue = 51118055,
          SpeakNpcId = 100001
        },
        [51118055] = {
          Content = "刚才他一放下礼物就跑了，这些还是他的同事告诉我的。",
          DialogueId = 51118055,
          GUID = "7FF7FBE6",
          NextDialogue = 51118056,
          SpeakNpcId = 100001
        },
        [51118056] = {
          Content = "原来是这样啊！那我要给哥哥加油！",
          DialogueId = 51118056,
          GUID = "7FF7FC10",
          NextDialogue = 51118057,
          SpeakNpcId = 701024
        },
        [51118057] = {
          Content = "他说你只要照顾好自己就行了，等他赢了游戏，一定会回来看你的。",
          DialogueId = 51118057,
          GUID = "7FF7FC3A",
          NextDialogue = 51118058,
          SpeakNpcId = 100001
        },
        [51118058] = {
          Content = "嗯嗯，那我要回去好好睡一觉，不然哥哥会担心的……",
          DialogueId = 51118058,
          GUID = "7FF7FC64",
          NextDialogue = 51118059,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Think_Start"
          }
        },
        [51118059] = {
          Content = "谢谢你帮我，{性别：大哥哥|大姐姐}，再见……哈欠……",
          DialogueId = 51118059,
          GUID = "7FF7FC8E",
          NextDialogue = 51118060,
          SpeakNpcId = 701024,
          TalkActionId = {
            [1] = "701024:Think_End"
          }
        },
        [51118060] = {
          Content = "（女孩给了你报酬，然后带着一脸满足的笑容接过礼物，进屋去了。）",
          DialogueId = 51118060,
          GUID = "7FF7FCB8",
          NextDialogue = 51118061
        },
        [51118061] = {
          Content = "（等到真相被揭穿的那一天，她还能再露出这样的笑容吗……？）",
          DialogueId = 51118061,
          GUID = "7FF7FCE2"
        },
        [51119000] = {
          Content = "金口一张白龙降，折扇轻摇故事来。诸位乡亲，诸位父老，诸位不远万里来到华胥的外乡客，大家且听我一言！",
          DialogueId = 51119000,
          GUID = "7FF896F0",
          NextDialogue = 51119001,
          SpeakNpcId = 701026,
          TalkActionId = {
            [1] = "701026:Talk01_Start"
          }
        },
        [51119001] = {
          Content = "鄙人名唤权都通，曾被白龙神君赐号——全通先生。平时最爱与诸位挚爱亲朋分享这世间百态趣事，今日便有一桩趣闻想与各位说道说道。",
          DialogueId = 51119001,
          GUID = "7FF8971A",
          NextDialogue = 51119002,
          SpeakNpcId = 701026
        },
        [51119002] = {
          Content = "不过呢……今日天气燥热，我这喉咙啊也焦渴难耐，若是诸位能先赏点银钱让我买壶茶水润润喉咙，或许这故事就能说得更好。",
          DialogueId = 51119002,
          GUID = "7FF89744",
          LookAt = {
            [1] = "701026:n(0)"
          },
          NextOptions = {
            [1] = 51119003,
            [2] = 51119005,
            [3] = 51119007
          },
          SpeakNpcId = 701026,
          TalkActionId = {
            [1] = "701026:Talk01_End"
          }
        },
        [51119003] = {
          Content = "白龙神君赐号？骗人的吧？",
          DialogueId = 51119003,
          GUID = "7FF8976E",
          ImprPlusId = 1208,
          NextDialogue = 51119004
        },
        [51119004] = {
          Content = "名号的确是假的，白龙神君并未与我赐号，但要不是如此吆喝，如何才能让诸位听众驻足呢？白龙神君即使知晓，想必也不会怪罪于我。",
          DialogueId = 51119004,
          GUID = "7FF89798",
          NextDialogue = 51119009,
          SpeakNpcId = 701026
        },
        [51119005] = {
          Content = "你得说的好才能讨钱吧。",
          DialogueId = 51119005,
          GUID = "7FF897C2",
          ImprPlusId = 1206,
          NextDialogue = 51119006
        },
        [51119006] = {
          Content = "这位外乡客说的是，此举只凭自愿，绝无要挟之意，只是看各位父老是否愿意先让我们龙君青睐的信众喝上口水，解我燃喉之急啊。",
          DialogueId = 51119006,
          GUID = "7FF897EC",
          NextDialogue = 51119009,
          SpeakNpcId = 701026
        },
        [51119007] = {
          Content = "（给他点银钱买茶水。）",
          DialogueId = 51119007,
          GUID = "7FF89816",
          ImprPlusId = 1209,
          NextDialogue = 51119008
        },
        [51119008] = {
          Content = "感谢感谢，外乡客，鄙人记住你的恩情了。",
          DialogueId = 51119008,
          GUID = "7FF89840",
          NextDialogue = 51119009,
          SpeakNpcId = 701026
        },
        [51119009] = {
          Content = "（一些不差钱的围观者递上了银钱，远处很快跑来一名端茶之人，这权都通接过紫砂壶，猛地灌了一口，这才继续说起来。）",
          DialogueId = 51119009,
          GUID = "7FF8986A",
          NextDialogue = 51119010
        },
        [51119010] = {
          Content = "感谢诸位信任，今日，我权都通就为大家说上一个我才听说的趣闻。",
          DialogueId = 51119010,
          GUID = "7FF89894",
          NextDialogue = 51119011,
          SpeakNpcId = 701026,
          TalkActionId = {
            [1] = "701026:Talk02_Start"
          }
        },
        [51119011] = {
          Content = "这华胥境内，哪里最繁华？自然是那皓京城中，这事儿，就发生在皓京。皓京城内呢，有一条狭窄的小巷，巷子两边都住着一户人家，一家姓吕，一家姓马。",
          DialogueId = 51119011,
          GUID = "7FF898BE",
          NextDialogue = 51119012,
          SpeakNpcId = 701026
        },
        [51119012] = {
          Content = "这两家，平日相处很是和睦，端的是相敬如宾啊，但天有变迁，这皓京城内的天禄司，因着皓京城许多住宅年久失修问题，要各家上报宅邸面积。",
          DialogueId = 51119012,
          GUID = "7FF898E8",
          NextDialogue = 51119013,
          SpeakNpcId = 701026
        },
        [51119013] = {
          Content = "这事闹得，上报上去的面积到时候可就是天禄司需要出钱的部分了，为着让上面多关照自家，这吕马两家啊，不约而同都开始琢磨起了扩建一事。",
          DialogueId = 51119013,
          GUID = "7FF89912",
          NextDialogue = 51119014,
          SpeakNpcId = 701026
        },
        [51119014] = {
          Content = "但这小巷之间的地块此前并非两家所属，但也并无文书说明巷中空地归属，这一下可就陷入了僵局。",
          DialogueId = 51119014,
          GUID = "7FF8993C",
          NextDialogue = 51119015,
          SpeakNpcId = 701026
        },
        [51119015] = {
          Content = "吕家说自己院中种了棵梨树，树荫早已罩住巷子，所以那地该是自家的。",
          DialogueId = 51119015,
          GUID = "7FF89966",
          NextDialogue = 51119016,
          SpeakNpcId = 701026
        },
        [51119016] = {
          Content = "马家却说自己原先一直将家中香料放在巷内晾晒，吕家也从未提出异议，说明这地该是他家的呀。",
          DialogueId = 51119016,
          GUID = "7FF89990",
          NextDialogue = 51119017,
          SpeakNpcId = 701026
        },
        [51119017] = {
          Content = "这双方，各执一词，那是吵个昏天黑地，要不是咱们大风九章在上，肯定是要撕打起来的。",
          DialogueId = 51119017,
          GUID = "7FF899BA",
          NextDialogue = 51119018,
          SpeakNpcId = 701026,
          TalkActionId = {
            [1] = "701026:Talk02_End"
          }
        },
        [51119018] = {
          Content = "但话又说到这了，两家都有理，难道此事就没办法了吗？",
          DialogueId = 51119018,
          GUID = "7FF899E4",
          NextDialogue = 51119019,
          SpeakNpcId = 701026
        },
        [51119019] = {
          Content = "（权都通特意顿了一下，似乎在吊人胃口。）",
          DialogueId = 51119019,
          GUID = "7FF89A0E",
          NextDialogue = 51119020
        },
        [51119020] = {
          Content = "对了，大家可别忘了，那可是皓京城，自然是有着许多管理邻里纷争的调解人。",
          DialogueId = 51119020,
          GUID = "7FF89A38",
          NextDialogue = 51119021,
          SpeakNpcId = 701026,
          TalkActionId = {
            [1] = "701026:Explain01_Start"
          }
        },
        [51119021] = {
          Content = "那调解人，一听说此事，便马不停蹄地赶去了，调解者一听两家说出了自己的理由，却是幽幽一笑，当场作诗一首：",
          DialogueId = 51119021,
          GUID = "7FF89A62",
          NextDialogue = 51119022,
          SpeakNpcId = 701026
        },
        [51119022] = {
          Content = "黑蛟鼓惑恶念起，龙君一怒断嗔痴。几番无果闹荒唐，让他三尺又何妨？",
          DialogueId = 51119022,
          GUID = "7FF89A8C",
          NextDialogue = 51119023,
          SpeakNpcId = 701026
        },
        [51119023] = {
          Content = "诶呀！这话的意思说明什么？诸位听众可能听出来？这是要将这争吵不停的二人比作神话里那为非作歹的黑蛟一般，要与白龙神君劝人向善之心对着来！",
          DialogueId = 51119023,
          GUID = "7FF89AB6",
          NextDialogue = 51119024,
          SpeakNpcId = 701026
        },
        [51119024] = {
          Content = "那烛阴恶兽因心生恶念，被白龙神君封印于荒野，而今日，为何在这泱泱华胥又生出贪嗔之人啊？此话一出，两家讪讪，不再争执，各自回去了。",
          DialogueId = 51119024,
          GUID = "7FF89AE0",
          NextDialogue = 51119025,
          SpeakNpcId = 701026
        },
        [51119025] = {
          Content = "于是吕家回去后，为表自己诚心，拆了自家院墙向后三尺，在门口立上了一座白龙神君的雕像。那马家见状，也将自己院墙拆除，向后三尺，摆了同样的雕像。",
          DialogueId = 51119025,
          GUID = "7FF89B0A",
          NextDialogue = 51119026,
          SpeakNpcId = 701026
        },
        [51119026] = {
          Content = "喜哉乐哉！息事宁哉！这巷子后来也成了附近邻居们每每发生争执之时前往理论之地，为的就是让白龙神君见证自己的虔诚之心，从未动摇啊！",
          DialogueId = 51119026,
          GUID = "7FF89B34",
          NextDialogue = 51119027,
          SpeakNpcId = 701026
        },
        [51119027] = {
          Content = "今日鄙人便斗胆改一下诗句，不若改为“向善之心何以见，三尺之争见真心。”诸位看客以为如何？",
          DialogueId = 51119027,
          GUID = "7FF89B5E",
          NextDialogue = 51119028,
          SpeakNpcId = 701026,
          TalkActionId = {
            [1] = "701026:Explain01_End"
          }
        },
        [51119028] = {
          Content = "（路人纷纷向其喝彩，夸赞起白龙神君，权都通又收到了许多打赏，人群逐渐散去……）",
          DialogueId = 51119028,
          GUID = "7FF89B88",
          Scripts = "PARA{\nMoveTo{ActorId{701081},TargetPoint{\"quandoutong_show1\"},MoveSpeed{100},Visibility{\"Hide\"}},\nMoveTo{ActorId{701082},TargetPoint{\"quandoutong_show2\"},MoveSpeed{100},Visibility{\"Hide\"}},\nMoveTo{ActorId{701083},TargetPoint{\"quandoutong_show3\"},MoveSpeed{100},Visibility{\"Hide\"}},\nMoveTo{ActorId{701084},TargetPoint{\"quandoutong_show4\"},MoveSpeed{100},Visibility{\"Hide\"}},\nMoveTo{ActorId{701085},TargetPoint{\"quandoutong_show5\"},MoveSpeed{100},Visibility{\"Hide\"}},\nMoveTo{ActorId{701086},TargetPoint{\"quandoutong_show6\"},MoveSpeed{100},Visibility{\"Hide\"}}\n}"
        },
        [51119029] = {
          Content = "有钱的捧个钱场，没钱的捧个人场！",
          DialogueId = 51119029,
          GUID = "7FF89BB2",
          SpeakNpcId = 701026
        },
        [51120000] = {
          Content = "黄药师，此药服用后有何注意事项？可有忌口？",
          DialogueId = 51120000,
          GUID = "7FF93B00",
          LookAt = {
            [1] = "701028:n(701027)",
            [2] = "701027:n(701028)"
          },
          NextDialogue = 51120001,
          SpeakNpcId = 701028,
          TalkActionId = {
            [1] = "701028:Talk01_Start"
          }
        },
        [51120001] = {
          Content = "自然是有的，你要记得，药效如何全依据你是否遵守我以下所说：",
          DialogueId = 51120001,
          GUID = "7FF93B2A",
          NextDialogue = 51120002,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701028:Talk01_End"
          }
        },
        [51120002] = {
          Content = "其一，这药不可空腹服下，否则体重不减反增。你需一日三餐都吃半饱以上，方可服用。",
          DialogueId = 51120002,
          GUID = "7FF93B54",
          NextDialogue = 51120003,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Talk02_Start"
          }
        },
        [51120003] = {
          Content = "其二，这药副作用猛烈，你需努力运动，我给你一本册子，你按这上面，每日运动一个时辰，直至大汗淋漓，我这药带来的副作用才可被排出。",
          DialogueId = 51120003,
          GUID = "7FF93B7E",
          NextDialogue = 51120004,
          SpeakNpcId = 701027
        },
        [51120004] = {
          Content = "其三，我这药最忌断药，你此次只从我这里买了一月的用量，一月后你需要尽快来我这购入下一月的，若是断药，则你前一个月的效果全都前功尽弃！",
          DialogueId = 51120004,
          GUID = "7FF93BA8",
          NextDialogue = 51120005,
          SpeakNpcId = 701027
        },
        [51120005] = {
          Content = "就是这三点，你可记住了？",
          DialogueId = 51120005,
          GUID = "7FF93BD2",
          NextDialogue = 51120006,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Talk02_End"
          }
        },
        [51120006] = {
          Content = "药师，我这记住是记住了，但这么复杂的要求，你真能保证我在三个月内瘦成一道闪电吗？",
          DialogueId = 51120006,
          GUID = "7FF93BFC",
          NextDialogue = 51120007,
          SpeakNpcId = 701028,
          TalkActionId = {
            [1] = "701028:Think_Start"
          }
        },
        [51120007] = {
          Content = "小雁啊小雁，我黄药师何曾骗过人？若不是我的药灵验，你又如何才能找到我这来？",
          DialogueId = 51120007,
          GUID = "7FF93C26",
          NextDialogue = 51120008,
          SpeakNpcId = 701027
        },
        [51120008] = {
          Content = "好……好像是这个道理……我明白了，这次一定要瘦下去！",
          DialogueId = 51120008,
          GUID = "7FF93C50",
          NextDialogue = 51120009,
          SpeakNpcId = 701028,
          TalkActionId = {
            [1] = "701028:Think_End"
          }
        },
        [51120009] = {
          Content = "（名唤小雁的女孩手持一瓶药，兴致勃勃地跑走了。）",
          DialogueId = 51120009,
          GUID = "7FF93C7A",
          NextDialogue = 51120010,
          Scripts = "MoveTo{ActorId{701028},TargetPoint{"LuoYan_Target"},MoveSpeed{200},Visibility{"Hide"}}"
        },
        [51120010] = {
          Content = "客人好性子，在此处等待如此之久，定是有药相求，说吧，是保身体康健，还是如刚才的小姑娘一般，求个身材窈窕？",
          DialogueId = 51120010,
          GUID = "7FF93CA4",
          LookAt = {
            [1] = "701027:n(0)"
          },
          NextOptions = {
            [1] = 51120011,
            [2] = 51120013,
            [3] = 51120015
          },
          SpeakNpcId = 701027
        },
        [51120011] = {
          Content = "你刚才说的要求，不用吃药也可以瘦下来吧……",
          DialogueId = 51120011,
          GUID = "7FF93CCE",
          ImprPlusId = 1208,
          NextDialogue = 51120012
        },
        [51120012] = {
          Content = "哦？客人聪明呀，这种事情都被你看出来了，的确如此，若是她严格按照我的要求行事，不出三月，恐怕两月便心想事成。",
          DialogueId = 51120012,
          GUID = "7FF93CF8",
          NextDialogue = 51120017,
          SpeakNpcId = 701027
        }
      }
    end
  },
  {
    MinKey = 51120013,
    MaxKey = 51125608,
    Loader = function()
      return {
        [51120013] = {
          Content = "你不会是在卖假药吧？",
          DialogueId = 51120013,
          GUID = "7FF93D22",
          ImprPlusId = 1207,
          NextDialogue = 51120014
        },
        [51120014] = {
          Content = "假药？如何见得？那姑娘现在还没服下一口，客人您也未见成效，如何能断定我卖的是假药呢？",
          DialogueId = 51120014,
          GUID = "7FF93D4C",
          NextDialogue = 51120017,
          SpeakNpcId = 701027
        },
        [51120015] = {
          Content = "你得给我开点封口费了吧。",
          DialogueId = 51120015,
          GUID = "7FF93D76",
          ImprPlusId = 1206,
          NextDialogue = 51120016
        },
        [51120016] = {
          Content = "封口费？为何？我在这交易之地，做着你情我愿的买卖，也不违反大风九章，如何会需要到给客人您封口费的地步呢？",
          DialogueId = 51120016,
          GUID = "7FF93DA0",
          NextDialogue = 51120017,
          SpeakNpcId = 701027
        },
        [51120017] = {
          Content = "你卖给她的究竟是什么？",
          DialogueId = 51120017,
          GUID = "7FF93DCA",
          NextDialogue = 51120018,
          SpeakNpcId = 100001
        },
        [51120018] = {
          Content = "客人既然已经知晓，何必再假意询问，卖的自然是让她心想事成之药，必能达成她心之所愿。",
          DialogueId = 51120018,
          GUID = "7FF93DF4",
          NextDialogue = 51120019,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Explain01_Start"
          }
        },
        [51120019] = {
          Content = "……所以还是假药喽？万一她吃出什么毛病怎么办？",
          DialogueId = 51120019,
          GUID = "7FF93E1E",
          NextDialogue = 51120020,
          SpeakNpcId = 100001
        },
        [51120020] = {
          Content = "呵呵，客人心地善良，但我黄药师也不是什么奸恶之人，不做谋财害命之事。那小姑娘体态康健，却执意想通过节食和药物减肥，实非明智之举。",
          DialogueId = 51120020,
          GUID = "7FF93E48",
          NextDialogue = 51120021,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Explain01_End"
          }
        },
        [51120021] = {
          Content = "所以我建议她好好吃饭的同时，给她开了些补剂，里面掺的是一人日常所需的营养，免得她运动后气血亏空，瘫倒在地啊。",
          DialogueId = 51120021,
          GUID = "7FF93E72",
          NextDialogue = 51120022,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Talk01_Start"
          }
        },
        [51120022] = {
          Content = "你很懂啊？",
          DialogueId = 51120022,
          GUID = "7FF93E9C",
          NextDialogue = 51120023,
          SpeakNpcId = 100001
        },
        [51120023] = {
          Content = "诶？不敢很懂，只敢略懂，客人，小药师我只是做着一些小本生意，勉强在这黑市混口饭吃而已。",
          DialogueId = 51120023,
          GUID = "7FF93EC6",
          NextDialogue = 51120024,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Talk01_End"
          }
        },
        [51120024] = {
          Content = "所以别的药你也是一样的卖法？用补剂代替药品。",
          DialogueId = 51120024,
          GUID = "7FF93EF0",
          NextDialogue = 51120025,
          SpeakNpcId = 100001
        },
        [51120025] = {
          Content = "你们这些家伙总是喜欢刨根问底，有些事睁一只眼闭一只眼便算了罢。我也并未害人，只是让他们以正确的方式去达成他们的目的。",
          DialogueId = 51120025,
          GUID = "7FF93F1A",
          NextDialogue = 51120026,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Talk02_Start"
          }
        },
        [51120026] = {
          Content = "想要长寿，那便早睡早起，健康饮食，想要美丽，那便香薰敷面，减少操劳。客人对药的定义还是过于狭隘了不是吗？",
          DialogueId = 51120026,
          GUID = "7FF93F44",
          NextDialogue = 51120027,
          SpeakNpcId = 701027
        },
        [51120027] = {
          Content = "药，即可以是一方服入腹中便可见效的物品，也可以是一种生活方针，我表面是给了他们药，实际却是指导了他们要如何生活。",
          DialogueId = 51120027,
          GUID = "7FF93F6E",
          NextDialogue = 51120028,
          SpeakNpcId = 701027
        },
        [51120028] = {
          Content = "这样看起来，我拿这钱是否理所应当？",
          DialogueId = 51120028,
          GUID = "7FF93F98",
          NextDialogue = 51120029,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Talk02_End"
          }
        },
        [51120029] = {
          Content = "（好像很有道理……）",
          DialogueId = 51120029,
          GUID = "7FF93FC2",
          NextDialogue = 51120030,
          SpeakNpcId = 100001
        },
        [51120030] = {
          Content = "所以啊，客人莫要纠结了，若是我害人自有应天尉大人来找我麻烦，如何还能让我“作恶多端”呢？",
          DialogueId = 51120030,
          GUID = "7FF93FEC",
          NextDialogue = 51120031,
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Explain01_Start"
          }
        },
        [51120031] = {
          Content = "若是客人不买药，不如往边上让让？把机会让给需要的人？",
          DialogueId = 51120031,
          GUID = "7FF94016",
          SpeakNpcId = 701027,
          TalkActionId = {
            [1] = "701027:Explain01_End"
          }
        },
        [51120032] = {
          Content = "看山看水不如看病，吃素吃肉不如吃我药师的灵丹妙药啊~",
          DialogueId = 51120032,
          GUID = "7FF94040",
          SpeakNpcId = 701027
        },
        [51121000] = {
          Content = "不管怎样，你今日必须给我一个说法！",
          DialogueId = 51121000,
          GUID = "7FF9DF10",
          LookAt = {
            [1] = "701029:n(701030)",
            [2] = "701030:n(701029)"
          },
          NextDialogue = 51121001,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Talk01_Start",
            [2] = "701030:Talk02_Start"
          }
        },
        [51121001] = {
          Content = "说法，什么说法？你别太无理取闹……",
          DialogueId = 51121001,
          GUID = "7FF9DF3A",
          NextOptions = {
            [1] = 51121002,
            [2] = 51121003,
            [3] = 51121004
          },
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701029:Talk01_End",
            [2] = "701030:Talk02_End"
          }
        },
        [51121002] = {
          Content = "看起来吵得有点凶，过去劝劝架吧。",
          DialogueId = 51121002,
          GUID = "7FF9DF64",
          ImprPlusId = 1207,
          NextDialogue = 51121005
        },
        [51121003] = {
          Content = "打起来！打起来！",
          DialogueId = 51121003,
          GUID = "7FF9DF8E",
          ImprPlusId = 1210,
          NextDialogue = 51121005
        },
        [51121004] = {
          Content = "什么事吵成这样……",
          DialogueId = 51121004,
          GUID = "7FF9DFB8",
          ImprPlusId = 1209,
          NextDialogue = 51121005
        },
        [51121005] = {
          Content = "你，对，就是你这个有着满头雪发的{性别：老头|老太}，你过来，帮人家评评理！",
          DialogueId = 51121005,
          GUID = "7FF9DFE2",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121006,
          SpeakNpcId = 701029
        },
        [51121006] = {
          Content = "瞧你这眼神，大好一个{性别：小伙子|小姑娘}都被你看成老人家了。与其在这里丢人现脸，你还是早点回家睡觉吧。",
          DialogueId = 51121006,
          GUID = "7FF9E00C",
          LookAt = {
            [1] = "701029:n(701030)",
            [2] = "701030:n(701029)"
          },
          NextDialogue = 51121007,
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701030:Talk01_Start"
          }
        },
        [51121007] = {
          Content = "你还说！分明就是你害的，要不是你整日昼伏夜出，扰得我日日夜夜睡不上一个好觉，我写书的创意是如何枯竭的，定是被你搅浑了！",
          DialogueId = 51121007,
          GUID = "7FF9E036",
          NextDialogue = 51121008,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701030:Talk01_End"
          }
        },
        [51121008] = {
          Content = "你有完没完，不管我什么时间出门，什么时间回家，都是我的自由，我既没有在回家之时去敲你的门，也没在出门的时候摔你的门，如何惹到你了？",
          DialogueId = 51121008,
          GUID = "7FF9E060",
          NextDialogue = 51121009,
          SpeakNpcId = 701030
        },
        [51121009] = {
          Content = "你那动静，与敲门摔门有何区别？你那又笨又重的靴子在家中踩来踩去，呱唧作响，每回上床之前，要将两只靴子一一甩开，发出咚咚两声。",
          DialogueId = 51121009,
          GUID = "7FF9E08A",
          NextDialogue = 51121010,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Explain01_Start"
          }
        },
        [51121010] = {
          Content = "少胡扯了，之前你来说过一次，我不是后面都尽量想起来放轻声音了吗？",
          DialogueId = 51121010,
          GUID = "7FF9E0B4",
          NextDialogue = 51121011,
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701030:Talk02_Start"
          }
        },
        [51121011] = {
          Content = "对！你只记得放轻第二只靴子，却忘了第一只，我被你那第一只靴子吵醒，一直在等你甩第二只，你却迟迟不甩，我便干等到天亮！",
          DialogueId = 51121011,
          GUID = "7FF9E0DE",
          NextDialogue = 51121012,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Explain01_End"
          }
        },
        [51121012] = {
          Content = "不是……这也怪我吗？况且在那之后我不都已经格外注意了吗，如今每晚不过是在自家正常走动、洗漱，也没见其他邻居来找我。",
          DialogueId = 51121012,
          GUID = "7FF9E108",
          NextDialogue = 51121013,
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701030:Talk02_End"
          }
        },
        [51121013] = {
          Content = "半点声音都听不得，莫不是你自己耳朵有问题。有病就去治，别来烦别人好吗？",
          DialogueId = 51121013,
          GUID = "7FF9E132",
          NextDialogue = 51121014,
          SpeakNpcId = 701030
        },
        [51121014] = {
          Content = "你！你欺人太甚！",
          DialogueId = 51121014,
          GUID = "7FF9E15C",
          NextOptions = {
            [1] = 51121015
          },
          RestartTag = 51121014,
          SpeakNpcId = 701029
        },
        [51121015] = {
          Content = "试试劝架吧。",
          DialogueId = 51121015,
          FailDialogue = 51121016,
          GUID = "7FF9E186",
          ImprCheckId = 1127,
          NextDialogue = 51121017
        },
        [51121016] = {
          Content = "（眼前的二人怒上心头，越吵越激烈，压根听不到你微弱的劝架声……）",
          DialogueId = 51121016,
          GUID = "7FF9E1B0"
        },
        [51121017] = {
          Content = "不要吵了。",
          DialogueId = 51121017,
          GUID = "7FF9E1DA",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121018,
          SpeakNpcId = 100001
        },
        [51121018] = {
          Content = "这位好心人，你刚才也听到了，这家伙作息吊诡，搅我安眠。我本在家中创作写书，创意枯竭，本就神经衰弱，却被这动静搅得连觉也没法睡！",
          DialogueId = 51121018,
          GUID = "7FF9E204",
          NextDialogue = 51121019,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Talk01_Start"
          }
        },
        [51121019] = {
          Content = "我到底闹出什么天大的动静了？连在自家走动都要管，难道非得要我像个贼一样蹑手蹑脚你才能满意？",
          DialogueId = 51121019,
          GUID = "7FF9E22E",
          NextDialogue = 51121020,
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701029:Talk01_End",
            [2] = "701030:Talk02_Start"
          }
        },
        [51121020] = {
          Content = "好了好了……我先问问你，你为什么要昼伏夜出？",
          DialogueId = 51121020,
          GUID = "7FF9E258",
          NextDialogue = 51121021,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "701030:Talk02_End"
          }
        },
        [51121021] = {
          Content = "我吗？我没办法，码头力工本来就是老板让几点过去搬货就几点去，只是最近接到的单子便让我深夜卸货，忙完回来也就天亮了。",
          DialogueId = 51121021,
          GUID = "7FF9E282",
          NextDialogue = 51121022,
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701030:Explain01_Start"
          }
        },
        [51121022] = {
          Content = "你为何要接这种阴间时辰的单子？",
          DialogueId = 51121022,
          GUID = "7FF9E2AC",
          LookAt = {
            [1] = "701029:n(701030)",
            [2] = "701030:n(701029)"
          },
          NextDialogue = 51121023,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Talk02_Start"
          }
        },
        [51121023] = {
          Content = "呵……你以为大家都跟你一样在家躺着就有钱吃饭吗？我不干活哪来的钱吃饭，再说晚上的单子油水足，赚的多啊！",
          DialogueId = 51121023,
          GUID = "7FF9E2D6",
          NextDialogue = 51121024,
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701030:Explain01_End"
          }
        },
        [51121024] = {
          Content = "什么叫我在家躺着就有饭吃？我每日呕心沥血在家钻研字句用词之时，你考虑过我创意的疲乏与苦衷吗？",
          DialogueId = 51121024,
          GUID = "7FF9E300",
          NextDialogue = 51121025,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Talk02_End"
          }
        },
        [51121025] = {
          Content = "听起来你们两个都很有道理。",
          DialogueId = 51121025,
          GUID = "7FF9E32A",
          NextDialogue = 51121026,
          SpeakNpcId = 100001
        },
        [51121026] = {
          Content = "我不管，他就是吵到我睡觉，你给评评理吧！",
          DialogueId = 51121026,
          GUID = "7FF9E354",
          NextDialogue = 51121027,
          SpeakNpcId = 701029
        },
        [51121027] = {
          Content = "快结束这出闹剧吧，哈欠……我还得回家睡觉，晚上上工呢。",
          DialogueId = 51121027,
          GUID = "7FF9E37E",
          NextOptions = {
            [1] = 51121028,
            [2] = 51121034
          },
          SpeakNpcId = 701030
        },
        [51121028] = {
          Content = "帮余下说话。",
          DialogueId = 51121028,
          GUID = "7FF9E3A8",
          NextDialogue = 51121029
        },
        [51121029] = {
          Content = "你的作息时间毕竟和大家都不一样，打扰了他也是事实。所以还是再注意把脚步声放轻点吧。",
          DialogueId = 51121029,
          GUID = "7FF9E3D2",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121030,
          SpeakNpcId = 100001
        },
        [51121030] = {
          Content = "你听你听，还是义士大人说话中肯！",
          DialogueId = 51121030,
          GUID = "7FF9E3FC",
          NextDialogue = 51121031,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Explain01_Start"
          }
        },
        [51121031] = {
          Content = "怎么你也向着他……哼！",
          DialogueId = 51121031,
          GUID = "7FF9E426",
          NextDialogue = 51121032,
          SpeakNpcId = 701030
        },
        [51121032] = {
          Content = "鄙人先行谢过，义士大人您可真是人中龙凤，气度不凡，多谢您为我伸冤！",
          DialogueId = 51121032,
          GUID = "7FF9E450",
          NextDialogue = 51121033,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701029:Explain01_End"
          }
        },
        [51121033] = {
          Content = "他吵到你也是生计所迫，并不是故意的。你们邻居一场，多体谅一些对方的难处吧。",
          DialogueId = 51121033,
          GUID = "7FF9E47A",
          NextDialogue = 51121040,
          SpeakNpcId = 100001
        },
        [51121034] = {
          Content = "帮董筑说话。",
          DialogueId = 51121034,
          GUID = "7FF9E4A4",
          NextDialogue = 51121035
        },
        [51121035] = {
          Content = "如果其他邻居没有和你一样的困扰，也许是你过于敏感了。考虑用棉花把耳朵塞起来如何？",
          DialogueId = 51121035,
          GUID = "7FF9E4CE",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121036,
          SpeakNpcId = 100001
        },
        [51121036] = {
          Content = "听到没？路人都帮我说话，都说了你自己塞上耳朵得了，非要吵来吵去的。",
          DialogueId = 51121036,
          GUID = "7FF9E4F8",
          NextDialogue = 51121037,
          SpeakNpcId = 701030,
          TalkActionId = {
            [1] = "701030:Talk01_Start"
          }
        },
        [51121037] = {
          Content = "你！你有眼无珠！分明就是他的过错，却让我一再忍耐，你们未免太过分了！",
          DialogueId = 51121037,
          GUID = "7FF9E522",
          NextDialogue = 51121038,
          SpeakNpcId = 701029
        },
        [51121038] = {
          Content = "若是我的书出版之后有了钱，定要去皓京买幢独栋别墅，第一时间搬出这里，再不与你这种人同为里邻！",
          DialogueId = 51121038,
          GUID = "7FF9E54C",
          NextDialogue = 51121039,
          SpeakNpcId = 701029,
          TalkActionId = {
            [1] = "701030:Talk01_End"
          }
        },
        [51121039] = {
          Content = "狴犴没来抓我，说明我没问题，但要是你再闹下去，会不会来抓你我就不知道了。",
          DialogueId = 51121039,
          GUID = "7FF9E576",
          NextDialogue = 51121040,
          SpeakNpcId = 701030
        },
        [51121040] = {
          Content = "事情就到这里吧，我先走了，你们和睦相处，日后不要起争执了。",
          DialogueId = 51121040,
          GUID = "7FF9E5A0",
          NextDialogue = 51121041,
          SpeakNpcId = 100001
        },
        [51121041] = {
          Content = "（余下急匆匆地离开了，董筑挠挠头，切了一声，什么也没说。）",
          DialogueId = 51121041,
          GUID = "7FF9E5CA",
          NextDialogue = 51121042
        },
        [51121042] = {
          Content = "（想必他们的关系并不会因为一次小调解就冰释前嫌，但至少暂时不会吵架了。）",
          DialogueId = 51121042,
          GUID = "7FF9E5F4"
        },
        [51122000] = {
          Content = "娃娃娃娃，快过来！",
          DialogueId = 51122000,
          GUID = "7FFA8320",
          LookAt = {
            [1] = "701031:n(0)"
          },
          NextDialogue = 51122001,
          SpeakNpcId = 701031
        },
        [51122001] = {
          Content = "（你环顾四周，并没有发现别人的身影，于是你试探性指了指自己。）",
          DialogueId = 51122001,
          GUID = "7FFA834A",
          NextDialogue = 51122002
        },
        [51122002] = {
          Content = "对咯，叫你呢娃娃，快过来呀！",
          DialogueId = 51122002,
          GUID = "7FFA8374",
          NextDialogue = 51122003,
          NextOptions = {
            [1] = 51122003,
            [2] = 51122004,
            [3] = 51122005
          },
          SpeakNpcId = 701031
        },
        [51122003] = {
          Content = "（老实走过去。）",
          DialogueId = 51122003,
          GUID = "7FFA839E",
          ImprPlusId = 1207,
          NextDialogue = 51122006
        },
        [51122004] = {
          Content = "（难道是要给我推销？）",
          DialogueId = 51122004,
          GUID = "7FFA83C8",
          ImprPlusId = 1206,
          NextDialogue = 51122006
        },
        [51122005] = {
          Content = "（装作什么也没看见走开。）",
          DialogueId = 51122005,
          GUID = "7FFA83F2",
          ImprPlusId = 1210,
          NextDialogue = 51122006
        },
        [51122006] = {
          Content = "诶呀你这小娃儿，好生难叫，老夫我啊老远就注意到你了，叫你半天也不应，我就在那想啊，难道这娃娃小小年纪就失聪了？",
          DialogueId = 51122006,
          GUID = "7FFA841C",
          NextDialogue = 51122007,
          SpeakNpcId = 701031,
          TalkActionId = {
            [1] = "701031:Talk01_Start"
          }
        },
        [51122007] = {
          Content = "现在看起来，精精神神，倒是没有毛病的样子。",
          DialogueId = 51122007,
          GUID = "7FFA8446",
          NextDialogue = 51122008,
          SpeakNpcId = 701031,
          TalkActionId = {
            [1] = "701031:Talk01_End"
          }
        },
        [51122008] = {
          Content = "所以你叫我是做什么？",
          DialogueId = 51122008,
          GUID = "7FFA8470",
          NextDialogue = 51122009,
          SpeakNpcId = 100001
        },
        [51122009] = {
          Content = "娃娃，你别紧张，华胥可没什么坏人，只是我这有一瓶新酿好的酒，想让你品鉴一番。",
          DialogueId = 51122009,
          GUID = "7FFA849A",
          NextDialogue = 51122010,
          SpeakNpcId = 701031,
          TalkActionId = {
            [1] = "701031:Talk02_Start"
          }
        },
        [51122010] = {
          Content = "哦哦，老夫知晓你要怀疑，听我给你解释，我呢是个专门卖酒的，你可去城里打听打听我酒瓢子的名号，凡是平日爱喝上那么一口的，自然是都晓得。",
          DialogueId = 51122010,
          GUID = "7FFA84C4",
          NextDialogue = 51122011,
          SpeakNpcId = 701031
        },
        [51122011] = {
          Content = "但这最近呢，老夫却接到个织星客的订单，说是要出口一批甜酒到大陆另一头的海伯利亚去。",
          DialogueId = 51122011,
          GUID = "7FFA84EE",
          NextDialogue = 51122012,
          SpeakNpcId = 701031
        },
        [51122012] = {
          Content = "但看了这订单我可就犯难了呀，订单特意要求了酒味要淡，甘甜可口，这这这……和咱平日酿的酒口味差了十万八千里呀，但奈何这订单出手确实阔绰……",
          DialogueId = 51122012,
          GUID = "7FFA8518",
          NextDialogue = 51122013,
          SpeakNpcId = 701031,
          TalkActionId = {
            [1] = "701031:Talk02_End"
          }
        },
        [51122013] = {
          Content = "所以你研发新酒，想找人帮你试试口味。",
          DialogueId = 51122013,
          GUID = "7FFA8542",
          NextDialogue = 51122014,
          SpeakNpcId = 100001
        },
        [51122014] = {
          Content = "娃娃聪慧！所以老夫绝无别心，这瓶香料酒，是我专程收的圆糯米，蒸制时加入玉桂，带出一丝温润的甜香，再加青砖红提香增味。",
          DialogueId = 51122014,
          GUID = "7FFA856C",
          NextDialogue = 51122015,
          SpeakNpcId = 701031,
          TalkActionId = {
            [1] = "701031:Explain01_Start"
          }
        },
        [51122015] = {
          Content = "最后，老夫特地订购了一批南山甜果，果肉碾碎成汁后混入现采山泉之水，历时整整三日，最终制成。",
          DialogueId = 51122015,
          GUID = "7FFA8596",
          NextDialogue = 51122016,
          SpeakNpcId = 701031
        },
        [51122016] = {
          Content = "那帮老头们整日喝的都是辛辣烈酒，舌头早已品不出好坏，问来问去只说过于甜腻，老夫也是求助无门，才想起来在这街上等个有缘之人。",
          DialogueId = 51122016,
          GUID = "7FFA85C0",
          NextDialogue = 51122017,
