          GUID = "7FFB2880",
          NextOptions = {
            [1] = 51123009,
            [2] = 51123011
          },
          SpeakNpcId = 701032
        },
        [51123009] = {
          Content = "看你一人在这里，有些担心。",
          DialogueId = 51123009,
          GUID = "7FFB28AA",
          ImprPlusId = 1209,
          NextDialogue = 51123010
        },
        [51123010] = {
          Content = "嗨！这有什么好担心的，这可是华胥，白龙神君庇佑的好地方。{性别：小伙子|小姑娘}，你这份好意老农我心领了呀。",
          DialogueId = 51123010,
          GUID = "7FFB28D4",
          NextDialogue = 51123013,
          SpeakNpcId = 701032
        },
        [51123011] = {
          Content = "我没事，我就溜达。",
          DialogueId = 51123011,
          GUID = "7FFB28FE",
          ImprPlusId = 1210,
          NextDialogue = 51123012
        },
        [51123012] = {
          Content = "溜达？你不会是迷路了还嘴硬吧？记得带好香囊啊，可别碰上玄色狴犴喽。",
