          GUID = "7FFB2928",
          NextDialogue = 51123013,
          SpeakNpcId = 701032
        },
        [51123013] = {
          Content = "所以，你是一位吟游诗人？",
          DialogueId = 51123013,
          GUID = "7FFB2952",
          NextDialogue = 51123014,
          SpeakNpcId = 100001
        },
        [51123014] = {
          Content = "吟游诗人？这名儿倒是新鲜。不过我可不是什么诗人，我是个种地的。喏，这一大片都是我家的田地。",
          DialogueId = 51123014,
          GUID = "7FFB297C",
          NextDialogue = 51123015,
          SpeakNpcId = 701032,
          TalkActionId = {
            [1] = "701032:Talk01_Start"
          }
        },
        [51123015] = {
          Content = "对老农我来说啊，吟诗作对就是消遣罢了，和赏花看戏没什么区别。",
          DialogueId = 51123015,
          GUID = "7FFB29A6",
          NextDialogue = 51123016,
          SpeakNpcId = 701032
        },
        [51123016] = {
          Content = "不过啊，想我年轻那会倒是真用心读过几年书，想着有朝一日能入三司为神君效力，诶呀，想想就美啊。",
          DialogueId = 51123016,
          GUID = "7FFB29D0",
          NextDialogue = 51123017,
          SpeakNpcId = 701032
        },
        [51123017] = {
          Content = "那怎么没去？",
          DialogueId = 51123017,
          GUID = "7FFB29FA",
          NextDialogue = 51123018,
          SpeakNpcId = 100001
        },
        [51123018] = {
          Content = "早起去割麦，割出万里田，整日忙不歇，归家喝小酒。老农我种田一等一地好，但摊上那些乱七八糟的事就开始犯难啦。",
          DialogueId = 51123018,
          GUID = "7FFB2A24",
          NextDialogue = 51123019,
          SpeakNpcId = 701032
        },
        [51123019] = {
          Content = "天理司的辩经，天禄司的账，天梁司的机关，咱是一个都搞不明白哟。要是咱也能入仕，那明日大风九章就该改成大风乱吹啦。",
          DialogueId = 51123019,
          GUID = "7FFB2A4E",
          NextDialogue = 51123020,
          SpeakNpcId = 701032,
          TalkActionId = {
            [1] = "701032:Talk01_End"
          }
        },
        [51123020] = {
          Content = "原来是这样。",
          DialogueId = 51123020,
          GUID = "7FFB2A78",
          NextDialogue = 51123021,
          SpeakNpcId = 100001
        },
        [51123021] = {
          Content = "不过像现在这样，没事念念打油诗，和年轻人聊聊天，晚上回去和我那好大儿就着集市上买来的卤肉，喝点小酒，也挺好的不是？",
          DialogueId = 51123021,
          GUID = "7FFB2AA2",
          NextDialogue = 51123022,
          SpeakNpcId = 701032,
          TalkActionId = {
            [1] = "701032:Talk02_Start"
          }
        },
        [51123022] = {
          Content = "诶呀，今儿天不早了，{性别：小伙子|小姑娘}，咱们先不说啦！我要拾掇拾掇，回家喝上两口咯！",
