        [51125205] = {
          Content = "嘿！有好事也不叫我们，可得敲他一壶上好的碧茅！",
          DialogueId = 51125205,
          GUID = "7FFC90F2",
          SpeakNpcId = 701034
        },
        [51125301] = {
          Content = "您别说，咱们华胥就是数一数二的安全，看到那四处巡逻的狴犴了没？但凡有奸人作恶，都会被迅速逮捕！",
          DialogueId = 51125301,
          GUID = "7FFCA0B2",
          NextDialogue = 51125302,
          SpeakNpcId = 701036
        },
        [51125302] = {
          Content = "哼，我们海伯利亚也很安全的，知道帝国军团的威名吗？帝国的铁骑会踏破每一句反抗的声音。",
          DialogueId = 51125302,
          GUID = "7FFCA0DC",
          NextDialogue = 51125303,
          SpeakNpcId = 701037
        },
        [51125303] = {
          Content = "拉倒吧！从外头回来的织星客谁不说你们海伯利亚隔三差五就和南边打仗，这也能叫安全？",
          DialogueId = 51125303,
          GUID = "7FFCA106",
          NextDialogue = 51125304,
          SpeakNpcId = 701036
        },
        [51125304] = {
          Content = "打仗那是……那是帝国的本事……打仗的目的就是为了和平！",
          DialogueId = 51125304,
          GUID = "7FFCA130",
          NextDialogue = 51125305,
          SpeakNpcId = 701037
        },
        [51125305] = {
          Content = "啧啧，那你为何苦苦要来华胥生活？姐们，来了华胥，只要你一心向善，白龙神君就会护佑你日日平安。",
          DialogueId = 51125305,
          GUID = "7FFCA15A",
          SpeakNpcId = 701036
        },
        [51125401] = {
          Content = "这荒塔倒是上了年头了，想来曾经也是咱们机枢派的杰作，竟任由它被风吹雨打，无人维护……",
          DialogueId = 51125401,
          GUID = "7FFCB11A",
          NextOptions = {
            [1] = 51125402
          },
          SpeakNpcId = 701038
        },
        [51125402] = {
          Content = "这是做什么用的？",
