          NextOptions = {
            [1] = 51125703,
            [2] = 51125720
          },
          SpeakNpcId = 701041
        },
        [51125703] = {
          Content = "继续听下去。",
          DialogueId = 51125703,
          GUID = "7FFCE2A6",
          NextDialogue = 51125704
        },
        [51125704] = {
          Content = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
          DialogueId = 51125704,
          GUID = "7FFCE2D0",
          NextDialogue = 51125705,
          SpeakNpcId = 701041
        },
        [51125705] = {
          Content = "当年的华胥，没有大风九章的庇佑，秽兽四起，袭击无辜之人，为了活命，是不分老幼，都得想着法和那些凶恶的野兽去斗来斗去。",
          DialogueId = 51125705,
          GUID = "7FFCE2FA",
          NextDialogue = 51125706,
          SpeakNpcId = 701041
        },
        [51125706] = {
          Content = "有争斗就会有伤亡，那时，华胥人口数量极少，因为大多数出生的孩子都难在这乱世之中活下来，为了寻找到让华胥境内安宁的办法，有龙一族上下求索。",
          DialogueId = 51125706,
          GUID = "7FFCE324",
          NextDialogue = 51125707,
          SpeakNpcId = 701041
        },
        [51125707] = {
          Content = "而我们的前辈矩呢，走遍了华胥，发现哪儿都是不得安生，于是他想着，不如出去看看，去看看人家是怎么做的，取其长处再充盈自身。",
          DialogueId = 51125707,
          GUID = "7FFCE34E",
          NextOptions = {
            [1] = 51125708
          },
          SpeakNpcId = 701041
        },
        [51125708] = {
          Content = "继续听下去。",
          DialogueId = 51125708,
          GUID = "7FFCE378",
          NextDialogue = 51125709
        },
        [51125709] = {
          Content = "当年啊，还没现在这么厉害的船，也没有织星客的存在，想要出海，全凭运气，运气好便漂流到荒岛看鸟，运气不好，就只能葬身海底喂鱼喽。",
          DialogueId = 51125709,
          GUID = "7FFCE3A2",
          NextDialogue = 51125710,
          SpeakNpcId = 701041
        },
        [51125710] = {
          Content = "但矩呢，抱定要为万民谋安宁的一颗赤心，自制了艘船，说是不连累别人，愣是一个人就从咱们这浮星埠下了海！",
          DialogueId = 51125710,
          GUID = "7FFCE3CC",
          NextDialogue = 51125711,
          SpeakNpcId = 701041
        },
        [51125711] = {
          Content = "好在，白龙神君眷顾，矩在风浪里去了那神秘的塔之国，但可惜的是，那边也不得安生，矩认为外民也无法给华胥带来希望，于是便带着同样想要安定的人回来了。",
          DialogueId = 51125711,
          GUID = "7FFCE3F6",
          NextDialogue = 51125712,
          SpeakNpcId = 701041
        },
        [51125712] = {
          Content = "这都多少年过去了，大家都以为矩早就是个死人，结果啊非但没死，还又带了许许多多的活人回来了浮星埠。",
          DialogueId = 51125712,
          GUID = "7FFCE420",
          NextOptions = {
            [1] = 51125713
          },
          SpeakNpcId = 701041
        },
        [51125713] = {
          Content = "继续听下去。",
          DialogueId = 51125713,
          GUID = "7FFCE44A",
          NextDialogue = 51125714
        },
        [51125714] = {
          Content = "你们可能好奇，矩是如何做到如此准确的寻路，是有神灵庇佑还是靠的信念和直觉？",
          DialogueId = 51125714,
          GUID = "7FFCE474",
          NextDialogue = 51125715,
          SpeakNpcId = 701041
        },
        [51125715] = {
          Content = "都不是，老柳头啊也不卖关子了，现在织星者们出海时用的引路的工具不是叫千星板吗？矩也是一样，只是啊，他手里用的那个，就是第一个。",
          DialogueId = 51125715,
          GUID = "7FFCE49E",
          NextDialogue = 51125716,
          SpeakNpcId = 701041
        },
        [51125716] = {
          Content = "他用几块木板测绘星辰，记录航向，这才能在茫茫大海上自由来去，不受羁绊。",
          DialogueId = 51125716,
          GUID = "7FFCE4C8",
          NextDialogue = 51125717,
          SpeakNpcId = 701041
        },
        [51125717] = {
          Content = "矩的成功出海与归来，让华胥的有龙们不再畏惧海洋，现在浮星埠的繁华和织星客们的昌盛，也是多亏了当年矩的先行。",
          DialogueId = 51125717,
          GUID = "7FFCE4F2",
          NextDialogue = 51125718,
          SpeakNpcId = 701041
        },
        [51125718] = {
          Content = "所以，矩和飏，都是咱们要时时牢记于心的开国贤君，没有他们，就没有今天的华胥，我们要时时刻刻记住他们的名字和事迹！懂了吗？",
          DialogueId = 51125718,
          GUID = "7FFCE51C",
          NextDialogue = 51125719,
          SpeakNpcId = 701041
        },
        [51125719] = {
          Content = "（响起一阵叫好声。）",
          DialogueId = 51125719,
          GUID = "7FFCE546"
        },
        [51125720] = {
          Content = "不听了。",
          DialogueId = 51125720,
          GUID = "7FFCE570",
          NextDialogue = 51125721
        },
        [51125721] = {
          Content = "（身后传来老柳头宣扬两位华胥开国贤君事迹的声音和喝茶群众的叫好声……）",
          DialogueId = 51125721,
          GUID = "7FFCE59A"
        },
        [51125801] = {
          Content = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
          DialogueId = 51125801,
          GUID = "7FFCF2BA",
          NextDialogue = 51125802,
          SpeakNpcId = 701042
        },
        [51125802] = {
          Content = "这千星板上了船还没个三年，怎么就这么快就要去保养了呢，这次不知道他们还记不记得提前预约机枢派的师傅……先看看刻度有没有被磨坏吧！",
          DialogueId = 51125802,
          GUID = "7FFCF2E4",
          NextDialogue = 51125803,
          SpeakNpcId = 701042
        },
        [51125803] = {
          Content = "呀！吓了我一跳，你是异国人吗？在咱们船上做什么？",
          DialogueId = 51125803,
          GUID = "7FFCF30E",
          NextOptions = {
            [1] = 51125804,
            [2] = 51125807
          },
          SpeakNpcId = 701042
        },
        [51125804] = {
          Content = "好奇你在做什么。",
          DialogueId = 51125804,
          GUID = "7FFCF338",
          ImprPlusId = 1208,
          NextDialogue = 51125805
        },
        [51125805] = {
          Content = "我？我在查看这船上千星板的情况呀，我是这艘船上配的工匠，专门负责日常维护这千星板的运作，要是没有这千星板，这船只可就没法出航啦。",
          DialogueId = 51125805,
          GUID = "7FFCF362",
          NextDialogue = 51125806,
          SpeakNpcId = 701042
        },
        [51125806] = {
          Content = "你有事的话，以后再来找我吧，现在我还要仔细检查一下过热情况……",
          DialogueId = 51125806,
          GUID = "7FFCF38C",
          SpeakNpcId = 701042
        },
        [51125807] = {
          Content = "闲逛到这里了。",
          DialogueId = 51125807,
          GUID = "7FFCF3B6",
          ImprPlusId = 1207,
          NextDialogue = 51125808
        },
        [51125808] = {
          Content = "哦哦是吗？可我在检查千星板的情况呢，要是出了问题，这船就没法出航啦，你有什么事情的话以后再来找我聊吧。",
          DialogueId = 51125808,
          GUID = "7FFCF3E0",
          SpeakNpcId = 701042
        },
        [51125809] = {
          Content = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
          DialogueId = 51125809,
          GUID = "7FFCF40A",
          NextDialogue = 51125810,
          SpeakNpcId = 701042
        },
        [51125810] = {
          Content = "这个刻度误差……我手动增加五次校准运算后结果也大差不差……那是不是可以申请延期保养时间了。",
          DialogueId = 51125810,
          GUID = "7FFCF434",
          NextDialogue = 51125811,
          SpeakNpcId = 701042
        },
        [51125811] = {
          Content = "呀，又是你，异国人，你又逛到我这啦。",
          DialogueId = 51125811,
          GUID = "7FFCF45E",
          NextOptions = {
            [1] = 51125812,
            [2] = 51125815,
            [3] = 51125825
          },
          SpeakNpcId = 701042
        },
        [51125812] = {
          Content = "师傅你是做什么的？",
          DialogueId = 51125812,
          GUID = "7FFCF488",
          NextDialogue = 51125813
        },
        [51125813] = {
          Content = "我吗？自然是这船上配的工匠啦，我的工作就是负责维护千星板的运作情况，保证它一切正常，不会临时出意外，不然会影响到下一次出航。",
          DialogueId = 51125813,
          GUID = "7FFCF4B2",
          NextDialogue = 51125814,
          SpeakNpcId = 701042
        },
        [51125814] = {
          Content = "这些信息都要记录下来，找天禄司申请通文时用得到呢。",
          DialogueId = 51125814,
          GUID = "7FFCF4DC",
          NextOptions = {
            [1] = 51125815,
            [2] = 51125825
          },
          SpeakNpcId = 701042
        },
        [51125815] = {
          Content = "千星板是什么？",
          DialogueId = 51125815,
          GUID = "7FFCF506",
          NextDialogue = 51125816
        },
        [51125816] = {
          Content = "千星板可是咱们织星客们赖以生存的传家宝呢！在一望无际的大海上，只有它能观测天上的星星的方位，给船只导航指路，怎么都不会跑偏。",
          DialogueId = 51125816,
          GUID = "7FFCF530",
          NextDialogue = 51125817,
          SpeakNpcId = 701042
        },
        [51125817] = {
          Content = "华胥四周的海域紊乱，没有千星板的正确指引，织星客们很容易在乱流之间迷路，所以啊，我们每回远航之前，都需要仔细检查千星板的情况。",
          DialogueId = 51125817,
          GUID = "7FFCF55A",
          NextOptions = {
            [1] = 51125818,
            [2] = 51125822
          },
          SpeakNpcId = 701042
        },
        [51125818] = {
          Content = "你说的保养是什么意思？",
          DialogueId = 51125818,
          GUID = "7FFCF584",
          NextDialogue = 51125819
        },
        [51125819] = {
          Content = "保养吗？其实就是让机枢派的老师傅们帮咱们看看千星板是否出现一些零件松动之类的情况，虽然大多数情况都没什么问题，但是在海上航行，难免会有浪涛大时磕碰。",
          DialogueId = 51125819,
          GUID = "7FFCF5AE",
          NextDialogue = 51125820,
          SpeakNpcId = 701042
        },
        [51125820] = {
          Content = "我们这种普通工匠能看出问题但不会修，只有去机枢派找有专门检测器材的老师傅们帮着看看，但是频率不需要太高，大概四五年一次就好。",
          DialogueId = 51125820,
          GUID = "7FFCF5D8",
          NextDialogue = 51125821,
          SpeakNpcId = 701042
        },
        [51125821] = {
          Content = "不过即使是过去找他们，也需要给到日常测量的一些数据，方便给出更好的判断。",
          DialogueId = 51125821,
          GUID = "7FFCF602",
          SpeakNpcId = 701042
        },
        [51125822] = {
          Content = "千星板在哪，我怎么没看到？",
          DialogueId = 51125822,
          GUID = "7FFCF62C",
          NextDialogue = 51125823
        },
        [51125823] = {
          Content = "哈哈，笨家伙，就在咱们脚下呀，咱们这种用来出海的大船，千星板都是装在船舱里的，只有最大的那块板会倒置朝向天空，方便观测星空。",
          DialogueId = 51125823,
          GUID = "7FFCF656",
          NextDialogue = 51125824,
          SpeakNpcId = 701042
        },
        [51125824] = {
          Content = "用你们外国人能听懂的话来形容，大概有些像那种大型的吊灯，我们在海上的时候，每时每刻都需要有人在船舱里值班记录千星板转动的幅度，不然就容易偏航呢。",
          DialogueId = 51125824,
          GUID = "7FFCF680",
          SpeakNpcId = 701042
        },
        [51125825] = {
          Content = "没什么要问的。",
          DialogueId = 51125825,
          GUID = "7FFCF6AA",
          NextDialogue = 51125826
        },
        [51125826] = {
          Content = "有事再来找我吧，我要测量新的数据啦。",
          DialogueId = 51125826,
          GUID = "7FFCF6D4",
          SpeakNpcId = 701042
        },
        [51125901] = {
          Content = "白女士，这个什么什么身，是什么意思，我听不懂。",
          DialogueId = 51125901,
          GUID = "7FFD0322",
          NextDialogue = 51125902,
          SpeakNpcId = 701043
        },
        [51125902] = {
          Content = "戕，这个字念戕，就是和你们异国人经常用的枪字一个读音。",
          DialogueId = 51125902,
          GUID = "7FFD034C",
          NextDialogue = 51125903,
          SpeakNpcId = 701044
        },
        [51125903] = {
          Content = "哦哦！枪！枪身就是，用枪打对方的身子，对不对？",
          DialogueId = 51125903,
          GUID = "7FFD0376",
          NextDialogue = 51125904,
          SpeakNpcId = 701043
        },
        [51125904] = {
          Content = "这……诶，你就这么理解吧，也没什么问题，总之就是，在我们华胥，不能出现伤人之事，所以你带来的枪我们就先没收了，等你离开华胥之时再还给你。",
          DialogueId = 51125904,
          GUID = "7FFD03A0",
          NextDialogue = 51125905,
          SpeakNpcId = 701044
        },
        [51125905] = {
          Content = "可以可以，我来做生意，听本地的规矩，大风什么的，还有别的吗？",
          DialogueId = 51125905,
          GUID = "7FFD03CA",
          NextDialogue = 51125906,
          SpeakNpcId = 701043
        },
        [51125906] = {
          Content = "你既然是来做生意的，那这第二条：毁约背盟，不可为也。你可得谨记于心。",
          DialogueId = 51125906,
          GUID = "7FFD03F4",
          NextDialogue = 51125907,
          SpeakNpcId = 701044
        },
        [51125907] = {
          Content = "毁约，听得懂，背萌是什么意思？背上萌萌的吗？",
          DialogueId = 51125907,
          GUID = "7FFD041E",
          NextDialogue = 51125908,
          SpeakNpcId = 701043
        },
        [51125908] = {
          Content = "不是那个萌……是盟约的盟，意思就是，你如果和咱们华胥人做生意，在谈妥价格之后，一定要在白龙神君的见证下立契，不然我们是不敢信你的。",
          DialogueId = 51125908,
          GUID = "7FFD0448",
          NextDialogue = 51125909,
          SpeakNpcId = 701044
        },
        [51125909] = {
          Content = "哦哦，我明白了，你们要写合同，我们那边也写的，没问题没问题！",
          DialogueId = 51125909,
          GUID = "7FFD0472",
          NextDialogue = 51125910,
          SpeakNpcId = 701043
        },
        [51125910] = {
          Content = "不不不，不一样，我们这是契约，是在白龙神君的见证下完成的，我们写的合同都是用沉月香香灰掺进墨里写，立契的时候便有了神君亲鉴。",
          DialogueId = 51125910,
          GUID = "7FFD049C",
          NextDialogue = 51125911,
          SpeakNpcId = 701044
        },
        [51125911] = {
          Content = "如若一方背誓，可是会被狴犴大人追缉的！",
          DialogueId = 51125911,
          GUID = "7FFD04C6",
          NextDialogue = 51125912,
          SpeakNpcId = 701044
        },
        [51125912] = {
          Content = "狴犴！华胥大狗，这个我知道的！",
          DialogueId = 51125912,
          GUID = "7FFD04F0",
          NextDialogue = 51125913,
          SpeakNpcId = 701043
        },
        [51125913] = {
          Content = "你这家伙，好生无礼！不可以这么称呼狴犴大人！",
          DialogueId = 51125913,
          GUID = "7FFD051A",
          SpeakNpcId = 701044
        },
        [51126001] = {
          Content = "妈妈说的都是骗我的，什么叫我大了就可以长出角，前年说去年长，去年说今年长。结果还是什么都没有……",
          DialogueId = 51126001,
          GUID = "7FFD138A",
          NextDialogue = 51126002,
          SpeakNpcId = 701045
        },
        [51126002] = {
          Content = "难道我根本长不出角吗？不要啊，我不想当抟土氏，我想当光荣的有龙氏。",
          DialogueId = 51126002,
          GUID = "7FFD13B4",
          NextOptions = {
            [1] = 51126003,
            [2] = 51126005
          },
          SpeakNpcId = 701045
        },
        [51126003] = {
          Content = "当抟土氏不好吗？",
          DialogueId = 51126003,
          GUID = "7FFD13DE",
          ImprPlusId = 1207,
          NextDialogue = 51126004
        },
        [51126004] = {
          Content = "不好不好，当然不好，只有成为有龙才有强大的魔法，只有成为有龙才能在华胥为神君效力。",
          DialogueId = 51126004,
          GUID = "7FFD1408",
          SpeakNpcId = 701045
        },
        [51126005] = {
          Content = "有龙可能会变成秽兽的。",
          DialogueId = 51126005,
          GUID = "7FFD1432",
          ImprPlusId = 1209,
          NextDialogue = 51126006
        },
        [51126006] = {
          Content = "秽兽？我才不怕呢，即使变成了秽兽，我也会成为光荣的狴犴大人，我妈妈一定也会为我骄傲的！",
          DialogueId = 51126006,
          GUID = "7FFD145C",
          SpeakNpcId = 701045
        },
        [51126007] = {
          Content = "怎么样才能长出角呢，我揪……我揪……嗷！好痛……",
          DialogueId = 51126007,
          GUID = "7FFD1486",
          NextDialogue = 51126008,
          SpeakNpcId = 701045
        },
        [51126008] = {
          Content = "是你啊，{性别：大哥哥|大姐姐}，我妈妈最近告诉我一个新办法，就是在这浮星埠去摸过往路过有龙氏的角，摸多了就可以长出自己的角来。",
          DialogueId = 51126008,
          GUID = "7FFD14B0",
          NextDialogue = 51126009,
          SpeakNpcId = 701045
        },
        [51126009] = {
          Content = "她还说，如果摸的多，就可以长出一模一样的，所以一定要找角好看的有龙氏！{性别：大哥哥|大姐姐}，我喜欢你的角，你可以给我摸摸吗？",
          DialogueId = 51126009,
          GUID = "7FFD14DA",
          NextOptions = {
            [1] = 51126010,
            [2] = 51126030
          },
          SpeakNpcId = 701045
        },
        [51126010] = {
          Content = "给他摸摸。",
          DialogueId = 51126010,
          GUID = "7FFD1504",
          NextDialogue = 51126011
        },
        [51126011] = {
          Content = "谢谢你！小小的，硬硬的，我可得好好摸摸。",
          DialogueId = 51126011,
          GUID = "7FFD152E",
          NextDialogue = 51126012,
          SpeakNpcId = 701045
        },
        [51126012] = {
          Content = "你说如果我有一天也长出角来，妈妈会不会为我高兴？我是不是也可以使出很厉害的魔法？{性别：大哥哥|大姐姐}，你会不会魔法？",
          DialogueId = 51126012,
          GUID = "7FFD1558",
          NextOptions = {
            [1] = 51126013,
            [2] = 51126017
          },
          SpeakNpcId = 701045
        },
        [51126013] = {
          Content = "我会，但是在你们华胥应该没法用。",
          DialogueId = 51126013,
          GUID = "7FFD1582",
          NextDialogue = 51126014
        },
        [51126014] = {
          Content = "哦哦，我明白了，像{性别：大哥哥|大姐姐}这种很厉害的有龙，一定有那种可以排山倒海的魔法吧，是不是一拳就能打飞三十只玄色狴犴！",
          DialogueId = 51126014,
          GUID = "7FFD15AC",
          NextDialogue = 51126015,
          SpeakNpcId = 701045
        },
        [51126015] = {
          Content = "哇！怎么想都好厉害，{性别：大哥哥|大姐姐}，要是我有一天也长出角，你可不可以教我这种很厉害的魔法！",
          DialogueId = 51126015,
          GUID = "7FFD15D6",
          NextDialogue = 51126016,
          SpeakNpcId = 701045
        },
        [51126016] = {
          Content = "你先长出来再说吧。",
          DialogueId = 51126016,
          GUID = "7FFD1600",
          SpeakNpcId = 100001
        },
        [51126017] = {
          Content = "我不会，我只会用剑和拳头。",
          DialogueId = 51126017,
          GUID = "7FFD162A",
          NextDialogue = 51126018
        },
        [51126018] = {
          Content = "诶？在华胥是不能使用暴力的，不过{性别：大哥哥|大姐姐}你这么有自信，是不是就和……应天……唔，我忘了叫什么，反正就是在华胥唯一可以使用武力的存在。",
          DialogueId = 51126018,
          GUID = "7FFD1654",
          NextDialogue = 51126019,
          SpeakNpcId = 701045
        },
        [51126019] = {
          Content = "他们都很威风的，走到哪里我们都会很尊重他们，因为他们是直接为神君效力，可厉害啦！",
          DialogueId = 51126019,
          GUID = "7FFD167E",
          NextDialogue = 51126020,
          SpeakNpcId = 701045
        },
        [51126020] = {
          Content = "你说等我长出角以后，能不能成为像你这样的厉害的有龙呢……",
          DialogueId = 51126020,
          GUID = "7FFD16A8",
          NextDialogue = 51126021,
          SpeakNpcId = 701045
        },
        [51126021] = {
          Content = "你先长出来再说吧。",
          DialogueId = 51126021,
          GUID = "7FFD16D2",
          SpeakNpcId = 100001
        },
        [51126022] = {
          Content = "摸了也不会长角的。",
          DialogueId = 51126022,
          GUID = "7FFD16FC",
          NextDialogue = 51126023
        },
        [51126023] = {
          Content = "你骗人！妈妈明明不是这么说的！你是坏有龙，呜啊！！！狴犴大人会把你抓走的！",
          DialogueId = 51126023,
          GUID = "7FFD1726",
          NextOptions = {
            [1] = 51126024,
            [2] = 51126027
          },
          SpeakNpcId = 701045
        },
        [51126024] = {
          Content = "为了哄他撒谎吧。",
          DialogueId = 51126024,
          GUID = "7FFD1750",
          NextDialogue = 51126025
        },
        [51126025] = {
          Content = "好了好了，我骗你的，你迟早会长出角，成为有龙氏。",
          DialogueId = 51126025,
          GUID = "7FFD177A",
          NextDialogue = 51126026,
          SpeakNpcId = 100001
        },
        [51126026] = {
          Content = "哼……这就对了嘛，成为有龙氏是我的梦想……",
          DialogueId = 51126026,
          GUID = "7FFD17A4",
          SpeakNpcId = 701045
        },
        [51126027] = {
          Content = "坚持自己的说法。",
          DialogueId = 51126027,
          GUID = "7FFD17CE",
          NextDialogue = 51126028
        },
        [51126028] = {
          Content = "哪有长大以后会物种变异的，你小时候没有角，长大也不会有角的。",
          DialogueId = 51126028,
          GUID = "7FFD17F8",
          NextDialogue = 51126029,
          SpeakNpcId = 100001
        },
        [51126029] = {
          Content = "呜啊啊！！！坏有龙，欺负小孩！你在这等着，我叫我爸爸来揍你！",
          DialogueId = 51126029,
          GUID = "7FFD1822",
          SpeakNpcId = 701045
        },
        [51126030] = {
          Content = "离开吧。",
          DialogueId = 51126030,
          GUID = "7FFD184C",
          NextDialogue = 51126031
        },
        [51126031] = {
          Content = "我一定会成为有龙氏的，一定！",
          DialogueId = 51126031,
          GUID = "7FFD1876",
          SpeakNpcId = 701045
        },
        [51126101] = {
          Content = "既然如此，早知道就早些来走这流程，拿了身份，我上次那笔大单也不至于因为资金周转不过来丢了……",
          DialogueId = 51126101,
          GUID = "7FFD23F2",
          NextDialogue = 51126102,
          SpeakNpcId = 701046
        },
        [51126102] = {
          Content = "这位朋友，你也是来申请成为织星客的吗？",
          DialogueId = 51126102,
          GUID = "7FFD241C",
          NextOptions = {
            [1] = 51126103,
            [2] = 51126107
          },
          SpeakNpcId = 701046
        },
        [51126103] = {
          Content = "算是，正好听到你在说这事。",
          DialogueId = 51126103,
          GUID = "7FFD2446",
          NextDialogue = 51126104
        },
        [51126104] = {
          Content = "那你可就问对人了，我刚走完那些流程，什么填表验资的，条条框框每一道手续，我都门儿清。",
          DialogueId = 51126104,
          GUID = "7FFD2470",
          NextDialogue = 51126105,
          SpeakNpcId = 701046
        },
        [51126105] = {
          Content = "不过……我的意思也不是说流程繁琐，毕竟百年春绝不刁难每一位心诚的商人。",
          DialogueId = 51126105,
          GUID = "7FFD249A",
          NextDialogue = 51126106,
          SpeakNpcId = 701046
        },
        [51126106] = {
          Content = "多谢你的好意，但我暂时还不打算申请。",
          DialogueId = 51126106,
          GUID = "7FFD24C4",
          SpeakNpcId = 100001
        },
        [51126107] = {
          Content = "不是，只是听到你在说这事。",
          DialogueId = 51126107,
          GUID = "7FFD24EE",
          NextDialogue = 51126108
        },
        [51126108] = {
          Content = "哦哦，我以为来百年春的外国人都是想成为织星客呢，不过此话一说我也想起来，似乎你们外来的和咱们本地的走的不是一套流程。",
          DialogueId = 51126108,
          GUID = "7FFD2518",
          NextDialogue = 51126109,
          SpeakNpcId = 701046
        },
        [51126109] = {
          Content = "不过你也放心，百年春绝不刁难每一位心诚的商人。",
          DialogueId = 51126109,
          GUID = "7FFD2542",
          NextDialogue = 51126110,
          SpeakNpcId = 701046
        },
        [51126110] = {
          Content = "多谢你的好意，但我暂时还不打算申请。",
          DialogueId = 51126110,
          GUID = "7FFD256C",
          SpeakNpcId = 100001
        },
        [51126111] = {
          Content = "没想到成为织星客还有如此多的便利！百年春真是家大业大啊。",
          DialogueId = 51126111,
          GUID = "7FFD2596",
          NextDialogue = 51126112,
          SpeakNpcId = 701046
        },
        [51126112] = {
          Content = "又是你呀外国人，这次下定决心要成为织星客了吗？",
          DialogueId = 51126112,
          GUID = "7FFD25C0",
          NextOptions = {
            [1] = 51126113,
            [2] = 51126119,
            [3] = 51126126
          },
          SpeakNpcId = 701046
        },
        [51126113] = {
          Content = "你还真是织星客的铁杆招牌。",
          DialogueId = 51126113,
          GUID = "7FFD25EA",
          NextDialogue = 51126114
        },
        [51126114] = {
          Content = "你要是知道加入织星客后可以获得百年春多大的扶持，你也会像我现在这样的。",
          DialogueId = 51126114,
          GUID = "7FFD2614",
          NextOptions = {
            [1] = 51126115
          },
          SpeakNpcId = 701046
        },
        [51126115] = {
          Content = "那么究竟有什么福利？",
          DialogueId = 51126115,
          GUID = "7FFD263E",
          NextDialogue = 51126116
        },
        [51126116] = {
          Content = "那可太多了，让我和你掰扯掰扯。像我这种刚入行的新人，成为织星客就可以申请一笔本金，算利息但是不高，这笔钱拿来干什么行当都可以。",
          DialogueId = 51126116,
          GUID = "7FFD2668",
          NextDialogue = 51126117,
          SpeakNpcId = 701046
        },
        [51126117] = {
          Content = "有了百年春这棵大树的名声作保，我们再去找人聊生意，再大户的人家也都会客气三分，还有些人家也会冲着织星客的名头主动找上门来。",
          DialogueId = 51126117,
          GUID = "7FFD2692",
          NextDialogue = 51126118,
          SpeakNpcId = 701046
        },
        [51126118] = {
          Content = "比此前我挨家挨户上门收货可好太多了。",
          DialogueId = 51126118,
          GUID = "7FFD26BC",
          SpeakNpcId = 701046
        },
        [51126119] = {
          Content = "原来你们华胥不是所有商人都叫织星客吗？",
          DialogueId = 51126119,
          GUID = "7FFD26E6",
          NextDialogue = 51126120
        },
        [51126120] = {
          Content = "不不不，那你可就搞错了，织星客是织星客，还有货郎和摊贩嘛，不一样的。",
          DialogueId = 51126120,
          GUID = "7FFD2710",
          NextDialogue = 51126121,
          SpeakNpcId = 701046
        },
        [51126121] = {
          Content = "织星客虽然有着极大的便利，但也规矩多多，比如谈好的生意必须要立契之类的，那些做惯了行商的、在自家门口做生意的，反而会被这些规矩束缚。",
          DialogueId = 51126121,
          GUID = "7FFD273A",
          NextDialogue = 51126122,
          SpeakNpcId = 701046
        },
        [51126122] = {
          Content = "我之前便是如此，游历四方，顺便做做小生意，赚了点钱，便想着做大些才过来。",
          DialogueId = 51126122,
          GUID = "7FFD2764",
          NextOptions = {
            [1] = 51126123
          },
          SpeakNpcId = 701046
        },
        [51126123] = {
          Content = "华胥大概有多少织星客？",
          DialogueId = 51126123,
          GUID = "7FFD278E",
          NextDialogue = 51126124
        },
        [51126124] = {
          Content = "多少？不知道，谁去仔细算过这些东西，毕竟有一些商户为了自己的招牌更加信得过也会去做织星客。非要说的话，有个……七成？六成？",
          DialogueId = 51126124,
          GUID = "7FFD27B8",
          NextDialogue = 51126125,
          SpeakNpcId = 701046
        },
        [51126125] = {
          Content = "总之，在哪儿遇见织星客做什么生意都不奇怪就是了。",
          DialogueId = 51126125,
          GUID = "7FFD27E2",
          SpeakNpcId = 701046
        },
        [51126126] = {
          Content = "下次再聊吧。",
          DialogueId = 51126126,
          GUID = "7FFD280C",
          NextDialogue = 51126127
        },
        [51126127] = {
          Content = "好啊，下次要来申请的时候再聊吧。",
          DialogueId = 51126127,
          GUID = "7FFD2836",
          SpeakNpcId = 701046
        },
        [51126201] = {
          Content = "聪先生，百年春今年的扩建规模真的已经超出计划许多了，原先只是说把现有的建筑整修一番，如今却是又额外建了个茶室。",
          DialogueId = 51126201,
          GUID = "7FFD345A",
          NextDialogue = 51126202,
          SpeakNpcId = 701047
        },
        [51126202] = {
          Content = "对啊，我知道，老李出的钱嘛，你们能接受他的援建款，为啥不能接受我的呢？咱们织星客出去赚了钱再回来报效百年春，这都是多少年的传统了。",
          DialogueId = 51126202,
          GUID = "7FFD3484",
          NextDialogue = 51126203,
          SpeakNpcId = 701048
        },
        [51126203] = {
          Content = "真的不行，聪先生，您也知道大家都喜欢给百年春捐钱，本身商会也不是什么很大的楼，愣是这些年一人一砖地建成了如此规模，实在不成了。",
          DialogueId = 51126203,
          GUID = "7FFD34AE",
          NextDialogue = 51126204,
          SpeakNpcId = 701047
        },
        [51126204] = {
          Content = "再这样建下去这百年春非塌不可，到时候大家都还得重建。",
          DialogueId = 51126204,
          GUID = "7FFD34D8",
          NextDialogue = 51126205,
          SpeakNpcId = 701047
        },
        [51126205] = {
          Content = "我不管，你们收了老李的钱，就得收我的，不然我半夜过来偷偷把钱扔这儿。",
          DialogueId = 51126205,
          GUID = "7FFD3502",
          NextDialogue = 51126206,
          SpeakNpcId = 701048
        },
        [51126206] = {
          Content = "这……可是李先生从前年开始就在等着今年的扩建额度下来，他第一时间便来填了申请，也是有先来后到一说的。",
          DialogueId = 51126206,
          GUID = "7FFD352C",
          NextDialogue = 51126207,
          SpeakNpcId = 701047
        },
        [51126207] = {
          Content = "那就把我的钱拿去扶持那些刚加进来的织星客吧，就像当年商会扶持我一样！",
          DialogueId = 51126207,
          GUID = "7FFD3556",
          SpeakNpcId = 701048
        },
        [51126301] = {
          Content = "不好说，但这月亮怎么也是当年的织星客一砖一瓦建出来的，肯定是留了一条上去的路。",
          DialogueId = 51126301,
          GUID = "7FFD44C2",
          NextDialogue = 51126302,
          SpeakNpcId = 701049
        },
        [51126302] = {
          Content = "何况这毕竟也是咱们这一片的大香炉，日常也得有人去维修之类的。",
          DialogueId = 51126302,
          GUID = "7FFD44EC",
          NextDialogue = 51126303,
          SpeakNpcId = 701049
        },
        [51126303] = {
          Content = "你说的是，可是路在哪儿啊，我也没瞧见啊？",
          DialogueId = 51126303,
          GUID = "7FFD4516",
          NextDialogue = 51126304,
          SpeakNpcId = 701050
        },
        [51126304] = {
          Content = "诶呀，我在想办法了，你不要吵。",
          DialogueId = 51126304,
          GUID = "7FFD4540",
          NextOptions = {
            [1] = 51126305,
            [2] = 51126312,
            [3] = 51126323
          },
          SpeakNpcId = 701049
        },
        [51126305] = {
          Content = "你们在聊什么？",
          DialogueId = 51126305,
          GUID = "7FFD456A",
          NextDialogue = 51126306
        },
        [51126306] = {
          Content = "唔啊！异国人！",
          DialogueId = 51126306,
          GUID = "7FFD4594",
          NextDialogue = 51126307,
          SpeakNpcId = 701050
        },
        [51126307] = {
          Content = "异国人也对这个大月亮感兴趣吗？",
          DialogueId = 51126307,
          GUID = "7FFD45BE",
          NextOptions = {
            [1] = 51126308,
            [2] = 51126310
          },
          SpeakNpcId = 701049
        },
        [51126308] = {
          Content = "感兴趣。",
          DialogueId = 51126308,
          GUID = "7FFD45E8",
          NextDialogue = 51126309
        },
        [51126309] = {
          Content = "阿兔真笨，谁来到百年春对这月亮不感兴趣的？那么大一个，恐怕在海上漂着的时候隔着老远就能看到了啦。",
          DialogueId = 51126309,
          GUID = "7FFD4612",
          SpeakNpcId = 701049
        },
        [51126310] = {
          Content = "不感兴趣。",
          DialogueId = 51126310,
          GUID = "7FFD463C",
          NextDialogue = 51126311
        },
        [51126311] = {
          Content = "诶？怎么可能！那么亮，那么大，你不感兴趣吗？我不信！",
          DialogueId = 51126311,
          GUID = "7FFD4666",
          SpeakNpcId = 701050
        },
        [51126312] = {
          Content = "你们为什么要爬上去？",
          DialogueId = 51126312,
          GUID = "7FFD4690",
          NextDialogue = 51126313
        },
        [51126313] = {
          Content = "之前有人说，大月亮顶上是咱们这烟津渡的最高点，站在上面就能看到整个烟津渡，我们想上去看看！",
          DialogueId = 51126313,
          GUID = "7FFD46BA",
          NextDialogue = 51126314,
          SpeakNpcId = 701049
        },
        [51126314] = {
          Content = "对！我们想去数数这百年春的头顶一天会飞过去多少只薯了鸥！",
          DialogueId = 51126314,
          GUID = "7FFD46E4",
          NextOptions = {
            [1] = 51126315
          },
          SpeakNpcId = 701050
        },
        [51126315] = {
          Content = "所以这月亮是个建筑？",
          DialogueId = 51126315,
          GUID = "7FFD470E",
          NextDialogue = 51126316
        },
        [51126316] = {
          Content = "你不知道？哦也是，你是异国人呢，这月亮是我们烟津渡的大型香炉，是曾经有个很有钱的织星客投资盖的呢。",
          DialogueId = 51126316,
          GUID = "7FFD4738",
          NextOptions = {
            [1] = 51126317
          },
          SpeakNpcId = 701049
        },
        [51126317] = {
          Content = "为什么是个月亮的样子？",
          DialogueId = 51126317,
          GUID = "7FFD4762",
          NextDialogue = 51126318
        },
        [51126318] = {
          Content = "这个我知道！因为那位织星客说，所有出海在外的织星客们就像天上的星星，有朝一日总会回到故乡，而故乡应该有一盏明月，等待游子们的归来！",
          DialogueId = 51126318,
          GUID = "7FFD478C",
          NextDialogue = 51126319,
          SpeakNpcId = 701050
        },
        [51126319] = {
          Content = "可算给你装了一把，那你知不知道，那位织星客给大月亮起的名字叫什么？",
          DialogueId = 51126319,
          GUID = "7FFD47B6",
          NextDialogue = 51126320,
          SpeakNpcId = 701049
        },
        [51126320] = {
          Content = "唔……这个我没记住……",
          DialogueId = 51126320,
          GUID = "7FFD47E0",
          NextDialogue = 51126321,
          SpeakNpcId = 701050
        },
        [51126321] = {
          Content = "咳咳，就让我告诉你吧，这个大月亮叫——月是故乡明。",
          DialogueId = 51126321,
          GUID = "7FFD480A",
          NextDialogue = 51126322,
          SpeakNpcId = 701049
        },
        [51126322] = {
          Content = "好长的名字，不怪我记不住嘛！我看还是大月亮好记。",
          DialogueId = 51126322,
          GUID = "7FFD4834",
          SpeakNpcId = 701050
        },
        [51126323] = {
          Content = "以后再来找你们玩吧。",
          DialogueId = 51126323,
          GUID = "7FFD485E",
          NextDialogue = 51126324
        },
        [51126324] = {
          Content = "再见外国人，我们还是继续想想怎么才能爬上去吧。",
          DialogueId = 51126324,
          GUID = "7FFD4888",
          SpeakNpcId = 701049
        },
        [51126401] = {
          Content = "奇了，今天能碰到这种老古董千星板，拿来用来预测天气都难……更别说是运势上……",
          DialogueId = 51126401,
          GUID = "7FFD552A",
          NextDialogue = 51126402,
          SpeakNpcId = 701051
        },
        [51126402] = {
          Content = "想必这块板得比我爷爷的爷爷的爷爷岁数还要大……不，或许会比我爷爷的爷爷的……诶呀，太绕口了，总之就是祖宗辈的！",
          DialogueId = 51126402,
          GUID = "7FFD5554",
          NextOptions = {
            [1] = 51126403,
            [2] = 51126405
          },
          SpeakNpcId = 701051
        },
        [51126403] = {
          Content = "你在做什么？",
          DialogueId = 51126403,
          GUID = "7FFD557E",
          NextDialogue = 51126404
        },
        [51126404] = {
          Content = "我？刚淘了个千星板，老古董了，想着拿回家玩玩，就当作收藏了。你是谁啊，你也对这种以前的东西感兴趣？",
          DialogueId = 51126404,
          GUID = "7FFD55A8",
          SpeakNpcId = 701051
        },
        [51126405] = {
          Content = "千星板？那是什么？",
          DialogueId = 51126405,
          GUID = "7FFD55D2",
          NextDialogue = 51126406
        },
        [51126406] = {
          Content = "哦？一个异国人对我们华胥的东西感兴趣，那我作为东道主，岂不是要多指导指导你了？有什么你不懂的，尽管问我，我一定知无不言言无不尽！",
          DialogueId = 51126406,
          GUID = "7FFD55FC",
          SpeakNpcId = 701051
        },
        [51126407] = {
          Content = "嚯，这块千星板的年岁可真够久了！",
          DialogueId = 51126407,
          GUID = "7FFD5626",
          NextDialogue = 51126408,
          SpeakNpcId = 701051
        },
        [51126408] = {
          Content = "来啦，是要问千星板的事情吗？",
          DialogueId = 51126408,
          GUID = "7FFD5650",
          NextDialogue = 51126430,
          SpeakNpcId = 701051
        },
        [51126409] = {
          Content = "千星板的来历？",
          DialogueId = 51126409,
          GUID = "7FFD567A",
          NextDialogue = 51126410
        },
        [51126410] = {
          Content = "这个的话……说来话长。千星板最早可以追溯到华胥建国之前呢，就是那个矩和飏的时代，百家争鸣，有一派名为秉烛，专研观星。",
          DialogueId = 51126410,
          GUID = "7FFD56A4",
          NextDialogue = 51126411,
          SpeakNpcId = 701051
        },
        [51126411] = {
          Content = "秉烛派认为，头顶的星空之中暗藏着足以毁灭整个世界的危机，为了抵御这场危机，他们研习千星术，通过观测星空和星象来寻找破局之法。",
          DialogueId = 51126411,
          GUID = "7FFD56CE",
          NextDialogue = 51126412,
          SpeakNpcId = 701051
        },
        [51126412] = {
          Content = "就是这样的一个门派里，却出了一名奇人——北落，北落认为，整日将心思放在星星和月亮，未来和虚无也太无聊了。",
          DialogueId = 51126412,
          GUID = "7FFD56F8",
          NextDialogue = 51126413,
          SpeakNpcId = 701051
        },
        [51126413] = {
          Content = "他更喜欢和自己的朋友走街串巷，他那朋友里，就有着当时还没出华胥的矩。",
          DialogueId = 51126413,
          GUID = "7FFD5722",
          NextDialogue = 51126414,
          SpeakNpcId = 701051
        },
        [51126414] = {
          Content = "所以在他们的协作下，第一块千星板出现了，就像我手中的这块一样，最开始的板只有导航的作用，不过在那个时候，也够用了。",
          DialogueId = 51126414,
          GUID = "7FFD574C",
          NextDialogue = 51126430,
          SpeakNpcId = 701051
        },
        [51126415] = {
          Content = "千星板只有织星客有吗？",
          DialogueId = 51126415,
          GUID = "7FFD5776",
          NextDialogue = 51126416
        },
        [51126416] = {
          Content = "其实只要想买，有的是办法搞到手。但是千星板并非是拿到手上就能用明白的。",
          DialogueId = 51126416,
          GUID = "7FFD57A0",
          NextDialogue = 51126417,
          SpeakNpcId = 701051
        },
        [51126417] = {
          Content = "你看，我现在开启这块千星板，你能不能看明白。",
          DialogueId = 51126417,
          GUID = "7FFD57CA",
          NextDialogue = 51126418,
          SpeakNpcId = 701051
        },
        [51126418] = {
          Content = "（他将千星板摊在掌心，那交叠的方块自下而上缓缓旋转叠升，直到交隔之间微微悬浮，转至最顶端的小方块停滞不动。）",
          DialogueId = 51126418,
          GUID = "7FFD57F4",
          NextDialogue = 51126419
        },
        [51126419] = {
          Content = "这就是开启成功的样子了，此物会随着方位的变换而旋转角度，只有织星客们才会专门去学习如何从这些角度里解读出方位信息。",
          DialogueId = 51126419,
          GUID = "7FFD581E",
          NextDialogue = 51126420,
          SpeakNpcId = 701051
        },
        [51126420] = {
          Content = "理论上说，只要学会了都能用，但就是这学会……也不是简单的事。",
          DialogueId = 51126420,
          GUID = "7FFD5848",
          NextDialogue = 51126430,
          SpeakNpcId = 701051
        },
        [51126421] = {
          Content = "千星板有哪些功能？",
          DialogueId = 51126421,
          GUID = "7FFD5872",
          NextDialogue = 51126422
        },
        [51126422] = {
          Content = "最早的千星板是只有导航的作用，但随着织星客们后续对千星板的不断改进，现在的千星板也多了一些功能。",
          DialogueId = 51126422,
          GUID = "7FFD589C",
          NextDialogue = 51126423,
          SpeakNpcId = 701051
        },
        [51126423] = {
          Content = "比如观测天气，通过观测星星的变化和流动，推断出未来一段时间天气情况如何，非常实用，要是运什么需要干燥保存的货物赶上了下雨天可就麻烦啦。",
          DialogueId = 51126423,
          GUID = "7FFD58C6",
          NextDialogue = 51126424,
          SpeakNpcId = 701051
        },
        [51126424] = {
          Content = "还有观测运势，织星客们认为星空的变动与世间的一切有着密不可分的关系，尤其是有关自身的商业、动迁计划等。",
          DialogueId = 51126424,
          GUID = "7FFD58F0",
          NextDialogue = 51126425,
          SpeakNpcId = 701051
        },
        [51126425] = {
          Content = "他们往往会选择星势良好的日子出行或做一些决定，也会在星势不好的日子里拒绝出门和交易。",
          DialogueId = 51126425,
          GUID = "7FFD591A",
          NextDialogue = 51126426,
          SpeakNpcId = 701051
        },
        [51126426] = {
          Content = "但这种功能繁多的板子很难用的，最基础的还是导航啦，简单直接，家家常备。",
          DialogueId = 51126426,
          GUID = "7FFD5944",
          NextDialogue = 51126430,
          SpeakNpcId = 701051
        },
        [51126427] = {
          Content = "没什么想问的了。",
          DialogueId = 51126427,
          GUID = "7FFD596E",
          NextDialogue = 51126428
        },
        [51126428] = {
          Content = "织星客们这么多年，每年都会给千星术起源的秉烛派送些香火钱，多少也是买个技术费了。",
          DialogueId = 51126428,
          GUID = "7FFD5998",
          NextDialogue = 51126429,
          SpeakNpcId = 701051
        },
        [51126429] = {
          Content = "若是有机会，你可得去秉烛派逛逛，看看他们又用千星术琢磨出什么新东西了。",
          DialogueId = 51126429,
          GUID = "7FFD59C2",
          SpeakNpcId = 701051
        },
        [51126430] = {
          DialogueId = 51126430,
          DialoguePanelType = "None",
