          ImprPlusId = 1211,
          NextDialogue = 51127915
        },
        [51127915] = {
          Content = "（自尘土中来，归尘土中去……）",
          DialogueId = 51127915,
          GUID = "7FFE4D8E"
        },
        [51128001] = {
          Content = "嘶……又冷起来了，这鬼天气！我带来的考古器材全都结了一层晶，零件迟钝，反应不灵，诶！又要让虬先生破费维修了！",
          DialogueId = 51128001,
          GUID = "7FFE5BAA",
          NextDialogue = 51128002,
          SpeakNpcId = 701072
        },
        [51128002] = {
          Content = "咦？你是谁？你怎么会跑到这种地方来？快回去快回去，这里可不是等闲之辈可以随意来往的地方！",
          DialogueId = 51128002,
          GUID = "7FFE5BD4",
          NextOptions = {
