        [51140037] = {
          Camera = "-287.652344,948.660156,170.522461,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "（扶疏正痴痴望着一个方向发呆，连鱼龙也显得垂头丧气。）",
          DialogueId = 51140037,
          FinalCamera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          GUID = "80061252",
          Scripts = "PARA{\nMoveTo{ActorId{100001},MoveSpeed{100},TargetPoint{\"Targetpoint_20030901\"},Visibility{\"Show\"}},\nMoveTo{ActorId{200002},MoveSpeed{100},TargetPoint{\"Targetpoint_20030902\"},Visibility{\"Show\"}}\n}",
          SpeakNpcId = 0,
          TalkActionId = {
            [1] = "701075:Think_Start"
          },
          ToFinalCameraBlendTime = 4
        },
        [51140038] = {
          Content = "是有什么心事吗？",
          DialogueId = 51140038,
          GUID = "8006127C",
          ImprPlusId = 1209
        },
        [51140039] = {
          Content = "（等她发现自己。）",
          DialogueId = 51140039,
          GUID = "800612A6",
          ImprPlusId = 1207
        },
        [51140040] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "唔，{nickname}，是你……怎么得空来了枯荣阁，温习时想起一些往事，不免失神，让你见笑了。",
          DialogueId = 51140040,
          GUID = "800612D0",
          LookAt = {
            [1] = "701075:n(100001)"
          },
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Think_End"
          },
          TurnTo = {
            [1] = "701075:n(100001)"
          }
        },
        [51140041] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "唔，{nickname}，是你……怎么得空来了枯荣阁，温书入迷一时失神，居然没注意到你进来。",
          DialogueId = 51140041,
          GUID = "800612FA",
          LookAt = {
            [1] = "701075:n(100001)"
          },
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Think_End"
          },
          TurnTo = {
            [1] = "701075:n(100001)"
          }
        },
        [51140042] = {
          Camera = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
          Content = "我都要把这里的诊籍都翻遍了，不是发烧感冒就是胃痛腹泻，怎么也和尾生说的那种情况对不上呀。",
          DialogueId = 51140042,
          GUID = "80061324",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Alright_Start"
          }
        },
        [51140043] = {
          Camera = "147.988281,-372.753906,263.493164,0.000021,-23.151232,113.072533,76.142418,493.532471,false,Manual,3.0",
          Content = "扶疏扶疏，我们这次来是有一件奇怪的事情要问你呢！",
          DialogueId = 51140043,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "8006134E",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          TurnTo = {
            [1] = "100001:n(701075)",
            [2] = "701075:n(200002)"
          }
        },
        [51140044] = {
          Camera = "-74.871094,-49.457031,176.993164,0.000086,-14.999942,-17.730551,35.000015,130.112747,false,Manual,7.0",
          Content = "是身体不适还是另有心疾，能帮到你的地方，扶疏定然鼎力相助。",
          DialogueId = 51140044,
          FacialId = {
            [1] = "701075:Smile01"
          },
          GUID = "80061378",
          SpeakNpcId = 701075
        },
        [51140045] = {
          Content = "（你向扶疏讲述了一位无由生在寻找生病妻子的事。）",
          DialogueId = 51140045,
          GUID = "800613A2",
          IsBlack = 1,
          SpeakNpcId = 0,
          TurnTo = {
            [1] = "701075:n(100001)"
          }
        },
        [51140046] = {
          Camera = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
          Content = "大抵是家姐生前收治过的病人。据记载，烟津渡上次洪灾致人溺亡已是九十余年前……",
          DialogueId = 51140046,
          GUID = "800613CC",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Explain01_Start",
            [2] = "200002:Excited01_End"
          }
        },
        [51140047] = {
          Camera = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
          Content = "那时家姐年纪尚轻，尚未自立门户，还在枯荣阁坐诊。",
          DialogueId = 51140047,
          GUID = "800613F6",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Explain01_End"
          }
        },
        [51140048] = {
          Camera = "171.115234,-119.117188,100.751953,0.000108,-4.999999,154.070587,35.000008,300.780701,false,Manual,5.20548",
          Content = "那个尾生竟然已经死了九十多年了吗！",
          DialogueId = 51140048,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "80061420",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          }
        },
        [51140049] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "没错，他的妻子如今还活着的希望已是渺茫。",
          DialogueId = 51140049,
          FacialId = {
            [1] = "701075:Think01"
          },
          GUID = "8006144A",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Think_Start"
          }
        },
        [51140050] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "但如此痴情之人，帮他寻得当年妻子下落，权当圆他一个念想，让他得以了却执念，回归往生也好。",
          DialogueId = 51140050,
          GUID = "80061474",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "200002:Shock03_End"
          }
        },
        [51140051] = {
          Camera = "-113.632812,-83.152344,198.851562,0.00007,-17.949545,-0.526916,35.000011,645.22876,false,DoNotOverride,7.0",
          Content = "家姐历年行医都有诊籍留档，{nickname}，我随你去阁中找找。",
          DialogueId = 51140051,
          FacialId = {
            [1] = "701075:None"
          },
          GUID = "8006149E",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Think_End"
          }
        },
        [51140052] = {
          Camera = "95.519531,110.679688,109.566406,0.000037,0.0,-126.112823,11.880002,248.943176,false,Manual,2.8",
          Content = "找到诊籍了吗？",
          DialogueId = 51140052,
          GUID = "800614C8",
          Scripts = "SEQ{ MoveTo{ActorId{701075},MoveSpeed{150},TargetPoint{\"Targetpoint_20030907\"}}, TurnTo{TurnToDescription{\"701075:n(100001)\"}}\n}",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "200002:Alright_End"
          }
        },
        [51140053] = {
          Camera = "-6.933594,-41.625,141.566406,0.000099,-5.84296,-115.514038,14.773981,58.703678,false,Manual,2.8",
          Content = "没有，似乎没有对得上的，只有这一篇有些奇怪。",
          DialogueId = 51140053,
          GUID = "800614F2",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51140054] = {
          Content = "（你将诊籍递给扶疏，她仔细看了一会儿。）",
          DialogueId = 51140054,
          GUID = "8006151C",
          IsBlack = 1,
          SpeakNpcId = 0
        },
        [51140055] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "咦……这里面有个人……我曾在姐姐的日记里见过……",
          DialogueId = 51140055,
          GUID = "80061546",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Think_Start"
          }
        },
        [51140056] = {
          Camera = "120.662109,32.841797,142.3125,0.000078,-19.999907,-159.908264,22.322252,236.840927,false,Manual,7.0",
          Content = "日记？你姐姐还写过日记呀？",
          DialogueId = 51140056,
          GUID = "80061570",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "701075:n(200002)"
          },
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Talk01_Start",
            [2] = "701075:Think_End"
          }
        },
        [51140057] = {
          Camera = "-93.105469,39.958984,123.023438,0.000084,6.0,-18.908363,35.000008,178.587616,false,Manual,7.0",
          Content = "嗯，姐姐怕我醒了后她不在，我对她不与我重叠的生活毫无了解，便将自己的经历以日记形式记录了下来。",
          DialogueId = 51140057,
          GUID = "8006159A",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "701075:n(200002)"
          },
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Explain02_Start",
            [2] = "200002:Talk01_End"
          }
        },
        [51140058] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "……不好意思，又提到你的伤心事了。",
          DialogueId = 51140058,
          GUID = "800615C4",
          LookAt = {
            [1] = "701075:n(100001)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "701075:Explain02_End"
          }
        },
        [51140059] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "并无感伤，姐姐想必也是不愿看到我伤怀才如此行事。",
          DialogueId = 51140059,
          GUID = "800615EE",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Disagree"
          }
        },
        [51140060] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "姐姐曾在年轻时的日记里提过一名患者，其妻在大疫中不幸殒命，自此患上心病，终日幻想其妻尚存于世，与那个不存在的人对话。",
          DialogueId = 51140060,
          GUID = "80061618",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Talk03_Start"
          }
        },
        [51140061] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "姐姐写道，这让她照见了自己的影子，如同姐姐与沉睡中的我对话一样，有趣却又愚痴。",
          DialogueId = 51140061,
          GUID = "80061642",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Talk03ToThink_Start"
          }
        },
        [51140062] = {
          Content = "那位患者拒绝服药，姐姐只得想了个法子，借口要为他的妻子诊病，以试药为由，回回让他带走两副汤药，自己先吃一副。",
          DialogueId = 51140062,
          GUID = "8006166C",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Talk03ToThink_End"
          }
        },
        [51140063] = {
          Camera = "124.955078,118.574219,128.228516,0.000018,-6.242916,-137.315506,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "我想起来了！尾生之前说过，他给自己的妻子试药来着！",
          DialogueId = 51140063,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "80061696",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          }
        },
        [51140064] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "…………！原来如此，尾生的妻子，我们已经找到了。她就是：",
          DialogueId = 51140064,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "800616C0",
          LookAt = {
            [1] = "100001:n(701075)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "200002:Shock03_End"
          }
        },
        [51140065] = {
          Content = "刘姓女子",
          DialogueId = 51140065,
          GUID = "800616EA",
          ImprPlusId = 1211
        },
        [51140066] = {
          Content = "陈姓女子",
          DialogueId = 51140066,
          GUID = "80061714",
          ImprPlusId = 1211
        },
        [51140067] = {
          Content = "柳姓男子",
          DialogueId = 51140067,
          GUID = "8006173E",
          ImprPlusId = 1211
        },
        [51140068] = {
          Content = "早已不存于世",
          DialogueId = 51140068,
          GUID = "80061768",
          ImprPlusId = 1208
        },
        [51140069] = {
          Camera = "-130.283203,752.826172,160.511719,0.000086,2.696961,101.435776,11.88,100000.0,false,Manual,2.8",
          Content = "想来，那名真正的患者，应是诊籍里的柳姓男子，也就是<H>柳尾生</>吧？",
          DialogueId = 51140069,
          GUID = "80061792",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Talk03ToTalkL_Start"
          }
        },
        [51140070] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "拜托你们寻找妻子的那位无由生名叫尾生，应该就是这位柳姓病人死后幻化而成。",
          DialogueId = 51140070,
          GUID = "800617BC",
          SpeakNpcId = 701075
        },
        [51140071] = {
          Camera = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
          Content = "扶疏，你在说什么呀……我都有点糊涂了……",
          DialogueId = 51140071,
          GUID = "800617E6",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Disagree",
            [2] = "701075:Talk03ToTalkL_End"
          }
        },
        [51140072] = {
          Camera = "-86.828125,129.613281,73.053711,0.000108,9.999997,-87.957306,28.133715,234.328125,false,Manual,1.855292",
          Content = "……我明白了！你姐姐救治的那个病人，不是尾生的妻子，而是尾生自己！他的妻子早就过世了，而他得了心病，一直以为自己的妻子还在身边！",
          DialogueId = 51140072,
          GUID = "80061810",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(701075)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51140073] = {
          Camera = "-642.771484,-71.21875,4.600586,0.000118,7.999989,2.046195,42.955368,234.325912,false,DoNotOverride,7.0",
          Content = "是的……他之所以在暴雨中苦等一夜，直到溺亡都等不来他的妻子，是因为他吃了药，妄想的症状有所减轻，所以反而“看不到”幻想出的妻子了。",
          DialogueId = 51140073,
          GUID = "8006183A",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Talk03_End"
          }
        },
        [51140074] = {
          Camera = "-6.933594,-41.625,141.566406,0.000099,-5.84296,-115.514038,14.773981,58.703678,false,Manual,2.8",
          Content = "扶疏，这册诊籍里的柳姓男子，他的名字是不是叫<H>柳尾生</>？",
          DialogueId = 51140074,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "80061864",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51140075] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "不错。他的姓名应该只记在姐姐日记里，你怎知……？",
          DialogueId = 51140075,
          GUID = "8006188E",
          SpeakNpcId = 701075
        },
        [51140076] = {
          Camera = "-86.828125,129.613281,73.053711,0.000108,9.999997,-87.957306,28.133715,234.328125,false,Manual,1.855292",
          Content = "拜托我们寻找妻子的那位无由生名叫尾生，应该就是这位柳姓病人死后幻化而成。",
          DialogueId = 51140076,
          GUID = "800618B8",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ConfidentLToExplain_Start"
          }
        },
        [51140077] = {
          Camera = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
          Content = "……我明白了！扶疏的姐姐救治的那个病人，不是尾生的妻子，而是尾生自己！他的妻子早就过世了，而他得了心病，一直以为自己的妻子还在身边！",
          DialogueId = 51140077,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "80061800.0",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          }
        },
        [51140078] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "是的……他之所以在暴雨中苦等一夜，直到溺亡都等不来他的妻子，是因为他吃了药，妄想的症状有所减轻，所以反而“看不到”幻想出的妻子了。",
          DialogueId = 51140078,
          GUID = "8006190C",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ConfidentLToExplain_End",
            [2] = "200002:Excited02_End"
          }
        },
        [51140079] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "竟是……此般造化弄人。",
          DialogueId = 51140079,
          GUID = "80061936",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "100001:Confident_End"
          }
        },
        [51140080] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "呜……小仆从，我们赶紧回去把消息带给尾生吧。它实在太可怜了，希望它能解脱出来，回到那个什么忘川……",
          DialogueId = 51140080,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "80061960",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Sigh_Start"
          }
        },
        [51140081] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "恕我冒昧，{nickname}，你打算如何告知那位尾生呢？",
          DialogueId = 51140081,
          FacialId = {
            [1] = "701075:Disappoint01"
          },
          GUID = "8006198A",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Talk02_Start",
            [2] = "200002:Sigh_End"
          }
        },
        [51140082] = {
          Camera = "-80.082031,72.5625,90.84375,0.000107,3.097224,-93.557159,11.88,234.325912,false,Manual,1.855292",
          Content = "扶疏，你似乎有什么建议？",
          DialogueId = 51140082,
          GUID = "800619B4",
          LookAt = {
            [1] = "200002:n(701075)",
            [2] = "100001:n(701075)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "701075:Talk02_End",
            [2] = "100001：Explain02_Start"
          }
        },
        [51140083] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "那位无由生，生前便已执念深重，不愿相信眼前事实。倘若如实告知，只怕……对它的执念并无助益。",
          DialogueId = 51140083,
          GUID = "800619DE",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Explain02_Start"
          }
        },
        [51140084] = {
          Camera = "-19.023438,-3.457031,149.845703,0.000083,1.15922,-11.708227,35.000008,85.264961,false,Manual,7.0",
          Content = "如果你愿意听扶疏一言——",
          DialogueId = 51140084,
          GUID = "80061A08",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "100001：Explain02_End"
          }
        },
        [51140085] = {
          Content = "（扶疏在你的耳边低语了几句。）",
          DialogueId = 51140085,
          GUID = "80061A32",
          IsBlack = 1,
          LookAt = {
            [1] = "701075:n(701075)"
          },
          SpeakNpcId = 0
        },
        [51140086] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "如此，对它来说或许是更好的答案。",
          DialogueId = 51140086,
          FacialId = {
            [1] = "701075:None"
          },
          GUID = "80061A5C",
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Explain02_End"
          }
        },
        [51140087] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "谢谢你，扶疏。我们告辞了。",
          DialogueId = 51140087,
          GUID = "80061A86",
          Scripts = "PARA{\nMoveTo{_delay{2},ActorId{100001},MoveSpeed{150},TargetPoint{\"Targetpoint_20030905\"}},\nMoveTo{_delay{2},ActorId{200002},MoveSpeed{150},TargetPoint{\"Targetpoint_20030906\"}}\n}",
          SpeakNpcId = 100001
        },
        [51140088] = {
          Camera = "112.988281,113.580078,57.077148,0.000138,3.696717,102.451233,35.000008,820.2052,false,Manual,7.0",
          Content = "……斯人已逝，徒留生者徘徊在尘世间，茕茕孑立，形影成双。",
          DialogueId = 51140088,
          GUID = "80061AB0",
          Scripts = "MoveTo{ActorId{701075},MoveSpeed{150},TargetPoint{"Targetpoint_20030904"}},",
          SpeakNpcId = 701075
        },
        [51140089] = {
          Camera = "-50.109375,864.226562,147.566406,0.000144,0.0,169.044022,50.171638,134.067627,false,Manual,7.0",
          Content = "消弭执念，说起来容易，但对真正心怀执念的人而言，它真的好沉重……太沉重了……你说是不是？",
          DialogueId = 51140089,
          FacialId = {
            [1] = "701075:Sad01"
          },
          GUID = "80061ADA",
          Scripts = "SEQ{ TurnTo{TurnToDescription{\"701075:p(-20)\"}}, LookAt{LookAtDescription{\"701075:n(100001)\"}}\n}",
          SpeakNpcId = 701075
        },
        [51140090] = {
          Camera = "-50.109375,864.226562,147.566406,0.000144,0.0,169.044022,50.171638,134.067627,false,Manual,7.0",
          Content = "——姐姐。",
          DialogueId = 51140090,
          GUID = "80061B04",
          LookAt = {
            [1] = "701075:n(701075)"
          },
          SpeakNpcId = 701075,
          TalkActionId = {
            [1] = "701075:Sad02_Start"
          }
        },
        [51150001] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "你们回来了！怎么样，有问到我妻子的消息吗？",
          DialogueId = 51150001,
          GUID = "800C750A",
          SpeakNpcId = 701074,
          TalkActionId = {
            [1] = "701074:Wuyou_Born"
          }
        },
        [51150002] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "（按照扶疏的建议，你开始向尾生娓娓道来妻子的下落……）",
          DialogueId = 51150002,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800C7534",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51150003] = {
          Camera = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
          Content = "什么？你说闲书已经不在人世了？因为……我已经死了九十多年？",
          DialogueId = 51150003,
          GUID = "800C755E",
          SpeakNpcId = 701074
        },
        [51150004] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          Content = "是的。",
          DialogueId = 51150004,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "800C7588",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001：Explain01_End"
          }
        },
        [51150005] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "……原来……在这虞泉……我竟已浑浑噩噩度过如此之久……",
          DialogueId = 51150005,
          GUID = "800C75B2",
          SpeakNpcId = 701074
        },
        [51150006] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "那闲书呢？她去了哪儿？她……这些年来，她好吗？",
          DialogueId = 51150006,
          GUID = "800C75DC",
          SpeakNpcId = 701074
        },
        [51150007] = {
          Camera = "-455.513672,-227.362305,283.345703,0.000077,-20.494774,26.363897,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "(你与白对视了一眼）",
          DialogueId = 51150007,
          GUID = "800C7606",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 0
        },
        [51150008] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "闲书抱病多年，一直得你照料，但她不愿成为你的负累。所以当年，她选择了离家出走。",
          DialogueId = 51150008,
          GUID = "800C7630",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ExplainTwo_Start"
          }
        },
        [51150009] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "但是……机缘巧合之下，她遇到了一位在烟津渡旅行的天才药师。在那位天才药师的悉心治疗下，闲书得以痊愈。",
          DialogueId = 51150009,
          GUID = "800C765A",
          LookAt = {
            [1] = "100001:n(701074)",
            [2] = "200002:n(701074)"
          },
          SpeakNpcId = 100001
        },
        [51150010] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "可当她回到家去找你的时候，却听到了你已经死在洪水里的消息。",
          DialogueId = 51150010,
          FacialId = {
            [1] = "100001:Sad03"
          },
          GUID = "800C7684",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ExplainTwo_End"
          }
        },
        [51150011] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "竟是……如此……",
          DialogueId = 51150011,
          GUID = "800C76AE",
          SpeakNpcId = 701074
        },
        [51150012] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          Content = "但，她并没有让自己就这样一辈子浑浑噩噩下去。为你痛哭一场后，她拜那位药师为师，开始学习药学。",
          DialogueId = 51150012,
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "800C76D8",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51150013] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          Content = "她希望可以尽绵薄之力，为那些被病痛折磨的人缓解痛苦。她不希望她与你的悲剧，再在其他人身上上演。",
          DialogueId = 51150013,
          GUID = "800C7702",
          SpeakNpcId = 100001
        },
        [51150014] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "她是一个勤奋的学生，后来，她也成为了老师，她也有了自己的学生。再后来，学生又有了学生……",
          DialogueId = 51150014,
          GUID = "800C772C",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51150015] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "他们一起，救治了很多病人。学生们都很爱戴她，就像她的儿女一样……一直到她九十岁高龄辞世。",
          DialogueId = 51150015,
          GUID = "800C7756",
          SpeakNpcId = 100001
        },
        [51150016] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "……太好了，太好了……",
          DialogueId = 51150016,
          GUID = "800C7780",
          SpeakNpcId = 701074
        },
        [51150017] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "她的病好了……她幸福地度过一生……我便放心了……",
          DialogueId = 51150017,
          GUID = "800C77AA",
          SpeakNpcId = 701074,
          TalkActionId = {
            [1] = "701074:Wuyou_Agree"
          }
        },
        [51150018] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "一切都……过去了……我也可以安心地……",
          DialogueId = 51150018,
          GUID = "800C77D4",
          SpeakNpcId = 701074
        },
        [51150019] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "谢谢你们，二位，真的……谢谢……",
          DialogueId = 51150019,
          GUID = "800C77FE",
          SpeakNpcId = 701074,
          TalkActionId = {
            [1] = "701074:Wuyou_Disappear"
          }
        },
        [51150020] = {
          Content = "尾生的身体逐渐透明，直到逐渐消失在你面前，在完全消散的瞬间，你看到什么晶莹剔透的东西从它体内坠落。",
          DialogueId = 51150020,
          GUID = "800C7828",
          SpeakNpcId = 0
        },
        [51150021] = {
          Content = "无由生也会流泪吗？还是说只是一束偶然折射过来的阳光……",
          DialogueId = 51150021,
          GUID = "800C7852",
          SpeakNpcId = 0
        },
        [51151201] = {
          Camera = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "是白魔王大人和她忠诚的有龙氏随从！你们来找我玩啦！",
          DialogueId = 51151201,
          GUID = "800D39EA",
          NextDialogue = 51151202,
          Scripts = "SEQ{\nPARA{\nLookAt{LookAtDescription{\"200002:n(900012)\"}}, \nLookAt{LookAtDescription{\"100001:n(900012)\"}},\nPlayAnimation{ActorId{900012},AnimationId{\"Talk02_Start\"}},\nLookAt{LookAtDescription{\"900012:n(200002)\"}}\n},\nLookAt{_delay{1},LookAtDescription{\"900012:n(100001)\"}}\n}",
          SpeakNpcId = 900012
        },
        [51151202] = {
          Content = "“她忠诚的有龙氏随从”不配拥有自己的姓名吗？",
          DialogueId = 51151202,
          GUID = "800D3A14",
          NextDialogue = 51151203,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51151203] = {
          Content = "当然是开玩笑的啦，{nickname}也是锦鲤皎皎的好朋友！你的角红红的一只，像枫叶，很特别。我很羡慕这样的角呢。",
          DialogueId = 51151203,
          FacialId = {
            [1] = "900012:Smile02"
          },
          GUID = "800D3A3E",
          NextDialogue = 51151204,
          SpeakNpcId = 900012,
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "900012:Talk02_End"
          }
        },
        [51151204] = {
          Camera = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "说起来，锦鲤皎皎，这个高高的、装满小球的机器是什么？",
          DialogueId = 51151204,
          FacialId = {
            [1] = "900012:None"
          },
          FinalCamera = "368.707031,55.0,181.27832,0.000102,5.401252,-149.163544,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "800D3A68",
          NextDialogue = 51151205,
          SpeakNpcId = 200002,
          ToFinalCameraBlendTime = 1
        },
        [51151205] = {
          Camera = "277.509766,14.723633,155.932617,0.000082,-10.198612,-178.573135,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "不愧是火眼金睛的白魔王大人，一眼就能看出好东西！这可是本皎皎做生意的独家秘诀。",
          DialogueId = 51151205,
          FacialId = {
            [1] = "900012:Confident01"
          },
          GUID = "800D3A92",
          LookAt = {
            [1] = "900012:n(200002)"
          },
          NextDialogue = 51151206,
          SpeakNpcId = 900012,
          TalkActionId = {
            [1] = "900012:Excited01_Start"
          }
        },
        [51151206] = {
          Content = "我特意找一个机枢派的叫公、公什么的师傅定制了这套福运蛋机。只要往里面投入代币，它就会给你随机吐小奖品出来！",
          DialogueId = 51151206,
          GUID = "800D3ABC",
          NextDialogue = 51151207,
          SpeakNpcId = 900012,
          TalkActionId = {
            [1] = "900012:Excited01_End"
          }
        },
        [51151207] = {
          Camera = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "随机性才是挣钱的诀窍——这是本皎皎某天向白龙神君大人祈祷时，一下子福至心灵想出来的。怎么样，是不是天才般的想法？",
          DialogueId = 51151207,
          GUID = "800D3AE6",
          LookAt = {
            [1] = "900012:n(900012)"
          },
          NextDialogue = 51151208,
          SpeakNpcId = 900012,
          TalkActionId = {
            [1] = "900012:Excited02_Start"
          }
        },
        [51151208] = {
          Camera = "-57.599609,-59.527832,146.118164,0.000087,-5.198607,48.427074,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "那你的生意好吗？",
          DialogueId = 51151208,
          GUID = "800D3B10",
          NextDialogue = 51151209,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "900012:Excited02_End",
            [2] = "100001:Talk02_Start"
          }
        },
        [51151209] = {
          Camera = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "……呜，一般。",
          DialogueId = 51151209,
          FacialId = {
