            [2] = "100001:Talk02_End"
          }
        },
        [51151210] = {
          Content = "因为这个想法太新潮了，所以到现在连机器的本钱还没挣回来。大概这就是高手常常落寞吧。",
          DialogueId = 51151210,
          FacialId = {
