          GUID = "800D3BB8",
          SpeakNpcId = 900012,
          TalkActionId = {
            [1] = "900012:Shy03_End"
          }
        },
        [51151301] = {
          Content = "是{nickname}和白魔王大人，你们来找我玩啦！今天的福运蛋又上新了新款式，要不要来扭一发试试？",
          DialogueId = 51151301,
          GUID = "800D4A52",
          NextOptions = {
