          ContentFR = "Ne force pas trop ! Utilise vite le Sérum qu’on a préparé au Poste d’Alchimie !",
          DialogueId = 60030702,
          Duration = 4,
          GUID = "9647D2E3",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600307/9647D2E3"
        },
        [60030801] = {
          ContentFR = "Et voilà ! J’ai activé un nouveau Poste d’Alchimie !",
          DialogueId = 60030801,
          Duration = 4,
          GUID = "9647E34A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600308/9647E34A"
        },
        [60030901] = {
          ContentFR = "Aïe ! Il n’y a plus une goutte de Sérum dans le Poste d’Alchimie ! On ferait mieux de filer !",
          DialogueId = 60030901,
          Duration = 4,
          GUID = "9647F3B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600309/9647F3B2"
        },
        [60031001] = {
          ContentFR = "Allez, dépêche-toi d’utiliser le Sérum qu’on vient de fabriquer !",
          DialogueId = 60031001,
          Duration = 4,
          GUID = "9648041A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600310/9648041A"
        },
        [60031101] = {
          ContentFR = "Grrr... toxines... croître... mort... s’accélère... Grrr...",
          DialogueId = 60031101,
          Duration = 4,
          GUID = "96481482",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600311/96481482"
        },
        [60031201] = {
          ContentFR = "Les ennemis arrivent ! Heureusement, ce Poste d’Alchimie fonctionne ! Combats près de lui !",
          DialogueId = 60031201,
          Duration = 4,
          GUID = "964824EA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600312/964824EA"
        },
        [60040101] = {
          ContentFR = "Eh, on accepte vraiment les missions les plus étranges, pas vrai ? Allez, trouvons ce véhicule dont parlait le commanditaire.",
          DialogueId = 60040101,
          Duration = 4,
          GUID = "964DD912",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600401/964DD912"
        },
        [60040201] = {
          ContentFR = "Ouah ! On dirait que le signal a fonctionné — le véhicule bouge ! Reste sur tes gardes pendant l’escorte ! Pas question de s’effondrer avant d’arriver !",
          DialogueId = 60040201,
          Duration = 4,
          GUID = "964DE97A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600402/964DE97A"
        },
        [60040301] = {
          ContentFR = "Argh ! La porte du point de contrôle est encore verrouillée ! Élimine-les et fonce !",
          DialogueId = 60040301,
          Duration = 4,
          GUID = "964DF9E2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600403/964DF9E2"
        },
        [60040401] = {
          ContentFR = "La porte est ouverte, on peut continuer ! Bip bip biiip !",
          DialogueId = 60040401,
          Duration = 4,
          GUID = "964E0A4A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600404/964E0A4A"
        },
        [60040501] = {
          ContentFR = "Le véhicule est bloqué par un obstacle, détruis-le !",
          DialogueId = 60040501,
          Duration = 4,
          GUID = "964E1AB2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600405/964E1AB2"
        },
        [60040601] = {
          ContentFR = "Non, pas encore... L’obstacle tient toujours ! Allez, concentre-toi et fracasse-moi ça !",
          DialogueId = 60040601,
          Duration = 4,
          GUID = "964E2B1A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600406/964E2B1A"
        },
        [60040701] = {
          ContentFR = "Héhé ! Ce petit tas de débris croyait pouvoir nous arrêter ? Retourne près du véhicule et envoie le signal pour qu’il redémarre !",
          DialogueId = 60040701,
          Duration = 4,
          GUID = "964E3B82",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600407/964E3B82"
        },
        [60040801] = {
          ContentFR = "Argh ! La porte du point de contrôle est verrouillée ! Occupe-toi de cet officier pour qu’on puisse avancer !",
          DialogueId = 60040801,
          Duration = 4,
          GUID = "964E3B86",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600408/964E3B86"
        },
        [60050101] = {
          ContentFR = "Cette mission consiste à repousser tous les ennemis de la zone ? Ça me va ! On va leur montrer de quel bois on se chauffe.",
          DialogueId = 60050101,
          Duration = 4,
          GUID = "965441B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600501/965441B2"
        },
        [60050201] = {
          ContentFR = "On en a éliminé un sacré paquet... Ils devraient avoir compris la leçon, maintenant. Mission terminée, allons chercher notre récompense !",
          DialogueId = 60050201,
          Duration = 4,
          GUID = "9654521A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600502/9654521A"
        },
        [60060101] = {
          ContentFR = "La cible est à terre... Mission échouée.",
          DialogueId = 60060101,
          Duration = 1,
          GUID = "965AAA52",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/0/600601/965AAA52"
        },
        [60060201] = {
          ContentFR = "Cette mission est un peu plus délicate : il faut d’abord libérer la cible, puis la raccompagner en lieu sûr.",
          DialogueId = 60060201,
          Duration = 4,
          GUID = "965ABABA",
          NextDialogue = 60060202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABABA"
        },
        [60060202] = {
          ContentFR = "Suivons les repères indiqués par le commanditaire — la zone des <H>Cellules secrètes</> doit se trouver dans le repaire ennemi.",
          DialogueId = 60060202,
          Duration = 4,
          GUID = "965ABAE4",
          NextDialogue = 60060203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABAE4"
        },
        [60060203] = {
          ContentFR = "Mais au fait, qui est cette personne qu’on doit sauver ? Autant d’argent pour un inconnu aussi mystérieux... Ce serait pas un gros poisson, par hasard ?",
          DialogueId = 60060203,
          Duration = 4,
          GUID = "965ABB0E",
          NextDialogue = 60060204,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB0E"
        },
        [60060204] = {
          ContentFR = "Ou alors... il y a une petite histoire entre lui et le commanditaire, hmm ? Hé hé hé...",
          DialogueId = 60060204,
          Duration = 4,
          GUID = "965ABB38",
          NextDialogue = 60060205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB38"
        },
        [60060205] = {
          ContentFR = "N’oublie pas ce que le commanditaire a dit — pas de questions, sinon pas de paiement.",
          DialogueId = 60060205,
          Duration = 4,
          GUID = "965ABB62",
          NextDialogue = 60060206,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB62"
        },
        [60060206] = {
          ContentFR = "Euh... bon, d’accord. J’vais retenir ma curiosité, pour cette fois.",
          DialogueId = 60060206,
          Duration = 3,
          GUID = "965ABB8C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB8C"
        },
        [60060301] = {
          ContentFR = "D’après les infos qu’on a récoltées, les Cellules secrètes sont composées de plusieurs pièces isolées. L’une d’elles abrite la cible.",
          DialogueId = 60060301,
          Duration = 4,
          GUID = "965ACB22",
          NextDialogue = 60060302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB22"
        },
        [60060302] = {
          ContentFR = "Ces types sont vraiment prudents ! S’ils remarquent une tentative de sauvetage, ils pourraient supprimer la cible avant qu’on arrive...",
          DialogueId = 60060302,
          Duration = 4,
          GUID = "965ACB4C",
          NextDialogue = 60060303,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB4C"
        },
        [60060303] = {
          ContentFR = "Fais attention, surtout !",
          DialogueId = 60060303,
          Duration = 2.5,
          GUID = "965ACB76",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB76"
        },
        [60060401] = {
          ContentFR = "Regarde là-bas, c’est la zone des Cellules secrètes ! Fais gaffe à éviter les <H>patrouilles</> ennemies !",
          DialogueId = 60060401,
          Duration = 4,
          GUID = "965ADB8A",
          NextDialogue = 60060402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600604/965ADB8A"
        },
        [60060402] = {
          ContentFR = "S’ils déclenchent l’alarme, la cible est fichue !",
          DialogueId = 60060402,
          Duration = 3,
          GUID = "965ADBB4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600604/965ADBB4"
        },
        [60060501] = {
          ContentFR = "Pfiou... toutes ces cellules se ressemblent ! Mais grâce à l’intelligence du petit larbin, on va s’en sortir sans problème.",
          DialogueId = 60060501,
          Duration = 4,
          GUID = "965AEBF2",
          NextDialogue = 60060502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600605/965AEBF2"
        },
        [60060502] = {
          ContentFR = "Dépêche-toi de trouver la cellule où est enfermée la cible ! Sa Majesté le Roi Démon veille au grain.",
          DialogueId = 60060502,
          Duration = 4,
          GUID = "965AEC1C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600605/965AEC1C"
        },
        [60060601] = {
          ContentFR = "N-N’approchez pas... !",
          DialogueId = 60060601,
          Duration = 2.5,
          GUID = "965AFC5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 60060602,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFC5A"
        },
        [60060602] = {
          ContentFR = "N’aie pas peur, nous sommes des Chasseurs de Phoxène. On est là pour te sauver !",
          DialogueId = 60060602,
          Duration = 3,
          GUID = "965AFC84",
          NextDialogue = 60060603,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600606/965AFC84"
        },
        [60060603] = {
          ContentFR = "Hein... ? Oh, je comprends... C’est cette personne qui vous envoie... n’est-ce pas ?",
          DialogueId = 60060603,
          Duration = 4,
          GUID = "965AFCAE",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 60060604,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFCAE"
        },
        [60060604] = {
          ContentFR = "Merci ! Partons vite, j’ai hâte de le revoir...",
          DialogueId = 60060604,
          Duration = 4,
          GUID = "965AFCD8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFCD8"
        },
        [60060701] = {
          ContentFR = "Oh non ! L’un des patrouilleurs a déclenché l’alarme !",
          DialogueId = 60060701,
          Duration = 3,
          GUID = "965B0CC2",
          NextDialogue = 60060702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0CC2"
        },
        [60060702] = {
          ContentFR = "Je le savais ! Ces lâches sont prêts à tout, ils veulent exécuter la cible avant qu’on arrive !",
          DialogueId = 60060702,
          Duration = 4,
          GUID = "965B0CEC",
          NextDialogue = 60060703,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0CEC"
        },
        [60060703] = {
          ContentFR = "On doit la sauver avant qu’il ne soit trop tard !",
          DialogueId = 60060703,
          Duration = 2,
          GUID = "965B0D16",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0D16"
        },
        [60060801] = {
          ContentFR = "J’entends des appels à l’aide ! C’est sûrement la cible !",
          DialogueId = 60060801,
          Duration = 2,
          GUID = "965B1D2A",
          NextDialogue = 60060802,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600608/965B1D2A"
        },
        [60060802] = {
          ContentFR = "Cette cellule-là — c’est la bonne ! Vite, va la sauver !",
          DialogueId = 60060802,
          Duration = 2,
          GUID = "965B1D54",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600608/965B1D54"
        },
        [60060901] = {
          ContentFR = "Je... je ne peux plus bouger... s’il vous plaît... aidez-moi... !",
          DialogueId = 60060901,
          Duration = 3,
          GUID = "965B2D92",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 60060902,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600609/965B2D92"
        },
        [60060902] = {
          ContentFR = "Je ne peux pas... m’effondrer maintenant... pas ici...",
          DialogueId = 60060902,
          Duration = 3,
          GUID = "965B3DFA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600609/965B3DFA"
        },
        [60110101] = {
          ContentFR = "Notre mission consiste à capturer la cible. S’il résiste... on n’aura d’autre choix que de le neutraliser d’abord.",
          DialogueId = 60110101,
          Duration = 4,
          GUID = "967AB572",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601101/967AB572"
        },
        [60110201] = {
          ContentFR = "La cible est à terre ! Attrape-le avant qu’il ne reprenne ses forces et tente de fuir !",
          DialogueId = 60110201,
          Duration = 4,
          GUID = "967AC5DA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601102/967AC5DA"
        },
        [60110301] = {
          ContentFR = "Mission accomplie ! Préparons-nous à quitter les lieux.",
          DialogueId = 60110301,
          Duration = 4,
          GUID = "967AD642",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601103/967AD642"
        },
        [60110501] = {
          ContentFR = "Cette fois, notre cible maîtrise l’art du [Camouflage] : elle peut dissimuler sa présence...",
          DialogueId = 60110501,
          Duration = 4,
          GUID = "967AF712",
          NextDialogue = 60110502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601105/967AF712"
        },
        [60110502] = {
          ContentFR = "... et créer des leurres à son image pour tromper ses adversaires ! Ne te laisse pas berner !",
          DialogueId = 60110502,
          Duration = 4,
          GUID = "967AF73C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601105/967AF73C"
        },
        [60110601] = {
          ContentFR = "Cette fois, notre cible possède un [Instinct du combat] affûté — et transporte un robot de soutien pour renforcer sa puissance !",
          DialogueId = 60110601,
          Duration = 4,
          GUID = "967B077A",
          NextDialogue = 60110602,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601106/967B077A"
        },
        [60110602] = {
          ContentFR = "Attention : son robot explosif peut s’autodétruire à tout moment !",
          DialogueId = 60110602,
          Duration = 4,
          GUID = "967B07A4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601106/967B07A4"
        },
        [60110701] = {
          ContentFR = "Cette fois, notre cible dispose d’un arsenal impressionnant — elle est passée maître en [Assaut armé] ! Reste sur tes gardes, elle pose des mines et frappe brutalement au corps à corps !",
          DialogueId = 60110701,
          Duration = 4,
          GUID = "967B180C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601107/967B180C"
        },
        [60120101] = {
          ContentFR = "Voici la zone à explorer. Laisse-moi trouver un endroit sûr pour installer mon précieux Excavateur.",
          DialogueId = 60120101,
          Duration = 4,
          GUID = "96811E12",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601201/96811E12"
        },
        [60120201] = {
          ContentFR = "L’Excavateur est en place ! Protège-le bien. S’il s’arrête, récupère des Modules d’excavation sur les ennemis.",
          DialogueId = 60120201,
          Duration = 4,
          GUID = "96812E7A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601202/96812E7A"
        },
        [60120301] = {
          ContentFR = "Prospection terminée ! Voici ta récompense. Tu veux continuer à explorer ou faire une pause ?",
          DialogueId = 60120301,
          Duration = 4,
          GUID = "96813EE2",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601203/96813EE2"
        },
        [60120401] = {
          ContentFR = "L’Excavateur est à l’arrêt ! Va chercher quelques Modules d’excavation pour le relancer.",
          DialogueId = 60120401,
          Duration = 4,
          GUID = "96814F4A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601204/96814F4A"
        },
        [60120501] = {
          ContentFR = "Il y a un autre emplacement à inspecter là-bas. Je te l’ai marqué — dès que tu y seras, j’installe un nouvel Excavateur.",
          DialogueId = 60120501,
          Duration = 4,
          GUID = "96815FB2",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601205/96815FB2"
        },
        [60120601] = {
          ContentFR = "Exactement, c’est bien ça ! Ces pièces sont des Modules d’excavation. Installe-les dans mon précieux Excavateur !",
          DialogueId = 60120601,
          Duration = 4,
          GUID = "9681701A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601206/9681701A"
        },
        [60130101] = {
          ContentFR = "Les Déchus ont placé une bombe extrêmement dangereuse ici ! Si on ne la détruit pas, tout le monde est en danger.",
          DialogueId = 60130101,
          Duration = 4,
          GUID = "968786B2",
          NextDialogue = 60130102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968786B2"
        },
        [60130102] = {
          ContentFR = "D’après le commanditaire, trois membres des Déchus sont derrière cette explosion. Je te préviens dès que je repère les autres.",
          DialogueId = 60130102,
          Duration = 4,
          GUID = "968786DC",
          NextDialogue = 60130103,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968786DC"
        },
        [60130103] = {
          ContentFR = "Si on les élimine avant de s’occuper du détonateur « Coup de Grâce », la mission devrait être beaucoup plus simple.",
          DialogueId = 60130103,
          Duration = 4,
          GUID = "968787DE",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968787DE"
        },
        [60130201] = {
          ContentFR = "Un de moins ! D’après les notes qu’il portait... je les ai localisés : les deux autres membres des Déchus sont dans la zone que j’ai marquée.",
          DialogueId = 60130201,
          Duration = 4,
          GUID = "9687971A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601302/9687971A"
        },
        [60130301] = {
          ContentFR = "Le détonateur « Coup de Grâce » est exposé — détruis-le vite !",
          DialogueId = 60130301,
          Duration = 4,
          GUID = "9687A782",
          NextDialogue = 60130302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601303/9687A782"
        },
        [60130302] = {
          ContentFR = "Non mais sérieusement ?! C’est même pas notre bombe, et c’est nous qu’ils attaquent ?!",
          DialogueId = 60130302,
          Duration = 4,
          GUID = "9687A784",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601303/9687A784"
        },
        [60130401] = {
          ContentFR = "On a désamorcé le « Coup de Grâce » ! Vite, on file d’ici !",
          DialogueId = 60130401,
          Duration = 4,
          GUID = "9687B7EA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601304/9687B7EA"
        },
        [60130501] = {
          ContentFR = "J’ai repéré le chef des Déchus !",
          DialogueId = 60130501,
          Duration = 4,
          GUID = "9687C852",
          NextDialogue = 60130502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601305/9687C852"
        },
        [60130502] = {
          ContentFR = "Puisque notre mission consiste à empêcher le « Coup de Grâce » d’exploser, abattre leurs chefs devrait bien nous aider. En avant !",
          DialogueId = 60130502,
          Duration = 4,
          GUID = "9687C87C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601305/9687C87C"
        },
        [60130601] = {
          ContentFR = "Mon chef-d’œuvre... il n’est pas encore achevé...",
          DialogueId = 60130601,
          Duration = 4,
          GUID = "9687C880",
          SpeakNpcId = 200034,
          VoiceName = "voice/$Locale$/story/0/601305/9687C880"
        },
        [60130701] = {
          ContentFR = "Arrogants et aveugles que vous êtes — venez donc, plongez dans la folie !",
          DialogueId = 60130701,
          Duration = 4,
          GUID = "9687C884",
          SpeakNpcId = 200035,
          VoiceName = "voice/$Locale$/story/0/601305/9687C884"
        },
        [60130801] = {
          ContentFR = "... Ainsi donc, c’est moi le jouet ? Amusant. Voyons un peu comment tu comptes échapper à la mort.",
          DialogueId = 60130801,
          Duration = 4,
          GUID = "9687C888",
          SpeakNpcId = 200036,
          VoiceName = "voice/$Locale$/story/0/601305/9687C888"
        },
        [60140001] = {
          ContentFR = "Pff... la lutte pathétique d’une bête acculée.",
          DialogueId = 60140001,
          Duration = 4,
          GUID = "968DDEEA",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_battleStart"
        },
        [60140002] = {
          ContentFR = "Voyons jusqu’où tu peux aller.",
          DialogueId = 60140002,
          Duration = 4,
          GUID = "968DDF14",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_battleEnd"
        },
        [60140003] = {
          ContentFR = "Pas mal... je t’accorde ça. Continue.",
          DialogueId = 60140003,
          Duration = 4,
          GUID = "968DDF3E",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_condemn"
        },
        [60140004] = {
          ContentFR = "Assez joué.",
          DialogueId = 60140004,
          Duration = 4,
          GUID = "968DDF68",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill06"
        },
        [60140005] = {
          ContentFR = "Tremble.",
          DialogueId = 60140005,
          Duration = 4,
          GUID = "968DDF92",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_01"
        },
        [60140006] = {
          ContentFR = "Vermine... tu n’as nulle part où fuir.",
          DialogueId = 60140006,
          Duration = 4,
          GUID = "968DDFBC",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_02"
        },
        [60140201] = {
          ContentFR = "... N’approche... pas... !",
          DialogueId = 60140201,
          Duration = 4,
          GUID = "968DFFBA",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleStart"
        },
        [60140202] = {
          ContentFR = "Oui... je n’ai pas le droit... de vivre...",
          DialogueId = 60140202,
          Duration = 6,
          GUID = "968DFFE4",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageStart"
        },
        [60140203] = {
          ContentFR = "Aaah... !",
          DialogueId = 60140203,
          Duration = 4,
          GUID = "968E000E",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageEnd"
        },
        [60140204] = {
          ContentFR = "Urrrgh... !",
          DialogueId = 60140204,
          Duration = 4,
          GUID = "968E0038",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_Condemn"
        },
        [60140205] = {
          ContentFR = "... Merci...",
          DialogueId = 60140205,
          Duration = 5,
          GUID = "968E0062",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleEnd"
        },
        [60140206] = {
          ContentFR = "... Aaah...",
          DialogueId = 60140206,
          Duration = 2,
          GUID = "968E008C",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill03"
        },
        [60140207] = {
          ContentFR = "... Vite... fuis... !",
          DialogueId = 60140207,
          Duration = 4,
          GUID = "968E00B6",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill10"
        },
        [60140401] = {
          ContentFR = "Mon enfant chéri... merci d’être venue au monde.",
          DialogueId = 60140401,
          Duration = 4,
          GUID = "968E208A",
          VoiceName = "voice/$Locale$/story/1002/101125/968E208A"
        },
        [60140402] = {
          ContentFR = "Tu es la fierté de notre vie.",
          DialogueId = 60140402,
          Duration = 3,
          GUID = "968E20B4",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20B4"
        },
        [60140403] = {
          ContentFR = "Psyche, viens, jurons-le sur nos petits doigts ! Nous serons amies pour la vie !",
          DialogueId = 60140403,
          Duration = 4,
          GUID = "968E20DE",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20DE"
        },
        [60140404] = {
          ContentFR = "Je me souviendrai que tu as vraiment vécu.",
          DialogueId = 60140404,
          Duration = 3,
          GUID = "968E2108",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2108"
        },
        [60140405] = {
          ContentFR = "Nous t’attendrons... jusqu’à ton retour.",
          DialogueId = 60140405,
          Duration = 2.5,
          GUID = "968E2132",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2132"
        },
        [60140406] = {
          ContentFR = "Ô destin, pour une seule fois... aie pitié de moi. Permets que je l’aide à accomplir ce vœu...",
          DialogueId = 60140406,
          Duration = 6,
          GUID = "968E215C",
          VoiceName = "voice/$Locale$/story/1002/101125/968E215C"
        },
        [60140407] = {
          ContentFR = "Prends cette fleur. Elle te portera bonheur.",
          DialogueId = 60140407,
          Duration = 3,
          GUID = "968E2186",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2186"
        },
        [60140408] = {
          ContentFR = "Tu pourras aller sur une petite île, bâtir une maison au bord de la mer, planter autour d’elle des fleurs blanches...",
          DialogueId = 60140408,
          Duration = 6,
          GUID = "968E21B0",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21B0"
        },
        [60140409] = {
          ContentFR = "Psyche, je suis venu te ramener à la maison.",
          DialogueId = 60140409,
          Duration = 3,
          GUID = "968E21DA",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21DA"
        },
        [60140501] = {
          ContentFR = "Tout jugement se prononce... au nom de la Justice.",
          DialogueId = 60140501,
          Duration = 5,
          GUID = "968E30F2",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleStart"
        },
        [60140502] = {
          ContentFR = "Tu oses défier la Loi ?",
          DialogueId = 60140502,
          Duration = 5,
          GUID = "968E311C",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_condemn"
        },
        [60140503] = {
          ContentFR = "Tu... as tenu face aux flammes.",
          DialogueId = 60140503,
          Duration = 5,
          GUID = "968E3146",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleEnd"
        },
        [60140504] = {
          ContentFR = "Alors... qu’as-tu à dire pour ta défense ?",
          DialogueId = 60140504,
          Duration = 5,
          GUID = "968E3170",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_01"
        },
        [60140505] = {
          ContentFR = "Tord-toi donc avant la sentence.",
          DialogueId = 60140505,
          Duration = 5,
          GUID = "968E319A",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_02"
        },
        [60140506] = {
          ContentFR = "Mourir enchaîné... voilà ton sort.",
          DialogueId = 60140506,
          Duration = 5,
          GUID = "968E31C4",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_01"
        },
        [60140507] = {
          ContentFR = "La Loi énumérera tous tes crimes.",
          DialogueId = 60140507,
          Duration = 5,
          GUID = "968E31EE",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_02"
        },
        [60140508] = {
          ContentFR = "Nul n’échappe à la prison de flammes.",
          DialogueId = 60140508,
          Duration = 5,
          GUID = "968E3218",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill03"
        },
        [60149001] = {
          ContentFR = "H-H-H-H-Haut les mains ! Oh, {性别:celui-là|celle-là} a l’air costaud... je m’en vais !",
          DialogueId = 60149001,
          Duration = 5,
          GUID = "9693A37A",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r01"
        },
        [60149002] = {
          Content = "可恶！怎么是你，再再再见。",
          DialogueId = 60149002,
          Duration = 3.8,
          GUID = "9693A3A4",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r02"
        },
        [60149003] = {
          Content = "留留留下买路财！啧，怎么今天一上来就碰到硬茬子，告辞。",
          DialogueId = 60149003,
          Duration = 6.7,
          GUID = "9693A3CE",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r03"
        },
        [60149004] = {
          Content = "除了打劫，逃跑我也是专业的！",
          DialogueId = 60149004,
          Duration = 3.5,
          GUID = "9693A3F8",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill01"
        },
        [60149005] = {
          Content = "舍不得孩子套不着狼，这些都给你，别再追啦！",
          DialogueId = 60149005,
          Duration = 5.1,
          GUID = "9693A422",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill02"
        },
        [60149006] = {
          Content = "咋还在追我啊，这个给你行了吧。",
          DialogueId = 60149006,
          Duration = 3.5,
          GUID = "9693A44C",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill03"
        },
        [60149007] = {
          Content = "你使那么大劲干啥呢！",
          DialogueId = 60149007,
          Duration = 2.5,
          GUID = "9693A476",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01"
        },
        [60149008] = {
          Content = "可恶，以后走夜路小心点！",
          DialogueId = 60149008,
          Duration = 3.2,
          GUID = "9693A4A0",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02"
        },
        [60149009] = {
          Content = "啊啊啊啊啊，我要生气了！",
          DialogueId = 60149009,
          Duration = 3.4,
          GUID = "9693A4CA",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03"
        },
        [60149010] = {
          Content = "笨笨笨蛋，追不上我吧，桀桀桀桀桀桀~",
          DialogueId = 60149010,
          Duration = 6,
          GUID = "9693A4F4",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill04"
        },
        [60149011] = {
          Content = "这次是我大意了，下次我一定要把你打得抱头大哭，呜……",
          DialogueId = 60149011,
          Duration = 10.4,
          GUID = "9693A51E",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_death"
        },
        [60149012] = {
          Content = "东西南北四条街，打听打听谁是爹，道上谁不知道我打劫皎皎的名号！",
          DialogueId = 60149012,
          Duration = 6.9,
          GUID = "9693A548",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r01"
        },
        [60149013] = {
          Content = "跟我斗，你还是太年轻了呀~",
          DialogueId = 60149013,
          Duration = 5.7,
          GUID = "9693A572",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r02"
        },
        [60149014] = {
          Content = "哼，我打打打劫皎皎可不是好惹的。",
          DialogueId = 60149014,
          Duration = 4.8,
          GUID = "9693A59C",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r03"
        },
        [60149015] = {
          Content = "呼，呼……你咋还不累呢，吃啥玩意长大的啊。",
          DialogueId = 60149015,
          Duration = 8.8,
          GUID = "9693A5C6",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r04"
        },
        [60150001] = {
          ContentFR = "Reste loin de moi !",
          DialogueId = 60150001,
          Duration = 3,
          GUID = "9694478A",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack01"
        },
        [60150002] = {
          ContentFR = "Tu l’auras voulu !",
          DialogueId = 60150002,
          Duration = 3,
          GUID = "969447B4",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack02"
        },
        [60150003] = {
          ContentFR = "Je n’en peux plus... je me rends...",
          DialogueId = 60150003,
          Duration = 5,
          GUID = "969447DE",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Die"
        },
        [60150004] = {
          ContentFR = "Arrête ton cirque !",
          DialogueId = 60150004,
          Duration = 3,
          GUID = "96944808",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill01"
        },
        [60150005] = {
          ContentFR = "Arrête de me suivre !",
          DialogueId = 60150005,
          Duration = 3,
          GUID = "96944832",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill02"
        },
        [60150006] = {
          ContentFR = "Vous ne m’aurez pas !",
          DialogueId = 60150006,
          Duration = 4,
          GUID = "9694485C",
          SpeakNpcId = 200053,
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill03"
        },
        [60160001] = {
          Content = "开启锯轮攻击！（待包装）",
          DialogueId = 60160001,
          Duration = 4,
          GUID = "969AB02A",
          SpeakNpcId = 920001
        },
        [60160002] = {
          Content = "持续轰炸目标！（待包装）",
