        },
        [60160005] = {
          Content = "追踪型-炸弹攻击！（待包装）",
          DialogueId = 60160005,
          Duration = 4,
          GUID = "969AB0D2",
          SpeakNpcId = 920001
        },
        [60170001] = {
          ContentFR = "Meurs... MEEEUUURS !",
          DialogueId = 60170001,
          Duration = 1.5,
          GUID = "96A118CA",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01"
        },
        [60170002] = {
          ContentFR = "Raaagh... Urrhh... AAAARGH !",
          DialogueId = 60170002,
          Duration = 1.5,
          GUID = "96A118F4",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill06"
        },
        [60170003] = {
          ContentFR = "GRRRR... RAAH... ROOOAR !",
          DialogueId = 60170003,
          Duration = 4,
          GUID = "96A1191E",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill08"
        },
        [60180001] = {
          Content = "近吾者，必罹天劫！",
          DialogueId = 60180001,
          Duration = 3,
          GUID = "9834E965",
          SpeakNpcId = 240025,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleStart"
        },
        [60180002] = {
          Content = "吼————",
          DialogueId = 60180002,
          Duration = 3,
          GUID = "9834E966",
          SpeakNpcId = 240025,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Condemn"
        },
        [60180003] = {
          Content = "俱往矣……",
          DialogueId = 60180003,
          Duration = 3,
          GUID = "9834E967",
          SpeakNpcId = 240025,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleEnd"
        },
        [60180004] = {
          Content = "晦暝临世。",
          DialogueId = 60180004,
          Duration = 4,
          GUID = "9834E968",
          SpeakNpcId = 240025,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill05"
        },
        [60180005] = {
          Content = "吼————",
          DialogueId = 60180005,
          Duration = 5,
          GUID = "9834E969",
          SpeakNpcId = 240025,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill06"
        },
        [60180006] = {
          Content = "曀曀其阴，虺虺其雷——",
          DialogueId = 60180006,
          Duration = 3,
          GUID = "9834E970",
          SpeakNpcId = 240025,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill07"
        },
        [60200101] = {
          ContentFR = "Zut, on a été repérés par l’ennemi !",
          DialogueId = 60200101,
          Duration = 4,
          GUID = "96B46312",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602001/96B46312"
        },
        [60200201] = {
          ContentFR = "Ennemi repéré ! Empêche-le d’appeler des renforts !",
          DialogueId = 60200201,
          Duration = 4,
          GUID = "96B4737A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602002/96B4737A"
        },
        [60200301] = {
          ContentFR = "Attention, ils vont prévenir leurs alliés ! Si on ne fait rien, ça va très mal tourner.",
          DialogueId = 60200301,
          Duration = 4,
          GUID = "96B483E2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602003/96B483E2"
        },
        [60200401] = {
          ContentFR = "Ils vont appeler du renfort ! Vite, trouve un moyen de les en empêcher !",
          DialogueId = 60200401,
          Duration = 4,
          GUID = "96B4944A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602004/96B4944A"
        },
        [60200501] = {
          ContentFR = "Argh, on s’était si bien cachés ! Tant pis, il va falloir les éliminer rapidement.",
          DialogueId = 60200501,
          Duration = 4,
          GUID = "96B4A4B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602005/96B4A4B2"
        },
        [60210101] = {
          ContentFR = "Le commanditaire n’a pu nous gagner qu’un peu de temps. Allons vite démonter ces trois drôles de machines avant qu’il ne soit trop tard !",
          DialogueId = 60210101,
          Duration = 4,
          GUID = "9687C88C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602101/9687C88C"
        },
        [60210201] = {
          ContentFR = "Youpi ! Tout démonté ! Mission accomplie haut la main !",
          DialogueId = 60210201,
          Duration = 3,
          GUID = "9687C892",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602102/9687C892"
        },
        [60210301] = {
          ContentFR = "Le commanditaire dit que le temps est écoulé — on se replie, vite !",
          DialogueId = 60210301,
          Duration = 3,
          GUID = "9687C896",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602103/9687C896"
        },
        [60220101] = {
          ContentFR = "Hein, quoi ?! La première manche commence déjà !?",
          DialogueId = 60220101,
          Duration = 4,
          GUID = "9687C89A",
          NextDialogue = 60220102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602201/9687C89A"
        },
        [60220102] = {
          ContentFR = "Voyons voir... Oh ! On doit éliminer le champion de l’équipe « Les Déçus » !",
          DialogueId = 60220102,
          Duration = 3,
          GUID = "9687C89E",
          NextDialogue = 60220103,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602201/9687C89E"
        },
        [60220103] = {
          ContentFR = "Mais on ne sait même pas où ils se cachent ! Vite, cherchons des indices !",
          DialogueId = 60220103,
          Duration = 3,
          GUID = "9687C8A2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602201/9687C8A2"
        },
        [60220201] = {
          ContentFR = "Haha ! On a trouvé où il se planque ! Allez, on va le... euh, l’éliminer !",
          DialogueId = 60220201,
          Duration = 3,
          GUID = "9687C8A6",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602202/9687C8A6"
        },
        [60220301] = {
          ContentFR = "La prochaine manche, c’est un combat de territoire ! En avant !",
          DialogueId = 60220301,
          Duration = 3,
          GUID = "9687C8AA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602203/9687C8AA"
        },
        [60220401] = {
          ContentFR = "Chassez-les de la zone désignée ! La victoire sera pour « Le Commandant est le meilleur » !",
          DialogueId = 60220401,
          Duration = 4,
          GUID = "9687C8AE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602204/9687C8AE"
        },
        [60220501] = {
          ContentFR = "L’honneur de la Légion repose sur vos épaules.",
          DialogueId = 60220501,
          Duration = 4,
          GUID = "9687C8B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602205/9687C8B2"
        },
        [60220601] = {
          ContentFR = "Pff... Quelle résistance ! Il est temps de se battre sérieusement.",
          DialogueId = 60220601,
          Duration = 4,
          GUID = "9687C8B6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602206/9687C8B6"
        },
        [60220701] = {
          ContentFR = "Même si nous avons perdu... la prochaine manche sera la nôtre !",
          DialogueId = 60220701,
          Duration = 3,
          GUID = "9687C8BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602207/9687C8BA"
        },
        [60220801] = {
          ContentFR = "Enfin ! Troisième manche ! Vite, au coffre ! On ne va pas laisser quelqu’un d’autre le prendre !",
          DialogueId = 60220801,
          Duration = 4,
          GUID = "9687C8BE",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602208/9687C8BE"
        },
        [60220901] = {
          ContentFR = "Ça y est, ça commence ! Récupère les clés sur ces types et ouvre le coffre final !",
          DialogueId = 60220901,
          Duration = 3,
          GUID = "9687C8C2",
          NextDialogue = 60220902,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C2"
        },
        [60220902] = {
          ContentFR = "Impies ! Comment osez-vous convoiter un trésor béni par les dieux ? Préparez-vous à subir Sa colère !",
          DialogueId = 60220902,
          Duration = 4,
          GUID = "9687C8C4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C4"
        },
        [60221001] = {
          ContentFR = "En avant, fidèles serviteurs ! Récoltez le fruit de la victoire en Son nom !",
          DialogueId = 60221001,
          Duration = 4,
          GUID = "9687C8C6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          VoiceName = "voice/$Locale$/story/0/602210/9687C8C6"
        },
        [60221101] = {
          ContentFR = "Pour la gloire de la Légion ! En avant !",
          DialogueId = 60221101,
          Duration = 4,
          GUID = "9687C8CA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          VoiceName = "voice/$Locale$/story/0/602211/9687C8CA"
        },
        [60221201] = {
          ContentFR = "Comme prévu... la troisième manche est la plus décisive. À nous de briller !",
          DialogueId = 60221201,
          Duration = 4,
          GUID = "9687C8CE",
          SpeakNpcId = 930004,
          VoiceName = "voice/$Locale$/story/0/602212/9687C8CE"
        },
        [60221301] = {
          ContentFR = "Une serrure ouverte ! Continuons, on peut ouvrir les autres !",
          DialogueId = 60221301,
          Duration = 3,
          GUID = "9687C8D2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602213/9687C8D2"
        },
        [60221401] = {
          ContentFR = "Le coffre est ouvert, youpi ! C’est nous les vainqueurs !",
          DialogueId = 60221401,
          Duration = 3,
          GUID = "9687C8D6",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602214/9687C8D6"
        },
        [60221501] = {
          ContentFR = "Regarde, regarde ! L’organisation vient de lancer une nouvelle clé dans l’arène !",
          DialogueId = 60221501,
          Duration = 4,
          GUID = "9687C8DA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602215/9687C8DA"
        },
        [60221601] = {
          ContentFR = "Pour la gloire de la Légion ! En avant !",
          DialogueId = 60221601,
          Duration = 4,
          GUID = "9687C8DE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930005,
          VoiceName = "voice/$Locale$/story/0/602216/9687C8DE"
        },
        [60230101] = {
          ContentFR = "Allez vite, trouve le Poste d’Alchimie !",
          DialogueId = 60230101,
          Duration = 4,
          GUID = "96910001",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602301/96910001"
        },
        [60230201] = {
          ContentFR = "Ah oui, j’y pense ! Pour que le Poste d’Alchimie récupère le Sérum, il faut battre les ennemis juste à côté !",
          DialogueId = 60230201,
          Duration = 4,
          GUID = "96910029",
          NextDialogue = 60230202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602302/96910029"
        },
        [60230202] = {
          ContentFR = "Remplis le Poste d’Alchimie et la mission sera accomplie ! En avant, petit larbin, montre-leur notre grandeur !",
          DialogueId = 60230202,
          Duration = 4,
          GUID = "96910191",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602302/96910191"
        },
        [60230301] = {
          ContentFR = "Chut... J’entends des bruits bizarres... On dirait qu’un gros monstre arrive par ici !",
          DialogueId = 60230301,
          Duration = 4,
          GUID = "96910321",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602303/96910321"
        },
        [60230401] = {
          ContentFR = "Ouaaah ! Un monstre géant fonce sur nous en crachant un brouillard toxique !\nSi on le laisse faire, il va corrompre tout le Sérum dans le Poste d’Alchimie ! Vite, élimine-le !",
          DialogueId = 60230401,
          Duration = 4,
          GUID = "969104B1",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602304/969104B1"
        },
        [60300101] = {
          ContentFR = "Chut... J’ai cru entendre la voix d’un Géniemon ! Allons vite le chercher, il faut le sauver !",
          DialogueId = 60300101,
          Duration = 4,
          GUID = "96F47952",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/603001/96F47952"
        },
