        },
        [70011601] = {
          Camera = "-83.132812,-721.489746,92.419189,0.000006,-0.600217,80.994888,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La porte bloquée coupe désormais tout accès à la mine. À vos oreilles résonne une voix mécanique, glaciale, répétant par bribes l’annonce diffusée lorsque le puits fut scellé...\n« Les veines de Phoxène sont épuisées... À compter de ce jour, le site est déclaré zone abandonnée... Les Éolipyliens n’assureront plus aucune garantie de sécurité... Tout incident survenant lors d’une intrusion non autorisée ne saurait engager notre responsabilité... »",
          DialogueId = 70011601,
          Duration = 5,
          GUID = "AF44464A",
          SpeakNpcId = 102026
        },
        [70011701] = {
          ContentFR = "Une voix mécanique, froide et inflexible, répète sans relâche les instructions de relocalisation édictées par la Légion.\n\n« Les troupes stationnées de la VIᵉ Légion escorteront les mineurs inscrits sur la liste vers la province de Flagson, où ils poursuivront leur labeur. Le convoi ferroviaire partira exactement trois heures avant la fermeture officielle de la Fosse de Glevum.\nLes mineurs concernés sont priés de respecter les consignes suivantes :\n1) Tout bien personnel dépassant cinq kilogrammes : exécution immédiate.\n2) Absence lors de l’embarquement à l’heure fixée : exécution immédiate.\n3) Toute contestation relative à la liste nominative : exécution immédiate. »",
          DialogueId = 70011701,
          Duration = 5,
          GUID = "AF4456B2",
          SpeakNpcId = 102027
        },
        [70011801] = {
          Camera = "-415.066528,-79.582031,152.246094,0.000006,0.599875,-0.799286,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vieille photographie jaunie par les années, immortalisant l’effervescence de l’ouverture des Asphodèles. Citoyens modestes, marchands fortunés et même quelques dignitaires de la cité intérieure s’étaient rassemblés pour offrir leurs vœux à cette jeune taverne.",
          DialogueId = 70011801,
          Duration = 5,
          GUID = "AF44671A",
          SpeakNpcId = 102028
        },
        [70011901] = {
          Camera = "-652.218567,-446.646545,311.657959,0.000055,7.500012,42.603733,10.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une immense affiche, du type que l’on croise partout dans l’Empire, arborant des slogans tels que : « Toute gloire à l’Empereur ».",
          DialogueId = 70011901,
          Duration = 5,
          GUID = "AF447782",
          SpeakNpcId = 102029
        },
        [70012001] = {
          Camera = "251.815674,-114.571671,67.927124,0.000047,-3.399658,170.391632,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« La nouvelle session d’évaluation de la VIᵉ Légion, destinée aux citoyens Charons remplissant les conditions requises, va débuter sous peu.\nLes candidats peuvent se présenter au Bureau de la Sécurité pour déposer leur dossier.\nLe moment est venu de changer votre destin.\nSous la Bannière du Loup Noir, invoquez la puissance de l’Empereur Julius et offrez votre loyauté à l’Empire Hyperboréen !\n\nNotes :\nLes candidates et candidats faisant preuve d’une excellence exceptionnelle recevront la Médaille des Charons Couronnés, ouvrant droit à une résidence dans la cité Intérieure.\nCelles et ceux qui, sans obtenir la Médaille, se distingueront néanmoins par leurs performances seront incorporés parmi les Veilleurs de la cité extérieure.\nL’interprétation finale du règlement relève de la garnison provinciale de Cocytus, VIᵉ Légion.\nToute responsabilité liée aux incidents survenant au cours de l’évaluation incombe au participant. »",
          DialogueId = 70012001,
          Duration = 5,
          GUID = "AF4487EA",
          SpeakNpcId = 102030
        },
        [70012101] = {
          Camera = "-413.806396,24.681641,230.520782,0.000089,-29.19894,-18.408882,35.0,400.0,false,DoNotOverride,2.8",
          ContentFR = "Un conteneur bleu pâle porte l’inscription « Phoxichor ». Ce terme apparaît sur de nombreux dispositifs de transport, d’éclairage et d’énergie à travers l’Empire.\nD’après son nom, il s’agirait d’un dérivé raffiné du Phoxène.",
          DialogueId = 70012101,
          Duration = 5,
          GUID = "AF449852",
          SpeakNpcId = 102031
        },
        [70012201] = {
          Camera = "-829.676514,67.595215,115.704071,0.000047,28.996904,-8.414193,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chaque fois que les aiguilles de l’horloge franchissent le chiffre douze, le nom Todd Wells apparaît fugitivement sur le cadran.\nAssocier ainsi mécanismes ingénieux et optique subtile pour dissimuler une signature témoigne, sans nul doute, du talent d’un horloger d’exception.",
          DialogueId = 70012201,
          Duration = 5,
          GUID = "AF44A8BA",
          SpeakNpcId = 102032
        },
        [70012301] = {
          Camera = "576.424805,22.139282,190.283051,0.000035,-16.800291,175.187546,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "En vous approchant du véhicule, une voix surexcitée vous surprend :\n« Hé, hé, hé ! Vous aussi, vous vous intéressez à ce PRT20A, n’est-ce pas ? Rien d’étonnant ! Nous parlons tout de même d’un modèle civil de seconde génération, dérivé du militaire, doté d’une Roue Phoxynamo... Le fruit d’une sagesse transmise depuis des générations ! Certes, il n’égale pas la vitesse des modèles militaires, mais entendre le grondement de la Roue Phoxynamo d’aussi près, le conduire sur la route... c’est déjà un symbole de prestige ! »\nL’homme poursuit sans reprendre son souffle : histoire du modèle, structure interne, mécanisme de la roue, composition de la carrosserie, jusqu’aux nervures des pneus — rien n’échappe à son bavardage intarissable, qui dure des heures.\nQuand enfin le silence retombe, votre esprit bourdonne encore de termes obscurs sur des cylindres, des rotations et quantité d’autres mécaniques.\nEn levant les yeux pour comprendre pourquoi soudain tout s’est calmé, vous réalisez que le passionné s’est déjà rué vers un autre passant infortuné pour lui infliger à son tour le même discours enflammé.",
          DialogueId = 70012301,
          Duration = 5,
          GUID = "AF44B922",
          SpeakNpcId = 102033
        },
        [70012401] = {
          Camera = "-712.020264,-289.200195,10.626465,0.000082,16.793509,22.182402,10.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un imposant mémorial, dont l’arrière est couvert de noms de citoyens de l’Empire. Sur la face avant, une phrase profondément gravée :\n\n« À la mémoire des soldats qui ont donné leur vie pour offrir à cette terre une paix durable. Toute gloire à l’Empereur. »",
          DialogueId = 70012401,
          Duration = 5,
          GUID = "AF44C98A",
          SpeakNpcId = 102034
        },
        [70012501] = {
          Camera = "-593.807617,-151.208984,181.682983,0.000059,-13.99979,25.798237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas la première fois que vous apercevez des lampes de mineur, des pioches et des wagonnets dans les rues de Givrelac. La quantité même de ces outils annonce la grandeur qu’a jadis connue la cité lorsque l’extraction de Phoxène battait son plein.\nMais les voir abandonnés près des poubelles, recouverts de poussière... il est clair pour quiconque que la gloire des mineurs appartient désormais au passé.",
          DialogueId = 70012501,
          Duration = 5,
          GUID = "AF44D9F2",
          SpeakNpcId = 102035
        },
        [70012601] = {
          Camera = "-429.546875,-25.467529,208.017578,0.000075,25.39749,-29.411985,20.0,100000.0,false,Manual,2.8",
          ContentFR = "L’ombre titanesque de l’usine s’étend sur la cité, telle un géant dominant la foule, enveloppant de sa présence de frêles existences. Chaque jour, des milliers d’ouvriers franchissent ses portes.\nMême à plusieurs centaines de mètres, on perçoit encore le grondement incessant de ce colosse métallique.",
          DialogueId = 70012601,
          Duration = 5,
          GUID = "AF44EA5A",
          SpeakNpcId = 102036
        },
        [70012701] = {
          Camera = "7.69043,-170.557617,63.654785,0.0,0.0,-89.999939,10.0,100000.0,false,DoNotOverride,2.24",
          ContentFR = "Le barrage routier interdit tout passage.\nUn panneau bien visible précise que la zone située au-delà est désormais placée sous l’autorité des Veilleurs de la VIᵉ Légion.",
          DialogueId = 70012701,
          Duration = 5,
          GUID = "AF44FAC2",
          SpeakNpcId = 102037
        },
        [70012801] = {
          Camera = "902.932129,1093.807129,22.332031,0.000012,7.59978,-122.402924,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Une installation de chauffage alimentée au Phoxichor, diffusant une chaleur douce et réconfortante pour quiconque s’assied à proximité.\nSa pose sommaire et son emplacement approximatif laissent supposer l’œuvre d’un habitant non professionnel — l’Empire n’ayant aucune intention de fournir un système de chauffage aux Charons.",
          DialogueId = 70012801,
          Duration = 5,
          GUID = "AF450B2A",
          SpeakNpcId = 102038
        },
        [70012901] = {
          Camera = "538.746094,139.100586,83.406647,0.000042,-10.399529,-172.984406,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des graffitis grossiers, griffonnés à la hâte, saturés d’injures adressées aux Charons.",
          DialogueId = 70012901,
          Duration = 5,
          GUID = "AF451B92",
          SpeakNpcId = 102039
        },
        [70013001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.27",
          ContentFR = "Une tombe minuscule, assez grande pour un petit oiseau.\nLa stèle ne porte aucun nom, seulement l’inscription :\n\n« Ici repose mon compagnon éternel, le héros qui m’a aidé à fuir la mine. — Conon »",
          DialogueId = 70013001,
          Duration = 5,
          GUID = "AF452BFA",
          SpeakNpcId = 102040
        },
        [70013101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.28",
          ContentFR = "Un sac tissé diffusant une lueur jaune pâle. À ses formes anguleuses, on devine qu’il est rempli de Phoxène.\nLa base du sac est maculée de traces de sang séché.",
          DialogueId = 70013101,
          Duration = 5,
          GUID = "AF453C62",
          SpeakNpcId = 102041
        },
        [70013201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.29",
          ContentFR = "Blocs de construction\nDe simples blocs de construction, autrefois très prisés des enfants, mais qui paraissent aujourd’hui dépassés et vieillots.",
          DialogueId = 70013201,
          Duration = 5,
          GUID = "AF454CCA",
          SpeakNpcId = 102042
        },
        [70013301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.30",
          ContentFR = "Chambre de Psyche\nUne planche décorée d’un papillon vert pend à la porte, ornée d’un gribouillage enfantin : « Chambre de Psyche ». C’est ici que la petite Psyche vivait autrefois.\nAujourd’hui, la porte est verrouillée — sans doute une décision de sa mère, Daisy.",
          DialogueId = 70013301,
          Duration = 5,
          GUID = "AF455D32",
          SpeakNpcId = 102043
        },
        [70013401] = {
          Camera = "-274.459961,499.943848,20.897705,0.000001,4.999999,-79.999969,16.0,100000.0,false,Manual,2.8",
          ContentFR = "À travers la vitrine de la boutique des Cent Visages, vous apercevez une robe longue au goût exquis.\nChaque pli, chaque couture est parfaitement ajusté, mettant en valeur la silhouette tout en reflétant l’élégance naturelle de celle qui la porterait.\nUn vêtement taillé sur mesure pour l’élégance naturelle d’Harlan.",
          DialogueId = 70013401,
          Duration = 5,
          GUID = "AF456D9A",
          SpeakNpcId = 102044
        },
        [70013501] = {
          Camera = "36.606445,286.352539,23.979492,0.000003,-8.400025,-108.599854,15.0,100000.0,false,Manual,2.32",
          ContentFR = "Un seau et une serpillière posés près de Lio.\nCes outils sont manifestement destinés à nettoyer les taches rouge sombre à proximité — preuve silencieuse qu’un affrontement sanglant s’est joué ici peu de temps auparavant.",
          DialogueId = 70013501,
          Duration = 5,
          GUID = "AF457E02",
          SpeakNpcId = 102045
        },
        [70013601] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.33",
          ContentFR = "Une vieille affiche jaunie, dont on peine à déchiffrer le contenu :\n\n...\nLe récital de la célèbre chanteuse Violetta commencera dès la semaine prochaine !\nLe classique Né du Blizzard renaît sur scène, et sa voix céleste résonnera dans toute Givrelac !\nUne semaine entière de représentations immanquables ! À ne manquer sous aucun prétexte !\nContre rémunération, possibilité de vous faire entrer clandestinement dans la cité intérieure !\nVenez goûter à une fête musicale réservée à l’élite !\n...\nContact : Monsieur Jack\nPoint de rendez-vous : chaque nuit, à minuit, près de la bouche d’égout.\nCode à transmettre à l’homme roux : « Coucou, coucou ».",
          DialogueId = 70013601,
          Duration = 5,
          GUID = "AF458E6A",
          SpeakNpcId = 102046
        },
        [70013701] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.34",
          ContentFR = "Un manuel scolaire en lambeaux.\nLes espaces vierges ont été recouverts de gribouillages grossiers. On y voit Faye représentée en démon cornue, jetant des sortilèges inquiétants d’un geste de la main.",
          DialogueId = 70013701,
          Duration = 5,
          GUID = "AF459ED2",
          SpeakNpcId = 102047
        },
        [70013801] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.35",
          ContentFR = "On aperçoit parfois, à la Maison d’Hypnos, une femme au visage grave.\nElle passe le balai, prépare un repas chaud pour les enfants, puis s’en va discrètement.\n\nQuand on lui demande pourquoi, elle répond simplement :\n« Monsieur Henrik m’a engagée, alors je fais mon travail. C’est comme ça que va le monde. »\n\nSa voix trahit une lassitude silencieuse — de quoi décourager toute insistance.\n\nMais tous les enfants de la Maison d’Hypnos le savent : Madame Lina n’a jamais accepté le moindre sou de la part de Monsieur Henrik.",
          DialogueId = 70013801,
          Duration = 5,
          GUID = "AF45AF3A",
          SpeakNpcId = 102048
        },
        [70013901] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.36",
          ContentFR = "Un assemblage hétéroclite d’objets abandonnés. Difficile de comprendre les critères de sélection de Martin. Qui pouvaient bien être leurs anciens propriétaires ?",
          DialogueId = 70013901,
          Duration = 5,
          GUID = "AF45BFA2",
          SpeakNpcId = 102049
        },
        [70014001] = {
          Camera = "-394.105225,225.10498,147.011475,0.00004,-19.999113,-46.394775,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des boissons alcoolisées que Camilla a refusé de servir. Impossible de deviner où elles finiront leur route.",
          DialogueId = 70014001,
          Duration = 5,
          GUID = "AF45D00A",
          SpeakNpcId = 102050
        },
        [70014101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.38",
          ContentFR = "Empreintes\nDes empreintes de pas à la taille d’un enfant. Elles doivent être celles qu’a entendues Buck.",
          DialogueId = 70014101,
          Duration = 5,
          GUID = "AF45E072",
          SpeakNpcId = 102051
        },
        [70014201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.39",
          ContentFR = "Popcorn\nOn dirait que le sac du coupable s’est percé d’un minuscule trou, semant du popcorn tout au long de sa fuite.\n« Un parfum de fruits mûrs »... tout s’explique désormais.",
          DialogueId = 70014201,
          Duration = 5,
          GUID = "AF45F0DA",
          SpeakNpcId = 102052
        },
        [70014301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.40",
          ContentFR = "Une petite tente rudimentaire où Belinda vit depuis longtemps.\nElle y tient aussi une sorte de boutique de conseils — sans enseigne, sans domaine clairement défini.\nLes visiteurs qui passent semblent tous porter un secret lourd à confier.",
          DialogueId = 70014301,
          Duration = 5,
          GUID = "AF460142",
          SpeakNpcId = 102053
        },
        [70014401] = {
          Camera = "-277.21875,1095.014038,199.530029,0.000023,24.997671,-88.593628,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une gigantesque grue alimentée au Phoxichor.\nGrâce aux améliorations des Éolipyliens, il n’est plus nécessaire qu’un opérateur soit assis au sommet de la machine : depuis une simple salle de contrôle, une pression sur un levier suffit désormais à manipuler plusieurs grues à la fois, décuplant l’efficacité.\nMais ce progrès a brisé les rêves de nombreux enfants fascinés par ces colosses de métal... et supprimé tout autant de postes pour les ouvriers.",
          DialogueId = 70014401,
          Duration = 5,
          GUID = "AF4611AA",
          SpeakNpcId = 102054
        },
        [70014501] = {
          Camera = "-553.419922,-854.08313,145.091064,0.000012,-2.200284,52.400944,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une foreuse mobile militaire abandonnée, identifié comme modèle PRT05MV.\nLe temps a laissé ses marques : rouille, traces d’usure, peinture écaillée.\nPersonne ne le surveille, personne ne vient le récupérer.\nEst-ce la confiance de l’Empire quant à la sécurité de ses machines... ou la simple crainte de la Légion, qui dissuade tout être vivant d’approcher cette carcasse désertée ?",
          DialogueId = 70014501,
          Duration = 5,
          GUID = "AF462212",
          SpeakNpcId = 102055
        },
        [70014601] = {
          Camera = "18.892578,-214.330688,159.580475,0.000026,-31.400263,99.99868,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un morceau de pain noir moisi, enveloppé dans une vieille feuille de journal.\nLe pain est immangeable, mais en dépliant le papier et en nettoyant la moisissure, on distingue une édition d’il y a plus de dix ans, relatant l’accord conclu entre la VIᵉ Légion et les anciens propriétaires de la Fosse de Glevum.\n...\nDans l’intérêt des mineurs et pour le développement futur de Givrelac, la Fosse de Glevum cesse à partir de ce jour toute exploitation privée. Toutes les opérations seront désormais placées sous la gestion directe de la Légion.\n...\nL’article est accompagné de photographies de la cérémonie.\nPourtant, sur ces clichés en noir et blanc, seuls l’officier brandissant l’accord et les mineurs acclamant sont visibles. Les anciens propriétaires de la Fosse n’apparaissent pas une seule fois — était-ce par refus... ou parce qu’ils n’étaient déjà plus en état d’assister à la scène ?",
          DialogueId = 70014601,
          Duration = 5,
          GUID = "AF46327A",
          SpeakNpcId = 102056
        },
        [70014701] = {
          ContentFR = "Une lettre froissée, à l’évidence imprimée en masse et non écrite à la main :\n\n« Bonjour, citoyens de l’Empire. Je suis Dis Ier, fondateur de l’Empire Hyperboréen, et je vous écris depuis la Capitale Impériale de Dismania.\nOui, vous avez bien lu : je ne suis pas mort. J’ai survécu grâce à des arts occultes.\n\nJe m’apprête à reprendre notre grande campagne contre Élysium.\nMalheureusement, mes fonds de guerre sont actuellement déposés à Givrelac, et mon état m’empêche de m’y rendre.\n\nSi vous avez encore l’honneur et le sang d’un vrai fils de l’Empire, envoyez vos contributions au 233, Avenue du Triomphe, dans la Capitale Impériale.\nJe vous jure que lorsque j’aurai retrouvé mes forces et récupéré l’intégralité des fonds militaires, je vous rembourserai le double.\n\nSouvenez-vous : la guerre est imminente. N’attendez pas !\nJe compte sur votre soutien. Lorsque le moment viendra, je reviendrai tel l’éclair ! »\n\n(Une arnaque grossière, manifestement destinée aux crédules.)",
          DialogueId = 70014701,
          Duration = 5,
          GUID = "AF4642E2",
          SpeakNpcId = 102057
        },
        [70014801] = {
          Camera = "-233.383423,129.945312,39.479553,0.000071,26.799578,-19.787138,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une boisson fermentée nommée Contes de Givrelac. Un simple tour de valve suffit à remplir son verre. Sa teinte rappelle le Phoxène ; son premier goût, mentholé, évoque la brise glacée du lac.\nEn descendant, elle révèle une douceur miellée, comme l’éclat jadis glorieux de l’industrie minière.\nPuis vient l’amertume tourbée, profonde, persistante — une saveur qui s’accroche à l’âme.\n(Contes de Givrelac porte bien son nom. Pas étonnant qu’elle soit la boisson la plus prisée aux Asphodèles.)",
          DialogueId = 70014801,
          Duration = 5,
          GUID = "AF46534A",
          SpeakNpcId = 102058
        },
        [70014901] = {
          Camera = "144.133301,295.799561,71.270615,0.000111,5.599437,-116.392715,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un mécanisme d’engrenages d’une finesse remarquable.\nPeu importe sa rotation, rien ne semble changer dans les Asphodèles, mais les légers cliquetis provenant de l’arrière du comptoir révèlent que ce dispositif n’a rien d’une simple décoration.",
          DialogueId = 70014901,
          Duration = 5,
          GUID = "AF4663B2",
          NextDialogue = 70014902,
          SpeakNpcId = 102059
        },
        [70014902] = {
          ContentFR = "Comme Camilla le disait si bien :\n« Pour une poignée de pièces, un marchand monterait volontiers à l’échafaud. »\nLes Asphodèles ne se résument peut-être pas à une modeste échoppe vendant des boissons fermentées...",
          DialogueId = 70014902,
          GUID = "AF4663B3",
          SpeakNpcId = 102059
        },
        [70015001] = {
          Camera = "267.163086,229.933594,218.354156,0.000008,-28.000093,-144.996719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un des nombreux usages de la technologie à base de Phoxène dans la vie quotidienne des citoyens de l’Empire.\nBien que la puissance d’éclairage reste moyenne, sa faible consommation, son coût réduit et sa longue durée de vie en ont fait la lampe la plus couramment utilisée à Givrelac.\nLa VIᵉ Légion en avait également installé un grand nombre lors de l’agrandissement de la Fosse de Glevum.",
          DialogueId = 70015001,
          Duration = 5,
          GUID = "AF46741A",
          SpeakNpcId = 102060
        },
        [70015101] = {
          Camera = "-293.902832,-246.538574,58.947754,0.000011,22.198734,42.000011,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Un encadrement on ne peut plus banal, typique de l’Empire. Pourtant, en fixant ces deux petits carrés, impossible de ne pas y voir un visage grimaçant qui semble dire :\n« Quoi ?! Qu’est-ce que tu regardes, toi ?! »",
          DialogueId = 70015101,
          Duration = 5,
          GUID = "AF46741B",
          SpeakNpcId = 102061
        },
        [70015201] = {
          ContentFR = "Des ossements, des armes et des provisions à moitié consommées, écrasés sous une pile de sacs usés — vestiges muets des Chasseurs de Phoxène disparus au fond de la mine abandonnée.\nVieilles ou neuves, ces besaces appartenaient à ceux qui étaient venus avec le même rêve : ressortir riches et victorieux.\nTous ont finalement trouvé la même fin misérable.",
          DialogueId = 70015201,
          GUID = "AF4694EA"
        },
        [70015301] = {
          ContentFR = "Leur journal, froissé, et les morceaux de Phoxène ternis racontent une autre histoire : s’il leur avait été accordé un peu plus de temps... peut-être leur avenir aurait-il été tout autre.",
          DialogueId = 70015301,
          GUID = "AF46A552"
        },
        [70015401] = {
          ContentFR = "Un faux Écho de Givrelac gît dans une poubelle — une contrefaçon évidente, truffée d’erreurs d’impression.\nEn l’ouvrant, on tombe sur une succession d’histoires sensationnalistes :",
          DialogueId = 70015401,
          Duration = 5,
          GUID = "AF46B5BA",
          NextDialogue = 70015402,
          SpeakNpcId = 102064
        },
        [70015402] = {
          ContentFR = "Les Secrets de Morris Glenville\n\nTout le monde connaît l’ascension fulgurante — puis la chute brutale — des Glenville : le jeune Morris, né dans la pauvreté, devenu magnat de l’acier, avant que la famille ne soit frappée par la folie, les morts accidentelles et les disparitions. Mais posons une autre question : pourquoi Morris tenait-il tant à conserver le souvenir de ses origines misérables ?",
          DialogueId = 70015402,
          Duration = 5,
          GUID = "AF46B5E4",
          NextDialogue = 70015403,
          SpeakNpcId = 102064
        },
        [70015403] = {
          ContentFR = "Peu savent que sa première fortune, Morris la gagna adolescent, sous les ordres d’un haut responsable des Éolipyliens — un Charon Couronné.\nSachant qu’il deviendrait plus tard un farouche anti-Charon, on peut se demander : quel secret enfoui reliait donc Morris à cet ancien supérieur ?",
          DialogueId = 70015403,
          Duration = 5,
          GUID = "AF46B60E",
          NextDialogue = 70015404,
          SpeakNpcId = 102064
        },
        [70015404] = {
          ContentFR = "Incroyable ! L’Empereur Julius est-il... un imposteur ?!?\nLes archives et les témoins de l’époque décrivent tous le prince Julius, avant son couronnement, comme un homme calme, courtois, d’une élégance discrète.\nPourquoi, alors, un changement si radical une fois devenu Empereur ?\nIl n’existe qu’une seule explication : le véritable Julius a été assassiné — et celui qui siège aujourd’hui au Palais de Bellona n’est qu’un usurpateur !",
          DialogueId = 70015404,
          Duration = 5,
          GUID = "AF46B638",
          NextDialogue = 70015405,
          SpeakNpcId = 102064
        },
        [70015405] = {
          ContentFR = "Un frisson vous parcourt : vous en avez déjà trop lu. Vous remettez aussitôt le faux journal dans la poubelle.",
          DialogueId = 70015405,
          Duration = 5,
          GUID = "AF46B662",
          SpeakNpcId = 102064
        },
        [70015501] = {
          Camera = "382.455078,-10.461182,127.896484,0.000083,-5.801112,-108.595062,30.0,96.67099,false,Manual,4.0",
          ContentFR = "Une photo prise il y a plus de dix ans. Le verre du cadre est couvert de traces de doigts.\nOn y voit une jeune Charon souriante, les cheveux caressés par le vent.\nAu dos, une inscription à l’encre :\n« Ma fille — Hayley. Prise à Rougerive. »\nElle ne ressemble pas vraiment à Psyche, et pourtant... son sourire limpide évoque irrésistiblement son souvenir.",
          DialogueId = 70015501,
          Duration = 5,
          GUID = "AF46C622"
        },
        [70015601] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentFR = "Sur la couverture épaisse du journal, une simple phrase : « Que leurs âmes reposent dans la Mer du Silence. »\nEn l’ouvrant, vous trouvez pages après pages des dates et des noms... terriblement familiers.",
          DialogueId = 70015601,
          Duration = 5,
          GUID = "AF46D68A",
          NextDialogue = 70015602
        },
        [70015602] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentFR = "...\n3 septembre, Carolina Brown.\n...\n29 octobre, Hunt Clark.\n...\n25 novembre, Psyche Frey.",
          DialogueId = 70015602,
          Duration = 5,
          GUID = "AF46D6B4"
        },
        [70015701] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentFR = "Un cristal semblable au Phoxène — du moins, de loin.\nDe près, ses veines et sa texture ne trompent pas : juste une simple pierre lumineuse, sans valeur.",
          DialogueId = 70015701,
          Duration = 5,
          GUID = "AF46E6F2",
          NextDialogue = 70015702
        },
        [70015702] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentFR = "L’humanité classe les minerais selon leur utilité. Le Phoxène est précieux ; ces pierres-là, méprisées.\nC’est ainsi que le Phoxène a été extrait, brisé, broyé, raffiné jusqu’à devenir du Phoxichor glacé dans les usines rugissantes — tandis que ces petites pierres sans importance sont restées intactes, préservées par leur inutilité même.",
          DialogueId = 70015702,
          Duration = 5,
          GUID = "AF46E71C"
        },
        [70015801] = {
          Camera = "492.773438,-508.054688,926.297363,0.000004,-0.000096,143.197693,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "码头四处可见的大型起重装置。不同于帝国常见的铆钉与金属交织而成的冰冷风格，华胥的装置多以木制榫卯结构为主。细看其底座上刻着一行小字：天梁司制造。",
          DialogueId = 70015801,
          Duration = 5,
          GUID = "AF46F75A"
        },
        [70015901] = {
          Camera = "-447.582031,-536.535156,268.742676,0.000001,5.399906,55.198711,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "损毁的上古机傀，在岁月的摧折中早已失去了原始功能。其零件如今随意地散落在烟津渡的各处，被茂盛生长的草木掩盖。",
          DialogueId = 70015901,
          Duration = 5,
          GUID = "AF4707C2"
        },
        [70016001] = {
          Content = "<H>银烛狂欢</>将在盖雷亚剧院如期举行，请参与者自行准备你心仪的装扮，选择你要扮演的身份。\n让我们放下职业、放下种族、放下冲突相聚在于此，沐浴在皇帝的恩典之下，齐声赞颂皇帝的仁德，荣耀尽归吾皇！",
          DialogueId = 70016001,
          GUID = "AF47182A"
        },
        [70016002] = {
          Content = "厚厚的点名册，详细地记录了每位工作人员一天的行程，除了排练，连吃饭睡觉和如厕的行程都被记录在内。\n不知是剧团长狠心地将所有人“软禁”在剧院之内，还是剧团长为了保护自己的演员，而不得不时刻关注每个人的动向。",
          DialogueId = 70016002,
          GUID = "AF471854"
        },
        [70016003] = {
          Content = "帝皇尾戒勋章，完全由纯金打造，只会颁发给为帝国做出卓越贡献的军人。\n\n科赛托斯行省冰湖城第六军团下属卫戍部队，<H>黎瑟·费西尔</>。\n在连年、数次<H>清缴秽兽作战</>中，决策果断，作战英勇，收尾迅速。\n在维护地区治安的过程中起到了无可比拟的关键作用。\n现经军团评估，以吾皇尤里乌斯之名，授予黎瑟·费西尔帝皇尾戒勋章及准尉军衔，望广大军人以其为榜样，奋发上进，共同成长。\n荣耀尽归吾皇。",
          DialogueId = 70016003,
          GUID = "AF47187E"
        },
        [70016004] = {
          Content = "压在一堆杂物下的老旧报纸，记录着很久以前的悲惨事故。\n\n<H>秽蚀者异常凶险，不要被表象欺骗！</>\n9月24日，本市发生一起极为恶劣的“秽蚀”事件，经第六军团卫戍部队调查后，得出以下结论：\n冰湖城市民费西尔夫妇于9月13日在泪湖畔公路边上偶遇一名叫做罗比·布朗的青年。因其身受重伤，费西尔夫妇将其带回家中照料。\n然而，罗比·布朗是一名秽蚀者，他躲过了帝国对潜在秽蚀者的例行盘查并潜逃至城外，且在接受费西尔夫妇帮助时，刻意掩盖了自己的秽蚀痕迹。十日后，悲剧发生：布朗蜕变成为秽兽，杀死了包括费西尔夫妇在内数十名居住在冰湖城南区的市民。第六军团下属冰湖城卫戍部队紧急出动才平息此次骚乱。\n骚乱共造成18人死亡，其中包含3名索拉之民；另有34人受伤。在此提醒各位市民谨记，不要轻易收留身份不明的卡戎之民，一旦发现秽蚀者，立即上报治安署。它们永远只是人类的敌人，无一例外。如有刻意包庇秽蚀者、隐瞒不报者，一律按照《海伯利亚刑事法典》第54条规定，处以死刑。",
          DialogueId = 70016004,
          GUID = "AF4718A8"
        },
        [70016005] = {
          Content = "系着歪扭蝴蝶结的朴素礼盒，礼盒边是一瓶帝国最顶尖的止痛剂，和一封不知是什么原因没被塞入礼盒的纸条，上面写着“希望你能早日康复”。",
          DialogueId = 70016005,
          GUID = "AF4718D2"
        },
        [70016006] = {
          Camera = "-35.015625,151.625,225.035156,0.000034,-14.798724,-71.592674,35.0,100000.0,false,Manual,22.0",
          Content = "（内城城墙下姐弟的合照，照片的右上角写着“黎瑟·费西尔”与“布鲁斯·费西尔”两个名字，还有庆祝弟弟布鲁斯通过第六军团考核的祝语。）",
          DialogueId = 70016006,
          GUID = "AF4718FC"
        },
        [70016007] = {
          Camera = "36.316406,112.411133,226.279297,0.00002,-31.198172,-98.592926,35.0,100000.0,false,Manual,22.0",
          Content = "（看起来很久没使用过的口琴，比起黎瑟的爱好，更像某种礼物。）",
          DialogueId = 70016007,
          GUID = "AF471926"
        },
        [70016008] = {
          Content = "石灰墙的一角用小刀刻满了密密麻麻的字，有的歪歪扭扭，似是孩童的字迹；有些已经成熟，像是成年人所写。这些字都是同一句话：\n“我不会再看着任何人被秽兽杀死。”",
          DialogueId = 70016008,
          GUID = "AF471950"
        },
        [70016009] = {
          Content = "多位幕后人员记录的道具筹备单，详细记录着盖雷亚剧院近半个月所有道具的出入情况。\n\n10月08日，服装、睡袋筹备完成，确认人：蒙德里（批注：食物储备不足，<H>为了接下来为期一个月的集中排练，得托人再送一批进来</>）\n…………\n11月12日，新麦克风3只替换完成，确认人：格林德（批注：有一只麦克风声音巨响，普奇剧团长说这样就好，不做更换。）\n11月14日，红色幕布替换完成，金色幕布已收回仓库。确认人：贝尔\n…………\n11月24日，丢失的5顶假发回收完成，确认人：贝尔（批注：更衣室的角落容易藏东西，我今天去把那清空一下。）\n11月25日，花冠15顶筹备完成，马靴9双筹备完成，确认人：蒙德里",
          DialogueId = 70016009,
          GUID = "AF47197A"
        },
        [70016010] = {
          Content = "与剧院帷幕材质十分接近的布料，虽然老旧但十分整洁，显然经过什么人的认真打理。\n仔细观察和触摸会发现，和袭击现场发现的帷幕是同一块布料。",
          DialogueId = 70016010,
          GUID = "AF4719A4"
        },
        [70016011] = {
          Content = "假人模型虽然很旧，但造型和姿势明显经过了精心设计，看起来端庄而优雅。",
          DialogueId = 70016011,
          GUID = "AF4719CE"
        },
        [70016012] = {
          Content = "四周遍布着巨大而凌乱的爪痕，就算这里不是怪物的藏身处，也一定是怪物经常活动的地方。想必这就是十三军团将此处列为封锁区域的原因之一。",
          DialogueId = 70016012,
          GUID = "AF4719F8"
        },
        [70016013] = {
          ContentFR = "Un fragment de la complexe cartographie des égouts de Givrelac reliant les différents quartiers de la cité. De vastes sections sont marquées d’un avertissement : \n« Interdit d’entrer sans autorisation des Veilleurs. »",
          DialogueId = 70016013,
          GUID = "AF471A22"
        },
        [70016101] = {
          Camera = "-15.959961,1605.265137,1322.948242,0.000059,-29.399687,-89.596825,20.875948,100000.0,false,Manual,22.0",
          Content = "（恢复炮台运输装置的供能，需要连通四根缆线。）",
          DialogueId = 70016101,
          GUID = "AF472892",
          NextDialogue = 70016102
        },
        [70016102] = {
          Camera = "224.294922,655.639038,672.151611,0.000109,-27.999538,-125.796112,20.875948,100000.0,false,Manual,22.0",
          Content = "（一根已经处于连通状态。）",
          DialogueId = 70016102,
          GUID = "AF4728BC",
          NextDialogue = 70016103
        },
        [70016103] = {
          Camera = "-1774.869141,-1374.734619,1171.844727,0.000131,-33.399078,23.004192,20.875948,100000.0,false,Manual,22.0",
          Content = "（还需要连通另外三根缆线，顺着它们找到髓动轮吧。）",
          DialogueId = 70016103,
          GUID = "AF4728E6"
        },
        [70016104] = {
          Camera = "-5344.007812,-255.292114,647.478394,0.000156,-14.998623,83.199738,20.875948,100000.0,false,Manual,22.0",
          Content = "（这是<H>一组</>髓动轮，且似乎需要在<H>特定时间</>内完成激活。）",
          DialogueId = 70016104,
          GUID = "AF472910"
        },
        [70016105] = {
          Camera = "5543.811523,-2108.574219,180.364319,0.000151,-3.998317,-104.994102,20.875948,100000.0,false,Manual,22.0",
          Content = "（似乎无法进入，有没有什么办法可以从<H>远处</>激活髓动轮呢？）",
          DialogueId = 70016105,
          GUID = "AF47293A"
        },
        [70016106] = {
          Camera = "157.341797,-91.314453,242.558594,0.0,-60.19952,101.398407,16.122608,100000.0,false,Manual,22.0",
          Content = "（这是一张陌生的脸。）",
          DialogueId = 70016106,
          GUID = "AF472964"
        },
        [70016107] = {
          Camera = "-71.794922,628.722656,135.195312,0.000076,12.199674,-90.596268,17.78793,100000.0,false,Manual,22.0",
          ContentFR = "※ Témoignage de Calem (unité des Narvals)\n« J’ai vu {性别2:le|la} Capitaine {nickname2} des Griffons sortir {性别2:seul|seule} de ████, le torse couvert de ████. »\n\n« {性别2:Il|Elle} nous a ordonné de rester en position, affirmant qu’{性别2:il|elle} allait vérifier ████ pour repérer d’éventuels Déchus cachés. »\n\n« Deux minutes plus tard, l’alarme s’est déclenchée. La Capitaine Falsi et moi avons accouru : le Capitaine Avar des Loups Blancs gisait dans une mare de sang. ████ était déjà enclenché. »",
          DialogueId = 70016107,
          GUID = "AF47298E"
        },
        [70016108] = {
          ContentFR = "Aucun signe de vie parmi les soldats.",
          DialogueId = 70016108,
          GUID = "AF4729B8"
        },
        [70016109] = {
          ContentFR = "Des carcasses de Souillés jonchent le sol — ce sont ces créatures qui ont fauché la jeunesse des soldats. Mais, jusqu’à leur dernier souffle, ces derniers ont riposté : leurs balles mortelles ont percé les monstres qui les ont emportés.",
          DialogueId = 70016109,
          GUID = "AF4729E2"
        },
        [70016110] = {
          Camera = "129.879883,311.569336,152.664062,0.000072,3.399556,-2.996889,17.78793,100000.0,false,Manual,22.0",
          ContentFR = "※ Enquête sur les origines de {nickname2}\n{nickname2} a été {性别2:identifié comme l’un des survivants|identifiée comme l’une des survivantes} du ████, survenu il y a trois ans lors de ████.\n\nD’après ses propres déclarations, {nickname2} souffre d’amnésie partielle, bien que ses facultés cognitives demeurent intactes et son jugement, stable.\n\nIl est à noter que, selon les témoignages d’autres rescapés, {nickname2} ne figurait pas sur la liste des passagers enregistrés à ████. Autrement dit, <H>{性别2:il était bel et bien un "passager fantôme"|elle était bel et bien une "passagère fantôme"}</>.\n\nÀ l’époque, la XIIIᵉ Légion mena une enquête approfondie sur son identité sans parvenir à l’authentifier, tout en écartant définitivement l’hypothèse ████.\n\nL’explication la plus plausible suggère {性别2:qu’il aurait été un civil local|qu’elle aurait été une civile locale} ayant cherché refuge dans ████ pour échapper aux bombardements, subissant alors un traumatisme crânien responsable de sa perte de mémoire.",
          DialogueId = 70016110,
          GUID = "AF47298F"
        },
        [70016111] = {
          Content = "用石块垒起的石堆，旁边放着一束白花，看起来似乎有着某种纪念意义。仔细看的话，有一块石头上似乎浅浅刻着一个“H”开头的名字，但已经难以辨认。",
          DialogueId = 70016111,
          GUID = "AF4729E3"
        },
        [70016201] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "记载大风九章诫律的大型石碑，用意为警醒世人。碑上所刻的诫律，在华胥境内请务必遵守。",
          DialogueId = 70016201,
          Duration = 5,
          GUID = "AF4738FA",
          NextDialogue = 70016202
        },
        [70016202] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "天地大德，其名为生。戕身害命，不可为也。\n夫人根基，定文为信。毁约背盟，不可为也。\n著真去伪，赤心为诚。妄言欺众，不可为也。",
          DialogueId = 70016202,
          Duration = 5,
          GUID = "AF473924",
          NextDialogue = 70016203
        },
        [70016203] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "卑以自牧，束己为谦。骄狂跋扈，不可为也。\n尊贤友客，守序为礼。放诞无忌，不可为也。\n以我及人，制宜为义。恃强凌弱，不可为也。",
          DialogueId = 70016203,
          Duration = 5,
          GUID = "AF47394E",
          NextDialogue = 70016204
        },
        [70016204] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "清心敛行，身正为廉。枉法贪酷，不可为也。\n裁辨是非，知之为明。淆乱颠倒，不可为也。\n垂聆天宪，恭肃为敬。离经叛道，不可为也。",
          DialogueId = 70016204,
          Duration = 5,
          GUID = "AF473978"
        },
        [70016301] = {
          Camera = "11.238281,-188.23291,625.148438,0.000004,-3.799989,-98.400398,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "华胥人的精神信仰——白龙神君太皓的塑像。",
          DialogueId = 70016301,
          Duration = 5,
          GUID = "AF474962",
          NextDialogue = 70016302
        },
        [70016302] = {
          Camera = "11.238281,-188.23291,625.148438,0.000004,-3.799989,-98.400398,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "这尊塑像龙首昂扬，伫立在百年春外的河滩之中，静静守护着这方净土。它起到的作用似乎不仅为精神寄托。据说当危机来临时，白龙神君能借助这尊塑像现身，回应人们的祈祷，荡清一切邪恶。",
          DialogueId = 70016302,
          Duration = 5,
          GUID = "AF47498C"
        },
        [70016401] = {
          Camera = "2886.273438,2012.956055,3502.893555,0.000015,5.199823,-141.799973,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "远看似乎是一尊明月高悬于百年春背面，近看才能发现其上独属于机械装置的纹路，随之而来的是馥郁袭人的香气。",
          DialogueId = 70016401,
          Duration = 5,
          GUID = "AF4759CA",
          NextDialogue = 70016402
        },
        [70016402] = {
          Camera = "2886.273438,2012.956055,3502.893555,0.000015,5.199823,-141.799973,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "这轮“明月”集悬衡机枢二派技术之大成，实为烟津渡区域的香料动力装置。香在这个装置内挥发，被鼓动吹往四方，维持着大风九章的秩序。",
          DialogueId = 70016402,
          Duration = 5,
          GUID = "AF4759F4"
        },
        [70016501] = {
          Camera = "29.942383,-19.513672,525.364014,0.000019,28.799376,-80.196136,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "不见天日的潮声岩穴反而能催生出大型的发光植物，这就是生命对于光明的永恒向往吗？",
          DialogueId = 70016501,
          Duration = 5,
          GUID = "AF476A32",
          NextDialogue = 70016502
        },
        [70016502] = {
          Camera = "29.942383,-19.513672,525.364014,0.000019,28.799376,-80.196136,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "它悬于岩顶，将皎洁而微弱的光辉洒往洞穴中，为偶尔路过的行人提供前路的指引。",
          DialogueId = 70016502,
          Duration = 5,
          GUID = "AF476A5C"
        },
        [70016601] = {
          Camera = "745.375,17.552734,2003.395996,0.000002,7.399881,175.19902,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "搁浅于微茫市的大型沉船，外表看上去已腐朽废弃，毫无生气，其内却别有洞天。被此处的主人虬先生改造为自己的居所，名为“潜龙居”。",
          DialogueId = 70016601,
          Duration = 5,
          GUID = "AF477A9A"
        },
        [70016701] = {
          Camera = "909.160156,-79.808594,2942.352051,0.000001,-4.80014,-178.998611,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "岁月能摧折大部分事物，使其失去原本功能，但显然有一些永恒的造物能够超越时间。",
          DialogueId = 70016701,
          Duration = 5,
          GUID = "AF478B02",
          NextDialogue = 70016702
        },
        [70016702] = {
          Camera = "909.160156,-79.808594,2942.352051,0.000001,-4.80014,-178.998611,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "机枢派的研究重地被毁数百年后，此地的机括战阵核心依然悬于听鸦原的上空，抵御着一切外来入侵者——纵使它的创造者早已泯于历史的尘埃之中。",
          DialogueId = 70016702,
          Duration = 5,
          GUID = "AF478B2C"
        },
        [70016801] = {
          Camera = "1339.019531,976.865234,1511.71582,0.000001,3.999799,-138.800369,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "尘漠石海中部的香塔，建于上一次烛阴之灾期间，曾用于净化局部空气，延缓尘漠蔓延的速度。",
          DialogueId = 70016801,
          Duration = 5,
          GUID = "AF479B6A",
          NextDialogue = 70016802
        },
        [70016802] = {
          Camera = "1339.019531,976.865234,1511.71582,0.000001,3.999799,-138.800369,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "以其倒塌在这片荒漠中的现状，结局已不明自言。",
          DialogueId = 70016802,
          Duration = 5,
          GUID = "AF479B94"
        },
        [70016901] = {
          Camera = "-970.289062,2657.070312,1862.426758,0.000044,17.199194,-63.00082,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "曾经生长于此地的巨树，受烛阴之灾的殃及，其树表如今已被厚厚一层结晶化的尘漠所覆盖。",
          DialogueId = 70016901,
          Duration = 5,
          GUID = "AF47ABD2",
          NextDialogue = 70016902
        },
        [70016902] = {
          Camera = "-970.289062,2657.070312,1862.426758,0.000044,17.199194,-63.00082,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "它的生命永远停滞在了这个时刻，枝叶也不再舒张，以无声的沉默警告一切活物不要踏入此地。",
          DialogueId = 70016902,
          Duration = 5,
          GUID = "AF47ABFC"
        },
        [70017001] = {
          Camera = "-194.170898,571.792969,277.285156,0.000037,16.40015,-66.80262,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "曾用于驱逐烛阴的祭坛。受烛阴泄漏而出力量的影响，扭曲的蜃影在此处久久不散。烛阴的悲鸣和吼叫如同幻痛般印刻在每个到访者的心灵之中。",
          DialogueId = 70017001,
          Duration = 5,
          GUID = "AF47BC3A"
        },
        [70017101] = {
          Camera = "233.236328,49.142578,328.026367,0.000006,-47.99913,-169.796097,35.0,404.294037,false,DoNotOverride,2.8",
          Content = "散落于桌上的医学笔记，纸张看起来有些年头，显然被人翻阅过多次。纸张的空白处以蝇头小字密密麻麻地写满了批注。仔细看可以发现字迹分属二人，较新字迹的归属人似乎是药理的初学者。",
          DialogueId = 70017101,
          Duration = 5,
          GUID = "AF47CCA2",
          NextDialogue = 70017102
        },
        [70017102] = {
          Camera = "233.236328,49.142578,328.026367,0.000006,-47.99913,-169.796097,35.0,404.294037,false,DoNotOverride,2.8",
          Content = "笔记的落款处以娟秀的字迹写着“扶风”二字。",
          DialogueId = 70017102,
          Duration = 5,
          GUID = "AF47CCCC"
        },
        [70017201] = {
          Camera = "-86.421875,207.039062,257.314453,0.000016,-39.599575,-81.797188,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "枯荣阁外面对庭院露天放置的古筝。只要看到这幅景象，就能想象出此间主人午后在这里抚一首琴曲，清风拂面的雅致。",
          DialogueId = 70017201,
          Duration = 5,
          GUID = "AF47DD0A"
        },
        [70017301] = {
          Camera = "-356.626953,463.605469,232.6875,0.000018,-4.400076,-38.39875,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "装有多格药草的药柜，似乎很少被使用。苦涩的气味十分冲脑醒神。",
          DialogueId = 70017301,
          Duration = 5,
          GUID = "AF47ED72"
        },
        [70017401] = {
          Camera = "-423.304688,2.398438,413.355469,0.000008,-43.799706,9.802094,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "供病人休憩的床铺，洁净无尘，被褥被一丝不苟地叠放好。靠近后能闻到一股似有若无的香气，与此间主人的气质非常相称。",
          DialogueId = 70017401,
          Duration = 5,
          GUID = "AF47FDDA"
        },
        [70017501] = {
          Camera = "641.003906,-32.821289,236.93042,0.0,-0.200043,179.599518,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "小巧的祠台，是华胥人用于悼念逝去亲人，供奉小小祭品的去处。",
          DialogueId = 70017501,
          Duration = 5,
          GUID = "AF480E42",
          NextDialogue = 70017502
        },
        [70017502] = {
          Camera = "641.003906,-32.821289,236.93042,0.0,-0.200043,179.599518,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "在他们看不见的角落，无由生早已大大方方地入住了这里——这份怀有对亲人思念的祭品，就由我们代为收下吧。",
          DialogueId = 70017502,
          Duration = 5,
          GUID = "AF480E6C"
        },
        [71000000] = {
          ContentFR = "Miaou...",
          DialogueId = 71000000,
          Duration = 3,
          GUID = "B1BDB580",
          SpeakNpcId = 800002
        },
        [71000100] = {
          ContentFR = "Un chat errant miaule tristement, comme s’il cherchait à attirer l’attention d’une âme charitable.",
          DialogueId = 71000100,
          GUID = "B1BDC5E8",
          SpeakNpcId = 800006
        },
        [71000200] = {
          ContentFR = "Excusez-moi, vous vendez de la nourriture pour chat ?",
          DialogueId = 71000200,
          GUID = "B1BDD650",
          NextDialogue = 710002001,
          SpeakNpcId = 100001
        },
        [71000210] = {
          ContentFR = "Excusez-moi, vous auriez de la nourriture pour chat ?  ",
          DialogueId = 71000210,
          GUID = "B1BDD7F4",
          NextDialogue = 710002101,
          SpeakNpcId = 100001
        },
        [71000220] = {
          ContentFR = "Vous disposez la nourriture devant le chat.",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001
        },
        [71000300] = {
          ContentFR = "Le chat bondit, s’éloigne de quelques pas, puis s’arrête pour vous regarder, comme s’il vous invitait à le suivre.",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006
        },
        [71000310] = {
          ContentFR = "Le chat bondit, s’éloigne de quelques pas, puis s’arrête pour vous regarder, comme s’il vous invitait à le suivre.",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006
        },
        [71000320] = {
          ContentFR = "Le chat bondit, s’éloigne de quelques pas, puis s’arrête pour vous regarder, comme s’il vous invitait à le suivre.",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006
        },
        [71000330] = {
          ContentFR = "Le chat tourne joyeusement autour de vos pieds. Son air satisfait réchauffe votre âme et vous emplit d’une étrange sérénité.",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006
        },
        [71000501] = {
          ContentFR = "Hé, arrêtez ! Sinon je vais devoir sortir ma botte secrète... Bon, vous l’aurez voulu— À L’AIDE !",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005
        },
        [71000502] = {
          ContentFR = "Bouaaah !",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005
        },
        [71000503] = {
          ContentFR = "Voilà, c’était le dernier.",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014
        },
        [71000504] = {
          ContentFR = "Je vais vérifier si d’autres ennemis rôdent dans le coin. Sois prudent.  ",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014
        },
        [71000505] = {
          ContentFR = "Reçu, reçu ! Je ferai attention !  ",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015
        },
        [71000506] = {
          ContentFR = "Oh, toi aussi tu es venu... Snif... Je ne pensais pas qu’autant de monde viendrait m’aider... Voici un petit présent pour vous remercier. Comptez sur moi à l’avenir !  ",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{"818015:n(0)"}}",
          SpeakNpcId = 818015
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci ! Me voilà tiré d’affaire... On repart à l’aventure !",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci ! Me voilà tiré d’affaire... On repart à l’aventure !",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          ContentFR = "Des tonneaux rejetés par les vagues s’entassent sur la plage. En fouillant, vous pourriez y trouver quelque chose d’utile.",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006
        },
        [71000612] = {
          ContentFR = "Le fond de ce tonneau est éventré. Quelles que soient les richesses qu’il contenait autrefois, il n’est plus qu’un débris inutile. Mieux vaut en examiner un autre.",
          DialogueId = 71000612,
          GUID = "B1BE19E8"
        },
        [71000613] = {
          ContentFR = "Ce tonneau ne renferme rien d’autre que des poissons et des crevettes pourris. Mieux vaut en examiner un autre.",
          DialogueId = 71000613,
          GUID = "B1BE1A12"
        },
        [71000615] = {
          ContentFR = "La persévérance finit par payer : en fouillant avec soin, vous découvrez dans une cache dissimulée quelques ressources encore utilisables.",
          DialogueId = 71000615,
          GUID = "B1BE1A66"
        },
        [71000701] = {
          ContentFR = "Quelle galère... il ne me restait plus que quelques conduites à vérifier.",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007
        },
        [71000710] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001
        },
        [71000711] = {
          ContentFR = "Je dois inspecter les conduites de Phoxichor qui alimentent la cité.",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007
        },
        [71000721] = {
          ContentFR = "Mais ma corde de sécurité a lâché à la conduite précédente… Peux-tu grimper vérifier les dernières à ma place ?",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007
        },
        [71000741] = {
          ContentFR = "J’ai marqué les conduites restantes, tu me sauves la mise !",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007
        },
        [71000751] = {
          ContentFR = "Cette conduite n’a aucun dégât. Autant passer à la suivante.",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006
        },
        [71000761] = {
          ContentFR = "La dernière est intacte. Il est temps d’aller prévenir l’ouvrier.",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006
        },
        [71000771] = {
          ContentFR = "Toutes intactes ? Parfait ! Merci infiniment !",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007
        },
        [71000780] = {
          ContentFR = "Cette conduite présente une légère fissure. Autant en avertir l’ouvrier.",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006
        },
        [71000781] = {
          ContentFR = "Pff... encore des heures sup’. Je vais chercher mes outils. Tiens, prends ma clé et va fermer la vanne principale de Phoxichor en attendant.",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007
        },
        [71000782] = {
          ContentFR = "Merci, je prends le relais.",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007
        },
        [71000801] = {
          ContentFR = "{nickname}, {nickname}, vite ! J’ai trouvé un nouveau sujet de recherche !",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011
        },
        [71000802] = {
          ContentFR = "Cette fois, le matériel se trouve de l’autre côté du lac. Tu peux m’aider à le récupérer ?",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011
        },
        [71000803] = {
          ContentFR = "Voici le matériel que Theo voulait. Je vais le lui rapporter.",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001
        },
        [71000804] = {
          ContentFR = "Merci ! Pour devenir un grand alchimiste, il y a encore tellement de choses à apprendre... mais j’y arriverai !",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011
        },
        [71000805] = {
          ContentFR = "Ah, je vois ! La première leçon pour devenir un grand alchimiste : trouver ses matériaux par soi-même !",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011
        },
        [71000901] = {
          ContentFR = "Cache-cache ! Cache-cache ! Viens jouer avec nous !",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008
        },
        [71000902] = {
          ContentFR = "Cache-cache ! Cache-cache ! Viens jouer avec nous !",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
