        [71001001] = {
          ContentFR = "Une voiture flambant neuve est là, abandonnée. Serait-ce... une occasion en or ?",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006
        },
        [71001002] = {
          ContentFR = "Le réservoir de Phoxichor est rempli à ras bord... Voilà bien une aubaine !",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006
        },
        [71001003] = {
          ContentFR = "Hé ! Que fais-tu ?! Vite, du renfort !",
