        [71001005] = {
          ContentFR = "Finalement, ta conscience l’emporte. Tu décides de signaler aux gardes de la porte de la cité la faille de sécurité.",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006
        },
        [71001006] = {
          ContentFR = "Merci de nous avoir prévenus. Nous allons renforcer les patrouilles immédiatement. Accepte ce petit cadeau comme gage de notre gratitude.",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010
        },
        [71001101] = {
          ContentFR = "Des Souillés arrivent ! Repousse-les !",
