          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001
        },
        [71001302] = {
          ContentFR = "Je devrais peut-être explorer un peu les environs. Avec un peu de chance, quelque chose me reviendra.",
