        },
        [71002006] = {
          ContentFR = "Toi non plus tu ne l’as pas trouvé... ? Tant pis ! Ce chat errant qui court partout ne peut pas être mon Jerry. Je dirai à maman de m’acheter un autre chat, plus sage et plus mignon !",
          DialogueId = 71002006,
          GUID = "B1BEFE9C",
          SpeakNpcId = 818018
        },
        [71002007] = {
          ContentFR = "Merci ! Jerry... mon petit Jerry...",
          DialogueId = 71002007,
          GUID = "B1BEFEC6",
          SpeakNpcId = 818017
        },
        [71002101] = {
          ContentFR = "Ah, {nickname} ! {性别:Mon sauveur|Ma sauveuse}, viens vite m’aider !",
          DialogueId = 71002101,
          GUID = "B1BF0E32",
          SpeakNpcId = 818007
        },
        [71002102] = {
          ContentFR = "Je dois livrer cette caisse de matériel à mes collègues de l’autre côté du Lac du Deuil, mais j’ai soudain une affreuse douleur au ventre. Peux-tu la livrer à ma place ? Je t’en supplie !",
          DialogueId = 71002102,
          GUID = "B1BF0E5C",
          SpeakNpcId = 818007
        },
        [71002103] = {
          ContentFR = "Bonjour, voici les fournitures que Kevin m’a chargé de vous remettre.",
          DialogueId = 71002103,
          GUID = "B1BF0E86",
          NextDialogue = 71002104,
          SpeakNpcId = 100001
        },
        [71002104] = {
          ContentFR = "Minute... il manque deux chargeurs et un fusil. Avoue, tu les as pris !",
          DialogueId = 71002104,
          GUID = "B1BF0EB0",
          SpeakNpcId = 818008
        },
        [71002105] = {
          ContentFR = "Le détournement de matériel impérial est une grave infraction ! Tu viens avec moi !",
          DialogueId = 71002105,
          GUID = "B1BF0EDA",
          SpeakNpcId = 818008
        },
        [71002106] = {
          ContentFR = "Hein ? J’étais aux toilettes une minute, et vous êtes déjà en train de vous battre !",
          DialogueId = 71002106,
          GUID = "B1BF0F04",
          NextDialogue = 71002107,
          SpeakNpcId = 818007
        },
        [71002107] = {
          ContentFR = "C’est eux qui ont commencé.",
          DialogueId = 71002107,
          GUID = "B1BF0F2E",
          NextDialogue = 71002108,
          SpeakNpcId = 100001
        },
        [71002108] = {
          ContentFR = "Regarde ce que {性别:ce vaurien|cette vaurienne} a fait, {性别:il|elle} a même eu le culot de voler des fournitures de la légion !",
          DialogueId = 71002108,
          GUID = "B1BF0F58",
          NextDialogue = 71002109,
          SpeakNpcId = 818008
        },
        [71002109] = {
          ContentFR = "Hein ? Oh ! Deux chargeurs et un fusil ? C’est moi, je les avais déjà pris pour ma part.",
          DialogueId = 71002109,
          GUID = "B1BF0F82",
          NextDialogue = 71002110,
          SpeakNpcId = 818007
        },
        [71002110] = {
          ContentFR = "Tu n’es pas sérieux... Remettre des fournitures de la Légion au premier venu ? Et si c’était {性别:un|une} Déchu ?!",
          DialogueId = 71002110,
          GUID = "B1BF0FAC",
          NextDialogue = 71002111,
          SpeakNpcId = 818008
        },
        [71002111] = {
          ContentFR = "Ah, désolé, désolé, promis je ferai plus attention la prochaine fois.",
          DialogueId = 71002111,
          GUID = "B1BF0FD6",
          NextDialogue = 71002112,
          SpeakNpcId = 818007
        },
        [71002112] = {
          ContentFR = "{nickname}, prends ça en dédommagement. Vraiment désolé de t’avoir embarqué là-dedans.",
          DialogueId = 71002112,
          GUID = "B1BF1000",
          Scripts = "TurnTo{TurnToDescription{"818007:n(0)"}}",
          SpeakNpcId = 818007
        },
        [71002113] = {
          ContentFR = "Tu essayes de gagner du temps, hein ? Les gars, gardez un œil sur {性别:ce gamin|cette gamine}, {性别:qu’il|qu’elle} ne file pas en douce.",
          DialogueId = 71002113,
          GUID = "B1BF102A",
          SpeakNpcId = 818008
        },
        [71002114] = {
          ContentFR = "Me revoilà !",
          DialogueId = 71002114,
          GUID = "B1BF1054",
          NextDialogue = 71002115,
          SpeakNpcId = 818007
        },
        [71002115] = {
          ContentFR = "Hein, du matériel manquant ? Oh ! Deux chargeurs et un fusil ? C’est moi qui les ai pris, tout à l’heure.",
          DialogueId = 71002115,
          GUID = "B1BF107E",
          NextDialogue = 71002116,
          SpeakNpcId = 818007
        },
        [71002116] = {
          ContentFR = "Tu n’es pas sérieux... Remettre des fournitures de la Légion au premier venu ? Et si c’était {性别:un|une} Déchu ?!",
          DialogueId = 71002116,
          GUID = "B1BF10A8",
          NextDialogue = 71002117,
          SpeakNpcId = 818008
        },
        [71002117] = {
          ContentFR = "Ah, désolé, désolé, promis je ferai plus attention la prochaine fois.",
          DialogueId = 71002117,
          GUID = "B1BF10D2",
          NextDialogue = 71002118,
          SpeakNpcId = 818007
        },
        [71002118] = {
          ContentFR = "{nickname}, prends ça en dédommagement. Vraiment désolé de t’avoir embarqué là-dedans.",
          DialogueId = 71002118,
          GUID = "B1BF10FC",
          Scripts = "TurnTo{TurnToDescription{"818007:n(0)"}}",
          SpeakNpcId = 818007
        },
        [71002201] = {
          ContentFR = "Pff... je n’ai vraiment pas envie de bosser aujourd’hui...",
          DialogueId = 71002201,
          GUID = "B1BF1E9A",
          SpeakNpcId = 818019
        },
        [71002202] = {
          ContentFR = "Le patron a encore eu une de ses idées géniales : « Que les plats du restaurant de la Paix d’Argent arrivent dans chaque foyer ! » Comme si nous, les pauvres livreurs, on allait se transformer en héros à sa place...",
          DialogueId = 71002202,
          GUID = "B1BF1EC4",
          NextDialogue = 71002203,
          SpeakNpcId = 818019
        },
        [71002203] = {
          ContentFR = "Besoin d’un coup de main ?",
          DialogueId = 71002203,
          GUID = "B1BF1EEE",
          NextDialogue = 71002204,
          SpeakNpcId = 100001
        },
        [71002204] = {
          ContentFR = "Absolument ! Si quelqu’un pouvait bosser à ma place, et sans rien demander en retour, ce serait le rêve ! Mais bon... on sait tous que ça n’arrive jamais...",
          DialogueId = 71002204,
          GUID = "B1BF1F18",
          NextDialogue = 71002205,
          SpeakNpcId = 818019
        },
        [71002205] = {
          ContentFR = "Bon, si tu veux vraiment m’aider, prends juste quelques plats. Je ne pourrai que te remercier... et te laisser boire autant d’eau que tu veux au Lac du Deuil !",
          DialogueId = 71002205,
          GUID = "B1BF1F42",
          SpeakNpcId = 818019
        },
        [71002206] = {
          ContentFR = "Hé ! Regardez ce qu’on a là, quelqu’un qui transporte un festin. On va se régaler aujourd’hui, les gars !",
          DialogueId = 71002206,
          GUID = "B1BF1F6C",
          NextDialogue = 71002207,
          SpeakNpcId = 818057
        },
        [71002207] = {
          ContentFR = "Pas touche ! Ces plats sont pour les clients ! S’ils ne reçoivent pas leur nourriture, toute ma journée de salaire s’envole !",
          DialogueId = 71002207,
          GUID = "B1BF1F96",
          NextDialogue = 71002208,
          SpeakNpcId = 818019
        },
        [71002208] = {
          ContentFR = "On s’en fiche, file-les nous !",
          DialogueId = 71002208,
          GUID = "B1BF1F97",
          NextDialogue = 71002209,
          SpeakNpcId = 818057
        },
        [71002209] = {
          ContentFR = "Arrêtez !",
          DialogueId = 71002209,
          GUID = "B1BF1F98",
          SpeakNpcId = 100001
        },
        [71002210] = {
          ContentFR = "Ouf... la soupe n’a pas coulé ! Allez, on continue la livraison avant que ça parte en vrille...",
          DialogueId = 71002210,
          GUID = "B1BF1FC0",
          SpeakNpcId = 818019
        },
        [71002211] = {
          ContentFR = "Allez, presque fini... plus qu’une dernière livraison ! Sérieusement, le patron pourrait se calmer avec ses idées farfelues...",
          DialogueId = 71002211,
          GUID = "B1BF20BC",
          SpeakNpcId = 818019
        },
        [71002212] = {
          ContentFR = "Qu’est-ce que c’est que ce bazar au milieu de la route... Tout me tombe dessus aujourd’hui !",
          DialogueId = 71002212,
          GUID = "B1BF1FEA",
          NextDialogue = 71002218,
          SpeakNpcId = 818019
        },
        [71002213] = {
          ContentFR = "Tiens, garde les plats. Je m’occupe de tout ce bazar.",
          DialogueId = 71002213,
          GUID = "B1BF2014",
          SpeakNpcId = 100001
        },
        [71002214] = {
          ContentFR = "Quoi ? Tout est dégagé ? On est encore dans les temps ! Allez, en route, en route !",
          DialogueId = 71002214,
          GUID = "B1BF2015",
          SpeakNpcId = 818019
        },
        [71002215] = {
          ContentFR = "Enfin, tout livré... sans toi, je n’aurais rien gagné. Bon... pause terminée, il faut retourner bosser...",
          DialogueId = 71002215,
          GUID = "B1BF203E",
          NextDialogue = 71002216,
          SpeakNpcId = 818019
        },
        [71002216] = {
          ContentFR = "Mais tu disais que tu arrêtais ?",
          DialogueId = 71002216,
          GUID = "B1BF2068",
          NextDialogue = 71002217,
          SpeakNpcId = 100001
        },
        [71002217] = {
          ContentFR = "Luno, le livreur secoue la poussière de ses vêtements et s’éloigne. La réponse à ta question se perd dans le petit soupir las qu’il laisse derrière lui...",
          DialogueId = 71002217,
          GUID = "B1BF2092",
          SpeakNpcId = 800006
        },
        [71002218] = {
          ContentFR = "J’en ai marre ! Cette fois, je le dis au patron, ce boulot, je le REFUSE !",
          DialogueId = 71002218,
          GUID = "B1BF1FEB",
          NextDialogue = 71002213,
          SpeakNpcId = 818019
        },
        [71002301] = {
          ContentFR = "Ouf... je n’ai pas tout cassé, j’espère...",
          DialogueId = 71002301,
          GUID = "B1BF2F02",
          SpeakNpcId = 818020
        },
        [71002302] = {
          ContentFR = "Qui est là... !?",
          DialogueId = 71002302,
          GUID = "B1BF2F2C",
          NextDialogue = 71002303,
          SpeakNpcId = 818020
        },
        [71002303] = {
          ContentFR = "Oh... juste {性别:un Chasseur de Phoxène|une Chasseuse de Phoxène} de passage. Euh... dis, tu veux pas me filer un coup de main ? Il faut juste tester ce truc, c’est super facile ! Je te donnerai une récompense.",
          DialogueId = 71002303,
          GUID = "B1BF2F56",
          SpeakNpcId = 818020
        },
        [71002304] = {
          ContentFR = "Tiens bon 15 secondes, et c’est fini ! Allez, courage !",
          DialogueId = 71002304,
          GUID = "B1BF2F80",
          SpeakNpcId = 818020
        },
        [71002305] = {
          ContentFR = "Tous les tirs ont raté... Ils disaient que c’était un bijou militaire d’Élysium ? Franchement, ça ressemble plus à un tas de ferraille... Ah, oublie ce que je viens de dire. Tiens, voilà ta paye. Et, euh... gardons ça entre nous, hein ?",
          DialogueId = 71002305,
          GUID = "B1BF2FAA",
          SpeakNpcId = 818020
        },
        [71002306] = {
          ContentFR = "Tous les tirs ont touché, et tu es toujours debout !? Mais c’était censé être un bijou militaire d’Élysium ! Bon... sûrement juste un truc hors de prix... Ah, oublie ce que je viens de dire. Tiens, voilà ta paye. Et, euh... gardons ça entre nous, hein ?",
          DialogueId = 71002306,
          GUID = "B1BF2FD4",
          SpeakNpcId = 818020
        },
        [71002401] = {
          ContentFR = "Argh... cet excavateur est déjà en panne alors qu’il n’a même pas commencé à travailler ! Mais... où est passé mon kit de réparation ?",
          DialogueId = 71002401,
          GUID = "B1BF3F6A",
          SpeakNpcId = 818015
        },
        [71002402] = {
          ContentFR = "Ouaah ! On se retrouve dans un endroit pareil, c’est un sacré hasard ! Puisque tu es là, tu ne veux pas jeter un œil à mon précieux excavateur pendant que je vais chercher mes outils ?",
          DialogueId = 71002402,
          GUID = "B1BF3F94",
          SpeakNpcId = 818015
        },
        [71002403] = {
          ContentFR = "Youpi ! Super, reste juste à côté et ne le perds pas de vue, d’accord ? Je reviens tout de suite !",
          DialogueId = 71002403,
          GUID = "B1BF3FBE",
          NextDialogue = 71002404,
          SpeakNpcId = 818015
        },
        [71002404] = {
          ContentFR = "Hmm... quelques pièces sont coincées. Si je les débloque un peu, ça devrait être plus facile à réparer ensuite.",
          DialogueId = 71002404,
          GUID = "B1BF3FE8",
          SpeakNpcId = 100001
        },
        [71002405] = {
          ContentFR = "L’excavateur fait du bruit et attire les Souillés aux alentours. Il faut les repousser avant qu’ils s’approchent trop.",
          DialogueId = 71002405,
          GUID = "B1BF4012",
          SpeakNpcId = 800006
        },
        [71002406] = {
          ContentFR = "Eh... tu as même débloqué les pièces coincées ? Tu es trop {性别:fort|forte}, merci beaucoup !",
          DialogueId = 71002406,
          GUID = "B1BF403C",
          SpeakNpcId = 818015
        },
        [71002407] = {
          ContentFR = "Ça y est, je suis de retour ! Je savais que je pouvais compter sur toi !",
          DialogueId = 71002407,
          GUID = "B1BF4066",
          SpeakNpcId = 818015
        },
        [71002501] = {
          ContentFR = "Bon... ce fichu égout est encore bouché...",
          DialogueId = 71002501,
          GUID = "B1BF4FD2",
          SpeakNpcId = 818021
        },
        [71002502] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71002502,
          GUID = "B1BF4FFC",
          NextDialogue = 71002503,
          SpeakNpcId = 100001
        },
        [71002503] = {
          ContentFR = "Tout ce secteur est bloqué. Mon supérieur m’a filé un manuel en me disant de « suivre les instructions », mais je n’y comprends rien... Tu pourrais m’aider ?",
          DialogueId = 71002503,
          GUID = "B1BF5026",
          NextOptions = {
            [1] = 710025041,
            [2] = 710025042
          },
          SpeakNpcId = 818021
        },
        [71002505] = {
          ContentFR = "D’après le manuel, il suffit d’ouvrir trois vannes pour créer un fort courant et tout évacuer.",
          DialogueId = 71002505,
          GUID = "B1BF507A",
          NextDialogue = 71002511,
          SpeakNpcId = 100001
        },
        [71002507] = {
          ContentFR = "Super ! La deuxième est par là-bas.",
          DialogueId = 71002507,
          GUID = "B1BF50CE",
          SpeakNpcId = 818021
        },
        [71002508] = {
          ContentFR = "Et la troisième... voyons voir... oui, la voilà !",
          DialogueId = 71002508,
          GUID = "B1BF50F8",
          SpeakNpcId = 818021
        },
        [71002509] = {
          ContentFR = "Parfait, j’ai tout compris ! Tiens, prends ça pour te remercier, tu l’as bien mérité.",
          DialogueId = 71002509,
          GUID = "B1BF5122",
          SpeakNpcId = 818021
        },
        [71002510] = {
          ContentFR = "Pas mal du tout, ta méthode ! Tiens, un petit quelque chose pour l’aide.",
          DialogueId = 71002510,
          GUID = "B1BF514C",
          SpeakNpcId = 818021
        },
        [71002511] = {
          ContentFR = "Ah, d’accord ! Tu peux me montrer comment faire ? Je regarderai et j’apprendrai.",
          DialogueId = 71002511,
          GUID = "B1BF507B",
          SpeakNpcId = 818021
        },
        [71002601] = {
          ContentFR = "Pff... cette pioche est déjà foutue ! Et avec toutes ces pierres qui restent, qu’est-ce que tu veux que je fasse ? Je vais pas creuser à mains nues quand même...",
          DialogueId = 71002601,
          GUID = "B1BF603A",
          SpeakNpcId = 818023
        },
        [71002602] = {
          ContentFR = "Toi aussi t’es un Chasseur de Phoxène, pas vrai ? J’ai accepté ce contrat en pensant que ce serait vite plié, mais impossible de le finir tout seul. Alors, on fait équipe ? On partage la récompense à parts égales.",
          DialogueId = 71002602,
          GUID = "B1BF6064",
          NextOptions = {
            [1] = 710026021,
            [2] = 710026022
          },
          SpeakNpcId = 818023,
          bForbidSkipOptions = true
        },
        [71002603] = {
          ContentFR = "Parfait. Occupe-toi du reste, je trie ce que j’ai déjà sorti.",
          DialogueId = 71002603,
          GUID = "B1BF608E",
          SpeakNpcId = 818023
        },
        [71002604] = {
          ContentFR = "Ouah... tu connais vraiment des astuces comme ça ? Impressionnant !",
          DialogueId = 71002604,
          GUID = "B1BF60B8",
          NextDialogue = 71002605,
          SpeakNpcId = 818023
        },
        [71002605] = {
          ContentFR = "Merci pour ton aide. Tiens, voilà ta part comme promis.",
          DialogueId = 71002605,
          GUID = "B1BF60E2",
          SpeakNpcId = 818023
        },
        [71002701] = {
          ContentFR = "Des barils dérivent au fil du canal, certains émettant de drôles de sons. Si tu les ouvres prudemment, tu pourrais y trouver quelque chose d’utile.",
          DialogueId = 71002701,
          GUID = "B1BF70A2",
          SpeakNpcId = 800006
        },
        [71002702] = {
          ContentFR = "Le fond de ce baril est percé. À part le sifflement du vent, rien d’intéressant. Mieux vaut regarder ailleurs.",
          DialogueId = 71002702,
          GUID = "B1BF70CC",
          SpeakNpcId = 800006
        },
        [71002703] = {
          ContentFR = "Ce baril est rempli d’ordures ménagères. Ça glougloute et ça empeste... mieux vaut regarder ailleurs.",
          DialogueId = 71002703,
          GUID = "B1BF70F6",
          SpeakNpcId = 800006
        },
        [71002704] = {
          ContentFR = "La persévérance finit par payer : en fouillant soigneusement, tu découvres des fournitures dissimulées dans une double paroi.",
          DialogueId = 71002704,
          GUID = "B1BF7120",
          SpeakNpcId = 800006
        },
        [71002705] = {
          ContentFR = "Le vieux baril s’écroule d’un coup avec fracas, attirant les Souillés alentour. Débarrasse-toi d’eux et empare-toi de ton butin !",
          DialogueId = 71002705,
          GUID = "B1BF714A",
          SpeakNpcId = 800006
        },
        [71002801] = {
          ContentFR = "Un éboulement bloque le passage devant toi. Dégage les rochers pour continuer.",
          DialogueId = 71002801,
          GUID = "B1BF810A",
          SpeakNpcId = 800006
        },
        [71002802] = {
          ContentFR = "En déblayant les pierres, tu trouves quelques fournitures encore utilisables. Mieux vaut ne pas les laisser ici.",
          DialogueId = 71002802,
          GUID = "B1BF8134",
          SpeakNpcId = 800006
        },
        [71002803] = {
          ContentFR = "Le bruit attire des Souillés à proximité. Profite des rochers instables au-dessus pour les repousser.",
          DialogueId = 71002803,
          GUID = "B1BF815E",
          SpeakNpcId = 800006
        },
        [71002804] = {
          ContentFR = "Après le combat, tu fouilles les environs et trouves d’autres fournitures utiles. Mieux vaut ne pas les laisser ici.",
          DialogueId = 71002804,
          GUID = "B1BF8188",
          SpeakNpcId = 800006
        },
        [71002901] = {
          ContentFR = "Sous les ordres du sergent, l’ennemi progresse méthodiquement vers toi. Abats le sergent au plus vite pour briser leur formation.",
          DialogueId = 71002901,
          GUID = "B1BF9172",
          SpeakNpcId = 800006
        },
        [71002902] = {
          ContentFR = "Grâce à ton sang-froid et à tes décisions avisées, l’ennemi s’effondre.",
          DialogueId = 71002902,
          GUID = "B1BF919C",
          SpeakNpcId = 800006
        },
        [71002903] = {
          ContentFR = "Le sergent appelle du renfort, d’autres ennemis arrivent sur toi.",
          DialogueId = 71002903,
          GUID = "B1BF91C6",
          SpeakNpcId = 800006
        },
        [71003001] = {
          ContentFR = "Des Souillés errent tout près, grognant avec nervosité et emplissant les environs d’une aura funeste. Débarrasse-t’en rapidement.",
          DialogueId = 71003001,
          GUID = "B1BFA1DA",
          SpeakNpcId = 800006
        },
        [71003002] = {
          ContentFR = "L’atmosphère s’alourdit encore, tu le sens : quelque chose de sinistre est sur le point de se manifester.",
          DialogueId = 71003002,
          GUID = "B1BFA204",
          SpeakNpcId = 800006
        },
        [71003003] = {
          ContentFR = "Le fracas du combat a attiré un fléau indomptable. L’incarnation de la destruction est enfin là. Abats-la, comme tu l’as déjà fait tant de fois.",
          DialogueId = 71003003,
          GUID = "B1BFA22E",
          SpeakNpcId = 800006
        },
        [71003004] = {
          ContentFR = "Avec la disparition des Souillés, l’aura maléfique se dissipe à son tour. Pour l’instant, la zone est sûre.",
          DialogueId = 71003004,
          GUID = "B1BFA258",
          SpeakNpcId = 800006
        },
        [71003101] = {
          ContentFR = "Ces derniers temps, les Géniemons sont devenus la cible de braconniers. Protège celui qui se trouve devant toi et chasse-les.",
          DialogueId = 71003101,
          GUID = "B1BFB242",
          SpeakNpcId = 800006
        },
        [71003102] = {
          ContentFR = "D’autres ennemis surgissent au loin.",
          DialogueId = 71003102,
          GUID = "B1BFB26C",
          SpeakNpcId = 800006
        },
        [71003103] = {
          ContentFR = "La menace est écartée. Le Géniemon est désormais en sécurité.",
          DialogueId = 71003103,
          GUID = "B1BFB296",
          SpeakNpcId = 800006
        },
        [71003201] = {
          ContentFR = "Un éboulement bloque le passage. Des explosifs abandonnés traînent par ici, ça pourrait t’aider à dégager le chemin.",
          DialogueId = 71003201,
          GUID = "B1BFC2AA",
          SpeakNpcId = 800006
        },
        [71003202] = {
          ContentFR = "Tu tombes sur le manuel de dynamitage des mineurs. Il est abîmé et effacé par endroits, mais on peut encore en déchiffrer le contenu.",
          DialogueId = 71003202,
          GUID = "B1BFC2D4",
          SpeakNpcId = 800006
        },
        [71003203] = {
          ContentFR = "Tu trouves quelques explosifs un peu abîmés. Avec un peu de bricolage, ils devraient encore servir.",
          DialogueId = 71003203,
          GUID = "B1BFC2FE",
          SpeakNpcId = 800006
        },
        [71003204] = {
          ContentFR = "Tu trouves une bobine de mèches usées. Après une petite remise en état, elles devraient encore faire l’affaire.",
          DialogueId = 71003204,
          GUID = "B1BFC328",
          SpeakNpcId = 800006
        },
        [71003206] = {
          ContentFR = "Tu suis les instructions du manuel et installes les charges. Il est temps de les faire exploser pour dégager le tunnel.",
          DialogueId = 71003206,
          Duration = 3,
          GUID = "B1BFC37C",
          SpeakNpcId = 800006
        },
        [71003207] = {
          ContentFR = "En nettoyant les débris, tu repères quelques fournitures encore utilisables. Mieux vaut ne pas les laisser ici.",
          DialogueId = 71003207,
          GUID = "B1BFC3A6",
          SpeakNpcId = 800006
        },
        [71003501] = {
          ContentFR = "Au loin, quelque chose scintille et attire ton attention. Peut-être vaudrait-il la peine d’aller voir de plus près.",
          DialogueId = 71003501,
          GUID = "B1BFF3E2",
          SpeakNpcId = 800006
        },
        [71003502] = {
          ContentFR = "Ah ! Je savais bien que ce bout de miroir brillant attirerait un Chasseur de Phoxène ! {性别:Attrapez-le|Attrapez-la} !",
          DialogueId = 71003502,
          GUID = "B1BFF40C",
          SpeakNpcId = 818028
        },
        [71003504] = {
          ContentFR = "Assez, assez ! On arrête ! Désolé, on n’osera plus recommencer... promis !",
          DialogueId = 71003504,
          GUID = "B1BFF460",
          SpeakNpcId = 818028
        },
        [71003601] = {
          ContentFR = "Soudain, une sirène stridente déchire le silence. Une nuée de drones magnétiques fonce droit sur toi.",
          DialogueId = 71003601,
          GUID = "B1C0044A",
          SpeakNpcId = 800006
        },
        [71003602] = {
          ContentFR = "La sirène devient plus assourdissante à chaque seconde. D’autres ennemis affluent.",
          DialogueId = 71003602,
          GUID = "B1C00474",
          SpeakNpcId = 800006
        },
        [71003603] = {
          ContentFR = "Le vacarme s’essouffle peu à peu... mais une ultime vague approche. Tiens bon.",
          DialogueId = 71003603,
          GUID = "B1C0049E",
          SpeakNpcId = 800006
        },
        [71003604] = {
          ContentFR = "Tous les ennemis gisent à terre. La dernière alarme s’éteint dans un grésillement, et le silence retombe enfin.",
          DialogueId = 71003604,
          GUID = "B1C004C8",
          SpeakNpcId = 800006
        },
        [71003701] = {
          ContentFR = "Pff... je n’ai vraiment pas envie de bosser aujourd’hui...",
          DialogueId = 71003701,
          GUID = "B1C014B2",
          SpeakNpcId = 818019
        },
        [71003702] = {
          ContentFR = "Non mais sérieusement... encore une livraison au Lac du Deuil ? Les gens peuvent pas manger dans des endroits normaux, non ? Ils ont pas peur d’avoir des ennuis, eux !? À force de courir partout, j’en peux plus...",
          DialogueId = 71003702,
          GUID = "B1C014DC",
          NextDialogue = 71003703,
          SpeakNpcId = 818019
        },
        [71003703] = {
          ContentFR = "Besoin d’un coup de main ?",
          DialogueId = 71003703,
          GUID = "B1C014DD",
          NextDialogue = 71003704,
          SpeakNpcId = 100001
        },
        [71003704] = {
          ContentFR = "OUI ! J’ai besoin que tu frappes ces clients d’un bon coup, ces ingrats. Et à leur balancer une avalanche de boules de neige ! Comme ça, peut-être qu’ils arrêteront de commander de la nourriture au milieu de nulle part !",
          DialogueId = 71003704,
          GUID = "B1C014DE",
          NextOptions = {
            [1] = 710037041,
            [2] = 710037042
          },
          SpeakNpcId = 818019,
          bForbidSkipOptions = true
        },
        [71003705] = {
          ContentFR = "Pff... ouais, je sais bien, c’est juste pour râler un peu. Bon, puisque tu es là, viens avec moi. Ça me tiendra compagnie, et la route paraîtra moins longue... Allez, assez traîné,  au boulot !",
          DialogueId = 71003705,
          GUID = "B1C01506",
          SpeakNpcId = 818019
        },
        [71003706] = {
          ContentFR = "Argh... avec tous ces éclats de glace, si ça tombe dans la nourriture, je suis fichu ! Faut trouver un moyen de dégager tout ça...",
          DialogueId = 71003706,
          GUID = "B1C01530",
          SpeakNpcId = 818019
        },
        [71003707] = {
          ContentFR = "Oh, trop bien ! C’était rapide, les plats sont encore chauds ! Allez, dépêchons-nous de livrer avant que le patron recommence son sermon...",
          DialogueId = 71003707,
          GUID = "B1C01656",
          SpeakNpcId = 818019
        },
        [71003708] = {
          ContentFR = "À l’aide ! Au moins laissez-moi finir mon repas avant de mourir !",
          DialogueId = 71003708,
          GUID = "B1C0155A",
          NextDialogue = 71003709,
          SpeakNpcId = 818029
        },
        [71003709] = {
          ContentFR = "Quoi !? Je le savais ! Il est vraiment en danger ! Vite, allons l’aider ! Et si jamais il raconte au patron que je lui ai sauvé la mise... peut-être qu’il me filera enfin une prime... héhé... héhéhé...",
          DialogueId = 71003709,
          GUID = "B1C01584",
          SpeakNpcId = 818019
        },
        [71003710] = {
          ContentFR = "Ouf ! Plus de bestioles dans les pattes, un bon repas chaud et la vue du lac... c’est ça, la belle vie !",
          DialogueId = 71003710,
          GUID = "B1C015AE",
          NextDialogue = 71003711,
          SpeakNpcId = 818024
        },
        [71003711] = {
          ContentFR = "Euh... Monsieur, vous n’avez pas encore payé...",
          DialogueId = 71003711,
          GUID = "B1C015D8",
          NextDialogue = 71003712,
          SpeakNpcId = 818019
        },
        [71003712] = {
          ContentFR = "Hein ? Mais t’es qu’un simple livreur, non ? Qu’est-ce que tu fous encore là ? Mets ça sur l’ardoise, je réglerai la prochaine fois que je passe au resto.",
          DialogueId = 71003712,
          GUID = "B1C01602",
          NextDialogue = 71003713,
          SpeakNpcId = 818024
        },
        [71003713] = {
          ContentFR = "Mais... si je rentre les mains vides, je vais me faire incendier par le patron...",
          DialogueId = 71003713,
          Duration = 3,
          GUID = "B1C0162C",
          NextDialogue = 71003714,
          SpeakNpcId = 818019
        },
        [71003714] = {
          ContentFR = "Tu observes toute la scène, puis avances tranquillement. Personne ne remarque la boule de neige qui se forme dans ta main, prête à voler.",
          DialogueId = 71003714,
          Duration = 4,
          GUID = "B1C0162D",
          NextDialogue = 71003715,
          SpeakNpcId = 800006
        },
        [71003715] = {
          ContentFR = "Aah ! C’est quoi ce truc ?! Une boule de neige ? Mais c’est geléééé ! Aaaah mon repas, il est tombé à l’eau ! Noooooon— !",
          DialogueId = 71003715,
          GUID = "B1C0162E",
          SpeakNpcId = 818024
        },
        [71003801] = {
          ContentFR = "Des Souillés rôdent par dizaines, obstruant le passage. Élimine-les !",
          DialogueId = 71003801,
          GUID = "B1C0251A",
          SpeakNpcId = 800006
        },
        [71003802] = {
          ContentFR = "Le fracas du combat en attire d’autres. Tiens ta position !",
          DialogueId = 71003802,
          GUID = "B1C02544",
          SpeakNpcId = 800006
        },
        [71003803] = {
          ContentFR = "Le dernier monstre s’effondre. Le tunnel est enfin dégagé, du moins, pour l’instant.",
          DialogueId = 71003803,
          GUID = "B1C0256E",
          SpeakNpcId = 800006
        },
        [71003901] = {
          Content = "房间中传来一股肃杀的气息，不安的预感萦绕在心头（待包装）",
          DialogueId = 71003901,
          GUID = "B1C03582",
          SpeakNpcId = 800006
        },
        [71003902] = {
          Content = "齿轮运动的声音响起，敌人正从开启的通道口中窜出（待包装）",
          DialogueId = 71003902,
          GUID = "B1C035AC",
          SpeakNpcId = 800006
        },
        [71003903] = {
          Content = "又是齿轮响动的声音，不远处的两个通道也开启了（待包装）",
          DialogueId = 71003903,
          GUID = "B1C035D6",
          SpeakNpcId = 800006
        },
        [71003904] = {
          Content = "齿轮转动，室内的全部通道均已开启，努力击杀敌人吧（待包装）",
          DialogueId = 71003904,
          GUID = "B1C03600",
          SpeakNpcId = 800006
        },
        [71003905] = {
          Content = "所有通道均已关闭，剩余的敌人将在不久后溃散（待包装）",
          DialogueId = 71003905,
          GUID = "B1C0362A",
          SpeakNpcId = 800006
        },
        [71004101] = {
          ContentFR = "Le dirigeable abandonné semble être devenu un entrepôt improvisé pour la faune local. Il y a peut-être encore quelque chose à récupérer.",
          DialogueId = 71004101,
          GUID = "B1C05652",
          SpeakNpcId = 800006
        },
        [71004102] = {
          ContentFR = "Le vacarme de ta fouille alerte les ennemis à proximité. Prépare-toi à les affronter.",
          DialogueId = 71004102,
          GUID = "B1C056A6",
          SpeakNpcId = 800006
        },
        [71004103] = {
          ContentFR = "Une fois le danger écarté, tu peux enfin faire le point sur tes trouvailles.",
          DialogueId = 71004103,
          GUID = "B1C056D0",
          SpeakNpcId = 800006
        },
        [71004201] = {
          ContentFR = "Mmm hmm... oui, bien solide...",
          DialogueId = 71004201,
          GUID = "B1C066BA",
          SpeakNpcId = 818038
        },
        [71004202] = {
          ContentFR = "Tu fais quoi ?",
          DialogueId = 71004202,
          GUID = "B1C066E4",
          NextDialogue = 71004203,
          SpeakNpcId = 100001
        },
        [71004203] = {
          ContentFR = "Je fais des recherches sur les Souillés. Tu veux m’aider à collecter quelques échantillons de spécimens ?",
          DialogueId = 71004203,
          GUID = "B1C066E5",
          NextOptions = {
            [1] = 710042031,
            [2] = 710042032
          },
          SpeakNpcId = 818038
        },
        [71004204] = {
          ContentFR = "Parfait ! Je te laisse faire. Je vais me reposer un peu, passer la journée à ramper partout m’a presque tué...",
          DialogueId = 71004204,
          GUID = "B1C0670E",
          SpeakNpcId = 818038
        },
        [71004205] = {
          ContentFR = "Aaaah ! Il y a encore des Souillés vivants ! Ne vous approchez pas, je suis là pour vous étudier, pas le contraire ! Oust !",
          DialogueId = 71004205,
          GUID = "B1C06738",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 818038
        },
        [71004206] = {
          ContentFR = "Merci ! Les échantillons sont complets, je retourne à mes recherches. À la prochaine !",
          DialogueId = 71004206,
          GUID = "B1C0678C",
          SpeakNpcId = 818038
        },
        [71004301] = {
          ContentFR = "Cette zone regorge toujours de magnifiques coquillages. La marée a rejeté quelques caisses sur le rivage, brise-les et découvre ce qu’elles renferment.",
          DialogueId = 71004301,
          GUID = "B1C07722",
          SpeakNpcId = 800006
        },
        [71004302] = {
          ContentFR = "Au fond d’une caisse, tu découvres quelques coquillages intacts.",
          DialogueId = 71004302,
          GUID = "B1C0774C",
          SpeakNpcId = 800006
        },
        [71004303] = {
          ContentFR = "On raconte que certains Souillés se cachent dans les caisses pour surprendre les imprudents. Malheureusement pour eux, cette fois ils sont tombés sur toi. Abats-les et empare-toi de ton dû.",
          DialogueId = 71004303,
          GUID = "B1C07776",
          SpeakNpcId = 800006
        },
        [71004401] = {
          ContentFR = "La zone est envahi par des Souillés. Élimine-les pour pouvoir sauver le Géniemon.",
          DialogueId = 71004401,
          GUID = "B1C0878A",
          SpeakNpcId = 800006
        },
        [71004402] = {
          ContentFR = "Le fracas du combat a attiré un fléau indomptable. L’incarnation de la destruction est enfin là. Abats-la, comme tu l’as déjà fait tant de fois.",
          DialogueId = 71004402,
          GUID = "B1C087B4",
          SpeakNpcId = 800006
        },
        [71004403] = {
          ContentFR = "La zone est sécurisée pour le moment. Profite-en pour attraper le Géniemon !",
          DialogueId = 71004403,
          GUID = "B1C087DE",
          SpeakNpcId = 800006
        },
        [71004501] = {
          ContentFR = "Les ennemis bloquent l’accès aux caisses de ravitaillement. Élimine-les !",
          DialogueId = 71004501,
          GUID = "B1C097F2",
          SpeakNpcId = 800006
        },
        [71004502] = {
          ContentFR = "L’incarnation de la destruction surgit dans la zone. Abats-la pour récupérer les ressources.",
          DialogueId = 71004502,
          GUID = "B1C0981C",
          SpeakNpcId = 800006
        },
        [71004503] = {
          ContentFR = "Les environs sont sûrs... pour l’instant. Ramasse vite tout le matériel.",
          DialogueId = 71004503,
          GUID = "B1C09846",
          SpeakNpcId = 800006
        },
        [71004601] = {
          ContentFR = "Un tas de caisses de ravitaillement se dresse devant toi. Ça pourrait valoir la peine d’y jeter un coup d’œil.",
          DialogueId = 71004601,
          GUID = "B1C0A85A",
          SpeakNpcId = 800006
        },
        [71004602] = {
          ContentFR = "Tu y découvres quelques ressources utiles.",
          DialogueId = 71004602,
          GUID = "B1C0A884",
          SpeakNpcId = 800006
        },
        [71004603] = {
          ContentFR = "On raconte que certains Souillés se cachent dans les caisses pour surprendre les imprudents. Malheureusement pour eux, cette fois ils sont tombés sur toi. Abats-les et empare-toi de ton dû.",
          DialogueId = 71004603,
          GUID = "B1C0A8AE",
          SpeakNpcId = 800006
        },
        [71004701] = {
          ContentFR = "Quelque chose brille au loin et attire ton regard. Ça pourrait valoir la peine d’y jeter un coup d’œil.",
          DialogueId = 71004701,
          GUID = "B1C0B8C2",
          SpeakNpcId = 800006
        },
        [71004702] = {
          ContentFR = "Au moment où tu ramasses l’objet, une alarme retentit. Une nuée d’ennemis fonce sur toi, prépare-toi au combat.",
          DialogueId = 71004702,
          GUID = "B1C0B8EC",
          SpeakNpcId = 800006
        },
        [71004703] = {
          ContentFR = "L’alarme s’éteint... mais son écho attire une deuxième vague. Tiens bon.",
          DialogueId = 71004703,
          GUID = "B1C0B916",
          SpeakNpcId = 800006
        },
        [71004704] = {
          ContentFR = "Tous les ennemis gisent à terre. La dernière alarme s’éteint dans un grésillement, et le silence retombe enfin.",
          DialogueId = 71004704,
          GUID = "B1C0B940",
          SpeakNpcId = 800006
        },
        [71004801] = {
          ContentFR = "Au loin, tu entends le craquement sec de la glace qui se brise. Tu ferais bien d’aller voir ce qui se passe.",
          DialogueId = 71004801,
          GUID = "B1C0C92A",
          SpeakNpcId = 800006
        },
        [71004802] = {
          ContentFR = "{性别:Un Chasseur de Phoxène|Une Chasseuse de Phoxène} ? Tu tombes bien. Sous le pont, les stalactites de glace s’accumulent dangereusement. Viens m’aider à les dégager.",
          DialogueId = 71004802,
          GUID = "B1C0C954",
          NextOptions = {
            [1] = 710048021,
            [2] = 710048022
          },
          SpeakNpcId = 818039
        },
        [71004803] = {
          ContentFR = "Merci pour ton aide. Occupe-toi de celles-là, je prends le reste.",
          DialogueId = 71004803,
          GUID = "B1C0C97E",
          SpeakNpcId = 818039
        },
        [71004805] = {
          ContentFR = "Voilà, c’est beaucoup plus sûr comme ça. Tiens, c’est pour toi, ta récompense.",
          DialogueId = 71004805,
          GUID = "B1C0C9D2",
          SpeakNpcId = 818039
        },
        [71004901] = {
          ContentFR = "Soupir... Impossible de traverser comme ça. J’aurais dû penser à acheter du Lotus d’hiver pour l’appât...",
          DialogueId = 71004901,
          GUID = "B1C0D992",
          SpeakNpcId = 818040
        },
        [71004902] = {
          ContentFR = "Hé, {性别:Chasseur de Phoxène|Chasseuse de Phoxène} ! J’ai besoin de Lotus d’hiver pour la pêche, mais il pousse de l’autre côté du lac. Tu pourrais m’en ramener un peu ?",
          DialogueId = 71004902,
          GUID = "B1C0D9BC",
          NextOptions = {
            [1] = 710049021,
            [2] = 710049022
          },
          SpeakNpcId = 818040,
          bForbidSkipOptions = true
        },
        [71004903] = {
          ContentFR = "Merci ! Je vais préparer ma canne en attendant ton retour.",
          DialogueId = 71004903,
          GUID = "B1C0D9E6",
          SpeakNpcId = 818040
        },
        [71004905] = {
          ContentFR = "La rive grouille de Souillés. Il vaut mieux les éliminer avant d’aller cueillir le Lotus d’hiver.",
          DialogueId = 71004905,
          GUID = "B1C0DA3A",
          SpeakNpcId = 800006
        },
        [71004906] = {
          ContentFR = "Tu récoltes tout le Lotus d’hiver disponible dans les environs. Il est temps de le rapporter au pêcheur.",
          DialogueId = 71004906,
          GUID = "B1C0DA64",
          SpeakNpcId = 800006
        },
        [71004907] = {
          ContentFR = "Parfait ! Avec autant d’appât, je vais forcément attraper du poisson aujourd’hui !",
          DialogueId = 71004907,
          GUID = "B1C0DA8E",
          SpeakNpcId = 818040
        },
        [71005001] = {
          ContentFR = "Hé, vous là-bas ! Vous pourriez me prendre en photo ?",
          DialogueId = 71005001,
          GUID = "B1C0E9FA",
          SpeakNpcId = 818041
        },
        [71005002] = {
          ContentFR = "Bonjour ! Vous pouvez m’aider à faire quelques photos ? C’est ma première fois à Givrelac, ce serait dommage de repartir sans souvenirs.",
          DialogueId = 71005002,
          GUID = "B1C0EA24",
          NextOptions = {
            [1] = 710050021,
            [2] = 710050022
          },
          SpeakNpcId = 818041,
          bForbidSkipOptions = true
        },
        [71005004] = {
          ContentFR = "Super ! N’oubliez pas de cadrer aussi le bâtiment derrière moi, j’adore sa forme.",
          DialogueId = 71005004,
          GUID = "B1C0EA78",
          SpeakNpcId = 818041
        },
        [71005005] = {
          ContentFR = "Vous avez un vrai talent pour ça, c’est parfait ! Merci beaucoup !",
          DialogueId = 71005005,
          GUID = "B1C0EAA2",
          SpeakNpcId = 818041
        },
        [71005101] = {
          ContentFR = "Viens, petit poisson, viens.",
          DialogueId = 71005101,
          GUID = "B1C0EAA3",
          SpeakNpcId = 818045
        },
        [71005102] = {
          ContentFR = "Tu fais quoi ?",
          DialogueId = 71005102,
          GUID = "B1C0FA62",
          NextDialogue = 71005103,
          SpeakNpcId = 100001
        },
        [71005103] = {
          ContentFR = "Je pêche, chut. Pas maintenant.",
          DialogueId = 71005103,
          GUID = "B1C0FA8C",
          SpeakNpcId = 818045
        },
        [71005104] = {
          ContentFR = "Tu attends un long moment à ses côtés. Pas un seul poisson ne mord à l’hameçon.",
          DialogueId = 71005104,
          GUID = "B1C0FA8D",
          NextDialogue = 71005105,
          SpeakNpcId = 800006
        },
        [71005105] = {
          ContentFR = "Tu es sûr que cela va marcher comme ça, au moins ?",
          DialogueId = 71005105,
          GUID = "B1C0FAB6",
          NextDialogue = 71005106,
          SpeakNpcId = 100001
        },
        [71005106] = {
          ContentFR = "Silence. Regarde juste.",
          DialogueId = 71005106,
          GUID = "B1C0FAE0",
          SpeakNpcId = 818045
        },
        [71005107] = {
          ContentFR = "Toujours pas un seul poisson après un long moment.",
          DialogueId = 71005107,
          GUID = "B1C0FAE1",
