        },
        [71005143] = {
          ContentFR = "Bref, désolé pour le dérangement. Tiens, c’est pour toi. Considère ça comme des excuses.",
          DialogueId = 71005143,
          GUID = "B1C0FFCC",
          SpeakNpcId = 818045
        },
        [71005201] = {
          ContentFR = "Des pièces porte-bonheur, des pièces magiques ! Venez en acheter, m’sieur, m’dame !",
          DialogueId = 71005201,
          GUID = "B1C10ACA",
          SpeakNpcId = 818046
        },
        [71005202] = {
          ContentFR = "En t’approchant, la fillette sort en hâte quelques pièces de sa poche et te les tend.",
          DialogueId = 71005202,
          GUID = "B1C10AF4",
          NextDialogue = 71005203,
          SpeakNpcId = 800006
        },
        [71005203] = {
          ContentFR = "Bonjour {性别:Monsieur|Mademoiselle} ! Tu veux une pièce porte-bonheur ? C’est maman qui me les a laissées ! Elle disait : une pièce chasse les soucis, deux pièces portent toujours bonheur, et trois... avec trois, tu peux tout réaliser !",
          DialogueId = 71005203,
          GUID = "B1C10B1E",
          NextDialogue = 71005204,
          SpeakNpcId = 818046
        },
        [71005204] = {
          ContentFR = "...",
          DialogueId = 71005204,
          GUID = "B1C10B48",
          NextDialogue = 71005205,
          SpeakNpcId = 100001
        },
        [71005205] = {
          ContentFR = "Elles sont toutes enchantées par maman, c’est vrai ! Je te mens pas ! Si tu ne me crois pas, demande aux autres ! Vas-y, vas-y, et reviens me dire si tu veux en acheter. J’attends ici.",
          DialogueId = 71005205,
          GUID = "B1C10B49",
          SpeakNpcId = 818046
        },
        [71005206] = {
          ContentFR = "Tu remarques quelques pièces porte-bonheur posées aux pieds d’un vieil homme. Tu engages la conversation avec lui.",
          DialogueId = 71005206,
          GUID = "B1C10B72",
          NextDialogue = 71005207,
          SpeakNpcId = 800006
        },
        [71005207] = {
          ContentFR = "Des pièces porte-bonheur ? Haha ! Si ça marchait vraiment, tu crois que je crèverais encore de faim, assis dans ce coin de rue ?",
          DialogueId = 71005207,
          GUID = "B1C10B73",
          NextDialogue = 71005208,
          SpeakNpcId = 818047
        },
        [71005208] = {
          ContentFR = "Mais ne le répète pas à la petite, d’accord ? Elle n’a déjà plus personne... La pauvre. Même quand quelque chose est faux, ça peut quand même donner un peu d’espoir, tu ne crois pas ?",
          DialogueId = 71005208,
          GUID = "B1C10B74",
          SpeakNpcId = 818047
        },
        [71005209] = {
          ContentFR = "Un garçon s’amuse avec quelques pièces porte-bonheur entre ses mains. Tu t’approches pour lui parler.",
          DialogueId = 71005209,
          GUID = "B1C10B9C",
          NextDialogue = 71005210,
          SpeakNpcId = 800006
        },
        [71005210] = {
          ContentFR = "Tu vois une différence entre la pièce porte-bonheur dans ma main gauche et la pièce dans ma main droite ?",
          DialogueId = 71005210,
          GUID = "B1C10B9D",
          NextDialogue = 71005211,
          SpeakNpcId = 818048
        },
        [71005211] = {
          ContentFR = "Il te montre ses deux mains. En les observant attentivement, tu confirmes qu’elles sont identiques.",
          DialogueId = 71005211,
          GUID = "B1C10B9E",
          NextDialogue = 71005212,
          SpeakNpcId = 800006
        },
        [71005212] = {
          ContentFR = "Eh oui ! Ces fameuses pièces porte-bonheur ? Ce ne sont que de simples pièces. La vraie magie, c’est la gentillesse de ceux qui les donnent.",
          DialogueId = 71005212,
          GUID = "B1C10B9F",
          NextDialogue = 71005213,
          SpeakNpcId = 818048
        },
        [71005213] = {
          ContentFR = "Et avec une seule de ces pièces porte-bonheur, tu peux offrir un sourire à cette petite fille. Des échanges aussi simples et précieux, on n’en voit pas souvent !",
          DialogueId = 71005213,
          GUID = "B1C10BA0",
          SpeakNpcId = 818048
        },
        [71005214] = {
          ContentFR = "Alors ? Tout le monde dit qu’elles marchent, pas vrai ?",
          DialogueId = 71005214,
          GUID = "B1C10BC6",
          SpeakNpcId = 818046
        },
        [71005215] = {
          ContentFR = "Hé hé, vraiment ? Eh bien, si c’est ce que tu veux, je te les vends toutes ! J’espère qu’elles t’apporteront beaucoup, beaucoup de bonheur !",
          DialogueId = 71005215,
          GUID = "B1C10BF0",
          SpeakNpcId = 818046
        },
        [71005216] = {
          ContentFR = "Par toi-même, hein... C’est trop cool ! Tu crois que moi aussi, un jour, je pourrais être comme toi ?",
          DialogueId = 71005216,
          GUID = "B1C10C1A",
          NextDialogue = 71005217,
          SpeakNpcId = 818046
        },
        [71005217] = {
          ContentFR = "Bien sûr.",
          DialogueId = 71005217,
          GUID = "B1C10C1B",
          NextDialogue = 71005218,
          SpeakNpcId = 100001
        },
        [71005218] = {
          ContentFR = "Hmm... je vais y réfléchir. Merci beaucoup !",
          DialogueId = 71005218,
          GUID = "B1C10C1C",
          SpeakNpcId = 818046
        },
        [71005301] = {
          ContentFR = "Au voleur ! Au voleur ! À l’aide, quelqu’un !",
          DialogueId = 71005301,
          GUID = "B1C11B32",
          SpeakNpcId = 818042
        },
        [71005302] = {
          ContentFR = "Dans quelle direction ?",
          DialogueId = 71005302,
          GUID = "B1C11B5C",
          NextDialogue = 71005303,
          SpeakNpcId = 100001
        },
        [71005303] = {
          ContentFR = "Là-bas ! Ils sont partis par là... snif... La cité extérieure est vraiment trop dangereuse...",
          DialogueId = 71005303,
          GUID = "B1C11B86",
          SpeakNpcId = 818042
        },
        [71005304] = {
          ContentFR = "Jackpot ! Ces gosses de la cité intérieure sont bourrés de fric ! On est tranquilles pour des mois !",
          DialogueId = 71005304,
          GUID = "B1C11C04",
          NextDialogue = 71005305,
          SpeakNpcId = 818043
        },
        [71005305] = {
          ContentFR = "Rendez ça. Tout de suite.",
          DialogueId = 71005305,
          GUID = "B1C11C2E",
          NextDialogue = 71005306,
          SpeakNpcId = 100001
        },
        [71005306] = {
          ContentFR = "Tss... {性别:Un héros de pacotille|Une héroïne de pacotille}, sérieux ? Alors tu vas voir de quel bois on se chauffe !",
          DialogueId = 71005306,
          GUID = "B1C11C58",
          SpeakNpcId = 818043
        },
        [71005307] = {
          ContentFR = "Pff... Quelle poisse aujourd’hui. On se tire !",
          DialogueId = 71005307,
          GUID = "B1C11CAC",
          SpeakNpcId = 818043
        },
        [71005308] = {
          ContentFR = "Les voleurs détalent dans toutes les directions. Tu ramasses le sac à main et réfléchis à ce que tu dois faire.",
          DialogueId = 71005308,
          GUID = "B1C11CD6",
          SpeakNpcId = 800006
        },
        [71005309] = {
          ContentFR = "On peut considérer ça comme des frais de scolarité : une leçon sur la dureté du monde. Tu prends l’argent sans hésiter, et tu es presque {性别:généreux|généreuse} de ne pas en réclamer davantage.",
          DialogueId = 71005309,
          GUID = "B1C11D2A",
          SpeakNpcId = 800006
        },
        [71005310] = {
          ContentFR = "J’ai retrouvé ton sac. C’est bien celui-là ?",
          DialogueId = 71005310,
          GUID = "B1C11D54",
          NextDialogue = 71005311,
          SpeakNpcId = 100001
        },
        [71005311] = {
          ContentFR = "Oui ! Oui — c’est ça ! Merci infiniment !",
          DialogueId = 71005311,
          GUID = "B1C11D7E",
          NextDialogue = 71005312,
          SpeakNpcId = 818042
        },
        [71005312] = {
          ContentFR = "La jeune fille essuie ses larmes, puis sort une liasse d’argent du sac et la met dans ta main.",
          DialogueId = 71005312,
          GUID = "B1C11DA8",
          NextDialogue = 71005313,
          SpeakNpcId = 800006
        },
        [71005313] = {
          ContentFR = "C’est pour te remercier. Je suis tellement soulagée de voir qu’il reste encore des Chasseurs de Phoxène aussi {性别:gentils|gentilles} que toi dans la cité extérieure... snif...",
          DialogueId = 71005313,
          GUID = "B1C11DA9",
          SpeakNpcId = 818042
        },
        [71005401] = {
          ContentFR = "Approchez-vous ! De superbes prix vous attendent, ne passez pas à côté !",
          DialogueId = 71005401,
          GUID = "B1C12B9A",
          SpeakNpcId = 818044
        },
        [71005402] = {
          ContentFR = "Eh, {性别:Chasseur de Phoxène|Chasseuse de Phoxène}, tu veux tenter ta chance ? Si tu arrives à ouvrir ce coffre, tout ce qu’il contient est pour toi !",
          DialogueId = 71005402,
          GUID = "B1C12BC4",
          SpeakNpcId = 818044
        },
        [71005403] = {
          ContentFR = "Tu entends un clic en tournant la serrure. Juste au moment où tu crois réussir... CLAC ! Le couvercle se referme brusquement. Peu importe ce que tu fais, le coffre refuse de s’ouvrir à nouveau.",
          DialogueId = 71005403,
          GUID = "B1C12C18",
          SpeakNpcId = 800006
        },
        [71005404] = {
          ContentFR = "Ah ! Tu as cassé mon coffre ! Il faut que tu rembourses ! Maintenant, donne-moi ton argent !",
          DialogueId = 71005404,
          GUID = "B1C12C42",
          NextOptions = {
            [1] = 710054041,
            [2] = 710054042
          },
          SpeakNpcId = 818044
        },
        [71005405] = {
          ContentFR = "Chut... pas si fort. J’ai d’autres... opportunités commerciales dans le coin. Écoute, prends ça, d’accord ? Et faisons comme si rien ne s’était passé.",
          DialogueId = 71005405,
          GUID = "B1C12CC0",
          NextDialogue = 71005406,
          SpeakNpcId = 818044
        },
        [71005406] = {
          ContentFR = "L’homme, conscient de son erreur, te glisse une bourse de pièces et s’éloigne, le coffre sous le bras.",
          DialogueId = 71005406,
          GUID = "B1C12CEA",
          SpeakNpcId = 800006
        },
        [71005407] = {
          ContentFR = "Tss ! Tu veux me pousser à agir, hein !",
          DialogueId = 71005407,
          GUID = "B1C12D14",
          NextDialogue = 71005408,
          SpeakNpcId = 818044
        },
        [71005408] = {
          ContentFR = "Je ne pensais pas qu’un escroc de ton genre aurait le courage de se battre... Très bien, prépare-toi à regretter ce choix.",
          DialogueId = 71005408,
          GUID = "B1C12D3E",
          SpeakNpcId = 100001
        },
        [71005409] = {
          ContentFR = "L’homme, comprenant qu’il ne peut rien faire, s’éloigne avec son coffre.",
          DialogueId = 71005409,
          GUID = "B1C12D68",
          SpeakNpcId = 800006
        },
        [71005501] = {
          ContentFR = "Toi là-bas ! {性别:Chasseur de Phoxène|Chasseuse de Phoxène}, aide-moi s’il te plaît !",
          DialogueId = 71005501,
          GUID = "B1C13C02",
          SpeakNpcId = 818049
        },
        [71005502] = {
          ContentFR = "J’ai... j’ai cru entendre quelque chose d’effrayant plus loin... tu pourrais aller voir ?",
          DialogueId = 71005502,
          GUID = "B1C13C2C",
          SpeakNpcId = 818049
        },
        [71005503] = {
          ContentFR = "Tu avances, mais rien de vraiment effrayant ne se présente. Peut-être n’était-ce qu’une illusion.",
          DialogueId = 71005503,
          GUID = "B1C13CAA",
          SpeakNpcId = 800006
        },
        [71005504] = {
          ContentFR = "Quelques Souillés rôdent en amont du canal, grognant et poussant des cris rauques. C’est sûrement ça qui a effrayé l’homme.",
          DialogueId = 71005504,
          GUID = "B1C13CFE",
          SpeakNpcId = 800006
        },
        [71005505] = {
          ContentFR = "Après les avoir mis en fuite, le silence revient. Il est temps de retourner voir l’homme.",
          DialogueId = 71005505,
          GUID = "B1C13D28",
          SpeakNpcId = 800006
        },
        [71005506] = {
          ContentFR = "Des plaques de métal sont coincées près du canal, produisant un bruit strident à chaque mouvement de l’eau. C’est probablement ce qui a effrayé l’homme.",
          DialogueId = 71005506,
          Duration = 3,
          GUID = "B1C13D52",
          NextDialogue = 71005507,
          SpeakNpcId = 800006
        },
        [71005507] = {
          ContentFR = "Tu récupères les plaques et les ranges dans ton sac. Le métal ne manque jamais d’acheteurs. Tu pourras les vendre une fois la mission terminée.",
          DialogueId = 71005507,
          GUID = "B1C13D53",
          SpeakNpcId = 800006
        },
        [71005508] = {
          ContentFR = "C’est calme maintenant... Ce bruit effrayant a disparu. Merci beaucoup !",
          DialogueId = 71005508,
          GUID = "B1C13D7C",
          SpeakNpcId = 818049
        },
        [71005601] = {
          ContentFR = "Argh... c’est coincé ! Je n’arrive pas à remonter ma ligne...",
          DialogueId = 71005601,
          GUID = "B1C14C6A",
          SpeakNpcId = 818050
        },
        [71005602] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71005602,
          GUID = "B1C14C94",
          NextDialogue = 71005603,
          SpeakNpcId = 100001
        },
        [71005603] = {
          ContentFR = "Ah ! {性别:Chasseur de Phoxène|Chasseuse de Phoxène} ! Ma ligne est emmêlée autour de quelques détritus là-dessous. Tu pourrais m’aider à la démêler ?",
          DialogueId = 71005603,
          GUID = "B1C14CBE",
          NextOptions = {
            [1] = 710056031,
            [2] = 710056032
          },
          SpeakNpcId = 818050
        },
        [71005604] = {
          ContentFR = "Parfait ! Je tiens la ligne, tu t’occupes du reste.",
          DialogueId = 71005604,
          GUID = "B1C14CE8",
          SpeakNpcId = 818050
        },
        [71005605] = {
          ContentFR = "Ouf... ça a marché, merci beaucoup !",
          DialogueId = 71005605,
          GUID = "B1C14D12",
          SpeakNpcId = 818050
        },
        [71005701] = {
          ContentFR = "À l’aide ! Hé oh ? Quelqu’un ? J’aurais vraiment besoin d’aide...",
          DialogueId = 71005701,
          GUID = "B1C15CD2",
          SpeakNpcId = 818051
        },
        [71005702] = {
          ContentFR = "Merci... euh, pourrais-tu me rendre un petit service ? En fuyant, j’ai laissé ma canne plus loin, mais il y a encore quelques Souillés...",
          DialogueId = 71005702,
          GUID = "B1C15CFC",
          NextOptions = {
            [1] = 710057021,
            [2] = 710057022
          },
          SpeakNpcId = 818051
        },
        [71005703] = {
          ContentFR = "Merci mille fois ! Je t’attends ici. Bonne chance !",
          DialogueId = 71005703,
          GUID = "B1C15D26",
          SpeakNpcId = 818051
        },
        [71005704] = {
          ContentFR = "C’est ma canne ! Merci infiniment, tu m’as sauvé la mise !",
          DialogueId = 71005704,
          GUID = "B1C15D50",
          SpeakNpcId = 818051
        },
        [71005801] = {
          ContentFR = "Hé, {性别:Chasseur de Phoxène|Chasseuse de Phoxène} ! Tu arrives juste à temps, j’ai une occasion en or que tu ne voudras pas rater.",
          DialogueId = 71005801,
          GUID = "B1C16D3A",
          SpeakNpcId = 818052
        },
        [71005802] = {
          ContentFR = "J’ai trouvé un tas d’Argentite un peu plus loin, mais c’était trop lourd pour moi. Alors, je te le laisse. Si tu veux, je peux te montrer où c’est.",
          DialogueId = 71005802,
          GUID = "B1C16D64",
          NextOptions = {
            [1] = 710058031,
            [2] = 710058032
          },
          SpeakNpcId = 818052
        },
        [71005804] = {
          ContentFR = "Parfait, suis-moi.",
          DialogueId = 71005804,
          GUID = "B1C16DB8",
          SpeakNpcId = 818052
        },
        [71005805] = {
          ContentFR = "Voici le premier tas.",
          DialogueId = 71005805,
          GUID = "B1C16DE2",
          SpeakNpcId = 818052
        },
        [71005806] = {
          ContentFR = "Il y en a encore plus loin, tu veux continuer ?",
          DialogueId = 71005806,
          GUID = "B1C16E0C",
          NextOptions = {
            [1] = 710058061,
            [2] = 710058062
          },
          SpeakNpcId = 818052
        },
        [71005807] = {
          ContentFR = "Parfait, suis-moi.",
          DialogueId = 71005807,
          GUID = "B1C16E36",
          SpeakNpcId = 818052
        },
        [71005808] = {
          ContentFR = "Voilà le deuxième tas.",
          DialogueId = 71005808,
          GUID = "B1C16E60",
          SpeakNpcId = 818052
        },
        [71005809] = {
          ContentFR = "Il y en a encore plus loin, tu veux continuer ?",
          DialogueId = 71005809,
          GUID = "B1C16E8A",
          NextOptions = {
            [1] = 710058091,
            [2] = 710058092
          },
          SpeakNpcId = 818052
        },
        [71005810] = {
          ContentFR = "Parfait, avance un peu et tu le verras.",
          DialogueId = 71005810,
          GUID = "B1C16EB4",
          SpeakNpcId = 818052
        },
        [71005811] = {
          ContentFR = "Maintenant ! À l’attaque !",
          DialogueId = 71005811,
          GUID = "B1C16EDE",
          NextDialogue = 71005812,
          SpeakNpcId = 818052
        },
        [71005812] = {
          ContentFR = "L’Argentite n’était qu’un appât, un piège monté par des voyous déguisés en mineurs. Montre-leur qu’ils se sont trompés de cible.",
          DialogueId = 71005812,
          Duration = 3,
          GUID = "B1C16F08",
          SpeakNpcId = 800006
        },
        [71005813] = {
          ContentFR = "Les voyous ont pris la fuite. Il est temps de compter le butin du jour.",
          DialogueId = 71005813,
          GUID = "B1C16F32",
          SpeakNpcId = 800006
        },
        [71005814] = {
          ContentFR = "Tss, si près du but... Euh, je veux dire... dommage pour toi. Bon, je ne te dérange pas plus, salut !",
          DialogueId = 71005814,
          GUID = "B1C16F5C",
          SpeakNpcId = 818052
        },
        [71005901] = {
          ContentFR = "Papa court trop vite, il bat tout le monde !",
          DialogueId = 71005901,
          GUID = "B1C17DA2",
          SpeakNpcId = 818053
        },
        [71005902] = {
          ContentFR = "Oh, encore un adversaire ! Tu veux défier mon papa ? Je parie que tu ne pourras pas le battre, il est super rapide !",
          DialogueId = 71005902,
          GUID = "B1C17DCC",
          NextOptions = {
            [1] = 710059021,
            [2] = 710059022
          },
          SpeakNpcId = 818053,
          bForbidSkipOptions = true
        },
        [71005903] = {
          ContentFR = "Eh bien, si c’est pour une course... d’accord. Mais avant, viens par ici, j’ai deux-trois choses à t’expliquer.",
          DialogueId = 71005903,
          GUID = "B1C17DF6",
          SpeakNpcId = 818054
        },
        [71005904] = {
          ContentFR = "Tiens, prends cet argent. Quand tu cours, fais comme si tu t’arrêtais un peu... je... je ne veux pas décevoir mon fils, alors je lui ai un peu exagéré les choses en disant que personne ne court plus vite que moi.",
          DialogueId = 71005904,
          GUID = "B1C17E20",
          NextOptions = {
            [1] = 710059041,
            [2] = 710059042
          },
          SpeakNpcId = 818054,
          bForbidSkipOptions = true
        },
        [71005905] = {
          ContentFR = "Merci... vraiment. Je te revaudrai ça.",
          DialogueId = 71005905,
          GUID = "B1C17E4A",
          SpeakNpcId = 818054
        },
        [71005906] = {
          ContentFR = "... Très bien.",
          DialogueId = 71005906,
          GUID = "B1C17E74",
          SpeakNpcId = 818054
        },
        [71005907] = {
          ContentFR = "Alors c’est parti ! Papa, courage !",
          DialogueId = 71005907,
          GUID = "B1C17E9E",
          NextDialogue = 71005908,
          SpeakNpcId = 818053
        },
        [71005908] = {
          ContentFR = "Trois...",
          DialogueId = 71005908,
          Duration = 1,
          GUID = "B1C17EC8",
          NextDialogue = 71005909,
          SpeakNpcId = 818053
        },
        [71005909] = {
          ContentFR = "Deux...",
          DialogueId = 71005909,
          Duration = 1,
          GUID = "B1C17EF2",
          NextDialogue = 71005910,
          SpeakNpcId = 818053
        },
        [71005910] = {
          ContentFR = "Un — Partez !",
          DialogueId = 71005910,
          Duration = 1,
          GUID = "B1C17F1C",
          SpeakNpcId = 818053
        },
        [71005911] = {
          ContentFR = "Ouah, papa, tu es trop fort !",
          DialogueId = 71005911,
          GUID = "B1C17F46",
          NextDialogue = 71005912,
          SpeakNpcId = 818053
        },
        [71005912] = {
          ContentFR = "Hé... Tu m’as laissé gagner, hein ? Merci pour ça. Tiens, prends ça. C’est le moins que je puisse faire.",
          DialogueId = 71005912,
          GUID = "B1C17F70",
          SpeakNpcId = 818054
        },
        [71005913] = {
          ContentFR = "Hé, ce n’est pas ce qu’on avait dit...",
          DialogueId = 71005913,
          GUID = "B1C17F9A",
          NextDialogue = 71005914,
          SpeakNpcId = 818054
        },
        [71005914] = {
          ContentFR = "Hein ? Qu’est-ce que vous aviez dit, papa ?",
          DialogueId = 71005914,
          GUID = "B1C17FC4",
          NextDialogue = 71005915,
          SpeakNpcId = 818053
        },
        [71005915] = {
          ContentFR = "Hum... rien. Pardon, fiston... j’ai perdu.",
          DialogueId = 71005915,
          GUID = "B1C17FEE",
          NextDialogue = 71005916,
          SpeakNpcId = 818054
        },
        [71005916] = {
          ContentFR = "Ce n’est pas grave, papa ! Tu as juste loupé cette fois. On gagnera la prochaine fois ! Je crois en toi !",
          DialogueId = 71005916,
          GUID = "B1C18018",
          NextDialogue = 71005917,
          SpeakNpcId = 818053
        },
        [71005917] = {
          ContentFR = "Oui... la prochaine fois. Bon, voilà ta récompense. Prends-la, tu l’as méritée.",
          DialogueId = 71005917,
          GUID = "B1C18042",
          SpeakNpcId = 818054
        },
        [71005918] = {
          ContentFR = "Désolé, fiston... j’ai perdu...",
          DialogueId = 71005918,
          GUID = "B1C1806C",
          NextDialogue = 71005919,
          SpeakNpcId = 818054
        },
        [71005919] = {
          ContentFR = "Ce n’est pas grave, papa ! Tu as juste loupé cette fois. On gagnera la prochaine fois ! Je crois en toi !",
          DialogueId = 71005919,
          GUID = "B1C18096",
          NextDialogue = 71005920,
          SpeakNpcId = 818053
        },
        [71005920] = {
          ContentFR = "Oui... la prochaine fois. Et merci, {性别:Chasseur de Phoxène|Chasseuse de Phoxène}, c’est ta récompense, tu l’as bien méritée.",
          DialogueId = 71005920,
          GUID = "B1C180C0",
