          DialogueId = 71007203,
          GUID = "B1C2533E",
          NextOptions = {
            [1] = 710072031,
            [2] = 710072032
          },
          SpeakNpcId = 818074,
          bForbidSkipOptions = true
        },
        [71007204] = {
          Content = "万分感谢，我就在这儿等你。",
          DialogueId = 71007204,
          GUID = "B1C25368",
          SpeakNpcId = 818074
        },
        [71007206] = {
          Content = "我这可都是从原产地千里迢迢运输回来的高档货，更有百年春官方认证。虽说贵了些，但一分钱绝对对得起一分货。",
          DialogueId = 71007206,
          GUID = "B1C253BC",
          SpeakNpcId = 818072
        },
        [71007207] = {
          Content = "都是日用品，高不高档有啥区别。还是我这便宜实惠的性价比更高，你说对吧。",
          DialogueId = 71007207,
          GUID = "B1C253E6",
          SpeakNpcId = 818073
        },
        [71007208] = {
          Content = "（仔细确认之后，你已经做出了选择。现在去给那位纠结的旅人提供你的宝贵建议吧。）",
          DialogueId = 71007208,
          GUID = "B1C25410",
          SpeakNpcId = 800006
        },
        [71007209] = {
          Content = "怎么样，你觉得哪家卖的更好？",
          DialogueId = 71007209,
          GUID = "B1C2543A",
          NextOptions = {
            [1] = 710072091,
            [2] = 710072092
          },
          SpeakNpcId = 818074,
          bForbidSkipOptions = true
        },
        [71007210] = {
          Content = "好，那就买他的吧！谢谢你！",
          DialogueId = 71007210,
          GUID = "B1C25464",
          SpeakNpcId = 818074
        },
        [71007301] = {
          Content = "（游荡的敌人挤满了四周，先击退它们，再去解救魔灵吧。）",
          DialogueId = 71007301,
          GUID = "B1C26352",
          SpeakNpcId = 800006
        },
        [71007302] = {
          Content = "（争斗的声响引来了更多敌人。）",
          DialogueId = 71007302,
          GUID = "B1C2637C",
          SpeakNpcId = 800006
        },
        [71007303] = {
          Content = "（附近暂时安全了，趁现在解救魔灵吧。）",
          DialogueId = 71007303,
          GUID = "B1C263A6",
          SpeakNpcId = 800006
        },
