          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527CB0"
        },
        [80020217] = {
          ContentFR = "J’ai eu cette illusion aussi, mais la réalité est bien différente.",
          DialogueId = 80020217,
          FacialId = {
