          GUID = "C8528B9E",
          NextDialogue = 80020308,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B9E"
        },
        [80020308] = {
          ContentFR = "Mais pour flâner en ville, je peux me permettre un peu plus de liberté. J’opte alors pour des tuniques claires.",
          DialogueId = 80020308,
          FacialId = {
            [1] = "93102:Happy01"
