          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C1C"
        },
        [80020311] = {
          ContentFR = "J’ajoute à ça un peu de parfum des Tisse-Étoiles, et quelques bijoux aux motifs venus d’ailleurs, de quoi me mettre de bonne humeur pour la journée.",
          DialogueId = 80020311,
