          GUID = "C8528CEE",
          NextDialogue = 80020316,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528CEE"
        },
        [80020316] = {
          ContentFR = "Alors j’ai commencé par les bases : une petite marchande de fleurs, une noble couverte de bijoux, une vieille femme chancelante... ou même, parfois, un "prince" ou une "princesse".",
