        },
        [80020417] = {
          ContentFR = "Quand j’ai quitté la Légion, on a perdu contact. Maintenant que ma vie est plus calme ici, je me demande parfois... si elle va bien.",
          DialogueId = 80020417,
          GUID = "C8529DAA",
          NextOptions = {
            [1] = 800204171
          },
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DAA"
        },
        [80020418] = {
          ContentFR = "Hein ? Hmm...",
          DialogueId = 80020418,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8529DD4",
          NextDialogue = 80020419,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DD4"
        },
        [80020419] = {
          ContentFR = "Vous avez raison. Plutôt que de rester là à couper des fleurs, autant aller la voir.",
          DialogueId = 80020419,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529DFE",
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DFE"
        },
        [80020501] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentFR = "Dès mon retour ici, vous êtes {性别:venu|venue} m’inviter à boire un verre. Dites-moi franchement, avez-vous appris quelques-uns de mes vieux tours d’agent et m’espionnez-vous en secret ?",
          DialogueId = 80020501,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C852AB72",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextOptions = {
            [1] = 800205011,
            [2] = 800205012
          },
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AB72"
        },
        [80020503] = {
          ContentFR = "Je ne faisais que plaisanter. En fait, vous êtes {性别:venu|venue} parce que vous vouliez savoir si j’avais retrouvé cette personne importante pour moi, n’est-ce pas ?",
          DialogueId = 80020503,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ABC6",
          NextDialogue = 80020504,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABC6"
        },
        [80020504] = {
          ContentFR = "Pour être honnête, non. Elle a été mutée loin de la capitale pour certaines raisons, donc je n’ai entendu parler d’elle que par des bribes venant d’autres personnes.",
          DialogueId = 80020504,
          GUID = "C852ABF0",
          NextDialogue = 80020505,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABF0"
        },
        [80020505] = {
          ContentFR = "Elle est dans une petite ville du sud, très différente d’ici où la glace et la neige règnent. Là-bas, elle peut profiter du soleil et écouter de la musique régulièrement.",
          DialogueId = 80020505,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AC1A",
          NextDialogue = 80020506,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC1A"
        },
        [80020506] = {
          ContentFR = "Je dois avouer que ça m’a un peu soulagée, car je ne savais pas trop comment la revoir... Mais savoir qu’elle va bien me rassure.",
          DialogueId = 80020506,
          GUID = "C852AC44",
          NextDialogue = 80020507,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC44"
        },
        [80020507] = {
          ContentFR = "Cela signifie que le dernier lien entre moi, la Légion et mon passé d’agent est enfin coupé.",
          DialogueId = 80020507,
          GUID = "C852AC6E",
          NextOptions = {
            [1] = 800205071,
            [2] = 800205072
          },
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC6E"
        },
        [80020508] = {
          ContentFR = "Oui, enfin.",
          DialogueId = 80020508,
          GUID = "C852AC98",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC98"
        },
        [80020509] = {
          ContentFR = "Avant oui, mais plus maintenant.",
          DialogueId = 80020509,
          GUID = "C852ACC2",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACC2"
        },
        [80020510] = {
          ContentFR = "C’est en fait un membre proche de ma famille. C’est elle qui m’a poussée à rejoindre la Légion... et c’est aussi à cause d’elle que j’en suis partie.",
          DialogueId = 80020510,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C852ACEC",
          NextDialogue = 80020511,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACEC"
        },
        [80020511] = {
          ContentFR = "Elle ne voulait pas que je fasse ce métier dangereux, mais j’ai tout fait pour lui prouver que j’étais capable, et que je pouvais partager certains de ses fardeaux.",
          DialogueId = 80020511,
          GUID = "C852AD16",
          NextDialogue = 80020512,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD16"
        },
        [80020512] = {
          ContentFR = "Le comble, c’est qu’elle et moi avons eu des missions opposées, elle devait éliminer Mlle Flora, moi, la protéger.",
          DialogueId = 80020512,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AD40",
          NextDialogue = 800205121,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD40"
        },
        [80020513] = {
          ContentFR = "Alors j’ai fui avec Mlle Flora avant que son plan d’assassinat ne démarre. Je n’avais ni le temps ni l’envie de repenser à mes jours dans la Légion ni à elle.",
          DialogueId = 80020513,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AD6A",
          NextDialogue = 80020514,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6A"
        },
        [80020514] = {
          ContentFR = "C’est seulement maintenant, que tout est un peu plus calme, et que vous êtes là pour écouter mes histoires, que tout ça m’a pesé au point de me faire perdre pied il y a peu.",
          DialogueId = 80020514,
          GUID = "C852AD6B",
          NextOptions = {
            [1] = 800205141,
            [2] = 800205142
          },
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6B"
        },
        [80020515] = {
          ContentFR = "La seule chose dont je suis sûre, c’est qu’un jour je devrai lui dire un adieu définitif. Avant, j’essayais de fuir cette réalité.",
          DialogueId = 80020515,
          GUID = "C852ADBE",
          NextDialogue = 80020516,
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADBE"
        },
        [80020516] = {
          ContentFR = "Maintenant que c’est arrivé, ça ne fait pas si mal. Je suis même soulagée de ne plus être hantée par ça.",
          DialogueId = 80020516,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ADE8",
          NextDialogue = 80020517,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADE8"
        },
        [80020517] = {
          ContentFR = "J’ai plein de choses que je veux faire : tailler des fleurs, préparer des pâtisseries, m’acheter quelques nouvelles tenues, et peut-être même danser un peu.",
          DialogueId = 80020517,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AE12",
          NextDialogue = 80020518,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE12"
        },
        [80020518] = {
          ContentFR = "Mais ce que je veux surtout, c’est vous remercier. Vous m’avez vraiment aidée à tourner la page sur ce qui me pesait le plus.",
          DialogueId = 80020518,
          GUID = "C852AE3C",
          NextOptions = {
            [1] = 800205181,
            [2] = 800205182
          },
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE3C"
        },
        [80020519] = {
          ContentFR = "Mais je dois aussi vous prévenir : maintenant que vous connaissez mon passé, cela veut dire qu’un jour, quand la Légion viendra pour moi et Mlle Flora, vous ne pourrez plus rester en dehors de tout ça.",
          DialogueId = 80020519,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AE66",
          NextDialogue = 80020520,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE66"
        },
        [80020520] = {
          ContentFR = "J’espère que vous n’êtes pas trop effrayé. On dirait que je vous ai tendu un bonbon empoisonné, non ?",
          DialogueId = 80020520,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C852AE90",
          NextDialogue = 80020521,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE90"
        },
        [80020521] = {
          ContentFR = "Rassurez-vous, moi, Hilda, la servante capable de tout, je prendrai mes responsabilités et resterai toujours à vos côtés pour vous protéger.",
          DialogueId = 80020521,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AEBA",
          SpeakNpcId = 93102,
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AEBA"
        },
        [80020522] = {
          ContentFR = "Merci, ça vous semble bizarre que je vous remercie ? C’est sincère.",
          DialogueId = 80020522,
          FacialId = {
            [1] = "93102:Happy02"
          },
          GUID = "C852AE65",
          NextDialogue = 80020519,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE65"
        },
        [80030100] = {
          ContentFR = "Les vacances, c’est précieux. Et les passer avec toi, c’est presque aussi bien que de dormir.",
          DialogueId = 80030100,
          GUID = "C878DD68"
        },
        [80030101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "Après une bonne sieste, un petit verre... Ah, rien de mieux que de ne pas bosser, c’est la vraie vie !",
          DialogueId = 80030101,
          GUID = "C858D272",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030102,
          SpeakNpcId = 94202
        },
        [80030102] = {
          ContentFR = "Ah, au fait, on m’a refilé un colis juste avant que je vienne. Je l’ai même pas encore ouvert, voyons un peu...",
          DialogueId = 80030102,
          GUID = "C858D29C",
          NextDialogue = 80030103,
          SpeakNpcId = 94202
        },
        [80030103] = {
          ContentFR = "Ça doit être le pyjama et l’encens pour dormir que j’ai demandé à mes gars... Parfait, je vais pouvoir faire une sieste tranquille après.",
          DialogueId = 80030103,
          GUID = "C858D2C6",
          NextDialogue = 80030104,
          SpeakNpcId = 94202
        },
        [80030104] = {
          ContentFR = "Hein ? C’est quoi ça... « Proposition pour optimiser les plantes décoratives de la XIIIᵉ Légion » ? « Demande d’achat d’installations de loisirs pour booster le moral des soldats » ?",
          DialogueId = 80030104,
          GUID = "C858D2F0",
          NextDialogue = 80030105,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          }
        },
        [80030105] = {
          ContentFR = "Ah, boulot, boulot... Ça a l’air ok, mais on en reparlera plus tard. Personne ne va me gâcher mes vacances. Peut-être la commandante, mais elle viendra pas ici.",
          DialogueId = 80030105,
          GUID = "C858D31A",
          NextOptions = {
            [1] = 800301051,
            [2] = 800301052
          },
          SpeakNpcId = 94202
        },
        [80030106] = {
          ContentFR = "Trouver des règles aussi pratiques, ça s’invente pas tout seul, hein.",
          DialogueId = 80030106,
          GUID = "C858D344",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          }
        },
        [80030107] = {
          ContentFR = "Hé, t’appelles ça glander ? Pas du tout.",
          DialogueId = 80030107,
          FacialId = {
            [1] = "94202:Blink"
          },
          GUID = "C858D36E",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          }
        },
        [80030108] = {
          ContentFR = "C’est mon fameux "Mode Howard énergie optimale" que j’ai inventé, un vrai boulot de titan.",
          DialogueId = 80030108,
          GUID = "C858D398",
          NextDialogue = 80030109,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030109] = {
          ContentFR = "Quand je me repose, je débranche complètement la tête du boulot, comme ça je redémarre sans stresser.",
          DialogueId = 80030109,
          GUID = "C858D3C2",
          NextDialogue = 80030110,
          SpeakNpcId = 94202
        },
        [80030110] = {
          ContentFR = "Après des années à peaufiner ça, c’est devenu redoutablement efficace.",
          DialogueId = 80030110,
          GUID = "C858D3EC",
          NextDialogue = 80030111,
          SpeakNpcId = 94202
        },
        [80030111] = {
          ContentFR = "Ça me permet de trouver la solution la plus "économe" en énergie pour n’importe quel problème, en un clin d’œil.",
          DialogueId = 80030111,
          GUID = "C858D416",
          NextDialogue = 80030112,
          SpeakNpcId = 94202
        },
        [80030112] = {
          ContentFR = "Comme cette conversation qui cache un double jeu.",
          DialogueId = 80030112,
          GUID = "C858D417",
          NextDialogue = 80030113,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030113] = {
          ContentFR = "Hein ? Je ne comprends pas.",
          DialogueId = 80030113,
          GUID = "80030113.0",
          NextDialogue = 80030114,
          SpeakNpcId = 790008
        },
        [80030114] = {
          ContentFR = "C’est un peu tard pour faire l’{性别:innocent|innocente}, non ?",
          DialogueId = 80030114,
          GUID = "C858D418",
          NextDialogue = 80030115,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030115] = {
          ContentFR = "... Dis-moi, Berenica va bien, oui ou non ?",
          DialogueId = 80030115,
          GUID = "80030115.0",
          NextDialogue = 80030116,
          SpeakNpcId = 790008
        },
        [80030116] = {
          ContentFR = "Alors c’est comme ça que s’appelle n° 0... Berenica, hein.",
          DialogueId = 80030116,
          GUID = "C858D419",
          NextDialogue = 80030117,
          SpeakNpcId = 94202
        },
        [80030117] = {
          ContentFR = "Un peu tard pour faire le naïf.",
          DialogueId = 80030117,
          GUID = "80030117.0",
          NextDialogue = 80030118,
          SpeakNpcId = 790008
        },
        [80030118] = {
          ContentFR = "Les gens malins savent qu’il faut toujours commencer par faire un peu le naïf.",
          DialogueId = 80030118,
          GUID = "C858D41A",
          NextDialogue = 80030119,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030119] = {
          ContentFR = "Mais franchement, tu peux me poser la question, ça changera rien. Même si je te disais, tu pourrais pas vérifier.",
          DialogueId = 80030119,
          GUID = "C858D41B",
          NextDialogue = 80030120,
          SpeakNpcId = 94202
        },
        [80030120] = {
          ContentFR = "Deuxièmement, avec mon "Mode Howard énergie optimale", le boulot c’est le boulot, la vie c’est la vie.",
          DialogueId = 80030120,
          GUID = "C858D41C",
          NextDialogue = 80030121,
          SpeakNpcId = 94202
        },
        [80030121] = {
          ContentFR = "La vie peut s’immiscer dans le boulot, mais pas l’inverse. Là, je suis en congé, donc je fais comme si on se voyait en pause. C’est la manière la plus "éco-énergétique" de gérer ça.",
          DialogueId = 80030121,
          GUID = "C858D41D",
          NextDialogue = 80030122,
          SpeakNpcId = 94202
        },
        [80030122] = {
          ContentFR = "Du coup, aujourd’hui ou plus tard, les discussions sur n° 0 n’avanceront pas, mais si c’est pour parler de la vie, là, je suis tout ouïe.",
          DialogueId = 80030122,
          GUID = "C858D41E",
          NextDialogue = 80030123,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030123] = {
          ContentFR = "Bon, on n’a plus rien à se dire, tu peux y aller.",
          DialogueId = 80030123,
          GUID = "C858D41F",
          NextDialogue = 80030124,
          SpeakNpcId = 790008
        },
        [80030124] = {
          ContentFR = "Je peux pas te dire où elle est, mais je garantis qu’elle est en sécurité.",
          DialogueId = 80030124,
          GUID = "C858D421",
          NextDialogue = 80030125,
          SpeakNpcId = 94202
        },
        [80030125] = {
          ContentFR = "Je peux pas vraiment croire à ta garantie.",
          DialogueId = 80030125,
          GUID = "C858D422",
          NextDialogue = 80030126,
          SpeakNpcId = 790008
        },
        [80030126] = {
          ContentFR = "Haha, les malins apprennent vite !",
          DialogueId = 80030126,
          GUID = "C858D423",
          NextDialogue = 80030127,
          SpeakNpcId = 94202
        },
        [80030127] = {
          ContentFR = "Bon, j’ai été sympa, c’est triste que ça ne soit pas apprécié... Je vais sûrement pas bien dormir demain...",
          DialogueId = 80030127,
          GUID = "C858D4BE",
          NextDialogue = 80030128,
          SpeakNpcId = 94202
        },
        [80030128] = {
          ContentFR = "Ah, je devrais essayer un congé maladie pendant mes vacances : je suis trop malade pour me reposer, donc j’allonge mes congés, ça tient la route, non ?!",
          DialogueId = 80030128,
          GUID = "C858D4E8",
          NextDialogue = 80030129,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          }
        },
        [80030129] = {
          ContentFR = "Et comme raison... je dirais que j’ai des douleurs un peu partout, surtout au niveau du cœur.",
          DialogueId = 80030129,
          GUID = "C858D512",
          NextDialogue = 80030130,
          SpeakNpcId = 94202
        },
        [80030130] = {
          ContentFR = "Je dirai que c’est à cause d’un conflit lors d’une enquête d’opinion, mais que ça s’est arrangé en privé. Peut-être que je toucherai une indemnité... Aujourd’hui a été une bonne journée.",
          DialogueId = 80030130,
          GUID = "C858D53C",
          NextDialogue = 80030131,
          SpeakNpcId = 94202
        },
        [80030131] = {
          ContentFR = "En deux secondes, t’as réussi à me prolonger les vacances. T’es vraiment {性别:un|une} super pote !",
          DialogueId = 80030131,
          GUID = "C858D566",
          NextDialogue = 80030132,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          }
        },
        [80030132] = {
          ContentFR = "J’attends avec impatience ma prochaine excuse pour... enfin, notre prochaine rencontre.",
          DialogueId = 80030132,
          GUID = "C858D590",
          SpeakNpcId = 94202
        },
        [80030201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "On dirait que tu es enfin {性别:prêt|prête} à papoter un peu de la vie, hein ?",
          DialogueId = 80030201,
          GUID = "C858E2DA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030202,
          SpeakNpcId = 94202
        },
        [80030202] = {
          ContentFR = "Bon, même si je suis en mission à Givrelac, cette rencontre, c’est pas du boulot. Faut pas croire que je suis juste de passage. J’ai pris un congé exprès pour venir boire un verre avec toi.",
          DialogueId = 80030202,
          GUID = "C858E304",
          NextDialogue = 80030203,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030203] = {
          ContentFR = "Comme excuse, j’ai dit que j’avais été invité à danser par une jeune noble de la cité intérieure.",
          DialogueId = 80030203,
          GUID = "C858E32E",
          NextDialogue = 80030204,
          SpeakNpcId = 94202
        },
        [80030204] = {
          ContentFR = "Faut pas être surpris, c’est pas la première fois qu’un jeune officier et une dame de la noblesse s’amusent un peu ensemble. Le commandement ferme les yeux là-dessus. Et puis si ça marche, ça renforce le poids de la Légion, alors ce n’est pas si mal.",
          DialogueId = 80030204,
          GUID = "C858E358",
          NextDialogue = 80030205,
          SpeakNpcId = 94202
        },
        [80030205] = {
          ContentFR = "En tant que vrai gentleman, c’est tout à fait normal que je prolonge mes congés pour ce genre de motifs.",
          DialogueId = 80030205,
          GUID = "C858E382",
          NextOptions = {
            [1] = 800302051,
            [2] = 800302052
          },
          SpeakNpcId = 94202
        },
        [80030206] = {
          ContentFR = "Tu me brises le cœur... Je vais devoir prolonger mon congé pour m’en remettre.",
          DialogueId = 80030206,
          GUID = "C858E3AC",
          NextDialogue = 80030208,
          SpeakNpcId = 94202
        },
        [80030207] = {
          ContentFR = "Ah, je vais faire comme si c’était sincère. Merci !",
          DialogueId = 80030207,
          GUID = "C858E3D6",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030208] = {
          ContentFR = "Avec le temps, j’ai compris qu’on utilise surtout "gentleman" pour taquiner, rarement pour vraiment complimenter.",
          DialogueId = 80030208,
          GUID = "C858E400",
          NextDialogue = 80030209,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030209] = {
          ContentFR = "Quand j’étais petit, mes sœurs me disaient que devenir un gentleman, c’était le but ultime pour un garçon, le sens de la vie.",
          DialogueId = 80030209,
          GUID = "C858E42A",
          NextOptions = {
            [1] = 800302091,
            [2] = 800302092
          },
          SpeakNpcId = 94202
        },
        [80030210] = {
          ContentFR = "Peut-être que tu dis ça parce que t’as une bonne image de moi... mais non, c’étaient tout sauf des dames.",
          DialogueId = 80030210,
          GUID = "C858E454",
          NextDialogue = 80030212,
          SpeakNpcId = 94202
        },
        [80030211] = {
          ContentFR = "On est tous passés par là, naïf et mignon.",
          DialogueId = 80030211,
          GUID = "C858E47E",
          NextDialogue = 80030212,
          SpeakNpcId = 94202
        },
        [80030212] = {
          ContentFR = "C’est un vieux souvenir d’enfance qui fait encore un peu mal... mais puisqu’on est potes de vacances, je peux bien t’en parler.",
          DialogueId = 80030212,
          GUID = "C858E4A8",
          NextDialogue = 80030213,
          SpeakNpcId = 94202
        },
        [80030213] = {
          ContentFR = "J’ai grandi sous la "bienveillance" de mes sœurs ! Pour survivre à leurs griffes... euh, à leur attention, j’ai dû développer des talents...",
          DialogueId = 80030213,
          GUID = "C858E4D2",
          NextOptions = {
            [1] = 800302131,
            [2] = 800302132
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030214] = {
          ContentFR = "Oui, bienveillance... mais pas beaucoup.",
          DialogueId = 80030214,
          GUID = "C858E4FC",
          NextDialogue = 80030216,
          SpeakNpcId = 94202
        },
        [80030215] = {
          ContentFR = "C’est pas que j’ai souffert, c’est la vie qui m’a malmené.",
          DialogueId = 80030215,
          GUID = "C858E526",
          NextDialogue = 80030216,
          SpeakNpcId = 94202
        },
        [80030216] = {
          ContentFR = "Elles me répétaient sans arrêt qu’un gentleman devait embrasser l’ourlet de la robe d’une dame quand ils se rencontraient, respecter les règles et cacher ses vrais sentiments.",
          DialogueId = 80030216,
          GUID = "C858E550",
          NextDialogue = 80030217,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030217] = {
          ContentFR = "J’avais à peine cinq ou six ans, j’étais pas hyper motivé, mais pour devenir un vrai gentleman, je parlais à toutes les dames que je croisais.",
          DialogueId = 80030217,
          GUID = "C858E57A",
          NextDialogue = 80030218,
          SpeakNpcId = 94202
        },
        [80030218] = {
          ContentFR = "Tu peux imaginer leurs rires derrière moi. Heureusement, le lendemain, elles m’ont dit qu’un gentleman n’avait pas besoin d’aller aussi loin.",
          DialogueId = 80030218,
          GUID = "C858E5A4",
          NextDialogue = 80030219,
          SpeakNpcId = 94202
        },
        [80030219] = {
          ContentFR = "Enfin, elles m’ont ensuite dit que c’était plutôt la main qu’il fallait embrasser, pas la robe.",
          DialogueId = 80030219,
          GUID = "C858E5CE",
          NextDialogue = 80030220,
          SpeakNpcId = 94202
        },
        [80030220] = {
          ContentFR = "Bon, plus j’y pense, plus ça me fait mal au cœur. Allez, on boit un coup à mon enfance traumatisante.",
          DialogueId = 80030220,
          GUID = "C858E5F8",
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "Je suis là, je ne pouvais pas te poser un lapin, quand même ?",
          DialogueId = 80030401,
          GUID = "C85903AA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030402,
          SpeakNpcId = 94202
        },
        [80030402] = {
          ContentFR = "Tiens, voilà le "Conteneur militaire à régulation thermique" amélioré. Je l’ai déjà testé, aucun souci... bâille...",
          DialogueId = 80030402,
          GUID = "C85903D4",
          NextDialogue = 80030403,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_Start"
          }
        },
        [80030403] = {
          ContentFR = "Mais là, je suis crevé, il faut que je trouve un endroit pour pioncer un peu. Mes congés sont presque finis, demain je peux pas aller voir la commandante Sibylle avec des cernes.",
          DialogueId = 80030403,
          GUID = "C85903FE",
          NextOptions = {
            [1] = 800304031,
            [2] = 800304032
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_End"
          }
        },
        [80030404] = {
          ContentFR = "T’as l’œil, oui, il y a un truc qui me chiffonne.",
          DialogueId = 80030404,
          GUID = "C8590428",
          NextDialogue = 80030405,
          SpeakNpcId = 94202
        },
        [80030405] = {
          ContentFR = "Puisque tu l’as remarqué, je vais pas te le cacher : j’ai fait un cauchemar.",
          DialogueId = 80030405,
          GUID = "C8590452",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202
        },
        [80030406] = {
          ContentFR = "Bien sûr que non. Tu sais combien je suis paresseux. Je refuse la plupart des invitations.",
          DialogueId = 80030406,
          GUID = "C859047C",
          NextDialogue = 80030407,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030407] = {
          ContentFR = "Pour être honnête, j’ai fait un cauchemar cette nuit, alors je ne me sens pas très bien aujourd'hui.",
          DialogueId = 80030407,
          GUID = "C85904A6",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202
        },
        [80030408] = {
          ContentFR = "Comme beaucoup d’autres, c’était encore au sujet de mon père, ce casse-pieds...",
          DialogueId = 80030408,
          GUID = "C85904D0",
          NextOptions = {
            [1] = 800304081
          },
          SpeakNpcId = 94202
        },
        [80030409] = {
          ContentFR = "Oui, c’était aussi un soldat de l’Empire. Mais maintenant... il est alité depuis plusieurs années.",
          DialogueId = 80030409,
          GUID = "C85904FA",
          NextDialogue = 80030410,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030410] = {
          ContentFR = "À l’époque où mes sœurs me dupaient pour que je devienne un gentleman, lui, il était déjà sergent dans la Légion. Il passait plus de temps au front qu’à la maison, un peu comme moi aujourd’hui.",
          DialogueId = 80030410,
          GUID = "C8590524",
          NextDialogue = 80030411,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030411] = {
          ContentFR = "Mais à la différence de moi, il était fier de son uniforme. Pour lui, la Légion était sa vraie maison, et notre foyer n’était qu’un hôtel où il pouvait se plaindre à sa guise.",
          DialogueId = 80030411,
          GUID = "C859054E",
          NextDialogue = 80030412,
          SpeakNpcId = 94202
        },
        [80030412] = {
          ContentFR = "À chaque retour, il râlait. La photo de l’Empereur était mal accrochée. Mes sœurs rentraient trop tard...",
          DialogueId = 80030412,
          GUID = "C8590578",
          NextDialogue = 80030413,
          SpeakNpcId = 94202
        },
        [80030413] = {
          ContentFR = "Mais il y avait toujours un rituel. Il m’inspectait.",
          DialogueId = 80030413,
          GUID = "C85905A2",
          NextDialogue = 80030414,
          SpeakNpcId = 94202
        },
        [80030414] = {
          ContentFR = "Il mesurait ma taille, comptait mes lectures, vérifiait si je connaissais les noms des forteresses, et demandait mes nouvelles compétences de survie.",
          DialogueId = 80030414,
          GUID = "C85905CC",
          NextDialogue = 80030415,
          SpeakNpcId = 94202
        },
        [80030415] = {
          ContentFR = "J’ai essayé de parler d’autre chose, mais rien ne l’intéressait en dehors d’être "soldat".",
          DialogueId = 80030415,
          GUID = "C85905F6",
          NextDialogue = 80030416,
          SpeakNpcId = 94202
        },
        [80030416] = {
          ContentFR = "Un jour, pour lui faire plaisir, j’ai sculpté une petite arme en bois, comme mes gadgets actuels, tout fier d’attendre ses compliments.",
          DialogueId = 80030416,
          GUID = "C8590620",
          NextDialogue = 80030417,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_Start"
          }
        },
        [80030417] = {
          ContentFR = "Mais il l’a juste jetée sur la table en disant d’un ton sévère : « Arrête ces bêtises et concentre-toi sur comment devenir un bon soldat. »",
          DialogueId = 80030417,
          GUID = "C859064A",
          NextDialogue = 80030418,
          SpeakNpcId = 94202
        },
        [80030418] = {
          ContentFR = "À ce moment-là, j’ai ressenti un froid, une douleur tranchante comme le vent dehors, invisible et insupportable.",
          DialogueId = 80030418,
          GUID = "C8590674",
          NextDialogue = 80030419,
          SpeakNpcId = 94202
        },
        [80030419] = {
          ContentFR = "Avec le temps, j’ai compris que c’était de la haine, pas très forte, mais suffisante pour voir cet homme comme un inconnu détestable.",
          DialogueId = 80030419,
          GUID = "C859069E",
          NextDialogue = 80030420,
          SpeakNpcId = 94202
        },
        [80030420] = {
          ContentFR = "Après ça, j’ai arrêté de chercher à lui plaire, ignoré ses inspections, et ses insultes.",
          DialogueId = 80030420,
          GUID = "C85906C8",
          NextDialogue = 80030421,
          SpeakNpcId = 94202
        },
        [80030421] = {
          ContentFR = "Puis un jour, il est revenu, blessé à la tête en protégeant ses hommes. Il était vivant, mais inconscient.",
          DialogueId = 80030421,
          GUID = "C85906F2",
          NextDialogue = 80030422,
          SpeakNpcId = 94202
        },
        [80030422] = {
          ContentFR = "Il n’avait pas d’économies, avait envoyé tout son salaire à la maison, et la seule chose qui l’accompagnait, c’était une médaille brillante... et une arme en bois cassée en deux.",
          DialogueId = 80030422,
          GUID = "C859071C",
          NextDialogue = 80030423,
          SpeakNpcId = 94202
        },
        [80030423] = {
          ContentFR = "Je pensais que c’était parce qu’il était déçu de moi, mais ses hommes m’ont dit qu’il gardait toujours cette arme sur lui, et qu’elle s’est cassée quand il est tombé.",
          DialogueId = 80030423,
          GUID = "C8590746",
          NextDialogue = 80030424,
          SpeakNpcId = 94202
        },
        [80030424] = {
          ContentFR = "Au fond, il m’aimait, mais sa façon de le montrer m’était insupportable.",
          DialogueId = 80030424,
          GUID = "C8590770",
          NextDialogue = 80030425,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_End"
          }
        },
        [80030425] = {
          ContentFR = "S’il avait été fier, j’aurais préféré qu’il le dise clairement, un simple encouragement aurait suffi, plutôt que de me forcer à faire ce que je n’aimais pas.",
          DialogueId = 80030425,
          GUID = "C859079A",
          NextDialogue = 80030426,
          SpeakNpcId = 94202
        },
        [80030426] = {
          ContentFR = "Même s’il ne me pousse plus, j’ai quand même rejoint la Légion comme il le voulait.",
          DialogueId = 80030426,
          GUID = "C85907C4",
          NextDialogue = 80030427,
          SpeakNpcId = 94202
        },
        [80030427] = {
          ContentFR = "Je voulais comprendre cet endroit qui a fait de lui un homme taciturne, et prouver que je pouvais m’en sortir, même sans ses reproches.",
          DialogueId = 80030427,
          GUID = "C85907EE",
          NextDialogue = 80030428,
          SpeakNpcId = 94202
        },
        [80030428] = {
          ContentFR = "Mais malheureusement, quand j’ai rejoint la Légion, j’ai compris qu’il avait raison, il voulait me protéger.",
          DialogueId = 80030428,
          GUID = "C8590818",
          NextDialogue = 80030429,
          SpeakNpcId = 94202
        },
        [80030429] = {
          ContentFR = "Nous ne sommes pas comme les autres dans la Légion. On s’est traînés hors des charniers, à genoux pour recevoir des médailles balancées comme une aumône.",
          DialogueId = 80030429,
          GUID = "C8590842",
          NextDialogue = 80030430,
          SpeakNpcId = 94202
        },
        [80030430] = {
          ContentFR = "Un boulot digne, une vie confortable, notre survie même, tout dépend de ces petites médailles. Mon père a tout donné pour notre famille.",
          DialogueId = 80030430,
          GUID = "C859086C",
          NextDialogue = 80030431,
          SpeakNpcId = 94202
        },
        [80030431] = {
          ContentFR = "Il a obéi, supporté, caché ses émotions, s’est habitué à la douleur et aux pleurs, et s’est fait une carapace.",
          DialogueId = 80030431,
          GUID = "C8590896",
          NextDialogue = 80030432,
          SpeakNpcId = 94202
        },
        [80030432] = {
          ContentFR = "Moi, je ne peux pas faire ça. Mais j’ai besoin d’argent pour vivre et maintenir la dignité de ma famille. Du coup, je reste là, suspendu entre deux mondes, un raté heureux.",
          DialogueId = 80030432,
          GUID = "C85908C0",
          NextOptions = {
            [1] = 800304321
          },
          SpeakNpcId = 94202
        },
        [80030433] = {
          ContentFR = "...",
          DialogueId = 80030433,
          GUID = "C85908EA",
          NextDialogue = 80030434,
          SpeakNpcId = 94202
        },
        [80030434] = {
          ContentFR = "Tu es vraiment perspicace. Pour être honnête, j’ai longtemps été perdu.",
          DialogueId = 80030434,
          GUID = "C8590914",
          NextDialogue = 80030435,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030435] = {
          ContentFR = "Même si mon choix diffère de ce qu’il voulait, je ne regrette pas ma vie.",
          DialogueId = 80030435,
          GUID = "C859093E",
          NextOptions = {
            [1] = 800304351,
            [2] = 800304352
          },
          SpeakNpcId = 94202
        },
        [80030436] = {
          ContentFR = "J’espère bien. Si ça arrive, mes cauchemars pourront enfin s’arrêter.",
          DialogueId = 80030436,
          GUID = "C8590968",
          NextDialogue = 80030438,
          SpeakNpcId = 94202
        },
        [80030437] = {
          ContentFR = "Excellent, avec ça je devrais enfin dormir sans cauchemars.",
          DialogueId = 80030437,
          GUID = "C8590992",
          NextDialogue = 80030438,
          SpeakNpcId = 94202
        },
        [80030438] = {
          ContentFR = "Merci, {性别:mon|ma} pote de vacances, mais maintenant je dois dormir un peu, sinon je vais devoir demander un autre jour de congé demain.",
          DialogueId = 80030438,
          GUID = "C85909BC",
          NextDialogue = 80030439,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030439] = {
          ContentFR = "T’inquiète, la prochaine fois qu’on se voit, je serai le Randy que tu connais. Et si je fais encore un cauchemar, je compte sur toi pour me préparer un autre verre.",
          DialogueId = 80030439,
          GUID = "C85909E6",
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030501] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "Un petit remontant, bien sucré s’il te plaît. Et tiens, j’ai ramené quelques douceurs de l’Empire. J’ai fait la queue pendant mon jour de repos... Goûte-moi ça.",
          DialogueId = 80030501,
          GUID = "C8591412",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextOptions = {
            [1] = 800305011,
            [2] = 800305012
          },
          SpeakNpcId = 94202
        },
        [80030502] = {
          ContentFR = "Exactement. Une boisson sucrée, pour adoucir... une petite requête.",
          DialogueId = 80030502,
          GUID = "C859143C",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030503] = {
          ContentFR = "Quoi ?! Pas du tout ! Bon... ok, j’ai bel et bien une petite faveur à te demander. Mais c’est pas un piège, promis.",
          DialogueId = 80030503,
          GUID = "C8591466",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030504] = {
          ContentFR = "Ahem... Je sais que ça sort de nulle part, mais... ça te dirait de m’accompagner au bal ?",
          DialogueId = 80030504,
          GUID = "C8591490",
          NextDialogue = 80030505,
          SpeakNpcId = 94202
        },
        [80030505] = {
          ContentFR = "Tu sais, ces soirées diplomatiques dans la cité intérieure, avec la noblesse et tout le cirque, des événements indispensables pour que la Légion conserve de bonnes relations avec les pouvoirs locaux.",
          DialogueId = 80030505,
          GUID = "C85914BA",
          NextDialogue = 80030506,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02_Start"
          }
        },
        [80030506] = {
          ContentFR = "Franchement, j’ai zéro envie d’y aller. Même en mission officielle, devoir sourire à la noblesse, c’est juste insupportable.",
          DialogueId = 80030506,
          GUID = "C85914E4",
          NextDialogue = 80030507,
          SpeakNpcId = 94202
        },
        [80030507] = {
          ContentFR = "Du coup, j’ai eu une idée de génie : Y aller au bras d’une partenaire splendide.",
          DialogueId = 80030507,
          GUID = "C859150E",
          NextDialogue = 80030508,
          SpeakNpcId = 94202
        },
        [80030508] = {
          ContentFR = "Comme ça, personne n’osera m’interrompre pour me présenter leurs cousines célibataires qu’ils ont vues trois fois dans leur vie.",
          DialogueId = 80030508,
          GUID = "C8591538",
          NextOptions = {
            [1] = 800305081,
            [2] = 800305082
          },
          SpeakNpcId = 94202
        },
        [80030509] = {
          ContentFR = "Eh bien... je me disais... peut-être... tu pourrais envisager un petit déguisement ?",
          DialogueId = 80030509,
          GUID = "C8591562",
          NextOptions = {
            [1] = 800305091,
            [2] = 800305092
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02_End"
          }
        },
        [80030510] = {
          ContentFR = " Je ne peux pas. C’est moi l’invité, après tout.",
          DialogueId = 80030510,
          GUID = "C859158C",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030511] = {
          ContentFR = "Je t’en prie, j’ai épuisé toutes mes options. T’es ma dernière chance.",
          DialogueId = 80030511,
          GUID = "C85915B6",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030512] = {
          ContentFR = "On a bu combien de fois ensemble, hein ? Pour moi, t’es déjà plus proche que mes propres sœurs ! C’est justement parce que t’es mon meilleur pote que je te le demande.",
          DialogueId = 80030512,
          GUID = "C85915E0",
          NextDialogue = 80030513,
          SpeakNpcId = 94202
        },
        [80030513] = {
          ContentFR = "Allez, arrête de faire cette tête. Si tu m’aides, je te file la moitié de mon salaire pendant six mois ! Et si la commandante Sibylle essaie encore de t’arrêter, je me sacrifierai pour te couvrir !",
          DialogueId = 80030513,
          GUID = "C859160A",
          NextDialogue = 80030514,
          SpeakNpcId = 94202
        },
        [80030514] = {
          ContentFR = "Et si ça ne te suffit pas, je me mettrai moi-même en robe après le bal, rien que pour toi. Ça te va ?",
          DialogueId = 80030514,
          GUID = "C8591634",
          NextOptions = {
            [1] = 800305141,
            [2] = 800305142
          },
          SpeakNpcId = 94202
        },
        [80030515] = {
          ContentFR = "Non, non, non ! Tu te méprends complètement, c’est pas du tout ce que tu crois !",
          DialogueId = 80030515,
          GUID = "C859165E",
          NextDialogue = 80030516,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030516] = {
          ContentFR = "Je veux dire, c’est normal, non ? Entre vrais potes, on fait tout ensemble : sortir, manger, aller aux toilettes et essayer des robes. C’est ça, l’amitié !",
          DialogueId = 80030516,
          GUID = "C8591688",
          NextOptions = {
            [1] = 800305161
          },
          SpeakNpcId = 94202
        },
        [80030517] = {
          ContentFR = "Allez, rigole pas... je suis vraiment en détresse là. Dis-moi juste si t’acceptes, sinon je vais devoir me creuser la tête pour un autre plan...",
          DialogueId = 80030517,
          GUID = "C85916B2",
          NextOptions = {
            [1] = 800305171,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030518] = {
          ContentFR = "Réfléchis encore un peu, hein...",
          DialogueId = 80030518,
          GUID = "C85916DC",
          NextDialogue = 80030519,
          SpeakNpcId = 94202
        },
        [80030519] = {
          ContentFR = "Attends... tu dis que tu acceptes ? Sérieux ? T’es un vrai frère, même si on est pas de la même famille !",
          DialogueId = 80030519,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591706",
          NextDialogue = 80030520,
          SpeakNpcId = 94202
        },
        [80030520] = {
          ContentFR = "Je te dois une fière chandelle. Je vais devoir me creuser la tête pour te la rendre.",
          DialogueId = 80030520,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591730",
          NextDialogue = 80030521,
          SpeakNpcId = 94202
        },
        [80030521] = {
          ContentFR = "Mais bon, on verra ça après le bal. Pour l’instant, faut que je file préparer ma tenue avant que tu reviennes sur ta décision. ",
          DialogueId = 80030521,
          GUID = "C859175A",
          NextDialogue = 80030522,
          SpeakNpcId = 94202
        },
        [80030522] = {
          ContentFR = "Allez, à plus, mon complice de pause, mon partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
          DialogueId = 80030522,
          GUID = "C8591784",
          SpeakNpcId = 94202
        },
        [80030523] = {
          ContentFR = "Je comprends. Mais n’oublie pas. Après le bal, je trouverai toutes sortes de façons créatives pour te rendre la pareille, comme quand je cherche des excuses pour poser des congés.",
          DialogueId = 80030523,
          GUID = "C85917AE",
          NextDialogue = 80030524,
          SpeakNpcId = 94202
        },
        [80030524] = {
          ContentFR = "Pour l’instant, je vais me calmer un peu et te laisser de l’espace pour y penser. Cela dit, j’espère vraiment que tu accepteras, et je suis sûr que tu le feras !",
          DialogueId = 80030524,
          GUID = "C85917D8",
          NextDialogue = 80030525,
          SpeakNpcId = 94202
        },
        [80030525] = {
          ContentFR = "Bon, je file alors. J’attends de tes nouvelles, mon complice de pause, mon partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
          DialogueId = 80030525,
          GUID = "C8591802",
          SpeakNpcId = 94202
        },
        [80030526] = {
          ContentFR = "Exact. Tu es clairement la meilleure partenaire pour ce bal... Alors, tu veux bien me filer un coup de main et me sortir de ce pétrin ?",
          DialogueId = 80030526,
          GUID = "C8591856",
          NextOptions = {
            [1] = 800305261
          },
          SpeakNpcId = 94202
        },
        [80030527] = {
          ContentFR = "Hein ?",
          DialogueId = 80030527,
          GUID = "C8591880",
          NextDialogue = 80030528,
          SpeakNpcId = 94202
        },
        [80030528] = {
          ContentFR = "Quoi ?! Comment tu peux penser ça ? Si je voulais vraiment t’arrêter, je l’aurais déjà fait la première fois qu’on s’est vus !",
          DialogueId = 80030528,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C85918AA",
          NextDialogue = 80030529,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030529] = {
          ContentFR = "Pas besoin de poser mes précieux jours de congé juste pour organiser une "soirée piège".",
          DialogueId = 80030529,
          GUID = "C85918D4",
          NextDialogue = 80030530,
          SpeakNpcId = 94202
        },
        [80030530] = {
          ContentFR = "Et puis, même si je voulais te piéger, t’inviter à danser, ce serait bizarre, non ? Et si tu disais non ?",
          DialogueId = 80030530,
          GUID = "C85918FE",
          NextDialogue = 80030531,
          SpeakNpcId = 94202
        },
        [80030531] = {
          ContentFR = "Rassure-moi, c’était une blague ? Sinon, tu me prends vraiment pour un idiot sans scrupules, prêt à trahir mes amis pour avancer...",
          DialogueId = 80030531,
          GUID = "C8591928",
          NextOptions = {
            [1] = 800305311,
            [2] = 800305312
          },
          SpeakNpcId = 94202
        },
        [80030532] = {
          ContentFR = "Ouf... Parce que si tu pensais vraiment ça de moi, je crois que je prendrais un mois d’arrêt maladie juste pour m’en remettre.",
          DialogueId = 80030532,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591952",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030533] = {
          ContentFR = "Hé, au moins nie la partie où je trahis mes amis pour une promotion, ça ferait moins mal à mon petit cœur !",
          DialogueId = 80030533,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C859197C",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030534] = {
          ContentFR = "Mais maintenant, une chose est sûre : tu n’as jamais vraiment eu peur du danger.",
          DialogueId = 80030534,
          GUID = "C85919A6",
          NextDialogue = 80030535,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030535] = {
          ContentFR = "Tu faisais juste une blague, en imaginant le pire scénario, pour voir ma réaction.",
          DialogueId = 80030535,
          GUID = "C85919D0",
          NextOptions = {
            [1] = 800305351,
            [2] = 800305352
          },
          SpeakNpcId = 94202
        },
        [80030536] = {
          ContentFR = "Je croyais que j’étais le seul à être aussi joueur et taquin, mais toi aussi, hein ? D’où tu sors ça ?",
          DialogueId = 80030536,
          GUID = "C85919FA",
          NextDialogue = 80030537,
          SpeakNpcId = 94202
        },
        [80030537] = {
          ContentFR = "J’avoue, j’ai eu un moment de doute. Même si je savais que c’était impossible, au fond, j’ai flippé, et si c’était vrai ?",
          DialogueId = 80030537,
          GUID = "C8591A24",
          NextDialogue = 80030538,
          SpeakNpcId = 94202
        },
        [80030538] = {
          ContentFR = "Alors, pour compenser ta blague, tu dois accepter mon invitation.",
          DialogueId = 80030538,
          GUID = "C8591A4E",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030539] = {
          ContentFR = "Quoi ?!",
          DialogueId = 80030539,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591A78",
          NextDialogue = 80030540,
          SpeakNpcId = 94202
        },
        [80030540] = {
          ContentFR = "Bon, tu as raison ! J’ai toujours voulu t’arrêter, matin et soir, dès que mon cerveau était réveillé, j’y pensais ! Mais je procrastine tellement que je n’ai jamais passé à l’acte.",
          DialogueId = 80030540,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591AA2",
          NextDialogue = 80030541,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030541] = {
          ContentFR = "Cette fois, je voulais vraiment faire le boulot, mais tu m’as démasqué... Que faire ?",
          DialogueId = 80030541,
          GUID = "C8591ACC",
          NextDialogue = 80030542,
          SpeakNpcId = 94202
        },
        [80030542] = {
          ContentFR = "Je finirai par me faire virer de la Légion, à errer dans les rues glaciales de Givrelac, seul, affamé, sans abri...",
          DialogueId = 80030542,
          GUID = "C8591AF6",
          NextDialogue = 80030543,
          SpeakNpcId = 94202
        },
        [80030543] = {
          ContentFR = "Tu veux vraiment me voir finir en statue de glace sur le trottoir ?",
          DialogueId = 80030543,
          GUID = "C8591B20",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030544] = {
          ContentFR = "Réfléchis encore un peu, hein...",
          DialogueId = 80030544,
          GUID = "C8591B4A",
          NextDialogue = 80030545,
          SpeakNpcId = 94202
        },
        [80030545] = {
          ContentFR = "Attends... tu dis que tu acceptes ? Sérieux ? T’es une vraie sœur, même si on n’est pas de la même famille !",
          DialogueId = 80030545,
          GUID = "C8591B74",
          NextDialogue = 80030546,
          SpeakNpcId = 94202
        },
        [80030546] = {
          ContentFR = "Je te dois une fière chandelle. Je vais devoir me creuser la tête pour te la rendre.",
          DialogueId = 80030546,
          GUID = "C8591B9E",
          NextDialogue = 80030547,
          SpeakNpcId = 94202
        },
        [80030547] = {
          ContentFR = "Mais bon, on verra ça après le bal. Pour l’instant, faut que je file préparer ma tenue avant que tu ne reviennes sur ta décision.",
          DialogueId = 80030547,
          GUID = "C8591BC8",
          NextDialogue = 80030548,
          SpeakNpcId = 94202
        },
        [80030548] = {
          ContentFR = "Allez, à plus, ma complice de pause, ma partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
          DialogueId = 80030548,
          GUID = "C8591BF2",
          SpeakNpcId = 94202
        },
