        },
        [80040106] = {
          Camera = "98.562256,-40.027588,134.129395,-0.000519,-2.40243,174.925446,40.0,252.474731,false,Manual,18.208658",
          ContentFR = "L’an dernier, quand on a croisé ce grand grenadier, tu en as cueilli un sac entier... puis tout est tombé dans la vallée. Tu avais dit : « Quel gâchis ».",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040106,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "104.528809,-40.557373,134.380737,-0.000519,-2.40243,174.925446,40.0,252.474731,false,Manual,18.208658",
          GUID = "C85F3BE4",
          NextDialogue = 80040107,
          Scripts = "PARA{\nSEQ{PlayAnimation{ActorId{790007},AnimationId{\"Explain01_Start\"},Duration{2}},PlayAnimation{ActorId{790007},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{\"Disagree\"},Duration{1}}},\nSEQ{\nCameraMoveTo{_delay{10},TargetPosition{\"-29.085938,-97.268799,147.981201,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-29.085938,-97.268799,150.180298,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786\"},duration{8}}\n}\n}",
          SpeakNpcId = 790007,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3BE4"
        },
        [80040107] = {
          ContentFR = "Alors cette fois, j’en ai pris exprès rien que pour toi... Tu n’aimes plus ça, maintenant ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040107,
          FacialId = {
            [1] = "790008:Smile01"
          },
          GUID = "C85F3C0E",
          NextDialogue = 80040108,
          Scripts = "SEQ{\nCameraMoveTo{_delay{8.01},TargetPosition{\"-187.269043,-90.881348,151.269409,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-178.94751,-87.67041,150.519897,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205\"},duration{8}}\n}",
          SpeakNpcId = 790007,
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C0E"
        },
        [80040108] = {
          ContentFR = "Ce n’est pas ça. C’est juste que poisson et fruit... niveau goût, c’est un peu étrange, non ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040108,
          GUID = "C85F3C38",
          NextDialogue = 80040109,
          SpeakNpcId = 790008,
          TalkActionId = {
