        [80040410] = {
          Camera = "40.396484,533.094727,40.722107,0.000072,-4.601348,-103.414253,45.0,563.736694,false,Manual,7.664447",
          ContentFR = "Pas de fièvre, ta respiration est régulière... On dirait que tu t’es juste {性别:épuisé et que tu t’es endormi|épuisée et que tu t’es endormie}. C’est normal, tu as beaucoup souffert ces derniers jours.",
