        [80050100] = {
          ContentFR = "{性别:Monsieur|Mademoiselle} Licorne, tu fais une petite fête ? Je peux venir aussi ?",
          DialogueId = 80050100,
          GUID = "C865A388",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A388"
        },
        [80050101] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentFR = "Bonjour, {性别:Monsieur|Mademoiselle} Licorne. Je viens de recevoir un cadeau génial du Grand Magicien. Tu veux voir ?",
          DialogueId = 80050101,
          GUID = "C865A3B2",
          NextOptions = {
            [1] = 80050102
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A3B2"
        },
        [80050102] = {
          ContentFR = "Qu’est-ce que c’est ?",
          DialogueId = 80050102,
          GUID = "C865A3DC",
          NextDialogue = 80050103
        },
        [80050103] = {
          ContentFR = "Ce sont des blocs de construction.",
          DialogueId = 80050103,
          GUID = "C865A406",
          NextDialogue = 80050104,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A406"
        },
        [80050104] = {
          ContentFR = "Regarde, ces blocs, à première vue ils se ressemblent, mais si tu regardes bien, chaque pièce a une forme, une couleur, un motif un peu différents !",
          DialogueId = 80050104,
          GUID = "C865A430",
          NextDialogue = 80050105,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A430"
        },
        [80050105] = {
          ContentFR = "J’ai compté, il y a plus d’une douzaine de types différents dans cette boîte !",
          DialogueId = 80050105,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865A45A",
          NextOptions = {
            [1] = 80050106
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A45A"
        },
        [80050106] = {
          ContentFR = "Mais ce ne sont pas des douilles de cartouche, plutôt ?",
          DialogueId = 80050106,
          GUID = "C865A484",
          NextDialogue = 80050107
        },
        [80050107] = {
          ContentFR = "Hmm… alors ces blocs s’appellent « douilles » ? Tu sais beaucoup de choses ! Merci de me l’avoir dit. En échange, je vais te montrer comment les assembler, c’est super amusant !",
          DialogueId = 80050107,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865A4AE",
          NextDialogue = 80050108,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A4AE"
        },
        [80050108] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentFR = "Regarde, comme ça, ça fait un petit pistolet...",
          DialogueId = 80050108,
          GUID = "C865A4D8",
          IsBlack = 1,
          NextDialogue = 80050109,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/invite/feina_bullet_to_gun"},PlayAs2D{true}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A4D8"
        },
        [80050109] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentFR = "Et comme ça, un gros canon, boum boum boum !",
          DialogueId = 80050109,
          GUID = "C865A502",
          IsBlack = 1,
          NextDialogue = 80050110,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/invite/feina_bullet_to_cannon"},PlayAs2D{true}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A502"
        },
        [80050110] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentFR = "Maintenant c’est un dirigeable !",
          DialogueId = 80050110,
          GUID = "C865A52C",
          IsBlack = 1,
          NextOptions = {
            [1] = 80050111
          },
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/invite/feina_bullet_to_engine"},PlayAs2D{true}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A52C"
        },
        [80050111] = {
          ContentFR = "C’est l’Étranger qui t’a appris tout ça, pas vrai ?",
          DialogueId = 80050111,
          GUID = "C865A556",
          NextDialogue = 80050112
        },
        [80050112] = {
          ContentFR = "Oui ! Il m’a montré plein de façons de monter tout ça, comme faire un gros robot en blocs, avec des missiles qui sortent des épaules, et de grandes ailes dans le dos...",
          DialogueId = 80050112,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865A580",
          NextDialogue = 80050113,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A580"
        },
        [80050113] = {
          ContentFR = "Et les poings ! Les poings peuvent aussi être lancés ! Je vais te montrer !",
          DialogueId = 80050113,
          GUID = "C865A5AA",
          NextDialogue = 80050114,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Give"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A5AA"
        },
        [80050114] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          DialogueId = 80050114,
          GUID = "C865A5AB",
          IsBlack = 1,
          NextDialogue = 80050115,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/invite/feina_bullet_to_punch"},PlayAs2D{true}}"
        },
        [80050115] = {
          ContentFR = "... Ouf, c’est compliqué à faire... mais ça y est, c’est fini !",
          DialogueId = 80050115,
          GUID = "C865A5FE",
          NextDialogue = 80050116,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A5FE"
        },
        [80050116] = {
          ContentFR = "Je savais pas qu’on pouvait jouer comme ça avec des douilles, laisse-moi voir...",
          DialogueId = 80050116,
          GUID = "C865A628",
          NextDialogue = 80050117,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A628"
        },
        [80050117] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          DialogueId = 80050117,
          GUID = "C865A629",
          IsBlack = 1,
          NextDialogue = 80050118,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/invite/break_bullet_building"},PlayAs2D{true}}"
        },
        [80050118] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentFR = "Oh non, ça s’est cassé...",
          DialogueId = 80050118,
          GUID = "C865A67C",
          IsBlack = 1,
          NextDialogue = 80050119,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A67C"
        },
        [80050119] = {
          ContentFR = "... Ah...",
          DialogueId = 80050119,
          FacialId = {
            [1] = "790017:Sad02"
          },
          GUID = "C865A6A6",
          NextOptions = {
            [1] = 80050120
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A6A6"
        },
        [80050120] = {
          ContentFR = "Ne pleure pas ! Je vais te donner un autre cadeau pour me faire pardonner.",
          DialogueId = 80050120,
          GUID = "C865A6D0",
          NextDialogue = 80050121
        },
        [80050121] = {
          ContentFR = "Hmm... laisse-moi réfléchir...",
          DialogueId = 80050121,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865A6FA",
          NextDialogue = 80050122,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A6FA"
        },
        [80050122] = {
          ContentFR = "{性别:Monsieur|Mademoiselle} Licorne, pourrais-tu exaucer quatre de mes vœux ? On dit que les licornes peuvent réaliser n’importe quel souhait, alors je suis sûre que toi aussi !",
          DialogueId = 80050122,
          GUID = "C865A724",
          NextOptions = {
            [1] = 80050123,
            [2] = 80050124,
            [3] = 80050125
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A724"
        },
        [80050123] = {
          ContentFR = "Bien sûr, si je peux.",
          DialogueId = 80050123,
          GUID = "C865A74E",
          NextDialogue = 80050126
        },
        [80050124] = {
          ContentFR = "J’ai comme l’impression de me faire avoir...",
          DialogueId = 80050124,
          GUID = "C865A778",
          NextDialogue = 80050126
        },
        [80050125] = {
          ContentFR = "D’habitude c’est trois vœux, pas quatre, non ?",
          DialogueId = 80050125,
          GUID = "C865A7A2",
          NextDialogue = 80050126
        },
        [80050126] = {
          ContentFR = "Hihi...",
          DialogueId = 80050126,
          FacialId = {
            [1] = "790017:Satisfy01"
          },
          GUID = "C865A7CC",
          NextOptions = {
            [1] = 80050127
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A7CC"
        },
        [80050127] = {
          ContentFR = "D’accord, alors quel est ton premier vœu ?",
          DialogueId = 80050127,
          GUID = "C865A7F6",
          NextDialogue = 80050128
        },
        [80050128] = {
          ContentFR = "Je veux apprendre la magie ! Je connais juste un peu les bases, mais je ne sais pas vraiment comment m’en servir... {性别:Monsieur|Mademoiselle} Licorne, tu peux m’enseigner ?",
          DialogueId = 80050128,
          FacialId = {
            [1] = "790017:Smile02"
          },
          GUID = "C865A820",
          NextOptions = {
            [1] = 80050129,
            [2] = 80050132
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A820"
        },
        [80050129] = {
          ContentFR = "Pourquoi ne pas demander à l’Étranger de t’apprendre ?",
          DialogueId = 80050129,
          GUID = "C865A84A",
          NextDialogue = 80050130
        },
        [80050130] = {
          ContentFR = "Il veut pas, et il me laisse pas lire les livres de magie, il les a mis tout en haut d’une étagère, j’arrive même pas à les atteindre en me mettant sur la pointe des pieds.",
          DialogueId = 80050130,
          GUID = "C865A874",
          NextDialogue = 80050131,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A874"
        },
        [80050131] = {
          ContentFR = "Alors, quand il n’est pas là, j’empile des chaises pour prendre un livre en cachette, chut, ça reste entre nous, hein ?",
          DialogueId = 80050131,
          GUID = "C865A89E",
          NextDialogue = 80050138,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A89E"
        },
        [80050132] = {
          ContentFR = "Je fais payer les cours, tu sais.",
          DialogueId = 80050132,
          GUID = "C865A8C8",
          NextDialogue = 80050133
        },
        [80050133] = {
          ContentFR = "Hein ? Euh, attends... un gros pot de guimauves, ça irait ?",
          DialogueId = 80050133,
          FacialId = {
            [1] = "790017:Shock02"
          },
          GUID = "C865A8F2",
          NextDialogue = 80050134,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A8F2"
        },
        [80050134] = {
          ContentFR = "Mais puisque c’est ton vœu, je vais le faire gratuitement.",
          DialogueId = 80050134,
          GUID = "C865A91C",
          NextDialogue = 80050135,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A91C"
        },
        [80050135] = {
          ContentFR = "Youpi !",
          DialogueId = 80050135,
          FacialId = {
            [1] = "790017:Happy01"
          },
          GUID = "C865A946",
          NextDialogue = 80050136,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A946"
        },
        [80050136] = {
          ContentFR = "L’Étranger veut pas, et il me laisse pas lire les livres de magie, il les a mis tout en haut d’une étagère, j’arrive même pas à les atteindre en me mettant sur la pointe des pieds.",
          DialogueId = 80050136,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865A970",
          NextDialogue = 80050137,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A970"
        },
        [80050137] = {
          ContentFR = "Alors, quand il n’est pas là, j’empile des chaises pour prendre un livre en cachette, chut, ça reste entre nous, hein ?",
          DialogueId = 80050137,
          GUID = "C865A99A",
          NextDialogue = 80050138,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A99A"
        },
        [80050138] = {
          ContentFR = "Il dit toujours que pour apprendre la magie, il faut quitter le confort de la maison, s’éloigner du feu chaud pour aller dans la steppe, une terre dure et sauvage...",
          DialogueId = 80050138,
          GUID = "C865A9C4",
          NextDialogue = 80050139,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A9C4"
        },
        [80050139] = {
          ContentFR = "Là-bas, il y a plein de loups des neiges avec des yeux verts terrifiants, et des sorcières des marais sur leurs balais, couvertes de poison.",
          DialogueId = 80050139,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865A9EE",
          NextOptions = {
            [1] = 80050140,
            [2] = 80050143
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A9EE"
        },
        [80050140] = {
          ContentFR = "Il exagère pour te faire peur, ce n’est pas si terrible.",
          DialogueId = 80050140,
          GUID = "C865AA18",
          NextDialogue = 80050141
        },
        [80050141] = {
          ContentFR = "Ah... je le savais ! Il a juste peur que je tombe malade ou que je me blesse. Mais si je ne guéris jamais... je ne veux pas rester couchée à rien faire, être un poids pour lui.",
          DialogueId = 80050141,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865AA42",
          NextDialogue = 80050142,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AA42"
        },
        [80050142] = {
          ContentFR = "Je veux devenir une enfant utile. Je ne veux plus être détestée.",
          DialogueId = 80050142,
          GUID = "C865AA6C",
          NextDialogue = 80050145,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AA6C"
        },
        [80050143] = {
          ContentFR = "Il y a des choses bien plus terrifiantes que les loups des neiges et les sorcières des marais.",
          DialogueId = 80050143,
          GUID = "C865AA96",
          NextDialogue = 80050144
        },
        [80050144] = {
          ContentFR = "Alors, je ne peux pas vous laisser y aller seuls. Je dois apprendre la magie pour vous aider.",
          DialogueId = 80050144,
          GUID = "C865AAC0",
          NextDialogue = 80050145,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AAC0"
        },
        [80050145] = {
          ContentFR = "Alors, s’il te plaît, apprends-moi ! Je promets de garder ça secret.",
          DialogueId = 80050145,
          FacialId = {
            [1] = "790017:Confident02"
          },
          GUID = "C865AAEA",
          NextOptions = {
            [1] = 80050146
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AAEA"
        },
        [80050146] = {
          ContentFR = "D’accord, on va commencer tout de suite.",
          DialogueId = 80050146,
          GUID = "C865AB14",
          NextDialogue = 80050147
        },
        [80050147] = {
          ContentFR = "Youpi ! Tu es {性别:le meilleur et le plus gentil Monsieur Licorne|la meilleure et la plus gentille Mademoiselle Licorne} du monde entier !",
          DialogueId = 80050147,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865AB3E",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AB3E"
        },
        [80050201] = {
          Camera = "364.267578,-629.911316,141.387695,0.0,0.0,123.199776,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mon deuxième vœu, c’est que tu m’emmènes en cachette hors de la ville, {性别:Monsieur|Mademoiselle} Licorne... Je veux voir les vraies étoiles.",
          DialogueId = 80050201,
          Duration = 5,
          GUID = "C865B41A",
          IsBlack = 1,
          NextDialogue = 80050202,
          Scripts = "PlayAnimation{_click{false},_delay{5},ActorId{790017},AnimationId{"Disagree"},Duration{1}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B41A"
        },
        [80050202] = {
          Camera = "198.488281,-216.339706,-7.433838,0.000016,4.399113,131.781357,18.0,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Le ciel est si vaste, si haut. Il y en a plein, elles brillent tellement... c’est magnifique...",
          DialogueId = 80050202,
          FinalCamera = "164.765625,-177.972809,-5.608887,0.000038,26.398823,132.182083,18.0,100000.0,false,DoNotOverride,22.0",
          GUID = "C865B444",
          NextDialogue = 80050203,
          SpeakNpcId = 790017,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B444"
        },
        [80050203] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "En ville, même quand il ne neige pas, le ciel est enfermé par les murs et les toits... On ne voit qu’un tout petit bout. C’est jamais assez...",
          DialogueId = 80050203,
          GUID = "C865B46E",
          NextDialogue = 80050204,
          SpeakNpcId = 790017,
          TurnTo = {
            [1] = "790017:n(100001)",
            [2] = "100001:n(790017)"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B46E"
        },
        [80050204] = {
          ContentFR = "La lampe étoilée que m’a offerte l’Étranger est très jolie... mais quand même, rien ne vaut le vrai ciel étoilé, atchoum !",
          DialogueId = 80050204,
          GUID = "C865B498",
          NextOptions = {
            [1] = 80050205,
            [2] = 80050206
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B498"
        },
        [80050205] = {
          ContentFR = "Fais attention à ne pas attraper froid.",
          DialogueId = 80050205,
          GUID = "C865B4C2",
          NextDialogue = 80050207
        },
        [80050206] = {
          ContentFR = "Viens te mettre derrière moi, je vais te couper du vent.",
          DialogueId = 80050206,
          GUID = "C865B4EC",
          NextDialogue = 80050207
        },
        [80050207] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "T’inquiète pas, je n’ai pas froid du tout ! Tu veux voir ? Ma main est toute chaude ! J’aimerais rester encore un peu...",
          DialogueId = 80050207,
          GUID = "C865B516",
          NextDialogue = 80050208,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{"DisagreeHead"},Duration{2}},PlayAnimation{_delay{2},ActorId{790017},AnimationId{"Talk02_Start"},Duration{1}}}",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B516"
        },
        [80050208] = {
          Camera = "-370.169922,731.447144,106.094727,0.000026,35.394604,129.986496,18.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Regarde là-bas ! Tu trouves pas que ces étoiles, alignées comme ça, ça ressemble à un petit lapin ?",
          DialogueId = 80050208,
          GUID = "C865B540",
          NextOptions = {
            [1] = 80050209,
            [2] = 80050211,
            [3] = 80050214
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B540"
        },
        [80050209] = {
          ContentFR = "Oui, on dirait.",
          DialogueId = 80050209,
          GUID = "C865B56A",
          NextDialogue = 80050210
        },
        [80050210] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hihi, alors ce soir, je vais inventer une histoire, l’histoire d’un petit lapin dans les étoiles !",
          DialogueId = 80050210,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865B594",
          NextOptions = {
            [1] = 80050217
          },
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{"Confident_Start"},Duration{2}},PlayAnimation{_delay{3},ActorId{790017},AnimationId{"Confident_End"},Duration{1}}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B594"
        },
        [80050211] = {
          ContentFR = "Moi je vois une grosse cuisse de poulet.",
          DialogueId = 80050211,
          GUID = "C865B5BE",
          NextDialogue = 80050212
        },
        [80050212] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hein ? ... Je vois pas trop... Dis, t’aurais pas un peu faim, par hasard ?",
          DialogueId = 80050212,
          FacialId = {
            [1] = "790017:Shock01"
          },
          GUID = "C865B5E8",
          NextDialogue = 80050213,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B5E8"
        },
        [80050213] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je plaisantais. Dis-moi…",
          DialogueId = 80050213,
          GUID = "C865B612",
          NextOptions = {
            [1] = 80050217
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "790017:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B612"
        },
        [80050214] = {
          ContentFR = "On dirait un dauphin avec un slip sur la tête.",
          DialogueId = 80050214,
          GUID = "C865B63C",
          NextDialogue = 80050215
        },
        [80050215] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hein ?! C-c’est quoi ce truc ? J’arrive pas du tout à l’imaginer...",
          DialogueId = 80050215,
          FacialId = {
            [1] = "790017:Shock01"
          },
          GUID = "C865B666",
          NextDialogue = 80050216,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B666"
        },
        [80050216] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je plaisantais. Dis-moi…",
          DialogueId = 80050216,
          GUID = "C865B690",
          NextOptions = {
            [1] = 80050217
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "790017:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B690"
        },
        [80050217] = {
          ContentFR = "Pourquoi tu aimes tant regarder les étoiles, Fina ?",
          DialogueId = 80050217,
          GUID = "C865B6BA",
          NextDialogue = 80050218
        },
        [80050218] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il y a longtemps, ma maman m’a raconté une histoire. Celle d’un petit oiseau... qui est devenu une étoile. C’est mon histoire préférée, je vais te la raconter.",
          DialogueId = 80050218,
          GUID = "C865B6E4",
          NextDialogue = 80050219,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{"Explain02_Start"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{"Explain02_End"},Duration{1}}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B6E4"
        },
        [80050219] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Cet oiseau n’était pas comme les autres, ses plumes étaient moches, sa voix pas jolie du tout... Il n’avait ni serres pointues ni bec acéré. Les autres oiseaux le repoussaient, se moquaient de lui, voulaient qu’il parte.",
          DialogueId = 80050219,
          GUID = "C865B70E",
          NextDialogue = 80050220,
          Scripts = "PlayAnimation{_delay{2},ActorId{790017},AnimationId{"DisagreeHead"},Duration{2}}",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B70E"
        },
        [80050220] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais ce petit oiseau rêvait des étoiles. Il priait le ciel chaque nuit... Il voulait les rejoindre, même si ça voulait dire brûler dans leur lumière. Ça lui allait.",
          DialogueId = 80050220,
          GUID = "C865B738",
          NextOptions = {
            [1] = 80050221
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B738"
        },
        [80050221] = {
          ContentFR = "Les étoiles ont répondu à ses prières ?",
          DialogueId = 80050221,
          GUID = "C865B762",
          NextDialogue = 80050222
        },
        [80050222] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... Certaines l’ont ignoré, d’autres l’ont moqué, un vilain petit oiseau qui voulait voler parmi les étoiles ? Quelle blague.",
          DialogueId = 80050222,
          GUID = "C865B78C",
          NextOptions = {
            [1] = 80050223
          },
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{"Explain01_End"},Duration{2}},PlayAnimation{ActorId{790017},AnimationId{"DisagreeHead"},Duration{1}}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B78C"
        },
        [80050223] = {
          ContentFR = "Et après ?",
          DialogueId = 80050223,
          GUID = "C865B7B6",
          NextDialogue = 80050224
        },
        [80050224] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il a arrêté de supplier. Il a dit au revoir à sa famille... et il s’est envolé, seul, vers le ciel.",
          DialogueId = 80050224,
          GUID = "C865B7E0",
          NextDialogue = 80050225,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B7E0"
        },
        [80050225] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il est monté de plus en plus haut, là où le vent est glacé. Jusqu’à ce qu’il gèle. Il ne pouvait plus bouger... plus chanter... plus voler.",
          DialogueId = 80050225,
          GUID = "C865B80A",
          NextOptions = {
            [1] = 80050226
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B80A"
        },
        [80050226] = {
          ContentFR = "... C’est une fin bien triste.",
          DialogueId = 80050226,
          GUID = "C865B834",
          NextDialogue = 80050227
        },
        [80050227] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas encore. Parce qu’à ce moment-là, il a senti son corps s’embraser. Son plumage terne s’est mis à briller doucement... comme une vraie <H>étoile</>.",
          DialogueId = 80050227,
          GUID = "C865B85E",
          NextDialogue = 80050228,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{"Explain01_Start"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{"Explain01_End"},Duration{1}}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B85E"
        },
        [80050228] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, il est devenu une étoile ! Une vraie !",
          DialogueId = 80050228,
          GUID = "C865B888",
          NextDialogue = 80050229,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B888"
        },
        [80050229] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voilà, c’est fini. Est-ce que tu l’as aimé, mon histoire, {性别:Monsieur|Mademoiselle} Licorne ?",
          DialogueId = 80050229,
          GUID = "C865B8B2",
          LookAt = {
            [1] = "790017:p(180102P)"
          },
          NextOptions = {
            [1] = 80050230,
            [2] = 80050232
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B8B2"
        },
        [80050230] = {
          ContentFR = "Oui, c’était une très belle histoire.",
          DialogueId = 80050230,
          GUID = "C865B8DC",
          NextDialogue = 80050231
        },
        [80050231] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce petit oiseau était plus courageux que je l’aurais cru. J’ai beaucoup aimé.",
          DialogueId = 80050231,
          GUID = "C865B906",
          LookAt = {
            [1] = "790017:n(100001)"
          },
          NextDialogue = 80050235,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B906"
        },
        [80050232] = {
          ContentFR = "Non... c’est trop triste pour moi.",
          DialogueId = 80050232,
          GUID = "C865B930",
          NextDialogue = 80050233
        },
        [80050233] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je trouve que ce n’était pas juste qu’il ait à se sacrifier... Il aurait dû se battre contre les injustices, pas les fuir.",
          DialogueId = 80050233,
          GUID = "C865B95A",
          LookAt = {
            [1] = "790017:n(100001)"
          },
          NextDialogue = 80050234,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B95A"
        },
        [80050234] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vraiment... ? Hmm... Ce serait une toute autre histoire, alors.",
          DialogueId = 80050234,
          GUID = "C865B984",
          NextDialogue = 80050235,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B984"
        },
        [80050235] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 80050235,
          GUID = "C865B9AE",
          LookAt = {
            [1] = "790017:p(180102P)"
          },
          NextDialogue = 80050236,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B9AE"
        },
        [80050236] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu crois que moi aussi... je pourrais devenir comme cet oiseau, un jour ?",
          DialogueId = 80050236,
          GUID = "C865B9D8",
          LookAt = {
            [1] = "790017:n(790017)"
          },
          NextOptions = {
            [1] = 80050237
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B9D8"
        },
        [80050237] = {
          ContentFR = "... La famille du petit oiseau serait très triste.",
          DialogueId = 80050237,
          GUID = "C865BA02",
          NextDialogue = 80050238
        },
        [80050238] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah... Je n’avais jamais pensé à ça.",
          DialogueId = 80050238,
          GUID = "C865BA2C",
          LookAt = {
            [1] = "790017:n(100001)"
          },
          NextDialogue = 80050239,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{"Sigh_End"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{"DisagreeHead"},Duration{1}}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BA2C"
        },
        [80050239] = {
          ContentFR = "J’imaginais qu’ils seraient heureux pour lui... parce qu’il brille si fort, toujours là-haut, pour toujours.",
          DialogueId = 80050239,
          GUID = "C865BA56",
          NextDialogue = 80050240,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BA56"
        },
        [80050240] = {
          ContentFR = "Et quand ils pensent à lui, ils n’ont qu’à lever les yeux, comme nous ce soir, pour lui dire bonsoir.",
          DialogueId = 80050240,
          GUID = "C865BA80",
          NextDialogue = 80050241,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BA80"
        },
        [80050241] = {
          ContentFR = "Mais maintenant que tu le dis... Il ne bouge plus, il ne parle plus... Ils peuvent le voir, mais ils ne peuvent jamais l’atteindre.",
          DialogueId = 80050241,
          GUID = "C865BAAA",
          NextDialogue = 80050242,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BAAA"
        },
        [80050242] = {
          ContentFR = "Tu crois qu’ils seraient tristes ? J’ai besoin d’y réfléchir...",
          DialogueId = 80050242,
          GUID = "C865BAD4",
          NextDialogue = 80050243,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BAD4"
        },
        [80050243] = {
          ContentFR = "Merci de m’avoir accompagnée ce soir, {性别:Monsieur|Mademoiselle} Licorne. On rentre à la maison, maintenant.",
          DialogueId = 80050243,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865BAFE",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BAFE"
        },
        [80050301] = {
          Camera = "-220.272461,-361.613037,104.543945,0.0,0.0,64.200195,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mon troisième vœu, c’est que toi, {性别:Monsieur|Mademoiselle} Licorne, tu m’emmènes sur les remparts de Givrelac.",
          DialogueId = 80050301,
          GUID = "C865C482",
          IsBlack = 1,
          NextDialogue = 80050302,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C482"
        },
        [80050302] = {
          Camera = "-58.240234,-248.958618,99.918945,0.000097,3.997675,105.603172,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Haa... haa... haa...",
          DialogueId = 80050302,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          FinalCamera = "-21.044922,-372.557251,86.48877,0.000079,4.397842,110.200386,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C4AC",
          NextOptions = {
