          VoiceName = "voice/$Locale$/inv/Linen/002/C88C27DA"
        },
        [80110202] = {
          ContentFR = "Hé, à Givrelac, tu bosses toujours comme avant ? T’es encore aux Asphodèles ?",
          DialogueId = 80110202,
