          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          ContentFR = "Ah ouais ? Rien n’a changé alors. Les Asphodèles, c’est tranquille... au moins, Camilla te balance pas des missions de pillage et d’assassinat à l’improviste.",
          DialogueId = 80110203,
          FacialId = {
