        [80120122] = {
          Camera = "13.058594,-189.487427,130.297607,0.000067,-5.400023,73.400612,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouais, d’habitude je cours entre deux bennes, je récupère ce qui peut encore servir, et je revends à ceux que ça intéresse.",
          DialogueId = 80120122,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "10.127441,-188.613403,130.297607,0.000069,-5.400023,72.800484,35.0,100000.0,false,DoNotOverride,2.8",
