        },
        [80120124] = {
          Camera = "-46.604492,-258.057495,81.282959,0.000152,2.599918,66.012314,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ces vieux meubles en bois sont top, on peut en faire des planches pour des lits ou des tables. J’ai demandé au tailleur, les rideaux, nappes et tapis, après un bon lavage, ça peut servir pour faire des fringues.",
          DialogueId = 80120124,
          FacialId = {
            [1] = "790019:Confident02"
          },
          GUID = "C89283D8",
          NextDialogue = 80120125,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89283D8"
        },
        [80120125] = {
          Camera = "3.307129,189.679504,120.907227,0.0,-2.599973,-71.797028,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quelques familles des taudis pourront mieux dormir et s’habiller, et moi, je me fais un peu de blé. Même si le musicien a été dur, il a bien payé, hé hé...",
          DialogueId = 80120125,
          GUID = "C8928402",
          NextDialogue = 80120126,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790008:Think_Start",
            [2] = "790019:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928402"
        },
        [80120126] = {
          Camera = "30.832031,-69.490662,105.26709,0.000002,4.999924,73.193848,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu trouves pas ça drôle ? J’étais furieuse tout à l’heure, et maintenant, plus du tout !",
          DialogueId = 80120126,
          FacialId = {
            [1] = "790019:Happy01"
          },
          GUID = "C892842C",
          NextDialogue = 80120127,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892842C"
        },
        [80120127] = {
          Camera = "-37.370605,-328.404663,168.14209,0.000007,-11.000026,70.593628,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bref, Monsieur Kossak est parti pour Dismania, les pauvres ont du matos, même si j’ai pris une petite engueulade, c’est pas grave ! Dès que je bosse, j’oublie tout !",
          DialogueId = 80120127,
          FacialId = {
            [1] = "790019:Smile01"
          },
          FinalCamera = "-37.370605,-328.404663,152.396973,0.000009,-9.199978,70.193542,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8928456",
          NextOptions = {
            [1] = 801201271,
            [2] = 801201272
          },
          Scripts = "SEQ{\nPlayAnimation{ActorId{790019},AnimationId{\"Explain02_End\"},Duration{1},_click{false}},\nPlayAnimation{ActorId{790019},AnimationId{\"DisagreeHead\"},Duration{3},_delay{4},_click{false}}\n}",
          SpeakNpcId = 790019,
          ToFinalCameraBlendTime = 11.5,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928456"
        },
        [80120128] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Super, ça me fera de l’aide pour sortir ses armoires. Prends ce que tu veux pendant qu’on y est.",
          DialogueId = 80120128,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C8928480",
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928480"
        },
        [80120129] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfait ! Considère ça comme un remerciement d’avoir écouté mes plaintes. Allez, viens m’aider. Choisis ce que tu veux.",
          DialogueId = 80120129,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C89284AA",
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284AA"
        },
        [80120130] = {
          ContentFR = "Tu as passé une journée bien remplie avec Margie... Mais une fois chez toi, difficile d’ignorer la douleur dans les bras.",
          DialogueId = 80120130,
          GUID = "C89284D4",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284D4"
        },
        [80120201] = {
          Camera = "1333.655273,158.495117,593.059387,0.000084,-23.399462,-148.791443,45.0,1393.645752,false,Manual,2.8",
          ContentFR = "Margie a récupéré les affaires que le grand musicien Kossak avait laissées derrière lui et a carrément réquisitionné une pièce entière du Sanctuaire. On entend souvent des bruits de ferraille et de coups de marteau s’en échapper : visiblement, elle y transforme sans relâche du vieux bric-à-brac en trésor.",
          DialogueId = 80120201,
          FinalCamera = "1329.534668,166.603516,574.799133,0.000082,-22.599415,-147.989853,45.0,1393.645752,false,Manual,2.8",
          GUID = "C892907A",
          Scripts = "SEQ{\nCameraMoveTo{TargetPosition{\"-536.0,361.0,216.0,0.000089,-19.999989,-58.799721,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}},\nCameraMoveTo{TargetPosition{\"-180.185974,-395.118164,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nCameraMoveTo{TargetPosition{\"-180.185974,-405.0,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}},\n}",
