        },
        [80120207] = {
          Camera = "232.653351,361.8125,281.633331,0.000094,-18.999201,-161.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avec mon flair de "détective", je te le dis : cette planche cache forcément un truc ! Depuis que je fouille les poubelles, tous les secrets du coin, que je les cherche ou pas, viennent finir dans mon sac.",
          DialogueId = 80120207,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          GUID = "C8929176",
          NextDialogue = 80120208,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790019},AnimationId{\"Agree\"},Duration{1},_click{false}},\nPlayAnimation{ActorId{790019},AnimationId{\"Think_Start\"},Duration{4},_delay{1},_click{false}},\nPlayAnimation{ActorId{790019},AnimationId{\"Think_End\"},Duration{1},_click{false}}\n}",
          SpeakNpcId = 790019,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929176"
        },
        [80120208] = {
          Camera = "-233.092163,217.391113,116.084183,0.0,-0.600005,-144.397369,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des vitres brisées dans les poubelles ? En général, ça veut dire qu’il y a eu une engueulade. Un sac rempli de fringues usées ? Bingo, ils ont touché un héritage. Et je te parle même pas des lettres d’amour déchirées que je ramasse parfois...",
          DialogueId = 80120208,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89291A0",
          NextDialogue = 80120209,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790019},AnimationId{\"Explain01_Start\"},Duration{3},_click{false}},\nPlayAnimation{ActorId{790019},AnimationId{\"Explain01_End\"},Duration{1},_click{false}},\nPARA{\nPlayFacial{_delay{6.5},ActorId{790008},FacialId{\"Happy02\"}},\nLookAt{LookAtDescription{\"790019:p(P33010202)\"}},\n}\n}",
