        [80120209] = {
          Camera = "96.989166,365.946533,258.328094,0.000015,-19.39859,-156.192947,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bon, je m’égare. Revenons à cette planche creuse. Il faisait trop sombre dans la pièce, alors je l’ai sortie ici. J’allais l’ouvrir quand tu es {性别:arrivé|arrivée}. Y a forcément quelque chose là-dedans...",
          DialogueId = 80120209,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "135.622986,382.351562,322.567413,0.000009,-24.598625,-156.393433,35.000008,100000.0,false,DoNotOverride,2.8",
