          NextDialogue = 80120224,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929416"
        },
        [80120224] = {
          Camera = "-255.582703,344.383789,69.178757,0.000035,7.599951,-112.388451,35.000008,264.602783,false,Manual,2.8",
          ContentFR = "Qu’il l’ait oubliée ou laissée volontairement, peu importe. Il m’a confié ses affaires. Je dois faire ça sérieusement.",
          DialogueId = 80120224,
          GUID = "C8929440",
          NextDialogue = 80120225,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929440"
        },
        [80120225] = {
          Camera = "-501.36084,57.133301,131.599701,0.000011,-4.399932,31.404215,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Viens, {nickname}, on va voir Camilla. Je crois qu’elle sait lire les partitions. Je vais lui demander de m’apprendre à la chanter.",
          DialogueId = 80120225,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892946A",
          NextDialogue = 80120226,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Explain02_End",
            [2] = "\n790008:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892946A"
        },
        [80120226] = {
          Camera = "-302.98645,187.943359,114.158592,0.000014,3.400027,-133.7966,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et une fois que je saurai, j’apprendrai cette chanson aux Charons de Givrelac. Je leur dirai qu’un grand musicien a écrit ça spécialement pour eux.",
          DialogueId = 80120226,
          FacialId = {
            [1] = "790019:Happy01"
          },
          FinalCamera = "-302.98645,187.943359,114.158592,0.000026,3.400027,-133.7966,36.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929494",
          NextDialogue = 80120227,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929494"
        },
        [80120227] = {
          Camera = "193.657837,-330.853027,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Comme ça, elle ne finira pas en fumée, brûlée avec les autres partitions ratées.",
          DialogueId = 80120227,
          FinalCamera = "153.661621,-330.320312,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89294BE",
          NextDialogue = 80120228,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294BE"
        },
        [80120228] = {
          Camera = "79.69873,985.43457,55.531265,0.000044,12.80017,92.181931,55.0,490.84668,false,Manual,1.2",
          ContentFR = "Et qui sait ? Peut-être qu’un jour, cette chanson résonnera jusqu’à la capitale. Peut-être qu’il entendra les Charons la chanter. Mais même s’il ne l’entend jamais, c’est pas grave. J’aurai fait ma part.",
          DialogueId = 80120228,
          FinalCamera = "103.997955,961.556152,69.737282,0.000067,10.600037,97.981682,55.0,490.84668,false,Manual,1.2",
          GUID = "C89294E8",
          NextDialogue = 80120229,
          SpeakNpcId = 790019,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294E8"
        },
        [80120229] = {
          Camera = "-312.233704,183.148438,116.782532,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Redonner vie à ce qui n’aurait jamais dû finir à la benne, c’est ça, ma mission !",
          DialogueId = 80120229,
          FacialId = {
            [1] = "790019:Happy02"
          },
          FinalCamera = "-316.72876,177.902344,117.07206,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929512",
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{"-285.357117,180.728271,121.084183,0.0,0.0,-143.597351,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}}",
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929512"
        },
        [80120230] = {
          ContentFR = "D’après Camilla, Les Démons brisent leurs chaînes est effectivement une œuvre brillante, mais aussi redoutablement difficile à chanter.",
          DialogueId = 80120230,
          Duration = 4,
          GUID = "C892953C",
          NextDialogue = 80120231,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892953C"
        },
        [80120231] = {
          ContentFR = "Il aura fallu trois jours à Margie pour la maîtriser, en descendant même d’un octave. Peu après, on entendait déjà sa mélodie flotter dans les rues de Givrelac.",
          DialogueId = 80120231,
          Duration = 5,
          GUID = "C8929566",
          NextDialogue = 80120232,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929566"
        },
        [80120232] = {
          ContentFR = "C’est ça, selon Margie, l’art de transformer les déchets en trésors.",
          DialogueId = 80120232,
          Duration = 3,
          GUID = "C8929590",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929590"
        },
        [80120290] = {
          DialogueId = 80120290,
          GUID = "C89291CB",
          IsBlack = 1,
          NextDialogue = 80120210,
          Scripts = "PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/yaoyue_woodbrk"},PlayAs2D{true}}"
        },
        [80120301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentFR = "Hmm...",
          DialogueId = 80120301,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A0E2",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120302,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A0E2"
        },
        [80120302] = {
          ContentFR = "C’est à la fois amer et sucré... Beurk, c’est exactement le genre de goût que mon vieux crétin adore ! Moi, je pense qu’il me faudra encore dix, non, vingt ans pour apprécier ça.",
          DialogueId = 80120302,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A10C",
          NextOptions = {
            [1] = 801203021,
            [2] = 801203031
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A10C"
        },
        [80120303] = {
          ContentFR = "Je ne comprends pas du tout ! Pourquoi s’infliger un goût aussi amer ?!",
          DialogueId = 80120303,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A136",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A136"
        },
        [80120304] = {
          ContentFR = "Exact ! Après une journée de boulot, quelques verres bien frais, ça dénoue tout, de la tête aux pieds !",
          DialogueId = 80120304,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A160",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A160"
        },
        [80120305] = {
          ContentFR = "Mon père ! Tout le monde l’appelle le vieux Martin. Avant que je reprenne le flambeau, il gérait toutes les poubelles de Givrelac.",
          DialogueId = 80120305,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A18A",
          NextDialogue = 80120306,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A18A"
        },
        [80120306] = {
          ContentFR = "Si tout le monde ne l’avait pas surnommé « Roi des Déchets », je n’aurais pas hérité du ridicule surnom de « Princesse des Déchets »... Ce vieux crétin m’a vraiment mise dans une sacrée galère !",
          DialogueId = 80120306,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A1B4",
          NextDialogue = 80120307,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1B4"
        },
        [80120307] = {
          ContentFR = "Moi, j’aurais préféré un surnom plus cool, plus intelligent, plus fiable...",
          DialogueId = 80120307,
          FacialId = {
            [1] = "93301:Iyada01"
          },
          GUID = "C892A1DE",
          NextOptions = {
            [1] = 801203071,
            [2] = 801203081
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1DE"
        },
        [80120308] = {
          ContentFR = "Exactement ! Hé hé, tu me comprends !",
          DialogueId = 80120308,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A208",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A208"
        },
        [80120309] = {
          ContentFR = "Aaah, tais-toi, tais-toi ! Sinon, je t’assomme avec ma pelle !",
          DialogueId = 80120309,
          FacialId = {
            [1] = "93301:Disappoint01"
          },
          GUID = "C892A232",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A232"
        },
        [80120310] = {
          ContentFR = "Pfff... Depuis qu’il m’a refilé tout le boulot, je ne le vois plus. Aucune idée de ce qu’il fout. J’espère qu’il ne va pas nous attirer d’ennuis, à moi et à Madame Camilla !",
          DialogueId = 80120310,
          FacialId = {
            [1] = "93301:Unhappy01"
          },
          GUID = "C892A25C",
          NextOptions = {
            [1] = 801203101
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A25C"
        },
        [80120311] = {
          ContentFR = "Euh, si ce n’était pas pour ce goût amer... en fait, ça fait un moment que je ne pense plus trop à ce vieux crétin...",
          DialogueId = 80120311,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892A286",
          NextOptions = {
            [1] = 801203111,
            [2] = 801203121
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A286"
        },
        [80120312] = {
          ContentFR = "Je bosse beaucoup aussi, hein ! Et puis, au final, tout ce boulot, c’est lui qui me l’a refilé !",
          DialogueId = 80120312,
          FacialId = {
            [1] = "93301:Shock02"
          },
          GUID = "C892A2B0",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2B0"
        },
        [80120313] = {
          ContentFR = "Hé hé... Quand les petits animaux grandissent, ils quittent le nid pour se débrouiller seuls. C’est normal.",
          DialogueId = 80120313,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A2DA",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2DA"
        },
        [80120314] = {
          ContentFR = "Et puis, pendant les dix premières années de ma vie, ce vieux crétin ne me lâchait pas. Surtout après qu’on a quitté notre vieille maison pour Givrelac, on a passé une année entière dans les champs enneigés, rien que tous les deux, sans croiser âme qui vive.",
          DialogueId = 80120314,
          GUID = "C892A304",
          NextDialogue = 80120315,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A304"
        },
        [80120315] = {
          ContentFR = "J’en ai déjà trop entendu de ses histoires, ses chansons, ses combines... Alors, je ne pense plus tellement à lui... Enfin, presque.",
          DialogueId = 80120315,
          GUID = "C892A32E",
          NextDialogue = 80120316,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A32E"
        },
        [80120316] = {
          ContentFR = "Et puis, à peine arrivés à Givrelac, ce vieux crétin a commencé à "se tailler son territoire", "recruter des hommes de main", "organiser un racket de protection", "s’allier avec les puissants locaux" et "devenir le grand chef". Il avait l’air de bien s’amuser tout seul.",
          DialogueId = 80120316,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A358",
          NextOptions = {
            [1] = 801203161
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A358"
        },
        [80120317] = {
          ContentFR = "Ah non, non, c’est juste qu’il a cartographié les emplacements des poubelles, recruté les éboueurs, fixé les règles pour la collecte, trouvé des commerçants intéressés par le recyclage grâce à Camilla, et fini par devenir le « Roi des Déchets ».",
          DialogueId = 80120317,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A382",
          NextDialogue = 80120318,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A382"
        },
        [80120318] = {
          ContentFR = "Ce vieux crétin adore raconter ses histoires grandiloquentes, comme un comédien avec ses dialogues tout écrits ! Il doit traîner ces mauvaises habitudes depuis son patelin où ça bastonnait tout le temps. Il n’arrive pas à s’en défaire, pfff...",
          DialogueId = 80120318,
          GUID = "C892A3AC",
          NextOptions = {
            [1] = 801203181
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3AC"
        },
        [80120319] = {
          ContentFR = "C’est pas simple à dire ! Le vieux adore se vanter de ses "exploits glorieux" là-bas. Genre...",
          DialogueId = 80120319,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A3D6",
          NextDialogue = 80120320,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3D6"
        },
        [80120320] = {
          ContentFR = "« Chaque mission d’un récupérateur touche à l’honneur personnel et à l’intérêt familial. Du plan au moindre détail, tout doit être parfait. Et ton père, c’est le meilleur récupérateur de tous. »",
          DialogueId = 80120320,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A400",
          NextDialogue = 80120321,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A400"
        },
        [80120321] = {
          ContentFR = "C’est à cause de son influence que, quand je suis arrivée à Givrelac, je parlais exactement comme un « petit Martin ». Camilla en avait marre et a mis un temps fou à me faire perdre cet accent.",
          DialogueId = 80120321,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A42A",
          NextOptions = {
            [1] = 801203211
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A42A"
        },
        [80120322] = {
          ContentFR = "Non merci, c’est trop honteux !",
          DialogueId = 80120322,
          FacialId = {
            [1] = "93301:Unacceptable01"
          },
          GUID = "C892A454",
          NextOptions = {
            [1] = 801203221,
            [2] = 801203231
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A454"
        },
        [80120323] = {
          ContentFR = "Bon, juste cette fois, hein ! Après, plus jamais.",
          DialogueId = 80120323,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A47E",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A47E"
        },
        [80120324] = {
          ContentFR = "Aaaah ! J’abandonne, j’abandonne ! Arrête, s’il te plaît !",
          DialogueId = 80120324,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A4A8",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4A8"
        },
        [80120325] = {
          ContentFR = "Alors voilà... Quand le vieux Martin m’a déposée chez Camilla pour partir gérer ses affaires, je lui disais...",
          DialogueId = 80120325,
          FacialId = {
            [1] = "93301:Think01"
          },
          GUID = "C892A4D2",
          NextDialogue = 80120326,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4D2"
        },
        [80120326] = {
          ContentFR = "« Souviens-toi de ta mission, Père. Notre avenir dépend de chacune de tes actions. J’espère que tu as bien lavé ton visage, brossé tes dents, et que tu as un plan béton. »",
          DialogueId = 80120326,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A4FC",
          NextOptions = {
            [1] = 801203261
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4FC"
        },
        [80120327] = {
          ContentFR = "Et lui, il ôtait son chapeau et me répondait : « À vos ordres, madame ! Si l’un de nous échoue, on écrira son nom avec "idiot" sur la porte des Asphodèles pour que tout le monde voie. »",
          DialogueId = 80120327,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A526",
          NextOptions = {
            [1] = 801203271
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A526"
        },
        [80120328] = {
          ContentFR = "Et je lui rétorquais : « Puisqu’on porte le même nom, autant l’écrire au fond d’une marmite, ça m’évitera la honte et le feu du foyer brûlera ta disgrâce ! »",
          DialogueId = 80120328,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A550",
          NextOptions = {
            [1] = 801203281
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A550"
        },
        [80120329] = {
          ContentFR = "Hahahahahaha !",
          DialogueId = 80120329,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A57A",
          NextDialogue = 80120330,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A57A"
        },
        [80120330] = {
          ContentFR = "Maintenant, je comprends mieux pourquoi tu t’appelles « Princesse des Déchets », c’est pas entièrement la faute de Martin, hein.",
          DialogueId = 80120330,
          GUID = "C892A5A4",
          NextDialogue = 80120331,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5A4"
        },
        [80120331] = {
          ContentFR = "Je m’en fiche ! C’est entièrement sa faute ! Rien que de penser que j’ai failli devenir un fanfaron comme lui, j’en ai des frissons.",
          DialogueId = 80120331,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A5CE",
          NextDialogue = 80120332,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5CE"
        },
        [80120332] = {
          ContentFR = "Tu sais, j’ai capté que, même si ce vieux crétin critique le chaos de notre ancien chez-nous, il y est attaché et fier en secret. Je crois pas qu’il soit parti juste parce qu’il détestait l’anarchie.",
          DialogueId = 80120332,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A5F8",
          NextDialogue = 80120333,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5F8"
        },
        [80120333] = {
          ContentFR = "Mais qu’est-ce qui a bien pu se passer pour qu’il prenne la décision de me traîner à travers la neige, à fuir notre patelin ?",
          DialogueId = 80120333,
          FacialId = {
            [1] = "93301:Unhappy02"
          },
          GUID = "C892A622",
          NextDialogue = 80120334,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A622"
        },
        [80120334] = {
          ContentFR = "Il doit cacher un secret énorme ! Mais dès que je lui pose la question, il me répond toujours : « Je ne te dirai rien. Si tu veux savoir, débrouille-toi toute seule. »",
          DialogueId = 80120334,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A64C",
          NextDialogue = 80120335,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A64C"
        }
      }
    end
  },
  {
    MinKey = 80120335,
    MaxKey = 80130416,
    Loader = function()
      return {
        [80120335] = {
          ContentFR = "Alors l’année dernière, je l’ai espionné pendant des mois. Mais ce vieux est une vraie ombre, et les affaires qu’il a ramenées de chez nous, personne ne sait où elles sont cachées.",
          DialogueId = 80120335,
          GUID = "C892A676",
          NextDialogue = 80120336,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A676"
        },
        [80120336] = {
          ContentFR = "J’ai creusé pendant des mois, sans rien trouver. Et pour couronner le tout, il s’est moqué de moi.",
          DialogueId = 80120336,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A6A0",
          NextOptions = {
            [1] = 801203361
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6A0"
        },
        [80120337] = {
          ContentFR = "Oui, moqué ! Un jour, alors qu’on s’y attendait le moins, le vieux est revenu. Il a passé la journée avec moi, et en partant, il a carrément oublié sa valise, celle qu’il avait ramenée de chez nous !",
          DialogueId = 80120337,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A6CA",
          NextDialogue = 80120338,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6CA"
        },
        [80120338] = {
          ContentFR = "Je me suis dit : « Enfin, le vieux a laissé une trace ! » J’ouvre la valise, et dedans, y’avait juste une marmite...",
          DialogueId = 80120338,
          GUID = "C892A6F4",
          NextDialogue = 80120339,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6F4"
        },
        [80120339] = {
          ContentFR = "Margie tape avec colère sur la marmite posée sur sa tête, ça fait un bruit creux.",
          DialogueId = 80120339,
          GUID = "C892A71E",
          NextDialogue = 80120340,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A71E"
        },
        [80120340] = {
          ContentFR = "C’est ça ! Et y’avait un mot dans la valise...",
          DialogueId = 80120340,
          GUID = "C892A748",
          NextDialogue = 80120341,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A748"
        },
        [80120341] = {
          ContentFR = "« Chère Margie, je savais que tu fouillerais cette valise pour découvrir mon secret. J’ai donc déplacé le secret là où tu ne t’y attendra pas. »",
          DialogueId = 80120341,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A772",
          NextDialogue = 80120342,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A772"
        },
        [80120342] = {
          ContentFR = "« Pour te faire pardonner ta déception, je t’offre cet objet, un casque multifonction ! Porté à l’endroit, il protège ta tête, retourné, c’est une marmite pour cuisiner, et la lampe fixée à l’avant éclaire le chemin. L’outil parfait, à la maison comme en voyage. »",
          DialogueId = 80120342,
          GUID = "C892A79C",
          NextDialogue = 80120343,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A79C"
        },
        [80120343] = {
          ContentFR = "« Et puis, joyeux anniversaire. Martin. »",
          DialogueId = 80120343,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A7C6",
          NextOptions = {
            [1] = 801203431,
            [2] = 801203432
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7C6"
        },
        [80120344] = {
          ContentFR = "... Je suis sûre qu’il se moquait de moi !",
          DialogueId = 80120344,
          GUID = "C892A7F0",
          NextDialogue = 80120345,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7F0"
        },
        [80120345] = {
          ContentFR = "Bref, après ça, j’ai laissé tomber son secret.",
          DialogueId = 80120345,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A81A",
          NextDialogue = 80120346,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A81A"
        },
        [80120346] = {
          ContentFR = "Tiens, en parlant de secret, j’ai une intuition...",
          DialogueId = 80120346,
          GUID = "C892A844",
          NextDialogue = 80120347,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A844"
        },
        [80120347] = {
          ContentFR = "Quelle intuition ?",
          DialogueId = 80120347,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A86E",
          NextDialogue = 80120348,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A86E"
        },
        [80120348] = {
          ContentFR = "Son secret... il serait pas caché dans ce « casque multifonction » ?",
          DialogueId = 80120348,
          GUID = "C892A898",
          NextDialogue = 80120349,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A898"
        },
        [80120349] = {
          ContentFR = "Il a dit « là où tu ne t’y attendra pas », alors... et si c’était justement là, sous notre nez, que ça se trouvait ?",
          DialogueId = 80120349,
          GUID = "C892A8C2",
          NextDialogue = 80120350,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8C2"
        },
        [80120350] = {
          ContentFR = "Ah... ! En y repensant, j’étais tellement dépitée à l’époque que je n’ai même pas fouillé ce casque ! Si c’est un objet modifié, il pourrait bien cacher quelque chose ! Laisse-moi voir ça de plus près !",
          DialogueId = 80120350,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A8EC",
          NextDialogue = 80120351,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8EC"
        },
        [80120351] = {
          ContentFR = "Vraiment ! Sous la couche d’absorption des chocs, il y a une cavité secrète ! Je savais que tu avais l’étoffe d’{性别:un|une} détective !",
          DialogueId = 80120351,
          GUID = "C892A916",
          IsBlack = 1,
          NextDialogue = 80120352,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A916"
        },
        [80120352] = {
          ContentFR = "Vieux crétin ! Cette fois, c’est toi qui vas voir !",
          DialogueId = 80120352,
          GUID = "C892A940",
          IsBlack = 1,
          NextDialogue = 80120353,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A940"
        },
        [80120353] = {
          ContentFR = "Margie manipule habilement le casque marmite, visiblement expérimentée dans le bricolage à partir de déchets, ses doigts agiles démontent rapidement l’objet.",
          DialogueId = 80120353,
          GUID = "C892A96A",
          IsBlack = 1,
          NextDialogue = 80120354,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A96A"
        },
        [80120354] = {
          ContentFR = "C’est... ça...",
          DialogueId = 80120354,
          GUID = "C892A994",
          IsBlack = 1,
          NextDialogue = 80120355,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A994"
        },
        [80120355] = {
          ContentFR = "Margie ouvre grand les yeux, bouche bée devant la marmite. Tu prends l’objet et remarques une petite inscription gravée sous le fond.",
          DialogueId = 80120355,
          GUID = "C892A9BE",
          IsBlack = 1,
          NextDialogue = 80120356,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9BE"
        },
        [80120356] = {
          ContentFR = "« À ma fille Margie l’Idiote : »",
          DialogueId = 80120356,
          GUID = "C892A9E8",
          IsBlack = 1,
          NextDialogue = 80120357,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9E8"
        },
        [80120357] = {
          ContentFR = "« Félicitations pour avoir encore perdu dans le jeu "Chercher le secret de Martin". Par conséquent, j’ajoute "idiote" à ton prénom. »",
          DialogueId = 80120357,
          GUID = "C892AA12",
          IsBlack = 1,
          NextDialogue = 80120358,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA12"
        },
        [80120358] = {
          ContentFR = "« Puisque nous partageons le même nom, j’ai gravé ton nom au fond cette marmite, ça m’évitera la honte et le feu du foyer brûlera ta disgrâce ! »",
          DialogueId = 80120358,
          GUID = "C892AA3C",
