        },
        [80120401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentFR = "Snif snif... Margie la détective vient encore de résoudre une affaire explosive...",
