        },
        [80130421] = {
          Camera = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il y avait aussi une ville nommée Rougerive. La rivière y devenait rouge au coucher du soleil. Ça avait l’air si beau...",
          DialogueId = 80130421,
          FacialId = {
            [1] = "790023:Happy02"
          },
          GUID = "C8991D32",
          NextDialogue = 80130422,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991D32"
        },
        [80130422] = {
          Camera = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le rouge, je le connaissais que sous forme de sang. Je comprenais pas comment ça pouvait être beau, du rouge...",
          DialogueId = 80130422,
          FacialId = {
            [1] = "790023:None"
          },
          GUID = "C8991D5C",
          NextDialogue = 80130423,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991D5C"
        },
        [80130423] = {
          Camera = "-303.0,-180.0,112.583984,0.000004,-2.799988,17.9942,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et là... j’ai eu un vœu égoïste. Je me suis dit que je voulais voir ces choses-là, juste une fois : la neige blanche de Givrelac, le crépuscule rouge de Rougerive. Et ensuite... je te rendrais ton corps.",
          DialogueId = 80130423,
          FacialId = {
            [1] = "790023:Satisfy01"
          },
          GUID = "C8991D86",
          NextDialogue = 80130424,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991D86"
        },
        [80130424] = {
          Camera = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Maintenant, c’est fait. Je les ai vus. Je les garde bien en tête, alors...",
          DialogueId = 80130424,
          FacialId = {
            [1] = "790023:None"
          },
          GUID = "C8991DB0",
          NextDialogue = 80130425,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991DB0"
        },
        [80130425] = {
          Camera = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Ok, ça suffit.",
          DialogueId = 80130425,
          GUID = "C8991DDA",
          NextDialogue = 80130426,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991DDA"
        },
        [80130426] = {
          Camera = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’aurais jamais cru entendre un type avec ma tronche dire un truc pareil. À ce rythme-là, on finirait presque par croire que ce vieux fumier de Jones était un génie.",
          DialogueId = 80130426,
          GUID = "C8991E04",
          NextDialogue = 80130427,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991E04"
        },
        [80130427] = {
          Camera = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je te comprends. Moi non plus j’aime pas avoir des dettes. Quand t’as demandé à Jones de virer ce foutu tourne-disque, je me suis dit que tu m'avais déjà rendu la moitié de ma vie.",
          DialogueId = 80130427,
          GUID = "C8991E2E",
          NextDialogue = 80130428,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991E2E"
        },
        [80130428] = {
          Camera = "-306.0,-179.0,112.583984,0.000004,-2.799988,17.994255,36.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Après ça, on s’est barrés ensemble. Donc, pour moi, on était quittes.",
          DialogueId = 80130428,
          GUID = "C8991E58",
          NextDialogue = 80130429,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790024},AnimationId{\"Explain01_Start\"},Duration{3},_click{false}},\nPlayAnimation{ActorId{790024},AnimationId{\"Explain01_End\"},Duration{1},_click{false}}\n}",
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991E58"
        },
        [80130429] = {
          Camera = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais là, t’as recommencé à me devoir quelque chose. Pendant que t’étais évanoui, j’ai dû m’occuper tout seul d’une horde de gamins bruyants dans Crac’n’Pop.",
          DialogueId = 80130429,
          FacialId = {
            [1] = "790024:Yeer_EyeChangedSad"
          },
          GUID = "C8991E82",
          NextDialogue = 80130430,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790024},AnimationId{\"Sigh_Start\"},Duration{3},_click{false}},\nPlayAnimation{ActorId{790024},AnimationId{\"Sigh_End\"},Duration{1},_click{false}}\n}",
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991E82"
        },
        [80130430] = {
          Camera = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ils venaient tous pour toi, évidemment. J’ai dû faire semblant d’être toi, sourire comme un idiot, parler gentiment, rester calme...",
          DialogueId = 80130430,
          FacialId = {
            [1] = "790024:Yeer_EyeChanged"
          },
          GUID = "C8991EAC",
          NextDialogue = 80130431,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991EAC"
        },
        [80130431] = {
          ContentFR = "Ensuite, j’ai dû venir jusqu’à Givrelac, me replonger dans tous ces foutus souvenirs, et tout expliquer à {nickname}.",
          DialogueId = 80130431,
          GUID = "C8991ED6",
          NextDialogue = 80130432,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991ED6"
        },
        [80130432] = {
          Camera = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et tu crois que c’est en me refilant le corps que ça va s’effacer, tout ça ?",
          DialogueId = 80130432,
          GUID = "C8991F00",
          NextDialogue = 80130433,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991F00"
        },
        [80130433] = {
          ContentFR = "Et surtout, le plus important, t’as jamais demandé mon avis.",
          DialogueId = 80130433,
          GUID = "C8991F2A",
          NextDialogue = 80130434,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991F2A"
        },
        [80130434] = {
          Camera = "-55.089355,-146.949646,115.0,0.0,0.0,167.992569,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Yale, t’es pas juste un type qui me doit quelque chose. T’es aussi celui qui m’a sauvé. T’es mon meilleur pote. Et Crac’n’Pop, c’est autant ta boutique que la mienne.",
          DialogueId = 80130434,
          FacialId = {
            [1] = "790024:Yeer_EyeChangedSad"
          },
          GUID = "C8991F54",
          NextDialogue = 80130435,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991F54"
        },
        [80130435] = {
          Camera = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors arrête de t’excuser. Si tu veux vraiment te faire pardonner... Aide-moi à faire tourner la boutique. T’auras tout le temps de me rendre la pareille.",
          DialogueId = 80130435,
          GUID = "C8991F7E",
          NextDialogue = 80130436,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790024:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991F7E"
        },
        [80130436] = {
          Camera = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 80130436,
          GUID = "C8991FA8",
          LookAt = {
            [1] = "790023:p(79002GP)"
          },
          NextDialogue = 80130437,
          SpeakNpcId = 790023,
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991FA8"
        },
        [80130437] = {
          Camera = "-303.0,-180.0,112.583984,0.000004,-2.799988,17.9942,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Tu as raison... Si je m’effaçais maintenant, Crac’n’Pop ne pourrait plus rouvrir.",
          DialogueId = 80130437,
          FacialId = {
            [1] = "790024:Yeer_EyeChanged",
            [2] = "790023:Smile01"
          },
          GUID = "C8991FD2",
          LookAt = {
            [1] = "790023:n(790024)"
          },
          NextDialogue = 80130438,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991FD2"
        },
        [80130438] = {
          Camera = "-303.0,-180.0,112.583984,0.000004,-2.799988,17.9942,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis... j’ai lu des récits sur d’autres endroits aussi, qui avaient l’air magnifiques. Honnêtement, j’aimerais les découvrir, moi aussi.",
          DialogueId = 80130438,
          GUID = "C8991FFC",
          NextDialogue = 80130439,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991FFC"
        },
        [80130439] = {
          Camera = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas de souci, on y ira ensemble. Mais promets-moi une chose : pas de « je te rends ton corps » à chaque fois qu’un paysage est joli. D’accord ?",
          DialogueId = 80130439,
          GUID = "C8992026",
          NextDialogue = 80130440,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790023:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8992026"
        },
        [80130440] = {
          Camera = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Promis. Plus jamais. Rentrons. Les enfants doivent attendre l’ouverture de Crac’n’Pop.",
          DialogueId = 80130440,
          FacialId = {
            [1] = "790023:Happy02"
          },
          GUID = "C8992050",
          NextDialogue = 80130441,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8992050"
        },
        [80130441] = {
          Camera = "-315.086426,-472.144592,127.0,-0.0,-4.000004,58.795139,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et merci, {nickname}. Quand on sera rentrés, on t’enverra gratuitement un gros colis de P’tits Boum !",
          DialogueId = 80130441,
          GUID = "C899207A",
          NextOptions = {
            [1] = 801304411
          },
          SpeakNpcId = 790023,
          TurnTo = {
            [1] = "100001:n(790023)",
            [2] = "790023:n(100001)",
            [3] = "790024:n(100001)"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C899207A"
        },
        [80130443] = {
          ContentFR = "Une journée qui s’est éternisée touche enfin à sa fin. Ce n’est pas une nuit aussi longue qui s’installe, mais une douce lueur d’aube qui pointe à l’horizon, comme le signe d’un nouveau commencement.",
          DialogueId = 80130443,
          GUID = "C89920CE",
          VoiceName = "voice/$Locale$/inv/Yeer/004/C89920CE"
        },
        [80140101] = {
          ContentFR = "Qui es-tu ?",
          DialogueId = 80140101,
          Duration = 3,
          GUID = "C89F5152",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5152"
        },
        [80140102] = {
          ContentFR = "Qu’est-ce que tu fais ?",
          DialogueId = 80140102,
          Duration = 3,
          GUID = "C89F517C",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F517C"
        },
        [80140103] = {
          Camera = "308.258453,-324.54126,203.320312,0.000018,-13.199941,134.196289,45.171967,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis-moi, Parsifal, que s’est-il passé ? Qui t’a brisé les cornes ?",
          DialogueId = 80140103,
          FacialId = {
            [1] = "790031:CM_Angry01",
            [2] = "790030:Disappoint01"
          },
          GUID = "C89F51A6",
          LookAt = {
            [1] = "790031:n(790030)"
          },
          NextDialogue = 80140104,
          Scripts = "SetLocation{ActorId{790032},TargetPoint{"SetPoint_Puqi"},Visibility{"Hide"}}",
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F51A6"
        },
        [80140104] = {
          Camera = "-311.42627,-48.326935,136.539062,0.000017,-3.399344,6.607203,41.865784,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peu m’importe ce que pensent les autres à l’extérieur, mais ici, dans la troupe de la Flûte Enchantée, toute forme d’intimidation est strictement interdite. Nous ne laisserons pas la bêtise, la haine et les préjugés souiller notre art !",
          DialogueId = 80140104,
          GUID = "C89F51D0",
          LookAt = {
            [1] = "790031:n(790030)"
          },
          NextDialogue = 80140105,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F51D0"
        },
        [80140105] = {
          ContentFR = "N’aie pas peur, Parsifal. Dis simplement la vérité. Je te promets que la troupe agira justement et exclura tout coupable.",
          DialogueId = 80140105,
          GUID = "C89F51FA",
          LookAt = {
            [1] = "790031:n(790030)"
          },
          NextDialogue = 80140106,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F51FA"
        },
        [80140106] = {
          Camera = "-60.211216,-179.25705,55.679688,0.000037,18.399382,95.598686,58.124969,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Ne pas laisser la haine et les préjugés souiller l’art »... Madame Violetta, si la troupe n’avait pas cette règle tacite qui interdit aux Charons de monter sur scène, je vous croirais.",
          DialogueId = 80140106,
          GUID = "C89F5224",
          NextDialogue = 80140107,
          Scripts = "LookAt{_delay{6},LookAtDescription{"790030:n(790031)"}}",
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5224"
        },
        [80140107] = {
          Camera = "-64.211678,-24.009537,132.21875,0.000007,2.199819,-2.797291,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est parce que... !",
          DialogueId = 80140107,
          FacialId = {
            [1] = "790031:CM_Shock01"
          },
          GUID = "C89F524E",
          LookAt = {
            [1] = "790030:n(790031)"
          },
          NextDialogue = 80140108,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F524E"
        },
        [80140108] = {
          Camera = "285.028381,-293.271179,282.699219,0.000063,-23.799669,134.202179,35.63834,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Pardonnez-moi, Madame Violetta. Je n’aurais pas dû parler ainsi.",
          DialogueId = 80140108,
          FinalCamera = "249.140015,-256.372009,260.007812,0.000063,-23.799669,134.202179,35.63834,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5278",
          NextDialogue = 80140109,
          SpeakNpcId = 790030,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5278"
        },
        [80140109] = {
          ContentFR = "Je ne remets pas en cause vos intentions. Je sais que, comme notre mentor, vous ne faites aucune distinction entre Sola et Charon. Ce sont seulement les spectateurs, avec leur étroitesse d’esprit et leur arrogance, qui creusent ce fossé.",
          DialogueId = 80140109,
          GUID = "C89F52A2",
          NextDialogue = 80140110,
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F52A2"
        },
        [80140110] = {
          ContentFR = "Tous ici m’ont traité avec gentillesse. Personne ne m’a intimidé. Quant à mes cornes... c’est <H>moi qui les ai coupées</>.",
          DialogueId = 80140110,
          GUID = "C89F52CC",
          NextDialogue = 80140111,
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F52CC"
        },
        [80140111] = {
          ContentFR = "... Parsifal...",
          DialogueId = 80140111,
          GUID = "C89F52F6",
          NextDialogue = 80140112,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F52F6"
        },
        [80140112] = {
          Camera = "3689.480957,-784.508362,319.140625,0.000159,7.198042,-109.808243,11.909616,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je veux monter sur scène, Madame Violetta. Je veux chanter avec ma propre voix, voir le public de mes propres yeux, entrer dans ce monde éclairé par les projecteurs...",
          DialogueId = 80140112,
          FinalCamera = "3452.359619,-1442.865723,407.496094,0.000159,7.198042,-109.808243,11.909616,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5320",
          NextDialogue = 80140113,
          SpeakNpcId = 790030,
          TalkActionId = {
            [1] = "790031:Shock_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5320"
        },
        [80140113] = {
          Camera = "-79.301102,-133.298798,120.894531,0.000185,-0.201231,89.005852,42.56609,134.092804,false,Manual,2.8",
          ContentFR = "Tant que ces "cornes de démon" ne sont plus là, je pourrai enfin monter sur scène, non ?",
          DialogueId = 80140113,
          GUID = "C89F534A",
          NextDialogue = 80140114,
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F534A"
        },
        [80140114] = {
          Camera = "-72.874443,-96.31089,142.296875,0.000143,-1.001825,22.198147,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pauvre enfant...",
          DialogueId = 80140114,
          FacialId = {
            [1] = "790031:CM_Sad01"
          },
          GUID = "C89F5374",
          LookAt = {
            [1] = "790031:n(790030)"
          },
          NextDialogue = 80140115,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5374"
        },
        [80140115] = {
          Camera = "-39.245445,-88.370117,65.621094,0.000033,23.998367,110.798157,35.000011,76.612511,false,Manual,9.097586",
          ContentFR = "Mais arracher une partie de soi-même, ça fait mal. Donnez-moi encore un peu de temps, je finirai par retirer les morceaux restants...",
          DialogueId = 80140115,
          GUID = "C89F539E",
          NextDialogue = 80140116,
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F539E"
        },
        [80140116] = {
          Camera = "-272.279846,-55.369659,98.152344,0.000052,2.598238,8.203966,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Arrête ! Ne touche plus à tes cornes.",
          DialogueId = 80140116,
          GUID = "C89F53C8",
          NextDialogue = 80140117,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F53C8"
        },
        [80140117] = {
          ContentFR = "... J’ai pris ma décision. Pour la prochaine représentation de Né du blizzard, tu monteras sur scène avec Susanna et Fane. Tu seras le rôle principal : "La fée sans nom".",
          DialogueId = 80140117,
          GUID = "C89F53F2",
          NextDialogue = 80140118,
          Scripts = "PlayAnimation{_delay{3},ActorId{790031},AnimationId{"Talk03_End"},Duration{2},_click{false}},",
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F53F2"
        },
        [80140118] = {
          Camera = "269.129089,-303.197998,134.738281,0.000062,-1.001852,131.806335,42.862888,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Quoi ?",
          DialogueId = 80140118,
          FacialId = {
            [1] = "790030:Shock01"
          },
          GUID = "C89F541C",
          LookAt = {
            [1] = "790030:n(790031)"
          },
          NextDialogue = 80140119,
          Scripts = "SitOrStand{ActorId{790030},State{"Stand"}}",
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F541C"
        },
        [80140119] = {
          Camera = "-475.37677,-270.540131,435.15625,0.000049,-28.199356,17.585888,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violetta ! J’entends tes absurdités d’ici, donner à Parsifal le rôle principal ?!",
          DialogueId = 80140119,
          FacialId = {
            [1] = "790030:None"
          },
          FinalCamera = "-475.37677,-270.540131,403.910156,0.000049,-28.199356,17.585888,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5446",
          LookAt = {
            [1] = "790030:n(790032)",
            [2] = "790032:n(790031)"
          },
          NextDialogue = 80140120,
          Scripts = "MoveTo{ActorId{790032},MoveSpeed{80},TargetPoint{"P80140120"}}",
          SpeakNpcId = 790032,
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "790031:n(790032)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5446"
        },
        [80140120] = {
          ContentFR = "Tu es folle ? Demain, la ville entière saura qu’un Charon est la star de la troupe de la Flûte Enchantée ! Notre réputation vieille de plusieurs décennies sera ruinée !",
          DialogueId = 80140120,
          GUID = "C89F5470",
          LookAt = {
            [1] = "790031:n(790032)"
          },
          NextDialogue = 80140121,
          SpeakNpcId = 790032,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5470"
        },
        [80140121] = {
          Camera = "141.589691,-501.412964,133.425781,0.000001,-0.599643,94.196159,52.004452,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Calme-toi, Putsch. C’est un rôle de fée, un peu d’ornement sur la tête est naturel, non ? On demandera au chef accessoiriste de faire un accessoire extravagant, personne ne verra que Parsifal est un Charon.",
          DialogueId = 80140121,
          FacialId = {
            [1] = "790031:CM_Smile01"
          },
          GUID = "C89F549A",
          LookAt = {
            [1] = "790031:n(790032)"
          },
          NextDialogue = 80140122,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790031},AnimationId{\"Explain02_Start\"},Duration{2}},\nPlayAnimation{_delay{3},ActorId{790031},AnimationId{\"Explain02_End\"},Duration{1}}\n}",
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F549A"
        },
        [80140122] = {
          ContentFR = "Je m’occuperai personnellement des autres membres pour que tu ne sois pas gênée. Si un problème survient, tu diras que c’est moi qui ai forcé la troupe.",
          DialogueId = 80140122,
          GUID = "C89F54C4",
          NextDialogue = 80140123,
          Scripts = "SEQ{\nPlayAnimation{_delay{1.5},ActorId{790031},AnimationId{\"Disagree\"},Duration{2},_delay{2}},\nPlayAnimation{_delay{1.5},ActorId{790031},AnimationId{\"Explain01_Start\"},Duration{1}}\n}",
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F54C4"
        },
        [80140123] = {
          Camera = "141.589691,-501.412964,133.425781,0.000001,-0.599643,94.196159,52.004452,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis, tu le sais, Parsifal est le meilleur chanteur que nous ayons. Son talent dépasse même le mien à son âge. Sinon, il ne chanterait pas derrière le rideau depuis si longtemps.",
          DialogueId = 80140123,
          FinalCamera = "141.589691,-501.412964,133.425781,0.0,-0.399709,105.796799,52.004452,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F54EE",
          LookAt = {
            [1] = "790031:n(790030)",
            [2] = "790032:n(790030)"
          },
          NextDialogue = 80140124,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Explain01_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F54EE"
        },
        [80140124] = {
          ContentFR = "Je refuse de voir un don aussi rare et précieux rester enfoui dans l’ombre, privé de toute chance de s’épanouir. Parsifal mérite l’opportunité de briller sous les projecteurs.",
          DialogueId = 80140124,
          GUID = "C89F5518",
          NextDialogue = 80140125,
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5518"
        },
        [80140125] = {
          Camera = "-93.044205,115.413742,181.152344,0.000014,-13.400175,-51.013519,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais Né du blizzard est notre plus gros succès récent. Si on change le rôle principal sans prévenir, tout le monde voudra savoir qui est ce nouveau venu.",
          DialogueId = 80140125,
          GUID = "C89F5542",
          LookAt = {
            [1] = "790032:n(790031)",
            [2] = "790031:n(790032)"
          },
          NextDialogue = 80140126,
          SpeakNpcId = 790032,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5542"
        },
        [80140126] = {
          ContentFR = "Tu sais comment les journaux à Givrelac peuvent être impitoyables. Comment garderons-nous son secret ?",
          DialogueId = 80140126,
          GUID = "C89F556C",
          NextDialogue = 80140127,
          SpeakNpcId = 790032,
          TalkActionId = {
            [1] = "790032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F556C"
        },
        [80140127] = {
          Camera = "135.852097,-177.88208,141.5,0.000022,-1.199743,108.59391,35.0,154.067352,false,Manual,2.8",
          ContentFR = "À Givrelac, y a-t-il une nouvelle plus captivante que la dernière idylle de notre star locale Violetta ?",
          DialogueId = 80140127,
          FacialId = {
            [1] = "790031:CM_Smile01"
          },
          GUID = "C89F5596",
          NextDialogue = 80140128,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790032:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5596"
        },
        [80140128] = {
          Camera = "-16.624153,32.01741,155.753906,0.000003,-6.600373,-48.810413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu... tu veux dire que...",
          DialogueId = 80140128,
          FacialId = {
            [1] = "790031:CM_Idle"
          },
          GUID = "C89F55C0",
          NextDialogue = 80140129,
          SpeakNpcId = 790032,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F55C0"
        },
        [80140129] = {
          Camera = "132.767883,-339.10141,147.777344,0.000007,-3.800016,93.188416,43.91328,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je m’ennuie un peu ces temps-ci. Je prévois de sortir avec le Baron Andrew, boire un thé... Haha, j’ai hâte de voir les titres inventés par les journalistes.",
          DialogueId = 80140129,
          FacialId = {
            [1] = "790031:CM_Happy01"
          },
          GUID = "C89F55EA",
          NextDialogue = 80140130,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F55EA"
        },
        [80140130] = {
          Camera = "310.552002,-526.269592,200.597656,0.000119,-8.998903,116.991135,41.455132,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Soupir... Bon, d’accord. Mais tu ne porteras pas ça toute seule. Comme je l’ai toujours dit, dans une troupe, on est une famille. Quoi qu’il arrive, on fait face ensemble. Je m’occupe des accessoires.",
          DialogueId = 80140130,
          FacialId = {
            [1] = "790031:CM_Smile01"
          },
          FinalCamera = "292.040833,-535.704895,200.597656,0.000119,-8.998903,116.991135,41.455132,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5614",
          LookAt = {
            [1] = "790032:n(790031)"
          },
          NextDialogue = 80140131,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790032},AnimationId{\"Disagree\"},Duration{1},_click{false}},\nLookAt{_delay{4},LookAtDescription{\"790032:n(790030)\"}}\n}",
          SpeakNpcId = 790032,
          TalkActionId = {
            [1] = "790031:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5614"
        },
        [80140131] = {
          ContentFR = "Merci, Madame Violetta, Directrice Putsch. Mais si mon secret éclate, ce sera une honte pour la troupe...",
          DialogueId = 80140131,
          GUID = "C89F563E",
          NextDialogue = 80140132,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790030},AnimationId{\"DisagreeHead\"},Duration{1},_click{false}}\n}",
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F563E"
        },
        [80140132] = {
          Camera = "228.412537,-163.239441,130.269531,0.000019,1.000431,146.591461,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parsifal, regarde-moi dans les yeux, crois-tu en ta performance ?",
          DialogueId = 80140132,
          GUID = "C89F5668",
          LookAt = {
            [1] = "790030:n(790031)"
          },
          NextDialogue = 80140133,
          SpeakNpcId = 790031,
          TurnTo = {
            [1] = "790031:n(790030)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5668"
        },
        [80140133] = {
          ContentFR = "... Oui. J’y crois.",
          DialogueId = 80140133,
          GUID = "C89F5692",
          NextDialogue = 80140134,
          SpeakNpcId = 790030,
          TalkActionId = {
            [1] = "790030:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5692"
        },
        [80140134] = {
          Camera = "-185.420715,-82.395569,162.160156,0.000011,-6.399982,13.392228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors tout ira bien. Tu es mon élève le plus doué. Pense seulement à faire vivre le personnage, à toucher le public par ta voix et ton jeu, sans qu’ils se préoccupent de qui tu es.",
          DialogueId = 80140134,
          GUID = "C89F56BC",
          NextDialogue = 80140135,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790031},AnimationId{\"Disagree\"},Duration{1},_click{false}},\nPlayAnimation{_delay{4},ActorId{790031},AnimationId{\"Explain01_Start\"},Duration{3},_click{false}}\n}",
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F56BC"
        },
        [80140135] = {
          Camera = "67.660095,-107.371399,151.609375,0.000017,0.599984,137.796341,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Je comprends. Je donnerai tout à chaque répétition. Je leur montrerai... comment une vraie fée prend vie dans un script et une partition.",
          DialogueId = 80140135,
          FacialId = {
            [1] = "790030:Happy01"
          },
          GUID = "C89F56E6",
          NextDialogue = 80140136,
          SpeakNpcId = 790030,
          TalkActionId = {
            [1] = "790031:Explain01_End",
            [2] = "790030:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F56E6"
        },
        [80140136] = {
          Camera = "-176.469574,-68.699188,170.910156,0.000072,-9.199588,8.997595,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Allez, ne te stresse pas. Sois toi-même, ça suffira. Moi aussi, je suis impatiente... Peut-être que ce sera la meilleure représentation de Né du blizzard de tous les temps.",
          DialogueId = 80140136,
          FacialId = {
            [1] = "790031:CM_Happy01"
          },
          GUID = "C89F5710",
          NextDialogue = 80140137,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790031},AnimationId{\"Confident_Start\"},Duration{3},_click{false}},\nPlayAnimation{ActorId{790031},AnimationId{\"Confident_End\"},Duration{1},_click{false}}\n}",
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5710"
        },
        [80140137] = {
          Camera = "332.264832,-264.852875,133.148438,0.000017,-1.400052,144.39798,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je le ferai. Je chanterai mieux que tous, pour que vous et ma mère soyez fiers de moi.",
          DialogueId = 80140137,
          GUID = "C89F573A",
          NextDialogue = 80140138,
          SpeakNpcId = 790030,
          TalkActionId = {
            [1] = "790030:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F573A"
        },
        [80140138] = {
          ContentFR = "J’ai hâte de voir ça.",
          DialogueId = 80140138,
          GUID = "C89F5764",
          NextDialogue = 80140139,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5764"
        },
        [80140139] = {
          ContentFR = "Mesdames et messieurs, ce soir marque les débuts sur scène de Parsifal Snowfield, le nouveau talent de la troupe de la Flûte Enchantée. Offrons-lui nos fleurs et applaudissements, et attendons-nous à d’autres performances éclatantes !",
          DialogueId = 80140139,
          GUID = "C89F578E",
          IsBlack = 1,
          NextDialogue = 80140164,
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F578E"
        },
        [80140140] = {
          Camera = "315.0,615.696289,269.0,0.000017,-22.79999,-124.998627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouah... Quel spectacle ! Le rôle principal était parfait, je ne m’en lasse pas ! Parsifal ? Je ne l’avais jamais entendu avant. C’est une star venue d’ailleurs ?",
          DialogueId = 80140140,
          FinalCamera = "306.0,615.696289,269.0,0.000017,-22.79999,-124.998627,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F57B8",
          NextDialogue = 80140141,
          SpeakNpcId = 790033,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F57B8"
        },
        [80140141] = {
          ContentFR = "Pourtant, sa voix ressemble à celle du précédent rôle principale... Une imitation ?",
          DialogueId = 80140141,
          GUID = "C89F57E2",
          NextDialogue = 80140142,
          SpeakNpcId = 790034,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F57E2"
        },
        [80140142] = {
          Camera = "-330.339844,-54.918457,134.652344,0.000047,-17.400023,59.799068,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mademoiselle Violetta ! Ô ma rose écarlate, ma douce lune, la jardinière de mon âme, ma déesse de rêve, éclairez ma nuit !",
          DialogueId = 80140142,
          FacialId = {
            [1] = "790035:CM_Happy01"
          },
          GUID = "C89F580C",
          SpeakNpcId = 790035,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F580C"
        },
        [80140143] = {
          Camera = "773.728516,172.965027,562.851562,0.000013,-24.400105,-161.396423,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi... ?",
          DialogueId = 80140143,
          FinalCamera = "473.599609,71.939758,419.191406,0.000013,-24.400105,-161.396423,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5836",
          NextDialogue = 80140144,
          Scripts = "SEQ{\nMoveTo{ActorId{790039},MoveSpeed{260},TargetPoint{\"P80140143\"}},\nTurnTo{_click{false},TurnToDescription{\"790039:n(790031)\"}}\n}",
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Shock_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5836"
        },
        [80140144] = {
          Camera = "109.757812,-116.020081,131.90625,0.000012,-3.599912,-163.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dites-moi ! Ce qu’ont écrit les journaux, c’est faux, non ? Comment pourriez-vous vous abaisser à sortir avec un baron frivole, salissant votre pureté, Mademoiselle Violetta !",
          DialogueId = 80140144,
          FacialId = {
            [1] = "790039:CM_Angry01"
          },
          GUID = "C89F5860",
          LookAt = {
            [1] = "790038:n(790031)",
            [2] = "790037:n(790031)"
          },
          NextDialogue = 80140145,
          Scripts = "SEQ{\nMoveTo{_delay{6},ActorId{790039},MoveSpeed{80},TargetPoint{\"P80140145\"}},\nPlayAnimation{ActorId{790039},AnimationId{\"Angry01_Start\"},Duration{1},_click{false}}\n}",
          SpeakNpcId = 790039,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5860"
        },
        [80140145] = {
          Camera = "218.556641,-87.356079,99.0,0.000011,0.0,-170.399063,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Madame Violetta, faites attention !",
          DialogueId = 80140145,
          FacialId = {
            [1] = "790036:Shock01"
          },
          GUID = "C89F588A",
          IsBlack = 1,
          NextDialogue = 80140146,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F588A"
        },
        [80140146] = {
          Camera = "218.556641,-87.356079,99.0,0.000011,0.0,-170.399063,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sale gosse, dégage... toi... toi... un Charon ?!",
          DialogueId = 80140146,
          GUID = "C89F58B4",
          IsBlack = 1,
          NextDialogue = 80140147,
          Scripts = "PARA{\nSetLocation{ActorId{790036},TargetPoint{\"P80140146\"},Visibility{\"Show\"}},\nSetLocation{ActorId{790039},TargetPoint{\"P80140143\"},Visibility{\"Show\"}}\n}",
