          TalkActionId = {
            [1] = "790039:Shock_Start",
            [2] = "790031:Shock_End"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5908"
        },
        [80140149] = {
          ContentFR = "Un Charon sur scène ? La troupe est folle ?",
          DialogueId = 80140149,
          FacialId = {
            [1] = "790036:Shock01"
          },
          GUID = "C89F5932",
          NextDialogue = 80140150,
          Scripts = "PlayAnimation{ActorId{790036},AnimationId{"Sigh_End"},Duration{1},_click{false}}",
          SpeakNpcId = 790034,
          SpeakNpcName = "UI_CMNpc_Name_UproarAudience",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5932"
        },
        [80140150] = {
          ContentFR = "Comment osez-vous tromper le public, laisser ce démon salir nos yeux ? Où est le responsable ? Qu’il se montre !",
          DialogueId = 80140150,
          GUID = "C89F595C",
          NextDialogue = 80140151,
          SpeakNpcId = 790039,
          TalkActionId = {
            [1] = "790031:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F595C"
        },
        [80140151] = {
          Camera = "-911.287109,-294.924744,160.019531,0.000016,-3.999909,5.600585,53.01371,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est moi qui ai trompé la Directrice et Madame Violetta, pas eux ! S’il vous plaît...",
          DialogueId = 80140151,
          GUID = "C89F5986",
          LookAt = {
            [1] = "790036:n(790039)"
          },
          NextDialogue = 80140152,
          Scripts = "SEQ{\nPlayAnimation{ActorId{790036},AnimationId{\"Explain02_Start\"},Duration{3},_click{false}},\nPlayAnimation{ActorId{790036},AnimationId{\"Explain02_End\"},Duration{1},_click{false}}\n}",
