          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7372"
        },
        [80140310] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000432,50.799896,-6.183147,17.953863,125.0,false,DoNotOverride,2.8",
          ContentFR = "... Je me sens si mal... Qu’est-ce que vous m’avez fait... ?",
          DialogueId = 80140310,
          FinalCamera = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,17.953863,125.0,false,DoNotOverride,2.8",
