          NextDialogue = 80140330,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F76BA"
        },
        [80140330] = {
          ContentFR = "Est-ce que je pourrais... redevenir... comme avant ?",
          DialogueId = 80140330,
          GUID = "C89F76E4",
          NextDialogue = 80140331,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F76E4"
        },
        [80140331] = {
          ContentFR = "Ahah... AHAHAH ! Redevenir comme avant ? On n’a même pas touché à ton cerveau, c’est le feu qui t’a cramé la cervelle, ou t’étais déjà débile à la base ?",
          DialogueId = 80140331,
          GUID = "C89F770E",
          NextDialogue = 80140332,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F770E"
        },
        [80140332] = {
          ContentFR = "Ce qu’on voulait, c’était un monstre, un récipient, une arme fiable, mais sûrement pas toi. Comment pourrais-tu croire qu’on allait te rendre ta forme d’avant ?",
          DialogueId = 80140332,
          GUID = "C89F7738",
          NextDialogue = 80140333,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7738"
        },
        [80140333] = {
          ContentFR = "Pourquoi... POURQUOI ?!",
          DialogueId = 80140333,
          GUID = "C89F7762",
          NextDialogue = 80140334,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7762"
        },
        [80140334] = {
          ContentFR = "« Pourquoi » ?",
          DialogueId = 80140334,
          GUID = "C89F778C",
          NextDialogue = 80140335,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F778C"
        },
        [80140335] = {
          ContentFR = "Est-ce que tu t’excuses quand tu écrases une fourmi ? Tu expliques à une cerise pourquoi tu la broies entre tes dents ?",
          DialogueId = 80140335,
          GUID = "C89F77B6",
          NextDialogue = 80140336,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F77B6"
        },
        [80140336] = {
          ContentFR = "Ah, pardon... J’avais oublié. Un rebut comme toi a sans doute jamais goûté une cerise de sa vie.",
          DialogueId = 80140336,
          GUID = "C89F77E0",
