        [80140425] = {
          Camera = "43.179199,176.508789,110.248047,0.000011,-3.59994,23.599939,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Ouais. J’étais furieux. À cause de lui et de Madame Violetta, on a annulé la pièce. Tout ce travail... gâché.",
          DialogueId = 80140425,
          FacialId = {
            [1] = "790026:CM_Shock01"
          },
          GUID = "C89F867A",
          LookAt = {
            [1] = "790026:n(790027)"
          },
          NextDialogue = 80140426,
          SpeakNpcId = 790027,
          TurnTo = {
            [1] = "790027:p(90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F867A"
        },
        [80140426] = {
          ContentFR = "Mais... je me suis souvent demandé depuis, est-ce qu’il avait vraiment tort de monter sur scène ? Est-ce que c’était sa faute à lui, ou celle de cette foutue règle qui interdit aux Charons de jouer ?",
          DialogueId = 80140426,
          GUID = "C89F86A4",
          LookAt = {
            [1] = "790027:n(790026)"
          },
          NextDialogue = 80140427,
          SpeakNpcId = 790027,
          TurnTo = {
            [1] = "790027:n(790026)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86A4"
        },
        [80140427] = {
          ContentFR = "Pourquoi on monte sur scène ? Pour <H>célébrer l’art, ce qu’il a de plus pur</>...",
          DialogueId = 80140427,
          GUID = "C89F86CE",
          NextDialogue = 80140428,
          SpeakNpcId = 790027,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86CE"
        },
        [80140428] = {
          ContentFR = "Alors pourquoi les gens regardent les cornes avant la performance ? Si on jouait tous derrière un rideau, Parsifal serait-il différent de nous ?",
          DialogueId = 80140428,
          GUID = "C89F86F8",
          NextDialogue = 80140429,
          SpeakNpcId = 790027,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86F8"
        },
        [80140429] = {
          Camera = "184.165039,231.606201,98.688477,0.00003,4.399932,43.401665,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh si, y’a une différence. Il chantait mieux que moi.",
          DialogueId = 80140429,
          FacialId = {
            [1] = "790027:CM_Idle"
          },
          GUID = "C89F8722",
          NextDialogue = 80140430,
          SpeakNpcId = 790027,
          TalkActionId = {
            [1] = "790027:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8722"
        },
        [80140430] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouah. Entendre ça de toi, c’est rare. Dennis, le grand impulsif, aurait-il mûri ?",
          DialogueId = 80140430,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F874C",
          NextDialogue = 80140431,
          SpeakNpcId = 790026,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F874C"
        },
        [80140431] = {
          Camera = "96.443359,130.570557,116.894043,0.000003,-3.99997,42.200706,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hé ! Commence pas à jouer la directrice, toi !",
          DialogueId = 80140431,
          FacialId = {
            [1] = "790027:CM_Angry01"
          },
          GUID = "C89F8776",
          NextDialogue = 80140432,
          SpeakNpcId = 790027,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8776"
        },
        [80140432] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais non, c’était un compliment ! Mais si Parsifal réapparaît un jour, je lui passerai un sacré savon. Disparaître comme ça, sans une lettre... Je lui en veux, mais il me manque.",
          DialogueId = 80140432,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          GUID = "C89F87A0",
          NextDialogue = 80140433,
          SpeakNpcId = 790026,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87A0"
        },
        [80140433] = {
          Camera = "-1153.268066,1960.390137,235.713867,0.000035,-6.800218,-58.593773,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Susanna... Dennis...",
          DialogueId = 80140433,
          GUID = "C89F87CA",
          NextDialogue = 80140434,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Paxi",
          TalkActionId = {
            [1] = "790025:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87CA"
        },
        [80140434] = {
          Camera = "185.86377,442.624756,59.498047,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu te souviens de ce que disait Violetta ? « Peut-être pas aujourd’hui, mais un jour, notre art connaîtra une époque plus pure. Une époque sans Solariens ni Charons, où seule comptera la beauté du jeu. »",
          DialogueId = 80140434,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          FinalCamera = "199.419434,397.746582,69.291504,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F87F4",
          NextDialogue = 80140435,
          SpeakNpcId = 790026,
          TalkActionId = {
            [1] = "790025:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87F4"
        },
        [80140435] = {
          ContentFR = "Je pense que, même si Violetta et Parsifal ont été rejetés, s’ils ont couvert notre troupe de honte... c’est justement grâce à des gens comme eux qu’un avenir meilleur pourra voir le jour.",
          DialogueId = 80140435,
          GUID = "C89F881E",
          NextDialogue = 80140436,
          SpeakNpcId = 790026,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F881E"
        },
        [80140436] = {
          ContentFR = "Ce jour-là, ils ne seront plus une "honte", mais des "héros" qui ont simplement ouvert les yeux avant les autres.",
          DialogueId = 80140436,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F8848",
          NextDialogue = 80140437,
          SpeakNpcId = 790026,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8848"
        },
        [80140437] = {
          Camera = "-475.065918,1530.032227,242.341553,0.000032,-7.199647,-170.999466,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 80140437,
          GUID = "C89F8872",
          NextDialogue = 80140438,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Paxi",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8872"
        },
        [80140438] = {
          Camera = "52.178223,609.198242,243.78833,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Souhaitons-lui bonne chance ! Peut-être qu’il est déjà dans un endroit où les Charons ont le droit de monter sur scène, comme à Luca ou à Aethyrie.",
          DialogueId = 80140438,
          FinalCamera = "-116.030762,898.193115,370.702637,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F889C",
          NextDialogue = 80140439,
          SpeakNpcId = 790026,
          TalkActionId = {
            [1] = "790026:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F889C"
        },
        [80140439] = {
          ContentFR = "Et qui sait, quand on partira en tournée là-bas, peut-être qu’on tombera sur lui... devenu une grande star comme Madame Violetta !",
          DialogueId = 80140439,
          GUID = "C89F88C6",
          LookAt = {
            [1] = "790025:n(790025)"
          },
          NextDialogue = 80140440,
          SpeakNpcId = 790026,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F88C6"
        },
        [80140440] = {
          ContentFR = "Ouais. J’espère qu’un jour, on remontera tous ensemble sur scène.",
          DialogueId = 80140440,
          GUID = "C89F88F0",
          LookAt = {
            [1] = "790027:n(790027)",
            [2] = "790026:n(790026)"
          },
          NextDialogue = 80140454,
          SpeakNpcId = 790027,
          TalkActionId = {
            [1] = "790026:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F88F0"
        },
        [80140441] = {
          Camera = "644.496094,-490.569336,714.540771,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
          ContentFR = "Si... si toi et moi nous étions rencontrés en tant qu’humains... est-ce qu’on serait tous les quatre sortis ensemble du théâtre, en riant comme ce soir ?",
          DialogueId = 80140441,
          FinalCamera = "644.496094,-490.569336,603.562866,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F891A",
          LookAt = {
            [1] = "790029:n(790028)"
          },
          NextDialogue = 80140442,
          SpeakNpcId = 790029,
          TalkActionId = {
            [1] = "790029:Explain02_Start",
            [2] = "790028:Tuosi02_Emo_Idle_Pose"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F891A"
        },
        [80140442] = {
          ContentFR = "Susanna t’aurait sauté dessus pour que tu l’accompagnes gratuitement, et toi, évidemment, t’aurais accepté sans discuter. On aurait tous fini dehors à répéter dans le froid, juste pour lui faire plaisir.",
          DialogueId = 80140442,
          GUID = "C89F8944",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_02.T_Story_Recall_110304_02'",
          NextDialogue = 80140443,
          SpeakNpcId = 790029,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8944"
        },
        [80140443] = {
          ContentFR = "Mais toi... tu avais une famille. Ta sœur, toujours sérieuse, toujours droite, serait sûrement venue te chercher. Ou alors... c’est toi qui l’aurais embarquée avec nous. Oui, c’est plus ton genre, ça.",
          DialogueId = 80140443,
          GUID = "C89F896E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_01.T_Story_Recall_110304_01'",
          NextDialogue = 80140444,
          SpeakNpcId = 790029,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F896E"
        },
        [80140444] = {
          ContentFR = "Non. Impossible. Qu’est-ce que je suis encore en train de m’inventer ?",
          DialogueId = 80140444,
          GUID = "C89F8998",
          IsBlack = 1,
          NextDialogue = 80140445,
          SpeakNpcId = 790029,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8998"
        },
        [80140445] = {
          ContentFR = "Cette scène, ces rôles, ces amis... c’était Parsifal. Ce n’est plus moi.",
          DialogueId = 80140445,
          GUID = "C89F89C2",
          IsBlack = 1,
          NextDialogue = 80140446,
          SpeakNpcId = 790029,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F89C2"
        },
        [80140446] = {
          ContentFR = "Mais...",
          DialogueId = 80140446,
          GUID = "C89F89EC",
          IsBlack = 1,
          NextDialogue = 80140447,
          SpeakNpcId = 790029,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F89EC"
        },
        [80140447] = {
          Camera = "612.479492,-311.0,51.0,-0.0,6.400003,149.998077,35.0,407.658783,false,DoNotOverride,1.2",
          ContentFR = "Ici, il me reste un dernier rôle. Et moi seul peux l’interpréter.",
          DialogueId = 80140447,
          GUID = "C89F8A16",
          NextDialogue = 80140448,
          Scripts = "PlayAnimation{_click{false},_delay{5},ActorId{790029},AnimationId{"Explain02_End"},Duration{1}}",
          SpeakNpcId = 790029,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A16"
        },
        [80140448] = {
          Camera = "101.459473,-124.397461,114.37085,0.00001,19.398399,147.190094,35.000008,407.658783,false,DoNotOverride,1.2",
          ContentFR = "J’ai trouvé assez de peintures, d’huiles, pour me faire passer pour toi. J’ai vu votre planque. Et avec la chaîne que tu m’as laissée...",
          DialogueId = 80140448,
          FinalCamera = "33.354004,-80.496094,142.904297,0.00001,19.398399,147.190094,35.000008,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F8A40",
          NextDialogue = 80140449,
          Scripts = "SEQ{\nPlayAnimation{_click{false},ActorId{790029},AnimationId{\"Talk01_Start\"},Duration{1}},\nPlayAnimation{_click{false},_delay{5},ActorId{790029},AnimationId{\"Talk01_End\"},Duration{1}},\nPlayAnimation{_click{false},ActorId{790029},AnimationId{\"Agree\"},Duration{1},_delay{1}}\n}",
          SpeakNpcId = 790029,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A40"
        },
        [80140449] = {
          Camera = "-1737.0,1331.0,973.443848,-0.000001,29.000006,-64.800743,35.0,407.658783,false,DoNotOverride,1.2",
          ContentFR = "Le comédien est prêt. Le costume, les accessoires, le décor aussi. Il ne manque plus que le rideau qui se lève.",
          DialogueId = 80140449,
          FinalCamera = "-1737.0,1331.0,973.443848,-0.000001,30.999987,-64.80072,35.0,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F8A6A",
          LookAt = {
            [1] = "790029:n(790029)"
          },
          NextDialogue = 80140450,
          SpeakNpcId = 790029,
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "790029:p(-90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A6A"
        },
        [80140450] = {
          Camera = "613.405762,312.25,52.490479,0.000005,6.699862,-153.800339,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne t’en fais pas, Blues. J’ai promis. Et je tiendrai parole.",
          DialogueId = 80140450,
          FinalCamera = "640.817383,256.542969,52.490479,0.000005,6.699862,-153.800339,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F8A94",
          Scripts = "SEQ{\nMoveTo{_click{false},ActorId{790029},MoveSpeed{95},TargetPoint{\"P80140449\"}},\nCameraMoveTo{_click{false},_delay{4},TargetPosition{\"58.193848,40.453125,189.723633,0.0,2.899996,-130.398499,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},\nLookAt{_click{false},LookAtDescription{\"790029:n(790028)\"}}\n}",
          SpeakNpcId = 790029,
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A94"
        },
        [80140451] = {
          ContentFR = "Je suis un comédien. Fier. Voici mon chant d’adieu.",
          DialogueId = 80140451,
          Duration = 4,
          GUID = "C89F8ABE",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8ABE"
        },
        [80140452] = {
          ContentFR = "Puis, je quitterai la scène. Rideau.",
          DialogueId = 80140452,
