        },
        [80150109] = {
          Camera = "-36.580048,-34.005859,134.240494,0.000189,0.610011,71.466766,25.0,116.244736,false,Manual,3.0",
          ContentFR = "Attends. Je remets mes gants. Je ne voudrais pas te blesser par accident.",
          DialogueId = 80150109,
