          ContentFR = "{性别:Désolé|Désolée}, je t’ai fait attendre ?",
          DialogueId = 80150110,
          FacialId = {
            [1] = "790044:None"
          },
          GUID = "C8A5BB6C",
          NextDialogue = 80150111,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BB6C"
        },
        [80150111] = {
          Camera = "-61.534256,-174.127441,136.342422,0.000261,-1.99352,69.701683,35.000011,1.5,false,DoNotOverride,15.0",
          ContentFR = "Non, ce n’est rien... C’est moi qui suis arrivée trop tôt.",
          DialogueId = 80150111,
          FacialId = {
            [1] = "790044:Smile01"
          },
          GUID = "C8A5BB96",
          NextDialogue = 80150112,
