        },
        [80150121] = {
          Camera = "-5.2649,-7.188477,165.547684,0.000205,-19.394308,83.935265,27.000002,577.353577,false,DoNotOverride,3.0",
          ContentFR = "En y repensant, j’ai l’impression de n’avoir servi à rien. Je venais juste plus tôt, veillais à ce que mes hommes ne brutalisent pas les Charons... rien de plus.",
          DialogueId = 80150121,
          FacialId = {
            [1] = "790044:Sad01"
          },
          FinalCamera = "-5.2649,-7.188477,165.547684,0.000213,-19.394308,83.935249,29.0,577.353577,false,DoNotOverride,3.0",
          GUID = "C8A5BD3A",
          NextDialogue = 80150122,
          SpeakNpcId = 790044,
          TalkActionId = {
            [1] = "790044:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BD3A"
        },
        [80150122] = {
          Camera = "1.409618,-55.074219,133.131363,0.000191,-2.394548,92.124672,25.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "C’est ironique, tu ne trouves pas ? J’ai mis tant d’efforts à m’adapter à la Légion, à vouloir la réformer... Et au final, je n’ai rien changé. C’est elle qui m’a changée.",
          DialogueId = 80150122,
          FacialId = {
