        },
        [80150128] = {
          Camera = "51.694923,-135.471191,130.445541,0.000198,-2.39004,114.467331,25.0,222.044281,false,Manual,3.0",
          ContentFR = "Mais toi, tu as agi. Comparé à ceux qui ont détourné le regard, tu t’es tenue droite.",
          DialogueId = 80150128,
          FacialId = {
            [1] = "790008:Unhappy01"
          },
          FinalCamera = "54.578606,-134.157715,130.445541,0.000198,-2.39004,114.467331,25.0,222.044281,false,Manual,3.0",
