            [1] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BE60"
        },
        [80150129] = {
          Camera = "64.961464,239.010254,146.234573,0.000215,-4.794485,-107.101105,36.0,1.5,false,DoNotOverride,15.0",
          ContentFR = "Tu as ressenti de la colère, de l’injustice, et tu as essayé de changer les choses. Et maintenant, tu as quitté la Légion. C’est la preuve que tu ne t’es pas laissée corrompre. Tu es restée toi-même.",
          DialogueId = 80150129,
          FacialId = {
            [1] = "790044:Sad01",
            [2] = "\n790008:None"
          },
          FinalCamera = "78.562416,234.505371,146.234573,0.000217,-4.594483,-110.301086,36.0,1.5,false,DoNotOverride,15.0",
