          ContentFR = "La prochaine fois qu’on se voit... je ne viendrai pas en avance.",
          DialogueId = 80150134,
          FacialId = {
            [1] = "790044:Happy01"
          },
          FinalCamera = "-6.938042,-5.080078,140.156479,0.000422,-0.797117,86.295303,31.0,81.0,false,Manual,3.0",
          GUID = "C8A5BF5C",
