        [80150239] = {
          Camera = "701.533142,-19.678223,342.430603,0.001379,-20.598722,179.159149,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Alors c’est décidé. À partir d’aujourd’hui, je vais sérieusement... "m’arrêter". Et tester les métiers... dans l’ordre alphabétique.",
          DialogueId = 80150239,
          FinalCamera = "750.443481,-20.394043,360.815552,0.001379,-20.598722,179.159149,35.000008,291.99585,false,DoNotOverride,15.0",
