          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DE5E"
        },
        [80150324] = {
          Camera = "38.568848,23.305664,122.765625,0.000132,6.796339,-167.826828,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Je pense que ton prénom, « Rhythm », veut dire un peu la même chose... Ce n’est pas que tu dois vivre selon un rythme imposé, mais que tu trouves le tien, à toi.",
          DialogueId = 80150324,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "38.568848,23.305664,122.765625,0.000139,6.796339,-167.826813,37.0,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DE88",
          NextDialogue = 80150325,
          SpeakNpcId = 790008,
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DE88"
        },
        [80150325] = {
          Camera = "-167.373047,41.786133,148.665527,0.000146,-6.203799,-14.629342,35.0,245.243332,false,Manual,5.0",
          ContentFR = "Alors, tu n’as pas à être toujours aussi tendue, à te surcharger. Vis un peu plus librement, décide toi-même quand avancer, quand t’arrêter. Quel est ton propre « rythme », Rhythm ? Je crois qu’une fois que tu maîtriseras vraiment ce morceau, tu comprendras.",
          DialogueId = 80150325,
          GUID = "C8A5DEB2",
          NextDialogue = 80150326,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Think_End"
