        },
        [80160101] = {
          Camera = "151.585999,-190.824707,95.898872,0.000003,1.80011,-153.390167,39.474983,223.616684,false,Manual,2.8",
          ContentFR = "C’est un endroit plutôt calme.",
          DialogueId = 80160101,
          Duration = 1,
