        },
        [80180210] = {
          Camera = "27.647949,-145.186035,176.830078,0.000124,-27.800474,-122.401695,30.000002,284.222046,false,DoNotOverride,2.8",
          ContentFR = "Tu m’appelais "Sibylle" avant... Mais peu importe.",
          DialogueId = 80180210,
          FinalCamera = "30.851074,-147.144043,176.830078,0.000117,-27.800474,-125.801666,30.000002,284.222046,false,DoNotOverride,2.8",
          GUID = "C8B905B4",
