        [80200050] = {
          Camera = "29.712376,30.286741,171.701172,0.000042,-16.598623,100.198341,35.0,121.834335,false,Manual,7.870067",
          Content = "我可能是天生觉少……不过我有多梦的症状。有时从梦中突然惊醒，就再也睡不着了。",
          DialogueId = 80200050,
          FinalCamera = "31.944149,17.895794,175.456055,0.000043,-16.598602,100.198334,35.0,141.404282,false,Manual,7.870067",
          GUID = "C8C5BCB4",
          NextDialogue = 80200051,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BCB4"
        },
        [80200051] = {
