            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BCDE"
        },
        [80200052] = {
          Camera = "360.680786,-114.169701,136.203125,0.000063,-0.798668,151.998245,40.0,439.529266,false,Manual,7.870067",
          Content = "不过我已经想好了一剂药方，不敢保证药到病除，但坚持服用也会有所裨益。",
          DialogueId = 80200052,
          FinalCamera = "383.679688,-126.399124,136.564453,0.000063,-0.798668,151.998245,40.0,439.529266,false,Manual,7.870067",
          GUID = "C8C5BD08",
          NextDialogue = 80200053,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790008:Shy03_Start",
            [2] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD08"
        },
        [80200053] = {
          Camera = "-677.720764,380.481873,76.758789,0.000025,-31.199032,162.811325,35.0,313.548645,false,Manual,1.445948",
          Content = "只是……其中最关键的一味“怀梦草”，是枯荣阁中没有的。要去百年春求购，又需好些时日。",
          DialogueId = 80200053,
          FinalCamera = "-710.28772,390.565186,56.109375,0.000025,-31.199032,162.811325,35.000008,732.714722,false,DoNotOverride,1.445948",
          GUID = "C8C5BD32",
          NextDialogue = 80200054,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD32"
        },
        [80200054] = {
          Camera = "778.143555,49.141846,84.628906,0.000074,3.000878,175.011826,35.0,841.834229,false,Manual,1.445948",
          Content = "最好便是枯荣阁附近寻上一寻，若是幸运，今晚你便能好好休息了。不知你意下如何呢？",
          DialogueId = 80200054,
          FinalCamera = "775.015259,13.243744,84.628906,0.000074,3.000878,175.011826,35.0,841.834229,false,Manual,1.445948",
