          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C70A"
        },
        [80200114] = {
          Content = "因此，我打算尝一口。",
          DialogueId = 80200114,
          GUID = "C8C5C734",
          NextOptions = {
            [1] = 802001141,
            [2] = 802001142,
            [3] = 802001143
