        },
        [80200218] = {
          Camera = "-84.304626,35.644173,65.415039,0.000002,2.396269,78.78582,35.0,107.243362,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "麻烦。麻烦。麻烦。麻烦！",
          DialogueId = 80200218,
          FacialId = {
            [1] = "790054:Angry01"
          },
          FinalCamera = "-66.061569,127.614021,68.84082,0.000002,1.396248,78.785858,35.0,107.243362,false,DoNotOverride,2.8",
          GUID = "C8C5D208",
          NextDialogue = 80200219,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？",
          TalkActionId = {
