          SpeakNpcId = 790054,
          SpeakNpcName = "？？？",
          TalkActionId = {
            [1] = "790054:Angry01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D232"
        },
        [80200220] = {
          Camera = "-2343.795166,1023.041992,114.227539,0.000092,-0.803982,-4.996912,35.0,2401.962891,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "扶风啊扶风！你怎能如此沉不住气呢！那小妮子脾气再臭，也是你亲妹子！你又不可能扔下她不管，干嘛总是气她呢！",
          DialogueId = 80200220,
          FinalCamera = "-2335.671875,1115.896973,114.227539,0.000092,-0.803982,-4.997154,35.0,2401.962891,false,Manual,2.8",
          GUID = "C8C5D25C",
          NextDialogue = 80200221,
          Scripts = "PARA{\nTurnTo{_delay{1.01},TurnToDescription{\"790054:p(90))\"}},\nPlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}},\nPlayAnimation{_delay{9.01},ActorId{790054},AnimationId{\"Talk03_End\"},Duration{1}}\n}",
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？",
          TalkActionId = {
