          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D25C"
        },
        [80200221] = {
          Camera = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
          Content = "没办法啊没办法，扶疏那一本正经的样子，实在是很好气……笑容没有消失，只是从扶疏妹妹的脸上，移到了我的脸上……",
          DialogueId = 80200221,
          FacialId = {
            [1] = "790054:Sad01"
          },
          GUID = "C8C5D286",
          NextDialogue = 80200222,
