        [80200223] = {
          Content = "扶、扶疏？是你吗？",
          DialogueId = 80200223,
          Duration = 1,
          GUID = "C8C5D2DA",
          LookAt = {
            [1] = "790008:n(790054)",
            [2] = "790054:n(790008)"
          },
          NextDialogue = 80200224,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D2DA"
        },
        [80200224] = {
          Camera = "-5.917664,812.056946,114.511719,0.000043,2.986077,54.542389,35.000015,234.030762,false,Manual,3.823875",
          CameraBlendCurve = "easeInOutQuad",
          Content = "不是哦。我是扶疏的双胞胎姐姐，扶风。将我俩弄混的人，你不是第一个。",
          DialogueId = 80200224,
          FacialId = {
            [1] = "790008:None",
            [2] = "790054:None"
          },
          FinalCamera = "-19.185059,822.114929,114.511719,0.000044,2.786068,50.5424,35.000015,234.030762,false,Manual,3.823875",
          GUID = "C8C5D304",
          NextDialogue = 80200225,
          Scripts = "PARA{\nPlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\nPlayAnimation{_delay{6.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\n}",
          SpeakNpcId = 790054,
          TalkActionId = {
            [1] = "790054:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D304"
        },
        [80200225] = {
          Content = "你找扶疏？怪了，她素来不和人来往，是个小闷葫芦，原来也有熟人？",
          DialogueId = 80200225,
          GUID = "C8C5D32E",
          NextOptions = {
            [1] = 802002251,
            [2] = 802002252,
            [3] = 802002253
          },
          Scripts = "PARA{\nPlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}},\nPlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}},\nPlayAnimation{_delay{6.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}}\n}",
          SpeakNpcId = 790054,
          TalkActionId = {
            [1] = "790054:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D32E"
        },
        [80200226] = {
          Content = "哇……你这个年纪的人，竟不觉得她闷，还这样夸奖她，不错不错，扶疏的朋友，就是我扶风的朋友！",
          DialogueId = 80200226,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D382",
          NextDialogue = 80200229,
          Scripts = "PARA{\nPlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\nPlayAnimation{_delay{5.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\n}",
          SpeakNpcId = 790054,
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D382"
        },
        [80200227] = {
          Content = "讹钱讹到我枯荣阁来了？！你去这十里八乡问问，这小闷葫芦的肚子里连点铜钱响都听不到，你要诬赖人，好歹也诬赖给我吧！",
          DialogueId = 80200227,
          FacialId = {
            [1] = "790054:Angry01"
          },
          GUID = "C8C5D3D6",
          NextDialogue = 80200229,
          Scripts = "PARA{\nPlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Angry01_Start\"},Duration{1}},\nPlayAnimation{_delay{8.01},ActorId{790054},AnimationId{\"Angry01_End\"},Duration{1}},\nPlayAnimation{_delay{8.5},ActorId{790054},AnimationId{\"Talk02_Start\"},Duration{1}},\nPlayAnimation{_delay{10},ActorId{790054},AnimationId{\"Talk02_End\"},Duration{1}}\n}",
          SpeakNpcId = 790054,
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D3D6"
        },
        [80200228] = {
          Content = "噫，油嘴滑舌，要是没病没痛就回家自己玩儿吧，乖。",
          DialogueId = 80200228,
          GUID = "C8C5D42A",
          NextDialogue = 80200229,
          Scripts = "PlayAnimation{_delay{4.01},ActorId{790054},AnimationId{"DisagreeHead"},Duration{1}}",
          SpeakNpcId = 790054,
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D42A"
        },
        [80200229] = {
          Camera = "-30.235046,1285.589722,155.125977,0.000064,-7.212188,-68.241211,35.000019,393.319,false,Manual,3.482719",
          CameraBlendCurve = "easeInOutQuad",
          Content = "所以，你造访枯荣阁所为何事？",
          DialogueId = 80200229,
          FacialId = {
            [1] = "790054:None"
          },
          FinalCamera = "31.76886,1303.230225,155.125977,0.00006,-7.012207,-79.441032,35.000019,393.319,false,Manual,3.482719",
          GUID = "C8C5D454",
          NextDialogue = 80200230,
          SpeakNpcId = 790054,
          TalkActionId = {
            [1] = "790054:Confident_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D454"
        },
        [80200230] = {
          Content = "我误食了音容草，头脑发昏，还看见奇奇怪怪的东西，我想扶疏一定能治，就寻医问药来了。",
          DialogueId = 80200230,
          FacialId = {
            [1] = "790008:Sad03"
          },
          GUID = "C8C5D47E",
          NextDialogue = 80200231,
          Scripts = "PlayAnimation{_delay{7.01},ActorId{790008},AnimationId{"Explain02_End"},Duration{1}}\n",
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D47E"
        },
        [80200231] = {
          Camera = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
          Content = "你来得不巧，扶疏正生着闷气呢，还是别在这时候打扰她了。不过我是一名医师，让我看病也是一样的。",
          DialogueId = 80200231,
          FinalCamera = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
          GUID = "C8C5D4A8",
          NextDialogue = 80200232,
          Scripts = "PARA{\nPlayAnimation{_delay{5.01},ActorId{790054},AnimationId{\"Think_End\"},Duration{1}},\nTurnTo{_delay{5.8},TurnToDescription{\"790054:n(790008)\"}},\nPlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\nPlayAnimation{_delay{9.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\n}",
          SpeakNpcId = 790054,
          TalkActionId = {
            [1] = "790054:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4A8"
        },
        [80200232] = {
          Camera = "-253.072449,961.222961,89.996094,0.000045,3.386319,-1.453428,35.000015,323.748901,false,Manual,3.482719",
          Content = "让我仔细看看……",
          DialogueId = 80200232,
          FinalCamera = "-253.819214,931.512756,89.996094,0.000045,3.186317,-1.253389,35.000015,323.748901,false,Manual,3.482719",
          GUID = "C8C5D4D2",
          NextDialogue = 80200233,
          Scripts = "MoveTo{ActorId{790054},TargetPoint{"BP_200301b_fushu03"},MoveSpeed{80},Visibility{"Show"}}",
          SpeakNpcId = 790054,
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4D2"
        },
        [80200233] = {
          Content = "嗯……步履还算稳健，双目也有焦点，口齿利索，舌头不打架，误食的量应该不大。大约是半片左右？",
          DialogueId = 80200233,
          GUID = "C8C5D4FC",
          NextDialogue = 80200234,
          Scripts = "PARA{\nPlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Think_Start\"},Duration{1}},\nPlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Think_End\"},Duration{1}}\n}",
          SpeakNpcId = 790054,
          TalkActionId = {
