        },
        [80210132] = {
          Camera = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
          Content = "什么嘛，没劲。我看你这副行头，又背着剑，还以为能看到阿妈出手呢。",
          DialogueId = 80210132,
          GUID = "C8CC32C8",
          NextDialogue = 80210133,
          SpeakNpcId = 790065,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC32C8"
        },
        [80210133] = {
          Camera = "393.839844,444.308105,335.135742,0.000015,-26.198637,-130.560333,35.000011,240.726898,false,Manual,2.8",
          Content = "哈哈，假以时日，会见到的。那么，在下告辞。",
          DialogueId = 80210133,
          FacialId = {
            [1] = "790067:Smile02"
          },
          FinalCamera = "359.804688,403.016113,308.810547,0.000015,-26.198637,-130.560333,35.000011,290.796356,false,Manual,2.8",
          GUID = "C8CC32F2",
          LookAt = {
            [1] = "790067:n(790067)"
          },
          NextDialogue = 80210134,
          SpeakNpcId = 790067,
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "790067:p(180)"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC32F2"
        },
        [80210134] = {
          Camera = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
          Content = "真的假的。喂，阿姐，听见了没，快别用阿妈的剑杀鸡了，以后还会用的，锈了怎么办。",
          DialogueId = 80210134,
          FacialId = {
            [1] = "790065:CM_Happy01"
          },
          GUID = "C8CC331C",
          LookAt = {
            [1] = "790065:n(790066)"
          },
          NextDialogue = 80210135,
          SpeakNpcId = 790065,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC331C"
        },
        [80210135] = {
          Camera = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
          Content = "一惊一乍的，以后的事，以后再说。",
          DialogueId = 80210135,
          GUID = "C8CC3346",
          LookAt = {
            [1] = "790066:n(790065)"
          },
          NextDialogue = 80210136,
          SpeakNpcId = 790066,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3346"
        },
        [80210136] = {
          Camera = "71.171875,-18.830078,134.579102,0.000001,10.798099,59.223282,35.000011,265.938843,false,Manual,2.8",
          Content = "倒是这位大哥哥，不妨坐下来歇息一会儿再走？",
          DialogueId = 80210136,
          FinalCamera = "71.171875,-18.830078,134.579102,0.0,10.798091,56.999958,35.000011,265.938843,false,Manual,2.8",
          GUID = "C8CC3370",
          LookAt = {
            [1] = "790065:n(790067)",
            [2] = "790066:n(790067)"
          },
          NextDialogue = 80210137,
          SpeakNpcId = 790066,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3370"
        },
        [80210137] = {
          Camera = "-152.511719,-805.267578,105.516602,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
          Content = "这可不行，我身后可是一直有一群小狗在追着，停留不得，就不打扰你们了。",
          DialogueId = 80210137,
          FacialId = {
            [1] = "790067:None"
          },
          FinalCamera = "-218.78125,-1024.449219,87.90332,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
          GUID = "C8CC339A",
          Scripts = "MoveTo{ActorId{790067},TargetPoint{"BP_NewTargetPoint_150301"},MoveSpeed{150}}",
          SpeakNpcId = 790067,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC339A"
        },
        [80210201] = {
          Camera = "-3911.427734,-2583.495605,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
          Content = "侠客爱憎分明，情天恨海，是非多多。更有好事者把这些纠缠写成书册，人人爱看。",
          DialogueId = 80210201,
          FinalCamera = "-3781.285156,-2732.086426,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
          GUID = "C8CC3E1A",
          NextDialogue = 80210202,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E1A"
        },
        [80210202] = {
          Content = "人人皆向往能策马红尘，但身在其中者，往往是另外一番愁滋味。",
          DialogueId = 80210202,
          GUID = "C8CC3E44",
          NextDialogue = 80210203,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E44"
        },
        [80210203] = {
          Camera = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          Content = "你回来了，鸣鸾。",
          DialogueId = 80210203,
          FacialId = {
            [1] = "790067:Smile01"
          },
          FinalCamera = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          GUID = "C8CC3E6E",
          LookAt = {
            [1] = "790067:n(790068)",
            [2] = "790068:n(790067)"
          },
          NextDialogue = 80210204,
          SpeakNpcId = 790067,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E6E"
        },
        [80210204] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          Content = "我回来了，刻舟。",
          DialogueId = 80210204,
          FacialId = {
            [1] = "790068:CM_Smile01"
          },
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC3E98",
          NextDialogue = 80210205,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Agree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E98"
        },
        [80210205] = {
          Camera = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
          Content = "那么结果呢？",
          DialogueId = 80210205,
          FinalCamera = "-361.898438,-71.477051,182.797852,0.0001,-12.798893,15.006591,20.0,592.475586,false,Manual,4.0",
          GUID = "C8CC3EC2",
          NextDialogue = 80210206,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3EC2"
        },
        [80210206] = {
          Content = "自然是有一些的。",
          DialogueId = 80210206,
          GUID = "C8CC3EEC",
          NextDialogue = 80210207,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3EEC"
        },
        [80210207] = {
          Camera = "109.556641,-109.840332,171.128906,0.000122,-10.598042,137.795868,20.0,275.546844,false,Manual,4.0",
          Content = "我踏足了五个国家，悟出了五门新功夫。",
          DialogueId = 80210207,
          FinalCamera = "32.886719,-42.50415,154.229492,0.000131,-5.197801,142.396057,20.0,155.23967,false,Manual,4.0",
          GUID = "C8CC3F16",
          NextDialogue = 80210208,
          SpeakNpcId = 790068,
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F16"
        },
        [80210208] = {
          Camera = "1812.060547,3093.102783,-750.477539,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
          Content = "我先是西出了华胥，踏入了赫墨的瀚海。",
          DialogueId = 80210208,
          FinalCamera = "1251.640625,3319.118652,-659.09082,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
          GUID = "C8CC3F40",
          NextDialogue = 80210209,
          SpeakNpcId = 790068,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F40"
        },
        [80210209] = {
          Camera = "-1200.404297,23490.853516,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
          Content = "之前我听人说赫墨的瀚海是万里黄沙，酷热无比。于是便拿定主意，夜半披星赶路。",
          DialogueId = 80210209,
          FinalCamera = "-1074.800781,23130.9375,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
          GUID = "C8CC3F6A",
          NextDialogue = 80210210,
          SpeakNpcId = 790068,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F6A"
        },
        [80210210] = {
          Content = "但我没料到夜半的沙漠却又奇寒无比，如果不做些什么必将冻毙其中，成为一具无名的白骨。",
          DialogueId = 80210210,
          GUID = "C8CC3F94",
          NextDialogue = 80210211,
          SpeakNpcId = 790068,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F94"
        },
        [80210211] = {
          Camera = "-23017.669922,21547.728516,8057.0,0.000038,14.399909,168.238129,22.934771,13322.412109,false,Manual,4.0",
          Content = "正当我烦恼该如何自救之时，我看到远处的地平上有几颗绿星忽闪忽闪，却又渐渐变大。",
          DialogueId = 80210211,
          FinalCamera = "-23384.009766,19835.208984,8057.0,0.000038,14.399909,166.236816,22.934771,13322.412109,false,Manual,4.0",
          GUID = "C8CC3FBE",
          NextDialogue = 80210212,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790067:Talk02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3FBE"
        },
        [80210212] = {
          Content = "那些绿星都是成对的，并且远远地也能透着股肃杀之气，像是典籍上提到的贪狼星。我突然醒悟过来，这并非是什么星星，而是狼的眼睛。",
          DialogueId = 80210212,
          GUID = "C8CC3FE8",
          NextDialogue = 80210213,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3FE8"
        },
        [80210213] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          Content = "可怜。",
          DialogueId = 80210213,
          GUID = "C8CC4012",
          NextDialogue = 80210214,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4012"
        },
        [80210214] = {
          Camera = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
          Content = "谁可怜。",
          DialogueId = 80210214,
          FinalCamera = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
          GUID = "C8CC403C",
          NextDialogue = 80210215,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC403C"
        },
        [80210215] = {
          Content = "自然不是你可怜。",
          DialogueId = 80210215,
          GUID = "C8CC4066",
          NextDialogue = 80210216,
          SpeakNpcId = 790067,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4066"
        },
        [80210216] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          Content = "那你错怪我了，那些小狗崽子安然无恙，我只是拍晕了几只，把它们拖到沙丘的背风处，当做垫背，靠着它们的体温囫囵了一个晚上。",
          DialogueId = 80210216,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4090",
          NextDialogue = 80210217,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Disagree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4090"
        },
        [80210217] = {
          Content = "了结它们倒也不难，但真要如此的话，我活不过第一个晚上。",
          DialogueId = 80210217,
          GUID = "C8CC40BA",
          NextDialogue = 80210218,
          SpeakNpcId = 790068,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC40BA"
        },
        [80210218] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000083,-19.79907,13.007248,30.000008,125.0,false,Manual,2.8",
          Content = "于你来说，几只野狼自然不是对手，但是我记得你的掌风素来刚猛凌厉，号称降龙，没想到居然能控制到恰好击晕活物而留其性命的地步。",
          DialogueId = 80210218,
          FinalCamera = "-29.367188,-76.549561,193.577148,0.000083,-19.79907,13.007559,30.000008,125.0,false,Manual,2.8",
          GUID = "C8CC40E4",
          NextDialogue = 80210219,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:Talk01_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC40E4"
        },
        [80210219] = {
          Content = "这应该便是你悟出的第一门功夫吧。",
          DialogueId = 80210219,
          GUID = "C8CC410E",
          NextDialogue = 80210220,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC410E"
        },
        [80210220] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          Content = "不愧是刻舟刻大侠，立刻意识到关节所在。在那过后每晚我都是如此过夜，击晕野狼取暖。从而悟出了一套新的掌法，我称之为狼眠掌。",
          DialogueId = 80210220,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4138",
          NextDialogue = 80210221,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Agree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4138"
        },
        [80210221] = {
          Camera = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          Content = "好，好个狼眠掌，当浮一大白。",
          DialogueId = 80210221,
          FacialId = {
            [1] = "790067:Smile02"
          },
          FinalCamera = "-156.203125,50.284424,160.674805,0.000084,-5.398062,-15.405737,33.0,343.677704,false,Manual,3.0",
          GUID = "C8CC4162",
          NextDialogue = 80210222,
          SpeakNpcId = 790067,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4162"
        },
        [80210222] = {
          Content = "那么第二门功夫，应当就是在海伯利亚帝国了。让我猜猜你悟出了什么……有类迅捷剑术的快剑？还是如同冰湖城坚冰一样厚重的长拳？",
          DialogueId = 80210222,
          GUID = "C8CC418C",
          NextDialogue = 80210223,
          SpeakNpcId = 790067,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC418C"
        },
        [80210223] = {
          Camera = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          Content = "想不到你人一直在华胥，却还知道海伯利亚还有个冰湖城。",
          DialogueId = 80210223,
          FinalCamera = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          GUID = "C8CC41B6",
          NextDialogue = 80210224,
          SpeakNpcId = 790068,
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC41B6"
        },
        [80210224] = {
          Content = "最近交了个朋友，在冰湖城居住，所以多少知道一些。",
          DialogueId = 80210224,
          FacialId = {
            [1] = "790067:Smile01"
          },
          GUID = "C8CC41E0",
          NextDialogue = 80210225,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC41E0"
        },
        [80210225] = {
          Content = "原来如此，不过你猜错了，我着急赶路，直接去了卢卡。",
          DialogueId = 80210225,
          GUID = "C8CC420A",
          NextDialogue = 80210226,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790067:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC420A"
        },
        [80210226] = {
          Content = "在前往卢卡的路上，我遭遇了传说中的海中精怪，被称作塞壬的异兽。它们貌似婵娟，但是却能以歌声摄人心魄。",
          DialogueId = 80210226,
          GUID = "C8CC4234",
          NextDialogue = 80210227,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4234"
        },
        [80210227] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          Content = "那岂不是和百年前的前辈莫抱琴一般，能以传音入密的功夫乱人心神？",
          DialogueId = 80210227,
          GUID = "C8CC425E",
          NextDialogue = 80210228,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790068:Talk03_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC425E"
        },
        [80210228] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          Content = "确实如出一辙。只是我当时没有想到这些，只顾着跳入水中，闭息凝神，又抓住了路过的巨鲸，才堪堪逃得性命。",
          DialogueId = 80210228,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4288",
          NextDialogue = 80210229,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Agree"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4288"
        },
        [80210229] = {
          Content = "但也因此，我的闭气功夫见长不少，几乎不再惧怕毒雾之类的雕虫小技。而我将这套法门唤作长鲸心法。",
          DialogueId = 80210229,
          GUID = "C8CC42B2",
          NextDialogue = 80210230,
          SpeakNpcId = 790068,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC42B2"
        },
        [80210230] = {
          Content = "然后呢？",
          DialogueId = 80210230,
          GUID = "C8CC42DC",
          NextDialogue = 80210231,
          SpeakNpcId = 790067,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC42DC"
        },
        [80210231] = {
          Content = "我在卢卡也没有停留太久，于是去了传颂会的雅什尼亚，在那里我……",
          DialogueId = 80210231,
          GUID = "C8CC4306",
          NextDialogue = 80210232,
          SpeakNpcId = 790068,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4306"
        },
        [80210232] = {
          Camera = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          Content = "稍等，我打断一下。",
          DialogueId = 80210232,
          FacialId = {
            [1] = "790067:None"
          },
          GUID = "C8CC4330",
          NextDialogue = 80210233,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790068:Confident_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4330"
        },
        [80210233] = {
          Content = "你可以打断，但需要自罚一杯。",
          DialogueId = 80210233,
          GUID = "C8CC435A",
          NextDialogue = 80210234,
          SpeakNpcId = 790068,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC435A"
        },
        [80210234] = {
          Content = "罚就罚，没问题，我只是想问你，她呢？你最终找到她了吗？",
          DialogueId = 80210234,
          GUID = "C8CC4384",
          NextDialogue = 80210235,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4384"
        },
        [80210235] = {
          Camera = "-54.832031,-48.86377,169.512695,0.000115,-10.397644,109.791862,20.0,116.948799,false,Manual,4.0",
          Content = "……",
          DialogueId = 80210235,
          FacialId = {
            [1] = "790068:CM_Idle"
          },
          GUID = "C8CC43AE",
          NextDialogue = 80210236,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Confident_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC43AE"
        },
        [80210236] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          Content = "你说过，不找到她是不会回华胥的。",
          DialogueId = 80210236,
          FinalCamera = "-22.458984,-65.278564,190.244141,0.000084,-19.79907,13.007616,30.000008,115.331322,false,Manual,2.8",
          GUID = "C8CC43D8",
          NextDialogue = 80210237,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC43D8"
        },
        [80210237] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          Content = "我累了。",
          DialogueId = 80210237,
          FacialId = {
            [1] = "790068:CM_Sad01"
          },
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4402",
          NextDialogue = 80210238,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Disagree"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4402"
        },
        [80210238] = {
          Content = "我无时无刻不在想着她。沙砾里，海浪里，森林里，圣塔旁，絮语河上，我都寻觅过她，但是却又寻她不见。",
          DialogueId = 80210238,
          GUID = "C8CC442C",
          NextDialogue = 80210239,
          SpeakNpcId = 790068,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC442C"
        },
        [80210239] = {
          Content = "于是我在想，她会不会是回到了华胥这个伤心地。但，依旧没有人见过她。",
          DialogueId = 80210239,
          GUID = "C8CC4456",
          NextDialogue = 80210240,
          SpeakNpcId = 790068,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4456"
        },
        [80210240] = {
          Camera = "55.90625,-152.534912,193.577148,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
          Content = "可怜。",
          DialogueId = 80210240,
          FinalCamera = "57.841797,-147.262451,191.289062,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
          GUID = "C8CC4480",
          NextDialogue = 80210241,
          SpeakNpcId = 790067,
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4480"
        },
        [80210241] = {
          Camera = "118.96875,-145.442871,164.535156,0.000056,-5.398397,129.398148,33.0,376.434326,false,Manual,3.0",
          Content = "谁可怜。",
          DialogueId = 80210241,
          FinalCamera = "107.117188,-131.01001,162.773438,0.000061,-5.398397,129.398041,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC44AA",
          NextDialogue = 80210242,
          SpeakNpcId = 790068,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC44AA"
        },
        [80210242] = {
          Camera = "-2.816406,-67.810547,183.550781,0.000092,-19.198992,12.008528,30.000008,92.276848,false,Manual,2.8",
          Content = "天下有情人。",
          DialogueId = 80210242,
          GUID = "C8CC44D4",
          NextDialogue = 80210243,
          SpeakNpcId = 790067,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC44D4"
        },
        [80210243] = {
          Camera = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          Content = "哈哈。",
          DialogueId = 80210243,
          FacialId = {
            [1] = "790068:CM_Smile01"
          },
          FinalCamera = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          GUID = "C8CC44FE",
          NextDialogue = 80210244,
          SpeakNpcId = 790068,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC44FE"
        },
        [80210244] = {
          Content = "要说可怜，你也同样，我远离华胥不受大风九章羁绊，而你的话，恐怕在来见我之前，刚刚和应天尉交过手吧。",
          DialogueId = 80210244,
          GUID = "C8CC4528",
          NextDialogue = 80210245,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4528"
        },
        [80210245] = {
          Camera = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          Content = "那是自然，但也早就习惯如此了，正如你习惯了漂泊异乡一样。",
          DialogueId = 80210245,
          FinalCamera = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          GUID = "C8CC4552",
          NextDialogue = 80210246,
          SpeakNpcId = 790067,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4552"
        },
        [80210246] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          Content = "刚刚你打断我的话，罚酒一杯，该喝了。等你喝完我就上路继续找她，这次我反其道行之，先从海路到伊瑟尔。",
          DialogueId = 80210246,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC457C",
          NextDialogue = 80210247,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC457C"
        },
        [80210247] = {
          Camera = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
          Content = "我刚刚已经罚完了。",
          DialogueId = 80210247,
          FinalCamera = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
          GUID = "C8CC45A6",
          NextDialogue = 80210248,
          SpeakNpcId = 790067,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC45A6"
        },
        [80210248] = {
          Content = "什么时候？我怎么没瞧见。",
          DialogueId = 80210248,
          GUID = "C8CC45D0",
          NextDialogue = 80210249,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC45D0"
        },
        [80210249] = {
          Content = "在你说到圣塔旁，絮语河上的时候。",
          DialogueId = 80210249,
          GUID = "C8CC45FA",
          NextDialogue = 80210250,
          SpeakNpcId = 790067,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC45FA"
        },
        [80210250] = {
          Content = "真的假的？唉，可能是我太想见她了。",
          DialogueId = 80210250,
          GUID = "C8CC4624",
          NextDialogue = 80210251,
          SpeakNpcId = 790068,
          TalkActionId = {
            [1] = "790068:Disagree"
