          DialogueId = 200006152,
          GUID = "200006152",
          ImprPlusId = 1001,
          NextDialogue = 20000618,
          Subtitle = "How much will the leader of your legion get paid?"
        },
        [200008091] = {
          ContentFR = "– Tu remarques qu’elle a l’air abattue, comme si quelque chose la tracassait.",
          DialogueId = 200008091,
          GUID = "200008091",
          ImprPlusId = 1004,
          NextDialogue = 20000810
        },
        [200008092] = {
          ContentFR = "– Tu remarques les fleurs qu’elle observait, c’est sans doute à elles qu’elle soupirait.",
          DialogueId = 200008092,
          GUID = "200008092.0",
          ImprPlusId = 1003,
          NextDialogue = 20000811
        },
        [200008093] = {
          ContentFR = "Le repos ne suffit pas toujours. Sortir prendre l’air pourrait te faire du bien.",
          DialogueId = 200008093,
          GUID = "200008093.0",
          ImprPlusId = 1005,
          NextDialogue = 20000812
        },
        [200008161] = {
          ContentFR = "Elle a l’air un peu fatiguée...",
          DialogueId = 200008161,
          GUID = "200008161.0",
          NextDialogue = 20000817
        },
        [200008162] = {
          ContentFR = "Elle fleurit à merveille !",
          DialogueId = 200008162,
          GUID = "200008162.0",
          NextDialogue = 20000818
        },
        [200008201] = {
          ContentFR = "Observer la couleur",
