          GUID = "200008202.0",
          NextDialogue = 20000823
        },
        [200008203] = {
          ContentFR = "Regarder les pétales de près",
          DialogueId = 200008203,
          GUID = "200008203.0",
          NextDialogue = 20000827
        },
        [200008341] = {
          ContentFR = "La réconforter — même les fleurs les plus fortes finissent par dépérir.",
