          GUID = "200008411",
          ImprPlusId = 1001,
          NextDialogue = 20000842
        },
        [200008412] = {
          ContentFR = "– Je vais l’aider.",
          DialogueId = 200008412,
          GUID = "200008412",
          ImprPlusId = 1002,
          NextDialogue = 20000842
        },
        [200009111] = {
          ContentFR = "En effet... si elles avaient le choix, elles ne voudraient pas être cueillies.",
          DialogueId = 200009111,
          GUID = "200009111",
          ImprPlusId = 1004,
          NextDialogue = 20000913
        },
        [200009112] = {
          ContentFR = "Peut-être que leur rôle est d’être admirées par les gens.",
          DialogueId = 200009112,
          GUID = "200009112",
          ImprPlusId = 1001,
          NextDialogue = 20000912
        },
        [200009151] = {
          ContentFR = "Je ferai de mon mieux pour qu’elles vivent le plus longtemps possible.",
