          GUID = "510039133.0",
          ImprPlusId = 1003,
          NextDialogue = 51003919
        },
        [510040011] = {
          ContentFR = "Imagine que tu es un démon féroce.",
          DialogueId = 510040011,
          GUID = "510040011.0",
          NextDialogue = 51004002
        },
        [510040012] = {
          ContentFR = "Répète-leur les insultes qu’ils t’adressent.",
