  {
    MinKey = 800202021,
    MaxKey = 801502262,
    Loader = function()
      return {
        [800202021] = {
          ContentFR = "Tu devrais te reposer alors, notre petite pause peut attendre.",
          DialogueId = 800202021,
          GUID = "800202021.0",
          NextDialogue = 80020203
        },
        [800202022] = {
          ContentFR = "Tu exagères un peu, non ?",
          DialogueId = 800202022,
          GUID = "800202022.0",
          NextDialogue = 80020204
        },
        [800202091] = {
          ContentFR = "Tu es vraiment qu’une simple servante ?",
          DialogueId = 800202091,
          GUID = "800202091.0",
          NextDialogue = 80020210
        },
        [800202092] = {
          ContentFR = "Ça a l’air terriblement dangereux.",
          DialogueId = 800202092,
          GUID = "800202092.0",
          NextDialogue = 80020211
        },
        [800202161] = {
          ContentFR = "Ça sonne comme une aventure pleine de charme.",
          DialogueId = 800202161,
          GUID = "800202161.0",
          NextDialogue = 80020217
        },
        [800202162] = {
          ContentFR = "Ça semble être un métier difficile.",
          DialogueId = 800202162,
          GUID = "800202162.0",
          NextDialogue = 80020218
        },
        [800203021] = {
          ContentFR = "Je peux venir avec toi ?",
          DialogueId = 800203021,
          GUID = "800203021.0",
          NextDialogue = 80020303
        },
        [800203022] = {
          ContentFR = "Toi, faire les boutiques ?",
          DialogueId = 800203022,
          GUID = "800203022.0",
          NextDialogue = 80020304
        },
        [800203121] = {
          ContentFR = "C’est vraiment si efficace que ça ?",
          DialogueId = 800203121,
          GUID = "800203121.0",
          NextDialogue = 80020313
        },
        [800203122] = {
          ContentFR = "Ça a l’air vraiment élégant.",
          DialogueId = 800203122,
          GUID = "800203122.0",
          NextDialogue = 80020314
        },
        [800203161] = {
          ContentFR = "Un prince ?",
          DialogueId = 800203161,
          GUID = "800203161.0",
          NextDialogue = 80020317
        },
        [800204021] = {
          ContentFR = "Tu sembles de bonne humeur.",
          DialogueId = 800204021,
          GUID = "800204021.0",
          NextDialogue = 80020403
        },
        [800204022] = {
          ContentFR = "Voilà un vrai travail de servante.",
          DialogueId = 800204022,
          GUID = "800204022.0",
          NextDialogue = 80020404
        },
        [800204091] = {
          ContentFR = "Alors, qu’est-ce qui te tracasse ?",
          DialogueId = 800204091,
          GUID = "800204091.0",
          NextDialogue = 80020410
        },
        [800204092] = {
          ContentFR = "Tu peux m’en dire plus sur tes anciens collègues ?",
          DialogueId = 800204092,
          GUID = "800204092.0",
          NextDialogue = 80020411
        },
        [800204171] = {
          ContentFR = "Si tu te poses la question, pourquoi ne pas aller la voir ?",
          DialogueId = 800204171,
          GUID = "800204171.0",
          NextDialogue = 80020418
        },
        [800205011] = {
          ContentFR = "Ah ? Ce n’est qu’une coïncidence.",
          DialogueId = 800205011,
          GUID = "800205011.0",
          NextDialogue = 80020503
        },
        [800205012] = {
          ContentFR = "Avec des cheveux aussi voyants que les tiens, c’est difficile de ne pas te remarquer.",
          DialogueId = 800205012,
          GUID = "800205012.0",
          NextDialogue = 80020503
        },
        [800205071] = {
          ContentFR = "On dirait que tu as fait la paix.",
          DialogueId = 800205071,
          GUID = "800205071.0",
          NextDialogue = 80020508
        },
        [800205072] = {
          ContentFR = "Tu ne ressens pas un peu de regret ?",
          DialogueId = 800205072,
          GUID = "800205072.0",
          NextDialogue = 80020509
        },
        [800205121] = {
          ContentFR = "Quand j’hésitais encore, elle, elle ne doutait pas et voulait accomplir sa mission, me voyant même comme un obstacle à éliminer si besoin.",
          DialogueId = 800205121,
          GUID = "C852AD41",
          NextDialogue = 80020513,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD41"
        },
        [800205141] = {
          ContentFR = "Est-ce que tu la détestes encore ?",
          DialogueId = 800205141,
          GUID = "C852AD6C",
          NextDialogue = 800205143
        },
        [800205142] = {
          ContentFR = "Est-ce que tu l’aimes toujours ?",
          DialogueId = 800205142,
          GUID = "C852AD6D",
          NextDialogue = 800205143
        },
        [800205143] = {
          ContentFR = "Honnêtement, je ne sais pas. Je ressens surtout de la colère, un peu de tristesse, et de la nostalgie. Pour des agents comme nous, aimer ou haïr est un luxe qu’on ne peut pas se permettre.",
          DialogueId = 800205143,
          FacialId = {
            [1] = "93102:Unhappy01"
          },
          GUID = "C852AD94",
          NextDialogue = 80020515,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD94"
        },
        [800205181] = {
          ContentFR = "Pardon ? Tu viens de dire « merci » ?",
          DialogueId = 800205181,
          GUID = "800205181.0",
          NextDialogue = 80020522
        },
        [800205182] = {
          ContentFR = "Je n’ai pas bien entendu, répète.",
          DialogueId = 800205182,
          GUID = "800205182.0",
          NextDialogue = 80020522
        },
        [800301051] = {
          ContentFR = "Franchement, là-dessus, t’as des principes en béton.",
          DialogueId = 800301051,
          GUID = "800301051.0",
          NextDialogue = 80030106
        },
        [800301052] = {
          ContentFR = "T’es toujours en train de glander, Randy.",
          DialogueId = 800301052,
          GUID = "800301052.0",
          NextDialogue = 80030107
        },
        [800302051] = {
          ContentFR = "Mentir pour avoir des congés, ça, c’est un gentleman ?",
          DialogueId = 800302051,
          GUID = "800302051.0",
          NextDialogue = 80030206
        },
        [800302052] = {
          ContentFR = "Oui, oui, sans aucun doute, t’es un vrai gentleman.",
          DialogueId = 800302052,
          GUID = "800302052.0",
          NextDialogue = 80030207
        },
        [800302091] = {
          ContentFR = "Tes sœurs ? Ça devait être de vraies dames, alors.",
          DialogueId = 800302091,
          GUID = "800302091.0",
          NextDialogue = 80030210
        },
        [800302092] = {
          ContentFR = "J’ai du mal à imaginer ce que tu étais quand tu étais gamin.",
          DialogueId = 800302092,
          GUID = "800302092.0",
          NextDialogue = 80030211
        },
        [800302131] = {
          ContentFR = "Bienveillance ? Ça sonne plutôt pas mal.",
          DialogueId = 800302131,
          GUID = "800302131.0",
          NextDialogue = 80030214
        },
        [800302132] = {
          ContentFR = "Bienveillance ? Ça me rappelle le sens sarcastique de "gentleman". Tu as dû souffrir, dis donc.",
          DialogueId = 800302132,
          GUID = "800302132.0",
          NextDialogue = 80030215
        },
        [800304031] = {
          ContentFR = "Quelque chose te tracasse ? Tu n’es pas comme ça d’habitude.",
          DialogueId = 800304031,
          GUID = "800304031.0",
          NextDialogue = 80030404
        },
        [800304032] = {
          ContentFR = "T’es pressé... t’as une autre danse de prévue, c’est ça ?",
          DialogueId = 800304032,
          GUID = "800304032.0",
          NextDialogue = 80030406
        },
        [800304071] = {
          ContentFR = "Un cauchemar ? Quel genre ?",
          DialogueId = 800304071,
          GUID = "800304071.0",
          NextDialogue = 80030408
        },
        [800304081] = {
          ContentFR = "Ton père ? C’est la première fois que tu en parles.",
          DialogueId = 800304081,
          GUID = "800304081.0",
          NextDialogue = 80030409
        },
        [800304321] = {
          ContentFR = "Tu es sûr ?",
          DialogueId = 800304321,
          GUID = "800304321.0",
          NextDialogue = 80030433
        },
        [800304351] = {
          ContentFR = "S’il se réveillait maintenant, il serait fier de toi.",
          DialogueId = 800304351,
          GUID = "800304351.0",
          NextDialogue = 80030436
        },
        [800304352] = {
          ContentFR = "Je te refais un verre ?",
          DialogueId = 800304352,
          GUID = "800304352.0",
          NextDialogue = 80030437
        },
        [800305011] = {
          ContentFR = "Merci... T’as l’air de bonne humeur aujourd’hui.",
          DialogueId = 800305011,
          GUID = "C8790EF4",
          NextDialogue = 80030502
        },
        [800305012] = {
          ContentFR = "Tu mijotes quelque chose, hein ?",
          DialogueId = 800305012,
          GUID = "C8790F48",
          NextDialogue = 80030503
        },
        [800305081] = {
          ContentFR = "Une partenaire splendide, hein ? Et pourquoi c’est moi que tu viens voir ?",
          DialogueId = 800305081,
          GUID = "C879106E",
          NextDialogue = 80030509,
          TriggerCondition = {
            IsBoy = {}
          }
        },
        [800305082] = {
          ContentFR = "Alors c’est pour ça que tu m’as invitée...",
          DialogueId = 800305082,
          GUID = "800305082.0",
          NextDialogue = 80030526,
          TriggerCondition = {
            IsGirl = {}
          }
        },
        [800305091] = {
          ContentFR = "Et pourquoi pas toi ?",
          DialogueId = 800305091,
          GUID = "800305091.0",
          NextDialogue = 80030510
        },
        [800305092] = {
          ContentFR = "... T’es sérieux là ?",
          DialogueId = 800305092,
          GUID = "800305092.0",
          NextDialogue = 80030511
        },
        [800305141] = {
          ContentFR = "Hein ? Mec, c’est quoi ce délire...",
          DialogueId = 800305141,
          GUID = "800305141.0",
          NextDialogue = 80030515
        },
        [800305142] = {
          ContentFR = "Avoue, c’est toi qui rêves de porter une robe.",
          DialogueId = 800305142,
          GUID = "800305142.0",
          NextDialogue = 80030515
