          DialogueId = 801704032,
          GUID = "801704032.0",
          NextDialogue = 80170406
        },
        [801704261] = {
          ContentFR = "Non... ce n’est pas encore toute l’histoire.",
          DialogueId = 801704261,
          GUID = "801704261.0",
          NextDialogue = 80170427
        },
        [801704381] = {
          ContentFR = "Regrettes-tu ce temps-là ?",
          DialogueId = 801704381,
          GUID = "801704381.0",
          NextDialogue = 80170439
        },
        [801901041] = {
          ContentFR = "Je voulais juste te voir.",
          DialogueId = 801901041,
          GUID = "801901041.0",
          NextDialogue = 80190105
        },
        [801901042] = {
          ContentFR = "Je voulais juste t’inviter à boire un verre.",
          DialogueId = 801901042,
          GUID = "801901042.0",
          NextDialogue = 80190106
        },
        [801901101] = {
          ContentFR = "T’es le plus bavard de tous ceux que j’ai invités.",
          DialogueId = 801901101,
          GUID = "801901101.0",
          NextDialogue = 80190111
        },
        [801901102] = {
          ContentFR = "Je t’invite à boire et tu balances des remarques ? Continue comme ça, et je fais la tête.",
          DialogueId = 801901102,
          GUID = "801901102.0",
          NextDialogue = 80190112
        },
        [801901151] = {
          ContentFR = "Tu veux dire que tu es l’un d’eux ?",
          DialogueId = 801901151,
          GUID = "801901151.0",
          NextDialogue = 80190116
        },
        [801901171] = {
          ContentFR = "Je te raccompagne pas.",
          DialogueId = 801901171,
          GUID = "801901171.0",
          NextDialogue = 80190118
        },
        [801901172] = {
          ContentFR = "Alors c’est toi qui t’occupes de chasser les profiteurs pour moi ?",
          DialogueId = 801901172,
          GUID = "801901172.0",
          NextDialogue = 80190119
        },
        [801902011] = {
          ContentFR = "Tu es invité et tu arrives en retard ? Pas cool.",
          DialogueId = 801902011,
          GUID = "801902011.0",
          NextDialogue = 80190203
        },
        [801902012] = {
          ContentFR = "C’est pas une excuse, tu veux juste grappiller quelques verres de plus.",
