          GUID = "801902012.0",
          NextDialogue = 80190202
        },
        [801902041] = {
          ContentFR = "La Légion ?",
          DialogueId = 801902041,
          GUID = "801902041.0",
          NextDialogue = 80190205
        },
        [801902151] = {
          ContentFR = "Comparé à ça, trente minutes de retard, ce n’est rien.",
          DialogueId = 801902151,
          GUID = "801902151.0",
          NextDialogue = 80190216
        },
        [801902152] = {
          ContentFR = "Tu devrais plutôt te reposer que boire ici.",
          DialogueId = 801902152,
          GUID = "801902152.0",
          NextDialogue = 80190217
        },
        [801902191] = {
          ContentFR = "On dirait que tu les détestes.",
          DialogueId = 801902191,
          GUID = "801902191.0",
          NextDialogue = 80190220
        },
        [801903031] = {
          ContentFR = "Dis quelque chose.",
          DialogueId = 801903031,
          GUID = "801903031.0",
          NextDialogue = 80190304
        },
        [801903032] = {
          ContentFR = "Ça va ?",
          DialogueId = 801903032,
          GUID = "801903032.0",
          NextDialogue = 80190304
        },
        [801903061] = {
          ContentFR = "Je devrais te préparer un mouchoir pour tes larmes ?",
          DialogueId = 801903061,
          GUID = "801903061.0",
          NextDialogue = 80190307
        },
        [801903062] = {
          ContentFR = "Tu vas finir par pleurer, non ?",
          DialogueId = 801903062,
          GUID = "801903062.0",
          NextDialogue = 80190307
        },
        [801903151] = {
          ContentFR = "Entre amis, c’est normal de se confier.",
          DialogueId = 801903151,
          GUID = "801903151.0",
          NextDialogue = 80190316
        },
        [801903152] = {
          ContentFR = "Tu es trop cynique, moi je crois encore aux gens.",
          DialogueId = 801903152,
          GUID = "801903152.0",
          NextDialogue = 80190316
        },
        [801903171] = {
          ContentFR = "Alors, ça veut dire que je suis pas vraiment ton {性别:ami|amie} ?",
          DialogueId = 801903171,
          GUID = "801903171.0",
          NextDialogue = 80190318
        },
        [801903221] = {
          ContentFR = "Je ne tiens pas un resto ici !",
          DialogueId = 801903221,
          GUID = "801903221.0",
          NextDialogue = 80190323
        },
        [801903222] = {
          ContentFR = "Si tu veux. Essaie juste de pas le descendre aussi vite cette fois.",
          DialogueId = 801903222,
          GUID = "801903222.0",
          NextDialogue = 80190323
        },
        [801903231] = {
          ContentFR = "Mmmh. Un bon verre, un bon ami... et un sacré moulin à paroles.",
          DialogueId = 801903231,
          GUID = "801903231.0",
          NextDialogue = 80190324
        },
        [801904021] = {
          ContentFR = "Non, je n’ai rien dit.",
          DialogueId = 801904021,
          GUID = "801904021.0",
          NextDialogue = 80190403
        },
        [801904091] = {
          ContentFR = "Tu parles du travail de livraison pour les Déchus dont tu m’as parlé ?",
          DialogueId = 801904091,
          GUID = "801904091.0",
          NextDialogue = 80190410
        },
        [801904161] = {
          ContentFR = "D’accord, va-t’en vite.",
          DialogueId = 801904161,
          GUID = "801904161.0",
          NextDialogue = 80190417
        },
        [801904162] = {
          ContentFR = "Mais tu n’es pas qu’un simple ami de beuverie.",
          DialogueId = 801904162,
          GUID = "801904162.0",
          NextDialogue = 80190417
        },
        [801904321] = {
          ContentFR = "Pour un gars sans scrupules, tu n’es pas mauvais non plus.",
          DialogueId = 801904321,
          GUID = "801904321.0",
          NextDialogue = 80190433
        },
        [801904322] = {
          ContentFR = "Donc tu n’as pas encore de raison de fuir, c’est ça ?",
          DialogueId = 801904322,
          GUID = "801904322.0",
          NextDialogue = 80190433
        },
        [801904361] = {
          ContentFR = "Non, pas du tout. Tu veux un autre verre ?",
          DialogueId = 801904361,
          GUID = "801904361.0",
          NextDialogue = 80190437
        },
        [801904362] = {
